from dataclasses import dataclass
import logging
from typing import Deque, Dict, List, Tuple, Type, Union, Set, Generic, get_args, get_origin, Optional
from typedflow.nodes import ConsumerNode, ProviderNode, DumpNode, LoaderNode
__all__ = ['Flow']
logger = logging.getLogger(__file__)
Node = Union[ProviderNode, ConsumerNode]
@dataclass
class Flow:
    dump_nodes: List[DumpNode]
    debug: bool = False
    def validate(self) -> None:
        """
        not implemented because Python Generic doesn't offer
        any ways to access to the actual type
        """
        self.typecheck()
    def get_loader_nodes_with_broadcast(self) -> List[LoaderNode]:
        """
        Get load nodes. While node checking, all the debug status
        is attachced to all nodes.
        Therefore, this method should pass all the nodes in the DAG.
        """
        loaders: List[LoaderNode] = []
        visited: List[Node] = []
        cands: Deque[Node] = Deque()
        cands.extend(self.dump_nodes)
        while True:
            try:
                node: Node = cands.pop()
            except IndexError:
                return loaders
            if node in visited:
                continue
            else:
                visited.append(node)
            node.debug: bool = self.debug
            if isinstance(node, LoaderNode):
                if node not in loaders:
                    loaders.append(node)
            else:
                cands.extend([n for n in node.precs.values()
                              if n not in visited])
    def run(self,
            validate: bool = True) -> None:
        """
        Run flow.
        """
        if validate:
            self.validate()
        batch_id: int = 0
        while True:
            for node in self.dump_nodes:
                node.run_and_dump(batch_id=batch_id)
            if all([node.finished for node in self.dump_nodes]):
                return
    def is_inherited(self, sub: Type, sup: Type) -> bool:
        """
        This is not a static method in order to be used recursively.
        >>> is_inherited(int, object)
        True
        >>> is_inherited(int, int)
        True
        >>> is_inherited(List[int], Iterable[int])
        True
        >>> is_inherited(Iterable[int], List[int])
        False
        """
        if sub == sup:
            return True
        _sub_orig: Optional[Type] = get_origin(sub)
        if _sub_orig is None:  # i.e. sub_orig is primitive
            return False
        sub_orig: Type = _sub_orig
        _sup_orig: Optional[Type] = get_origin(sup)
        if _sup_orig is None:
            return False
        sup_orig: Type = _sup_orig
        if issubclass(sub_orig, Generic) and issubclass(sup_orig, Generic):
            # Compare original type
            if not self.is_inherited(sup_orig, sub_orig):
                return False
            # compare arguments
            for sub_arg, sup_arg in zip(get_args(sub), get_args(sup)):
                if not self.is_inherited(sub_arg, sup_arg):
                    return False
        return True
    def typecheck(self) -> None:
        """
        Check type consistency with inputs/outputs.
        Return nothing when there are no errors, unless raise AssertionError.
        """
        cands: Deque[Tuple[ConsumerNode, Dict[str, ProviderNode]]] = Deque()
        # initially check all dumps
        for node in self.dump_nodes:
            cands.append(
                (node, {name: ups_node.get_return_type()
                        for name, ups_node in node.precs.items()}))
        while True:
            try:
                node, ups_dict = cands.pop()
            except IndexError:
                break
            arg_types: Type = node.get_arg_types()
            keys: Set[str] = set(arg_types.keys())
            assert keys == set(ups_dict.keys()), f'Invalid arguments. Expected: {arg_types}, Actual: {ups_dict}'
            for key in keys:
                if not self.is_inherited(ups_dict[key], arg_types[key]):
                    raise AssertionError(f'Invalid type for arg {key}: Expected {arg_types[key]}, Actual {ups_dict[key]}')
            for new_node in node.precs.values():
                if isinstance(new_node, ConsumerNode):
                    cands.append(
                        (new_node, {name: ups_node.get_return_type()
                                    for name, ups_node in new_node.precs.items()}))
        # check batch_size
        loaders: List[LoaderNode] = self.get_loader_nodes_with_broadcast()
        assert len({ld.batch_size for ld in loaders}) == 1

import numpy as np
from .concrete_value import ConcreteValue
from ..ir.type import Tensor
def _raise_type_error(op, *args):
    raise ValueError(f"Type error: op\n{op}\nwas given arguments\n{tuple(args)}")
def _elementwise_numpy_op_prop_fn(op, x, y):
    if (
        isinstance(x, Tensor)
        and isinstance(y, ConcreteValue)
        and (y.val.dtype == np.float32 or y.val.dtype == np.float64)
    ):
        return x
    elif (
        isinstance(x, ConcreteValue)
        and isinstance(y, Tensor)
        and (x.val.dtype == np.float32 or x.val.dtype == np.float64)
    ):
        return y
    else:
        _raise_type_error(op, x, y)
def _gather_prop_fn(op, x, y):
    if not (
        isinstance(x, Tensor)
        and isinstance(y, ConcreteValue)
        and x.shape is not None
        and y.val is not None
        and x.device == y.device
        and isinstance(y.val, np.ndarray)
    ):
        _raise_type_error(op, x, y)
    if x.device is None:
        _raise_type_error(op, x, y)
    device = x.device
    if "axis" in op.attributes:
        axis = op.attributes["axis"]
    else:
        axis = 0
    if isinstance(y.val, np.ndarray) and axis == 0:
        # Manually compute the new shape for the common case
        new_shape = y.val.shape + x.shape[1:]
    else:
        # Use the NumPy implementation in the general case
        temp = np.zeros(x.shape)
        new_shape = np.take(temp, y.val.astype(np.int64), axis=axis).shape
    return Tensor(dtype=x.dtype, shape=new_shape, device=device)
def _reshape_prop_fn(op, x, y):
    if not (
        isinstance(x, Tensor)
        and isinstance(y, ConcreteValue)
        and isinstance(y.val, np.ndarray)
    ):
        _raise_type_error(op, x, y)
    y = y.val.tolist()
    if y.count(-1) > 1:
        _raise_type_error(op, x, y)
    new_shape = []
    for dim in y:
        if dim != -1:
            new_shape.append(dim)
        else:
            new_shape.append(int(np.prod(x.shape) / np.prod(y) * -1))
    return Tensor(shape=tuple(new_shape), dtype=x.dtype, device=x.device)
def _pow_prop_fn(op, x, y):
    if not (isinstance(x, Tensor) and isinstance(y, ConcreteValue)):
        _raise_type_error(op, x, y)
    return x
def _slice_prop_fn(op, x, starts, ends, axes, steps):
    if not (
        isinstance(x, Tensor)
        and isinstance(starts, ConcreteValue)
        and isinstance(ends, ConcreteValue)
        and isinstance(axes, ConcreteValue)
        and isinstance(steps, ConcreteValue)
        and isinstance(starts.val, np.ndarray)
        and isinstance(ends.val, np.ndarray)
        and isinstance(axes.val, np.ndarray)
        and (isinstance(steps.val, np.ndarray) or isinstance(steps.val, np.int64))
        and x.device == starts.device
        and x.device == ends.device
        and x.device == axes.device
        and x.device == steps.device
    ):
        _raise_type_error(op, x, starts, ends, axes, steps)
    starts = starts.val
    ends = ends.val
    axes = axes.val
    steps = steps.val
    if len(steps.shape) == 0:
        steps = np.expand_dims(steps, 0)
    # TODO handle the other cases, e.g. negative indices
    assert -1 not in starts.tolist()
    assert -1 not in ends.tolist()
    assert -1 not in axes.tolist()
    if steps is None:
        steps = [1] * len(starts)
    elif isinstance(steps, np.int64):
        steps = [steps] * len(starts)
    else:
        assert len(steps) == len(starts)
    slices = {
        axis: slice(s, e, step) for (s, e, axis, step) in zip(starts, ends, axes, steps)
    }
    slices = tuple(slices.get(d, slice(None)) for d in range(len(x.shape)))
    new_shape = []
    for i, slice_ in enumerate(slices):
        start = slice_.start
        stop = slice_.stop
        step = slice_.step
        if start is None:
            start = 0
        if stop is None:
            stop = x.shape[i]
        if step is None:
            step = 1
        new_shape.append(int(np.ceil((stop - start) / step)))
    return Tensor(shape=tuple(new_shape), dtype=x.dtype, device=x.device)
def _shape_prop_fn(op, x):
    if not isinstance(x, Tensor):
        _raise_type_error(op, x)
    return ConcreteValue(np.array(x.shape, dtype=np.int64), x.device)
MixedRegister = {
    ("Add", (Tensor, ConcreteValue)): _elementwise_numpy_op_prop_fn,
    ("Div", (Tensor, ConcreteValue)): _elementwise_numpy_op_prop_fn,
    ("Gather", (Tensor, ConcreteValue)): _gather_prop_fn,
    ("Mul", (Tensor, ConcreteValue)): _elementwise_numpy_op_prop_fn,
    ("Reshape", (Tensor, ConcreteValue)): _reshape_prop_fn,
    ("Pow", (Tensor, ConcreteValue)): _pow_prop_fn,
    (
        "Slice",
        (Tensor, ConcreteValue, ConcreteValue, ConcreteValue, ConcreteValue),
    ): _slice_prop_fn,
    ("Shape", (Tensor,)): _shape_prop_fn,
    ("Sub", (ConcreteValue, Tensor)): _elementwise_numpy_op_prop_fn,
}

