def start_server(**opts):
    os.system(get_cmd(**opts))
def annotate_do(txt):
    if not txt: return {}
    from stanza.server import CoreNLPClient,StartServer
    with CoreNLPClient(
            start_server=StartServer.DONT_START,
            output_format='json') as client:
        try:
            return client.annotate(txt)
        except:
            return
