                    pass
            if not isinstance(wellness_equals, bool):
                try:
                    iter(wellness_equals)
                    wellness_equals = all(wellness_equals)
                except TypeError:
                    pass
            return element_equals and wellness_equals
        return False
    def __str__(self):
        return f"[{self.wellness}] {self.element}"
