from typing import (
    Tuple,
    Optional,
)
def check_tool_paths() -> Tuple[Optional[str], Optional[str]]:
    """
    Attempts to locate `pyenv` and `poetry`.
    Utilizes `subprocess.run` in order to execute `which` on both
    `pyenv` and `poetry`.
    """
    pyenv = subprocess.run(["which", "pyenv"], capture_output=True)
    poetry = subprocess.run(["which", "poetry"], capture_output=True)
    if pyenv.returncode == 0:
        pyenv_path = pyenv.stdout.decode("UTF-8")
    else:
        pyenv_path = None
    if poetry.returncode == 0:
        poetry_path = poetry.stdout.decode("UTF-8")
    else:
        poetry_path = None
    return (pyenv_path, poetry_path)

import abc
import collections.abc
import typing as ta
from omnibus import check
from omnibus import collections as col
from omnibus import dataclasses as dc
from omnibus import properties
from omnibus.serde import mapping as sm
class QualifiedName(dc.Pure, ta.Sequence[str]):
    parts: ta.Sequence[str] = dc.field(coerce=col.seq)
    dc.check(lambda parts: (
            parts and
            all(parts) and
            all(isinstance(p, str) for p in parts)
    ))
    def __repr__(self) -> str:
        return 'QualifiedName([%s])' % (', '.join(map(repr, self.parts)),)
    @property
    def dotted(self) -> str:
        return '.'.join(self.parts)
    def prefixed(self, sz: int) -> ta.Sequence[ta.Optional[str]]:
        if len(self) > sz:
            raise ValueError(self)
        return ((None,) * (sz - len(self))) + tuple(self.parts)
    @property
    def pair(self) -> ta.Tuple[ta.Optional[str], str]:
        return self.prefixed(2)  # noqa
    @property
    def triple(self) -> ta.Tuple[ta.Optional[str], ta.Optional[str], str]:
        return self.prefixed(3)  # noqa
    @property
    def quad(self) -> ta.Tuple[ta.Optional[str], ta.Optional[str], ta.Optional[str], str]:
        return self.prefixed(4)  # noqa
    def __iter__(self) -> ta.Iterator[str]:
        return iter(self.parts)
    def __len__(self) -> int:
        return len(self.parts)
    def __getitem__(self, idx: int) -> str:
        return self.parts[idx]
    @classmethod
    def of_dotted(cls, dotted: str) -> 'QualifiedName':
        return cls(dotted.split('.'))
    @classmethod
    def of(cls, obj: ta.Union['QualifiedName', ta.Iterable[str]]) -> 'QualifiedName':
        if isinstance(obj, QualifiedName):
            return obj
        elif isinstance(obj, str):
            raise TypeError(obj)
        elif isinstance(obj, collections.abc.Iterable):
            return cls(list(obj))
        else:
            raise TypeError(obj)
    @classmethod
    def of_optional(cls, obj: ta.Union[None, 'QualifiedName', ta.Iterable[str]]) -> ta.Optional['QualifiedName']:
        if obj is None:
            return None
        else:
            return cls.of(obj)
class QualifiedNameSerde(sm.AutoSerde[QualifiedName]):
    def serialize(self, obj: QualifiedName) -> ta.Any:
        return list(check.isinstance(obj, QualifiedName).parts)
    def deserialize(self, ser: ta.Any) -> QualifiedName:
        return QualifiedName.of(ser)
class Code(dc.Enum):
    @abc.abstractproperty
    def fn(self) -> ta.Callable:
        raise NotImplementedError
    def __call__(self, *args, **kwargs):
        return self.fn(*args, **kwargs)
class Lambda(Code, allow_setattr=True):
    src: str = dc.field(check=lambda s: isinstance(s, str) and ':' in s)
    @properties.cached
    def fn(self) -> ta.Callable:
        return eval('lambda ' + self.src)
class LambdaSerde(sm.AutoSerde[Lambda]):
    def serialize(self, obj: Lambda) -> ta.Any:
        return sm.serialize_dataclass_fields(obj)
    def deserialize(self, ser: ta.Any) -> Lambda:
        if isinstance(ser, str):
            return Lambda(ser)
        return sm.deserialize_dataclass_fields(ser, Lambda)

from __future__ import annotations
import typing as t
T = t.TypeVar("T")
def optional(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
) -> t.Optional[T]:
    """Get a value safely from the given dict using the given key.
    If the value is not found or is None, return it anyway.
    :raises: ValueError
    """
    if parser is None:
        value = dict_.get(key)
    else:
        value = parser(dict_, key)
    if value is not None and not isinstance(value, expect):
        raise ValueError(
            f"{dict_}: {repr(key)}: {repr(value)}: invalid type {type(value)}, expecting {expect}"
        )
    return t.cast(T, value)
def required(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
    default: t.Optional[T] = None,
    default_factory: t.Optional[t.Callable[[], T]] = None,
) -> T:
    """Get a value safely from the given dict using the given key.
    If the value is not found or is None, raise value error.
    :raises: ValueError
    """
    value: t.Optional[T] = optional(dict_, key, expect, parser=parser)
    if value is None:
        if default is not None:
            return default
        if default_factory is not None:
            return default_factory()
        raise ValueError(f"{dict_}: {repr(key)}: value is required")
    return value
def flatten_dict(d: t.Dict[t.Any, t.Any]) -> t.Dict[str, object]:
    """Flatten a nested dictionary.
    :param dist d: The nested dictionary to flatten.
    :rtype: dict
    :example:
    .. code-block:: python
        flatten_dict({"a": 1, "b": {"c": 2, "d": {"e": 3, "f": 4}}})
        # {
        #     "a": 1,
        #     "b:c": 2,
        #     "b:d:e": 3,
        #     "b:d:f": 4,
        # }
    """
    def items() -> t.Iterable[t.Tuple[str, object]]:
        for key, value in d.items():
            if not isinstance(key, str):
                raise ValueError(f"{key}: expected {str}, but got {type(key)}")
            if isinstance(value, dict):
                for subkey, subvalue in flatten_dict(value).items():
                    if not isinstance(subkey, str):
                        raise ValueError(
                            f"{subkey}: expected {str}, but got {type(subkey)}"
                        )
                    yield key + ":" + subkey, subvalue
            else:
                yield key, value
    return dict(items())
def unflatten_dict(d: t.Dict[object, object]) -> t.Dict[object, object]:
    """Convert a flattened dict back to nested dict.
    :param dict d: The flattened dict to convert.
    :rtype: dict
    :example:
    .. code-block:: python
        unflatten_dict({"a": 1, "b:c": 2, "b:d:e": 3, "b:d:f": 4})
        # {
        #   "a": 1,
        #   "b": {"c": 2, "d": {"e": 3, "f": 4}},
        # }
    """
    dict_: t.Dict[object, object] = {}
    for k, v in d.items():
        if not isinstance(k, str):
            raise ValueError(f"{k}: expected {str}, but got {type(k)}")
        if ":" in k:
            _dict: t.Union[object, t.Dict[object, object]] = dict_
            fields = k.split(":")
            count = len(fields)
            for i in range(count):
                field = fields[i]
                if not isinstance(_dict, dict):
                    continue
                if field not in _dict:
                    _dict[field] = v if i == (count - 1) else {}
                _dict = _dict[field]
        else:
            dict_[k] = v
    return dict_

