                    lookup_group = []
                continue
            if len(lookup_group) > 0:
                # we need to clear this buffer first before we can yield this item
                async for litem in self._get_batch_children(parent, lookup_group):
                    yield litem
                lookup_group = []
            yield self._fill_object(item, parent)
        # flush the rest
        if len(lookup_group) > 0:
            async for item in self._get_batch_children(parent, lookup_group):
                yield item
    @profilable
    async def contains(self, oid: str, key: str) -> bool:
        return await self._manager._storage.has_key(self, oid, key)  # noqa
    @profilable
    @cache(lambda oid: {"oid": oid, "variant": "len"})
    async def len(self, oid: str) -> bool:
        return await self._manager._storage.len(self, oid)
    @profilable
    async def items(self, container):
        # XXX not using cursor because we can't cache with cursor results...
        keys = await self.keys(container.__uuid__)
        async for item in self.get_children(container, keys):
            yield item.__name__, item
    @profilable
    @cache(
        lambda base_obj, id: {"container": base_obj, "id": id, "variant": "annotation"},
        True,
        additional_keys=[lambda item: {"oid": item["zoid"]}],
    )
    async def _get_annotation(self, base_obj, id):
        try:
            result = await self._manager._storage.get_annotation(self, base_obj.__uuid__, id)
        except KeyError:
            return _EMPTY
        if result is None:
            return _EMPTY
        return result
    @profilable
    async def get_annotation(self, base_obj, id, reader=None):
        result = await self._get_annotation(base_obj, id)
        if result == _EMPTY:
            raise KeyError(id)
        if reader is None:
            obj = app_settings["object_reader"](result)
        else:
            obj = reader(result)
        obj.__of__ = base_obj.__uuid__
        obj.__txn__ = self
        return obj
    @profilable
    @cache(lambda oid: {"oid": oid, "variant": "annotation-keys"})
    async def get_annotation_keys(self, oid):
        return [r["id"] for r in await self._manager._storage.get_annotation_keys(self, oid)]
    async def del_blob(self, bid):
        return await self._manager._storage.del_blob(self, bid)
    async def write_blob_chunk(self, bid, oid, chunk_index, data):
        return await self._manager._storage.write_blob_chunk(self, bid, oid, chunk_index, data)
    async def read_blob_chunk(self, bid, chunk=0):
        return await self._manager._storage.read_blob_chunk(self, bid, chunk)
    async def read_blob_chunks(self, bid):
        return await self._manager._storage.read_blob_chunks(self, bid)
    async def get_total_number_of_objects(self):
        return await self._manager._storage.get_total_number_of_objects(self)
    async def get_total_number_of_resources(self):
        return await self._manager._storage.get_total_number_of_resources(self)
    async def get_total_resources_of_type(self, type_):
        return await self._manager._storage.get_total_resources_of_type(self, type_)
    async def _get_resources_of_type(self, type_, page_size=1000):
        page = 1
        keys = await self._manager._storage._get_page_resources_of_type(
            self, type_, page=page, page_size=page_size
        )
        while len(keys) > 0:
            for key in keys:
                yield key
            page += 1
            keys = await self._manager._storage._get_page_resources_of_type(
                self, type_, page=page, page_size=page_size
            )
    async def get_page_of_keys(self, parent_oid, page=1, page_size=1000):
        return await self._manager._storage.get_page_of_keys(self, parent_oid, page=page, page_size=page_size)
    @profilable
    async def iterate_keys(self, oid, page_size=1000):
        page = 1
        keys = await self._manager._storage.get_page_of_keys(self, oid, page=page, page_size=page_size)
        while len(keys) > 0:
            for key in keys:
                yield key
            page += 1
            keys = await self._manager._storage.get_page_of_keys(self, oid, page=page, page_size=page_size)
    def __enter__(self):
        task_vars.tm.set(self.manager)
        task_vars.txn.set(self)
        return self
    def __exit__(self, *args):
        """
        contextvars already tears down to previous value, do not set to None here!
        """
    async def __aenter__(self):
        return self.__enter__()
    async def __aexit__(self, *args):
        return self.__exit__()

import click
import subprocess
from variables import *  # noqa: F403
@click.command()
@click.option(
    "--env",
    default="staging",
    type=click.Choice(["staging", "prod"], case_sensitive=True),
    help="Choose environnement",
)
@click.option(
    "--klass", default=None, type=str, help="upload data for a specific model"
)
def upload_public_data(env, klass=None):
    """Trigger upload management command of public_data scalingo host."""
    # get the right parameter for scalingo call
    env = ENVS[env]  # noqa: F405
    # build command
    cmd = (
        f"scalingo --app {env['app']} --region {env['region']} "
        "run python manage.py load_data"
    )
    if klass:
        if klass.startswith("public_data.models"):
            cmd += f" --class {klass}"
        else:
            cmd += f" --class public_data.models.{klass}"
    click.echo(f"Execute: {cmd}")
    # execute cmd
    cmd = cmd.split()
    try:
        normal = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            # check=True,
            text=True,
        )
        if normal.stdout:
            click.secho(normal.stdout, fg="green")
    except subprocess.CalledProcessError as e:
        click.secho(f"error occured: {e}", fg="red")
if __name__ == "__main__":
    upload_public_data()

from Crypto.Signature import pkcs1_15
from Crypto.Hash import SHA256
from Crypto.PublicKey import RSA
from riposte import Riposte
from riposte.printer import Palette
import os.path
import sys
blast = Riposte('[blastdoor]$ ')
@blast.command('help')
def help():
    blast.status("List of commands")
    blast.status("generate <filename>       - Generate a private RSA key")
    blast.status("publickey <filename>      - Generate public key from private key")
    blast.status("sign <filename> <message> - Sign message with private key")
    blast.status("exit                      - Exit the program")
@blast.command('generate')
def generate(filename: str):
    if not os.path.isfile(filename):
        # Generate RSA keypair
        blast.status("Generating RSA key...")
        key = RSA.generate(4096)
        enc_key = key.export_key()
        blast.status("Writing private key file...")
        public_key_file = open(filename, 'wb')
        public_key_file.write(enc_key)
        blast.success("Done")
    else:
        blast.error("File already exists!")
@blast.command('publickey')
def publickey(filename: str):
    if os.path.isfile(filename):
        key = RSA.import_key(open(filename).read())
        blast.print(Palette.CYAN.format(key.publickey().export_key().decode('utf-8')))
    else:
        blast.error("File doesn't exist!")
@blast.command('sign')
def sign(filename: str, message: str):
    if os.path.isfile(filename):
        key = RSA.import_key(open(filename).read())
        h = SHA256.new(message.encode('utf-8'))
        signature = pkcs1_15.new(key).sign(h)
        blast.print(Palette.CYAN.format(b64encode(signature).decode('utf-8')))
    else:
        blast.error("File doesn't exists!")
@blast.command('exit')
def exit():
    blast.status("Goobye!")
    sys.exit()
blast.run()

from typing import List
from elasticsearch.exceptions import RequestError
from lucyfer.searchset.fields.mapping.base import MappingMixin
class ElasticMappingMixin(MappingMixin):
    def prepare_qs_for_suggestions(self, qs, prefix: str):
        search = qs.extra(size=0).query('query_string', **{"fields": self.sources, "query": f'*{prefix}*'})
        for source in self.sources:
            search.aggs.bucket(source, "terms", field=source)
        return search
    def get_suggestions_from_prepared_qs(self, qs, prefix: str) -> List[str]:
        try:
            aggs = qs.execute().to_dict().get("aggregations", defaultdict(dict))
        except RequestError:
            return []
        result = []
        for source in self.sources:
            if aggs[source].get("buckets"):
                result.extend(
                    [val for val
                     in [str(val["key"]) for val in aggs[source]["buckets"]]
                     if prefix in val]
                )
        return list(set(result))

