I *hate* writing modules like this... but, I always seem to end up with one
after some amount of time.
They're never what I want, maybe because what I want is to not have to write
this kind of code. Doesn't everyone have to print shit out? Like, exceptions?
I also constantly debate if these modules are even worth existing, or if I
should add the same tedious crap at the site of every `raise` that someone
might have to read.
So... here it is. Once again.
This module prints things... as plain, markdown-ish strings. It doesn't depend
on anything outside the standard library, and should probably stay that way.
"""
from typing import Sequence, Callable, Any, Iterable, Union
import inspect
from pathlib import Path
import shlex
def tick(value) -> str:
    return f"`{value}`"
def fmt_class(cls) -> str:
    if cls.__module__ == "builtins":
        return tick(cls.__name__)
    return tick(f"{cls.__module__}.{cls.__name__}")
def fmt_path(path: Path) -> str:
    return tick(path)
def fmt_cmd(
    cmd: Iterable[str],
    *,
    code_width: int=80,
    indent: Union[str, int]="  "
):
    if isinstance(indent, int):
        indent = " " * indent
    lines = [""]
    for token in cmd:
        quoted = shlex.quote(token)
        if len(lines[-1]) + 1 + len(quoted) > code_width - 2:
            lines[-1] += " \\"
            lines.append(indent)
        if not lines[-1].isspace():
            lines[-1] += " "
        lines[-1] += quoted
    return "\n".join(lines)
def fmt(x: Any) -> str:
    if inspect.isclass(x):
        return fmt_class(x)
    if isinstance(x, Path):
        return fmt_path(x)
    return repr(x)
def coordinate(
    seq: Sequence,
    conjunction: str,
    *,
    to_s: Callable[[Any], str] = fmt,
    sep: str = ",",
) -> str:
    """\
    Examples:
    1.  Empty list
        >>> fmt_list([])
        '[empty]'
    2.  List with a single item
        >>> fmt_list([1])
        '1'
    3.  List with two items
        >>> fmt_list([1, 2])
        '1 and 2'
    4.  List with more than two items
        >>> fmt_list([1, 2, 3])
        '1, 2 and 3'
    5.  Defaults to `repr` to cast to string
        >>> fmt_list(['a', 'b', 'c'])
        "'a', 'b' and 'c'"
    6.  Providing an alternative cast function
        >>> fmt_list(['a', 'b', 'c'], lambda x: f"`{x}`")
        '`a`, `b` and `c`'
    """
    length = len(seq)
    if length == 0:
        return "[empty]"
    if length == 1:
        return to_s(seq[0])
    return f" {conjunction} ".join(
        (f"{sep} ".join(map(to_s, seq[0:-1])), to_s(seq[-1]))
    )

from __future__ import unicode_literals
import frappe
from frappe.model.document import Document
from frappe.desk.form import assign_to
from frappe import throw, _
from frappe.utils import add_days, add_months, add_years, getdate, nowdate
class AssetMaintenance(Document):
	def validate(self):
		for task in self.get('asset_maintenance_tasks'):
			if task.end_date and (getdate(task.start_date) >= getdate(task.end_date)):
				throw(_("Start date should be less than end date for task {0}").format(task.maintenance_task))
			if getdate(task.next_due_date) < getdate(nowdate()):
				task.maintenance_status = "Overdue"
	def on_update(self):
		for task in self.get('asset_maintenance_tasks'):
			if not task.assign_to:
				task.db_set("assign_to", self.maintenance_manager)
				task.db_set("assign_to_name", self.maintenance_manager_name)
			assign_tasks(self.name, task.assign_to, task.maintenance_task, task.next_due_date)
		self.sync_maintenance_tasks()
	def sync_maintenance_tasks(self):
		tasks_names = []
		for task in self.get('asset_maintenance_tasks'):
			tasks_names.append(task.name)
			update_maintenance_log(asset_maintenance = self.name, item_code = self.item_code, item_name = self.item_name, task = task)
		asset_maintenance_logs = frappe.get_all("Asset Maintenance Log", fields=["name"], filters = {"asset_maintenance": self.name,
			"task": ("not in", tasks_names)})
		if asset_maintenance_logs:
			for asset_maintenance_log in asset_maintenance_logs:
				maintenance_log = frappe.get_doc('Asset Maintenance Log', asset_maintenance_log.name)
				maintenance_log.db_set('maintenance_status', 'Cancelled')
@frappe.whitelist()
def assign_tasks(asset_maintenance_name, assign_to_member, maintenance_task, next_due_date):
	team_member = frappe.get_doc('User', assign_to_member).email
	args = {
		'doctype' : 'Asset Maintenance',
		'assign_to' : team_member,
		'name' : asset_maintenance_name,
		'description' : maintenance_task,
		'date' : next_due_date
	}
	if not frappe.db.sql("""select owner from `tabToDo`
		where reference_type=%(doctype)s and reference_name=%(name)s and status="Open"
		and owner=%(assign_to)s""", args):
		assign_to.add(args)
@frappe.whitelist()
def calculate_next_due_date(periodicity, start_date = None, end_date = None, last_completion_date = None, next_due_date = None):
	if not start_date and not last_completion_date:
		start_date = frappe.utils.now()
	if last_completion_date and (last_completion_date > start_date or not start_date):
		start_date = last_completion_date
	if periodicity == 'Daily':
		next_due_date = add_days(start_date, 1)
	if periodicity == 'Weekly':
		next_due_date = add_days(start_date, 7)
	if periodicity == 'Monthly':
		next_due_date = add_months(start_date, 1)
	if periodicity == 'Yearly':
		next_due_date = add_years(start_date, 1)
	if periodicity == '2 Yearly':
		next_due_date = add_years(start_date, 2)
	if periodicity == 'Quarterly':
		next_due_date = add_months(start_date, 3)
	if end_date and (start_date >= end_date or last_completion_date >= end_date or next_due_date):
		next_due_date = ""
	return next_due_date
def update_maintenance_log(asset_maintenance, item_code, item_name, task):
	asset_maintenance_log = frappe.get_value("Asset Maintenance Log", {"asset_maintenance": asset_maintenance,
		"task": task.maintenance_task, "maintenance_status": ('in',['Planned','Overdue'])})
	if not asset_maintenance_log:
		asset_maintenance_log = frappe.get_doc({
			"doctype": "Asset Maintenance Log",
			"asset_maintenance": asset_maintenance,
			"asset_name": asset_maintenance,
			"item_code": item_code,
			"item_name": item_name,
			"task": task.maintenance_task,
			"has_certificate": task.certificate_required,
			"description": task.description,
			"assign_to_name": task.assign_to_name,
			"periodicity": str(task.periodicity),
			"maintenance_type": task.maintenance_type,
			"due_date": task.next_due_date
		})
		asset_maintenance_log.insert()
	else:
		maintenance_log = frappe.get_doc('Asset Maintenance Log', asset_maintenance_log)
		maintenance_log.assign_to_name = task.assign_to_name
		maintenance_log.has_certificate = task.certificate_required
		maintenance_log.description = task.description
		maintenance_log.periodicity = str(task.periodicity)
		maintenance_log.maintenance_type = task.maintenance_type
		maintenance_log.due_date = task.next_due_date
		maintenance_log.save()
@frappe.whitelist()
def get_team_members(doctype, txt, searchfield, start, page_len, filters):
	return frappe.db.get_values('Maintenance Team Member', {'parent':filters.get("maintenance_team")})
