from typing import Tuple, List
from uuid import uuid4
from django.db import models, connection
from django.db.migrations.recorder import MigrationRecorder
from django.db.models import Max, Index, Q
from django.utils.crypto import get_random_string
from django.utils.functional import cached_property
from django.utils.timezone import now
from liquidb.consts import SELF_NAME
def _generate_commit_name() -> str:
    """Generates commit name base on datetime"""
    date = now().strftime("%d-%m-%YT%H:%M:%S")
    salt = get_random_string(6)
    return f"{salt}_{date}"
def _create_migration_hash(migration_identifiers: List[Tuple[str, str]]) -> str:
    """create md5 out of tuples of [(app_name, migration_file), ...]"""
    separator = ";"
    inner_separator = "-"
    # always sort alphabetically to ensure same result for unsorted app and sorted
    joined_value = separator.join(
        inner_separator.join([app, name]) for app, name in sorted(migration_identifiers)
    )
    # no reason to check it is only hash of commits
    return hashlib.md5(joined_value.encode("utf-8")).hexdigest()  # nosec  # NOQA
def get_latest_applied_migrations_qs(
    connection_obj=None,
) -> "QuerySet[MigrationRecorder.Migration]":
    """Return latest applied migration in all django apps in project"""
    if connection_obj is None:
        connection_obj = connection
    recorder = MigrationRecorder(connection_obj)
    migration_qs = recorder.migration_qs.exclude(app=SELF_NAME)
    lastest_ids = (
        migration_qs.values("app")
        .annotate(latest_id=Max("id"))
        .values_list(
            "latest_id",
            flat=True,
        )
    )
    return migration_qs.filter(id__in=lastest_ids)
class Snapshot(models.Model):
    name = models.TextField(default=_generate_commit_name, db_index=True, unique=True)
    created = models.DateTimeField(default=now)
    applied = models.BooleanField(default=False)
    class Meta:
        indexes = [
            # by default all applied is false
            # only one row can be applied at the time
            Index(fields=["applied"], name="unique_applied", condition=Q(applied=True))
        ]
    def __repr__(self):
        class_name = self.__class__.__name__
        return f"{class_name}: {self.id}, {self.name}"
    def __eq__(self, other):
        if not isinstance(other, Snapshot):
            return False
        return self.migration_hash == other.migration_hash
    def __hash__(self):
        return hash(self.migration_hash)
    @property
    def consistent_state(self) -> bool:
        """Return True if all connected migrations to current snapshot is applied"""
        current_state = get_latest_applied_migrations_qs().values_list("app", "name")
        current_hash = _create_migration_hash(current_state)
        return self.migration_hash == current_hash
    @cached_property
    def migration_hash(self) -> str:
        """Generate migration hash"""
        return _create_migration_hash(self.migrations.values_list("app", "name"))
class MigrationState(models.Model):
    uuid = models.UUIDField(unique=True, primary_key=True, db_index=True, default=uuid4)
    snapshot = models.ForeignKey(
        Snapshot, on_delete=models.CASCADE, related_name="migrations"
    )
    migration_id = models.IntegerField(db_index=True)
    # redundant info to restore migration
    # from django/db/migrations/recorder.py:30
    app = models.CharField(max_length=255)
    name = models.CharField(max_length=255)
    def __repr__(self):
        return f"Migration {self.app} {self.name}"

import struct
import socket
import logging
logger = logging.getLogger("modbus_server_logger")
logger.setLevel(logging.DEBUG)
formatter = logging.Formatter("%(levelname)-10s: %(message)s")
streamhandler = logging.StreamHandler()
streamhandler.setLevel(logging.DEBUG)
streamhandler.setFormatter(formatter)
logger.addHandler(streamhandler)
logger.propagate = False  # prevent double logging
class Client:
    def __init__(self, host="localhost", port=502, unit_id=0):
        self.host = host
        self.port = port
        self.unit_id = unit_id
        self.s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.s.connect((host, port))
        self.transaction_id = 0
    def send_request(self, function_code, data_frame):
        pdu_frame = struct.pack("!B", function_code) + data_frame
        protocol = 0  # Always 0, reserved for future use (lol)
        length = len(pdu_frame)
        unit_id = self.unit_id
        header_frame = struct.pack(
            "!HHHB",
            self.transaction_id,
            protocol,
            length,
            unit_id,
        )
        adu_frame = header_frame + pdu_frame
        self.s.sendall(adu_frame)
        current_transaction_id = self.transaction_id
        self.transaction_id += 1
        # Send request and get response:
        response = self.s.recv(255)
        ## Extract Header + Function Code:
        # Transaction ID:   (2 Bytes)   Identifies the request-response-pair, is echoed in the response
        # Protocol:         (2 Bytes)   Always 0 ("reserved for future use", lol)
        # Length:           (2 Bytes)   Length of the remaining frame in bytes (Total Length - 6)
        # Unit ID:          (1 Byte)    "Slave ID", inner identifier to route to different units (typically 0)
        # Function Code:    (1 Byte)    1,2,3,4,5,6,15,16,43: Read/Write input/register etc.
        try:
            (
                transaction_id,
                protocol,
                length,
                res_unit_id,
                res_function_code,
            ) = struct.unpack("!HHHBB", response[:8])
            # print(transaction_id, protocol, length, res_unit_id, res_function_code)
        except struct.error:
            logger.error(f"Received incompatible bytes {response}")
            return None
        if transaction_id != current_transaction_id:
            logger.error(f"Received non-matching Transaction ID {transaction_id}")
            return None
        if res_function_code == 128:
            logger.error("Illegal Function")
            return None
        if res_function_code == 129:
            logger.error("Illegal Data Address")
            return None
        if res_function_code == 130:
            logger.error("Illegal Data Value")
            return None
        if res_function_code == 131:
            logger.error("Slave Device Failure")
            return None
        if length != len(response) - 6:
            logger.error(
                f"Response Length field ({length}) not consistent with remaining length of frame ({len(response)-6})"
            )
            return None
        if res_unit_id != self.unit_id:
            logger.error(
                f"Wrong unit ID: Received {res_unit_id}, asked for {self.unit_id}"
            )
            return None
        if res_function_code != function_code:
            logger.error(
                f"Wrong function_code: Received {res_function_code}, requested {function_code}"
            )
            return None
        return response[8:]
    def _read_bits(self, function_code, address, quantity=1):
        if address < 0 or address > 65536:
            raise ValueError(f"Address must be in 0 ... 65536, not {address}")
        if quantity < 1:
            raise ValueError(f"Quantity of registers must be >= 1")
        if function_code in (1, 2) and quantity > 2000:
            raise ValueError(
                f"Quantity of coils/discrete inputs must be < 2000, not {quantity}"
            )
        data_frame = struct.pack("!HH", address, quantity)
        response = self.send_request(function_code, data_frame)
        if not response:  # Error, should be in log
            return None
        data_length = struct.unpack("!B", response[0:1])[0]
        if len(response[1:]) != data_length:
            logger.error(
                f"Wrong data length: Header says {data_length}, data length is {len(response[1:])}"
            )
            return None
        data = response[1:]
        data_ints = struct.unpack(f"!{data_length}B", response[1:])
        bool_list = []
        for data_int in data_ints:
            # There must be a better way! (to convert bytes to a list of booleans)
            bool_list.extend(
                [bool(int(i)) for i in reversed(list(format(data_int, "b")))]
            )
        # Return bool or list(bool):
        if len(bool_list) == 1:
            return bool_list[0]
        else:
            return bool_list
    def _read_registers(self, function_code, address, quantity=1, encoding="H"):
        if not type(address) == int or address < 0 or address > 65535:
            raise ValueError(
                f"Address must be an integer between 0 and 65535, not {address}"
            )
        if quantity < 1:
            raise ValueError(f"Quantity of registers must be >= 1")
        if quantity > 125:
            raise ValueError(f"Quantity of registers must be < 125, not {quantity}")
        if encoding not in ("H", "h", "e", "f"):
            raise ValueError(f"encoding must be 'H', 'h', or 'e'")
        if encoding in ("f"):
            quantity *= 2
        data_frame = struct.pack("!HH", address, quantity)
        response = self.send_request(function_code, data_frame)
        if not response:  # Error, should be in log
            return None
        data_length = struct.unpack("!B", response[0:1])[0]
        if len(response[1:]) != data_length:
            logger.error(
                f"Wrong data length: Header says {data_length}, data length is {len(response[1:])}"
            )
            return None
        number_of_values = data_length // struct.calcsize(encoding)
        values = struct.unpack(f"!{number_of_values}{encoding}", response[1:])
        if len(values) == 1:
            return values[0]
        else:
            return values
    def read_coil(self, address):
        return self._read_bits(1, address)
    def read_coils(self, address, quantity=1):
        return self._read_bits(1, address, quantity)
    def read_discrete_input(self, address, quantity=1):
        return self._read_bits(2, address)
    def read_discrete_inputs(self, address, quantity=1):
        return self._read_bits(2, address, quantity)
    def read_holding_register(self, address, quantity=1, encoding="H"):
        return self._read_registers(3, address, quantity, encoding)
    def read_holding_registers(self, address, encoding="H"):
        return self._read_registers(3, address, encoding=encoding)
    def read_input_register(self, address, quantity=1, encoding="H"):
        return self._read_registers(4, address, quantity, encoding)
    def read_input_registers(self, address, encoding="H"):
        return self._read_registers(4, address, encoding=encoding)

import copy
from ansible_filter.helpers import array_to_dict
STATE_KEY = 'state'
STATE_PRESENT = 'present'
STATE_ABSENT = 'absent'
ACTION_KEY = 'action'
ACTION_CREATE = 'create'
ACTION_UPDATE = 'update'
ACTION_NOOP = 'noop'
ACTION_DELETE = 'delete'
OBJ_KEY = 'value'
def dict_to_array(obj_dict):
    obj_array = []
    for obj_key, obj_value in obj_dict.items():
        obj_array.append(obj_value)
    return obj_array
def get_action(local_obj, origin_obj, state, origin_default):
    if not origin_obj:
        result = ACTION_CREATE if state == STATE_PRESENT else ACTION_NOOP
    elif is_equal_obj(local_obj, origin_obj):
        result = ACTION_NOOP if state == STATE_PRESENT or is_equal_obj(origin_default, origin_obj) else ACTION_DELETE
    else:
        result = ACTION_UPDATE if state == STATE_PRESENT else ACTION_DELETE
    return result
def str2bool(v):
    return v.lower() in ("yes", "true", "t", "1")
def is_equal_obj(local_obj, origin_obj):
    result = None
    if is_all_empty(local_obj, origin_obj):
        result = True
    elif is_any_bool(local_obj, origin_obj):
        result = is_equal_bool(local_obj, origin_obj)
    elif is_all_dict(local_obj, origin_obj):
        result = is_equal_dict(local_obj, origin_obj)
    elif is_list(local_obj) and is_list(origin_obj):
        result = is_equal_list(local_obj, origin_obj)
    elif local_obj != origin_obj:
        result = False
    return True if result is None else result
def is_equal_bool(left, right):
    if not isinstance(left, bool):
        left = str2bool(left)
    if not isinstance(right, bool):
        right = str2bool(right)
    return left is right
def is_equal_list(left, right):
    if len(left) != len(right):
        return False
    for i in range(len(left)):
        local_value = left[i]
        origin_value = right[i]
        if not is_equal_obj(local_value, origin_value):
            return False
    return True
def is_equal_dict(left, right):
    for key, local_value in left.items():
        origin_value = right.get(key)
        if not is_equal_obj(local_value, origin_value):
            return False
    return True
def is_any_bool(left, right):
    return isinstance(left, bool) or isinstance(right, bool)
def is_all_empty(left, right):
    return is_empty(left) and is_empty(right)
def is_all_dict(left, right):
    return is_dict(left) and is_dict(right)
def is_all_list(left, right):
    return is_list(left) and is_list(right)
def is_dict(obj):
    return isinstance(obj, dict)
def is_list(obj):
    return isinstance(obj, list)
def is_empty(value):
    if value:
        return False
    return True
def remove_state(obj):
    return obj.pop(STATE_KEY, STATE_PRESENT)
def update_obj(obj, origin_obj):
    if origin_obj:
        updated_obj = copy.deepcopy(origin_obj)
        updated_obj.update(obj)
    else:
        updated_obj = obj
    return updated_obj
def change_set(local, origin, origin_default=None, attr='name'):
    result_dict = {
        ACTION_CREATE: [],
        ACTION_UPDATE: [],
        ACTION_DELETE: [],
        ACTION_NOOP: []
    }
    if not local:
        return result_dict
    if is_dict(local):
        origin = {} if not is_dict(origin) else origin
        change_set_item(result_dict, local, origin, origin_default)
        return result_dict
    if is_list(local):
        local_dict = array_to_dict(local, attr)
        origin_dict = {} if not is_list(origin) else array_to_dict(origin, attr)
        change_set_items(result_dict, local_dict, origin_dict, origin_default)
        return result_dict
    raise TypeError('Can not build change set for given objects: ' + str(local) + ", " + str(origin))
def change_set_item(result_dict, local_obj, origin_obj, origin_default):
    obj = copy.deepcopy(local_obj)
    state = remove_state(obj)
    action = get_action(obj, origin_obj, state, origin_default)
    obj = update_obj(obj, origin_obj)
    result_dict[action].append(obj)
def change_set_items(result_dict, local_dict, origin_dict, origin_default):
    for obj_key, local_obj in local_dict.items():
        origin_obj = origin_dict.get(obj_key)
        change_set_item(result_dict, local_obj, origin_obj, origin_default)

