from __future__ import annotations
import logging
import os
from dataclasses import dataclass
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List, Optional, Union
import drmaa2
from .scheduler_mode_interface import SchedulerModeInterface
from .utils import check_jobscript_is_readable
@dataclass
class StatusInfo:
    '''Class for keeping track of job status.'''
    job: drmaa2.Job
    output_path: Path
    i: int
    info: Optional[drmaa2.JobInfo] = None
    state: Optional[drmaa2.JobState] = None
    final_state: Optional[str] = None
class JobScheduler:
    def __init__(self, working_directory: Optional[Union[Path, str]], cluster_output_dir: Optional[Union[Path, str]], project: str,
                 queue: str, cluster_resources: Optional[dict[str,str]] = None, timeout: timedelta = timedelta(hours=2)):
        """JobScheduler can be used for cluster job submissions"""
        self.batch_number = 0
        self.cluster_output_dir: Optional[Path] = Path(cluster_output_dir) if cluster_output_dir else None
        self.job_completion_status: Dict[str, bool] = {}
        self.job_history: Dict[int, Dict[int, StatusInfo]] = {}
        self.jobscript: Path
        self.job_env: Optional[Dict[str, str]] = None
        self.jobscript_args: List
        self.output_paths: List[Path] = []
        self.project = self.check_project_list(project)
        self.queue = self.check_queue_list(queue)
        self.start_time = datetime.now()
        self.status_infos: List[StatusInfo]
        self.timeout = timeout
        self.working_directory = Path(working_directory) if working_directory else Path.home()
        self.resources: Dict[str, str] = {}
        if cluster_resources:
            self.resources.update(cluster_resources)
        self.scheduler_mode : SchedulerModeInterface
        self.memory : str
        self.cores : int
        self.job_name : str
    def check_queue_list(self, queue: str) -> str:
        if not queue:
            raise ValueError(f"queue must be non-empty string")
        queue = queue.lower()
        with os.popen('qconf -sql') as q_proc:
            q_name_list = q_proc.read().split()
        if queue in q_name_list:
            return queue
        else:
            raise ValueError(f"queue {queue} not in queue list: {q_name_list}\n")
    def check_project_list(self, project: str) -> str:
        if not project:
            raise ValueError(f"project must be non-empty string")
        with os.popen('qconf -sprjl') as prj_proc:
            prj_name_list = prj_proc.read().split()
        if project in prj_name_list:
            return project
        else:
            raise ValueError(f"{project} must be in list of project names: {prj_name_list}\n")
    def get_output_paths(self) -> List[Path]:
        return self.output_paths
    def get_success(self) -> bool:
        return all(self.job_completion_status.values())
    def timestamp_ok(self, output: Path) -> bool:
        mod_time = datetime.fromtimestamp(output.stat().st_mtime)
        if mod_time > self.start_time:
            return True
        return False
    def run(self, scheduler_mode: SchedulerModeInterface, jobscript: Path, job_env: Dict[str,str], memory: str = "4G",
            cores: int = 6, jobscript_args: Optional[List] = None, job_name: str = "ParProcCo_job") -> bool:
        self.jobscript = check_jobscript_is_readable(jobscript)
        self.job_env = job_env
        self.scheduler_mode = scheduler_mode
        self.memory = memory
        self.cores = cores
        self.job_name = job_name
        job_indices = list(range(scheduler_mode.number_jobs))
        if jobscript_args is None:
            jobscript_args = []
        self.jobscript_args = jobscript_args
        self.job_history[self.batch_number] = {}
        self.job_completion_status = {str(i): False for i in range(scheduler_mode.number_jobs)}
        self.output_paths.clear()
        return self._run_and_monitor(job_indices)
    def _run_and_monitor(self, job_indices: List[int]) -> bool:
        session = drmaa2.JobSession()  # Automatically destroyed when it is out of scope
        self._run_jobs(session, job_indices)
        self._wait_for_jobs(session)
        self._report_job_info()
        return self.get_success()
    def _run_jobs(self, session: drmaa2.JobSession, job_indices: List[int]) -> None:
        logging.debug(f"Running jobs on cluster for jobscript {self.jobscript} and args {self.jobscript_args}")
        try:
            # Run all input paths in parallel:
            self.status_infos = []
            for i in job_indices:
                template = self._create_template(i)
                logging.debug(f"Submitting drmaa job with jobscript {self.jobscript} and args {template.args}")
                job = session.run_job(template)
                self.status_infos.append(StatusInfo(job, Path(template.output_path), i))
                logging.debug(
                    f"drmaa job for jobscript {self.jobscript} and args {template.args}"
                    f" has been submitted with id {job.id}")
        except drmaa2.Drmaa2Exception:
            logging.error(f"Drmaa exception", exc_info=True)
            raise
        except Exception:
            logging.error(f"Unknown error occurred running drmaa job", exc_info=True)
            raise
    def _create_template(self, i: int) -> drmaa2.JobTemplate:
        if self.cluster_output_dir:
            if not self.cluster_output_dir.is_dir():
                logging.debug(f"Making directory {self.cluster_output_dir}")
                self.cluster_output_dir.mkdir(exist_ok=True, parents=True)
            else:
                logging.debug(f"Directory {self.cluster_output_dir} already exists")
            error_dir = self.cluster_output_dir / "cluster_logs"
        else:
            error_dir = self.working_directory / "cluster_logs"
        if not error_dir.is_dir():
            logging.debug(f"Making directory {error_dir}")
            error_dir.mkdir(exist_ok=True, parents=True)
        else:
            logging.debug(f"Directory {error_dir} already exists")
        output_fp, stdout_fp, stderr_fp = self.scheduler_mode.generate_output_paths(self.cluster_output_dir, error_dir, i, self.start_time)
        if output_fp and output_fp not in self.output_paths:
            self.output_paths.append(Path(output_fp))
        args = self.scheduler_mode.generate_args(i, self.memory, self.cores, self.jobscript_args, output_fp)
        logging.info(f"creating template with jobscript: {str(self.jobscript)} and args: {args}")
        self.resources["m_mem_free"] = self.memory
        jt = drmaa2.JobTemplate({
            "job_name": self.job_name,
            "job_category": self.project,
            "remote_command": str(self.jobscript),
            "min_slots": self.cores,
            "args": args,
            "resource_limits": self.resources,
            "working_directory": str(self.working_directory),
            "output_path": stdout_fp,
            "error_path": stderr_fp,
            "queue_name": self.queue,
            "implementation_specific": {
                "uge_jt_pe": f"smp",
            },
        })
        job_env = dict(self.job_env) if self.job_env is not None else {}
        test_ppc_dir = os.getenv("TEST_PPC_DIR")
        if test_ppc_dir:
            logging.debug('Adding TEST_PPC_DIR=%s to environment', test_ppc_dir)
            job_env.update(TEST_PPC_DIR=test_ppc_dir)
        jt.job_environment = job_env
        return jt
    def _wait_for_jobs(self, session: drmaa2.JobSession) -> None:
        try:
            job_list = [status_info.job for status_info in self.status_infos]
            # Wait for jobs to start (timeout shouldn't include queue time)
            job_list_str = ", ".join([str(job.id) for job in job_list])
            logging.info(f"Waiting for jobs to start: {job_list_str}")
            session.wait_all_started(job_list)
            logging.info(f"Jobs started, waiting for jobs: {job_list_str}")
            session.wait_all_terminated(job_list, int(round(self.timeout.total_seconds())))
            jobs_running = False
            for job in job_list:
                if job.get_state()[0] == drmaa2.JobState.RUNNING:
                    logging.warning(f"Job {job.id} timed out. Terminating job now.")
                    jobs_running = True
                    job.terminate()
            if jobs_running:
                # Termination takes some time, wait a max of 2 mins
                session.wait_all_terminated(job_list, 120)
        except drmaa2.Drmaa2Exception:
            logging.error(f"Drmaa exception", exc_info=True)
        except Exception:
            logging.error(f"Unknown error occurred running drmaa job", exc_info=True)
    def _report_job_info(self) -> None:
        # Iterate through jobs with logging to check individual job outcomes
        for status_info in self.status_infos:
            logging.debug(f"Retrieving info for drmaa job {status_info.job.id}")
            try:
                status_info.state = status_info.job.get_state()[0]  # Returns job state and job substate (always seems to be None)
                status_info.info = status_info.job.get_info()
            except Exception:
                logging.error(f"Failed to get job information for job {status_info.job.id}", exc_info=True)
                raise
            try:
                time_to_dispatch = status_info.info.dispatch_time - status_info.info.submission_time
                wall_time = status_info.info.finish_time - status_info.info.dispatch_time
            except Exception:
                logging.error(f"Failed to get job submission time statistics for job {status_info.job.id}")
                raise
            # Check job states against expected possible options:
            if status_info.state == drmaa2.JobState.UNDETERMINED:  # Lost contact?
                status_info.final_state = "UNDETERMINED"
                logging.warning(
                    f"Job state undetermined for job {status_info.job.id}. job info: {status_info.info}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif status_info.state == drmaa2.JobState.FAILED:
                status_info.final_state = "FAILED"
                logging.error(
                    f"drmaa job {status_info.job.id} failed. Terminating signal: {status_info.info.terminating_signal}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif not status_info.output_path.is_file():
                status_info.final_state = "NO_OUTPUT"
                logging.error(
                    f"drmaa job {status_info.job.id} with args {self.jobscript_args} has not created"
                    f" output file {status_info.output_path}"
                    f" Terminating signal: {status_info.info.terminating_signal}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif not self.timestamp_ok(status_info.output_path):
                status_info.final_state = "OLD_OUTPUT_FILE"
                logging.error(
                    f"drmaa job {status_info.job.id} with args {self.jobscript_args} has not created"
                    f" a new output file {status_info.output_path}"
                    f" Terminating signal: {status_info.info.terminating_signal}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif status_info.state == drmaa2.JobState.DONE:
                self.job_completion_status[str(status_info.i)] = True
                status_info.final_state = "SUCCESS"
                logging.info(
                    f"Job {status_info.job.id} with args {self.jobscript_args} completed."
                    f" CPU time: {timedelta(seconds=float(status_info.info.cpu_time))}; Slots: {status_info.info.slots}"
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            else:
                status_info.final_state = "UNSPECIFIED"
                logging.error(
                    f"Unexpected job state for job {status_info.job.id}"
                    f" with args {self.jobscript_args}, job info: {status_info.info}"
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            self.job_history[self.batch_number][status_info.job.id] = status_info
    def resubmit_jobs(self, job_indices: List[int]) -> bool:
        self.batch_number += 1
        self.job_history[self.batch_number] = {}
        self.job_completion_status = {str(i): False for i in job_indices}
        logging.info(f"Resubmitting jobs with job_indices: {job_indices}")
        return self._run_and_monitor(job_indices)
    def filter_killed_jobs(self, jobs: List[drmaa2.Job]) -> List[drmaa2.Job]:
        killed_jobs = [job for job in jobs if job.info.terminating_signal == "SIGKILL"]
        return killed_jobs
    def rerun_killed_jobs(self, allow_all_failed: bool = False):
        logging.info("Rerunning killed jobs")
        job_history = self.job_history
        if all(self.job_completion_status.values()):
            logging.warning("No failed jobs to rerun")
            return True
        elif allow_all_failed or any(self.job_completion_status.values()):
            failed_jobs = [job_info for job_info in job_history[0].values() if job_info.final_state != "SUCCESS"]
            killed_jobs = self.filter_killed_jobs(failed_jobs)
            killed_jobs_indices = [job.i for job in killed_jobs]
            logging.info(f"Total failed_jobs: {len(failed_jobs)}. Total killed_jobs: {len(killed_jobs)}")
            success = self.resubmit_jobs(killed_jobs_indices)
            return success
        raise RuntimeError(f"All jobs failed. job_history: {job_history}\n")

import logging
import multiprocessing
import os
import re
import sys
import time
from copy import deepcopy

import psutil

from pyro.Anonymizer import Anonymizer
from pyro.Enums.BuildEvent import BuildEvent
from pyro.Comparators import is_command_node
from pyro.PackageManager import PackageManager
from pyro.PapyrusProject import PapyrusProject
from pyro.PathHelper import PathHelper
from pyro.PexReader import PexReader
from pyro.ProcessManager import ProcessManager
from pyro.Enums.ProcessState import ProcessState
from pyro.TimeElapsed import TimeElapsed

from pyro.Comparators import endswith


class BuildFacade:
    log: logging.Logger = logging.getLogger('pyro')

    ppj: PapyrusProject = None

    time_elapsed: TimeElapsed = TimeElapsed()

    scripts_count: int = 0
    success_count: int = 0
    command_count: int = 0

    @property
    def failed_count(self) -> int:
        return self.command_count - self.success_count

    @property
    def build_time(self) -> str:
        raw_time, avg_time = ('{0:.3f}s'.format(t)
                              for t in (self.time_elapsed.value(), self.time_elapsed.average(self.success_count)))

        return f'Compilation time: ' \
               f'{raw_time} ({avg_time}/script) - ' \
               f'{self.success_count} succeeded, ' \
               f'{self.failed_count} failed ' \
               f'({self.scripts_count} scripts)'

    def __init__(self, ppj: PapyrusProject) -> None:
        self.ppj = ppj

        self.scripts_count = len(self.ppj.psc_paths)

        # WARN: if methods are renamed and their respective option names are not, this will break.
        options: dict = deepcopy(self.ppj.options.__dict__)

        for key in options:
            if key in ('args', 'input_path', 'anonymize', 'package', 'zip', 'zip_compression'):
                continue
            if key.startswith(('ignore_', 'no_', 'force_', 'resolve_')):
                continue
            if key.endswith('_token'):
                continue
            setattr(self.ppj.options, key, getattr(self.ppj, f'get_{key}')())

    def _find_modified_scripts(self) -> list:
        pex_paths: list = []

        for object_name, script_path in self.ppj.psc_paths.items():
            script_name, _ = os.path.splitext(os.path.basename(script_path))

            # if pex exists, compare time_t in pex header with psc's last modified timestamp
            pex_match: list = [pex_path for pex_path in self.ppj.pex_paths if endswith(pex_path, f'{script_name}.pex', ignorecase=True)]
            if not pex_match:
                continue

            pex_path: str = pex_match[0]
            if not os.path.isfile(pex_path):
                continue

            try:
                header = PexReader.get_header(pex_path)
            except ValueError:
                BuildFacade.log.warning(f'Cannot determine compilation time due to unknown magic: "{pex_path}"')
                continue

            psc_last_modified: float = os.path.getmtime(script_path)
            pex_last_compiled: float = float(header.compilation_time.value)

            # if psc is older than the pex
            if psc_last_modified < pex_last_compiled:
                pex_paths.append(pex_path)

        return PathHelper.uniqify(pex_paths)

    @staticmethod
    def _limit_priority() -> None:
        process = psutil.Process(os.getpid())
        process.nice(psutil.BELOW_NORMAL_PRIORITY_CLASS if sys.platform == 'win32' else 19)

    def try_build_event(self, event: BuildEvent) -> None:
        if event == BuildEvent.PRE:
            has_event_node, event_node = self.ppj.has_pre_build_node, self.ppj.pre_build_node
        elif event == BuildEvent.POST:
            has_event_node, event_node = self.ppj.has_post_build_node, self.ppj.post_build_node
        else:
            raise NotImplementedError

        if has_event_node:
            BuildFacade.log.info(event_node.get('Description'))

            reformat = lambda s: re.sub('[ \t\n\r]+', ' ', s.strip())

            environ: dict = os.environ.copy()
            command: str = ' && '.join(reformat(node.text) for node in filter(is_command_node, event_node))

            ProcessManager.run_command(command, self.ppj.project_path, environ)

    def try_compile(self) -> None:
        """Builds and passes commands to Papyrus Compiler"""
        commands: list = self.ppj.build_commands()

        self.command_count = len(commands)

        self.time_elapsed.start_time = time.time()

        if self.ppj.options.no_parallel or self.command_count == 1:
            for command in commands:
                if ProcessManager.run_compiler(command) == ProcessState.SUCCESS:
                    self.success_count += 1
        elif self.command_count > 0:
            multiprocessing.freeze_support()
            worker_limit = min(self.command_count, self.ppj.options.worker_limit)
            pool = multiprocessing.Pool(processes=worker_limit,
                                        initializer=BuildFacade._limit_priority)
            for state in pool.imap(ProcessManager.run_compiler, commands):
                if state == ProcessState.SUCCESS:
                    self.success_count += 1
            pool.close()
            pool.join()

        self.time_elapsed.end_time = time.time()

    def try_anonymize(self) -> None:
        """Obfuscates identifying metadata in compiled scripts"""
        scripts: list = self._find_modified_scripts()

        if not scripts and not self.ppj.missing_scripts and not self.ppj.options.no_incremental_build:
            BuildFacade.log.error('Cannot anonymize compiled scripts because no source scripts were modified')
        else:
            # these are absolute paths. there's no reason to manipulate them.
            for pex_path in self.ppj.pex_paths:
                if not os.path.isfile(pex_path):
                    BuildFacade.log.warning(f'Cannot locate file to anonymize: "{pex_path}"')
                    continue

                Anonymizer.anonymize_script(pex_path)

    def try_pack(self) -> None:
        """Generates BSA/BA2 packages for project"""
        package_manager = PackageManager(self.ppj)
        package_manager.create_packages()

    def try_zip(self) -> None:
        """Generates ZIP file for project"""
        package_manager = PackageManager(self.ppj)
        package_manager.create_zip()

from opentrons.protocol_api.labware import Well
from opentrons.types import Location
CommandLocation = Union[Location, None, Sequence, Well]
def listify(location: Any) -> List:
    if isinstance(location, list):
        try:
            return listify(location[0])
        except IndexError:
            return [location]
    else:
        return [location]
def _stringify_new_loc(loc: Union[Location, Well]) -> str:
    if isinstance(loc, Location):
        if loc.labware.is_empty:
            return str(loc.point)
        else:
            return repr(loc.labware)
    elif isinstance(loc, Well):
        return str(loc)
    else:
        raise TypeError(loc)
def stringify_location(location: CommandLocation) -> str:
    loc_str_list = [_stringify_new_loc(loc) for loc in listify(location)]
    return ", ".join(loc_str_list)

from typing import Any, Dict, Tuple
from collections import OrderedDict
from collections.abc import Iterable
from mypyc.ops import (
    deserialize_modules, DeserMaps, ModuleIR, FuncDecl, FuncIR, ClassIR, FuncSignature, RType
)
from mypyc.sametype import is_same_type, is_same_signature
def get_dict(x: Any) -> Dict[str, Any]:
    if hasattr(x, '__mypyc_attrs__'):
        return {k: getattr(x, k) for k in x.__mypyc_attrs__ if hasattr(x, k)}
    else:
        return dict(x.__dict__)
def get_function_dict(x: FuncIR) -> Dict[str, Any]:
    """Get a dict of function attributes safe to compare across serialization"""
    d = get_dict(x)
    d.pop('blocks', None)
    d.pop('env', None)
    return d
def assert_blobs_same(x: Any, y: Any, trail: Tuple[Any, ...]) -> None:
    """Compare two blobs of IR as best we can.
    FuncDecls, FuncIRs, and ClassIRs are compared by fullname to avoid
    infinite recursion.
    (More detailed comparisions should be done manually.)
    Types and signatures are compared using mypyc.sametype.
    Containers are compared recursively.
    Anything else is compared with ==.
    The `trail` argument is used in error messages.
    """
    assert type(x) is type(y), ("Type mismatch at {}".format(trail), type(x), type(y))
    if isinstance(x, (FuncDecl, FuncIR, ClassIR)):
        assert x.fullname == y.fullname
    elif isinstance(x, OrderedDict):
        assert len(x.keys()) == len(y.keys()), "Keys mismatch at {}".format(trail)
        for (xk, xv), (yk, yv) in zip(x.items(), y.items()):
            assert_blobs_same(xk, yk, trail + ("keys",))
            assert_blobs_same(xv, yv, trail + (xk,))
    elif isinstance(x, dict):
        assert x.keys() == y.keys(), "Keys mismatch at {}".format(trail)
        for k in x.keys():
            assert_blobs_same(x[k], y[k], trail + (k,))
    elif isinstance(x, Iterable) and not isinstance(x, str):
        for i, (xv, yv) in enumerate(zip(x, y)):
            assert_blobs_same(xv, yv, trail + (i,))
    elif isinstance(x, RType):
        assert is_same_type(x, y), "RType mismatch at {}".format(trail)
    elif isinstance(x, FuncSignature):
        assert is_same_signature(x, y), "Signature mismatch at {}".format(trail)
    else:
        assert x == y, "Value mismatch at {}".format(trail)
def assert_modules_same(ir1: ModuleIR, ir2: ModuleIR) -> None:
    """Assert that two module IRs are the same (*).
    * Or rather, as much as we care about preserving across
    serialization.  We drop the actual IR bodies of functions but try
    to preserve everything else.
    """
    assert ir1.fullname == ir2.fullname
    assert ir1.imports == ir2.imports
    for cls1, cls2 in zip(ir1.classes, ir2.classes):
        assert_blobs_same(get_dict(cls1), get_dict(cls2), (ir1.fullname, cls1.fullname))
    for fn1, fn2 in zip(ir1.functions, ir2.functions):
        assert_blobs_same(get_function_dict(fn1), get_function_dict(fn2),
                          (ir1.fullname, fn1.fullname))
        assert_blobs_same(get_dict(fn1.decl), get_dict(fn2.decl),
                          (ir1.fullname, fn1.fullname))
    assert_blobs_same(ir1.final_names, ir2.final_names, (ir1.fullname, 'final_names'))
def check_serialization_roundtrip(irs: Dict[str, ModuleIR]) -> None:
    """Check that we can serialize modules out and deserialize them to the same thing."""
    serialized = {k: ir.serialize() for k, ir in irs.items()}
    ctx = DeserMaps({}, {})
    irs2 = deserialize_modules(serialized, ctx)
    assert irs.keys() == irs2.keys()
    for k in irs:
        assert_modules_same(irs[k], irs2[k])

from typing import Tuple
import numpy as np
import torch
from torch import matmul
def regularize_matrix(mat, regularization, relative_to_diag_mean=True):
    if regularization > 0:
        assert len(set(mat.shape[-2:])) == 1, "matrix must be square"
        if relative_to_diag_mean:
            diag_mean = batch_diag(mat).mean(dim=-1, keepdim=True)
            diag_regularization = batch_diag_matrix(
                torch.ones_like(mat[..., 0]) * diag_mean * regularization
            )
        else:
            diag_regularization = batch_diag_matrix(
                torch.ones_like(mat[..., 0]) * regularization
            )
        regularized_mat = mat + diag_regularization
    else:
        regularized_mat = mat
    return regularized_mat
def cholesky(
    mat,
    upper=False,
    out=None,
    regularization=0.0,
    initial_try_regularization=1e-6,
    max_regularization=1e2,
    step_factor=10,
    warning=True,
):
    if regularization > 0 and warning:
        warnings.warn(f"regularizing matrix with value: {regularization}")
        regularized_mat = regularize_matrix(
            mat=mat, regularization=regularization, relative_to_diag_mean=True
        )
    else:
        regularized_mat = mat
    try:
        # TODO: there is currently a magma bug that occurs for certain batch sizes.
        #  github issue: https://github.com/pytorch/pytorch/issues/26996
        #  see also https://discuss.pytorch.org/t/cuda-illegal-memory-access-when-using-batched-torch-cholesky/51624/8
        #  for the temporary hack used below
        # device = regularized_mat.device
        # return torch.cholesky(regularized_mat.to("cpu"), upper=upper, out=out).to(device)
        # TODO: bug still exists, but only for certain batch sizes. This slows down too much
        return torch.cholesky(regularized_mat, upper=upper, out=out)
    except RuntimeError:
        if torch.isnan(mat).any():
            raise ValueError("NaN detected in input mat.")
        else:
            regularization = max(
                regularization * step_factor, initial_try_regularization
            )
            if regularization > max_regularization:
                raise ValueError(
                    f"attempted regularization greater than "
                    f"max_regularization: {max_regularization}."
                )
            else:
                return cholesky(
                    mat=mat,
                    upper=upper,
                    out=out,
                    regularization=regularization,
                )
def cov_and_chol_from_invcholesky_param(Linv_tril, Linv_logdiag):
    L = torch.inverse(
        torch.tril(Linv_tril, -1) + batch_diag_matrix(torch.exp(Linv_logdiag))
    )
    return matmul(L, L.transpose(-1, -2)), L
def cov_from_invcholesky_param(Linv_tril, Linv_logdiag):
    return cov_and_chol_from_invcholesky_param(
        Linv_tril=Linv_tril, Linv_logdiag=Linv_logdiag
    )[0]
def inv_from_invcholesky_param(Linv_tril, Linv_logdiag):
    Linv = torch.tril(Linv_tril, -1) + batch_diag_matrix(
        torch.exp(Linv_logdiag)
    )
    return matmul(Linv.transpose(-1, -2), Linv)
def batch_cholesky_inverse(Lmat):
    """
    performs torch.cholesky_inverse for matrices with leading
    match dimensions.
    Note that torch can do batched torch.cholesky but not torch.cholesky_inverse
    """
    Lmatinv = torch.inverse(Lmat)
    return matmul(Lmatinv.transpose(-1, -2), Lmatinv)
def batch_diag(mat):
    return mat[..., torch.arange(mat.shape[-2]), torch.arange(mat.shape[-1])]
def batch_diag_matrix(diagonal):
    N = diagonal.shape[-1]
    shape = diagonal.shape[:-1] + (N, N)
    device, dtype = diagonal.device, diagonal.dtype
    result = torch.zeros(shape, dtype=dtype, device=device)
    indices = torch.arange(result.numel(), device=device).reshape(shape)
    indices = indices.diagonal(dim1=-2, dim2=-1)
    result.view(-1)[indices] = diagonal
    return result
def symmetrize(mat):
    return 0.5 * (mat + mat.transpose(-1, -2))
def matvec(mat, vec):
    if vec.ndim == 1:
        return torch.matmul(mat, vec)
    elif mat.ndim == 2:
        return torch.matmul(vec, mat.transpose(1, 0))
    else:
        return torch.matmul(mat, vec[..., None])[..., 0]
def get_numerical_precision(x):
    if isinstance(x, float):
        eps = np.finfo(np.array(x).dtype).eps
    elif isinstance(x, (torch.Tensor,)):
        eps = torch.finfo(x.dtype).eps
    elif isinstance(x, (np.ndarray, np.generic)):
        eps = np.finfo(x.dtype).eps
    else:
        raise ValueError("unknown dtype of {}".format(x))
    return eps
def stable_log(x, eps=None):
    eps = get_numerical_precision(x) if eps is None else eps
    return torch.log(x + eps)
# def kron(A, B):
#     res_vec = torch.matmul(A[:, None, :, None], B[None, :, None, :])
#     return res_vec.reshape([A.shape[0] * B.shape[0], A.shape[1] * B.shape[1]])
def kron(A, B):
    """
    Kronecker Product.
    Works with batch dimemsion(s) - requires both A and B have same batch dims.
    """
    A_shp, B_shp = A.shape, B.shape
    assert A_shp[:-2] == B_shp[:-2]
    kron_block = torch.matmul(
        A[..., :, None, :, None], B[..., None, :, None, :]
    )
    kron = kron_block.reshape(
        A_shp[:-2] + (A_shp[-2] * B_shp[-2], A_shp[-1] * B_shp[-1],)
    )
    return kron
def vectorize_normal_dist_params(m, V):
    # Take lower-triangular incl. diagonal from covariance matrix of state.
    indices = torch.tril_indices(row=V.shape[-2], col=V.shape[-1], offset=0)
    V_vectorised = V[..., indices[0], indices[1]]
    return torch.cat((m, V_vectorised), dim=-1)
def logmeanexp(self: torch.Tensor, dim: int, keepdim: bool = False):
    return torch.logsumexp(self, dim=dim, keepdim=keepdim) - np.log(
        self.shape[dim]
    )
def make_block_diagonal(mats: Tuple[torch.Tensor]) -> torch.Tensor:
    if not isinstance(mats, (list, tuple)):
        raise Exception("provide list or tuple")
    elif len(mats) > 1:
        off_diag_upper_right = torch.zeros(
            mats[-2].shape[:-1] + (mats[-1].shape[-1],),
            dtype=mats[-1].dtype,
            device=mats[-1].device,
        )
        off_diag_lower_left = torch.zeros(
            mats[-1].shape[:-1] + (mats[-2].shape[-1],),
            dtype=mats[-1].dtype,
            device=mats[-1].device,
        )
        block_diagonal = torch.cat(
            [
                torch.cat([mats[-2], off_diag_upper_right], dim=-1),
                torch.cat([off_diag_lower_left, mats[-1]], dim=-1),
            ],
            dim=-2,
        )
        return make_block_diagonal(tuple(mats[:-2]) + (block_diagonal,))
    else:  # final recursion
        return mats[0]

from __future__ import unicode_literals
import os
from jinja2 import Environment, PackageLoader
from .analyzer import model_check
from .electrum2haros import parse_output, render_result
from .haros2electrum import config2model, render_model
###############################################################################
# Plugin Entry Point
###############################################################################
PLUGIN = 'haros_plugin_electrum'
def configuration_analysis(iface, config):
    if (not config.launch_commands or len(config.nodes.enabled) < 2
            or not config.hpl_properties):
        return
    settings = config.user_attributes.get(PLUGIN, {})
    try:
        _validate_settings(settings)
    except PluginSettingsError as e:
        iface.log_error(e.message)
    jar_path = _get_jar_path(settings)
    scopes = _get_scopes(settings)
    jinja = Jinja()
    try:
        model = config2model(config)
        ele_src = render_model(jinja, model)
        filename = 'model_{}.ele'.format('_'.join(config.name.split()))
        with open(filename, 'w') as f:
            f.write(ele_src)
            f.write('\n')
        iface.export_file(filename)
        output = model_check(jar_path, ele_src, scopes)
        result = parse_output(output, config)
        html = render_result(jinja, result)
        iface.report_runtime_violation('counterexample', html, result.resources)
    except Exception as e:
        iface.log_error(e.message)
def _validate_settings(settings):
    jar = settings.get('jar')
    if not jar:
        raise PluginSettingsError.missing_jar()
    if not isinstance(jar, dict):
        raise PluginSettingsError.jar_not_dict()
    if not 'path' in jar and not 'env' in jar:
        raise PluginSettingsError.missing_jar_path()
    if 'env' in jar and not os.environ.get(jar['env']):
        raise PluginSettingsError.missing_env_var(jar['env'])
    scopes = settings.get('scope')
    if scopes:
        for key in ('time', 'msgs', 'values'):
            n = scopes.get(key)
            if n is not None and (not isinstance(n, int) or n < 0):
                raise PluginSettingsError.invalid_scope(key, n)
def _get_jar_path(settings):
    jar = settings['jar']
    path = jar.get('path')
    if path is None:
        env_var = jar['env']
        path = os.environ[env_var]
    return path
def _get_scopes(settings):
    scopes = settings.get('scope', {})
    if not 'time' in scopes:
        scopes['time'] = 10
    if not 'msgs' in scopes:
        scopes['msgs'] = 9
    if not 'values' in scopes:
        scopes['values'] = 4
    return scopes
###############################################################################
# Data Structures
###############################################################################
def Jinja():
    return Environment(
        loader=PackageLoader(PLUGIN, 'templates'),
        line_statement_prefix=None,
        line_comment_prefix=None,
        trim_blocks=True,
        lstrip_blocks=True,
        autoescape=False
    )
class PluginSettingsError(Exception):
    @classmethod
    def missing_jar(cls):
        return cls('missing `jar` field in plugin settings')
    @classmethod
    def jar_not_dict(cls):
        return cls('expected a dictionary under the `jar` setting')
    @classmethod
    def missing_jar_path(cls):
        return cls('missing .jar path; expected one of `jar:path` or `jar:env`')
    @classmethod
    def missing_env_var(cls, var):
        return cls("missing '{}' env. variable with .jar path".format(var))
    @classmethod
    def invalid_scope(cls, key, n):
        return cls("invalid scope value for '{}': {}".format(key, n))

