from binascii import unhexlify
from functools import lru_cache
from operator import itemgetter
import json
import click
import colormath.color_conversions as cv
import colormath.color_diff as cd
import colormath.color_objects as co
import seaborn as sns
assert 949 == len(sns.xkcd_rgb)  # e.g. 'very light green': '#d1ffbd'
def _hex_to_rgb(hx: str) -> tuple:
    hx = hx.lstrip('#')
    assert 6 == len(hx), hx
    r, g, b = unhexlify(hx)
    return r, g, b
def _hex_to_color(hx: str) -> co.sRGBColor:
    c = co.BaseRGBColor(*_hex_to_rgb(hx))
    return co.sRGBColor(c.rgb_r / 256,
                        c.rgb_g / 256,
                        c.rgb_b / 256)
@lru_cache()
def get_name_to_srgb() -> dict:
    keys = sns.xkcd_rgb.keys()
    return dict(zip(keys, sns.xkcd_palette(keys)))
def _red_check():
    red = co.BaseRGBColor(*_hex_to_rgb('#ff000d'), is_upscaled=True)
    assert red.is_upscaled
    red = get_name_to_srgb()['bright red']
    red = co.sRGBColor(*red)
    assert not red.is_upscaled
    assert '#ff000d' == red.get_rgb_hex() == sns.xkcd_rgb['bright red']
@lru_cache()
def get_color_by_name(name) -> co.sRGBColor:
    return co.sRGBColor(*get_name_to_srgb()[name])
def distance_between_colors(c1: co.sRGBColor,
                            c2: co.sRGBColor) -> float:
    assert isinstance(c1, co.sRGBColor), 'pass a proper color, please'
    return cd.delta_e_cie2000(cv.convert_color(c1, co.LabColor),
                              cv.convert_color(c2, co.LabColor))
def distance_to_all_colors(c1: co.sRGBColor, thresh_dist=22):
    dist = {name: distance_between_colors(c1, get_color_by_name(name))
            for name in sns.xkcd_rgb.keys()}
    dist = {name: round(distance, 2)
            for name, distance in sorted(dist.items(), key=itemgetter(1))
            if distance < thresh_dist}
    return dist
def demo():
    _red_check()
    red = get_color_by_name('bright red')
    for name in 'bright red,red,pink,purple,violet,blue'.split(','):
        d = distance_between_colors(red, get_color_by_name(name))
        print(round(d, 1), name)
    d = distance_to_all_colors(red)
    print('')
    print(json.dumps(d, indent=4))
@click.command()
@click.argument('rgb-hex')
def main(rgb_hex):
    d = distance_to_all_colors(_hex_to_color(rgb_hex))
    print(json.dumps(d, indent=4))
if __name__ == '__main__':
    main()

from .. import types
from .schedule import Stage, create_schedule
def create_scheme(inputs, func):
    """Create a quantization scheme.
    """
    if not isinstance(inputs, list):
        inputs = [inputs]
    return Scheme(inputs, func)
def create_schedule_from_scheme(scheme, name=""):
    """Create a schedule from a scheme.
    """
    return create_schedule(scheme.inputs, func=None, name=name)
class Scheme(object):
    """A quantization scheme.
    """
    def __init__(self, inputs, func):
        self.inputs = inputs
        self.func = func
        # execute and attach stages to function
        ret = func(*inputs)
        for op, stage in Stage._mapping:
            func.__setattr__(op.name, op)
    def downsize(self, inputs, dtype):
        """Downsize a (list of) tensor to the specified integer type.
        """
        if not isinstance(dtype, (types.Int, types.UInt)):
            raise RuntimeError("Downsize to non-integer type is not allowed")
        if not isinstance(inputs, list):
            inputs = [inputs]
        for tensor in inputs:
            tensor.dtype = dtype
    def quantize(self, inputs, dtype):
        """Quantize a (list of) tensor to the specified fixed-point type.
        """
        if not isinstance(dtype, (types.Fixed, types.UFixed)):
            raise RuntimeError("Quantize to integer type is not allowed")
        if not isinstance(inputs, list):
            inputs = [inputs]
        for tensor in inputs:
            tensor.dtype = dtype

from .lib.utils import args_vs_config, choose_repo, get_config, mklog, print_output
from .lib.args import get_args
def get_repos(args, gitlab):
    repos = []
    if not args.repos and not args.groups:
        repos.extend(gitlab.get_all_repos())
    else:
        if args.repos:
            repos.extend(gitlab.get_repos(args.repos))
        if args.groups:
            repos.extend(gitlab.get_group_repos(args.groups))
    if args.interactive:
        repos = choose_repo(repos)
    return repos
def get_members(args, gitlab):
    if args.groups:
        groups = gitlab.get_groups(args.groups)
        return gitlab.get_members(groups, "groups")
    return gitlab.get_members(get_repos(args, gitlab))
def main():
    args = get_args("GitLab")
    args.add_argument("-g", "--groups", nargs="+", help="gitlab group names")
    args = args.parse_args()
    mklog(args.verbosity)
    config = get_config("GitLab")
    token, destination = args_vs_config(args, config)
    gitlab = GitLab(token, destination, args.protocol)
    command_actions = {
        "sync": lambda: gitlab.batch_run(gitlab.clone_or_pull, get_repos(args, gitlab)),
        "status": lambda: gitlab.batch_run(gitlab.status, get_repos(args, gitlab)),
        "jobs": lambda: gitlab.get_last_failed_jobs(get_repos(args, gitlab)),
        "schedules": lambda: gitlab.get_pipeline_schedules(get_repos(args, gitlab)),
        "members": lambda: get_members(args, gitlab),
    }
    output = command_actions[args.command]()
    print_output(output)
if __name__ == "__main__":
    main()

from pathlib import Path
from typing import Dict, List
import toml
@dataclass
class JournalConfiguration:
    """Used to represent configuration for a journal"""
    name: str
    path: Path
    def __str__(self) -> str:
        return f"{self.name} at path: {self.path}"
    def to_dict(self) -> dict:
        """Convert class to dict representation for saving to disk as toml"""
        return {"path": str(self.path)}
@dataclass
class WaldenConfiguration:
    """Used to represent configuration file for walden"""
    config_path: Path
    default_journal_path: Path
    journals: Dict[str, JournalConfiguration]
    def save(self):
        """Write current configuration to disk"""
        config = {
            journal_name: journal_info.to_dict()
            for journal_name, journal_info in self.journals.items()
        }
        config["config_path"] = str(self.config_path)
        config["default_journal_path"] = str(self.default_journal_path)
        self.config_path.write_text(toml.dumps({"walden": config}))

