        if not fileset_id:
            uri = 'https://'+__salt__['pillar.get']('rubrik.node','')+'/api/v1/fileset'
            headers = {'Content-Type':'application/json','Accept':'application/json','Authorization':token}
            payload = '{"hostId":"'+my_host['id']+'","templateId":"'+my_fst['id']+'"}'
