            fileset_id = data['id']
        '''Assign SLA'''
        uri = 'https://'+__salt__['pillar.get']('rubrik.node','')+'/api/v1/fileset/'+fileset_id
        headers = {'Content-Type':'application/json','Accept':'application/json','Authorization':token}
        payload = '{"configuredSlaDomainId":"'+my_sla['id']+'"}'
