from dataclasses import asdict
class UpdateInputTensorConstraints:
    def __init__(self, config=None):
        if config is None:
            config = {}
        self.config = self._make_config(**config)
        self.data_input_predicator = self._make_data_input_predicator(self.config)
        self.model_runnable_predicator = self._make_model_runnable_predicator(
            self.config
        )
        self.num_handled_models = 0
    def _make_data_input_predicator(self, config):
        module = load_module(config["data_input_predicator_filepath"])
        cls = getattr(module, config["data_input_predicator_class_name"])
        return cls(config["data_input_predicator_config"])
    def _make_model_runnable_predicator(self, config):
        module = load_module(config["model_runnable_predicator_filepath"])
        cls = getattr(module, config["model_runnable_predicator_class_name"])
        return cls(config["model_runnable_predicator_config"])
    def _make_config(
        self,
        data_input_predicator_filepath,
        model_runnable_predicator_filepath,
        data_input_predicator_class_name="DataInputPredicator",
        model_runnable_predicator_class_name="ModelRunner",
        data_input_predicator_config=None,
        model_runnable_predicator_config=None,
        dimension_generalizer_filepath=None,
        dimension_generalizer_class_name="StaticToDynamic",
        dimension_generalizer_config=None,
        model_path_prefix="",
        resume=False,
        last_model_log_file=None,
        limits_handled_models=None,
    ):
        if data_input_predicator_config is None:
            data_input_predicator_config = {}
        if model_runnable_predicator_config is None:
            model_runnable_predicator_config = {}
        if dimension_generalizer_config is None:
            dimension_generalizer_config = {}
        return {
            "resume": resume,
            "model_path_prefix": model_path_prefix,
            "data_input_predicator_filepath": data_input_predicator_filepath,
            "data_input_predicator_class_name": data_input_predicator_class_name,
            "data_input_predicator_config": data_input_predicator_config,
            "model_runnable_predicator_filepath": model_runnable_predicator_filepath,
            "model_runnable_predicator_class_name": model_runnable_predicator_class_name,
            "model_runnable_predicator_config": model_runnable_predicator_config,
            "dimension_generalizer_filepath": dimension_generalizer_filepath,
            "dimension_generalizer_class_name": dimension_generalizer_class_name,
            "dimension_generalizer_config": dimension_generalizer_config,
            "last_model_log_file": last_model_log_file,
            "limits_handled_models": limits_handled_models,
        }
    def __call__(self, model_path):
        model_path = os.path.join(self.config["model_path_prefix"], model_path)
        cstr_path = os.path.join(model_path, "input_tensor_constraints.py")
        if (
            self.config["resume"]
            and os.path.exists(cstr_path)
            and DynamicDimConstraints.kSymbols in open(cstr_path).read()
        ):
            module = load_module(cstr_path)
            symbols = getattr(module, DynamicDimConstraints.kSymbols)
            if len(symbols) > 0:
                return
        tensor_metas = self._get_tensor_metas(model_path)
        tensor_meta_attrs_list = [asdict(tensor_meta) for tensor_meta in tensor_metas]
        logging.warning("before create_inputs_by_metas")
        inputs = self.get_dimension_generalizer().create_inputs_by_metas(
            module=self.get_model(model_path),
            tensor_meta_attrs_list=tensor_meta_attrs_list,
        )
        logging.warning("after create_inputs_by_metas")
        dyn_dim_cstr = make_dyn_dim_cstr_from_tensor_metas(tensor_metas)
        def data_input_predicator(input_var_name):
            return self.data_input_predicator(model_path, input_var_name)
        def get_tmp_model_path_ctx_mgr(dim_axes_pairs):
            return self._try_dimension_generalization(
                dim_axes_pairs, model_path, inputs
            )
        def get_predicator_is_dyn_dim_cstr_feasible(tmp_model_path):
            def is_dyn_dim_cstr_feasible(dyn_dim_cstr):
                return self._is_dyn_dim_cstr_feasible(
                    tmp_model_path, tensor_metas, dyn_dim_cstr
                )
            return is_dyn_dim_cstr_feasible
        dyn_dim_cstr_feasibility_ctx_mgr = DynDimCstrFeasibilityContextManager(
            get_tmp_model_path_ctx_mgr=get_tmp_model_path_ctx_mgr,
            get_predicator_is_dyn_dim_cstr_feasible=get_predicator_is_dyn_dim_cstr_feasible,
        )
        dyn_dim_cstr, dim_gen_pass_names = symbolize_data_input_dims(
            dyn_dim_cstr,
            is_data_input=data_input_predicator,
            dyn_dim_cstr_feasibility_ctx_mgr=dyn_dim_cstr_feasibility_ctx_mgr,
        )
        self._save_dyn_dim_cstr(dyn_dim_cstr, model_path)
        self._save_dim_gen_pass_names(dim_gen_pass_names, model_path)
        self.num_handled_models += 1
        limits = self.config["limits_handled_models"]
        if limits is not None:
            if self.num_handled_models >= limits:
                print(
                    "`num_handled_models` exceeds config `limits_handled_models`",
                    file=sys.stderr,
                )
                sys.exit(0)
    def get_dimension_generalizer(self):
        if hasattr(self, "_dim_generalizer"):
            return self._dim_generalizer
        assert self.config["dimension_generalizer_filepath"] is not None
        decorator_cls = getattr(
            load_module(self.config["dimension_generalizer_filepath"]),
            self.config["dimension_generalizer_class_name"],
        )
        self._dim_generalizer = decorator_cls(
            self.config["dimension_generalizer_config"]
        )
        return self._dim_generalizer
    def get_model(self, model_path):
        py_module = load_module(os.path.join(model_path, "model.py"))
        GraphModule = getattr(py_module, "GraphModule")
        GraphModule.__graph_net_file_path__ = py_module.__graph_net_file_path__
        return GraphModule()
    @contextmanager
    def _try_dimension_generalization(self, dim_axes_pairs, model_path, inputs):
        logging.warning("enter _try_dimension_generalization")
        if self.config["dimension_generalizer_filepath"] is None:
            self._save_model_to_log_file(model_path)
            yield model_path, ()
            return
        model = self.get_model(model_path)
        dim_generalizer = self.get_dimension_generalizer()
        dim_gen_pass = dim_generalizer(model, dim_axes_pairs)
        logging.warning("before need_rewrite")
        need_rewrite = dim_gen_pass.need_rewrite(inputs)
        logging.warning("after need_rewrite")
        if not need_rewrite:
            self._save_model_to_log_file(model_path)
            yield model_path, ()
            return
        logging.warning("before rewrite")
        graph_module = dim_gen_pass.rewrite(inputs)
        logging.warning("after rewrite")
        with tempfile.TemporaryDirectory() as tmp_dir:
            shutil.copytree(Path(model_path), Path(tmp_dir), dirs_exist_ok=True)
            dim_gen_pass.save_graph_module(graph_module, tmp_dir)
            self._save_model_to_log_file(tmp_dir)
            yield tmp_dir, dim_gen_pass.get_pass_names()
    def _save_model_to_log_file(self, model_path):
        if self.config["last_model_log_file"] is not None:
            log_file = Path(self.config["last_model_log_file"])
            shutil.copy(Path(model_path) / "model.py", log_file)
    def _save_dim_gen_pass_names(self, dim_gen_pass_names, model_path):
        from graph_net.graph_net_json_file_util import (
            kDimensionGeneralizationPasses,
            update_json,
        )
        update_json(
            model_path, kDimensionGeneralizationPasses, list(dim_gen_pass_names)
        )
    def _save_dyn_dim_cstr(self, dyn_dim_cstr, model_path):
        cstr_code = dyn_dim_cstr.serialize_to_py_str()
        with open(os.path.join(model_path, "input_tensor_constraints.py"), "w") as fp:
            fp.write(cstr_code)
    def _get_tensor_metas(self, model_path):
        make = TensorMeta.unserialize_from_py_file
        return [
            *make(os.path.join(model_path, "input_meta.py")),
            *make(os.path.join(model_path, "weight_meta.py")),
        ]
    def _is_dyn_dim_cstr_feasible(
        self, model_path, tensor_metas, dyn_dim_cstr: DynamicDimConstraints
    ):
        tensor_metas = copy.deepcopy(tensor_metas)
        update_tensor_metas_by_dyn_dim_cstr(tensor_metas, dyn_dim_cstr)
        weight_meta_code = "\n".join(
            tensor_meta.serialize_to_py_str() for tensor_meta in tensor_metas
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            for filename in ["graph_net.json", "model.py"]:
                with open(os.path.join(tmpdir, filename), "w") as f:
                    f.write(open(os.path.join(model_path, filename)).read())
            with open(os.path.join(tmpdir, "input_meta.py"), "w") as f:
                f.write("")
            with open(os.path.join(tmpdir, "weight_meta.py"), "w") as f:
                f.write(weight_meta_code)
            return self.model_runnable_predicator(tmpdir)
def update_tensor_metas_by_dyn_dim_cstr(
    tensor_metas: list[TensorMeta], dyn_dim_cstr: DynamicDimConstraints
):
    input_shapes_with_names = dyn_dim_cstr.input_shapes
    name2shape = {
        name: [dyn_dim_cstr._try_reify(dim) for dim in shape]
        for shape, name in input_shapes_with_names
    }
    for tensor_meta in tensor_metas:
        if tensor_meta.name not in name2shape:
            continue
        tensor_meta.shape = name2shape[tensor_meta.name]
        if tensor_meta.data is not None:
            assert isinstance(tensor_meta.data, (list, tuple))
            size = functools.reduce(lambda a, b: a * b, tensor_meta.shape, 1)
            doubled_data = [*tensor_meta.data, *tensor_meta.data]
            tensor_meta.data = doubled_data[:size]
def make_dyn_dim_cstr_from_tensor_metas(tensor_metas: list[TensorMeta]):
    named_shapes = [
        (shape, name)
        for tensor_meta in tensor_metas
        for name in [tensor_meta.name]
        for shape in [tensor_meta.shape]
    ]
    return DynamicDimConstraints.make_by_named_inputs(
        named_shapes=named_shapes,
    )
class DynDimCstrFeasibilityPredicator:
    def __init__(
        self,
        is_dyn_dim_cstr_feasible: Callable[[DynamicDimConstraints], bool],
        dim_gen_pass_names: tuple[str],
    ):
        self.is_dyn_dim_cstr_feasible = is_dyn_dim_cstr_feasible
        self.dim_gen_pass_names = dim_gen_pass_names
    def __call__(self, dyn_dim_cstr: DynamicDimConstraints) -> bool:
        return self.is_dyn_dim_cstr_feasible(dyn_dim_cstr)
class DynDimCstrFeasibilityContextManager:
    def __init__(
        self,
        get_tmp_model_path_ctx_mgr,
        get_predicator_is_dyn_dim_cstr_feasible,
    ):
        self.get_tmp_model_path_ctx_mgr = get_tmp_model_path_ctx_mgr
        self.get_predicator_is_dyn_dim_cstr_feasible = (
            get_predicator_is_dyn_dim_cstr_feasible
        )
    @contextmanager
    def __call__(
        self, dim_axes_pairs
    ) -> AbstractContextManager[DynDimCstrFeasibilityPredicator]:
        ctx_mgr = self.get_tmp_model_path_ctx_mgr
        with ctx_mgr(dim_axes_pairs) as (tmp_model_apth, dg_pass_names):
            predicator = self.get_predicator_is_dyn_dim_cstr_feasible(tmp_model_apth)
            yield DynDimCstrFeasibilityPredicator(predicator, dg_pass_names)
def symbolize_data_input_dims(
    dyn_dim_cstr: DynamicDimConstraints,
    is_data_input: Callable[[str], bool],
    dyn_dim_cstr_feasibility_ctx_mgr: DynDimCstrFeasibilityContextManager,
) -> (DynamicDimConstraints | None, tuple[str]):
    """
    is_data_input: Callable[["input_var_name:str"], bool]
    Symbolizes data input dimensions as much as possible.
    Returns new DynamicDimConstraints if success.
    Returns None if no symbolicable dim .
    """
    unique_dims = []
    dim2axes = {}
    def dumpy_filter_fn(input_name, input_idx, axis, dim):
        if is_data_input(input_name):
            print("data_input", input_name, input_idx, axis, dim)
            if dim not in unique_dims:
                unique_dims.append(dim)
                dim2axes[dim] = []
            dim2axes[dim].append(axis)
        # No symbolization by returning False
        return False
    # Collect input dimensions into `unique_dims`
    assert dyn_dim_cstr.symbolize(dumpy_filter_fn) is None
    total_dim_gen_pass_names = ()
    def append_dim_gen_pass_names(dim_gen_pass_names):
        nonlocal total_dim_gen_pass_names
        total_dim_gen_pass_names = tuple(
            [
                *total_dim_gen_pass_names,
                *(
                    pass_name
                    for pass_name in dim_gen_pass_names
                    if pass_name not in total_dim_gen_pass_names
                ),
            ]
        )
    for i, picked_dim in enumerate(unique_dims):
        logging.warning(f"{i=} {picked_dim=} {dim2axes[picked_dim]=}")
        cur_dyn_dim_cstr = copy.deepcopy(dyn_dim_cstr)
        def filter_fn(input_name, input_idx, axis, dim):
            return (
                is_data_input(input_name)
                and dim == picked_dim
                and (dim > 1 or axis == 0)
            )
        symbol = cur_dyn_dim_cstr.symbolize(filter_fn)
        if symbol is None:
            continue
        sym2example_value = {symbol: picked_dim + 1}
        if not cur_dyn_dim_cstr.check_delta_symbol2example_value(sym2example_value):
            continue
        dim_axes_pairs = tuple(
            (dim, axes) for dim in unique_dims[: i + 1] for axes in [dim2axes[dim]]
        )
        ctx_mgr = dyn_dim_cstr_feasibility_ctx_mgr
        logging.warning("before dyn_dim_cstr_feasibility_ctx_mgr")
        with ctx_mgr(dim_axes_pairs) as dyn_dim_cstr_feasibility:
            logging.warning("enter dyn_dim_cstr_feasibility_ctx_mgr")
            tmp_dyn_dim_cstr = copy.deepcopy(cur_dyn_dim_cstr)
            tmp_dyn_dim_cstr.update_symbol2example_value(sym2example_value)
            logging.warning("before dyn_dim_cstr_feasibility")
            is_dyn_dim_cstr_feasible = dyn_dim_cstr_feasibility(tmp_dyn_dim_cstr)
            logging.warning("after dyn_dim_cstr_feasibility")
            if not is_dyn_dim_cstr_feasible:
                continue
            dyn_dim_cstr = cur_dyn_dim_cstr
            append_dim_gen_pass_names(dyn_dim_cstr_feasibility.dim_gen_pass_names)
            logging.warning("leave dyn_dim_cstr_feasibility_ctx_mgr")
    return dyn_dim_cstr, total_dim_gen_pass_names

import json
import urllib.request
import urllib.parse
import base64
import sys
import os
from pathlib import Path
from datetime import datetime
CLIENT_ID = os.environ.get("SPOTIFY_CLIENT_ID", "")
CLIENT_SECRET = os.environ.get("SPOTIFY_CLIENT_SECRET", "")
TOKEN_FILE = Path.home() / ".config" / "spotify-clawd" / "token.json"
def load_token():
    if not TOKEN_FILE.exists():
        print("Error: Not authenticated. Run spotify-auth.py first.")
        sys.exit(1)
    return json.loads(TOKEN_FILE.read_text())
def save_token(token_data):
    TOKEN_FILE.write_text(json.dumps(token_data, indent=2))
def refresh_token(token_data):
    auth_header = base64.b64encode(f"{CLIENT_ID}:{CLIENT_SECRET}".encode()).decode()

    data = urllib.parse.urlencode({
        "grant_type": "refresh_token",
        "refresh_token": token_data["refresh_token"],
    }).encode()

    req = urllib.request.Request(
        "https://accounts.spotify.com/api/token",
        data=data,
        headers={
            "Authorization": f"Basic {auth_header}",
            "Content-Type": "application/x-www-form-urlencoded",
        }
    )

    with urllib.request.urlopen(req) as resp:
        new_data = json.load(resp)

    # Keep refresh token if not returned
    if "refresh_token" not in new_data:
        new_data["refresh_token"] = token_data["refresh_token"]

    save_token(new_data)
    return new_data
def api_request(endpoint, token_data, params=None):
    url = f"https://api.spotify.com/v1{endpoint}"
    if params:
        url += "?" + urllib.parse.urlencode(params)

    req = urllib.request.Request(
        url,
        headers={"Authorization": f"Bearer {token_data['access_token']}"}
    )

    try:
        with urllib.request.urlopen(req) as resp:
            return json.load(resp)
    except urllib.error.HTTPError as e:
        if e.code == 401:
            # Token expired, refresh and retry
            token_data = refresh_token(token_data)
            req = urllib.request.Request(
                url,
                headers={"Authorization": f"Bearer {token_data['access_token']}"}
            )
            with urllib.request.urlopen(req) as resp:
                return json.load(resp)
        raise
def get_recently_played(token_data, limit=20):
    return api_request("/me/player/recently-played", token_data, {"limit": limit})
def get_top_artists(token_data, time_range="medium_term", limit=20):
    return api_request("/me/top/artists", token_data, {"time_range": time_range, "limit": limit})
def get_top_tracks(token_data, time_range="medium_term", limit=20):
    return api_request("/me/top/tracks", token_data, {"time_range": time_range, "limit": limit})
def get_recommendations(token_data, seed_artists=None, seed_tracks=None, seed_genres=None, limit=20):
    params = {"limit": limit}
    if seed_artists:
        params["seed_artists"] = ",".join(seed_artists[:5])
    if seed_tracks:
        params["seed_tracks"] = ",".join(seed_tracks[:5])
    if seed_genres:
        params["seed_genres"] = ",".join(seed_genres[:5])
    return api_request("/recommendations", token_data, params)
def main():
    if len(sys.argv) < 2:
        print("Usage: spotify-api.py <command>")
        print("Commands: recent, top-artists, top-tracks, recommend")
        return 1

    cmd = sys.argv[1]
    token_data = load_token()

    if cmd == "recent":
        data = get_recently_played(token_data)
        print("Recently Played:")
        for item in data["items"]:
            track = item["track"]
            played_at = item["played_at"]
            artists = ", ".join(a["name"] for a in track["artists"])
            print(f"  {track['name']} - {artists} ({played_at[:10]})")

    elif cmd == "top-artists":
        time_range = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        data = get_top_artists(token_data, time_range)
        print(f"Top Artists ({time_range}):")
        for i, artist in enumerate(data["items"], 1):
            genres = ", ".join(artist["genres"][:3]) if artist["genres"] else "N/A"
            print(f"  {i}. {artist['name']} [{genres}]")

    elif cmd == "top-tracks":
        time_range = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        data = get_top_tracks(token_data, time_range)
        print(f"Top Tracks ({time_range}):")
        for i, track in enumerate(data["items"], 1):
            artists = ", ".join(a["name"] for a in track["artists"])
            print(f"  {i}. {track['name']} - {artists}")

    elif cmd == "recommend":
        # Get top artists for seeds
        top = get_top_artists(token_data, limit=5)
        seed_artists = [a["id"] for a in top["items"][:3]]

        data = get_recommendations(token_data, seed_artists=seed_artists)
        print("Recommendations based on your top artists:")
        for track in data["tracks"]:
            artists = ", ".join(a["name"] for a in track["artists"])
            print(f"  {track['name']} - {artists}")

    elif cmd == "json":
        # Raw JSON output for any endpoint
        endpoint = sys.argv[2] if len(sys.argv) > 2 else "/me"
        data = api_request(endpoint, token_data)
        print(json.dumps(data, indent=2))

    else:
        print(f"Unknown command: {cmd}")
        return 1

    return 0
if __name__ == "__main__":
    exit(main())

from __future__ import annotations
import importlib
from typing import Optional, TYPE_CHECKING, Type, cast
from ripperdoc.core.config import ProtocolType
from ripperdoc.core.providers.base import ProviderClient
from ripperdoc.utils.log import get_logger
if TYPE_CHECKING:  # pragma: no cover - type checking only
    from ripperdoc.core.providers.anthropic import AnthropicClient  # noqa: F401
    from ripperdoc.core.providers.gemini import GeminiClient  # noqa: F401
    from ripperdoc.core.providers.openai import OpenAIClient  # noqa: F401
logger = get_logger()
def _load_client(module: str, cls: str, extra: str) -> Type[ProviderClient]:
    """Dynamically import a provider client, pointing users to the right extra."""
    try:
        mod = importlib.import_module(f"ripperdoc.core.providers.{module}")
        client_cls = cast(Type[ProviderClient], getattr(mod, cls, None))
        if client_cls is None:
            raise ImportError(f"{cls} not found in {module}")
        return client_cls
    except ImportError as exc:
        raise RuntimeError(
            f"{cls} requires optional dependency group '{extra}'. "
            f"Install with `pip install ripperdoc[{extra}]`."
        ) from exc
def get_provider_client(protocol: ProtocolType) -> Optional[ProviderClient]:
    """Return a provider client for the given protocol."""
    if protocol == ProtocolType.ANTHROPIC:
        return _load_client("anthropic", "AnthropicClient", "anthropic")()
    if protocol == ProtocolType.OPENAI_COMPATIBLE:
        return _load_client("openai", "OpenAIClient", "openai")()
    if protocol == ProtocolType.GEMINI:
        return _load_client("gemini", "GeminiClient", "gemini")()
    if protocol == ProtocolType.OAUTH:
        return _load_client("openai", "OpenAIClient", "openai")()
    logger.warning("[providers] Unsupported protocol", extra={"protocol": protocol})
    return None
__all__ = ["ProviderClient", "get_provider_client"]

import importlib.util
import paddle
from pathlib import Path
import sys
import os
import numpy as np
import random
import platform
import traceback
import subprocess
import re
from graph_net.paddle import utils
from graph_net_bench import path_utils
from graph_net_bench import test_compiler_util
from graph_net import model_path_util
from graph_net.paddle.backend.graph_compiler_backend import GraphCompilerBackend
from graph_net.paddle.backend.cinn_backend import CinnBackend
from graph_net.paddle.backend.nope_backend import NopeBackend
registry_backend = {
    "cinn": CinnBackend(),
    "nope": NopeBackend(),
}
def get_compiler_backend(args) -> GraphCompilerBackend:
    assert args.compiler in registry_backend, f"Unknown compiler: {args.compiler}"
    return registry_backend[args.compiler]
def set_seed(random_seed):
    paddle.seed(random_seed)
    random.seed(random_seed)
    np.random.seed(random_seed)
def init_env(args):
    if test_compiler_util.is_gpu_device(args.device):
        paddle.set_flags({"FLAGS_cudnn_exhaustive_search": 1})
def get_hardward_name(args):
    hardware = "unknown"
    if test_compiler_util.is_gpu_device(args.device):
        hardware = paddle.device.cuda.get_device_name(0)
    elif args.device == "xpu":
        try:
            output = subprocess.check_output(["xpu-smi", "-L"], text=True)
            hardware = next(
                match.group(2)
                for line in output.splitlines()
                if (
                    match := re.match(
                        r"XPU\s+(\d+):\s+(.+?)\s+\(UUID:\s*([^)]+)\)", line
                    )
                )
            )
        except Exception:
            pass
    elif args.device == "cpu":
        hardware = platform.processor()
    return hardware
def get_compile_framework_version(args):
    if args.compiler in ["cinn", "nope"]:
        return paddle.__version__
    return "unknown"
def load_class_from_file(file_path: str, class_name: str):
    file = Path(file_path).resolve()
    module_name = file.stem
    with open(file_path, "r", encoding="utf-8") as f:
        original_code = f.read()
    import_stmt = "import paddle"
    modified_code = f"{import_stmt}\n{original_code}"
    spec = importlib.util.spec_from_loader(module_name, loader=None)
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    compiled_code = compile(modified_code, filename=file, mode="exec")
    exec(compiled_code, module.__dict__)
    model_class = getattr(module, class_name, None)
    return model_class
def get_model(model_path):
    model_class = load_class_from_file(
        f"{model_path}/model.py", class_name="GraphModule"
    )
    return model_class()
def get_input_dict(model_path):
    inputs_params = utils.load_converted_from_text(f"{model_path}")
    params = inputs_params["weight_info"]
    inputs = inputs_params["input_info"]
    params.update(inputs)
    state_dict = {k: utils.replay_tensor(v) for k, v in params.items()}
    return state_dict
def get_input_spec(model_path):
    inputs_params_list = utils.load_converted_list_from_text(f"{model_path}")
    input_spec = [None] * len(inputs_params_list)
    for i, v in enumerate(inputs_params_list):
        dtype = v["info"]["dtype"]
        shape = v["info"]["shape"]
        input_spec[i] = paddle.static.InputSpec(shape, dtype)
    return input_spec
def get_static_model(args, model):
    static_model = paddle.jit.to_static(
        model,
        input_spec=get_input_spec(args.model_path),
        full_graph=True,
        backend=None,
    )
    static_model.eval()
    program = static_model.forward.concrete_program.main_program  # noqa
    return static_model
def measure_performance(model_call, args, compiler, profile=False):
    runtime_seed = 1024
    stats = {}
    paddle.seed(runtime_seed)
    outs = model_call()
    # Warmup runs
    warmup_e2e_times = []
    for _ in range(args.warmup):
        duration_box = test_compiler_util.DurationBox(-1)
        with test_compiler_util.naive_timer(duration_box, compiler.synchronize):
            model_call()
        warmup_e2e_times.append(duration_box.value)
    compiler.synchronize()
    # Ensure the measuring time is not less than 100ms.
    min_trials = int(100 / np.mean(warmup_e2e_times[1:]))
    trials = max(args.trials, min_trials)
    hardware_name = get_hardward_name(args)
    print(
        f"[Profiling] Using device: {args.device} {hardware_name}, warm up {args.warmup}, trials {trials}",
        file=sys.stderr,
        flush=True,
    )
    if profile:
        import paddle.profiler as profiler
        p = profiler.Profiler()
        p.start()
    if test_compiler_util.is_gpu_device(args.device):
        """
        Acknowledgement: We evaluate the performance on both end-to-end and GPU-only timings,
        With reference to methods only based on CUDA events from KernelBench in https://github.com/ScalingIntelligence/KernelBench
        """
        e2e_times = []
        gpu_times = []
        for i in range(trials):
            # End-to-end timing (naive_timer)
            duration_box = test_compiler_util.DurationBox(-1)
            with test_compiler_util.naive_timer(duration_box, compiler.synchronize):
                # GPU-only timing (CUDA Events)
                start_event = paddle.device.Event(enable_timing=True)
                end_event = paddle.device.Event(enable_timing=True)
                start_event.record()
                model_call()
                end_event.record()
            if profile:
                p.step()
            gpu_time_ms = start_event.elapsed_time(end_event)
            e2e_times.append(duration_box.value)
            gpu_times.append(gpu_time_ms)
            print(
                f"Trial {i + 1}: e2e={duration_box.value:.5f} ms, gpu={gpu_time_ms:.5f} ms",
                file=sys.stderr,
                flush=True,
            )
        stats["e2e"] = test_compiler_util.get_timing_stats(e2e_times)
        stats["gpu"] = test_compiler_util.get_timing_stats(gpu_times)
    else:  # CPU or other devices
        e2e_times = []
        for i in range(trials):
            duration_box = test_compiler_util.DurationBox(-1)
            with test_compiler_util.naive_timer(duration_box, compiler.synchronize):
                model_call()
            if profile:
                p.step()
            e2e_times.append(duration_box.value)
            print(
                f"Trial {i + 1}: e2e={duration_box.value:.4f} ms",
                file=sys.stderr,
                flush=True,
            )
        stats["e2e"] = test_compiler_util.get_timing_stats(e2e_times)
    if profile:
        p.stop()
        p.summary()
    return outs, stats
def check_outputs(args, expected_out, compiled_out):
    def _flatten_outputs_to_list(outs):
        flattened_outs = outs
        if isinstance(outs, paddle.Tensor):
            flattened_outs = [outs]
        else:
            flattened_outs = [
                x
                for out in outs
                for x in (out if isinstance(out, (tuple, list)) else (out,))
            ]
        return flattened_outs
    expected_out = _flatten_outputs_to_list(expected_out)
    compiled_out = _flatten_outputs_to_list(compiled_out)
    def _get_output_dtypes(outs):
        dtypes = [
            str(tensor.dtype).replace("paddle.", "")
            if isinstance(tensor, paddle.Tensor)
            else None
            for i, tensor in enumerate(outs)
        ]
        return dtypes
    eager_dtypes = _get_output_dtypes(expected_out)
    compiled_dtypes = _get_output_dtypes(compiled_out)
    type_match = test_compiler_util.check_output_datatype(
        args, eager_dtypes, compiled_dtypes
    )
    def _get_output_shapes(outs):
        shapes = [
            tensor.shape if isinstance(tensor, paddle.Tensor) else None
            for i, tensor in enumerate(outs)
        ]
        return shapes
    eager_shapes = _get_output_shapes(expected_out)
    compiled_shapes = _get_output_shapes(compiled_out)
    shape_match = test_compiler_util.check_output_shape(
        args, eager_shapes, compiled_shapes
    )
    def _transfer_to_float(origin_outputs):
        outputs = []
        for item in origin_outputs:
            if isinstance(item, paddle.Tensor) and item.dtype not in [
                paddle.float32,
                paddle.float64,
            ]:
                item = item.astype("float32")
            outputs.append(item)
        return outputs
    if type_match and shape_match:
        test_compiler_util.check_equal(
            args,
            expected_out,
            compiled_out,
            cmp_equal_func=get_cmp_equal,
        )
        expected_out_fp32 = _transfer_to_float(expected_out)
        compiled_out_fp32 = _transfer_to_float(compiled_out)
        test_compiler_util.check_allclose(
            args,
            expected_out_fp32,
            compiled_out_fp32,
            cmp_all_close_func=get_cmp_all_close,
            cmp_max_diff_func=get_cmp_max_diff,
            cmp_mean_diff_func=get_cmp_mean_diff,
            cmp_max_relative_diff_func=get_cmp_max_relative_diff,
            cmp_mean_relative_diff_func=get_cmp_mean_relative_diff,
        )
def check_and_print_gpu_utilization(compiler):
    if paddle.device.is_compiled_with_cuda():
        device_id = int(paddle.device.get_device().split(":")[-1])
        device_count = paddle.device.cuda.device_count()
        gpu_util, mem_util = test_compiler_util.get_device_utilization(
            device_id, device_count, compiler.synchronize
        )
        if gpu_util is not None and mem_util is not None:
            print(
                f"Device status: gpu_id {device_id}, gpu_util {gpu_util:.2f}%, mem_util {mem_util:.2f}%",
                file=sys.stderr,
                flush=True,
            )
def test_single_model(args):
    model_path = os.path.normpath(args.model_path)
    test_compiler_util.print_with_log_prompt(
        "[Processing]", model_path, args.log_prompt
    )
    compiler = get_compiler_backend(args)
    check_and_print_gpu_utilization(compiler)
    input_dict = get_input_dict(model_path)
    model = get_model(model_path)
    model.eval()
    test_compiler_util.print_basic_config(
        args, get_hardward_name(args), get_compile_framework_version(args)
    )
    # Run on eager mode
    eager_success = False
    eager_time_stats = {}
    try:
        print("Run model in eager mode.", file=sys.stderr, flush=True)
        static_model = get_static_model(args, model)
        expected_out, eager_time_stats = measure_performance(
            lambda: static_model(**input_dict), args, compiler, profile=False
        )
        eager_success = True
    except Exception as e:
        print(
            f"Run model in eager mode failed: {str(e)}\n{traceback.format_exc()}",
            file=sys.stderr,
            flush=True,
        )
    # Run on compiling mode
    compiled_success = False
    compiled_time_stats = {}
    try:
        print("Run model in compiled mode.", file=sys.stderr, flush=True)
        input_spec = get_input_spec(model_path)
        compiled_model = compiler(model, input_spec)
        compiled_out, compiled_time_stats = measure_performance(
            lambda: compiled_model(**input_dict), args, compiler, profile=False
        )
        compiled_success = True
    except Exception as e:
        print(
            f"Run model in compiled mode failed: {str(e)}\n{traceback.format_exc()}",
            file=sys.stderr,
            flush=True,
        )
    test_compiler_util.print_running_status(args, eager_success, compiled_success)
    if eager_success and compiled_success:
        check_outputs(args, expected_out, compiled_out)
    test_compiler_util.print_times_and_speedup(
        args, eager_time_stats, compiled_time_stats
    )
def get_cmp_equal(expected_out, compiled_out):
    def convert(x):
        if x.dtype in [paddle.float16, paddle.bfloat16]:
            return x.astype("float32")
        elif x.dtype in [paddle.uint8, paddle.int8, paddle.int16]:
            return x.astype("int32")
        return x
    return " ".join(
        str(int(paddle.equal_all(convert(a), convert(b))))
        for a, b in zip(expected_out, compiled_out)
    )
def get_cmp_all_close(expected_out, compiled_out, atol, rtol):
    return " ".join(
        str(int(paddle.allclose(a, b, atol=atol, rtol=rtol)))
        for a, b in zip(compiled_out, expected_out)
    )
def get_format_str(f):
    if (abs(f) > 1e5 or abs(f) < 1e-5) and abs(f) != 0.0:
        return str(f"{f:.5E}")
    else:
        return str(f"{f:.5f}")
def get_cmp_max_diff(expected_out, compiled_out):
    return " ".join(
        get_format_str(paddle.max(paddle.abs(a - b)).item())
        for a, b in zip(expected_out, compiled_out)
    )
def get_cmp_mean_diff(expected_out, compiled_out):
    return " ".join(
        get_format_str(paddle.mean(paddle.abs(a - b)).item())
        for a, b in zip(expected_out, compiled_out)
    )
def get_cmp_max_relative_diff(expected_out, compiled_out):
    epsilon = 1e-8
    return " ".join(
        get_format_str(paddle.max(paddle.abs(a - b) / (paddle.abs(a) + epsilon)).item())
        for a, b in zip(expected_out, compiled_out)
    )
def get_cmp_mean_relative_diff(expected_out, compiled_out):
    epsilon = 1e-8
    return " ".join(
        get_format_str(
            paddle.mean(paddle.abs(a - b) / (paddle.abs(a) + epsilon)).item()
        )
        for a, b in zip(expected_out, compiled_out)
    )
def get_cmp_diff_count(expected_out, compiled_out, atol, rtol):
    return " ".join(
        str(paddle.sum(~paddle.isclose(a, b, atol=atol, rtol=rtol)).item())
        for a, b in zip(expected_out, compiled_out)
    )
