        '- "arguments": a JSON STRING (not object) containing only the required parameter values inferred from the question.\n'
        "Do NOT include optional parameters that use default values unless explicitly mentioned.\n"
        "Do NOT output any other text, explanation, or markdown.\n\n"
        f'User question: "{content}"\n\n'
        "Available functions:\n"
    )
    for i, func in enumerate(functions, 1):
        name = func["name"]
        desc = func.get("description", "No description.")
        params_desc = simplify_params_for_prompt(func["parameters"])
        prompt += f"{i}. Function name: `{name}`\n   Description: {desc}\n   Parameters:\n{params_desc}\n\n"
    prompt += "Your response:"
    return prompt
def extract_and_stringify_arguments(text: str) -> dict:
    text = text.strip()
    outer_obj = None
    try:
        outer_obj = json.loads(text)
    except json.JSONDecodeError:
        match = re.search(r"```(?:json)?\s*({.*?})\s*```", text, re.DOTALL | re.IGNORECASE)
        if match:
            try:
                outer_obj = json.loads(match.group(1))
            except json.JSONDecodeError:
                print(f"Found invalid json format in pattern match: {match}")
    if outer_obj and isinstance(outer_obj, dict):
        name = outer_obj.get("name")
        args = outer_obj.get("arguments", {})
        if isinstance(args, str):
            try:
                json.loads(args)
                arguments_str = args
            except json.JSONDecodeError:
                arguments_str = "{}"
                print(f"Found invalid json format in arguments, set to {arguments_str}")
        elif isinstance(args, dict):
            arguments_str = json.dumps(args)
        else:
            arguments_str = "{}"
        return {"name": name, "arguments": arguments_str}
    return {"name": "", "arguments": "{}"}
def process_jsonl(input_path: str, output_path: str):
    with open(input_path, "r", encoding="utf-8") as fin, open(output_path, "w", encoding="utf-8") as fout:
        for line_num, line in enumerate(fin, 1):
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
                content = record["question"][0][0]["content"]
                functions = record["function"]
                prompt = build_prompt(content, functions)
                response = Generation.call(
                    model="qwen-max", messages=[{"role": "user", "content": prompt}], temperature=0.0
                )
                reply = response.output.text
                result = extract_and_stringify_arguments(reply)
                result = json.dumps(result, ensure_ascii=False)
                print(f"id {line_num}, result: {result}")
                fout.write(result + "\n")
                fout.flush()
            except Exception as e:
                print(f"Error on line {line_num}: {e}")
                fout.write('{"name": null, "arguments": "{}"}\n')
if __name__ == "__main__":
    process_jsonl(
        "../../bfcl_v3/tool_call/tool_call_bfcl_v3_multiple_raw.jsonl",
        "../../bfcl_v3/tool_call/tool_call_bfcl_v3_multiple_raw_llm_output.jsonl",
    )

import os
import gymnasium as gym
import numpy as np
from typing import Union, List, Any, Optional, Dict
from dataclasses import dataclass
from libero.libero import get_libero_path
import torch
from cosmos_rl.simulators.libero.venv import ReconfigureSubprocEnv
from cosmos_rl.simulators.libero.utils import (
    get_benchmark_overridden,
    get_libero_dummy_action,
)
from cosmos_rl.simulators.utils import save_rollout_video
def normalize_gripper_action(action, binarize=True):
    """Normalize gripper action from [0,1] to [-1,+1] range."""
    action = action.copy()
    action[..., -1] = 2 * action[..., -1] - 1
    if binarize:
        action[..., -1] = np.sign(action[..., -1])
    return action
def invert_gripper_action(action):
    """Flip the sign of the gripper action (last dim)."""
    action = action.copy()
    action[..., -1] *= -1.0
    return action
@dataclass
class EnvStates:
    env_idx: int
    task_id: int = -1
    trial_id: int = -1
    active: bool = True
    complete: bool = False
    step: int = 0
    language: str = ""
    current_obs: Optional[Any] = None
    do_validation: bool = False
    valid_pixels: Optional[Dict[str, Any]] = None
class LiberoEnvWrapper(gym.Env):
    def __init__(self, cfg, *args, **kwargs):
        self.num_envs = getattr(cfg, "num_envs", 1)
        self.seed = getattr(cfg, "seed", 0)
        self.task_suite_name = getattr(cfg, "task_suite_name", "libero_all")
        self.height = getattr(cfg, "height", 256)
        self.width = getattr(cfg, "width", 256)
        self.max_steps = getattr(cfg, "max_steps", 512)
        self.task_suite = get_benchmark_overridden(self.task_suite_name)()
        self.env_states = [EnvStates(env_idx=i) for i in range(self.num_envs)]
        self._init_env()
    def _init_env(self):
        # lazy init the env fns
        dummy_env_fns = []
        for _ in range(self.num_envs):
            def dummy_env_fn():
                return None
            dummy_env_fns.append(dummy_env_fn)
        self.env = ReconfigureSubprocEnv(dummy_env_fns)
    def _get_fn_params(self, task_id: int):
        task = self.task_suite.get_task(task_id)
        task_bddl_file = os.path.join(
            get_libero_path("bddl_files"), task.problem_folder, task.bddl_file
        )
        fn_params = {
            "camera_heights": self.height,
            "camera_widths": self.width,
            "bddl_file_name": task_bddl_file,
            "seed": self.seed,
        }
        return task.language, fn_params
    def _extract_image_and_state(self, obs):
        full_images = []
        wrist_images = []
        states = []
        for env_id in range(len(obs)):
            full_images.append(obs[env_id]["agentview_image"][::-1, ::-1])
            wrist_images.append(obs[env_id]["robot0_eye_in_hand_image"][::-1, ::-1])
            states.append(
                np.concatenate(
                    [
                        obs[env_id]["robot0_eef_pos"],
                        obs[env_id]["robot0_eef_quat"],
                        obs[env_id]["robot0_gripper_qpos"],
                    ]
                )
            )
        return {
            "full_images": np.stack(full_images),
            "wrist_images": np.stack(wrist_images),
            "states": np.stack(states),
        }
    def _reconfigure(
        self, env_ids: List[int], task_ids: List[int], trial_ids: List[int]
    ):
        env_fn_params = [None for _ in range(len(env_ids))]
        task_descriptions = [None for _ in range(len(env_ids))]
        init_state = [None for _ in range(len(env_ids))]
        for i, env_id in enumerate(env_ids):
            desp, fn_params = self._get_fn_params(task_ids[i])
            task_descriptions[i] = desp
            env_fn_params[i] = fn_params
            n_trial_ids = len(self.task_suite.get_task_init_states(task_ids[i]))
            init_state[i] = self.task_suite.get_task_init_states(task_ids[i])[
                trial_ids[i] % n_trial_ids
            ]
            self.env_states[env_id] = EnvStates(
                env_idx=env_id,
                task_id=task_ids[i],
                trial_id=trial_ids[i],
            )
        self.env.reconfigure_env_fns(env_fn_params, env_ids)
        self.env.set_init_state(init_state, env_ids)
        dummy_actions = get_libero_dummy_action(len(env_ids))
        for _ in range(15):
            obs, _, _, _ = self.env.step(dummy_actions, env_ids)
        images_and_states = self._extract_image_and_state(obs)
        for i, env_id in enumerate(env_ids):
            self.env_states[env_id].current_obs = {
                k: v[i] for k, v in images_and_states.items()
            }
        return images_and_states, task_descriptions
    def _reconfigure_async(
        self, env_ids: List[int], task_ids: List[int], trial_ids: List[int]
    ):
        env_fn_params = [None for _ in range(len(env_ids))]
        for i, env_id in enumerate(env_ids):
            desp, fn_params = self._get_fn_params(task_ids[i])
            env_fn_params[i] = fn_params
            # Store state for reset_wait to use
            self.env_states[env_id] = EnvStates(
                env_idx=env_id,
                task_id=task_ids[i],
                trial_id=trial_ids[i],
                language=desp,
            )
        self.env.reconfigure_env_fns_async(env_fn_params, env_ids)
    def reset(
        self,
        env_ids: Union[int, List[int]],
        task_ids: Union[int, List[int]],
        trial_ids: Union[int, List[int]],
        do_validataion: Union[bool, List[bool]],
    ):
        if isinstance(env_ids, int):
            env_ids = [env_ids]
        if isinstance(task_ids, int):
            task_ids = [task_ids]
        if isinstance(trial_ids, int):
            trial_ids = [trial_ids]
        if isinstance(do_validataion, bool):
            do_validataion = [do_validataion]
        images_and_states, task_descriptions = self._reconfigure(
            env_ids, task_ids, trial_ids
        )
        for i, env_id in enumerate(env_ids):
            self.env_states[env_id].do_validation = do_validataion[i]
            if do_validataion[i]:
                self.env_states[env_id].valid_pixels = {
                    "full_images": [],
                    "wrist_images": [],
                }
        return images_and_states, task_descriptions
    def reset_async(
        self,
        env_ids: Union[int, List[int]],
        task_ids: Union[int, List[int]],
        trial_ids: Union[int, List[int]],
        do_validataion: Union[bool, List[bool]],
    ):
        if isinstance(env_ids, int):
            env_ids = [env_ids]
        if isinstance(task_ids, int):
            task_ids = [task_ids]
        if isinstance(trial_ids, int):
            trial_ids = [trial_ids]
        if isinstance(do_validataion, bool):
            do_validataion = [do_validataion]
        self._reconfigure_async(env_ids, task_ids, trial_ids)
        for i, env_id in enumerate(env_ids):
            self.env_states[env_id].do_validation = do_validataion[i]
            if do_validataion[i]:
                self.env_states[env_id].valid_pixels = {
                    "full_images": [],
                    "wrist_images": [],
                }
    def reset_wait(self, env_ids: List[int]):
        self.env.wait_for_reconfigure(env_ids)
        init_state = [None for _ in range(len(env_ids))]
        for i, env_id in enumerate(env_ids):
            n_trial_ids = len(
                self.task_suite.get_task_init_states(self.env_states[env_id].task_id)
            )
            init_state[i] = self.task_suite.get_task_init_states(
                self.env_states[env_id].task_id
            )[self.env_states[env_id].trial_id % n_trial_ids]
        self.env.set_init_state(init_state, env_ids)
        dummy_actions = get_libero_dummy_action(len(env_ids))
        for _ in range(15):
            obs, _, _, _ = self.env.step(dummy_actions, env_ids)
        images_and_states = self._extract_image_and_state(obs)
        for i, env_id in enumerate(env_ids):
            self.env_states[env_id].current_obs = {
                k: v[i] for k, v in images_and_states.items()
            }
        descriptions = [self.env_states[env_id].language for env_id in env_ids]
        return images_and_states, descriptions
    def step(self, env_ids: List[int], action):
        if isinstance(action, torch.Tensor):
            action = action.detach().cpu().numpy()
        active_indices = [
            i for i, env_id in enumerate(env_ids) if self.env_states[env_id].active
        ]
        if active_indices:
            active_env_ids = [env_ids[i] for i in active_indices]
            active_action = action[active_indices]
            obs, reward, done, info = self.env.step(active_action, active_env_ids)
            images_and_states = self._extract_image_and_state(obs)
            for i, env_id in enumerate(active_env_ids):
                self.env_states[env_id].step += 1
                if done[i] or self.env_states[env_id].step >= self.max_steps:
                    self.env_states[env_id].complete = done[i]
                    self.env_states[env_id].active = False
                for k, v in images_and_states.items():
                    self.env_states[env_id].current_obs[k] = v[i]
                if self.env_states[env_id].do_validation:
                    for img_key in ["full_images", "wrist_images"]:
                        self.env_states[env_id].valid_pixels[img_key].append(
                            images_and_states[img_key][i]
                        )
        completes = np.array([self.env_states[env_id].complete for env_id in env_ids])
        active = np.array([self.env_states[env_id].active for env_id in env_ids])
        finish_steps = np.array([self.env_states[env_id].step for env_id in env_ids])
        full_images_and_states = {}
        for key in ["full_images", "wrist_images", "states"]:
            full_images_and_states[key] = np.stack(
                [self.env_states[env_id].current_obs[key] for env_id in env_ids]
            )
        return {
            **full_images_and_states,
            "complete": completes,
            "active": active,
            "finish_step": finish_steps,
        }
    def chunk_step(self, env_ids: List[int], actions: torch.Tensor):
        if isinstance(actions, torch.Tensor):
            actions = actions.detach().cpu().numpy()
        steps = actions.shape[1] if actions.ndim > 2 else 1
        if actions.ndim == 2:
            actions = actions[:, None, :]
        for step in range(steps):
            results = self.step(env_ids, actions[:, step])
        return results
    def get_env_states(self, env_ids: List[int]):
        return [self.env_states[env_id] for env_id in env_ids]
    def save_validation_videos(self, rollout_dir: str, env_ids: List[int]):
        for env_id in env_ids:
            state = self.env_states[env_id]
            if not state.do_validation:
                continue
            task_name = (
                f"{self.task_suite_name}_task_{state.task_id}_trial_{state.trial_id}"
            )
            save_rollout_video(
                state.valid_pixels["full_images"],
                rollout_dir,
                task_name,
                state.complete,
            )

from typing import Dict, List
from .base import DriverBase
logger = logging.getLogger("OpenCastor.Dynamixel")
# Try to import the official SDK, but don't crash if it's missing (for simulation)
try:
    from dynamixel_sdk import (
        COMM_SUCCESS,
        PacketHandler,
        PortHandler,
    )
    HAS_DYNAMIXEL = True
except ImportError:
    HAS_DYNAMIXEL = False
    logger.warning("Dynamixel SDK not found. Running in mock mode.")
class DynamixelDriver(DriverBase):
    """
    Implementation for Robotis Dynamixel Servos (Protocol 2.0).
    Handles translation from RCAN 'degrees' to hardware 'ticks'.
    """
    # Dynamixel Control Table Addresses (Generic for X-series)
    ADDR_TORQUE_ENABLE = 64
    ADDR_GOAL_POSITION = 116
    ADDR_PRESENT_POSITION = 132
    PROTOCOL_VERSION = 2.0
    def __init__(self, config: Dict):
        self.port_name = config.get("port", "/dev/ttyUSB0")
        self.baud_rate = config.get("baud_rate", 57600)
        self.connected_motors: List[int] = []
        if not HAS_DYNAMIXEL:
            logger.warning("Dynamixel SDK unavailable, driver in mock mode")
            self.portHandler = None
            self.packetHandler = None
            return
        self.portHandler = PortHandler(self.port_name)
        self.packetHandler = PacketHandler(self.PROTOCOL_VERSION)
        if self._open_port():
            logger.info(f"Dynamixel Port Opened: {self.port_name}")
        else:
            logger.error(f"Failed to open Dynamixel Port: {self.port_name}")
    def _open_port(self) -> bool:
        if self.portHandler is None:
            return False
        if self.portHandler.openPort():
            if self.portHandler.setBaudRate(self.baud_rate):
                return True
        return False
    def engage(self, motor_ids: List[int]):
        """Turn on torque for specific motors."""
        if self.portHandler is None:
            return
        for mid in motor_ids:
            dxl_comm_result, dxl_error = self.packetHandler.write1ByteTxRx(
                self.portHandler, mid, self.ADDR_TORQUE_ENABLE, 1
            )
            if dxl_comm_result != COMM_SUCCESS:
                logger.error(
                    f"Failed to engage Motor {mid}: "
                    f"{self.packetHandler.getTxRxResult(dxl_comm_result)}"
                )
            else:
                self.connected_motors.append(mid)
    def disengage(self, motor_ids: List[int]):
        """Relax torque (Safe Mode)."""
        if self.portHandler is None:
            return
        for mid in motor_ids:
            self.packetHandler.write1ByteTxRx(self.portHandler, mid, self.ADDR_TORQUE_ENABLE, 0)
    def move(self, motor_id: int, angle_deg: float):
        """
        Moves a specific motor to an angle.
        RCAN Spec: 0 degrees is center.
        Dynamixel: 0-4095 ticks. Center is ~2048.
        """
        if self.portHandler is None:
            logger.info(f"[MOCK] Motor {motor_id} -> {angle_deg} deg")
            return
        # Convert Degrees to Ticks (0.088 deg/tick for MX/X series)
        ticks = int(2048 + (angle_deg / 0.088))
        # Safety Clamping
        ticks = max(0, min(4095, ticks))
        dxl_comm_result, dxl_error = self.packetHandler.write4ByteTxRx(
            self.portHandler, motor_id, self.ADDR_GOAL_POSITION, ticks
        )
        if dxl_comm_result != COMM_SUCCESS:
            logger.error(f"Communication Error on ID {motor_id}")
    def get_position(self, motor_id: int) -> float:
        """Reads current angle. Critical for closed-loop agent reasoning."""
        if self.portHandler is None:
            return 0.0
        ticks, dxl_comm_result, dxl_error = self.packetHandler.read4ByteTxRx(
            self.portHandler, motor_id, self.ADDR_PRESENT_POSITION
        )
        if dxl_comm_result != COMM_SUCCESS:
            return 0.0
        return (ticks - 2048) * 0.088
    def health_check(self) -> dict:
        """Probe the first connected Dynamixel motor (or ID 1 as default).
        Returns ok=True if the servo responds to a ping over the serial port.
        Returns ok=False with mode="mock" when running without the SDK.
        """
        if self.portHandler is None or self.packetHandler is None:
            return {
                "ok": False,
                "mode": "mock",
                "error": "Dynamixel SDK unavailable or port not open",
            }
        motor_id = self.connected_motors[0] if self.connected_motors else 1
        try:
            _model_num, result, _error = self.packetHandler.ping(self.portHandler, motor_id)
            if result == COMM_SUCCESS:
                return {"ok": True, "mode": "hardware", "error": None}
            return {
                "ok": False,
                "mode": "hardware",
                "error": f"Ping failed on motor {motor_id}: comm_result={result}",
            }
        except Exception as exc:
            return {"ok": False, "mode": "hardware", "error": str(exc)}
    def stop(self):
        self.disengage(self.connected_motors)
    def close(self):
        self.stop()
        if self.portHandler is not None:
            self.portHandler.closePort()

