import json
import os
import subprocess
from datetime import datetime, timezone
PALEST_INK_DIR = os.path.expanduser("~/.palest-ink")
CONFIG_FILE = os.path.join(PALEST_INK_DIR, "config.json")
DATA_DIR = os.path.join(PALEST_INK_DIR, "data")
MARKER_FILE = os.path.join(PALEST_INK_DIR, "tmp", "fsevent_marker")
def load_config():
    if os.path.exists(CONFIG_FILE):
        with open(CONFIG_FILE, "r") as f:
            return json.load(f)
    return {}
def save_config(config):
    with open(CONFIG_FILE, "w") as f:
        json.dump(config, f, indent=2, ensure_ascii=False)
def get_datafile(dt):
    path = os.path.join(DATA_DIR, dt.strftime("%Y"), dt.strftime("%m"), f"{dt.strftime('%d')}.jsonl")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return path
def guess_language(filepath):
    """Guess programming language from file extension (shared logic with collect_vscode.py)."""
    ext_map = {
        ".py": "python", ".js": "javascript", ".ts": "typescript",
        ".tsx": "typescript-react", ".jsx": "javascript-react",
        ".java": "java", ".go": "go", ".rs": "rust", ".rb": "ruby",
        ".php": "php", ".c": "c", ".cpp": "cpp", ".h": "c-header",
        ".cs": "csharp", ".swift": "swift", ".kt": "kotlin",
        ".scala": "scala", ".r": "r", ".R": "r",
        ".sql": "sql", ".sh": "shell", ".bash": "shell", ".zsh": "shell",
        ".html": "html", ".css": "css", ".scss": "scss", ".less": "less",
        ".json": "json", ".yaml": "yaml", ".yml": "yaml", ".toml": "toml",
        ".xml": "xml", ".md": "markdown", ".rst": "restructuredtext",
        ".vue": "vue", ".svelte": "svelte",
    }
    _, ext = os.path.splitext(filepath)
    return ext_map.get(ext.lower(), "unknown")
def find_workspace(filepath):
    """Walk up directory tree to find nearest .git directory."""
    directory = os.path.dirname(os.path.abspath(filepath))
    while directory != os.path.dirname(directory):  # stop at filesystem root
        if os.path.isdir(os.path.join(directory, ".git")):
            return directory
        directory = os.path.dirname(directory)
    return ""
def find_changed_files(watch_dir, marker_path):
    """Use find -newer to get files changed since marker mtime."""
    try:
        result = subprocess.run(
            [
                "find", watch_dir,
                "-newer", marker_path,
                "-maxdepth", "4",
                "-type", "f",
                "!", "-path", "*/.git/*",
                "!", "-path", "*/node_modules/*",
                "!", "-path", "*/__pycache__/*",
                "!", "-name", ".DS_Store",
            ],
            capture_output=True, text=True, timeout=10
        )
        if result.returncode != 0:
            return []
        return [p for p in result.stdout.strip().split("\n") if p]
    except (subprocess.TimeoutExpired, OSError):
        return []
def collect():
    config = load_config()
    if not config.get("collectors", {}).get("fsevent", True):
        return
    # Determine watched directories
    watched_dirs = config.get("watched_dirs", [])
    if not watched_dirs:
        watched_dirs = config.get("tracked_repos", [])
    if not watched_dirs:
        return
    # First run: create marker and exit
    first_run = not os.path.exists(MARKER_FILE)
    if first_run:
        os.makedirs(os.path.dirname(MARKER_FILE), exist_ok=True)
        open(MARKER_FILE, "w").close()
        return
    now = datetime.now(timezone.utc)
    changed_files = []
    for watch_dir in watched_dirs:
        if os.path.isdir(watch_dir):
            changed_files.extend(find_changed_files(watch_dir, MARKER_FILE))
    # Update marker timestamp before writing records
    os.utime(MARKER_FILE, None)
    if not changed_files:
        return
    records_by_file = {}
    count = 0
    seen_paths = set()
    for filepath in changed_files:
        filepath = os.path.normpath(filepath)
        if filepath in seen_paths:
            continue
        seen_paths.add(filepath)
        # Skip binary-like files and hidden system files
        filename = os.path.basename(filepath)
        if filename.startswith(".") and filename not in {".env", ".gitignore", ".eslintrc"}:
            continue
        workspace = find_workspace(filepath)
        language = guess_language(filepath)
        record = {
            "ts": now.isoformat(),
            "type": "file_change",
            "source": "fsevent_collector",
            "data": {
                "path": filepath,
                "workspace": workspace,
                "language": language,
                "event": "modified",
            }
        }
        datafile = get_datafile(now)
        if datafile not in records_by_file:
            records_by_file[datafile] = []
        records_by_file[datafile].append(record)
        count += 1
    for datafile, records in records_by_file.items():
        with open(datafile, "a") as f:
            for record in records:
                f.write(json.dumps(record, ensure_ascii=False) + "\n")
    if count > 0:
        print(f"[fsevent] Recorded {count} file changes")
if __name__ == "__main__":
    collect()

from celery import Celery
from common.celery_app import BaseTask
from common.models.base_repository import BaseRepository
from common.task_object.task_object import (
    RepositoryTaskObjectT,
    SecondaryRepositoryTaskObjectT,
)
from worker.utils.persister_base import PersisterBase, PersistingException
from worker.utils.processing_task import ProcessingTask
PERSIST_MAX_RETRIES = 20
P = ParamSpec("P")
def _default_persisting_cache(*_, **__):
    def decorator(func: Callable):
        return func
    return decorator
def persisting_task(
    celery_app: "Celery[BaseTask]",
    persister_type: Type[PersisterBase[RepositoryTaskObjectT]],
    get_task_object_repository: (
        Callable[[], BaseRepository[SecondaryRepositoryTaskObjectT]] | None
    ) = None,
    persisting_cache_decorator: Callable[
        [Callable], Callable
    ] = _default_persisting_cache,
):
    """Decorator to register a persisting task out of a callable.
    The callable must accept an IndexingPersister as first argument and the rest of the
    arguments are passed through to the task.
    :param get_task_object_repository: By default, the status of this task will be reported
        to the same repository as the persister_type is persisting. You can use this
        parameter if the persister_type is not persisting to the same repository as the
        task is reporting its state to.
    :param persisting_cache_decorator: Decorator is used before running the task allowing
        caching. The decorator needs to return a cache decorator and accept the persisting
        function which can be used to create the actually cache name.
        This can be used with `persisting_cache`.
    """
    def inner_decorator(persist_fcn: Callable[Concatenate[PersisterBase, P], None]):
        class PersistingTask(
            ProcessingTask[RepositoryTaskObjectT, SecondaryRepositoryTaskObjectT]
        ):
            """Base class for persisting tasks."""
            name = celery_app.gen_task_name(
                persist_fcn.__name__, persist_fcn.__module__
            )
            def __init__(self, max_retries: int):
                self.max_retries = max_retries
                super().__init__()
            # pylint does not consider metaclass:
            # https://stackoverflow.com/questions/22186843/pylint-w0223-method-is-abstract-in-class-but-is-not-overridden
            # pylint: disable=abstract-method
            @property
            def _repository(
                self,
            ) -> (
                BaseRepository[RepositoryTaskObjectT]
                | BaseRepository[SecondaryRepositoryTaskObjectT]
            ):
                if get_task_object_repository is None:
                    return persister_type.get_repository()
                return get_task_object_repository()
            @persisting_cache_decorator(persist_fcn)
            def run(self, *args, **kwargs) -> Any:
                passed_args = args[:-1]
                obj: RepositoryTaskObjectT = args[-1]
                with persister_type(obj.id_) as persister:
                    persist_fcn(persister, *passed_args, **kwargs)
                if len(passed_args) <= 0:
                    return None
                return passed_args[0]
        task_instance = PersistingTask(PERSIST_MAX_RETRIES)
        celery_app.register_task(
            task_instance, autoretry_for=[PersistingException], retry_backoff=True
        )
        return task_instance
    return inner_decorator

