    RequestDispatchMeta,
    UCMConnectorMetadata,
    UCMDirectConnector,
)
from ucm.logger import init_logger
from ucm.sparse.blend.blockwise_rope import block_wise_rope_forward
if TYPE_CHECKING:
    from vllm.v1.core.kv_cache_manager import KVCacheBlocks
