@dataclass
class ChunkMetaData:
    # [start, start + len)
    start_token_dix: int
    chunk_tokens_len: int
    start_blk_idx: int
    chunk_blks_len: int
    cached_start_position: int
    vllm_blk_ids: List[int] = field(default_factory=list)
    chunk_blks_hash: List[bytes] = field(default_factory=list)
    store_hits: List[bool] = field(default_factory=list)
    @property
    def end_token_dix(self) -> int:
        return self.start_token_dix + self.chunk_tokens_len
    @property
    def end_blk_idx(self) -> int:
        return self.start_blk_idx + self.chunk_blks_len
    @property
    def cached_end_position(self) -> int:
        return self.cached_start_position + self.chunk_tokens_len
    @property
    def position_offset(self) -> int:
        return self.start_token_dix - self.cached_start_position
    @property
    def hits_vllm_blk_ids(self) -> List[int]:
        return list(itertools.compress(self.vllm_blk_ids, self.store_hits))
    @property
    def hits_chunk_blks_hash(self) -> List[bytes]:
        return list(itertools.compress(self.chunk_blks_hash, self.store_hits))
    def merge_chunk(self, temp_chunk_meta: Self) -> None:
        # current we use a fix pattern(end with a fix token id) to recognize the text token chunk
        # in some special situation, one text chunk maybe split as multi text chunk, so we should merge them into one
        self.chunk_tokens_len += temp_chunk_meta.chunk_tokens_len
        self.chunk_blks_len += temp_chunk_meta.chunk_blks_len
        self.chunk_blks_hash += temp_chunk_meta.chunk_blks_hash
    def update_meta_partial_pc(self, num_pc_part_blks: int, block_size: int) -> None:
        if num_pc_part_blks > 0:
            self.start_token_dix += num_pc_part_blks * block_size
            self.chunk_tokens_len -= num_pc_part_blks * block_size
            self.start_blk_idx += num_pc_part_blks
            self.chunk_blks_len -= num_pc_part_blks
            self.chunk_blks_hash = self.chunk_blks_hash[num_pc_part_blks:]
            self.store_hits = self.store_hits[num_pc_part_blks:]
            self.cached_start_position += num_pc_part_blks * block_size
class BlendStage(Enum):
    BUILD_CHUNK_CACHE = auto()
    BUILD_PREFIX_CACHE = auto()
    CACHE_BLEND = auto()
    def is_blend_cache(self) -> bool:
        return self == BlendStage.CACHE_BLEND
    def is_prefix_cache(self) -> bool:
        return self == BlendStage.BUILD_PREFIX_CACHE
@dataclass
class BlendRequestMeta:
    ucm_block_hashs: list[bytes] = field(default_factory=list)
    # hbm pc is not supported
    hbm_hit_block_num: int = 0
    # ucm pc is supported
    pc_hit_block_num: int = 0
    chunks_meta: List[ChunkMetaData] = field(default_factory=list)
    blend_stage: BlendStage = BlendStage.BUILD_PREFIX_CACHE
@dataclass
class BlendRequestDispatchMeta(RequestDispatchMeta):
    chunks_meta: List[ChunkMetaData]
@dataclass
class UCMBlendConnectorMetadata(UCMConnectorMetadata):
    request_meta: dict[str, BlendRequestDispatchMeta] = field(default_factory=dict)
class UCMBlendConnector(UCMDirectConnector):
    """
    This Connector process chunk hash and prefix cache
    """
    def __init__(self, vllm_config: "VllmConfig", role: KVConnectorRole):
        super().__init__(vllm_config, role)
        ucm_sparse_config = self.launch_config.get("ucm_sparse_config", [])
        self.blend_stage = BlendStage.BUILD_PREFIX_CACHE
        self.req2rag_load_chunks: dict[str, list[ChunkMetaData]] = {}
        if "Blend" in ucm_sparse_config:
            blend_config = ucm_sparse_config["Blend"]
            self.enable_blend = True
            self.chunk_end_token_id = blend_config["chunk_end_token_id"]
        else:
            raise "UCMBlendConnector init failed, please check your config"
        self.requests_blend_meta: dict[str, BlendRequestMeta] = {}
        self.cos_sin_cache: torch.Tensor = None
        # if chunk cache hits less than min_blend_threshold, no need to cache blend
        self.min_blend_threshold = 16
        # post process delta rope meta
        self.delta_rope_vllm_ids: torch.Tensor = None
        self.delta_rope_positions: torch.Tensor = None
    def _process_req(self, all_token_ids: List[int]):
        """
        pre-assumption, we explicitly construct block-padded chunk req to make it cached all tokens
        beside chunk-build req, we try to split chunk from req, if no chunk exist, it just builds naive prefix cache
        if chunk found, first we should match the prefix cache as much as possible, cause, they can be fully reused
        then for other chunk blocks, if store hit num of block hash is less than threshold, we do not conduct cache blend
        finally, if there are quite many chunk block-hits, we do cache blend to get TTFT-promot
        """
        chunks_meta = []
        prefix_block_hashes = self.generate_hash(
            self.block_size, all_token_ids, self._seed
        )
        if (
            all_token_ids[-1] == self.chunk_end_token_id
            and len(all_token_ids) % self.block_size == 0
        ):
            return (
                BlendStage.BUILD_CHUNK_CACHE,
                prefix_block_hashes,
                chunks_meta,
                [],
            )
        start_blk_idx = 0
        start_token_dix = 0
        req_chunks_hashes = []
        for end_blk_idx, end_token_idx in enumerate(
            range(self.block_size - 1, len(all_token_ids), self.block_size)
        ):
            # only compare the last token id in each blk to split chunk
            # in future we should add chunk info as llm engine input,then pass them to schedule out
            # but this will bring lots of modification to engine.
            if all_token_ids[end_token_idx] == self.chunk_end_token_id:
                chunk_token_ids = all_token_ids[start_token_dix : end_token_idx + 1]
                chunk_blks_hash = self.generate_hash(
                    self.block_size, chunk_token_ids, self._seed
                )
                chunk_blks_len = end_blk_idx - start_blk_idx + 1
                chunk_tokens_len = chunk_blks_len * self.block_size
                rag_chunk_meta = ChunkMetaData(
                    start_token_dix=start_token_dix,
                    chunk_tokens_len=chunk_tokens_len,
                    start_blk_idx=start_blk_idx,
                    chunk_blks_len=chunk_blks_len,
                    chunk_blks_hash=chunk_blks_hash,
                    cached_start_position=0,
                )
                # update for next rag chunk
                start_blk_idx = end_blk_idx + 1
                start_token_dix = end_token_idx + 1
                chunks_meta.append(rag_chunk_meta)
                req_chunks_hashes.extend(chunk_blks_hash)
        if chunks_meta:
            # found chunk, as for suffix part(such as user question about chunk), current no need to cache hit and dump
            return (
                BlendStage.CACHE_BLEND,
                prefix_block_hashes,
                chunks_meta,
                req_chunks_hashes,
            )
        else:
            return (
                BlendStage.BUILD_PREFIX_CACHE,
                prefix_block_hashes,
                chunks_meta,
                req_chunks_hashes,
            )
    def _get_req_chunk_hit(
        self,
        req_stage: BlendStage,
        prefix_block_hashes: List[str],
        req_chunks_meta: List[ChunkMetaData],
        req_chunks_hashes: List[str],
    ) -> Tuple[int, int]:
        # first perform prefix cache lookup
        pc_lookup_results = self.store.lookup(prefix_block_hashes)
        pc_hit_blocks = 0
        chunk_hit_blocks = 0
        for i, hit in enumerate(pc_lookup_results):
            if not hit:
                break
            pc_hit_blocks += 1
        if not req_stage.is_blend_cache():
            return pc_hit_blocks, chunk_hit_blocks
        # then perform chunk cache lookup
        chunk_lookup_results = self.store.lookup(req_chunks_hashes[pc_hit_blocks:])
        chunk_hit_blocks = sum(chunk_lookup_results)
        chunk_lookup_results = pc_lookup_results[:pc_hit_blocks] + chunk_lookup_results
        # for cache blend
        for i, chunk_meta in enumerate(req_chunks_meta):
            chunk_meta.store_hits = chunk_lookup_results[
                chunk_meta.start_blk_idx : chunk_meta.end_blk_idx
            ]
        first_chunk_meta = req_chunks_meta[0]
        first_chunk_meta.update_meta_partial_pc(pc_hit_blocks, self.block_size)
        # remove total pc hit chunk
        if first_chunk_meta.chunk_tokens_len == 0:
            req_chunks_meta.pop(0)
        return pc_hit_blocks, chunk_hit_blocks
    def _generate_blend_dispatch_meta(
        self,
        req_meta: BlendRequestMeta,
        new_tokens: int,
        vllm_block_ids: list[int],
    ) -> BlendRequestDispatchMeta:
        """
        Request Blocks layout:
        Stage: Build Prefix Cache or Build Chunk Cache (max one chunk per req)
        ----------------------------------------------------------------------------------------------------------
        | prefix cache (at first chunk) | other chunk cache      |
        ----------------------------------------------------------------------------------------------------------
        |            LOAD               |          DUMP          |
        ----------------------------------------------------------------------------------------------------------
        |           REUSE               |     RECOMPUTE          |
        ----------------------------------------------------------------------------------------------------------
        Stage: Cache Blend
        ----------------------------------------------------------------------------------------------------------
        | prefix cache at first chunk | other chunk cache hit  | other chunk cache miss | suffix part(question) |
        ----------------------------------------------------------------------------------------------------------
        |            LOAD             |          LOAD          |    NO NEED TO DUMP    |     NO NEED TO DUMP    |
        ----------------------------------------------------------------------------------------------------------
        |           REUSE             |   REUSE & RECOMPUTE    |       RECOMPUTE       |        RECOMPUTE       |
        ----------------------------------------------------------------------------------------------------------
        """
        # current not support chunk prefill, cause the topK high deviation KV should come from the all tokens
        pc_hit_block_num = req_meta.pc_hit_block_num
        ucm_block_hashs = req_meta.ucm_block_hashs
        # load prefix part
        load_ucm_block_ids, load_vllm_block_ids = (
            ucm_block_hashs[:pc_hit_block_num],
            vllm_block_ids[:pc_hit_block_num],
        )
        dump_ucm_block_ids, dump_vllm_block_ids = [], []
        if req_meta.blend_stage.is_blend_cache():
            # just need to load, in future we may create a multi-chunk hash to dump and reuse the blended cache
            for chunk_meta in req_meta.chunks_meta:
                chunk_meta.vllm_blk_ids = vllm_block_ids[
                    chunk_meta.start_blk_idx : chunk_meta.end_blk_idx
                ]
                load_ucm_block_ids.extend(chunk_meta.hits_chunk_blks_hash)
                load_vllm_block_ids.extend(chunk_meta.hits_vllm_blk_ids)
            return BlendRequestDispatchMeta(
                (load_ucm_block_ids, load_vllm_block_ids),
                (dump_ucm_block_ids, dump_vllm_block_ids),
                req_meta.chunks_meta,
            )
        # build cache stage
        dump_ucm_block_ids, dump_vllm_block_ids = (
            ucm_block_hashs[pc_hit_block_num:],
            vllm_block_ids[pc_hit_block_num : len(ucm_block_hashs)],
        )
        return BlendRequestDispatchMeta(
            (load_ucm_block_ids, load_vllm_block_ids),
            (dump_ucm_block_ids, dump_vllm_block_ids),
            req_meta.chunks_meta,
        )
    def _post_process_chunk_cache(self, k_cache, vllm_ids, positions) -> None:
        """
        post process loaded chunk kcache
        """
        if self.cos_sin_cache is None:
            raise "Please call setup model first."
        # triton kernl for block-wise delta rope
        block_wise_rope_forward(k_cache, vllm_ids, positions, self.cos_sin_cache)
    def _register_cos_sin_cache(self, model: "Model") -> None:
        try:
            rotary_emb = model.model.layers[0].self_attn.rotary_emb
            self.cos_sin_cache = rotary_emb.cos_sin_cache
        except Exception:
            raise "get cos_sin_cache from model failed!  current not implemented for this model"
    def setup_model(self, model: "Model") -> None:
        self._register_cos_sin_cache(model)
    def get_num_new_matched_tokens(
        self,
        request: "Request",
        num_computed_tokens: int,
    ) -> tuple[int, bool]:
        # current not support HBM prefix cache, cause the blended cached have a ground view of all chunks
        # so they can not be applied to other req
        assert num_computed_tokens == 0
        all_token_ids = request.all_token_ids
        max_blk_num = len(all_token_ids) // self.block_size
        if max_blk_num == 0:
            return 0, False
        req_stage, prefix_block_hashes, req_chunks_meta, req_chunks_hashes = (
            self._process_req(all_token_ids)
        )
        pc_hit_blocks, chunk_hit_blocks = self._get_req_chunk_hit(
            req_stage, prefix_block_hashes, req_chunks_meta, req_chunks_hashes
        )
        if chunk_hit_blocks < self.min_blend_threshold:
            req_stage = BlendStage.BUILD_PREFIX_CACHE
            req_chunks_meta = []
        req_block_hashes = prefix_block_hashes
        if req_stage.is_blend_cache():
            req_block_hashes = req_chunks_hashes
        logger.info(
            f"request_id: {request.request_id}, "
            f"total_blocks_num: {max_blk_num}, "
            f"req_stage: {req_stage}, "
            f"first chunk prefix hit: {pc_hit_blocks}, "
            f"chunks cache total hit: {chunk_hit_blocks}, "
        )
        if self.metrics_config:
            self.monitor.update_stats(
                "ConnStats",
                {"interval_lookup_hit_rates": chunk_hit_blocks / max_blk_num},
            )
        pc_hit_tokens = pc_hit_blocks * self.block_size
        # When all the tokens are cached in ssd or hbm,
        # we need to recompute the last token. This if condition will be removed
        # once vLLM scheduler provides a better solution in the future.
        if pc_hit_tokens == request.num_tokens:
            pc_hit_tokens -= 1
        self.requests_blend_meta[request.request_id] = BlendRequestMeta(
            ucm_block_hashs=req_block_hashes,
            pc_hit_block_num=pc_hit_blocks,
            chunks_meta=req_chunks_meta,
            blend_stage=req_stage,
        )
        return pc_hit_tokens, False
    def update_state_after_alloc(
        self, request: "Request", blocks: "KVCacheBlocks", num_external_tokens: int
    ):
        pass
    def build_connector_meta(
        self, scheduler_output: SchedulerOutput
    ) -> KVConnectorMetadata:
        requests_dispatch_meta = {}
        # for new request, we need to load and dump
        for request in scheduler_output.scheduled_new_reqs:
            request_id, vllm_block_ids = request.req_id, request.block_ids[0]
            req_meta = self.requests_blend_meta.get(request_id)
            if req_meta:
                requests_dispatch_meta[request_id] = self._generate_blend_dispatch_meta(
                    req_meta,
                    scheduler_output.num_scheduled_tokens[request_id],
                    vllm_block_ids,
                )
        # for cached request, there are 3 situation:
        # 1. chunked prefill: we should make sure this will not happen
        # 2. resumed: we need to handle like new request
        # 3. TODO decode stage: nothing happened
        scheduled_cached_reqs = scheduler_output.scheduled_cached_reqs
        if not isinstance(scheduled_cached_reqs, list):
            # >= 0.9.2
            for i, request_id in enumerate(scheduled_cached_reqs.req_ids):
                if scheduler_output.num_scheduled_tokens[request_id] == 1:
                    # decode stage
                    continue
                req_meta = self.requests_blend_meta.get(request_id)
                if req_meta:
                    requests_dispatch_meta[request_id] = (
                        self._generate_blend_dispatch_meta(
                            req_meta,
                            scheduler_output.num_scheduled_tokens[request_id],
                            scheduled_cached_reqs.new_block_ids[i][0],
                        )
                    )
        else:
            for request in scheduled_cached_reqs:
                request_id = request.request_id
                if scheduler_output.num_scheduled_tokens[request_id] == 1:
                    # decode stage
                    continue
                req_meta = self.requests_blend_meta.get(request_id)
                if req_meta:
                    requests_dispatch_meta[request_id] = (
                        self._generate_blend_dispatch_meta(
                            req_meta,
                            scheduler_output.num_scheduled_tokens[request_id],
                            request.new_block_ids[0],
                        )
                    )
        # clear finished request
        for request_id in scheduler_output.finished_req_ids:
            self.requests_meta.pop(request_id, None)
        return UCMBlendConnectorMetadata(requests_dispatch_meta)
    def bind_connector_metadata(self, connector_metadata: KVConnectorMetadata) -> None:
        """
        Blend need build post process meta for loaded kv cache
        """
        super().bind_connector_metadata(connector_metadata)
        all_hits_vllm_ids = []
        positions = []
        for request_id, request in connector_metadata.request_meta.items():
            for chunk_meta in request.chunks_meta:
                all_hits_vllm_ids.extend(chunk_meta.hits_vllm_blk_ids)
                positions.extend(
                    [chunk_meta.position_offset] * len(chunk_meta.hits_vllm_blk_ids)
                )
        if all_hits_vllm_ids:
            self.delta_rope_vllm_ids = torch.tensor(
                all_hits_vllm_ids, device=self.device
            )
            self.delta_rope_positions = torch.tensor(positions, device=self.device)
    def clear_connector_metadata(self) -> None:
        """Clear the post process meta"""
        super().clear_connector_metadata()
        self.delta_rope_vllm_ids = None
        self.delta_rope_positions = None
    def wait_for_layer_load(self, layer_name: str) -> None:
        if self.delta_rope_vllm_ids is not None:
            k_cache = self.kv_caches[layer_name][0]
            self._post_process_chunk_cache(
                k_cache, self.delta_rope_vllm_ids, self.delta_rope_positions
            )

from sqlalchemy import text
from statgpt.common.config import Versions
from statgpt.common.config import multiline_logger as logger
from statgpt.common.settings.database import PostgresSettings
from .database import get_session_context_manager
class AlembicTableNotFoundError(RuntimeError):
    pass
class WrongAlembicVersionError(RuntimeError):
    pass
class DatabaseHealthChecker:
    def __init__(self):
        self._postgres_settings = PostgresSettings()
    @classmethod
    async def check_alembic_version(cls) -> None:
        async with get_session_context_manager() as session:
            res = await session.execute(
                text(
                    "SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'alembic_version');"
                )
            )
            table_exist: bool = res.scalar()  # type: ignore[assignment]
            if not table_exist:
                raise AlembicTableNotFoundError("Alembic table doesn't exist")
            res = await session.execute(text("SELECT version_num FROM alembic_version;"))
            alembic_version: str = res.scalar()  # type: ignore[assignment]
            if alembic_version != Versions.ALEMBIC_TARGET_VERSION:
                logger.error(
                    f"{alembic_version=}, TARGET_VERSION={Versions.ALEMBIC_TARGET_VERSION!r}"
                )
                raise WrongAlembicVersionError("Alembic version is not correct")
    async def check(self) -> None:
        for attempt in range(self._postgres_settings.alembic_max_retries):
            try:
                await self.check_alembic_version()
            except (AlembicTableNotFoundError, WrongAlembicVersionError) as e:
                logger.error(
                    f"Failed to check alembic version on attempt {attempt + 1}"
                    f"/{self._postgres_settings.alembic_max_retries}: {str(e)}"
                )
                if attempt < self._postgres_settings.alembic_max_retries - 1:
                    sleep_time = self._postgres_settings.alembic_retry_interval * (2**attempt)
                    logger.info(f"Retrying in {sleep_time:.2f} seconds...")
                    await asyncio.sleep(sleep_time)
                else:
                    raise

from fastapi import FastAPI
from fastapi.openapi.utils import get_openapi
def remove_null_from_any_of(schema: Dict[str, Any]) -> Dict[str, Any]:
    if "properties" in schema:
        for prop, prop_schema in schema["properties"].items():
            if "anyOf" in prop_schema:
                any_of = prop_schema["anyOf"]
                if len(any_of) == 2 and {"type": "null"} in any_of:
                    schema["properties"][prop] = [
                        x for x in any_of if x != {"type": "null"}
                    ][0]
                    if "required" in schema:
                        schema["required"] = [
                            x for x in schema["required"] if x != prop
                        ]
                else:
                    raise NotImplementedError(
                        "anyOf with more than 2 elements not supported"
                    )
    return schema
def patch_openapi_schema(schema: Dict[str, Any]) -> Dict[str, Any]:
    """Patching the openapi schema so the frontend code generator can handle it.
    If a model has a property that is optional (e.g.`sha256: str | None`) this
    will be represented as `anyOf` in the openapi schema.
    The frontend code generator does not handle this correctly, so we remove the
    `null` type from the `anyOf` and remove the property from the `required` list.
    """
    for component_name, component_schema in schema["components"]["schemas"].items():
        schema["components"]["schemas"][component_name] = remove_null_from_any_of(
            component_schema
        )
    return schema
def patch_openapi_schema_for_app(app: FastAPI):
    """Patch openapi schema for app (in place)"""
    openapi_schema = get_openapi(
        title=app.title,
        version=app.version,
        openapi_version=app.openapi_version,
        summary=app.summary,
        description=app.description,
        terms_of_service=app.terms_of_service,
        contact=app.contact,
        license_info=app.license_info,
        routes=app.routes,
        webhooks=app.webhooks.routes,
        tags=app.openapi_tags,
        servers=app.servers,
        separate_input_output_schemas=app.separate_input_output_schemas,
    )
    app.openapi_schema = patch_openapi_schema(openapi_schema)

import ast
import re
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple
class DocstringGenerator:
    """Generate docstrings automatically based on code analysis."""
    def __init__(self):
        self.generated_count = 0
        self.skipped_count = 0
    def analyze_function(self, node: ast.FunctionDef) -> dict[str, Any]:
        """Analyze a function node to extract information for docstring."""
        info = {
            "name": node.name,
            "args": [],
            "returns": None,
            "raises": set(),
            "is_async": isinstance(node, ast.AsyncFunctionDef),
            "is_property": False,
            "is_classmethod": False,
            "is_staticmethod": False,
            "has_yield": False,
            "complexity": 0,
        }
        # Check decorators
        for decorator in node.decorator_list:
            if isinstance(decorator, ast.Name):
                if decorator.id == "property":
                    info["is_property"] = True
                elif decorator.id == "classmethod":
                    info["is_classmethod"] = True
                elif decorator.id == "staticmethod":
                    info["is_staticmethod"] = True
        # Extract arguments
        for arg in node.args.args:
            if arg.arg not in ["self", "cls"]:
                arg_info = {"name": arg.arg, "type": None, "default": None}
                # Get type annotation
                if arg.annotation:
                    arg_info["type"] = ast.unparse(arg.annotation)
                info["args"].append(arg_info)
        # Extract return type
        if node.returns:
            info["returns"] = ast.unparse(node.returns)
        # Analyze function body
        for child in ast.walk(node):
            # Check for raise statements
            if isinstance(child, ast.Raise):
                if isinstance(child.exc, ast.Call) and isinstance(
                    child.exc.func, ast.Name
                ):
                    info["raises"].add(child.exc.func.id)
                elif isinstance(child.exc, ast.Name):
                    info["raises"].add(child.exc.id)
            # Check for yield
            if isinstance(child, ast.Yield | ast.YieldFrom):
                info["has_yield"] = True
            # Simple complexity metric
            if isinstance(child, ast.If | ast.For | ast.While | ast.Try):
                info["complexity"] += 1
        return info
    def generate_function_docstring(self, func_info: dict[str, Any]) -> str:
        """Generate a docstring for a function based on analysis."""
        lines = []
        # Summary line
        summary = self._generate_summary(func_info)
        lines.append(f'"""{summary}')
        # Extended description for complex functions
        if func_info["complexity"] > 3 or len(func_info["args"]) > 3:
            lines.append("")
            lines.append(self._generate_extended_description(func_info))
        # Args section
        if func_info["args"]:
            lines.append("")
            lines.append("Args:")
            for arg in func_info["args"]:
                arg_desc = self._generate_arg_description(arg)
                if arg["type"]:
                    lines.append(f"    {arg['name']}: {arg_desc}")
                else:
                    lines.append(f"    {arg['name']}: {arg_desc}")
        # Returns section
        if func_info["returns"] or not func_info["is_property"]:
            lines.append("")
            lines.append("Returns:")
            returns_desc = self._generate_returns_description(func_info)
            lines.append(f"    {returns_desc}")
        # Raises section
        if func_info["raises"]:
            lines.append("")
            lines.append("Raises:")
            for exc in sorted(func_info["raises"]):
                exc_desc = self._generate_exception_description(exc)
                lines.append(f"    {exc}: {exc_desc}")
        # Yields section
        if func_info["has_yield"]:
            lines.append("")
            lines.append("Yields:")
            lines.append("    Generated values from the iteration.")
        # Examples section for public methods
        if not func_info["name"].startswith("_") and func_info["complexity"] > 2:
            lines.append("")
            lines.append("Examples:")
            lines.append(self._generate_example(func_info))
        lines.append('"""')
        return "\n".join(lines)
    def _generate_summary(self, func_info: dict[str, Any]) -> str:
        """Generate a one-line summary for a function."""
        name = func_info["name"]
        # Common patterns
        if name.startswith("get_"):
            return f"Get {name[4:].replace('_', ' ')}."
        if name.startswith("set_"):
            return f"Set {name[4:].replace('_', ' ')}."
        elif name.startswith("is_"):
            return f"Check if {name[3:].replace('_', ' ')}."
        elif name.startswith("has_"):
            return f"Check if has {name[4:].replace('_', ' ')}."
        elif name.startswith("create_"):
            return f"Create {name[7:].replace('_', ' ')}."
        elif name.startswith("update_"):
            return f"Update {name[7:].replace('_', ' ')}."
        elif name.startswith("delete_"):
            return f"Delete {name[7:].replace('_', ' ')}."
        elif name.startswith("validate_"):
            return f"Validate {name[9:].replace('_', ' ')}."
        elif name.startswith("process_"):
            return f"Process {name[8:].replace('_', ' ')}."
        elif name.startswith("handle_"):
            return f"Handle {name[7:].replace('_', ' ')}."
        elif name == "__init__":
            return "Initialize the instance."
        elif name == "__str__":
            return "Return string representation."
        elif name == "__repr__":
            return "Return detailed representation."
        elif func_info["is_property"]:
            return f"Get the {name.replace('_', ' ')} property."
        elif func_info["is_async"]:
            return f"Asynchronously {name.replace('_', ' ')}."
        else:
            return f"{name.replace('_', ' ').capitalize()}."
    def _generate_extended_description(self, func_info: dict[str, Any]) -> str:
        """Generate extended description for complex functions."""
        if func_info["is_async"]:
            return "This is an asynchronous function that should be awaited."
        if func_info["has_yield"]:
            return "This is a generator function that yields values lazily."
        elif func_info["complexity"] > 5:
            return "This function implements complex logic with multiple conditional branches."
        else:
            return f"This function processes {
    len(
        func_info['args'])} parameters to produce a result."
    def _generate_arg_description(self, arg: dict[str, Any]) -> str:
        """Generate description for an argument."""
        name = arg["name"]
        arg_type = arg["type"]
        # Type-based descriptions
        if arg_type:
            if "str" in arg_type:
                return f"The {name.replace('_', ' ')} string."
            if "int" in arg_type:
                return f"The {name.replace('_', ' ')} integer value."
            elif "float" in arg_type:
                return f"The {name.replace('_', ' ')} floating point value."
            elif "bool" in arg_type:
                return f"Whether to {name.replace('_', ' ')}."
            elif "List" in arg_type:
                return f"List of {name.replace('_', ' ')}."
            elif "Dict" in arg_type:
                return f"Dictionary containing {name.replace('_', ' ')}."
            elif "Optional" in arg_type:
                return f"Optional {name.replace('_', ' ')}."
        # Name-based descriptions
        if name == "config":
            return "Configuration dictionary."
        if name == "data":
            return "Input data to process."
        elif name == "context":
            return "Execution context."
        elif name == "callback":
            return "Callback function to invoke."
        elif name.endswith("_id"):
            return f"Unique identifier for {name[:-3].replace('_', ' ')}."
        elif name.endswith("_path"):
            return f"Path to {name[:-5].replace('_', ' ')}."
        elif name.endswith("_url"):
            return f"URL for {name[:-4].replace('_', ' ')}."
        else:
            return f"The {name.replace('_', ' ')}."
    def _generate_returns_description(self, func_info: dict[str, Any]) -> str:
        """Generate description for return value."""
        returns_type = func_info["returns"]
        name = func_info["name"]
        if returns_type:
            if returns_type == "None":
                return "None"
            if returns_type == "bool":
                return "True if successful, False otherwise."
            elif returns_type == "str":
                return "The resulting string."
            elif returns_type == "int":
                return "The calculated integer value."
            elif returns_type == "float":
                return "The calculated floating point value."
            elif "List" in returns_type:
                return "List of results."
            elif "Dict" in returns_type:
                return "Dictionary containing the results."
            elif "Optional" in returns_type:
                return "The result if found, None otherwise."
            else:
                return f"The {returns_type} result."
        # Name-based inference
        if name.startswith(("is_", "has_")):
            return "True if condition is met, False otherwise."
        if name.startswith(("get_", "find_")):
            return "The requested value or None if not found."
        elif name.startswith(("create_", "build_")):
            return "The newly created instance."
        elif func_info["is_property"]:
            return f"The {name.replace('_', ' ')} value."
        else:
            return "The processed result."
    def _generate_exception_description(self, exc_name: str) -> str:
        """Generate description for an exception."""
        common_exceptions = {
            "ValueError": "If the input value is invalid.",
            "TypeError": "If the input type is incorrect.",
            "KeyError": "If the required key is not found.",
            "AttributeError": "If the required attribute is missing.",
            "RuntimeError": "If a runtime error occurs.",
            "NotImplementedError": "If the feature is not implemented.",
            "FileNotFoundError": "If the specified file is not found.",
            "PermissionError": "If permission is denied.",
            "ConnectionError": "If connection fails.",
            "TimeoutError": "If operation times out.",
        }
        return common_exceptions.get(exc_name, f"If {exc_name} occurs.")
    def _generate_example(self, func_info: dict[str, Any]) -> str:
        """Generate a simple example for a function."""
        name = func_info["name"]
        args = func_info["args"]
        # Build example call
        if args:
            arg_examples = []
            for arg in args[:3]:  # Limit to first 3 args
                if arg["type"] and "str" in arg["type"]:
                    arg_examples.append(f'"{arg["name"]}_value"')
                elif arg["type"] and "int" in arg["type"]:
                    arg_examples.append("123")
                elif arg["type"] and "bool" in arg["type"]:
                    arg_examples.append("True")
                else:
                    arg_examples.append(f"{arg['name']}_value")
            args_str = ", ".join(arg_examples)
            example = f"    >>> result = {name}({args_str})"
        else:
            example = f"    >>> result = {name}()"
        if func_info["is_async"]:
            example = f"    >>> result = await {name}()"
        return example
    def analyze_class(self, node: ast.ClassDef) -> dict[str, Any]:
        """Analyze a class node to extract information."""
        info = {
            "name": node.name,
            "bases": [],
            "methods": [],
            "attributes": [],
            "is_dataclass": False,
            "is_pydantic": False,
        }
        # Extract base classes
        for base in node.bases:
            if isinstance(base, ast.Name):
                info["bases"].append(base.id)
                if base.id in ["BaseModel", "BaseSettings"]:
                    info["is_pydantic"] = True
        # Check decorators
        for decorator in node.decorator_list:
            if isinstance(decorator, ast.Name) and decorator.id == "dataclass":
                info["is_dataclass"] = True
        # Extract methods
        for item in node.body:
            if isinstance(item, ast.FunctionDef):
                info["methods"].append(item.name)
        return info
    def generate_class_docstring(self, class_info: dict[str, Any]) -> str:
        """Generate a docstring for a class."""
        lines = []
        name = class_info["name"]
        # Summary
        if class_info["is_pydantic"]:
            lines.append(f'"""{name} Pydantic model.')
        elif class_info["is_dataclass"]:
            lines.append(f'"""{name} dataclass.')
        elif class_info["bases"]:
            lines.append(f'"""{name} extending {", ".join(class_info["bases"])}.')
        else:
            lines.append(f'"""{name} implementation.')
        # Extended description
        lines.append("")
        if class_info["is_pydantic"]:
            lines.append("This model validates and serializes data using Pydantic.")
        elif class_info["is_dataclass"]:
            lines.append("This dataclass provides a convenient data container.")
        else:
            lines.append(
                f"This class implements {name.replace('_', ' ').lower()} functionality."
            )
        # Attributes section
        if class_info["attributes"]:
            lines.append("")
            lines.append("Attributes:")
            for attr in class_info["attributes"]:
                lines.append(f"    {attr}: Description of {attr}.")
        # Methods section
        if class_info["methods"]:
            public_methods = [m for m in class_info["methods"] if not m.startswith("_")]
            if public_methods:
                lines.append("")
                lines.append("Methods:")
                for method in public_methods[:5]:  # Limit to first 5
                    lines.append(
                        f"    {method}: {method.replace('_', ' ').capitalize()}."
                    )
        lines.append('"""')
        return "\n".join(lines)
    def generate_module_docstring(self, file_path: Path) -> str:
        """Generate a module-level docstring."""
        module_name = file_path.stem
        # Special cases
        if module_name == "__init__":
            parent = file_path.parent.name
            return f'"""Package initialization for {parent}."""'
        if module_name == "config":
            return '"""Configuration management module."""'
        elif module_name == "utils":
            return '"""Utility functions and helpers."""'
        elif module_name == "models":
            return '"""Data models and schemas."""'
        elif module_name == "exceptions":
            return '"""Custom exception definitions."""'
        elif module_name.startswith("test_"):
            return f'"""Tests for {module_name[5:].replace("_", " ")}."""'
        else:
            return f'"""{module_name.replace("_", " ").capitalize()} module."""'
    def process_file(self, file_path: Path, dry_run: bool = False) -> bool:
        """Process a single file to add docstrings."""
        try:
            with open(file_path, encoding="utf-8") as f:
                content = f.read()
            # Parse AST
            tree = ast.parse(content)
            # Check if module docstring exists
            has_module_docstring = (
                isinstance(tree.body[0], ast.Expr)
                and isinstance(tree.body[0].value, ast.Constant)
                and isinstance(tree.body[0].value.value, str)
            )
            modifications = []
            # Add module docstring if missing
            if not has_module_docstring:
                module_doc = self.generate_module_docstring(file_path)
                modifications.append((0, 0, module_doc + "\n\n"))
            # Process functions and classes
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    if not ast.get_docstring(node):
                        func_info = self.analyze_function(node)
                        docstring = self.generate_function_docstring(func_info)
                        # Calculate indentation
                        indent = "    " * (node.col_offset // 4)
                        modifications.append(
                            (node.lineno, node.col_offset, f"{indent}{docstring}")
                        )
                        self.generated_count += 1
                elif isinstance(node, ast.ClassDef) and not ast.get_docstring(node):
                    class_info = self.analyze_class(node)
                    docstring = self.generate_class_docstring(class_info)
                    indent = "    " * (node.col_offset // 4)
                    modifications.append(
                        (node.lineno, node.col_offset, f"{indent}{docstring}")
                    )
                    self.generated_count += 1
            if modifications and not dry_run:
                # Apply modifications
                lines = content.split("\n")
                # Sort by line number (descending) to avoid offset issues
                modifications.sort(key=lambda x: x[0], reverse=True)
                for line_no, _col_offset, docstring in modifications:
                    if line_no == 0:
                        # Module docstring
                        lines.insert(0, docstring)
                    else:
                        # Function/class docstring
                        # Insert after the definition line
                        lines.insert(line_no, docstring)
                # Write back
                with open(file_path, "w", encoding="utf-8") as f:
                    f.write("\n".join(lines))
                return True
            return bool(modifications)
        except Exception as e:
            return False
def main():
    """Main entry point."""
    import argparse
    parser = argparse.ArgumentParser(description="Generate docstrings automatically")
    parser.add_argument("target", help="File or directory to process")
    parser.add_argument(
        "--dry-run", action="store_true", help="Show what would be done"
    )
    args = parser.parse_args()
    generator = DocstringGenerator()
    target = Path(args.target)
    if target.is_file():
        if generator.process_file(target, args.dry_run):
            pass")
    elif target.is_dir():
        files = list(target.rglob("*.py"))
        for file in files:
            if "__pycache__" not in str(file):
                if generator.process_file(file, args.dry_run):
                    pass")
if __name__ == "__main__":
    main()

