from __future__ import annotations
from typing import Any
import torch
from weathergen.model.ssl_target_processing import (
    DINOTargetProcessing,
    JEPATargetProcessing,
    iBOTPatchTargetProcessing,
)
from weathergen.train.target_and_aux_module_base import TargetAndAuxModuleBase, TargetAuxOutput
class EMATeacher(TargetAndAuxModuleBase):
    def __init__(self, model, ema_model, batch_size, training_cfg, **kwargs):
        # One of the issues is that the teacher model may have a different architecture
        # to the student, e.g. JEPA. So we need quite a flexible way to instantiate the
        # the teacher. Because of the device sharding etc that requires quite a bit of
        # massaging we assume that the teacher creates the EMA model correctly. However,
        # note that you cannot assume that model.state_dict equals ema_model.state_dict
        self.ema_model = ema_model
        self.batch_size = batch_size
        # is a dict of TargetProcessing classes as we may use several in parallel
        losses_cfg = [
            v.loss_fcts
            for k, v in training_cfg.losses.items()
            if v.type == "LossLatentSSLStudentTeacher"
        ]
        # TODO: support multiple LossLatentSSLStudentTeacher loss terms
        self.postprocess_targets = get_target_postprocessing(losses_cfg[0], training_cfg, **kwargs)
        self.reset()
    def reset(self, batch_size=None):
        self.ema_model.reset()
        if batch_size is not None:
            self.batch_size = batch_size
    def update_state_pre_backward(self, istep, batch, model, **kwargs) -> None:
        return
    def update_state_post_opt_step(self, istep, batch, model, **kwargs) -> None:
        if self.ema_model.is_model_sharded:
            self.ema_model.ema_model.reshard()
        self.ema_model.update(istep, self.batch_size)
    def compute(self, bidx, batch, model_params, model) -> tuple[Any, Any]:
        with torch.no_grad():
            outputs = self.ema_model.forward_eval(model_params, batch).get_latent_prediction(0)
            targets = {}
            for loss_name, target_module in self.postprocess_targets.items():
                targets[loss_name] = target_module(outputs[loss_name])
            # collect target meta-information for selected samples
            aux_outputs = [list(sample.meta_info.values())[0] for sample in batch.get_samples()]
            targets_out = TargetAuxOutput(batch.get_output_len(), batch.get_output_idxs())
            targets_out.latent = targets
            targets_out.aux_outputs = aux_outputs
            return targets_out
    def to_device(self, device) -> EMATeacher:
        for _, module in self.postprocess_targets.items():
            module.to(device)
        return self
    def get_current_beta(self, cur_step: int) -> float:
        beta = self.ema_model.get_current_beta(cur_step)
        return beta
def get_target_postprocessing(target_losses: list[str], training_cfg, **kwargs):
    return_dict = {}
    for loss_name, conf in target_losses.items():
        if loss_name == "iBOT":
            return_dict[loss_name] = iBOTPatchTargetProcessing(
                patch_out_dim=conf["out_dim"],
                center_momentum=conf["center_momentum"],
                student_temp=conf["loss_extra_args"]["student_temp"],
                teacher_temp=conf["teacher_temp"],
                teacher_style=conf["teacher_style"],
            )
        elif loss_name == "DINO":
            return_dict[loss_name] = DINOTargetProcessing(
                out_dim=conf["out_dim"],
                center_momentum=conf["center_momentum"],
                student_temp=conf["loss_extra_args"]["student_temp"],
                teacher_style=conf["teacher_style"],
            )
        elif loss_name == "JEPA":
            return_dict[loss_name] = JEPATargetProcessing()
        else:
            # We skip losses that are not handled by the EMATeacher
            continue
    return return_dict

import sys
import re
from datetime import datetime
MONTH_MAP = {
    'january': 1, 'february': 2, 'march': 3, 'april': 4,
    'may': 5, 'june': 6, 'july': 7, 'august': 8,
    'september': 9, 'october': 10, 'november': 11, 'december': 12,
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'sept': 9, 'oct': 10,
    'nov': 11, 'dec': 12
}
DATE_FORMATS = [
    '%B %d, %Y', '%b %d, %Y',
    '%d %B %Y', '%d %b %Y',
    '%m/%d/%Y', '%d/%m/%Y',
    '%Y-%m-%d', '%Y/%m/%d'
]
def parse_date(date_str: str) -> str:
    """Parse various date formats to ISO format (YYYY-MM-DD)."""
    date_str = date_str.strip()
    # Try standard formats
    for fmt in DATE_FORMATS:
        try:
            dt = datetime.strptime(date_str, fmt)
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            pass
    # Try regex pattern for "Month DD, YYYY" variations
    pattern = r'(\w+)\s+(\d{1,2}),?\s+(\d{4})'
    match = re.search(pattern, date_str, re.I)
    if match:
        month_name, day, year = match.groups()
        month_num = MONTH_MAP.get(month_name.lower())
        if month_num:
            return f'{year}-{month_num:02d}-{int(day):02d}'
    return ''
def parse_time(time_str: str) -> str:
    """Parse various time formats to HH:MM format."""
    if not time_str:
        return ''
    time_str = time_str.strip()
    # Pattern: HH:MM AM/PM or HH:MM
    pattern1 = r'(\d{1,2}):(\d{2})\s*(am|pm)?'
    match = re.search(pattern1, time_str, re.I)
    if match:
        hour, minute, ampm = int(match.group(1)), int(match.group(2)), match.group(3)
        if ampm:
            ampm = ampm.lower()
            if ampm == 'pm' and hour != 12:
                hour += 12
            elif ampm == 'am' and hour == 12:
                hour = 0
        return f'{hour:02d}:{minute:02d}'
    # Pattern: H AM/PM (no minutes)
    pattern2 = r'(\d{1,2})\s*(am|pm)'
    match = re.search(pattern2, time_str, re.I)
    if match:
        hour, ampm = int(match.group(1)), match.group(2).lower()
        if ampm == 'pm' and hour != 12:
            hour += 12
        elif ampm == 'am' and hour == 12:
            hour = 0
        return f'{hour:02d}:00'
    return ''
def main():
    if len(sys.argv) < 3:
        print("Usage: date_parser.py <date|time> <value>", file=sys.stderr)
        sys.exit(1)
    mode = sys.argv[1]
    value = sys.argv[2]
    if mode == 'date':
        print(parse_date(value))
    elif mode == 'time':
        print(parse_time(value))
    else:
        print(f"Unknown mode: {mode}", file=sys.stderr)
        sys.exit(1)
if __name__ == '__main__':
    main()

from diffusers.modular_pipelines import ModularPipelineBlocks, PipelineState
from diffusers.modular_pipelines.modular_pipeline_utils import (
    ComponentSpec,
    InputParam,
    OutputParam,
)
class PrepareContextFramesBlock(ModularPipelineBlocks):
    @property
    def expected_components(self) -> list[ComponentSpec]:
        return [
            ComponentSpec("generator", torch.nn.Module),
        ]
    @property
    def description(self) -> str:
        return "Prepare Context Frames block updates buffers tracking context frames used in KV cache recomputation"
    @property
    def inputs(self) -> list[InputParam]:
        return [
            InputParam(
                "latents",
                required=True,
                type_hint=torch.Tensor,
                description="Denoised latents",
            ),
            InputParam(
                "output_video",
                required=True,
                type_hint=torch.Tensor,
                description="Decoded video frames",
            ),
            InputParam(
                "current_start_frame",
                required=True,
                type_hint=int,
                description="Current starting frame index of current block",
            ),
            InputParam(
                "context_frame_buffer_max_size",
                type_hint=int,
                description="Max size of context frame buffer",
            ),
            InputParam(
                "decoded_frame_buffer_max_size",
                type_hint=int,
                description="Max size of decoded frame buffer",
            ),
            InputParam(
                "context_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of latent frames",
            ),
            InputParam(
                "decoded_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of decoded frames",
            ),
            InputParam(
                "first_context_frame",
                type_hint=torch.Tensor,
                description="First frame of first block",
            ),
        ]
    @property
    def intermediate_outputs(self) -> list[OutputParam]:
        return [
            OutputParam(
                "first_context_frame",
                type_hint=torch.Tensor,
                description="First frame of first block",
            ),
            OutputParam(
                "context_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of latent frames",
            ),
            OutputParam(
                "decoded_frame_buffer",
                type_hint=torch.Tensor,
                description="Sliding window of decoded frames",
            ),
        ]
    @torch.no_grad()
    def __call__(self, components, state: PipelineState) -> tuple[any, PipelineState]:
        block_state = self.get_block_state(state)
        if block_state.current_start_frame == 0:
            block_state.first_context_frame = block_state.latents[:, :1]
        if block_state.context_frame_buffer_max_size > 0:
            block_state.context_frame_buffer = torch.cat(
                [
                    block_state.context_frame_buffer,
                    block_state.latents.to(
                        block_state.context_frame_buffer.device,
                        block_state.context_frame_buffer.dtype,
                    ),
                ],
                dim=1,
            )[:, -block_state.context_frame_buffer_max_size :]
        if block_state.decoded_frame_buffer_max_size > 0:
            block_state.decoded_frame_buffer = torch.cat(
                [
                    block_state.decoded_frame_buffer,
                    block_state.output_video.to(
                        block_state.decoded_frame_buffer.device,
                        block_state.decoded_frame_buffer.dtype,
                    ),
                ],
                dim=1,
            )[:, -block_state.decoded_frame_buffer_max_size :]
        self.set_block_state(state, block_state)
        return components, state

