def get_selected_cuda_test_devices(mode: str | None = None):
    """Returns a list of CUDA devices according the selected ``mode`` behavior.
    If ``mode`` is ``None``, the ``global test_mode`` value will be used and
    this list will be a subset of the devices returned from ``get_test_devices()``.
    Args:
        mode: ``"basic"``, returns a list containing up to a single CUDA device.
          ``"unique"``, returns a list containing no more than one device of
          every CUDA architecture on the system.
          ``"unique_or_2x"`` behaves like ``"unique"`` but adds up to one
          additional CUDA device if the system only devices of a single CUDA
          architecture.
    """
    if mode is None:
        mode = test_mode
    if mode == "basic":
        if wp.is_cuda_available():
            return [wp.get_device("cuda:0")]
        else:
            return []
    cuda_devices = wp.get_cuda_devices()
    first_cuda_devices = {}
    for d in cuda_devices:
        if d.arch not in first_cuda_devices:
            first_cuda_devices[d.arch] = d
    selected_cuda_devices = list(first_cuda_devices.values())
    if mode == "unique_or_2x" and len(selected_cuda_devices) == 1 and len(cuda_devices) > 1:
        for d in cuda_devices:
            if d not in selected_cuda_devices:
                selected_cuda_devices.append(d)
                break
    return selected_cuda_devices
def get_test_devices(mode: str | None = None):
    """Returns a list of devices based on the mode selected.
    Args:
        mode: The testing mode to specify which devices to include. If not provided or ``None``, the
          ``global test_mode`` value will be used.
          "basic": Returns the CPU and the first GPU device when available.
          "unique": Returns the CPU and all unique GPU architectures.
          "unique_or_2x" (default): Behaves like "unique" but adds up to one additional CUDA device
            if the system only devices of a single CUDA architecture.
          "all": Returns all available devices.
    """
    if mode is None:
        mode = test_mode
    devices = []
    if mode == "basic":
        # only run on CPU and first GPU device
        if wp.is_cpu_available():
            devices.append(wp.get_device("cpu"))
        if wp.is_cuda_available():
            devices.append(wp.get_device("cuda:0"))
    elif mode == "unique" or mode == "unique_or_2x":
        # run on CPU and a subset of GPUs
        if wp.is_cpu_available():
            devices.append(wp.get_device("cpu"))
        devices.extend(get_selected_cuda_test_devices(mode))
    elif mode == "all":
        # run on all devices
        devices = wp.get_devices()
    else:
        raise ValueError(f"Unknown test mode selected: {mode}")
    return devices
def get_cuda_test_devices(mode=None):
    devices = get_test_devices(mode=mode)
    return [d for d in devices if d.is_cuda]
class StreamCapture:
    def __init__(self, stream_name):
        self.stream_name = stream_name  # 'stdout' or 'stderr'
        self.saved = None
        self.target = None
        self.tempfile = None
    def begin(self):
        # Flush the stream buffers managed by libc.
        # This is needed at the moment due to Carbonite not flushing the logs
        # being printed out when extensions are starting up.
        if LIBC is not None:
            LIBC.fflush(None)
        # Get the stream object (sys.stdout or sys.stderr)
        self.saved = getattr(sys, self.stream_name)
        self.target = os.dup(self.saved.fileno())
        # Create temporary capture stream
        self.tempfile = io.TextIOWrapper(
            tempfile.TemporaryFile(buffering=0),
            encoding="utf-8",
            errors="replace",
            newline="",
            write_through=True,
        )
        # Redirect the stream
        os.dup2(self.tempfile.fileno(), self.saved.fileno())
        setattr(sys, self.stream_name, self.tempfile)
    def end(self):
        # The following sleep doesn't seem to fix the test_print failure on Windows
        # if sys.platform == "win32":
        #    # Workaround for what seems to be a Windows-specific bug where
        #    # the output of CUDA's printf is not being immediately flushed
        #    # despite the context synchronization.
        #    time.sleep(0.01)
        if LIBC is not None:
            LIBC.fflush(None)
        # Restore the original stream
        os.dup2(self.target, self.saved.fileno())
        os.close(self.target)
        # Read the captured output
        self.tempfile.seek(0)
        res = self.tempfile.buffer.read()
        self.tempfile.close()
        # Restore the stream object
        setattr(sys, self.stream_name, self.saved)
        return str(res.decode("utf-8"))
# Subclasses for specific streams
class StdErrCapture(StreamCapture):
    def __init__(self):
        super().__init__("stderr")
class StdOutCapture(StreamCapture):
    def __init__(self):
        super().__init__("stdout")
class CheckOutput:
    def __init__(self, test):
        self.test = test
    def __enter__(self):
        # wp.force_load()
        self.capture = StdOutCapture()
        self.capture.begin()
    def __exit__(self, exc_type, exc_value, traceback):
        # ensure any stdout output is flushed
        wp.synchronize()
        s = self.capture.end()
        if s != "":
            print(s.rstrip())
            # fail if test produces unexpected output (e.g.: from wp.expect_eq() builtins)
            # we allow strings starting of the form "Module xxx load on device xxx"
            # for lazy loaded modules
            filtered_s = "\n".join(
                [line for line in s.splitlines() if not (line.startswith("Module") and "load on device" in line)]
            )
            if filtered_s.strip():
                self.test.fail(f"Unexpected output:\n'{s.rstrip()}'")
def assert_array_equal(result: wp.array, expect: wp.array):
    np.testing.assert_equal(result.numpy(), expect.numpy())
def assert_np_equal(result: np.ndarray, expect: np.ndarray, tol=0.0):
    if tol != 0.0:
        # TODO: Get all tests working without the .flatten()
        np.testing.assert_allclose(result.flatten(), expect.flatten(), atol=tol, equal_nan=True)
    else:
        # TODO: Get all tests working with strict=True
        np.testing.assert_array_equal(result, expect)
def most(x: np.ndarray, min_ratio: float = 0.8) -> bool:
    """Helper function to check if most elements of an array are greater than 0 (or True)."""
    if len(x) == 0:
        return True
    return bool(np.sum(x > 0) / len(x) >= min_ratio)
def find_nan_members(obj: Any | None) -> list[str]:
    """Helper function to find any Warp array members of an object that contain NaN values."""
    nan_members = []
    if obj is None:
        return nan_members
    for key, attr in obj.__dict__.items():
        if isinstance(attr, wp.array):
            arr = attr.numpy()
            # Skip structured arrays (e.g., arrays of warp structs) - np.isnan doesn't support them
            if arr.dtype.names is not None:
                continue
            if np.isnan(arr).any():
                nan_members.append(key)
    return nan_members
def find_nonfinite_members(obj: Any | None) -> list[str]:
    """Helper function to find any Warp array members of an object that contain non-finite values."""
    nonfinite_members = []
    if obj is None:
        return nonfinite_members
    for key, attr in obj.__dict__.items():
        if isinstance(attr, wp.array):
            arr = attr.numpy()
            # Skip structured arrays (e.g., arrays of warp structs) - np.isfinite doesn't support them
            if arr.dtype.names is not None:
                continue
            if not np.isfinite(arr).all():
                nonfinite_members.append(key)
    return nonfinite_members
# if check_output is True any output to stdout will be treated as an error
def create_test_func(func, device, check_output, **kwargs):
    # pass args to func
    def test_func(self):
        if check_output:
            with CheckOutput(self):
                func(self, device, **kwargs)
        else:
            func(self, device, **kwargs)
    # Copy the __unittest_expecting_failure__ attribute from func to test_func
    if hasattr(func, "__unittest_expecting_failure__"):
        test_func.__unittest_expecting_failure__ = func.__unittest_expecting_failure__
    return test_func
def skip_test_func(self):
    # A function to use so we can tell unittest that the test was skipped.
    self.skipTest("No suitable devices to run the test.")
def sanitize_identifier(s):
    """replace all non-identifier characters with '_'"""
    s = str(s)
    if s.isidentifier():
        return s
    else:
        return re.sub(r"\W|^(?=\d)", "_", s)
def add_function_test(cls, name, func, devices=None, check_output=True, **kwargs):
    if devices is None:
        setattr(cls, name, create_test_func(func, None, check_output, **kwargs))
    elif isinstance(devices, list):
        if not devices:
            # No devices to run this test
            setattr(cls, name, skip_test_func)
        else:
            for device in devices:
                setattr(
                    cls,
                    name + "_" + sanitize_identifier(device),
                    create_test_func(func, device, check_output, **kwargs),
                )
    else:
        setattr(
            cls,
            name + "_" + sanitize_identifier(devices),
            create_test_func(func, devices, check_output, **kwargs),
        )
def add_kernel_test(cls, kernel, dim, name=None, expect=None, inputs=None, devices=None):
    def test_func(self, device):
        args = []
        if inputs:
            args.extend(inputs)
        if expect:
            # allocate outputs to match results
            result = wp.array(expect, dtype=int, device=device)
            output = wp.zeros_like(result)
            args.append(output)
        # force load so that we don't generate any log output during launch
        kernel.module.load(device)
        with CheckOutput(self):
            wp.launch(kernel, dim=dim, inputs=args, device=device)
        # check output values
        if expect:
            assert_array_equal(output, result)
    if name is None:
        name = kernel.key
    # device is required for kernel tests, so use all devices if none were given
    if devices is None:
        devices = get_test_devices()
    # register test func with class for the given devices
    for d in devices:
        # use a function to forward the device to the inner test function
        def test_func_wrapper(test, device=d):
            test_func(test, device)
        setattr(cls, name + "_" + sanitize_identifier(d), test_func_wrapper)
# helper that first calls the test function to generate all kernel permutations
# so that compilation is done in one-shot instead of per-test
def add_function_test_register_kernel(cls, name, func, devices=None, **kwargs):
    func(None, None, **kwargs, register_kernels=True)
    add_function_test(cls, name, func, devices=devices, **kwargs)
def write_junit_results(
    outfile: str,
    test_records: list,
    tests_run: int,
    tests_failed: int,
    tests_errored: int,
    tests_skipped: int,
    test_duration: float,
):
    """Write a JUnit XML from our report data
    The report file is needed for GitLab to add test reports in merge requests.
    """
    root = ET.Element(
        "testsuite",
        name="Warp Tests",
        failures=str(tests_failed),
        errors=str(tests_errored),
        skipped=str(tests_skipped),
        tests=str(tests_run),
        time=f"{test_duration:.3f}",
    )
    for test_data in test_records:
        test_classname = test_data[0]
        test_methodname = test_data[1]
        test_duration = test_data[2]
        test_status = test_data[3]
        test_case = ET.SubElement(
            root, "testcase", classname=test_classname, name=test_methodname, time=f"{test_duration:.3f}"
        )
        if test_status == "FAIL":
            failure = ET.SubElement(test_case, "failure", message=str(test_data[4]))
            failure.text = str(test_data[5])  # Stacktrace
        elif test_status == "ERROR":
            error = ET.SubElement(test_case, "error")
            error.text = str(test_data[5])  # Stacktrace
        elif test_status == "SKIP":
            skip = ET.SubElement(test_case, "skipped")
            # Set the skip reason
            skip.set("message", str(test_data[4]))
    tree = ET.ElementTree(root)
    if hasattr(ET, "indent"):
        ET.indent(root)  # Pretty-printed XML output, Python 3.9 required
    tree.write(outfile, encoding="utf-8", xml_declaration=True)
class ParallelJunitTestResult(unittest.TextTestResult):
    def __init__(self, stream, descriptions, verbosity):
        stream = type(stream)(sys.stderr)
        self.test_record = []
        super().__init__(stream, descriptions, verbosity)
    def startTest(self, test):
        if self.showAll:
            self.stream.writeln(f"{self.getDescription(test)} ...")
            self.stream.flush()
        elif self.dots:
            self.stream.writeln(f"{test} ...")
            self.stream.flush()
        self.start_time = time.perf_counter_ns()
        super(unittest.TextTestResult, self).startTest(test)
    def _add_helper(self, test, show_all_message):
        if self.showAll:
            self.stream.writeln(f"{self.getDescription(test)} ... {show_all_message}")
        elif self.dots:
            self.stream.writeln(f"{test} ... {show_all_message}")
        self.stream.flush()
    def _record_test(self, test, code, message=None, details=None):
        # For class-level skips (setUpClass raising SkipTest), unittest passes an
        # _ErrorHolder instead of a real test case, and startTest is never called.
        # Guard against missing start_time and _testMethodName.
        start = getattr(self, "start_time", None)
        duration = round((time.perf_counter_ns() - start) * 1e-9, 3) if start is not None else 0.0
        class_name = test.__class__.__name__
        method_name = getattr(test, "_testMethodName", str(test))
        self.test_record.append((class_name, method_name, duration, code, message, details))
    def addSuccess(self, test):
        super(unittest.TextTestResult, self).addSuccess(test)
        self._add_helper(test, "ok")
        self._record_test(test, "OK")
    def addError(self, test, err):
        super(unittest.TextTestResult, self).addError(test, err)
        self._add_helper(test, "ERROR")
        self._record_test(test, "ERROR", str(err[1]), self._exc_info_to_string(err, test))
    def addFailure(self, test, err):
        super(unittest.TextTestResult, self).addFailure(test, err)
        self._add_helper(test, "FAIL")
        self._record_test(test, "FAIL", str(err[1]), self._exc_info_to_string(err, test))
    def addSkip(self, test, reason):
        super(unittest.TextTestResult, self).addSkip(test, reason)
        self._add_helper(test, f"skipped {reason!r}")
        self._record_test(test, "SKIP", reason)
    def addExpectedFailure(self, test, err):
        super(unittest.TextTestResult, self).addExpectedFailure(test, err)
        self._add_helper(test, "expected failure")
        self._record_test(test, "OK", "expected failure")
    def addUnexpectedSuccess(self, test):
        super(unittest.TextTestResult, self).addUnexpectedSuccess(test)
        self._add_helper(test, "unexpected success")
        self._record_test(test, "FAIL", "unexpected success")
    def addSubTest(self, test, subtest, err):
        super(unittest.TextTestResult, self).addSubTest(test, subtest, err)
        if err is not None:
            self._add_helper(test, "ERROR")
            # err is (class, error, traceback)
            self._record_test(test, "FAIL", str(err[1]), self._exc_info_to_string(err, test))
    def printErrors(self):
        pass

import json
import threading
from pathlib import Path
from collections import defaultdict
class CallTracer:
    def __init__(self, include_patterns=None, exclude_patterns=None):
        self.called_functions = set()
        self.call_counts = defaultdict(int)
        self._lock = threading.Lock()
        self._previous_profile = None
        self._previous_thread_profile = None
        self._tracing = False
        self.include_patterns = include_patterns or []
        self.exclude_patterns = exclude_patterns or [
            "site-packages",
            "venv",
            ".venv",
            "/lib/python",
            "/site-packages/pytest",
            "/site-packages/_pytest",
            "/site-packages/pluggy",
            "<frozen",
            "<string>",
        ]
    def _should_trace_file(self, filename):
        if not filename:
            return False
        if self.include_patterns:
            for pat in self.include_patterns:
                if pat in filename:
                    return True
            return False
        for pattern in self.exclude_patterns:
            if pattern in filename:
                return False
        return True
    def _trace_calls(self, frame, event, arg):
        if event == "call":
            code = frame.f_code
            filename = code.co_filename
            if self._should_trace_file(filename):
                func_name = code.co_name
                lineno = code.co_firstlineno
                key = (filename, func_name, lineno)
                with self._lock:
                    self.called_functions.add(key)
                    self.call_counts[key] += 1
        return self._trace_calls
    def start(self):
        if not self._tracing:
            self._previous_profile = sys.getprofile()
            self._previous_thread_profile = threading.getprofile()
            sys.setprofile(self._trace_calls)
            threading.setprofile(self._trace_calls)
            self._tracing = True
    def stop(self):
        if self._tracing:
            sys.setprofile(self._previous_profile)
            threading.setprofile(self._previous_thread_profile)
            self._tracing = False
    def __enter__(self):
        self.start()
        return self
    def __exit__(self, *args):
        self.stop()
    def save(self, filepath=".skylos_trace"):
        data = {
            "version": 1,
            "calls": [
                {
                    "file": filename,
                    "function": func_name,
                    "line": lineno,
                    "count": self.call_counts[(filename, func_name, lineno)],
                }
                for filename, func_name, lineno in sorted(self.called_functions)
            ],
        }
        Path(filepath).write_text(json.dumps(data, indent=2))
        print(f"Saved {len(self.called_functions)} traced function calls to {filepath}")
    @classmethod
    def load(cls, filepath=".skylos_trace"):
        path = Path(filepath)
        if not path.exists():
            return None
        try:
            data = json.loads(path.read_text())
            calls = set()
            for item in data.get("calls", []):
                calls.add((item["file"], item["function"], item["line"]))
            return calls
        except Exception as e:
            print(f"Warning: Failed to load trace data: {e}")
            return None
    def get_stats(self):
        files = set()
        for f, _, _ in self.called_functions:
            files.add(f)
        return {
            "total_calls": len(self.called_functions),
            "unique_functions": len(self.called_functions),
            "files_traced": len(files),
            "files": sorted(files),
        }
_global_tracer = None
def start_tracing(include_patterns=None, exclude_patterns=None):
    global _global_tracer
    _global_tracer = CallTracer(include_patterns, exclude_patterns)
    _global_tracer.start()
    return _global_tracer
def stop_tracing(save_path=".skylos_trace"):
    global _global_tracer
    if _global_tracer:
        _global_tracer.stop()
        _global_tracer.save(save_path)
        stats = _global_tracer.get_stats()
        print(
            f"Traced {stats['unique_functions']} functions across {stats['files_traced']} files"
        )
        return _global_tracer
    return None
def pytest_configure(config):
    if config.getoption("--skylos-trace", default=False):
        include = config.getoption("--skylos-trace-include", default=None)
        if include:
            include_patterns = include.split(",")
        else:
            include_patterns = None
        start_tracing(include_patterns=include_patterns)
        print("Skylos call tracing enabled")
def pytest_unconfigure(config):
    if config.getoption("--skylos-trace", default=False):
        stop_tracing()
def pytest_addoption(parser):
    parser.addoption(
        "--skylos-trace",
        action="store_true",
        default=False,
        help="Enable Skylos call tracing",
    )
    parser.addoption(
        "--skylos-trace-include",
        action="store",
        default=None,
        help="Comma separated list of path patterns to include in tracing",
    )
if __name__ == "__main__":
    import runpy
    if len(sys.argv) < 2:
        print("Usage: python -m skylos_trace <script.py> [args...]")
        print("       python -m skylos_trace -m <module> [args...]")
        sys.exit(1)
    sys.argv = sys.argv[1:]
    if sys.argv[0] == "-m":
        if len(sys.argv) < 2:
            print("Error: -m requires module name")
            sys.exit(1)
        module_name = sys.argv[1]
        sys.argv = sys.argv[1:]
        tracer = CallTracer()
        with tracer:
            runpy.run_module(module_name, run_name="__main__", alter_sys=True)
        tracer.save()
    else:
        script_path = sys.argv[0]
        tracer = CallTracer()
        with tracer:
            runpy.run_path(script_path, run_name="__main__")
        tracer.save()

from statgpt.app.chains.parameters import ChainParameters
from statgpt.app.chains.tools import StatGptTool, ToolArgs
from statgpt.app.chains.utils import dataset_utils
from statgpt.app.schemas import ToolArtifact, ToolMessageState
from statgpt.app.utils.formatters import (
    CitationFormatterConfig,
    DatasetFormatterConfig,
    DetailedDatasetFormatter,
)
from statgpt.common.schemas import ChannelConfig
from statgpt.common.schemas import DatasetStructureTool as DatasetStructureToolConfig
from statgpt.common.schemas import ToolTypes
class DatasetStructureArgs(ToolArgs):
    dataset_id: str = Field(
        description="Dataset ID (URN) in the format 'agency_id:resource_id(version)'."
    )
class DatasetStructureTool(
    StatGptTool[DatasetStructureToolConfig], tool_type=ToolTypes.DATASET_STRUCTURE
):
    def __init__(
        self, tool_config: DatasetStructureToolConfig, channel_config: ChannelConfig, **kwargs
    ):
        super().__init__(tool_config, channel_config, **kwargs)
        self._dataset_formatter_config = DatasetFormatterConfig(
            locale=channel_config.locale,
            add_source_id=True,
            add_entity_id=False,
            use_description=True,
            citation=CitationFormatterConfig(
                as_md_list=True,
                n_tabs=0,
                use_provider=True,
                use_last_updated=True,
                use_url=True,
            ),
            highlight_name_in_bold=True,
            list_level=0,
        )
    @classmethod
    def get_args_schema(cls, tool_config: DatasetStructureToolConfig) -> type[DatasetStructureArgs]:
        """Return the schema for the arguments that this tool accepts."""
        return DatasetStructureArgs
    async def _arun(self, inputs: dict, dataset_id: str, **kwargs) -> tuple[str, ToolArtifact]:
        dataset = await dataset_utils.get_dataset_by_source_id(inputs, dataset_id)
        target = ChainParameters.get_target(inputs)
        auth_context = ChainParameters.get_auth_context(inputs)
        if dataset is None:
            response = (
                f"Dataset with ID '{dataset_id}' not found among available datasets. "
                f"Please check the ID and try again."
            )
            if target:
                target.append_content(response)
            return response, ToolArtifact(state=ToolMessageState(type=self.tool_type))
        formatter = DetailedDatasetFormatter(
            self._dataset_formatter_config, auth_context=auth_context
        )
        response = await formatter.format(dataset)  # type: ignore[arg-type]
        if target:
            target.append_content(response)
        response += (
            "\n\nNote: Don't make any assumptions about the dataset beyond the provided structure information"
            ", especially regarding sample values of the datasets' dimensions."
        )
        return response, ToolArtifact(state=ToolMessageState(type=self.tool_type))

import json
import sys
def qinglite_login(mobile, code):
    url = "https://www.qinglite.cn/api/interface/user/user_mobile/login"
    payload = {
        "mobile": mobile,
        "code": code,
        "prefix": "+86",
        "act": 1,
        "app_type": "openclaw",
        "post_type": "ajax"
    }
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
    }
    try:
        response = requests.post(url, json=payload, headers=headers)
        response.raise_for_status()  # Raise an exception for HTTP errors
        response_json = response.json()
        if response_json.get("code") in [10000, 20000] and "token" in response_json.get("data", {}):
            token = response_json["data"]["token"]
            print(f"Login successful. Token: {token}")
            return token
        else:
            print(f"Login failed: {response_json.get('msg', 'Unknown error')}")
            return None
    except requests.exceptions.RequestException as e:
        print(f"Request error: {e}")
        return None
    except json.JSONDecodeError:
        print(f"Failed to decode JSON from response: {response.text}")
        return None
def qinglite_publish(token, title, content, post_type, media=""):
    url = "https://www.qinglite.cn/api/interface/content/news/create"
    payload = {
        "title": title,
        "content": content,
        "type": post_type,
        "media": media,
        "token": token,
        "app_type": "openclaw"
    }
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
    }
    try:
        response = requests.post(url, json=payload, headers=headers)
        response.raise_for_status()  # Raise an exception for HTTP errors
        response_json = response.json()
        if response_json.get("code") in [10000, 20000]:
            print(f"Publish successful: {response_json.get('msg', 'Success')}")
            return True
        else:
            print(f"Publish failed: {response_json.get('msg', 'Unknown error')}")
            return False
    except requests.exceptions.RequestException as e:
        print(f"Request error: {e}")
        return False
    except json.JSONDecodeError:
        print(f"Failed to decode JSON from response: {response.text}")
        return False
if __name__ == "__main__":
    action = sys.argv[1]
    if action == "login":
        if len(sys.argv) != 4:
            print("Usage: python qinglite_platform.py login <mobile> <code>")
            sys.exit(1)
        mobile = sys.argv[2]
        code = sys.argv[3]
        qinglite_login(mobile, code)
    elif action == "publish":
        if len(sys.argv) < 6 or len(sys.argv) > 7:
            print("Usage: python qinglite_platform.py publish <token> <title> <content> <type> [media]")
            sys.exit(1)
        token = sys.argv[2]
        title = sys.argv[3]
        content = sys.argv[4]
        post_type = int(sys.argv[5])
        media = sys.argv[6] if len(sys.argv) == 7 else ""
        qinglite_publish(token, title, content, post_type, media)
    else:
        print("Invalid action. Use 'login' or 'publish'.")
        sys.exit(1)

from argparse import ArgumentParser
from . import BaseTransformersCLICommand
def download_command_factory(args):
    return DownloadCommand(args.model, args.cache_dir, args.force, args.trust_remote_code)
class DownloadCommand(BaseTransformersCLICommand):
    @staticmethod
    def register_subcommand(parser: ArgumentParser):
        download_parser = parser.add_parser("download")
        download_parser.add_argument(
            "--cache-dir", type=str, default=None, help="Path to location to store the models"
        )
        download_parser.add_argument(
            "--force", action="store_true", help="Force the model to be download even if already in cache-dir"
        )
        download_parser.add_argument(
            "--trust-remote-code",
            action="store_true",
            help="Whether or not to allow for custom models defined on the Hub in their own modeling files. Use only if you've reviewed the code as it will execute on your local machine",
        )
        download_parser.add_argument("model", type=str, help="Name of the model to download")
        download_parser.set_defaults(func=download_command_factory)
    def __init__(self, model: str, cache: str, force: bool, trust_remote_code: bool):
        self._model = model
        self._cache = cache
        self._force = force
        self._trust_remote_code = trust_remote_code
    def run(self):
        from ..models.auto import AutoModel, AutoTokenizer
        AutoModel.from_pretrained(
            self._model, cache_dir=self._cache, force_download=self._force, trust_remote_code=self._trust_remote_code
        )
        AutoTokenizer.from_pretrained(
            self._model, cache_dir=self._cache, force_download=self._force, trust_remote_code=self._trust_remote_code
        )

import json
import platform
import ssl
import sys
from pip._vendor import idna
from pip._vendor import urllib3
from . import __version__ as requests_version
charset_normalizer = None
try:
    from pip._vendor import chardet
except ImportError:
    chardet = None
try:
    from pip._vendor.urllib3.contrib import pyopenssl
except ImportError:
    pyopenssl = None
    OpenSSL = None
    cryptography = None
else:
    import cryptography
    import OpenSSL
def _implementation():
    """Return a dict with the Python implementation and version.
    Provide both the name and the version of the Python implementation
    currently running. For example, on CPython 3.10.3 it will return
    {'name': 'CPython', 'version': '3.10.3'}.
    This function works best on CPython and PyPy: in particular, it probably
    doesn't work for Jython or IronPython. Future investigation should be done
    to work out the correct shape of the code for those platforms.
    """
    implementation = platform.python_implementation()
    if implementation == "CPython":
        implementation_version = platform.python_version()
    elif implementation == "PyPy":
        implementation_version = "{}.{}.{}".format(
            sys.pypy_version_info.major,
            sys.pypy_version_info.minor,
            sys.pypy_version_info.micro,
        )
        if sys.pypy_version_info.releaselevel != "final":
            implementation_version = "".join(
                [implementation_version, sys.pypy_version_info.releaselevel]
            )
    elif implementation == "Jython":
        implementation_version = platform.python_version()  # Complete Guess
    elif implementation == "IronPython":
        implementation_version = platform.python_version()  # Complete Guess
    else:
        implementation_version = "Unknown"
    return {"name": implementation, "version": implementation_version}
def info():
    """Generate information for a bug report."""
    try:
        platform_info = {
            "system": platform.system(),
            "release": platform.release(),
        }
    except OSError:
        platform_info = {
            "system": "Unknown",
            "release": "Unknown",
        }
    implementation_info = _implementation()
    urllib3_info = {"version": urllib3.__version__}
    charset_normalizer_info = {"version": None}
    chardet_info = {"version": None}
    if charset_normalizer:
        charset_normalizer_info = {"version": charset_normalizer.__version__}
    if chardet:
        chardet_info = {"version": chardet.__version__}
    pyopenssl_info = {
        "version": None,
        "openssl_version": "",
    }
    if OpenSSL:
        pyopenssl_info = {
            "version": OpenSSL.__version__,
            "openssl_version": f"{OpenSSL.SSL.OPENSSL_VERSION_NUMBER:x}",
        }
    cryptography_info = {
        "version": getattr(cryptography, "__version__", ""),
    }
    idna_info = {
        "version": getattr(idna, "__version__", ""),
    }
    system_ssl = ssl.OPENSSL_VERSION_NUMBER
    system_ssl_info = {"version": f"{system_ssl:x}" if system_ssl is not None else ""}
    return {
        "platform": platform_info,
        "implementation": implementation_info,
        "system_ssl": system_ssl_info,
        "using_pyopenssl": pyopenssl is not None,
        "using_charset_normalizer": chardet is None,
        "pyOpenSSL": pyopenssl_info,
        "urllib3": urllib3_info,
        "chardet": chardet_info,
        "charset_normalizer": charset_normalizer_info,
        "cryptography": cryptography_info,
        "idna": idna_info,
        "requests": {
            "version": requests_version,
        },
    }
def main():
    """Pretty-print the bug information as JSON."""
    print(json.dumps(info(), sort_keys=True, indent=2))
if __name__ == "__main__":
    main()

from werkzeug.utils import secure_filename
from pathlib import Path
# Max upload size: 10MB
MAX_UPLOAD_SIZE = 10 * 1024 * 1024
CERT_EXTENSIONS = {'.pem', '.crt', '.cer', '.p12', '.pfx', '.p7b', '.der', '.key'}
JSON_EXTENSIONS = {'.json'}
BACKUP_EXTENSIONS = {'.zip', '.enc'}
def validate_upload(file, allowed_extensions=None, max_size=MAX_UPLOAD_SIZE):
    """Validate an uploaded file. Returns (data, safe_filename) or raises ValueError."""
    if not file or not file.filename:
        raise ValueError("No file provided")
    filename = secure_filename(file.filename)
    if not filename:
        raise ValueError("Invalid filename")
    if allowed_extensions:
        ext = Path(filename).suffix.lower()
        if ext not in allowed_extensions:
            raise ValueError(f"Invalid file type: {ext}")
    data = file.read(max_size + 1)
    if len(data) > max_size:
        raise ValueError(f"File too large (max {max_size // (1024*1024)}MB)")
    return data, filename

from collections import defaultdict
import torch.nn as nn
from mindspeed_mm.utils.extra_processor.i2v_processors import I2VProcessor
from mindspeed_mm.models.ae.diffusers_ae_model import DiffusersAEModel
from mindspeed_mm.models.ae.casualvae import CausalVAE
from mindspeed_mm.models.ae.wfvae import WFVAE
from mindspeed_mm.models.ae.contextparallel_causalvae import ContextParallelCasualVAE
from mindspeed_mm.models.ae.autoencoder_kl_hunyuanvideo import AutoencoderKLHunyuanVideo
from mindspeed_mm.models.ae.wan_video_vae import WanVideoVAE
from mindspeed_mm.models.ae.stepvideo_vae import StepVideoVae
from mindspeed_mm.models.ae.movqvae import MOVQ
from mindspeed_mm.models.ae.flux_vae import FluxVae
from mindspeed_mm.models.ae.hunyuanvideo_15_vae import AutoencoderKLConv3D
AE_MODEL_MAPPINGS = {
    "casualvae": CausalVAE,
    "wfvae": WFVAE,
    "contextparallelcasualvae": ContextParallelCasualVAE,
    "autoencoder_kl_hunyuanvideo": AutoencoderKLHunyuanVideo,
    "wan_video_vae": WanVideoVAE,
    "stepvideovae": StepVideoVae,
    "movqvae": MOVQ,
    "flux_vae": FluxVae,
    "hunyuanvideo_15_vae": AutoencoderKLConv3D
}
class AEModel(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config.to_dict()
        self.i2v_processor_config = self.config.pop("i2v_processor", None)
        if self.i2v_processor_config is not None:
            self.i2v_processor = I2VProcessor(self.i2v_processor_config).get_processor()
        else:
            self.i2v_processor = None
        if config.model_id in AE_MODEL_MAPPINGS:
            self.model = AE_MODEL_MAPPINGS[config.model_id](**self.config)
        else:
            # import auto encoder from diffusers
            self.model = DiffusersAEModel(
                model_name=config.model_id, config=self.config
            )
    def get_model(self):
        return self.model
    def encode(self, x, **kwargs):
        if not isinstance(x, (list, tuple)):
            return self._single_encode(x, **kwargs)
        video_latents = []
        i2v_results = defaultdict(list)
        for i, _ in enumerate(x):
            kwargs_i = {
                key: value[i] if isinstance(value, (list, tuple)) and len(value) == len(x) else value
                for key, value in kwargs.items()
            }
            _video_latents, _i2v_results = self._single_encode(x[i], **kwargs_i)
            video_latents.append(_video_latents)
            if _i2v_results is None:
                continue
            for key, value in _i2v_results.items():
                i2v_results[key].append(value)
        return video_latents, i2v_results
    def _single_encode(self, x, **kwargs):
        _video_latents = self.model.encode(x)
        _i2v_results = None
