from subprocess import Popen
from threading import Event, Thread
def cleanup_threads(threads: list[Thread]):
    """Cleanup a list of threads"""
    for thread in threads:
        thread.join(timeout=5)
def cleanup_processes(processes: list[Popen]):
    """Cleanup a list of subprocesses"""
    for process in processes:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=60)
            except subprocess.TimeoutExpired:
                process.kill()
def monitor_process(process: Popen, stop_event: Event, error_queue: list, process_name: str):
    """Monitor a subprocess and signal errors via shared queue."""
    process.wait()
    if process.returncode != 0:
        err_msg = f"{process_name.capitalize()} failed with exit code {process.returncode}"
        if process.stderr:
            err_msg += f"\n{process.stderr.read().decode('utf-8')}"
        error_queue.append(RuntimeError(err_msg))
    stop_event.set()

from typing import List
from ripperdoc.utils.file_watch import ChangedFileNotice
def _format_changed_file_notice(notices: List[ChangedFileNotice]) -> str:
    """Render a system notice about files that changed on disk."""
    lines: List[str] = [
        "System notice: Files you previously read have changed on disk.",
        "Please re-read the affected files before making further edits.",
        "",
    ]
    for notice in notices:
        lines.append(f"- {notice.file_path}")
        summary = (notice.summary or "").rstrip()
        if summary:
            indented = "\n".join(f"    {line}" for line in summary.splitlines())
            lines.append(indented)
    return "\n".join(lines)

import torch
import torch.nn as nn
from einops import rearrange, repeat
def timestep_embedding(timesteps, dim, max_period=10000, repeat_only=False, dtype=torch.float32):
    if not repeat_only:
        half = dim // 2
        freqs = torch.exp(-math.log(max_period) * torch.arange(start=0, end=half, dtype=torch.float32, device=timesteps.device) / half)
        args = timesteps[:, None].float() * freqs[None]
        embedding = torch.cat([torch.cos(args), torch.sin(args)], dim=-1)
        if dim % 2:
            embedding = torch.cat([embedding, torch.zeros_like(embedding[:, :1])], dim=-1)
    else:
        embedding = repeat(timesteps, "b -> b d", d=dim)
    return embedding.to(dtype)
class TimeStepEmbedding(nn.Module):
    def __init__(self, hidden_size, time_embed_dim=None, max_period=10000, repeat_only=False):
        super().__init__()
        self.hidden_size = hidden_size
        self.time_embed_dim = time_embed_dim if time_embed_dim is not None else hidden_size
        self.max_period = max_period
        self.repeat_only = repeat_only
        self.time_embed = nn.Sequential(
            nn.Linear(self.hidden_size, time_embed_dim),
            nn.SiLU(),
            nn.Linear(time_embed_dim, time_embed_dim),
        )
    @property
    def dtype(self) -> torch.dtype:
        """The dtype of the module (assuming that all the module parameters have the same dtype)."""
        params = tuple(self.parameters())
        if len(params) > 0:
            return params[0].dtype
        else:
            buffers = tuple(self.buffers())
            return buffers[0].dtype
    def forward(self, timesteps):
        emb = timestep_embedding(timesteps, self.hidden_size, self.max_period, self.repeat_only, dtype=self.dtype)
        return self.time_embed(emb)

import torch
from torch.distributed.tensor import distribute_tensor
from mindspeed_mm.models.transformers.global_vars import get_ep_fsdp_group, get_check_moe_func
def finalize_model_grads_wrapper(fn):
    @wraps(fn)
    def wrapper(model, num_tokens=None):
        fn(model, num_tokens)
        ep_fsdp_group = get_ep_fsdp_group()
        check_moe_func = get_check_moe_func()
        if ep_fsdp_group is None:
            return
        for model_chunk in model:
            for name, param in model_chunk.named_parameters():
                if param.grad is None or not check_moe_func(name):
                    continue
                local_grad = param.grad.to_local()
                # All-Reduce within EP FSDP group
                torch.distributed.all_reduce(
                    local_grad,
                    op=torch.distributed.ReduceOp.AVG,
                    group=ep_fsdp_group,
                    async_op=True,
                )
                dtensor = distribute_tensor(
                    local_grad,
                    device_mesh=param.grad.device_mesh,
                    placements=param.grad.placements,
                )
                param.grad.copy_(dtensor)
        torch.npu.current_stream().synchronize()
    return wrapper

