import torch
from megatron.core import parallel_state
from rlinf.config import SupportedModel, get_supported_model
def get_tp_reshard_fn(model_type: str):
    model_type = get_supported_model(model_type)
    if model_type == SupportedModel.QWEN2_5:
        return tp_reshard_fn_qwen2_5
    elif model_type == SupportedModel.QWEN3:
        return tp_reshard_fn_qwen3_dense
    elif model_type == SupportedModel.QWEN3_MOE:
        return tp_reshard_fn_qwen3_moe
    else:
        raise NotImplementedError(
            f"get_tp_reshard_fn for model_type {model_type} is not implemented"
        )
def get_tpe_reshard_fn(model_type: str):
    model_type = get_supported_model(model_type)
    if model_type == SupportedModel.QWEN3_MOE:
        return tpe_reshard_fn_qwen3_moe
    else:
        raise NotImplementedError(
            f"get_tpe_reshard_fn for model_type {model_type} is not implemented"
        )
def get_pp_reshard_fn(model_type: str):
    model_type = get_supported_model(model_type)
    if model_type == SupportedModel.QWEN2_5:
        return pp_reshard_fn_qwen2_5
    elif model_type == SupportedModel.QWEN3:
        return pp_reshard_fn_qwen3_dense
    elif model_type == SupportedModel.QWEN3_MOE:
        return pp_reshard_fn_qwen3_moe
    else:
        raise NotImplementedError(
            f"get_pp_reshard_fn for model_type {model_type} is not implemented"
        )
##############################
# tp reshard fn implementation
##############################
def _gather_tp_group_tensor_and_reshard(tensor, dim, merge_factor, tp_group):
    gathered_tensors = [torch.zeros_like(tensor) for _ in range(merge_factor)]
    torch.distributed.all_gather(gathered_tensors, tensor, group=tp_group)
    resharded_tensor = torch.cat(gathered_tensors, dim=dim)
    return resharded_tensor
def tp_reshard_fn_qwen2_5(model_state_dict, merge_factor, tp_group):
    # Parameters that should skip TP resharding (just clone)
    param_skip_tp_reshard = [
        "linear_qkv.layer_norm_weight",
        "mlp.linear_fc1.layer_norm_weight",
        "final_layernorm.weight",
    ]
    # Parameters that need to be gathered on dim=0
    param_reshard_column_parallel_linear = [
        "word_embeddings.weight",
        "output_layer.weight",
        "self_attention.linear_qkv.weight",
        "self_attention.linear_qkv.bias",
        "mlp.linear_fc1.weight",
    ]
    # Parameters that need to be gathered on dim=1
    param_reshard_row_parallel_linear = [
        "self_attention.linear_proj.weight",
        "mlp.linear_fc2.weight",
    ]
    for k, v in model_state_dict.items():
        if any(param in k for param in param_skip_tp_reshard):
            model_state_dict[k] = v.clone()
            continue
        if any(param in k for param in param_reshard_column_parallel_linear):
            dim = 0
        elif any(param in k for param in param_reshard_row_parallel_linear):
            dim = 1
        else:
            assert False, f"Unknown parameter: {k}"
        model_state_dict[k] = _gather_tp_group_tensor_and_reshard(
            v, dim, merge_factor, tp_group
        )
    return model_state_dict
def tp_reshard_fn_qwen3_dense(model_state_dict, merge_factor, tp_group):
    # Parameters that should skip TP resharding (just clone)
    param_skip_tp_reshard = [
        "linear_qkv.layer_norm_weight",
        "linear_fc1.layer_norm_weight",
        "final_layernorm.weight",
        "q_layernorm.weight",
        "k_layernorm.weight",
        "pre_mlp_layernorm.weight",
        "router.weight",
    ]
    # Parameters that need to be gathered on dim=0
    param_reshard_column_parallel_linear = [
        "word_embeddings.weight",
        "output_layer.weight",
        "self_attention.linear_qkv.weight",
        "mlp.linear_fc1.weight",
    ]
    # Parameters that need to be gathered on dim=1
    param_reshard_row_parallel_linear = [
        "self_attention.linear_proj.weight",
        "mlp.linear_fc2.weight",
    ]
    for k, v in model_state_dict.items():
        if any(param in k for param in param_skip_tp_reshard):
            model_state_dict[k] = v.clone()
            continue
        if any(param in k for param in param_reshard_column_parallel_linear):
            dim = 0
        elif any(param in k for param in param_reshard_row_parallel_linear):
            dim = 1
        else:
            assert False, f"Unknown parameter: {k}"
        model_state_dict[k] = _gather_tp_group_tensor_and_reshard(
            v, dim, merge_factor, tp_group
        )
    return model_state_dict
def tp_reshard_fn_qwen3_moe(model_state_dict, merge_factor, tp_group):
    # Parameters that should skip TP resharding (just clone)
    param_skip_tp_reshard = [
        "linear_qkv.layer_norm_weight",
        "linear_fc1.layer_norm_weight",
        "final_layernorm.weight",
        "q_layernorm.weight",
        "k_layernorm.weight",
        "pre_mlp_layernorm.weight",
        "router.weight",
    ]
    # MoE model resharding the mlp weight in tpe_reshard_fn
    # Parameters that need to be gathered on dim=0
    param_reshard_column_parallel_linear = [
        "word_embeddings.weight",
        "output_layer.weight",
        "self_attention.linear_qkv.weight",
    ]
    # Parameters that need to be gathered on dim=1
    param_reshard_row_parallel_linear = [
        "self_attention.linear_proj.weight",
    ]
    # Parameters that need to skip in tp resharding
    param_reshard_skip_weight = [
        "linear_fc1.weight",
        "linear_fc2.weight",
    ]
    for k, v in model_state_dict.items():
        if any(param in k for param in param_skip_tp_reshard):
            model_state_dict[k] = v.clone()
            continue
        if any(param in k for param in param_reshard_column_parallel_linear):
            dim = 0
        elif any(param in k for param in param_reshard_row_parallel_linear):
            dim = 1
        elif any(param in k for param in param_reshard_skip_weight):
            continue
        else:
            assert False, f"Unknown parameter: {k}"
        model_state_dict[k] = _gather_tp_group_tensor_and_reshard(
            v, dim, merge_factor, tp_group
        )
    return model_state_dict
##############################
# tpe reshard fn implementation
##############################
def tpe_reshard_fn_qwen3_moe(
    model_state_dict, tpe_size, tpe_group, rollout_tp_size, dst_tp_rank
):
    for key, value in model_state_dict.items():
        if "linear_fc1.weight" in key:
            dim = 0
        elif "linear_fc2.weight" in key:
            dim = 1
        else:
            continue
        if tpe_size != 1:
            value = _gather_tp_group_tensor_and_reshard(value, dim, tpe_size, tpe_group)
        if dim == 0:
            # for the fc1 weight, we need to split it into two parts gate weight and up weight
            tpe_split_size = value.shape[dim] // tpe_size
            tpe_value_slice = torch.split(value, tpe_split_size, dim=dim)
            gate_proj_shards = []
            up_proj_shards = []
            for i, weight in enumerate(tpe_value_slice):
                weight_chunk = torch.chunk(weight, 2, dim=0)
                gate_proj_shards.append(weight_chunk[0])
                up_proj_shards.append(weight_chunk[1])
            gate_weight = torch.cat(gate_proj_shards, dim=dim)
            up_weight = torch.cat(up_proj_shards, dim=dim)
            rollout_split_size = gate_weight.shape[dim] // rollout_tp_size
            gate_value_slice = torch.split(gate_weight, rollout_split_size, dim=dim)
            up_value_slice = torch.split(up_weight, rollout_split_size, dim=dim)
            model_state_dict[key] = torch.cat(
                [gate_value_slice[dst_tp_rank], up_value_slice[dst_tp_rank]],
                dim=0,
            ).contiguous()
            del gate_weight, up_weight, gate_value_slice, up_value_slice, value
        else:
            rollout_split_size = value.shape[dim] // rollout_tp_size
            value_slice = torch.split(value, rollout_split_size, dim=dim)
            model_state_dict[key] = value_slice[dst_tp_rank].contiguous()
            del value
    return model_state_dict
##############################
# pp reshard fn implementation
##############################
def _gather_pp_group_tensor_and_reshard(
    model_state_dict, key, pp_src_idx, group, dtype
):
    tensor = model_state_dict.get(key)
    if tensor is not None:
        tensor_shape = [tensor.shape]
    else:
        tensor_shape = [None]
    torch.distributed.broadcast_object_list(tensor_shape, pp_src_idx, group=group)
    if tensor_shape[0] is None:
        return None
    if torch.distributed.get_rank() != pp_src_idx:
        tensor = torch.empty(tensor_shape[0], dtype=dtype).cuda()
    torch.distributed.broadcast(tensor.contiguous(), pp_src_idx, group=group)
    return tensor
def gather_pp_group_tensor_and_reshard(
    model_state_dict, keys_with_ranks, pp_group, dtype
):
    """Helper function to reshard multiple keys."""
    for key, target_rank in keys_with_ranks:
        tensor = _gather_pp_group_tensor_and_reshard(
            model_state_dict, key, target_rank, pp_group, dtype
        )
        if tensor is not None:
            model_state_dict[key] = tensor.clone()
    return model_state_dict
def _pp_reshard_fn_Qwen_model(model_state_dict, pp_group, dtype):
    """Common resharding logic for Qwen models."""
    pp_first_rank = parallel_state.get_pipeline_model_parallel_first_rank()
    pp_last_rank = parallel_state.get_pipeline_model_parallel_last_rank()
    keys_with_ranks = [
        ("embedding.word_embeddings.weight", pp_first_rank),
        ("decoder.final_layernorm.weight", pp_last_rank),
        ("decoder.final_layernorm.bias", pp_last_rank),
        ("output_layer.weight", pp_last_rank),
    ]
    return gather_pp_group_tensor_and_reshard(
        model_state_dict, keys_with_ranks, pp_group, dtype
    )
def pp_reshard_fn_qwen2_5(model_state_dict, pp_group, dtype):
    """Reshard pipeline parallel weights for Qwen2.5 models."""
    return _pp_reshard_fn_Qwen_model(model_state_dict, pp_group, dtype)
def pp_reshard_fn_qwen3_dense(model_state_dict, pp_group, dtype):
    """Reshard pipeline parallel weights for Qwen3 dense models."""
    return _pp_reshard_fn_Qwen_model(model_state_dict, pp_group, dtype)
def pp_reshard_fn_qwen3_moe(model_state_dict, pp_group, dtype):
    """Reshard pipeline parallel weights for Qwen3 MoE models."""
    return _pp_reshard_fn_Qwen_model(model_state_dict, pp_group, dtype)

import argparse
import json
import os
import sys
from datetime import datetime, timezone
def parse_jsonl(path):
    """Yield parsed JSON objects from a JSONL file."""
    if not os.path.isfile(path):
        return
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                continue
def parse_ts(ts_str):
    """Parse ISO timestamp string to datetime."""
    # Handle both Z and +00:00 suffixes
    ts_str = ts_str.replace("Z", "+00:00")
    return datetime.fromisoformat(ts_str)
def load_tasks(audit_path):
    """Load task pairs (started + completed) from dispatcher audit log."""
    starts = {}
    tasks = []
    for entry in parse_jsonl(audit_path):
        task_id = entry.get("task_id")
        if not task_id:
            continue
        if "user_message" in entry:
            starts[task_id] = entry
        elif "output" in entry and task_id in starts:
            start = starts.pop(task_id)
            tasks.append({
                "task_id": task_id,
                "user_id": start.get("user_id"),
                "timestamp_start": start["timestamp"],
                "timestamp_end": entry["timestamp"],
                "user_message": start["user_message"],
                "response": entry["output"],
                "response_length": entry.get("output_length", len(entry["output"])),
            })
    return tasks
def load_firewall(audit_path):
    """Load firewall entries (allow/deny + output) sorted by timestamp."""
    entries = []
    for entry in parse_jsonl(audit_path):
        if "command" not in entry:
            continue
        entries.append(entry)
    entries.sort(key=lambda e: e["timestamp"])
    return entries
def correlate(tasks, firewall_entries):
    """Match firewall entries to tasks by timestamp window."""
    traces = []
    for task in tasks:
        t_start = parse_ts(task["timestamp_start"])
        t_end = parse_ts(task["timestamp_end"])
        # Collect firewall entries within this task's time window
        tool_calls = {}
        for entry in firewall_entries:
            t_entry = parse_ts(entry["timestamp"])
            if t_entry < t_start:
                continue
            if t_entry > t_end:
                break
            cmd = entry["command"]
            if "allowed" in entry:
                tool_calls[cmd] = {
                    "command": cmd,
                    "allowed": entry["allowed"],
                    "reason": entry.get("reason", ""),
                }
            elif "output_length" in entry and cmd in tool_calls:
                tool_calls[cmd]["output_length"] = entry["output_length"]
        trace = {
            "task_id": task["task_id"],
            "user_id": task["user_id"],
            "timestamp": task["timestamp_start"],
            "user_message": task["user_message"],
            "tool_calls": list(tool_calls.values()),
            "response": task["response"],
        }
        traces.append(trace)
    return traces
def main():
    parser = argparse.ArgumentParser(description="Export correlated h-cli traces")
    parser.add_argument("-l", "--log-dir", default="logs",
                        help="Log directory (default: logs/)")
    parser.add_argument("-o", "--output", default="traces.jsonl",
                        help="Output file (default: traces.jsonl)")
    parser.add_argument("--since", default=None,
                        help="Only include tasks after this date (YYYY-MM-DD)")
    args = parser.parse_args()
    dispatcher_audit = os.path.join(args.log_dir, "claude", "audit.log")
    firewall_audit = os.path.join(args.log_dir, "firewall", "audit.log")
    if not os.path.isfile(dispatcher_audit):
        print(f"Not found: {dispatcher_audit}", file=sys.stderr)
        sys.exit(1)
    # Load and correlate
    tasks = load_tasks(dispatcher_audit)
    firewall_entries = load_firewall(firewall_audit)
    traces = correlate(tasks, firewall_entries)
    # Filter by date if requested
    if args.since:
        since = datetime.strptime(args.since, "%Y-%m-%d").replace(tzinfo=timezone.utc)
        traces = [t for t in traces if parse_ts(t["timestamp"]) >= since]
    # Write output
    with open(args.output, "w") as f:
        for trace in traces:
            f.write(json.dumps(trace, ensure_ascii=False) + "\n")
    print(f"Exported {len(traces)} traces -> {args.output}")
if __name__ == "__main__":
    main()

from __future__ import annotations
import os
import subprocess
import tempfile
import unittest
from pathlib import Path
ROOT = next(p for p in Path(__file__).resolve().parents if (p / "src").exists())
PYTRA_TEST_COMPILE_TIMEOUT_SEC = float(os.environ.get("PYTRA_TEST_COMPILE_TIMEOUT_SEC", "120"))
PYTRA_TEST_RUN_TIMEOUT_SEC = float(os.environ.get("PYTRA_TEST_RUN_TIMEOUT_SEC", "2"))
CPP_RUNTIME_SRCS = [
    "src/runtime/cpp/core/gc.ext.cpp",
    "src/runtime/cpp/core/io.ext.cpp",
]
class CppRuntimeIterableTest(unittest.TestCase):
    def _run(self, args: list[str], *, cwd: Path, timeout_sec: float, label: str) -> subprocess.CompletedProcess[str]:
        try:
            return subprocess.run(args, cwd=cwd, capture_output=True, text=True, timeout=timeout_sec)
        except subprocess.TimeoutExpired as ex:
            out_obj = ex.stdout
            err_obj = ex.stderr
            out_txt = out_obj if isinstance(out_obj, str) else ""
            err_txt = err_obj if isinstance(err_obj, str) else ""
            self.fail(
                f"{label} timed out after {timeout_sec:.1f}s: {' '.join(args)}\n"
                f"stdout:\n{out_txt}\n"
                f"stderr:\n{err_txt}"
            )
            raise AssertionError("unreachable")
    def test_runtime_iterable_protocol_helpers(self) -> None:
        cpp_src = r'''
#include "runtime/cpp/core/py_runtime.ext.h"
#include <cassert>
#include <iostream>
int main() {
    object list_obj = make_object(list<int64>{1, 2, 3});
    object iter_obj = py_iter_or_raise(list_obj);
    auto n0 = py_next_or_stop(iter_obj);
    auto n1 = py_next_or_stop(iter_obj);
    auto n2 = py_next_or_stop(iter_obj);
    auto n3 = py_next_or_stop(iter_obj);
    assert(n0.has_value() && obj_to_int64(*n0) == 1);
    assert(n1.has_value() && obj_to_int64(*n1) == 2);
    assert(n2.has_value() && obj_to_int64(*n2) == 3);
    assert(!n3.has_value());
    object mut_list_obj = make_object(list<int64>{10, 20});
    object mut_iter_obj = py_iter_or_raise(mut_list_obj);
    auto m0 = py_next_or_stop(mut_iter_obj);
    assert(m0.has_value() && obj_to_int64(*m0) == 10);
    py_append(mut_list_obj, make_object(int64(30)));
    auto m1 = py_next_or_stop(mut_iter_obj);
    auto m2 = py_next_or_stop(mut_iter_obj);
    auto m3 = py_next_or_stop(mut_iter_obj);
    assert(m1.has_value() && obj_to_int64(*m1) == 20);
    assert(m2.has_value() && obj_to_int64(*m2) == 30);
    assert(!m3.has_value());
    py_extend(mut_list_obj, make_object(list<int64>{40, 50}));
    assert(py_len(mut_list_obj) == 5);
    object p0 = py_pop(mut_list_obj);
    assert(obj_to_int64(p0) == 50);
    object p1 = py_pop(mut_list_obj, 0);
    assert(obj_to_int64(p1) == 10);
    py_reverse(mut_list_obj);
    assert(obj_to_int64(py_at(mut_list_obj, 0)) == 40);
    py_sort(mut_list_obj);
    assert(obj_to_int64(py_at(mut_list_obj, 0)) == 20);
    py_clear(mut_list_obj);
    assert(py_len(mut_list_obj) == 0);
    int64 sum = 0;
    for (object v : py_dyn_range(list_obj)) {
        sum += obj_to_int64(v);
    }
    assert(sum == 6);
    dict<str, object> d{};
    d["a"] = make_object(1);
    d["b"] = make_object(2);
    bool has_a = false;
    bool has_b = false;
    for (object key_obj : py_dyn_range(make_object(d))) {
        str key = obj_to_str(key_obj);
        if (key == "a") has_a = true;
        if (key == "b") has_b = true;
    }
    assert(has_a && has_b);
    str joined = "";
    for (object ch : py_dyn_range(make_object(str("ab")))) {
        joined += obj_to_str(ch);
    }
    assert(joined == "ab");
    object set_obj = make_object(set<int64>{1, 2, 3});
    int64 set_sum = 0;
    for (object v : py_dyn_range(set_obj)) {
        set_sum += obj_to_int64(v);
    }
    assert(set_sum == 6);
    bool thrown = false;
    try {
        for (object _ : py_dyn_range(make_object(int64(9)))) {
            (void)_;
        }
    } catch (const ::std::runtime_error&) {
        thrown = true;
    }
    assert(thrown);
    std::cout << "runtime iterable ok" << std::endl;
    return 0;
}
'''
        with tempfile.TemporaryDirectory() as tmpdir:
            work = Path(tmpdir)
            src = work / "runtime_iterable.cpp"
            exe = work / "runtime_iterable.out"
            src.write_text(cpp_src, encoding="utf-8")
            comp = self._run(
                [
                    "g++",
                    "-std=c++20",
                    "-O2",
                    "-I",
                    "src",
                    "-I",
                    "src/runtime/cpp",
                    str(src),
                    *CPP_RUNTIME_SRCS,
                    "-o",
                    str(exe),
                ],
                cwd=ROOT,
                timeout_sec=PYTRA_TEST_COMPILE_TIMEOUT_SEC,
                label="compile runtime iterable smoke",
            )
            self.assertEqual(comp.returncode, 0, msg=comp.stderr)
            run = self._run(
                [str(exe)],
                cwd=work,
                timeout_sec=PYTRA_TEST_RUN_TIMEOUT_SEC,
                label="run runtime iterable smoke",
            )
            self.assertEqual(run.returncode, 0, msg=run.stderr)
            self.assertIn("runtime iterable ok", run.stdout)
if __name__ == "__main__":
    unittest.main()

import json
import re
import sys
import os
from datetime import datetime, timezone

ID_PATTERN = re.compile(r'^EXP-\d{8}-\d{4}$')
VALID_SIGNIFICANCE = {'routine', 'notable', 'pivotal'}
BUILTIN_SOURCES = {'conversation', 'moltbook', 'x', 'heartbeat', 'flush_harvest', 'other'}
REQUIRED_FIELDS = {'id', 'timestamp', 'source', 'content', 'significance', 'significance_reason', 'reflected'}


def load_config_sources(config_path):
    """Load additional valid source names from config.json."""
    extra = set()
    if config_path and os.path.exists(config_path):
        try:
            with open(config_path) as f:
                cfg = json.load(f)
            for key in cfg.get('sources', {}):
                extra.add(key)
        except Exception:
            pass
    return BUILTIN_SOURCES | extra


def parse_iso(ts):
    """Check if timestamp is valid ISO-8601."""
    try:
        # Handle both Z and +00:00 formats
        ts = ts.replace('Z', '+00:00')
        dt = datetime.fromisoformat(ts)
        return dt
    except (ValueError, TypeError):
        return None


def validate(filepath, config_path=None):
    errors = []
    warnings = []
    valid_sources = load_config_sources(config_path)
    seen_ids = set()
    line_count = 0
    notable_pivotal_ids = []

    if not os.path.exists(filepath):
        return {
            'status': 'FAIL',
            'file': filepath,
            'errors': [{'line': None, 'field': None, 'message': f'File not found: {filepath}'}],
            'warnings': [],
            'stats': {}
        }

    with open(filepath, 'r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            line_count += 1

            # Parse JSON
            try:
                entry = json.loads(line)
            except json.JSONDecodeError as e:
                errors.append({
                    'line': line_num,
                    'field': None,
                    'message': f'Invalid JSON: {str(e)[:80]}'
                })
                continue

            if not isinstance(entry, dict):
                errors.append({
                    'line': line_num,
                    'field': None,
                    'message': f'Expected JSON object, got {type(entry).__name__}'
                })
                continue

            # Required fields
            for field in REQUIRED_FIELDS:
                if field not in entry:
                    errors.append({
                        'line': line_num,
                        'field': field,
                        'message': f'Missing required field: {field}'
                    })

            # ID format
            eid = entry.get('id', '')
            if eid and not ID_PATTERN.match(eid):
                errors.append({
                    'line': line_num,
                    'field': 'id',
                    'message': f'Invalid ID format: "{eid}" (expected EXP-YYYYMMDD-NNNN)'
                })

            # Duplicate ID
            if eid in seen_ids:
                errors.append({
                    'line': line_num,
                    'field': 'id',
                    'message': f'Duplicate ID: {eid}'
                })
            seen_ids.add(eid)

            # Timestamp
            ts = entry.get('timestamp')
            if ts:
                dt = parse_iso(ts)
                if dt is None:
                    errors.append({
                        'line': line_num,
                        'field': 'timestamp',
                        'message': f'Invalid ISO-8601 timestamp: "{ts}"'
                    })
                elif dt.tzinfo and dt > datetime.now(timezone.utc):
                    warnings.append({
                        'line': line_num,
                        'message': f'Timestamp is in the future: {ts}'
                    })

            # Source
            source = entry.get('source', '')
            if source and source not in valid_sources:
                errors.append({
                    'line': line_num,
                    'field': 'source',
                    'message': f'Unknown source: "{source}" (valid: {sorted(valid_sources)})'
                })

            # Significance
            sig = entry.get('significance', '')
            if sig and sig not in VALID_SIGNIFICANCE:
                errors.append({
                    'line': line_num,
                    'field': 'significance',
                    'message': f'Invalid significance: "{sig}" (valid: routine, notable, pivotal)'
                })

            # Track notable/pivotal for promotion check
            if sig in ('notable', 'pivotal'):
                notable_pivotal_ids.append(eid)

            # Content non-empty
            content = entry.get('content', '')
            if isinstance(content, str) and not content.strip():
                errors.append({
                    'line': line_num,
                    'field': 'content',
                    'message': 'Content is empty'
                })

            # Significance reason non-empty
            reason = entry.get('significance_reason', '')
            if isinstance(reason, str) and not reason.strip():
                warnings.append({
                    'line': line_num,
                    'message': 'significance_reason is empty'
                })

            # Reflected is boolean
            reflected = entry.get('reflected')
            if reflected is not None and not isinstance(reflected, bool):
                errors.append({
                    'line': line_num,
                    'field': 'reflected',
                    'message': f'reflected must be boolean, got {type(reflected).__name__}: {reflected}'
                })

    status = 'FAIL' if errors else 'PASS'
    return {
        'status': status,
        'file': filepath,
        'errors': errors,
        'warnings': warnings,
        'stats': {
            'total_entries': line_count,
            'unique_ids': len(seen_ids),
            'notable_pivotal_count': len(notable_pivotal_ids),
            'notable_pivotal_ids': notable_pivotal_ids
        }
    }


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: validate_experience.py <jsonl_file> [--config config.json]', file=sys.stderr)
        sys.exit(2)

    filepath = sys.argv[1]
    config_path = None
    if '--config' in sys.argv:
        idx = sys.argv.index('--config')
        if idx + 1 < len(sys.argv):
            config_path = sys.argv[idx + 1]

    result = validate(filepath, config_path)
    print(json.dumps(result, indent=2))
    sys.exit(0 if result['status'] == 'PASS' else 1)

import concurrent.futures
