            "meta_info": {
                "finish_reason": {"type": "stop"},
                "prompt_tokens": len(input_ids),
                "cached_tokens": 0,
                "completion_tokens": 5,
                "output_token_logprobs": [
                    [-0.0, 59],
                    [-0.0078125, 79075],
                    [-0.015625, 90],
                    [-0.0234375, 23],
                    [-0.03125, 92],
                ],
