Webhook API - UCM
Endpoints for managing webhook configurations.
"""
from flask import Blueprint, request
from auth.unified import require_auth
from utils.response import success_response, error_response
from models import db
from services.webhook_service import WebhookEndpoint, WebhookService
import json
import secrets
bp = Blueprint('webhooks', __name__)
@bp.route('/api/v2/webhooks', methods=['GET'])
@require_auth(['read:settings'])
def list_webhooks():
    """List all webhook endpoints"""
    endpoints = WebhookEndpoint.query.all()
    return success_response(data=[e.to_dict() for e in endpoints])
@bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['GET'])
@require_auth(['read:settings'])
def get_webhook(endpoint_id):
    """Get webhook endpoint details"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    return success_response(data=endpoint.to_dict())
@bp.route('/api/v2/webhooks', methods=['POST'])
@require_auth(['write:settings'])
def create_webhook():
    """Create new webhook endpoint"""
    data = request.get_json()

    if not data.get('name'):
        return error_response("Webhook name is required", 400)
    if not data.get('url'):
        return error_response("Webhook URL is required", 400)

    # Validate URL format
    url = data['url']
    if not url.startswith(('http://', 'https://')):
        return error_response("URL must start with http:// or https://", 400)

    events = data.get('events', ['*'])
    if not isinstance(events, list):
        return error_response('Events must be an array', 400)
    custom_headers = data.get('custom_headers', {})
    if custom_headers and not isinstance(custom_headers, dict):
        return error_response('Custom headers must be an object', 400)

    endpoint = WebhookEndpoint(
        name=data['name'],
        url=url,
        secret=data.get('secret') or secrets.token_urlsafe(32),
        events=json.dumps(events),
        ca_filter=data.get('ca_filter'),
        enabled=data.get('enabled', True),
        custom_headers=json.dumps(custom_headers)
    )

    db.session.add(endpoint)
    db.session.commit()

    return success_response(data=endpoint.to_dict(), message="Webhook created")
@bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['PUT'])
@require_auth(['write:settings'])
def update_webhook(endpoint_id):
    """Update webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    data = request.get_json()

    if 'name' in data:
        endpoint.name = data['name']
    if 'url' in data:
        url = data['url']
        if not url.startswith(('http://', 'https://')):
            return error_response("URL must start with http:// or https://", 400)
        endpoint.url = url
    if 'secret' in data:
        endpoint.secret = data['secret']
    if 'events' in data:
        if not isinstance(data['events'], list):
            return error_response('Events must be an array', 400)
        endpoint.events = json.dumps(data['events'])
    if 'ca_filter' in data:
        endpoint.ca_filter = data['ca_filter']
    if 'enabled' in data:
        endpoint.enabled = data['enabled']
    if 'custom_headers' in data:
        if data['custom_headers'] and not isinstance(data['custom_headers'], dict):
            return error_response('Custom headers must be an object', 400)
        endpoint.custom_headers = json.dumps(data['custom_headers'])

    db.session.commit()
    return success_response(data=endpoint.to_dict(), message="Webhook updated")
@bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['DELETE'])
@require_auth(['write:settings'])
def delete_webhook(endpoint_id):
    """Delete webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    db.session.delete(endpoint)
    db.session.commit()
    return success_response(message="Webhook deleted")
@bp.route('/api/v2/webhooks/<int:endpoint_id>/toggle', methods=['POST'])
@require_auth(['write:settings'])
def toggle_webhook(endpoint_id):
    """Enable/disable webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    endpoint.enabled = not endpoint.enabled
    db.session.commit()

    status = "enabled" if endpoint.enabled else "disabled"
    return success_response(data=endpoint.to_dict(), message=f"Webhook {status}")
@bp.route('/api/v2/webhooks/<int:endpoint_id>/test', methods=['POST'])
@require_auth(['write:settings'])
def test_webhook(endpoint_id):
    """Send test event to webhook endpoint"""
    success, message = WebhookService.test_endpoint(endpoint_id)

    if success:
        return success_response(message=message)
    else:
        return error_response(message, 400)
@bp.route('/api/v2/webhooks/<int:endpoint_id>/regenerate-secret', methods=['POST'])
@require_auth(['write:settings'])
def regenerate_secret(endpoint_id):
    """Regenerate webhook secret"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    endpoint.secret = secrets.token_urlsafe(32)
    db.session.commit()

    return success_response(
        data={'secret': endpoint.secret},
        message="Secret regenerated"
    )
@bp.route('/api/v2/webhooks/events', methods=['GET'])
@require_auth(['read:settings'])
def list_events():
    """List available webhook event types"""
    return success_response(data={
        'events': WebhookService.ALL_EVENTS,
        'descriptions': {
            'certificate.issued': 'When a new certificate is issued',
            'certificate.revoked': 'When a certificate is revoked',
            'certificate.renewed': 'When a certificate is auto-renewed',
            'certificate.expiring': 'When a certificate is about to expire',
            'ca.created': 'When a new CA is created',
            'ca.updated': 'When a CA is updated',
            'csr.submitted': 'When a CSR is submitted',
            'csr.approved': 'When a CSR is approved',
            'csr.rejected': 'When a CSR is rejected',
        }
    })

import argparse
import json
import sys
from datetime import datetime, timezone
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent))
from pubmed_search import search_and_fetch as pubmed_search
from semantic_scholar import search_papers as s2_search, get_paper, get_related, get_citations
def build_query(input_data: dict) -> str:
    """Build a search query from structured input."""
    parts = []
    if input_data.get("query"):
        return input_data["query"]
    if input_data.get("compound") or input_data.get("name"):
        parts.append(input_data.get("compound") or input_data.get("name"))
    if input_data.get("smiles"):
        # SMILES aren't great for text search, but compound name should be provided too
        pass
    if input_data.get("target"):
        parts.append(input_data["target"])
    if input_data.get("disease"):
        parts.append(input_data["disease"])
    if input_data.get("mechanism"):
        parts.append(input_data["mechanism"])
    if input_data.get("reaction"):
        parts.append(input_data["reaction"] + " catalyst")
    if input_data.get("topic"):
        parts.append(input_data["topic"])
    return " ".join(parts) if parts else ""
def deduplicate(pubmed_papers: list, s2_papers: list) -> list:
    """Merge and deduplicate papers from both sources."""
    seen_dois = set()
    seen_pmids = set()
    seen_titles = set()
    merged = []
    # PubMed papers first (more reliable metadata)
    for p in pubmed_papers:
        doi = p.get("doi", "").lower()
        pmid = p.get("pmid", "")
        title_key = p.get("title", "").lower()[:80]
        if doi and doi in seen_dois:
            continue
        if pmid and pmid in seen_pmids:
            continue
        if title_key in seen_titles:
            continue
        p["sources"] = ["pubmed"]
        if doi:
            seen_dois.add(doi)
        if pmid:
            seen_pmids.add(pmid)
        seen_titles.add(title_key)
        merged.append(p)
    # Add S2 papers that aren't already present
    for p in s2_papers:
        doi = p.get("doi", "").lower()
        pmid = p.get("pmid", "")
        title_key = p.get("title", "").lower()[:80]
        if doi and doi in seen_dois:
            # Enrich existing entry with S2 data
            for m in merged:
                if m.get("doi", "").lower() == doi:
                    m["sources"].append("semantic_scholar")
                    m["citation_count"] = p.get("citation_count", 0)
                    m["influential_citations"] = p.get("influential_citations", 0)
                    m["tldr"] = p.get("tldr", "")
                    m["pdf_url"] = p.get("pdf_url", "")
                    break
            continue
        if pmid and pmid in seen_pmids:
            continue
        if title_key in seen_titles:
            continue
        p["sources"] = ["semantic_scholar"]
        if doi:
            seen_dois.add(doi)
        if pmid:
            seen_pmids.add(pmid)
        seen_titles.add(title_key)
        merged.append(p)
    return merged
def chain_run(input_data: dict) -> dict:
    """Route input to appropriate literature search workflow."""
    context = input_data.get("context", "user")
    max_results = input_data.get("max_results", 10)
    years = input_data.get("years")
    # Handle specific paper lookups
    if input_data.get("doi"):
        paper_id = f"DOI:{input_data['doi']}"
        action = input_data.get("action", "details")
        if action == "citations":
            return get_citations(paper_id, max_results)
        elif action == "related":
            return get_related(paper_id, max_results)
        else:
            return get_paper(paper_id)
    if input_data.get("pmid"):
        paper_id = f"PMID:{input_data['pmid']}"
        return get_paper(paper_id)
    # Build search query
    query = build_query(input_data)
    if not query:
        return {
            "agent": "literature",
            "version": "1.0.0",
            "status": "error",
            "error": "No search query could be constructed. Provide 'query', 'compound', 'target', 'disease', or 'topic'.",
        }
    # Search both sources
    pubmed_results = pubmed_search(query, max_results, "relevance", years)
    s2_results = s2_search(query, max_results)
    pubmed_papers = pubmed_results.get("papers", [])
    s2_papers = s2_results.get("papers", [])
    # Merge and deduplicate
    merged = deduplicate(pubmed_papers, s2_papers)
    # Sort by citation count (if available), then year
    merged.sort(key=lambda p: (p.get("citation_count", 0), p.get("year", "0")), reverse=True)
    # Determine recommended next agents
    recommend_next = set()
    if any("drug" in (p.get("title", "") + " " + " ".join(p.get("mesh_terms", []))).lower() for p in merged[:5]):
        recommend_next.add("pharmacology")
    if any("synth" in (p.get("title", "") + " " + p.get("abstract", "")).lower() for p in merged[:5]):
        recommend_next.update(["chemistry-query", "catalyst-design"])
    if any("patent" in (p.get("title", "") + " " + p.get("abstract", "")).lower() for p in merged[:5]):
        recommend_next.add("ip-expansion")
    if any("adverse" in (p.get("title", "") + " " + p.get("abstract", "")).lower() for p in merged[:5]):
        recommend_next.add("market-intel")
    return {
        "agent": "literature",
        "version": "1.0.0",
        "context": context,
        "query": query,
        "status": "success" if merged else "no_results",
        "pubmed_total": pubmed_results.get("total_found", 0),
        "s2_total": s2_results.get("total_found", 0),
        "returned": len(merged),
        "papers": merged[:max_results],
        "recommend_next": sorted(recommend_next) if recommend_next else ["chemistry-query", "pharmacology"],
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }
def main():
    parser = argparse.ArgumentParser(description="Literature Agent - Chain Entry")
    parser.add_argument("--input-json", required=True, help="JSON input string")
    args = parser.parse_args()
    try:
        input_data = json.loads(args.input_json)
    except json.JSONDecodeError as e:
        print(json.dumps({"agent": "literature", "status": "error", "error": f"Invalid JSON: {e}"}))
        sys.exit(1)
    result = chain_run(input_data)
    print(json.dumps(result, indent=2))
if __name__ == "__main__":
    main()

import os
import logging
from flask import Flask, jsonify, request
from sentence_transformers import SentenceTransformer
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
app = Flask(__name__)
MODEL_NAME = os.environ.get("EMBEDDING_MODEL", "intfloat/e5-large-v2")
EMBEDDING_PORT = int(os.environ.get("EMBEDDING_PORT", "8765"))
logger.info(f"Loading model: {MODEL_NAME}")
logger.info("NOTE: First run will download the model from HuggingFace (~1.3GB)")
model = SentenceTransformer(MODEL_NAME)
logger.info(f"Model loaded successfully. Embedding dimension: {model.get_sentence_embedding_dimension()}")
@app.route("/health", methods=["GET"])
def health():
    return jsonify({
        "status": "ok",
        "model": MODEL_NAME,
        "embedding_dim": model.get_sentence_embedding_dimension()
    })
@app.route("/embed", methods=["POST"])
def embed():
    try:
        data = request.get_json()
        if not data or "texts" not in data:
            return jsonify({"error": "Missing 'texts' field"}), 400
        texts = data["texts"]
        if not isinstance(texts, list):
            return jsonify({"error": "'texts' must be a list"}), 400
        prefix = data.get("prefix", "passage: ")
        prefixed_texts = [f"{prefix}{text}" for text in texts]
        embeddings = model.encode(prefixed_texts, normalize_embeddings=True)
        return jsonify({
            "embeddings": embeddings.tolist(),
            "model": MODEL_NAME,
            "dimension": model.get_sentence_embedding_dimension()
        })
    except Exception as e:
        logger.error(f"Error generating embeddings: {e}")
        return jsonify({"error": str(e)}), 500
@app.route("/embed_query", methods=["POST"])
def embed_query():
    try:
        data = request.get_json()
        if not data or "query" not in data:
            return jsonify({"error": "Missing 'query' field"}), 400
        query = data["query"]
        prefixed_query = f"query: {query}"
        embedding = model.encode([prefixed_query], normalize_embeddings=True)
        return jsonify({
            "embedding": embedding[0].tolist(),
            "model": MODEL_NAME,
            "dimension": model.get_sentence_embedding_dimension()
        })
    except Exception as e:
        logger.error(f"Error generating query embedding: {e}")
        return jsonify({"error": str(e)}), 500
if __name__ == "__main__":
    logger.info(f"Starting embedding service on port {EMBEDDING_PORT}")
    app.run(host="127.0.0.1", port=EMBEDDING_PORT, debug=False)

