import sys
import importlib.resources
from typing import Optional
import click
from rich import print as rprint
# ----------------------------------------------------------------------
# Dynamically determine PDD_PATH at runtime.
# ----------------------------------------------------------------------
def get_local_pdd_path() -> str:
    """
    Return the PDD_PATH directory.
    First check the environment variable. If not set, attempt to
    deduce it via importlib.resources. If that fails, abort.
    """
    if "PDD_PATH" in os.environ:
        return os.environ["PDD_PATH"]
    else:
        try:
            p = importlib.resources.files("pdd").joinpath("cli.py")
            fallback_path = str(p.parent)
            # Also set it back into the environment for consistency
            os.environ["PDD_PATH"] = fallback_path
            return fallback_path
        except ImportError:
            rprint(
                "[red]Error: Could not determine the path to the 'pdd' package. "
                "Please set the PDD_PATH environment variable manually.[/red]"
            )
            sys.exit(1)
# ----------------------------------------------------------------------
# Simplified shell RC path logic
# ----------------------------------------------------------------------
def get_shell_rc_path(shell: str) -> Optional[str]:
    """Return the default RC file path for a given shell name."""
    home = os.path.expanduser("~")
    if shell == "bash":
        return os.path.join(home, ".bashrc")
    elif shell == "zsh":
        return os.path.join(home, ".zshrc")
    elif shell == "fish":
        return os.path.join(home, ".config", "fish", "config.fish")
    return None
def get_current_shell() -> Optional[str]:
    """Determine the currently running shell more reliably."""
    if not os.environ.get('PYTEST_CURRENT_TEST'):
        # Method 1: Check process name using 'ps'
        try:
            import subprocess
            result = subprocess.run(['ps', '-p', str(os.getppid()), '-o', 'comm='], 
                                capture_output=True, text=True)
            if result.returncode == 0:
                # Strip whitespace and get basename without path
                shell = os.path.basename(result.stdout.strip())
                # Remove leading dash if present (login shell)
                return shell.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass
        # Method 2: Check $0 special parameter
        try:
            result = subprocess.run(['sh', '-c', 'echo "$0"'], 
                                capture_output=True, text=True)
            if result.returncode == 0:
                shell = os.path.basename(result.stdout.strip())
                return shell.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass
    # Fallback to SHELL env var if all else fails
    return os.path.basename(os.environ.get("SHELL", ""))
def get_completion_script_extension(shell: str) -> str:
    """Get the appropriate file extension for shell completion scripts."""
    mapping = {
        "bash": "sh",
        "zsh": "zsh",
        "fish": "fish"
    }
    return mapping.get(shell, shell)
def install_completion(quiet: bool = False):
    """
    Install shell completion for the PDD CLI by detecting the user's shell,
    copying the relevant completion script, and appending a source command
    to the user's shell RC file if not already present.
    """
    shell = get_current_shell()
    rc_file = get_shell_rc_path(shell)
    if not rc_file:
        if not quiet:
            rprint(f"[red]Unsupported shell: {shell}[/red]")
        raise click.Abort()
    ext = get_completion_script_extension(shell)
    # Dynamically look up the local path at runtime:
    local_pdd_path = get_local_pdd_path()
    completion_script_path = os.path.join(local_pdd_path, f"pdd_completion.{ext}")
    if not os.path.exists(completion_script_path):
        if not quiet:
            rprint(f"[red]Completion script not found: {completion_script_path}[/red]")
        raise click.Abort()
    source_command = f"source {completion_script_path}"
    try:
        # Ensure the RC file exists (create if missing).
        if not os.path.exists(rc_file):
            # Create parent directories if they don't exist
            rc_dir = os.path.dirname(rc_file)
            if rc_dir: # Ensure rc_dir is not an empty string (e.g. if rc_file is in current dir)
                 os.makedirs(rc_dir, exist_ok=True)
            with open(rc_file, "w", encoding="utf-8") as cf:
                cf.write("") # Create an empty file
        # Read existing content
        with open(rc_file, "r", encoding="utf-8") as cf:
            content = cf.read()
        if source_command not in content:
            with open(rc_file, "a", encoding="utf-8") as rf:
                rf.write(f"\n# PDD CLI completion\n{source_command}\n")

            if not quiet:
                rprint(f"[green]Shell completion installed for {shell}.[/green]")
                rprint(f"Please restart your shell or run 'source {rc_file}' to enable completion.")
        else:
            if not quiet:
                rprint(f"[yellow]Shell completion already installed for {shell}.[/yellow]")
    except OSError as exc:
        if not quiet:
            rprint(f"[red]Failed to install shell completion: {exc}[/red]")
        raise click.Abort()

from .kernel_jb_base import ARM64_OP_IMM, asm
class KernelJBPatchSecureRootMixin:
    def patch_io_secure_bsd_root(self):
        """Skip security check in _IOSecureBSDRoot.
        Prefer symbol. On stripped kernels, resolve a function that references both
        "SecureRoot" and "SecureRootName" and patch a strict policy branch site.
        """
        self._log("\n[JB] _IOSecureBSDRoot: skip check")
        # Try symbol first
        foff = self._resolve_symbol("_IOSecureBSDRoot")
        if foff < 0:
            foff = self._find_secure_root_function()
        if foff < 0:
            self._log("  [-] function not found")
            return False
        func_end = self._find_func_end(foff, 0x1200)
        site = self._find_secure_root_branch_site(foff, func_end)
        if not site:
            self._log("  [-] secure-root policy branch not found")
            return False
        off, target = site
        b_bytes = self._compile_branch_checked(off, target)
        self.emit(off, b_bytes, f"b #0x{target - off:X} [_IOSecureBSDRoot]")
        return True
    def _find_secure_root_function(self):
        funcs_with_name = self._functions_referencing_string(b"SecureRootName")
        if not funcs_with_name:
            return -1
        funcs_with_root = self._functions_referencing_string(b"SecureRoot")
        common = funcs_with_name & funcs_with_root
        if not common:
            # Fail closed: a plain SecureRootName-only function is often setup/epilogue code.
            return -1
        # Deterministic pick: lowest function offset among common candidates.
        return min(common)
    def _functions_referencing_string(self, needle):
        func_starts = set()
        for str_off in self._all_cstring_offsets(needle):
            refs = self.find_string_refs(str_off, *self.kern_text)
            for adrp_off, _, _ in refs:
                fn = self.find_function_start(adrp_off)
                if fn >= 0:
                    func_starts.add(fn)
        return func_starts
    def _all_cstring_offsets(self, needle):
        if isinstance(needle, str):
            needle = needle.encode()
        out = []
        start = 0
        while True:
            pos = self.raw.find(needle, start)
            if pos < 0:
                break
            cstr = pos
            while cstr > 0 and self.raw[cstr - 1] != 0:
                cstr -= 1
            cend = self.raw.find(b"\x00", cstr)
            if cend > cstr and self.raw[cstr:cend] == needle:
                out.append(cstr)
            start = pos + 1
        return sorted(set(out))
    def _find_secure_root_branch_site(self, func_start, func_end):
        # Strict selection:
        #  - forward conditional branch
        #  - on w0
        #  - immediately after BL (typical compare/callback check)
        #  - not in epilogue guard area (AUTIBSP/TBZ+BRK integrity checks)
        for off in range(func_start, func_end - 4, 4):
            d = self._disas_at(off)
            if not d:
                continue
            i = d[0]
            if i.mnemonic not in ("cbnz", "cbz"):
                continue
            if not i.op_str.replace(" ", "").startswith("w0,"):
                continue
            prev = self._disas_at(off - 4)
            if not prev or not prev[0].mnemonic.startswith("bl"):
                continue
            target = None
            for op in reversed(i.operands):
                if op.type == ARM64_OP_IMM:
                    target = op.imm
                    break
            if not target or not (off < target < func_end):
                continue
            if self._looks_like_epilogue_guard(off, target, func_end):
                continue
            return (off, target)
        return None
    def _looks_like_epilogue_guard(self, off, target, func_end):
        if off >= func_end - 0x40 or target >= func_end - 0x20:
            return True
        for probe in range(max(target - 4, 0), min(target + 0x14, func_end), 4):
            d = self._disas_at(probe)
            if d and d[0].mnemonic == "brk":
                return True
        for probe in range(max(off - 0x10, 0), off + 4, 4):
            d = self._disas_at(probe)
            if d and d[0].mnemonic == "autibsp":
                return True
        return False
    def _compile_branch_checked(self, off, target):
        delta = target - off
        b_bytes = asm(f"b #{delta}")
        insns = self._disas_n(b_bytes, 0, 1)
        assert insns, "capstone decode failed for secure-root branch patch"
        ins = insns[0]
        assert ins.mnemonic == "b", (
            f"secure-root branch decode mismatch: expected 'b', got '{ins.mnemonic}'"
        )
        got_target = None
        for op in reversed(ins.operands):
            if op.type == ARM64_OP_IMM:
                got_target = op.imm
                break
        assert got_target == delta, (
            "secure-root branch target mismatch: "
            f"expected delta 0x{delta:X}, got 0x{(got_target or -1):X}"
        )
        return b_bytes

