        return res
    def get_open_orders(self, symbol: str = None) -> list:
        return [
            self.parse_order_response(o) for o in self.calls.get_open_orders()
        ]
    def get_order(self, symbol: str, order_id: int) -> FuturesOrder:
        response = self.calls.get_order_by_id(str(order_id))
        symbol = self.to_exchange_symbol(symbol)
        if response['symbol'] != symbol:
            raise Exception(
                'response symbol did not match parameter -- this should never happen'
            )
        return self.parse_order_response(response)
    def get_price(self, symbol: str) -> float:
        symbol = self.to_exchange_symbol(symbol)
        return float(self.calls.get_future(symbol)['mark'])
    def get_funding_rate_history(self, symbol: str, epoch_start: int,
                                 epoch_stop: int) -> list:
        symbol = self.to_exchange_symbol(symbol)
        # TODO dedup binance_futures_exchange maybe?
        history = []
        resolution = self.get_funding_rate_resolution()
        limit = 500
        window_start = epoch_start
        window_end = epoch_start + limit * resolution
        response = True
        while response:
            response = self.calls.get_funding_rates(window_start, window_end,
                                                    symbol)
            history.extend({
                               'rate': float(e['rate']),
                               'time': self.parse_timestamp(e['time'])
                           } for e in response)
            if response:
                window_start = window_end
                window_end = min(epoch_stop, window_start + limit * resolution)
        return sorted(history, key=operator.itemgetter('time'))
    def get_funding_rate_resolution(self) -> int:
        return time_builder.build_hour()
    def get_product_history(self, symbol, epoch_start, epoch_stop, resolution):
        return FTXInterface.ftx_product_history(self.calls,self.to_exchange_symbol(symbol), epoch_start, epoch_stop, resolution)
    def get_maker_fee(self) -> float:
        raise NotImplementedError
    def get_taker_fee(self) -> float:
        raise NotImplementedError
    def get_funding_rate(self, symbol: str) -> float:
        raise NotImplementedError

from primus.core.patches import PatchContext, get_param, register_patch
from primus.modules.module_utils import log_rank_0
@register_patch(
    "torchtitan.embedding.amp_alignment",
    backend="torchtitan",
    phase="setup",
    description="Align nn.Embedding outputs with AMP/autocast dtype",
    condition=lambda ctx: get_param(ctx, "primus_turbo.enable_embedding_autocast", False),
)
def patch_torchtitan_embedding_amp(ctx: PatchContext) -> None:
    """
    Monkey patch for AMP precision mismatch in nn.Embedding.
    """
    import torch
    import torch.nn as nn
    log_rank_0(
        "[Patch:torchtitan.embedding.amp_alignment] "
        "Installing nn.Embedding AMP/mixed precision alignment patch...",
    )
    def _hook(module, inp, out):
        if not isinstance(out, torch.Tensor) or not out.is_floating_point():
            return out
        if torch.is_autocast_enabled():
            runtime_dtype = torch.get_autocast_gpu_dtype()
            if out.dtype != runtime_dtype:
                return out.to(runtime_dtype)
        return out
    orig_init = nn.Embedding.__init__
    def new_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        self.register_forward_hook(_hook)
    nn.Embedding.__init__ = new_init
    log_rank_0(
        "[Patch:torchtitan.embedding.amp_alignment] "
        "nn.Embedding.__init__ patched for AMP/mixed precision alignment.",
    )

