import psutil
import logging
import threading
from typing import Optional
logger = logging.getLogger("api.utils.fd_guard")
class FDGuard:
    """
    Utility to monitor and protect against File Descriptor (FD) leaks.
    Logs warnings if the current process exceeds a specific threshold of open handles.
    """

    _process = psutil.Process()
    _lock = threading.Lock()
    _warning_threshold = 50  # Per-request context limit (theoretical)
    _critical_threshold = 800 # Process-wide limit (standard soft limit is often 1024)
    @classmethod
    def get_open_fd_count(cls) -> int:
        """Returns the number of open file descriptors for the current process."""
        try:
            return cls._process.num_fds()
        except (psutil.AccessDenied, AttributeError):
            # Fallback for systems where num_fds() might not be available or restricted
            return -1
    @classmethod
    def check_fd_usage(cls, context_name: str = "request"):
        """
        Checks current FD usage and logs a warning if it exceeds thresholds.
        Call this at the beginning or end of heavy I/O operations.
        """
        count = cls.get_open_fd_count()
        if count == -1:
            return
        if count > cls._critical_threshold:
            logger.critical(
                f"[FD_GUARD] CRITICAL: Process-wide File Descriptors at {count}. "
                f"Approaching system limit! Context: {context_name}"
            )
        elif count > 500: # Global warning
             logger.warning(
                f"[FD_GUARD] WARNING: High File Descriptor usage detected ({count}). "
                f"Context: {context_name}"
            )
    @classmethod
    def log_leak_warning(cls, filename: str, count: int):
        """Specifically logs a suspected leak for a file."""
        logger.warning(
            f"[FD_GUARD] SUSPECTED LEAK: File '{filename}' was not closed properly. "
            f"Current process FD count: {count}"
        )
# Global helper for middleware or decorators
def monitor_fd_usage(func):
    """Decorator to monitor FD usage around a function."""
    import functools
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        FDGuard.check_fd_usage(f"before_{func.__name__}")
        try:
            return await func(*args, **kwargs)
        finally:
            FDGuard.check_fd_usage(f"after_{func.__name__}")
    return wrapper

from contextvars import ContextVar
REQ_CTX = ContextVar("request_ctx", default=None)
def get_req_ctx(key, default=None):
    ctx = REQ_CTX.get()
    return ctx[key] if ctx and key in ctx else default
def update_req_ctx(**kwargs):
    ctx = REQ_CTX.get()
    if ctx is not None:
        ctx.update(kwargs)
@contextmanager
def set_req_ctx(data):
    token = REQ_CTX.set(data)
    try:
        yield
    finally:
        REQ_CTX.reset(token)

import copy
import json
import os
import time
import uuid
from concurrent.futures import ThreadPoolExecutor
from typing import Dict, List, Optional, Union
import requests
from common.uc_eval.utils.data_class import (
    ModelConfig,
    MultiTurnDialogRecord,
    RequestRecord,
)
from common.uc_eval.utils.utils import PathUtil, get_logger
from tqdm import tqdm
from transformers import AutoTokenizer, PreTrainedTokenizer
from typing_extensions import override
logger = get_logger()
TIMEOUT = 6000
HEADERS = {"User-Agent": "Benchmark Client", "Content-Type": "application/json"}
CHUNK_SIZE = 2**16
def _excute_with_pool(
    task_func: callable,
    process_func: callable,
    tasks: List,
    parallel_num: int,
    desc: str = "Processing Requests",
) -> List[RequestRecord | MultiTurnDialogRecord]:
    record_results: List[RequestRecord | MultiTurnDialogRecord] = []
    if parallel_num > len(tasks):
        logger.error(
            f"The number of requests: {len(tasks)} is less than parallel_num: {parallel_num}, please check..."
        )
        raise ValueError(
            f"The number of requests: {len(tasks)} is less than parallel_num: {parallel_num}, please check..."
        )
    logger.info(f"Start to send {len(tasks)} requests to server...")
    with ThreadPoolExecutor(max_workers=parallel_num) as executor:
        futures = [executor.submit(task_func, task) for task in tasks]
        with tqdm(total=len(futures), desc=desc, mininterval=0.5) as pbar:
            for future in concurrent.futures.as_completed(futures):
                try:
                    pbar.update(1)
                    result = process_func(future.result())
                    record_results.append(result)
                    pbar.set_postfix(
                        {
                            "Completed": len(record_results),
                            "Pending": len(futures) - pbar.n,
                        }
                    )
                except Exception as e:
                    pbar.update(1)
                    logger.error(f"Requested failed: {str(e)}")
                    raise Exception(f"Requested failed: {str(e)}")
        return record_results
class BaseClient:
    def __init__(
        self,
        config: ModelConfig,
        stream: bool = False,
        **kwargs,
    ):
        self.ip_ports = config.ip_ports
        self.url = f"http://{self.ip_ports}/v1/chat/completions"
        self.served_model_name = config.served_model_name
        tokenizer_path = PathUtil.get_datasets_dir_path(config.tokenizer_path)
        self.tokenizer: PreTrainedTokenizer = AutoTokenizer.from_pretrained(
            tokenizer_path
        )
        self.max_paralleml_num = kwargs.get("max_parallel_num", 10)
        self.session = self.create_session(self.max_paralleml_num)
        self.max_seq_length = config.max_seq_length
        self.payload = config.payload
        self.stream = stream
        if self.stream:
            self.payload.update(
                {"stream": True, "ignore_eos": True, "temperature": 0.0}
            )
    def create_session(self, max_parallel_num: int):
        session = requests.Session()
        adapter = requests.adapters.HTTPAdapter(
            pool_maxsize=max_parallel_num if max_parallel_num >= 10 else 10
        )
        session.mount("http://", adapter)
        session.mount("https://", adapter)
        return session
    def handle_requests_with_pool(
        self, prompt_list: List, parallel_num: int, max_tokens: int
    ) -> List[RequestRecord]:
        return _excute_with_pool(
            task_func=lambda prompt: self.send_request(prompt, max_tokens),
            process_func=self.update_request_record,
            tasks=prompt_list,
            parallel_num=parallel_num,
        )
    def send_request(self, prompt, max_tokens) -> List[RequestRecord]:
        """
        update payload and send request
        """
        payload = self._update_payload(prompt, max_tokens)
        record = self._create_record(prompt)
        if self.stream:
            record = self.do_stream_request(payload, record)
        else:
            record = self.do_request(payload, record)
        return record
    def _update_payload(self, prompt, max_tokens) -> Dict:
        """
        update request payload
        """
        payload = copy.deepcopy(self.payload)
        payload.update({"model": self.served_model_name})
        # If payload already has default max_tokens, the input max_tokens will be set to 0
        if max_tokens > 0:
            payload.update({"max_tokens": max_tokens})
        if isinstance(prompt, str):
            # If the length of input_ids is greater than max_seq_length, we need to split it
            input_ids = self.tokenizer.encode(prompt)
            if len(input_ids) > self.max_seq_length:
                input_ids = (
                    input_ids[: self.max_seq_length // 2]
                    + input_ids[-self.max_seq_length // 2 :]
                )
                prompt = self.tokenizer.decode(input_ids)
            message = [{"role": "user", "content": prompt}]
        if isinstance(prompt, list):
            # Multi-turn conversation - prompt already contains full message history.
            # No need to update messages as they are already properly formatted
            message = prompt
        payload.update({"messages": message})
        return payload
    def _create_record(self, prompt):
        # If the prompt is not a dict, it must be a list of dicts for multi-turn dialogue.
        if isinstance(prompt, str):
            record = RequestRecord(input_data=prompt)
        else:
            record = RequestRecord(input_data=str(prompt))
        return record
    def update_request_record(
        self, records: Union[RequestRecord, List[RequestRecord]]
    ) -> Union[RequestRecord, List[RequestRecord]]:
        """
        Get the number of input and output tokens for each request record
        """
        if not records:
            logger.warning("No records to update, please check...")
        if isinstance(records, RequestRecord):
            single_record = records
            records = [single_record]
        else:
            single_record = None
        for record in records:
            record.input_tokens = len(self.tokenizer.tokenize(record.input_data))
            record.output_tokens = len(self.tokenizer.tokenize(record.output_data))
            record.tbt_list = record.tbt_list[2:] if record.tbt_list else []
            record.tbt_latency = (
                sum(record.tbt_list) / record.output_tokens if record.tbt_list else 0
            )
        return records[0] if single_record is not None else records
    def _requset(self, payload):
        response = None
        try:
            response = self.session.post(
                self.url,
                headers=HEADERS,
                json=payload,
                timeout=TIMEOUT,
                stream=self.stream,
            )
            response.raise_for_status()
            return response
        except Exception as err:
            raise self._handle_request_error(err)
    def do_request(self, payload: Dict, record: RequestRecord) -> RequestRecord:
        record.start_time = time.time()
        response = self._requset(payload)
        result = json.loads(response.text)
        request_id = result.get("id", "request_id not found")
        output = self._get_message_from_response(result)
        record.request_id = request_id
        record.output_data = output
        record.is_success = True
        record.end_time = time.time()
        record.req_cost = record.end_time - record.start_time
        return record
    def _get_message_from_response(self, response) -> str:
        message = response.get("choices", [])[0].get("message", {})
        output = ""
        if message.get("content", "") is not None:
            output += message.get("content", "")
        elif message.get("reasoning_content", "") is not None:
            output += message.get("reasoning_content", "")
        return output
    def do_stream_request(self, payload: Dict, record: RequestRecord) -> RequestRecord:
        while True:
            all_chunks = []
            first_token = True
            last_chunk = None
            timeout_finish_reason = False
            cur_time = last_time = time.perf_counter()
            record.start_time = last_time
            with self.session.post(
                self.url, headers=HEADERS, json=payload, stream=self.stream
            ) as response:
                for chunk in response.iter_content(chunk_size=CHUNK_SIZE):
                    cur_time = time.perf_counter()
                    all_chunks.append(chunk)
                    if len(chunk.strip()) == 0:
                        continue
                    last_chunk = chunk
                    time_diff = cur_time - last_time
                    if first_token:
                        record.prefill_latency = time_diff
                        first_token = False
                    else:
                        record.tbt_list.append(time_diff)
                    last_time = cur_time
                    # Decode the chunk after removing the leading "data:" prefix
                    chunk_output = chunk[5:].strip().decode("utf-8")
                    # when the MindIE engine side timeout, it will return timeout information
                    if chunk.startswith(b"Engine callback timeout"):
                        self._print_request_info(
                            request_id=record.request_id,
                            chunk=chunk,
                            content=record.output_data,
                            all_chunks=all_chunks,
                            payload=payload,
                            msg="Engine callback timeout",
                        )
                        record.output_data = "TIMEOUT"
                        return record
                    if "[DONE]" in chunk_output:
                        logger.debug(f"Finished chunk: {chunk_output=}")
                        continue
                    output = self._get_message_from_stream_response(
                        json.loads(chunk_output)
                    )
                    if record.request_id == "":
                        record.request_id = json.loads(chunk_output).get(
                            "id", "request_id not found"
                        )
                    record.output_data += output
                    # when the uc-vllm request timeout, finish_reason == "length" and the final output is empty
                    finish_reason = (
                        json.loads(chunk_output)
                        .get("choices", [])[0]
                        .get("finish_reason", "")
                    )
                    if finish_reason == "length":
                        timeout_finish_reason = True
            # handle the last chunk
            if last_chunk.startswith(b"data:"):
                chunk_output = last_chunk[5:].strip().decode("utf-8")
            else:
                chunk_output = last_chunk.strip().strip().decode("utf-8").rstrip("\0")
            # while the last chunk meets the following conditions, the request is finished successfully
            if "[DONE]" in chunk_output:
                break
            else:
                self._print_request_info(
                    request_id=record.request_id,
                    chunk=chunk,
                    content=record.output_data,
                    all_chunks=all_chunks,
                    payload=payload,
                    msg="request failed, please retry!!!",
                )
                break
        # while the request is done, we need to check the content to see if the request is successful
        if record.output_data == "":
            if timeout_finish_reason:
                self._print_request_info(
                    request_id=record.request_id,
                    chunk=chunk,
                    content=record.output_data,
                    all_chunks=all_chunks,
                    payload=payload,
                    msg="vllm server scheduling timeout, please check",
                )
                return record
            else:
                self._print_request_info(
                    request_id=record.request_id,
                    chunk=chunk,
                    content=record.output_data,
                    all_chunks=all_chunks,
                    payload=payload,
                    msg="the request returned an empty message, which may be an unknown error on the engine side. Please check the specific reason!",
                )
                return record
        record.is_success = True
        record.end_time = time.perf_counter()
        record.req_cost = record.end_time - record.start_time
        logger.debug(f"{record.request_id} finished, cost: {record.req_cost:.2f}s")
        return record
    def _get_message_from_stream_response(self, response) -> str:
        message = response.get("choices", [])[0].get("delta", {})
        output = ""
        if message.get("content", "") is not None:
            output += message.get("content", "")
        elif message.get("reasoning_content", "") is not None:
            output += message.get("reasoning_content", "")
        return output
    def clear_hbm(self) -> bool:
        """
        The API is used to clear HBM. It is available only when the serving backend is VLLM.
        """
        os.environ["NO_PROXY"] = "127.0.0.1, localhost, local, .local"
        logger.info("Begin to clear HBM")
        headers = {"Content-Type": "application/json"}
        payload = {}
        url = f"http://{self.ip_ports}/reset_prefix_cache"
        try:
            response = requests.post(
                url, json=payload, headers=headers, timeout=TIMEOUT
            )
            response.raise_for_status()
        except Exception as err:
            raise self._handle_request_error(err)
        time.sleep(5)
        logger.info("Clear HBM success")
        return True
    def _handle_request_error(self, err: Exception) -> Exception:
        """
        Used to handle request errors
        """
        if isinstance(err, requests.exceptions.ConnectionError):
            logger.error(f"Cannot connect to {self.url}, please check your network")
            return ConnectionError(f"Cannot connect to {self.url}")
        elif isinstance(err, requests.exceptions.Timeout):
            logger.error("The request timed out, please check your server status")
            return TimeoutError(
                "The request timed out, please check your server status"
            )
        elif isinstance(err, requests.exceptions.HTTPError):
            status_code = err.response.status_code
            if status_code == 404:
                logger.error(
                    f"The requested resource does not exist, or the served model name is incorrect"
                )
            else:
                logger.error(f"HTTP error, status code: {status_code}")
            return Exception(f"HTTP error, status code: {status_code}, err: {err}")
        else:
            logger.error(f"Other error: {err}")
            return Exception(f"Other error: {err}")
    @staticmethod
    def _print_request_info(**kwargs):
        """print request info when the request is failed"""
        for key, value in kwargs.items():
            value = (
                json.dumps(value, ensure_ascii=False)
                if isinstance(value, dict)
                else value
            )
            logger.error(f"{key} => {value}")
class MultiDialogClient(BaseClient):
    def __init__(self, config: ModelConfig, stream: bool, **kwargs):
        super().__init__(config, stream, **kwargs)
        self.uuid = uuid.uuid4().hex
        self.enable_prefix_cache = kwargs.get("enable_prefix_cache", False)
        self.enable_clear_hbm = kwargs.get("enable_clear_hbm", False)
    @override
    def handle_requests_with_pool(
        self,
        cases: List[List[Union[str, Dict]]],
        parallel_num: int,
        max_tokens: int = -1,
    ) -> List[List[MultiTurnDialogRecord]]:
        return _excute_with_pool(
            task_func=lambda case: self._send_multi_request(case, max_tokens),
            process_func=self.update_request_record,
            tasks=cases,
            parallel_num=parallel_num,
        )
    def _send_multi_request(
        self, case: List[Union[str, Dict]], max_tokens: int = -1
    ) -> List[MultiTurnDialogRecord]:
        case_name, dialog = case
        history, conv_record = [], []
        conversion = dialog["conversations"]
        turns = self._convert_conversation_2_turns(conversion, 2)
        for i, turn in enumerate(turns):
            in_content, reply = turn[0]["value"], turn[1]["value"]
            # Update payload, then send request
            prompt = self._update_request_body(history, in_content)
            record: RequestRecord = self.send_request(prompt, max_tokens)
            record.case_name = case_name
            history = self._update_history(history, in_content, reply)
            if self.enable_clear_hbm:
                self.clear_hbm()
            multi_turn_record: MultiTurnDialogRecord = (
                self._update_multi_turn_request_record(record, len(turns), i)
            )
            conv_record.append(multi_turn_record)
        return conv_record
    def _update_multi_turn_request_record(
        self, record: RequestRecord, total_turns: int, turn_id: int
    ) -> MultiTurnDialogRecord:
        """
        Update multi-tuen dialogue request record
        """
        request_record = MultiTurnDialogRecord()
        request_record.__dict__.update(record.__dict__)
        request_record.total_turns = total_turns
        request_record.turn_id = turn_id
        return request_record
    @staticmethod
    def _convert_conversation_2_turns(conversion_list: list, chunk_size: int):
        """
        Convert conversation list to turns
        """
        if chunk_size < 0:
            raise ValueError(f"the chunk size {chunk_size} must be greater than 0")
        num_full_chunks = len(conversion_list) // chunk_size
        return [
            conversion_list[i * chunk_size : (i + 1) * chunk_size]
            for i in range(num_full_chunks)
        ]
    def _update_request_body(self, history: Optional[List[Dict]], in_content: str):
        """
        Multi turn dialogue request body
        """
        history = copy.deepcopy(history)
        if history and self.enable_prefix_cache:
            # To make sure the prefix cache is unique
            history[0]["content"] = f"uuid: [{self.uuid}]" + history[0]["content"]
        if history and not self.enable_prefix_cache:
            history[0]["content"] = (
                f"uuid: [{uuid.uuid4().hex}]" + history[0]["content"]
            )
        message = history + [{"role": "user", "content": in_content}]
        return message
    @staticmethod
    def _update_history(
        history: Optional[List[Dict]], in_content: str, out_content: str
    ) -> List[Dict]:
        """
        Update conversation history
        """
        history.append({"role": "user", "content": in_content})
        history.append({"role": "assistant", "content": out_content})
        return history
class DocQaClient(BaseClient):
    def __init__(self, config: ModelConfig, stream: bool, **kwargs):
        super().__init__(config, stream, **kwargs)
    @override
    def handle_requests_with_pool(
        self, cases: List[Union[str, str, str]], parallel_num: int, max_tokens: int = -1
    ) -> List[List[MultiTurnDialogRecord]]:
        return _excute_with_pool(
            task_func=lambda case: self.send_qa_request(case, max_tokens),
            process_func=self.update_request_record,
            tasks=cases,
            parallel_num=parallel_num,
        )
    def send_qa_request(
        self, case: Union[str, str, str, str], max_tokens: int = -1
    ) -> RequestRecord:
        case_name, prompt_list, question, answer = case
        all_record = RequestRecord()
        for i, prompt in enumerate(prompt_list):
            record: RequestRecord = self.send_request(prompt, max_tokens)
            if i == 0:
                all_record = record
                all_record.case_name = case_name
                all_record.question = question
                all_record.expected_output = answer
            if i == len(prompt_list) - 1:
                all_record.output_data = record.output_data
                all_record.output_tokens = record.output_tokens
        return all_record

import argparse
def parse_pytest_output(file_path):
    skipped_tests = {}
    skipped_count = 0
    with open(file_path, 'r') as file:
        for line in file:
            match = re.match(r'^SKIPPED \[(\d+)\] (tests/.*): (.*)$', line)
            if match:
                skipped_count += 1
                test_file, test_line, reason = match.groups()
                skipped_tests[reason] = skipped_tests.get(reason, []) + [(test_file, test_line)]
    for k,v in sorted(skipped_tests.items(), key=lambda x:len(x[1])):
        print(f"{len(v):4} skipped because: {k}")
    print("Number of skipped tests:", skipped_count)
def parse_pytest_failure_output(file_path):
    failed_tests = {}
    failed_count = 0
    with open(file_path, 'r') as file:
        for line in file:
            match = re.match(r'^FAILED (tests/.*) - (.*): (.*)$', line)
            if match:
                failed_count += 1
                _, error, reason = match.groups()
                failed_tests[reason] = failed_tests.get(reason, []) + [error]
    for k,v in sorted(failed_tests.items(), key=lambda x:len(x[1])):
        print(f"{len(v):4} failed because `{v[0]}` -> {k}")
    print("Number of failed tests:", failed_count)
    if failed_count>0:
        exit(1)
def parse_pytest_errors_output(file_path):
    print(file_path)
    error_tests = {}
    error_count = 0
    with open(file_path, 'r') as file:
        for line in file:
            match = re.match(r'^ERROR (tests/.*) - (.*): (.*)$', line)
            if match:
                error_count += 1
                _, test_error, reason = match.groups()
                error_tests[reason] = error_tests.get(reason, []) + [test_error]
    for k,v in sorted(error_tests.items(), key=lambda x:len(x[1])):
        print(f"{len(v):4} errored out because of `{v[0]}` -> {k}")
    print("Number of errors:", error_count)
    if error_count>0:
        exit(1)
def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--file", help="file to parse")
    parser.add_argument("--skip", action="store_true", help="show skipped reasons")
    parser.add_argument("--fail", action="store_true", help="show failed tests")
    parser.add_argument("--errors", action="store_true", help="show failed tests")
    args = parser.parse_args()
    if args.skip:
        parse_pytest_output(args.file)
    if args.fail:
        parse_pytest_failure_output(args.file)
    if args.errors:
        parse_pytest_errors_output(args.file)
if __name__ == "__main__":
    main()

from typing import Iterable, Iterator
from flax import nnx
class JaxModule(nnx.Module):
    """Base module for JAX layers, extending flax.nnx.Module.
    """
    def _get_name(self) -> str:
        return self.__class__.__name__
    def named_parameters(self,
                         prefix: str = "",
                         recurse=True) -> Iterator[tuple[str, nnx.Param]]:
        """Yields the named parameters of the module.

        Arguments:
            prefix: Prefix to add to the parameter names.
            recurse: If True, then yields parameters of this module and all submodules.
                Otherwise, yields only parameters that are direct members of this module.
        Yields:
            (string, Param): Tuple containing a name and parameter
        """
        for name, param in self.__dict__.items():
            if isinstance(param, nnx.Param):
                yield (f"{prefix}.{name}" if prefix else name), param
        if not recurse:
            return
        for name, child in self.named_children():
            child_prefix = f"{prefix}.{name}" if prefix else name
            yield from child.named_parameters(prefix=child_prefix,
                                              recurse=True)
    def named_children(
            self) -> Iterator[tuple[str, "JaxModule | JaxModuleList"]]:
        """Returns an iterator over immediate children modules.

        Yields:
            (string, Module | list): Tuple containing a name and child module
        """
        for name, value in self.__dict__.items():
            if isinstance(value, JaxModule):
                yield name, value
            elif isinstance(value, list) or isinstance(value, nnx.List):
                yield name, JaxModuleList(value)
class JaxModuleList(nnx.List):
    """A list container for JaxModule objects."""
    def __init__(self, modules: Iterable[JaxModule]):
        """Initializes the JaxModuleList.
        Args:
            modules: An optional list of JaxModule objects to initialize the list.
        """
        super().__init__()
        for module in modules:
            self.append(module)
    def _get_name(self) -> str:
        return self.__class__.__name__
    def named_parameters(self,
                         prefix: str = "",
                         recurse=True) -> Iterator[tuple[str, nnx.Param]]:
        """Yields the named parameters of all modules in the list."""
        for idx, module in enumerate(self):
            module_prefix = f"{prefix}.{idx}" if prefix else str(idx)
            yield from module.named_parameters(prefix=module_prefix,
                                               recurse=recurse)
    def named_children(
            self) -> Iterator[tuple[str, "JaxModule | JaxModuleList"]]:
        """Returns an iterator over the modules in the list with their indices as names.
        Yields:
            (string, JaxModule): Tuple containing the index as a string and the module
        """
        for idx, item in enumerate(self):
            if isinstance(item, JaxModule):
                yield str(idx), item
            elif isinstance(item, list):
                yield str(idx), JaxModuleList(item)

from graph_net.sample_pass.resumable_sample_pass_mixin import ResumableSamplePassMixin
from pathlib import Path
import os
import shutil
import tempfile
import ast
import inspect
import torch
from graph_net.imp_util import load_module
from graph_net.tensor_meta import TensorMeta
from graph_net.hash_util import get_sha256_hash
class AstGraphVariableRenamer(SamplePass, ResumableSamplePassMixin):
    def __init__(self, config):
        super().__init__(config)
        self.data_input_predicator = self._make_data_input_predicator(self.config)
        self.model_runnable_predicator = self._make_model_runnable_predicator(
            self.config
        )
    def _make_data_input_predicator(self, config):
        module = load_module(config["data_input_predicator_filepath"])
        cls = getattr(module, config["data_input_predicator_class_name"])
        return cls(config["data_input_predicator_config"])
    def _make_model_runnable_predicator(self, config):
        module = load_module(config["model_runnable_predicator_filepath"])
        cls = getattr(module, config["model_runnable_predicator_class_name"])
        return cls(config["model_runnable_predicator_config"])
    def declare_config(
        self,
        model_path_prefix: str,
        output_dir: str,
        device: str,
        resume: bool = False,
        try_run: bool = False,
        limits_handled_models: int = None,
        data_input_predicator_filepath: str = None,
        data_input_predicator_class_name: str = None,
        data_input_predicator_config: dict = None,
        model_runnable_predicator_filepath: str = None,
        model_runnable_predicator_class_name: str = None,
        model_runnable_predicator_config: dict = None,
    ):
        pass
    def __call__(self, rel_model_path: str):
        self.resumable_handle_sample(rel_model_path)
    def sample_handled(self, rel_model_path: str) -> bool:
        return self.naive_sample_handled(rel_model_path, search_file_name="model.py")
    def resume(self, rel_model_path: str):
        torch.cuda.empty_cache()
        dst_model_path = os.path.realpath(
            os.path.join(self.config["output_dir"], rel_model_path)
        )
        src_model_path = os.path.join(self.config["model_path_prefix"], rel_model_path)
        graph_module_class = load_class_from_file(
            os.path.join(src_model_path, "model.py"), class_name="GraphModule"
        )
        input_arg_names, weight_arg_names = self._get_input_and_weight_arg_names(
            graph_module_class, src_model_path
        )
        rename_map = self._create_rename_map(input_arg_names, weight_arg_names)
        with tempfile.TemporaryDirectory(prefix="graph_variable_renamer_") as temp_dir:
            temp_model_path = os.path.join(temp_dir, os.path.basename(dst_model_path))
            shutil.copytree(src_model_path, temp_model_path, dirs_exist_ok=True)
            self._update_model_py_file(
                temp_model_path, rename_map, input_arg_names, weight_arg_names
            )
            self._update_meta_file(temp_model_path, "weight_meta.py", rename_map)
            self._update_meta_file(temp_model_path, "input_meta.py", rename_map)
            if self.config["try_run"]:
                self._try_run(temp_model_path)
            shutil.copytree(temp_model_path, dst_model_path, dirs_exist_ok=True)
    def _get_input_and_weight_arg_names(self, graph_module, model_path):
        input_arg_names = []
        weight_arg_names = []
        sig = inspect.signature(graph_module.forward)
        for name, param in sig.parameters.items():
            if name == "self":
                continue
            is_not_data_input = not self.data_input_predicator(model_path, name)
            if is_not_data_input:
                weight_arg_names.append(name)
            else:
                input_arg_names.append(name)
        return input_arg_names, weight_arg_names
    def _create_rename_map(self, input_arg_names, weight_arg_names):
        rename_map = {}
        for idx, name in enumerate(input_arg_names):
            rename_map[name] = f"in_{idx}"
        for idx, name in enumerate(weight_arg_names):
            rename_map[name] = f"w_{idx}"
        return rename_map
    def _update_model_py_file(
        self, model_path, rename_map, input_arg_names, weight_arg_names
    ):
        model_file = Path(model_path) / "model.py"
        source = model_file.read_text(encoding="utf-8")
        tree = ast.parse(source)
        node = self._get_graph_module_ast(tree)
        graph_renamer = AstGraphRenamer(rename_map, input_arg_names, weight_arg_names)
        graph_renamer.visit(node)
        py_code = ast.unparse(tree)
        model_file.write_text(py_code, encoding="utf-8")
        file_hash = get_sha256_hash(py_code)
        (Path(model_path) / "graph_hash.txt").write_text(file_hash)
    def _get_graph_module_ast(self, tree):
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name == "GraphModule":
                return node
        return None
    def _update_meta_file(self, model_path, meta_filename, rename_map):
        meta_file = Path(model_path) / meta_filename
        tensor_metas = TensorMeta.unserialize_from_py_file(str(meta_file))
        for meta in tensor_metas:
            assert (
                meta.name in rename_map
            ), f"[Warning] {meta.name} in {meta_filename} not found in rename_map."
            if meta.original_name is None:
                meta.original_name = meta.name
            meta.name = rename_map[meta.name]
        py_code = "\n\n".join([meta.serialize_to_py_str() for meta in tensor_metas])
        meta_file.write_text(py_code)
    def _try_run(self, model_path):
        print(f"[AstGraphVariableRenamer] Try to run {model_path}")
        assert self.model_runnable_predicator(
            model_path
        ), f"{model_path} is not a runnable model"
def load_class_from_file(file_path: str, class_name: str):
    print(f"Load {class_name} from {file_path}")
    module = load_module(file_path, "unnamed_graph_module")
    model_class = getattr(module, class_name, None)
    return model_class
class AstGraphRenamer(ast.NodeTransformer):
    def __init__(self, rename_map, input_arg_names, weight_arg_names):
        self.rename_map = rename_map
        self.input_and_weight_arg_names = set(input_arg_names) | set(weight_arg_names)
        self.counters = {"tmp": 0}
        self.in_forward = False
    def visit_FunctionDef(self, node):
        if node.name != "forward":
            return node
        self.in_forward = True
        node.args.args = self._rename_function_args(node.args.args)
        node.body = self._rename_function_body(node.body)
        self.in_forward = False
        return node
    def _rename_function_args(self, args):
        new_function_args = []
        for arg in args:
            if arg.arg == "self":
                new_function_args.append(arg)
            else:
                new_function_args.append(self._create_renamed_arg(arg))
        return new_function_args
    def _create_renamed_arg(self, arg):
        if arg.arg in self.rename_map:
            return ast.arg(arg=self.rename_map[arg.arg], annotation=arg.annotation)
        return arg
    def _rename_function_body(self, body):
        new_function_body = []
        for stmt in body:
            stmt = self._remove_clear_stmt_of_args(stmt)
            if stmt:
                stmt = self.visit(stmt)
                new_function_body.append(stmt)
        return new_function_body
    def _remove_clear_stmt_of_args(self, stmt):
        # remove stmt like w_0 = None
        if self._is_assign_none(stmt):
            return self._clean_assign_none(stmt)
        # remove stmt like del w_0
        elif isinstance(stmt, ast.Delete):
            return self._clean_delete(stmt)
        else:
            pass
        return stmt
    def _is_assign_none(self, stmt):
        return (
            isinstance(stmt, ast.Assign)
            and isinstance(stmt.value, ast.Constant)
            and stmt.value.value is None
        )
    def _clean_assign_none(self, stmt):
        new_targets = [t for t in stmt.targets if not self._is_input_or_weight_var(t)]
        if not new_targets:
            return None
        stmt.targets = new_targets
        return stmt
    def _is_input_or_weight_var(self, target):
        return (
            isinstance(target, ast.Name)
            and target.id in self.input_and_weight_arg_names
        )
    def _clean_delete(self, stmt):
        new_targets = []
        for target in stmt.targets:
            kept = self._filter_delete_target(target)
            if kept:
                new_targets.append(kept)
        if not new_targets:
            return None
        stmt.targets = new_targets
        return stmt
    def _filter_delete_target(self, target):
        if isinstance(target, ast.Tuple):  # del (a, b)
            kept_elts = [e for e in target.elts if not self._is_input_or_weight_var(e)]
            return ast.Tuple(elts=kept_elts, ctx=ast.Del()) if kept_elts else None
        elif not self._is_input_or_weight_var(target):  # del a
            return target
        else:
            pass
        return None
    def visit_Assign(self, node):
        if not self.in_forward:
            return node
        self._register_new_local_variables(node.targets)
        self.generic_visit(node)
        return node
    def _register_new_local_variables(self, targets):
        for target in targets:
            for name in self._flatten_assignment_target(target):
                self._register_if_unknown(name)
    def _flatten_assignment_target(self, target):
        if isinstance(target, ast.Name):
            yield target.id
        elif isinstance(target, (ast.Tuple, ast.List)):
            for elt in target.elts:
                yield from self._flatten_assignment_target(elt)
        else:
            pass
    def _register_if_unknown(self, name):
        if name not in self.rename_map:
            new_name = f"tmp_{self.counters['tmp']}"
            self.counters["tmp"] += 1
            self.rename_map[name] = new_name
    def visit_Name(self, node):
        if not self.in_forward:
            return node
        if node.id in self.rename_map:
            return ast.Name(id=self.rename_map[node.id], ctx=node.ctx)
        return node

