from typing import List
import unittest


class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        # Check for empty board
        if not board:
            return False

        # Empty word is always found
        if word == "":
            return True

        # Convert word to list of characters
        letters = list(word)
        len_letters = len(letters)

        # Iterate through each cell in the board
        for row in range(len(board)):
            for col in range(len(board[0])):
                # Start DFS from this cell
                exists = self.depth_first_search(board, row, col,
                                                 len_letters, letters)
                if exists:
                    return True

        return False

    def depth_first_search(self,
                           board: List[List[str]],
                           row: int,
                           col: int,
                           len_letters: int,
                           letters: List[str],
                           index: int = 0
                           ) -> bool:
        # Get current letter and expected letter
        letter = board[row][col]
        letter_word = letters[index]

        # Check if letters match
        if letter == letter_word:
            # If we've found all letters, return True
            if len_letters - 1 == index:
                return True
            else:
                # Mark current cell as visited
                board[row][col] = '-'

                # Explore neighbors (left, right, up, down)
                # Left neighbor
                if col - 1 >= 0:
                    if self.depth_first_search(board, row, col - 1,
                                               len_letters, letters, index + 1):
                        return True

                # Right neighbor
                if col + 1 < len(board[0]):
                    if self.depth_first_search(board, row, col + 1,
                                               len_letters, letters, index + 1):
                        return True

                # Upper neighbor
                if row - 1 >= 0:
                    if self.depth_first_search(board, row - 1, col,
                                               len_letters, letters, index + 1):
                        return True

                # Lower neighbor
                if row + 1 < len(board):
                    if self.depth_first_search(board, row + 1, col,
                                               len_letters, letters, index + 1):
                        return True

                # Restore original letter (backtracking)
                board[row][col] = letter
        else:
            return False


class TestFindWord(unittest.TestCase):
    def setUp(self):
        self.sol = Solution()

    def test_find_words_4x4_True(self):
        board = [
            ['o', 'a', 'a', 'n'],
            ['e', 't', 'a', 'e'],
            ['i', 'h', 'k', 'r'],
            ['i', 'f', 'l', 'v']
        ]
        word = "oath"
        exists = self.sol.exist(board, word)
        self.assertTrue(exists)

    def test_find_words_3x4_True(self):
        board = [
            ['A', 'B', 'C', 'E'],
            ['S', 'F', 'C', 'S'],
            ['A', 'D', 'E', 'E']
        ]
        word = "ABCCED"
        exists = self.sol.exist(board, word)
        self.assertTrue(exists)

    def test_find_words_3x4_False(self):
        board = [
            ['A', 'B', 'C', 'E'],
            ['S', 'F', 'C', 'S'],
            ['A', 'D', 'E', 'E']
        ]
        word = "ABCB"
        exists = self.sol.exist(board, word)
        self.assertFalse(exists)


if __name__ == "__main__":
    unittest.main()

from bson import ObjectId
from ..warhammer.character import query_character

class ElementNotFoundError(Exception):
    pass

def set_edit_permissions(element, user_id, is_master_admin, shared_acc):
    # Set edit permissions based on ownership and admin status
    if element["owner_id"] != user_id and element["owner_id"] in shared_acc:
        element["can_edit"] = False
    else:
        if is_master_admin:
            element["can_edit"] = True
        else:
            element["can_edit"] = True if element["owner_id"] == user_id else False

    # Convert ObjectId to string for ID field
    element["id"] = str(element["_id"])

    # Return element without internal fields
    return {key: element[key] for key in element if key not in ["_id", "owner_id"]}

def all_allowed_owners_query(user_id, shared_acc):
    # Build MongoDB query for allowed owners
    if shared_acc:
        return {
            "$or": [
                {"owner_id": user_id},
                {"owner_id": "admin"},
                {"$and": [
                    {"shared": True}, 
                    {"$or": [{"owner_id": uid} for uid in shared_acc]}
                ]}
            ]
        }
    else:
        return {"$or": [{"owner_id": user_id}, {"owner_id": "admin"}]}

def create_element(user_id, element, is_master_admin, element_collection):
    # Create a copy of element with owner info
    element_with_owner = deepcopy(element)

    # Assign owner based on admin status
    if is_master_admin:
        element_with_owner["owner_id"] = "admin"
    else:
        element_with_owner["owner_id"] = user_id

    # Insert into database
    insert_result = element_collection.insert_one(element_with_owner)

    return {"id": str(insert_result.inserted_id)}

def get_element(user_id, element_id, is_master_admin, shared_acc, element_collection):
    # Find element by ID with ownership restrictions
    element = element_collection.find_one(
        {"$and": [
            {"_id": ObjectId(element_id)}, 
            all_allowed_owners_query(user_id, shared_acc)
        ]}
    )

    if not element:
        raise ElementNotFoundError

    # Set edit permissions
    if element["owner_id"] != user_id and element["owner_id"] in shared_acc:
        element["can_edit"] = False
    else:
        if is_master_admin:
            element["can_edit"] = True
        else:
            element["can_edit"] = True if element["owner_id"] == user_id else False

    return set_edit_permissions(element, user_id, is_master_admin, shared_acc)

def update_element(user_id, update_data, is_master_admin, element_collection):
    elem_id = ObjectId(update_data["id"])
    new_elem_data = deepcopy(update_data)
    del new_elem_data["id"]

    if new_elem_data:
        if is_master_admin:
            result = element_collection.update_one(
                {"$and": [{"_id": elem_id}, {"owner_id": "admin"}]}, 
                {"$set": new_elem_data}
            )
        else:
            result = element_collection.update_one(
                {"$and": [{"_id": elem_id}, {"owner_id": user_id}]}, 
                {"$set": new_elem_data}
            )

        if result.matched_count == 0:
            raise ElementNotFoundError

    return {"id": update_data["id"]}

def delete_element(user_id, element_id, is_master_admin, element_collection):
    if is_master_admin:
        result = element_collection.delete_one(
            {"$and": [{"_id": ObjectId(element_id)}, {"owner_id": "admin"}]}
        )
    else:
        result = element_collection.delete_one(
            {"$and": [{"_id": ObjectId(element_id)}, {"owner_id": user_id}]}
        )

    if result.deleted_count == 0:
        raise ElementNotFoundError

def list_elements(user_id, is_master_admin, shared_acc, element_collection):
    elements = element_collection.find(all_allowed_owners_query(user_id, shared_acc))
    list_of_elements = []

    for element in elements:
        list_of_elements.append(set_edit_permissions(element, user_id, is_master_admin, shared_acc))

    return list_of_elements

def get_character_resolved(character_id, user_id, is_master_admin, shared_acc, character_coll, item_prop_coll):
    owners_query = all_allowed_owners_query(user_id, shared_acc)
    character = query_character(character_id, owners_query, character_coll, item_prop_coll)

    if not character:
        raise ElementNotFoundError

    return set_edit_permissions(character, user_id, is_master_admin, shared_acc)

def get_generation_props(collection):
    generation_props = collection.find_one({"name": "generation_props"})

    if not generation_props:
        raise ElementNotFoundError

    return {key: generation_props[key] for key in generation_props if key not in ["_id", "name"]}

