# Core classes for structured access to CoreNLP JSON output
class Core:
    def __init__(self, json_dict, i=None, parent=None):
        self.data = json_dict
        self.i = i
        self.parent = parent

    @property
    def ents(self):
        return [
            CoreEnt(ent, parent=self)
            for sent in self.sentences
            for ent in sent.entitymentions
        ]

    @property
    def people(self):
        return [ent for ent in self.ents if ent.data.get('ner') == 'PERSON']


class CoreEnt(Core):
    pass


class CoreObj(Core):
    def __init__(self, json_dict, i=None, parent=None):
        self.data = json_dict
        self.i = i
        self.parent = parent

        # Parse sentences
        self.sentences = [
            CoreSent(sent, i=i, parent=self)
            for i, sent in enumerate(json_dict['sentences'])
        ]

        # Parse coreference chains
        self.corefs = [
            CoreCoref(coref, i=i, parent=self)
            for i, coref in enumerate(json_dict['corefs'])
        ]

        # Parse quotes
        self.quotes = [
            CoreQuote(quote, i=i, parent=parent)
            for i, quote in enumerate(json_dict['quotes'])
        ]


class CoreSent(Core):
    def __init__(self, json_dict, i=None, parent=None):
        self.data = json_dict
        self.i = i
        self.parent = parent

        # Set attributes directly from JSON dict
        for key, val in self.data.items():
            setattr(self, key, val)


class CoreCoref(Core):
    def __init__(self, json_dict, i=None, parent=None):
        self.data = json_dict
        self.i = i
        self.parent = parent


class CoreQuote(Core):
    def __init__(self, json_dict, i=None, parent=None):
        self.data = json_dict
        self.i = i
        self.parent = parent


class CoreDoc(Core):
    def __init__(self, json_l):
        self.data = json_l
        self.objs = [
            CoreObj(json_dict, i=i, parent=self)
            for i, json_dict in enumerate(self.data)
            if json_dict
        ]

    @property
    def sentences(self):
        return [
            sent
            for obj in self.objs
            for sent in obj.sentences
        ]


