# Parser module for web scraping and data extraction
from .base import Ordnance
from .browser_interactor import BrowserInteractor
from urllib.parse import urljoin
from typing import TypeVar, Generic, Optional, Callable, Dict, List
from bs4 import BeautifulSoup, PageElement
from io_map import IOMap


class Parser(IOMap):
    source: Optional[str]
    url: Optional[str]
    soup: Optional[BeautifulSoup]

    @classmethod
    def from_browser(cls, browser: BrowserInteractor):
        return cls(source=browser.current_source, url=browser.current_url)

    def __init__(self, source: Optional[str] = None, url: Optional[str] = None):
        self.url = url
        self.source = source
        self.load_soup()

    @property
    def name(self) -> str:
        return type(self).__name__

    @property
    def instruction(self) -> str:
        return f'parse {self.name}'

    def convert_url_to_absolute(self, url: str) -> str:
        if self.url is None:
            return url
        return urljoin(self.url, url)

    def load_soup(self) -> Optional[BeautifulSoup]:
        self.soup = BeautifulSoup(self.source, features='html.parser') if self.source is not None else None
        return self.soup

    def load_browser(self, browser: BrowserInteractor):
        self.source = browser.current_source
        self.url = browser.current_url
        self.load_soup()

    def parse(self, *args, **kwargs) -> Parser:
        return self

    def xpath_for_element(self, element: PageElement) -> str:
        xpath_components_reversed = []
        e = element
        while e.parent is not None:
            if e.name:
                index = 1
                for c in e.parent.children:
                    if c is e:
                        break
                    if c.name != e.name:
                        continue
                    index += 1
                xpath_components_reversed.append(f'{e.name}[{index}]')
            e = e.parent
        return '/'.join(reversed(xpath_components_reversed))

    def run(self, *args, **kwargs):
        self.parse(*args, **kwargs)


O = TypeVar(any)


class OrdnanceParser(Generic[O], Parser, Ordnance[O]):
    def run(self, *args, **kwargs):
        super().run(*args, **kwargs)
        return self.ordnance


class SeekParser(Generic[O], OrdnanceParser[O]):
    _instruction: str
    seeker: Callable[[BeautifulSoup, SeekParser, ...], Optional[O]]

    def __init__(
        self,
        instruction: str,
        seeker: Optional[Callable[[BeautifulSoup, SeekParser, ...], Optional[PageElement]]] = None,
        source: Optional[str] = None,
        url: Optional[str] = None,
        seek: Dict[str, any] = {}
    ):
        self._instruction = instruction
        self.seeker = seeker if seeker is not None else SoupSeeker(**seek)
        super().__init__(source=source, url=url)

    @property
    def instruction(self) -> str:
        return self._instruction

    def parse(self, *args, **kwargs):
        self.ordnance = self.seeker(self, *args, **kwargs)
        return self


class SoupElementParser(SeekParser[PageElement]):
    pass


class Seeker(IOMap):
    def __call__(self, parser: SeekParser, *args, **kwargs) -> Optional[PageElement]:
        return None


class SoupSeeker(Seeker):
    soup_args: List[any]
    soup_kwargs: Dict[str, any]

    def __init__(self, *args, **kwargs):
        self.soup_args = args
        self.soup_kwargs = kwargs

    def __call__(self, parser: SeekParser, *args, **kwargs):
        page_element = parser.soup.find(*self.soup_args, **self.soup_kwargs)
        return page_element


class SoupIndexSeeker(SoupSeeker):
    target_index: int

    def __init__(self, target_index: int, *args, **kwargs):
        self.target_index = target_index
        super().__init__(*args, **kwargs)

    def __call__(self, parser: SeekParser, *args, **kwargs):
        page_elements = parser.soup.find(*self.soup_args, **self.soup_kwargs)
        try:
            page_element = page_elements[self.target_index]
        except IndexError:
            page_element = None
        return page_element

import copy
from typing import Any, Iterable, List, Optional, Tuple, Union
import numpy as np
from sortedcontainers import SortedList
from .function import Function

class Specimen:
    def __init__(self, element: Any, wellness: Union[float, int]):
        self._element = copy.deepcopy(element)
        self._wellness = copy.deepcopy(wellness)

    @property
    def element(self) -> Any:
        return self._element

    @property
    def wellness(self) -> Union[float, int]:
        return self._wellness

    def __eq__(self, other: "Specimen"):
        if isinstance(other, Specimen):
            element_equals = self.element == other.element
            wellness_equals = self.wellness == other.wellness

            # Handle non-boolean equality results for element
            if not isinstance(element_equals, bool):
                try:
                    iter(element_equals)
                    element_equals = all(element_equals)
                except TypeError:
                    pass

            # Handle non-boolean equality results for wellness
            if not isinstance(wellness_equals, bool):
                try:
                    iter(wellness_equals)
                    wellness_equals = all(wellness_equals)
                except TypeError:
                    pass

            return element_equals and wellness_equals
        return False

    def __str__(self):
        return f"[{self.wellness}] {self.element}"

    def __repr__(self):
        return str(self)


class SpecimenGenerator:
    @staticmethod
    def __check_init_args(wellness_function: Function) -> Function:
        if not isinstance(wellness_function, Function):
            raise TypeError(
                "Expected argument wellness_function to be a Function, instead it is "
                f"{type(wellness_function)}."
            )
        return wellness_function

    @property
    def wellness_function(self):
        return self._wellness_function

    def __init__(self, wellness_function: Function):
        wellness_function = self.__check_init_args(wellness_function=wellness_function)
        self._wellness_function = wellness_function

    def get(self, element: Any) -> Specimen:
        return Specimen(element=element, wellness=self._wellness_function(element))

    def __call__(self, element) -> Specimen:
        return self.get(element)


class Population:
    @staticmethod
    def __check_init_args(
        wellness_function: Function,
        iterable: Optional[Iterable[Union[Any, Specimen]]],
        capacity: int,
        elitism: int,
    ) -> Tuple[SpecimenGenerator, List[Specimen], int, int]:
        if not isinstance(wellness_function, Function):
            raise TypeError(
                "Expected argument wellness_function to be a Function, instead it is "
                f"{type(wellness_function)}."
            )
        specimen_generator = SpecimenGenerator(wellness_function=wellness_function)

        # Check capacity before processing iterable
        if not isinstance(capacity, int):
            raise TypeError(
                "Expected argument capacity to be an int, instead it is "
                f"{type(capacity)}."
            )
        if capacity < 1:
            raise ValueError(
                "Expected argument capacity to be a positive integer, instead it is "
                f"{capacity}."
            )

        # Process iterable if provided
        if iterable is not None:
            try:
                iter(iterable)
            except TypeError:
                raise TypeError(
                    "Expected argument iterable to be an iterable or None, instead it "
                    f"is {type(iterable)}."
                )
            iterable = [
                x if isinstance(x, Specimen) else specimen_generator(x)
                for x in iterable
            ]
            if len(iterable) > capacity:
                iterable.sort(key=lambda x: -x.wellness)
                iterable = iterable[:capacity]

        # Check elitism
        if not isinstance(elitism, int):
            raise TypeError(
                "Expected argument elitism to be an int, instead it is "
                f"{type(elitism)}."
            )
        if elitism < 0:
            raise ValueError(
                "Expected argument elitism to be a non-negative integer, instead it is "
                f"{elitism}."
            )
        return specimen_generator, iterable, capacity, elitism

    def __init__(
        self,
        wellness_function: Function,
        iterable: Optional[Iterable[Union[Any, Specimen]]] = None,
        capacity: int = 10,
        elitism: int = 0,
    ):
        specimen_generator, iterable, capacity, elitism = self.__check_init_args(
            wellness_function=wellness_function,
            iterable=iterable,
            capacity=capacity,
            elitism=elitism,
        )
        self._specimen_generator = specimen_generator
        self._capacity = capacity
        self._elitism = elitism
        self.__content = SortedList(iterable=iterable, key=lambda x: -x.wellness)

    @property
    def wellness_function(self):
        return self._specimen_generator.wellness_function

    @property
    def specimen_generator(self):
        return self._specimen_generator

    @property
    def capacity(self):
        return self._capacity

    @property
    def elitism(self):
        return self._elitism

    def ban(self, x: Union[Any, Specimen]):
        if x is not None:
            self.__content.discard(
                x if isinstance(x, Specimen) else self.specimen_generator(x)
            )

    def cull(self, n_additional: int = 0):
        if not isinstance(n_additional, int):
            raise TypeError(
                "Expected argument n_additional to be an int, instead it is "
                f"{type(n_additional)}."
            )
        if n_additional < 0:
            raise ValueError(
                "Expected argument n_additional to be a non-negative integer, instead "
                f"it is {n_additional}."
            )

        n_to_remove_max = len(self) - self.elitism
        n_to_remove = len(self) - self.capacity + n_additional
        n_to_remove = min(n_to_remove, n_to_remove_max)

        if n_to_remove < len(self):
            for _ in range(n_to_remove):
                self.__content.pop()
        else:
            self.__content.clear()

    def pop(self, index: int = -1):
        if not isinstance(index, int):
            raise TypeError(
                f"Expected argument index to be an int, instead it is {type(index)}."
            )
        return (
            self.__content.pop(index)
            if len(self) > self.elitism
            else self.__content[index]
        )

    def append(self, specimen: Specimen):
        if not isinstance(specimen, Specimen):
            try:
                specimen = self.specimen_generator(specimen)
            except Exception as e:
                raise TypeError(
                    "Expected argument speciment to be a Specimen, instead it is "
                    f"{type(specimen)}. Or {e}. One of those."
                )
        self.__content.add(specimen)

    def add(self, specimen: Specimen, remove_before: bool = True):
        if not isinstance(remove_before, bool):
            raise TypeError(
                "Expected argument remove_before to be a bool, instead it is "
                f"{type(remove_before)}."
            )
        if remove_before:
            self.cull(n_additional=1)
        self.append(specimen=specimen)
        self.cull()

    def assimilate(self, specimina: Iterable[Specimen]):
        try:
            iter(specimina)
        except TypeError:
            raise TypeError(
                "Expected argument specimina to be an iterable, instead it is"
                f"{type(specimina)}."
            )
        for specimen in specimina:
            self.append(specimen)

    def invade(self, specimina: Iterable[Specimen], remove_before: bool = True):
        if not isinstance(remove_before, bool):
            raise TypeError(
                "Expected argument remove_before to be a bool, instead it is "
                f"{type(remove_before)}."
            )
        if remove_before:
            self.cull(len(specimina))
        self.assimilate(specimina)
        self.cull()

    def __getitem__(self, key: Union[int, Iterable]):
        try:
            return self.__content[int(key)]
        except Exception:
            try:
                iter(key)
                return np.array([self[x] for x in key])
            except TypeError:
                raise ValueError(
                    "Expected argument key to be an int or an iterable, instead it is "
                    f"{type(key)}."
                )

    def __len__(self):
        return len(self.__content)

    def __str__(self):
        to_return = f"Population ({len(self)} / {self.capacity})"
        if self.elitism != 0:
            to_return += f", elite: {self.elitism}"
        for specimen in self.__content:
            to_return += f"\n\t{specimen}"
        return to_return

# Ingest HRRR data from NOAA's GFS system
from datetime import datetime, timedelta
from typing import Optional
import argparse
import logging

from wx_explore.analysis.transformations import cartesian_to_polar
from wx_explore.common import metrics
from wx_explore.common.logging import init_sentry
from wx_explore.common.models import (
    Source,
    SourceField,
)
from wx_explore.common.utils import datetime2unix
from wx_explore.ingest.common import get_queue, get_or_create_projection
from wx_explore.ingest.grib import get_end_valid_time
from wx_explore.ingest.sources.source import IngestSource
from wx_explore.web.core import db

logger = logging.getLogger(__name__)


class HRRR(IngestSource):
    SOURCE_NAME = "hrrr"

    @staticmethod
    def generate_derived(grib):
        logger.info("Deriving wind")

        # Fetch wind speed and direction source fields
        speed_sf = SourceField.query.filter(
            SourceField.source.has(Source.short_name == HRRR.SOURCE_NAME),
            SourceField.metric == metrics.wind_speed,
        ).first()
        direction_sf = SourceField.query.filter(
            SourceField.source.has(Source.short_name == HRRR.SOURCE_NAME),
            SourceField.metric == metrics.wind_direction,
        ).first()

        if speed_sf is None or direction_sf is None:
            raise Exception("Unable to load wind speed and/or direction source fields")

        # XXX: switch to using group_by_time from analysis
        uv_pairs = zip(
            sorted(grib.select(name='10 metre U wind component', stepType='avg'), key=lambda m: (m.validDate, m.analDate)),
            sorted(grib.select(name='10 metre V wind component', stepType='avg'), key=lambda m: (m.validDate, m.analDate)),
        )

        logging.debug("Got uv_pairs")
        projection = None
        to_insert = {}

        for u, v in uv_pairs:
            speed, direction = cartesian_to_polar(u.values, v.values)
            logging.debug("Derived speed, direction")

            msg = u  # or v - this only matters for projection, valid/analysis dates, etc.
            valid_date = get_end_valid_time(msg)

            to_insert.update({
                (speed_sf.id, valid_date, msg.analDate): [speed],
                (direction_sf.id, valid_date, msg.analDate): [direction],
            })

            if projection is None:
                projection = get_or_create_projection(msg)

                if speed_sf.projection is None:
                    speed_sf.projection_id = projection.id
                elif speed_sf.projection != projection:
                    logger.error("Projection change in speed field")

                if direction_sf.projection is None:
                    direction_sf.projection_id = projection.id
                elif direction_sf.projection != projection:
                    logger.error("Projection change in direction field")

                db.session.commit()

        if projection is not None:
            return {
                projection: to_insert,
            }
        else:
            logger.warning("No U/V pairs ingested")
            return {}

    @staticmethod
    def queue(
            time_min: int = 0,
            time_max: int = 18,
            run_time: Optional[datetime] = None,
            acquire_time: Optional[datetime] = None
    ):
        if run_time is None:
            # hrrr is run each hour
            run_time = datetime.utcnow().replace(minute=0, second=0, microsecond=0)

        if acquire_time is None:
            # first files are available about 45 mins after
            acquire_time = run_time
            acquire_time += timedelta(minutes=45)

        base_url = run_time.strftime("https://nomads.ncep.noaa.gov/pub/data/nccf/com/hrrr/prod/hrrr.%Y%m%d/conus/hrrr.t%Hz.wrfsubhf{}.grib2")
        q = get_queue()

        for hr in range(time_min, time_max + 1):
            url = base_url.format(str(hr).zfill(2))
            q.put({
                "source": "hrrr",
                "valid_time": datetime2unix(run_time + timedelta(hours=hr)),
                "run_time": datetime2unix(run_time),
                "url": url,
                "idx_url": url + ".idx",
            }, schedule_at=acquire_time)


if __name__ == "__main__":
    init_sentry()
    logging.basicConfig(level=logging.INFO)

    parser = argparse.ArgumentParser(description='Ingest HRRR')
    parser.add_argument('--offset', type=int, default=0, help='Run offset to ingest')
    args = parser.parse_args()

    run_time = datetime.utcnow()
    run_time = run_time.replace(minute=0, second=0, microsecond=0)
    run_time -= timedelta(hours=args.offset)

    HRRR.queue(run_time=run_time)

# Import necessary modules
import subprocess;
import sys;

# Define search and reference parameters
SEARCH_X = "200";
SEARCH_Y = "200";
REF_X = "100";
REF_Y = "100";
STEP = "30";

# Get command line arguments
reference = sys.argv[1];
search = sys.argv[2];
nproc = sys.argv[3];

# Construct header file names
ref_hdr = reference[:reference.rfind(".")] + ".hdr";
search_hdr = search[:search.rfind(".")] + ".hdr";

# Extract reference image dimensions from header
ref_samples = "";
ref_lines = "";
infile = open(ref_hdr, "r");
for line in infile:
    if line.find("samples") > -1:
        elements = line.split();
        ref_samples = elements[len(elements) - 1].strip();
    if line.find("lines") > -1:
        elements = line.split();
        ref_lines = elements[len(elements) - 1].strip();
infile.close();

# Extract search image dimensions from header
search_samples = "";
search_lines = "";
infile = open(search_hdr, "r");
for line in infile:
    if line.find("samples") > -1:
        elements = line.split();
        search_samples = elements[len(elements) - 1].strip();
    if line.find("lines") > -1:
        elements = line.split();
        search_lines = elements[len(elements) - 1].strip();
infile.close();

# Run find_offset.py to get mean offsets
cmd = "\npython find_offset.py " + ref_hdr + " " + search_hdr + "\n";
pipe = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE).stdout;
output = pipe.read().strip().split();
pipe.close();

mean_x = output[4];
mean_y = output[5];

# Generate ampcor input files for each process
for i in range(1, int(nproc) + 1):
    lines_proc = int(ref_lines) // int(nproc) // int(REF_Y) * int(REF_Y);
    yoffset = 0;

    if int(mean_y) < 0:
        yoffset = -1 * int(mean_y);

    firstline = str((i - 1) * lines_proc + 1 + int(REF_Y) // 2 + yoffset);
    lastline = str(int(firstline) + lines_proc - 1);
    firstpix = "1";

    if int(mean_x) < 0:
        firstpix = str(1 - int(mean_x));

    # Write ampcor input file
    outfile = open("ampcor_aster_" + str(i) + ".in", "w");
    outfile.write("                  AMPCOR INPUT FILE\n");
    outfile.write("\n");
    outfile.write("DATA TYPE\n");
    outfile.write("\n");
    outfile.write("Data Type for Reference Image Real or Complex                   (-)    =  Real   ![Complex , Real]\n");
    outfile.write("Data Type for Search Image Real or Complex                      (-)    =  Real   ![Complex , Real]\n");
    outfile.write("\n");
    outfile.write("INPUT/OUTPUT FILES\n");
    outfile.write("\n");
    outfile.write("Reference Image Input File                                      (-)    =  " + reference + "\n");
    outfile.write("Search Image Input File                                         (-)    =  " + search + "\n");
    outfile.write("Match Output File                                               (-)    =  ampcor_aster_" + str(i) + ".off\n");
    outfile.write("\n");
    outfile.write("MATCH REGION\n");
    outfile.write("\n");
    outfile.write("Number of Samples in Reference/Search Images                    (-)    =  " + ref_samples + " " + search_samples + "\n");
    outfile.write("Start, End and Skip Lines in Reference Image                    (-)    =  " + firstline + " " + lastline + " " + STEP + "\n");
    outfile.write("Start, End and Skip Samples in Reference Image                  (-)    =  " + firstpix + " " + ref_samples + " " + STEP + "\n");
    outfile.write("\n");
    outfile.write("MATCH PARAMETERS\n");
    outfile.write("\n");
    outfile.write("Reference Window Size Samples/Lines                             (-)    = " + REF_X + " " + REF_Y + "\n");
    outfile.write("Search Pixels Samples/Lines                                     (-)    = " + SEARCH_X + " " + SEARCH_Y + "\n");
    outfile.write("Pixel Averaging Samples/Lines                                   (-)    =  1 1\n");
    outfile.write("Covariance Surface Oversample Factor and Window Size            (-)    =  64 16\n");
    outfile.write("Mean Offset Between Reference and Search Images Samples/Lines   (-)    =  " + mean_x + " " + mean_y + "\n");
    outfile.write("\n");
    outfile.write("MATCH THRESHOLDS AND DEBUG DATA\n");
    outfile.write("\n");
    outfile.write("SNR and Covariance Thresholds                                   (-)    =  0 10000000000\n");
    outfile.write("Debug and Display Flags T/F                                     (-)    =  f f\n");
    outfile.close();

exit();

import abc
import collections.abc
import typing as ta

from omnibus import check
from omnibus import collections as col
from omnibus import dataclasses as dc
from omnibus import properties
from omnibus.serde import mapping as sm


class QualifiedName(dc.Pure, ta.Sequence[str]):
    parts: ta.Sequence[str] = dc.field(coerce=col.seq)

    # Validation check for parts
    dc.check(lambda parts: (
            parts and
            all(parts) and
            all(isinstance(p, str) for p in parts)
    ))

    def __repr__(self) -> str:
        return 'QualifiedName([%s])' % (', '.join(map(repr, self.parts)),)

    @property
    def dotted(self) -> str:
        return '.'.join(self.parts)

    def prefixed(self, sz: int) -> ta.Sequence[ta.Optional[str]]:
        if len(self) > sz:
            raise ValueError(self)
        return ((None,) * (sz - len(self))) + tuple(self.parts)

    @property
    def pair(self) -> ta.Tuple[ta.Optional[str], str]:
        return self.prefixed(2)  # noqa

    @property
    def triple(self) -> ta.Tuple[ta.Optional[str], ta.Optional[str], str]:
        return self.prefixed(3)  # noqa

    @property
    def quad(self) -> ta.Tuple[ta.Optional[str], ta.Optional[str], ta.Optional[str], str]:
        return self.prefixed(4)  # noqa

    def __iter__(self) -> ta.Iterator[str]:
        return iter(self.parts)

    def __len__(self) -> int:
        return len(self.parts)

    def __getitem__(self, idx: int) -> str:
        return self.parts[idx]

    @classmethod
    def of_dotted(cls, dotted: str) -> 'QualifiedName':
        return cls(dotted.split('.'))

    @classmethod
    def of(cls, obj: ta.Union['QualifiedName', ta.Iterable[str]]) -> 'QualifiedName':
        if isinstance(obj, QualifiedName):
            return obj
        elif isinstance(obj, str):
            raise TypeError(obj)
        elif isinstance(obj, collections.abc.Iterable):
            return cls(list(obj))
        else:
            raise TypeError(obj)

    @classmethod
    def of_optional(cls, obj: ta.Union[None, 'QualifiedName', ta.Iterable[str]]) -> ta.Optional['QualifiedName']:
        if obj is None:
            return None
        else:
            return cls.of(obj)


class QualifiedNameSerde(sm.AutoSerde[QualifiedName]):
    def serialize(self, obj: QualifiedName) -> ta.Any:
        return list(check.isinstance(obj, QualifiedName).parts)

    def deserialize(self, ser: ta.Any) -> QualifiedName:
        return QualifiedName.of(ser)


class Code(dc.Enum):
    @abc.abstractproperty
    def fn(self) -> ta.Callable:
        raise NotImplementedError

    def __call__(self, *args, **kwargs):
        return self.fn(*args, **kwargs)


class Lambda(Code, allow_setattr=True):
    src: str = dc.field(check=lambda s: isinstance(s, str) and ':' in s)

    @properties.cached
    def fn(self) -> ta.Callable:
        return eval('lambda ' + self.src)


class LambdaSerde(sm.AutoSerde[Lambda]):
    def serialize(self, obj: Lambda) -> ta.Any:
        return sm.serialize_dataclass_fields(obj)

    def deserialize(self, ser: ta.Any) -> Lambda:
        if isinstance(ser, str):
            return Lambda(ser)
        return sm.deserialize_dataclass_fields(ser, Lambda)

# Type I clone - formatting changes with comments and whitespace adjustments
from __future__ import annotations

import typing as t

T = t.TypeVar("T")


def optional(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
) -> t.Optional[T]:
    """
    Get a value safely from the given dict using the given key.
    If the value is not found or is None, return it anyway.

    :raises: ValueError
    """
    # Determine value based on parser presence
    if parser is None:
        value = dict_.get(key)
    else:
        value = parser(dict_, key)

    # Validate type if value exists
    if value is not None and not isinstance(value, expect):
        raise ValueError(
            f"{dict_}: {repr(key)}: {repr(value)}: invalid type {type(value)}, expecting {expect}"
        )

    return t.cast(T, value)


def required(
    dict_: t.Dict[object, object],
    /,
    key: object,
    expect: t.Union[type, t.Tuple[type, ...]],
    *,
    parser: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
    default: t.Optional[T] = None,
    default_factory: t.Optional[t.Callable[[], T]] = None,
) -> T:
    """
    Get a value safely from the given dict using the given key.
    If the value is not found or is None, raise value error.

    :raises: ValueError
    """
    # First try to get optional value
    value: t.Optional[T] = optional(dict_, key, expect, parser=parser)

    # Handle missing value case
    if value is None:
        if default is not None:
            return default
        if default_factory is not None:
            return default_factory()
        raise ValueError(f"{dict_}: {repr(key)}: value is required")

    return value


def flatten_dict(d: t.Dict[t.Any, t.Any]) -> t.Dict[str, object]:
    """
    Flatten a nested dictionary.

    :param dist d: The nested dictionary to flatten.
    :rtype: dict

    :example:
    .. code-block:: python
        flatten_dict({"a": 1, "b": {"c": 2, "d": {"e": 3, "f": 4}}})
        # {
        #     "a": 1,
        #     "b:c": 2,
        #     "b:d:e": 3,
        #     "b:d:f": 4,
        # }
    """
    def items() -> t.Iterable[t.Tuple[str, object]]:
        for key, value in d.items():
            # Ensure key is string
            if not isinstance(key, str):
                raise ValueError(f"{key}: expected {str}, but got {type(key)}")

            # Recursively flatten nested dicts
            if isinstance(value, dict):
                for subkey, subvalue in flatten_dict(value).items():
                    # Ensure subkey is also string
                    if not isinstance(subkey, str):
                        raise ValueError(
                            f"{subkey}: expected {str}, but got {type(subkey)}"
                        )
                    yield key + ":" + subkey, subvalue
            else:
                yield key, value

    return dict(items())


def unflatten_dict(d: t.Dict[object, object]) -> t.Dict[object, object]:
    """
    Convert a flattened dict back to nested dict.

    :param dict d: The flattened dict to convert.
    :rtype: dict

    :example:
    .. code-block:: python
        unflatten_dict({"a": 1, "b:c": 2, "b:d:e": 3, "b:d:f": 4})
        # {
        #   "a": 1,
        #   "b": {"c": 2, "d": {"e": 3, "f": 4}},
        # }
    """
    dict_: t.Dict[object, object] = {}

    for k, v in d.items():
        # Ensure key is string
        if not isinstance(k, str):
            raise ValueError(f"{k}: expected {str}, but got {type(k)}")

        # Handle nested keys
        if ":" in k:
            _dict: t.Union[object, t.Dict[object, object]] = dict_
            fields = k.split(":")
            count = len(fields)

            for i in range(count):
                field = fields[i]

                # Skip if _dict is not a dict
                if not isinstance(_dict, dict):
                    continue

                # Create nested structure if needed
                if field not in _dict:
                    _dict[field] = v if i == (count - 1) else {}

                _dict = _dict[field]
        else:
            # Simple key-value assignment
            dict_[k] = v

    return dict_

