@enum.unique
class ImportErrors(Enum):
    same_line = 'AZUL101 more than one symbol imported per line'
    not_joined = 'AZUL102 symbols from the same module imported in separate statements'
    statement_not_ordered = 'AZUL111 import statements are not correctly ordered'
    symbol_not_ordered = 'AZUL112 symbols in from import are not correctly ordered'
    not_wrapped = 'AZUL131 from import lacks parentheses'
    missing_breaks = 'AZUL132 missing newline between parentheses and imported symbols'
    no_trailing_comma = 'AZUL133 symbol in from import lacks trailing comma'
    unresolvable = 'AZUL141 cannot resolve import statement from project root'


@enum.unique
class ModuleType(enum.IntEnum):
    # Values determine sorting order and correspond to the ordering defined in
    # the contributing guide.
    python_runtime = 1
    external_dependency = 2
    internal = 3

    @classmethod
    def from_module_name(cls, module_name: str) -> 'ModuleType':
        """
        Infer module origin by inspecting the spec from its resolved name.

        A builtin module:
        >>> ModuleType.from_module_name('sys')
        <ModuleType.python_runtime: 1>

        A non-builtin standard library module:
        >>> ModuleType.from_module_name('os')
        <ModuleType.python_runtime: 1>

        A downloaded external package:
        >>> ModuleType.from_module_name('boto3')
        <ModuleType.external_dependency: 2>

        A non-namespace internal module:
        >>> ModuleType.from_module_name('azul.indexer')
        <ModuleType.internal: 3>

        A non-namespace internal module outside the main src/ folder.
        The flake8-import-order plugin struggles with these:
        >>> ModuleType.from_module_name('azul_test_case')
        <ModuleType.internal: 3>

        A namespace internal module:
        >>> ModuleType.from_module_name('lambdas.service')
        <ModuleType.internal: 3>
        """
        spec = importlib.util.find_spec(module_name)
        if spec is None:
            raise ImportError
        elif spec.origin is None and spec.submodule_search_locations is None:
            # Not every module included in the Python standard library is
            # considered "builtin." That term is reserved for modules such as
            # `sys` that are implemented in C and lack an associated .py file.
            assert module_name in sys.builtin_module_names, module_name
            return cls.python_runtime
        else:
            if spec.origin is None:
                # Namespace modules lack an __init__.py and represent their
                # location as a list of directories.
                path = one(spec.submodule_search_locations)
            else:
                path = spec.origin
            if 'site-packages' in path:
                # Assuming dependencies are installed in a virtual environment.
                # More specific path test would fail in travis.
                return cls.external_dependency
            elif path.startswith(config.project_root):
                return cls.internal
            else:
                # Assume any non-builtin module imported from outside the
                # project is part of the standard library. Python installation
                # locations can vary.
                return cls.python_runtime


EitherImport = Union[ast.Import, ast.ImportFrom]


@attr.s(auto_attribs=True, kw_only=True, frozen=True, order=True)
class ModuleOrderInfo:
    module_type: ModuleType
    module_name: str
    is_from_import: bool

    @classmethod
    def normalize_module(cls, node: EitherImport) -> Tuple[str, bool]:
        if isinstance(node, ast.Import):
            module_name = one(node.names).name
            is_from_import = False
        elif isinstance(node, ast.ImportFrom):
            module_name = node.module
            is_from_import = True
        else:
            assert False, type(node)
        return module_name, is_from_import

    @classmethod
    def from_ast(cls, node: EitherImport) -> 'ModuleOrderInfo':
        """
        >>> def from_stmt(src): return ModuleOrderInfo.from_ast(one(ast.parse(src).body))
        >>> from_stmt('import azul.indexer, azul.service')
        Traceback (most recent call last):
        ...
        ValueError: too many items in iterable (expected 1)
        >>> from_stmt('import does_not_exist')
        Traceback (most recent call last):
        ...
        ImportError
        >>> from_stmt('import azul.indexer')
        ModuleOrderInfo(module_type=<ModuleType.internal: 3>, module_name='azul.indexer', is_from_import=False)
        >>> from_stmt('from azul.indexer import BaseIndexer')
        ModuleOrderInfo(module_type=<ModuleType.internal: 3>, module_name='azul.indexer', is_from_import=True)
        >>> from_stmt('import itertools')
        ModuleOrderInfo(module_type=<ModuleType.python_runtime: 1>, module_name='itertools', is_from_import=False)
        >>> from_stmt('from more_itertools import one') #doctest: +NORMALIZE_WHITESPACE
        ModuleOrderInfo(module_type=<ModuleType.external_dependency: 2>, \
                        module_name='more_itertools', \
                        is_from_import=True)
        """
        module_name, is_from_import = cls.normalize_module(node)
        module_type = ModuleType.from_module_name(module_name)
        return cls(
            module_type=module_type,
            module_name=module_name,
            is_from_import=is_from_import
        )


@attr.s(auto_attribs=True, kw_only=True, frozen=True)
class OrderedImport:
    node: EitherImport
    order_info: ModuleOrderInfo

    @classmethod
    def from_ast(cls, node: EitherImport) -> 'OrderedImport':
        return cls(node=node, order_info=ModuleOrderInfo.from_ast(node))

    def is_correct_order(self, other: 'OrderedImport') -> bool:
        return (self.node.lineno <= other.node.lineno) == (self.order_info <= other.order_info)


@attr.s(auto_attribs=True, kw_only=True, frozen=True)
class ErrorInfo:
    line: int
    column: int
    msg: str

    @classmethod
    def from_ast(cls, node: EitherImport, err: ImportErrors):
        return cls(
            line=node.lineno,
            column=node.col_offset,
            msg=err.value
        )

    def to_flake8_tuple(self) -> tuple:
        # flake8 requires a fourth attribute but it's not used
        return *attr.astuple(self), None


class ImportVisitor(ast.NodeVisitor):
    expected_resolution_failures = {
        'pydevd',
        # FIXME: Remove hacky import of SupportsLessThan
        #        https://github.com/DataBiosphere/azul/issues/2783
        '_typeshed'
    }

    def __init__(self, file_name: str, file_tokens: Iterable[TokenInfo]):
        super().__init__()
        self.file_name = file_name
        self.line_tokens = defaultdict(list)
        for token_info in file_tokens:
            self.line_tokens[token_info.start[0]].append(token_info)
        for line_tokens in self.line_tokens.values():
            line_tokens.sort(key=lambda token_info: token_info.start[1])
        self.errors: List[ErrorInfo] = []
        self.visited_order_info: List[OrderedImport] = []

    def visit_Import(self, node: ast.Import) -> None:
        self.check_split_import(node)
        self.check_statement_order(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        self.check_joined_import(node)
        self.check_wrapping(node)
        self.check_symbol_order(node)
        self.check_statement_order(node)

    def check_split_import(self, node: EitherImport) -> None:
        if len(node.names) > 1:
            self._error(node, ImportErrors.same_line)

    def check_statement_order(self, node: EitherImport) -> None:
        try:
            ordered_import = OrderedImport.from_ast(node)
        except ValueError:
            # Some other formatting error prevents the correct order from being
            # determined
            pass
        except ImportError:
            module_name, _ = ModuleOrderInfo.normalize_module(node)
            if module_name not in self.expected_resolution_failures:
                self._error(node, ImportErrors.unresolvable)
        else:
            # The order in which NodeVisitor traverses the syntax tree is unspecified
            # so we can't be sure which nodes have already been visited.
            # To prevent a single out-of-order import from causing errors on every
            # other line, we only compare each import statement with one other statement.
            # To prevent the same line from being reported twice, the error is always
            # reported for the node we're currently visiting, regardless of whether it
            # comes first or second.
            pred = self._visited_predecessor(node)
            succ = self._visited_successor(node)
            if pred is not None and not self._is_correct_order(pred, ordered_import):
                self._error(node, ImportErrors.statement_not_ordered)
            elif succ is not None and not self._is_correct_order(ordered_import, succ):
                self._error(node, ImportErrors.statement_not_ordered)
            self.visited_order_info.append(ordered_import)

    def check_joined_import(self, node: ast.ImportFrom) -> None:
        for visited in self.visited_order_info:
            if (
                isinstance(visited.node, ast.ImportFrom)
                and visited.node.module == node.module
                and self._is_same_block(node, visited.node)
            ):
                self._error(node, ImportErrors.not_joined)
                break

    def check_wrapping(self, node: ast.ImportFrom) -> None:
        start_tokens = self._filtered_tokens(node.lineno)
        end_tokens = self._filtered_tokens(node.end_lineno)
        for i, t in enumerate(start_tokens):
            if t.string == '(':
                if i < len(start_tokens) - 1 or len(end_tokens) > 1:
                    self._error(node, ImportErrors.missing_breaks)
                break
        else:
            self._error(node, ImportErrors.not_wrapped)
        for i in range(node.lineno + 1, node.end_lineno):
            tokens = self._filtered_tokens(i)
            if not tokens:
                pass
            elif len(tokens) > 2 and (tokens[1].string != 'as' or len(tokens) > 4):
                self._error(node, ImportErrors.same_line)
            elif tokens[-1].string != ',':
                self._error(node, ImportErrors.no_trailing_comma)

    def check_symbol_order(self, node: ast.ImportFrom):
        for alias0, alias1 in zip(node.names, node.names[1:]):
            if alias0.name > alias1.name:
                self._error(node, ImportErrors.symbol_not_ordered)

    def _error(self, node: EitherImport, err: ImportErrors) -> None:
        self.errors.append(ErrorInfo.from_ast(node, err))

    def _is_correct_order(
        self,
        import1: OrderedImport,
        import2: OrderedImport
    ) -> bool:
        return import1.is_correct_order(import2) or not self._is_same_block(import1.node, import2.node)

    def _is_same_block(self, node1: EitherImport, node2: EitherImport):
        if node1.col_offset != node2.col_offset:
            return False
        else:
            if node1.lineno > node2.lineno:
                node1, node2 = node2, node1
            # Local imports in different functions, for example
            # Check for dedent
            return not any(
                line_tokens and line_tokens[0].start[1] < node1.col_offset
                for line_tokens in map(self._filtered_tokens, range(node1.lineno, node2.lineno))
            )

    def _visited_successor(self, node: EitherImport) -> Optional[OrderedImport]:
        """
        Scan the list of previously visited nodes for the node with the lowest
        line number that is greater than the provided node's line number.
        """
        return min(
            filter(lambda t: t.node.lineno > node.lineno, self.visited_order_info),
            key=lambda t: t.node.lineno,
            default=None
        )

    def _visited_predecessor(self, node: EitherImport) -> Optional[OrderedImport]:
        """
        Scan the list of previously visited nodes for the node with the highest
        line number that is less than the provided node's line number.
        """
        return max(
            filter(lambda t: t.node.lineno < node.lineno, self.visited_order_info),
            key=lambda t: t.node.lineno,
            default=None
        )

    def _filtered_tokens(self, linenno):
        return [
            tokeninfo
            for tokeninfo in self.line_tokens[linenno]  # 1-based indexing for source code lines
            if tokeninfo.type not in (tokenize.COMMENT, tokenize.NEWLINE, tokenize.NL, tokenize.ENDMARKER)
        ]


class AzulImports:
    name = 'azul_imports'
    version = 1.0

    # The constructor signature is subject to the restrictions documented at
    # https://flake8.pycqa.org/en/3.8.2/plugin-development/plugin-parameters.html#indicating-desired-data
    def __init__(self, tree, file_tokens, filename):
        self.tree = tree
        self.tokens = file_tokens
        self.file_name = filename

    def _run(self) -> List[ErrorInfo]:
        visitor = ImportVisitor(self.file_name, self.tokens)
        visitor.visit(self.tree)
        return visitor.errors

    def run(self) -> List[tuple]:
        return [err.to_flake8_tuple() for err in self._run()]

import uuid
import logging
from flask_login import current_user

from app.extensions import db, HoustonModel
import app.extensions.logging as AuditLog
from app.utils import HoustonException

log = logging.getLogger(__name__)


class CollaborationUserState:
    ALLOWED_STATES = [
        'declined',
        'approved',
        'pending',
        'not_initiated',
        'revoked',
        'creator',
    ]
    DECLINED = ALLOWED_STATES[0]
    APPROVED = ALLOWED_STATES[1]
    PENDING = ALLOWED_STATES[2]
    NOT_INITIATED = ALLOWED_STATES[3]
    REVOKED = ALLOWED_STATES[4]
    CREATOR = ALLOWED_STATES[5]


class CollaborationUserAssociations(db.Model, HoustonModel):
    """
    Collaboration many to many association with Users.
    Current maximum of two users per Collaboration.
    """
    __mapper_args__ = {
        'confirm_deleted_rows': False,
    }

    collaboration_guid = db.Column(
        db.GUID, db.ForeignKey('collaboration.guid'), default=uuid.uuid4, primary_key=True
    )
    collaboration = db.relationship(
        'Collaboration', back_populates='collaboration_user_associations'
    )

    user_guid = db.Column(db.GUID, db.ForeignKey('user.guid'), primary_key=True)
    user = db.relationship('User', backref=db.backref('user_collaboration_associations'))

    read_approval_state = db.Column(
        db.String(length=32), default=CollaborationUserState.PENDING, nullable=False
    )
    edit_approval_state = db.Column(
        db.String(length=32), default=CollaborationUserState.NOT_INITIATED, nullable=False
    )

    def delete(self):
        self.collaboration.user_deleted(self)

    def has_read(self):
        return self.collaboration.user_has_read_access(self.user_guid)

    def has_edit(self):
        return self.collaboration.user_has_edit_access(self.user_guid)

    def get_other_user(self):
        return self.collaboration.get_other_user(self.user_guid)


class Collaboration(db.Model, HoustonModel):
    """
    Collaborations database model.
    """
    __mapper_args__ = {
        'confirm_deleted_rows': False,
    }

    guid = db.Column(
        db.GUID, default=uuid.uuid4, primary_key=True
    )  # pylint: disable=invalid-name

    collaboration_user_associations = db.relationship(
        'CollaborationUserAssociations', back_populates='collaboration'
    )

    initiator_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=False
    )
    edit_initiator_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=True
    )

    def __init__(self, members, initiator_user, **kwargs):
        num_users = len(members)
        if num_users != 2:
            raise ValueError('Creating a collaboration requires 2 members.')

        if not hasattr(initiator_user, 'is_user_manager'):
            # current user is not actually a User although it quacks like one so can't use isinstance
            raise ValueError(f'initiator_user {initiator_user} is not a user')

        # user manager created are handled differently
        manager_created = initiator_user not in members
        if manager_created and not initiator_user.is_user_manager:
            raise ValueError(
                f'Attempted creation of a collaboration by a non manager {initiator_user.email}.'
            )

        self.initiator_guid = initiator_user.guid
        self.edit_initiator_guid = None

        for user in members:
            if not hasattr(user, 'is_user_manager'):
                raise ValueError(f'User {user} is not a user manager')

            collab_user_assoc = CollaborationUserAssociations(
                collaboration=self, user=user
            )
            # Edit not enabled on creation
            collab_user_assoc.edit_approval_state = CollaborationUserState.NOT_INITIATED

            with db.session.begin(subtransactions=True):
                db.session.add(collab_user_assoc)

            # If you initiate, then you approve read. Manager created are also read approved
            if user == initiator_user or manager_created:
                collab_user_assoc.read_approval_state = CollaborationUserState.APPROVED
            else:
                collab_user_assoc.read_approval_state = CollaborationUserState.PENDING

        if manager_created:
            # User manager created collaboration, store who the creator was
            collab_creator = CollaborationUserAssociations(
                collaboration=self, user=initiator_user
            )
            from app.modules.notifications.models import NotificationType
            collab_creator.read_approval_state = CollaborationUserState.CREATOR
            collab_creator.edit_approval_state = CollaborationUserState.CREATOR

            for user in members:
                user_assoc = self._get_association_for_user(user.guid)
                self._notify_user(
                    collab_creator, user_assoc, NotificationType.collab_manager_create
                )

            with db.session.begin(subtransactions=True):
                db.session.add(collab_creator)

    def _get_association_for_user(self, user_guid):
        assoc = None
        for association in self.collaboration_user_associations:
            if association.user_guid == user_guid:
                assoc = association
        return assoc

    def _get_association_for_other_user(self, user_guid):
        assoc = None
        if user_guid is not None:
            other_user_guids = [
                association.user_guid
                for association in self.collaboration_user_associations
                if (association.user_guid != user_guid)
                & (association.read_approval_state != CollaborationUserState.CREATOR)
            ]
            assert len(other_user_guids) == 1
            assoc = self._get_association_for_user(other_user_guids[0])
        return assoc

    def get_users(self):
        users = []
        for association in self.collaboration_user_associations:
            if association.read_approval_state != CollaborationUserState.CREATOR:
                users.append(association.user)
        return users

    def user_guids(self):
        user_guids = []
        for association in self.collaboration_user_associations:
            if association.read_approval_state != CollaborationUserState.CREATOR:
                user_guids.append(association.user_guid)
        return user_guids

    def notify_pending_users(self):
        # Once created notify the pending user to accept
        for collab_user_assoc in self.collaboration_user_associations:
            if (
                collab_user_assoc.read_approval_state == CollaborationUserState.PENDING
                or collab_user_assoc.edit_approval_state == CollaborationUserState.PENDING
            ):
                from app.modules.notifications.models import NotificationType
                other_user_assoc = self._get_association_for_other_user(
                    collab_user_assoc.user.guid
                )
                if (
                    collab_user_assoc.read_approval_state
                    == CollaborationUserState.PENDING
                ):
                    self._notify_user(
                        other_user_assoc,
                        collab_user_assoc,
                        NotificationType.collab_request,
                    )
                if (
                    collab_user_assoc.edit_approval_state
                    == CollaborationUserState.PENDING
                ):
                    self._notify_user(
                        other_user_assoc,
                        collab_user_assoc,
                        NotificationType.collab_edit_request,
                    )

    def _notify_user(self, sending_user_assoc, receiving_user_assoc, notification_type):
        from app.modules.notifications.models import Notification, NotificationBuilder
        builder = NotificationBuilder(sending_user_assoc.user)
        builder.set_collaboration(self)
        Notification.create(notification_type, receiving_user_assoc.user, builder)

    def get_user_data_as_json(self):
        from app.modules.users.schemas import BaseUserSchema
        user_data = {}
        for association in self.collaboration_user_associations:
            if association.read_approval_state == CollaborationUserState.CREATOR:
                continue
            assoc_data = BaseUserSchema().dump(association.user).data
            assoc_data['viewState'] = association.read_approval_state
            assoc_data['editState'] = association.edit_approval_state
            user_data[str(association.user.guid)] = assoc_data
        return user_data

    def _is_approval_state_transition_valid(self, old_state, new_state):
        ret_val = False
        # Only certain transitions are permitted
        if old_state == CollaborationUserState.NOT_INITIATED:
            ret_val = new_state in [
                CollaborationUserState.CREATOR,
                CollaborationUserState.APPROVED,
                CollaborationUserState.PENDING,
            ]
        elif old_state == CollaborationUserState.PENDING:
            ret_val = new_state in [
                CollaborationUserState.APPROVED,
                CollaborationUserState.DECLINED,
            ]
        elif old_state == CollaborationUserState.APPROVED:
            ret_val = new_state == CollaborationUserState.REVOKED
        elif old_state == CollaborationUserState.DECLINED:
            ret_val = new_state == CollaborationUserState.APPROVED
        elif old_state == CollaborationUserState.REVOKED:
            ret_val = new_state == CollaborationUserState.APPROVED

        # Permit resetting to same state in all cases rather than handling separately for each
        if not ret_val:
            ret_val = old_state == new_state
        return ret_val

    def set_read_approval_state_for_user(self, user_guid, state):
        success = False
        if state not in CollaborationUserState.ALLOWED_STATES:
            raise ValueError(
                f'State "{state}" not in allowed states: {", ".join(CollaborationUserState.ALLOWED_STATES)}'
            )

        if user_guid is not None:
            assert isinstance(user_guid, uuid.UUID)
            for association in self.collaboration_user_associations:
                if association.user_guid == user_guid:
                    if self._is_approval_state_transition_valid(
                        association.read_approval_state, state
                    ):
                        association.read_approval_state = state
                        # If a user revokes view and previously allowed edit, they automatically
                        # revoke edit too
                        if (
                            state == CollaborationUserState.REVOKED
                            and association.edit_approval_state
                            == CollaborationUserState.APPROVED
                        ):
                            association.edit_approval_state = state

                        from app.modules.notifications.models import NotificationType
                        if state == CollaborationUserState.REVOKED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_revoke,
                            )
                        elif state == CollaborationUserState.APPROVED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_approved,
                            )

                        with db.session.begin(subtransactions=True):
                            db.session.merge(association)
                        success = True
        return success

    def user_has_read_access(self, user_guid):
        ret_val = False
        assert isinstance(user_guid, uuid.UUID)
        my_assoc = self._get_association_for_user(user_guid)
        other_assoc = self._get_association_for_other_user(user_guid)
        if my_assoc and other_assoc:
            ret_val = (
                my_assoc.read_approval_state == CollaborationUserState.APPROVED
                and other_assoc.read_approval_state == CollaborationUserState.APPROVED
            )
        return ret_val

    def user_has_edit_access(self, user_guid):
        ret_val = False
        assert isinstance(user_guid, uuid.UUID)
        my_assoc = self._get_association_for_user(user_guid)
        other_assoc = self._get_association_for_other_user(user_guid)
        if my_assoc and other_assoc:
            ret_val = (
                my_assoc.edit_approval_state == CollaborationUserState.APPROVED
                and other_assoc.edit_approval_state == CollaborationUserState.APPROVED
            )
        return ret_val

    def get_other_user(self, user_guid):
        other_assoc = self._get_association_for_other_user(user_guid)
        if other_assoc:
            return other_assoc.user
        return None

    def set_edit_approval_state_for_user(self, user_guid, state):
        success = False
        if state not in CollaborationUserState.ALLOWED_STATES:
            raise ValueError(
                f'State "{state}" not in allowed states: {", ".join(CollaborationUserState.ALLOWED_STATES)}'
            )

        if user_guid is not None:
            assert isinstance(user_guid, uuid.UUID)
            for association in self.collaboration_user_associations:
                if association.user_guid == user_guid:
                    if self._is_approval_state_transition_valid(
                        association.edit_approval_state, state
                    ):
                        association.edit_approval_state = state
                        with db.session.begin(subtransactions=True):
                            db.session.merge(association)

                        from app.modules.notifications.models import NotificationType
                        if state == CollaborationUserState.REVOKED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_edit_revoke,
                            )
                        elif state == CollaborationUserState.APPROVED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_edit_approved,
                            )
                        success = True
        return success

    def initiate_edit_with_other_user(self):
        self.edit_initiator_guid = current_user.guid
        my_assoc = self._get_association_for_user(current_user.guid)
        other_assoc = self._get_association_for_other_user(current_user.guid)

        if (
            my_assoc.read_approval_state == CollaborationUserState.APPROVED
            and other_assoc.read_approval_state == CollaborationUserState.APPROVED
        ):
            if self._is_approval_state_transition_valid(
                my_assoc.read_approval_state, CollaborationUserState.APPROVED
            ):
                my_assoc.edit_approval_state = CollaborationUserState.APPROVED
                with db.session.begin(subtransactions=True):
                    db.session.merge(my_assoc)

            if self._is_approval_state_transition_valid(
                other_assoc.edit_approval_state, CollaborationUserState.PENDING
            ):
                other_assoc.edit_approval_state = CollaborationUserState.PENDING
                with db.session.begin(subtransactions=True):
                    db.session.merge(other_assoc)
        else:
            raise HoustonException(
                log, 'Unable to start edit on unapproved collaboration'
            )

    # This relates to if the user can access the collaboration itself, not the data
    def user_can_access(self, user):
        return user in self.get_users()

    def __repr__(self):
        return (
            '<{class_name}('
            'guid={self.guid}, '
            ')>'.format(class_name=self.__class__.__name__, self=self)
        )

    def user_deleted(self, user_association):
        if user_association.read_approval_state == CollaborationUserState.CREATOR:
            # Collaboration creator removal is an odd case, we have to have an initiator so chose an arbitrary member
            new_creator = (
                self.collaboration_user_associations[0]
                if self.collaboration_user_associations[0] != user_association
                else self.collaboration_user_associations[1]
            )
            message = (
                f'Initiator user removed, assigning {new_creator.user_guid} as initiator'
            )
            AuditLog.audit_log_object(log, self, message)
            self.initiator_guid = new_creator.user_guid
            with db.session.begin(subtransactions=True):
                db.session.merge(self)
                db.session.delete(user_association)
        else:
            # If the user is a member and are removed then the collaboration is removed entirely
            self.delete()

    def delete(self):
        AuditLog.delete_object(log, self)
        with db.session.begin(subtransactions=True):
            for assoc in self.collaboration_user_associations:
                db.session.delete(assoc)
            db.session.delete(self)

# Import required modules
import os
import json
import requests
from requests.exceptions import HTTPError
from dotenv import load_dotenv
import logging

logger = logging.getLogger()

def __create_env_error_response(var_name: str):
    """
    Creates an error response for missing environment variables.
    Logs the error and returns a standardized response structure.
    """
    message = "Lambda function not properly configured. Missing environment variable '{0:s}'."
    logger.error(message.format(var_name))

    response = {
        'statusCode': 500,
        'body': json.dumps(message.format(var_name))
    }

    return response


def handler(event, context):
    # Load environment variables from .env file
    load_dotenv()

    # Configure log level based on environment variable
    logger.setLevel(os.getenv("HULL_LOG_LEVEL", logging.ERROR))

    # Log invocation event
    logger.info("Hull extract requester invoked with event: %s", event)

    # Parse configuration from environment variables
    logger.info("Parsing configuration from environment variables...")

    HULL_ORG = os.getenv("HULL_ORG_ID")
    CONNECTOR_ID = os.getenv("HULL_CONNECTOR_ID")
    CONNECTOR_SECRET = os.getenv("HULL_CONNECTOR_SECRET")
    CALLBACK_URL = os.getenv("HULL_EXPORT_CALLBACKURL")
    HULL_OBJECTTYPE = os.getenv("HULL_EXPORT_OBJECTTYPE")
    HULL_FIELDS = os.getenv("HULL_EXPORT_FIELDS")
    HULL_ESQUERY = os.getenv("HULL_EXPORT_ESQUERY")

    logger.info(
        "Loaded environment variables: %s",
        {
            "HULL_ORG_ID": HULL_ORG,
            "HULL_CONNECTOR_ID": CONNECTOR_ID,
            "HULL_CONNECTOR_SECRET": CONNECTOR_SECRET,
            "HULL_EXPORT_CALLBACKURL": CALLBACK_URL,
            "HULL_EXPORT_OBJECTTYPE": HULL_OBJECTTYPE,
            "HULL_EXPORT_FIELDS": HULL_FIELDS,
            "HULL_EXPORT_ESQUERY": HULL_ESQUERY
        }
    )

    # Perform pre-flight checks for required environment variables
    if not HULL_ORG:
        return __create_env_error_response("HULL_ORG_ID")

    if not CONNECTOR_ID:
        return __create_env_error_response("HULL_CONNECTOR_ID")

    if not CONNECTOR_SECRET:
        return __create_env_error_response("HULL_CONNECTOR_SECRET")

    if not CALLBACK_URL:
        return __create_env_error_response("HULL_EXPORT_CALLBACKURL")

    if not HULL_OBJECTTYPE:
        return __create_env_error_response("HULL_EXPORT_OBJECTTYPE")

    if not HULL_FIELDS:
        return __create_env_error_response("HULL_EXPORT_FIELDS")

    if not HULL_ESQUERY:
        return __create_env_error_response("HULL_EXPORT_ESQUERY")

    # Validate object type
    if HULL_OBJECTTYPE not in ["user", "account"]:
        message = "Lambda function not properly configured. Object type '{0:s}' is not one of the allowed values of 'user' or 'account'."
        logger.error(message.format(HULL_OBJECTTYPE))

        response = {
            'statusCode': 500,
            'body': json.dumps(message.format(HULL_OBJECTTYPE))
        }
        return response

    # All pre-flight checks passed; proceed to request export
    try:
        export_url = f"https://{HULL_ORG}/api/v1/extract/{HULL_OBJECTTYPE}s"

        req_body = {
            "url": CALLBACK_URL,
            "format": "json",
            "fields": json.loads(HULL_FIELDS),
            "query": json.loads(HULL_ESQUERY)
        }

        req_headers = {
            "Accept": "application/json",
            "Hull-App-Id": CONNECTOR_ID,
            "Hull-Access-Token": CONNECTOR_SECRET
        }

        logger.info(
            "Requesting extract from the Hull platform at url '%s' with headers %s and body %s",
            export_url,
            req_headers,
            req_body
        )

        response = requests.post(export_url, json=req_body, headers=req_headers)
        logger.info(
            "Extract requested, finished with status: %s %s",
            response.status_code,
            response.reason
        )

        response.raise_for_status()

    except HTTPError as http_error:
        logger.error("An unexpected HTTP error occurred: %s", http_error)

        response = {
            'statusCode': http_error.response.status_code,
            'body': json.dumps(f"An unexpected HTTP error occurred: {http_error}")
        }
        return response

    except Exception as err:
        logger.error("An unexpected error occurred: %s", err)

        response = {
            'statusCode': 500,
            'body': json.dumps(f"An unexpected error occurred: {err}")
        }
        return response

    else:
        logger.info(
            "Successfully requested export from Hull. Result will be sent to '%s'",
            CALLBACK_URL
        )

        response = {
            'statusCode': 200,
            'body': json.dumps(
                f"Successfully requested export from Hull. Result will be sent to '{CALLBACK_URL}'"
            )
        }
        return response

# Guillotina transaction implementation
from collections import OrderedDict
from guillotina import task_vars
from guillotina._settings import app_settings
from guillotina.component import get_adapter
from guillotina.component import query_adapter
from guillotina.const import ROOT_ID
from guillotina.content import Container
from guillotina.db.db import Root
from guillotina.db.interfaces import ITransaction
from guillotina.db.interfaces import ITransactionCache
from guillotina.db.interfaces import ITransactionStrategy
from guillotina.db.interfaces import IWriter
from guillotina.db.orm.interfaces import IBaseObject
from guillotina.exceptions import ConflictError
from guillotina.exceptions import ReadOnlyError
from guillotina.exceptions import RestartCommit
from guillotina.exceptions import TIDConflictError
from guillotina.exceptions import TransactionClosedException
from guillotina.exceptions import TransactionObjectRegistrationMismatchException
from guillotina.profile import profilable
from guillotina.registry import Registry
from guillotina.utils import lazy_apply
from typing import Any
from typing import AsyncIterator
from typing import Callable
