# Define type variable for Renderer
R = TypeVar("R", bound="Renderer")


@dataclass  # type: ignore
class Renderer(ContextManager["Renderer"], ABC):
    """Renderer base class."""

    # Fullscreen mode setting (not user-configurable)
    fullscreen: bool = field(default=True, init=False)
    """Whether to use fullscreen mode."""

    @abstractmethod
    def render(self, screen: Text) -> None:
        """Render a screen."""
        raise NotImplementedError("You must implement this method")

    @abstractmethod
    def next_event(self) -> Optional[Event]:
        """Attempt to get the next terminal event."""
        raise NotImplementedError("You must implement this method")

    @abstractmethod
    def __enter__(self: R) -> R:
        """
        Enter context.
        This should perform any setup required by the renderer.
        """
        raise NotImplementedError("You must implement this method")

    @abstractmethod
    def __exit__(
        self,
        exctype: Optional[Type[BaseException]],
        excinst: Optional[BaseException],
        exctb: Optional[TracebackType],
    ) -> Optional[bool]:
        """
        Exit context.
        This should perform any teardown required by the renderer.
        """
        raise NotImplementedError("You must implement this method")

    @abstractmethod
    @contextmanager
    def into_raw_mode(self: R) -> Iterator[R]:
        """Enter raw mode."""
        raise NotImplementedError("You must implement this method")

    @abstractmethod
    @contextmanager
    def hide_cursor(self: R) -> Iterator[R]:
        """Hide the cursor."""
        raise NotImplementedError("You must implement this method")

# I *hate* writing modules like this... but, I always seem to end up with one
# after some amount of time.
# They're never what I want, maybe because what I want is to not have to write
# this kind of code. Doesn't everyone have to print shit out? Like, exceptions?
# I also constantly debate if these modules are even worth existing, or if I
# should add the same tedious crap at the site of every `raise` that someone
# might have to read.
# So... here it is. Once again.
# This module prints things... as plain, markdown-ish strings. It doesn't depend
# on anything outside the standard library, and should probably stay that way.

"""
"""

from typing import Sequence, Callable, Any, Iterable, Union
import inspect
from pathlib import Path
import shlex


def tick(value) -> str:
    return f"`{value}`"


def fmt_class(cls) -> str:
    if cls.__module__ == "builtins":
        return tick(cls.__name__)
    return tick(f"{cls.__module__}.{cls.__name__}")


def fmt_path(path: Path) -> str:
    return tick(path)


def fmt_cmd(
    cmd: Iterable[str],
    *,
    code_width: int = 80,
    indent: Union[str, int] = "  "
):
    if isinstance(indent, int):
        indent = " " * indent

    lines = [""]
    for token in cmd:
        quoted = shlex.quote(token)
        if len(lines[-1]) + 1 + len(quoted) > code_width - 2:
            lines[-1] += " \\"
            lines.append(indent)

        if not lines[-1].isspace():
            lines[-1] += " "

        lines[-1] += quoted

    return "\n".join(lines)


def fmt(x: Any) -> str:
    if inspect.isclass(x):
        return fmt_class(x)
    if isinstance(x, Path):
        return fmt_path(x)
    return repr(x)


def coordinate(
    seq: Sequence,
    conjunction: str,
    *,
    to_s: Callable[[Any], str] = fmt,
    sep: str = ",",
) -> str:
    """\
    Examples:
    1.  Empty list
        >>> fmt_list([])
        '[empty]'
    2.  List with a single item
        >>> fmt_list([1])
        '1'
    3.  List with two items
        >>> fmt_list([1, 2])
        '1 and 2'
    4.  List with more than two items
        >>> fmt_list([1, 2, 3])
        '1, 2 and 3'
    5.  Defaults to `repr` to cast to string
        >>> fmt_list(['a', 'b', 'c'])
        "'a', 'b' and 'c'"
    6.  Providing an alternative cast function
        >>> fmt_list(['a', 'b', 'c'], lambda x: f"`{x}`")
        '`a`, `b` and `c`'
    """
    length = len(seq)

    if length == 0:
        return "[empty]"
    if length == 1:
        return to_s(seq[0])

    return f" {conjunction} ".join(
        (f"{sep} ".join(map(to_s, seq[0:-1])), to_s(seq[-1]))
    )

# Asset Maintenance Document Class
from __future__ import unicode_literals

import frappe
from frappe.model.document import Document
from frappe.desk.form import assign_to
from frappe import throw, _
from frappe.utils import add_days, add_months, add_years, getdate, nowdate


class AssetMaintenance(Document):
    def validate(self):
        # Validate maintenance tasks
        for task in self.get('asset_maintenance_tasks'):
            # Check if start date is not before end date
            if task.end_date and (getdate(task.start_date) >= getdate(task.end_date)):
                throw(_("Start date should be less than end date for task {0}").format(task.maintenance_task))

            # Update status if due date has passed
            if getdate(task.next_due_date) < getdate(nowdate()):
                task.maintenance_status = "Overdue"

    def on_update(self):
        # Assign tasks to maintenance manager if not already assigned
        for task in self.get('asset_maintenance_tasks'):
            if not task.assign_to:
                task.db_set("assign_to", self.maintenance_manager)
                task.db_set("assign_to_name", self.maintenance_manager_name)

            # Assign tasks to team members
            assign_tasks(
                self.name, 
                task.assign_to, 
                task.maintenance_task, 
                task.next_due_date
            )

        # Sync maintenance tasks
        self.sync_maintenance_tasks()

    def sync_maintenance_tasks(self):
        tasks_names = []

        # Process active tasks
        for task in self.get('asset_maintenance_tasks'):
            tasks_names.append(task.name)
            update_maintenance_log(
                asset_maintenance=self.name,
                item_code=self.item_code,
                item_name=self.item_name,
                task=task
            )

        # Cancel logs for removed tasks
        asset_maintenance_logs = frappe.get_all(
            "Asset Maintenance Log", 
            fields=["name"], 
            filters={
                "asset_maintenance": self.name,
                "task": ("not in", tasks_names)
            }
        )

        if asset_maintenance_logs:
            for asset_maintenance_log in asset_maintenance_logs:
                maintenance_log = frappe.get_doc('Asset Maintenance Log', asset_maintenance_log.name)
                maintenance_log.db_set('maintenance_status', 'Cancelled')


@frappe.whitelist()
def assign_tasks(asset_maintenance_name, assign_to_member, maintenance_task, next_due_date):
    """
    Assigns a maintenance task to a user
    """
    team_member = frappe.get_doc('User', assign_to_member).email

    args = {
        'doctype': 'Asset Maintenance',
        'assign_to': team_member,
        'name': asset_maintenance_name,
        'description': maintenance_task,
        'date': next_due_date
    }

    # Avoid duplicate assignments
    if not frappe.db.sql(
        """select owner from `tabToDo`
        where reference_type=%(doctype)s and reference_name=%(name)s and status="Open"
        and owner=%(assign_to)s""", 
        args
    ):
        assign_to.add(args)


@frappe.whitelist()
def calculate_next_due_date(periodicity, start_date=None, end_date=None, last_completion_date=None, next_due_date=None):
    """
    Calculates the next due date based on periodicity
    """
    # Use current date if no start date provided
    if not start_date and not last_completion_date:
        start_date = frappe.utils.now()

    # Prefer last completion date if valid
    if last_completion_date and (last_completion_date > start_date or not start_date):
        start_date = last_completion_date

    # Calculate next due date based on periodicity
    if periodicity == 'Daily':
        next_due_date = add_days(start_date, 1)

    if periodicity == 'Weekly':
        next_due_date = add_days(start_date, 7)

    if periodicity == 'Monthly':
        next_due_date = add_months(start_date, 1)

    if periodicity == 'Yearly':
        next_due_date = add_years(start_date, 1)

    if periodicity == '2 Yearly':
        next_due_date = add_years(start_date, 2)

    if periodicity == 'Quarterly':
        next_due_date = add_months(start_date, 3)

    # Clear due date if invalid
    if end_date and (start_date >= end_date or last_completion_date >= end_date or next_due_date):
        next_due_date = ""

    return next_due_date


def update_maintenance_log(asset_maintenance, item_code, item_name, task):
    """
    Updates or creates maintenance log for a task
    """
    # Check for existing log
    asset_maintenance_log = frappe.get_value(
        "Asset Maintenance Log", 
        {
            "asset_maintenance": asset_maintenance,
            "task": task.maintenance_task,
            "maintenance_status": ('in', ['Planned', 'Overdue'])
        }
    )

    if not asset_maintenance_log:
        # Create new log
        asset_maintenance_log = frappe.get_doc({
            "doctype": "Asset Maintenance Log",
            "asset_maintenance": asset_maintenance,
            "asset_name": asset_maintenance,
            "item_code": item_code,
            "item_name": item_name,
            "task": task.maintenance_task,
            "has_certificate": task.certificate_required,
            "description": task.description,
            "assign_to_name": task.assign_to_name,
            "periodicity": str(task.periodicity),
            "maintenance_type": task.maintenance_type,
            "due_date": task.next_due_date
        })
        asset_maintenance_log.insert()
    else:
        # Update existing log
        maintenance_log = frappe.get_doc('Asset Maintenance Log', asset_maintenance_log)
        maintenance_log.assign_to_name = task.assign_to_name
        maintenance_log.has_certificate = task.certificate_required
        maintenance_log.description = task.description
        maintenance_log.periodicity = str(task.periodicity)
        maintenance_log.maintenance_type = task.maintenance_type
        maintenance_log.due_date = task.next_due_date
        maintenance_log.save()


@frappe.whitelist()
def get_team_members(doctype, txt, searchfield, start, page_len, filters):
    """
    Returns list of team members for a maintenance team
    """
    return frappe.db.get_values(
        'Maintenance Team Member', 
        {'parent': filters.get("maintenance_team")}
    )


@frappe.whitelist()
def get_maintenance_log(asset_name):
    """
    Returns maintenance log statistics for an asset
    """
    return frappe.db.sql("""
        select maintenance_status, count(asset_name) as count, asset_name
        from `tabAsset Maintenance Log`
        where asset_name=%s group by maintenance_status""",
        (asset_name), 
        as_dict=1
    )

# Noise model definitions and utilities for stim-based quantum circuit simulation

import dataclasses
from typing import Optional, Dict, Set, Tuple
import stim

# Define Clifford gate categories
ANY_CLIFFORD_1_OPS = {"C_XYZ", "C_ZYX", "H", "H_YZ", "I"}
ANY_CLIFFORD_2_OPS = {"CX", "CY", "CZ", "XCX", "XCY", "XCZ", "YCX", "YCY", "YCZ"}
RESET_OPS = {"R", "RX", "RY"}
MEASURE_OPS = {"M", "MX", "MY"}
ANNOTATION_OPS = {"OBSERVABLE_INCLUDE", "DETECTOR", "SHIFT_COORDS", "QUBIT_COORDS", "TICK"}


@dataclasses.dataclass(frozen=True)
class NoiseModel:
    """Represents a noise model for quantum circuits."""

    idle: float
    measure_reset_idle: float
    noisy_gates: Dict[str, float]
    any_clifford_1: Optional[float] = None
    any_clifford_2: Optional[float] = None
    use_correlated_parity_measurement_errors: bool = False

    @staticmethod
    def SD6(p: float) -> 'NoiseModel':
        """Stabilizer code with 6% error rate per operation."""
        return NoiseModel(
            any_clifford_1=p,
            idle=p,
            measure_reset_idle=0,
            noisy_gates={
                "CX": p,
                "R": p,
                "M": p,
            },
        )

    @staticmethod
    def PC3(p: float) -> 'NoiseModel':
        """Pauli channel with 3% error rate per operation."""
        return NoiseModel(
            any_clifford_1=p,
            any_clifford_2=p,
            idle=p,
            measure_reset_idle=0,
            noisy_gates={
                "R": p,
                "M": p,
            },
        )

    @staticmethod
    def EM3_v1(p: float) -> 'NoiseModel':
        """EM3 but with measurement flip errors independent of measurement target depolarization error."""
        return NoiseModel(
            idle=p,
            measure_reset_idle=0,
            any_clifford_1=p,
            noisy_gates={
                "R": p,
                "M": p,
                "MPP": p,
            },
        )

    @staticmethod
    def EM3_v2(p: float) -> 'NoiseModel':
        """EM3 with measurement flip errors correlated with measurement target depolarization error."""
        return NoiseModel(
            any_clifford_1=0,
            any_clifford_2=0,
            idle=p,
            measure_reset_idle=0,
            use_correlated_parity_measurement_errors=True,
            noisy_gates={
                "R": p/2,
                "M": p/2,
                "MPP": p,
            },
        )

    @staticmethod
    def SI1000(p: float) -> 'NoiseModel':
        """Surface code with 1000x overhead, p error rate."""
        return NoiseModel(
            any_clifford_1=p / 10,
            idle=p / 10,
            measure_reset_idle=2 * p,
            noisy_gates={
                "CZ": p,
                "R": 2 * p,
                "M": 5 * p,
            },
        )

    def noisy_op(self, op: stim.CircuitInstruction, p: float, ancilla: int) -> Tuple[stim.Circuit, stim.Circuit, stim.Circuit]:
        """Generate noisy version of an operation with given error probability."""
        pre = stim.Circuit()
        mid = stim.Circuit()
        post = stim.Circuit()

        targets = op.targets_copy()
        args = op.gate_args_copy()

        if p > 0:
            if op.name in ANY_CLIFFORD_1_OPS:
                post.append_operation("DEPOLARIZE1", targets, p)
            elif op.name in ANY_CLIFFORD_2_OPS:
                post.append_operation("DEPOLARIZE2", targets, p)
            elif op.name in RESET_OPS or op.name in MEASURE_OPS:
                if op.name in RESET_OPS:
                    post.append_operation("Z_ERROR" if op.name.endswith("X") else "X_ERROR", targets, p)
                if op.name in MEASURE_OPS:
                    pre.append_operation("Z_ERROR" if op.name.endswith("X") else "X_ERROR", targets, p)
            elif op.name == "MPP":
                assert len(targets) % 3 == 0 and all(t.is_combiner for t in targets[1::3]), repr(op)
                assert args == [] or args == [0]
                if self.use_correlated_parity_measurement_errors:
                    for k in range(0, len(targets), 3):
                        mid += parity_measurement_with_correlated_measurement_noise(
                            t1=targets[k],
                            t2=targets[k + 2],
                            ancilla=ancilla,
                            mix_probability=p)
                    return pre, mid, post
                else:
                    pre.append_operation("DEPOLARIZE2", [t.value for t in targets if not t.is_combiner], p)
                    args = [p]
            else:
                raise NotImplementedError(repr(op))

        mid.append_operation(op.name, targets, args)
        return pre, mid, post

    def noisy_circuit(self, circuit: stim.Circuit, *, qs: Optional[Set[int]] = None) -> stim.Circuit:
        """Apply noise model to an entire circuit."""
        result = stim.Circuit()
        ancilla = circuit.num_qubits

        current_moment_pre = stim.Circuit()
        current_moment_mid = stim.Circuit()
        current_moment_post = stim.Circuit()

        used_qubits: Set[int] = set()
        measured_or_reset_qubits: Set[int] = set()

        if qs is None:
            qs = set(range(circuit.num_qubits))

        def flush():
            nonlocal result
            if not current_moment_mid:
                return

            # Apply idle depolarization rules.
            idle_qubits = sorted(qs - used_qubits)
            if used_qubits and idle_qubits and self.idle > 0:
                current_moment_post.append_operation("DEPOLARIZE1", idle_qubits, self.idle)

            idle_qubits = sorted(qs - measured_or_reset_qubits)
            if measured_or_reset_qubits and idle_qubits and self.measure_reset_idle > 0:
                current_moment_post.append_operation("DEPOLARIZE1", idle_qubits, self.measure_reset_idle)

            # Move current noisy moment into result.
            result += current_moment_pre
            result += current_moment_mid
            result += current_moment_post

            used_qubits.clear()
            current_moment_pre.clear()
            current_moment_mid.clear()
            current_moment_post.clear()
            measured_or_reset_qubits.clear()

        for op in circuit:
            if isinstance(op, stim.CircuitRepeatBlock):
                flush()
                result += self.noisy_circuit(op.body_copy(), qs=qs) * op.repeat_count
            elif isinstance(op, stim.CircuitInstruction):
                if op.name == "TICK":
                    flush()
                    result.append_operation("TICK", [])
                    continue

                if op.name in self.noisy_gates:
                    p = self.noisy_gates[op.name]
                elif self.any_clifford_1 is not None and op.name in ANY_CLIFFORD_1_OPS:
                    p = self.any_clifford_1
                elif self.any_clifford_2 is not None and op.name in ANY_CLIFFORD_2_OPS:
                    p = self.any_clifford_2
                elif op.name in ANNOTATION_OPS:
                    p = 0
                else:
                    raise NotImplementedError(repr(op))

                pre, mid, post = self.noisy_op(op, p, ancilla)
                current_moment_pre += pre
                current_moment_mid += mid
                current_moment_post += post

                # Ensure the circuit is not touching qubits multiple times per tick.
                touched_qubits = {
                    t.value
                    for t in op.targets_copy()
                    if t.is_x_target or t.is_y_target or t.is_z_target or t.is_qubit_target
                }
                if op.name in ANNOTATION_OPS:
                    touched_qubits.clear()

                # Hack: turn off this assertion off for now since correlated errors are built into circuit.
                #assert touched_qubits.isdisjoint(used_qubits), repr(current_moment_pre + current_moment_mid + current_moment_post)

                used_qubits |= touched_qubits
                if op.name in MEASURE_OPS or op.name in RESET_OPS:
                    measured_or_reset_qubits |= touched_qubits
            else:
                raise NotImplementedError(repr(op))

        flush()
        return result


def mix_probability_to_independent_component_probability(mix_probability: float, n: float) -> float:
    """Converts the probability of applying a full mixing channel to independent component probabilities.

    If each component is applied independently with the returned component probability, the overall effect
    is identical to, with probability `mix_probability`, uniformly picking one of the components to apply.
    Note that, unlike in other places in the code, the all-identity case is one of the components that can
    be picked when applying the error case.
    """
    return 0.5 - 0.5 * (1 - mix_probability) ** (1 / 2 ** (n - 1))


def parity_measurement_with_correlated_measurement_noise(
        *,
        t1: stim.GateTarget,
        t2: stim.GateTarget,
        ancilla: int,
        mix_probability: float) -> stim.Circuit:
    """Performs a noisy parity measurement.

    With probability mix_probability, applies a random element from
        {I1,X1,Y1,Z1}*{I2,X2,Y2,Z2}*{no flip, flip}

    Note that, unlike in other places in the code, the all-identity term is one of the possible
    samples when the error occurs.
    """
    ind_p = mix_probability_to_independent_component_probability(mix_probability, 5)

    # Generate all possible combinations of (non-identity) channels. Assumes triple of targets
    # with last element corresponding to measure qubit.
    circuit = stim.Circuit()
    circuit.append_operation('R', [ancilla])

    if t1.is_x_target:
        circuit.append_operation('XCX', [t1.value, ancilla])
    if t1.is_y_target:
        circuit.append_operation('YCX', [t1.value, ancilla])
    if t1.is_z_target:
        circuit.append_operation('ZCX', [t1.value, ancilla])

    if t2.is_x_target:
        circuit.append_operation('XCX', [t2.value, ancilla])
    if t2.is_y_target:
        circuit.append_operation('YCX', [t2.value, ancilla])
    if t2.is_z_target:
        circuit.append_operation('ZCX', [t2.value, ancilla])

    first_targets = ["I", stim.target_x(t1.value), stim.target_y(t1.value), stim.target_z(t1.value)]
    second_targets = ["I", stim.target_x(t2.value), stim.target_y(t2.value), stim.target_z(t2.value)]
    measure_targets = ["I", stim.target_x(ancilla)]

    errors = []
    for first_target in first_targets:
        for second_target in second_targets:
            for measure_target in measure_targets:
                error = []
                if first_target != "I":
                    error.append(first_target)
                if second_target != "I":
                    error.append(second_target)
                if measure_target != "I":
                    error.append(measure_target)
                if len(error) > 0:
                    errors.append(error)

    for error in errors:
        circuit.append_operation("CORRELATED_ERROR", error, ind_p)

    circuit.append_operation('M', [ancilla])
    return circuit

# Import necessary modules
from __future__ import unicode_literals
import logging
import shlex
from collections import defaultdict
import six
from docker import utils as docker_utils
from ....functional import resolve_value
from ....utils import format_image_tag
from ...input import ItemType, CmdCheck, ExecPolicy
from ...policy.utils import get_instance_volumes, extract_user, init_options
from .. import StateFlags, State
from ..base import ContainerBaseState

log = logging.getLogger(__name__)

# Define container update variables
CONTAINER_UPDATE_VARS = [
    # Key in inspect output, docker-py kwarg, whether to also check create kwargs, check client for constraints support,
    # conversion function
    ('BlkioWeight', 'blkio_weight', False, False, None),
    ('CpuPeriod', 'cpu_period', False, True, None),
    ('CpuQuota', 'cpu_quota', False, True, None),
    ('CpuShares', 'cpu_shares', True, True, None),
    ('CpusetCpus', 'cpuset_cpus', False, True, None),
    ('CpusetMems', 'cpuset_mems', False, True, None),
    ('Memory', 'mem_limit', True, True, docker_utils.parse_bytes),
    ('MemoryReservation', 'mem_reservation', False, False, docker_utils.parse_bytes),
    ('MemorySwap', 'memswap_limit', True, True, docker_utils.parse_bytes),
    ('KernelMemory', 'kernel_memory', False, True, docker_utils.parse_bytes),
    ('OomKillDisable', 'oom_kill_disable', False, True, None),
    ('PidsLimit', 'pids_limit', False, True, None),
]

def _check_environment(c_config, instance_detail):
    def _parse_env():
        for env_str in instance_env:
            var_name, sep, env_val = env_str.partition('=')
            if sep:
                yield var_name, env_val

    create_options = init_options(c_config.create_options)
    if not create_options:
        return True

    instance_env = instance_detail['Config']['Env'] or []
    config_env = resolve_value(create_options.get('environment'))

    if not config_env:
        return True

    current_env = dict(_parse_env())
    log.debug("Checking environment. Config / container instance:\n%s\n%s", config_env, current_env)

    for k, v in six.iteritems(config_env):
        if current_env.get(k) != resolve_value(v):
            return False

    return True

def _strip_quotes(cmd_item):
    if len(cmd_item) >= 2:
        first, last = cmd_item[0], cmd_item[-1]
        if first in ("'", '"') and first == last:
            return cmd_item[1:-1]
    return cmd_item

def _normalize_cmd(cmd):
    if isinstance(cmd, six.string_types):
        cmd = shlex.split(cmd)
    return list(map(_strip_quotes, cmd))

def _check_cmd(c_config, instance_detail):
    create_options = init_options(c_config.create_options)
    if not create_options:
        return True

    instance_config = instance_detail['Config']
    config_cmd = resolve_value(create_options.get('command')) if create_options else None

    if config_cmd:
        instance_cmd = instance_config['Cmd'] or []
        log.debug("Checking command. Config / container instance:\n%s\n%s", config_cmd, instance_cmd)
        if _normalize_cmd(config_cmd) != instance_cmd:
            return False

    config_entrypoint = resolve_value(create_options.get('entrypoint')) if create_options else None
    if config_entrypoint:
        instance_entrypoint = instance_config['Entrypoint'] or []
        log.debug("Checking entrypoint. Config / container instance:\n%s\n%s", config_entrypoint, instance_entrypoint)

        if isinstance(config_entrypoint, six.string_types):
            if [config_entrypoint] != instance_entrypoint:
                return False
        elif list(config_entrypoint) != instance_entrypoint:
            return False

    return True

def _check_container_network_ports(container_config, client_config, instance_detail):
    if not container_config.exposes:
        return True

    instance_ports = instance_detail['NetworkSettings']['Ports'] or {}

    for port_binding in container_config.exposes:
        port = resolve_value(port_binding.exposed_port)
        i_key = port if isinstance(port, six.string_types) and '/' in port else '{0}/tcp'.format(port)
        log.debug("Looking up port %s configuration.", i_key)

        if i_key not in instance_ports:
            log.debug("Not found.")
            return False

        bind_port = resolve_value(port_binding.host_port)
        if bind_port:
            i_val = instance_ports[i_key]
            if not i_val:
                log.debug("Port is exposed but not published.")
                return False

            interface = resolve_value(port_binding.interface)
            if interface:
                bind_addr = resolve_value(client_config.interfaces.get(interface))
            else:
                bind_addr = '0.0.0.0'

            bind_config = {'HostIp': bind_addr, 'HostPort': six.text_type(bind_port)}
            log.debug("Checking port. Config / container instance:\n%s\n%s", bind_config, i_val)

            if bind_config not in i_val:
                return False

    return True

def _check_limits(container_config, instance_detail, client_config):
    constraints = client_config.constraints
    i_host_config = instance_detail['HostConfig']
    c_host_config = container_config.host_config
    c_create_options = container_config.create_options

    update_dict = {}
    needs_reset = False

    for inspect_key, config_key, check_co, check_cs, input_func in CONTAINER_UPDATE_VARS:
        if check_cs and not constraints.get(config_key):
            log.debug("Skipping check for {0} - not supported by the client.".format(config_key))
            continue

        i_value = i_host_config.get(inspect_key) or None
        c_value = c_host_config.get(config_key) or None

        if not c_value and check_co:
            c_value = c_create_options.get(config_key) or None

        if config_key == 'memswap_limit' and not c_value:
            # Has a dependent default value.
            mem = c_host_config.get('mem_limit') or c_create_options.get('mem_limit')
            if mem:
                c_value = docker_utils.parse_bytes(mem) * 2

        if c_value and input_func:
            c_value = input_func(c_value)

        if i_value or c_value:
            log.debug("Comparing host-config variable %s - Container: %s - Config: %s.", inspect_key, i_value, c_value)
            if i_value != c_value:
                if c_value is not None:
                    log.debug("Updating %s to %s.", inspect_key, c_value)
                    update_dict[config_key] = c_value
                else:
                    # The API implementation (maybe just docker-py) will discard empty default values.
                    log.debug("Host-config variable %s cannot be reset to default, suggesting container reset.",
                              inspect_key)
                    needs_reset = True

    return update_dict, needs_reset

def _check_restart_policy(container_config, instance_detail):
    c_restart_policy = container_config.host_config.get('restart_policy')
    i_restart_policy = instance_detail['HostConfig'].get('RestartPolicy')

    if c_restart_policy and i_restart_policy:
        cr_name = c_restart_policy.get('Name')
        ir_name = i_restart_policy.get('Name')

        if cr_name == 'on-failure':
            if ir_name == 'on-failure':
                rp_update = c_restart_policy.get('MaximumRetryCount', 0) != i_restart_policy.get('MaximumRetryCount', 0)
            else:
                rp_update = True
        else:
            rp_update = cr_name != ir_name
    else:
        rp_update = False

    if rp_update:
        return {'restart_policy': c_restart_policy}

    return {}

class UpdateContainerState(ContainerBaseState):
    """
    Extends the base state by checking the current instance detail against the container configuration and volumes
    other containers. Also checks if the container image matches the configured image's id.
    """
    def __init__(self, *args, **kwargs):
        super(UpdateContainerState, self).__init__(*args, **kwargs)
        self.volume_checker = None
        self.endpoint_registry = None
        self.current_commands = None

    def _check_links(self):
        instance_links = self.detail['HostConfig']['Links'] or []
        link_dict = defaultdict(set)

        for host_link in instance_links:
            link_name, __, link_alias = host_link.partition(':')
            link_dict[link_name[1:]].add(link_alias.rpartition('/')[2])

        for link in self.config.links:
            instance_aliases = link_dict.get(self.policy.cname(self.config_id.map_name, link.container))
            config_alias = link.alias or self.policy.get_hostname(link.container)

            if not instance_aliases or config_alias not in instance_aliases:
                log.debug("Checked link %s - could not find alias %s", link.container, config_alias)
                return False

            log.debug("Checked link %s - found alias %s", link.container, config_alias)

        return True

    def _check_commands(self, check_option):
        def _find_full_command(f_cmd, f_user):
            for __, c_user, c_cmd in self.current_commands:
                if c_user == f_user and c_cmd == f_cmd:
                    log.debug("Command for user %s found: %s.", c_user, c_cmd)
                    return True
            log.debug("Command for user %s not found: %s.", f_user, f_cmd)
            return False

        def _find_partial_command(f_cmd, f_user):
            for __, c_user, c_cmd in self.current_commands:
                if c_user == f_user and f_cmd in c_cmd:
                    log.debug("Command for user %s found: %s.", c_user, c_cmd)
                    return True
            log.debug("Command for user %s not found: %s.", f_user, f_cmd)
            return False

        def _cmd_running(cmd, cmd_user):
            res_cmd = resolve_value(cmd)
            if isinstance(res_cmd, (list, tuple)):
                res_cmd = ' '.join(res_cmd)
            if cmd_user is not None:
                res_user = resolve_value(cmd_user)
            else:
                res_user = extract_user(self.config.user)
            if res_user is None:
                res_user = 'root'
            log.debug("Looking up %s command for user %s: %s", check_option, res_user, res_cmd)
            return cmd_exists(res_cmd, res_user)

        if not self.config.exec_commands:
            return None

        if not self.current_commands:
            log.debug("No running exec commands found for container.")
            return self.config.exec_commands

        log.debug("Checking commands for container %s.", self.container_name)

        if check_option == CmdCheck.FULL:
            cmd_exists = _find_full_command
        elif check_option == CmdCheck.PARTIAL:
            cmd_exists = _find_partial_command
        else:
            log.debug("Invalid check mode %s - skipping.", check_option)
            return None

        return [exec_cmd for exec_cmd in self.config.exec_commands
                if not _cmd_running(exec_cmd.cmd, exec_cmd.user) and exec_cmd.policy != ExecPolicy.INITIAL]

    def _check_volumes(self):
        instance_volumes = get_instance_volumes(self.detail, self.client_config.features['volumes'])
        return self.volume_checker.check(self.config_id, self.container_map, self.config, instance_volumes)

    def _check_container_network_mode(self):
        net_mode = self.config.network_mode or 'default'
        if (net_mode == 'none') != self.detail['Config'].get('NetworkDisabled', False):
            return False

        instance_mode = self.detail['HostConfig'].get('NetworkMode') or 'default'

        if isinstance(net_mode, tuple):
            ref_mode = 'container:{0}'.format(self.policy.cname(self.config_id.map_name, *net_mode))
        else:
            ref_mode = net_mode

        return ref_mode == instance_mode

    def set_defaults(self):
        super(UpdateContainerState, self).set_defaults()
        self.current_commands = None

    def inspect(self):
        super(UpdateContainerState, self).inspect()
        if self.detail and self.detail['State']['Running'] and self.config_id.config_type == ItemType.CONTAINER:
            check_exec_option = self.options['check_exec_commands']
            if check_exec_option and check_exec_option != CmdCheck.NONE and self.config.exec_commands:
                self.current_commands = self.client.top(self.detail['Id'], ps_args='-eo pid,user,args')['Processes']

    def get_state(self):
        base_state, state_flags, extra = super(UpdateContainerState, self).get_state()

        if base_state == State.ABSENT or state_flags & StateFlags.NEEDS_RESET:
            return base_state, state_flags, extra

        config_id = self.config_id
        c_image_id = self.detail['Image']

        if config_id.config_type == ItemType.VOLUME:
            volumes = get_instance_volumes(self.detail, False)
            if volumes:
                default_paths = self.policy.default_volume_paths[config_id.map_name]
                if self.container_map.use_attached_parent_name:
                    volume_name = '{0}.{1}'.format(config_id.config_name, config_id.instance_name)
                else:
                    volume_name = config_id.instance_name

                mapped_path = resolve_value(default_paths[volume_name])
                self.volume_checker.register_attached(volume_name, mapped_path, volumes.get(mapped_path))
        else:
            image_name = format_image_tag(self.container_map.get_image(self.config.image or config_id.config_name))
            images = self.policy.images[self.client_name]
            ref_image_id = images.get(image_name)

            if c_image_id != ref_image_id and (not self.config.persistent or self.options['update_persistent']):
                state_flags |= StateFlags.IMAGE_MISMATCH

            if not self._check_volumes():
                state_flags |= StateFlags.VOLUME_MISMATCH

            if not self._check_links():
                state_flags |= StateFlags.MISSING_LINK

            if not (_check_environment(self.config, self.detail) and _check_cmd(self.config, self.detail) and
                    _check_container_network_ports(self.config, self.client_config, self.detail)):
                state_flags |= StateFlags.MISC_MISMATCH

            if base_state == State.RUNNING:
                check_exec_option = self.options['check_exec_commands']
                if check_exec_option:
                    missing_exec_cmds = self._check_commands(check_exec_option)
                    if missing_exec_cmds:
                        state_flags |= StateFlags.EXEC_COMMANDS
                        extra['exec_commands'] = missing_exec_cmds

            if self.endpoint_registry:  # Client supports networking.
                net_s_flags, net_extra = self.endpoint_registry.check_container_config(config_id, self.config,
                                                                                       self.detail)
                state_flags |= net_s_flags
                extra.update(net_extra)
            elif not self._check_container_network_mode():
                state_flags |= StateFlags.MISC_MISMATCH

            hc_update, hc_needs_reset = _check_limits(self.config, self.detail, self.client_config)
            restart_policy_update = _check_restart_policy(self.config, self.detail)
            hc_update.update(restart_policy_update)

            if not self.client_config.features['container_update_restart_policy'] and restart_policy_update:
                hc_needs_reset = True

            if hc_update:
                if not self.client_config.features['container_update']:
                    hc_needs_reset = True
                state_flags |= StateFlags.HOST_CONFIG_UPDATE
                extra['update_container'] = hc_update

            if hc_needs_reset:
                if not self.options['skip_limit_reset']:
                    state_flags |= StateFlags.MISC_MISMATCH
                else:
                    log.info("Container has a different host-config that cannot be update, but is not reset.")

        return base_state, state_flags, extra

