        "b": pd.Series(index=["b"], data=[2]),
        "c": pd.DataFrame({"c": [3]}),
        "d": pd.Series(data=[4], name="e", index=[4]),
    }

    result = _flatten_index(data)
    expected = pd.Series(index=["a_0", "b_b", "c_c_0", "d_4"], data=[1, 2, 3, 4])

    assert result.equals(expected)


