import shutil
from collections import OrderedDict
import torch
from torch import distributed as dist

# Move data to specified device
def data2device(mmdata, device):
    item = dict()
    item = {
        key: val.to(device)
        for key, val in mmdata.items() if torch.is_tensor(val)
    }
    item['deeptext'] = {
        key: val.to(device)
        for key, val in mmdata['deeptext'].items()
    }
    return item

# Save model checkpoint and best model
def save_checkpoint(state,
                    is_best,
                    checkpoint_dir,
                    filename='checkpoint.pth.tar'):
    if (not torch.distributed.is_initialized()
        ) or torch.distributed.get_rank() == 0:
        file_path = os.path.join(checkpoint_dir, filename)
        torch.save(state, file_path)
        if is_best:
            shutil.copyfile(file_path,
                            os.path.join(checkpoint_dir, 'model_best.pth.tar'))

# Reduce tensor across distributed processes
def reduce_tensor(tensor):
    rt = tensor.clone()
    dist.all_reduce(rt, op=dist.ReduceOp.SUM)
    rt /= (
        torch.distributed.get_world_size()
        if torch.distributed.is_initialized() else 1)
    return rt

# Adjust learning rate with step decay
def adjust_learning_rate(optimizer, epoch, args):
    """Sets the learning rate to the initial LR decayed by 10 every 30
    epochs."""
    lr = args.lr * (0.1**(epoch // 20))
    for param_group in optimizer.param_groups:
        param_group['lr'] = lr
    return lr

# Load model checkpoint
def load_checkpoint(model, checkpoint_path, log_info=True):
    if os.path.isfile(checkpoint_path):
        checkpoint = torch.load(checkpoint_path, map_location='cuda:0')
        if isinstance(checkpoint, dict) and 'state_dict' in checkpoint:
            new_state_dict = OrderedDict()
            for k, v in checkpoint['state_dict'].items():
                name = k[7:] if k.startswith('module') else k
                new_state_dict[name] = v
            model.load_state_dict(new_state_dict, strict=False)
        else:
            model.load_state_dict(checkpoint, strict=False)
    else:
        raise FileNotFoundError()

# Resume training from checkpoint
def resum_checkpoint(args, log_info=True):
    if os.path.isfile(args.resume):
        print("=> loading checkpoint '{}'".format(args.resume))
        checkpoint = torch.load(
            args.resume,
            map_location=lambda storage, loc: storage.cuda(args.gpu))
        start_epoch = checkpoint['epoch']
        best_prec1 = checkpoint['best_prec1']
        model_state = checkpoint['state_dict']
        optimizer_state = checkpoint['optimizer']
        if 'state_dict_ema' in checkpoint:
            model_state_ema = checkpoint['state_dict_ema']
        else:
            model_state_ema = None
        print("=> loaded checkpoint '{}' (epoch {})".format(
            args.resume, checkpoint['epoch']))
        if start_epoch >= args.epochs:
            print(
                f'Launched training for {args.epochs}, checkpoint already run {start_epoch}'
            )
            exit(1)
    else:
        print("=> no checkpoint found at '{}'".format(args.resume))
        model_state = None
        model_state_ema = None
        optimizer_state = None
    return model_state, model_state_ema, optimizer_state, start_epoch, best_prec1

# Test/load checkpoint for inference
def test_load_checkpoint(args):
    if os.path.isfile(args.resume):
        print("=> loading checkpoint '{}'".format(args.resume))
        checkpoint = torch.load(
            args.resume,
            map_location=lambda storage, loc: storage.cuda(args.gpu))
        checkpoint = {
            k[len('module.'):] if k.startswith('module.') else k: v
            for k, v in checkpoint.items()
        }
        optimizer_state = checkpoint['optimizer']
        model_state = checkpoint['state_dict']
        if 'state_dict_ema' in checkpoint:
            model_state_ema = checkpoint['state_dict_ema']
        else:
            model_state_ema = None
    else:
        print("=> no checkpoint found at '{}'".format(args.resume))
        model_state = None
        model_state_ema = None
        optimizer_state = None
    return model_state, model_state_ema, optimizer_state

# Get current learning rate from optimizer
def get_lr(optimizer):
    for param_group in optimizer.param_groups:
        return param_group['lr']

import logging
import os
from typing import Text

import rasa.utils.io as io_utils

logger = logging.getLogger(__name__)


def transform_entity_synonyms(synonyms, known_synonyms=None):
    """Transforms the entity synonyms into a text->value dictionary"""
    # Initialize entity synonyms dictionary
    entity_synonyms = known_synonyms if known_synonyms else {}

    # Process each synonym entry
    for s in synonyms:
        if "value" in s and "synonyms" in s:
            for synonym in s["synonyms"]:
                entity_synonyms[synonym] = s["value"]

    return entity_synonyms


def check_duplicate_synonym(entity_synonyms, text, syn, context_str=""):
    # Check for duplicate synonyms with conflicting values
    if text in entity_synonyms and entity_synonyms[text] != syn:
        logger.warning(
            "Found inconsistent entity synonyms while {0}, "
            "overwriting {1}->{2} "
            "with {1}->{3} during merge"
            "".format(context_str, text, entity_synonyms[text], syn)
        )


def get_file_format(resource_name: Text) -> Text:
    from rasa.nlu.training_data import loading

    # Validate resource exists
    if resource_name is None or not os.path.exists(resource_name):
        raise AttributeError("Resource '{}' does not exist.".format(resource_name))

    # List files and determine formats
    files = io_utils.list_files(resource_name)
    file_formats = list(map(lambda f: loading.guess_format(f), files))

    # Default to json if no files found
    if not file_formats:
        return "json"

    # Determine format based on first file and consistency check
    fformat = file_formats[0]
    if fformat == "md" and all(f == fformat for f in file_formats):
        return fformat

    return "json"

# SI Unit conversion functions

from __future__ import annotations
from ..TypesHelper import Number_t
from . import SIUnits
from ..prefixes import SIPrefixes


def celsiusUnit(value: Number_t, *, power: Number_t = 1):
    # Convert Celsius to Kelvin
    return SIUnits.kelvinUnit(value + 273.15, power=power)


def hertzUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    return value / SIUnits.secondUnit(1, exp10=-exp, power=power)


def newtonUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=exp, power=power)
    result /= SIUnits.secondUnit(1, power=2 * power)
    return result


def pascalUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = SIUnits.kilogramUnit(value, exp10=exp, power=power) / SIUnits.meterUnit(1, power=power)
    result /= SIUnits.secondUnit(1, power=2 * power)
    return result


def jouleUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=exp, power=2 * power)
    result /= SIUnits.secondUnit(1, power=2 * power)
    return result


def wattUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=exp, power=2 * power)
    result /= SIUnits.secondUnit(1, power=3 * power)
    return result


def coulombUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = SIUnits.secondUnit(value, power=power) * SIUnits.ampereUnit(1, exp10=exp, power=power)
    return result


def voltUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=exp, power=2 * power)
    result /= (SIUnits.secondUnit(1, power=3 * power) * SIUnits.ampereUnit(1, power=power))
    return result


def faradUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = coulombUnit(value, exp10=exp, power=power) / voltUnit(1, power=power)
    return result


def ohmUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = voltUnit(value, exp10=exp, power=power) / SIUnits.ampereUnit(1, power=power)
    return result


def siemensUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = value / ohmUnit(1, exp10=-exp, power=power)
    return result


def weberUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = jouleUnit(value, exp10=exp, power=power) / SIUnits.ampereUnit(1, power=power)
    return result


def teslaUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = SIUnits.kilogramUnit(value, exp10=exp, power=power) / SIUnits.ampereUnit(1, power=power)
    result /= SIUnits.secondUnit(1, power=2 * power)
    return result


def henryUnit(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1):
    exp = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(exp, int):
        raise RuntimeError()
    result = voltUnit(value, exp10=exp, power=power) * SIUnits.secondUnit(1, power=power)
    result /= SIUnits.ampereUnit(1, power=power)
    return result

