# Import necessary types and classes from opentrons
from opentrons.protocol_api.labware import Well
from opentrons.types import Location
from typing import Union, Sequence, List, Any

# Define CommandLocation type alias
CommandLocation = Union[Location, None, Sequence, Well]

def listify(location: Any) -> List:
    # Convert location to list if not already a list
    if isinstance(location, list):
        try:
            # Recursively process first element if list is non-empty
            return listify(location[0])
        except IndexError:
            # Return list containing original empty list if index error occurs
            return [location]
    else:
        # Wrap non-list item in a list
        return [location]

def _stringify_new_loc(loc: Union[Location, Well]) -> str:
    # Convert Location or Well object to string representation
    if isinstance(loc, Location):
        if loc.labware.is_empty:
            # Return point coordinates as string if labware is empty
            return str(loc.point)
        else:
            # Return labware representation otherwise
            return repr(loc.labware)
    elif isinstance(loc, Well):
        # Return Well string representation
        return str(loc)
    else:
        # Raise TypeError for unsupported types
        raise TypeError(loc)

def stringify_location(location: CommandLocation) -> str:
    # Process location(s) through listify and stringify functions
    loc_str_list = [_stringify_new_loc(loc) for loc in listify(location)]
    # Join string representations with comma and space
    return ", ".join(loc_str_list)

from typing import Tuple
import numpy as np
import torch
from torch import matmul

def regularize_matrix(mat, regularization, relative_to_diag_mean=True):
    # Regularize matrix by adding diagonal term
    if regularization > 0:
        assert len(set(mat.shape[-2:])) == 1, "matrix must be square"

        if relative_to_diag_mean:
            diag_mean = batch_diag(mat).mean(dim=-1, keepdim=True)
            diag_regularization = batch_diag_matrix(
                torch.ones_like(mat[..., 0]) * diag_mean * regularization
            )
        else:
            diag_regularization = batch_diag_matrix(
                torch.ones_like(mat[..., 0]) * regularization
            )

        regularized_mat = mat + diag_regularization
    else:
        regularized_mat = mat

    return regularized_mat


def cholesky(
    mat,
    upper=False,
    out=None,
    regularization=0.0,
    initial_try_regularization=1e-6,
    max_regularization=1e2,
    step_factor=10,
    warning=True,
):
    # Cholesky decomposition with automatic regularization
    if regularization > 0 and warning:
        warnings.warn(f"regularizing matrix with value: {regularization}")
        regularized_mat = regularize_matrix(
            mat=mat, regularization=regularization, relative_to_diag_mean=True
        )
    else:
        regularized_mat = mat

    try:
        # TODO: there is currently a magma bug that occurs for certain batch sizes.
        #  github issue: https://github.com/pytorch/pytorch/issues/26996
        #  see also https://discuss.pytorch.org/t/cuda-illegal-memory-access-when-using-batched-torch-cholesky/51624/8
        #  for the temporary hack used below
        # device = regularized_mat.device
        # return torch.cholesky(regularized_mat.to("cpu"), upper=upper, out=out).to(device)
        # TODO: bug still exists, but only for certain batch sizes. This slows down too much
        return torch.cholesky(regularized_mat, upper=upper, out=out)
    except RuntimeError:
        if torch.isnan(mat).any():
            raise ValueError("NaN detected in input mat.")
        else:
            regularization = max(
                regularization * step_factor, initial_try_regularization
            )
            if regularization > max_regularization:
                raise ValueError(
                    f"attempted regularization greater than "
                    f"max_regularization: {max_regularization}."
                )
            else:
                return cholesky(
                    mat=mat,
                    upper=upper,
                    out=out,
                    regularization=regularization,
                )


def cov_and_chol_from_invcholesky_param(Linv_tril, Linv_logdiag):
    # Compute covariance and Cholesky factor from inverse Cholesky parameters
    L = torch.inverse(
        torch.tril(Linv_tril, -1) + batch_diag_matrix(torch.exp(Linv_logdiag))
    )
    return matmul(L, L.transpose(-1, -2)), L


def cov_from_invcholesky_param(Linv_tril, Linv_logdiag):
    # Compute covariance from inverse Cholesky parameters
    return cov_and_chol_from_invcholesky_param(
        Linv_tril=Linv_tril, Linv_logdiag=Linv_logdiag
    )[0]


def inv_from_invcholesky_param(Linv_tril, Linv_logdiag):
    # Compute inverse from inverse Cholesky parameters
    Linv = torch.tril(Linv_tril, -1) + batch_diag_matrix(
        torch.exp(Linv_logdiag)
    )
    return matmul(Linv.transpose(-1, -2), Linv)


def batch_cholesky_inverse(Lmat):
    """
    performs torch.cholesky_inverse for matrices with leading
    match dimensions.
    Note that torch can do batched torch.cholesky but not torch.cholesky_inverse
    """
    Lmatinv = torch.inverse(Lmat)
    return matmul(Lmatinv.transpose(-1, -2), Lmatinv)


def batch_diag(mat):
    # Extract diagonal elements from batched matrices
    return mat[..., torch.arange(mat.shape[-2]), torch.arange(mat.shape[-1])]


def batch_diag_matrix(diagonal):
    # Create batched diagonal matrices from diagonal vectors
    N = diagonal.shape[-1]
    shape = diagonal.shape[:-1] + (N, N)
    device, dtype = diagonal.device, diagonal.dtype
    result = torch.zeros(shape, dtype=dtype, device=device)
    indices = torch.arange(result.numel(), device=device).reshape(shape)
    indices = indices.diagonal(dim1=-2, dim2=-1)
    result.view(-1)[indices] = diagonal
    return result


def symmetrize(mat):
    # Symmetrize matrix by averaging with its transpose
    return 0.5 * (mat + mat.transpose(-1, -2))


def matvec(mat, vec):
    # Matrix-vector multiplication handling different dimensionalities
    if vec.ndim == 1:
        return torch.matmul(mat, vec)
    elif mat.ndim == 2:
        return torch.matmul(vec, mat.transpose(1, 0))
    else:
        return torch.matmul(mat, vec[..., None])[..., 0]


def get_numerical_precision(x):
    # Get machine epsilon for various numeric types
    if isinstance(x, float):
        eps = np.finfo(np.array(x).dtype).eps
    elif isinstance(x, (torch.Tensor,)):
        eps = torch.finfo(x.dtype).eps
    elif isinstance(x, (np.ndarray, np.generic)):
        eps = np.finfo(x.dtype).eps
    else:
        raise ValueError("unknown dtype of {}".format(x))
    return eps


def stable_log(x, eps=None):
    # Compute logarithm with numerical stability
    eps = get_numerical_precision(x) if eps is None else eps
    return torch.log(x + eps)


# def kron(A, B):
#     res_vec = torch.matmul(A[:, None, :, None], B[None, :, None, :])
#     return res_vec.reshape([A.shape[0] * B.shape[0], A.shape[1] * B.shape[1]])


def kron(A, B):
    """
    Kronecker Product.
    Works with batch dimemsion(s) - requires both A and B have same batch dims.
    """
    A_shp, B_shp = A.shape, B.shape
    assert A_shp[:-2] == B_shp[:-2]

    kron_block = torch.matmul(
        A[..., :, None, :, None], B[..., None, :, None, :]
    )
    kron = kron_block.reshape(
        A_shp[:-2] + (A_shp[-2] * B_shp[-2], A_shp[-1] * B_shp[-1],)
    )
    return kron


def vectorize_normal_dist_params(m, V):
    # Vectorize mean and lower-triangular part of covariance matrix
    indices = torch.tril_indices(row=V.shape[-2], col=V.shape[-1], offset=0)
    V_vectorised = V[..., indices[0], indices[1]]
    return torch.cat((m, V_vectorised), dim=-1)


def logmeanexp(self: torch.Tensor, dim: int, keepdim: bool = False):
    # Compute log-mean-exp in a numerically stable way
    return torch.logsumexp(self, dim=dim, keepdim=keepdim) - np.log(
        self.shape[dim]
    )


def make_block_diagonal(mats: Tuple[torch.Tensor]) -> torch.Tensor:
    # Construct block diagonal matrix from list of matrices
    if not isinstance(mats, (list, tuple)):
        raise Exception("provide list or tuple")
    elif len(mats) > 1:
        off_diag_upper_right = torch.zeros(
            mats[-2].shape[:-1] + (mats[-1].shape[-1],),
            dtype=mats[-1].dtype,
            device=mats[-1].device,
        )
        off_diag_lower_left = torch.zeros(
            mats[-1].shape[:-1] + (mats[-2].shape[-1],),
            dtype=mats[-1].dtype,
            device=mats[-1].device,
        )
        block_diagonal = torch.cat(
            [
                torch.cat([mats[-2], off_diag_upper_right], dim=-1),
                torch.cat([off_diag_lower_left, mats[-1]], dim=-1),
            ],
            dim=-2,
        )
        return make_block_diagonal(tuple(mats[:-2]) + (block_diagonal,))
    else:  # final recursion
        return mats[0]

# Plugin entry point for Electrum integration with Haros
from __future__ import unicode_literals

import os
from jinja2 import Environment, PackageLoader

from .analyzer import model_check
from .electrum2haros import parse_output, render_result
from .haros2electrum import config2model, render_model

###############################################################################
# Plugin Entry Point
###############################################################################
PLUGIN = 'haros_plugin_electrum'


def configuration_analysis(iface, config):
    # Skip analysis if required conditions are not met
    if (not config.launch_commands 
            or len(config.nodes.enabled) < 2
            or not config.hpl_properties):
        return

    settings = config.user_attributes.get(PLUGIN, {})

    try:
        _validate_settings(settings)
    except PluginSettingsError as e:
        iface.log_error(e.message)

    jar_path = _get_jar_path(settings)
    scopes = _get_scopes(settings)
    jinja = Jinja()

    try:
        # Generate Electrum model from configuration
        model = config2model(config)
        ele_src = render_model(jinja, model)

        # Write model to file
        filename = 'model_{}.ele'.format('_'.join(config.name.split()))
        with open(filename, 'w') as f:
            f.write(ele_src)
            f.write('\n')

        iface.export_file(filename)

        # Run model checking and process results
        output = model_check(jar_path, ele_src, scopes)
        result = parse_output(output, config)
        html = render_result(jinja, result)

        iface.report_runtime_violation('counterexample', html, result.resources)

    except Exception as e:
        iface.log_error(e.message)


def _validate_settings(settings):
    jar = settings.get('jar')

    if not jar:
        raise PluginSettingsError.missing_jar()

    if not isinstance(jar, dict):
        raise PluginSettingsError.jar_not_dict()

    if not 'path' in jar and not 'env' in jar:
        raise PluginSettingsError.missing_jar_path()

    if 'env' in jar and not os.environ.get(jar['env']):
        raise PluginSettingsError.missing_env_var(jar['env'])

    scopes = settings.get('scope')

    if scopes:
        for key in ('time', 'msgs', 'values'):
            n = scopes.get(key)
            if n is not None and (not isinstance(n, int) or n < 0):
                raise PluginSettingsError.invalid_scope(key, n)


def _get_jar_path(settings):
    jar = settings['jar']
    path = jar.get('path')

    if path is None:
        env_var = jar['env']
        path = os.environ[env_var]

    return path


def _get_scopes(settings):
    scopes = settings.get('scope', {})

    if not 'time' in scopes:
        scopes['time'] = 10

    if not 'msgs' in scopes:
        scopes['msgs'] = 9

    if not 'values' in scopes:
        scopes['values'] = 4

    return scopes


###############################################################################
# Data Structures
###############################################################################
def Jinja():
    return Environment(
        loader=PackageLoader(PLUGIN, 'templates'),
        line_statement_prefix=None,
        line_comment_prefix=None,
        trim_blocks=True,
        lstrip_blocks=True,
        autoescape=False
    )


class PluginSettingsError(Exception):
    @classmethod
    def missing_jar(cls):
        return cls('missing `jar` field in plugin settings')

    @classmethod
    def jar_not_dict(cls):
        return cls('expected a dictionary under the `jar` setting')

    @classmethod
    def missing_jar_path(cls):
        return cls('missing .jar path; expected one of `jar:path` or `jar:env`')

    @classmethod
    def missing_env_var(cls, var):
        return cls("missing '{}' env. variable with .jar path".format(var))

    @classmethod
    def invalid_scope(cls, key, n):
        return cls("invalid scope value for '{}': {}".format(key, n))

# Tezos chain generation script
import os
import random
import string
import subprocess
import sys
from datetime import datetime, timezone

import yaml

from ._version import get_versions

sys.path.insert(0, "tqchain")
__version__ = get_versions()["version"]


def run_docker(image, entrypoint, *args):
    # Run docker command and capture output
    return subprocess.check_output(
        "docker run --entrypoint %s --rm %s %s" % (entrypoint, image, " ".join(args)),
        stderr=subprocess.STDOUT,
        shell=True,
    )


def extract_key(keys, index: int) -> bytes:
    # Extract key from tezos-client output
    return keys[index].split(b":")[index].strip().decode("ascii")


def gen_key(image):
    # Generate new tezos key pair using docker container
    keys = run_docker(
        image,
        "sh",
        "-c",
        "'/usr/local/bin/tezos-client --protocol PsDELPH1Kxsx gen keys mykey && /usr/local/bin/tezos-client --protocol PsDELPH1Kxsx show address mykey -S'",
    ).split(b"\n")

    return {
        "public": extract_key(keys, 1),
        "secret": extract_key(keys, 2)
    }


def get_genesis_vanity_chain_id(seed_len=16):
    # Generate a vanity chain ID using flextesa
    seed = "".join(
        random.choice(string.ascii_uppercase + string.digits) for _ in range(seed_len)
    )
    FLEXTESA = "registry.gitlab.com/tezos/flextesa:01e3f596-run"

    return (
        run_docker(
            FLEXTESA,
            "flextesa",
            "vani",
            '""',
            "--seed",
            seed,
            "--first",
            "--machine-readable",
            "csv",
        )
        .decode("utf-8")
        .split(",")[1]
    )


# Chain configuration constants
CHAIN_CONSTANTS = {
    "number_of_nodes": {
        "help": "number of peers in the cluster",
        "default": 1,
        "type": int,
    },
    "number_of_bakers": {
        "help": "number of bakers in the cluster",
        "default": 1,
        "type": int,
    },
    "zerotier_network": {"help": "Zerotier network id for external chain access"},
    "zerotier_token": {"help": "Zerotier token for external chain access"},
    "bootstrap_peer": {"help": "peer ip to join"},
    "docker_image": {
        "help": "Version of the Tezos docker image",
        "default": "tezos/tezos:v8-release",
    },
    "rpc_auth": {
        "help": "Should spin up an RPC authentication server",
        "action": "store_true",
        "default": False,
    },
}


def get_args():
    # Parse command line arguments
    parser = argparse.ArgumentParser(
        description="Generate helm values for use with the tezos-chain helm chart"
    )
    parser.add_argument(
        "--version",
        action="version",
        version="%(prog)s {version}".format(version=__version__),
    )
    parser.add_argument("chain_name", action="store", help="Name of your chain")

    for k, v in CHAIN_CONSTANTS.items():
        parser.add_argument(*["--" + k.replace("_", "-")], **v)

    return parser.parse_args()


def main():
    args = get_args()

    # Validate number of nodes
    if args.number_of_nodes < 1:
        print(
            f"Invalid argument --number-of-nodes {args.number_of_nodes}, must be 1 or more"
        )
        exit(1)

    # Validate number of bakers
    if args.number_of_bakers < 1:
        print(
            f"Invalid argument --number-of-bakers {args.number_of_bakers}, must be 1 or more"
        )
        exit(1)

    # Prepare bootstrap accounts
    bootstrap_accounts = [f"baker{n}" for n in range(args.number_of_bakers)]

    # Base configuration constants
    base_constants = {
        "chain_name": args.chain_name,
        "images": {
            "tezos": args.docker_image,
        },
        "genesis": {
            "genesis_chain_id": get_genesis_vanity_chain_id(),
            "bootstrap_timestamp": datetime.utcnow()
            .replace(tzinfo=timezone.utc)
            .isoformat(),
        },
        "zerotier_in_use": bool(args.zerotier_network),
        "rpc_auth": args.rpc_auth,
        "zerotier_config": {
            "zerotier_network": args.zerotier_network,
            "zerotier_token": args.zerotier_token,
        },
    }

    # Generate account keys
    accounts = {"secret": [], "public": []}
    for account in bootstrap_accounts:
        keys = gen_key(args.docker_image)
        for key_type in keys:
            accounts[key_type].append(
                {
                    "name": account,
                    "key": keys[key_type],
                    "type": key_type,
                }
            )

    # Configure nodes
    creation_nodes = [
        {"bake_for": f"baker{n}"} for n in range(args.number_of_bakers)
    ] + [{} for n in range(args.number_of_nodes - args.number_of_bakers)]

    invitation_nodes = [{}]
    bootstrap_peers = [args.bootstrap_peer] if args.bootstrap_peer else []

    # Create creation constants
    creation_constants = {
        **base_constants,
        "accounts": accounts["secret"],
        "is_invitation": False,
        "bootstrap_peers": bootstrap_peers,
        "nodes": creation_nodes,
    }

    # Create invitation constants
    invitation_constants = {
        **base_constants,
        "accounts": accounts["public"],
        "is_invitation": True,
        "bootstrap_peers": bootstrap_peers,
        "nodes": invitation_nodes,
    }

    # Remove rpc_auth from invitation constants
    invitation_constants.pop("rpc_auth")

    # Write YAML files
    files_path = f"{os.getcwd()}/{args.chain_name}"

    with open(f"{files_path}_values.yaml", "w") as yaml_file:
        yaml.dump(creation_constants, yaml_file)
        print(f"Wrote chain creation constants to {files_path}_values.yaml")

    with open(f"{files_path}_invite_values.yaml", "w") as yaml_file:
        yaml.dump(invitation_constants, yaml_file)
        print(f"Wrote chain invitation constants to {files_path}_invite_values.yaml")


if __name__ == "__main__":
    main()

