from .. import types
from .schedule import Stage, create_schedule

def create_scheme(inputs, func):
    """Create a quantization scheme."""
    # Ensure inputs is a list
    if not isinstance(inputs, list):
        inputs = [inputs]

    return Scheme(inputs, func)

def create_schedule_from_scheme(scheme, name=""):
    """Create a schedule from a scheme."""
    return create_schedule(scheme.inputs, func=None, name=name)

class Scheme(object):
    """A quantization scheme."""

    def __init__(self, inputs, func):
        self.inputs = inputs
        self.func = func

        # Execute function and attach stages to it
        ret = func(*inputs)

        # Attach operations as attributes to the function
        for op, stage in Stage._mapping:
            func.__setattr__(op.name, op)

    def downsize(self, inputs, dtype):
        """Downsize a (list of) tensor to the specified integer type."""
        # Validate dtype
        if not isinstance(dtype, (types.Int, types.UInt)):
            raise RuntimeError("Downsize to non-integer type is not allowed")

        # Ensure inputs is a list
        if not isinstance(inputs, list):
            inputs = [inputs]

        # Update dtype for each tensor
        for tensor in inputs:
            tensor.dtype = dtype

    def quantize(self, inputs, dtype):
        """Quantize a (list of) tensor to the specified fixed-point type."""
        # Validate dtype
        if not isinstance(dtype, (types.Fixed, types.UFixed)):
            raise RuntimeError("Quantize to integer type is not allowed")

        # Ensure inputs is a list
        if not isinstance(inputs, list):
            inputs = [inputs]

        # Update dtype for each tensor
        for tensor in inputs:
            tensor.dtype = dtype

# Import necessary modules
from pathlib import Path
from typing import Dict, List
import toml

# Dataclass for journal configuration
@dataclass
class JournalConfiguration:
    """Used to represent configuration for a journal"""
    name: str
    path: Path

    def __str__(self) -> str:
        return f"{self.name} at path: {self.path}"

    def to_dict(self) -> dict:
        """Convert class to dict representation for saving to disk as toml"""
        return {"path": str(self.path)}

# Dataclass for Walden configuration
@dataclass
class WaldenConfiguration:
    """Used to represent configuration file for walden"""
    config_path: Path
    default_journal_path: Path
    journals: Dict[str, JournalConfiguration]

    def save(self):
        """Write current configuration to disk"""
        # Build journal configuration dictionary
        config = {
            journal_name: journal_info.to_dict()
            for journal_name, journal_info in self.journals.items()
        }

        # Add top-level paths
        config["config_path"] = str(self.config_path)
        config["default_journal_path"] = str(self.default_journal_path)

        # Write to disk using TOML format
        self.config_path.write_text(toml.dumps({"walden": config}))

