def calc_17(values: list[int]) -> int:
    # Initialize total to zero
    total: int = 0

    # Iterate through each value in the list
    for v in values:
        if v % 2 == 0:
            # Add even numbers directly
            total += v
        else:
            # Double odd numbers before adding
            total += v * 2

    return total

