def _resolve_call_name(node: ast.Call):
    """
    Resolve the full qualified name of a function call.
    Handles chained attributes like 'module.Class.method'.
    """
    func = node.func
    parts = []

    # Extract attribute chain from right to left
    while isinstance(func, ast.Attribute):
        parts.append(func.attr)
        func = func.value

    # Add the base name if it's a Name node
    if isinstance(func, ast.Name):
        parts.append(func.id)
        parts.reverse()
        return ".".join(parts)

    return None


class TaintVisitor(ast.NodeVisitor):
    """
    AST visitor that tracks taint flow through variables and expressions.
    Used to detect potential security vulnerabilities by tracking untrusted input.
    """

    def __init__(self, file_path, findings, sanitizers=None):
        self.file_path = file_path
        self.findings = findings
        self.env_stack = [{}]  # Variable environment stack
        self.sources = {"input", "request"}  # Known sources of untrusted data
        self.request_obj = "request"  # Request object identifier
        self._symbol_stack = ["<module>"]  # Symbol scope stack
        self.sanitizers = sanitizers or set()  # Set of known sanitizing functions

    def _current_symbol(self):
        """Get the current symbol (function/class/module) name."""
        if self._symbol_stack:
            return self._symbol_stack[-1]
        else:
            return "<module>"

    def _push(self):
        """Push a new variable scope onto the stack."""
        self.env_stack.append({})

    def _pop(self):
        """Pop the current variable scope from the stack."""
        if self.env_stack:
            self.env_stack.pop()

    def _set(self, name, tainted):
        """Mark a variable as tainted (untrusted) in the current scope."""
        if not self.env_stack:
            self._push()
        self.env_stack[-1][name] = bool(tainted)

    def _get(self, name):
        """Check if a variable is marked as tainted, searching scopes from innermost to outermost."""
        for env in reversed(self.env_stack):
            if name in env:
                return env[name]
        return False

    def _taint_params(self, fn: ast.AST):
        """Mark all function parameters as potentially tainted."""
        args = []

        # Collect all parameter types
        if hasattr(fn, "args") and fn.args:
            args.extend(getattr(fn.args, "posonlyargs", []) or [])
            args.extend(getattr(fn.args, "args", []) or [])
            args.extend(getattr(fn.args, "kwonlyargs", []) or [])

            if fn.args.vararg:
                args.append(fn.args.vararg)
            if fn.args.kwarg:
                args.append(fn.args.kwarg)

        # Mark each parameter as tainted (except self/cls)
        for a in args:
            name = getattr(a, "arg", None)
            if not name:
                continue
            if name in ("self", "cls"):
                continue
            self._set(name, True)

    def is_tainted(self, node):
        """
        Determine if an AST node represents tainted (untrusted) data.
        Handles various expression types including string formatting,
        concatenation, method calls, and variable references.
        """
        if node is None:
            return False

        # JoinedStr (f-strings): check if any formatted value is tainted
        if isinstance(node, ast.JoinedStr):
            return any(
                isinstance(v, ast.FormattedValue) and self.is_tainted(v.value)
                for v in node.values
            )

        # Binary operations with + or %: check both operands
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Mod)):
            return self.is_tainted(node.left) or self.is_tainted(node.right)

        # String .format() calls are considered dangerous
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "format"
        ):
            return True

        # Direct calls to known sources (e.g., input(), request.data)
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id in self.sources
        ):
            return True

        # Attribute/subscript access on request object is tainted
        if isinstance(node, (ast.Attribute, ast.Subscript)):
            base = node.value
            while isinstance(base, (ast.Attribute, ast.Subscript)):
                base = base.value
            if isinstance(base, ast.Name) and base.id == self.request_obj:
                return True
            return self.is_tainted(node.value)

        # Variable reference - check if it's marked as tainted
        if isinstance(node, ast.Name):
            return self._get(node.id)

        # Function call - check arguments and keywords
        if isinstance(node, ast.Call):
            # Check if this is a known sanitizer
            if self.sanitizers:
                call_name = _resolve_call_name(node)
                if call_name and call_name in self.sanitizers:
                    return False

            # Check if method call on tainted object
            if isinstance(node.func, ast.Attribute):
                if self.is_tainted(node.func.value):
                    return True

            # Check if any argument is tainted
            if any(self.is_tainted(arg) for arg in node.args):
                return True

            # Check if any keyword argument value is tainted
            if any(self.is_tainted(k.value) for k in node.keywords):
                return True

        return False

    def generic_visit(self, node):
        """Recursively visit all child nodes."""
        for field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for item in value:
                    if isinstance(item, ast.AST):
                        self.visit(item)
            elif isinstance(value, ast.AST):
                self.visit(value)

    def visit_FunctionDef(self, node):
        """Handle function definitions - enter new scope and mark parameters."""
        self._push()
        self._symbol_stack.append(node.name)
        self._taint_params(node)
        self.generic_visit(node)
        self._symbol_stack.pop()
        self._pop()

    def visit_AsyncFunctionDef(self, node):
        """Handle async function definitions."""
        self._push()
        self._symbol_stack.append(node.name)
        self._taint_params(node)
        self.generic_visit(node)
        self._symbol_stack.pop()
        self._pop()

    def visit_ClassDef(self, node):
        """Handle class definitions."""
        self._symbol_stack.append(node.name)
        self.generic_visit(node)
        self._symbol_stack.pop()

    def visit_Assign(self, node):
        """Handle variable assignments - propagate taint from value to target."""
        t = self.is_tainted(node.value)
        for tgt in node.targets:
            if isinstance(tgt, ast.Name):
                self._set(tgt.id, t)
        self.generic_visit(node)

    def visit_AnnAssign(self, node):
        """Handle annotated assignments."""
        if node.value:
            t = self.is_tainted(node.value)
            if isinstance(node.target, ast.Name):
                self._set(node.target.id, t)
        self.generic_visit(node)

# Coda API CLI Tool
import argparse
import csv
import json
import os
import re
import sys
import time
from typing import Any, Dict, List, Optional, Tuple
from urllib.parse import urljoin, urlencode

# Try to import requests, fallback to urllib for environments without it
try:
    import requests
    HAS_REQUESTS = True
except ImportError:
    HAS_REQUESTS = False
    import urllib.request
    import urllib.error


class CodaAPIError(Exception):
    """Custom exception for Coda API errors."""
    pass


class CodaClient:
    """Client for the Coda REST API v1."""

    BASE_URL = "https://coda.io/apis/v1/"

    def __init__(self, token: Optional[str] = None):
        self.token = token or os.environ.get("CODA_API_TOKEN")
        if not self.token:
            raise CodaAPIError(
                "Coda API token required. Set CODA_API_TOKEN environment variable "
                "or pass --token."
            )

        if HAS_REQUESTS:
            self.session = requests.Session()
            self.session.headers.update({
                "Authorization": f"Bearer {self.token}",
                "Content-Type": "application/json"
            })

    def _request(
        self,
        method: str,
        endpoint: str,
        params: Optional[Dict] = None,
        json_data: Optional[Dict] = None
    ) -> Tuple[Dict[str, Any], int]:
        """Make HTTP request with rate limit handling."""
        # Join URL: BASE_URL + endpoint (endpoint may start with /)
        base = self.BASE_URL.rstrip('/')
        ep = endpoint.lstrip('/')
        url = f"{base}/{ep}"
        max_retries = 3
        retry_delay = 1

        # Add query params to URL
        if params:
            query = urlencode(params)
            url += ('&' if '?' in url else '?') + query

        for attempt in range(max_retries):
            try:
                if HAS_REQUESTS:
                    response = self.session.request(
                        method, url, json=json_data
                    )
                    status_code = response.status_code
                    text = response.text
                else:
                    # Fallback to urllib
                    req = urllib.request.Request(
                        url,
                        data=json.dumps(json_data).encode() if json_data else None,
                        headers={
                            "Authorization": f"Bearer {self.token}",
                            "Content-Type": "application/json"
                        },
                        method=method
                    )
                    try:
                        with urllib.request.urlopen(req) as resp:
                            status_code = resp.status
                            text = resp.read().decode()
                    except urllib.error.HTTPError as e:
                        status_code = e.code
                        text = e.read().decode()

                # Handle rate limiting (429)
                if status_code == 429:
                    if attempt < max_retries - 1:
                        time.sleep(retry_delay)
                        retry_delay *= 2
                        continue
                    raise CodaAPIError("Rate limit exceeded. Please wait and try again.")

                # Handle other errors
                if status_code >= 400:
                    try:
                        error_data = json.loads(text)
                        message = error_data.get("message", "Unknown error")
                    except:
                        message = text or "Unknown error"

                    if status_code == 401:
                        raise CodaAPIError(f"Authentication failed: {message}")
                    elif status_code == 403:
                        raise CodaAPIError(f"Permission denied: {message}")
                    elif status_code == 404:
                        raise CodaAPIError(f"Resource not found: {message}")
                    else:
                        raise CodaAPIError(f"API error ({status_code}): {message}")

                # Return JSON if present, else empty dict
                if text:
                    return json.loads(text), status_code
                return {}, status_code

            except Exception as e:
                if attempt == max_retries - 1:
                    raise CodaAPIError(f"Network error: {e}")
                time.sleep(retry_delay)
                retry_delay *= 2

        return {}, 500

    def get(self, endpoint: str, params: Optional[Dict] = None) -> Dict[str, Any]:
        """GET request."""
        result, _ = self._request("GET", endpoint, params=params)
        return result

    def post(self, endpoint: str, data: Optional[Dict] = None) -> Tuple[Dict[str, Any], int]:
        """POST request."""
        return self._request("POST", endpoint, json_data=data)

    def put(self, endpoint: str, data: Optional[Dict] = None) -> Tuple[Dict[str, Any], int]:
        """PUT request."""
        return self._request("PUT", endpoint, json_data=data)

    def patch(self, endpoint: str, data: Optional[Dict] = None) -> Tuple[Dict[str, Any], int]:
        """PATCH request."""
        return self._request("PATCH", endpoint, json_data=data)

    def delete(self, endpoint: str) -> Tuple[Dict[str, Any], int]:
        """DELETE request."""
        return self._request("DELETE", endpoint)

    def list_all(self, endpoint: str, params: Optional[Dict] = None) -> List[Dict]:
        """List all items with automatic pagination."""
        items = []
        params = params or {}

        while True:
            result = self.get(endpoint, params)
            items.extend(result.get("items", []))

            next_page_token = result.get("nextPageToken")
            if not next_page_token:
                break

            params["pageToken"] = next_page_token

        return items


def extract_doc_id(doc_id_or_url: str) -> str:
    """Extract doc ID from URL or return as-is if already an ID."""
    if "coda.io" in doc_id_or_url:
        match = re.search(r'/_d([a-zA-Z0-9_-]+)', doc_id_or_url)
        if match:
            return match.group(1)
        match = re.search(r'/d/([a-zA-Z0-9_-]+)', doc_id_or_url)
        if match:
            return match.group(1)
    return doc_id_or_url


def confirm_action(message: str, force: bool = False) -> bool:
    """Ask for confirmation unless force=True."""
    if force:
        return True
    response = input(f"{message} [y/N]: ").strip().lower()
    return response in ('y', 'yes')


def print_json(data: Any, compact: bool = False):
    """Print data as formatted JSON."""
    indent = None if compact else 2
    print(json.dumps(data, indent=indent, ensure_ascii=False))


def print_table(headers: List[str], rows: List[List[str]]):
    """Print simple ASCII table."""
    if not rows:
        print("No data.")
        return

    widths = [len(h) for h in headers]
    for row in rows:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(str(cell)))

    header_line = " | ".join(h.ljust(w) for h, w in zip(headers, widths))
    print(header_line)
    print("-" * len(header_line))

    for row in rows:
        print(" | ".join(str(cell).ljust(w) for cell, w in zip(row, widths)))


class DocsCommands:
    def __init__(self, client: CodaClient):
        self.client = client

    def list(self, args):
        params = {}
        if args.is_owner:
            params["isOwner"] = "true"
        if args.query:
            params["query"] = args.query
        if args.workspace_id:
            params["workspaceId"] = args.workspace_id
        if args.folder_id:
            params["folderId"] = args.folder_id
        if args.limit:
            params["limit"] = args.limit

        if args.all:
            items = self.client.list_all("/docs", params)
        else:
            result = self.client.get("/docs", params)
            items = result.get("items", [])

        if args.format == "json":
            print_json(items)
        else:
            headers = ["ID", "Name", "Owner", "Updated"]
            rows = [[d["id"], d["name"], d.get("owner", "N/A"),
                    d.get("updatedAt", "N/A")[:10]] for d in items]
            print_table(headers, rows)
            print(f"\nTotal: {len(items)} docs")

    def get(self, args):
        doc_id = extract_doc_id(args.doc_id)
        result = self.client.get(f"/docs/{doc_id}")
        print_json(result)

    def create(self, args):
        payload = {"title": args.title}
        if args.source_doc:
            payload["sourceDoc"] = extract_doc_id(args.source_doc)
        if args.folder_id:
            payload["folderId"] = args.folder_id
        if args.timezone:
            payload["timezone"] = args.timezone

        result, status = self.client.post("/docs", payload)
        if status == 201:
            print(f"Created doc: {result['name']} (ID: {result['id']})")
            print(f"URL: {result['browserLink']}")
        else:
            print_json(result)

    def delete(self, args):
        doc_id = extract_doc_id(args.doc_id)
        try:
            doc_info = self.client.get(f"/docs/{doc_id}")
            doc_name = doc_info.get("name", "Unknown")
        except:
            doc_name = doc_id

        if not confirm_action(
            f"Delete doc '{doc_name}'? This cannot be undone.",
            args.force
        ):
            print("Cancelled.")
            return

        _, status = self.client.delete(f"/docs/{doc_id}")
        print(f"Doc '{doc_name}' deleted." if status == 200 else "Deletion accepted.")


class TablesCommands:
    def __init__(self, client: CodaClient):
        self.client = client

    def list(self, args):
        doc_id = extract_doc_id(args.doc_id)
        items = self.client.list_all(f"/docs/{doc_id}/tables")

        if args.format == "json":
            print_json(items)
        else:
            headers = ["ID", "Name", "Type", "Rows"]
            rows = [[t["id"], t["name"], t.get("tableType", "N/A"),
                    str(t.get("rowCount", "N/A"))] for t in items]
            print_table(headers, rows)


class RowsCommands:
    def __init__(self, client: CodaClient):
        self.client = client

    def list(self, args):
        doc_id = extract_doc_id(args.doc_id)
        table_id = args.table_id

        params = {}
        if args.query:
            params["query"] = args.query
        if args.limit:
            params["limit"] = args.limit

        if args.all:
            items = self.client.list_all(f"/docs/{doc_id}/tables/{table_id}/rows", params)
        else:
            result = self.client.get(f"/docs/{doc_id}/tables/{table_id}/rows", params)
            items = result.get("items", [])

        if args.format == "json":
            print_json(items)
        elif args.format == "csv":
            if not items:
                print("No rows.")
                return
            columns = set()
            for item in items:
                columns.update(item.get("values", {}).keys())
            columns = sorted(columns)

            writer = csv.writer(sys.stdout)
            writer.writerow(["ID", "Name"] + columns)
            for item in items:
                row = [item["id"], item.get("name", "")]
                for col in columns:
                    val = item.get("values", {}).get(col, "")
                    if isinstance(val, dict):
                        val = json.dumps(val)
                    row.append(val)
                writer.writerow(row)
        else:
            headers = ["ID", "Name", "Values"]
            rows = [[r["id"], r.get("name", "N/A")[:40],
                    json.dumps(r.get("values", {}))[:50] + "..."]
                   for r in items[:20]]
            print_table(headers, rows)
            if len(items) > 20:
                print(f"\n... and {len(items) - 20} more rows")

    def insert(self, args):
        doc_id = extract_doc_id(args.doc_id)
        table_id = args.table_id

        rows = []
        if args.data:
            rows.append({"cells": json.loads(args.data)})
        elif args.file:
            with open(args.file) as f:
                data = json.load(f)
                if isinstance(data, list):
                    rows = [{"cells": r} for r in data]
                else:
                    rows = [{"cells": data}]

        payload = {"rows": rows}
        result, status = self.client.post(
            f"/docs/{doc_id}/tables/{table_id}/rows",
            payload
        )
        print(f"Inserted {len(rows)} row(s)." if status == 200 else f"Queued: {result.get('requestId')}")

    def update(self, args):
        doc_id = extract_doc_id(args.doc_id)
        table_id = args.table_id
        row_id = args.row_id

        payload = {"row": {"cells": json.loads(args.data)}}
        result, status = self.client.put(
            f"/docs/{doc_id}/tables/{table_id}/rows/{row_id}",
            payload
        )
        print("Row updated." if status == 200 else f"Queued: {result.get('requestId')}")

    def delete(self, args):
        doc_id = extract_doc_id(args.doc_id)
        table_id = args.table_id
        row_id = args.row_id

        if not confirm_action(
            f"Delete row {row_id}?",
            args.force
        ):
            print("Cancelled.")
            return

        _, status = self.client.delete(
            f"/docs/{doc_id}/tables/{table_id}/rows/{row_id}"
        )
        print("Row deleted." if status == 200 else "Delete queued.")


class PagesCommands:
    def __init__(self, client: CodaClient):
        self.client = client

