# Parts of the code here are adapted from PyTorch
# repo: https://github.com/pytorch/pytorch

import functools
import torch
from megatron.core.parallel_state import (
    get_global_memory_buffer,
    get_tensor_model_parallel_group,
    get_tensor_model_parallel_world_size,
)
from megatron.core.utils import (
    is_torch_min_version,
    prepare_input_tensors_for_wgrad_compute,
)
from torch.cuda.amp import custom_bwd, custom_fwd


# Determine appropriate distributed functions based on PyTorch version
if is_torch_min_version("1.13.0"):
    dist_all_gather_func = torch.distributed.all_gather_into_tensor
    dist_reduce_scatter_func = torch.distributed.reduce_scatter_tensor
else:
    dist_all_gather_func = torch.distributed._all_gather_base
    dist_reduce_scatter_func = torch.distributed._reduce_scatter_base

# Try importing fused CUDA kernels for gradient accumulation
try:
    import fused_weight_gradient_mlp_cuda
except ImportError:
    _grad_accum_fusion_available = False


class LinearWithGradAccumulationAndAsyncCommunication(torch.autograd.Function):
    """See linear_with_grad_accumulation_and_async_allreduce"""

    @staticmethod
    @custom_fwd
    def forward(
        ctx,
        input,
        weight,
        bias,
        gradient_accumulation_fusion,
        allreduce_dgrad,
        sequence_parallel,
        grad_output_buffer,
        wgrad_deferral_limit,
        tp_group,
    ):
        # Save inputs for backward pass
        ctx.save_for_backward(input, weight)
        ctx.use_bias = bias is not None
        ctx.gradient_accumulation_fusion = gradient_accumulation_fusion
        ctx.allreduce_dgrad = allreduce_dgrad
        ctx.sequence_parallel = sequence_parallel
        ctx.wgrad_deferral_limit = wgrad_deferral_limit
        ctx.grad_output_buffer = grad_output_buffer
        ctx.weight_main_grad = weight.main_grad

        # Handle sequence parallelism by gathering inputs across tensor model parallel groups
        if sequence_parallel:
            world_size = get_tensor_model_parallel_world_size()
            dim_size = list(input.size())
            dim_size[0] = dim_size[0] * world_size
            all_gather_buffer = get_global_memory_buffer().get_tensor(dim_size, input.dtype, "mpu")
            dist_all_gather_func(all_gather_buffer, input, group=tp_group)
            total_input = all_gather_buffer
        else:
            total_input = input

        # Compute output: y = x @ W^T + b
        output = torch.matmul(total_input, weight.t())
        if bias is not None:
            output = output + bias

        return output

    @staticmethod
    @custom_bwd
    def backward(ctx, grad_output):
        input, weight = ctx.saved_tensors
        weight.main_grad = ctx.weight_main_grad
        use_bias = ctx.use_bias
        grad_output_buffer = ctx.grad_output_buffer
        wgrad_deferral_limit = ctx.wgrad_deferral_limit

        # Helper function to prepare inputs for backward computation
        def pre_process(_grad_output_, _input_, async_op=True):
            if ctx.sequence_parallel:
                world_size = get_tensor_model_parallel_world_size()
                _dim_size = list(_input_.size())
                _dim_size[0] = _dim_size[0] * world_size
                all_gather_buffer = get_global_memory_buffer().get_tensor(_dim_size, _input_.dtype, "mpu")

                # Here we rely on CUDA_DEVICE_MAX_CONNECTIONS=1 to ensure that the
                # gather is scheduled before the input gradient computation
                _handle = dist_all_gather_func(
                    all_gather_buffer, input, group=get_tensor_model_parallel_group(), async_op=True
                )
                _total_input = all_gather_buffer
                _grad_output = _grad_output_
                return _grad_output, _total_input, _handle
            else:
                _total_input = _input_
                _grad_output = _grad_output_
                return _grad_output, _total_input, None

        # Prepare tensors for weight gradient computation
        def prepare_for_wgrad_compute(_grad_output, _total_input, _handle):
            if ctx.sequence_parallel and _handle is not None:
                _handle.wait()
            return prepare_input_tensors_for_wgrad_compute(_grad_output, _total_input)

        # Process weight gradient computation (with optional fusion)
        def process_wgrad(_weight, _grad_output, _total_input, _handle, wgrad_gemm_accum_func=None):
            grad_output_, total_input_ = prepare_for_wgrad_compute(_grad_output, _total_input, _handle)
            wgrad_gemm_accum_func(total_input_, grad_output_, _weight.main_grad)

        # Import required modules locally to avoid circular dependencies
        from primus.core.pipeline_parallel.handler.wgrad_handler import (
            WGradRunningCache,
        )
        from ..pipeline_parallel.wgrad_adapter import insert_wgrad_func_into_cache
        from ..pipeline_parallel.zerobubble.zbpp_utils import WeightGradStore

        # Determine whether to compute weight gradients immediately or defer them
        wgrad_compute = not WeightGradStore.split_bw() and (
            WGradRunningCache.cur_minibatch is None and WGradRunningCache.cur_chunk is None
        )

        # Buffer grad_output if deferral is enabled and buffer has space
        if grad_output_buffer is not None and wgrad_compute:
            if wgrad_deferral_limit == 0 or len(grad_output_buffer) < wgrad_deferral_limit:
                grad_output_buffer.append(grad_output)
                wgrad_compute = False

        # Pre-process grad_output and input for wgrad computation
        if wgrad_compute:
            grad_output, total_input, handle = pre_process(grad_output, input, async_op=wgrad_compute)

        # Compute gradient w.r.t. input: dL/dx = dL/dy @ W
        grad_input = grad_output.matmul(weight)

        # Prepare for wgrad computation if deferred earlier
        if wgrad_compute:
            grad_output, total_input = prepare_for_wgrad_compute(grad_output, total_input, handle)

        # Asynchronous all-reduce for data parallelism
        if ctx.allreduce_dgrad:
            handle = torch.distributed.all_reduce(
                grad_input, group=get_tensor_model_parallel_group(), async_op=wgrad_compute
            )
            # Ensure ordering via CUDA_DEVICE_MAX_CONNECTIONS=1

        # Handle sequence parallel reduce-scatter for input gradients
        if ctx.sequence_parallel:
            assert not ctx.allreduce_dgrad
            dim_size = list(input.size())
            sub_grad_input = torch.empty(
                dim_size, dtype=input.dtype, device=torch.cuda.current_device(), requires_grad=False
            )
            handle = dist_reduce_scatter_func(
                sub_grad_input, grad_input, group=get_tensor_model_parallel_group(), async_op=wgrad_compute
            )
            # Ensure ordering via CUDA_DEVICE_MAX_CONNECTIONS=1

        # Gradient accumulation with fusion (if enabled)
        if ctx.gradient_accumulation_fusion:
            if wgrad_compute:
                if weight.main_grad.dtype == torch.float32:
                    fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp32(
                        total_input, grad_output, weight.main_grad
                    )
                elif weight.main_grad.dtype in (torch.float16, torch.bfloat16):
                    fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp16(
                        total_input, grad_output, weight.main_grad
                    )
                else:
                    raise RuntimeError("Unsupported gradient type for gradient accumulation fusion")
            else:
                # Setup deferred wgrad function
                wgrad_gemm_accum_func = None
                if weight.main_grad.dtype == torch.float32:
                    wgrad_gemm_accum_func = fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp32
                elif weight.main_grad.dtype in (torch.float16, torch.bfloat16):
                    wgrad_gemm_accum_func = fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp16
                else:
                    raise RuntimeError("Unsupported gradient type for gradient accumulation fusion")

                insert_wgrad_func_into_cache(
                    weight,
                    functools.partial(pre_process, grad_output, input),
                    functools.partial(
                        process_wgrad,
                        weight,
                        wgrad_gemm_accum_func=wgrad_gemm_accum_func,
                    ),
                )

                # Handle dummy grad_weight to prevent background thread execution
                if hasattr(weight, "grad_added_to_main_grad"):
                    if getattr(weight, "zero_out_wgrad", False):
                        grad_weight = torch.zeros(
                            weight.main_grad.shape,
                            dtype=input.dtype,
                            device=torch.cuda.current_device(),
                            requires_grad=False,
                        )
                    else:
                        grad_weight = torch.empty(
                            weight.main_grad.shape,
                            dtype=input.dtype,
                            device=torch.cuda.current_device(),
                            requires_grad=False,
                        )
                    weight.grad_added_to_main_grad = True
                else:
                    grad_weight = None
        else:
            # Standard weight gradient computation without fusion
            grad_weight = grad_output.t().matmul(total_input)

        # Bias gradient computation
        grad_bias = grad_output.sum(dim=0) if use_bias else None

        # Wait for asynchronous operations and return results
        if ctx.sequence_parallel:
            if handle is not None:
                handle.wait()
            return sub_grad_input, grad_weight, grad_bias, None, None, None, None, None, None

        if ctx.allreduce_dgrad:
            if handle is not None:
                handle.wait()

        return grad_input, grad_weight, grad_bias, None, None, None, None, None, None

# Import necessary modules
from functools import wraps
from typing import Callable, Optional
import torch

# Local imports
from rlinf.algorithms.utils import (
    calculate_scores,
    postprocess_embodied_advantages_outputs,
    postprocess_loss_metric,
    postprocess_reasoning_advantages_outputs,
    preprocess_embodied_advantages_inputs,
    preprocess_loss_inputs,
    preprocess_reasoning_advantages_inputs,
)

# Registry for advantage functions
ADV_REGISTRY: dict[str, Callable] = {}

def register_advantage(name: str):
    """Decorator to register an advantage function."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            return fn(*args, **kwargs)

        # Register using lowercase key
        ADV_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def get_adv_and_returns(name: str) -> Callable:
    """Retrieve a registered advantage function by name."""
    if name.lower() not in ADV_REGISTRY:
        raise ValueError(
            f"Advantage '{name}' not registered. Available: {list(ADV_REGISTRY.keys())}"
        )
    return ADV_REGISTRY[name.lower()]

# Registry for policy loss functions
LOSS_REGISTRY: dict[str, Callable] = {}

def register_policy_loss(name: str):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            return fn(*args, **kwargs)

        # Register using lowercase key
        LOSS_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def get_policy_loss(name: str):
    if name.lower() not in LOSS_REGISTRY:
        raise ValueError(f"Loss '{name}' not registered")
    return LOSS_REGISTRY[name.lower()]

def policy_loss(**kwargs) -> tuple[torch.Tensor, dict]:
    """
    Unified actor loss entry point.
    """
    loss_type = kwargs["loss_type"]
    loss_fn = get_policy_loss(loss_type)

    task_type = kwargs["task_type"]

    # Preprocess inputs for embodied tasks
    if task_type == "embodied":
        kwargs = preprocess_loss_inputs(**kwargs)

    # Compute loss and metrics
    loss, metrics_data = loss_fn(**kwargs)

    # Postprocess metrics for embodied tasks
    if task_type == "embodied":
        metrics_data = postprocess_loss_metric(metrics_data)

    return loss, metrics_data

def calculate_adv_and_returns(**kwargs) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    """
    Unified entry point for advantage and return computation.
    Accepts variable keyword arguments, preprocesses them, then dispatches
    to the appropriate algorithm via registry.
    """
    adv_type = kwargs["adv_type"]
    fn = get_adv_and_returns(adv_type)

    task_type = kwargs["task_type"]

    if task_type == "embodied":
        # Embodied task preprocessing
        kwargs = preprocess_embodied_advantages_inputs(**kwargs)

        # Calculate scores for non-GAE methods
        if adv_type != "gae":
            kwargs = calculate_scores(**kwargs)

        # Compute advantages and returns
        advantages, returns = fn(**kwargs)

        # Postprocess outputs
        res = postprocess_embodied_advantages_outputs(
            advantages=advantages, returns=returns, **kwargs
        )
    else:
        # Reasoning task handling
        kwargs = preprocess_reasoning_advantages_inputs(**kwargs)
        advantages, returns = fn(**kwargs)
        res = postprocess_reasoning_advantages_outputs(advantages, returns)

    return res

# Error handling module for the Castor Gateway
# All errors returned by the gateway now share the same shape:
#     {"error": "<human-readable message>", "code": "<ERROR_CODE>", "status": <http_status>}

# Usage
# -----
# Raise ``CastorAPIError`` anywhere inside an endpoint to return a structured
# error response without having to construct ``JSONResponse`` manually::
#     from castor.api_errors import CastorAPIError
#     raise CastorAPIError("BRAIN_NOT_READY", "Brain is not initialized", 503)
# Call ``register_error_handlers(app)`` once at application startup to install
# the global exception handlers.

from __future__ import annotations

import logging
from fastapi import HTTPException, Request
from fastapi.responses import JSONResponse

logger = logging.getLogger("OpenCastor.Gateway")


class CastorAPIError(Exception):
    """Raise this to return a structured JSON error from any endpoint."""

    def __init__(self, code: str, message: str, status: int = 400):
        self.code = code
        self.message = message
        self.status = status
        super().__init__(message)


def register_error_handlers(app) -> None:
    """Install global exception handlers on the FastAPI *app* instance.

    Must be called after the ``app`` object is created but before any
    requests are handled (i.e. at module level in ``api.py``).
    """

    @app.exception_handler(CastorAPIError)
    async def _castor_error_handler(request: Request, exc: CastorAPIError):
        return JSONResponse(
            status_code=exc.status,
            content={"error": exc.message, "code": exc.code, "status": exc.status},
        )

    @app.exception_handler(HTTPException)
    async def _http_error_handler(request: Request, exc: HTTPException):
        detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail)
        return JSONResponse(
            status_code=exc.status_code,
            content={
                "error": detail,
                "code": f"HTTP_{exc.status_code}",
                "status": exc.status_code,
            },
        )

    @app.exception_handler(Exception)
    async def _unhandled_error_handler(request: Request, exc: Exception):
        logger.exception("Unhandled gateway error on %s %s", request.method, request.url.path)
        return JSONResponse(
            status_code=500,
            content={
                "error": "Internal server error",
                "code": "INTERNAL_ERROR",
                "status": 500,
            },
        )

