# Test for C++ runtime iterable protocol helpers
from __future__ import annotations

import os
import subprocess
import tempfile
import unittest
from pathlib import Path

ROOT = next(p for p in Path(__file__).resolve().parents if (p / "src").exists())

PYTRA_TEST_COMPILE_TIMEOUT_SEC = float(os.environ.get("PYTRA_TEST_COMPILE_TIMEOUT_SEC", "120"))
PYTRA_TEST_RUN_TIMEOUT_SEC = float(os.environ.get("PYTRA_TEST_RUN_TIMEOUT_SEC", "2"))

CPP_RUNTIME_SRCS = [
    "src/runtime/cpp/core/gc.ext.cpp",
    "src/runtime/cpp/core/io.ext.cpp",
]


class CppRuntimeIterableTest(unittest.TestCase):
    def _run(
        self,
        args: list[str],
        *,
        cwd: Path,
        timeout_sec: float,
        label: str,
    ) -> subprocess.CompletedProcess[str]:
        try:
            return subprocess.run(args, cwd=cwd, capture_output=True, text=True, timeout=timeout_sec)
        except subprocess.TimeoutExpired as ex:
            out_obj = ex.stdout
            err_obj = ex.stderr
            out_txt = out_obj if isinstance(out_obj, str) else ""
            err_txt = err_obj if isinstance(err_obj, str) else ""
            self.fail(
                f"{label} timed out after {timeout_sec:.1f}s: {' '.join(args)}\n"
                f"stdout:\n{out_txt}\n"
                f"stderr:\n{err_txt}"
            )
            raise AssertionError("unreachable")

    def test_runtime_iterable_protocol_helpers(self) -> None:
        cpp_src = r'''
#include "runtime/cpp/core/py_runtime.ext.h"
#include <cassert>
#include <iostream>

int main() {
    object list_obj = make_object(list<int64>{1, 2, 3});
    object iter_obj = py_iter_or_raise(list_obj);
    auto n0 = py_next_or_stop(iter_obj);
    auto n1 = py_next_or_stop(iter_obj);
    auto n2 = py_next_or_stop(iter_obj);
    auto n3 = py_next_or_stop(iter_obj);

    assert(n0.has_value() && obj_to_int64(*n0) == 1);
    assert(n1.has_value() && obj_to_int64(*n1) == 2);
    assert(n2.has_value() && obj_to_int64(*n2) == 3);
    assert(!n3.has_value());

    object mut_list_obj = make_object(list<int64>{10, 20});
    object mut_iter_obj = py_iter_or_raise(mut_list_obj);
    auto m0 = py_next_or_stop(mut_iter_obj);
    assert(m0.has_value() && obj_to_int64(*m0) == 10);

    py_append(mut_list_obj, make_object(int64(30)));
    auto m1 = py_next_or_stop(mut_iter_obj);
    auto m2 = py_next_or_stop(mut_iter_obj);
    auto m3 = py_next_or_stop(mut_iter_obj);

    assert(m1.has_value() && obj_to_int64(*m1) == 20);
    assert(m2.has_value() && obj_to_int64(*m2) == 30);
    assert(!m3.has_value());

    py_extend(mut_list_obj, make_object(list<int64>{40, 50}));
    assert(py_len(mut_list_obj) == 5);

    object p0 = py_pop(mut_list_obj);
    assert(obj_to_int64(p0) == 50);

    object p1 = py_pop(mut_list_obj, 0);
    assert(obj_to_int64(p1) == 10);

    py_reverse(mut_list_obj);
    assert(obj_to_int64(py_at(mut_list_obj, 0)) == 40);

    py_sort(mut_list_obj);
    assert(obj_to_int64(py_at(mut_list_obj, 0)) == 20);

    py_clear(mut_list_obj);
    assert(py_len(mut_list_obj) == 0);

    int64 sum = 0;
    for (object v : py_dyn_range(list_obj)) {
        sum += obj_to_int64(v);
    }
    assert(sum == 6);

    dict<str, object> d{};
    d["a"] = make_object(1);
    d["b"] = make_object(2);

    bool has_a = false;
    bool has_b = false;
    for (object key_obj : py_dyn_range(make_object(d))) {
        str key = obj_to_str(key_obj);
        if (key == "a") has_a = true;
        if (key == "b") has_b = true;
    }
    assert(has_a && has_b);

    str joined = "";
    for (object ch : py_dyn_range(make_object(str("ab")))) {
        joined += obj_to_str(ch);
    }
    assert(joined == "ab");

    object set_obj = make_object(set<int64>{1, 2, 3});
    int64 set_sum = 0;
    for (object v : py_dyn_range(set_obj)) {
        set_sum += obj_to_int64(v);
    }
    assert(set_sum == 6);

    bool thrown = false;
    try {
        for (object _ : py_dyn_range(make_object(int64(9)))) {
            (void)_;
        }
    } catch (const ::std::runtime_error&) {
        thrown = true;
    }
    assert(thrown);

    std::cout << "runtime iterable ok" << std::endl;
    return 0;
}
'''

        with tempfile.TemporaryDirectory() as tmpdir:
            work = Path(tmpdir)
            src = work / "runtime_iterable.cpp"
            exe = work / "runtime_iterable.out"

            src.write_text(cpp_src, encoding="utf-8")

            comp = self._run(
                [
                    "g++",
                    "-std=c++20",
                    "-O2",
                    "-I",
                    "src",
                    "-I",
                    "src/runtime/cpp",
                    str(src),
                    *CPP_RUNTIME_SRCS,
                    "-o",
                    str(exe),
                ],
                cwd=ROOT,
                timeout_sec=PYTRA_TEST_COMPILE_TIMEOUT_SEC,
                label="compile runtime iterable smoke",
            )

            self.assertEqual(comp.returncode, 0, msg=comp.stderr)

            run = self._run(
                [str(exe)],
                cwd=work,
                timeout_sec=PYTRA_TEST_RUN_TIMEOUT_SEC,
                label="run runtime iterable smoke",
            )

            self.assertEqual(run.returncode, 0, msg=run.stderr)
            self.assertIn("runtime iterable ok", run.stdout)


if __name__ == "__main__":
    unittest.main()

# Validates experience JSONL files against schema and rules
import json
import re
import sys
import os
from datetime import datetime, timezone

# ID pattern: EXP-YYYYMMDD-NNNN
ID_PATTERN = re.compile(r'^EXP-\d{8}-\d{4}$')

# Valid significance levels
VALID_SIGNIFICANCE = {'routine', 'notable', 'pivotal'}

# Built-in data sources
BUILTIN_SOURCES = {
    'conversation',
    'moltbook',
    'x',
    'heartbeat',
    'flush_harvest',
    'other'
}

# Required fields in each entry
REQUIRED_FIELDS = {
    'id',
    'timestamp',
    'source',
    'content',
    'significance',
    'significance_reason',
    'reflected'
}


def load_config_sources(config_path):
    """Load additional valid source names from config.json."""
    extra = set()

    # Check if config path exists and is provided
    if config_path and os.path.exists(config_path):
        try:
            with open(config_path) as f:
                cfg = json.load(f)

            # Add all keys from 'sources' section
            for key in cfg.get('sources', {}):
                extra.add(key)
        except Exception:
            # Silently ignore config loading errors
            pass

    # Return union of built-in and extra sources
    return BUILTIN_SOURCES | extra


def parse_iso(ts):
    """Check if timestamp is valid ISO-8601."""
    try:
        # Normalize timezone format (Z -> +00:00)
        ts = ts.replace('Z', '+00:00')
        dt = datetime.fromisoformat(ts)
        return dt
    except (ValueError, TypeError):
        return None


def validate(filepath, config_path=None):
    errors = []
    warnings = []

    # Load valid sources
    valid_sources = load_config_sources(config_path)

    seen_ids = set()
    line_count = 0
    notable_pivotal_ids = []

    # Check if file exists
    if not os.path.exists(filepath):
        return {
            'status': 'FAIL',
            'file': filepath,
            'errors': [{'line': None, 'field': None, 'message': f'File not found: {filepath}'}],
            'warnings': [],
            'stats': {}
        }

    # Process file line by line
    with open(filepath, 'r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()

            # Skip empty lines
            if not line:
                continue

            line_count += 1

            # Parse JSON
            try:
                entry = json.loads(line)
            except json.JSONDecodeError as e:
                errors.append({
                    'line': line_num,
                    'field': None,
                    'message': f'Invalid JSON: {str(e)[:80]}'
                })
                continue

            # Ensure entry is a dictionary
            if not isinstance(entry, dict):
                errors.append({
                    'line': line_num,
                    'field': None,
                    'message': f'Expected JSON object, got {type(entry).__name__}'
                })
                continue

            # Check required fields
            for field in REQUIRED_FIELDS:
                if field not in entry:
                    errors.append({
                        'line': line_num,
                        'field': field,
                        'message': f'Missing required field: {field}'
                    })

            # Validate ID format
            eid = entry.get('id', '')
            if eid and not ID_PATTERN.match(eid):
                errors.append({
                    'line': line_num,
                    'field': 'id',
                    'message': f'Invalid ID format: "{eid}" (expected EXP-YYYYMMDD-NNNN)'
                })

            # Check for duplicate IDs
            if eid in seen_ids:
                errors.append({
                    'line': line_num,
                    'field': 'id',
                    'message': f'Duplicate ID: {eid}'
                })
            seen_ids.add(eid)

            # Validate timestamp
            ts = entry.get('timestamp')
            if ts:
                dt = parse_iso(ts)
                if dt is None:
                    errors.append({
                        'line': line_num,
                        'field': 'timestamp',
                        'message': f'Invalid ISO-8601 timestamp: "{ts}"'
                    })
                elif dt.tzinfo and dt > datetime.now(timezone.utc):
                    warnings.append({
                        'line': line_num,
                        'message': f'Timestamp is in the future: {ts}'
                    })

            # Validate source
            source = entry.get('source', '')
            if source and source not in valid_sources:
                errors.append({
                    'line': line_num,
                    'field': 'source',
                    'message': f'Unknown source: "{source}" (valid: {sorted(valid_sources)})'
                })

            # Validate significance
            sig = entry.get('significance', '')
            if sig and sig not in VALID_SIGNIFICANCE:
                errors.append({
                    'line': line_num,
                    'field': 'significance',
                    'message': f'Invalid significance: "{sig}" (valid: routine, notable, pivotal)'
                })

            # Track notable/pivotal entries
            if sig in ('notable', 'pivotal'):
                notable_pivotal_ids.append(eid)

            # Validate content is non-empty
            content = entry.get('content', '')
            if isinstance(content, str) and not content.strip():
                errors.append({
                    'line': line_num,
                    'field': 'content',
                    'message': 'Content is empty'
                })

            # Warn about missing significance reason
            reason = entry.get('significance_reason', '')
            if isinstance(reason, str) and not reason.strip():
                warnings.append({
                    'line': line_num,
                    'message': 'significance_reason is empty'
                })

            # Validate reflected field type
            reflected = entry.get('reflected')
            if reflected is not None and not isinstance(reflected, bool):
                errors.append({
                    'line': line_num,
                    'field': 'reflected',
                    'message': f'reflected must be boolean, got {type(reflected).__name__}: {reflected}'
                })

    # Determine final status
    status = 'FAIL' if errors else 'PASS'

    return {
        'status': status,
        'file': filepath,
        'errors': errors,
        'warnings': warnings,
        'stats': {
            'total_entries': line_count,
            'unique_ids': len(seen_ids),
            'notable_pivotal_count': len(notable_pivotal_ids),
            'notable_pivotal_ids': notable_pivotal_ids
        }
    }


if __name__ == '__main__':
    # Command-line argument handling
    if len(sys.argv) < 2:
        print('Usage: validate_experience.py <jsonl_file> [--config config.json]', file=sys.stderr)
        sys.exit(2)

    filepath = sys.argv[1]
    config_path = None

    # Handle optional --config flag
    if '--config' in sys.argv:
        idx = sys.argv.index('--config')
        if idx + 1 < len(sys.argv):
            config_path = sys.argv[idx + 1]

    # Run validation
    result = validate(filepath, config_path)

    # Output results
    print(json.dumps(result, indent=2))

    # Exit with appropriate code
    sys.exit(0 if result['status'] == 'PASS' else 1)

