import operator
from typing import Optional

from blankly.enums import MarginType, HedgeMode, Side, PositionMode, TimeInForce, ContractType, OrderStatus, OrderType
from blankly.exchanges.interfaces.ftx.ftx_api import FTXAPI
from blankly.exchanges.interfaces.ftx.ftx_interface import FTXInterface
from blankly.exchanges.interfaces.futures_exchange_interface import FuturesExchangeInterface
from blankly.exchanges.orders.futures.futures_order import FuturesOrder
from blankly.utils import utils, time_builder

import datetime
import math


class FTXFuturesInterface(FuturesExchangeInterface):
    calls: FTXAPI

    @staticmethod
    def to_exchange_symbol(symbol: str):
        base_asset, quote_asset = symbol.split('-', 1)
        if quote_asset != 'USD':
            raise ValueError('invalid symbol')
        return base_asset + '-PERP'  # only perpetual contracts right now

    @staticmethod
    def to_blankly_symbol(symbol: str):
        base_asset, contract_type = symbol.split('-', 1)
        if contract_type != 'PERP':
            raise ValueError(
                'invalid symbol -- blankly only supports perpetual contracts')
        return base_asset + '-USD'

    @staticmethod
    def parse_timestamp(time: str) -> int:
        return int(datetime.datetime.fromisoformat(time).timestamp())

    @staticmethod
    def to_order_status(status: str, cancel: bool = False) -> OrderStatus:
        if status in ('new', 'open'):
            return OrderStatus.OPEN
        elif status == 'closed':
            if cancel:
                return OrderStatus.CANCELED
            else:
                return OrderStatus.FILLED
        raise ValueError(f'invalid order status: {status}')

    @staticmethod
    def to_order_type(type: str) -> OrderType:
        if type == 'market':
            return OrderType.MARKET
        elif type == 'limit':
            return OrderType.LIMIT
        elif type == 'takeProfit':
            return OrderType.TAKE_PROFIT
        elif type == 'stop':
            return OrderType.STOP
        raise ValueError(f'invalid order type: {type}')

    def parse_order_response(self,
                             response: dict,
                             cancel: bool = False) -> FuturesOrder:
        return FuturesOrder(
            symbol=response['future'],
            id=int(response['id']),
            status=self.to_order_status(response['status'], cancel),
            size=float(response['size']),
            type=self.to_order_type(response['type']),
            contract_type=ContractType.PERPETUAL,
            side=Side(response['side']),
            position=PositionMode.BOTH,
            price=float(response['avgFillPrice']),
            limit_price=float(response['price']),
            time_in_force=TimeInForce.IOC
            if response['ioc'] else TimeInForce.GTC,
            response=response,
            interface=self)

    def init_exchange(self):
        # will throw exception if our api key is stinky
        self.calls.get_account_info()

    def get_products(self, filter: str = None) -> dict:
        res = self.calls.list_futures()
        products = {}
        for prod in res:
            if '-PERP' not in prod['name']:
                continue  # only perpetual contracts for now
            symbol = prod['underlying'] + '-USD'
            products[symbol] = {
                'symbol': symbol,
                'base_asset': prod['underlying'],
                'quote_asset': 'USD',
                'contract_type': ContractType.PERPETUAL,
                'price_precision': utils.increment_to_precision(
                    prod['priceIncrement']),
                'size_precision': utils.increment_to_precision(
                    prod['sizeIncrement']),
                'exchange_specific': prod
            }
        if filter:
            return products[filter]
        return products

    def get_account(self, filter: str = None) -> dict:
        balances = self.calls.get_balances()
        coins = self.calls.get_coins()
        accounts = {
            coin['id']: {
                'available': 0.0,
                'hold': 0.0,  # TODO
                'exchange_specific': coin
            }
            for coin in coins
        }
        for bal in balances:
            coin = bal['coin']
            accounts[coin].available = float(bal['free'])
            # merge into exchange_specific
            accounts[coin].exchange_specific = {
                **accounts[coin].exchange_specific,
                **bal
            }
        if filter:
            return accounts[filter]
        return accounts

    def get_position(self, filter: str = None) -> Optional[dict]:
        leverage = self.get_leverage()
        res = self.calls.get_positions()
        positions = {}
        for position in res:
            symbol = self.to_exchange_symbol(position['future'])
            size = float(position['netSize'])
            if size == 0:
                continue
            positions[symbol] = {
                'size': size,
                'position': PositionMode.BOTH,
                'contract_type': ContractType.PERPETUAL,
                'exchange_specific': position
            }
        if filter:
            return positions.get(filter, None)
        return positions

    def market_order(self,
                     symbol: str,
                     side: Side,
                     size: float,
                     position: PositionMode = PositionMode.BOTH,
                     reduce_only: bool = False) -> FuturesOrder:
        symbol = self.to_exchange_symbol(symbol)
        if position != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position} not supported on FTX Futures')
        res = self.calls.place_order(symbol, side, None, size, 'market',
                                     reduce_only)
        return self.parse_order_response(res)

    def limit_order(
            self,
            symbol: str,
            side: Side,
            price: float,
            size: float,
            position: PositionMode = PositionMode.BOTH,
            reduce_only: bool = False,
            time_in_force: TimeInForce = TimeInForce.GTC) -> FuturesOrder:
        symbol = self.to_exchange_symbol(symbol)
        if time_in_force == TimeInForce.GTC:
            ioc = False
        elif time_in_force == TimeInForce.IOC:
            ioc = True
        else:
            raise ValueError(
                f'time in force {time_in_force} not supported on FTX Futures')
        if position != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position} not supported on FTX Futures')
        res = self.calls.place_order(symbol,
                                     side,
                                     price,
                                     size,
                                     'limit',
                                     reduce_only,
                                     ioc=ioc)
        return self.parse_order_response(res)

    def take_profit_order(
            self,
            symbol: str,
            side: Side,
            price: float,
            size: float,
            position: PositionMode = PositionMode.BOTH) -> FuturesOrder:
        symbol = self.to_exchange_symbol(symbol)
        if position != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position} not supported on FTX Futures')
        res = self.calls.place_conditional_order(symbol,
                                                 side,
                                                 size,
                                                 'takeProfit',
                                                 trigger_price=price)
        return self.parse_order_response(res)

    def stop_loss_order(self,
                        symbol: str,
                        side: Side,
                        price: float,
                        size: float,
                        position: PositionMode = PositionMode.BOTH) -> FuturesOrder:
        symbol = self.to_exchange_symbol(symbol)
        if position != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position} not supported on FTX Futures')
        res = self.calls.place_conditional_order(symbol,
                                                 side,
                                                 size,
                                                 'stop',
                                                 trigger_price=price)
        return self.parse_order_response(res)

    @utils.order_protection
    def set_hedge_mode(self, hedge_mode: HedgeMode):
        if hedge_mode == HedgeMode.HEDGE:
            raise Exception('HEDGE mode not supported on FTX Futures')
        pass  # FTX only has ONEWAY mode

    def get_hedge_mode(self):
        return HedgeMode.ONEWAY

    @utils.order_protection
    def set_leverage(self, leverage: float, symbol: str = None):
        if symbol:
            raise Exception(
                'FTX Futures does not allow setting leverage per symbol. Use interface.set_leverage(leverage) to set '
                'account-wide leverage instead. ')
        self.calls.change_account_leverage(leverage)

    def get_leverage(self, symbol: str = None) -> float:
        # doesn't matter if symbol passed or not, ftx leverage is same for all
        return self.calls.get_account_info()['leverage']

    @utils.order_protection
    def set_margin_type(self, symbol: str, type: MarginType):
        if type == MarginType.ISOLATED:
            raise Exception('isolated margin not supported on FTX Futures')
        pass

    def get_margin_type(self, symbol: str):
        return MarginType.CROSSED

    def cancel_order(self, symbol: str, order_id: int) -> FuturesOrder:
        res = self.get_order(symbol, order_id)
        res.status = OrderStatus.CANCELED
        self.calls.cancel_order(str(order_id))
        return res

    def get_open_orders(self, symbol: str = None) -> list:
        return [
            self.parse_order_response(o) for o in self.calls.get_open_orders()
        ]

    def get_order(self, symbol: str, order_id: int) -> FuturesOrder:
        response = self.calls.get_order_by_id(str(order_id))
        symbol = self.to_exchange_symbol(symbol)
        if response['symbol'] != symbol:
            raise Exception(
                'response symbol did not match parameter -- this should never happen'
            )
        return self.parse_order_response(response)

    def get_price(self, symbol: str) -> float:
        symbol = self.to_exchange_symbol(symbol)
        return float(self.calls.get_future(symbol)['mark'])

    def get_funding_rate_history(self, symbol: str, epoch_start: int,
                                 epoch_stop: int) -> list:
        symbol = self.to_exchange_symbol(symbol)
        # TODO dedup binance_futures_exchange maybe?
        history = []
        resolution = self.get_funding_rate_resolution()
        limit = 500
        window_start = epoch_start
        window_end = epoch_start + limit * resolution
        response = True
        while response:
            response = self.calls.get_funding_rates(window_start, window_end,
                                                    symbol)
            history.extend({
                               'rate': float(e['rate']),
                               'time': self.parse_timestamp(e['time'])
                           } for e in response)
            if response:
                window_start = window_end
                window_end = min(epoch_stop, window_start + limit * resolution)
        return sorted(history, key=operator.itemgetter('time'))

    def get_funding_rate_resolution(self) -> int:
        return time_builder.build_hour()

    def get_product_history(self, symbol, epoch_start, epoch_stop, resolution):
        return FTXInterface.ftx_product_history(self.calls,
                                                self.to_exchange_symbol(symbol),
                                                epoch_start, epoch_stop, resolution)

    def get_maker_fee(self) -> float:
        raise NotImplementedError

    def get_taker_fee(self) -> float:
        raise NotImplementedError

    def get_funding_rate(self, symbol: str) -> float:
        raise NotImplementedError

# Tests for input_id_columns and upstream_id_columns properties
# used for calculating progress percentage in features with different lineage types.

from __future__ import annotations

from metaxy_testing.models import SampleFeatureSpec
from metaxy import (
    BaseFeature,
    FeatureDep,
    FeatureGraph,
    FeatureKey,
    FieldKey,
    FieldSpec,
)
from metaxy.models.lineage import LineageRelationship


class TestUpstreamIdColumns:
    """Tests for FeaturePlan.upstream_id_columns property."""

    def test_no_deps_returns_empty_list(self, graph: FeatureGraph):
        """Root feature with no dependencies returns empty list."""
        class RootFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["root"]),
                id_columns=["sample_uid"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(RootFeature.spec().key)
        assert plan.upstream_id_columns == []

    def test_single_upstream_returns_id_columns(self, graph: FeatureGraph):
        """Single upstream feature returns its id_columns."""
        class Upstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream"]),
                id_columns=["video_id", "frame_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass

        class Downstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["downstream"]),
                id_columns=["video_id", "frame_id"],
                deps=[FeatureDep(feature=Upstream)],
                fields=[FieldSpec(key=FieldKey(["result"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(Downstream.spec().key)
        assert set(plan.upstream_id_columns) == {"video_id", "frame_id"}

    def test_multiple_upstream_union_of_id_columns(self, graph: FeatureGraph):
        """Multiple upstream features return union of their id_columns."""
        class UpstreamA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream_a"]),
                id_columns=["video_id", "frame_id"],
                fields=[FieldSpec(key=FieldKey(["value_a"]), code_version="1")],
            ),
        ):
            pass

        class UpstreamB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream_b"]),
                id_columns=["video_id", "audio_id"],
                fields=[FieldSpec(key=FieldKey(["value_b"]), code_version="1")],
            ),
        ):
            pass

        class Downstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["downstream"]),
                id_columns=["video_id", "frame_id", "audio_id"],
                deps=[FeatureDep(feature=UpstreamA), FeatureDep(feature=UpstreamB)],
                fields=[FieldSpec(key=FieldKey(["result"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(Downstream.spec().key)
        assert set(plan.upstream_id_columns) == {"video_id", "frame_id", "audio_id"}

    def test_with_rename_applies_column_mapping(self, graph: FeatureGraph):
        """FeatureDep.rename is applied to upstream id_columns."""
        class Upstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream"]),
                id_columns=["sample_uid", "original_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass

        class Downstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["downstream"]),
                id_columns=["sample_uid", "renamed_id"],
                deps=[
                    FeatureDep(
                        feature=Upstream,
                        rename={"original_id": "renamed_id"},
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["result"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(Downstream.spec().key)
        assert set(plan.upstream_id_columns) == {"sample_uid", "renamed_id"}
        assert "original_id" not in plan.upstream_id_columns

    def test_with_partial_rename(self, graph: FeatureGraph):
        """Only renamed columns are affected, others pass through unchanged."""
        class Upstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream"]),
                id_columns=["video_id", "frame_id", "extra_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass

        class Downstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["downstream"]),
                id_columns=["video_id", "renamed_frame_id", "extra_id"],
                deps=[
                    FeatureDep(
                        feature=Upstream,
                        rename={"frame_id": "renamed_frame_id"},
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["result"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(Downstream.spec().key)
        assert set(plan.upstream_id_columns) == {
            "video_id",
            "renamed_frame_id",
            "extra_id",
        }
        assert "frame_id" not in plan.upstream_id_columns


class TestInputIdColumns:
    """Tests for FeaturePlan.input_id_columns property."""

    def test_identity_lineage_returns_upstream_id_columns(self, graph: FeatureGraph):
        """Identity (1:1) lineage returns upstream_id_columns."""
        class Upstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream"]),
                id_columns=["video_id", "frame_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass

        class Downstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["downstream"]),
                id_columns=["video_id", "frame_id"],
                deps=[FeatureDep(feature=Upstream)],
                fields=[FieldSpec(key=FieldKey(["result"]), code_version="1")],
                # Default lineage is identity
            ),
        ):
            pass

        plan = graph.get_feature_plan(Downstream.spec().key)
        assert set(plan.input_id_columns) == {"video_id", "frame_id"}
        assert plan.input_id_columns == plan.upstream_id_columns

    def test_aggregation_lineage_returns_aggregation_columns(self, graph: FeatureGraph):
        """Aggregation (N:1) lineage returns aggregation columns."""
        class SensorReadings(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["sensor_readings"]),
                id_columns=["sensor_id", "timestamp", "reading_id"],
                fields=[FieldSpec(key=FieldKey(["temperature"]), code_version="1")],
            ),
        ):
            pass

        class HourlyStats(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["hourly_stats"]),
                id_columns=["sensor_id", "hour"],
                deps=[
                    FeatureDep(
                        feature=SensorReadings,
                        lineage=LineageRelationship.aggregation(on=["sensor_id", "hour"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["avg_temp"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(HourlyStats.spec().key)
        # input_id_columns should be the aggregation columns
        assert set(plan.input_id_columns) == {"sensor_id", "hour"}
        # These should equal the downstream id_columns for aggregation
        assert set(plan.input_id_columns) == set(plan.feature.id_columns)

    def test_expansion_lineage_returns_parent_columns(self, graph: FeatureGraph):
        """Expansion (1:N) lineage returns parent columns from ExpansionRelationship.on."""
        class Video(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video"]),
                id_columns=["video_id"],
                fields=[FieldSpec(key=FieldKey(["resolution"]), code_version="1")],
            ),
        ):
            pass

        class VideoFrames(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video_frames"]),
                id_columns=["video_id", "frame_id"],
                deps=[
                    FeatureDep(
                        feature=Video,
                        lineage=LineageRelationship.expansion(on=["video_id"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["embedding"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(VideoFrames.spec().key)
        # input_id_columns should be the parent columns (expansion 'on')
        assert plan.input_id_columns == ["video_id"]

    def test_aggregation_with_multiple_upstreams(self, graph: FeatureGraph):
        """Aggregation with multiple upstreams - each dep can have its own lineage.
        With per-dep lineage, input_id_columns is the intersection of input columns
        from all dependencies after their lineage transformations.
        """
        class UpstreamA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream_a"]),
                id_columns=["sensor_id", "timestamp", "reading_id"],
                fields=[FieldSpec(key=FieldKey(["temp"]), code_version="1")],
            ),
        ):
            pass

        class UpstreamB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream_b"]),
                id_columns=["sensor_id", "hour"],  # UpstreamB also has hour column
                fields=[FieldSpec(key=FieldKey(["humidity"]), code_version="1")],
            ),
        ):
            pass

        class Aggregated(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["aggregated"]),
                id_columns=["sensor_id", "hour"],
                deps=[
                    FeatureDep(
                        feature=UpstreamA,
                        lineage=LineageRelationship.aggregation(on=["sensor_id", "hour"]),
                    ),
                    # UpstreamB has identity lineage (default) - its input columns are its ID columns
                    FeatureDep(feature=UpstreamB),
                ],
                fields=[FieldSpec(key=FieldKey(["stats"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(Aggregated.spec().key)
        # input_id_columns is intersection of:
        # - UpstreamA after aggregation: ["sensor_id", "hour"]
        # - UpstreamB with identity: ["sensor_id", "hour"]
        # Intersection: ["sensor_id", "hour"]
        assert set(plan.input_id_columns) == {"sensor_id", "hour"}

    def test_expansion_with_renamed_upstream(self, graph: FeatureGraph):
        """Expansion lineage with renamed upstream columns."""
        class Video(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video"]),
                id_columns=["video_id"],
                fields=[FieldSpec(key=FieldKey(["resolution"]), code_version="1")],
            ),
        ):
            pass

        class VideoFrames(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video_frames"]),
                id_columns=["vid_id", "frame_id"],
                deps=[
                    FeatureDep(
                        feature=Video,
                        rename={"video_id": "vid_id"},
                        lineage=LineageRelationship.expansion(on=["vid_id"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["embedding"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(VideoFrames.spec().key)
        # input_id_columns should use the renamed column
        assert plan.input_id_columns == ["vid_id"]

    def test_identity_with_multiple_upstreams_and_renames(self, graph: FeatureGraph):
        """Identity lineage with multiple upstreams and various renames.
        With per-dep lineage, input_id_columns is the intersection of input columns
        from all dependencies. When deps have different ID columns, the intersection
        is only the common columns.
        """
        class UpstreamA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream_a"]),
                id_columns=["sample_uid", "col_a"],
                fields=[FieldSpec(key=FieldKey(["value_a"]), code_version="1")],
            ),
        ):
            pass

        class UpstreamB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["upstream_b"]),
                id_columns=["sample_uid", "col_b"],
                fields=[FieldSpec(key=FieldKey(["value_b"]), code_version="1")],
            ),
        ):
            pass

        class Downstream(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["downstream"]),
                id_columns=["sample_uid", "renamed_a", "renamed_b"],
                deps=[
                    FeatureDep(feature=UpstreamA, rename={"col_a": "renamed_a"}),
                    FeatureDep(feature=UpstreamB, rename={"col_b": "renamed_b"}),
                ],
                fields=[FieldSpec(key=FieldKey(["result"]), code_version="1")],
            ),
        ):
            pass

        plan = graph.get_feature_plan(Downstream.spec().key)
        # input_id_columns is the intersection of:
        # - UpstreamA (identity): ["sample_uid", "renamed_a"] (after rename)
        # - UpstreamB (identity): ["sample_uid", "renamed_b"] (after rename)
        # Intersection: ["sample_uid"]
        assert set(plan.input_id_columns) == {"sample_uid"}

