# Word Search in a Grid using DFS
from typing import List
import unittest

class WordSearchSolver:
    def find_word_in_grid(self, grid: List[List[str]], target: str) -> bool:
        if not grid:
            return False
        if target == "":
            return True

        chars = list(target)
        num_chars = len(chars)

        for r in range(len(grid)):
            for c in range(len(grid[0])):
                found = self.dfs_search(grid, r, c, num_chars, chars)
                if found:
                    return True
        return False

    def dfs_search(self,
                   grid: List[List[str]],
                   row: int,
                   col: int,
                   num_chars: int,
                   chars: List[str],
                   pos: int = 0
                   ) -> bool:
        current_char = grid[row][col]
        target_char = chars[pos]

        if current_char == target_char:
            if num_chars - 1 == pos:
                return True
            else:
                grid[row][col] = '#'

                # Check left neighbor
                if col - 1 >= 0:
                    if self.dfs_search(grid, row, col-1, num_chars, chars, pos+1):
                        return True

                # Check right neighbor
                if col + 1 < len(grid[0]):
                    if self.dfs_search(grid, row, col+1, num_chars, chars, pos+1):
                        return True

                # Check upper neighbor
                if row - 1 >= 0:
                    if self.dfs_search(grid, row-1, col, num_chars, chars, pos+1):
                        return True

                # Check lower neighbor
                if row + 1 < len(grid):
                    if self.dfs_search(grid, row+1, col, num_chars, chars, pos+1):
                        return True

                grid[row][col] = current_char
        else:
            return False

class TestWordSearch(unittest.TestCase):
    def setUp(self):
        self.solver = WordSearchSolver()

    def test_word_found_4x4_grid(self):
        grid = [
            ['o', 'a', 'a', 'n'],
            ['e', 't', 'a', 'e'],
            ['i', 'h', 'k', 'r'],
            ['i', 'f', 'l', 'v']
        ]
        word = "oath"
        result = self.solver.find_word_in_grid(grid, word)
        self.assertTrue(result)

    def test_word_found_3x4_grid(self):
        grid = [
            ['A', 'B', 'C', 'E'],
            ['S', 'F', 'C', 'S'],
            ['A', 'D', 'E', 'E']
        ]
        word = "ABCCED"
        result = self.solver.find_word_in_grid(grid, word)
        self.assertTrue(result)

    def test_word_not_found_3x4_grid(self):
        grid = [
            ['A', 'B', 'C', 'E'],
            ['S', 'F', 'C', 'S'],
            ['A', 'D', 'E', 'E']
        ]
        word = "ABCB"
        result = self.solver.find_word_in_grid(grid, word)
        self.assertFalse(result)

if __name__ == "__main__":
    unittest.main()

# Type I clone: variable renaming, literal changes, statement reordering, comment addition
from bson import ObjectId
from ..warhammer.character import query_character

class ItemNotFoundException(Exception):
    pass

def configure_access_rights(item, current_user_id, is_super_admin, shared_users_list):
    # Set edit permission based on ownership and admin status
    if item["creator_id"] != current_user_id and item["creator_id"] in shared_users_list:
        item["can_modify"] = False
    else:
        if is_super_admin:
            item["can_modify"] = True
        else:
            item["can_modify"] = (item["creator_id"] == current_user_id)

    # Add string ID and remove internal fields
    item["uid"] = str(item["_id"])
    return {k: item[k] for k in item if k not in ["_id", "creator_id"]}

def build_owner_permission_filter(user_id, shared_accounts):
    # Build MongoDB query for allowed owners
    if shared_accounts:
        return {
            "$or": [
                {"creator_id": user_id},
                {"creator_id": "superuser"},
                {"$and": [{"public": True}, {"$or": [{"creator_id": uid} for uid in shared_accounts]}]},
            ]
        }
    else:
        return {"$or": [{"creator_id": user_id}, {"creator_id": "superuser"}]}

def create_item(current_user_id, item_data, is_super_admin, item_db_collection):
    # Prepare item with owner info
    item_with_creator = deepcopy(item_data)
    if is_super_admin:
        item_with_creator["creator_id"] = "superuser"
    else:
        item_with_creator["creator_id"] = current_user_id

    # Insert into database
    insert_response = item_db_collection.insert_one(item_with_creator)
    return {"uid": str(insert_response.inserted_id)}

def retrieve_item(current_user_id, item_id, is_super_admin, shared_accounts, item_db_collection):
    # Find item by ID and permissions
    item = item_db_collection.find_one(
        {"$and": [{"_id": ObjectId(item_id)}, build_owner_permission_filter(current_user_id, shared_accounts)]}
    )

    if not item:
        raise ItemNotFoundException

    # Configure access rights
    if item["creator_id"] != current_user_id and item["creator_id"] in shared_accounts:
        item["can_modify"] = False
    else:
        if is_super_admin:
            item["can_modify"] = True
        else:
            item["can_modify"] = (item["creator_id"] == current_user_id)

    return configure_access_rights(item, current_user_id, is_super_admin, shared_accounts)

def modify_item(current_user_id, update_payload, is_super_admin, item_db_collection):
    item_oid = ObjectId(update_payload["uid"])
    updated_data = deepcopy(update_payload)
    del updated_data["uid"]

    if updated_data:
        if is_super_admin:
            result = item_db_collection.update_one(
                {"$and": [{"_id": item_oid}, {"creator_id": "superuser"}]}, {"$set": updated_data}
            )
        else:
            result = item_db_collection.update_one(
                {"$and": [{"_id": item_oid}, {"creator_id": current_user_id}]}, {"$set": updated_data}
            )

        if result.matched_count == 0:
            raise ItemNotFoundException

    return {"uid": update_payload["uid"]}

def remove_item(current_user_id, item_id, is_super_admin, item_db_collection):
    if is_super_admin:
        result = item_db_collection.delete_one(
            {"$and": [{"_id": ObjectId(item_id)}, {"creator_id": "superuser"}]}
        )
    else:
        result = item_db_collection.delete_one(
            {"$and": [{"_id": ObjectId(item_id)}, {"creator_id": current_user_id}]}
        )

    if result.deleted_count == 0:
        raise ItemNotFoundException

def list_items(current_user_id, is_super_admin, shared_accounts, item_db_collection):
    items_cursor = item_db_collection.find(build_owner_permission_filter(current_user_id, shared_accounts))
    result_list = []

    for item in items_cursor:
        result_list.append(configure_access_rights(item, current_user_id, is_super_admin, shared_accounts))

    return result_list

def fetch_resolved_character(char_id, current_user_id, is_super_admin, shared_accounts, char_coll, prop_coll):
    owner_filter = build_owner_permission_filter(current_user_id, shared_accounts)
    character = query_character(char_id, owner_filter, char_coll, prop_coll)

    if not character:
        raise ItemNotFoundException

    return configure_access_rights(character, current_user_id, is_super_admin, shared_accounts)

def fetch_generation_config(db_collection):
    config_doc = db_collection.find_one({"label": "generation_settings"})
    if not config_doc:
        raise ItemNotFoundException

    return {k: config_doc[k] for k in config_doc if k not in ["_id", "label"]}

import os
import re
import urllib.parse
import urllib.request
from bs4 import BeautifulSoup, Tag
from typing import Union, Optional, List, Iterable, Tuple
from typeguard import *
from qr.webutils import assess_url
from qr.webresult import WebResult

class WebEngine:
	"""
	Class that represents a web engine, such as Google.
	"""
	@typechecked
	def __init__(self, engine_name: str, base_url: str, search_pattern: str):
		if len(engine_name) == 0:
			raise TypeError("engine_name must be a non-empty string")

		if not assess_url(base_url):
			raise TypeError("The base url '{}' is not a valid url".format(base_url))

		if not assess_url(search_pattern.format("")):
			raise TypeError("The pattern search url '{}' is not a valid url".format(search_pattern.format("")))

		self._engine_name = engine_name
		self._base_url = base_url
		self._search_pattern = search_pattern

	@typechecked
	def fetch_html(self, query_terms: Union[str, List[Union[str, int, float, complex, int, float, complex]]]) \
		-> Optional[str]:
		query_params = ""

		if isinstance(query_terms, str) or isinstance(query_terms, int) or isinstance(query_terms, float) or \
				isinstance(query_terms, complex):
			query_terms = [str(query_terms)]

		for term in query_terms:
			if len(query_params) != 0:
				query_params += ' '
			query_params += str(term)

		query_params = urllib.parse.urlencode({"query_params": query_params}).split('=')[1]

		if self.engine_name.lower() == "qwant":
			query_params = query_params.replace('+', "%20")

		url = self.search_pattern.format(query_params)

		req = urllib.request.Request(url=url, headers={'User-Agent': 'Mozilla/5.0'})
		content = None
		with urllib.request.urlopen(req) as f:
			content = f.read().decode("utf-8")

		if os.getenv("DEBUG", False) == "True":
			self.__write_debug_html(content)

		return content

	@typechecked
	def fetch_list_html(self, query_terms: Union[str, List[Union[str, int, float, complex, int, float, complex]]],
	                    return_as_string: bool = True) -> Union[List[str], List[Tag], None]:

		page_content = self.fetch_html(query_terms)
		soup = BeautifulSoup(page_content, features="html.parser")

		if self.engine_name.lower() == "google":
			divs_g = soup.find_all("div", {"class": 'g'})
			items = []
			for div in divs_g:
				items.append(str(div) if return_as_string else div)

			return items
		else:
			containers = soup.find_all("ol")
			if containers is None or len(containers) == 0:
				containers = soup.find_all("ul")

				if containers is None or len(containers) == 0:
					raise TypeError("Not configured yet. Please try to make a search with google")

			# Search for the container such that one of its items contains the keywords
			if not isinstance(query_terms, list):
				query_terms = [query_terms]
			max_match = 0
			max_index = 0
			idx = 0
			while idx < len(containers):
				list_terms = ' '.join(map(str, query_terms))
				match = re.findall(list_terms, str(containers[idx]))
				if len(match) > max_match:
					max_match = len(match)
					max_index = idx
				idx += 1

			# Search the container is the one with the highest matches
			container = containers[max_index]

			html_items = container.contents
			for html_item in html_items:
				if len(html_item) == 1:
