# Custom exception for small failures
class MinorError(Exception):
    def __init__(self, msg=None):
        self.msg = "no message" if msg is None else msg
    def __str__(self) -> str:
        return f"MinorError: {self.msg}"

try:
    raise MinorError()
except MinorError as error:
    print(error)  # MinorError: no message

try:
    raise MinorError("encountered a minor issue")
except MinorError as error:
    print(error)  # MinorError: encountered a minor issue

# Modified version of FileIndex class with renamed variables and reordered logic
import sqlite3
from pathlib import Path
from typing import Iterable, Optional, Union
from .threadsafe_db import ThreadsafeDatabase, retry_while_locked
from .iterator_stack import IteratorStack
from .optional_generator import optional_generator
from .file_index_node import FileIndexNode

# Use the directory containing this file as base for scripts
base_dir = Path(__file__).parent
index_creation_script_path = base_dir / 'create_index.sqlite'

class FileIndex:
    db_connection: sqlite3.Connection
    database: ThreadsafeDatabase

    @classmethod
    def from_existing(cls, db_path: Union[Path, str]):
        instance = cls()
        instance.db_connection = sqlite3.Connection(db_path, check_same_thread=False)
        instance.db_connection.execute('PRAGMA foreign_keys=ON;')
        instance.db_connection.row_factory = sqlite3.Row
        instance.database = ThreadsafeDatabase(instance.db_connection)
        return instance

    @classmethod
    def initialize_new(cls, db_path: Union[Path, str]):
        instance = cls.from_existing(db_path)
        with open(index_creation_script_path) as sql_script:
            instance.database.execute_script(sql_script.read())
        return instance

    @classmethod
    def open_or_create(cls, db_path: Union[Path, str]):
        target_path = Path(db_path)
        if target_path.exists():
            return cls.from_existing(target_path)
        else:
            return cls.initialize_new(target_path)

    def __get_parent_identifier(self, item_path: Path, db_cursor: sqlite3.Cursor, path_cache: dict):
        parent_path: Path = item_path.parent
        try:
            return path_cache[parent_path]
        except KeyError:
            if item_path == parent_path:
                path_cache[parent_path] = None
                return None
            parent_node = self.get_folder_node_by_path(parent_path, acquire_lock=False)
            if parent_node:
                path_cache[parent_path] = parent_node.id
                return parent_node.id
            else:
                grandparent_id = self.__get_parent_identifier(parent_path, db_cursor, path_cache)
                retry_while_locked(
                    db_cursor.execute,
                    'INSERT INTO folders (path, parent) VALUES (?, ?)',
                    (str(parent_path), grandparent_id)
                )
                path_cache[parent_path] = db_cursor.lastrowid
                return db_cursor.lastrowid

    @optional_generator
    def add_entries(
            self,
            entry_paths: Iterable[Union[Path, str]],
            traverse_subdirs=True,
            report_paths=False,
            # report_nodes=False,
            force_rescan=False
    ):
        with self.database.lock:
            parent_lookup = dict()
            cursor = self.database.connection.cursor()
            traversal_stack = IteratorStack()
            traversal_stack.push(map(Path, entry_paths))

            for current_path in traversal_stack:  # type: Path
                if report_paths:
                    yield current_path

                parent_id = self.__get_parent_identifier(
                    current_path, cursor, parent_lookup
                )

                if current_path.is_file():
                    try:
                        retry_while_locked(
                            cursor.execute,
                            'INSERT INTO files (path, parent) VALUES (?, ?)',
                            (str(current_path), parent_id)
                        )
                    except sqlite3.IntegrityError:
                        continue
                else:
                    try:
                        retry_while_locked(
                            cursor.execute,
                            'INSERT INTO folders (path, parent) VALUES (?, ?)',
                            (str(current_path), parent_id)
                        )
                    except sqlite3.IntegrityError:
                        if not force_rescan:
                            continue
                    else:
                        parent_lookup[current_path] = cursor.lastrowid

                    if traverse_subdirs:
                        traversal_stack.push(current_path.iterdir())

            retry_while_locked(self.db_connection.commit)

    def get_file_entry_by_id(self, file_identifier, needs_lock=False) -> Optional[FileIndexNode]:
        for row in self.database.execute(
            'SELECT * FROM files WHERE id=?', (file_identifier,),
            use_self_cursor=True, acquire_lock=needs_lock
        ):
            return FileIndexNode(self, row)

    def get_folder_entry_by_id(self, folder_identifier, needs_lock=False) -> Optional[FileIndexNode]:
        for row in self.database.execute(
            'SELECT * FROM folders WHERE id=?', (folder_identifier,),
            use_self_cursor=True, acquire_lock=needs_lock
        ):
            return FileIndexNode(self, row)

    def get_file_entry_by_path(self, path: Union[Path, str], needs_lock=False) -> Optional[FileIndexNode]:
        for row in self.database.execute(
            'SELECT * FROM files WHERE path=?', (str(path),),
            use_self_cursor=True, acquire_lock=needs_lock
        ):
            return FileIndexNode(self, row)

    def get_folder_entry_by_path(self, path: Union[Path, str], needs_lock=False) -> Optional[FileIndexNode]:
        for row in self.database.execute(
            'SELECT * FROM folders WHERE path=?', (str(path),),
            use_self_cursor=True, acquire_lock=needs_lock
        ):
            return FileIndexNode(self, row)

    def optimize(self):
        self.database.execute('VACUUM')

    def find_entries(self, search_term, include_directories=False):
        pattern = f'%{search_term}%'
        if include_directories:
            results = self.database.execute(
                'SELECT * FROM folders WHERE path LIKE ? '
                'UNION ALL '
                'SELECT * FROM files WHERE path LIKE ? '
                'ORDER BY path COLLATE NOCASE ASC;',
                (pattern, pattern)
            )
        else:
            results = self.database.execute(
                'SELECT * FROM files WHERE path LIKE ? '
                'ORDER BY path COLLATE NOCASE ASC',
                (pattern,)
            )
        yield from map(lambda row: FileIndexNode(self, row), results)

    def list_root_entries(self):
        results = self.database.execute(
            'SELECT * FROM folders WHERE parent IS NULL '
            'UNION ALL '
            'SELECT * FROM files WHERE parent IS NULL '
            'ORDER BY path COLLATE NOCASE ASC'
        )
        yield from map(lambda row: FileIndexNode(self, row), results)

