# Modified version of the Flow class with Type I clone transformations
from dataclasses import dataclass
import logging
from typing import Deque, Dict, List, Tuple, Type, Union, Set, Generic, get_args, get_origin, Optional
from typedflow.nodes import ConsumerNode, ProviderNode, DumpNode, LoaderNode

__all__ = ['Pipeline']
logger = logging.getLogger(__file__)
GraphElement = Union[ProviderNode, ConsumerNode]

@dataclass
class Pipeline:
    final_nodes: List[DumpNode]
    verbose: bool = False

    def verify(self) -> None:
        """
        not implemented because Python Generic doesn't offer
        any ways to access to the actual type
        """
        self.type_check()

    def fetch_loader_nodes_with_broadcast(self) -> List[LoaderNode]:
        """
        Get load nodes. While node checking, all the debug status
        is attachted to all nodes.
        Therefore, this method should pass all the nodes in the DAG.
        """
        loaders: List[LoaderNode] = []
        visited: List[GraphElement] = []
        candidates: Deque[GraphElement] = Deque()
        candidates.extend(self.final_nodes)

        while True:
            try:
                current_node: GraphElement = candidates.pop()
            except IndexError:
                return loaders

            if current_node in visited:
                continue
            else:
                visited.append(current_node)

            current_node.debug: bool = self.verbose

            if isinstance(current_node, LoaderNode):
                if current_node not in loaders:
                    loaders.append(current_node)
            else:
                candidates.extend([predecessor for predecessor in current_node.precs.values()
                                   if predecessor not in visited])

    def execute(self,
                check: bool = True) -> None:
        """
        Execute pipeline.
        """
        if check:
            self.verify()

        iteration_id: int = 0
        while True:
            for node in self.final_nodes:
                node.run_and_dump(batch_id=iteration_id)

            if all([node.finished for node in self.final_nodes]):
                return

    def is_subclass(self, child: Type, parent: Type) -> bool:
        """
        This is not a static method in order to be used recursively.
        >>> is_subclass(int, object)
        True
        >>> is_subclass(int, int)
        True
        >>> is_subclass(List[int], Iterable[int])
        True
        >>> is_subclass(Iterable[int], List[int])
        False
        """
        if child == parent:
            return True

        _child_orig: Optional[Type] = get_origin(child)
        if _child_orig is None:  # i.e. child_orig is primitive
            return False

        child_orig: Type = _child_orig
        _parent_orig: Optional[Type] = get_origin(parent)
        if _parent_orig is None:
            return False

        parent_orig: Type = _parent_orig

        if issubclass(child_orig, Generic) and issubclass(parent_orig, Generic):
            # Compare original type
            if not self.is_subclass(parent_orig, child_orig):
                return False

            # compare arguments
            for child_arg, parent_arg in zip(get_args(child), get_args(parent)):
                if not self.is_subclass(child_arg, parent_arg):
                    return False

        return True

    def type_check(self) -> None:
        """
        Check type consistency with inputs/outputs.
        Return nothing when there are no errors, unless raise AssertionError.
        """
        queue: Deque[Tuple[ConsumerNode, Dict[str, ProviderNode]]] = Deque()

        # initially check all final nodes
        for node in self.final_nodes:
            queue.append(
                (node, {name: upstream_node.get_return_type()
                        for name, upstream_node in node.precs.items()}))

        while True:
            try:
                current_node, upstream_dict = queue.pop()
            except IndexError:
                break

            argument_types: Type = current_node.get_arg_types()
            parameter_names: Set[str] = set(argument_types.keys())
            assert parameter_names == set(upstream_dict.keys()), f'Invalid arguments. Expected: {argument_types}, Actual: {upstream_dict}'

            for param in parameter_names:
                if not self.is_subclass(upstream_dict[param], argument_types[param]):
                    raise AssertionError(f'Invalid type for arg {param}: Expected {argument_types[param]}, Actual {upstream_dict[param]}')

            for upstream_node in current_node.precs.values():
                if isinstance(upstream_node, ConsumerNode):
                    queue.append(
                        (upstream_node, {name: upstream_upstream.get_return_type()
                                        for name, upstream_upstream in upstream_node.precs.items()}))

        # check batch_size
        loader_nodes: List[LoaderNode] = self.fetch_loader_nodes_with_broadcast()
        assert len({loader.batch_size for loader in loader_nodes}) == 1

import numpy as np
from .concrete_value import ConcreteValue
from ..ir.type import Tensor

def _type_error(op, *args):
    raise ValueError(f"Type mismatch: operation\n{op}\nreceived arguments\n{tuple(args)}")

def _binary_op_type_check(op, x, y):
    if (
        isinstance(x, Tensor)
        and isinstance(y, ConcreteValue)
        and (y.val.dtype == np.float32 or y.val.dtype == np.float64)
    ):
        return x
    elif (
        isinstance(x, ConcreteValue)
        and isinstance(y, Tensor)
        and (x.val.dtype == np.float32 or x.val.dtype == np.float64)
    ):
        return y
    else:
        _type_error(op, x, y)

def _gather_shape_inference(op, x, y):
    if not (
        isinstance(x, Tensor)
        and isinstance(y, ConcreteValue)
        and x.shape is not None
        and y.val is not None
        and x.device == y.device
        and isinstance(y.val, np.ndarray)
    ):
        _type_error(op, x, y)

    if x.device is None:
        _type_error(op, x, y)

    device = x.device

    axis = op.attributes.get("axis", 0)

    if isinstance(y.val, np.ndarray) and axis == 0:
        # Direct shape computation for common case
        new_shape = y.val.shape + x.shape[1:]
    else:
        # General case using NumPy
        temp_arr = np.zeros(x.shape)
        new_shape = np.take(temp_arr, y.val.astype(np.int64), axis=axis).shape

    return Tensor(dtype=x.dtype, shape=new_shape, device=device)

def _reshape_shape_inference(op, x, y):
    if not (
        isinstance(x, Tensor)
        and isinstance(y, ConcreteValue)
        and isinstance(y.val, np.ndarray)
    ):
        _type_error(op, x, y)

    y_list = y.val.tolist()

    if y_list.count(-1) > 1:
        _type_error(op, x, y_list)

    new_dims = []
    for dim in y_list:
        if dim != -1:
            new_dims.append(dim)
        else:
            total_size = int(np.prod(x.shape))
            known_dims_product = np.prod([d for d in y_list if d != -1])
            new_dims.append(int(total_size / known_dims_product * -1))

    return Tensor(shape=tuple(new_dims), dtype=x.dtype, device=x.device)

def _power_shape_inference(op, x, y):
    if not (isinstance(x, Tensor) and isinstance(y, ConcreteValue)):
        _type_error(op, x, y)
    return x

def _slice_shape_inference(op, x, starts_val, ends_val, axes_val, steps_val):
    if not (
        isinstance(x, Tensor)
        and isinstance(starts_val, ConcreteValue)
        and isinstance(ends_val, ConcreteValue)
        and isinstance(axes_val, ConcreteValue)
        and isinstance(steps_val, ConcreteValue)
        and isinstance(starts_val.val, np.ndarray)
        and isinstance(ends_val.val, np.ndarray)
        and isinstance(axes_val.val, np.ndarray)
        and (isinstance(steps_val.val, np.ndarray) or isinstance(steps_val.val, np.int64))
        and x.device == starts_val.device
        and x.device == ends_val.device
        and x.device == axes_val.device
        and x.device == steps_val.device
    ):
        _type_error(op, x, starts_val, ends_val, axes_val, steps_val)

    starts = starts_val.val
    ends = ends_val.val
    axes = axes_val.val
    steps = steps_val.val

    if len(steps.shape) == 0:
        steps = np.expand_dims(steps, 0)

    assert -1 not in starts.tolist()
    assert -1 not in ends.tolist()
    assert -1 not in axes.tolist()

    if steps is None:
        steps = [1] * len(starts)
    elif isinstance(steps, np.int64):
        steps = [steps] * len(starts)
    else:
        assert len(steps) == len(starts)

    slices_dict = {
        axis: slice(s, e, step) for (s, e, axis, step) in zip(starts, ends, axes, steps)
    }

    slices_tuple = tuple(slices_dict.get(d, slice(None)) for d in range(len(x.shape)))

    output_dims = []
    for idx, slc in enumerate(slices_tuple):
        start_idx = slc.start
        end_idx = slc.stop
        step_size = slc.step

        if start_idx is None:
            start_idx = 0
        if end_idx is None:
            end_idx = x.shape[idx]
        if step_size is None:
            step_size = 1

        output_dims.append(int(np.ceil((end_idx - start_idx) / step_size)))

    return Tensor(shape=tuple(output_dims), dtype=x.dtype, device=x.device)

def _tensor_shape_extraction(op, x):
    if not isinstance(x, Tensor):
        _type_error(op, x)
    return ConcreteValue(np.array(x.shape, dtype=np.int64), x.device)

MixedOperatorRegistry = {
    ("Add", (Tensor, ConcreteValue)): _binary_op_type_check,
    ("Div", (Tensor, ConcreteValue)): _binary_op_type_check,
    ("Gather", (Tensor, ConcreteValue)): _gather_shape_inference,
    ("Mul", (Tensor, ConcreteValue)): _binary_op_type_check,
    ("Reshape", (Tensor, ConcreteValue)): _reshape_shape_inference,
    ("Pow", (Tensor, ConcreteValue)): _power_shape_inference,
    (
        "Slice",
        (Tensor, ConcreteValue, ConcreteValue, ConcreteValue, ConcreteValue),
    ): _slice_shape_inference,
    ("Shape", (Tensor,)): _tensor_shape_extraction,
    ("Sub", (ConcreteValue, Tensor)): _binary_op_type_check,
}

import json
import os
from typing import (
    Any, Dict, NoReturn, Optional
)
from dbt import flags
from dbt import tracking
from dbt.clients.jinja import undefined_error, get_rendered
from dbt.exceptions import raise_compiler_error, MacroReturn
from dbt.logger import GLOBAL_LOGGER as logger
from dbt.utils import merge
from dbt.version import __version__ as dbt_version
import yaml

# These modules are added to the context. Consider alternative
# approaches which will extend well to potentially many modules
import pytz
import datetime

def get_pytz_module_context() -> Dict[str, Any]:
    context_exports = pytz.__all__  # type: ignore
    return {
        name: getattr(pytz, name) for name in context_exports
    }

def get_datetime_module_context() -> Dict[str, Any]:
    context_exports = [
        'date',
        'datetime',
        'time',
        'timedelta',
        'tzinfo'
    ]
    return {
        name: getattr(datetime, name) for name in context_exports
    }

def get_context_modules() -> Dict[str, Dict[str, Any]]:
    return {
        'pytz': get_pytz_module_context(),
        'datetime': get_datetime_module_context(),
    }

class ContextMember:
    def __init__(self, value, name=None):
        self.name = name
        self.inner = value

    def key(self, default):
        if self.name is None:
            return default
        return self.name

def contextmember(value):
    if isinstance(value, str):
        return lambda v: ContextMember(v, name=value)
    return ContextMember(value)

def contextproperty(value):
    if isinstance(value, str):
        return lambda v: ContextMember(property(v), name=value)
    return ContextMember(property(value))

class ContextMeta(type):
    def __new__(mcls, name, bases, dct):
        context_members = {}
        context_attrs = {}
        new_dct = {}

        for base in bases:
            context_members.update(getattr(base, '_context_members_', {}))
            context_attrs.update(getattr(base, '_context_attrs_', {}))

        for key, value in dct.items():
            if isinstance(value, ContextMember):
                context_key = value.key(key)
                context_members[context_key] = value.inner
                context_attrs[context_key] = key
                value = value.inner
            new_dct[key] = value

        new_dct['_context_members_'] = context_members
        new_dct['_context_attrs_'] = context_attrs
        return type.__new__(mcls, name, bases, new_dct)

class Var:
    UndefinedVarError = "Required var '{}' not found in config:\nVars "\
                        "supplied to {} = {}"
    _VAR_NOTSET = object()

    def __init__(self, model, context, overrides):
        self.model = model
        self.context = context
        # These are hard-overrides (eg. CLI vars) that should take
        # precedence over context-based var definitions
        self.overrides = overrides

        if model is None:
            # during config parsing we have no model and no local vars
            self.model_name = '<Configuration>'
            local_vars = {}
        else:
            self.model_name = model.name
            local_vars = model.local_vars()

        self.local_vars = merge(local_vars, overrides)

    def pretty_dict(self, data):
        return json.dumps(data, sort_keys=True, indent=4)

    def get_missing_var(self, var_name):
        pretty_vars = self.pretty_dict(self.local_vars)
        msg = self.UndefinedVarError.format(
            var_name, self.model_name, pretty_vars
        )
        raise_compiler_error(msg, self.model)

    def assert_var_defined(self, var_name, default):
        if var_name not in self.local_vars and default is self._VAR_NOTSET:
            return self.get_missing_var(var_name)

    def get_rendered_var(self, var_name):
        raw = self.local_vars[var_name]
        # if bool/int/float/etc are passed in, don't compile anything
        if not isinstance(raw, str):
            return raw
        return get_rendered(raw, self.context)

    def __call__(self, var_name, default=_VAR_NOTSET):
        if var_name in self.local_vars:
            return self.get_rendered_var(var_name)
        elif default is not self._VAR_NOTSET:
            return default
        else:
            return self.get_missing_var(var_name)

class BaseContext(metaclass=ContextMeta):
    def __init__(self, cli_vars):
        self._ctx = {}
        self.cli_vars = cli_vars

    def generate_builtins(self):
        builtins: Dict[str, Any] = {}
        for key, value in self._context_members_.items():
            if hasattr(value, '__get__'):
                # handle properties, bound methods, etc
                value = value.__get__(self)
            builtins[key] = value
        return builtins

    def to_dict(self):
        self._ctx['context'] = self._ctx
        builtins = self.generate_builtins()
        self._ctx['builtins'] = builtins
        self._ctx.update(builtins)
        return self._ctx

    @contextproperty
    def dbt_version(self) -> str:
        return dbt_version

    @contextproperty
    def var(self) -> Var:
        return Var(None, self._ctx, self.cli_vars)

    @contextmember
    @staticmethod
    def env_var(var: str, default: Optional[str] = None) -> str:
        if var in os.environ:
            return os.environ[var]
        elif default is not None:
            return default
        else:
            msg = f"Env var required but not provided: '{var}'"
            undefined_error(msg)

    if os.environ.get('DBT_MACRO_DEBUGGING'):
        @contextmember
        @staticmethod
        def debug():
            import sys
            import ipdb  # type: ignore
            frame = sys._getframe(3)
            ipdb.set_trace(frame)
            return ''

    @contextmember('return')
    @staticmethod
    def _return(value: Any) -> NoReturn:
        raise MacroReturn(value)

    @contextmember
    @staticmethod
    def fromjson(string: str, default: Any = None) -> Any:
        try:
            return json.loads(string)
        except ValueError:
            return default

    @contextmember
    @staticmethod
    def tojson(
        value: Any, default: Any = None, sort_keys: bool = False
    ) -> Any:
        try:
            return json.dumps(value, sort_keys=sort_keys)
        except ValueError:
            return default

    @contextmember
    @staticmethod
    def fromyaml(value: str, default: Any = None) -> Any:
        try:
            return yaml.safe_load(value)
        except (AttributeError, ValueError, yaml.YAMLError):
            return default

    # safe_dump defaults to sort_keys=True, but we act like json.dumps (the
    # opposite)
    @contextmember
    @staticmethod
    def toyaml(
        value: Any, default: Optional[str] = None, sort_keys: bool = False
    ) -> Optional[str]:
        try:
            return yaml.safe_dump(data=value, sort_keys=sort_keys)
        except (ValueError, yaml.YAMLError):
            return default

    @contextmember
    @staticmethod
    def log(msg: str, info: bool = False) -> str:
        if info:
            logger.info(msg)
        else:
            logger.debug(msg)
        return ''

    @contextproperty
    def run_started_at(self) -> Optional[datetime.datetime]:
        if tracking.active_user is not None:
            return tracking.active_user.run_started_at
        else:
            return None

    @contextproperty
    def invocation_id(self) -> Optional[str]:
        if tracking.active_user is not None:
            return tracking.active_user.invocation_id
        else:
            return None

    @contextproperty
    def modules(self) -> Dict[str, Any]:
        return get_context_modules()

    @contextproperty
    def flags(self) -> Any:
        return flags

def generate_base_context(cli_vars: Dict[str, Any]) -> Dict[str, Any]:
    ctx = BaseContext(cli_vars)
    return ctx.to_dict()

# Modified version of SwankDatabase and related classes with Type I clone transformations
from __future__ import annotations
import abc
import datetime as dt_module
from typing import Iterable, Mapping, Union, Type, Optional, Any
import itertools
import functools
import filelock
import re
import collections.abc
import contextlib
from ..jamming import BaseJamDatabase, Jam, JamId, JamItem, JamKind, JamParchment, JamFileDatabase
from . import utils
from .exceptions import EmptyJam
from ..file_locking import FileLock

class SwankDatabase:
    def __init__(self, jam_db: BaseJamDatabase) -> None:
        self.jam_db = jam_db

    @classmethod
    def create_ethereal(cls) -> SwankDatabase:
        return cls(JamFileDatabase.create_ethereal())

    def get_jam_kind(self, arg: Union[Swank, Type[Swank], str]) -> JamKind:
        fixed_arg = type(arg) if isinstance(arg, Swank) else arg
        return self.jam_db[fixed_arg]

    def get_jam_item(self, swank: Swank) -> JamKind:
        assert swank.has_jam_id_and_index
        return self.get_jam_kind(swank)[swank.jam_id][swank.jam_index]

    def get_swank_type(self, arg: Union[Swank, Type[Swank], str]) -> JamKind:
        if isinstance(arg, str):
            jam_kind_name = arg
            return utils.name_to_type(jam_kind_name)
        else:
            if isinstance(arg, Swank):
                return type(arg)
            elif issubclass(arg, Swank):
                return arg

    def load_swank(self, swank_type_or_name: Union[Type[Swank], str], jam_id: Union[JamId, str],
                   jam_index: int) -> Swank:
        jam_kind = self.get_jam_kind(swank_type_or_name)
        swank_type = self.get_swank_type(swank_type_or_name)
        jam_item = jam_kind[jam_id][jam_index]
        jam = jam_item.read_jam()
        if jam is None:
            raise EmptyJam
        return swank_type._Swank__from_jam(jam, jam_id=jam_id, jam_index=jam_index,
                                           swank_database=self)

    def save_swank(self, swank: Swank) -> None:
        if not swank.has_jam_id_and_index:
            swank.jam_id = JamId.create(block_size=swank.default_block_size)
            swank.jam_index = 0
        jam_item = self.get_jam_item(swank)
        jam = swank._Swank__to_jam()
        jam_item.write_jam(jam)

    def iterate_latest(self, swank_type: Type[Swank]) -> Iterable[Swank]:
        return swank_type.iterate_latest(self)

    def _reduce(self) -> tuple:
        return (type(self), self.jam_db)

    def __eq__(self, other: Any) -> bool:
        return (type(other) == type(self)) and (self._reduce() == other._reduce())

    def __hash__(self) -> int:
        return hash(self._reduce())

    def __repr__(self) -> str:
        return f'{type(self).__name__}({self.jam_db})'

class SwankType(abc.ABCMeta):
    def __new__(mcls, name, bases, dict_) -> Type[Swank]:
        cls = abc.ABCMeta.__new__(mcls, name, bases, dict_)
        if len(cls.mro()) >= 3: # i.e. it's not the base `Swank` type, which doesn't have fields
            cls._Swank__fields = mcls.__get_fields(cls)
        return cls

    def __get_fields(cls) -> dict:
        fields = {}
        existing_names = set()
        for type_ in cls.mro():
            for name, value in vars(type_).items():
                if name in existing_names:
                    # This attribute was already overridden in a subclass, if it's a field we don't
                    # want to include it.
                    continue
                existing_names.add(name)
                if name.startswith('__'):
                    continue
                if isinstance(value, BaseField):
                    assert name not in fields
                    fields[name] = value
        return fields

    def iterate_latest(cls, swank_database: SwankDatabase) -> Iterable[Swank]:
        jam_parchments_by_latest = sorted(
            swank_database.get_jam_kind(cls),
            key=lambda jam_parcment: jam_parcment._get_path().stat().st_mtime,
            reverse=True,
        )
        for jam_parchment in jam_parchments_by_latest:
            for i in reversed(range(len(jam_parchment))):
                yield swank_database.load_swank(cls, jam_parchment.jam_id, i)

    def get_last(cls, swank_database: SwankDatabase) -> Swank:
        try:
            return next(cls.iterate_latest(swank_database))
        except StopIteration:
            raise IndexError

    def get_by_name(cls, swank_database: SwankDatabase, name_substring: str) -> Swank:
        for swank in cls.iterate_latest(swank_database):
            if name_substring in str(swank.jam_id):
                return swank
        raise LookupError

class Swank(metaclass=SwankType):
    default_block_size: int = 1_000
    jam_id: Optional[JamId] = None
    jam_index: Optional[int] = None

    def __init__(self, *, swank_database: SwankDatabase, jam_id: Optional[Union[JamId, str]] = None,
                 jam_index: Optional[int] = None, **kwargs):
        assert (jam_id, jam_index).count(None) in {0, 2}
        self.__field_values = {}
        self.jam_id = None if jam_id is None else JamId.cast(jam_id)
        self.jam_index = jam_index
        self.swank_database = swank_database
        assert set(kwargs) <= set(self._Swank__fields)
        for field_name, field in self.__fields.items():
            try:
                value = kwargs[field_name]
            except KeyError:
                value = field.get_default_value(swank_database)
            setattr(self, field_name, value)

    @property
    def has_jam_id_and_index(self):
        jam_id_exists = (self.jam_id is not None)
        jam_index_exists = (self.jam_index is not None)
        assert jam_id_exists == jam_index_exists
        return jam_id_exists

    @classmethod
    def __from_jam(cls, jam: Jam, *, jam_id: JamId, jam_index: int,
                   swank_database: SwankDatabase) -> Swank:
        fields = cls._Swank__fields
        swank = cls.__new__(cls)
        swank_cache = {(jam_id, jam_index): swank}
        ### Parsing jam into fields: ###############################################################
        #                                                                                          #
        kwargs = {}
        for full_field_name, value in jam.items():
            field_name, field_type_name = full_field_name.split('.')
            field = fields[field_name]
            assert field_type_name == field.field_type_name
            kwargs[field_name] = field.from_jam(value, swank_database=swank_database,
                                                swank_cache=swank_cache)
        #                                                                                          #
        ### Finished parsing jam into fields. ######################################################
        cls.__init__(swank, **kwargs,
                     jam_id=jam_id, jam_index=jam_index, swank_database=swank_database)
        return swank

    def __to_jam(self) -> Jam:
        fields = self._Swank__fields
        return {
            f'{name}.{field_type.field_type_name}':
                field_type.to_jam(getattr(self, name, None), self.swank_database)
            for name, field_type in fields.items()
        }

    @classmethod
    def load(cls, swank_database: SwankDatabase, jam_id: Union[JamId, str],
             jam_index: int) -> Swank:
        return swank_database.load_swank(cls, jam_id=jam_id, jam_index=jam_index)

    def reload(self) -> Swank:
        return type(self).load(self.swank_database, self.jam_id, self.jam_index)

    def save(self, *, all_parchment_fields: bool = True) -> Swank:
        from .fields import ParchmentField
        self.swank_database.save_swank(self)
        if all_parchment_fields:
            for field_name, field in self._Swank__fields.items():
                if isinstance(field, ParchmentField):
                    getattr(self, field_name).save()

    def _reduce(self) -> tuple:
        return (type(self), self.swank_database, self.jam_id, self.jam_index)

    def __eq__(self, other: Any) -> bool:
        return (
            (type(other) == type(self)) and
            self.has_jam_id_and_index and
            (self._reduce() == other._reduce())
        )

    def __hash__(self) -> int:
        return hash(self._reduce())

    def __repr__(self) -> str:
        text = ', '.join(
            f'{name}={value}' for name, value in self.__field_values.items()
        )
        return f'<{type(self).__name__}: {text}>'

    def to_savvy_content(self) -> tuple:
        return (str(self.jam_id), self.jam_index)

    @property
    @functools.cache
    def parchment_lock(self):
        jam_item = self.swank_database.get_jam_item(self)
        lock_path = jam_item.jam_parchment._get_lock_path()
        return FileLock(lock_path)

class SwankRef:
    def __init__(self, swank_database: SwankDatabase, swank_type: Type[Swank], jam_id: JamId,
                 jam_index: int) -> None:
        self.swank_database = swank_database
        self.swank_type = swank_type
        self.swank_type_name = utils.type_to_name(swank_type)
        self.jam_kind_name = utils.type_to_name(swank_type)
        assert isinstance(jam_id, JamId)
        self.jam_id = jam_id
        assert isinstance(jam_index, int)
        self.jam_index = jam_index

    @property
    def jam_item(self) -> JamItem:
        return self.swank_database.jam_database[self.jam_kind_name][self.jam_id][self.jam_index]

    def get(self) -> Swank:
        return self.swank_database.load_swank(self.jam_kind_name, self.jam_id, self.jam_index)

    @staticmethod
    def from_swank_or_ref(swank_or_ref: Optional[Union[Swank, SwankRef]]) -> Optional[SwankRef]:
        if swank_or_ref is None:
            return None
        elif isinstance(swank_or_ref, Swank):
            swank = swank_or_ref
            assert swank.has_jam_id_and_index
            return SwankRef(swank.swank_database, type(swank), swank.jam_id, swank.jam_index)
        else:
            assert isinstance(swank_or_ref, SwankRef)
            return swank_or_ref

    def _reduce(self) -> tuple:
        return (type(self), self.swank_database, self.swank_type, self.jam_id, self.jam_index)

    @property
    @functools.cache
    def parchment_lock(self):
        jam_kind = self.swank_database.get_jam_kind(self.swank_type)
        jam_item = jam_kind[self.jam_id][self.jam_index]
        lock_path = jam_item.jam_parchment._get_lock_path()
        return FileLock(lock_path)

    @contextlib.contextmanager
    def lock_and_load(self, *, save: bool = False) -> Swank:
        with self.parchment_lock:
            yield (swank := self.get())
            if save:
                swank.save()

    @contextlib.contextmanager
    def lock_and_load_or_create(self, *, save: bool = False) -> Swank:
        with self.parchment_lock:
            try:
                swank = self.get()
            except EmptyJam:
                swank = self.swank_type(swank_database=self.swank_database,
                                        jam_id=self.jam_id,
                                        jam_index=self.jam_index)
            yield swank
            if save:
                swank.save()

    def __repr__(self) -> str:
        return f'<{type(self).__name__}: {self.swank_type_name}>'

    def __eq__(self, other: Any) -> bool:
        return (type(other) == type(self)) and (self._reduce() == other._reduce())

    def __hash__(self) -> int:
        return hash(self._reduce())

