from enum import Enum


def check_numeric_sequence(values, converter, agg_func):
    try:
        converted = [converter(v) for v in values]
    except:
        return None

    for val in converted:
        if np.isnan(val) or np.isinf(val):
            return None

    return converter(agg_func(converted))


def evaluate_metrics(data, hostname, subscribers):
    data = data.copy()

    empty_indices = []
    for idx, recv in enumerate(data['received']):
        if int(recv.strip()) == 0:
            empty_indices.append(idx)

    if len(empty_indices) > 0.75 * len(data['received']):
        # reject if more than 75% entries are empty
        return None

    for field in data.keys():
        subset = data[field]
        for idx in reversed(empty_indices):
            del subset[idx]
        data[field] = subset

    received_count = check_numeric_sequence(data['received'], int, np.sum)
    if received_count is None or received_count == 0:
        return None

    sent_count = check_numeric_sequence(data['sent'], int, np.sum)
    if sent_count is None:
        return None

    lost_count = check_numeric_sequence(data['lost'], int, np.sum)
    if lost_count is None:
        return None

    total_data = check_numeric_sequence(data['data_received'], int, np.sum)
    if total_data is None:
        return None

    min_latency = check_numeric_sequence(data['latency_min'], float, np.min)
    if min_latency is None:
        return None

    max_latency = check_numeric_sequence(data['latency_max'], float, np.max)
    if max_latency is None:
        return None

    avg_latency = check_numeric_sequence(data['latency_mean'], float, np.mean)
    if avg_latency is None:
        return None

    var_latency = check_numeric_sequence(data['latency_variance'], float, np.mean)
    if var_latency is None:
        return None

    cpu_load = check_numeric_sequence(data['cpu_usage'], float, np.mean)
    if cpu_load is None:
        return None

    mem_usage = check_numeric_sequence([data['ru_maxrss'][-1]], float, np.mean)
    if mem_usage is None:
        return None

    mem_usage /= 1000.0

    if 'mac' in hostname.lower():
        # getrusage() on macOS returns bytes
        mem_usage /= 1024.0

    return {
        'received': received_count,
        'sent': sent_count,
        'lost': lost_count,
        'data_received': total_data,
        'latency_min': min_latency,
        'latency_max': max_latency,
        'latency_mean': avg_latency,
        'latency_variance': var_latency,
        'jitter': np.sqrt(var_latency + 0.000001),
        'cpu_usage': cpu_load,
        'rel_cpu_usage': cpu_load / float(received_count),
        'ram_usage': mem_usage,
        'length': len(data['data_received']),
        'throughput': total_data / 1024.0 / 1024.0 / float(len(data['data_received'])) / float(subscribers)
    }


class Outcome(Enum):
    CYCLONEDDS_SUCCESS = 1
    FASTRTPS_SUCCESS = 2
    FASTRTPS_ERROR = 3
    CYCLONEDDS_ERROR = 4


def compare_results(cyclonedds_result, fastrtps_result):
    if cyclonedds_result is None:
        return {
            'cpu_usage': Outcome.CYCLONEDDS_ERROR.value,
            'cpu_usage_diff': 0,
            'rel_cpu_usage': Outcome.CYCLONEDDS_ERROR.value,
            'rel_cpu_usage_diff': 0,
            'ram_usage': Outcome.CYCLONEDDS_ERROR.value,
            'ram_usage_diff': 0,
            'latency_mean': Outcome.CYCLONEDDS_ERROR.value,
            'latency_mean_diff': 0,
            'jitter': Outcome.CYCLONEDDS_ERROR.value,
            'jitter_diff': 0,
            'throughput': Outcome.CYCLONEDDS_ERROR.value,
            'throughput_diff': 0
        }
    if fastrtps_result is None:
        return {
            'cpu_usage': Outcome.FASTRTPS_ERROR.value,
            'cpu_usage_diff': 0,
            'rel_cpu_usage': Outcome.FASTRTPS_ERROR.value,
            'rel_cpu_usage_diff': 0,
            'ram_usage': Outcome.FASTRTPS_ERROR.value,
            'ram_usage_diff': 0,
            'latency_mean': Outcome.FASTRTPS_ERROR.value,
            'latency_mean_diff': 0,
            'jitter': Outcome.FASTRTPS_ERROR.value,
            'jitter_diff': 0,
            'throughput': Outcome.FASTRTPS_ERROR.value,
            'throughput_diff': 0
        }

    comparison = {}

    for metric in ['cpu_usage', 'rel_cpu_usage', 'ram_usage', 'latency_mean', 'jitter']:
        if cyclonedds_result[metric] < fastrtps_result[metric]:
            comparison[metric] = Outcome.CYCLONEDDS_SUCCESS.value
            comparison[f"{metric}_diff"] = fastrtps_result[metric] / (cyclonedds_result[metric] + 0.000001)
        else:
            comparison[metric] = Outcome.FASTRTPS_SUCCESS.value
            comparison[f"{metric}_diff"] = cyclonedds_result[metric] / (fastrtps_result[metric] + 0.000001)

    for metric in ['throughput']:
        if cyclonedds_result[metric] > fastrtps_result[metric]:
            comparison[metric] = Outcome.CYCLONEDDS_SUCCESS.value
            comparison[f"{metric}_diff"] = cyclonedds_result[metric] / (fastrtps_result[metric] + 0.000001)
        else:
            comparison[metric] = Outcome.FASTRTPS_SUCCESS.value
            comparison[f"{metric}_diff"] = fastrtps_result[metric] / (cyclonedds_result[metric] + 0.000001)

    return comparison


def to_boolean(value):
    return value if isinstance(value, bool) else str(value).lower().strip() in ['1', 'true']

def aggregate_test_data(database):
    raw_data = database["raw"]
    processed_results = []

    # Sort and iterate through all nested keys for consistent ordering
    for host, host_data in sorted(raw_data.items()):
        for mode, mode_data in sorted(host_data.items()):
            for topic, topic_data in sorted(mode_data.items()):
                for rate, rate_data in sorted(topic_data.items(), key=lambda x: int(x[0])):
                    for subs, subs_data in sorted(rate_data.items(), key=lambda x: int(x[0])):
                        for zero_copy, zc_data in sorted(subs_data.items(), key=lambda x: to_boolean(x[0])):
                            for reliable, rel_data in sorted(zc_data.items(), key=lambda x: to_boolean(x[0])):
                                for transient, trans_data in sorted(rel_data.items(), key=lambda x: to_boolean(x[0])):
                                    cdds = evaluate_metrics(trans_data.get("cyclonedds", {}), host, subs)
                                    fast = evaluate_metrics(trans_data.get("fastrtps", {}), host, subs)
                                    raw = evaluate_metrics(trans_data.get("raw_cyclonedds", {}), host, subs)

                                    if cdds is None and fast is None and raw is None:
                                        continue

                                    processed_results.append({
                                        "host": host,
                                        "mode": mode,
                                        "topic": topic,
                                        "rate": int(rate),
                                        "subs": int(subs),
                                        "zero_copy": to_boolean(zero_copy),
                                        "reliable": to_boolean(reliable),
                                        "transient": to_boolean(transient),
                                        "cyclonedds": cdds,
                                        "fastrtps": fast,
                                        "raw": raw,
                                        "comparison": compare_results(cdds, fast)
                                    })

    database["processed"] = processed_results

