import functools as ft
import inspect as ins
import itertools as it
import re as regex
from typing import (Any, Callable, Dict, List, Optional, Set, Tuple, Union,
                    get_type_hints)
import falcon as fl
from falcontyping.typedjson import args_of, origin_of
from .exceptions import TypeValidationError

try:
    from typing_extensions import Protocol
    class ResourceMethodWithoutReturnValue(Protocol):
        def __call__(self, req: fl.Request, resp: fl.Response, **kw: Any) -> None:  # pragma: no cover
            ...
    class ResourceMethodWithReturnValue(Protocol):
        def __call__(self, req: fl.Request, resp: fl.Response, **kw: Any) -> Any:  # pragma: no cover
            ...
except ImportError:  # pragma: no cover
    ResourceMethodWithoutReturnValue = Callable  # type: ignore # pragma: no cover
    ResourceMethodWithReturnValue = Callable     # type: ignore # pragma: no cover

try:
    from pydantic import BaseModel as PydanticBaseModel
except ImportError:
    PydanticBaseModel = None  # type: ignore

try:
    from marshmallow import Schema as MarshmallowSchema
except ImportError:
    MarshmallowSchema = None  # type: ignore

_AVAILABLE_EXTERNAL_SCHEMA_PRODIVERS = set(
    list(filter(None, [MarshmallowSchema, PydanticBaseModel]))
)

# Modified pattern with different formatting and comments
_FIELD_PATTERN = regex.compile(
    r'{((?P<fname>[^}:]*)((?P<cname_sep>:(?P<cname>[^}\(]*))(\((?P<argstr>[^}]*)\))?)?)}'
)

# Changed method names order and naming convention
_METHOD_NAMES: List[str] = [
    'on_%s' % m for m in ('get', 'post', 'put', 'patch', 'delete', 'head', 'options')
]

def validate_type_preconditions(type_: Any) -> None:
    """Check if required schema providers are available."""
    if len(_AVAILABLE_EXTERNAL_SCHEMA_PRODIVERS) == 0:
        raise TypeValidationError('No schema provider is installed. You need to install either Marshmallow or Pydantic')

    error_msg = ('Resource methods must accept/return either Nothing, '
                 'marshmallow.Schema or pydantic.BaseModel not {}')

    def predicate(t: Any) -> bool:
        """Determine if a type is acceptable for request/response body."""
        origin, args = origin_of(t), args_of(t)
        if origin is Union:
            return all(predicate(arg) for arg in args)
        else:
            has_supported_parent = any(
                issubclass(t, parent) for parent in _AVAILABLE_EXTERNAL_SCHEMA_PRODIVERS
            )
            return (has_supported_parent or t == type(None)) and t is not Any  # noqa
    try:
        if type_ and not predicate(type_):
            raise TypeValidationError(error_msg.format(type_))
    except TypeError:
        raise TypeValidationError(error_msg.format(type_))

def validate_method_signature(method: ResourceMethodWithReturnValue, uri_params: Set[str]) -> Tuple[Optional[str],
                                                                                                        Dict]:
    """
    Check resource method signature compliance.
    :returns: body parameter name and type hints
    """
    hints = get_type_hints(method)
    params = ins.getfullargspec(method).args

    # Validate URI parameters
    for param in filter(lambda p: hints.get(p, None) is Any or p not in params, uri_params):
        raise TypeValidationError(f'URI parameter {param} has type hint Any or is missing from signature')

    validate_type_preconditions(
        hints.get('return', None)
    )

    # Validate method signature structure
    if len(params) < 3:
        raise TypeValidationError('Every resource method must have the first two parameters as '
                                  'falcon.Request and falcon.Response')
    if hints.get(params[1], Any) not in [fl.Request, Any]:
        raise TypeValidationError('First parameter must be of type falcon.Request')
    if hints.get(params[2], Any) not in [fl.Response, Any]:
        raise TypeValidationError('Second parameter must be of type falcon.Response')

    # Validate body parameters
    body_params = set(params) - (uri_params | set(it.islice(params, 3)) | set(['return']))
    if len(body_params) > 1 and any(hints.get(param) for param in body_params):
        raise TypeValidationError('Any resource method can not accept more than one request parameter, that is one'
                                  'parameter of type marshmallow.Schema or pydantic.BaseModel')

    for param_name in body_params:
        validate_type_preconditions(hints.get(param_name, None))

    return next(iter(body_params & set(hints)), None), hints

def patch_resource_methods(uri_template: str, resource: Any) -> None:
    """Add type hint support by patching resource methods."""
    uri_params = set(match.group('fname') for match in _FIELD_PATTERN.finditer(uri_template))

    def resource_method_wrapper(method: ResourceMethodWithReturnValue) -> ResourceMethodWithoutReturnValue:
        """
        Wraps resource methods to handle response media assignment.
        This function will takes whatever is returned by resource methods and assigns
        it to response.media.
        """
        @ft.wraps(method)
        def curried(request: fl.Request, response: fl.Response, **kwargs: Any) -> None:
            media = method(request, response, **kwargs)
            if media:
                response.media = media
        return curried

    resource.methods_body_parameter = {}
    resource.hints = {}

    for method_name in filter(ft.partial(hasattr, resource), _METHOD_NAMES):
        method: ResourceMethodWithReturnValue = getattr(resource, method_name)
        if not callable(method):
            raise TypeValidationError(f'{resource}.{method_name} must be a Callable')
        try:
            body_param, hints = validate_method_signature(method, uri_params=uri_params)
            resource.methods_body_parameter[method_name] = body_param
            resource.hints[method_name] = hints
        except TypeValidationError as e:
            raise TypeValidationError(f'{resource}.{method} raised: {e}')

        wrapped = resource_method_wrapper(method)
        setattr(resource, method_name, wrapped)

