def number_to_words(num: Union[int, str]) -> str:
    """:returns: written form of an integer 0-999, or for the leading integer of a string"""
    if isinstance(num, str):
        if num.isdigit():
            return number_to_words(int(num))
        match = leading_integer_regexp.search(num)
        if not match:
            return num
        initial_num = match.group(0)
        written_num = number_to_words(int(initial_num))
        rest = num[match.end():]
        return f"{written_num}_{rest}"
    if not (0 <= num <= 999):
        raise NotImplementedError("Numbers must be in range 0...999 inclusive")
    if num == 0:
        return "zero"
    full_num = str(num).zfill(3)
    hundreds_digit = full_num[0]
    tens_digit = full_num[1]
    ones_digit = full_num[2]

    ones_val = ones_map.get(ones_digit)
    tens_val = tens_map.get(tens_digit)
    special_val = special_map.get(f"{tens_digit}{ones_digit}")
    hundreds_val = ones_map.get(hundreds_digit)

    parts = []
    if hundreds_val:
        parts.append(f"{hundreds_val}_hundred")
    if special_val:
        parts.append(special_val)
    elif tens_val and ones_val:
        parts.append(f"{tens_val}_{ones_val}")
    elif tens_val:
        parts.append(tens_val)
    elif ones_val:
        parts.append(ones_val)
    return "_and_".join(parts)

def generate_unique_name(name: str, taken_names: List[str]) -> str:
    """:returns a unique name based on the name passed and the taken names"""
    matches = [item for item in taken_names if item.startswith(name)]
    if not any(matches):
        return name
    count = len(matches)
    if count > 999:
        raise NotImplementedError(">999 methods with similar names not supported")
    suffix = number_to_words(count + 1)
    return f"{name}_{suffix}"

def correct_escape_sequences(text: str) -> str:
    """
