def process_text_annotation(text_input):
    if not text_input: 
        return {}
    from stanza.server import CoreNLPClient, StartServer
    with CoreNLPClient(
            start_server=StartServer.DONT_START,
            output_format='json') as client:
        try:
            return client.annotate(text_input)
        except Exception:
            return None

def annotate_text(text_content, num_workers=4, split_by_paragraph=True, show_progress=None):
    import lltk
    if show_progress is None: 
        show_progress = num_workers > 1
    if split_by_paragraph:
        paragraphs = [p.strip() for p in text_content.split('\n\n')]
        return lltk.pmap(process_text_annotation, paragraphs, num_proc=num_workers, progress=show_progress)
    else:
        return process_text_annotation(text_content)

def annotate_file(file_path, num_workers=4, split_by_paragraph=True, save_result=True, output_file=None, overwrite=True, display_progress=True):
    # Check file existence
    if not os.path.exists(file_path): 
        return

    # Process file content
    result = None
    with open(file_path) as f:
        content = f.read().strip()
        if content:
            result = annotate_text(content, num_proc=num_workers, by_para=split_by_paragraph, progress=display_progress)
    if not result: 
        return []

    # Save results if requested
    if save_result:
        if not output_file: 
            output_file = file_path.replace('/txt/', '/corenlp/')
            output_file = '.'.join([os.path.splitext(output_file)[0], 'json'])

        if not overwrite and os.path.exists(output_file): 
            return
        output_dir = os.path.split(output_file)[0]
        if not os.path.exists(output_dir): 
            os.makedirs(output_dir)
        with open(output_file, 'w') as out_f:
            json.dump(result, out_f, indent=4)

    return result

def _process_single_file(file_path, **options):
    options['num_proc'] = 1
    options['progress'] = False
    return annotate_file(file_path, **options)

def batch_annotate_files(file_paths_list):
    from lltk import tools
    return tools.pmap(_process_single_file, file_paths_list, num_proc=8)

