from __future__ import annotations
import importlib.util
from functools import lru_cache
from glob import iglob
from pathlib import Path
from typing import List, Tuple
import pytest

@lru_cache(maxsize=None)
def retrieve_test_cases(day: int, part: int) -> Tuple[List[str], Tuple[str, str]]:
    pattern = f"{Path.cwd()}/tests/fixtures/{day:02d}*.txt"
    files = list(iglob(pattern))

    if not files:
        raise FileNotFoundError(f"no fixtures found: {pattern}")

    for file_path in files:
        try:
            with open(file_path, 'r') as file:
                content = file.read()
                parts = content.split("---------------------\n")
        except FileNotFoundError:
            yield ([], ("", ""))
        else:
            sample_input = parts[0].splitlines()
            expected_outputs = (parts[1].strip(), parts[2].strip())
            yield (sample_input, expected_outputs)

def format_parameter_label(label_name):
    def inner(value):
        return f"{label_name}+{value}"
    return inner

def execute_solver(day: int, part: int, data: List[str]) -> str:
    try:
        module_name = f"aoc.day_{day:02d}"
        module = importlib.import_module(module_name)
        solver_function = getattr(module, f"answer{part}")
    except (AttributeError, ModuleNotFoundError):
        raise NotImplementedError(f"missing implementation: {module_name}:answer{part}")
    else:
        result = solver_function(data)
        return str(result)

@pytest.mark.parametrize("part_index", [1, 2])
@pytest.mark.parametrize("day_number", range(1, 25))
def test_all_solutions(day_number: int, part_index: int) -> None:
    try:
        test_data = retrieve_test_cases(day_number, part_index)
        for (input_data, expected_results) in test_data:
            actual_result = execute_solver(day_number, part_index, input_data)
            assert actual_result == expected_results[part_index - 1]
    except (FileNotFoundError, NotImplementedError) as error:
        pytest.skip(f"Skipped {day_number}.{part_index} due to: {error}")

