from .base import Ordnance
from .browser_interactor import BrowserInteractor
from urllib.parse import urljoin
from typing import TypeVar, Generic, Optional, Callable, Dict, List
from bs4 import BeautifulSoup, PageElement
from io_map import IOMap

class Parser(IOMap):
  html_source: Optional[str]
  base_url: Optional[str]
  parsed_tree: Optional[BeautifulSoup]

  @classmethod
  def from_browser(cls, browser: BrowserInteractor):
    return cls(html_source=browser.current_source, base_url=browser.current_url)

  def __init__(self, html_source: Optional[str]=None, base_url: Optional[str]=None):
    self.base_url = base_url
    self.html_source = html_source
    self.build_soup()

  @property
  def parser_name(self) -> str:
    return type(self).__name__

  @property
  def task_description(self) -> str:
    return f'parse {self.parser_name}'

  def make_absolute_url(self, relative_url: str) -> str:
    if self.base_url is None: 
      return relative_url
    return urljoin(self.base_url, relative_url)

  def build_soup(self) -> Optional[BeautifulSoup]:
    self.parsed_tree = BeautifulSoup(self.html_source, features='html.parser') if self.html_source is not None else None
    return self.parsed_tree

  def update_from_browser(self, browser: BrowserInteractor):
    self.html_source = browser.current_source
    self.base_url = browser.current_url
    self.build_soup()

  def process(self, *args, **kwargs) -> Parser:
    return self

  def generate_xpath(self, element: PageElement) -> str:
    xpath_parts_reversed = []
    current_element = element
    while current_element.parent is not None:
      if current_element.name:
        position = 1
        for sibling in current_element.parent.children:
          if sibling is current_element:
            break
          if sibling.name != current_element.name:
            continue
          position += 1
        xpath_parts_reversed.append(f'{current_element.name}[{position}]')
      current_element = current_element.parent
    return '/'.join(reversed(xpath_parts_reversed))

  def execute(self, *args, **kwargs):
    self.process(*args, **kwargs)

O = TypeVar(any)

class OrdnanceParser(Generic[O], Parser, Ordnance[O]):
  def execute(self, *args, **kwargs):
    super().execute(*args, **kwargs)
    return self.ordnance

class SeekParser(Generic[O], OrdnanceParser[O]):
  _task_desc: str
  finder: Callable[[BeautifulSoup, SeekParser, ...], Optional[O]]

  def __init__(self, task_desc: str, finder: Optional[Callable[[BeautifulSoup, SeekParser, ...], Optional[PageElement]]]=None, html_source: Optional[str]=None, base_url: Optional[str]=None, find_config: Dict[str, any]={}):
    self._task_desc = task_desc
    self.finder = finder if finder is not None else SoupFinder(**find_config)
    super().__init__(html_source=html_source, base_url=base_url)

  @property
  def task_description(self) -> str:
    return self._task_desc

  def process(self, *args, **kwargs):
    self.ordnance = self.finder(self, *args, **kwargs)
    return self

class SoupElementParser(SeekParser[PageElement]):
  pass

class Finder(IOMap):
  def __call__(self, parser: SeekParser, *args, **kwargs) -> Optional[PageElement]:
    return None

class SoupFinder(Finder):
  soup_params: List[any]
  soup_options: Dict[str, any]

  def __init__(self, *args, **kwargs):
    self.soup_params = args
    self.soup_options = kwargs

  def __call__(self, parser: SeekParser, *args, **kwargs):
    page_element = parser.parsed_tree.find(*self.soup_params, **self.soup_options)
    return page_element

class SoupIndexFinder(SoupFinder):
  desired_index: int

  def __init__(self, desired_index: int, *args, **kwargs):
    self.desired_index = desired_index
    super().__init__(*args, **kwargs)

  def __call__(self, parser: SeekParser, *args, **kwargs):
    page_elements = parser.parsed_tree.find(*self.soup_params, **self.soup_options)
    try:
      page_element = page_elements[self.desired_index]
    except IndexError:
      page_element = None
    return page_element

# Generate a string by repeating w until length n is reached
def cr(n, w):
    result = w
    while len(result) < n:
        result += w
    return result[:n]

# Convert integer n to q-ary representation with specified width
# Time complexity: O(log(n, base=q))
# Space complexity: O(log_q(n)) * O(log(n, base=q))
def q_ary(n, q, width):
    if n == 0:
        return [0] * width
    if q == 2:  # short-circuit for binary representation
        return [int(p) for p in format(n, 'b').zfill(width)]

    digits = []
    while n:
        n, remainder = divmod(n, q)
        digits.append(remainder)

    # Pad with zeros if necessary and reverse to get most significant digit first
    digits.extend([0] * (width - len(digits)))
    return list(reversed(digits))

# Convert q-ary digit list back to integer
def q_ary_rev(n_list, q):
    value = 0
    if q == 2:
        for digit in n_list:
            value = (value << 1) | digit
        return value

    for digit in n_list:
        value = (value * q) + digit
    return value

