from sortedcontainers import SortedList
from .function import Function

class Individual:
    def __init__(self, data: Any, fitness: Union[float, int]):
        self._data = copy.deepcopy(data)
        self._fitness = copy.deepcopy(fitness)

    @property
    def data(self) -> Any:
        return self._data

    @property
    def fitness(self) -> Union[float, int]:
        return self._fitness

    def __eq__(self, other: "Individual"):
        if isinstance(other, Individual):
            data_match = self.data == other.data
            fitness_match = self.fitness == other.fitness
            if not isinstance(data_match, bool):
                try:
                    iter(data_match)
                    data_match = all(data_match)
                except TypeError:
                    pass
            if not isinstance(fitness_match, bool):
                try:
                    iter(fitness_match)
                    fitness_match = all(fitness_match)
                except TypeError:
                    pass
            return data_match and fitness_match
        return False

    def __str__(self):
        return f"[{self.fitness}] {self.data}"

    def __repr__(self):
        return str(self)

class IndividualFactory:
    @staticmethod
    def __validate_constructor_args(quality_function: Function) -> Function:
        if not isinstance(quality_function, Function):
            raise TypeError(
                "Parameter quality_function must be a Function, got "
                f"{type(quality_function)} instead."
            )
        return quality_function

    @property
    def quality_function(self):
        return self._quality_function

    def __init__(self, quality_function: Function):
        quality_function = self.__validate_constructor_args(quality_function=quality_function)
        self._quality_function = quality_function

    def create(self, item: Any) -> Individual:
        return Individual(data=item, fitness=self._quality_function(item))

    def __call__(self, item) -> Individual:
        return self.create(item)

class Group:
    @staticmethod
    def __validate_constructor_parameters(
        quality_function: Function,
        collection: Optional[Iterable[Union[Any, Individual]]],
        max_size: int,
        preservation: int,
    ) -> Tuple[IndividualFactory, List[Individual], int, int]:
        if not isinstance(quality_function, Function):
            raise TypeError(
                "Parameter quality_function must be a Function, got "
                f"{type(quality_function)} instead."
            )
        individual_factory = IndividualFactory(quality_function=quality_function)

        # Validate max_size before processing collection
        if not isinstance(max_size, int):
            raise TypeError(
                "Parameter max_size must be an integer, got "
                f"{type(max_size)} instead."
            )
        if max_size < 1:
            raise ValueError(
                "Parameter max_size must be a positive integer, got "
                f"{max_size}."
            )

        if collection is not None:
            try:
                iter(collection)
            except TypeError:
                raise TypeError(
                    "Parameter collection must be an iterable or None, got "
                    f"{type(collection)}."
                )
            collection = [
                y if isinstance(y, Individual) else individual_factory(y)
                for y in collection
            ]
            if len(collection) > max_size:
                collection.sort(key=lambda y: -y.fitness)
                collection = collection[:max_size]

        if not isinstance(preservation, int):
            raise TypeError(
                "Parameter preservation must be an integer, got "
                f"{type(preservation)} instead."
            )
        if preservation < 0:
            raise ValueError(
                "Parameter preservation must be a non-negative integer, got "
                f"{preservation}."
            )
        return individual_factory, collection, max_size, preservation

    def __init__(
        self,
        quality_function: Function,
        collection: Optional[Iterable[Union[Any, Individual]]] = None,
        max_size: int = 10,
        preservation: int = 0,
    ):
        individual_factory, collection, max_size, preservation = self.__validate_constructor_parameters(
            quality_function=quality_function,
            collection=collection,
            max_size=max_size,
            preservation=preservation,
        )
        self._individual_factory = individual_factory
        self._max_size = max_size
        self._preservation = preservation
        self.__items = SortedList(iterable=collection, key=lambda y: -y.fitness)

    @property
    def quality_function(self):
