    @property
    def individual_factory(self):
        return self._individual_factory

    @property
    def max_size(self):
        return self._max_size

    @property
    def preservation(self):
        return self._preservation

    def exclude(self, y: Union[Any, Individual]):
        if y is not None:
            self.__items.discard(
                y if isinstance(y, Individual) else self.individual_factory(y)
            )

    def trim(self, extra_count: int = 0):
        if not isinstance(extra_count, int):
            raise TypeError(
                "Parameter extra_count must be an integer, got "
                f"{type(extra_count)} instead."
            )
        if extra_count < 0:
            raise ValueError(
                "Parameter extra_count must be a non-negative integer, got "
                f"{extra_count}."
            )
        max_removal = len(self) - self.preservation
        removal_count = len(self) - self.max_size + extra_count
        removal_count = min(removal_count, max_removal)
        if removal_count < len(self):
            for _ in range(removal_count):
                self.__items.pop()
        else:
            self.__items.clear()

    def extract(self, position: int = -1):
        if not isinstance(position, int):
            raise TypeError(
                f"Parameter position must be an integer, got {type(position)} instead."
            )
        return (
            self.__items.pop(position)
            if len(self) > self.preservation
            else self.__items[position]
        )

    def include(self, individual: Individual):
        if not isinstance(individual, Individual):
            try:
                individual = self.individual_factory(individual)
            except Exception as err:
                raise TypeError(
                    "Parameter individual must be an Individual, got "
                    f"{type(individual)}. Or {err}. One of these."
                )
        self.__items.add(individual)

    def insert(self, individual: Individual, evict_first: bool = True):
        if not isinstance(evict_first, bool):
            raise TypeError(
                "Parameter evict_first must be a boolean, got "
                f"{type(evict_first)}."
            )
        if evict_first:
            self.trim(extra_count=1)
        self.include(individual=individual)
        self.trim()

    def integrate(self, individuals: Iterable[Individual]):
        try:
            iter(individuals)
        except TypeError:
            raise TypeError(
                "Parameter individuals must be an iterable, got "
                f"{type(individuals)}."
            )
        for individual in individuals:
            self.include(individual)

    def infiltrate(self, individuals: Iterable[Individual], evict_first: bool = True):
        if not isinstance(evict_first, bool):
            raise TypeError(
                "Parameter evict_first must be a boolean, got "
                f"{type(evict_first)}."
            )
        if evict_first:
            self.trim(len(individuals))
        self.integrate(individuals)
        self.trim()

    def __getitem__(self, index: Union[int, Iterable]):
        try:
            return self.__items[int(index)]
        except Exception:
            try:
                iter(index)
                return np.array([self[z] for z in index])
            except TypeError:
                raise ValueError(
                    "Parameter index must be an integer or an iterable, got "
                    f"{type(index)}."
                )

    def __len__(self):
        return len(self.__items)

    def __str__(self):
        result = f"Group ({len(self)} / {self.max_size})"
        if self.preservation != 0:
            result += f", preserved: {self.preservation}"
        for individual in self.__items:
            result += f"\n\t{individual}"
        return result

# Merge two sorted linked lists
class Solution:
    def mergeTwoLists(self, list1, list2):
        if list1 is None or (list2 and list1.val > list2.val):
            list1, list2 = list2, list1
        current = list1
        while current and list2:
            if current.next is None or (current.next.val > list2.val):
                current.next, list2 = list2, current.next
            current = current.next
        return list1

from typing import (
    Tuple,
    Optional,
)
import subprocess

def find_executables() -> Tuple[Optional[str], Optional[str]]:
    """
    Tries to locate `pyenv` and `poetry` using system path lookup.
    Executes shell commands via `subprocess.run` to determine the full paths.
    """
    pyenv_result = subprocess.run(["which", "pyenv"], capture_output=True)
    poetry_result = subprocess.run(["which", "poetry"], capture_output=True)

    if pyenv_result.returncode == 0:
        pyenv_location = pyenv_result.stdout.decode("UTF-8").strip()
    else:
        pyenv_location = None

    if poetry_result.returncode == 0:
        poetry_location = poetry_result.stdout.decode("UTF-8").strip()
    else:
        poetry_location = None

    return (pyenv_location, poetry_location)

# Module for qualified name handling and code representation
import abc
import collections.abc
import typing as ta
from omnibus import check
from omnibus import collections as col
from omnibus import dataclasses as dc
from omnibus import properties
from omnibus.serde import mapping as sm

class QualifiedName(dc.Pure, ta.Sequence[str]):
    parts: ta.Sequence[str] = dc.field(coerce=col.seq)
    dc.check(lambda parts: (
            parts and
            all(parts) and
            all(isinstance(p, str) for p in parts)
    ))

    def __repr__(self) -> str:
        return 'QualifiedName([%s])' % (', '.join(map(repr, self.parts)),)

    @property
    def dotted(self) -> str:
        return '.'.join(self.parts)

    def prefixed(self, sz: int) -> ta.Sequence[ta.Optional[str]]:
        if len(self) > sz:
            raise ValueError(self)
        return ((None,) * (sz - len(self))) + tuple(self.parts)

    @property
    def pair(self) -> ta.Tuple[ta.Optional[str], str]:
        return self.prefixed(2)  # noqa

    @property
    def triple(self) -> ta.Tuple[ta.Optional[str], ta.Optional[str], str]:
        return self.prefixed(3)  # noqa

    @property
    def quad(self) -> ta.Tuple[ta.Optional[str], ta.Optional[str], ta.Optional[str], str]:
        return self.prefixed(4)  # noqa

    def __iter__(self) -> ta.Iterator[str]:
        return iter(self.parts)

    def __len__(self) -> int:
        return len(self.parts)

    def __getitem__(self, idx: int) -> str:
        return self.parts[idx]

    @classmethod
    def of_dotted(cls, dotted: str) -> 'QualifiedName':
        return cls(dotted.split('.'))

    @classmethod
    def of(cls, obj: ta.Union['QualifiedName', ta.Iterable[str]]) -> 'QualifiedName':
        if isinstance(obj, QualifiedName):
            return obj
        elif isinstance(obj, str):
            raise TypeError(obj)
        elif isinstance(obj, collections.abc.Iterable):
            return cls(list(obj))
        else:
            raise TypeError(obj)

    @classmethod
    def of_optional(cls, obj: ta.Union[None, 'QualifiedName', ta.Iterable[str]]) -> ta.Optional['QualifiedName']:
        if obj is None:
            return None
        else:
            return cls.of(obj)

class QualifiedNameSerde(sm.AutoSerde[QualifiedName]):
    def serialize(self, obj: QualifiedName) -> ta.Any:
        return list(check.isinstance(obj, QualifiedName).parts)

    def deserialize(self, ser: ta.Any) -> QualifiedName:
        return QualifiedName.of(ser)

class Code(dc.Enum):
    @abc.abstractproperty
    def fn(self) -> ta.Callable:
        raise NotImplementedError

    def __call__(self, *args, **kwargs):
        return self.fn(*args, **kwargs)

class Lambda(Code, allow_setattr=True):
    src: str = dc.field(check=lambda s: isinstance(s, str) and ':' in s)

    @properties.cached
    def fn(self) -> ta.Callable:
        return eval('lambda ' + self.src)

class LambdaSerde(sm.AutoSerde[Lambda]):
    def serialize(self, obj: Lambda) -> ta.Any:
        return sm.serialize_dataclass_fields(obj)

    def deserialize(self, ser: ta.Any) -> Lambda:
        if isinstance(ser, str):
            return Lambda(ser)
        return sm.deserialize_dataclass_fields(ser, Lambda)

import logging
import ssl
from typing import Optional
from pkg_resources import parse_version
from twisted.internet import threads
import ldap3
import ldap3.core.exceptions
import synapse

__version__ = "0.1.5"
logger = logging.getLogger(__name__)

class ActiveDirectoryUPNException(Exception):
    """Raised when user login credentials cannot be mapped to a UPN"""
    pass

class LDAPMode(object):
    SIMPLE = "simple",
    SEARCH = "search",
    LIST = (SIMPLE, SEARCH)

class LdapAuthProvider(object):
    _ldap_tls = ldap3.Tls(validate=ssl.CERT_REQUIRED)

    def __init__(self, config, account_handler):
        self.account_handler = account_handler
        self.ldap_mode = config.mode
        self.ldap_uris = [config.uri] if isinstance(config.uri, str) else config.uri
        self.ldap_start_tls = config.start_tls
        self.ldap_base = config.base
        self.ldap_attributes = config.attributes

        if self.ldap_mode == LDAPMode.SEARCH:
            self.ldap_bind_dn = config.bind_dn
            self.ldap_bind_password = config.bind_password
            self.ldap_filter = config.filter

        self.ldap_active_directory = config.active_directory

        if self.ldap_active_directory:
            self.ldap_default_domain = config.default_domain
            self.ldap_root_domain = None  # type: Optional[str]

    def get_supported_login_types(self):
        return {'m.login.password': ('password',)}

    async def check_auth(self, username, login_type, login_dict):
        password = login_dict['password']

        if not password:
            return False

        if username.startswith("@") and ":" in username:
            username = username.split(":", 1)[0][1:]

        uid_value = username
        default_display_name = username
        localpart = username

        if self.ldap_active_directory:
            try:
                (login, domain, localpart) = await self._map_login_to_upn(username)
                uid_value = login + "@" + domain
                default_display_name = login
            except ActiveDirectoryUPNException:
                return False

        try:
            server = self._get_server()
            logger.debug(
                "Attempting LDAP connection with %s",
                self.ldap_uris
            )

            if self.ldap_mode == LDAPMode.SIMPLE:
                bind_dn = "{prop}={value},{base}".format(
                    prop=self.ldap_attributes['uid'],
                    value=uid_value,
                    base=self.ldap_base
                )
                result, conn = await self._ldap_simple_bind(
                    server=server, bind_dn=bind_dn, password=password
                )
                logger.debug(
                    'LDAP authentication method simple bind returned: '
                    '%s (conn: %s)',
                    result,
                    conn
                )
                if not result:
                    return False

            elif self.ldap_mode == LDAPMode.SEARCH:
                filters = [(self.ldap_attributes["uid"], uid_value)]
                result, conn, _ = await self._ldap_authenticated_search(
                    server=server, password=password, filters=filters
                )
                logger.debug(
                    'LDAP auth method authenticated search returned: '
                    '%s (conn: %s)',
                    result,
                    conn
                )
                if not result:
                    return False
            else:  # pragma: no cover
                raise RuntimeError(
                    'Invalid LDAP mode specified: {mode}'.format(
                        mode=self.ldap_mode
                    )
                )

            try:
                logger.info(
                    "User authenticated against LDAP server: %s",
                    conn
                )
            except NameError:  # pragma: no cover
                logger.warning(
                    "Authentication method yielded no LDAP connection, "
                    "aborting!"
                )
                return False

            user_id = self.account_handler.get_qualified_user_id(localpart)

            if await self.account_handler.check_user_exists(user_id):
                if hasattr(conn, "unbind"):
                    await threads.deferToThread(conn.unbind)
                return user_id
            else:
                if self.ldap_mode == LDAPMode.SEARCH:
                    filters = [(self.ldap_attributes['uid'], uid_value)]
                    result, conn, response = await self._ldap_authenticated_search(
                        server=server, password=password, filters=filters,
                    )

                    display_name = response["attributes"].get(
                        self.ldap_attributes["name"], [localpart]
                    )
                    display_name = (
                        display_name[0]
                        if len(display_name) == 1
                        else default_display_name
                    )
                    mail = response["attributes"].get("mail", [None])
                    mail = mail[0] if len(mail) == 1 else None
                else:
                    display_name = default_display_name
                    mail = None

                user_id = await self.register_user(localpart, display_name, mail)
                return user_id

            return False
        except ldap3.core.exceptions.LDAPException as e:
            logger.warning("Error during ldap authentication: %s", e)
            return False

    async def check_3pid_auth(self, medium, address, password):
        if self.ldap_mode != LDAPMode.SEARCH:
            logger.debug("3PID LDAP login/register attempted but LDAP search mode "
                         "not enabled. Bailing.")
            return None

        if medium != "email":
            return None

        try:
            server = self._get_server()
            logger.debug(
                "Attempting LDAP connection with %s",
                self.ldap_uris
            )
            search_filter = [(self.ldap_attributes["mail"], address)]
            result, conn, response = await self._ldap_authenticated_search(
                server=server, password=password, filters=search_filter,
            )
            logger.debug(
                'LDAP auth method authenticated search returned: '
                '%s (conn: %s) (response: %s)',
                result,
                conn,
                response
            )

            if hasattr(conn, "unbind"):
                await threads.deferToThread(conn.unbind)

            if not result:
                return None

            localpart = response["attributes"].get(
                self.ldap_attributes["uid"], [None]
            )
            localpart = localpart[0] if len(localpart) == 1 else None

            if self.ldap_active_directory and localpart and "@" in localpart:
                (login, domain) = localpart.lower().rsplit("@", 1)
                localpart = login + "/" + domain
                if (
                    self.ldap_default_domain
                    and domain.lower() == self.ldap_default_domain.lower()
                ):
                    localpart = login

            givenName = response["attributes"].get(
                self.ldap_attributes["name"], [localpart]
            )
            givenName = givenName[0] if len(givenName) == 1 else localpart

            user_id = await self.register_user(localpart, givenName, address)
            return user_id
        except ldap3.core.exceptions.LDAPException as e:
            logger.warning("Error during ldap authentication: %s", e)
            raise

    async def register_user(self, localpart, name, email_address):
        user_id = self.account_handler.get_qualified_user_id(localpart)
        if await self.account_handler.check_user_exists(user_id):
            return user_id

        emails = [email_address] if email_address is not None else []

        if parse_version(synapse.__version__) <= parse_version("0.99.3"):
            user_id, access_token = (
                await self.account_handler.register(
                    localpart=localpart, displayname=name,
                )
            )
        else:
            user_id, access_token = (
                await self.account_handler.register(
                    localpart=localpart, displayname=name, emails=emails,
                )
            )

        logger.info(
            "Registration based on LDAP data was successful: %s",
            user_id,
        )
        return user_id

    @staticmethod
    def parse_config(config):
        class _LdapConfig(object):
            pass

        ldap_config = _LdapConfig()
        ldap_config.enabled = config.get("enabled", False)
        ldap_config.mode = LDAPMode.SIMPLE

        _require_keys(config, [
            "uri",
            "base",
            "attributes",
        ])

        ldap_config.uri = config["uri"]
        ldap_config.start_tls = config.get("start_tls", False)
        ldap_config.base = config["base"]
        ldap_config.attributes = config["attributes"]

        if "bind_dn" in config:
            ldap_config.mode = LDAPMode.SEARCH
            _require_keys(config, [
                "bind_dn",
                "bind_password",
            ])
            ldap_config.bind_dn = config["bind_dn"]
            ldap_config.bind_password = config["bind_password"]
            ldap_config.filter = config.get("filter", None)

        _require_keys(config['attributes'], [
            "uid",
            "name",
            "mail",
        ])

        ldap_config.active_directory = config.get("active_directory", False)
        if ldap_config.active_directory:
            ldap_config.default_domain = config.get("default_domain", None)

        return ldap_config

    def _get_server(self, get_info: Optional[str] = None) -> ldap3.ServerPool:
        return ldap3.ServerPool(
            [
                ldap3.Server(
                    uri,
                    get_info=get_info,
                    tls=self._ldap_tls
                )
                for uri in self.ldap_uris
            ],
        )

    async def _fetch_root_domain(self) -> str:
        if self.ldap_root_domain is not None:
            return self.ldap_root_domain

        self.ldap_root_domain = ""

        if self.ldap_mode != LDAPMode.SEARCH:
            logger.info("Fetching root domain is supported in search mode only")
            return self.ldap_root_domain

        server = self._get_server(get_info=ldap3.DSA)
        result, conn = await self._ldap_simple_bind(
            server=server,
            bind_dn=self.ldap_bind_dn,
            password=self.ldap_bind_password,
        )

        if not result:
            logger.warning("Unable to get root domain due to failed LDAP bind")
            return self.ldap_root_domain

        if (
            conn.server.info.other
            and conn.server.info.other.get("rootDomainNamingContext")
        ):
            self.ldap_root_domain = ".".join(
                [
                    dc.split("=")[1] for dc
                    in conn.server.info.other["rootDomainNamingContext"][0].split(",")
                    if "=" in dc
                ]
            )
            logger.info('Obtained root domain "%s"', self.ldap_root_domain)

        if not self.ldap_root_domain:
            logger.warning(
                "No valid `rootDomainNamingContext` attribute was found in the RootDSE. "
                "Logging in using short domain name will be unavailable."
            )

        await threads.deferToThread(conn.unbind)
        return self.ldap_root_domain

    async def _ldap_simple_bind(self, server, bind_dn, password):
        try:
            conn = await threads.deferToThread(
                ldap3.Connection,
                server, bind_dn, password,
                authentication=ldap3.SIMPLE,
                read_only=True,
            )
            logger.debug(
                "Established LDAP connection in simple bind mode: %s",
                conn
            )

            if self.ldap_start_tls:
                await threads.deferToThread(conn.open)
                await threads.deferToThread(conn.start_tls)
                logger.debug(
                    "Upgraded LDAP connection in simple bind mode through "
                    "StartTLS: %s",
                    conn
                )

            if await threads.deferToThread(conn.bind):
                logger.debug("LDAP Bind successful in simple bind mode.")
                return (True, conn)

            logger.info(
                "Binding against LDAP failed for '%s' failed: %s",
                bind_dn, conn.result['description']
            )
            await threads.deferToThread(conn.unbind)
            return (False, None)
        except ldap3.core.exceptions.LDAPException as e:
            logger.warning("Error during LDAP authentication: %s", e)
            raise

    async def _ldap_authenticated_search(self, server, password, filters):
        try:
            result, conn = await self._ldap_simple_bind(
                server=server,
                bind_dn=self.ldap_bind_dn,
                password=self.ldap_bind_password,
            )
            if not result:
                return (False, None, None)

            query = ""
            for filter_item in filters:
                query += "({key}={value})".format(
                    key=filter_item[0],
                    value=filter_item[1],
                )

            if self.ldap_filter:
                query += self.ldap_filter

            query = "(&{query})".format(
                query=query,
            )

            logger.debug(
                "LDAP search filter: %s",
                query
            )

            await threads.deferToThread(
                conn.search,
                search_base=self.ldap_base,
                search_filter=query,
                attributes=[
                    self.ldap_attributes['uid'],
                    self.ldap_attributes['name'],
                    self.ldap_attributes['mail'],
                ],
            )

            responses = [
                response
                for response
                in conn.response
                if response['type'] == 'searchResEntry'
            ]

            if len(responses) == 1:
                user_dn = responses[0]['dn']
                logger.debug('LDAP search found dn: %s', user_dn)

                await threads.deferToThread(conn.unbind)
                result, conn = await self._ldap_simple_bind(
                    server=server, bind_dn=user_dn, password=password
                )
                return (result, conn, responses[0])
            else:
                if len(responses) == 0:
                    logger.info(
                        "LDAP search returned no results for '%s'",
                        filters
                    )
                else:
                    logger.info(
                        "LDAP search returned too many (%s) results for '%s'",
                        len(responses), filters
                    )

                await threads.deferToThread(conn.unbind)
                return (False, None, None)
        except ldap3.core.exceptions.LDAPException as e:
            logger.warning("Error during LDAP authentication: %s", e)
            raise

    async def _map_login_to_upn(self, username):
        login = username.lower()
        domain = self.ldap_default_domain
        localpart = username

        if '\\' in username:
            (domain, login) = username.lower().rsplit('\\', 1)
            ldap_root_domain = await self._fetch_root_domain()
            if ldap_root_domain and not domain.endswith(ldap_root_domain):
                domain += "." + ldap_root_domain
        elif "/" in username:
            (login, domain) = username.lower().rsplit("/", 1)
        else:
            if not self.ldap_default_domain:
                logger.info(
                    'No LDAP separator "/" was found in uid "%s" '
                    'and LDAP default domain was not configured.',
                    username
                )
                raise ActiveDirectoryUPNException()

        if self.ldap_default_domain and domain == self.ldap_default_domain.lower():
            localpart = login
        else:
            localpart = login + "/" + domain

        return (login, domain, localpart)

def _require_keys(config, required):
    missing = [key for key in required if key not in config]
    if missing:
        raise Exception(
            "LDAP enabled but missing required config values: {}".format(
                ", ".join(missing)
            )
        )

# Type I clone: Renamed variables, changed literals, reordered statements
from __future__ import annotations
import typing as t

# Type variable for generic operations
X = t.TypeVar("X")

def safe_get(
    mapping: t.Dict[object, object],
    /,
    lookup_key: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform_func: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
) -> t.Optional[X]:
    """Retrieve a value from the mapping using the specified key.
    Returns None if key is missing or value is None.
    :raises: ValueError when type mismatch occurs
    """
    if transform_func is None:
        result = mapping.get(lookup_key)
    else:
        result = transform_func(mapping, lookup_key)

    if result is not None and not isinstance(result, expected_type):
        raise ValueError(
            f"{mapping}: {repr(lookup_key)}: {repr(result)}: invalid type {type(result)}, expecting {expected_type}"
        )
    return t.cast(X, result)

def mandatory_get(
    mapping: t.Dict[object, object],
    /,
    lookup_key: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform_func: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
    fallback_value: t.Optional[X] = None,
    factory_func: t.Optional[t.Callable[[], X]] = None,
) -> X:
    """Retrieve a required value from the mapping using the specified key.
    Raises ValueError if value is missing and no fallback provided.
    :raises: ValueError when value is required but not available
    """
    temp_val: t.Optional[X] = safe_get(mapping, lookup_key, expected_type, transform_func=transform_func)

    if temp_val is None:
        if fallback_value is not None:
            return fallback_value
        if factory_func is not None:
            return factory_func()
        raise ValueError(f"{mapping}: {repr(lookup_key)}: value is required")
    return temp_val

def compress_dict(source: t.Dict[t.Any, t.Any]) -> t.Dict[str, object]:
    """Compress a nested dictionary into a flat structure with colon-separated keys.
    :param dict source: The nested dictionary to compress.
    :rtype: dict
    :example:
    .. code-block:: python
        compress_dict({"a": 1, "b": {"c": 2, "d": {"e": 3, "f": 4}}})
        # {
        #     "a": 1,
        #     "b:c": 2,
        #     "b:d:e": 3,
        #     "b:d:f": 4,
        # }
    """
    def generate_pairs() -> t.Iterable[t.Tuple[str, object]]:
        for original_key, original_value in source.items():
            if not isinstance(original_key, str):
                raise ValueError(f"{original_key}: expected {str}, but got {type(original_key)}")
            if isinstance(original_value, dict):
                for nested_key, nested_value in compress_dict(original_value).items():
                    if not isinstance(nested_key, str):
                        raise ValueError(
                            f"{nested_key}: expected {str}, but got {type(nested_key)}"
                        )
                    yield original_key + ":" + nested_key, nested_value
            else:
                yield original_key, original_value
    return dict(generate_pairs())

def expand_dict(flattened: t.Dict[object, object]) -> t.Dict[object, object]:
    """Convert a flattened dictionary back into its nested form.
    :param dict flattened: The flattened dictionary to expand.
    :rtype: dict
    :example:
    .. code-block:: python
        expand_dict({"a": 1, "b:c": 2, "b:d:e": 3, "b:d:f": 4})
        # {
        #   "a": 1,
        #   "b": {"c": 2, "d": {"e": 3, "f": 4}},
        # }
    """
    target_dict: t.Dict[object, object] = {}
    for key, value in flattened.items():
        if not isinstance(key, str):
            raise ValueError(f"{key}: expected {str}, but got {type(key)}")
        if ":" in key:
            current_dict: t.Union[object, t.Dict[object, object]] = target_dict
            parts = key.split(":")
            length = len(parts)
            for idx in range(length):
                part = parts[idx]
                if not isinstance(current_dict, dict):
                    continue
                if part not in current_dict:
                    current_dict[part] = value if idx == (length - 1) else {}
                current_dict = current_dict[part]
        else:
            target_dict[key] = value
    return target_dict

# Load VPoser2 model weights
import toolz
import torch
import logging
import typing
import os
import glob

logger = logging.getLogger(__name__)
__all__ = ["VPoserLoader"]

class VPoserLoader(typing.Callable[[torch.nn.Module], None]):
    def __init__(self, 
        checkpoint_path: str,        
        use_cache: bool = False,
    ):
        if os.path.isdir(checkpoint_path):
            self.file_path = glob.glob(os.path.join(checkpoint_path, 'snapshots', '*.ckpt'))[-1]
        else:
            self.file_path = checkpoint_path

        if use_cache:
            self.loaded_state = torch.load(
                self.file_path, map_location=lambda storage, loc: storage
            )['state_dict']

    def __call__(self,
        model: torch.nn.Module
    ) -> None:        
        if isinstance(model, VPoser):
            state = self.loaded_state if hasattr(self, 'loaded_state') else torch.load(
                self.file_path, map_location=lambda storage, loc: storage
            )['state_dict']
            model.load_state_dict(
                toolz.keymap(lambda k: k.replace('vp_model.', ''), state),
                strict=False
            )
            logger.info(f"Loaded VPoser weights from {self.file_path}")

import uuid
import logging
from flask_login import current_user
from app.extensions import db, HoustonModel
import app.extensions.logging as AuditLog
from app.utils import HoustonException
log = logging.getLogger(__name__)

class CollaborationUserState:
    ALLOWED_STATES = [
        'declined',
        'approved',
        'pending',
        'not_initiated',
        'revoked',
        'creator',
    ]
    DECLINED = ALLOWED_STATES[0]
    APPROVED = ALLOWED_STATES[1]
    PENDING = ALLOWED_STATES[2]
    NOT_INITIATED = ALLOWED_STATES[3]
    REVOKED = ALLOWED_STATES[4]
    CREATOR = ALLOWED_STATES[5]

class CollaborationUserAssociations(db.Model, HoustonModel):
    """
    Collaboration many-to-many association with Users.
    Current maximum of two users per Collaboration.
    """
    __mapper_args__ = {
        'confirm_deleted_rows': False,
    }
    collaboration_guid = db.Column(
        db.GUID, db.ForeignKey('collaboration.guid'), default=uuid.uuid4, primary_key=True
    )
    collaboration = db.relationship(
        'Collaboration', back_populates='collaboration_user_associations'
    )
    user_guid = db.Column(db.GUID, db.ForeignKey('user.guid'), primary_key=True)
    user = db.relationship('User', backref=db.backref('user_collaboration_associations'))
    read_approval_state = db.Column(
        db.String(length=32), default=CollaborationUserState.PENDING, nullable=False
    )
    edit_approval_state = db.Column(
        db.String(length=32), default=CollaborationUserState.NOT_INITIATED, nullable=False
    )

    def delete(self):
        self.collaboration.user_deleted(self)

    def has_read(self):
        return self.collaboration.user_has_read_access(self.user_guid)

    def has_edit(self):
        return self.collaboration.user_has_edit_access(self.user_guid)

    def get_other_user(self):
        return self.collaboration.get_other_user(self.user_guid)


class Collaboration(db.Model, HoustonModel):
    """
    Collaborations database model.
    """
    __mapper_args__ = {
        'confirm_deleted_rows': False,
    }
    guid = db.Column(
        db.GUID, default=uuid.uuid4, primary_key=True
    )  # pylint: disable=invalid-name
    collaboration_user_associations = db.relationship(
        'CollaborationUserAssociations', back_populates='collaboration'
    )
    initiator_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=False
    )
    edit_initiator_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=True
    )

    def __init__(self, members, initiator_user, **kwargs):
        num_users = len(members)
        if num_users != 2:
            raise ValueError('Creating a collaboration requires 2 members.')
        if not hasattr(initiator_user, 'is_user_manager'):
            # current user is not actually a User although it quacks like one so can't use isinstance
            raise ValueError(f'initiator_user {initiator_user} is not a user')
        # user manager created are handled differently
        manager_created = initiator_user not in members
        if manager_created and not initiator_user.is_user_manager:
            raise ValueError(
                f'Attempted creation of a collaboration by a non manager {initiator_user.email}.'
            )
        self.initiator_guid = initiator_user.guid
        self.edit_initiator_guid = None
        for user in members:
            if not hasattr(user, 'is_user_manager'):
                raise ValueError(f'User {user} is not a user manager')
            collab_user_assoc = CollaborationUserAssociations(
                collaboration=self, user=user
            )
            # Edit not enabled on creation
            collab_user_assoc.edit_approval_state = CollaborationUserState.NOT_INITIATED
            with db.session.begin(subtransactions=True):
                db.session.add(collab_user_assoc)
            # If you initiate, then you approve read. Manager created are also read approved
            if user == initiator_user or manager_created:
                collab_user_assoc.read_approval_state = CollaborationUserState.APPROVED
            else:
                collab_user_assoc.read_approval_state = CollaborationUserState.PENDING
        if manager_created:
            # User manager created collaboration, store who the creator was
            collab_creator = CollaborationUserAssociations(
                collaboration=self, user=initiator_user
            )
            from app.modules.notifications.models import NotificationType
            collab_creator.read_approval_state = CollaborationUserState.CREATOR
            collab_creator.edit_approval_state = CollaborationUserState.CREATOR
            for user in members:
                user_assoc = self._get_association_for_user(user.guid)
                self._notify_user(
                    collab_creator, user_assoc, NotificationType.collab_manager_create
                )
            with db.session.begin(subtransactions=True):
                db.session.add(collab_creator)

    def _get_association_for_user(self, user_guid):
        assoc = None
        for association in self.collaboration_user_associations:
            if association.user_guid == user_guid:
                assoc = association
        return assoc

    def _get_association_for_other_user(self, user_guid):
        assoc = None
        if user_guid is not None:
            other_user_guids = [
                association.user_guid
                for association in self.collaboration_user_associations
                if (association.user_guid != user_guid)
                & (association.read_approval_state != CollaborationUserState.CREATOR)
            ]
            assert len(other_user_guids) == 1
            assoc = self._get_association_for_user(other_user_guids[0])
        return assoc

    def get_users(self):
        users = []
        for association in self.collaboration_user_associations:
            if association.read_approval_state != CollaborationUserState.CREATOR:
                users.append(association.user)
        return users

    def user_guids(self):
        user_guids = []
        for association in self.collaboration_user_associations:
            if association.read_approval_state != CollaborationUserState.CREATOR:
                user_guids.append(association.user_guid)
        return user_guids

    def notify_pending_users(self):
        # Once created notify the pending user to accept
        for collab_user_assoc in self.collaboration_user_associations:
            if (
                collab_user_assoc.read_approval_state == CollaborationUserState.PENDING
                or collab_user_assoc.edit_approval_state == CollaborationUserState.PENDING
            ):
                from app.modules.notifications.models import NotificationType
                other_user_assoc = self._get_association_for_other_user(
                    collab_user_assoc.user.guid
                )
                if (
                    collab_user_assoc.read_approval_state
                    == CollaborationUserState.PENDING
                ):
                    self._notify_user(
                        other_user_assoc,
                        collab_user_assoc,
                        NotificationType.collab_request,
                    )
                if (
                    collab_user_assoc.edit_approval_state
                    == CollaborationUserState.PENDING
                ):
                    self._notify_user(
                        other_user_assoc,
                        collab_user_assoc,
                        NotificationType.collab_edit_request,
                    )

    def _notify_user(self, sending_user_assoc, receiving_user_assoc, notification_type):
        from app.modules.notifications.models import Notification, NotificationBuilder
        builder = NotificationBuilder(sending_user_assoc.user)
        builder.set_collaboration(self)
        Notification.create(notification_type, receiving_user_assoc.user, builder)

    def get_user_data_as_json(self):
        from app.modules.users.schemas import BaseUserSchema
        user_data = {}
        for association in self.collaboration_user_associations:
            if association.read_approval_state == CollaborationUserState.CREATOR:
                continue
            assoc_data = BaseUserSchema().dump(association.user).data
            assoc_data['viewState'] = association.read_approval_state
            assoc_data['editState'] = association.edit_approval_state
            user_data[str(association.user.guid)] = assoc_data
        return user_data

    def _is_approval_state_transition_valid(self, old_state, new_state):
        ret_val = False
        # Only certain transitions are permitted
        if old_state == CollaborationUserState.NOT_INITIATED:
            ret_val = new_state in [
                CollaborationUserState.CREATOR,
                CollaborationUserState.APPROVED,
                CollaborationUserState.PENDING,
            ]
        elif old_state == CollaborationUserState.PENDING:
            ret_val = new_state in [
                CollaborationUserState.APPROVED,
                CollaborationUserState.DECLINED,
            ]
        elif old_state == CollaborationUserState.APPROVED:
            ret_val = new_state == CollaborationUserState.REVOKED
        elif old_state == CollaborationUserState.DECLINED:
            ret_val = new_state == CollaborationUserState.APPROVED
        elif old_state == CollaborationUserState.REVOKED:
            ret_val = new_state == CollaborationUserState.APPROVED
        # Permit resetting to same state in all cases rather than handling separately for each
        if not ret_val:
            ret_val = old_state == new_state
        return ret_val

    def set_read_approval_state_for_user(self, user_guid, state):
        success = False
        if state not in CollaborationUserState.ALLOWED_STATES:
            raise ValueError(
                f'State "{state}" not in allowed states: {", ".join(CollaborationUserState.ALLOWED_STATES)}'
            )
        if user_guid is not None:
            assert isinstance(user_guid, uuid.UUID)
            for association in self.collaboration_user_associations:
                if association.user_guid == user_guid:
                    if self._is_approval_state_transition_valid(
                        association.read_approval_state, state
                    ):
                        association.read_approval_state = state
                        # If a user revokes view and previously allowed edit, they automatically
                        # revoke edit too
                        if (
                            state == CollaborationUserState.REVOKED
                            and association.edit_approval_state
                            == CollaborationUserState.APPROVED
                        ):
                            association.edit_approval_state = state
                        from app.modules.notifications.models import NotificationType
                        if state == CollaborationUserState.REVOKED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_revoke,
                            )
                        elif state == CollaborationUserState.APPROVED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_approved,
                            )
                        with db.session.begin(subtransactions=True):
                            db.session.merge(association)
                        success = True
        return success

    def user_has_read_access(self, user_guid):
        ret_val = False
        assert isinstance(user_guid, uuid.UUID)
        my_assoc = self._get_association_for_user(user_guid)
        other_assoc = self._get_association_for_other_user(user_guid)
        if my_assoc and other_assoc:
            ret_val = (
                my_assoc.read_approval_state == CollaborationUserState.APPROVED
                and other_assoc.read_approval_state == CollaborationUserState.APPROVED
            )
        return ret_val

    def user_has_edit_access(self, user_guid):
        ret_val = False
        assert isinstance(user_guid, uuid.UUID)
        my_assoc = self._get_association_for_user(user_guid)
        other_assoc = self._get_association_for_other_user(user_guid)
        if my_assoc and other_assoc:
            ret_val = (
                my_assoc.edit_approval_state == CollaborationUserState.APPROVED
                and other_assoc.edit_approval_state == CollaborationUserState.APPROVED
            )
        return ret_val

    def get_other_user(self, user_guid):
        other_assoc = self._get_association_for_other_user(user_guid)
        if other_assoc:
            return other_assoc.user
        return None

    def set_edit_approval_state_for_user(self, user_guid, state):
        success = False
        if state not in CollaborationUserState.ALLOWED_STATES:
            raise ValueError(
                f'State "{state}" not in allowed states: {", ".join(CollaborationUserState.ALLOWED_STATES)}'
            )
        if user_guid is not None:
            assert isinstance(user_guid, uuid.UUID)
            for association in self.collaboration_user_associations:
                if association.user_guid == user_guid:
                    if self._is_approval_state_transition_valid(
                        association.edit_approval_state, state
                    ):
                        association.edit_approval_state = state
                        with db.session.begin(subtransactions=True):
                            db.session.merge(association)
                        from app.modules.notifications.models import NotificationType
                        if state == CollaborationUserState.REVOKED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_edit_revoke,
                            )
                        elif state == CollaborationUserState.APPROVED:
                            self._notify_user(
                                association,
                                self._get_association_for_other_user(user_guid),
                                NotificationType.collab_edit_approved,
                            )
                        success = True
        return success

    def initiate_edit_with_other_user(self):
        self.edit_initiator_guid = current_user.guid
        my_assoc = self._get_association_for_user(current_user.guid)
        other_assoc = self._get_association_for_other_user(current_user.guid)
        if (
            my_assoc.read_approval_state == CollaborationUserState.APPROVED
            and other_assoc.read_approval_state == CollaborationUserState.APPROVED
        ):
            if self._is_approval_state_transition_valid(
                my_assoc.read_approval_state, CollaborationUserState.APPROVED
            ):
                my_assoc.edit_approval_state = CollaborationUserState.APPROVED
                with db.session.begin(subtransactions=True):
                    db.session.merge(my_assoc)
            if self._is_approval_state_transition_valid(
                other_assoc.edit_approval_state, CollaborationUserState.PENDING
            ):
                other_assoc.edit_approval_state = CollaborationUserState.PENDING
                with db.session.begin(subtransactions=True):
                    db.session.merge(other_assoc)
        else:
            raise HoustonException(
                log, 'Unable to start edit on unapproved collaboration'
            )

    # This relates to if the user can access the collaboration itself, not the data
    def user_can_access(self, user):
        return user in self.get_users()

    def __repr__(self):
        return (
            '<{class_name}('
            'guid={self.guid}, '
            ')>'.format(class_name=self.__class__.__name__, self=self)
        )

    def user_deleted(self, user_association):
        if user_association.read_approval_state == CollaborationUserState.CREATOR:
            # Collaboration creator removal is an odd case, we have to have an initiator so chose an arbitrary member
            new_creator = (
                self.collaboration_user_associations[0]
                if self.collaboration_user_associations[0] != user_association
                else self.collaboration_user_associations[1]
            )
            message = (
                f'Initiator user removed, assigning {new_creator.user_guid} as initiator'
            )
            AuditLog.audit_log_object(log, self, message)
            self.initiator_guid = new_creator.user_guid
            with db.session.begin(subtransactions=True):
                db.session.merge(self)
                db.session.delete(user_association)
        else:
            # If the user is a member and are removed then the collaboration is removed entirely
            self.delete()

    def delete(self):
        AuditLog.delete_object(log, self)
        with db.session.begin(subtransactions=True):
            for assoc in self.collaboration_user_associations:
                db.session.delete(assoc)
            db.session.delete(self)

