# Upload public data to Scalingo environment
import click
import subprocess
from variables import *  # noqa: F403

@click.command()
@click.option(
    "--environment",
    default="staging",
    type=click.Choice(["staging", "prod"], case_sensitive=True),
    help="Select deployment environment",
)
@click.option(
    "--model_class", default=None, type=str, help="Upload data for a specific model"
)
def upload_public_data(environment, model_class=None):
    """Trigger the load_data management command on the public_data Scalingo app."""
    # Retrieve environment configuration
    env_config = ENVS[environment]  # noqa: F405

    # Construct the scalingo command
    cmd_parts = (
        f"scalingo --app {env_config['app']} --region {env_config['region']} "
        "run python manage.py load_data"
    )

    if model_class:
        if model_class.startswith("public_data.models"):
            cmd_parts += f" --class {model_class}"
        else:
            cmd_parts += f" --class public_data.models.{model_class}"

    click.echo(f"Running command: {cmd_parts}")

    # Prepare and execute command
    command_list = cmd_parts.split()
    try:
        result = subprocess.run(
            command_list,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        if result.stdout:
            click.secho(result.stdout, fg="green")
    except subprocess.CalledProcessError as error:
        click.secho(f"An error occurred: {error}", fg="red")

if __name__ == "__main__":
    upload_public_data()

