from Crypto.Signature import pkcs1_15
from Crypto.Hash import SHA256
from Crypto.PublicKey import RSA
from riposte import Riposte
from riposte.printer import Palette
import os.path
import sys

# Initialize the interactive shell
shell = Riposte('[blastdoor]$ ')

@shell.command('help')
def display_help():
    shell.status("Available commands:")
    shell.status("generate <filename>       - Create a new RSA private key")
    shell.status("publickey <filename>      - Extract and display public key from private key file")
    shell.status("sign <filename> <message> - Sign a message using the private key")
    shell.status("exit                      - Terminate the program")

@shell.command('generate')
def create_key(filename: str):
    if not os.path.exists(filename):
        shell.status("Generating RSA key pair...")
        private_key = RSA.generate(4096)
        key_data = private_key.export_key()
        shell.status("Saving private key to file...")
        with open(filename, 'wb') as key_file:
            key_file.write(key_data)
        shell.success("Key generation completed successfully")
    else:
        shell.error("Error: File already exists!")

@shell.command('publickey')
def show_public_key(filename: str):
    if os.path.isfile(filename):
        with open(filename, 'r') as f:
            imported_key = RSA.import_key(f.read())
        shell.print(Palette.CYAN.format(imported_key.publickey().export_key().decode('utf-8')))
    else:
        shell.error("Error: Specified file does not exist!")

@shell.command('sign')
def sign_message(filename: str, message: str):
    if os.path.isfile(filename):
        with open(filename, 'r') as f:
            private_key = RSA.import_key(f.read())

        hash_obj = SHA256.new(message.encode('utf-8'))
        signature = pkcs1_15.new(private_key).sign(hash_obj)
        shell.print(Palette.CYAN.format(b64encode(signature).decode('utf-8')))
    else:
        shell.error("Error: File not found!")

@shell.command('exit')
def terminate_program():
    shell.status("Goodbye!")
    sys.exit(0)

shell.run()

# Modified version of ElasticMappingMixin for generating search suggestions
from typing import List, Dict, Any
from collections import defaultdict
from elasticsearch.exceptions import RequestError
from lucyfer.searchset.fields.mapping.base import MappingMixin

class ElasticMappingMixin(MappingMixin):
    def prepare_search_for_suggestions(self, search_query, term_prefix: str) -> Any:
        # Configure search to return no results but include aggregations
        search = search_query.extra(size=0).query(
            'query_string', 
            **{"fields": self.sources, "query": f'*{term_prefix}*'}
        )

        # Add terms aggregation for each source field
        for field_source in self.sources:
            search.aggs.bucket(field_source, "terms", field=field_source)

        return search

    def extract_suggestions_from_search(self, search_query, term_prefix: str) -> List[str]:
        try:
            # Execute search and get aggregation results
            response_dict = search_query.execute().to_dict()
            aggregations = response_dict.get("aggregations", defaultdict(dict))
        except RequestError:
            return []

        suggestion_list = []

        # Process each source field's buckets
        for field_source in self.sources:
            if aggregations[field_source].get("buckets"):
                # Extract keys from buckets and filter by prefix
                bucket_items = [str(bucket_item["key"]) 
                               for bucket_item in aggregations[field_source]["buckets"]]
                filtered_items = [item for item in bucket_items if term_prefix in item]
                suggestion_list.extend(filtered_items)

        # Remove duplicates and return unique suggestions
        return list(set(suggestion_list))

# Database handler for managing work entries
import sqlite3

class WorkDatabase:
    def __init__(self) -> None:
        self.connection = sqlite3.connect("WorkDatabase.db")
        self.cursor = self.connection.cursor()
        self.cursor.execute(
            "CREATE TABLE IF NOT EXISTS WorkDatabase(description TEXT, category TEXT, creationDate DATE)"
        )

    def InsertWork(self, work_entry):
        self.cursor.execute(
            "INSERT INTO WorkDatabase(description, category, creationDate) VALUES(?, ?, ?)",
            (work_entry.description, work_entry.category, work_entry.creationDate),
        )
        return self.cursor.lastrowid

    def GetAllWorks(self):
        return self.cursor.execute("SELECT rowid, * FROM WorkDatabase").fetchall()

    def __del__(self):
        self.connection.commit()
        self.connection.close()

