# Define version history and related models for entity metadata management
from __future__ import annotations
from typing import List, Optional
from pydantic import BaseModel, Extra, Field, confloat

class EntityVersionHistory(BaseModel):
    class Config:
        extra = Extra.forbid

    entityType: str = Field(
        ...,
        description='Type of entity (e.g., `database`, `table`, `dashboard`) for which this version history applies.',
    )
    versions: List

class EntityVersion(BaseModel):
    __root__: confloat(ge=0.1, multiple_of=0.1) = Field(
        ...,
        description='Metadata version in `Major.Minor` format. Initial version is `0.1`. Minor version increments for backward-compatible changes (e.g., `1.0` → `1.1`). Major version increments for breaking changes (e.g., `1.1` → `2.0`).',
    )

class ChangeDescription(BaseModel):
    class Config:
        extra = Extra.forbid

    fieldsAdded: Optional[List[str]] = Field(
        None, description='List of fields newly introduced in the version change.'
    )
    fieldsUpdated: Optional[List[str]] = Field(
        None, description='List of fields whose values were modified during the version change.'
    )
    fieldsDeleted: Optional[List[str]] = Field(
        None, description='List of fields removed during the version change.'
    )
    previousVersion: Optional[EntityVersion] = None

import oneflow as flow
from oneflow_gpt.model import Embedding, LayerNorm
from oneflow_gpt.model import ColumnParallelLinear, RowParallelLinear

def create_gradient_scaler(config):
    if config.grad_scale_value is not None:
        scaler = flow.amp.StaticGradScaler(config.grad_scale_value)
    elif config.scale_init_value is not None:
        scaler = flow.amp.GradScaler(
            init_scale=config.scale_init_value,
            growth_factor=2.0,
            backoff_factor=0.5,
            growth_interval=config.scale_window,
        )
    else:
        scaler = None
    return scaler

def build_lr_scheduler(config, optimizer):
    assert config.decay_mode in ("none", "cosine")
    if config.decay_mode == "none":
        return None
    if config.decay_steps is None:
        return None
    min_lr_ratio = config.min_learning_rate / config.learning_rate
    scheduler = flow.optim.lr_scheduler.CosineDecayLR(
        optimizer, decay_steps=config.decay_steps, alpha=min_lr_ratio,
    )
    if config.warmup_steps is not None and config.warmup_steps > 0:
        scheduler = flow.optim.lr_scheduler.WarmUpLR(
            scheduler,
            warmup_factor=0,
            warmup_iters=config.warmup_steps,
            warmup_method="linear",
        )
    return scheduler

def _collect_weight_decay_params(module):
    decay_group = {"params": []}
    no_decay_group = {"params": [], "weight_decay": 0.0}
    for submodule in module.modules():
        if isinstance(submodule, Embedding):
            for param in submodule.parameters(recurse=False):
                if param is None:
                    continue
                decay_group["params"].append(param)
        elif isinstance(submodule, LayerNorm):
            for param in submodule.parameters(recurse=False):
                if param is None:
                    continue
                no_decay_group["params"].append(param)
        elif isinstance(submodule, (ColumnParallelLinear, RowParallelLinear)):
            for name, param in submodule.named_parameters(recurse=False):
                if param is None:
                    continue
                if name == "weight":
                    decay_group["params"].append(param)
                elif name == "bias":
                    no_decay_group["params"].append(param)
                else:
                    raise NotImplementedError("parameter not supported")
        else:
            assert len(list(submodule.parameters(recurse=False))) == 0
    return [decay_group, no_decay_group]

def _apply_gradient_clipping(param_groups, max_norm):
    if int(max_norm) == 1:
        for group in param_groups:
            group["clip_grad_max_norm"] = 1.0
            group["clip_grad_norm_type"] = 2.0

def construct_optimizer(config, model):
    param_lists = _collect_weight_decay_params(model)
    _apply_gradient_clipping(param_lists, config.grad_clip_threshold)
    if config.training_optimizer == "adamw":
        opt = flow.optim.AdamW(
            param_lists,
            lr=config.learning_rate,
            weight_decay=config.l2_regularization,
            betas=(config.adam_beta1, config.adam_beta2),
            eps=config.adam_epsilon,
        )
    elif config.training_optimizer == "sgd":
        opt = flow.optim.SGD(param_lists, lr=config.learning_rate)
    else:
        raise NotImplementedError("optimizer not supported")
    return opt

