def set_seed(seed):
    torch.manual_seed(seed)

set_seed(42)

class TextGenie:
    def __init__(
        self,
        paraphrase_model_name,
        mask_model_name=None,
        spacy_model_name="en_core_web_sm",
        device="cpu",
    ):
        tqdm.write("Loading Paraphrase Model..")
        self.paraphrase_model = T5ForConditionalGeneration.from_pretrained(
            paraphrase_model_name
        )
        self.paraphrase_tokenizer = T5Tokenizer.from_pretrained(paraphrase_model_name)
        self.paraphrase_model = self.paraphrase_model.to(device)
        self.device = device

        if mask_model_name:
            tqdm.write("Loading Mask Fill Model..")
            from transformers import pipeline
            self.mask_augmenter = pipeline("fill-mask", model=mask_model_name)
            import spacy
            self.nlp = spacy.load(spacy_model_name)

    def extract_keywords(self, sentence):
        result = []
        pos_tags = ["PROPN", "NOUN", "ADJ"]
        special_tags = ["NUM"]
        valid_pos_tags = pos_tags + special_tags

        doc = self.nlp(sentence)
        for token in doc:
            if (token.text in self.nlp.Defaults.stop_words or token.text in punctuation) and token.pos_ not in special_tags:
                continue
            if token.pos_ in valid_pos_tags:
                result.append(token.text)
        return list(set(result))

    def augment_sent_mask_filling(self, sent, n_mask_predictions=5):
        keywords = self.extract_keywords(sent)
        augmented_sents = []
        for keyword in keywords:
            masked_sent = sent.replace(keyword, self.mask_augmenter.tokenizer.mask_token, 1)
            candidates = self.mask_augmenter(masked_sent, top_k=n_mask_predictions)
            for generated_sent in candidates:
                if generated_sent["sequence"].lower() != sent.lower():
                    augmented_sents.append(generated_sent["sequence"])
        return augmented_sents

    def augment_sent_t5(self, sent, prefix, n_predictions=5, top_k=120, max_length=256):
        text = prefix + sent + " </s>"
        encoding = self.paraphrase_tokenizer.encode_plus(
            text, pad_to_max_length=True, return_tensors="pt"
        )
        input_ids = encoding["input_ids"].to(self.device)
        attention_masks = encoding["attention_mask"].to(self.device)

        beam_outputs = self.paraphrase_model.generate(
            input_ids=input_ids,
            attention_mask=attention_masks,
            do_sample=True,
            max_length=max_length,
            top_k=top_k,
            top_p=0.98,
            early_stopping=True,
            num_return_sequences=n_predictions,
        )

        final_outputs = []
        for beam_output in beam_outputs:
            generated_sent = self.paraphrase_tokenizer.decode(
                beam_output, skip_special_tokens=True, clean_up_tokenization_spaces=True
            )
            if (
                generated_sent.lower() != sent.lower()
                and generated_sent not in final_outputs
            ):
                final_outputs.append(generated_sent)
        return final_outputs

    def convert_to_active(self, sent):
        if is_passive(sent):
            return pass2act(sent)
        else:
            return sent

    def magic_once(
        self,
        sent,
        paraphrase_prefix,
        n_paraphrase_predictions=5,
        paraphrase_top_k=120,
        paraphrase_max_length=256,
        n_mask_predictions=None,
        convert_to_active=True,
    ):
        sent = sent.strip()
        output = []
        output += self.augment_sent_t5(
            sent,
            paraphrase_prefix,
            n_paraphrase_predictions,
            paraphrase_top_k,
            paraphrase_max_length,
        )
        if n_mask_predictions and isinstance(n_mask_predictions, int):
            output += self.augment_sent_mask_filling(sent, n_mask_predictions)
        if convert_to_active:
            active_voice = self.convert_to_active(sent)
            if active_voice.lower() != sent.lower():
                output.append(active_voice)
        return list(set(output))

    def magic_lamp(
        self,
        sentences,
        paraphrase_prefix,
        n_paraphrase_predictions=5,
        paraphrase_top_k=120,
        paraphrase_max_length=256,
        n_mask_predictions=None,
        convert_to_active=True,
        label_column=None,
        data_column=None,
        column_names=None,
    ):
        all_sentences = None
        with_labels = False
        out_file = os.path.join(os.getcwd(), "sentences_aug.txt")

        if isinstance(sentences, str):
            sentences_path = os.path.join(os.getcwd(), sentences)
            if sentences_path.endswith(".txt"):
                all_sentences = open(sentences_path).read().strip().split("\n")
            elif sentences_path.endswith(".csv") or sentences_path.endswith(".tsv"):
                if not label_column:
                    raise Exception(
                        "Please provide the column name that contains labels using the 'label_column' parameter."
                    )
                if not data_column:
                    raise Exception(
                        "Please provide the column name that contains data using the 'data_column' parameter."
                    )
                if column_names and not isinstance(column_names, list):
                    raise Exception("Please provide column names in a python list.")

                out_file = (
                    sentences_path.replace(".csv", "").replace(".tsv", "") + "_aug.tsv"
                )
                with_labels = True

                if sentences_path.endswith(".csv"):
                    if column_names:
                        all_sentences = pd.read_csv(sentences_path, names=column_names)
                    else:
                        all_sentences = pd.read_csv(sentences_path)
                elif sentences_path.endswith(".tsv"):
                    if column_names:
                        all_sentences = pd.read_csv(
                            sentences_path, names=column_names, sep="\t"
                        )
                    else:
                        all_sentences = pd.read_csv(sentences_path)

                if label_column not in all_sentences.columns:
                    raise Exception(
                        "Please provide label column name for the dataset using the 'label_column' parameter. If already provided, please check for typos in the name of the label column."
                    )
                if data_column not in all_sentences.columns:
                    raise Exception(
                        "Please provide data column name for the dataset using the 'data_column' parameter. If already provided, please check for typos in the name of the data column."
                    )

                labels = all_sentences[label_column].unique()
                if all_sentences.iloc[0].tolist() == column_names:
                    all_sentences = all_sentences.drop(0)

                augmented_data = []
                for ix in tqdm(range(all_sentences.shape[0])):
                    sent = all_sentences[data_column][ix].strip()
                    label = all_sentences[label_column][ix].strip()
                    aug_sent = self.magic_once(
                        sent,
                        paraphrase_prefix,
                        n_paraphrase_predictions,
                        paraphrase_top_k,
                        paraphrase_max_length,
                        n_mask_predictions,
                        convert_to_active,
                    )
                    aug_sent = [[s, label] for s in aug_sent]
                    augmented_data.extend(aug_sent)

                augmented_data = pd.DataFrame(
                    data=augmented_data, columns=["Text", "Label"]
                )
                augmented_data.to_csv(out_file, sep="\t", index=None)
            else:
                raise Exception(
                    "Unsupported file format. Currently, following formats are supported: list/csv/tsv"
                )
        elif isinstance(sentences, list):
            all_sentences = sentences

        if all_sentences is None:
            raise Exception("Error: No sentences found.")

        if not with_labels:
            augmented_data = []
            for sent in tqdm(all_sentences):
                augmented_data.extend(
                    self.magic_once(
                        sent,
                        paraphrase_prefix,
                        n_paraphrase_predictions,
                        paraphrase_top_k,
                        paraphrase_max_length,
                        n_mask_predictions,
                        convert_to_active,
                    )
                )
            with open(out_file, "w") as f:
                for line in augmented_data:
                    f.write(line + "\n")

        tqdm.write(f"\nCompleted writing output to {out_file}.")
        return augmented_data

# Modified version of Vocabulary class with renamed variables and reordered logic
import collections
from typing import Iterable, Optional, Sequence
from absl import logging

class Vocabulary:
  """Represents a vocabulary that can be built from a dataset."""
  def __init__(self,
               vocab_file: Optional[str] = None,
               sequences: Optional[Iterable[Sequence[bytes]]] = None,
               min_count: int = 1,
               pad_symbol: bytes = b'<pad>',
               unknown_symbol: bytes = b'<unk>',
               start_symbol: bytes = b'<s>',
               end_symbol: bytes = b'</s>'):
    """Loads the vocab from disk (if `vocab_file` is given) or builds it from `sequences`."""
    self.pad_token = pad_symbol
    self.unk_token = unknown_symbol
    self.bos_token = start_symbol
    self.eos_token = end_symbol
    self.special_tokens = (pad_symbol, unknown_symbol, start_symbol, end_symbol)

    if vocab_file:
      self.load(vocab_file)
    elif sequences is not None:
      self.build(sequences, min_freq=min_count)
    else:
      raise ValueError(
          ('Vocabulary needs either `vocab_file` or `sequences` to '
           'be provided, got %r and %r.') % (vocab_file, sequences))

  def build(self,
            tokenized_sequences: Iterable[Sequence[bytes]],
            min_freq: int = 1):
    """Builds a vocabulary over tokens with optional minimum frequency.
    Args:
      tokenized_sequences: Iterable of token sequences to build the vocabulary.
      min_freq: The minimum frequency of each token to be included. Default: 1.
    """
    # Count all the tokens.
    freq_counter = collections.Counter()
    for seq in tokenized_sequences:
      freq_counter.update(seq)

    # Add special tokens to the start of vocab.
    vocab_dict = collections.OrderedDict()
    for special_token in self.special_tokens:
      vocab_dict[special_token] = len(vocab_dict)

    # Add all other tokens to the vocab if their frequency is >= min_freq.
    for token, count in sorted(
        # Sort by frequency (from high to low), and then by token string.
        # This makes sure high frequency tokens get a low token ID.
        freq_counter.items(),
        key=lambda item: (-item[1], item[0])):
      if count >= min_freq:
        vocab_dict[token] = len(vocab_dict)

    logging.info('Number of unfiltered tokens: %d', len(freq_counter))
    logging.info('Vocabulary size: %d', len(vocab_dict))
    self.vocab = vocab_dict

  def __getitem__(self, key: str):
    return self.vocab[key]

  def keys(self):
    return self.vocab.keys()

  def values(self):
    return self.vocab.values()

  def __len__(self):
    return len(self.vocab)

  @property
  def pad_idx(self):
    """The index of the padding token."""
    return self.vocab[self.pad_token]

  @property
  def unk_idx(self):
    """The index of the unknown word token."""
    return self.vocab[self.unk_token]

  @property
  def bos_idx(self):
    """The index of the beginning-of-sequence token."""
    return self.vocab[self.bos_token]

  @property
  def eos_idx(self):
    """The index of the end-of-sequence token."""
    return self.vocab[self.eos_token]

  def load(self, path: str) -> None:
    """Loads a vocabulary (one token per line) from disk."""
    vocab_dict = collections.OrderedDict()
    with open(path, 'rb') as file_handle:
      for idx, token_line in enumerate(file_handle):
        assert isinstance(token_line, bytes), 'Expected byte tokens.'
        vocab_dict[token_line.rstrip()] = idx
    logging.info('Loaded vocabulary, size: %d', len(vocab_dict))
    self.vocab = vocab_dict

  def save(self, path: str) -> None:
    """Saves the vocabulary to disk."""
    with open(path, 'wb') as output_file:
      for token in self.vocab:
        assert isinstance(token, bytes), 'Expected byte tokens.'
        output_file.write(token + b'\n')
    logging.info('Saved vocabulary to %s.', path)

# Calculate archive data for export
import datetime
import io
import json
import os
import tarfile
import time
import typing
import zipfile
import flask
from .. import logic

def collect_export_files(user_identifier: int, target_object_ids: typing.Optional[typing.List[int]] = None) -> typing.Dict[str, bytes]:
    collected_files = {}
    if target_object_ids is None:
        active_instrument_ids = {
            instrument.identifier
            for instrument in logic.instruments.get_instruments()
        }
    else:
        active_instrument_ids = set()
    active_action_ids = set()
    active_user_ids = set()
    active_location_ids = set()
    referenced_markdown_images = set()
    accessible_objects = logic.object_permissions.get_objects_with_permissions(
        user_identifier,
        logic.object_permissions.Permissions.READ
    )
    export_data = {}
    object_records = []
    for obj in accessible_objects:
        if target_object_ids is not None and obj.identifier not in target_object_ids:
            continue
        collected_files[f"sampledb_export/{obj.identifier}.rdf"] = logic.rdf.generate_rdf(user_identifier, obj.identifier)
        object_records.append({
            'id': obj.identifier,
            'action_id': obj.action_id,
            'versions': [],
            'comments': [],
            'location_assignments': [],
            'publications': [],
            'files': []
        })
        active_action_ids.add(obj.action_id)
        for version in logic.objects.get_object_versions(obj.identifier):
            active_user_ids.add(version.user_id)
            object_records[-1]['versions'].append(
                {
                    'id': version.version_id,
                    'user_id': version.user_id,
                    'utc_datetime': version.utc_datetime.isoformat(),
                    'schema': version.schema,
                    'data': version.data
                }
            )
            for referenced_user_id, _ in logic.objects.find_user_references(version, False):
                active_user_ids.add(referenced_user_id)
            for markdown in logic.markdown_to_html.get_markdown_from_object_data(version.data):
                referenced_markdown_images.update(logic.markdown_images.find_referenced_markdown_images(logic.markdown_to_html.markdown_to_safe_html(markdown)))
        for comment in logic.comments.get_comments_for_object(obj.identifier):
            active_user_ids.add(comment.user_id)
            object_records[-1]['comments'].append({
                'id': comment.id,
                'author_id': comment.user_id,
                'content': comment.content,
                'utc_datetime': comment.utc_datetime.isoformat()
            })
        for assignment in logic.locations.get_object_location_assignments(obj.identifier):
            active_user_ids.add(assignment.user_id)
            active_user_ids.add(assignment.responsible_user_id)
            active_location_ids.add(assignment.location_id)
            object_records[-1]['location_assignments'].append({
                'id': assignment.id,
                'assigning_user_id': assignment.user_id,
                'responsible_user_id': assignment.responsible_user_id,
                'location_id': assignment.location_id,
                'utc_datetime': assignment.utc_datetime.isoformat(),
            })
        log_entries = logic.object_log.get_object_log_entries(obj.identifier, user_identifier)
        publication_entries = {
            (entry.data['doi'], entry.data['title']): entry
            for entry in log_entries
            if entry.type == logic.object_log.ObjectLogEntryType.LINK_PUBLICATION
        }
        for pub_info in logic.publications.get_publications_for_object(obj.identifier):
            object_records[-1]['publications'].append({
                'doi': pub_info.doi,
                'title': pub_info.title,
                'object_name': pub_info.object_name
            })
            if (pub_info.doi, pub_info.title) in publication_entries:
                pub_entry = publication_entries[(pub_info.doi, pub_info.title)]
                object_records[-1]['publications'][-1]['user_id'] = pub_entry.user_id
                object_records[-1]['publications'][-1]['utc_datetime'] = pub_entry.utc_datetime.isoformat()
        for file_info in logic.files.get_files_for_object(obj.identifier):
            if not file_info.is_hidden:
                active_user_ids.add(file_info.user_id)
                object_records[-1]['files'].append({
                    'id': file_info.id,
                    'hidden': False,
                    'title': file_info.title,
                    'description': file_info.description,
                    'uploader_id': file_info.user_id,
                    'utc_datetime': file_info.utc_datetime.isoformat()
                })
                if file_info.storage in {'local', 'database'}:
                    object_records[-1]['files'][-1]['original_file_name'] = file_info.original_file_name
                    try:
                        file_bytes = file_info.open(read_only=True).read()
                    except Exception:
                        pass
                    else:
                        file_name = os.path.basename(file_info.original_file_name)
                        object_records[-1]['files'][-1]['path'] = f'objects/{obj.identifier}/files/{file_info.id}/{file_name}'
                        collected_files[f"sampledb_export/objects/{obj.identifier}/files/{file_info.id}/{file_name}"] = file_bytes
                elif file_info.storage == 'url':
                    object_records[-1]['files'][-1]['url'] = file_info.url
            else:
                object_records[-1]['files'].append({
                    'id': file_info.id,
                    'hidden': True,
                    'hide_reason': file_info.hide_reason
                })
    export_data['objects'] = object_records
    action_records = []
    for action_record in logic.actions.get_actions():
        if action_record.id in active_action_ids:
            active_user_ids.add(action_record.user_id)
            active_instrument_ids.add(action_record.instrument_id)
            action_permissions = logic.action_permissions.get_user_action_permissions(action_record.id, user_identifier)
            if logic.action_permissions.Permissions.READ in action_permissions:
                action_translation = logic.action_translations.get_action_translation_for_action_in_language(
                    action_id=action_record.id,
                    language_id=logic.languages.Language.ENGLISH
                )
                action_type_translation = logic.action_type_translations.get_action_type_translation_for_action_type_in_language(
                    action_type_id=action_record.type_id,
                    language_id=logic.languages.Language.ENGLISH
                )
                action_records.append({
                    'id': action_record.id,
                    'type': action_type_translation.object_name.lower(),
                    'name': action_translation.name,
                    'user_id': action_record.user_id,
                    'instrument_id': action_record.instrument_id,
                    'description': action_translation.description,
                    'description_is_markdown': action_record.description_is_markdown,
                    'short_description': action_translation.short_description,
                    'short_description_is_markdown': action_record.short_description_is_markdown
                })
                if action_record.description_is_markdown:
                    referenced_markdown_images.update(logic.markdown_images.find_referenced_markdown_images(logic.markdown_to_html.markdown_to_safe_html(action_translation.description)))
                if action_record.short_description_is_markdown:
                    referenced_markdown_images.update(logic.markdown_images.find_referenced_markdown_images(logic.markdown_to_html.markdown_to_safe_html(action_translation.short_description)))
    export_data['actions'] = action_records
    instrument_records = []
    for instrument_record in logic.instruments.get_instruments():
        if instrument_record.id in active_instrument_ids:
            active_user_ids.update({user.id for user in instrument_record.responsible_users})
            instrument_translation = logic.instrument_translations.get_instrument_translation_for_instrument_in_language(
                instrument_id=instrument_record.id,
                language_id=logic.languages.Language.ENGLISH
            )
            instrument_records.append({
                'id': instrument_record.id,
                'name': instrument_translation.name,
                'description': instrument_translation.description,
                'description_is_markdown': instrument_record.description_is_markdown,
                'short_description': instrument_translation.short_description,
                'short_description_is_markdown': instrument_record.short_description_is_markdown,
                'instrument_scientist_ids': [user.id for user in instrument_record.responsible_users],
                'instrument_log_entries': []
            })
            user_is_responsible = user_identifier in [user.id for user in instrument_record.responsible_users]
            if user_is_responsible:
                instrument_records[-1]['notes'] = instrument_translation.notes
                instrument_records[-1]['notes_is_markdown'] = instrument_record.notes_is_markdown
            if instrument_record.users_can_view_log_entries or user_is_responsible:
                for log_entry in logic.instrument_log_entries.get_instrument_log_entries(instrument_record.id):
                    active_user_ids.add(log_entry.user_id)
                    instrument_records[-1]['instrument_log_entries'].append({
                        'id': log_entry.id,
                        'author_id': log_entry.user_id,
                        'file_attachments': [],
                        'object_attachments': [],
                        'versions': []
                    })
                    for version in log_entry.versions:
                        instrument_records[-1]['instrument_log_entries'][-1]['versions'].append({
                            'log_entry_id': log_entry.id,
                            'version_id': version.version_id,
                            'content': version.content,
                            'utc_datetime': version.utc_datetime.isoformat(),
                            'categories': []
                        })
                        for category in version.categories:
                            instrument_records[-1]['instrument_log_entries'][-1]['versions'][-1]['categories'].append({
                                'id': category.id,
                                'title': category.title
                            })
                    file_attachments = logic.instrument_log_entries.get_instrument_log_file_attachments(log_entry.id)
                    for attachment in file_attachments:
                        file_name = os.path.basename(attachment.file_name)
                        file_path = f'instruments/{instrument_record.id}/log_entries/{log_entry.id}/files/{attachment.id}/{file_name}'
                        instrument_records[-1]['instrument_log_entries'][-1]['file_attachments'].append({
                            'file_name': attachment.file_name,
                            'path': file_path
                        })
                        collected_files["sampledb_export/" + file_path] = attachment.content
                    object_attachments = logic.instrument_log_entries.get_instrument_log_object_attachments(log_entry.id)
                    for obj_attachment in object_attachments:
                        instrument_records[-1]['instrument_log_entries'][-1]['object_attachments'].append({
                            'object_id': obj_attachment.object_id
                        })
            if instrument_record.description_is_markdown:
                referenced_markdown_images.update(logic.markdown_images.find_referenced_markdown_images(logic.markdown_to_html.markdown_to_safe_html(instrument_translation.description)))
            if instrument_record.short_description_is_markdown:
                referenced_markdown_images.update(logic.markdown_images.find_referenced_markdown_images(logic.markdown_to_html.markdown_to_safe_html(instrument_translation.short_description)))
            if user_is_responsible and instrument_record.notes_is_markdown:
                referenced_markdown_images.update(logic.markdown_images.find_referenced_markdown_images(logic.markdown_to_html.markdown_to_safe_html(instrument_translation.notes)))
    export_data['instruments'] = instrument_records
    user_records = []
    for user_record in logic.users.get_users(exclude_hidden=False):
        if user_record.id in active_user_ids:
            user_records.append({
                'id': user_record.id,
                'name': user_record.name,
                'orcid_id': f'https://orcid.org/{user_record.orcid}' if user_record.orcid else None,
                'affiliation': user_record.affiliation if user_record.affiliation else None,
                'role': user_record.role if user_record.role else None
            })
    export_data['users'] = user_records
    locations = logic.locations.get_locations()
    all_relevant_location_ids = set()
    while active_location_ids:
        new_relevant_location_ids = set()
        for loc in locations:
            if loc.id in active_location_ids:
                new_relevant_location_ids.add(loc.parent_location_id)
        all_relevant_location_ids.update(active_location_ids)
        active_location_ids = new_relevant_location_ids - all_relevant_location_ids
    location_records = []
    for loc in locations:
        if loc.id in all_relevant_location_ids:
            location_records.append({
                'id': loc.id,
                'parent_id': loc.parent_location_id,
                'name': loc.name,
                'description': loc.description
            })
    export_data['locations'] = location_records
    for image_name in referenced_markdown_images:
        content = logic.markdown_images.get_markdown_image(image_name, user_identifier)
        if content is not None:
            collected_files[f'sampledb_export/markdown_files/{image_name}'] = content
    collected_files['sampledb_export/data.json'] = json.dumps(export_data, indent=2)
    readme_content = f"""SampleDB Export
===============
The file data.json contains information on objects from the SampleDB instance at {flask.url_for('frontend.index', _external=True)} in JSON format. Aside from information on the objects themselves, it also contains information on relevant actions, instruments, users and locations.
"""
    if len(collected_files) > 1:
        readme_content += """
The objects directory contains files uploaded for the objects in data.json.
"""
    readme_content += f"""
This archive was created for user #{user_identifier} at {datetime.datetime.now().isoformat()}.
"""
    collected_files["sampledb_export/README.txt"] = readme_content
    for name, content in collected_files.items():
        if isinstance(content, str):
            collected_files[name] = content.encode('utf-8')
    return collected_files

def create_zip_archive(user_identifier: int, target_object_ids: typing.Optional[typing.List[int]] = None) -> bytes:
    export_files = collect_export_files(user_identifier, target_object_ids=target_object_ids)
    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, 'w') as zip_file:
        for file_name, file_content in export_files.items():
            zip_file.writestr(file_name, file_content)
    return zip_buffer.getvalue()

def create_tar_gz_archive(user_identifier: int, target_object_ids: typing.Optional[typing.List[int]] = None) -> bytes:
    export_files = collect_export_files(user_identifier, target_object_ids=target_object_ids)
    tar_buffer = io.BytesIO()
    with tarfile.open('sampledb_export.tar.gz', 'w:gz', fileobj=tar_buffer) as tar_file:
        for file_name, file_content in export_files.items():
            tar_info = tarfile.TarInfo(file_name)
            tar_info.size = len(file_content)
            tar_info.mode = 0o444
            tar_info.mtime = time.time()
            tar_file.addfile(tar_info, fileobj=io.BytesIO(file_content))
    return tar_buffer.getvalue()

ARCHIVE_FORMATS = {
    '.zip': ('.zip Archive', create_zip_archive, 'application/zip'),
    '.tar.gz': ('.tar.gz Archive', create_tar_gz_archive, 'application/gzip')
}

# Abstract renderer implementation with context management
from __future__ import annotations
from abc import ABC, abstractmethod
from contextlib import contextmanager
from dataclasses import dataclass, field
from types import TracebackType
from typing import ContextManager, Iterator, Optional, Text, Type, TypeVar
from ..messages import Event

T = TypeVar("T", bound="BaseRenderer")

@dataclass  # type: ignore
class BaseRenderer(ContextManager["BaseRenderer"], ABC):
    """Base class for terminal renderers."""
    use_fullscreen: bool = field(default=True, init=False)
    """Flag indicating if fullscreen display mode is enabled."""

    @abstractmethod
    def draw(self, content: Text) -> None:
        """Display the given screen content."""
        raise NotImplementedError("This method must be implemented by subclasses")

    @abstractmethod
    def poll_event(self) -> Optional[Event]:
        """Retrieve the next available terminal event, if any."""
        raise NotImplementedError("This method must be implemented by subclasses")

    @abstractmethod
    def __enter__(self: T) -> T:
        """
        Enter the renderer's context.
        Initialize necessary resources and setup for rendering.
        """
        raise NotImplementedError("This method must be implemented by subclasses")

    @abstractmethod
    def __exit__(
        self,
        exception_type: Optional[Type[BaseException]],
        exception_instance: Optional[BaseException],
        traceback: Optional[TracebackType],
    ) -> Optional[bool]:
        """
        Exit the renderer's context.
        Clean up and release any allocated resources.
        """
        raise NotImplementedError("This method must be implemented by subclasses")

    @abstractmethod
    @contextmanager
    def raw_input_mode(self: T) -> Iterator[T]:
        """Activate raw input processing mode."""
        raise NotImplementedError("This method must be implemented by subclasses")

    @abstractmethod
    @contextmanager
    def cursor_invisible(self: T) -> Iterator[T]:
        """Temporarily hide the cursor during rendering."""
        raise NotImplementedError("This method must be implemented by subclasses")

# I *hate* creating utility modules like this... yet, inevitably, I end up with one
# after a while.
# They rarely match my expectations—perhaps because what I truly desire is to avoid
# writing such boilerplate. Doesn't everyone need to output information? Think of
# exceptions, for instance?
# I'm also perpetually torn about whether these modules justify their existence,
# or if I should instead inline the same repetitive logic at each `raise` site,
# where it might be read more directly.
# Anyway, here it is again. Once more.
# This module outputs text in plain, markdown-style format. It relies solely on
# the standard library and should remain that way.
"""
from typing import Sequence, Callable, Any, Iterable, Union
import inspect
from pathlib import Path
import shlex

def backtick(value) -> str:
    return f"`{value}`"

def format_class(cls) -> str:
    if cls.__module__ == "builtins":
        return backtick(cls.__name__)
    return backtick(f"{cls.__module__}.{cls.__name__}")

def format_path(path: Path) -> str:
    return backtick(path)

def format_command(
    cmd: Iterable[str],
    *,
    line_length: int=80,
    indent_size: Union[str, int]="  "
):
    if isinstance(indent_size, int):
        indent_size = " " * indent_size
    lines = [""]
    for part in cmd:
        escaped = shlex.quote(part)
        if len(lines[-1]) + 1 + len(escaped) > line_length - 2:
            lines[-1] += " \\"
            lines.append(indent_size)
        if not lines[-1].isspace():
            lines[-1] += " "
        lines[-1] += escaped
    return "\n".join(lines)

def format_item(x: Any) -> str:
    if inspect.isclass(x):
        return format_class(x)
    if isinstance(x, Path):
        return format_path(x)
    return repr(x)

def join_items(
    seq: Sequence,
    connector: str,
    *,
    converter: Callable[[Any], str] = format_item,
    delimiter: str = ",",
) -> str:
    """\
    Examples:
    1.  Empty sequence
        >>> join_items([])
        '[empty]'
    2.  Single-element sequence
        >>> join_items([42])
        '42'
    3.  Two-element sequence
        >>> join_items([1, 2])
        '1 and 2'
    4.  Multi-element sequence
        >>> join_items([1, 2, 3])
        '1, 2 and 3'
    5.  Uses `repr` by default
        >>> join_items(['x', 'y', 'z'])
        "'x', 'y' and 'z'"
    6.  Custom conversion function
        >>> join_items(['a', 'b'], connector='or', converter=lambda s: f"'{s}'")
        "'a' or 'b'"
    """
    count = len(seq)
    if count == 0:
        return "[empty]"
    if count == 1:
        return converter(seq[0])
    return f" {connector} ".join(
        (f"{delimiter} ".join(map(converter, seq[:-1])), converter(seq[-1]))
    )

# Asset Maintenance Management Module
from __future__ import unicode_literals
import frappe
from frappe.model.document import Document
from frappe.desk.form import assign_to
from frappe import throw, _
from frappe.utils import add_days, add_months, add_years, getdate, nowdate

class AssetMaintenance(Document):
    def validate(self):
        for task in self.get('asset_maintenance_tasks'):
            if task.end_date and (getdate(task.start_date) >= getdate(task.end_date)):
                throw(_("Start date should be earlier than end date for task {0}").format(task.maintenance_task))
            if getdate(task.next_due_date) < getdate(nowdate()):
                task.maintenance_status = "Overdue"

    def on_update(self):
        for task in self.get('asset_maintenance_tasks'):
            if not task.assign_to:
                task.db_set("assign_to", self.maintenance_manager)
                task.db_set("assign_to_name", self.maintenance_manager_name)
            schedule_tasks(self.name, task.assign_to, task.maintenance_task, task.next_due_date)
        self.sync_asset_tasks()

    def sync_asset_tasks(self):
        task_names = []
        for task in self.get('asset_maintenance_tasks'):
            task_names.append(task.name)
            update_maintenance_record(asset_maintenance=self.name, item_code=self.item_code, 
                                      item_name=self.item_name, task=task)

        asset_logs = frappe.get_all("Asset Maintenance Log", fields=["name"], 
                                    filters={"asset_maintenance": self.name,
                                             "task": ("not in", task_names)})

        if asset_logs:
            for log in asset_logs:
                record = frappe.get_doc('Asset Maintenance Log', log.name)
                record.db_set('maintenance_status', 'Cancelled')

@frappe.whitelist()
def schedule_tasks(asset_maintenance_name, assign_to_member, maintenance_task, next_due_date):
    team_member_email = frappe.get_doc('User', assign_to_member).email
    task_args = {
        'doctype': 'Asset Maintenance',
        'assign_to': team_member_email,
        'name': asset_maintenance_name,
        'description': maintenance_task,
        'date': next_due_date
    }

    existing_assignment = frappe.db.sql("""SELECT owner FROM `tabToDo`
        WHERE reference_type=%(doctype)s AND reference_name=%(name)s AND status='Open'
        AND owner=%(assign_to)s""", task_args)

    if not existing_assignment:
        assign_to.add(task_args)

@frappe.whitelist()
def calculate_next_due_date(periodicity, start_date=None, end_date=None, 
                           last_completion_date=None, next_due_date=None):
    if not start_date and not last_completion_date:
        start_date = frappe.utils.now()

    if last_completion_date and (last_completion_date > start_date or not start_date):
        start_date = last_completion_date

    if periodicity == 'Daily':
        next_due_date = add_days(start_date, 1)
    elif periodicity == 'Weekly':
        next_due_date = add_days(start_date, 7)
    elif periodicity == 'Monthly':
        next_due_date = add_months(start_date, 1)
    elif periodicity == 'Yearly':
        next_due_date = add_years(start_date, 1)
    elif periodicity == '2 Yearly':
        next_due_date = add_years(start_date, 2)
    elif periodicity == 'Quarterly':
        next_due_date = add_months(start_date, 3)

    if end_date and (start_date >= end_date or last_completion_date >= end_date or next_due_date):
        next_due_date = ""

    return next_due_date

def update_maintenance_record(asset_maintenance, item_code, item_name, task):
    existing_log = frappe.get_value("Asset Maintenance Log", {
        "asset_maintenance": asset_maintenance,
        "task": task.maintenance_task,
        "maintenance_status": ('in', ['Planned', 'Overdue'])
    })

    if not existing_log:
        new_log = frappe.get_doc({
            "doctype": "Asset Maintenance Log",
            "asset_maintenance": asset_maintenance,
            "asset_name": asset_maintenance,
            "item_code": item_code,
            "item_name": item_name,
            "task": task.maintenance_task,
            "has_certificate": task.certificate_required,
            "description": task.description,
            "assign_to_name": task.assign_to_name,
            "periodicity": str(task.periodicity),
            "maintenance_type": task.maintenance_type,
            "due_date": task.next_due_date
        })
        new_log.insert()
    else:
        maintenance_record = frappe.get_doc('Asset Maintenance Log', existing_log)
        maintenance_record.assign_to_name = task.assign_to_name
        maintenance_record.has_certificate = task.certificate_required
        maintenance_record.description = task.description
        maintenance_record.periodicity = str(task.periodicity)
        maintenance_record.maintenance_type = task.maintenance_type
        maintenance_record.due_date = task.next_due_date
        maintenance_record.save()

@frappe.whitelist()
def get_team_members(doctype, txt, searchfield, start, page_len, filters):
    return frappe.db.get_values('Maintenance Team Member', 
                                {'parent': filters.get("maintenance_team")})

@frappe.whitelist()
def get_maintenance_log(asset_name):
    return frappe.db.sql("""
        SELECT maintenance_status, COUNT(asset_name) AS count, asset_name
        FROM `tabAsset Maintenance Log`
        WHERE asset_name=%s 
        GROUP BY maintenance_status
    """, (asset_name,), as_dict=1)

# Modified version of the original code with Type I clone transformations
import dataclasses
from typing import Optional, Dict, Set, Tuple
import stim

# Constants for Clifford gate classifications
CLIFFORD_SINGLE_QUBIT_GATES = {"C_XYZ", "C_ZYX", "H", "H_YZ", "I"}
CLIFFORD_TWO_QUBIT_GATES = {"CX", "CY", "CZ", "XCX", "XCY", "XCZ", "YCX", "YCY", "YCZ"}
RESET_OPERATIONS = {"R", "RX", "RY"}
MEASUREMENT_OPERATIONS = {"M", "MX", "MY"}
ANNOTATION_OPERATIONS = {"OBSERVABLE_INCLUDE", "DETECTOR", "SHIFT_COORDS", "QUBIT_COORDS", "TICK"}

@dataclasses.dataclass(frozen=True)
class ErrorModel:
    # Error rates for different operations
    idle_error: float
    measurement_reset_idle_error: float
    gate_errors: Dict[str, float]

    # Optional global error rates for Clifford gates
    single_clifford_error_rate: Optional[float] = None
    two_clifford_error_rate: Optional[float] = None

    # Flag for correlated parity measurement errors
    use_correlated_parity_measurement_errors: bool = False

    @staticmethod
    def SD6(error_prob: float) -> 'ErrorModel':
        return ErrorModel(
            single_clifford_error_rate=error_prob,
            idle_error=error_prob,
            measurement_reset_idle_error=0,
            gate_errors={
                "CX": error_prob,
                "R": error_prob,
                "M": error_prob,
            },
        )

    @staticmethod
    def PC3(error_prob: float) -> 'ErrorModel':
        return ErrorModel(
            single_clifford_error_rate=error_prob,
            two_clifford_error_rate=error_prob,
            idle_error=error_prob,
            measurement_reset_idle_error=0,
            gate_errors={
                "R": error_prob,
                "M": error_prob,
            },
        )

    @staticmethod
    def EM3_v1(error_prob: float) -> 'ErrorModel':
        """EM3 but with measurement flip errors independent of measurement target depolarization error."""
        return ErrorModel(
            idle_error=error_prob,
            measurement_reset_idle_error=0,
            single_clifford_error_rate=error_prob,
            gate_errors={
                "R": error_prob,
                "M": error_prob,
                "MPP": error_prob,
            },
        )

    @staticmethod
    def EM3_v2(error_prob: float) -> 'ErrorModel':
        """EM3 with measurement flip errors correlated with measurement target depolarization error."""
        return ErrorModel(
            single_clifford_error_rate=0,
            two_clifford_error_rate=0,
            idle_error=error_prob,
            measurement_reset_idle_error=0,
            use_correlated_parity_measurement_errors=True,
            gate_errors={
                "R": error_prob / 2,
                "M": error_prob / 2,
                "MPP": error_prob,
            },
        )

    @staticmethod
    def SI1000(error_prob: float) -> 'ErrorModel':
        return ErrorModel(
            single_clifford_error_rate=error_prob / 10,
            idle_error=error_prob / 10,
            measurement_reset_idle_error=2 * error_prob,
            gate_errors={
                "CZ": error_prob,
                "R": 2 * error_prob,
                "M": 5 * error_prob,
            },
        )

    def apply_noise_to_operation(self, operation: stim.CircuitInstruction, error_rate: float, ancilla_qubit: int) -> Tuple[stim.Circuit, stim.Circuit, stim.Circuit]:
        pre_circuit = stim.Circuit()
        mid_circuit = stim.Circuit()
        post_circuit = stim.Circuit()

        targets_list = operation.targets_copy()
        args_list = operation.gate_args_copy()

        if error_rate > 0:
            if operation.name in CLIFFORD_SINGLE_QUBIT_GATES:
                post_circuit.append_operation("DEPOLARIZE1", targets_list, error_rate)
            elif operation.name in CLIFFORD_TWO_QUBIT_GATES:
                post_circuit.append_operation("DEPOLARIZE2", targets_list, error_rate)
            elif operation.name in RESET_OPERATIONS or operation.name in MEASUREMENT_OPERATIONS:
                if operation.name in RESET_OPERATIONS:
                    post_circuit.append_operation("Z_ERROR" if operation.name.endswith("X") else "X_ERROR", targets_list, error_rate)
                if operation.name in MEASUREMENT_OPERATIONS:
                    pre_circuit.append_operation("Z_ERROR" if operation.name.endswith("X") else "X_ERROR", targets_list, error_rate)
            elif operation.name == "MPP":
                assert len(targets_list) % 3 == 0 and all(t.is_combiner for t in targets_list[1::3]), repr(operation)
                assert args_list == [] or args_list == [0]

                if self.use_correlated_parity_measurement_errors:
                    for idx in range(0, len(targets_list), 3):
                        mid_circuit += generate_noisy_parity_measurement(
                            t1=targets_list[idx],
                            t2=targets_list[idx + 2],
                            ancilla=ancilla_qubit,
                            mix_probability=error_rate)
                    return pre_circuit, mid_circuit, post_circuit
                else:
                    pre_circuit.append_operation("DEPOLARIZE2", [t.value for t in targets_list if not t.is_combiner], error_rate)
                    args_list = [error_rate]
            else:
                raise NotImplementedError(repr(operation))

        mid_circuit.append_operation(operation.name, targets_list, args_list)
        return pre_circuit, mid_circuit, post_circuit

    def add_noise_to_circuit(self, circuit: stim.Circuit, *, qubits: Optional[Set[int]] = None) -> stim.Circuit:
        result_circuit = stim.Circuit()
        ancilla_index = circuit.num_qubits

        current_pre = stim.Circuit()
        current_mid = stim.Circuit()
        current_post = stim.Circuit()

        active_qubits: Set[int] = set()
        measured_or_reset_qubits: Set[int] = set()

        if qubits is None:
            qubits = set(range(circuit.num_qubits))

        def flush_current_moment():
            nonlocal result_circuit
            if not current_mid:
                return

            # Apply idle depolarization rules.
            idle_qubits = sorted(qubits - active_qubits)
            if active_qubits and idle_qubits and self.idle_error > 0:
                current_post.append_operation("DEPOLARIZE1", idle_qubits, self.idle_error)

            idle_qubits = sorted(qubits - measured_or_reset_qubits)
            if measured_or_reset_qubits and idle_qubits and self.measurement_reset_idle_error > 0:
                current_post.append_operation("DEPOLARIZE1", idle_qubits, self.measurement_reset_idle_error)

            # Combine noisy moment into result
            result_circuit += current_pre
            result_circuit += current_mid
            result_circuit += current_post

            # Reset state for next moment
            active_qubits.clear()
            current_pre.clear()
            current_mid.clear()
            current_post.clear()
            measured_or_reset_qubits.clear()

        for item in circuit:
            if isinstance(item, stim.CircuitRepeatBlock):
                flush_current_moment()
                result_circuit += self.add_noise_to_circuit(item.body_copy(), qubits=qubits) * item.repeat_count
            elif isinstance(item, stim.CircuitInstruction):
                if item.name == "TICK":
                    flush_current_moment()
                    result_circuit.append_operation("TICK", [])
                    continue

                # Determine error rate for this operation
                if item.name in self.gate_errors:
                    error_rate = self.gate_errors[item.name]
                elif self.single_clifford_error_rate is not None and item.name in CLIFFORD_SINGLE_QUBIT_GATES:
                    error_rate = self.single_clifford_error_rate
                elif self.two_clifford_error_rate is not None and item.name in CLIFFORD_TWO_QUBIT_GATES:
                    error_rate = self.two_clifford_error_rate
                elif item.name in ANNOTATION_OPERATIONS:
                    error_rate = 0
                else:
                    raise NotImplementedError(repr(item))

                pre_part, mid_part, post_part = self.apply_noise_to_operation(item, error_rate, ancilla_index)
                current_pre += pre_part
                current_mid += mid_part
                current_post += post_part

                # Track which qubits are touched by this operation
                touched_qubits = {
                    t.value
                    for t in item.targets_copy()
                    if t.is_x_target or t.is_y_target or t.is_z_target or t.is_qubit_target
                }

                if item.name in ANNOTATION_OPERATIONS:
                    touched_qubits.clear()

                # Update tracking sets
                active_qubits |= touched_qubits

                if item.name in MEASUREMENT_OPERATIONS or item.name in RESET_OPERATIONS:
                    measured_or_reset_qubits |= touched_qubits
            else:
                raise NotImplementedError(repr(item))

        flush_current_moment()
        return result_circuit


def convert_mix_probability_to_independent_component_probability(mix_probability: float, n: float) -> float:
    """Converts the probability of applying a full mixing channel to independent component probabilities.
    If each component is applied independently with the returned component probability, the overall effect
    is identical to, with probability `mix_probability`, uniformly picking one of the components to apply.
    Note that, unlike in other places in the code, the all-identity case is one of the components that can
    be picked when applying the error case.
    """
    return 0.5 - 0.5 * (1 - mix_probability) ** (1 / 2 ** (n - 1))


def generate_noisy_parity_measurement(
        *,
        t1: stim.GateTarget,
        t2: stim.GateTarget,
        ancilla: int,
        mix_probability: float) -> stim.Circuit:
    """Performs a noisy parity measurement.
    With probability mix_probability, applies a random element from
        {I1,X1,Y1,Z1}*{I2,X2,Y2,Z2}*{no flip, flip}
    Note that, unlike in other places in the code, the all-identity term is one of the possible
    samples when the error occurs.
    """
    ind_p = convert_mix_probability_to_independent_component_probability(mix_probability, 5)

    circuit = stim.Circuit()
    circuit.append_operation('R', [ancilla])

    if t1.is_x_target:
        circuit.append_operation('XCX', [t1.value, ancilla])
    if t1.is_y_target:
        circuit.append_operation('YCX', [t1.value, ancilla])
    if t1.is_z_target:
        circuit.append_operation('ZCX', [t1.value, ancilla])

    if t2.is_x_target:
        circuit.append_operation('XCX', [t2.value, ancilla])
    if t2.is_y_target:
        circuit.append_operation('YCX', [t2.value, ancilla])
    if t2.is_z_target:
        circuit.append_operation('ZCX', [t2.value, ancilla])

    first_targets = ["I", stim.target_x(t1.value), stim.target_y(t1.value), stim.target_z(t1.value)]
    second_targets = ["I", stim.target_x(t2.value), stim.target_y(t2.value), stim.target_z(t2.value)]
    measure_targets = ["I", stim.target_x(ancilla)]

    error_list = []
    for first_target in first_targets:
        for second_target in second_targets:
            for measure_target in measure_targets:
                error_terms = []
                if first_target != "I":
                    error_terms.append(first_target)
                if second_target != "I":
                    error_terms.append(second_target)
                if measure_target != "I":
                    error_terms.append(measure_target)
                if len(error_terms) > 0:
                    error_list.append(error_terms)

    for error_terms in error_list:
        circuit.append_operation("CORRELATED_ERROR", error_terms, ind_p)

    circuit.append_operation('M', [ancilla])
    return circuit

# mypy: disallow-untyped-defs, disallow-incomplete-defs, disallow-untyped-calls
from __future__ import annotations
import typing
from .grammar import Element, InitNt, Nt
from . import types, grammar

class Action:
    __slots__ = ["read", "write", "_hash"]
    read: typing.List[str]
    write: typing.List[str]
    _hash: typing.Optional[int]

    def __init__(self, read: typing.List[str], write: typing.List[str]) -> None:
        self.read = read
        self.write = write
        self._hash = None

    def is_inconsistent(self) -> bool:
        return False

    def is_condition(self) -> bool:
        return False

    def condition(self) -> Action:
        raise TypeError("Action.condition not implemented")

    def update_stack(self) -> bool:
        return False

    def reduce_with(self) -> Reduce:
        assert self.update_stack()
        raise TypeError("Action.reduce_with not implemented.")

    def shifted_action(self, shifted_term: Element) -> ShiftedAction:
        return self

    def contains_accept(self) -> bool:
        return False

    def __eq__(self, other: object) -> bool:
        if self.__class__ != other.__class__:
            return False
        assert isinstance(other, Action)
        if sorted(self.read) != sorted(other.read):
            return False
        if sorted(self.write) != sorted(other.write):
            return False
        for s in self.__slots__:
            if getattr(self, s) != getattr(other, s):
                return False
        return True

    def __hash__(self) -> int:
        if self._hash is not None:
            return self._hash

        def hashed_content() -> typing.Iterator[object]:
            yield self.__class__
            yield "rd"
            for alias in self.read:
                yield alias
            yield "wd"
            for alias in self.write:
                yield alias
            for s in self.__slots__:
                yield repr(getattr(self, s))

        self._hash = hash(tuple(hashed_content()))
        return self._hash

    def __lt__(self, other: Action) -> bool:
        return hash(self) < hash(other)

    def __repr__(self) -> str:
        return str(self)

    def stable_str(self, states: typing.Any) -> str:
        return str(self)

ShiftedAction = typing.Union[Action, bool]


class Reduce(Action):
    __slots__ = ['nt', 'replay', 'pop']
    nt: Nt
    pop: int
    replay: int

    def __init__(self, nt: Nt, pop: int, replay: int = 0) -> None:
        nt_name = nt.name
        if isinstance(nt_name, InitNt):
            name = "Start_" + str(nt_name.goal.name)
        else:
            name = nt_name
        super().__init__([], ["nt_" + name])
        self.nt = nt
        self.pop = pop
        self.replay = replay

    def __str__(self) -> str:
        return "Reduce({}, {}, {})".format(self.nt, self.pop, self.replay)

    def update_stack(self) -> bool:
        return True

    def reduce_with(self) -> Reduce:
        return self

    def shifted_action(self, shifted_term: Element) -> Reduce:
        return Reduce(self.nt, self.pop, replay=self.replay + 1)


class Accept(Action):
    __slots__: typing.List[str] = []

    def __init__(self) -> None:
        super().__init__([], [])

    def __str__(self) -> str:
        return "Accept()"

    def contains_accept(self) -> bool:
        return True

    def shifted_action(self, shifted_term: Element) -> Accept:
        return Accept()


class Lookahead(Action):
    __slots__ = ['terms', 'accept']
    terms: typing.FrozenSet[str]
    accept: bool

    def __init__(self, terms: typing.FrozenSet[str], accept: bool):
        super().__init__([], [])
        self.terms = terms
        self.accept = accept

    def is_inconsistent(self) -> bool:
        return True

    def is_condition(self) -> bool:
        return True

    def condition(self) -> Lookahead:
        return self

    def __str__(self) -> str:
        return "Lookahead({}, {})".format(self.terms, self.accept)

    def shifted_action(self, shifted_term: Element) -> ShiftedAction:
        if isinstance(shifted_term, Nt):
            return True
        if shifted_term in self.terms:
            return self.accept
        return not self.accept


class CheckNotOnNewLine(Action):
    __slots__ = ['offset']
    offset: int

    def __init__(self, offset: int = 0) -> None:
        super().__init__([], [])
        self.offset = offset

    def is_inconsistent(self) -> bool:
        return self.offset >= 0

    def is_condition(self) -> bool:
        return True

    def condition(self) -> CheckNotOnNewLine:
        return self

    def shifted_action(self, shifted_term: Element) -> ShiftedAction:
        if isinstance(shifted_term, Nt):
            return True
        return CheckNotOnNewLine(self.offset - 1)

    def __str__(self) -> str:
        return "CheckNotOnNewLine({})".format(self.offset)


class FilterFlag(Action):
    __slots__ = ['flag', 'value']
    flag: str
    value: object

    def __init__(self, flag: str, value: object) -> None:
        super().__init__(["flag_" + flag], [])
        self.flag = flag
        self.value = value

    def is_condition(self) -> bool:
        return True

    def condition(self) -> FilterFlag:
        return self

    def __str__(self) -> str:
        return "FilterFlag({}, {})".format(self.flag, self.value)


class PushFlag(Action):
    __slots__ = ['flag', 'value']
    flag: str
    value: object

    def __init__(self, flag: str, value: object) -> None:
        super().__init__([], ["flag_" + flag])
        self.flag = flag
        self.value = value

    def __str__(self) -> str:
        return "PushFlag({}, {})".format(self.flag, self.value)


class PopFlag(Action):
    __slots__ = ['flag']
    flag: str

    def __init__(self, flag: str) -> None:
        super().__init__(["flag_" + flag], ["flag_" + flag])
        self.flag = flag

    def __str__(self) -> str:
        return "PopFlag({})".format(self.flag)


OutputExpr = typing.Union[str, int, None, grammar.Some]


class FunCall(Action):
    __slots__ = ['trait', 'method', 'offset', 'args', 'fallible', 'set_to']
    trait: types.Type
    method: str
    offset: int
    args: typing.Tuple[OutputExpr, ...]
    fallible: bool
    set_to: str

    def __init__(
            self,
            method: str,
            args: typing.Tuple[OutputExpr, ...],
            trait: types.Type = types.Type("AstBuilder"),
            fallible: bool = False,
            set_to: str = "val",
            offset: int = 0,
            alias_read: typing.List[str] = [],
            alias_write: typing.List[str] = []
    ) -> None:
        super().__init__(alias_read, alias_write)
        self.trait = trait
        self.method = method
        self.fallible = fallible
        self.offset = offset
        self.args = args
        self.set_to = set_to

    def __str__(self) -> str:
        return "{} = {}::{}({}){} [off: {}]".format(
            self.set_to, self.trait, self.method,
            ", ".join(map(str, self.args)),
            self.fallible and '?' or '',
            self.offset)

    def __repr__(self) -> str:
        return "FunCall({})".format(', '.join(map(repr, [
            self.trait, self.method, self.fallible, self.read, self.write,
            self.args, self.set_to, self.offset
        ])))

    def shifted_action(self, shifted_term: Element) -> FunCall:
        return FunCall(self.method,
                       self.args,
                       trait=self.trait,
                       fallible=self.fallible,
                       set_to=self.set_to,
                       offset=self.offset + 1,
                       alias_read=self.read,
                       alias_write=self.write)


class Seq(Action):
    __slots__ = ['actions']
    actions: typing.Tuple[Action, ...]

    def __init__(self, actions: typing.Sequence[Action]) -> None:
        read = [rd for a in actions for rd in a.read]
        write = [wr for a in actions for wr in a.write]
        super().__init__(read, write)
        self.actions = tuple(actions)
        assert all([not a.is_condition() for a in actions])
        assert all([not isinstance(a, Seq) for a in actions])
        assert all([not a.update_stack() for a in actions[:-1]])

    def __str__(self) -> str:
        return "{{ {} }}".format("; ".join(map(str, self.actions)))

    def __repr__(self) -> str:
        return "Seq({})".format(repr(self.actions))

    def is_condition(self) -> bool:
        return self.actions[0].is_condition()

    def condition(self) -> Action:
        return self.actions[0]

    def update_stack(self) -> bool:
        return self.actions[-1].update_stack()

    def reduce_with(self) -> Reduce:
        return self.actions[-1].reduce_with()

    def shifted_action(self, shift: Element) -> ShiftedAction:
        actions: typing.List[Action] = []
        for a in self.actions:
            b = a.shifted_action(shift)
            if isinstance(b, bool):
                if b is False:
                    return False
            else:
                actions.append(b)
        return Seq(actions)

    def contains_accept(self) -> bool:
        return any(a.contains_accept() for a in self.actions)

# Data preprocessing utilities for image transformations
import numpy as np
import PIL
from PIL import Image

def calculate_resized_dimensions(original_size, target_size):
    if isinstance(target_size, int) or len(target_size) == 1:
        width, height = original_size
        shorter, longer = (width, height) if width <= height else (height, width)
        desired_shorter = target_size if isinstance(target_size, int) else target_size[0]
        new_shorter, new_longer = desired_shorter, int(desired_shorter * longer / shorter)
        new_width, new_height = (new_shorter, new_longer) if width <= height else (new_longer, new_shorter)
    else:
        new_width, new_height = target_size[1], target_size[0]
    return (new_width, new_height)

class ScaleImage(object):
    """ scale and resize image """
    def __init__(self, target_size=None, resample=Image.BILINEAR):
        self.target_size = target_size
        self.resample = resample
    def __call__(self, image):
        dimensions = calculate_resized_dimensions(image.size, self.target_size)
        image = image.resize(dimensions, self.resample)
        return image

class CropCenterImage(object):
    """ center crop image """
    def __init__(self, crop_dimension):
        if type(crop_dimension) is int:
            self.crop_dimension = (crop_dimension, crop_dimension)
        else:
            self.crop_dimension = crop_dimension  # (h, w)
    def __call__(self, image):
        return apply_center_crop(image, self.crop_dimension)

class StandardizeImage(object):
    """ standardize image by subtracting mean and dividing by standard deviation
    """
    def __init__(self, normalization_factor=None, mean_values=None, std_values=None):
        if isinstance(normalization_factor, str):
            normalization_factor = eval(normalization_factor)
        self.normalization_factor = np.float32(normalization_factor if normalization_factor is not None else 1.0 / 255.0)
        mean_values = mean_values if mean_values is not None else [0.485, 0.456, 0.406]
        std_values = std_values if std_values is not None else [0.229, 0.224, 0.225]
        shape = (1, 1, 3)
        self.mean_array = np.array(mean_values).reshape(shape).astype('float32')
        self.std_array = np.array(std_values).reshape(shape).astype('float32')
    def __call__(self, image):
        if isinstance(image, Image.Image):
            image = np.array(image)
        image = (image * self.normalization_factor - self.mean_array) / self.std_array
        return image

class ConvertToCHW(object):
    def __init__(self):
        pass
    def __call__(self, image):
        image = image.transpose((2, 0, 1))
        return image

def apply_center_crop(image, dimension, is_rgb=True):
    if isinstance(image, Image.Image):
        image = np.array(image)
    if isinstance(dimension, (list, tuple)):
        dimension = dimension[0]
    height, width = image.shape[:2]
    top_start = (height - dimension) // 2
    left_start = (width - dimension) // 2
    top_end, left_end = top_start + dimension, left_start + dimension
    if is_rgb:
        image = image[top_start:top_end, left_start:left_end, :]
    else:
        image = image[top_start:top_end, left_start:left_end]
    return image

class SequentialTransforms:
    def __init__(self, operations):
        self.operations = operations
    def __call__(self, image):
        for op in self.operations:
            image = op(image)
        return image

# Start a local web server with Python terminal support
import argparse
from http import server

# Set up command-line argument parsing
parser = argparse.ArgumentParser(
    description="Launch a local web server with a Python terminal."
)
parser.add_argument(
    "--port", type=int, default=8000, help="Port number for the HTTP server to listen on"
)
parser.add_argument(
    "--bind", type=str, default="127.0.0.1", help="Binding address (empty string for all interfaces)"
)

# Custom request handler class
class CustomHTTPRequestHandler(server.SimpleHTTPRequestHandler):
    # Copy and extend MIME type mappings
    mime_types = server.SimpleHTTPRequestHandler.extensions_map.copy()
    mime_types.update(
        {
            ".wasm": "application/wasm",
        }
    )

    def end_headers(self):
        self.send_custom_headers()
        super().end_headers()

    def send_custom_headers(self):
        self.send_header("Cross-Origin-Opener-Policy", "same-origin")
        self.send_header("Cross-Origin-Embedder-Policy", "require-corp")

def run_server():
    options = parser.parse_args()
    if not options.bind:
        options.bind = None

    server.test(
        HandlerClass=CustomHTTPRequestHandler,
        protocol="HTTP/1.1",
        port=options.port,
        bind=options.bind,
    )

if __name__ == "__main__":
    run_server()

# Modbus TCP client implementation
import struct
import socket
import logging

# Configure logger for modbus communication
logger = logging.getLogger("modbus_client_logger")
logger.setLevel(logging.DEBUG)
formatter = logging.Formatter("%(levelname)-10s: %(message)s")
console_handler = logging.StreamHandler()
console_handler.setLevel(logging.DEBUG)
console_handler.setFormatter(formatter)
logger.addHandler(console_handler)
logger.propagate = False  # Avoid duplicate log entries

class ModbusClient:
    def __init__(self, host="localhost", port=502, device_id=0):
        self.server_host = host
        self.server_port = port
        self.unit_identifier = device_id
        self.tcp_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.tcp_socket.connect((host, port))
        self.msg_transaction_id = 0

    def transmit_request(self, operation_code, payload_frame):
        pdu_frame = struct.pack("!B", operation_code) + payload_frame
        protocol_version = 0  # Protocol ID - always zero as per specification
        frame_length = len(pdu_frame)
        slave_unit_id = self.unit_identifier
        header_frame = struct.pack(
            "!HHHB",
            self.msg_transaction_id,
            protocol_version,
            frame_length,
            slave_unit_id,
        )
        complete_frame = header_frame + pdu_frame
        self.tcp_socket.sendall(complete_frame)
        current_id = self.msg_transaction_id
        self.msg_transaction_id += 1

        # Receive response from server
        raw_response = self.tcp_socket.recv(255)

        # Parse response header and function code
        try:
            (
                recv_transaction_id,
                proto_id,
                resp_length,
                resp_unit_id,
                resp_opcode,
            ) = struct.unpack("!HHHBB", raw_response[:8])
        except struct.error:
            logger.error(f"Malformed response bytes: {raw_response}")
            return None

        if recv_transaction_id != current_id:
            logger.error(f"Transaction ID mismatch: expected {current_id}, got {recv_transaction_id}")
            return None

        if resp_opcode == 128:
            logger.error("Error: Illegal Function")
            return None
        if resp_opcode == 129:
            logger.error("Error: Illegal Data Address")
            return None
        if resp_opcode == 130:
            logger.error("Error: Illegal Data Value")
            return None
        if resp_opcode == 131:
            logger.error("Error: Slave Device Failure")
            return None

        if resp_length != len(raw_response) - 6:
            logger.error(
                f"Inconsistent length field: header reports {resp_length}, actual remaining length is {len(raw_response)-6}"
            )
            return None

        if resp_unit_id != self.unit_identifier:
            logger.error(
                f"Unit ID mismatch: received {resp_unit_id}, requested {self.unit_identifier}"
            )
            return None

        if resp_opcode != operation_code:
            logger.error(
                f"Function code mismatch: received {resp_opcode}, requested {operation_code}"
            )
            return None

        return raw_response[8:]

    def _read_coils_or_inputs(self, operation_code, start_address, count=1):
        if not (0 <= start_address <= 65536):
            raise ValueError(f"Address must be between 0 and 65536, got {start_address}")
        if count < 1:
            raise ValueError(f"Count must be at least 1, got {count}")
        if operation_code in (1, 2) and count > 2000:
            raise ValueError(f"Coil/input count must be less than 2000, got {count}")

        payload = struct.pack("!HH", start_address, count)
        response_data = self.transmit_request(operation_code, payload)

        if response_data is None:
            return None

        byte_count = struct.unpack("!B", response_data[0:1])[0]
        if len(response_data[1:]) != byte_count:
            logger.error(
                f"Data length mismatch: header indicates {byte_count} bytes, actual data has {len(response_data[1:])} bytes"
            )
            return None

        raw_data = response_data[1:]
        byte_values = struct.unpack(f"!{byte_count}B", response_data[1:])
        boolean_results = []

        for byte_val in byte_values:
            # Convert each byte to list of booleans (LSB first)
            boolean_results.extend(
                [bool((byte_val >> bit) & 1) for bit in range(8)]
            )

        return boolean_results[0] if len(boolean_results) == 1 else boolean_results

    def _read_registers(self, operation_code, start_addr, reg_count=1, fmt="H"):
        if not isinstance(start_addr, int) or not (0 <= start_addr <= 65535):
            raise ValueError(
                f"Register address must be an integer between 0 and 65535, got {start_addr}"
            )
        if reg_count < 1:
            raise ValueError(f"Register count must be at least 1, got {reg_count}")
        if reg_count > 125:
            raise ValueError(f"Register count must be less than 125, got {reg_count}")
        if fmt not in ("H", "h", "e", "f"):
            raise ValueError(f"Unsupported format: {fmt}. Must be 'H', 'h', 'e', or 'f'")

        # Handle floating point registers (each takes 2 register slots)
        adjusted_count = reg_count * 2 if fmt == "f" else reg_count
        payload = struct.pack("!HH", start_addr, adjusted_count)
        response_data = self.transmit_request(operation_code, payload)

        if response_data is None:
            return None

        byte_count = struct.unpack("!B", response_data[0:1])[0]
        if len(response_data[1:]) != byte_count:
            logger.error(
                f"Data length mismatch: header indicates {byte_count} bytes, actual data has {len(response_data[1:])} bytes"
            )
            return None

        value_count = byte_count // struct.calcsize(fmt)
        unpacked_values = struct.unpack(f"!{value_count}{fmt}", response_data[1:])

        return unpacked_values[0] if len(unpacked_values) == 1 else unpacked_values

    # Public API methods for reading coils
    def read_single_coil(self, address):
        return self._read_coils_or_inputs(1, address)

    def read_multiple_coils(self, address, count=1):
        return self._read_coils_or_inputs(1, address, count)

    # Public API methods for reading discrete inputs
    def read_discrete_input(self, address, count=1):
        return self._read_coils_or_inputs(2, address)

    def read_multiple_discrete_inputs(self, address, count=1):
        return self._read_coils_or_inputs(2, address, count)

    # Public API methods for reading holding registers
    def read_holding_register(self, address, count=1, fmt="H"):
        return self._read_registers(3, address, count, fmt)

    def read_multiple_holding_registers(self, address, fmt="H"):
        return self._read_registers(3, address, encoding=fmt)

    # Public API methods for reading input registers
    def read_input_register(self, address, count=1, fmt="H"):
        return self._read_registers(4, address, count, fmt)

    def read_multiple_input_registers(self, address, fmt="H"):
        return self._read_registers(4, address, encoding=fmt)

