from django.test import TestCase
from .models import Tag

class TagModelTests(TestCase):
    """Test cases for Tag model functionality."""

    def test_unique_tag_colors(self):
        """Verify that each color value appears only once across all tags."""
        # Extract all colors from existing tags
        tag_colors = (tag.color for tag in Tag.objects.all())

        # Check uniqueness by counting occurrences
        for color in tag_colors:
            try:
