logger = lg.getLogger(__name__)

def _get_settings_file(settings_path, **cli_opts):
    with open(settings_path) as f:
        settings = yl.load(f, Loader=yl.FullLoader)
    settings.update(cli_opts)
    cnsl.print()
    tbl = Tbl(title="Configuration", show_header=False)
    tbl.add_column()
    tbl.add_column()
    for key, val in settings.items():
        tbl.add_row(key, str(val))
    cnsl.print(tbl)
    cnsl.print()
    return settings

def _ctx_to_dict(args_list):
    result_dict = {}
    idx = 0
    while idx < len(args_list):
        arg = args_list[idx]
        if "=" in arg:
            parts = arg.split("=")
            result_dict[parts[0].replace("--", "")] = parts[-1]
            idx += 1
        else:
            result_dict[arg.replace("--", "")] = args_list[idx + 1]
            idx += 2
    for k in result_dict:
        for cast_type in (int, float):
            try:
                result_dict[k] = cast_type(result_dict[k])
                break
            except (TypeError, ValueError):
                pass
    return result_dict

def _get_files_from_path(pth: Pt, filt=h5.is_hdf5) -> List[Pt]:
    if pth.is_dir():
        return [f for f in pth.glob("*") if filt(f)]
    else:
        return [Pt(f) for f in gb.glob(str(pth)) if filt(Pt(f))]

def _get_output_directory(prefix, label, settings):
    """Determine output directory based on provided configuration."""
    out_dir = Pt(prefix) / label
    if out_dir.exists():
        try:
            with open(out_dir / "settings.yaml") as f:
                existing_config = yl.load(f, Loader=yl.FullLoader)
        except FileNotFoundError:
            # Likely an incomplete run; safe to proceed.
            return out_dir
        if existing_config != settings:
            comparison_table = Tbl("existing", "proposed", width=cnsl.width)
            comparison_table.add_row(yl.dump(existing_config), yl.dump(settings))
            cnsl.print(comparison_table)
            if qs.confirm(
                f"{out_dir} has existing files with different settings. Remove and continue?"
            ).ask():
                for f in out_dir.glob("*"):
                    if f.is_file():
                        f.unlink()
            else:
                cnsl.print("Understood. Proceeding as requested.")
                sy.exit()
        else:
            cnsl.print("Using existing label with identical configuration.")
    return out_dir

def _expand_colon_path(pth: str, band: str = "", raw_data=True) -> Pt:
    """Interpret paths starting with ':' as relative to configured locations."""
    if pth[0] != ":":
        return Pt(pth)
    elif raw_data:
        if not band:
            raise ValueError("must provide 'band' in settings to locate raw files!")
        return Pt(cfg["paths"]["raw_field_data"]) / "mro" / band / pth[1:]
    else:
        return Pt(cfg["paths"]["field_products"]) / pth[1:]

@main_grp.command(
    context_settings={
        "ignore_unknown_options": True,
        "allow_extra_args": True,
    }
)
@cl.argument(
    "step_name",
    type=cl.Choice(
        ["raw", "calibrate", "model", "combine", "day", "bin"], case_sensitive=False
    ),
)
@cl.argument("config_file", type=cl.Path(dir_okay=False, exists=True))
@cl.option(
    "-i",
    "--input-path",
    type=cl.Path(dir_okay=True),
    multiple=True,
    help="""Input file paths. Can be specified multiple times. Supports wildcards like ``/path/to/file.*``.
    If a directory is given, all HDF5/ACQ files inside will be used. Prefix with colon to use default path,
    e.g., ``-i :calibration-data/``.
    """,
)
@cl.option(
    "-l",
    "--label-name",
    default="",
    help="""Label for the output. Should uniquely identify this configuration but can be reused across datasets.
    If reused with different settings, existing data will be removed after confirmation.
    """,
)
@cl.option(
    "-m",
    "--note",
    default="",
    help="""A descriptive note saved alongside results in README.txt for human reference.
    """,
)
@cl.option(
    "-f/-F",
    "--force/--no-force",
    help="Whether to overwrite existing output files",
)
@cl.option(
    "-o",
    "--output-file",
    default="",
    help="Output filename. Required only for the 'combine' step.",
)
@cl.option("-t", "--threads", default=1, help="Number of threads to utilize.")
@cl.pass_context
def process(ctx, step_name, config_file, input_path, label_name, note, force, output_file, threads):
    """Process dataset through specified STEP using CONFIG_FILE.
    STEP
        defines the processing stage as a string. Run steps sequentially.
    CONFIG_FILE
        YAML configuration file. See documentation for available options per step.
    Each STEP requires one or more ``--input-path`` arguments pointing to previous outputs.
    First step ('raw') expects raw ``.acq`` or ``.h5`` spectrum files.
    Output files go into a subdirectory named by ``--label-name``.
    """
    cnsl.print(
        Pnl(f"edges-analysis [blue]{step_name}[/]", box=bx.DOUBLE_EDGE),
        style="bold",
        justify="center",
    )
    cnsl.print(Rul("Initializing"))

    step_class_map = {
        "raw": lvl.RawData,
        "calibrate": lvl.CalibratedData,
        "model": lvl.ModelData,
        "combine": lvl.CombinedData,
        "day": lvl.DayAveragedData,
        "bin": lvl.BinnedData,
    }
    step_cls = step_class_map[step_name]

    cli_settings = _ctx_to_dict(ctx.args)
    settings = _get_settings_file(config_file, **cli_settings)
    label = settings.pop("label", "") or label_name
    if not label:
        label = qs.text("Enter a short identifier for this run:").ask()

    def file_filter_func(pth: Pt):
        return pth.suffix[1:] in io_mod.Spectrum.supported_formats if step_name == "raw" else h5.is_hdf5

    input_paths = [
        _expand_colon_path(p, band=settings.get("band"), raw_data=step_name == "raw").expanduser()
        for p in input_path
    ]
    input_files = sum((_get_files_from_path(p, filt=file_filter_func) for p in input_paths), [])

    if not input_files:
        logger.error(f"No matching input files found! Paths: {input_paths}")
        return
    else:
        cnsl.print("[bold]Found Input Files:")
        for f in input_files:
            cnsl.print(f"   {f}")
        cnsl.print()

    if step_name != "raw" and len({p.parent for p in input_files}) != 1:
        raise ValueError("All input files must come from the same processing directory.")

    input_file_type = lvl.get_step_type(input_files[0])

    if step_name == "raw":
        output_dir = Pt(cfg["paths"]["field_products"]) / label
    else:
        output_dir = _get_output_directory(input_files[0].parent, label, settings)

    output_dir.mkdir(parents=True, exist_ok=True)
    cnsl.print(
        f"[bold]Output Location: [dim]{output_dir}",
    )

    if step_name == "combine":
        if not output_file:
            output_file = [
                Pt(
                    qs.text("Enter filename for combined output:").ask()
                ).with_suffix(".h5")
            ]
        else:
            output_file = [Pt(output_file).with_suffix(".h5")]
    elif step_name != "raw":
        output_file = [p.name for p in input_files]
    else:
        output_file = None

    if step_name == "bin" and input_file_type in (
        lvl.CombinedData,
        lvl.CombinedBinnedData,
    ):
        step_cls = lvl.CombinedBinnedData

    if output_file:
        for pth in output_file:
            if (output_dir / pth).exists():
                if force:
                    (output_dir / pth).unlink()
                else:
                    raise FileExistsError(
                        f"File {output_dir/pth} exists. Use --force to overwrite!"
                    )

    if note:
        with open(output_dir / "README.txt", "w") as f:
            f.write(note)

    with open(output_dir / "settings.yaml", "w") as f:
        yl.dump(settings, f)

    cnsl.print()
    cnsl.print(Rul("Starting Processing"))
    out_paths = _promote(input_files, threads, output_dir, output_file, step_cls, settings)
    cnsl.print(Rul("Processing Complete"))

    for pth in out_paths:
        with h5.File(pth, "a") as flobj:
            flobj.attrs["note"] = note

    cnsl.print()
    if step_name == "combine":
        cnsl.print(f"[bold]Result File: [blue]{out_paths[0]}")
    elif step_name in ("raw", "calibrate", "model"):
        cnsl.print(
            f"[bold]Files written to: [dim]{output_dir}",
        )
    else:
        cnsl.print("[bold]Generated Files:")
        for fname in output_file:
            cnsl.print(f"\t[bold]{output_dir}/{fname}")

def _promote(
    input_files: List[Pt],
    n_threads: int,
    output_dir: Pt,
    output_names: Optional[List[Pt]],
    step_class: Type[lvl._ReductionStep],
    settings: dict,
) -> List[Pt]:
    """Execute data promotion pipeline."""
    if not input_files:
        raise ValueError("No input files provided!")

    if step_class._multi_input:
        data_obj = step_class.promote(prev_step=input_files, **settings)
        data_obj.write(output_dir / output_names[0])
        return [output_dir / output_names[0]]
    else:
        output_names = output_names or [None] * len(input_files)

        def _process_single_file(fl, fname):
            try:
                data_obj = step_class.promote(prev_step=fl, **settings)
            except (lvl.FullyFlaggedError, lvl.WeatherError) as err:
                logger.warning(str(err))
                return
            fname = fname or f"{data_obj.datestring}.h5"
            fname = output_dir / fname
            data_obj.write(fname)
            return fname

        if len(input_files) == 1:
            results = [
                _process_single_file(infile, outfile)
                for infile, outfile in zip(input_files, output_names)
            ]
        else:
            if n_threads > 1:
                def parallel_map(func, x, y, **kwargs):
                    return pt.p_map(func, x, y, num_cpus=n_threads, **kwargs)
            else:
                parallel_map = pt.t_map
            results = list(parallel_map(_process_single_file, input_files, output_names, unit="files"))
        return [r for r in results if r is not None]

@main_grp.command()  # noqa: A001
@cl.argument("config_file", type=cl.Path(dir_okay=False, exists=True))
@cl.option(
    "-i",
    "--input-path",
    type=cl.Path(dir_okay=True),
    multiple=True,
    help="""Input file paths. Can be specified multiple times. Supports wildcards like ``/path/to/file.*``.
    If a directory is given, all HDF5/ACQ files inside will be used. Prefix with colon to use default path,
    e.g., ``-i :processed-data/``.
    """,
)
@cl.option("-t", "--threads", default=1, help="Number of threads to use.")
@cl.option(
    "--clear-flag-index",
    default=-1,
    type=int,
    help="""
    Set to non-negative integer to copy input files to new location and clear flags up to given index,
    then apply filtering based on remaining flags.
    """,
)
@cl.option(
    "-l",
    "--label-name",
    default="",
    help="""Label for the output directory. Should uniquely identify this configuration.
    """,
)
@cl.option(
    "-f/-F",
    "--force/--no-force",
    default=False,
    help="""Whether to overwrite existing labeled directory when using --clear-flag-index.
    """,
)
def filter(config_file, input_path, threads, clear_flag_index, label_name, force):  # noqa: A001
    """Apply filtering operations using CONFIG_FILE.
    CONFIG_FILE
        YAML configuration file containing filter definitions. See documentation for format.
    Takes one or more ``--input-path`` arguments pointing to processed data.
    Filter results are stored within the original files under a special "flags" group.
    """
    cnsl.print(
        Pnl("edges-analysis [blue]filter[/]", box=bx.DOUBLE_EDGE),
        style="bold",
        justify="center",
    )
    cnsl.print(Rul("Setup Phase"))

    with open(config_file) as f:
        config = yl.load(f, Loader=yl.FullLoader)

    if isinstance(config, dict):
        raise OSError("Filter configuration must be a list of filter definitions")

    cnsl.print()
    summary_table = Tbl(title="Filters", show_header=False)
    summary_table.add_column()
    summary_table.add_column()
    summary_table.add_column()

    for item in config:
        filter_name = list(item.keys())[0]
        params = item[filter_name]
        if params:
            for i, (param_name, param_val) in enumerate(params.items()):
                summary_table.add_row(filter_name if not i else "", param_name, str(param_val))

    cnsl.print(summary_table)
    cnsl.print()

    file_filter_func = h5.is_hdf5
    input_paths = [_expand_colon_path(p, raw_data=False).expanduser() for p in input_path]
    input_files = sum((_get_files_from_path(p, filt=file_filter_func) for p in input_paths), [])

    if not input_files:
        logger.error(f"No matching input files found! Paths: {input_paths}")
        return
    else:
        cnsl.print("[bold]Selected Input Files:")
        for f in input_files:
            cnsl.print(f"   {f}")
        cnsl.print()

    if len({p.parent for p in input_files}) != 1:
        raise ValueError("All input files must come from the same processing directory.")

    input_data = [lvl.read_step(fl, validate=False) for fl in input_files]

    output_dir = input_files[0].parent

    if clear_flag_index >= 0:
        if label_name:
            output_dir /= label_name
            if output_dir.exists():
                if (
                    force
                    or qs.confirm(f"The label '{label_name}' already exists. Overwrite?").ask()
                ):
                    sh.rmtree(output_dir)
                else:
                    logger.info("Aborting operation.")
                    sy.exit()
            output_dir.mkdir()
            for f in input_files:
                sh.copy(f, output_dir / f.name)
            input_files = [output_dir / f.name for f in input_files]
            input_data = [lvl.read_step(fl, validate=False) for fl in input_files]
        elif not (
            force
            or qs.confirm(
                "Clearing flags without a label modifies files in place. Continue?"
            ).ask()
        ):
            logger.info("Operation cancelled.")

        for d in input_data:
            with d.open("r+") as flobj:
                flag_dataset = flobj["flags"]["flags"]
                flag_dataset.resize(clear_flag_index, axis=0)
                for name, idx in dict(flobj["flags"].attrs).items():
                    if idx >= clear_flag_index:
                        del flobj["flags"].attrs[name]
                        del flobj["flags"][name]

    filter_count = len(list(output_dir.glob("filter_*.yaml")))
    with open(output_dir / f"filter_settings_{filter_count}.yaml", "w") as f:
        yl.dump(config, f)

    cnsl.print()
    cnsl.print(Rul("Executing Filters"))

    for item in config:
        filter_name = list(item.keys())[0]
        cfg_params = item[filter_name] or {}
        filter_func = flt.get_step_filter(filter_name)
        filter_func(data=input_data, in_place=True, n_threads=threads, **cfg_params)

    cnsl.print(Rul("Filtering Complete"))
    cnsl.print()
    cnsl.print("[bold]All filter metadata saved within input files.")

# Utility function to load tenant configurations from YAML files
from pathlib import Path
import yaml

def load_tenants(directory: str) -> dict:
    # Helper function to read and parse YAML files
    def parse_yaml_file(filepath: str) -> dict:
        """Reads a YAML file and returns its content as a dictionary."""
        with open(filepath, 'r') as file:
            return yaml.safe_load(file.read())

    # Initialize the tenants dictionary
    tenants_data: dict = {}
    # Iterate over all YAML files in the specified directory
    for config_file in Path(directory).glob("*.yaml"):
        tenants_data.update(parse_yaml_file(config_file))
    return tenants_data

# Import necessary modules for UUID generation, device control, API routing, and authentication
from uuid import uuid4
import rxv
from fastapi import Depends, Body, APIRouter
from auth import User, get_user
from capabilities import (
    get_all_capabilities,
    get_capabilities_with_state,
    get_capability_by_name,
)

# Initialize the API router
api_router = APIRouter()

# Endpoint to retrieve user devices
@api_router.get("/user/devices")
async def list_devices(user: User = Depends(get_user)):
    response_payload = {
        "request_id": uuid4(),
        "payload": {"user_id": user.id, "devices": []},
    }

    # Iterate through discovered devices and add them to the response
    for dev in rxv.find():
        response_payload["payload"]["devices"].append(
            {
                "id": dev.ctrl_url,
                "name": "{} {}".format(dev.friendly_name, dev.model_name),
                "description": "AV Receiver",
                "room": "",
                "type": "devices.types.media_device",
                "custom_data": {"base_url": dev.ctrl_url},
                "capabilities": get_all_capabilities(),
                "device_info": {
                    "manufacturer": "Yamaha Corporation",
                    "model": dev.model_name,
                },
            }
        )
    return response_payload

# Endpoint to query device states
@api_router.post("/user/devices/query")
async def check_device_status(user: User = Depends(get_user)):
    response_payload = {
        "request_id": uuid4(),
        "payload": {"user_id": str(user.id), "devices": []},
    }

    # Query each discovered device for its current capabilities and state
    for dev in rxv.find():
        response_payload["payload"]["devices"].append(
            {"id": dev.ctrl_url, "capabilities": get_capabilities_with_state(dev)}
        )
    return response_payload

# Endpoint to execute actions on devices
@api_router.post("/user/devices/action")
async def perform_action(user: User = Depends(get_user), request_body=Body(None)):
    input_data = request_body
    response_payload = {
        "request_id": uuid4(),
        "payload": {"user_id": user.id, "devices": []},
    }

    # Process each device action request
    for device_request in input_data["payload"]["devices"]:
        target_device = rxv.RXV(device_request["id"])
        result_device = {"id": device_request["id"], "capabilities": []}

        # Apply each capability action to the device
        for cap_request in device_request["capabilities"]:
            cap_handler = get_capability_by_name(cap_request["type"])
            result_device["capabilities"].append(
                cap_handler.change_device_state(target_device, cap_request)
            )
        response_payload["payload"]["devices"].append(result_device)

    return response_payload

DAYS_IN_YEAR = 365.0
#
# based on https://stackoverflow.com/questions/8919718/financial-python-library-that-has-xirr-and-xnpv-function
# with some handling for special cases from
# https://github.com/RayDeCampo/java-xirr/blob/master/src/main/java/org/decampo/xirr/Xirr.java
#
def irregular_npv(cashflows, discount_rate):
    '''Calculate the irregular net present value.
    >>> from datetime import date
    >>> cashflows = {date(2019, 12, 31): -100, date(2020, 12, 31): 110}
    >>> irregular_npv(cashflows, -0.10)
    22.257507852701295
    '''
    if discount_rate == -1.0:
        return float('inf')
    base_date = min(cashflows.keys())
    if discount_rate <= -1.0:
        return sum([-abs(amount) / (-1.0 - discount_rate)**((date - base_date).days / DAYS_IN_YEAR) for date, amount in cashflows.items()])
    return sum([amount / (1.0 + discount_rate)**((date - base_date).days / DAYS_IN_YEAR) for date, amount in cashflows.items()])

def irregular_irr(cashflows):
    '''Calculate the irregular internal rate of return.
    >>> from datetime import date
    >>> cashflows = {date(2019, 12, 31): -80005.8, date(2020, 3, 12): 65209.6}
    >>> irregular_irr(cashflows)
    -0.645363882724717
    '''
    if not cashflows or len(cashflows) < 2:
        return None
    if all(amount >= 0 for amount in cashflows.values()):
        return -float("inf")
    if all(amount <= 0 for amount in cashflows.values()):
        return float("inf")
    irr_result = None
    try:
        irr_result = scipy.optimize.newton(lambda r: irregular_npv(cashflows, r), 0)
    except (RuntimeError, OverflowError):    # Failed to converge?
        irr_result = scipy.optimize.brentq(lambda r: irregular_npv(cashflows, r), -0.999999999999999, 1e20)
    if not isinstance(irr_result, complex):
        return irr_result
    else:
        return None

def adjusted_irr(cashflows):
    '''A "cleaned" version of the irr which avoids returning a irr for some extreme cases and ignores amounts which are almost 0.
    '''
    cleaned_cashflows = {}
    for date, amount in cashflows.items():
        if round(amount, 2) != 0:
            cleaned_cashflows[date] = amount
    result = irregular_irr(cleaned_cashflows)
    if result is not None and (abs(result) >= 100 or round(result, 4) == 0):
        return None
    else:
        return result

