import socket
from .. import schema

class Address(schema.BinarySchema):
    addr_type: int = schema.uint8
    ip_address: str = schema.Switch(
        "addr_type",
        {
            1: schema.Convert(
                schema.Bytes(4), 
                encode=socket.inet_aton, 
                decode=socket.inet_ntoa
            ),
            4: schema.Convert(
                schema.Bytes(16),
                encode=lambda data: socket.inet_pton(socket.AF_INET6, data),
                decode=lambda data: socket.inet_ntop(socket.AF_INET6, data),
            ),
            3: schema.LengthPrefixedString(schema.uint8),
        },
    )
    port_number: int = schema.uint16be

    @classmethod
    def create_from_address(cls, address):
        try:
            return cls(1, *address)
        except OSError:
            try:
                return cls(4, *address)
            except OSError:
                return cls(3, *address)

