class Buyer(PayPalEntity):
    """Paypal Buyer object representation
    """
    def __init__(
        self, buyer_id: str, person_name: PaypalName, email: str, 
        contact_phone: ContactPhone, dob: str, tax_details: PayerTaxDetails, 
        postal_address: PaypalPortableAddress, **kwargs
    ):
        super().__init__(kwargs.get('json_response', dict()), kwargs.get('response_type', ResponseType.MINIMAL))    
        self.buyer_id = buyer_id
        self.person_name = person_name
        self.email_address = email 
        self.contact_phone = contact_phone
        self._dob = dob
        self.tax_details = tax_details 
        self.postal_address = postal_address

    def to_dict(self) -> dict:
        d = super().to_dict()
        if '_dob' in d.keys():
            d['birth_date'] = d.pop('_dob')
        return d

    @property
    def date_of_birth(self) -> datetime:
        try:
            return datetime.strptime(self._dob, '%Y-%m-%d') if self._dob != None else None
        except:
            return None

    @classmethod
    def from_json(cls: Type[T], json_data: dict, response_type: ResponseType = ResponseType.MINIMAL) -> T:
        person_name, contact_phone, tax_details, postal_address = None, None, None, None
        if 'name' in json_data.keys():
            person_name = PaypalName.from_json(json_data['name'], response_type)
        if 'phone' in json_data.keys():
            contact_phone = ContactPhone.from_json(json_data['phone'], response_type)
        if 'tax_info' in json_data.keys():
            tax_details = PayerTaxDetails.from_json(json_data['tax_info'], response_type)
        if 'address' in json_data.keys():
            postal_address = PaypalPortableAddress.from_json(json_data['address'], response_type)
        return cls(
            json_data.get('payer_id'), person_name, json_data.get('email_address'), contact_phone, 
            json_data.get('birth_date'), tax_details, postal_address, json_response= json_data, 
            response_type = response_type
        )

    @classmethod
    def build(
        cls, buyer_id: str, person_name: PaypalName = None, email: str = None,
        contact_phone: ContactPhone = None, dob: str = None, tax_details: PayerTaxDetails  = None, 
        postal_address: PaypalPortableAddress = None
    ) -> 'Buyer':
        return cls(buyer_id, person_name, email, contact_phone, dob, tax_details, postal_address)

