class PayPalOrder(PayPalEntity):
    """Paypal Order object representation
    """
    def __init__(self, transaction_type: str, buyer: Buyer, line_items: List[OrderLineItem], context: OrderContext, **kwargs):
        super().__init__(kwargs.get('json_response', dict()), kwargs.get('response_type', ResponseType.MINIMAL))
        self.transaction_type = transaction_type
        self.buyer = buyer
        self.line_items = line_items
        self.context = context
        self.status = self._json_response.get('status')
        self.id = self._json_response.get('id', kwargs.get('id'))
        self._create_time = self._json_response.get('create_time')
        self._update_time = self._json_response.get('update_time')
        self.links = [ActionLink(x['href'], x['rel'], x.get('method', 'GET')) for x in self._json_response.get('links', [])]

    @property
    def status_as_enum(self) -> OrderState:
        """Status of the order as an enum constant

        Returns:
            OrderState -- An enumerated constant representing the order status or None
        """
        try:
            return OrderState[self.status] if self.status else None
        except:
            return None

    @property
    def created_at(self) -> datetime:
        try:
            return datetime.strptime(self._create_time, '%Y-%m-%d') if self._create_time != None else None
        except:
            return None

    @property
    def last_updated(self) -> datetime:
        try:
            return datetime.strptime(self._update_time, '%Y-%m-%d') if self._update_time != None else None
        except:
            return None

    @property
    def self_link(self) -> ActionLink:
        """Retrieves a link to read this entity details.

        Returns:
            ActionLink -- The link for requesting the information to the API.
        """
        return next(filter(lambda x: x.rel == 'self', self.links), None)

    @property
    def approval_link(self) -> ActionLink:
        """Retrieves a link to make an approval on this order.

        Returns:
            ActionLink -- The link for the API action.
        """
        return next(filter(lambda x: x.rel == 'approve', self.links), None)

    @property
    def payment_capture_link(self) -> ActionLink:
        """Retrieves a link to capture a payment for this order.

        Returns:
            ActionLink -- The link for the API action.
        """
        return next(filter(lambda x: x.rel == 'capture', self.links), None)

    def to_dict(self) -> dict:
        d = super().to_dict()
        if '_dob' in d.keys():
            d['birth_date'] = d.pop('_dob')
        return d

    @classmethod
    def from_json(cls: Type[T], json_data: dict, response_type: ResponseType = ResponseType.MINIMAL) -> T:
        buyer, context, line_items = None, None, []
        if 'payer' in json_data.keys():
            buyer = Buyer.from_json(json_data['payer'], response_type)

        if 'application_context' in json_data.keys():
            context = OrderContext.from_json(json_data['application_context'], response_type)

        if 'purchase_units' in json_data.keys():
            line_items = [OrderLineItem.from_json(x, response_type) for x in json_data['purchase_units']]
        return cls(
            json_data.get('intent'), buyer, line_items, context,
            json_response= json_data, response_type = response_type
        )

    @classmethod
    def build(cls, *, transaction_type: TransactionMode, line_items: List[OrderLineItem], buyer: Buyer = None, context: OrderContext = None) -> 'PayPalOrder':
        return cls(transaction_type.name, buyer, line_items, context)

