# Calculate the h-index for a list of citations
class Solution:
  def hIndex(self, papers: List[int]) -> int:
    total = len(papers)
    papers.sort()
    for idx, count in enumerate(papers):
      if count >= total - idx:
        return total - idx
    return 0

