import shutil
import os
from collections import OrderedDict
import torch
from torch import distributed as dist

def move_data_to_device(mmdata, target_device):
    result = {}
    # Process tensor fields directly in mmdata
    result = {
        key: val.to(target_device)
        for key, val in mmdata.items() 
        if torch.is_tensor(val)
    }

    # Handle nested 'deeptext' structure
    result['deeptext'] = {
        key: val.to(target_device)
        for key, val in mmdata['deeptext'].items()
    }
    return result

def save_model_checkpoint(model_state,
                          is_best_model,
                          save_directory,
                          filename='model_checkpoint.pth.tar'):
    # Only main process saves checkpoints
    if (not torch.distributed.is_initialized()
        ) or torch.distributed.get_rank() == 0:
        full_path = os.path.join(save_directory, filename)
        torch.save(model_state, full_path)

        # Save best model if applicable
        if is_best_model:
            shutil.copyfile(full_path,
                            os.path.join(save_directory, 'best_model.pth.tar'))

def average_tensor(tensor_val):
    # Clone tensor to avoid modifying original
    avg_result = tensor_val.clone()
    dist.all_reduce(avg_result, op=dist.ReduceOp.SUM)

    # Normalize by world size when distributed
    world_size = (torch.distributed.get_world_size()
                  if torch.distributed.is_initialized() else 1)
    avg_result /= world_size
    return avg_result

def update_learning_rate(optimizer, current_epoch, training_args):
    """Adjusts learning rate using step decay every 20 epochs"""
    base_lr = training_args.learning_rate
    new_lr = base_lr * (0.1**(current_epoch // 20))

    for group in optimizer.param_groups:
        group['lr'] = new_lr

    return new_lr

def restore_from_checkpoint(model, checkpoint_file, verbose=True):
    if os.path.isfile(checkpoint_file):
        checkpoint_data = torch.load(checkpoint_file, map_location='cuda:0')

        if isinstance(checkpoint_data, dict) and 'state_dict' in checkpoint_data:
            # Handle DataParallel prefix removal
            cleaned_state_dict = OrderedDict()
            for param_name, param_val in checkpoint_data['state_dict'].items():
                clean_name = param_name[7:] if param_name.startswith('module') else param_name
                cleaned_state_dict[clean_name] = param_val

            model.load_state_dict(cleaned_state_dict, strict=False)
        else:
            # Direct state dict loading
            model.load_state_dict(checkpoint_data, strict=False)
    else:
        raise FileNotFoundError(f"Checkpoint file not found: {checkpoint_file}")

def load_from_resume(args, verbose=True):
    if os.path.isfile(args.resume_path):
        print("=> loading checkpoint '{}'".format(args.resume_path))
        checkpoint_data = torch.load(
            args.resume_path,
            map_location=lambda storage, loc: storage.cuda(args.gpu_id))

        start_epoch = checkpoint_data['epoch']
        best_accuracy = checkpoint_data['best_prec1']
        model_weights = checkpoint_data['state_dict']
        optimizer_weights = checkpoint_data['optimizer']

        # Check for EMA weights
        ema_weights = checkpoint_data.get('state_dict_ema', None)

        print("=> loaded checkpoint '{}' (epoch {})".format(
            args.resume_path, checkpoint_data['epoch']))

        # Verify training hasn't already completed
        if start_epoch >= args.total_epochs:
            print(
                f'Training configured for {args.total_epochs} epochs, but checkpoint at epoch {start_epoch}'
            )
            exit(1)
    else:
        print("=> no checkpoint found at '{}'".format(args.resume_path))
        model_weights = None
        ema_weights = None
        optimizer_weights = None
        start_epoch = 0
        best_accuracy = 0.0

    return model_weights, ema_weights, optimizer_weights, start_epoch, best_accuracy

def test_checkpoint_loading(args):
    if os.path.isfile(args.resume_path):
        print("=> loading checkpoint '{}'".format(args.resume_path))
        checkpoint_data = torch.load(
            args.resume_path,
            map_location=lambda storage, loc: storage.cuda(args.gpu_id))

        # Clean module prefixes from keys
        cleaned_checkpoint = {
            k[len('module.'):] if k.startswith('module.') else k: v
            for k, v in checkpoint_data.items()
        }

        optimizer_weights = cleaned_checkpoint['optimizer']
        model_weights = cleaned_checkpoint['state_dict']
        ema_weights = cleaned_checkpoint.get('state_dict_ema', None)
    else:
        print("=> no checkpoint found at '{}'".format(args.resume_path))
        model_weights = None
        ema_weights = None
        optimizer_weights = None

    return model_weights, ema_weights, optimizer_weights

def extract_learning_rate(optimizer):
    # Get current learning rate from optimizer
    for group in optimizer.param_groups:
        return group['lr']

