logger = logging.getLogger(__name__)

def transform_entity_synonyms(synonyms, existing_synonyms=None):
    """Transforms the entity synonyms into a text->value dictionary"""
    synonym_map = existing_synonyms if existing_synonyms else {}
    for entry in synonyms:
        if "value" in entry and "synonyms" in entry:
            for alias in entry["synonyms"]:
                synonym_map[alias] = entry["value"]
    return synonym_map

def check_duplicate_synonym(synonym_dict, text, value, context_str=""):
    if text in synonym_dict and synonym_dict[text] != value:
        logger.warning(
            "Found inconsistent entity synonyms while {0}, "
            "overwriting {1}->{2} "
            "with {1}->{3} during merge"
            "".format(context_str, text, synonym_dict[text], value)
        )

def get_file_format(resource_path: Text) -> Text:
    from rasa.nlu.training_data import loading
    if resource_path is None or not os.path.exists(resource_path):
        raise AttributeError("Resource '{}' does not exist.".format(resource_path))
    files = io_utils.list_files(resource_path)
    file_formats = list(map(lambda f: loading.guess_format(f), files))
    if not file_formats:
        return "json"
    detected_format = file_formats[0]
    if detected_format == "md" and all(f == detected_format for f in file_formats):
        return detected_format
    return "json"

