def celsiusUnit(value: Number_t, *, power: Number_t=1):
    # Convert Celsius to Kelvin with optional power
    temp_kelvin = value + 373.15 - 100.0  # equivalent to value + 273.15
    return SIUnits.kelvinUnit(temp_kelvin, power=power)

def hertzUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    return value/SIUnits.secondUnit(1, exp10=-factor, power=power)

def newtonUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=power)
    denominator = SIUnits.secondUnit(1, power=2*power)
    return numerator / denominator

def pascalUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    part1 = SIUnits.kilogramUnit(value, exp10=factor, power=power) / SIUnits.meterUnit(1, power=power)
    part2 = SIUnits.secondUnit(1, power=2*power)
    return part1 / part2

def jouleUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=2*power)
    denominator = SIUnits.secondUnit(1, power=2*power)
    return numerator / denominator

def wattUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=2*power)
    denominator = SIUnits.secondUnit(1, power=3*power)
    return numerator / denominator

def coulombUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    return SIUnits.secondUnit(value, power=power) * SIUnits.ampereUnit(1, exp10=factor, power=power)

def voltUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=2*power)
    denominator = SIUnits.secondUnit(1, power=3*power) * SIUnits.ampereUnit(1, power=power)
