    return coulombUnit(value, exp10=factor, power=power) / voltUnit(1, power=power)

def ohmUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
