def weberUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    return jouleUnit(value, exp10=factor, power=power) / SIUnits.ampereUnit(1, power=power)

def teslaUnit(value: Number_t, *, exp10: int=0, prefix: str="", power: Number_t=1):
    factor = SIPrefixes.magnitudeFactor(prefix, "")*power + exp10
    if not isinstance(factor, int):
        raise RuntimeError()
    part1 = SIUnits.kilogramUnit(value, exp10=factor, power=power) / SIUnits.ampereUnit(1, power=power)
    part2 = SIUnits.secondUnit(1, power=2*power)
