# Modified version of JobScheduler with Type I clone transformations
from __future__ import annotations
import logging
import os
from dataclasses import dataclass
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List, Optional, Union
import drmaa2
from .scheduler_mode_interface import SchedulerModeInterface
from .utils import check_jobscript_is_readable

@dataclass
class JobStatusRecord:
    '''Class for keeping track of job status.'''
    task: drmaa2.Job
    result_path: Path
    idx: int
    details: Optional[drmaa2.JobInfo] = None
    condition: Optional[drmaa2.JobState] = None
    end_state: Optional[str] = None

class ClusterManager:
    def __init__(self, base_directory: Optional[Union[Path, str]], results_dir: Optional[Union[Path, str]], account: str,
                 slot: str, cluster_params: Optional[dict[str,str]] = None, max_wait: timedelta = timedelta(hours=2)):
        """ClusterManager can be used for cluster job submissions"""
        self.batch_index = 0
        self.results_directory: Optional[Path] = Path(results_dir) if results_dir else None
        self.task_completion_status: Dict[str, bool] = {}
        self.task_history: Dict[int, Dict[int, JobStatusRecord]] = {}
        self.script_file: Path
        self.task_env: Optional[Dict[str, str]] = None
        self.script_args: List
        self.result_paths: List[Path] = []
        self.account = self.validate_account_list(account)
        self.slot = self.validate_slot_list(slot)
        self.init_time = datetime.now()
        self.status_records: List[JobStatusRecord]
        self.max_wait = max_wait
        self.base_directory = Path(base_directory) if base_directory else Path.home()
        self.parameters: Dict[str, str] = {}
        if cluster_params:
            self.parameters.update(cluster_params)
        self.cluster_mode : SchedulerModeInterface
        self.ram : str
        self.threads : int
        self.task_name : str

    def validate_slot_list(self, slot: str) -> str:
        if not slot:
            raise ValueError(f"slot must be non-empty string")
        slot = slot.lower()
        with os.popen('qconf -sql') as q_proc:
            s_name_list = q_proc.read().split()
        if slot in s_name_list:
            return slot
        else:
            raise ValueError(f"slot {slot} not in slot list: {s_name_list}\n")

    def validate_account_list(self, account: str) -> str:
        if not account:
            raise ValueError(f"account must be non-empty string")
        with os.popen('qconf -sprjl') as acc_proc:
            acc_name_list = acc_proc.read().split()
        if account in acc_name_list:
            return account
        else:
            raise ValueError(f"{account} must be in list of account names: {acc_name_list}\n")

    def get_result_paths(self) -> List[Path]:
        return self.result_paths

    def get_success_rate(self) -> bool:
        return all(self.task_completion_status.values())

    def is_timestamp_valid(self, result: Path) -> bool:
        mod_time = datetime.fromtimestamp(result.stat().st_mtime)
        if mod_time > self.init_time:
            return True
        return False

    def execute(self, cluster_mode: SchedulerModeInterface, script_file: Path, task_env: Dict[str,str], ram: str = "4G",
                threads: int = 6, script_args: Optional[List] = None, task_name: str = "ParProcCo_task") -> bool:
        self.script_file = check_jobscript_is_readable(script_file)
        self.task_env = task_env
        self.cluster_mode = cluster_mode
        self.ram = ram
        self.threads = threads
        self.task_name = task_name
        task_indices = list(range(cluster_mode.total_tasks))
        if script_args is None:
            script_args = []
        self.script_args = script_args
        self.task_history[self.batch_index] = {}
        self.task_completion_status = {str(i): False for i in range(cluster_mode.total_tasks)}
        self.result_paths.clear()
        return self._execute_and_monitor(task_indices)

    def _execute_and_monitor(self, task_indices: List[int]) -> bool:
        session = drmaa2.JobSession()  # Automatically destroyed when it is out of scope
        self._submit_jobs(session, task_indices)
        self._await_jobs(session)
        self._log_job_details()
        return self.get_success_rate()

    def _submit_jobs(self, session: drmaa2.JobSession, task_indices: List[int]) -> None:
        logging.debug(f"Submitting jobs on cluster for script {self.script_file} and args {self.script_args}")
        try:
            # Submit all input paths in parallel:
            self.status_records = []
            for idx in task_indices:
                template = self._build_template(idx)
                logging.debug(f"Submitting drmaa task with script {self.script_file} and args {template.args}")
                task = session.run_job(template)
                self.status_records.append(JobStatusRecord(task, Path(template.output_path), idx))
                logging.debug(
                    f"drmaa task for script {self.script_file} and args {template.args}"
                    f" has been submitted with id {task.id}")
        except drmaa2.Drmaa2Exception:
            logging.error(f"Drmaa exception", exc_info=True)
            raise
        except Exception:
            logging.error(f"Unknown error occurred running drmaa task", exc_info=True)
            raise

    def _build_template(self, idx: int) -> drmaa2.JobTemplate:
        if self.results_directory:
            if not self.results_directory.is_dir():
                logging.debug(f"Creating directory {self.results_directory}")
                self.results_directory.mkdir(exist_ok=True, parents=True)
            else:
                logging.debug(f"Directory {self.results_directory} already exists")
            error_dir = self.results_directory / "cluster_logs"
        else:
            error_dir = self.base_directory / "cluster_logs"
        if not error_dir.is_dir():
            logging.debug(f"Creating directory {error_dir}")
            error_dir.mkdir(exist_ok=True, parents=True)
        else:
            logging.debug(f"Directory {error_dir} already exists")
        result_fp, stdout_fp, stderr_fp = self.cluster_mode.generate_output_paths(self.results_directory, error_dir, idx, self.init_time)
        if result_fp and result_fp not in self.result_paths:
            self.result_paths.append(Path(result_fp))
        args = self.cluster_mode.generate_args(idx, self.ram, self.threads, self.script_args, result_fp)
        logging.info(f"creating template with script: {str(self.script_file)} and args: {args}")
        self.parameters["m_mem_free"] = self.ram
        jt = drmaa2.JobTemplate({
            "job_name": self.task_name,
            "job_category": self.account,
            "remote_command": str(self.script_file),
            "min_slots": self.threads,
            "args": args,
            "resource_limits": self.parameters,
            "working_directory": str(self.base_directory),
            "output_path": stdout_fp,
            "error_path": stderr_fp,
            "queue_name": self.slot,
            "implementation_specific": {
                "uge_jt_pe": f"smp",
            },
        })
        task_env = dict(self.task_env) if self.task_env is not None else {}
        test_ppc_dir = os.getenv("TEST_PPC_DIR")
        if test_ppc_dir:
            logging.debug('Adding TEST_PPC_DIR=%s to environment', test_ppc_dir)
            task_env.update(TEST_PPC_DIR=test_ppc_dir)
        jt.job_environment = task_env
        return jt

    def _await_jobs(self, session: drmaa2.JobSession) -> None:
        try:
            task_list = [status_record.task for status_record in self.status_records]
            # Wait for tasks to start (timeout shouldn't include queue time)
            task_list_str = ", ".join([str(task.id) for task in task_list])
            logging.info(f"Waiting for tasks to start: {task_list_str}")
            session.wait_all_started(task_list)
            logging.info(f"Tasks started, waiting for tasks: {task_list_str}")
            session.wait_all_terminated(task_list, int(round(self.max_wait.total_seconds())))
            tasks_running = False
            for task in task_list:
                if task.get_state()[0] == drmaa2.JobState.RUNNING:
                    logging.warning(f"Task {task.id} timed out. Terminating task now.")
                    tasks_running = True
                    task.terminate()
            if tasks_running:
                # Termination takes some time, wait a max of 2 mins
                session.wait_all_terminated(task_list, 120)
        except drmaa2.Drmaa2Exception:
            logging.error(f"Drmaa exception", exc_info=True)
        except Exception:
            logging.error(f"Unknown error occurred running drmaa task", exc_info=True)

    def _log_job_details(self) -> None:
        # Iterate through tasks with logging to check individual task outcomes
        for status_record in self.status_records:
            logging.debug(f"Retrieving info for drmaa task {status_record.task.id}")
            try:
                status_record.condition = status_record.task.get_state()[0]  # Returns task state and task substate (always seems to be None)
                status_record.details = status_record.task.get_info()
            except Exception:
                logging.error(f"Failed to get task information for task {status_record.task.id}", exc_info=True)
                raise
            try:
                time_to_dispatch = status_record.details.dispatch_time - status_record.details.submission_time
                wall_time = status_record.details.finish_time - status_record.details.dispatch_time
            except Exception:
                logging.error(f"Failed to get task submission time statistics for task {status_record.task.id}")
                raise
            # Check task states against expected possible options:
            if status_record.condition == drmaa2.JobState.UNDETERMINED:  # Lost contact?
                status_record.end_state = "UNDETERMINED"
                logging.warning(
                    f"Task state undetermined for task {status_record.task.id}. task info: {status_record.details}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif status_record.condition == drmaa2.JobState.FAILED:
                status_record.end_state = "FAILED"
                logging.error(
                    f"drmaa task {status_record.task.id} failed. Terminating signal: {status_record.details.terminating_signal}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif not status_record.result_path.is_file():
                status_record.end_state = "NO_OUTPUT"
                logging.error(
                    f"drmaa task {status_record.task.id} with args {self.script_args} has not created"
                    f" output file {status_record.result_path}"
                    f" Terminating signal: {status_record.details.terminating_signal}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif not self.is_timestamp_valid(status_record.result_path):
                status_record.end_state = "OLD_OUTPUT_FILE"
                logging.error(
                    f"drmaa task {status_record.task.id} with args {self.script_args} has not created"
                    f" a new output file {status_record.result_path}"
                    f" Terminating signal: {status_record.details.terminating_signal}."
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            elif status_record.condition == drmaa2.JobState.DONE:
                self.task_completion_status[str(status_record.idx)] = True
                status_record.end_state = "SUCCESS"
                logging.info(
                    f"Task {status_record.task.id} with args {self.script_args} completed."
                    f" CPU time: {timedelta(seconds=float(status_record.details.cpu_time))}; Slots: {status_record.details.slots}"
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            else:
                status_record.end_state = "UNSPECIFIED"
                logging.error(
                    f"Unexpected task state for task {status_record.task.id}"
                    f" with args {self.script_args}, task info: {status_record.details}"
                    f" Dispatch time: {time_to_dispatch}; Wall time: {wall_time}."
                )
            self.task_history[self.batch_index][status_record.task.id] = status_record

    def resubmit_tasks(self, task_indices: List[int]) -> bool:
        self.batch_index += 1
        self.task_history[self.batch_index] = {}
        self.task_completion_status = {str(i): False for i in task_indices}
        logging.info(f"Resubmitting tasks with task_indices: {task_indices}")
        return self._execute_and_monitor(task_indices)

    def filter_terminated_tasks(self, tasks: List[drmaa2.Job]) -> List[drmaa2.Job]:
        terminated_tasks = [task for task in tasks if task.info.terminating_signal == "SIGKILL"]
        return terminated_tasks

    def retry_failed_tasks(self, allow_all_failed: bool = False):
        logging.info("Retrying terminated tasks")
        task_history = self.task_history
        if all(self.task_completion_status.values()):
            logging.warning("No failed tasks to retry")
            return True
        elif allow_all_failed or any(self.task_completion_status.values()):
            failed_tasks = [task_info for task_info in task_history[0].values() if task_info.end_state != "SUCCESS"]
            terminated_tasks = self.filter_terminated_tasks(failed_tasks)
            terminated_tasks_indices = [task.idx for task in terminated_tasks]
            logging.info(f"Total failed_tasks: {len(failed_tasks)}. Total terminated_tasks: {len(terminated_tasks)}")
            success = self.resubmit_tasks(terminated_tasks_indices)
            return success
        raise RuntimeError(f"All tasks failed. task_history: {task_history}\n")

# Modified version of BuildFacade with renamed variables, reordered logic, and minor structural changes
import logging
import multiprocessing
import os
import re
import sys
import time
from copy import deepcopy

import psutil

from pyro.Anonymizer import Anonymizer
from pyro.Enums.BuildEvent import BuildEvent
from pyro.Comparators import is_command_node
from pyro.PackageManager import PackageManager
from pyro.PapyrusProject import PapyrusProject
from pyro.PathHelper import PathHelper
from pyro.PexReader import PexReader
from pyro.ProcessManager import ProcessManager
from pyro.Enums.ProcessState import ProcessState
from pyro.TimeElapsed import TimeElapsed

from pyro.Comparators import endswith


class BuildFacade:
    logger: logging.Logger = logging.getLogger('pyro')

    project: PapyrusProject = None

    timer: TimeElapsed = TimeElapsed()

    total_scripts: int = 0
    compiled_successfully: int = 0
    total_commands: int = 0

    @property
    def failed_compilations(self) -> int:
        return self.total_commands - self.compiled_successfully

    @property
    def compilation_duration(self) -> str:
        raw_duration, avg_duration = ('{0:.3f}s'.format(t)
                                      for t in (self.timer.value(), self.timer.average(self.compiled_successfully)))

        return f'Compilation time: ' \
               f'{raw_duration} ({avg_duration}/script) - ' \
               f'{self.compiled_successfully} succeeded, ' \
               f'{self.failed_compilations} failed ' \
               f'({self.total_scripts} scripts)'

    def __init__(self, ppj: PapyrusProject) -> None:
        self.project = ppj

        self.total_scripts = len(self.project.psc_paths)

        # WARN: if methods are renamed and their respective option names are not, this will break.
        config_options: dict = deepcopy(self.project.options.__dict__)

        for key in config_options:
            if key in ('args', 'input_path', 'anonymize', 'package', 'zip', 'zip_compression'):
                continue
            if key.startswith(('ignore_', 'no_', 'force_', 'resolve_')):
                continue
            if key.endswith('_token'):
                continue
            setattr(self.project.options, key, getattr(self.project, f'get_{key}')())

    def _detect_changed_scripts(self) -> list:
        modified_pex_files: list = []

        for object_name, script_path in self.project.psc_paths.items():
            script_filename, _ = os.path.splitext(os.path.basename(script_path))

            # if pex exists, compare time_t in pex header with psc's last modified timestamp
            matching_pex: list = [pex_file for pex_file in self.project.pex_paths if endswith(pex_file, f'{script_filename}.pex', ignorecase=True)]
            if not matching_pex:
                continue

            pex_filepath: str = matching_pex[0]
            if not os.path.isfile(pex_filepath):
                continue

            try:
                header_info = PexReader.get_header(pex_filepath)
            except ValueError:
                BuildFacade.logger.warning(f'Cannot determine compilation time due to unknown magic: "{pex_filepath}"')
                continue

            psc_mtime: float = os.path.getmtime(script_path)
            pex_compile_time: float = float(header_info.compilation_time.value)

            # if psc is older than the pex
            if psc_mtime < pex_compile_time:
                modified_pex_files.append(pex_filepath)

        return PathHelper.uniqify(modified_pex_files)

    @staticmethod
    def _adjust_process_priority() -> None:
        current_process = psutil.Process(os.getpid())
        current_process.nice(psutil.BELOW_NORMAL_PRIORITY_CLASS if sys.platform == 'win32' else 19)

    def trigger_build_event(self, event_type: BuildEvent) -> None:
        if event_type == BuildEvent.PRE:
            has_hook, hook_node = self.project.has_pre_build_node, self.project.pre_build_node
        elif event_type == BuildEvent.POST:
            has_hook, hook_node = self.project.has_post_build_node, self.project.post_build_node
        else:
            raise NotImplementedError

        if has_hook:
            BuildFacade.logger.info(hook_node.get('Description'))

            normalize_whitespace = lambda s: re.sub('[ \t\n\r]+', ' ', s.strip())

            env_vars: dict = os.environ.copy()
            command_line: str = ' && '.join(normalize_whitespace(node.text) for node in filter(is_command_node, hook_node))

            ProcessManager.run_command(command_line, self.project.project_path, env_vars)

    def attempt_compilation(self) -> None:
        """Builds and passes commands to Papyrus Compiler"""
        build_commands: list = self.project.build_commands()

        self.total_commands = len(build_commands)

        self.timer.start_time = time.time()

        if self.project.options.no_parallel or self.total_commands == 1:
            for cmd in build_commands:
                if ProcessManager.run_compiler(cmd) == ProcessState.SUCCESS:
                    self.compiled_successfully += 1
        elif self.total_commands > 0:
            multiprocessing.freeze_support()
            max_workers = min(self.total_commands, self.project.options.worker_limit)
            pool = multiprocessing.Pool(processes=max_workers,
                                        initializer=BuildFacade._adjust_process_priority)
            for result in pool.imap(ProcessManager.run_compiler, build_commands):
                if result == ProcessState.SUCCESS:
                    self.compiled_successfully += 1
            pool.close()
            pool.join()

        self.timer.end_time = time.time()

    def attempt_anonymization(self) -> None:
        """Obfuscates identifying metadata in compiled scripts"""
        target_scripts: list = self._detect_changed_scripts()

        if not target_scripts and not self.project.missing_scripts and not self.project.options.no_incremental_build:
            BuildFacade.logger.error('Cannot anonymize compiled scripts because no source scripts were modified')
        else:
            # these are absolute paths. there's no reason to manipulate them.
            for pex_filepath in self.project.pex_paths:
                if not os.path.isfile(pex_filepath):
                    BuildFacade.logger.warning(f'Cannot locate file to anonymize: "{pex_filepath}"')
                    continue

                Anonymizer.anonymize_script(pex_filepath)

    def attempt_packaging(self) -> None:
        """Generates BSA/BA2 packages for project"""
        packer = PackageManager(self.project)
        packer.create_packages()

    def attempt_archiving(self) -> None:
        """Generates ZIP file for project"""
        packer = PackageManager(self.project)
        packer.create_zip()

# Helper function to convert various location types into a list format
from opentrons.protocol_api.labware import Well
from opentrons.types import Location
from typing import Union, Sequence, List, Any

CommandLocation = Union[Location, None, Sequence, Well]

def flatten_location(loc_input: Any) -> List:
    if isinstance(loc_input, list):
        try:
            return flatten_location(loc_input[0])
        except IndexError:
            return [loc_input]
    else:
        return [loc_input]

def _format_location_str(loc: Union[Location, Well]) -> str:
    if isinstance(loc, Location):
        if loc.labware.is_empty:
            return str(loc.point)
        else:
            return repr(loc.labware)
    elif isinstance(loc, Well):
        return str(loc)
    else:
        raise TypeError(loc)

def convert_location_to_string(loc: CommandLocation) -> str:
    formatted_list = [_format_location_str(item) for item in flatten_location(loc)]
    return ", ".join(formatted_list)

# Perform a roundtrip check for module IR serialization/deserialization
from typing import Any, Dict, Tuple
from collections import OrderedDict
from collections.abc import Iterable
from mypyc.ops import (
    deserialize_modules, DeserMaps, ModuleIR, FuncDecl, FuncIR, ClassIR, FuncSignature, RType
)
from mypyc.sametype import is_same_type, is_same_signature

def extract_attributes(obj: Any) -> Dict[str, Any]:
    if hasattr(obj, '__mypyc_attrs__'):
        return {attr: getattr(obj, attr) for attr in obj.__mypyc_attrs__ if hasattr(obj, attr)}
    else:
        return dict(obj.__dict__)

def get_func_attributes(func_ir: FuncIR) -> Dict[str, Any]:
    """Extract a dictionary of function attributes suitable for comparison across serialization"""
    attrs = extract_attributes(func_ir)
    attrs.pop('blocks', None)
    attrs.pop('env', None)
    return attrs

def verify_identical_blobs(obj1: Any, obj2: Any, path: Tuple[Any, ...]) -> None:
    """Verify that two IR blobs are equivalent to the extent supported.
    FuncDecls, FuncIRs, and ClassIRs are compared by fullname to prevent infinite recursion.
    (More detailed comparisons should be performed manually.)
    Types and signatures are checked using mypyc.sametype.
    Containers are recursively verified.
    All other objects are compared using ==.
    The `path` argument is used for constructing informative error messages.
    """
    assert type(obj1) is type(obj2), ("Type mismatch at {}".format(path), type(obj1), type(obj2))

    if isinstance(obj1, (FuncDecl, FuncIR, ClassIR)):
        assert obj1.fullname == obj2.fullname
    elif isinstance(obj1, OrderedDict):
        assert len(obj1.keys()) == len(obj2.keys()), "Keys mismatch at {}".format(path)
        for (k1, v1), (k2, v2) in zip(obj1.items(), obj2.items()):
            verify_identical_blobs(k1, k2, path + ("keys",))
            verify_identical_blobs(v1, v2, path + (k1,))
    elif isinstance(obj1, dict):
        assert obj1.keys() == obj2.keys(), "Keys mismatch at {}".format(path)
        for key in obj1.keys():
            verify_identical_blobs(obj1[key], obj2[key], path + (key,))
    elif isinstance(obj1, Iterable) and not isinstance(obj1, str):
        for idx, (val1, val2) in enumerate(zip(obj1, obj2)):
            verify_identical_blobs(val1, val2, path + (idx,))
    elif isinstance(obj1, RType):
        assert is_same_type(obj1, obj2), "RType mismatch at {}".format(path)
    elif isinstance(obj1, FuncSignature):
        assert is_same_signature(obj1, obj2), "Signature mismatch at {}".format(path)
    else:
        assert obj1 == obj2, "Value mismatch at {}".format(path)

def verify_module_equivalence(mod1: ModuleIR, mod2: ModuleIR) -> None:
    """Verify that two module IRs are equivalent (*).
    (*) Or rather, as much as we care about preserving across
    serialization. We discard actual IR bodies of functions but attempt
    to preserve all other relevant data.
    """
    assert mod1.fullname == mod2.fullname
    assert mod1.imports == mod2.imports

    for cls1, cls2 in zip(mod1.classes, mod2.classes):
        verify_identical_blobs(extract_attributes(cls1), extract_attributes(cls2),
                               (mod1.fullname, cls1.fullname))

    for fn1, fn2 in zip(mod1.functions, mod2.functions):
        verify_identical_blobs(get_func_attributes(fn1), get_func_attributes(fn2),
                               (mod1.fullname, fn1.fullname))
        verify_identical_blobs(extract_attributes(fn1.decl), extract_attributes(fn2.decl),
                               (mod1.fullname, fn1.fullname))

    verify_identical_blobs(mod1.final_names, mod2.final_names, (mod1.fullname, 'final_names'))

def validate_serialization_roundtrip(modules: Dict[str, ModuleIR]) -> None:
    """Validate that modules can be serialized and deserialized without loss."""
    serialized_data = {name: module.serialize() for name, module in modules.items()}
    context = DeserMaps({}, {})
    deserialized_modules = deserialize_modules(serialized_data, context)

    assert modules.keys() == deserialized_modules.keys()
    for name in modules:
        verify_module_equivalence(modules[name], deserialized_modules[name])

# Modified version with Type I clone transformations
from typing import Tuple
import numpy as np
import torch
from torch import matmul

def normalize_matrix(matrix, norm_factor, scale_by_average_diag=True):
    if norm_factor > 0:
        assert len(set(matrix.shape[-2:])) == 1, "matrix must be square"
        if scale_by_average_diag:
            diag_avg = batch_diagonal(matrix).mean(dim=-1, keepdim=True)
            diag_norm = batch_diagonal_matrix(
                torch.ones_like(matrix[..., 0]) * diag_avg * norm_factor
            )
        else:
            diag_norm = batch_diagonal_matrix(
                torch.ones_like(matrix[..., 0]) * norm_factor
            )
        normalized_mat = matrix + diag_norm
    else:
        normalized_mat = matrix
    return normalized_mat

def cholesky_decomposition(
    matrix,
    upper=False,
    out=None,
    norm=0.0,
    initial_norm_attempt=1e-6,
    max_norm_limit=1e2,
    factor=10,
    verbose=True,
):
    if norm > 0 and verbose:
        print(f"applying regularization with value: {norm}")
        normalized_mat = normalize_matrix(
            matrix=matrix, norm_factor=norm, scale_by_average_diag=True
        )
    else:
        normalized_mat = matrix
    try:
        # TODO: there is currently a magma bug that occurs for certain batch sizes.
        #  github issue: https://github.com/pytorch/pytorch/issues/26996
        #  see also https://discuss.pytorch.org/t/cuda-illegal-memory-access-when-using-batched-torch-cholesky/51624/8
        #  for the temporary hack used below
        # device = normalized_mat.device
        # return torch.cholesky(normalized_mat.to("cpu"), upper=upper, out=out).to(device)
        # TODO: bug still exists, but only for certain batch sizes. This slows down too much
        return torch.cholesky(normalized_mat, upper=upper, out=out)
    except RuntimeError:
        if torch.isnan(matrix).any():
            raise ValueError("NaN detected in input matrix.")
        else:
            norm = max(
                norm * factor, initial_norm_attempt
            )
            if norm > max_norm_limit:
                raise ValueError(
                    f"attempted normalization greater than "
                    f"max_norm_limit: {max_norm_limit}."
                )
            else:
                return cholesky_decomposition(
                    matrix=matrix,
                    upper=upper,
                    out=out,
                    norm=norm,
                )

def covariance_and_cholesky_from_inverse_param(Linv_tril, Linv_logdiag):
    L = torch.inverse(
        torch.tril(Linv_tril, -1) + batch_diagonal_matrix(torch.exp(Linv_logdiag))
    )
    return matmul(L, L.transpose(-1, -2)), L

def covariance_from_inverse_param(Linv_tril, Linv_logdiag):
    return covariance_and_cholesky_from_inverse_param(
        Linv_tril=Linv_tril, Linv_logdiag=Linv_logdiag
    )[0]

def inverse_from_inverse_param(Linv_tril, Linv_logdiag):
    Linv = torch.tril(Linv_tril, -1) + batch_diagonal_matrix(
        torch.exp(Linv_logdiag)
    )
    return matmul(Linv.transpose(-1, -2), Linv)

def batch_cholesky_inverse(Lmat):
    """
    performs torch.cholesky_inverse for matrices with leading
    match dimensions.
    Note that torch can do batched torch.cholesky but not torch.cholesky_inverse
    """
    Lmatinv = torch.inverse(Lmat)
    return matmul(Lmatinv.transpose(-1, -2), Lmatinv)

def batch_diagonal(mat):
    return mat[..., torch.arange(mat.shape[-2]), torch.arange(mat.shape[-1])]

def batch_diagonal_matrix(diagonal):
    N = diagonal.shape[-1]
    shape = diagonal.shape[:-1] + (N, N)
    device, dtype = diagonal.device, diagonal.dtype
    result = torch.zeros(shape, dtype=dtype, device=device)
    indices = torch.arange(result.numel(), device=device).reshape(shape)
    indices = indices.diagonal(dim1=-2, dim2=-1)
    result.view(-1)[indices] = diagonal
    return result

def symmetrize_matrix(mat):
    return 0.5 * (mat + mat.transpose(-1, -2))

def matrix_vector_product(mat, vec):
    if vec.ndim == 1:
        return torch.matmul(mat, vec)
    elif mat.ndim == 2:
        return torch.matmul(vec, mat.transpose(1, 0))
    else:
        return torch.matmul(mat, vec[..., None])[..., 0]

def get_machine_epsilon(x):
    if isinstance(x, float):
        eps = np.finfo(np.array(x).dtype).eps
    elif isinstance(x, (torch.Tensor,)):
        eps = torch.finfo(x.dtype).eps
    elif isinstance(x, (np.ndarray, np.generic)):
        eps = np.finfo(x.dtype).eps
    else:
        raise ValueError("unknown dtype of {}".format(x))
    return eps

def stable_logarithm(x, eps=None):
    eps = get_machine_epsilon(x) if eps is None else eps
    return torch.log(x + eps)

# def kron(A, B):
#     res_vec = torch.matmul(A[:, None, :, None], B[None, :, None, :])
#     return res_vec.reshape([A.shape[0] * B.shape[0], A.shape[1] * B.shape[1]])

def kronecker_product(A, B):
    """
    Kronecker Product.
    Works with batch dimemsion(s) - requires both A and B have same batch dims.
    """
    A_shp, B_shp = A.shape, B.shape
    assert A_shp[:-2] == B_shp[:-2]
    kron_block = torch.matmul(
        A[..., :, None, :, None], B[..., None, :, None, :]
    )
    kron = kron_block.reshape(
        A_shp[:-2] + (A_shp[-2] * B_shp[-2], A_shp[-1] * B_shp[-1],)
    )
    return kron

def flatten_covariance_params(mean, cov):
    # Take lower-triangular incl. diagonal from covariance matrix of state.
    indices = torch.tril_indices(row=cov.shape[-2], col=cov.shape[-1], offset=0)
    cov_flat = cov[..., indices[0], indices[1]]
    return torch.cat((mean, cov_flat), dim=-1)

def log_mean_exp(tensor: torch.Tensor, dim: int, keepdim: bool = False):
    return torch.logsumexp(tensor, dim=dim, keepdim=keepdim) - np.log(
        tensor.shape[dim]
    )

def construct_block_diagonal(matrices: Tuple[torch.Tensor]) -> torch.Tensor:
    if not isinstance(matrices, (list, tuple)):
        raise Exception("provide list or tuple")
    elif len(matrices) > 1:
        off_diag_upper_right = torch.zeros(
            matrices[-2].shape[:-1] + (matrices[-1].shape[-1],),
            dtype=matrices[-1].dtype,
            device=matrices[-1].device,
        )
        off_diag_lower_left = torch.zeros(
            matrices[-1].shape[:-1] + (matrices[-2].shape[-1],),
            dtype=matrices[-1].dtype,
            device=matrices[-1].device,
        )
        block_diag = torch.cat(
            [
                torch.cat([matrices[-2], off_diag_upper_right], dim=-1),
                torch.cat([off_diag_lower_left, matrices[-1]], dim=-1),
            ],
            dim=-2,
        )
        return construct_block_diagonal(tuple(matrices[:-2]) + (block_diag,))
    else:  # final recursion
        return matrices[0]

# Plugin implementation for Electrum integration with Haros
from __future__ import unicode_literals
import os
from jinja2 import Environment, PackageLoader
from .analyzer import model_check
from .electrum2haros import parse_output, render_result
from .haros2electrum import config2model, render_model

###############################################################################
# Plugin Entry Point
###############################################################################
PLUGIN_NAME = 'haros_plugin_electrum'

def analyze_configuration(iface, configuration):
    # Skip analysis if required components are missing
    if (not configuration.launch_commands or len(configuration.nodes.enabled) < 2
            or not configuration.hpl_properties):
        return

    # Retrieve plugin-specific settings
    plugin_settings = configuration.user_attributes.get(PLUGIN_NAME, {})

    try:
        _validate_plugin_settings(plugin_settings)
    except PluginConfigurationError as error:
        iface.log_error(error.message)

    # Determine JAR file location
    jar_location = _find_jar_file(plugin_settings)
    # Get analysis scopes
    analysis_scopes = _determine_scopes(plugin_settings)

    # Initialize Jinja environment
    template_engine = JinjaEnvironment()

    try:
        # Generate model from configuration
        system_model = config2model(configuration)
        electrum_code = render_model(template_engine, system_model)

        # Save model to file
        filename = 'model_{}.ele'.format('_'.join(configuration.name.split()))
        with open(filename, 'w') as file_handle:
            file_handle.write(electrum_code)
            file_handle.write('\n')

        # Export the model file
        iface.export_file(filename)

        # Run model checking
        check_output = model_check(jar_location, electrum_code, analysis_scopes)
        analysis_result = parse_output(check_output, configuration)

        # Generate HTML report
        html_report = render_result(template_engine, analysis_result)
        iface.report_runtime_violation('counterexample', html_report, analysis_result.resources)

    except Exception as exception:
        iface.log_error(exception.message)

def _validate_plugin_settings(settings):
    jar_config = settings.get('jar')
    if not jar_config:
        raise PluginConfigurationError.missing_jar()

    if not isinstance(jar_config, dict):
        raise PluginConfigurationError.jar_not_dict()

    if 'path' not in jar_config and 'env' not in jar_config:
        raise PluginConfigurationError.missing_jar_path()

    if 'env' in jar_config and not os.environ.get(jar_config['env']):
        raise PluginConfigurationError.missing_env_var(jar_config['env'])

    # Validate scope values if provided
    scope_values = settings.get('scope')
    if scope_values:
        for scope_key in ('time', 'msgs', 'values'):
            value = scope_values.get(scope_key)
            if value is not None and (not isinstance(value, int) or value < 0):
                raise PluginConfigurationError.invalid_scope(scope_key, value)

def _find_jar_file(settings):
    jar_config = settings['jar']
    path_value = jar_config.get('path')

    if path_value is None:
        env_variable = jar_config['env']
        path_value = os.environ[env_variable]

    return path_value

def _determine_scopes(settings):
    default_scopes = settings.get('scope', {})

    # Apply default values if not specified
    if 'time' not in default_scopes:
        default_scopes['time'] = 10
    if 'msgs' not in default_scopes:
        default_scopes['msgs'] = 9
    if 'values' not in default_scopes:
        default_scopes['values'] = 4

    return default_scopes

###############################################################################
# Data Structures
###############################################################################
def JinjaEnvironment():
    return Environment(
        loader=PackageLoader(PLUGIN_NAME, 'templates'),
        line_statement_prefix=None,
        line_comment_prefix=None,
        trim_blocks=True,
        lstrip_blocks=True,
        autoescape=False
    )

class PluginConfigurationError(Exception):
    @classmethod
    def missing_jar(cls):
        return cls('missing `jar` field in plugin settings')

    @classmethod
    def jar_not_dict(cls):
        return cls('expected a dictionary under the `jar` setting')

    @classmethod
    def missing_jar_path(cls):
        return cls('missing .jar path; expected one of `jar:path` or `jar:env`')

    @classmethod
    def missing_env_var(cls, var_name):
        return cls("missing '{}' environment variable with .jar path".format(var_name))

    @classmethod
    def invalid_scope(cls, key_name, value):
        return cls("invalid scope value for '{}': {}".format(key_name, value))

