import os
import subprocess
import torch
from ucca.convert import passage2file
import tempfile

def save_passages(predictions, directory):
    if not os.path.exists(directory):
        try:
            os.makedirs(directory)
        except Exception as err:
            print(err)
    for item in predictions:
        passage2file(item, os.path.join(directory, item.ID + ".xml"))

class UCCA_Evaluator(object):
    def __init__(
        self, model, reference_dir=None, output_dir=None,
    ):
        self.model = model
        self.reference_dir = reference_dir
        self.output_dir = output_dir
        self.temp_output_dir = tempfile.TemporaryDirectory(prefix="ucca-eval-")
        self.highest_F = 0

    @torch.no_grad()
    def inference(self, data_loader):
        self.model.eval()
        results = []
        for batch in data_loader:
            word_ids, pos_ids, dep_ids, ent_ids, ent_iob_ids, passages, alignments, trees, all_nodes, all_remote = batch
            word_ids = word_ids.cuda() if torch.cuda.is_available() else word_ids
            pos_ids = pos_ids.cuda() if torch.cuda.is_available() else pos_ids
            dep_ids = dep_ids.cuda() if torch.cuda.is_available() else dep_ids
            ent_ids = ent_ids.cuda() if torch.cuda.is_available() else ent_ids
            ent_iob_ids = ent_iob_ids.cuda() if torch.cuda.is_available() else ent_iob_ids
            predicted_passages = self.model.parse(word_ids, pos_ids, dep_ids, ent_ids, ent_iob_ids, passages, alignments, trees, all_nodes, all_remote)
            results.extend(predicted_passages)
        return results

    def clear_temp(self):
        self.temp_output_dir.cleanup()

    def evaluate(self, data_loader):
        generated_passages = self.inference(data_loader)
        save_passages(generated_passages, self.temp_output_dir.name)
        child = subprocess.Popen(
            "python -m scripts.evaluate_standard {} {} -f".format(
                self.reference_dir, self.temp_output_dir.name
            ),
            shell=True,
            stdout=subprocess.PIPE,
        )
        evaluation_output = str(child.communicate()[0], encoding="utf-8")
        try:
            Fscore_line = evaluation_output.strip().split("\n")[-1]
            Fscore_value = Fscore_line.strip().split()[-1]
            Fscore = float(Fscore_value)
            print("Fscore={}".format(Fscore))
        except IndexError:
            print("Unable to retrieve FScore. Skipping.")
            Fscore = 0
        if Fscore > self.highest_F:
            print('\n'.join(evaluation_output.split('\n')[1:]))
            self.highest_F = Fscore
            if self.output_dir:
                save_passages(generated_passages, self.output_dir)
        return Fscore

# Import necessary modules for thread locking and authentication errors
from thread import allocate_lock
from pyfire.auth.backends import InvalidAuthenticationError

class AuthenticationManager(object):
    """Manages all active authentication backends"""
    def __init__(self):
        self.backends = {}
        self._mutex = allocate_lock()

    def add_backend(self, name, handler):
        """Adds a new authentication backend"""
        registered = False
        with self._mutex:
            if name not in self.backends:
                self.backends[name] = handler
                registered = True
        if not registered:
            raise AttributeError("backend already exists")

    def remove_backend(self, name):
        """Removes an authentication backend"""
        removed = False
        with self._mutex:
            if name in self.backends:
                self.backends[name].cleanup()
                del self.backends[name]
                removed = True
        if not removed:
            raise AttributeError("backend not found")

    def check_credentials(self, username, password):
        """Verifies username and password against all registered backends.
           Returns the backend name where authentication succeeded or raises
           InvalidAuthenticationError otherwise.
        """
        matched = ""
        with self._mutex:
            for backend_name, handler in self.backends.iteritems():
                if handler.authenticate_userpass(username, password):
                    matched = backend_name
                    break
        if matched == "":
            raise InvalidAuthenticationError("invalid credentials provided")
        return matched

    def verify_session(self, session_token):
        """Validates the given session token against all backends.
           Returns the backend name where validation succeeded or raises
           InvalidAuthenticationError otherwise.
        """
        matched = ""
        with self._mutex:
            for backend_name, handler in self.backends.iteritems():
                if handler.check_token(session_token):
                    matched = backend_name
                    break
        if matched == "":
            raise InvalidAuthenticationError("session token invalid")
        return matched

