import mutagen.oggvorbis as ogg_reader
import os
import tempfile
from django import forms as django_forms
from django.core.files.base import File as DjangoFile
from django.db import models as db_models
from django.db.models.fields.files import (
    FileDescriptor as BaseFileDescriptor,
    FieldFile as BaseFieldFile,
    FileField as BaseFileField,
)

class CustomAudioFile(DjangoFile):
    def __get_performer(self):
        performer = self.metadata.get("artist") or ""
        return performer
    performer = property(__get_performer)

    def __get_song_name(self):
        song_name = self.metadata.get("title") or ""
        return song_name
    song_name = property(__get_song_name)

    def __get_category(self):
        category = self.metadata.get("genre") or ""
        return category
    category = property(__get_category)

    def __get_duration(self):
        duration = self.metadata.get("total_time") or 0
        return duration
    duration = property(__get_duration)

    def __get_info(self):
        if not hasattr(self, "_metadata_cache"):
            self.__store_metadata()
        return self._metadata_cache
    metadata = property(__get_info)

    def __extract_tag_data(self, audio_file):
        data = {}
        if audio_file.tags is not None:
            for field in "artist", "title", "album", "genre":
                value = ",".join(audio_file.tags.get(field, []))
                data.update(**{field: value})
        return data

    def __extract_stream_info(self, audio_file):
        data = {}
        if audio_file.info is not None:
            data.update(bitrate_kbps=audio_file.info.bitrate / 1000)
            data.update(sample_rate=audio_file.info.sample_rate)
            data.update(duration_seconds=int(audio_file.info.length))
        return data

    def __store_metadata(self):
        def __build_metadata(audio_obj):
            info = {}
            info.update(**self.__extract_tag_data(audio_obj))
            info.update(**self.__extract_stream_info(audio_obj))
            return info

        was_closed = self.closed
        self.open()
        temp_fd, temp_path = tempfile.mkstemp()
        try:
            self.seek(0)
            os.write(temp_fd, self.read())
            os.close(temp_fd)
            self._metadata_cache = __build_metadata(
                ogg_reader.OggVorbis(temp_path)
            )
        except ogg_reader.OggVorbisHeaderError:
            self._metadata_cache = {}
        finally:
            os.remove(temp_path)
            if was_closed:
                self.close()

    def __repr__(self):
        return self.name

    def __str__(self):
        return repr(self)

class CustomAudioFileDescriptor(BaseFileDescriptor):
    def __set__(self, instance, value):
        old_file = instance.__dict__.get(self.field.name)
        super().__set__(instance, value)
        if old_file is not None:
            self.field._refresh_metadata_fields(instance, force=True)

class CustomAudioFieldFile(CustomAudioFile, BaseFieldFile):
    def delete(self, save=True):
        if hasattr(self, "_metadata_cache"):
            del self._metadata_cache
        super().delete(save)

class CustomAudioField(BaseFileField):
    attr_class = CustomAudioFieldFile
    descriptor_class = CustomAudioFileDescriptor
    description = "Path to audio file"

    def __init__(
        self,
        verbose_name=None,
        name=None,
        upload_to="",
        storage=None,
        artist_db_field=None,
        title_db_field=None,
        genre_db_field=None,
        length_db_field=None,
        size_db_field=None,
        **kwargs,
    ):
        self.artist_db_field = artist_db_field
        self.title_db_field = title_db_field
        self.genre_db_field = genre_db_field
        self.length_db_field = length_db_field
        self.size_db_field = size_db_field
        super().__init__(verbose_name, name, upload_to, storage, **kwargs)

    def contribute_to_class(self, cls, name, **kwargs):
        super().contribute_to_class(cls, name, **kwargs)
        db_models.signals.post_init.connect(
            self._refresh_metadata_fields, sender=cls
        )

    def _refresh_metadata_fields(self, instance, force=False, *args, **kwargs):
        """
        Updates database fields based on associated metadata properties
        :return: None
        """
        has_any_db_field = any(
            [
                self.artist_db_field,
                self.title_db_field,
                self.length_db_field,
                self.genre_db_field,
            ]
        )
        if not has_any_db_field:
            return

        # getattr will invoke the CustomAudioFileDescriptor's __get__ method
        audio_file = getattr(instance, self.attname)

        if not audio_file and not force:
            return

        metadata_complete = (
            not self.length_db_field or getattr(instance, self.length_db_field)
        ) or (not self.size_db_field or getattr(instance, self.size_db_field))

        if metadata_complete and not force:
            return

        if audio_file:
            performer = audio_file.performer
            song_name = audio_file.song_name
            category = audio_file.category
            duration = audio_file.duration
            file_size = audio_file.size
        else:
            performer = None
            song_name = None
            category = None
            duration = None
            file_size = None

        if self.artist_db_field and not getattr(instance, self.artist_db_field):
            setattr(instance, self.artist_db_field, performer)
        if self.title_db_field and not getattr(instance, self.title_db_field):
            setattr(instance, self.title_db_field, song_name)
        if self.genre_db_field and not getattr(instance, self.genre_db_field):
            setattr(instance, self.genre_db_field, category)
        if self.length_db_field and not getattr(instance, self.length_db_field):
            setattr(instance, self.length_db_field, duration)
        if self.size_db_field and not getattr(instance, self.size_db_field):
            setattr(instance, self.size_db_field, file_size)

    def formfield(self, **kwargs):
        defaults = {"form_class": django_forms.FileField}
        defaults.update(kwargs)
        return super().formfield(**defaults)

# Image validation utility using PIL library
from PIL import Image
import os
import argparse

def check_image(filepath, debug=False):
    if debug: 
        print(f"validating {filepath}", end="...")
    try:
        # Open and verify the image file
        img = Image.open(filepath)
        img.verify()  # Check for corruption or incomplete data
        img.close()   # Close the file handle

        # Reopen to perform additional transformation test
        img = Image.open(filepath)
        img.transpose(Image.FLIP_LEFT_RIGHT)  # Test basic processing capability
        img.close()

        if debug: 
            print("passed")
        return True
    except Exception:
        if debug: 
            print("failed")
        return False

def check_directory(directory_path, debug=False):
    base_dir = os.path.join(os.getcwd(), directory_path)
    invalid_files = []

    print("scanning directory recursively...",)
    for current_dir, _, files in os.walk(base_dir):
        for file_name in files:
            full_file_path = os.path.join(current_dir, file_name)
            if not check_image(full_file_path, debug): 
                invalid_files.append(file_name)
    print("completed")

    if invalid_files: 
        print(f"The following images could not be processed by PIL:\n{invalid_files}")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Image integrity checker")
    parser.add_argument("-i", "--image", help="Path to a single image file")
    parser.add_argument("-d", "--directory", help="Path to a directory to scan")
    parser.add_argument("-v", "--verbose", action="store_true", help="Enable verbose output")
    arguments = parser.parse_args()

    if arguments.image is not None:
        check_image(arguments.image, arguments.verbose)
    if arguments.directory is not None:
        check_directory(arguments.directory, arguments.verbose)

