        # First case: no specific project name provided
        if project_name is None:
            for current_dir, subdirs, filenames in os.walk(directory):
                for filename in filenames:
                    if filename == 'vivado_hls.app':
                        if found_path is None:
                            found_path = current_dir
                        else:
                            raise ManyHLSProjectsError
            if found_path is None:
                raise NoHLSProjectError
        else:
            # Second case: specific project name provided
            found_path = os.path.join(directory, project_name)
            if not os.path.exists(found_path) or \
               'vivado_hls.app' not in os.listdir(found_path):
                raise NoSpecifiedHLSProjectError

        solutions_list = []

        try:
            config_tree = ET.parse(os.path.join(found_path, 'vivado_hls.app'))
            root_element = config_tree.getroot()
            solutions_node = None

            # Find the solutions element in the XML tree
            for node in root_element:
                if node.tag.endswith('solutions'):
                    solutions_node = node
                    break

            if solutions_node is None:
                raise RuntimeError(
                    'Could not locate the "solutions" tag in vivado_hls.app')

            # Extract solution names
            for solution_elem in solutions_node:
                sol_name = solution_elem.get('name')
                if sol_name is not None:
                    solutions_list.append(sol_name)

        except Exception as error:
            raise InvalidHLSProjectError(exception=error)

        return found_path, solutions_list

    def get_hdl_dir_path(self, project_directory: str, solution_name: str) -> str:
        return os.path.join(project_directory, solution_name, 'impl', 'ip', 'hdl')

    def get_ip_hdl_file_path(self, project_directory: str, solution_name: str) -> str:
        return os.path.join(self.get_hdl_dir_path(project_directory, solution_name),
                            'vhdl', 'myproject.vhd')

    def parse_ports(self, hdl_content: str) -> list:
        import re  # Moved import inside method to avoid unused import warning
        pattern = re.compile(
            r'entity\s+myproject\s+is\s+port\s*\((.*)\)\s*;\s*end\s*;',
            flags=re.DOTALL|re.IGNORECASE)
        match = pattern.search(hdl_content)

        if match is None:
            return []

        port_section = match.group(1)
        port_lines = map(str.strip, port_section.split('\n'))
        ports = []

        line_pattern = re.compile(r'(\S+)\s*:\s+(in|out)\s+([^;]+);?',
                                flags=re.IGNORECASE)

        for line in port_lines:
            line_match = line_pattern.search(line)
            if line_match is None:
                continue

            direction = IOType.INPUT if line_match.group(2).lower() == 'in' else IOType.OUTPUT
            ports.append(Port(line_match.group(1), direction, ValueType.convert(line_match.group(3))))

        return ports

    def parse_num_inputs(self, ports_list: list, hdl_content: str) -> int:
        size_var_name = None

        # Find the first port starting with 'const_size_in'
        for port in ports_list:
            if port.name.startswith('const_size_in'):
                size_var_name = port.name
                break

        if size_var_name is None:
            return None

        # Extract assignment value
        assign_pattern = re.compile(size_var_name + r'\s+<=\s+(\S+)\s*;', flags=re.IGNORECASE)
        assign_match = assign_pattern.search(hdl_content)

        if assign_match is None:
            return None

        constant_identifier = assign_match.group(1)

        # Find the constant definition
        const_pattern = re.compile(
            r'constant\s+' + constant_identifier +
            r'\s*:\s+std_logic_vector.+:=\s*"([01]+)"\s*;', flags=re.IGNORECASE)
        const_match = const_pattern.search(hdl_content)

        if const_match is None:
            return None

        return int(const_match.group(1), 2)

