from typing import List
import aiohttp
from . import helpers
from .typings import Application, Authentication, APC, DeviceList
from .const import DEVICE_LIST_URL, DEVICE_ATTR_URL, AUTH_URL, POWER_STATE_URL

class APCService:
    """ API Service for managing APC devices """
    def __init__(self, app_context: Application.Context):
        self._app_context = app_context
        self._connection_timeout = 30

    async def _execute_request(self, endpoint, headers: dict = None, payload=None, json_data=None):
        if self._auth_token:
            headers = headers or {}
            headers["Authorization"] = f"auth_token {self._auth_token}"

        async with aiohttp.ClientSession(timeout=self._connection_timeout) as session:
            if not payload and not json_data:
                async with session.get(endpoint, headers=headers) as resp:
                    return await resp.json()
            else:
                async with session.post(
                    endpoint, headers=headers, data=payload, json=json_data
                ) as resp:
                    return await resp.json()

    def _has_valid_credentials(self) -> bool:
        return bool(self._auth_token and self._refresh_token)

    async def authenticate(self, email_address: str, pwd: str):
        """ Authenticate user with credentials """
        if self._has_valid_credentials():
            return True

        auth_request: Authentication.Request = {}
        credentials = auth_request["user"]
        credentials["application"] = helpers.Application.as_payload(self._app_context)
        credentials["email"] = email_address
        credentials["password"] = pwd

        auth_response: Authentication.Response = await self._execute_request(AUTH_URL, json=auth_request)
        self._auth_token = auth_response["access_token"]
        self._refresh_token = auth_response["refresh_token"]
        return True

    async def fetch_devices(self):
        """ Retrieve all registered devices """
        if not self._has_valid_credentials():
            return None

        devices_list: List[APC.Device] = []
        raw_devices: List[dict] = await self._execute_request(DEVICE_LIST_URL)

        for raw_device in raw_devices:
            device = helpers.Devices.as_instance(raw_device)
            devices_list.append(device)

            device_outlets = await self._fetch_device_attributes(raw_device["serial_number"])
            for outlet in device_outlets:
                device.outlets.append(outlet)

        return devices_list

    async def _fetch_device_attributes(self, serial: str):
        if not self._has_valid_credentials():
            return None

        outlets_list: List[APC.Outlet] = []
        raw_outlets: List[dict] = await self._execute_request(DEVICE_ATTR_URL.format(dsn=serial))

        for raw_outlet in raw_outlets:
            outlets_list.append(helpers.Devices.as_outlet_instance(raw_outlet))

        return outlets_list

    async def update_power_state(self, outlet: APC.Outlet, is_on: bool):
        """ Update power state for a specific outlet """
        if not self._has_valid_credentials():
            return False

        power_command: Devices.PowerState = {}
        power_command["datapoint"] = {}
        datapoint = power_command["datapoint"]
        datapoint["value"] = bool(is_on)

        await self._execute_request(POWER_STATE_URL.format(**outlet), json=power_command)
        return True

# Calculate color distances using XKCD color palette
from binascii import unhexlify
from functools import lru_cache
from operator import itemgetter
import json
import click
import colormath.color_conversions as cv
import colormath.color_diff as cd
import colormath.color_objects as co
import seaborn as sns

assert 949 == len(sns.xkcd_rgb)  # e.g. 'very light green': '#d1ffbd'

def _hex_to_rgb(hx: str) -> tuple:
    hx = hx.lstrip('#')
    assert 6 == len(hx), hx
    r, g, b = unhexlify(hx)
    return r, g, b

def _hex_to_color(hx: str) -> co.sRGBColor:
    c = co.BaseRGBColor(*_hex_to_rgb(hx))
    return co.sRGBColor(c.rgb_r / 256,
                        c.rgb_g / 256,
                        c.rgb_b / 256)

@lru_cache()
def get_name_to_srgb() -> dict:
    keys = list(sns.xkcd_rgb.keys())
    return dict(zip(keys, sns.xkcd_palette(keys)))

def _red_check():
    red = co.BaseRGBColor(*_hex_to_rgb('#ff000d'), is_upscaled=True)
    assert red.is_upscaled
    red = get_name_to_srgb()['bright red']
    red = co.sRGBColor(*red)
    assert not red.is_upscaled
    assert '#ff000d' == red.get_rgb_hex() == sns.xkcd_rgb['bright red']

@lru_cache()
def get_color_by_name(name) -> co.sRGBColor:
    return co.sRGBColor(*get_name_to_srgb()[name])

def distance_between_colors(c1: co.sRGBColor,
                            c2: co.sRGBColor) -> float:
    assert isinstance(c1, co.sRGBColor), 'pass a proper color, please'
    return cd.delta_e_cie2000(cv.convert_color(c1, co.LabColor),
                              cv.convert_color(c2, co.LabColor))

def distance_to_all_colors(c1: co.sRGBColor, thresh_dist=22):
    dist = {name: distance_between_colors(c1, get_color_by_name(name))
            for name in sns.xkcd_rgb.keys()}
    dist = {name: round(distance, 2)
            for name, distance in sorted(dist.items(), key=itemgetter(1))
            if distance < thresh_dist}
    return dist

def demo():
    _red_check()
    red = get_color_by_name('bright red')
    for name in 'bright red,red,pink,purple,violet,blue'.split(','):
        d = distance_between_colors(red, get_color_by_name(name))
        print(round(d, 1), name)
    d = distance_to_all_colors(red)
    print('')
    print(json.dumps(d, indent=4))

@click.command()
@click.argument('rgb-hex')
def main(rgb_hex):
    d = distance_to_all_colors(_hex_to_color(rgb_hex))
    print(json.dumps(d, indent=4))

if __name__ == '__main__':
    main()

