from .. import types as tensor_types
from .schedule import Stage, create_schedule as generate_schedule

def build_scheme(input_tensors, operation_func):
    """Construct a quantization scheme for the given inputs and function.
    """
    if not isinstance(input_tensors, list):
        input_tensors = [input_tensors]
    return QuantizationScheme(input_tensors, operation_func)

def generate_schedule_from_quantization(scheme_obj, identifier=""):
    """Generate an execution schedule based on a quantization scheme.
    """
    return generate_schedule(scheme_obj.inputs, func=None, name=identifier)

class QuantizationScheme(object):
    """Represents a quantization configuration.
    """
    def __init__(self, input_list, compute_func):
        self.inputs = input_list
        self.func = compute_func

        # Run the function to establish connections and stages
        result = compute_func(*input_list)

        # Attach stages to the function object
        for operation, stage in Stage._mapping:
            compute_func.__setattr__(operation.name, operation)

    def reduce_precision(self, data_tensors, target_dtype):
        """Convert a (list of) tensor to a lower-precision integer representation.
        """
        if not isinstance(target_dtype, (tensor_types.Int, tensor_types.UInt)):
            raise RuntimeError("Precision reduction to non-integer type is prohibited")
        if not isinstance(data_tensors, list):
            data_tensors = [data_tensors]
        for tensor in data_tensors:
            tensor.dtype = target_dtype

    def apply_quantization(self, data_list, fixed_point_type):
        """Apply fixed-point quantization to a (list of) tensor.
        """
        if not isinstance(fixed_point_type, (tensor_types.Fixed, tensor_types.UFixed)):
            raise RuntimeError("Quantization to integer type is not supported")
        if not isinstance(data_list, list):
            data_list = [data_list]
        for tensor in data_list:
            tensor.dtype = fixed_point_type

