# Import necessary modules for GitLab operations and argument parsing
from .lib.utils import args_vs_config, choose_repo, get_config, mklog, print_output
from .lib.args import get_args

def fetch_repositories(args, gitlab_instance):
    repositories = []
    if not args.repositories and not args.groups:
        repositories.extend(gitlab_instance.get_all_repos())
    else:
        if args.repositories:
            repositories.extend(gitlab_instance.get_repos(args.repositories))
        if args.groups:
            repositories.extend(gitlab_instance.get_group_repos(args.groups))
    if args.interactive:
        repositories = choose_repo(repositories)
    return repositories

def fetch_members(args, gitlab_instance):
    if args.groups:
        groups = gitlab_instance.get_groups(args.groups)
        return gitlab_instance.get_members(groups, "groups")
    return gitlab_instance.get_members(fetch_repositories(args, gitlab_instance))

def main():
    # Parse command-line arguments
    args = get_args("GitLab")
    args.add_argument("-g", "--groups", nargs="+", help="GitLab group names")
    args = args.parse_args()

    # Setup logging based on verbosity level
    mklog(args.verbosity)

    # Load configuration and resolve token/destination
    config = get_config("GitLab")
    token, destination = args_vs_config(args, config)

    # Initialize GitLab client
    gitlab = GitLab(token, destination, args.protocol)

    # Define available commands and their actions
    command_actions = {
        "sync": lambda: gitlab.batch_run(gitlab.clone_or_pull, fetch_repositories(args, gitlab)),
        "status": lambda: gitlab.batch_run(gitlab.status, fetch_repositories(args, gitlab)),
        "jobs": lambda: gitlab.get_last_failed_jobs(fetch_repositories(args, gitlab)),
        "schedules": lambda: gitlab.get_pipeline_schedules(fetch_repositories(args, gitlab)),
        "members": lambda: fetch_members(args, gitlab),
    }

    # Execute the selected command and capture output
    result = command_actions[args.command]()
    print_output(result)

if __name__ == "__main__":
    main()

# Configuration classes for managing journal and application settings
from pathlib import Path
from typing import Dict, List
import toml
from dataclasses import dataclass

@dataclass
class EntryConfig:
    """Represents configuration details for a journal entry"""
    title: str
    location: Path

    def __str__(self) -> str:
        return f"{self.title} located at: {self.location}"

    def as_dict(self) -> dict:
        """Transform the object into dictionary format for TOML serialization"""
        return {"location": str(self.location)}

@dataclass
class WaldenAppConfig:
    """Holds configuration data for the Walden application"""
    settings_file: Path
    primary_journal_dir: Path
    journals: Dict[str, EntryConfig]

    def persist(self):
        """Save current configuration state to disk"""
        config_data = {
            journal_key: journal_value.as_dict()
            for journal_key, journal_value in self.journals.items()
        }
        config_data["settings_file"] = str(self.settings_file)
        config_data["primary_journal_dir"] = str(self.primary_journal_dir)
        self.settings_file.write_text(toml.dumps({"walden": config_data}))

