# Find the most frequent non-banned word in a paragraph
class Solution:
    def mostCommonWord(self, paragraph: str, banned: List[str]) -> str:
        # Normalize paragraph: replace non-alphanumeric chars with spaces and convert to lowercase
        normalized = "".join(char.lower() if char.isalnum() else " " for char in paragraph)

        # Count word frequencies
        word_counts = Counter(normalized.split())

        # Convert banned list to set for faster lookup
        banned_set = set(banned)

        # Sort by frequency (descending) then alphabetically (ascending)
        for word, freq in sorted(word_counts.items(), key=lambda item: (item[1], item[0]), reverse=True):
            if word not in banned_set:
                return word

