# Utility functions for data batching and sequence padding
import numpy as np
from typing import List

def create_batches(data: np.ndarray, batch_size: int):
    total_samples = data.shape[0]
    for start_idx in range(0, total_samples, batch_size):
        yield data[start_idx: start_idx + batch_size]

def pad_sequences_to_length(sequence_list: List, padding_token, target_length: int = -1):
    if target_length < 0:
        target_length = np.max([len(item) for item in sequence_list])

    for sequence in sequence_list:
        padding_needed = target_length - len(sequence)
        if padding_needed > 0:
            sequence.extend([padding_token] * padding_needed)

    return sequence_list

import torch
import torch.nn as nn
import torch.nn.functional as F
from .spectral_normalization import SpectralNorm
import logging

class Graph_GAN(nn.Module):
    """Legacy MPGAN implementation - updated version available in model.py"""
    def __init__(self, generator_model, config):
        super(Graph_GAN, self).__init__()
        self.config = config
        self.G = generator_model
        self.D = not generator_model
        self.config.spectral_norm = (
            self.config.spectral_norm_gen if self.G else self.config.spectral_norm_disc
        )
        self.config.batch_norm = self.config.batch_norm_gen if self.G else self.config.batch_norm_disc
        self.config.mp_iterations = self.config.mp_iters_gen if self.G else self.config.mp_iters_disc
        self.config.fe1_param = self.config.fe1g if self.G else self.config.fe1d

        if self.G:
            self.config.dea = False
        if self.D:
            self.config.lfc = False

        if self.G:
            self.initial_node_dim = (
                self.config.latent_node_size
                if self.config.latent_node_size
                else self.config.hidden_node_size
            )
        else:
            self.initial_node_dim = self.config.node_feat_size

        if not self.config.fe1_param:
            self.config.fe1_param = self.config.fe.copy()

        self.config.fn1_param = self.config.fn.copy()

        # Additional parameters for edge network
        extra_params = 0
        if self.config.pos_diffs:
            if self.config.deltacoords:
                if self.config.coords == "cartesian":
                    extra_params += 3
                elif self.config.coords == "polar" or self.config.coords == "polarrel":
                    extra_params += 2
            if self.config.deltar:
                extra_params += 1
        extra_params += int(self.config.int_diffs)

        if config.lfc:
            self.lfc = nn.Linear(
                config.lfc_latent_size, config.num_hits * self.initial_node_dim
            )

        # Edge and node networks (ModuleLists of ModuleLists)
        # Dimensions: # of MP layers × # of FC layers per MP layer
        self.edge_nets = nn.ModuleList()
        self.node_nets = nn.ModuleList()

        if self.config.batch_norm:
            self.edge_bn = nn.ModuleList()
            self.node_bn = nn.ModuleList()

        # Build first MP layer networks
        self.config.fe1_input_dim = (
            2 * self.initial_node_dim
            + extra_params
            + self.config.clabels_first_layer
            + self.config.mask_fne_np
        )
        self.config.fe1_param.insert(0, self.config.fe1_input_dim)
        self.config.fe1_output_dim = self.config.fe1_param[-1]

        fe_layer = nn.ModuleList()
        if self.config.batch_norm:
            bne_layer = nn.ModuleList()

        for j in range(len(self.config.fe1_param) - 1):
            linear = nn.Linear(self.config.fe1_param[j], self.config.fe1_param[j + 1])
            fe_layer.append(linear)
            if self.config.batch_norm:
                bne_layer.append(nn.BatchNorm1d(self.config.fe1_param[j + 1]))

        self.edge_nets.append(fe_layer)
        if self.config.batch_norm:
            self.edge_bn.append(bne_layer)

        self.config.fn1_param.insert(
            0,
            self.config.fe1_output_dim
            + self.initial_node_dim
            + self.config.clabels_first_layer
            + self.config.mask_fne_np,
        )
        self.config.fn1_param.append(self.config.hidden_node_size)

        fn_layer = nn.ModuleList()
        if self.config.batch_norm:
            bnn_layer = nn.ModuleList()

        for j in range(len(self.config.fn1_param) - 1):
            linear = nn.Linear(self.config.fn1_param[j], self.config.fn1_param[j + 1])
            fn_layer.append(linear)
            if self.config.batch_norm:
                bnn_layer.append(nn.BatchNorm1d(self.config.fn1_param[j + 1]))

        self.node_nets.append(fn_layer)
        if self.config.batch_norm:
            self.node_bn.append(bnn_layer)

        # Build networks for remaining MP layers
        self.config.fe_input_dim = (
            2 * self.config.hidden_node_size
            + extra_params
            + self.config.clabels_hidden_layers
            + self.config.mask_fne_np
        )
        self.config.fe_param = self.config.fe.copy()
        self.config.fe_param.insert(0, self.config.fe_input_dim)
        self.config.fe_output_dim = self.config.fe_param[-1]

        self.config.fn_param = self.config.fn.copy()
        self.config.fn_param.insert(
            0,
            self.config.fe_output_dim
            + self.config.hidden_node_size
            + self.config.clabels_hidden_layers
            + self.config.mask_fne_np,
        )
        self.config.fn_param.append(self.config.hidden_node_size)

        for i in range(self.config.mp_iterations - 1):
            fe_layer = nn.ModuleList()
            if self.config.batch_norm:
                bne_layer = nn.ModuleList()

            for j in range(len(self.config.fe_param) - 1):
                linear = nn.Linear(self.config.fe_param[j], self.config.fe_param[j + 1])
                fe_layer.append(linear)
                if self.config.batch_norm:
                    bne_layer.append(nn.BatchNorm1d(self.config.fe_param[j + 1]))

            self.edge_nets.append(fe_layer)
            if self.config.batch_norm:
                self.edge_bn.append(bne_layer)

            fn_layer = nn.ModuleList()
            if self.config.batch_norm:
                bnn_layer = nn.ModuleList()

            for j in range(len(self.config.fn_param) - 1):
                linear = nn.Linear(self.config.fn_param[j], self.config.fn_param[j + 1])
                fn_layer.append(linear)
                if self.config.batch_norm:
                    bnn_layer.append(nn.BatchNorm1d(self.config.fn_param[j + 1]))

            self.node_nets.append(fn_layer)
            if self.config.batch_norm:
                self.node_bn.append(bnn_layer)

        # Final discriminator FCN
        if self.config.dea:
            self.config.fnd_param = self.config.fnd.copy()
            self.config.fnd_param.insert(0, self.config.hidden_node_size + int(self.config.mask_fnd_np))
            self.config.fnd_param.append(1)
            self.disc_final = nn.ModuleList()
            self.disc_bn = nn.ModuleList()

            for i in range(len(self.config.fnd_param) - 1):
                linear = nn.Linear(self.config.fnd_param[i], self.config.fnd_param[i + 1])
                self.disc_final.append(linear)
                if self.config.batch_norm:
                    self.disc_bn.append(nn.BatchNorm1d(self.config.fnd_param[i + 1]))

        # Initial generator mask FCN
        if (
            self.G
            and (hasattr(self.config, "mask_learn") and self.config.mask_learn)
            or (hasattr(self.config, "mask_learn_sep") and self.config.mask_learn_sep)
        ):
            self.config.fmg_param = self.config.fmg.copy()
            self.config.fmg_param.insert(0, self.initial_node_dim)
            self.config.fmg_param.append(1 if self.config.mask_learn else self.config.num_hits)
            self.gen_mask_net = nn.ModuleList()
            self.gen_mask_bn = nn.ModuleList()

            for i in range(len(self.config.fmg_param) - 1):
                linear = nn.Linear(self.config.fmg_param[i], self.config.fmg_param[i + 1])
                self.gen_mask_net.append(linear)
                if self.config.batch_norm:
                    self.gen_mask_bn.append(nn.BatchNorm1d(self.config.fmg_param[i + 1]))

        p = self.config.gen_dropout if self.G else self.config.disc_dropout
        self.dropout_layer = nn.Dropout(p=p)

        if self.config.glorot:
            self.initialize_weights()

        if self.config.spectral_norm:
            for ml in self.edge_nets:
                for i in range(len(ml)):
                    ml[i] = SpectralNorm(ml[i])
            for ml in self.node_nets:
                for i in range(len(ml)):
                    ml[i] = SpectralNorm(ml[i])
            if self.config.dea:
                for i in range(len(self.disc_final)):
                    self.disc_final[i] = SpectralNorm(self.disc_final[i])
            if self.config.mask_learn:
                for i in range(len(self.gen_mask_net)):
                    self.gen_mask_net[i] = SpectralNorm(self.gen_mask_net[i])

        if self.config.lfc:
            logging.info("lfcn: ")
            logging.info(self.lfc)

        logging.info("fe: ")
        logging.info(self.edge_nets)
        logging.info("fn: ")
        logging.info(self.node_nets)

        if self.config.dea:
            logging.info("fnd: ")
            logging.info(self.disc_final)

        if (
            self.G
            and (hasattr(self.config, "mask_learn") and self.config.mask_learn)
            or (hasattr(self.config, "mask_learn_sep") and self.config.mask_learn_sep)
        ):
            logging.info("fmg: ")
            logging.info(self.gen_mask_net)

    def forward(self, x, labels=None, epoch=0):
        batch_size = x.shape[0]
        logging.debug(f"x: {x}")

        if self.config.lfc:
            x = self.lfc(x).reshape(batch_size, self.config.num_hits, self.initial_node_dim)
            logging.debug(f"LFC'd x: {x}")

        try:
            mask_bool = (
                (
                    self.D
                    and (
                        self.config.mask_manual
                        or self.config.mask_real_only
                        or self.config.mask_learn
                        or self.config.mask_c
                        or self.config.mask_learn_sep
                    )
                )
                or (
                    self.G
                    and (self.config.mask_learn or self.config.mask_c or self.config.mask_learn_sep)
                )
                and epoch >= self.config.mask_epoch
            )

            if self.D and (mask_bool or self.config.mask_fnd_np):
                mask = x[:, :, 3:4] + 0.5

            if self.D and (
                self.config.mask_manual
                or self.config.mask_learn
                or self.config.mask_c
                or self.config.mask_learn_sep
            ):
                x = x[:, :, :3]

            if self.G and self.config.mask_learn:
                mask = F.leaky_relu(self.gen_mask_net[0](x), negative_slope=self.config.leaky_relu_alpha)
                if self.config.batch_norm:
                    mask = self.gen_mask_bn[0](mask)
                mask = self.dropout_layer(mask)

                for i in range(len(self.gen_mask_net) - 1):
                    mask = F.leaky_relu(
                        self.gen_mask_net[i + 1](mask), negative_slope=self.config.leaky_relu_alpha
                    )
                    if self.config.batch_norm:
                        mask = self.gen_mask_bn[i](mask)
                    mask = self.dropout_layer(mask)

                mask = torch.sign(mask) if self.config.mask_learn_bin else torch.sigmoid(mask)
                logging.debug("gen mask \n {}".format(mask[:2, :, 0]))

            if self.G and self.config.mask_c:
                nump = (labels[:, self.config.clabels] * self.config.num_hits).int() - 1
                mask = (x[:, :, 0].argsort(1).argsort(1) <= nump.unsqueeze(1)).unsqueeze(2).float()
                logging.debug(
                    "x \n {} \n num particles \n {} \n gen mask \n {}".format(
                        x[:2, :, 0], nump[:2], mask[:2, :, 0]
                    )
                )

            if self.config.mask_fne_np:
                nump = torch.mean(mask, dim=1)
                logging.debug("nump \n {}".format(nump[:2]))

            if self.G and self.config.mask_learn_sep:
                nump = x[:, -1, :]
                x = x[:, :-1, :]

                for i in range(len(self.gen_mask_net)):
                    nump = F.leaky_relu(
                        self.gen_mask_net[i](nump), negative_slope=self.config.leaky_relu_alpha
                    )
                    if self.config.batch_norm:
                        nump = self.gen_mask_bn[i](nump)
                    nump = self.dropout_layer(nump)

                nump = torch.argmax(nump, dim=1)
                mask = (x[:, :, 0].argsort(1).argsort(1) <= nump.unsqueeze(1)).unsqueeze(2).float()
                logging.debug(
                    "x \n {} \n num particles \n {} \n gen mask \n {}".format(
                        x[:2, :, 0], nump[:2], mask[:2, :, 0]
                    )
                )
        except AttributeError:
            mask_bool = False

        if not mask_bool:
            mask = None

        for i in range(self.config.mp_iterations):
            clabel_iter = self.config.clabels and (
                (i == 0 and self.config.clabels_first_layer)
                or (i and self.config.clabels_hidden_layers)
            )
            node_dim = x.size(2)
            fe_in_size = self.config.fe_input_dim if i else self.config.fe1_input_dim
            fe_out_size = self.config.fe_output_dim if i else self.config.fe1_output_dim

            if clabel_iter:
                fe_in_size -= self.config.clabels
            if self.config.mask_fne_np:
                fe_in_size -= 1

            # Message passing
            A, A_mask = self.getA(x, i, batch_size, fe_in_size, mask_bool, mask)

            num_knn = (
                self.config.num_hits
                if (hasattr(self.config, "fully_connected") and self.config.fully_connected)
                else self.config.num_knn
            )

            if (A != A).any():
                logging.warning("Nan values in A \n x: \n {} \n A: \n {}".format(x, A))

            if clabel_iter:
                A = torch.cat((A, labels.repeat(self.config.num_hits * num_knn, 1)), axis=1)
            if self.config.mask_fne_np:
                A = torch.cat((A, nump.repeat(self.config.num_hits * num_knn, 1)), axis=1)

            for j in range(len(self.edge_nets[i])):
                A = F.leaky_relu(self.edge_nets[i][j](A), negative_slope=self.config.leaky_relu_alpha)
                if self.config.batch_norm:
                    A = self.edge_bn[i][j](A)
                A = self.dropout_layer(A)

            if (A != A).any():
                logging.warning(
                    "Nan values in A after message passing \n x: \n {} \n A: \n {}".format(x, A)
                )

            # Message aggregation into new features
            A = A.view(batch_size, self.config.num_hits, num_knn, fe_out_size)
            if mask_bool:
                if self.config.fully_connected:
                    A = A * mask.unsqueeze(1)
                else:
                    A = A * A_mask.reshape(batch_size, self.config.num_hits, num_knn, 1)

            A = torch.sum(A, 2) if self.config.sum else torch.mean(A, 2)
            x = torch.cat((A, x), 2).view(batch_size * self.config.num_hits, fe_out_size + node_dim)

            if (x != x).any():
                logging.warning(
                    "Nan values in x after message passing \n x: \n {} \n A: \n {}".format(x, A)
                )

            if clabel_iter:
                x = torch.cat((x, labels.repeat(self.config.num_hits, 1)), axis=1)
            if self.config.mask_fne_np:
                x = torch.cat((x, nump.repeat(self.config.num_hits, 1)), axis=1)

            for j in range(len(self.node_nets[i]) - 1):
                x = F.leaky_relu(self.node_nets[i][j](x), negative_slope=self.config.leaky_relu_alpha)
                if self.config.batch_norm:
                    x = self.node_bn[i][j](x)
                x = self.dropout_layer(x)

            x = self.dropout_layer(self.node_nets[i][-1](x))
            x = x.view(batch_size, self.config.num_hits, self.config.hidden_node_size)

            if (x != x).any():
                logging.warning("Nan values in x after fn \n x: \n {} \n A: \n {}".format(x, A))

        if self.G:
            x = (
                torch.tanh(x[:, :, : self.config.node_feat_size])
                if self.config.gtanh
                else x[:, :, : self.config.node_feat_size]
            )
            if mask_bool:
                x = torch.cat((x, mask - 0.5), dim=2)
            if hasattr(self.config, "mask_feat_bin") and self.config.mask_feat_bin:
                mask = (
                    x[:, :, 3:4] < 0
                ).float() - 0.5
                x = torch.cat((x[:, :, :3], mask), dim=2)
            return x
        else:
            if self.config.dea:
                if mask_bool:
                    x = x * mask
                    x = torch.sum(x, 1)
                    if not self.config.sum:
                        x = x / (torch.sum(mask, 1) + 1e-12)
                else:
                    x = torch.sum(x, 1) if self.config.sum else torch.mean(x, 1)

                if hasattr(self.config, "mask_fnd_np") and self.config.mask_fnd_np:
                    num_particles = torch.mean(mask, dim=1)
                    x = torch.cat((num_particles, x), dim=1)

                for i in range(len(self.disc_final) - 1):
                    x = F.leaky_relu(self.disc_final[i](x), negative_slope=self.config.leaky_relu_alpha)
                    if self.config.batch_norm:
                        x = self.disc_bn[i](x)
                    x = self.dropout_layer(x)

                x = self.dropout_layer(self.disc_final[-1](x))
            else:
                x = x[:, :, :1]
                if mask_bool:
                    logging.debug("D output pre mask")
                    logging.debug(mask[:2, :, 0])
                    logging.debug(x[:2, :, 0])
                    x = x * mask
                    logging.debug("post mask")
                    logging.debug(x[:2, :, 0])
                    x = torch.sum(x, 1) / (torch.sum(mask, 1) + 1e-12)
                else:
                    x = torch.mean(x, 1)

            return x if (self.config.loss == "w" or self.config.loss == "hinge") else torch.sigmoid(x)

    def getA(self, x, i, batch_size, fe_in_size, mask_bool, mask):
        node_dim = x.size(2)
        num_coords = 3 if self.config.coords == "cartesian" else 2
        A_mask = None

        if self.config.fully_connected:
            x1 = x.repeat(1, 1, self.config.num_hits).view(
                batch_size, self.config.num_hits * self.config.num_hits, node_dim
            )
            x2 = x.repeat(1, self.config.num_hits, 1)

            if self.config.pos_diffs:
                if self.config.all_ef and not (self.D and i == 0):
                    diffs = x2 - x1
                else:
                    diffs = x2[:, :, :num_coords] - x1[:, :, :num_coords]

                dists = torch.norm(diffs + 1e-12, dim=2).unsqueeze(2)

                if self.config.deltar and self.config.deltacoords:
                    A = torch.cat((x1, x2, diffs, dists), 2)
                elif self.config.deltar:
                    A = torch.cat((x1, x2, dists), 2)
                elif self.config.deltacoords:
                    A = torch.cat((x1, x2, diffs), 2)

                A = A.view(batch_size * self.config.num_hits * self.config.num_hits, fe_in_size)
            else:
                A = torch.cat((x1, x2), 2).view(
                    batch_size * self.config.num_hits * self.config.num_hits, fe_in_size
                )
        else:
            x1 = x.repeat(1, 1, self.config.num_hits).view(
                batch_size, self.config.num_hits * self.config.num_hits, node_dim
            )

            if mask_bool:
                mul = 1e4
                x2 = (((1 - mul) * mask + mul) * x).repeat(1, self.config.num_hits, 1)
            else:
                x2 = x.repeat(1, self.config.num_hits, 1)

            if (self.config.all_ef or not self.config.pos_diffs) and not (self.D and i == 0):
                diffs = x2 - x1
            else:
                diffs = x2[:, :, :num_coords] - x1[:, :, :num_coords]

            dists = torch.norm(diffs + 1e-12, dim=2).reshape(
                batch_size, self.config.num_hits, self.config.num_hits
            )

            sorted = torch.sort(dists, dim=2)
            self_loops = int(self.config.self_loops is False)

            dists = sorted[0][:, :, self_loops : self.config.num_knn + self_loops].reshape(
                batch_size, self.config.num_hits * self.config.num_knn, 1
            )
            sorted_indices = sorted[1][:, :, self_loops : self.config.num_knn + self_loops].reshape(
                batch_size, self.config.num_hits * self.config.num_knn, 1
            )

            sorted_indices.repeat(1, 1, node_dim)

            x1_knn = x.repeat(1, 1, self.config.num_knn).view(
                batch_size, self.config.num_hits * self.config.num_knn, node_dim
            )

            if mask_bool:
                x2_knn = torch.gather(
                    torch.cat((x, mask), dim=2), 1, sorted_indices.repeat(1, 1, node_dim + 1)
                )
                A_mask = x2_knn[:, :, -1:]
                x2_knn = x2_knn[:, :, :-1]
            else:
                x2_knn = torch.gather(x, 1, sorted_indices.repeat(1, 1, node_dim))

            if self.config.pos_diffs:
                A = torch.cat((x1_knn, x2_knn, dists), dim=2)
            else:
                A = torch.cat((x1_knn, x2_knn), dim=2)

        return A, A_mask

    def initialize_weights(self):
        logging.info("glorot-ing")
        for m in self.modules():
            if isinstance(m, nn.Linear):
                torch.nn.init.xavier_uniform(m.weight, self.config.glorot)

    def load(self, backup):
        for m_from, m_to in zip(backup.modules(), self.modules()):
            if isinstance(m_to, nn.Linear):
                m_to.weight.data = m_from.weight.data.clone()
                if m_to.bias is not None:
                    m_to.bias.data = m_from.bias.data.clone()

    def reset_parameters(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                m.reset_parameters()

