# Modified version of the Rubrik Salt module with renamed variables and reordered logic
import time as t
import logging as lg
import sys as s
import json as j
import base64 as b64
import requests as r
import salt as slt
import datetime as dt

s.path.append('/var/cache/salt/minion/files/extmods/modules/')

r.packages.urllib3.disable_warnings()
LOG = lg.getLogger(__name__)

def __virtual__():
    return True

def _get_auth_header():
    if s.version_info < (3,):
        return b64.b64encode(slt.__salt__['pillar.get']('rubrik.username','')+":"+slt.__salt__['pillar.get']('rubrik.password',''))
    else:
        return b64.b64encode(bytes(slt.__salt__['pillar.get']('rubrik.username','')+':'+slt.__salt__['pillar.get']('rubrik.password',''),'utf-8'))

def _get_token():
    '''
    Return a token given API credentials provided via pillar
    '''
    try:
        node = slt.__salt__['pillar.get']('rubrik.node','')
        uri = ('https://'+node+'/api/v1/session')
        auth_header = 'Basic {0}'.format(_get_auth_header().decode("utf-8"))
        hdrs = {'Content-Type':'application/json', 'Authorization':auth_header}
        resp = r.post(uri, headers=hdrs, verify=False)
        if resp.status_code == 422:
            raise ValueError("Authentication failed with the Rubrik cluster")
        token = str(j.loads(resp.text)["token"])
        return ('Bearer {0}'.format(token))
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error("Rubrik node connection issues. Please check Rubrik node IP address or hostname in the YAML configuration file, error: "+str(ex))
        return ("Rubrik node connection issues. Please check Rubrik node IP address or hostname in the YAML configuration file, error: "+str(ex))

def cluster_info():
    '''
    Return information for the Rubrik cluster
    '''
    try:
        token = _get_token()
        node = slt.__salt__['pillar.get']('rubrik.node','')
        uri = ('https://'+node+'/api/v1/cluster/me')
        hdrs = {'Accept':'application/json', 'Authorization':token}
        response = r.get(uri, headers=hdrs, verify=False, timeout=15)
        data = response.json()
        cluster_data = {
            "id": data['id'],
            "version": data['version'],
            "apiVersion": data['apiVersion']
        }
        return j.dumps(cluster_data, sort_keys=True, indent=2, separators=(',', ': '))
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error("Something went wrong getting the Rubrik cluster information, error: "+str(ex))
        return ("Something went wrong getting the Rubrik cluster information, error: "+str(ex))

def get_vmware_vm_sla(hostname=None):
    '''
    Returns the SLA for the given vSphere VM
    '''
    try:
        if not hostname:
            hostname = slt.__grains__['id']
        token = _get_token()
        node = slt.__salt__['pillar.get']('rubrik.node','')
        my_vm = False
        uri = 'https://'+node+'/api/v1/vmware/vm?primary_cluster_id=local&is_relic=false&name='+hostname
        hdrs = {'Accept':'application/json', 'Authorization':token}
        vm_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        for vm in vm_query.json()['data']:
            if vm['name'] == hostname:
                my_vm = vm
        if not my_vm:
            LOG.error("VMware VM not found.")
            raise ValueError("VMware VM not found")
        return ("Current SLA domain is: "+my_vm['effectiveSlaDomainName'])
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error('Something went wrong getting the SLA Domain for this VM, error: '+str(ex))
        return ('Something went wrong getting the SLA Domain for this VM, error: '+str(ex))

def set_vmware_vm_sla(hostname=None,sla_domain=None):
    '''
    Updates the SLA for the given vSphere VM
    '''
    try:
        if not hostname:
            hostname = slt.__grains__['id']
        if not sla_domain:
            LOG.error("No SLA Domain name passed")
            raise ValueError("No SLA Domain name passed")
        token = _get_token()
        node = slt.__salt__['pillar.get']('rubrik.node','')
        my_vm = False
        uri = 'https://'+node+'/api/v1/vmware/vm?primary_cluster_id=local&is_relic=false&name='+hostname
        hdrs = {'Accept':'application/json', 'Authorization':token}
        vm_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        for vm in vm_query.json()['data']:
            if vm['name'] == hostname:
                my_vm = vm
        if not my_vm:
            LOG.error("VMware VM not found.")
            raise ValueError("VMware VM not found")
        if my_vm['effectiveSlaDomainName'] == sla_domain:
            LOG.info('SLA Domain already set to '+sla_domain)
            return ('SLA Domain already set to '+sla_domain)
        else:
            my_sla = False
            uri = 'https://'+node+'/api/v1/sla_domain?primary_cluster_id=local&name='+sla_domain
            hdrs = {'Accept':'application/json', 'Authorization':token}
            sla_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
            for sla in sla_query.json()['data']:
                if sla['name'] == sla_domain:
                    my_sla = sla
            if not my_sla:
                LOG.error("SLA domain not found.")
                raise ValueError("SLA domain not found")
            uri = 'https://'+node+'/api/v1/vmware/vm/'+my_vm['id']
            hdrs = {'Content-Type':'application/json','Accept':'application/json','Authorization':token}
            payload = '{"configuredSlaDomainId":"'+my_sla['id']+'"}'
            update_sla = r.patch(uri, headers=hdrs, verify=False, data=payload)
            if update_sla.status_code != 200:
                raise ValueError("Something went wrong setting the SLA Domain")
            LOG.info('SLA Domain updated to '+sla_domain)
            return ('SLA Domain updated to '+sla_domain)
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error('Something went wrong setting the SLA Domain for this VM, error: '+str(ex))
        return ('Something went wrong setting the SLA Domain for this VM, error: '+str(ex))

def od_backup_vmware_vm(hostname=None,sla_domain=None,object_type='vmware_vm',wait_for_completion=False):
    '''
    Takes an on-demand snapshot for the given machine and policy
    '''
    try:
        if not hostname:
            hostname = slt.__grains__['id']
        if not sla_domain:
            LOG.error("No SLA Domain name passed")
            raise ValueError("No SLA Domain name passed")
        token = _get_token()
        node = slt.__salt__['pillar.get']('rubrik.node','')
        uri = ('https://'+node+'/api/v1/vmware/vm?primary_cluster_id=local&is_relic=false&name='+hostname)
        hdrs = {'Accept':'application/json', 'Authorization':token}
        vm_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        for vm in vm_query.json()['data']:
            if vm['name'] == hostname:
                my_vm = vm
        if not my_vm:
            LOG.error("VMware VM not found.")
            raise ValueError("VMware VM not found")
        my_sla = False
        uri = ('https://'+node+'/api/v1/sla_domain?primary_cluster_id=local&name='+sla_domain)
        sla_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        for sla in sla_query.json()['data']:
            if sla['name'] == sla_domain:
                my_sla = sla
        if not my_sla:
            LOG.error("SLA domain not found.")
            raise ValueError("SLA domain not found")
        uri = ('https://'+node+'/api/v1/vmware/vm/'+my_vm['id']+'/snapshot')
        hdrs = {'Content-Type':'application/json','Accept':'application/json','Authorization':token}
        payload = '{"slaId":"'+my_sla['id']+'"}'
        take_snapshot = r.post(uri, headers=hdrs, verify=False, data=payload)
        if take_snapshot.status_code != 202:
            raise ValueError("Something went wrong setting the SLA Domain")
        task_id = take_snapshot.json()["id"]
        LOG.info('Snapshot taken with task ID: '+task_id)
        if wait_for_completion:
            status = take_snapshot.json()["status"]
            while status not in ['SUCCEEDED','FAILED','WARNING']:
                t.sleep(5)
                uri = ('https://'+node+'/api/v1/vmware/vm/request/'+task_id)
                task_status = r.get(uri, headers=hdrs, verify=False)
                status = task_status.json()["status"]
            LOG.info('Snapshot finished with status: '+status)
            return ('Snapshot finished with status: '+status)
        else:
            return ('Snapshot taken with task ID: '+task_id)
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error('Something went wrong taking an on-demand snapshot for this VM, error: '+str(ex))
        return ('Something went wrong taking an on-demand snapshot for this VM, error: '+str(ex))

def register_host(hostname=None):
    '''
    Registers the host against the Rubrik cluster - requires that the Rubrik Backup Connector be installed,
    and that DNS resolution to the hostname be working correctly (otherwise IP address can be passed using the
    'hostname' parameter)
    '''
    try:
        if not hostname:
            hostname = slt.__grains__['id']
        token = _get_token()
        node = slt.__salt__['pillar.get']('rubrik.node','')
        uri = 'https://'+node+'/api/v1/host'
        hdrs = {'Content-Type':'application/json','Accept':'application/json','Authorization':token}
        payload = '{"hostname":"'+hostname+'","hasAgent":true}'
        register_host = r.post(uri, headers=hdrs, verify=False, data=payload)
        if register_host.status_code != 201:
            raise ValueError("Status code: "+str(register_host.status_code)+", message: "+register_host.json()["message"])
        data = register_host.json()
        message = 'Host registered as '+hostname+', host ID is '+data['id']
        LOG.info(message)
        return message
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error('Something went wrong registering the host, error: '+str(ex))
        return ('Something went wrong registering the host, error: '+str(ex))

def get_host_registration(hostname=None,os_type='Linux'):
    '''
    Checks the host registration status, returning a boolean value (true=registered, false=not_registered)
    '''
    try:
        host_registered = False
        if not hostname:
            hostname = slt.__grains__['id']
        token = _get_token()
        if os_type == 'Linux':
            os_type = 'UnixLike'
        elif os_type == 'Windows':
            os_type = 'Windows'
        node = slt.__salt__['pillar.get']('rubrik.node','')
        uri = 'https://'+node+'/api/v1/host?primary_cluster_id=local&operating_system_type='+os_type+'&name='+hostname
        hdrs = {'Accept':'application/json', 'Authorization':token}
        host_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        if host_query.json()['total'] == 0:
            host_registered = False
        else:
            for host in host_query.json()['data']:
                if host['name'] == hostname:
                    host_registered = True
        message = ('Host registration status for: '+hostname+', OS type: '+os_type+' is: '+str(host_registered))
        LOG.info(message)
        return host_registered
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error('Something went wrong getting host registration status, error: '+str(ex))
        return ('Something went wrong getting host registration status, error: '+str(ex))

def add_fileset_to_host(hostname=None,fileset_name=None,sla_domain=None,os_type='Linux'):
    '''
    Adds a fileset to a Windows/Linux/Unix host
    '''
    try:
        if not hostname:
            hostname = slt.__grains__['id']
        if not sla_domain:
            LOG.error("No SLA Domain name passed")
            raise ValueError("No SLA Domain name passed")
        if not fileset_name:
            LOG.error("No Fileset Template name passed")
            raise ValueError("No Fileset Template name passed")
        token = _get_token()
        if os_type == 'Linux':
            os_type = 'UnixLike'
        elif os_type == 'Windows':
            os_type = 'Windows'
        node = slt.__salt__['pillar.get']('rubrik.node','')
        my_host = False
        uri = 'https://'+node+'/api/v1/host?primary_cluster_id=local&operating_system_type='+os_type+'&name='+hostname
        hdrs = {'Accept':'application/json', 'Authorization':token}
        host_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        for host in host_query.json()['data']:
            if host['name'] == hostname:
                my_host = host
        if not my_host:
            LOG.error("Host not found.")
            raise ValueError("Host not found")
        my_fst = False
        uri = 'https://'+node+'/api/v1/fileset_template?primary_cluster_id=local&operating_system_type='+os_type+'&name='+fileset_name
        fst_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        for fst in fst_query.json()['data']:
            if fst['name'] == fileset_name:
                my_fst = fst
        if not my_fst:
            LOG.error("Fileset template not found.")
            raise ValueError("Fileset template not found")
        my_sla = False
        uri = 'https://'+node+'/api/v1/sla_domain?primary_cluster_id=local&name='+sla_domain
        sla_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        for sla in sla_query.json()['data']:
            if sla['name'] == sla_domain:
                my_sla = sla
        if not my_sla:
            LOG.error("SLA domain not found.")
            raise ValueError("SLA domain not found")
        fileset_id = False
        uri = 'https://'+node+'/api/v1/fileset?primary_cluster_id=local&is_relic=false&host_id='+my_host['id']+'&template_id='+my_fst['id']
        fileset_query = r.get(uri, headers=hdrs, verify=False, timeout=15)
        if fileset_query.json()['total'] > 0:
            fileset_id = fileset_query.json()['data'][0]['id']
        if not fileset_id:
            uri = 'https://'+node+'/api/v1/fileset'
            hdrs = {'Content-Type':'application/json','Accept':'application/json','Authorization':token}
            payload = '{"hostId":"'+my_host['id']+'","templateId":"'+my_fst['id']+'"}'
            create_fileset = r.post(uri, headers=hdrs, verify=False, data=payload)
            if create_fileset.status_code != 201:
                raise ValueError("Something went wrong creating the fileset")
            data = create_fileset.json()
            fileset_id = data['id']
        uri = 'https://'+node+'/api/v1/fileset/'+fileset_id
        hdrs = {'Content-Type':'application/json','Accept':'application/json','Authorization':token}
        payload = '{"configuredSlaDomainId":"'+my_sla['id']+'"}'
        register_host = r.patch(uri, headers=hdrs, verify=False, data=payload)
        if register_host.status_code != 200:
            raise ValueError("Something went wrong applying the SLA to the fileset")
        data = register_host.json()
        message = 'Fileset created, ID is '+fileset_id+'. SLA '+my_sla['name']+' applied.'
        LOG.info(message)
        return message
    except Exception as ex:
        lg_tuple = s.exc_info()
        LOG.error('Something went wrong creating the fileset, error: '+str(ex))
        return ('Something went wrong creating the fileset, error: '+str(ex))

