        self.StrictChecks = self.__TryParseStrictChecks(log, xmlElement)  # Optional[type: XmlClangTidyPlatformStrictChecks]

    def __TryParseCompiler(self, log: Log, xmlElement: ET.Element) -> Optional[XmlClangTidyPlatformCompiler]:
        elements = xmlElement.findall("Compiler")
        if len(elements) > 1:
            raise XmlException2("Only one 'Compiler' element is allowed within a ClangTidyConfiguration.Platform")
        if not elements:
            return None
        return XmlClangTidyPlatformCompiler(log, elements[0])

    def __TryParseDefines(self, log: Log, xmlElement: ET.Element) -> Optional[XmlClangTidyPlatformDefines]:
        elements = xmlElement.findall("Defines")
        if len(elements) > 1:
            raise XmlException2("Only one 'Defines' element is allowed within a ClangTidyConfiguration.Platform")
        if not elements:
            return None
        return XmlClangTidyPlatformDefines(log, elements[0])

    def __TryParseStrictChecks(self, log: Log, xmlElement: ET.Element) -> Optional[XmlClangTidyPlatformStrictChecks]:
        elements = xmlElement.findall("StrictChecks")
        if len(elements) > 1:
            raise XmlException2("Only one 'StrictChecks' element is allowed within a ClangTidyConfiguration.Platform")
