API_TOKEN = os.environ.get("LEETIFY_API_KEY")
if not API_TOKEN:
    print(json.dumps({"error": "LEETIFY_API_KEY environment variable not set"}))
    sys.exit(1)

BASE_URL = "https://api-public.cs-prod.leetify.com"

def make_api_call(path, query_params=None):
    auth_headers = {"Authorization": f"Bearer {API_TOKEN}"}
    full_url = f"{BASE_URL}{path}"

    try:
        api_response = requests.get(full_url, params=query_params, headers=auth_headers)
        if api_response.status_code == 200:
            return {"success": True, "payload": api_response.json()}
        else:
            return {"success": False, "message": f"{api_response.status_code} {api_response.text}"}
    except Exception as ex:
        return {"success": False, "message": str(ex)}

def fetch_player_match_details(player_steam_id, match_position=0):
    # Step 1: Retrieve list of recent matches
    result = make_api_call('/v3/profile/matches', {'steam64_id': player_steam_id, 'limit': match_position + 1})

    if not result['success']:
        print(json.dumps({"error": result.get('message')}))
        return

    match_list = result['payload']

    # Handle both direct list and wrapped response formats
    if isinstance(match_list, dict) and 'matches' in match_list:
        match_list = match_list['matches']

    if not isinstance(match_list, list):
        print(json.dumps({"error": "Unexpected API response format"}))
        return

    if len(match_list) <= match_position:
        print(json.dumps({"error": f"Match index {match_position} not found. Total matches: {len(match_list)}"}))
        return

    selected_match = match_list[match_position]

    # Step 2: Extract specific player statistics from the match
    player_data = next((p for p in selected_match.get('stats', []) if p['steam64_id'] == player_steam_id), None)

    if not player_data:
        print(json.dumps({"error": "Player stats not found in this match"}))
        return

    # Step 3: Build the analysis data structure
    output_data = {
        "metadata": {
            "map_name": selected_match.get('map_name'),
            "timestamp": selected_match.get('finished_at'),
            "scores": selected_match.get('team_scores'),
            "source": selected_match.get('data_source'),
            "match_identifier": selected_match.get('id')
        },
        # Contains detailed metrics like accuracy, sprays, counter-strafing, utility usage,
        # trade stats, entry stats, clutch opportunities, etc.
        "player_stats": player_data 
    }

    # Output JSON for downstream processing
    print(json.dumps(output_data, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--username", required=True)
    parser.add_argument("--position", type=int, default=0)
    arguments = parser.parse_args()

    current_script_path = os.path.dirname(os.path.abspath(__file__))
    try:
        # Convert username to Steam ID
        steam_id_output = subprocess.check_output(
            ['python3', os.path.join(current_script_path, 'steam_ids.py'), 'get', '--username', arguments.username],
            text=True
        ).strip()

        if "No Steam ID" in steam_id_output or not steam_id_output:
            print(json.dumps({"error": f"Steam ID not found for {arguments.username}"}))
