        action='webauthn_toggle',
        resource_type='webauthn',
        resource_id=str(cred_id),
        resource_name=f'WebAuthn credential {cred_id}',
        details=f'{"Enabled" if is_enabled else "Disabled"} WebAuthn credential {cred_id}',
        success=True
    )

    return success_response(message=msg)

@bp.route('/register/options', methods=['POST'])
@require_auth()
def get_registration_params():
    """Generate WebAuthn registration parameters - uses WebAuthnService for crypto operations"""
    current_user = g.current_user
    host = request.host

    params = WebAuthnService.generate_registration_options(current_user, host)
    return success_response(data=params)

@bp.route('/register/verify', methods=['POST'])
@require_auth()
def confirm_registration():
    """Validate WebAuthn registration and store credential"""
    current_user = g.current_user
    payload = request.get_json()

    cred_data = payload.get('credential', {})
    cred_label = payload.get('name', 'Security Key')
    host = request.host

    success, msg, credential = WebAuthnService.verify_registration(
        current_user.id, cred_data, host, cred_label
    )

    if not success:
        return error_response(msg, 400)

    AuditService.log_action(
        action='webauthn_register',
        resource_type='webauthn',
        resource_id=str(credential.id) if credential else None,
        resource_name=cred_label,
        details=f'Created WebAuthn credential: {cred_label}',
        success=True
    )

    return success_response(data=credential.to_dict() if credential else None, message=msg)

# Modified version of UpdateInputTensorConstraints class with structural changes and renamed components
from graph_net.dynamic_dim_constraints import DynamicDimConstraints
from contextlib import AbstractContextManager
from graph_net.imp_util import load_module
from graph_net.tensor_meta import TensorMeta
from typing import Callable, Tuple, Optional
import functools
import copy
import sys
import os
from contextlib import contextmanager
import tempfile
import shutil
from pathlib import Path
from dataclasses import asdict

class ModifyInputTensorConstraints:
    def __init__(self, settings=None):
        if settings is None:
            settings = {}
        self.settings = self._build_settings(**settings)
        self.input_predictor = self._create_input_predictor(self.settings)
        self.runnable_predictor = self._create_runnable_predictor(self.settings)
        self.processed_count = 0

    def _create_input_predictor(self, settings):
        module = load_module(settings["input_predictor_filepath"])
        cls = getattr(module, settings["input_predictor_class_name"])
        return cls(settings["input_predictor_config"])

    def _create_runnable_predictor(self, settings):
        module = load_module(settings["runnable_predictor_filepath"])
        cls = getattr(module, settings["runnable_predictor_class_name"])
        return cls(settings["runnable_predictor_config"])

    def _build_settings(
        self,
        input_predictor_filepath,
        runnable_predictor_filepath,
        input_predictor_class_name="DataInputPredictor",
        runnable_predictor_class_name="ModelRunner",
        input_predictor_config=None,
        runnable_predictor_config=None,
        dim_generalizer_filepath=None,
        dim_generalizer_class_name="StaticToDynamic",
        dim_generalizer_config=None,
        model_path_prefix="",
        resume=False,
        last_model_log_file=None,
        max_processed_models=None,
    ):
        if input_predictor_config is None:
            input_predictor_config = {}
        if runnable_predictor_config is None:
            runnable_predictor_config = {}
        if dim_generalizer_config is None:
            dim_generalizer_config = {}
        return {
            "resume": resume,
            "model_path_prefix": model_path_prefix,
            "input_predictor_filepath": input_predictor_filepath,
            "input_predictor_class_name": input_predictor_class_name,
            "input_predictor_config": input_predictor_config,
            "runnable_predictor_filepath": runnable_predictor_filepath,
            "runnable_predictor_class_name": runnable_predictor_class_name,
            "runnable_predictor_config": runnable_predictor_config,
            "dim_generalizer_filepath": dim_generalizer_filepath,
            "dim_generalizer_class_name": dim_generalizer_class_name,
            "dim_generalizer_config": dim_generalizer_config,
            "last_model_log_file": last_model_log_file,
            "max_processed_models": max_processed_models,
        }

    def __call__(self, model_location):
        model_location = os.path.join(self.settings["model_path_prefix"], model_location)
        cstr_path = os.path.join(model_location, "input_tensor_constraints.py")

        # Check for existing constraints file and resume condition
        if (
            self.settings["resume"]
            and os.path.exists(cstr_path)
            and DynamicDimConstraints.kSymbols in open(cstr_path).read()
        ):
            module = load_module(cstr_path)
            symbols = getattr(module, DynamicDimConstraints.kSymbols)
            if len(symbols) > 0:
                return

        tensor_metas = self._extract_tensor_metas(model_location)
        tensor_meta_attrs_list = [asdict(tensor_meta) for tensor_meta in tensor_metas]

        logging.warning("before create_inputs_by_metas")
        inputs = self.get_dimension_generalizer().create_inputs_by_metas(
            module=self.get_model(model_location),
            tensor_meta_attrs_list=tensor_meta_attrs_list,
        )
        logging.warning("after create_inputs_by_metas")

        dyn_dim_cstr = make_dyn_dim_cstr_from_tensor_metas(tensor_metas)

        def input_predictor_wrapper(input_var_name):
            return self.input_predictor(model_location, input_var_name)

        def get_tmp_model_path_ctx_mgr(dim_axes_pairs):
            return self._attempt_dimension_generalization(
                dim_axes_pairs, model_location, inputs
            )

        def get_predicator_is_dyn_dim_cstr_feasible(tmp_model_path):
            def is_dyn_dim_cstr_feasible(dyn_dim_cstr):
                return self._is_dyn_dim_cstr_feasible(
                    tmp_model_path, tensor_metas, dyn_dim_cstr
                )
            return is_dyn_dim_cstr_feasible

        dyn_dim_cstr_feasibility_ctx_mgr = DynDimCstrFeasibilityContextManager(
            get_tmp_model_path_ctx_mgr=get_tmp_model_path_ctx_mgr,
            get_predicator_is_dyn_dim_cstr_feasible=get_predicator_is_dyn_dim_cstr_feasible,
        )

        dyn_dim_cstr, dim_gen_pass_names = symbolize_data_input_dims(
            dyn_dim_cstr,
            is_data_input=input_predictor_wrapper,
            dyn_dim_cstr_feasibility_ctx_mgr=dyn_dim_cstr_feasibility_ctx_mgr,
        )

        self._store_dyn_dim_cstr(dyn_dim_cstr, model_location)
        self._store_dim_gen_pass_names(dim_gen_pass_names, model_location)
        self.processed_count += 1

        limits = self.settings["max_processed_models"]
        if limits is not None:
            if self.processed_count >= limits:
                print(
                    "`processed_count` exceeds config `max_processed_models`",
                    file=sys.stderr,
                )
                sys.exit(0)

    def get_dimension_generalizer(self):
        if hasattr(self, "_dim_generalizer"):
            return self._dim_generalizer
        assert self.settings["dim_generalizer_filepath"] is not None
        decorator_cls = getattr(
            load_module(self.settings["dim_generalizer_filepath"]),
            self.settings["dim_generalizer_class_name"],
        )
        self._dim_generalizer = decorator_cls(
            self.settings["dim_generalizer_config"]
        )
        return self._dim_generalizer

    def get_model(self, model_location):
        py_module = load_module(os.path.join(model_location, "model.py"))
        GraphModule = getattr(py_module, "GraphModule")
        GraphModule.__graph_net_file_path__ = py_module.__graph_net_file_path__
        return GraphModule()

    @contextmanager
    def _attempt_dimension_generalization(self, dim_axes_pairs, model_location, inputs):
        logging.warning("enter _attempt_dimension_generalization")
        if self.settings["dim_generalizer_filepath"] is None:
            self._save_model_to_log_file(model_location)
            yield model_location, ()
            return

        model = self.get_model(model_location)
        dim_generalizer = self.get_dimension_generalizer()
        dim_gen_pass = dim_generalizer(model, dim_axes_pairs)

        logging.warning("before need_rewrite")
        need_rewrite = dim_gen_pass.need_rewrite(inputs)
        logging.warning("after need_rewrite")

        if not need_rewrite:
            self._save_model_to_log_file(model_location)
            yield model_location, ()
            return

        logging.warning("before rewrite")
        graph_module = dim_gen_pass.rewrite(inputs)
        logging.warning("after rewrite")

        with tempfile.TemporaryDirectory() as tmp_dir:
            shutil.copytree(Path(model_location), Path(tmp_dir), dirs_exist_ok=True)
            dim_gen_pass.save_graph_module(graph_module, tmp_dir)
            self._save_model_to_log_file(tmp_dir)
            yield tmp_dir, dim_gen_pass.get_pass_names()

    def _save_model_to_log_file(self, model_location):
        if self.settings["last_model_log_file"] is not None:
            log_file = Path(self.settings["last_model_log_file"])
            shutil.copy(Path(model_location) / "model.py", log_file)

    def _store_dim_gen_pass_names(self, dim_gen_pass_names, model_location):
        from graph_net.graph_net_json_file_util import (
            kDimensionGeneralizationPasses,
            update_json,
        )
        update_json(
            model_location, kDimensionGeneralizationPasses, list(dim_gen_pass_names)
        )

    def _store_dyn_dim_cstr(self, dyn_dim_cstr, model_location):
        cstr_code = dyn_dim_cstr.serialize_to_py_str()
        with open(os.path.join(model_location, "input_tensor_constraints.py"), "w") as fp:
            fp.write(cstr_code)

    def _extract_tensor_metas(self, model_location):
        make = TensorMeta.unserialize_from_py_file
        return [
            *make(os.path.join(model_location, "input_meta.py")),
            *make(os.path.join(model_location, "weight_meta.py")),
        ]

    def _is_dyn_dim_cstr_feasible(
        self, model_location, tensor_metas, dyn_dim_cstr: DynamicDimConstraints
    ):
        tensor_metas = copy.deepcopy(tensor_metas)
        update_tensor_metas_by_dyn_dim_cstr(tensor_metas, dyn_dim_cstr)
        weight_meta_code = "\n".join(
            tensor_meta.serialize_to_py_str() for tensor_meta in tensor_metas
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            for filename in ["graph_net.json", "model.py"]:
                with open(os.path.join(tmpdir, filename), "w") as f:
                    f.write(open(os.path.join(model_location, filename)).read())
            with open(os.path.join(tmpdir, "input_meta.py"), "w") as f:
                f.write("")
            with open(os.path.join(tmpdir, "weight_meta.py"), "w") as f:
                f.write(weight_meta_code)
            return self.runnable_predictor(tmpdir)

def update_tensor_metas_by_dyn_dim_cstr(
    tensor_metas: list[TensorMeta], dyn_dim_cstr: DynamicDimConstraints
):
    input_shapes_with_names = dyn_dim_cstr.input_shapes
    name2shape = {
        name: [dyn_dim_cstr._try_reify(dim) for dim in shape]
        for shape, name in input_shapes_with_names
    }
    for tensor_meta in tensor_metas:
        if tensor_meta.name not in name2shape:
            continue
        tensor_meta.shape = name2shape[tensor_meta.name]
        if tensor_meta.data is not None:
            assert isinstance(tensor_meta.data, (list, tuple))
            size = functools.reduce(lambda a, b: a * b, tensor_meta.shape, 1)
            doubled_data = [*tensor_meta.data, *tensor_meta.data]
            tensor_meta.data = doubled_data[:size]

def make_dyn_dim_cstr_from_tensor_metas(tensor_metas: list[TensorMeta]):
    named_shapes = [
        (shape, name)
        for tensor_meta in tensor_metas
        for name in [tensor_meta.name]
        for shape in [tensor_meta.shape]
    ]
    return DynamicDimConstraints.make_by_named_inputs(
        named_shapes=named_shapes,
    )

class DynDimCstrFeasibilityPredicator:
    def __init__(
        self,
        is_dyn_dim_cstr_feasible: Callable[[DynamicDimConstraints], bool],
        dim_gen_pass_names: Tuple[str],
    ):
        self.is_dyn_dim_cstr_feasible = is_dyn_dim_cstr_feasible
        self.dim_gen_pass_names = dim_gen_pass_names

    def __call__(self, dyn_dim_cstr: DynamicDimConstraints) -> bool:
        return self.is_dyn_dim_cstr_feasible(dyn_dim_cstr)

class DynDimCstrFeasibilityContextManager:
    def __init__(
        self,
        get_tmp_model_path_ctx_mgr,
        get_predicator_is_dyn_dim_cstr_feasible,
    ):
        self.get_tmp_model_path_ctx_mgr = get_tmp_model_path_ctx_mgr
        self.get_predicator_is_dyn_dim_cstr_feasible = (
            get_predicator_is_dyn_dim_cstr_feasible
        )

    @contextmanager
    def __call__(
        self, dim_axes_pairs
    ) -> AbstractContextManager[DynDimCstrFeasibilityPredicator]:
        ctx_mgr = self.get_tmp_model_path_ctx_mgr
        with ctx_mgr(dim_axes_pairs) as (tmp_model_apth, dg_pass_names):
            predicator = self.get_predicator_is_dyn_dim_cstr_feasible(tmp_model_apth)
            yield DynDimCstrFeasibilityPredicator(predicator, dg_pass_names)

def symbolize_data_input_dims(
    dyn_dim_cstr: DynamicDimConstraints,
    is_data_input: Callable[[str], bool],
    dyn_dim_cstr_feasibility_ctx_mgr: DynDimCstrFeasibilityContextManager,
) -> Tuple[Optional[DynamicDimConstraints], Tuple[str]]:
    """
    is_data_input: Callable[["input_var_name:str"], bool]
    Symbolizes data input dimensions as much as possible.
    Returns new DynamicDimConstraints if success.
    Returns None if no symbolicable dim .
    """
    unique_dims = []
    dim2axes = {}

    def dumpy_filter_fn(input_name, input_idx, axis, dim):
        if is_data_input(input_name):
            print("data_input", input_name, input_idx, axis, dim)
            if dim not in unique_dims:
                unique_dims.append(dim)
                dim2axes[dim] = []
            dim2axes[dim].append(axis)
        # No symbolization by returning False
        return False

    # Collect input dimensions into `unique_dims`
    assert dyn_dim_cstr.symbolize(dumpy_filter_fn) is None

    total_dim_gen_pass_names = ()

    def append_dim_gen_pass_names(dim_gen_pass_names):
        nonlocal total_dim_gen_pass_names
        total_dim_gen_pass_names = tuple(
            [
                *total_dim_gen_pass_names,
                *(
                    pass_name
                    for pass_name in dim_gen_pass_names
                    if pass_name not in total_dim_gen_pass_names
                ),
            ]
        )

    for i, picked_dim in enumerate(unique_dims):
        logging.warning(f"{i=} {picked_dim=} {dim2axes[picked_dim]=}")
        cur_dyn_dim_cstr = copy.deepcopy(dyn_dim_cstr)

        def filter_fn(input_name, input_idx, axis, dim):
            return (
                is_data_input(input_name)
                and dim == picked_dim
                and (dim > 1 or axis == 0)
            )

        symbol = cur_dyn_dim_cstr.symbolize(filter_fn)
        if symbol is None:
            continue

        sym2example_value = {symbol: picked_dim + 1}
        if not cur_dyn_dim_cstr.check_delta_symbol2example_value(sym2example_value):
            continue

        dim_axes_pairs = tuple(
            (dim, axes) for dim in unique_dims[: i + 1] for axes in [dim2axes[dim]]
        )
        ctx_mgr = dyn_dim_cstr_feasibility_ctx_mgr

        logging.warning("before dyn_dim_cstr_feasibility_ctx_mgr")
        with ctx_mgr(dim_axes_pairs) as dyn_dim_cstr_feasibility:
            logging.warning("enter dyn_dim_cstr_feasibility_ctx_mgr")
            tmp_dyn_dim_cstr = copy.deepcopy(cur_dyn_dim_cstr)
            tmp_dyn_dim_cstr.update_symbol2example_value(sym2example_value)
            logging.warning("before dyn_dim_cstr_feasibility")
            is_dyn_dim_cstr_feasible = dyn_dim_cstr_feasibility(tmp_dyn_dim_cstr)
            logging.warning("after dyn_dim_cstr_feasibility")

            if not is_dyn_dim_cstr_feasible:
                continue

            dyn_dim_cstr = cur_dyn_dim_cstr
            append_dim_gen_pass_names(dyn_dim_cstr_feasibility.dim_gen_pass_names)
            logging.warning("leave dyn_dim_cstr_feasibility_ctx_mgr")

    return dyn_dim_cstr, total_dim_gen_pass_names

# Spotify API client for fetching user data and recommendations
import json
import urllib.request
import urllib.parse
import base64
import sys
import os
from pathlib import Path
from datetime import datetime

CLIENT_ID = os.environ.get("SPOTIFY_CLIENT_ID", "")
CLIENT_SECRET = os.environ.get("SPOTIFY_CLIENT_SECRET", "")
TOKEN_FILE = Path.home() / ".config" / "spotify-clawd" / "token.json"

def load_token():
    if not TOKEN_FILE.exists():
        print("Error: Not authenticated. Run spotify-auth.py first.")
        sys.exit(1)
    return json.loads(TOKEN_FILE.read_text())

def save_token(token_data):
    TOKEN_FILE.write_text(json.dumps(token_data, indent=2))

def refresh_token(token_data):
    auth_header = base64.b64encode(f"{CLIENT_ID}:{CLIENT_SECRET}".encode()).decode()

    payload = urllib.parse.urlencode({
        "grant_type": "refresh_token",
        "refresh_token": token_data["refresh_token"],
    }).encode()

    request = urllib.request.Request(
        "https://accounts.spotify.com/api/token",
        data=payload,
        headers={
            "Authorization": f"Basic {auth_header}",
            "Content-Type": "application/x-www-form-urlencoded",
        }
    )

    with urllib.request.urlopen(request) as response:
        updated_data = json.load(response)

    # Preserve refresh token if missing in response
    if "refresh_token" not in updated_data:
        updated_data["refresh_token"] = token_data["refresh_token"]

    save_token(updated_data)
    return updated_data

def api_request(endpoint, token_data, params=None):
    url = f"https://api.spotify.com/v1{endpoint}"
    if params:
        url += "?" + urllib.parse.urlencode(params)

    request = urllib.request.Request(
        url,
        headers={"Authorization": f"Bearer {token_data['access_token']}"}
    )

    try:
        with urllib.request.urlopen(request) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        if error.code == 401:
            # Token expired, refresh and retry
            token_data = refresh_token(token_data)
            request = urllib.request.Request(
                url,
                headers={"Authorization": f"Bearer {token_data['access_token']}"}
            )
            with urllib.request.urlopen(request) as response:
                return json.load(response)
        raise

def get_recently_played(token_data, limit=20):
    return api_request("/me/player/recently-played", token_data, {"limit": limit})

def get_top_artists(token_data, time_range="medium_term", limit=20):
    return api_request("/me/top/artists", token_data, {"time_range": time_range, "limit": limit})

def get_top_tracks(token_data, time_range="medium_term", limit=20):
    return api_request("/me/top/tracks", token_data, {"time_range": time_range, "limit": limit})

def get_recommendations(token_data, seed_artists=None, seed_tracks=None, seed_genres=None, limit=20):
    query_params = {"limit": limit}
    if seed_artists:
        query_params["seed_artists"] = ",".join(seed_artists[:5])
    if seed_tracks:
        query_params["seed_tracks"] = ",".join(seed_tracks[:5])
    if seed_genres:
        query_params["seed_genres"] = ",".join(seed_genres[:5])
    return api_request("/recommendations", token_data, query_params)

def main():
    if len(sys.argv) < 2:
        print("Usage: spotify-api.py <command>")
        print("Commands: recent, top-artists, top-tracks, recommend")
        return 1

    command = sys.argv[1]
    token_data = load_token()

    if command == "recent":
        result = get_recently_played(token_data)
        print("Recently Played:")
        for item in result["items"]:
            track = item["track"]
            played_at = item["played_at"]
            artists = ", ".join(a["name"] for a in track["artists"])
            print(f"  {track['name']} - {artists} ({played_at[:10]})")

    elif command == "top-artists":
        time_range = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        result = get_top_artists(token_data, time_range)
        print(f"Top Artists ({time_range}):")
        for idx, artist in enumerate(result["items"], 1):
            genres = ", ".join(artist["genres"][:3]) if artist["genres"] else "N/A"
            print(f"  {idx}. {artist['name']} [{genres}]")

    elif command == "top-tracks":
        time_range = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        result = get_top_tracks(token_data, time_range)
        print(f"Top Tracks ({time_range}):")
        for idx, track in enumerate(result["items"], 1):
            artists = ", ".join(a["name"] for a in track["artists"])
            print(f"  {idx}. {track['name']} - {artists}")

    elif command == "recommend":
        # Get top artists for seeds
        top = get_top_artists(token_data, limit=5)
        seed_artists = [a["id"] for a in top["items"][:3]]

        result = get_recommendations(token_data, seed_artists=seed_artists)
        print("Recommendations based on your top artists:")
        for track in result["tracks"]:
            artists = ", ".join(a["name"] for a in track["artists"])
            print(f"  {track['name']} - {artists}")

    elif command == "json":
        # Raw JSON output for any endpoint
        endpoint = sys.argv[2] if len(sys.argv) > 2 else "/me"
        result = api_request(endpoint, token_data)
        print(json.dumps(result, indent=2))

    else:
        print(f"Unknown command: {command}")
        return 1

    return 0

if __name__ == "__main__":
    exit(main())

# Dynamically load provider clients based on protocol type
from __future__ import annotations
import importlib
from typing import Optional, TYPE_CHECKING, Type, cast
from ripperdoc.core.config import ProtocolType
from ripperdoc.core.providers.base import ProviderClient
from ripperdoc.utils.log import get_logger

if TYPE_CHECKING:  # pragma: no cover - type checking only
    from ripperdoc.core.providers.anthropic import AnthropicClient  # noqa: F401
    from ripperdoc.core.providers.gemini import GeminiClient  # noqa: F401
    from ripperdoc.core.providers.openai import OpenAIClient  # noqa: F401

logger = get_logger()

def _fetch_provider_client(module_name: str, class_name: str, required_extra: str) -> Type[ProviderClient]:
    """Dynamically import a provider client class, guiding users to install required dependencies."""
    try:
        module = importlib.import_module(f"ripperdoc.core.providers.{module_name}")
        client_class = cast(Type[ProviderClient], getattr(module, class_name, None))
        if client_class is None:
            raise ImportError(f"{class_name} not found in {module_name}")
        return client_class
    except ImportError as error:
        raise RuntimeError(
            f"{class_name} requires optional dependency group '{required_extra}'. "
            f"Install with `pip install ripperdoc[{required_extra}]`."
        ) from error

def get_client_for_protocol(protocol: ProtocolType) -> Optional[ProviderClient]:
    """Instantiate and return a provider client corresponding to the given protocol."""
    if protocol == ProtocolType.ANTHROPIC:
        return _fetch_provider_client("anthropic", "AnthropicClient", "anthropic")()
    if protocol == ProtocolType.OPENAI_COMPATIBLE:
        return _fetch_provider_client("openai", "OpenAIClient", "openai")()
    if protocol == ProtocolType.GEMINI:
        return _fetch_provider_client("gemini", "GeminiClient", "gemini")()
    if protocol == ProtocolType.OAUTH:
        return _fetch_provider_client("openai", "OpenAIClient", "openai")()

    logger.warning("[providers] Unsupported protocol detected", extra={"protocol": protocol})
    return None

__all__ = ["ProviderClient", "get_client_for_protocol"]

# Framework adapter module.
# Provides multi-framework support with adapters for Jest, Pytest, JUnit, Vitest, and more.
# Handles framework-specific patterns, imports, and test structure.
"""
from typing import Dict, List, Any, Optional
from enum import Enum

class TestingFramework(Enum):
    """Supported testing frameworks."""
    JEST = "jest"
    VITEST = "vitest"
    PYTEST = "pytest"
    UNITTEST = "unittest"
    JUNIT = "junit"
    TESTNG = "testng"
    MOCHA = "mocha"
    JASMINE = "jasmine"

class ProgrammingLanguage(Enum):
    """Supported programming languages."""
    TYPESCRIPT = "typescript"
    JAVASCRIPT = "javascript"
    PYTHON = "python"
    JAVA = "java"

class TestFrameworkAdapter:
    """Adapter for multiple testing frameworks."""
    def __init__(self, framework: TestingFramework, language: ProgrammingLanguage):
        """
        Initialize framework adapter.
        Args:
            framework: Testing framework
            language: Programming language
        """
        self.framework = framework
        self.language = language

    def generate_imports(self) -> str:
        """Generate framework-specific imports."""
        if self.framework == TestingFramework.JEST:
            return self._jest_imports()
        elif self.framework == TestingFramework.VITEST:
            return self._vitest_imports()
        elif self.framework == TestingFramework.PYTEST:
            return self._pytest_imports()
        elif self.framework == TestingFramework.UNITTEST:
            return self._unittest_imports()
        elif self.framework == TestingFramework.JUNIT:
            return self._junit_imports()
        elif self.framework == TestingFramework.TESTNG:
            return self._testng_imports()
        elif self.framework == TestingFramework.MOCHA:
            return self._mocha_imports()
        else:
            return ""

    def _jest_imports(self) -> str:
        """Generate Jest imports."""
        return """import { describe, it, expect, beforeEach, afterEach } from '@jest/globals';"""

    def _vitest_imports(self) -> str:
        """Generate Vitest imports."""
        return """import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';"""

    def _pytest_imports(self) -> str:
        """Generate Pytest imports."""
        return """import pytest"""

    def _unittest_imports(self) -> str:
        """Generate unittest imports."""
        return """import unittest"""

    def _junit_imports(self) -> str:
        """Generate JUnit imports."""
        return """import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.AfterEach;
import static org.junit.jupiter.api.Assertions.*;"""

    def _testng_imports(self) -> str:
        """Generate TestNG imports."""
        return """import org.testng.annotations.Test;
import org.testng.annotations.BeforeMethod;
import org.testng.annotations.AfterMethod;
import static org.testng.Assert.*;"""

    def _mocha_imports(self) -> str:
        """Generate Mocha imports."""
        return """import { describe, it, beforeEach, afterEach } from 'mocha';
import { expect } from 'chai';"""

    def wrap_test_content(
        self,
        suite_name: str,
        test_body: str
    ) -> str:
        """
        Wrap test content in framework-specific suite structure.
        Args:
            suite_name: Name of test suite
            test_body: Test functions/methods
        Returns:
            Complete test suite code
        """
        if self.framework in [TestingFramework.JEST, TestingFramework.VITEST, TestingFramework.MOCHA]:
            return f"""describe('{suite_name}', () => {{
{self._indent(test_body, 2)}
}});"""
        elif self.framework == TestingFramework.PYTEST:
            return f"""class Test{self._to_class_name(suite_name)}:
    \"\"\"Test suite for {suite_name}.\"\"\"
{self._indent(test_body, 4)}"""
        elif self.framework == TestingFramework.UNITTEST:
            return f"""class Test{self._to_class_name(suite_name)}(unittest.TestCase):
    \"\"\"Test suite for {suite_name}.\"\"\"
{self._indent(test_body, 4)}"""
        elif self.framework in [TestingFramework.JUNIT, TestingFramework.TESTNG]:
            return f"""public class {self._to_class_name(suite_name)}Test {{
{self._indent(test_body, 4)}
}}"""
        return test_body

    def create_test_function(
        self,
        test_name: str,
        test_body: str,
        docstring: str = ""
    ) -> str:
        """
        Generate framework-specific test function.
        Args:
            test_name: Name of test
            test_body: Test body code
            docstring: Test description
        Returns:
            Complete test function
        """
        if self.framework == TestingFramework.JEST:
            return self._jest_test(test_name, test_body, docstring)
        elif self.framework == TestingFramework.VITEST:
            return self._vitest_test(test_name, test_body, docstring)
        elif self.framework == TestingFramework.PYTEST:
            return self._pytest_test(test_name, test_body, docstring)
        elif self.framework == TestingFramework.UNITTEST:
            return self._unittest_test(test_name, test_body, docstring)
        elif self.framework == TestingFramework.JUNIT:
            return self._junit_test(test_name, test_body, docstring)
        elif self.framework == TestingFramework.TESTNG:
            return self._testng_test(test_name, test_body, docstring)
        elif self.framework == TestingFramework.MOCHA:
            return self._mocha_test(test_name, test_body, docstring)
        else:
            return ""

    def _jest_test(self, test_name: str, test_body: str, docstring: str) -> str:
        """Generate Jest test."""
        return f"""it('{test_name}', () => {{
  // {docstring}
{self._indent(test_body, 2)}
}});"""

    def _vitest_test(self, test_name: str, test_body: str, docstring: str) -> str:
        """Generate Vitest test."""
        return f"""it('{test_name}', () => {{
  // {docstring}
{self._indent(test_body, 2)}
}});"""

    def _pytest_test(self, test_name: str, test_body: str, docstring: str) -> str:
        """Generate Pytest test."""
        func_name = test_name.replace(' ', '_').replace('-', '_')
        return f"""def test_{func_name}(self):
    \"\"\"
    {docstring or test_name}
    \"\"\"
{self._indent(test_body, 4)}"""

    def _unittest_test(self, test_name: str, test_body: str, docstring: str) -> str:
        """Generate unittest test."""
        func_name = self._to_camel_case(test_name)
        return f"""def test_{func_name}(self):
    \"\"\"
    {docstring or test_name}
    \"\"\"
{self._indent(test_body, 4)}"""

    def _junit_test(self, test_name: str, test_body: str, docstring: str) -> str:
        """Generate JUnit test."""
        method_name = self._to_camel_case(test_name)
        return f"""@Test
public void test{method_name}() {{
    // {docstring}
{self._indent(test_body, 4)}
}}"""

    def _testng_test(self, test_name: str, test_body: str, docstring: str) -> str:
        """Generate TestNG test."""
        method_name = self._to_camel_case(test_name)
        return f"""@Test
public void test{method_name}() {{
    // {docstring}
{self._indent(test_body, 4)}
}}"""

    def _mocha_test(self, test_name: str, test_body: str, docstring: str) -> str:
        """Generate Mocha test."""
        return f"""it('{test_name}', () => {{
  // {docstring}
{self._indent(test_body, 2)}
}});"""

    def produce_assertion(
        self,
        actual: str,
        expected: str,
        assertion_kind: str = "equals"
    ) -> str:
        """
        Generate framework-specific assertion.
        Args:
            actual: Actual value expression
            expected: Expected value expression
            assertion_kind: Type of assertion (equals, not_equals, true, false, throws)
        Returns:
            Assertion statement
        """
        if self.framework in [TestingFramework.JEST, TestingFramework.VITEST]:
            return self._jest_assertion(actual, expected, assertion_kind)
        elif self.framework in [TestingFramework.PYTEST, TestingFramework.UNITTEST]:
            return self._python_assertion(actual, expected, assertion_kind)
        elif self.framework in [TestingFramework.JUNIT, TestingFramework.TESTNG]:
            return self._java_assertion(actual, expected, assertion_kind)
        elif self.framework == TestingFramework.MOCHA:
            return self._chai_assertion(actual, expected, assertion_kind)
        else:
            return f"assert {actual} == {expected}"

    def _jest_assertion(self, actual: str, expected: str, assertion_kind: str) -> str:
        """Generate Jest assertion."""
        if assertion_kind == "equals":
            return f"expect({actual}).toBe({expected});"
        elif assertion_kind == "not_equals":
            return f"expect({actual}).not.toBe({expected});"
        elif assertion_kind == "true":
            return f"expect({actual}).toBe(true);"
        elif assertion_kind == "false":
            return f"expect({actual}).toBe(false);"
        elif assertion_kind == "throws":
            return f"expect(() => {actual}).toThrow();"
        else:
            return f"expect({actual}).toBe({expected});"

    def _python_assertion(self, actual: str, expected: str, assertion_kind: str) -> str:
        """Generate Python assertion."""
        if assertion_kind == "equals":
            return f"assert {actual} == {expected}"
        elif assertion_kind == "not_equals":
            return f"assert {actual} != {expected}"
        elif assertion_kind == "true":
            return f"assert {actual} is True"
        elif assertion_kind == "false":
            return f"assert {actual} is False"
        elif assertion_kind == "throws":
            return f"with pytest.raises(Exception):\n    {actual}"
        else:
            return f"assert {actual} == {expected}"

    def _java_assertion(self, actual: str, expected: str, assertion_kind: str) -> str:
        """Generate Java assertion."""
        if assertion_kind == "equals":
            return f"assertEquals({expected}, {actual});"
        elif assertion_kind == "not_equals":
            return f"assertNotEquals({expected}, {actual});"
        elif assertion_kind == "true":
            return f"assertTrue({actual});"
        elif assertion_kind == "false":
            return f"assertFalse({actual});"
        elif assertion_kind == "throws":
            return f"assertThrows(Exception.class, () -> {actual});"
        else:
            return f"assertEquals({expected}, {actual});"

    def _chai_assertion(self, actual: str, expected: str, assertion_kind: str) -> str:
        """Generate Chai assertion."""
        if assertion_kind == "equals":
            return f"expect({actual}).to.equal({expected});"
        elif assertion_kind == "not_equals":
            return f"expect({actual}).to.not.equal({expected});"
        elif assertion_kind == "true":
            return f"expect({actual}).to.be.true;"
        elif assertion_kind == "false":
            return f"expect({actual}).to.be.false;"
        elif assertion_kind == "throws":
            return f"expect(() => {actual}).to.throw();"
        else:
            return f"expect({actual}).to.equal({expected});"

    def produce_setup_teardown(
        self,
        setup_code: str = "",
        teardown_code: str = ""
    ) -> str:
        """Generate setup and teardown hooks."""
        result = []
        if self.framework in [TestingFramework.JEST, TestingFramework.VITEST, TestingFramework.MOCHA]:
            if setup_code:
                result.append(f"""beforeEach(() => {{
{self._indent(setup_code, 2)}
}});""")
            if teardown_code:
                result.append(f"""afterEach(() => {{
{self._indent(teardown_code, 2)}
}});""")
        elif self.framework == TestingFramework.PYTEST:
            if setup_code:
                result.append(f"""@pytest.fixture(autouse=True)
def setup_method(self):
{self._indent(setup_code, 4)}
    yield""")
            if teardown_code:
                result.append(f"""
{self._indent(teardown_code, 4)}""")
        elif self.framework == TestingFramework.UNITTEST:
            if setup_code:
                result.append(f"""def setUp(self):
{self._indent(setup_code, 4)}""")
            if teardown_code:
                result.append(f"""def tearDown(self):
{self._indent(teardown_code, 4)}""")
        elif self.framework in [TestingFramework.JUNIT, TestingFramework.TESTNG]:
            annotation = "@BeforeEach" if self.framework == TestingFramework.JUNIT else "@BeforeMethod"
            if setup_code:
                result.append(f"""{annotation}
public void setUp() {{
{self._indent(setup_code, 4)}
}}""")
            annotation = "@AfterEach" if self.framework == TestingFramework.JUNIT else "@AfterMethod"
            if teardown_code:
                result.append(f"""{annotation}
public void tearDown() {{
{self._indent(teardown_code, 4)}
}}""")
        return "\n\n".join(result)

    def _indent(self, text: str, spaces: int) -> str:
        """Indent text by number of spaces."""
        indent = " " * spaces
        lines = text.split('\n')
        return '\n'.join(indent + line if line.strip() else line for line in lines)

    def _to_camel_case(self, text: str) -> str:
        """Convert text to camelCase."""
        words = text.replace('-', ' ').replace('_', ' ').split()
        if not words:
            return text
        return words[0].lower() + ''.join(word.capitalize() for word in words[1:])

    def _to_class_name(self, text: str) -> str:
        """Convert text to ClassName."""
        words = text.replace('-', ' ').replace('_', ' ').split()
        return ''.join(word.capitalize() for word in words)

    def identify_framework(self, code: str) -> Optional[TestingFramework]:
        """
        Auto-detect testing framework from code.
        Args:
            code: Test code
        Returns:
            Detected framework or None
        """
        # Jest patterns
        if 'from \'@jest/globals\'' in code or '@jest/' in code:
            return TestingFramework.JEST
        # Vitest patterns
        if 'from \'vitest\'' in code or 'import { vi }' in code:
            return TestingFramework.VITEST
        # Pytest patterns
        if 'import pytest' in code or 'def test_' in code and 'pytest.fixture' in code:
            return TestingFramework.PYTEST
        # Unittest patterns
        if 'import unittest' in code and 'unittest.TestCase' in code:
            return TestingFramework.UNITTEST
        # JUnit patterns
        if '@Test' in code and 'import org.junit' in code:
            return TestingFramework.JUNIT
        # TestNG patterns
        if '@Test' in code and 'import org.testng' in code:
            return TestingFramework.TESTNG
        # Mocha patterns
        if 'from \'mocha\'' in code or ('describe(' in code and 'from \'chai\'' in code):
            return TestingFramework.MOCHA
        return None

# Calculate the sum based on even/odd rules 
from pytra.utils.assertions import py_assert_stdout

def compute_17(numbers: list[int]) -> int:
    result: int = 0
    for val in numbers:
        if val % 2 == 0:
            result += val
        else:
            result += val * 2
    return result

def _test_main() -> None:
    print(compute_17([1, 2, 3, 4]))

if __name__ == "__main__":
    print(py_assert_stdout(['14'], _test_main))

