class ANSI:
    """
    Utility class for ANSI escape codes to format terminal output.
    Reference: en.wikipedia.org/wiki/ANSI_escape_code
    """
    _bold = "\u001b[1m"
    _red = "\u001b[31m"
    _gray = "\u001b[90m"
    _reset = "\u001b[0m"

    @classmethod
    def bold(cls, text):
        return f"{cls._bold}{text}{cls._reset}"

    @classmethod
    def red(cls, text):
        return f"{cls._bold}{cls._red}{text}{cls._reset}"

    @classmethod
    def gray(cls, text):
        return f"{cls._gray}{text}{cls._reset}"


def tabulate(rows: List[List[Union[str, int]]], headers: List[str]) -> str:
    """
    Format data into a human-readable table using fixed-width columns.
    Based on solutions from:
    - stackoverflow.com/a/8356620/593036
    - stackoverflow.com/questions/9535954/printing-lists-as-tabular-data
    """
    col_widths = [max(len(str(item)) for item in column) for column in zip(*rows, headers)]
    row_format = ("{{:{}}} " * len(headers)).format(*col_widths)
    output_lines = []

    output_lines.append(row_format.format(*headers))
    output_lines.append(row_format.format(*["-" * width for width in col_widths]))

    for row_data in rows:
        output_lines.append(row_format.format(*row_data))

    return "\n".join(output_lines)


