class RepoCreateCommand(BaseUserCommand):
    def run(self):
        print(
            ANSI.red(
                "WARNING! Repository management via transformers-cli is deprecated. "
                "Please use `huggingface-cli` for all repository operations."
            )
        )
        token = HfFolder.get_token()
        if token is None:
            print("You are not logged in.")
            exit(1)

        try:
            git_version = subprocess.check_output(["git", "--version"]).decode("utf-8")
            print(ANSI.gray(git_version.strip()))
        except FileNotFoundError:
            print("Git appears to be missing. Please install it first.")

        try:
            git_lfs_version = subprocess.check_output(["git-lfs", "--version"]).decode("utf-8")
            print(ANSI.gray(git_lfs_version.strip()))
        except FileNotFoundError:
            print(
                ANSI.red(
                    "Git LFS is not installed. Please install it from https://git-lfs.github.com/ "
                    "and run `git lfs install` (only required once)."
                )
            )

        print("")
        user, _ = whoami(token)
        namespace = self.arguments.organization if self.arguments.organization is not None else user
        repo_id = f"{namespace}/{self.arguments.name}"
        print(f"About to create repository: {ANSI.bold(repo_id)}")

        if not self.arguments.yes:
            confirmation = input("Continue? [Y/n] ").lower()
            if confirmation not in ("", "y", "yes"):
                print("Operation cancelled.")
                exit()

        try:
            repo_url = create_repo(repo_id=repo_id, token=token)
        except HTTPError as error:
            print(error)
            print(ANSI.red(error.response.text))
            exit(1)

        print("\nYour repository is now available at:")
        print(f"  {ANSI.bold(repo_url)}")
        print("\nTo clone it locally, run the following command and proceed with commits/pushes as usual:")
        print(f"\n  git clone {repo_url}")
        print("")

import ast
import sys
from skylos.rules.danger.taint import TaintVisitor

# Set of functions that perform HTTP redirects
REDIRECT_FUNCS = {"redirect", "HttpResponseRedirect", "HttpResponsePermanentRedirect"}

class _RedirectFlowAnalyzer(TaintVisitor):
    def visit_Call(self, node):
        # Extract function name from call node
        func = node.func
        func_name = None

        if isinstance(func, ast.Name):
            func_name = func.id
        elif isinstance(func, ast.Attribute):
            func_name = func.attr

        # Check if the function is a redirect function and has arguments
        if func_name in REDIRECT_FUNCS and node.args:
            url_arg = node.args[0]

            # If the URL argument is tainted (user-controlled), flag it
            if self.is_tainted(url_arg):
                self.findings.append(
                    {
                        "rule_id": "SKY-D230",
                        "severity": "HIGH",
                        "message": "Possible open redirect: user-controlled URL passed to redirect.",
                        "file": str(self.file_path),
                        "line": node.lineno,
                        "col": node.col_offset,
                        "symbol": self._current_symbol(),
                    }
                )

        self.generic_visit(node)

def analyze(tree, file_path, findings):
    try:
        analyzer = _RedirectFlowAnalyzer(file_path, findings)
        analyzer.visit(tree)
    except Exception as e:
        print(f"Redirect flow analysis failed for {file_path}: {e}", file=sys.stderr)

