def _extract_call_path(node: ast.Call):
    func = node.func
    segments = []
    while isinstance(func, ast.Attribute):
        segments.append(func.attr)
        func = func.value
    if isinstance(func, ast.Name):
        segments.append(func.id)
        segments.reverse()
        return ".".join(segments)
    return None

class SecurityTaintAnalyzer(ast.NodeVisitor):
    def __init__(self, source_file, issues, cleaners=None):
        self.source_file = source_file
        self.issues = issues
        self.context_stack = [{}]
        self.entry_points = {"input", "request"}
        self.request_identifier = "request"
        self._scope_chain = ["<module>"]
        self.cleaners = cleaners or set()

    def _current_scope(self):
        if self._scope_chain:
            return self._scope_chain[-1]
        else:
            return "<module>"

    def _enter_scope(self):
        self.context_stack.append({})

    def _exit_scope(self):
        if self.context_stack:
            self.context_stack.pop()

    def _bind(self, name, is_tainted):
        if not self.context_stack:
            self._enter_scope()
        self.context_stack[-1][name] = bool(is_tainted)

    def _lookup(self, name):
        for ctx in reversed(self.context_stack):
            if name in ctx:
                return ctx[name]
        return False

    def _mark_parameters_as_tainted(self, fn: ast.AST):
        params = []
        if hasattr(fn, "args") and fn.args:
            params.extend(getattr(fn.args, "posonlyargs", []) or [])
            params.extend(getattr(fn.args, "args", []) or [])
            params.extend(getattr(fn.args, "kwonlyargs", []) or [])
            if fn.args.vararg:
                params.append(fn.args.vararg)
            if fn.args.kwarg:
                params.append(fn.args.kwarg)
        for p in params:
            param_name = getattr(p, "arg", None)
            if not param_name:
                continue
            if param_name in ("self", "cls"):
                continue
            self._bind(param_name, True)

    def is_source_tainted(self, node):
        if node is None:
            return False
        if isinstance(node, ast.JoinedStr):
            return any(
                isinstance(v, ast.FormattedValue) and self.is_source_tainted(v.value)
                for v in node.values
            )
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Mod)):
            return self.is_source_tainted(node.left) or self.is_source_tainted(node.right)
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "format"
        ):
            return True
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id in self.entry_points
        ):
            return True
        if isinstance(node, (ast.Attribute, ast.Subscript)):
            base = node.value
            while isinstance(base, (ast.Attribute, ast.Subscript)):
                base = base.value
            if isinstance(base, ast.Name) and base.id == self.request_identifier:
                return True
            return self.is_source_tainted(node.value)
        if isinstance(node, ast.Name):
            return self._lookup(node.id)
        if isinstance(node, ast.Call):
            if self.cleaners:
                call_path = _extract_call_path(node)
                if call_path and call_path in self.cleaners:
                    return False
            if isinstance(node.func, ast.Attribute):
                if self.is_source_tainted(node.func.value):
                    return True
            if any(self.is_source_tainted(arg) for arg in node.args):
                return True
            if any(self.is_source_tainted(k.value) for k in node.keywords):
                return True
        return False

    def generic_visit(self, node):
        for field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for item in value:
                    if isinstance(item, ast.AST):
                        self.visit(item)
            elif isinstance(value, ast.AST):
                self.visit(value)

    def visit_FunctionDef(self, node):
        self._enter_scope()
        self._scope_chain.append(node.name)
        self._mark_parameters_as_tainted(node)
        self.generic_visit(node)
        self._scope_chain.pop()
        self._exit_scope()

    def visit_AsyncFunctionDef(self, node):
        self._enter_scope()
        self._scope_chain.append(node.name)
        self._mark_parameters_as_tainted(node)
        self.generic_visit(node)
        self._scope_chain.pop()
        self._exit_scope()

    def visit_ClassDef(self, node):
        self._scope_chain.append(node.name)
        self.generic_visit(node)
        self._scope_chain.pop()

    def visit_Assign(self, node):
        t = self.is_source_tainted(node.value)
        for target in node.targets:
            if isinstance(target, ast.Name):
                self._bind(target.id, t)
        self.generic_visit(node)

    def visit_AnnAssign(self, node):
        if node.value:
            t = self.is_source_tainted(node.value)
            if isinstance(node.target, ast.Name):
                self._bind(node.target.id, t)
        self.generic_visit(node)

