import functools
import torch
from megatron.core.parallel_state import (
    get_global_memory_buffer,
    get_tensor_model_parallel_group,
    get_tensor_model_parallel_world_size,
)
from megatron.core.utils import (
    is_torch_min_version,
    prepare_input_tensors_for_wgrad_compute,
)
from torch.cuda.amp import custom_bwd, custom_fwd

# Determine appropriate distributed functions based on PyTorch version
if is_torch_min_version("1.13.0"):
    dist_all_gather_func = torch.distributed.all_gather_into_tensor
    dist_reduce_scatter_func = torch.distributed.reduce_scatter_tensor
else:
    dist_all_gather_func = torch.distributed._all_gather_base
    dist_reduce_scatter_func = torch.distributed._reduce_scatter_base

# Attempt to import fused CUDA kernel for weight gradient computation
try:
    import fused_weight_gradient_mlp_cuda
    _grad_accum_fusion_available = True
except ImportError:
    _grad_accum_fusion_available = False


class LinearWithGradAccumulationAndAsyncCommunication(torch.autograd.Function):
    """Custom autograd function for linear layer with gradient accumulation and async communication."""

    @staticmethod
    @custom_fwd
    def forward(
        ctx,
        input_tensor,
        weight_matrix,
        bias_vector,
        enable_grad_accum_fusion,
        do_async_dgrad_allreduce,
        use_sequence_parallel,
        grad_output_cache,
        max_deferred_wgrads,
        tp_comm_group,
    ):
        # Save inputs for backward pass
        ctx.save_for_backward(input_tensor, weight_matrix)
        ctx.use_bias_flag = bias_vector is not None
        ctx.grad_accum_fusion_enabled = enable_grad_accum_fusion
        ctx.async_dgrad_reduction = do_async_dgrad_allreduce
        ctx.sequence_parallel_mode = use_sequence_parallel
        ctx.max_deferral_limit = max_deferred_wgrads
        ctx.grad_output_storage = grad_output_cache
        ctx.primary_weight_grad = weight_matrix.main_grad

        # Sequence parallel: gather inputs across tensor-parallel ranks
        if use_sequence_parallel:
            world_size = get_tensor_model_parallel_world_size()
            shape_list = list(input_tensor.size())
            shape_list[0] *= world_size
            allgather_buffer = get_global_memory_buffer().get_tensor(shape_list, input_tensor.dtype, "mpu")
            dist_all_gather_func(allgather_buffer, input_tensor, group=tp_comm_group)
            full_input = allgather_buffer
        else:
            full_input = input_tensor

        # Compute output: y = x @ W^T + b
        result = torch.matmul(full_input, weight_matrix.t())
        if bias_vector is not None:
            result += bias_vector
        return result

    @staticmethod
    @custom_bwd
    def backward(ctx, grad_out):
        saved_input, saved_weight = ctx.saved_tensors
        saved_weight.main_grad = ctx.primary_weight_grad
        has_bias = ctx.use_bias_flag
        grad_cache = ctx.grad_output_storage
        max_deferral = ctx.max_deferral_limit

        # Helper: prepare inputs for wgrad computation (e.g., sequence-parallel gather)
        def _prepare_inputs(_grad_out_, _input_, async_mode=True):
            if ctx.sequence_parallel_mode:
                world_size = get_tensor_model_parallel_world_size()
                local_shape = list(_input_.size())
                local_shape[0] *= world_size
                gather_buf = get_global_memory_buffer().get_tensor(local_shape, _input_.dtype, "mpu")
                handle = dist_all_gather_func(
                    gather_buf, _input_, group=get_tensor_model_parallel_group(), async_op=async_mode
                )
                gathered_input = gather_buf
                return _grad_out_, gathered_input, handle
            else:
                return _grad_out_, _input_, None

        # Helper: finalize inputs before wgrad GEMM
        def _finalize_for_wgrad(_grad_out__, _input__, handle_):
            if ctx.sequence_parallel_mode and handle_ is not None:
                handle_.wait()
            return prepare_input_tensors_for_wgrad_compute(_grad_out__, _input__)

        # Helper: execute deferred wgrad computation
        def _run_wgrad(_weight__, _grad_out__, _input__, handle__, wgrad_fn=None):
            g_out, inp = _finalize_for_wgrad(_grad_out__, _input__, handle__)
            wgrad_fn(inp, g_out, _weight__.main_grad)

        # Import pipeline-parallel utilities
        from primus.core.pipeline_parallel.handler.wgrad_handler import (
            WGradRunningCache,
        )
        from ..pipeline_parallel.wgrad_adapter import insert_wgrad_func_into_cache
        from ..pipeline_parallel.zerobubble.zbpp_utils import WeightGradStore

        # Determine whether to compute wgrad immediately or defer it
        immediate_wgrad = not WeightGradStore.split_bw() and (
            WGradRunningCache.cur_minibatch is None and WGradRunningCache.cur_chunk is None
        )

        # Buffer grad_output if deferral is enabled and buffer not full
        if grad_cache is not None and immediate_wgrad:
            if max_deferral == 0 or len(grad_cache) < max_deferral:
                grad_cache.append(grad_out)
                immediate_wgrad = False

        # Pre-process inputs if doing immediate wgrad
        if immediate_wgrad:
            grad_out, full_input, comm_handle = _prepare_inputs(grad_out, saved_input, async_op=True)
        else:
            grad_out, full_input, comm_handle = _prepare_inputs(grad_out, saved_input, async_op=False)

        # Compute grad_input: dL/dx = dL/dy @ W
        grad_input = grad_out.matmul(saved_weight)

        # Finalize inputs for wgrad if needed
        if immediate_wgrad:
            grad_out, full_input = _finalize_for_wgrad(grad_out, full_input, comm_handle)

        # Asynchronous dgrad all-reduce if enabled
        if ctx.async_dgrad_reduction:
            comm_handle = torch.distributed.all_reduce(
                grad_input, group=get_tensor_model_parallel_group(), async_op=immediate_wgrad
            )

        # Sequence-parallel reduce-scatter for grad_input
        if ctx.sequence_parallel_mode:
            assert not ctx.async_dgrad_reduction
            local_shape = list(saved_input.size())
            sub_grad_input = torch.empty(
                local_shape, dtype=saved_input.dtype, device=torch.cuda.current_device(), requires_grad=False
            )
            comm_handle = dist_reduce_scatter_func(
                sub_grad_input, grad_input, group=get_tensor_model_parallel_group(), async_op=immediate_wgrad
            )

        # Gradient accumulation fusion path
        if ctx.grad_accum_fusion_enabled:
            if immediate_wgrad:
                if saved_weight.main_grad.dtype == torch.float32:
                    fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp32(
                        full_input, grad_out, saved_weight.main_grad
                    )
                elif saved_weight.main_grad.dtype in (torch.float16, torch.bfloat16):
                    fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp16(
                        full_input, grad_out, saved_weight.main_grad
                    )
                else:
                    raise RuntimeError("Unsupported gradient dtype for fusion")
            else:
                # Defer wgrad computation
                wgrad_fn = None
                if saved_weight.main_grad.dtype == torch.float32:
                    wgrad_fn = fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp32
                elif saved_weight.main_grad.dtype in (torch.float16, torch.bfloat16):
                    wgrad_fn = fused_weight_gradient_mlp_cuda.wgrad_gemm_accum_fp16
                else:
                    raise RuntimeError("Unsupported gradient dtype for fusion")

                insert_wgrad_func_into_cache(
                    saved_weight,
                    functools.partial(_prepare_inputs, grad_out, saved_input),
                    functools.partial(
                        _run_wgrad,
                        saved_weight,
                        wgrad_gemm_accum_func=wgrad_fn,
                    ),
                )

                # Handle dummy grad_weight to prevent background thread execution
                if hasattr(saved_weight, "grad_added_to_main_grad"):
                    if getattr(saved_weight, "zero_out_wgrad", False):
                        grad_weight = torch.zeros_like(saved_weight.main_grad, dtype=saved_input.dtype)
                    else:
                        grad_weight = torch.empty_like(saved_weight.main_grad, dtype=saved_input.dtype)
                    saved_weight.grad_added_to_main_grad = True
                else:
                    grad_weight = None
        else:
            # Standard wgrad: dL/dW = dL/dy^T @ x
            grad_weight = grad_out.t().matmul(full_input)

        # Bias gradient if applicable
        grad_bias = grad_out.sum(dim=0) if has_bias else None

        # Wait for any pending communications and return gradients
        if ctx.sequence_parallel_mode:
            if comm_handle is not None:
                comm_handle.wait()
            return sub_grad_input, grad_weight, grad_bias, None, None, None, None, None, None

        if ctx.async_dgrad_reduction:
            if comm_handle is not None:
                comm_handle.wait()

        return grad_input, grad_weight, grad_bias, None, None, None, None, None, None

# Register and manage advantage functions and policy losses for reinforcement learning
from functools import wraps
from typing import Callable, Optional
import torch
from rlinf.algorithms.utils import (
    calculate_scores,
    postprocess_embodied_advantages_outputs,
    postprocess_loss_metric,
    postprocess_reasoning_advantages_outputs,
    preprocess_embodied_advantages_inputs,
    preprocess_loss_inputs,
    preprocess_reasoning_advantages_inputs,
)

# Registry dictionaries for advantage and loss functions
ADVANTAGE_REGISTRY: dict[str, Callable] = {}
LOSS_FUNCTION_REGISTRY: dict[str, Callable] = {}

def register_advantage_function(name: str):
    """Decorator to register an advantage computation function."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            return fn(*args, **kwargs)
        ADVANTAGE_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def get_advantage_function_by_name(name: str) -> Callable:
    """Fetch a registered advantage function by its name."""
    if name.lower() not in ADVANTAGE_REGISTRY:
        raise ValueError(
            f"Advantage '{name}' is not registered. Available options: {list(ADVANTAGE_REGISTRY.keys())}"
        )
    return ADVANTAGE_REGISTRY[name.lower()]

def register_policy_loss_function(name: str):
    """Decorator to register a policy loss function."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            return fn(*args, **kwargs)
        LOSS_FUNCTION_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def retrieve_policy_loss_function(name: str):
    """Retrieve a registered policy loss function by name."""
    if name.lower() not in LOSS_FUNCTION_REGISTRY:
        raise ValueError(f"Loss function '{name}' is not registered")
    return LOSS_FUNCTION_REGISTRY[name.lower()]

def compute_actor_loss(**kwargs) -> tuple[torch.Tensor, dict]:
    """
    Unified actor loss computation entry point.
    Handles preprocessing, dispatching, and postprocessing based on task type.
    """
    loss_type = kwargs["loss_type"]
    loss_fn = retrieve_policy_loss_function(loss_type)
    task_type = kwargs["task_type"]

    # Preprocess inputs for embodied tasks
    if task_type == "embodied":
        kwargs = preprocess_loss_inputs(**kwargs)

    # Compute loss and metrics
    loss, metrics_data = loss_fn(**kwargs)

    # Postprocess metrics for embodied tasks
    if task_type == "embodied":
        metrics_data = postprocess_loss_metric(metrics_data)

    return loss, metrics_data

def compute_advantages_and_returns(**kwargs) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    """
    Unified method for computing advantages and returns.
    Routes to the appropriate algorithm via registry after preprocessing.
    """
    adv_type = kwargs["advantage_type"]
    fn = get_advantage_function_by_name(adv_type)
    task_type = kwargs["task_type"]

    if task_type == "embodied":
        # Embodied task preprocessing and postprocessing
        kwargs = preprocess_embodied_advantages_inputs(**kwargs)
        if adv_type != "gae":
            kwargs = calculate_scores(**kwargs)
        advantages, returns = fn(**kwargs)
        result = postprocess_embodied_advantages_outputs(
            advantages=advantages, returns=returns, **kwargs
        )
    else:
        # Reasoning task handling
        kwargs = preprocess_reasoning_advantages_inputs(**kwargs)
        advantages, returns = fn(**kwargs)
        result = postprocess_reasoning_advantages_outputs(advantages, returns)

    return result

# All gateway errors now follow a consistent structure:
# {"error": "<human-readable message>", "code": "<ERROR_CODE>", "status": <http_status>}
# Usage
# -----
# Raise ``CastorAPIError`` within any endpoint to return a formatted error response
# without manually building a ``JSONResponse``::
#     from castor.api_errors import CastorAPIError
#     raise CastorAPIError("BRAIN_NOT_READY", "Brain is not initialized", 503)
# Call ``install_error_handlers(app)`` once during app initialization to set up
# the global exception handlers.
"""
from __future__ import annotations
import logging
from fastapi import HTTPException, Request
from fastapi.responses import JSONResponse

logger = logging.getLogger("OpenCastor.Gateway")

class CastorAPIError(Exception):
    """Raise this exception to emit a standardized JSON error from any endpoint."""
    def __init__(self, code: str, message: str, status: int = 400):
        self.code = code
        self.message = message
        self.status = status
        super().__init__(message)

def install_error_handlers(app) -> None:
    """Register global exception handlers for the FastAPI *app* instance.
    Should be invoked after creating the ``app`` object and before processing
    requests (e.g., at module level in ``api.py``).
    """
    @app.exception_handler(CastorAPIError)
    async def _castor_exception_handler(request: Request, exc: CastorAPIError):
        return JSONResponse(
            status_code=exc.status,
            content={"error": exc.message, "code": exc.code, "status": exc.status},
        )

    @app.exception_handler(HTTPException)
    async def _http_exception_handler(request: Request, exc: HTTPException):
        detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail)
        return JSONResponse(
            status_code=exc.status_code,
            content={
                "error": detail,
                "code": f"HTTP_{exc.status_code}",
                "status": exc.status_code,
            },
        )

    @app.exception_handler(Exception)
    async def _generic_exception_handler(request: Request, exc: Exception):
        logger.exception("Unhandled gateway error on %s %s", request.method, request.url.path)
        return JSONResponse(
            status_code=500,
            content={
                "error": "Internal server error",
                "code": "INTERNAL_ERROR",
                "status": 500,
            },
        )

