# Analyze agent project structure and extract key components
from __future__ import annotations
import json
import os
import sys
from collections import defaultdict

def inspect_agent_layout(agent_path):
    """Inspect the layout of an agent directory."""
    output = {"files": [], "imports": defaultdict(list), "classes": [], "functions": []}
    for dirpath, _, filenames in os.walk(agent_path):
        for filename in filenames:
            if filename.endswith(".py"):
                full_path = os.path.join(dirpath, filename)
                relative = os.path.relpath(full_path, agent_path)
                output["files"].append(relative)
                # Basic parsing to gather imports, classes, and functions
                with open(full_path, encoding="utf-8", errors="ignore") as file_obj:
                    text = file_obj.read()
                    # Collect import statements
                    for line in text.split("\n"):
                        stripped = line.strip()
                        if stripped.startswith(("import ", "from ")):
                            stripped.split()[1]
                            output["imports"][relative].append(stripped)
                    # Simple class name extraction
                    for line in text.split("\n"):
                        stripped = line.strip()
                        if stripped.startswith("class "):
                            class_name = stripped.split("class ")[1].split("(")[0].strip()
                            output["classes"].append(f"{relative}: {class_name}")
                    # Simple function name extraction (top-level only)
                    for line in text.split("\n"):
                        stripped = line.strip()
                        if stripped.startswith("def ") and not stripped.startswith("    def"):
                            func_name = stripped.split("def ")[1].split("(")[0].strip()
                            output["functions"].append(f"{relative}: {func_name}")
    return output

def inspect_all_agents(root_dir):
    """Inspect all agents in the specified root directory."""
    summaries = {}
    # Identify potential agent directories
    for entry in os.listdir(root_dir):
        entry_path = os.path.join(root_dir, entry)
        if os.path.isdir(entry_path):
            # Look for typical agent files
            agent_indicators = ["agent.py", "config.py", "state.py"]
            if any(
                os.path.exists(os.path.join(entry_path, indicator))
                for indicator in agent_indicators
            ):
                summaries[entry] = inspect_agent_layout(entry_path)
    return summaries

def discover_shared_patterns(summaries):
    """Discover shared patterns across various agents."""
    shared_files = set()
    initial = True
    for _name, info in summaries.items():
        if initial:
            shared_files = set(info["files"])
            initial = False
        else:
            shared_files = shared_files.intersection(set(info["files"]))
    return {
        "shared_files": sorted(shared_files),
        "file_occurrences": count_file_occurrences(summaries),
    }

def count_file_occurrences(summaries):
    """Determine how frequently each file appears across agents."""
    counts = defaultdict(int)
    for _name, info in summaries.items():
        for filepath in info["files"]:
            counts[filepath] += 1
    return dict(sorted(counts.items(), key=lambda x: x[1], reverse=True))

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(1)
    agents_root = sys.argv[1]
    if not os.path.exists(agents_root):
        sys.exit(1)
    analysis_results = inspect_all_agents(agents_root)
    # Display shared patterns
    shared_info = discover_shared_patterns(analysis_results)
    for filepath in shared_info["shared_files"]:
        pass
    for filepath, freq in list(shared_info["file_occurrences"].items())[:10]:
        pass
    # Save detailed results to JSON
    with open("agent_inspection.json", "w") as output_file:
        json.dump(analysis_results, output_file, indent=2)

# Database health verification module
from sqlalchemy import text
from statgpt.common.config import Versions
from statgpt.common.config import multiline_logger as logger
from statgpt.common.settings.database import PostgresSettings
from .database import get_session_context_manager

class TableMissingError(RuntimeError):
    pass

class VersionMismatchError(RuntimeError):
    pass

class HealthMonitor:
    def __init__(self):
        self._db_config = PostgresSettings()

    @classmethod
    async def verify_migration_status(cls) -> None:
        async with get_session_context_manager() as conn:
            result = await conn.execute(
                text(
                    "SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'alembic_version');"
                )
            )
            exists: bool = result.scalar()  # type: ignore[assignment]
            if not exists:
                raise TableMissingError("Migration tracking table is missing")

            result = await conn.execute(text("SELECT version_num FROM alembic_version;"))
            current_version: str = result.scalar()  # type: ignore[assignment]

            if current_version != Versions.ALEMBIC_TARGET_VERSION:
                logger.error(
                    f"{current_version=}, EXPECTED_VERSION={Versions.ALEMBIC_TARGET_VERSION!r}"
                )
                raise VersionMismatchError("Database migration version mismatch")

    async def validate(self) -> None:
        for trial in range(self._db_config.alembic_max_retries):
            try:
                await self.verify_migration_status()
            except (TableMissingError, VersionMismatchError) as err:
                logger.error(
                    f"Attempt {trial + 1}/{self._db_config.alembic_max_retries} failed: {str(err)}"
                )
                if trial < self._db_config.alembic_max_retries - 1:
                    delay = self._db_config.alembic_retry_interval * (2**trial)
                    logger.info(f"Waiting {delay:.2f} seconds before retry...")
                    await asyncio.sleep(delay)
                else:
                    raise

import ast
import re
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple

class DocstringCreator:
    """Automatically produce docstrings by examining code structure."""
    def __init__(self):
        self.created_count = 0
        self.ignored_count = 0

    def inspect_function(self, node: ast.FunctionDef) -> dict[str, Any]:
        """Examine a function node to gather details for docstring creation."""
        details = {
            "name": node.name,
            "parameters": [],
            "return_type": None,
            "exceptions": set(),
            "is_async_func": isinstance(node, ast.AsyncFunctionDef),
            "is_property_method": False,
            "is_class_method": False,
            "is_static_method": False,
            "contains_yield": False,
            "difficulty_score": 0,
        }

        # Inspect decorators
        for dec in node.decorator_list:
            if isinstance(dec, ast.Name):
                if dec.id == "property":
                    details["is_property_method"] = True
                elif dec.id == "classmethod":
                    details["is_class_method"] = True
                elif dec.id == "staticmethod":
                    details["is_static_method"] = True

        # Collect parameter information
        for param in node.args.args:
            if param.arg not in ["self", "cls"]:
                param_detail = {"name": param.arg, "type_hint": None, "default_value": None}
                if param.annotation:
                    param_detail["type_hint"] = ast.unparse(param.annotation)
                details["parameters"].append(param_detail)

        # Capture return type annotation
        if node.returns:
            details["return_type"] = ast.unparse(node.returns)

        # Analyze function body
        for subnode in ast.walk(node):
            # Look for raise statements
            if isinstance(subnode, ast.Raise):
                if isinstance(subnode.exc, ast.Call) and isinstance(
                    subnode.exc.func, ast.Name
                ):
                    details["exceptions"].add(subnode.exc.func.id)
                elif isinstance(subnode.exc, ast.Name):
                    details["exceptions"].add(subnode.exc.id)

            # Check for yield expressions
            if isinstance(subnode, ast.Yield | ast.YieldFrom):
                details["contains_yield"] = True

            # Basic complexity calculation
            if isinstance(subnode, ast.If | ast.For | ast.While | ast.Try):
                details["difficulty_score"] += 1

        return details

    def produce_function_docstring(self, func_details: dict[str, Any]) -> str:
        """Create a docstring for a function using extracted information."""
        sections = []

        # Brief summary line
        brief = self._produce_summary(func_details)
        sections.append(f'"""{brief}')

        # Detailed description for complex functions
        if func_details["difficulty_score"] > 3 or len(func_details["parameters"]) > 3:
            sections.append("")
            sections.append(self._produce_detailed_description(func_details))

        # Parameters section
        if func_details["parameters"]:
            sections.append("")
            sections.append("Parameters:")
            for param in func_details["parameters"]:
                param_desc = self._produce_parameter_description(param)
                if param["type_hint"]:
                    sections.append(f"    {param['name']}: {param_desc}")
                else:
                    sections.append(f"    {param['name']}: {param_desc}")

        # Return value section
        if func_details["return_type"] or not func_details["is_property_method"]:
            sections.append("")
            sections.append("Returns:")
            returns_desc = self._produce_return_description(func_details)
            sections.append(f"    {returns_desc}")

        # Exceptions section
        if func_details["exceptions"]:
            sections.append("")
            sections.append("Raises:")
            for exc in sorted(func_details["exceptions"]):
                exc_desc = self._produce_exception_description(exc)
                sections.append(f"    {exc}: {exc_desc}")

        # Yields section for generators
        if func_details["contains_yield"]:
            sections.append("")
            sections.append("Yields:")
            sections.append("    Values produced during iteration.")

        # Examples section for public methods with moderate complexity
        if not func_details["name"].startswith("_") and func_details["difficulty_score"] > 2:
            sections.append("")
            sections.append("Examples:")
            sections.append(self._produce_example(func_details))

        sections.append('"""')
        return "\n".join(sections)

    def _produce_summary(self, func_details: dict[str, Any]) -> str:
        """Produce a concise one-line summary for a function."""
        name = func_details["name"]

        # Pattern-based summaries
        if name.startswith("get_"):
            return f"Retrieve {name[4:].replace('_', ' ')}."
        if name.startswith("set_"):
            return f"Set {name[4:].replace('_', ' ')}."
        elif name.startswith("is_"):
            return f"Determine whether {name[3:].replace('_', ' ')}."
        elif name.startswith("has_"):
            return f"Check if the object contains {name[4:].replace('_', ' ')}."
        elif name.startswith("create_"):
            return f"Create {name[7:].replace('_', ' ')}."
        elif name.startswith("update_"):
            return f"Update {name[7:].replace('_', ' ')}."
        elif name.startswith("delete_"):
            return f"Remove {name[7:].replace('_', ' ')}."
        elif name.startswith("validate_"):
            return f"Validate {name[9:].replace('_', ' ')}."
        elif name.startswith("process_"):
            return f"Process {name[8:].replace('_', ' ')}."
        elif name.startswith("handle_"):
            return f"Handle {name[7:].replace('_', ' ')}."
        elif name == "__init__":
            return "Initialize the class instance."
        elif name == "__str__":
            return "Provide string representation of the object."
        elif name == "__repr__":
            return "Provide unambiguous representation of the object."
        elif func_details["is_property_method"]:
            return f"Access the {name.replace('_', ' ')} property."
        elif func_details["is_async_func"]:
            return f"Execute {name.replace('_', ' ')} asynchronously."
        else:
            return f"{name.replace('_', ' ').capitalize()}."

    def _produce_detailed_description(self, func_details: dict[str, Any]) -> str:
        """Generate detailed description for complex functions."""
        if func_details["is_async_func"]:
            return "This is an asynchronous function that must be awaited."
        if func_details["contains_yield"]:
            return "This generator function yields results lazily as they become available."
        elif func_details["difficulty_score"] > 5:
            return "This function implements sophisticated logic with multiple decision points."
        else:
            param_count = len(func_details['args']) if 'args' in func_details else len(func_details['parameters'])
            return f"This function processes {param_count} inputs to compute the output."

    def _produce_parameter_description(self, param: dict[str, Any]) -> str:
        """Create description for a function parameter."""
        name = param["name"]
        param_type = param["type_hint"]

        # Type-based descriptions
        if param_type:
            if "str" in param_type:
                return f"The {name.replace('_', ' ')} string argument."
            if "int" in param_type:
                return f"The {name.replace('_', ' ')} integer value."
            elif "float" in param_type:
                return f"The {name.replace('_', ' ')} floating-point number."
            elif "bool" in param_type:
                return f"Whether to enable {name.replace('_', ' ')}."
            elif "List" in param_type:
                return f"Collection of {name.replace('_', ' ')}."
            elif "Dict" in param_type:
                return f"Mapping containing {name.replace('_', ' ')}."
            elif "Optional" in param_type:
                return f"Optional {name.replace('_', ' ')} value."

        # Name-based descriptions
        if name == "config":
            return "Configuration dictionary with settings."
        if name == "data":
            return "Input data to be processed."
        elif name == "context":
            return "Execution context for the operation."
        elif name == "callback":
            return "Function to be called upon completion."
        elif name.endswith("_id"):
            return f"Unique identifier for {name[:-3].replace('_', ' ')}."
        elif name.endswith("_path"):
            return f"File system path to {name[:-5].replace('_', ' ')}."
        elif name.endswith("_url"):
            return f"Web address for {name[:-4].replace('_', ' ')}."
        else:
            return f"The {name.replace('_', ' ')} parameter."

    def _produce_return_description(self, func_details: dict[str, Any]) -> str:
        """Create description for the return value."""
        return_type = func_details["return_type"]
        name = func_details["name"]

        if return_type:
            if return_type == "None":
                return "No value returned."
            if return_type == "bool":
                return "True when successful, False otherwise."
            elif return_type == "str":
                return "The resulting string value."
            elif return_type == "int":
                return "The computed integer result."
            elif return_type == "float":
                return "The computed floating-point result."
            elif "List" in return_type:
                return "A list containing the results."
            elif "Dict" in return_type:
                return "A dictionary with the computed results."
            elif "Optional" in return_type:
                return "The result if available, otherwise None."
            else:
                return f"The {return_type} result."

        # Name-based inference
        if name.startswith(("is_", "has_")):
            return "Boolean indicating whether the condition holds."
        if name.startswith(("get_", "find_")):
            return "The requested value or None if not found."
        elif name.startswith(("create_", "build_")):
            return "The newly created object instance."
        elif func_details["is_property_method"]:
            return f"The current value of the {name.replace('_', ' ')} property."
        else:
            return "The processed output result."

    def _produce_exception_description(self, exc_name: str) -> str:
        """Create description for an exception type."""
        standard_exceptions = {
            "ValueError": "When the provided value does not meet requirements.",
            "TypeError": "When the input has an incorrect data type.",
            "KeyError": "When the expected key is absent from the mapping.",
            "AttributeError": "When the required attribute is missing.",
            "RuntimeError": "When an unexpected runtime issue occurs.",
            "NotImplementedError": "When the functionality is not yet implemented.",
            "FileNotFoundError": "When the specified file cannot be located.",
            "PermissionError": "When access is denied due to insufficient permissions.",
            "ConnectionError": "When network connection fails.",
            "TimeoutError": "When the operation exceeds the time limit.",
        }
        return standard_exceptions.get(exc_name, f"When {exc_name.lower()} occurs.")

    def _produce_example(self, func_details: dict[str, Any]) -> str:
        """Generate a simple usage example for a function."""
        name = func_details["name"]
        params = func_details["parameters"]

        # Build example call
        if params:
            arg_examples = []
            for param in params[:3]:  # Limit to first 3 arguments
                if param["type_hint"] and "str" in param["type_hint"]:
                    arg_examples.append(f'"{param["name"]}_value"')
                elif param["type_hint"] and "int" in param["type_hint"]:
                    arg_examples.append("42")
                elif param["type_hint"] and "bool" in param["type_hint"]:
                    arg_examples.append("True")
                else:
                    arg_examples.append(f"{param['name']}_value")
            args_str = ", ".join(arg_examples)
            example = f"    >>> outcome = {name}({args_str})"
        else:
            example = f"    >>> outcome = {name}()"

        if func_details["is_async_func"]:
            example = f"    >>> outcome = await {name}()"

        return example

    def inspect_class(self, node: ast.ClassDef) -> dict[str, Any]:
        """Examine a class node to extract relevant information."""
        info = {
            "name": node.name,
            "parent_classes": [],
            "methods": [],
            "attributes": [],
            "is_dataclass_style": False,
            "is_pydantic_model": False,
        }

        # Extract base classes
        for base in node.bases:
            if isinstance(base, ast.Name):
                info["parent_classes"].append(base.id)
                if base.id in ["BaseModel", "BaseSettings"]:
                    info["is_pydantic_model"] = True

        # Check for dataclass decorator
        for dec in node.decorator_list:
            if isinstance(dec, ast.Name) and dec.id == "dataclass":
                info["is_dataclass_style"] = True

        # Extract method names
        for item in node.body:
            if isinstance(item, ast.FunctionDef):
                info["methods"].append(item.name)

        return info

    def produce_class_docstring(self, class_info: dict[str, Any]) -> str:
        """Create a docstring for a class based on analysis."""
        lines = []
        name = class_info["name"]

        # Summary line
        if class_info["is_pydantic_model"]:
            lines.append(f'"""{name} Pydantic model definition.')
        elif class_info["is_dataclass_style"]:
            lines.append(f'"""{name} data container class.')
        elif class_info["parent_classes"]:
            lines.append(f'"""{name} class extending {", ".join(class_info["parent_classes"])}.')
        else:
            lines.append(f'"""{name} implementation class.')

        # Extended description
        lines.append("")
        if class_info["is_pydantic_model"]:
            lines.append("This model provides data validation and serialization capabilities.")
        elif class_info["is_dataclass_style"]:
            lines.append("This class serves as a convenient container for structured data.")
        else:
            lines.append(
                f"This class implements {name.replace('_', ' ').lower()} functionality."
            )

        # Attributes section
        if class_info["attributes"]:
            lines.append("")
            lines.append("Attributes:")
            for attr in class_info["attributes"]:
                lines.append(f"    {attr}: Description of {attr}.")

        # Methods section
        if class_info["methods"]:
            public_methods = [m for m in class_info["methods"] if not m.startswith("_")]
            if public_methods:
                lines.append("")
                lines.append("Methods:")
                for method in public_methods[:5]:  # Limit to first 5
                    lines.append(
                        f"    {method}: {method.replace('_', ' ').capitalize()}."
                    )

        lines.append('"""')
        return "\n".join(lines)

    def produce_module_docstring(self, file_path: Path) -> str:
        """Generate a module-level docstring."""
        module_name = file_path.stem

        # Special cases
        if module_name == "__init__":
            parent = file_path.parent.name
            return f'"""Package initialization for {parent}."""'
        if module_name == "config":
            return '"""Module for configuration management."""'
        elif module_name == "utils":
            return '"""Collection of utility helper functions."""'
        elif module_name == "models":
            return '"""Data models and schema definitions."""'
        elif module_name == "exceptions":
            return '"""Custom exception class definitions."""'
        elif module_name.startswith("test_"):
            return f'"""Test suite for {module_name[5:].replace("_", " ")}."""'
        else:
            return f'"""{module_name.replace("_", " ").capitalize()} module implementation."""'

    def handle_file(self, file_path: Path, simulation: bool = False) -> bool:
        """Process a single file to insert docstrings."""
        try:
            with open(file_path, encoding="utf-8") as source_file:
                content = source_file.read()

            # Parse AST
            tree = ast.parse(content)

            # Check if module docstring exists
            has_module_docstring = (
                isinstance(tree.body[0], ast.Expr)
                and isinstance(tree.body[0].value, ast.Constant)
                and isinstance(tree.body[0].value.value, str)
            )

            changes = []

            # Add module docstring if missing
            if not has_module_docstring:
                module_doc = self.produce_module_docstring(file_path)
                changes.append((0, 0, module_doc + "\n\n"))

            # Process functions and classes
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    if not ast.get_docstring(node):
                        func_details = self.inspect_function(node)
                        docstring = self.produce_function_docstring(func_details)
                        # Calculate indentation
                        indent = "    " * (node.col_offset // 4)
                        changes.append(
                            (node.lineno, node.col_offset, f"{indent}{docstring}")
                        )
                        self.created_count += 1

                elif isinstance(node, ast.ClassDef) and not ast.get_docstring(node):
                    class_info = self.inspect_class(node)
                    docstring = self.produce_class_docstring(class_info)
                    indent = "    " * (node.col_offset // 4)
                    changes.append(
                        (node.lineno, node.col_offset, f"{indent}{docstring}")
                    )
                    self.created_count += 1

            if changes and not simulation:
                # Apply modifications
                lines = content.split("\n")
                # Sort by line number (descending) to avoid offset issues
                changes.sort(key=lambda x: x[0], reverse=True)
                for line_no, _col_offset, docstring in changes:
                    if line_no == 0:
                        # Module docstring
                        lines.insert(0, docstring)
                    else:
                        # Function/class docstring
                        # Insert after the definition line
                        lines.insert(line_no, docstring)

                # Write back
                with open(file_path, "w", encoding="utf-8") as target_file:
                    target_file.write("\n".join(lines))
                return True

            return bool(changes)

        except Exception as error:
            return False

def main():
    """Main entry point for the application."""
    import argparse
    parser = argparse.ArgumentParser(description="Automatically generate docstrings for Python files")
    parser.add_argument("target", help="File or directory to process")
    parser.add_argument(
        "--dry-run", action="store_true", help="Show what would be modified without making changes"
    )
    args = parser.parse_args()

    creator = DocstringCreator()
    target = Path(args.target)

    if target.is_file():
        if creator.handle_file(target, args.dry_run):
            pass
    elif target.is_dir():
        files = list(target.rglob("*.py"))
        for file in files:
            if "__pycache__" not in str(file):
                if creator.handle_file(file, args.dry_run):
                    pass

if __name__ == "__main__":
    main()

import platform
import subprocess
from pathlib import Path
from .helpers import (
    SOURCE_FNM,
    NotInstalledError,
    get_itk_dir,
    get_node_binaries_dir,
    get_nvm_dir,
    get_viewer_dir,
    run_for_platform,
)

class SetupManager:
    """
    Handles the setup process of itk-vtk-viewer across different operating systems.
    Also supports partial installation by verifying if required binaries are already present.
    """
    def __init__(self):
        self.os_type = platform.system()
        self.setup_steps = (
            self.setup_node_manager,
            self.setup_runtime,
            self.setup_viewer,
        )
        self.base_dir = get_itk_dir()  # directory for itk_vtk_viewer within qim3d.viz
        # Check if NVM_DIR is set (could be from prior installation or user configuration)
        self.sys_nvm_path = os.getenv('NVM_DIR')
        if self.sys_nvm_path is not None:
            self.sys_nvm_path = Path(self.sys_nvm_path)
        self.local_nvm_path = get_nvm_dir(self.base_dir)
        if not os.path.isdir(self.local_nvm_path):
            os.mkdir(self.local_nvm_path)

    @property
    def node_manager_exists(self) -> bool:
        """
        Determines whether nvm (Node Version Manager) is globally or locally installed.
        """
        def _unix_like() -> bool:
            cmd_template = lambda nvmsh: f'/bin/bash -c "source {nvmsh} && nvm"'
            if self.sys_nvm_path is not None:
                nvm_script = self.sys_nvm_path / 'nvm.sh'
                result = subprocess.run(
                    cmd_template(nvm_script), shell=True, capture_output=True
                )
                if not result.stderr:
                    self.nvm_root = self.sys_nvm_path
                    return True
            nvm_script = self.local_nvm_path / 'nvm.sh'
            result = subprocess.run(cmd_template(nvm_script), shell=True, capture_output=True)
            self.nvm_root = self.local_nvm_path
            return not bool(result.stderr)
        def _win() -> bool:
            result = subprocess.run(
                ['powershell.exe', 'fnm --version'], capture_output=True
            )
            return not bool(result.stderr)
        return run_for_platform(
            linux_func=_unix_like, windows_func=_win, macos_func=_unix_like
        )

    @property
    def runtime_exists(self) -> bool:
        """
        Verifies presence of Node.js and npm (Node Package Manager).
        """
        def _unix_like() -> bool:
            bin_path = get_node_binaries_dir(self.nvm_root)
            path_str = f'"{bin_path}"' if bin_path else ''
            command = f'export PATH="$PATH:{path_str}" && npm version'
            result = subprocess.run(command, shell=True, capture_output=True)
            return not bool(result.stderr)
        def _win() -> bool:
            # Local npm installation is enforced on Windows for proper viewer operation
            return False
        return run_for_platform(
            linux_func=_unix_like, windows_func=_win, macos_func=_unix_like
        )

    def execute_setup(self):
        """
        Begins installation only if needed. Skips steps already completed.
        """
        if self.node_manager_exists:
            self.setup_progress = 1
            print('Node manager already available')
            if self.runtime_exists:
                self.setup_progress = 2
                print('Runtime environment already configured')
        else:
            self.setup_progress = 0
        for step in self.setup_steps[self.setup_progress:]:
            step()

    def setup_node_manager(self):
        def _unix_like():
            print(f'Setting up Node manager at {self.nvm_root}...')
            _ = subprocess.run(
                [
                    f'export NVM_DIR={self.nvm_root} && bash {self.base_dir / "install_nvm.sh"}'
                ],
                shell=True,
                capture_output=True,
            )
        def _win():
            print('Configuring node manager...')
            subprocess.run(
                [
                    'powershell.exe',
                    f'$env:XDG_DATA_HOME = "{self.base_dir}";',
                    'winget install Schniz.fnm',
                ]
            )
        run_for_platform(linux_func=_unix_like, windows_func=_win, macos_func=_unix_like)
        print('Node manager setup complete')

    def setup_runtime(self):
        def _unix_like():
            print(f'Installing Node.js into {self.nvm_root}...')
            if self.setup_progress == 0:
                target_dir = self.nvm_root
                prefix = f'export NVM_DIR={target_dir} && '
            elif self.setup_progress == 1:
                target_dir = self.sys_nvm_path
                prefix = ''
            nvm_script = Path(target_dir) / 'nvm.sh'
            command = f'{prefix}/bin/bash -c "source {nvm_script} && nvm install 22"'
            result = subprocess.run(command, shell=True, capture_output=True)
        def _win():
            subprocess.run(
                [
                    'powershell.exe',
                    f'$env:XDG_DATA_HOME = "{self.base_dir}";',
                    SOURCE_FNM,
                    f'fnm use --fnm-dir {self.base_dir} --install-if-missing 22',
                ]
            )
        print('Setting up Node.js runtime...')
        run_for_platform(linux_func=_unix_like, windows_func=_win, macos_func=_unix_like)
        print('Node.js runtime ready')

    def setup_viewer(self):
        def _unix_like():
            bin_dir = get_node_binaries_dir(self.nvm_root)
            command = f'export PATH="$PATH:{bin_dir}" && npm install --prefix {self.view_dir} @qim3d/itk-vtk-viewer'
            result = subprocess.run([command], shell=True, capture_output=True)
        def _win():
            try:
                node_bin = get_node_binaries_dir(self.base_dir)
                print(f'Installing into {self.view_dir}')
                subprocess.run(
                    [
                        'powershell.exe',
                        f"$env:PATH=$env:PATH + ';{node_bin}';",
                        f'npm install --prefix {self.view_dir} @qim3d/itk-vtk-viewer',
                    ],
                    capture_output=True,
                )
            except NotInstalledError:  # Fallback to global npm if local install failed
                subprocess.run(
                    ['powershell.exe', SOURCE_FNM, 'npm install @qim3d/itk-vtk-viewer'],
                    capture_output=True,
                )
        self.view_dir = get_viewer_dir(self.base_dir)
        if not os.path.isdir(self.view_dir):
            os.mkdir(self.view_dir)
        print('Installing itk-vtk-viewer...')
        run_for_platform(linux_func=_unix_like, windows_func=_win, macos_func=_unix_like)
        print('itk-vtk-viewer installation complete')

# Compatibility adapter for RenderDoc API changes across versions
import re
from dataclasses import dataclass
from typing import Any

def extract_version_numbers(version_string: str) -> tuple[int, int]:
    """Extract major and minor version numbers from a RenderDoc version string."""
    pattern = re.search(r"(\d+)\.(\d+)", version_string)
    if not pattern:
        return (0, 0)
    return int(pattern.group(1)), int(pattern.group(2))

@dataclass(frozen=True)
class RenderDocControllerAdapter:
    """Compatibility wrapper to handle API differences between RenderDoc versions."""
    controller_handle: Any
    version_info: tuple[int, int]

    def retrieve_initial_actions(self) -> Any:
        """Get initial draw actions with version-compatible method selection."""
        if self.version_info >= (1, 32) and hasattr(self.controller_handle, "GetRootActions"):
            return self.controller_handle.GetRootActions()
        if hasattr(self.controller_handle, "GetDrawcalls"):
            return self.controller_handle.GetDrawcalls()
        raise AttributeError("controller does not support GetRootActions or GetDrawcalls")

    def fetch_api_details(self) -> Any:
        """Fetch API properties from the underlying controller."""
        return self.controller_handle.GetAPIProperties()

    def list_all_resources(self) -> Any:
        """Retrieve all available resources from the controller."""
        return self.controller_handle.GetResources()

    def obtain_pipeline_state(self) -> Any:
        """Get current graphics/compute pipeline state."""
        return self.controller_handle.GetPipelineState()

    def access_structured_log(self) -> Any:
        """Access structured log file from the controller."""
        return self.controller_handle.GetStructuredFile()

    def navigate_to_event(self, event_id: int, enforce: bool = True) -> None:
        """Replay up to the specified event ID."""
        self.controller_handle.SetFrameEvent(event_id, enforce)

    def enumerate_textures(self) -> Any:
        """List all texture descriptions available in the capture."""
        return self.controller_handle.GetTextures()

    def enumerate_buffers(self) -> Any:
        """List all buffer descriptions available in the capture."""
        return self.controller_handle.GetBuffers()

    def terminate_replay(self) -> None:
        """Cleanly shut down the replay controller."""
        self.controller_handle.Shutdown()

