# PyFT8 main application - FT8 decoder and transmitter
import time
import os
import threading
from PyFT8.receiver import Receiver, AudioIn
from PyFT8.gui import Gui
from PyFT8.transmitter import AudioOut

def initialize_rig_control():
    try:
        from Rigctrl.rig import Rig
        print("Rig control module loaded successfully")
        return Rig()
    except ImportError:
        print("Warning: Rig control not available")
        return None

def load_or_create_config(config_filename = 'PyFT8.pkl'):
    import pickle
    global configuration
    if os.path.exists(config_filename):
        with open(config_filename, 'rb') as file:
            configuration = pickle.load(file)
    else:
        callsign = input("Enter your callsign: ")
        locator = input("Enter your 4-character grid square: ")
        configuration = {'mStation': {'c':callsign, 'g':locator}}
        with open(config_filename, 'wb') as file:
            pickle.dump(configuration, file)

class FT8_QSO:
    def initialize(self):
        self.remote_station = {'c':None, 'g':None}
        self.local_station = configuration['mStation']
        self.frequency_info = {'b':'20m', 'f':14.074}
        self.timing = {'time_on':None, 'time_off':None}
        self.reports = {'sent': None, 'rcvd': None}

    def write_adif_log(self, log_file = "PyFT8.adif"):
        log_data = {'call':self.remote_station['c'], 'gridsquare':self.remote_station['g'], 'mode':'FT8',
        'operator':self.local_station['c'], 'station_callsign':self.local_station['c'], 'my_gridsquare':self.local_station['g'], 
        'rst_sent':self.reports['sent'], 'rst_rcvd':self.reports['rcvd'], 
        'qso_date':time.strftime("%Y%m%d", self.timing['time_on']), 'qso_date_off':time.strftime("%Y%m%d", self.timing['time_off']),
        'time_on':time.strftime("%H%M%S", self.timing['time_on']), 'time_off':time.strftime("%H%M%S", self.timing['time_on']),
        'band':self.frequency_info['b'], 'freq':self.frequency_info['f']}
        if(not os.path.exists(log_file)):
            with open(log_file, 'w') as file:
                file.write("header <eoh>")
        with open(log_file,'a') as file:
            file.write(f"\n")
            for key, value in log_data.items():
                value_str = str(value)
                file.write(f"<{key}:{len(value_str)}>{value_str} ")
            file.write(f"<eor>\n")

def get_current_cycle_time():
    return time.time() % 15

def check_immediate_transmit():
    current_time = get_current_cycle_time()
    return True if 0.5 < current_time < 2.5 else False

def is_report_message(msg):         return "+" in msg or "-" in msg
def is_response_report(msg):        return is_report_message(msg) and 'R' in msg
def is_rrr(msg):                    return 'RRR' in msg
def is_rr73(msg):                   return 'RR73' in msg
def is_73(msg):                     return '73' in msg and not is_rr73(msg)
def is_grid_locator(msg):           return not is_report_message(msg) and not is_73(msg) and not is_rr73(msg) and not is_rrr(msg) 

def handle_message_click(decoded_msg, msg_source, snr_value):
    global qso_session
    cycle_start = time.time() - (time.time() % 15) + 15 * int(msg_source[0] / (audio_in.hops_per_grid/2))
    if time.time() - cycle_start > 17.5:
        print("Message received too late")
        return
    call_a, call_b, grid_rpt, _ = decoded_msg.split()
    my_callsign = configuration['mStation']
    response = ""
    if call_a == "CQ":
        qso_session.initialize()
        qso_session.timing['time_on'] = time.gmtime()
        qso_session.remote_station = {'c': call_b, 'g': grid_rpt}
        response = f"{qso_session.remote_station['c']} {my_callsign['c']} {my_callsign['g']}"
        transmit_async(response, immediate = check_immediate_transmit())
        return
    if call_a == my_callsign['c']:
        if qso_session.remote_station['c'] is None:
            qso_session.remote_station['c'] = call_b
        if is_grid_locator(grid_rpt):
            qso_session.remote_station = {'c': call_b, 'g': grid_rpt}
            qso_session.reports['sent'] = f"{snr_value:+03d}"
            response = f"{qso_session.remote_station['c']} {my_callsign['c']} {snr_value:+03d}"
        if is_report_message(grid_rpt):
            response = f"{qso_session.remote_station['c']} {my_callsign['c']} R{snr_value:+03d}"
            qso_session.reports['rcvd'] = grid_rpt[-3:]
        if is_response_report(grid_rpt) or is_rrr(grid_rpt):
            response = f"{qso_session.remote_station['c']} {my_callsign['c']} RR73"
        if is_rr73(grid_rpt):
            response = f"{qso_session.remote_station['c']} {my_callsign['c']} 73"
        transmit_async(response, immediate = check_immediate_transmit())

    if is_73(grid_rpt) or " 73" in response or is_rr73(grid_rpt):
        qso_session.timing['time_off'] = time.gmtime()
        qso_session.write_adif_log()

def generate_audio_file(message, output_path):
    symbols = audio_out.create_ft8_symbols(message)
    audio_samples = audio_out.create_ft8_wave(symbols)
    audio_out.write_to_wave_file(audio_samples, output_path)
    print(f"Audio file created: {output_path}")    

def transmit_async(message, immediate = False):
    threading.Thread(target = transmit_message, args = (message, immediate,), daemon = True).start()

def transmit_message(message, immediate = False):
    print(f"Transmitting: {message}")
    if output_device_index is None:
        print("Error: No audio output device configured")
        return
    symbols = audio_out.create_ft8_symbols(message)
    audio_data = audio_out.create_ft8_wave(symbols)
    if not immediate:
        delay = 15 - ((time.time()-0.5) % 15)
        if delay > 0:
            time.sleep(delay)
    print("Starting transmission")
    rig.ptt_on()
    audio_out.play_data_to_soundcard(audio_data, output_device_index)
    rig.ptt_off()
    return True

def wait_for_interrupt():
    import time
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        pass

#============= GUI Callbacks ==========================================================
def handle_decode_event(event_data):
    if gui_instance:
        gui_instance.post_decode(event_data.h0_idx, event_data.f0_idx, event_data.msg, event_data.snr)
    print(f"{event_data.cyclestart_str} {event_data.snr} {event_data.dt:4.1f} {event_data.fHz} ~ {event_data.msg}")

def handle_button_click(btn_label, btn_location, btn_data):
    if btn_label == "CQ":
        mc, mg = configuration['mStation']['c'], configuration['mStation']['g']
        transmit_async(f"CQ {mc} {mg}", immediate = check_immediate_transmit())
    if btn_label == "Tx off":
        rig.ptt_off()
    if('m' in btn_label):
        qso_session.frequency_info = {'b':btn_label, 'f':btn_data}
        rig.set_freq_Hz(int(1000000*btn_data))

#=============== CLI Interface ========================================================================        
def command_line_interface():
    global audio_in, audio_out, output_device_index, rig, gui_instance, qso_session
    import time
    import argparse
    parser = argparse.ArgumentParser(prog='PyFT8rx', description = 'FT8 decoder and transmitter')
    parser.add_argument('-i', '--inputcard_keywords', help = 'Comma-separated keywords to identify the input sound device') 
    parser.add_argument('-v','--verbose',  action='store_true',  help = 'Verbose mode: include debugging output')    
    parser.add_argument('-o','--outputcard_keywords', help = 'Comma-separated keywords to identify the output sound device')
    parser.add_argument('-n','--no_gui',  action='store_true',  help = 'Disable GUI window')
    parser.add_argument('-m','--transmit_message', nargs='?', help = 'Transmit a specific message')
    parser.add_argument('-w','--wave_output_file', nargs='?', help = 'Output WAV filename', default = 'PyFT8.wav')
    args = parser.parse_args()
    output_device_index = None
    gui_instance = None
    if args.outputcard_keywords:
        output_keywords = args.outputcard_keywords.replace(' ','').split(',')
        audio_out = AudioOut()
        output_device_index = audio_out.find_device(output_keywords)
        load_or_create_config()
        rig = initialize_rig_control()

    if args.transmit_message:
        if not transmit_message(args.transmit_message):
            generate_audio_file(args.transmit_message, args.wave_output_file)      
    else:
        audio_in = AudioIn(3100)
        input_device_index = audio_in.find_device(args.inputcard_keywords.replace(' ','').split(','))
        if not input_device_index:
            print("No input audio device found")
        else:
            gui_instance = None if args.no_gui else Gui(audio_in.dBgrid_main, 4, 2, configuration['mStation'], handle_message_click, handle_button_click)
            rx = Receiver(audio_in, [200, 3100], handle_decode_event)
            audio_in.start_streamed_audio(input_device_index)
            if gui_instance is not None:
                if output_device_index:
                    qso_session = FT8_QSO()
                gui_instance.plt.show()
            else:
                wait_for_interrupt()

