# Modified version of EMATeacher class with renamed variables and reordered statements
from __future__ import annotations
from typing import Any
import torch
from weathergen.model.ssl_target_processing import (
    DINOTargetProcessing,
    JEPATargetProcessing,
    iBOTPatchTargetProcessing,
)
from weathergen.train.target_and_aux_module_base import TargetAndAuxModuleBase, TargetAuxOutput

class EMATeacher(TargetAndAuxModuleBase):
    def __init__(self, student_model, teacher_model, batch_size, train_config, **kwargs):
        # One of the issues is that the teacher model may have a different architecture
        # to the student, e.g. JEPA. So we need quite a flexible way to instantiate the
        # the teacher. Because of the device sharding etc that requires quite a bit of
        # massaging we assume that the teacher creates the EMA model correctly. However,
        # note that you cannot assume that model.state_dict equals ema_model.state_dict
        self.teacher_ema_model = teacher_model
        self.batch_size_val = batch_size

        # Extract loss configurations for SSL student-teacher losses
        loss_cfg_list = [
            v.loss_fcts
            for k, v in train_config.losses.items()
            if v.type == "LossLatentSSLStudentTeacher"
        ]

        # TODO: support multiple LossLatentSSLStudentTeacher loss terms
        self.target_modules = get_target_postprocessing(loss_cfg_list[0], train_config, **kwargs)
        self.reset()

    def reset(self, batch_size=None):
        self.teacher_ema_model.reset()
        if batch_size is not None:
            self.batch_size_val = batch_size

    def update_state_pre_backward(self, step_idx, data_batch, student_model, **kwargs) -> None:
        return

    def update_state_post_opt_step(self, step_idx, data_batch, student_model, **kwargs) -> None:
        if self.teacher_ema_model.is_model_sharded:
            self.teacher_ema_model.ema_model.reshard()
        self.teacher_ema_model.update(step_idx, self.batch_size_val)

    def compute(self, batch_idx, data_batch, model_params, student_model) -> tuple[Any, Any]:
        with torch.no_grad():
            outputs = self.teacher_ema_model.forward_eval(model_params, data_batch).get_latent_prediction(0)
            targets = {}

            for loss_key, target_processor in self.target_modules.items():
                targets[loss_key] = target_processor(outputs[loss_key])

            # collect target meta-information for selected samples
            aux_data = [list(sample.meta_info.values())[0] for sample in data_batch.get_samples()]

            targets_out = TargetAuxOutput(data_batch.get_output_len(), data_batch.get_output_idxs())
            targets_out.latent = targets
            targets_out.aux_outputs = aux_data

            return targets_out

    def to_device(self, device) -> EMATeacher:
        for _, module in self.target_modules.items():
            module.to(device)
        return self

    def get_current_beta(self, current_step: int) -> float:
        beta = self.teacher_ema_model.get_current_beta(current_step)
        return beta


def get_target_postprocessing(target_losses: list[str], training_cfg, **kwargs):
    result_dict = {}

    for loss_name, conf in target_losses.items():
        if loss_name == "iBOT":
            result_dict[loss_name] = iBOTPatchTargetProcessing(
                patch_out_dim=conf["out_dim"],
                center_momentum=conf["center_momentum"],
                student_temp=conf["loss_extra_args"]["student_temp"],
                teacher_temp=conf["teacher_temp"],
                teacher_style=conf["teacher_style"],
            )
        elif loss_name == "DINO":
            result_dict[loss_name] = DINOTargetProcessing(
                out_dim=conf["out_dim"],
                center_momentum=conf["center_momentum"],
                student_temp=conf["loss_extra_args"]["student_temp"],
                teacher_style=conf["teacher_style"],
            )
        elif loss_name == "JEPA":
            result_dict[loss_name] = JEPATargetProcessing()
        else:
            # We skip losses that are not handled by the EMATeacher
            continue

    return result_dict

# Module for parsing dates and times into standardized formats
import sys
import re
from datetime import datetime

# Mapping of month names to their numeric values
MONTH_MAPPING = {
    'january': 1, 'february': 2, 'march': 3, 'april': 4,
    'may': 5, 'june': 6, 'july': 7, 'august': 8,
    'september': 9, 'october': 10, 'november': 11, 'december': 12,
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'sept': 9, 'oct': 10,
    'nov': 11, 'dec': 12
}

# Supported date format patterns
DATE_PATTERNS = [
    '%B %d, %Y', '%b %d, %Y',
    '%d %B %Y', '%d %b %Y',
    '%m/%d/%Y', '%d/%m/%Y',
    '%Y-%m-%d', '%Y/%m/%d'
]

def convert_date(date_input: str) -> str:
    """Convert various date representations to ISO format (YYYY-MM-DD)."""
    date_input = date_input.strip()

    # Attempt parsing with predefined formats
    for fmt in DATE_PATTERNS:
        try:
            parsed_dt = datetime.strptime(date_input, fmt)
            return parsed_dt.strftime('%Y-%m-%d')
        except ValueError:
            continue

    # Fallback: regex-based parsing for "Month DD, YYYY" style
    regex_pattern = r'(\w+)\s+(\d{1,2}),?\s+(\d{4})'
    match = re.search(regex_pattern, date_input, re.IGNORECASE)
    if match:
        month_str, day_str, year_str = match.groups()
        month_val = MONTH_MAPPING.get(month_str.lower())
        if month_val is not None:
            return f'{year_str}-{month_val:02d}-{int(day_str):02d}'

    return ''

def convert_time(time_input: str) -> str:
    """Convert various time representations to HH:MM format."""
    if not time_input:
        return ''

    time_input = time_input.strip()

    # Pattern for HH:MM with optional AM/PM
    time_regex1 = r'(\d{1,2}):(\d{2})\s*(am|pm)?'
    match = re.search(time_regex1, time_input, re.IGNORECASE)
    if match:
        hour_val, minute_val, ampm_val = int(match.group(1)), int(match.group(2)), match.group(3)
        if ampm_val:
            ampm_val = ampm_val.lower()
            if ampm_val == 'pm' and hour_val != 12:
                hour_val += 12
            elif ampm_val == 'am' and hour_val == 12:
                hour_val = 0
        return f'{hour_val:02d}:{minute_val:02d}'

    # Pattern for hour-only with AM/PM
    time_regex2 = r'(\d{1,2})\s*(am|pm)'
    match = re.search(time_regex2, time_input, re.IGNORECASE)
    if match:
        hour_val, ampm_val = int(match.group(1)), match.group(2).lower()
        if ampm_val == 'pm' and hour_val != 12:
            hour_val += 12
        elif ampm_val == 'am' and hour_val == 12:
            hour_val = 0
        return f'{hour_val:02d}:00'

    return ''

def main():
    if len(sys.argv) < 3:
        print("Usage: date_parser.py <date|time> <value>", file=sys.stderr)
        sys.exit(1)

    action = sys.argv[1]
    input_value = sys.argv[2]

    if action == 'date':
        print(convert_date(input_value))
    elif action == 'time':
        print(convert_time(input_value))
    else:
        print(f"Unknown mode: {action}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

# Prepare context frames for KV cache recomputation in video diffusion pipelines
from diffusers.modular_pipelines import ModularPipelineBlocks, PipelineState
from diffusers.modular_pipelines.modular_pipeline_utils import (
    ComponentSpec,
    InputParam,
    OutputParam,
)

class InitializeContextBufferBlock(ModularPipelineBlocks):
    @property
    def required_components(self) -> list[ComponentSpec]:
        return [
            ComponentSpec("rng_generator", torch.nn.Module),
        ]

    @property
    def docstring(self) -> str:
        return "Initialize and maintain sliding window buffers for context and decoded frames during inference"

    @property
    def input_specs(self) -> list[InputParam]:
        return [
            InputParam(
                "latent_input",
                required=True,
                type_hint=torch.Tensor,
                description="Processed latent representations",
            ),
            InputParam(
                "reconstructed_video",
                required=True,
                type_hint=torch.Tensor,
                description="Output video tensor after decoding",
            ),
            InputParam(
                "frame_offset_index",
                required=True,
                type_hint=int,
                description="Index of the first frame in current processing segment",
            ),
            InputParam(
                "context_buffer_capacity",
                type_hint=int,
                description="Maximum number of context frames to retain",
            ),
            InputParam(
                "decoded_buffer_capacity",
                type_hint=int,
                description="Maximum number of decoded frames to store",
            ),
            InputParam(
                "context_history",
                type_hint=torch.Tensor,
                description="Current buffer containing previous context frames",
            ),
            InputParam(
                "decoded_history",
                type_hint=torch.Tensor,
                description="Current buffer containing previous decoded frames",
            ),
            InputParam(
                "initial_frame",
                type_hint=torch.Tensor,
                description="First frame from initial processing block",
            ),
        ]

    @property
    def intermediate_results(self) -> list[OutputParam]:
        return [
            OutputParam(
                "initial_frame",
                type_hint=torch.Tensor,
                description="First frame from initial processing block",
            ),
            OutputParam(
                "context_history",
                type_hint=torch.Tensor,
                description="Updated buffer with latest context frames",
            ),
            OutputParam(
                "decoded_history",
                type_hint=torch.Tensor,
                description="Updated buffer with latest decoded frames",
            ),
        ]

    @torch.no_grad()
    def __call__(self, components, state: PipelineState) -> tuple[any, PipelineState]:
        local_state = self.get_block_state(state)

        # Set initial frame when starting new sequence
        if local_state.frame_offset_index == 0:
            local_state.initial_frame = local_state.latent_input[:, :1]

        # Update context frame buffer with sliding window logic
        if local_state.context_buffer_capacity > 0:
            local_state.context_history = torch.cat(
                [
                    local_state.context_history,
                    local_state.latent_input.to(
                        local_state.context_history.device,
                        local_state.context_history.dtype,
                    ),
                ],
                dim=1,
            )[:, -local_state.context_buffer_capacity:]

        # Update decoded frame buffer with sliding window logic
        if local_state.decoded_buffer_capacity > 0:
            local_state.decoded_history = torch.cat(
                [
                    local_state.decoded_history,
                    local_state.reconstructed_video.to(
                        local_state.decoded_history.device,
                        local_state.decoded_history.dtype,
                    ),
                ],
                dim=1,
            )[:, -local_state.decoded_buffer_capacity:]

        self.set_block_state(state, local_state)
        return components, state

# Feature Flags API endpoints for admin-only operations
from typing import List, Optional, Dict, Any
from ..services.feature_flags import get_feature_service
from ..routers.auth import require_admin
from ..models import User
router = APIRouter(prefix="/flags", tags=["Feature Flags"])

@router.get("/")
async def retrieve_all_flags(current_user: User = Depends(require_admin)):
    """Retrieve all feature flags stored in Consul."""
    service = get_feature_service()
    return service.fetch_all_flags()

@router.post("/")
async def add_or_modify_flag(
    flag_name: str = Query(...),
    settings: Dict[str, Any] = Body(...),  # {enabled: bool, rollout_percentage: int, tenant_overrides: {...}}
    current_user: User = Depends(require_admin)
):
    """Admin only: Modify, enable/disable or configure rollout/overrides for a specific feature flag."""
    service = get_feature_service()

    # Validate the settings object
    if not isinstance(settings.get('enabled'), bool):
         raise HTTPException(status_code=400, detail="'enabled' must be a boolean value")

    result = service.apply_flag(flag_name, settings)
    if not result:
         raise HTTPException(status_code=500, detail="Unable to persist changes to Consul")

    return {"message": f"Flag '{flag_name}' updated successfully.", "settings": settings}

@router.delete("/")
async def remove_flag(
    flag_name: str = Query(...),
    current_user: User = Depends(require_admin)
):
    """Admin only: Permanently delete a feature flag."""
    service = get_feature_service()
    try:
