def _get_implementation_details():
    """Return a dictionary containing the Python implementation name and version."""
    impl_name = platform.python_implementation()

    if impl_name == "CPython":
        impl_version = platform.python_version()
    elif impl_name == "PyPy":
        major, minor, micro = sys.pypy_version_info.major, sys.pypy_version_info.minor, sys.pypy_version_info.micro
        impl_version = f"{major}.{minor}.{micro}"
        if sys.pypy_version_info.releaselevel != "final":
            impl_version += sys.pypy_version_info.releaselevel
    elif impl_name in ("Jython", "IronPython"):
        impl_version = platform.python_version()  # Estimated value
    else:
        impl_version = "Unknown"

    return {"name": impl_name, "version": impl_version}

def gather_system_info():
    """Compile system and library information for bug reporting."""
    try:
        os_info = {
            "system": platform.system(),
            "release": platform.release(),
        }
    except OSError:
        os_info = {
            "system": "Unknown",
            "release": "Unknown",
