from werkzeug.utils import secure_filename
from pathlib import Path

# Maximum allowed upload size: 10 MB
MAX_FILE_SIZE = 10 * 1024 * 1024
CERTIFICATE_EXTENSIONS = {'.pem', '.crt', '.cer', '.p12', '.pfx', '.p7b', '.der', '.key'}
JSON_FILE_EXTENSIONS = {'.json'}
BACKUP_FILE_EXTENSIONS = {'.zip', '.enc'}

def check_uploaded_file(file_obj, permitted_extensions=None, max_length=MAX_FILE_SIZE):
    """Check an uploaded file. Returns (content, sanitized_name) or raises ValueError."""
    if not file_obj or not file_obj.filename:
        raise ValueError("No file provided")

    clean_name = secure_filename(file_obj.filename)
    if not clean_name:
        raise ValueError("Invalid filename")

    if permitted_extensions:
        file_suffix = Path(clean_name).suffix.lower()
        if file_suffix not in permitted_extensions:
            raise ValueError(f"Invalid file type: {file_suffix}")

    content = file_obj.read(max_length + 1)
    if len(content) > max_length:
        raise ValueError(f"File too large (max {max_length // (1024*1024)}MB)")

    return content, clean_name

# Import necessary modules for process and thread management
from subprocess import Popen
from threading import Event, Thread

def terminate_threads(thread_list: list[Thread]):
    """Gracefully terminate a collection of threads"""
    for t in thread_list:
        t.join(timeout=5)

def terminate_subprocesses(proc_list: list[Popen]):
    """Terminate and clean up a list of subprocesses"""
    for proc in proc_list:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except TimeoutError:
                proc.kill()

def watch_subprocess(proc: Popen, shutdown_flag: Event, error_buffer: list, name: str):
    """Watch a subprocess and report failures through a shared buffer."""
    proc.wait()
    if proc.returncode != 0:
        msg = f"{name.capitalize()} failed with exit code {proc.returncode}"
        if proc.stderr:
            msg += f"\n{proc.stderr.read().decode('utf-8')}"
        error_buffer.append(RuntimeError(msg))
    shutdown_flag.set()

# Time step embedding module for diffusion models
import torch
import torch.nn as nn
import math
from einops import rearrange, repeat

def generate_timestep_embedding(timesteps, embedding_dim, max_time=10000, only_repeat=False, tensor_dtype=torch.float32):
    if not only_repeat:
        half_dim = embedding_dim // 2
        angular_freqs = torch.exp(-math.log(max_time) * torch.arange(start=0, end=half_dim, dtype=torch.float32, device=timesteps.device) / half_dim)
        scaled_timesteps = timesteps[:, None].float() * angular_freqs[None]
        positional_encoding = torch.cat([torch.cos(scaled_timesteps), torch.sin(scaled_timesteps)], dim=-1)
        if embedding_dim % 2 == 1:
            positional_encoding = torch.cat([positional_encoding, torch.zeros_like(positional_encoding[:, :1])], dim=-1)
    else:
        positional_encoding = repeat(timesteps, "batch -> batch d", d=embedding_dim)
    return positional_encoding.to(tensor_dtype)

class TemporalFeatureEmbedding(nn.Module):
    def __init__(self, feature_size, projection_dim=None, max_time=10000, only_repeat=False):
        super().__init__()
        self.feature_size = feature_size
        self.projection_dim = projection_dim if projection_dim is not None else feature_size
        self.max_time = max_time
        self.only_repeat = only_repeat
        self.temporal_projection = nn.Sequential(
            nn.Linear(self.feature_size, projection_dim),
            nn.SiLU(),
            nn.Linear(projection_dim, projection_dim),
        )

    @property
    def data_type(self) -> torch.dtype:
        """Determines the data type of the module (assuming uniform parameter types)."""
        model_params = tuple(self.parameters())
        if len(model_params) > 0:
            return model_params[0].dtype
        else:
            buffers = tuple(self.buffers())
            return buffers[0].dtype

    def forward(self, time_steps):
        encoded = generate_timestep_embedding(time_steps, self.feature_size, self.max_time, self.only_repeat, dtype=self.data_type)
        return self.temporal_projection(encoded)

