def extract_table_html(image, table_components, ocr_processor):
    ocr_results = ocr_processor(np.array(image))
    ocr_results = LayoutRecognizer.sort_Y_firstly(
        [{"x0": box[0][0], "x1": box[1][0],
          "top": box[0][1], "text": text[0],
          "bottom": box[-1][1],
          "layout_type": "table",
          "page_number": 0} for box, text in ocr_results if box[0][0] <= box[1][0] and box[0][1] <= box[-1][1]],
        np.mean([box[-1][1] - box[0][1] for box, _ in ocr_results]) / 3
    )

    def collect_elements(keyword, tolerance=10, overlap_ratio=0.6):
        nonlocal ocr_results
        elements = LayoutRecognizer.sort_Y_firstly(
            [item for item in table_components if re.match(keyword, item["label"])], tolerance)
        elements = LayoutRecognizer.layouts_cleanup(ocr_results, elements, 5, overlap_ratio)
        return LayoutRecognizer.sort_Y_firstly(elements, 0)

    header_boxes = collect_elements(r".*header$")
    row_boxes = collect_elements(r".* (row|header)")
    span_boxes = collect_elements(r".*spanning")
    column_boxes = sorted([item for item in table_components if re.match(
        r"table column$", item["label"])], key=lambda x: x["x0"])
    column_boxes = LayoutRecognizer.layouts_cleanup(ocr_results, column_boxes, 5, 0.5)

    for box in ocr_results:
        # Match with rows
        row_idx = LayoutRecognizer.find_overlapped_with_threshold(box, row_boxes, thr=0.3)
        if row_idx is not None:
            box["R"] = row_idx
            box["R_top"] = row_boxes[row_idx]["top"]
            box["R_bott"] = row_boxes[row_idx]["bottom"]

        # Match with headers
        header_idx = LayoutRecognizer.find_overlapped_with_threshold(box, header_boxes, thr=0.3)
        if header_idx is not None:
            box["H_top"] = header_boxes[header_idx]["top"]
            box["H_bott"] = header_boxes[header_idx]["bottom"]
            box["H_left"] = header_boxes[header_idx]["x0"]
            box["H_right"] = header_boxes[header_idx]["x1"]
            box["H"] = header_idx

        # Match with columns
        col_idx = LayoutRecognizer.find_horizontally_tightest_fit(box, column_boxes)
        if col_idx is not None:
            box["C"] = col_idx
            box["C_left"] = column_boxes[col_idx]["x0"]
            box["C_right"] = column_boxes[col_idx]["x1"]

        # Match with spans
        span_idx = LayoutRecognizer.find_overlapped_with_threshold(box, span_boxes, thr=0.3)
        if span_idx is not None:
            box["H_top"] = span_boxes[span_idx]["top"]
            box["H_bott"] = span_boxes[span_idx]["bottom"]
            box["H_left"] = span_boxes[span_idx]["x0"]
            box["H_right"] = span_boxes[span_idx]["x1"]
            box["SP"] = span_idx

    html_template = """
