    }
    th {
      color: #fff;
      background-color: #6ac1ca;
    }
    td:hover {
      background: #c1e8e8;
    }
    tr:nth-child(even) {
      background-color: #f2f2f2;
    }
    ._table_1nkzy_11 th,
    ._table_1nkzy_11 td {
      text-align: center;
