    def bypass_proxy_via_registry(host):
        try:
            import winreg
        except ImportError:
            return False
        try:
            internetSettings = winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Internet Settings",
            )
            proxyEnable = int(winreg.QueryValueEx(internetSettings, "ProxyEnable")[0])
            proxyOverride = winreg.QueryValueEx(internetSettings, "ProxyOverride")[0]
        except (OSError, ValueError):
            return False
        if not proxyEnable or not proxyOverride:
            return False
        proxyOverride = proxyOverride.split(";")
        for test in proxyOverride:
            if test == "<local>":
                if "." not in host:
                    return True
            test = test.replace(".", r"\.")
            test = test.replace("*", r".*")
            test = test.replace("?", r".")
            if re.match(test, host, re.I):
                return True
        return False

    def should_bypass_proxy(host):  # renamed function
        """Determine if proxy should be skipped based on environment or registry settings."""
        if getproxies_environment():
            return proxy_bypass_environment(host)
        else:
            return bypass_proxy_via_registry(host)

def mapping_to_items(d):
    """Convert dictionary-like object to items sequence"""
    if hasattr(d, "items"):
        d = d.items()
    return d

def calculate_length(obj):
    total_size = None
    current_offset = 0

    if hasattr(obj, "__len__"):
        total_size = len(obj)
    elif hasattr(obj, "len"):
        total_size = obj.len
    elif hasattr(obj, "fileno"):
        try:
            fileno = obj.fileno()
        except (io.UnsupportedOperation, AttributeError):
            pass
        else:
            total_size = os.fstat(fileno).st_size
            if "b" not in obj.mode:
                warnings.warn(
                    (
                        "Requests has determined the content-length for this "
                        "request using the binary size of the file: however, the "
                        "file has been opened in text mode (i.e. without the 'b' "
                        "flag in the mode). This may lead to an incorrect "
                        "content-length. In Requests 3.0, support will be removed "
                        "for files in text mode."
                    ),
                    FileModeWarning,
                )

    if hasattr(obj, "tell"):
        try:
            current_offset = obj.tell()
        except OSError:
            if total_size is not None:
                current_offset = total_size
        else:
            if hasattr(obj, "seek") and total_size is None:
                try:
                    obj.seek(0, 2)
                    total_size = obj.tell()
                    obj.seek(current_offset or 0)
                except OSError:
                    total_size = 0

    if total_size is None:
        total_size = 0
    return max(0, total_size - current_offset)

def fetch_netrc_credentials(url, enforce_errors=False):
    """Extract authentication info from netrc for given URL"""
    netrc_file = os.environ.get("NETRC")
    if netrc_file is not None:
        netrc_paths = (netrc_file,)
    else:
        netrc_paths = (f"~/{f}" for f in CREDENTIAL_FILES)

    try:
        from netrc import NetrcParseError, netrc
        netrc_location = None
        for f in netrc_paths:
            try:
                loc = os.path.expanduser(f)
            except KeyError:
                return
            if os.path.exists(loc):
                netrc_location = loc
                break

        if netrc_location is None:
            return

        ri = urlparse(url)
        splitstr = b":"
        if isinstance(url, str):
            splitstr = splitstr.decode("ascii")
        host = ri.netloc.split(splitstr)[0]

        try:
            _netrc = netrc(netrc_location).authenticators(host)
            if _netrc:
                login_idx = 0 if _netrc[0] else 1
                return (_netrc[login_idx], _netrc[2])
        except (NetrcParseError, OSError):
            if enforce_errors:
                raise
    except (ImportError, AttributeError):
        pass

def infer_filename(obj):
    """Attempt to determine filename from object"""
    name = getattr(obj, "name", None)
    if name and isinstance(name, basestring) and name[0] != "<" and name[-1] != ">":
        return os.path.basename(name)

def extract_zipped_content(path):
    """Handle paths that reference zip archive members"""
    if os.path.exists(path):
        return path

    archive, member = os.path.split(path)
    while archive and not os.path.exists(archive):
        archive, prefix = os.path.split(archive)
        if not prefix:
            break
        member = "/".join([prefix, member])

    if not zipfile.is_zipfile(archive):
        return path

    zip_file = zipfile.ZipFile(archive)
    if member not in zip_file.namelist():
        return path

    tmp_dir = tempfile.gettempdir()
    extracted_path = os.path.join(tmp_dir, member.split("/")[-1])
    if not os.path.exists(extracted_path):
        with atomic_open(extracted_path) as file_handler:
            file_handler.write(zip_file.read(member))
    return extracted_path

@contextlib.contextmanager
def atomic_write(filename):
    """Write file atomically to disk"""
    tmp_descriptor, tmp_name = tempfile.mkstemp(dir=os.path.dirname(filename))
    try:
        with os.fdopen(tmp_descriptor, "wb") as tmp_handler:
            yield tmp_handler
        os.replace(tmp_name, filename)
    except BaseException:
        os.remove(tmp_name)
        raise

def pair_list_to_ordered_dict(value):
    """Convert value to OrderedDict if possible"""
    if value is None:
        return None
    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError("cannot encode objects that are not 2-tuples")
    return OrderedDict(value)

def pair_list_from_value(value):
    """Convert value to list of key-value pairs"""
    if value is None:
        return None
    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError("cannot encode objects that are not 2-tuples")
    if isinstance(value, Mapping):
        value = value.items()
    return list(value)

def parse_rfc2068_list(value):
    """Parse comma-separated headers per RFC 2068 Section 2"""
    result = []
    for item in _parse_list_header(value):
        if item[:1] == item[-1:] == '"':
            item = unquote_header_value(item[1:-1])
        result.append(item)
    return result

def parse_rfc2068_dict(value):
    """Parse key=value headers per RFC 2068 Section 2"""
    result = {}
    for item in _parse_list_header(value):
        if "=" not in item:
            result[item] = None
            continue
        name, value = item.split("=", 1)
        if value[:1] == value[-1:] == '"':
            value = unquote_header_value(value[1:-1])
        result[name] = value
    return result

def unquote_header_value_safe(value, is_filename=False):
    """Safely unquote header values following browser conventions"""
    if value and value[0] == value[-1] == '"':
        value = value[1:-1]
        if not is_filename or value[:2] != "\\\\":
            return value.replace("\\\\", "\\").replace('\\"', '"')
    return value

def cookiejar_to_dict(cj):
    """Extract cookies from CookieJar into dictionary"""
    cookie_dict = {}
    for cookie in cj:
        cookie_dict[cookie.name] = cookie.value
    return cookie_dict

def dict_to_cookiejar(cj, cookie_data):
    """Insert cookies from dictionary into CookieJar"""
    return cookiejar_from_dict(cookie_data, cj)

def extract_charsets_from_content(content):
    """Extract character encodings from HTML content"""
    warnings.warn(
        (
            "In requests 3.0, extract_charsets_from_content will be removed. For "
            "more information, please see the discussion on issue #2266. (This"
            " warning should only appear once.)"
        ),
        DeprecationWarning,
    )
    charset_re = re.compile(r'<meta.*?charset=["\']*(.+?)["\'>]', flags=re.I)
    pragma_re = re.compile(r'<meta.*?content=["\']*;?charset=(.+?)["\'>]', flags=re.I)
    xml_re = re.compile(r'^<\?xml.*?encoding=["\']*(.+?)["\'>]')
    return (
        charset_re.findall(content)
        + pragma_re.findall(content)
        + xml_re.findall(content)
    )

def decode_content_type(header):
    """Parse content-type header into type and parameters"""
    tokens = header.split(";")
    content_type, params = tokens[0].strip(), tokens[1:]
    params_dict = {}
    items_to_strip = "\"' "
    for param in params:
        param = param.strip()
        if param:
            key, value = param, True
            index_of_equals = param.find("=")
            if index_of_equals != -1:
                key = param[:index_of_equals].strip(items_to_strip)
                value = param[index_of_equals + 1 :].strip(items_to_strip)
            params_dict[key.lower()] = value
    return content_type, params_dict

def detect_encoding_from_headers(headers):
    """Determine encoding from HTTP headers"""
    content_type = headers.get("content-type")
    if not content_type:
        return None
    content_type, params = decode_content_type(content_type)
    if "charset" in params:
        return params["charset"].strip("'\"")
    if "text" in content_type:
        return "ISO-8859-1"
    if "application/json" in content_type:
        return "utf-8"

def decode_stream_unicode(iterator, response):
    """Decode byte stream to unicode"""
    if response.encoding is None:
        yield from iterator
        return
    decoder = codecs.getincrementaldecoder(response.encoding)(errors="replace")
    for chunk in iterator:
        rv = decoder.decode(chunk)
        if rv:
            yield rv
    rv = decoder.decode(b"", final=True)
    if rv:
        yield rv

def slice_string(string, chunk_size):
    """Generate chunks of specified size from string"""
    position = 0
    if chunk_size is None or chunk_size <= 0:
        chunk_size = len(string)
    while position < len(string):
        yield string[position : position + chunk_size]
        position += chunk_size

def extract_unicode_content(response):
    """Extract unicode content from response object"""
    warnings.warn(
        (
            "In requests 3.0, extract_unicode_content will be removed. For "
            "more information, please see the discussion on issue #2266. (This"
            " warning should only appear once.)"
        ),
        DeprecationWarning,
    )
    tried_encodings = []
    encoding = detect_encoding_from_headers(response.headers)
    if encoding:
        try:
            return str(response.content, encoding)
        except UnicodeError:
            tried_encodings.append(encoding)
    try:
        return str(response.content, encoding, errors="replace")
    except TypeError:
        return response.content

UNRESERVED_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz" + "0123456789-._~"
)

def decode_unreserved_uri(uri):
    """Decode percent-encoded unreserved characters in URI"""
    parts = uri.split("%")
    for i in range(1, len(parts)):
        h = parts[i][0:2]
        if len(h) == 2 and h.isalnum():
            try:
                c = chr(int(h, 16))
            except ValueError:
                raise InvalidURL(f"Invalid percent-escape sequence: '{h}'")
            if c in UNRESERVED_CHARS:
                parts[i] = c + parts[i][2:]
            else:
                parts[i] = f"%{parts[i]}"
        else:
            parts[i] = f"%{parts[i]}"
    return "".join(parts)

def normalize_uri(uri):
    """Normalize URI through unquote/quote cycle"""
    safe_with_percent = "!#$%&'()*+,/:;=?@[]~"
    safe_without_percent = "!#$&'()*+,/:;=?@[]~"
    try:
        return quote(decode_unreserved_uri(uri), safe=safe_with_percent)
    except InvalidURL:
        return quote(uri, safe=safe_without_percent)

def ip_in_subnet(ip_addr, subnet_cidr):
    """Check if IP address belongs to subnet"""
    ip_int = struct.unpack("=L", socket.inet_aton(ip_addr))[0]
    net_addr, bits = subnet_cidr.split("/")
    netmask = struct.unpack("=L", socket.inet_aton(dotted_mask(int(bits))))[0]
    network = struct.unpack("=L", socket.inet_aton(net_addr))[0] & netmask
    return (ip_int & netmask) == (network & netmask)

def dotted_mask(mask_bits):
    """Convert CIDR mask to dotted decimal notation"""
    bits = 0xFFFFFFFF ^ (1 << 32 - mask_bits) - 1
    return socket.inet_ntoa(struct.pack(">I", bits))

def is_valid_ipv4(ip_str):
    """Validate IPv4 address format"""
    try:
        socket.inet_aton(ip_str)
    except OSError:
        return False
    return True

def is_valid_cidr(cidr_str):
    """Validate CIDR notation format"""
    if cidr_str.count("/") == 1:
        try:
            mask = int(cidr_str.split("/")[1])
        except ValueError:
            return False
        if mask < 1 or mask > 32:
            return False
        try:
            socket.inet_aton(cidr_str.split("/")[0])
        except OSError:
            return False
    else:
        return False
    return True

@contextlib.contextmanager
def temporary_environ(env_var, new_value):
    """Temporarily set environment variable"""
    value_changed = new_value is not None
    if value_changed:
        old_value = os.environ.get(env_var)
        os.environ[env_var] = new_value
    try:
        yield
    finally:
        if value_changed:
            if old_value is None:
                del os.environ[env_var]
            else:
                os.environ[env_var] = old_value

def check_proxy_bypass(url, no_proxy_list):
    """Determine if proxy should be bypassed for URL"""
    def get_proxy_env(key):
        return os.environ.get(key) or os.environ.get(key.upper())

    no_proxy_arg = no_proxy_list
    if no_proxy_list is None:
        no_proxy_list = get_proxy_env("no_proxy")

    parsed = urlparse(url)
    if parsed.hostname is None:
        return True

    if no_proxy_list:
        no_proxy_list = (host for host in no_proxy_list.replace(" ", "").split(",") if host)
        if is_valid_ipv4(parsed.hostname):
            for proxy_ip in no_proxy_list:
                if is_valid_cidr(proxy_ip):
                    if ip_in_subnet(parsed.hostname, proxy_ip):
                        return True
                elif parsed.hostname == proxy_ip:
                    return True
        else:
            host_with_port = parsed.hostname
            if parsed.port:
                host_with_port += f":{parsed.port}"
            for host in no_proxy_list:
                if parsed.hostname.endswith(host) or host_with_port.endswith(host):
                    return True

    with temporary_environ("no_proxy", no_proxy_arg):
        try:
            bypass = should_bypass_proxy(parsed.hostname)
        except (TypeError, socket.gaierror):
            bypass = False
    if bypass:
        return True
    return False

def get_environment_proxies(url, no_proxy=None):
    """Get proxy configuration from environment"""
    if check_proxy_bypass(url, no_proxy=no_proxy):
        return {}
    else:
        return getproxies()

def choose_proxy(url, proxies):
    """Select appropriate proxy for URL"""
    proxies = proxies or {}
    urlparts = urlparse(url)
    if urlparts.hostname is None:
        return proxies.get(urlparts.scheme, proxies.get("all"))

    proxy_keys = [
        urlparts.scheme + "://" + urlparts.hostname,
        urlparts.scheme,
        "all://" + urlparts.hostname,
        "all",
    ]
    proxy = None
    for key in proxy_keys:
        if key in proxies:
            proxy = proxies[key]
            break
    return proxy

def resolve_proxy_config(request_obj, proxies, use_environment=True):
    """Resolve proxy configuration for request"""
    proxies = proxies if proxies is not None else {}
    url = request_obj.url
    scheme = urlparse(url).scheme
    no_proxy = proxies.get("no_proxy")
    updated_proxies = proxies.copy()

    if use_environment and not check_proxy_bypass(url, no_proxy=no_proxy):
        environ_proxies = get_environment_proxies(url, no_proxy=no_proxy)
        proxy = environ_proxies.get(scheme, environ_proxies.get("all"))
        if proxy:
            updated_proxies.setdefault(scheme, proxy)
    return updated_proxies

def generate_default_user_agent(app_name="python-requests"):
    """Generate default user agent string"""
    return f"{app_name}/{__version__}"

def create_default_headers():
    """Create default HTTP headers"""
    return CaseInsensitiveDict(
        {
            "User-Agent": generate_default_user_agent(),
            "Accept-Encoding": ACCEPT_ENCODING_HEADER,
            "Accept": "*/*",
            "Connection": "keep-alive",
        }
    )

def parse_link_headers(value):
    """Parse Link headers from HTTP response"""
    links = []
    replace_chars = " '\""
    value = value.strip(replace_chars)
    if not value:
        return links

    for val in re.split(", *<", value):
        try:
            url, params = val.split(";", 1)
        except ValueError:
            url, params = val, ""
        link = {"url": url.strip("<> '\"")}
        for param in params.split(";"):
            try:
                key, value = param.split("=")
            except ValueError:
                break
            link[key.strip(replace_chars)] = value.strip(replace_chars)
        links.append(link)
    return links

# Null byte sequences for JSON detection
_null_byte = "\x00".encode("ascii")
_null_double = _null_byte * 2
_null_triple = _null_byte * 3

def detect_json_encoding(data):
    """Detect UTF encoding of JSON data"""
    sample = data[:4]
    if sample in (codecs.BOM_UTF32_LE, codecs.BOM_UTF32_BE):
        return "utf-32"
    if sample[:3] == codecs.BOM_UTF8:
        return "utf-8-sig"
    if sample[:2] in (codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE):
        return "utf-16"

    null_count = sample.count(_null_byte)
    if null_count == 0:
        return "utf-8"
    if null_count == 2:
        if sample[::2] == _null_double:
            return "utf-16-be"
        if sample[1::2] == _null_double:
            return "utf-16-le"
    if null_count == 3:
        if sample[:3] == _null_triple:
            return "utf-32-be"
        if sample[1:] == _null_triple:
            return "utf-32-le"
    return None

def add_scheme_if_missing(url, default_scheme):
    """Add scheme to URL if missing"""
    parsed = parse_url(url)
    scheme, auth, host, port, path, query, fragment = parsed
    netloc = parsed.netloc
    if not netloc:
        netloc, path = path, netloc
    if auth:
        netloc = "@".join([auth, netloc])
    if scheme is None:
        scheme = default_scheme
    if path is None:
        path = ""
    return urlunparse((scheme, netloc, path, "", query, fragment))

def extract_auth_from_url(url):
    """Extract username/password from URL"""
    parsed = urlparse(url)
    try:
        auth = (unquote(parsed.username), unquote(parsed.password))
    except (AttributeError, TypeError):
        auth = ("", "")
    return auth

def validate_header(header_tuple):
    """Verify header components don't contain invalid characters"""
    name, value = header_tuple
    validate_header_component(header_tuple, name, 0)
    validate_header_component(header_tuple, value, 1)

def validate_header_component(header, component, validator_index):
    if isinstance(component, str):
        validator = _HEADER_VALIDATORS_STR[validator_index]
    elif isinstance(component, bytes):
        validator = _HEADER_VALIDATORS_BYTE[validator_index]
    else:
        raise InvalidHeader(
            f"Header part ({component!r}) from {header} "
            f"must be of type str or bytes, not {type(component)}"
        )
    if not validator.match(component):
        header_kind = "name" if validator_index == 0 else "value"
        raise InvalidHeader(
            f"Invalid leading whitespace, reserved character(s), or return"
            f"character(s) in header {header_kind}: {component!r}"
        )

def strip_fragment_and_auth(url):
    """Remove fragment and authentication from URL"""
    scheme, netloc, path, params, query, fragment = urlparse(url)
    if not netloc:
        netloc, path = path, netloc
    netloc = netloc.rsplit("@", 1)[-1]
    return urlunparse((scheme, netloc, path, params, query, ""))

def reset_request_body(prepared_request):
    """Reset file pointer to original position for redirects"""
    body_seek = getattr(prepared_request.body, "seek", None)
    if body_seek is not None and isinstance(
        prepared_request._body_position, integer_types
    ):
        try:
            body_seek(prepared_request._body_position)
        except OSError:
            raise UnrewindableBodyError(
                "An error occurred when rewinding request body for redirect."
            )
    else:
        raise UnrewindableBodyError("Unable to rewind request body for redirect.")

# Model loader module for nemo_automodel components
import importlib.abc
import pathlib
import sys
from .gpt2 import build_gpt2_model  # noqa: F401

__all__ = [
    "build_gpt2_model",
]

_MODELS_DIR = pathlib.Path(__file__).parent
_PACKAGE_PREFIX = __name__ + "."

def _list_available_model_packages() -> set[str]:
    """Return the set of model sub-package names shipped with this installation."""
    return {
        item.name
        for item in _MODELS_DIR.iterdir()
        if item.is_dir() and not item.name.startswith(("_", ".")) and (item / "__init__.py").exists()
    }

def _generate_upgrade_error_message(module_name: str) -> str:
    return (
        f"Module '{__name__}' has no submodule '{module_name}'. "
        f"Available model submodules in this installation: "
        f"{sorted(_list_available_model_packages())}. "
        f"If '{module_name}' is a newly added model, your installed version of "
        f"nemo_automodel may be too old.  Upgrade with:\n"
        f"  pip install --upgrade nemo_automodel\n"
        f"or install from source:\n"
        f"  pip install git+https://github.com/NVIDIA-NeMo/Automodel.git"
    )

def __getattr__(name: str):
    raise ModuleNotFoundError(_generate_upgrade_error_message(name))

class _ModelImportErrorHandler(importlib.abc.MetaPathFinder):
    """Produces a helpful error when importing a non-existent model subpackage.
    Installed at the *end* of ``sys.meta_path`` so it is only consulted after
    all real finders have already returned ``None``.  For any import of the form
    ``nemo_automodel.components.models.<name>`` (direct child only), it raises
    a ``ModuleNotFoundError`` with upgrade instructions instead of the default
    unhelpful message.
    """
    def find_spec(self, fullname, path, target=None):
        if not fullname.startswith(_PACKAGE_PREFIX):
            return None
        sub_module_name = fullname[len(_PACKAGE_PREFIX):]
        if "." in sub_module_name:
            return None
        raise ModuleNotFoundError(_generate_upgrade_error_message(sub_module_name))

sys.meta_path.append(_ModelImportErrorHandler())

