# ============ BM25 IMPLEMENTATION ============
class BM25Ranker:
    """BM25 ranking algorithm for text search"""
    def __init__(self, k1=1.5, b=0.75):
        self.k1 = k1
        self.b = b
        self.documents = []
        self.lengths = []
        self.mean_length = 0
        self.inverse_doc_freq = {}
        self.document_frequencies = ddict(int)
        self.total_docs = 0

    def _tokenize(self, text):
        """Lowercase, split, remove punctuation, filter short words"""
        cleaned = re.sub(r'[^\w\s]', ' ', str(text).lower())
        return [term for term in cleaned.split() if len(term) > 2]

    def train(self, corpus):
        """Build BM25 index from documents"""
        self.documents = [self._tokenize(doc) for doc in corpus]
        self.total_docs = len(self.documents)
        if self.total_docs == 0:
            return

        self.lengths = [len(doc) for doc in self.documents]
        self.mean_length = sum(self.lengths) / self.total_docs

        for doc in self.documents:
            seen_terms = set()
            for term in doc:
                if term not in seen_terms:
                    self.document_frequencies[term] += 1
                    seen_terms.add(term)

        for term, df in self.document_frequencies.items():
            self.inverse_doc_freq[term] = ln((self.total_docs - df + 0.5) / (df + 0.5) + 1)

    def rank(self, query_text):
        """Score all documents against query"""
        query_tokens = self._tokenize(query_text)
        scores = []

        for doc_index, document in enumerate(self.documents):
            current_score = 0
            doc_len = self.lengths[doc_index]
            tf_counts = ddict(int)

            for word in document:
                tf_counts[word] += 1

            for token in query_tokens:
                if token in self.inverse_doc_freq:
                    tf = tf_counts[token]
                    idf_value = self.inverse_doc_freq[token]
                    numerator_part = tf * (self.k1 + 1)
                    denominator_part = tf + self.k1 * (1 - self.b + self.b * doc_len / self.mean_length)
                    current_score += idf_value * numerator_part / denominator_part

            scores.append((doc_index, current_score))

        return sorted(scores, key=lambda pair: pair[1], reverse=True)

# ============ SEARCH FUNCTIONS ============
def _read_csv_file(path):
    """Load CSV and return list of dicts"""
    with open(path, 'r', encoding='utf-8') as file:
        return list(csv.DictReader(file))

def _execute_search(filepath, query_cols, result_cols, search_term, limit):
    """Core search function using BM25"""
    if not filepath.is_file():
        return []

    records = _read_csv_file(filepath)

    # Build documents from query columns
    docs = [" ".join(str(row.get(field, "")) for field in query_cols) for row in records]

    # BM25 search
    ranker = BM25Ranker()
    ranker.train(docs)
    ranked_list = ranker.rank(search_term)

    # Get top results with score > 0
    output = []
    for idx, score in ranked_list[:limit]:
        if score > 0:
            record = records[idx]
            filtered_record = {col: record.get(col, "") for col in result_cols if col in record}
            output.append(filtered_record)

    return output

def _identify_category(input_text):
    """Auto-detect the most relevant domain from query"""
    normalized = input_text.lower()

    category_keywords = {
        "hue": ["color", "palette", "hex", "#", "rgb"],
        "graph": ["chart", "graph", "visualization", "trend", "bar", "pie", "scatter", "heatmap", "funnel"],
        "frontpage": ["landing", "page", "cta", "conversion", "hero", "testimonial", "pricing", "section"],
        "item": ["saas", "ecommerce", "e-commerce", "fintech", "healthcare", "gaming", "portfolio", "crypto", "dashboard"],
        "theme": ["style", "design", "ui", "minimalism", "glassmorphism", "neumorphism", "brutalism", "dark mode", "flat", "aurora", "prompt", "css", "implementation", "variable", "checklist", "tailwind"],
        "interaction": ["ux", "usability", "accessibility", "wcag", "touch", "scroll", "animation", "keyboard", "navigation", "mobile"],
        "font": ["font", "typography", "heading", "serif", "sans"],
        "symbol": ["icon", "icons", "lucide", "heroicons", "symbol", "glyph", "pictogram", "svg icon"],
        "component-react": ["react", "next.js", "nextjs", "suspense", "memo", "usecallback", "useeffect", "rerender", "bundle", "waterfall", "barrel", "dynamic import", "rsc", "server component"],
        "interface-web": ["aria", "focus", "outline", "semantic", "virtualize", "autocomplete", "form", "input type", "preconnect"]
    }

    scores = {category: sum(1 for kw in keywords if kw in normalized) for category, keywords in category_keywords.items()}
    top_category = max(scores, key=scores.get)

    return top_category if scores[top_category] > 0 else "theme"

def find_matches(query, category=None, limit=TOP_K):
    """Main search function with auto-category detection"""
    if category is None:
        category = _identify_category(query)

    config = CSV_SETTINGS.get(category, CSV_SETTINGS["theme"])
    file_path = ROOT_DIR / config["filename"]

    if not file_path.exists():
        return {"error": f"File not found: {file_path}", "category": category}

    matches = _execute_search(file_path, config["query_fields"], config["return_fields"], query, limit)

    return {
        "category": category,
        "query": query,
        "source_file": config["filename"],
        "total": len(matches),
        "data": matches
    }

def find_stack_match(query, framework, limit=TOP_K):
    """Search stack-specific guidelines"""
    if framework not in FRAMEWORK_CONFIG:
        return {"error": f"Unknown stack: {framework}. Available: {', '.join(SUPPORTED_STACKS)}"}

    file_path = ROOT_DIR / FRAMEWORK_CONFIG[framework]["filepath"]

    if not file_path.exists():
        return {"error": f"Stack file not found: {file_path}", "framework": framework}

    matches = _execute_search(file_path, _FRAMEWORK_COLS["query_fields"], _FRAMEWORK_COLS["return_fields"], query, limit)

    return {
        "category": "stack",
        "framework": framework,
        "query": query,
        "source_file": FRAMEWORK_CONFIG[framework]["filepath"],
        "total": len(matches),
        "data": matches
    }

# Handle duplicate database entries using unique constraints or primary keys
from typing import Callable, TypeVar
from psycopg.errors import UniqueViolation
from sqlalchemy import UniqueConstraint
from sqlalchemy.exc import IntegrityError as SQLAIntegrityError
from sqlalchemy.inspection import inspect
from functools import wraps

T = TypeVar("T")

def manage_duplicate_inserts(operation: Callable[..., T]) -> Callable[..., T | None]:
    """
    Decorator that deals with duplicate insert operations by searching for existing records
    based on unique constraints or primary key values.
    When a unique constraint violation is detected, this decorator attempts each unique
    constraint in order until it locates the pre-existing record responsible for the conflict.
    """
    @wraps(operation)
    def inner_wrapper(*arguments, **keyword_args) -> T | None:
        try:
            return operation(*arguments, **keyword_args)
        except SQLAIntegrityError as error:
            if isinstance(error.orig, UniqueViolation):
                entity_model = arguments[0].model
                session = arguments[1]
                payload = arguments[2]
                session.rollback()
                payload_data = payload.model_dump()
                metadata_mapper = inspect(entity_model)
                mapped_table = metadata_mapper.local_table

                # Try to match using unique constraints first
                for index_constraint in mapped_table.constraints:
                    if isinstance(index_constraint, UniqueConstraint):
                        search_query = session.query(entity_model)
                        all_fields_available = True

                        for field_column in index_constraint.columns:
                            if field_column.name in payload_data:
                                search_query = search_query.filter(
                                    getattr(entity_model, field_column.name) == payload_data[field_column.name],
                                )
                            else:
                                all_fields_available = False
                                break

                        if all_fields_available:
                            found_record = search_query.one_or_none()
                            if found_record:
                                return found_record

                # Fallback: try matching by primary key
                fallback_query = session.query(entity_model)
                for pk_column in metadata_mapper.primary_key:
                    if pk_column.name in payload_data:
                        fallback_query = fallback_query.filter(
                            getattr(entity_model, pk_column.name) == payload_data[pk_column.name]
                        )

                matched_record = fallback_query.one_or_none()
                if matched_record:
                    return matched_record

            raise
    return inner_wrapper

# Modified version of CountdownAnswerAsJudge with renamed variables and reordered logic
from ajet.task_judge.base_judge import BaseJudge
from ajet.workflow import WorkflowOutput, WorkflowTask
import re

class CountdownAnswerAsJudge(BaseJudge):
    def __init__(self, settings):
        self.settings = settings
        self.format_reward = 0.1
        self.full_score = 1.0

    def _check_equation_format(self, expr, allowed_digits):
        try:
            digits_in_expr = [int(d) for d in re.findall(r"\d+", expr)]
            sorted_allowed = sorted(allowed_digits)
            sorted_expr_digits = sorted(digits_in_expr)
            return sorted_expr_digits == sorted_allowed
        except Exception:
            return False

    def _calculate_expression_value(self, expr):
        try:
            valid_chars_pattern = r"^[\d+\-*/().\s]+$"
            if not re.match(valid_chars_pattern, expr):
                raise ValueError("Expression contains invalid characters.")
            calculated = eval(expr, {"__builtins__": None}, {})
            return calculated
        except Exception:
            return None

    def _assess_response(self, expression, goal, numbers):
        if expression is None:
            return 0
        if not self._check_equation_format(expression, numbers):
            return self.format_reward
        try:
            value = self._calculate_expression_value(expression)
            if value is None:
                return self.format_reward
            if abs(value - goal) < 1e-5:
                return self.full_score
            else:
                return self.format_reward
        except Exception:
            return self.format_reward

    def compute_reward(self, task: WorkflowTask, output: WorkflowOutput) -> tuple:
        score = 0
        answer_text = output.metadata["final_answer"]
        target_value = output.metadata["target"]
        provided_numbers = output.metadata["nums"]

        if target_value is None or not provided_numbers:
            return 0.0, False

        box_pattern = r"\\boxed\{([^}]*)\}"
        match = re.search(box_pattern, answer_text)

        if match:
            extracted = match.group(1)
            score = self._assess_response(extracted, target_value, provided_numbers)
            success = score >= self.full_score
        else:
            score = 0.0
            success = False

        return score, success

# Session Catchup Tool for Planning Files
import json
import sys
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple

PLANNING_FILE_LIST = ['task_plan.md', 'progress.md', 'findings.md']

def identify_ide() -> str:
    """
    Determine the active IDE by checking environment variables and directory structure.
    Returns 'claude-code', 'opencode', or 'unknown'.
    """
    # Check for OpenCode environment
    if os.environ.get('OPENCODE_DATA_DIR'):
        return 'opencode'
    # Check for Claude Code directory
    claude_path = Path.home() / '.claude'
    if claude_path.exists():
        return 'claude-code'
    # Check for OpenCode directory
    opencode_path = Path.home() / '.local' / 'share' / 'opencode'
    if opencode_path.exists():
        return 'opencode'
    return 'unknown'

def convert_to_claude_path(project_path: str) -> Path:
    """Transform project path into Claude's storage format."""
    cleaned = project_path.replace('/', '-')
    if not cleaned.startswith('-'):
        cleaned = '-' + cleaned
    cleaned = cleaned.replace('_', '-')
    return Path.home() / '.claude' / 'projects' / cleaned

def get_opencode_storage(project_path: str) -> Optional[Path]:
    """
    Retrieve OpenCode session storage root directory.
    OpenCode uses: ~/.local/share/opencode/storage/session/{projectHash}/
    Note: This returns only the storage root; session discovery differs in OpenCode.
    """
    data_dir = os.environ.get('OPENCODE_DATA_DIR',
                               str(Path.home() / '.local' / 'share' / 'opencode'))
    storage_root = Path(data_dir) / 'storage'
    if not storage_root.exists():
        return None
    return storage_root

def list_sessions_claude(storage_path: Path) -> List[Path]:
    """Retrieve all session files sorted by modification time (newest first)."""
    sessions = list(storage_path.glob('*.jsonl'))
    main_sessions = [s for s in sessions if not s.name.startswith('agent-')]
    return sorted(main_sessions, key=lambda p: p.stat().st_mtime, reverse=True)

def list_sessions_opencode(storage_path: Path) -> List[Path]:
    """
    Retrieve all OpenCode session files sorted by modification time.
    OpenCode stores sessions at: storage/session/{projectHash}/{sessionID}.json
    """
    session_base = storage_path / 'session'
    if not session_base.exists():
        return []
    found_sessions = []
    for project_hash_dir in session_base.iterdir():
        if project_hash_dir.is_dir():
            for session_file in project_hash_dir.glob('*.json'):
                found_sessions.append(session_file)
    return sorted(found_sessions, key=lambda p: p.stat().st_mtime, reverse=True)

def get_first_timestamp(session_file: Path) -> Optional[str]:
    """Extract timestamp of the first message in a session file."""
    try:
        with open(session_file, 'r') as f:
            for line in f:
                try:
                    record = json.loads(line)
                    ts = record.get('timestamp')
                    if ts:
                        return ts
                except:
                    continue
    except:
        pass
    return None

def find_planning_changes(session_file: Path) -> Tuple[int, Optional[str]]:
    """
    Scan session file for planning file modifications.
    Returns (line_number, filename) of most recent update, or (-1, None) if none found.
    """
    latest_update_line = -1
    latest_update_name = None
    try:
        with open(session_file, 'r') as f:
            for line_idx, line in enumerate(f):
                if '"Write"' not in line and '"Edit"' not in line:
                    continue
                try:
                    data = json.loads(line)
                    if data.get('type') != 'assistant':
                        continue
                    content = data.get('message', {}).get('content', [])
                    if not isinstance(content, list):
                        continue
                    for entry in content:
                        if entry.get('type') != 'tool_use':
                            continue
                        tool_name = entry.get('name', '')
                        if tool_name not in ('Write', 'Edit'):
                            continue
                        file_path = entry.get('input', {}).get('file_path', '')
                        for pf in PLANNING_FILE_LIST:
                            if file_path.endswith(pf):
                                latest_update_line = line_idx
                                latest_update_name = pf
                                break
                except json.JSONDecodeError:
                    continue
    except Exception:
        pass
    return latest_update_line, latest_update_name

def retrieve_messages_from_session(session_file: Path, skip_until_line: int = -1) -> List[Dict]:
    """
    Extract conversation messages from a session file.
    If skip_until_line >= 0, only extract messages after that line.
    Otherwise, extract all messages.
    """
    output = []
    try:
        with open(session_file, 'r') as f:
            for line_idx, line in enumerate(f):
                if skip_until_line >= 0 and line_idx <= skip_until_line:
                    continue
                try:
                    msg = json.loads(line)
                except json.JSONDecodeError:
                    continue
                msg_type = msg.get('type')
                is_meta = msg.get('isMeta', False)
                if msg_type == 'user' and not is_meta:
                    content = msg.get('message', {}).get('content', '')
                    if isinstance(content, list):
                        for item in content:
                            if isinstance(item, dict) and item.get('type') == 'text':
                                content = item.get('text', '')
                                break
                        else:
                            content = ''
                    if content and isinstance(content, str):
                        # Skip system/command messages
                        if content.startswith(('<local-command', '<command-', '<task-notification')):
                            continue
                        if len(content) > 20:
                            output.append({
                                'role': 'user',
                                'content': content,
                                'line': line_idx,
                                'session': session_file.stem[:8]
                            })
                elif msg_type == 'assistant':
                    msg_content = msg.get('message', {}).get('content', '')
                    text_part = ''
                    tools_used = []
                    if isinstance(msg_content, str):
                        text_part = msg_content
                    elif isinstance(msg_content, list):
                        for item in msg_content:
                            if item.get('type') == 'text':
                                text_part = item.get('text', '')
                            elif item.get('type') == 'tool_use':
                                tool_name = item.get('name', '')
                                tool_input = item.get('input', {})
                                if tool_name == 'Edit':
                                    tools_used.append(f"Edit: {tool_input.get('file_path', 'unknown')}")
                                elif tool_name == 'Write':
                                    tools_used.append(f"Write: {tool_input.get('file_path', 'unknown')}")
                                elif tool_name == 'Bash':
                                    cmd = tool_input.get('command', '')[:80]
                                    tools_used.append(f"Bash: {cmd}")
                                elif tool_name == 'AskUserQuestion':
                                    tools_used.append("AskUserQuestion")
                                else:
                                    tools_used.append(f"{tool_name}")
                    if text_part or tools_used:
                        output.append({
                            'role': 'assistant',
                            'content': text_part[:600] if text_part else '',
                            'tools': tools_used,
                            'line': line_idx,
                            'session': session_file.stem[:8]
                        })
    except Exception:
        pass
    return output

def main():
    project_path = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    # Identify IDE
    ide = identify_ide()
    if ide == 'opencode':
        print("\n[planning-with-files] OpenCode session catchup is not yet fully supported")
        print("OpenCode uses a different session storage format (.json) than Claude Code (.jsonl)")
        print("Session catchup requires parsing OpenCode's message storage structure.")
        print("\nWorkaround: Manually read task_plan.md, progress.md, and findings.md to catch up.")
        return
    # Claude Code path
    project_dir = convert_to_claude_path(project_path)
    if not project_dir.exists():
        return
    sessions = list_sessions_claude(project_dir)
    if len(sessions) < 2:
        return
    # Skip the current session (most recently modified = index 0)
    prior_sessions = sessions[1:]
    # Find the most recent planning file update across ALL prior sessions
    # Sessions are sorted newest first, so we scan in order
    target_session = None
    target_line = -1
    target_file = None
    target_session_index = -1
    for idx, session in enumerate(prior_sessions):
        line, filename = find_planning_changes(session)
        if line >= 0:
            target_session = session
            target_line = line
            target_file = filename
            target_session_index = idx
            break
    if not target_session:
        # No planning file updates found in any prior session
        return
    # Collect ALL messages from the update point forward, across all sessions
    combined_messages = []
    # 1. Get messages from the session with the update (after the update line)
    messages_from_target = retrieve_messages_from_session(target_session, skip_until_line=target_line)
    combined_messages.extend(messages_from_target)
    # 2. Get ALL messages from sessions between target_session and current
    # These are sessions[1:update_session_idx] (newer than target_session)
    intermediate_sessions = prior_sessions[:target_session_index]
    # Process from oldest to newest for correct chronological order
    for session in reversed(intermediate_sessions):
        messages = retrieve_messages_from_session(session, skip_until_line=-1)  # Get all messages
        combined_messages.extend(messages)
    if not combined_messages:
        return
    # Output catchup report
    print(f"\n[planning-with-files] SESSION CATCHUP DETECTED (IDE: {ide})")
    print(f"Last planning update: {target_file} in session {target_session.stem[:8]}...")
    sessions_processed = target_session_index + 1
    if sessions_processed > 1:
        print(f"Scanning {sessions_processed} sessions for unsynced context")
    print(f"Unsynced messages: {len(combined_messages)}")
    print("\n--- UNSYNCED CONTEXT ---")
    # Show up to 100 messages
    MAX_MESSAGES = 100
    if len(combined_messages) > MAX_MESSAGES:
        print(f"(Showing last {MAX_MESSAGES} of {len(combined_messages)} messages)\n")
        messages_to_display = combined_messages[-MAX_MESSAGES:]
    else:
        messages_to_display = combined_messages
    current_session_id = None
    for msg in messages_to_display:
        # Show session marker when it changes
        if msg.get('session') != current_session_id:
            current_session_id = msg.get('session')
            print(f"\n[Session: {current_session_id}...]")
        if msg['role'] == 'user':
            print(f"USER: {msg['content'][:300]}")
        else:
            if msg.get('content'):
                print(f"CLAUDE: {msg['content'][:300]}")
            if msg.get('tools'):
                print(f"  Tools: {', '.join(msg['tools'][:4])}")
    print("\n--- RECOMMENDED ---")
    print("1. Run: git diff --stat")
    print("2. Read: task_plan.md, progress.md, findings.md")
    print("3. Update planning files based on above context")
    print("4. Continue with task")

if __name__ == '__main__':
    main()

