from transformers import AutoConfig
from typing_extensions import override

# Custom Unpickler to handle megatron/GLM classes by replacing them with dummy implementations
class CustomUnpickler(pickle.Unpickler):
    @override
    def find_class(self, module_name, class_name):
        # Define a dummy class for unsupported modules
        class PlaceholderClass:
            def __init__(self, *args, **kwargs):
                pass

        if module_name.startswith("megatron") or module_name.startswith("glm"):
            return PlaceholderClass
        return super().find_class(module_name, class_name)

pickle.Unpickler = CustomUnpickler


# Custom storage reader that wraps FileSystemReader and handles metadata loading
class CustomStorageReader(dist_cp.FileSystemReader):
    @override
    def read_metadata(self):
        meta_path = self.fs.concat_path(self.path, ".metadata")
        with self.fs.create_stream(meta_path, "rb") as meta_file:
            metadata = CustomUnpickler(meta_file).load()

        if getattr(metadata, "storage_meta", None) is None:
            metadata.storage_meta = dist.cp.StorageMeta()
        metadata.storage_meta.load_id = self.load_id

        if metadata.planner_data is None:
            metadata.planner_data = {}
        return metadata


# Custom load planner that skips optimizer-related state dict entries
class CustomLoadPlanner(dist_cp.default_planner.DefaultLoadPlanner):
    @override
    def set_up_planner(
        self,
        state_dict: dist_cp.metadata.STATE_DICT_TYPE,
        metadata: dist_cp.metadata.Metadata | None = None,
        is_coordinator: bool = False,
    ) -> None:
        for key, value in metadata.state_dict_metadata.items():
            if "optimizer" in key or "_state" in key:
                continue
            print(f"Detected {key} in torch_dist checkpoint")
            if isinstance(value, dist_cp.metadata.TensorStorageMetadata):
                value = torch.empty(value.size, dtype=value.properties.dtype)
            state_dict[key] = value
        super().set_up_planner(state_dict, metadata, is_coordinator)


# Helper functions to extract expert- and layer-specific parameters
def extract_expert_params(args, param_name, param_tensor):
    if ".experts." not in param_name:
        yield param_name, param_tensor
        return

    num_experts = args.num_experts
    match = re.search(r"mlp.experts\.(.+)\.weight(\d+)", param_name)

    if not match:
        assert param_tensor.shape[0] == num_experts
        for expert_idx in range(num_experts):
            new_name = param_name.replace(".experts.experts.", ".experts.") + str(expert_idx)
            expert_tensor = param_tensor[expert_idx]
            yield new_name, expert_tensor
    else:
        yield param_name, param_tensor


def extract_layer_params(args, param_name, param_tensor):
    if ".layers." not in param_name:
        yield param_name, param_tensor
        return

    num_layers = args.num_layers
    match = re.search(r"\.layers\.(\d+)\.", param_name)

    if not match:
        assert param_tensor.shape[0] == num_layers
        for layer_idx in range(num_layers):
            new_name = param_name.replace(".layers.", f".layers.{layer_idx}.")
            layer_tensor = param_tensor[layer_idx]
            yield from extract_expert_params(args, new_name, layer_tensor)
    else:
        yield from extract_expert_params(args, param_name, param_tensor)


def collect_named_parameters(args, state_dict):
    for name, tensor in state_dict.items():
        full_name = f"module.module.{name}"
        yield from extract_layer_params(args, full_name, tensor)


# Main function to save model tensors in chunks using safetensors format
def export_model_tensors(args, model_type, state_dict, output_dir, max_chunk_size, vocab_size=None):
    args.sglang_enable_ep_moe = False
    print(f"Saving model to {output_dir}")
    os.makedirs(output_dir, exist_ok=True)

    current_chunk_size = 0
    total_bytes = 0
    chunked_tensors = [{}]

    for name, tensor in collect_named_parameters(args, state_dict):
        if vocab_size:
            tensor = remove_padding(name, tensor, vocab_size)

        converted_tensors = convert_to_hf(args, model_type, name, tensor)
        for conv_name, conv_tensor in converted_tensors:
            tensor_bytes = conv_tensor.numel() * conv_tensor.element_size()

            if tensor_bytes + current_chunk_size > max_chunk_size:
                chunked_tensors.append({})
                current_chunk_size = 0

            chunked_tensors[-1][conv_name] = conv_tensor
            current_chunk_size += tensor_bytes
            total_bytes += tensor_bytes

    # Build metadata
    metadata = {
        "metadata": {"total_size": total_bytes},
        "weight_map": {}
    }
    num_chunks = len(chunked_tensors)

    for idx, tensors in enumerate(chunked_tensors):
        filename = f"model-{idx:05d}-of-{num_chunks:05d}.safetensors"
        for key in tensors.keys():
            metadata["weight_map"][key] = filename

    index_path = os.path.join(output_dir, "model.safetensors.index.json")
    with open(index_path, "w") as f:
        json.dump(metadata, f, indent=2)
    print(f"Index saved at {index_path}")

    # Save each chunk
    for idx, tensors in enumerate(chunked_tensors):
        filename = f"model-{idx:05d}-of-{num_chunks:05d}.safetensors"
        start_time = time.time()
        filepath = os.path.join(output_dir, filename)
        safetensors.torch.save_file(tensors, filepath)
        elapsed = time.time() - start_time
        print(f"{filename} saved in {elapsed:.2f} seconds")


# Copy non-weight assets (e.g., tokenizer, config) from source to destination
def transfer_assets(source_dir, target_dir):
    for item in os.listdir(source_dir):
        if item == "model.safetensors.index.json" or item.endswith(".safetensors"):
            continue

        src_path = os.path.join(source_dir, item)
        if not os.path.isfile(src_path):
            print(f"Skipping {item}, not a file.")
            continue

        dst_path = os.path.join(target_dir, item)
        print(f"Copying {src_path} to {dst_path}")
        shutil.copy(src_path, dst_path)


