    # Parameters that should bypass TP reshaping (just duplicate)
    param_ignore_tp_reshape = [
        "linear_qkv.layer_norm_weight",
        "linear_fc1.layer_norm_weight",
        "final_layernorm.weight",
        "q_layernorm.weight",
