    ]
    # MoE models handle MLP weights in tpe_reshard_fn
    # Parameters requiring gathering along dim=0
    param_column_parallel_linear = [
        "word_embeddings.weight",
        "output_layer.weight",
        "self_attention.linear_qkv.weight",
    ]
    # Parameters requiring gathering along dim=1
    param_row_parallel_linear = [
        "self_attention.linear_proj.weight",
    ]
    # Parameters to skip during TP reshaping
    param_skip_weight = [
        "linear_fc1.weight",
        "linear_fc2.weight",
    ]

    for name, weight in model_checkpoint.items():
        if any(ignore_key in name for ignore_key in param_ignore_tp_reshape):
            model_checkpoint[name] = weight.clone()
            continue
        if any(col_key in name for col_key in param_column_parallel_linear):
            axis = 0
        elif any(row_key in name for row_key in param_row_parallel_linear):
            axis = 1
        elif any(skip_key in name for skip_key in param_skip_weight):
            continue
        else:
            assert False, f"Unrecognized parameter: {name}"
        model_checkpoint[name] = _collect_tp_partitioned_tensor_and_redistribute(
            weight, axis, gather_scale, tp_group
        )
    return model_checkpoint

#################################
# tpe reshard function implementation
#################################
def tpe_reshape_fn_qwen3_moe(
    model_checkpoint, tpe_world_size, tpe_group, rollout_tp_world_size, target_tp_rank
):
    for key, value in model_checkpoint.items():
        if "linear_fc1.weight" in key:
            axis = 0
        elif "linear_fc2.weight" in key:
            axis = 1
        else:
            continue

        if tpe_world_size != 1:
            value = _collect_tp_partitioned_tensor_and_redistribute(value, axis, tpe_world_size, tpe_group)

        if axis == 0:
            # For fc1 weight, split into gate and up projections
            tpe_partition_size = value.shape[axis] // tpe_world_size
            tpe_value_partitions = torch.split(value, tpe_partition_size, dim=axis)
            gate_shards = []
            up_shards = []
            for i, shard in enumerate(tpe_value_partitions):
                chunk = torch.chunk(shard, 2, dim=0)
                gate_shards.append(chunk[0])
                up_shards.append(chunk[1])
            combined_gate = torch.cat(gate_shards, dim=axis)
            combined_up = torch.cat(up_shards, dim=axis)

            rollout_partition_size = combined_gate.shape[axis] // rollout_tp_world_size
            gate_slices = torch.split(combined_gate, rollout_partition_size, dim=axis)
            up_slices = torch.split(combined_up, rollout_partition_size, dim=axis)

            model_checkpoint[key] = torch.cat(
                [gate_slices[target_tp_rank], up_slices[target_tp_rank]],
                dim=0,
            ).contiguous()

            del combined_gate, combined_up, gate_slices, up_slices, value
        else:
            rollout_partition_size = value.shape[axis] // rollout_tp_world_size
            slices = torch.split(value, rollout_partition_size, dim=axis)
            model_checkpoint[key] = slices[target_tp_rank].contiguous()
            del value
    return model_checkpoint

#################################
# pp reshard function implementation
#################################
def _gather_pipeline_parallel_tensor_and_redistribute(
    model_checkpoint, key, src_rank, group, dtype
):
    tensor = model_checkpoint.get(key)
    if tensor is not None:
        shape_list = [tensor.shape]
    else:
        shape_list = [None]

    torch.distributed.broadcast_object_list(shape_list, src_rank, group=group)
    if shape_list[0] is None:
        return None

    if torch.distributed.get_rank() != src_rank:
        tensor = torch.empty(shape_list[0], dtype=dtype).cuda()

    torch.distributed.broadcast(tensor.contiguous(), src_rank, group=group)
    return tensor

def gather_pipeline_parallel_tensors(
    model_checkpoint, keys_with_ranks, pp_group, dtype
):
    """Helper function to reshard multiple keys."""
    for key, source_rank in keys_with_ranks:
        tensor = _gather_pipeline_parallel_tensor_and_redistribute(
            model_checkpoint, key, source_rank, pp_group, dtype
        )
        if tensor is not None:
            model_checkpoint[key] = tensor.clone()
    return model_checkpoint

def _pp_reshape_fn_Qwen_model(model_checkpoint, pp_group, dtype):
    """Common reshaping logic for Qwen models."""
    first_pp_rank = parallel_state.get_pipeline_model_parallel_first_rank()
    last_pp_rank = parallel_state.get_pipeline_model_parallel_last_rank()

    keys_with_ranks = [
        ("embedding.word_embeddings.weight", first_pp_rank),
        ("decoder.final_layernorm.weight", last_pp_rank),
        ("decoder.final_layernorm.bias", last_pp_rank),
        ("output_layer.weight", last_pp_rank),
    ]

    return gather_pipeline_parallel_tensors(
        model_checkpoint, keys_with_ranks, pp_group, dtype
    )

def pp_reshape_fn_qwen2_5(model_checkpoint, pp_group, dtype):
    """Reshape pipeline parallel weights for Qwen2.5 models."""
    return _pp_reshape_fn_Qwen_model(model_checkpoint, pp_group, dtype)

def pp_reshape_fn_qwen3_dense(model_checkpoint, pp_group, dtype):
    """Reshape pipeline parallel weights for Qwen3 dense models."""
    return _pp_reshape_fn_Qwen_model(model_checkpoint, pp_group, dtype)

def pp_reshape_fn_qwen3_moe(model_checkpoint, pp_group, dtype):
    """Reshape pipeline parallel weights for Qwen3 MoE models."""
    return _pp_reshape_fn_Qwen_model(model_checkpoint, pp_group, dtype)

# Export correlated h-cli traces from audit logs
import argparse
import json
import os
import sys
from datetime import datetime, timezone

def read_jsonl_file(filepath):
    """Generate parsed JSON objects from a JSONL file."""
    if not os.path.isfile(filepath):
        return
    with open(filepath) as file:
        for line in file:
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                continue

def convert_timestamp(ts_string):
    """Parse ISO timestamp string to datetime object."""
    # Normalize both Z and +00:00 suffixes
    ts_string = ts_string.replace("Z", "+00:00")
    return datetime.fromisoformat(ts_string)

def collect_task_pairs(log_path):
    """Gather task pairs (initiated + finished) from dispatcher audit log."""
    initiations = {}
    completed_tasks = []
    for record in read_jsonl_file(log_path):
        task_identifier = record.get("task_id")
        if not task_identifier:
            continue
        if "user_message" in record:
            initiations[task_identifier] = record
        elif "output" in record and task_identifier in initiations:
            start_record = initiations.pop(task_identifier)
            completed_tasks.append({
                "task_id": task_identifier,
                "user_id": start_record.get("user_id"),
                "start_time": start_record["timestamp"],
                "end_time": record["timestamp"],
                "user_input": start_record["user_message"],
                "ai_output": record["output"],
                "output_size": record.get("output_length", len(record["output"])),
            })
    return completed_tasks

def gather_firewall_records(log_path):
    """Collect firewall entries (allow/deny + output) sorted chronologically."""
    records = []
    for record in read_jsonl_file(log_path):
        if "command" not in record:
            continue
        records.append(record)
    records.sort(key=lambda r: r["timestamp"])
    return records

def align_with_firewall(task_list, firewall_records):
    """Match firewall entries to tasks based on time windows."""
    aligned_traces = []
    for task in task_list:
        t_begin = convert_timestamp(task["start_time"])
        t_finish = convert_timestamp(task["end_time"])
        # Gather firewall entries within this task's timeframe
        tool_interactions = {}
        for record in firewall_records:
            t_record = convert_timestamp(record["timestamp"])
            if t_record < t_begin:
                continue
            if t_record > t_finish:
                break
            cmd = record["command"]
            if "allowed" in record:
                tool_interactions[cmd] = {
                    "command": cmd,
                    "allowed": record["allowed"],
                    "justification": record.get("reason", ""),
                }
            elif "output_length" in record and cmd in tool_interactions:
                tool_interactions[cmd]["output_length"] = record["output_length"]
        trace = {
            "task_id": task["task_id"],
            "user_id": task["user_id"],
            "timestamp": task["start_time"],
            "user_message": task["user_input"],
            "tool_calls": list(tool_interactions.values()),
            "response": task["ai_output"],
        }
        aligned_traces.append(trace)
    return aligned_traces

def main():
    parser = argparse.ArgumentParser(description="Export correlated h-cli traces")
    parser.add_argument("-d", "--log-directory", default="logs",
                        help="Log directory (default: logs/)")
    parser.add_argument("-f", "--output-file", default="traces.jsonl",
                        help="Output file (default: traces.jsonl)")
    parser.add_argument("--after-date", default=None,
                        help="Only include tasks after this date (YYYY-MM-DD)")
    arguments = parser.parse_args()

    dispatcher_log = os.path.join(arguments.log_directory, "claude", "audit.log")
    firewall_log = os.path.join(arguments.log_directory, "firewall", "audit.log")

    if not os.path.isfile(dispatcher_log):
        print(f"Not found: {dispatcher_log}", file=sys.stderr)
        sys.exit(1)

    # Load and correlate data
    task_data = collect_task_pairs(dispatcher_log)
    firewall_data = gather_firewall_records(firewall_log)
    aligned_data = align_with_firewall(task_data, firewall_data)

    # Filter by date if specified
    if arguments.after_date:
        cutoff = datetime.strptime(arguments.after_date, "%Y-%m-%d").replace(tzinfo=timezone.utc)
        aligned_data = [t for t in aligned_data if convert_timestamp(t["timestamp"]) >= cutoff]

    # Write output
    with open(arguments.output_file, "w") as output:
        for trace in aligned_data:
            output.write(json.dumps(trace, ensure_ascii=False) + "\n")
    print(f"Exported {len(aligned_data)} traces -> {arguments.output_file}")

if __name__ == "__main__":
    main()

