# Validate experience log entries from a JSONL file
import json
import re
import sys
import os
from datetime import datetime, timezone

ID_REGEX = re.compile(r'^EXP-\d{8}-\d{4}$')
ACCEPTABLE_SIGNIFICANCE_LEVELS = {'routine', 'notable', 'pivotal'}
DEFAULT_SOURCES = {'conversation', 'moltbook', 'x', 'heartbeat', 'flush_harvest', 'other'}
MANDATORY_FIELDS = {'id', 'timestamp', 'source', 'content', 'significance', 'significance_reason', 'reflected'}


def load_extra_sources(config_file):
    """Load additional valid source names from config.json."""
    additional = set()
    if config_file and os.path.exists(config_file):
        try:
            with open(config_file) as file:
                config = json.load(file)
            for key in config.get('sources', {}):
                additional.add(key)
        except Exception:
            pass
    return DEFAULT_SOURCES | additional


def parse_timestamp(ts):
    """Check if timestamp is valid ISO-8601."""
    try:
        # Handle both Z and +00:00 formats
        ts = ts.replace('Z', '+00:00')
        dt = datetime.fromisoformat(ts)
        return dt
    except (ValueError, TypeError):
        return None


def check(filepath, config_path=None):
    problems = []
    alerts = []
    acceptable_sources = load_extra_sources(config_path)
    identified_entries = set()
    entry_count = 0
    high_priority_ids = []

    if not os.path.exists(filepath):
        return {
            'status': 'FAIL',
            'file': filepath,
            'errors': [{'line': None, 'field': None, 'message': f'File not found: {filepath}'}],
            'warnings': [],
            'stats': {}
        }

    with open(filepath, 'r', encoding='utf-8') as stream:
        for line_number, line in enumerate(stream, 1):
            line = line.strip()
            if not line:
                continue
            entry_count += 1

            # Parse JSON
            try:
                record = json.loads(line)
            except json.JSONDecodeError as e:
                problems.append({
                    'line': line_number,
                    'field': None,
                    'message': f'Invalid JSON: {str(e)[:80]}'
                })
                continue

            if not isinstance(record, dict):
                problems.append({
                    'line': line_number,
                    'field': None,
                    'message': f'Expected JSON object, got {type(record).__name__}'
                })
                continue

            # Mandatory fields
            for field in MANDATORY_FIELDS:
                if field not in record:
                    problems.append({
                        'line': line_number,
                        'field': field,
                        'message': f'Missing required field: {field}'
                    })

            # ID format
            eid = record.get('id', '')
            if eid and not ID_REGEX.match(eid):
                problems.append({
                    'line': line_number,
                    'field': 'id',
                    'message': f'Invalid ID format: "{eid}" (expected EXP-YYYYMMDD-NNNN)'
                })

            # Duplicate ID
            if eid in identified_entries:
                problems.append({
                    'line': line_number,
                    'field': 'id',
                    'message': f'Duplicate ID: {eid}'
                })
            identified_entries.add(eid)

            # Timestamp
            ts = record.get('timestamp')
            if ts:
                dt = parse_timestamp(ts)
                if dt is None:
                    problems.append({
                        'line': line_number,
                        'field': 'timestamp',
                        'message': f'Invalid ISO-8601 timestamp: "{ts}"'
                    })
                elif dt.tzinfo and dt > datetime.now(timezone.utc):
                    alerts.append({
                        'line': line_number,
                        'message': f'Timestamp is in the future: {ts}'
                    })

            # Source
            source = record.get('source', '')
            if source and source not in acceptable_sources:
                problems.append({
                    'line': line_number,
                    'field': 'source',
                    'message': f'Unknown source: "{source}" (valid: {sorted(acceptable_sources)})'
                })

            # Significance
            sig = record.get('significance', '')
            if sig and sig not in ACCEPTABLE_SIGNIFICANCE_LEVELS:
                problems.append({
                    'line': line_number,
                    'field': 'significance',
                    'message': f'Invalid significance: "{sig}" (valid: routine, notable, pivotal)'
                })

            # Track notable/pivotal for promotion check
            if sig in ('notable', 'pivotal'):
                high_priority_ids.append(eid)

            # Content non-empty
            content = record.get('content', '')
            if isinstance(content, str) and not content.strip():
                problems.append({
                    'line': line_number,
                    'field': 'content',
                    'message': 'Content is empty'
                })

            # Significance reason non-empty
            reason = record.get('significance_reason', '')
            if isinstance(reason, str) and not reason.strip():
                alerts.append({
                    'line': line_number,
                    'message': 'significance_reason is empty'
                })

            # Reflected is boolean
            reflected = record.get('reflected')
            if reflected is not None and not isinstance(reflected, bool):
                problems.append({
                    'line': line_number,
                    'field': 'reflected',
                    'message': f'reflected must be boolean, got {type(reflected).__name__}: {reflected}'
                })

    outcome = 'FAIL' if problems else 'PASS'
    return {
        'status': outcome,
        'file': filepath,
        'errors': problems,
        'warnings': alerts,
        'stats': {
            'total_entries': entry_count,
            'unique_ids': len(identified_entries),
            'notable_pivotal_count': len(high_priority_ids),
            'notable_pivotal_ids': high_priority_ids
        }
    }


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: validate_experience.py <jsonl_file> [--config config.json]', file=sys.stderr)
        sys.exit(2)

    filepath = sys.argv[1]
    config_path = None
    if '--config' in sys.argv:
        idx = sys.argv.index('--config')
        if idx + 1 < len(sys.argv):
            config_path = sys.argv[idx + 1]

    result = check(filepath, config_path)
    print(json.dumps(result, indent=2))
    sys.exit(0 if result['status'] == 'PASS' else 1)

