def calc_expected_logprobs(tokenizer, text: str) -> list[dict]:
    token_ids = tokenizer.encode(text, add_special_tokens=False)
    return [
        {"token": tokenizer.convert_ids_to_tokens(tid), "token_id": tid, "logprob": -idx / 128}
        for idx, tid in enumerate(token_ids)
    ]

def get_expected_prompt_token_ids(tokenizer, messages: list[dict], tools: list[dict] | None) -> list[int]:
    prompt_text = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True, tools=tools)
    return tokenizer.encode(prompt_text, add_special_tokens=False)

