                TwoTurnStub.OPENAI_MESSAGES_SECOND_TURN_FROM_CLIENT,
                TwoTurnStub.SECOND_RESPONSE,
                None,
                "stop",
                id="second_turn",
            ),
        ],
    )
    def test_chat_completions_endpoint_multi_turn(self, messages_list, expected_content_val, expected_tool_calls_val, expected_finish_reason_val):
        with with_mock_server(process_fn=TwoTurnStub.process_fn) as server:
