# Webhook API - UCM
# Routes for managing webhook configurations.
"""
from flask import Blueprint, request
from auth.unified import require_auth
from utils.response import success_response, error_response
from models import db
from services.webhook_service import WebhookEndpoint, WebhookService
import json
import secrets

bp = Blueprint('webhooks', __name__)

@bp.route('/api/v2/webhooks', methods=['GET'])
@require_auth(['read:settings'])
def list_webhooks():
    """Retrieve all webhook endpoints"""
    endpoints = WebhookEndpoint.query.all()
    return success_response(data=[e.to_dict() for e in endpoints])

@bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['GET'])
@require_auth(['read:settings'])
def get_webhook(endpoint_id):
    """Fetch details of a specific webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    return success_response(data=endpoint.to_dict())

@bp.route('/api/v2/webhooks', methods=['POST'])
@require_auth(['write:settings'])
def create_webhook():
    """Create a new webhook endpoint"""
    payload = request.get_json()

    if not payload.get('name'):
        return error_response("Webhook name is required", 400)
    if not payload.get('url'):
        return error_response("Webhook URL is required", 400)

    # Validate URL format
    target_url = payload['url']
    if not target_url.startswith(('http://', 'https://')):
        return error_response("URL must start with http:// or https://", 400)

    trigger_events = payload.get('events', ['*'])
    if not isinstance(trigger_events, list):
        return error_response('Events must be an array', 400)
    headers = payload.get('custom_headers', {})
    if headers and not isinstance(headers, dict):
        return error_response('Custom headers must be an object', 400)

    endpoint = WebhookEndpoint(
        name=payload['name'],
        url=target_url,
        secret=payload.get('secret') or secrets.token_urlsafe(32),
        events=json.dumps(trigger_events),
        ca_filter=payload.get('ca_filter'),
        enabled=payload.get('enabled', True),
        custom_headers=json.dumps(headers)
    )

    db.session.add(endpoint)
    db.session.commit()

    return success_response(data=endpoint.to_dict(), message="Webhook created")

@bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['PUT'])
@require_auth(['write:settings'])
def update_webhook(endpoint_id):
    """Update an existing webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    payload = request.get_json()

    if 'name' in payload:
        endpoint.name = payload['name']
    if 'url' in payload:
        target_url = payload['url']
        if not target_url.startswith(('http://', 'https://')):
            return error_response("URL must start with http:// or https://", 400)
        endpoint.url = target_url
    if 'secret' in payload:
        endpoint.secret = payload['secret']
    if 'events' in payload:
        if not isinstance(payload['events'], list):
            return error_response('Events must be an array', 400)
        endpoint.events = json.dumps(payload['events'])
    if 'ca_filter' in payload:
        endpoint.ca_filter = payload['ca_filter']
    if 'enabled' in payload:
        endpoint.enabled = payload['enabled']
    if 'custom_headers' in payload:
        if payload['custom_headers'] and not isinstance(payload['custom_headers'], dict):
            return error_response('Custom headers must be an object', 400)
        endpoint.custom_headers = json.dumps(payload['custom_headers'])

    db.session.commit()
    return success_response(data=endpoint.to_dict(), message="Webhook updated")

@bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['DELETE'])
@require_auth(['write:settings'])
def delete_webhook(endpoint_id):
    """Delete a webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    db.session.delete(endpoint)
    db.session.commit()
    return success_response(message="Webhook deleted")

@bp.route('/api/v2/webhooks/<int:endpoint_id>/toggle', methods=['POST'])
@require_auth(['write:settings'])
def toggle_webhook(endpoint_id):
    """Enable or disable a webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    endpoint.enabled = not endpoint.enabled
    db.session.commit()

    status = "enabled" if endpoint.enabled else "disabled"
    return success_response(data=endpoint.to_dict(), message=f"Webhook {status}")

@bp.route('/api/v2/webhooks/<int:endpoint_id>/test', methods=['POST'])
@require_auth(['write:settings'])
def test_webhook(endpoint_id):
    """Send a test event to the webhook endpoint"""
    success, message = WebhookService.test_endpoint(endpoint_id)

    if success:
        return success_response(message=message)
    else:
        return error_response(message, 400)

@bp.route('/api/v2/webhooks/<int:endpoint_id>/regenerate-secret', methods=['POST'])
@require_auth(['write:settings'])
def regenerate_secret(endpoint_id):
    """Regenerate the secret for a webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    endpoint.secret = secrets.token_urlsafe(32)
    db.session.commit()

    return success_response(
        data={'secret': endpoint.secret},
        message="Secret regenerated"
    )

@bp.route('/api/v2/webhooks/events', methods=['GET'])
@require_auth(['read:settings'])
def list_events():
    """List available webhook event types"""
    return success_response(data={
        'events': WebhookService.ALL_EVENTS,
        'descriptions': {
            'certificate.issued': 'When a new certificate is issued',
            'certificate.revoked': 'When a certificate is revoked',
            'certificate.renewed': 'When a certificate is auto-renewed',
            'certificate.expiring': 'When a certificate is about to expire',
            'ca.created': 'When a new CA is created',
            'ca.updated': 'When a CA is updated',
            'csr.submitted': 'When a CSR is submitted',
            'csr.approved': 'When a CSR is approved',
            'csr.rejected': 'When a CSR is rejected',
        }
    })

# Literature search agent implementation with multi-source integration
import argparse
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from pubmed_search import search_and_fetch as pubmed_search
from semantic_scholar import search_papers as s2_search, get_paper, get_related, get_citations

def construct_search_query(data: dict) -> str:
    """Construct a literature search query from structured input."""
    components = []

    # Direct query takes precedence
    if data.get("query"):
        return data["query"]

    # Add compound or name information
    if data.get("compound") or data.get("name"):
        components.append(data.get("compound") or data.get("name"))

    # SMILES are not suitable for text-based search
    if data.get("smiles"):
        pass  # Placeholder for potential future use

    # Add target, disease, mechanism, reaction, and topic fields
    if data.get("target"):
        components.append(data["target"])
    if data.get("disease"):
        components.append(data["disease"])
    if data.get("mechanism"):
        components.append(data["mechanism"])
    if data.get("reaction"):
        components.append(data["reaction"] + " catalyst")
    if data.get("topic"):
        components.append(data["topic"])

    return " ".join(components) if components else ""

def merge_and_deduplicate(pubmed_records: list, s2_records: list) -> list:
    """Combine papers from both sources while removing duplicates."""
    processed_dois = set()
    processed_pmids = set()
    processed_titles = set()
    combined_list = []

    # Process PubMed records first (higher priority)
    for record in pubmed_records:
        doi = record.get("doi", "").lower()
        pmid = record.get("pmid", "")
        title_signature = record.get("title", "").lower()[:80]

        # Skip duplicates based on DOI, PMID, or title
        if doi and doi in processed_dois:
            continue
        if pmid and pmid in processed_pmids:
            continue
        if title_signature in processed_titles:
            continue

        record["sources"] = ["pubmed"]
        if doi:
            processed_dois.add(doi)
        if pmid:
            processed_pmids.add(pmid)
        processed_titles.add(title_signature)
        combined_list.append(record)

    # Process Semantic Scholar records
    for record in s2_records:
        doi = record.get("doi", "").lower()
        pmid = record.get("pmid", "")
        title_signature = record.get("title", "").lower()[:80]

        # Check if already exists in combined list
        if doi and doi in processed_dois:
            # Enrich existing entry with S2-specific data
            for item in combined_list:
                if item.get("doi", "").lower() == doi:
                    item["sources"].append("semantic_scholar")
                    item["citation_count"] = record.get("citation_count", 0)
                    item["influential_citations"] = record.get("influential_citations", 0)
                    item["tldr"] = record.get("tldr", "")
                    item["pdf_url"] = record.get("pdf_url", "")
                    break
            continue

        if pmid and pmid in processed_pmids:
            continue
        if title_signature in processed_titles:
            continue

        record["sources"] = ["semantic_scholar"]
        if doi:
            processed_dois.add(doi)
        if pmid:
            processed_pmids.add(pmid)
        processed_titles.add(title_signature)
        combined_list.append(record)

    return combined_list

def execute_chain(input_data: dict) -> dict:
    """Execute the appropriate literature search workflow based on input."""
    context = input_data.get("context", "user")
    limit = input_data.get("max_results", 10)
    year_range = input_data.get("years")

    # Handle direct paper lookups by DOI or PMID
    if input_data.get("doi"):
        identifier = f"DOI:{input_data['doi']}"
        operation = input_data.get("action", "details")
        if operation == "citations":
            return get_citations(identifier, limit)
        elif operation == "related":
            return get_related(identifier, limit)
        else:
            return get_paper(identifier)

    if input_data.get("pmid"):
        identifier = f"PMID:{input_data['pmid']}"
        return get_paper(identifier)

    # Build search query from input
    query = construct_search_query(input_data)
    if not query:
        return {
            "agent": "literature",
            "version": "1.0.0",
            "status": "error",
            "error": "Unable to construct search query. Provide 'query', 'compound', 'target', 'disease', or 'topic'.",
        }

    # Execute searches across both platforms
    pubmed_response = pubmed_search(query, limit, "relevance", year_range)
    s2_response = s2_search(query, limit)

    pubmed_papers = pubmed_response.get("papers", [])
    s2_papers = s2_response.get("papers", [])

    # Merge results and remove duplicates
    final_results = merge_and_deduplicate(pubmed_papers, s2_papers)

    # Sort by citation count and publication year
    final_results.sort(key=lambda p: (p.get("citation_count", 0), p.get("year", "0")), reverse=True)

    # Determine recommended follow-up agents based on content analysis
    next_agents = set()

    # Check for drug-related content
    if any("drug" in (p.get("title", "") + " " + " ".join(p.get("mesh_terms", []))).lower() 
           for p in final_results[:5]):
        next_agents.add("pharmacology")

    # Check for synthesis-related content
    if any("synth" in (p.get("title", "") + " " + p.get("abstract", "")).lower() 
           for p in final_results[:5]):
        next_agents.update(["chemistry-query", "catalyst-design"])

    # Check for patent-related content
    if any("patent" in (p.get("title", "") + " " + p.get("abstract", "")).lower() 
           for p in final_results[:5]):
        next_agents.add("ip-expansion")

    # Check for adverse effect mentions
    if any("adverse" in (p.get("title", "") + " " + p.get("abstract", "")).lower() 
           for p in final_results[:5]):
        next_agents.add("market-intel")

    return {
        "agent": "literature",
        "version": "1.0.0",
        "context": context,
        "query": query,
        "status": "success" if final_results else "no_results",
        "pubmed_total": pubmed_response.get("total_found", 0),
        "s2_total": s2_response.get("total_found", 0),
        "returned": len(final_results),
        "papers": final_results[:limit],
        "recommend_next": sorted(next_agents) if next_agents else ["chemistry-query", "pharmacology"],
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }

def main():
    parser = argparse.ArgumentParser(description="Literature Agent - Chain Entry Point")
    parser.add_argument("--input-json", required=True, help="JSON-formatted input string")
    args = parser.parse_args()

    try:
        input_data = json.loads(args.input_json)
    except json.JSONDecodeError as error:
        print(json.dumps({"agent": "literature", "status": "error", "error": f"Invalid JSON: {error}"}))
        sys.exit(1)

    result = execute_chain(input_data)
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

# Embedding service using SentenceTransformers
import os
import logging
from flask import Flask, jsonify, request
from sentence_transformers import SentenceTransformer

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

app = Flask(__name__)

# Configuration from environment variables
MODEL_NAME = os.environ.get("EMBEDDING_MODEL", "intfloat/e5-large-v2")
SERVICE_PORT = int(os.environ.get("EMBEDDING_PORT", "8765"))

logger.info(f"Initializing model: {MODEL_NAME}")
logger.info("NOTE: Initial execution will fetch the model from HuggingFace (~1.3GB)")
embedder = SentenceTransformer(MODEL_NAME)

embedding_dim = embedder.get_sentence_embedding_dimension()
logger.info(f"Model initialized successfully. Embedding dimension: {embedding_dim}")

@app.route("/status", methods=["GET"])
def health_check():
    return jsonify({
        "status": "ok",
        "model": MODEL_NAME,
        "embedding_dim": embedding_dim
    })

@app.route("/encode", methods=["POST"])
def generate_embeddings():
    try:
        payload = request.get_json()
        if not payload or "texts" not in payload:
            return jsonify({"error": "Missing 'texts' field"}), 400

        input_texts = payload["texts"]
        if not isinstance(input_texts, list):
            return jsonify({"error": "'texts' must be a list"}), 400

        prefix = payload.get("prefix", "passage: ")
        modified_texts = [f"{prefix}{text}" for text in input_texts]

        vectors = embedder.encode(modified_texts, normalize_embeddings=True)

        return jsonify({
            "embeddings": vectors.tolist(),
            "model": MODEL_NAME,
            "dimension": embedding_dim
        })
    except Exception as error:
        logger.error(f"Exception during embedding generation: {error}")
        return jsonify({"error": str(error)}), 500

@app.route("/encode_query", methods=["POST"])
def generate_query_embedding():
    try:
        payload = request.get_json()
        if not payload or "query" not in payload:
            return jsonify({"error": "Missing 'query' field"}), 400

        user_query = payload["query"]
        formatted_query = f"query: {user_query}"

        vector = embedder.encode([formatted_query], normalize_embeddings=True)

        return jsonify({
            "embedding": vector[0].tolist(),
            "model": MODEL_NAME,
            "dimension": embedding_dim
        })
    except Exception as error:
        logger.error(f"Exception during query embedding: {error}")
        return jsonify({"error": str(error)}), 500

if __name__ == "__main__":
    logger.info(f"Starting embedding server on port {SERVICE_PORT}")
    app.run(host="127.0.0.1", port=SERVICE_PORT, debug=False)

