import os
import sys
import importlib.resources
from typing import Optional
import click
from rich import print as rprint

# ----------------------------------------------------------------------
# Runtime resolution of PDD_PATH directory.
# ----------------------------------------------------------------------
def retrieve_pdd_directory() -> str:
    """
    Locate and return the PDD_PATH directory.
    First checks the environment variable; if absent, attempts to infer it
    using importlib.resources. If both fail, terminate execution.
    """
    if "PDD_PATH" in os.environ:
        return os.environ["PDD_PATH"]
    else:
        try:
            resource_path = importlib.resources.files("pdd").joinpath("cli.py")
            inferred_path = str(resource_path.parent)
            # Store back into environment for consistency
            os.environ["PDD_PATH"] = inferred_path
            return inferred_path
        except ImportError:
            rprint(
                "[red]Error: Unable to resolve the 'pdd' package location. "
                "Please manually define the PDD_PATH environment variable.[/red]"
            )
            sys.exit(1)

# ----------------------------------------------------------------------
# Streamlined shell RC file path logic
# ----------------------------------------------------------------------
def locate_shell_rc(shell_name: str) -> Optional[str]:
    """Determine the default RC file path based on the provided shell name."""
    user_home = os.path.expanduser("~")
    if shell_name == "bash":
        return os.path.join(user_home, ".bashrc")
    elif shell_name == "zsh":
        return os.path.join(user_home, ".zshrc")
    elif shell_name == "fish":
        return os.path.join(user_home, ".config", "fish", "config.fish")
    return None

def detect_active_shell() -> Optional[str]:
    """Identify the currently active shell with improved reliability."""
    if not os.environ.get('PYTEST_CURRENT_TEST'):
        # Approach 1: Inspect process name via 'ps'
        try:
            import subprocess
            proc_result = subprocess.run(['ps', '-p', str(os.getppid()), '-o', 'comm='], 
                                      capture_output=True, text=True)
            if proc_result.returncode == 0:
                # Clean output: strip whitespace and extract basename
                shell_name = os.path.basename(proc_result.stdout.strip())
                # Eliminate leading dash (login shells often include it)
                return shell_name.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass

        # Approach 2: Evaluate $0 parameter through shell
        try:
            exec_result = subprocess.run(['sh', '-c', 'echo "$0"'], 
                                       capture_output=True, text=True)
            if exec_result.returncode == 0:
                shell_name = os.path.basename(exec_result.stdout.strip())
                return shell_name.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass

    # Final fallback: use SHELL environment variable
    return os.path.basename(os.environ.get("SHELL", ""))

def derive_completion_extension(shell_name: str) -> str:
    """Map shell names to their corresponding completion script extensions."""
    shell_mapping = {
        "bash": "sh",
        "zsh": "zsh",
        "fish": "fish"
    }
    return shell_mapping.get(shell_name, shell_name)

def enable_completion(silent: bool = False):
    """
    Activate shell completion for the PDD CLI by detecting the user's shell,
    copying the appropriate completion script, and appending a source directive
    to the user's shell RC file—unless already present.
    """
    current_shell = detect_active_shell()
    rc_filepath = locate_shell_rc(current_shell)

    if not rc_filepath:
        if not silent:
            rprint(f"[red]Unsupported shell detected: {current_shell}[/red]")
        raise click.Abort()

    ext = derive_completion_extension(current_shell)

    # Resolve local PDD path dynamically at runtime:
    pdd_dir = retrieve_pdd_directory()
    completion_script = os.path.join(pdd_dir, f"pdd_completion.{ext}")

    if not os.path.exists(completion_script):
        if not silent:
            rprint(f"[red]Completion script missing: {completion_script}[/red]")
        raise click.Abort()

    source_line = f"source {completion_script}"

    try:
        # Ensure RC file exists (create if needed)
        if not os.path.exists(rc_filepath):
            parent_dir = os.path.dirname(rc_filepath)
            if parent_dir:  # Avoid issues when parent_dir is empty string
                os.makedirs(parent_dir, exist_ok=True)
            with open(rc_filepath, "w", encoding="utf-8") as rc_file:
                rc_file.write("")  # Initialize empty file

        # Read existing content
        with open(rc_filepath, "r", encoding="utf-8") as rc_file:
            existing_content = rc_file.read()

        if source_line not in existing_content:
            with open(rc_filepath, "a", encoding="utf-8") as rc_file:
                rc_file.write(f"\n# PDD CLI completion\n{source_line}\n")

            if not silent:
                rprint(f"[green]Shell completion enabled for {current_shell}.[/green]")
                rprint(f"Restart your shell or execute 'source {rc_filepath}' to apply changes.")
        else:
            if not silent:
                rprint(f"[yellow]Shell completion already configured for {current_shell}.[/yellow]")
    except OSError as error:
        if not silent:
            rprint(f"[red]Installation failed: {error}[/red]")
        raise click.Abort()

# Patch to bypass secure root checks in kernel
from .kernel_jb_base import ARM64_OP_IMM, asm

class KernelJBPatchSecureRootMixin:
    def patch_io_secure_bsd_root(self):
        """Bypass security validation in _IOSecureBSDRoot.
        Prioritize symbol lookup. For stripped kernels, locate a function referencing both
        "SecureRoot" and "SecureRootName", then replace its strict policy branch.
        """
        self._log("\n[JB] _IOSecureBSDRoot: bypass check")
        # Attempt symbol resolution first
        foff = self._resolve_symbol("_IOSecureBSDRoot")
        if foff < 0:
            foff = self._locate_secure_root_function()
        if foff < 0:
            self._log("  [-] target function not found")
            return False

        func_limit = self._find_func_end(foff, 0x1200)
        site = self._find_secure_root_branch_site(foff, func_limit)
        if not site:
            self._log("  [-] secure-root policy branch location not identified")
            return False

        offset, dest = site
        b_bytes = self._compile_branch_checked(offset, dest)
        self.emit(offset, b_bytes, f"b #0x{dest - offset:X} [_IOSecureBSDRoot]")
        return True

    def _locate_secure_root_function(self):
        funcs_with_name = self._functions_referencing_string(b"SecureRootName")
        if not funcs_with_name:
            return -1

        funcs_with_root = self._functions_referencing_string(b"SecureRoot")
        common = funcs_with_name & funcs_with_root
        if not common:
            # Fail-safe: SecureRootName-only functions are usually setup/teardown code
            return -1

        # Deterministic selection: smallest function offset among candidates
        return min(common)

    def _functions_referencing_string(self, pattern):
        func_starts = set()
        for str_off in self._all_cstring_offsets(pattern):
            refs = self.find_string_refs(str_off, *self.kern_text)
            for adrp_off, _, _ in refs:
                fn = self.find_function_start(adrp_off)
                if fn >= 0:
                    func_starts.add(fn)
        return func_starts

    def _all_cstring_offsets(self, pattern):
        if isinstance(pattern, str):
            pattern = pattern.encode()
        out = []
        start = 0
        while True:
            pos = self.raw.find(pattern, start)
            if pos < 0:
                break
            cstr = pos
            while cstr > 0 and self.raw[cstr - 1] != 0:
                cstr -= 1
            cend = self.raw.find(b"\x00", cstr)
            if cend > cstr and self.raw[cstr:cend] == pattern:
                out.append(cstr)
            start = pos + 1
        return sorted(set(out))

    def _find_secure_root_branch_site(self, func_start, func_end):
        # Refined selection criteria:
        #  - forward conditional branch instruction
        #  - operating on register w0
        #  - preceded by BL (typical comparison/call sequence)
        #  - outside epilogue guard zone (AUTIBSP/TBZ+BRK integrity protections)
        for off in range(func_start, func_end - 4, 4):
            d = self._disas_at(off)
            if not d:
                continue
            i = d[0]
            if i.mnemonic not in ("cbnz", "cbz"):
                continue
            if not i.op_str.replace(" ", "").startswith("w0,"):
                continue

            prev = self._disas_at(off - 4)
            if not prev or not prev[0].mnemonic.startswith("bl"):
                continue

            target = None
            for op in reversed(i.operands):
                if op.type == ARM64_OP_IMM:
                    target = op.imm
                    break

            if not target or not (off < target < func_end):
                continue

            if self._looks_like_epilogue_guard(off, target, func_end):
                continue

            return (off, target)
        return None

    def _looks_like_epilogue_guard(self, off, target, func_end):
        if off >= func_end - 0x40 or target >= func_end - 0x20:
            return True

        for probe in range(max(target - 4, 0), min(target + 0x14, func_end), 4):
            d = self._disas_at(probe)
            if d and d[0].mnemonic == "brk":
                return True

        for probe in range(max(off - 0x10, 0), off + 4, 4):
            d = self._disas_at(probe)
            if d and d[0].mnemonic == "autibsp":
                return True
        return False

    def _compile_branch_checked(self, off, target):
        delta = target - off
        b_bytes = asm(f"b #{delta}")
        insns = self._disas_n(b_bytes, 0, 1)
        assert insns, "capstone decode failed for secure-root branch patch"

        ins = insns[0]
        assert ins.mnemonic == "b", (
            f"secure-root branch decode mismatch: expected 'b', got '{ins.mnemonic}'"
        )

        got_target = None
        for op in reversed(ins.operands):
            if op.type == ARM64_OP_IMM:
                got_target = op.imm
                break

        assert got_target == delta, (
            "secure-root branch target mismatch: "
            f"expected delta 0x{delta:X}, got 0x{(got_target or -1):X}"
        )
        return b_bytes

# Custom exceptions for the requests library
"""
This module defines the exception classes used by the requests library.
"""
from pip._vendor.urllib3.exceptions import HTTPError as BaseHTTPError
from .compat import JSONDecodeError as CompatJSONDecodeError

class RequestException(IOError):
    """An ambiguous exception occurred during request processing."""
    def __init__(self, *args, **kwargs):
        """Initialize with optional 'request' and 'response' objects."""
        response = kwargs.pop("response", None)
        self.response = response
        self.request = kwargs.pop("request", None)
        if response is not None and not self.request and hasattr(response, "request"):
            self.request = self.response.request
        super().__init__(*args, **kwargs)

class InvalidJSONError(RequestException):
    """An error occurred while parsing JSON."""

class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Unable to decode text as JSON."""
    def __init__(self, *args, **kwargs):
        """
        Initialize using JSONDecodeError's constructor first,
        then pass arguments to parent classes preserving JSON-specific info.
        """
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)

class HTTPError(RequestException):
    """An HTTP protocol error occurred."""

class ConnectionError(RequestException):
    """Network connection failure."""

class ProxyError(ConnectionError):
    """Proxy-related communication error."""

class SSLError(ConnectionError):
    """Secure socket layer (SSL/TLS) error."""

class Timeout(RequestException):
    """Request duration exceeded allowed time limit.
    Includes both connection and read timeout scenarios.
    """
class ConnectTimeout(ConnectionError, Timeout):
    """Connection establishment exceeded time limit.
    These requests are generally safe to retry.
    """
class ReadTimeout(Timeout):
    """Server failed to send data within expected timeframe."""

class URLRequired(RequestException):
    """A valid URL must be provided for the request."""

class TooManyRedirects(RequestException):
    """Maximum redirect count exceeded."""

class MissingSchema(RequestException, ValueError):
    """URL missing required scheme (e.g., 'http://' or 'https://')."""

class InvalidSchema(RequestException, ValueError):
    """Specified URL scheme is not supported."""

class InvalidURL(RequestException, ValueError):
    """Provided URL format is invalid."""

class InvalidHeader(RequestException, ValueError):
    """Header value does not conform to standards."""

class InvalidProxyURL(InvalidURL):
    """Proxy server address is malformed."""

class ChunkedEncodingError(RequestException):
    """Server sent malformed chunked transfer encoding."""

class ContentDecodingError(RequestException, BaseHTTPError):
    """Response content could not be decoded properly."""

class StreamConsumedError(RequestException, TypeError):
    """Attempted to read from already-consumed response body."""

class RetryError(RequestException):
    """Custom retry mechanism encountered a failure."""

class UnrewindableBodyError(RequestException):
    """Cannot rewind request body after network error."""

# Warning classes
class RequestsWarning(Warning):
    """Base class for all Requests-related warnings."""

class FileModeWarning(RequestsWarning, DeprecationWarning):
    """File opened in text mode; binary size was inferred."""

class RequestsDependencyWarning(RequestsWarning):
    """Installed dependency version does not meet requirements."""

