class FTXFuturesInterface(FuturesExchangeInterface):
    api_client: FTXAPI

    @staticmethod
    def convert_to_exchange_symbol(symbol: str):
        base_asset, quote_asset = symbol.split('-', 1)
        if quote_asset != 'USD':
            raise ValueError('invalid symbol')
        return base_asset + '-PERP'  # only perpetual contracts currently supported
    @staticmethod
    def convert_to_blankly_symbol(symbol: str):
        base_asset, contract_type = symbol.split('-', 1)
        if contract_type != 'PERP':
            raise ValueError(
                'invalid symbol -- blankly only supports perpetual contracts')
        return base_asset + '-USD'
    @staticmethod
    def convert_timestamp(time_str: str) -> int:
        return int(datetime.datetime.fromisoformat(time_str).timestamp())
    @staticmethod
    def map_order_status(status: str, cancelled: bool = False) -> OrderStatus:
        if status in ('new', 'open'):
            return OrderStatus.OPEN
        elif status == 'closed':
            if cancelled:
                return OrderStatus.CANCELED
            else:
                return OrderStatus.FILLED
        raise ValueError(f'invalid order status: {status}')
    @staticmethod
    def map_order_type(order_type: str) -> OrderType:
        if order_type == 'market':
            return OrderType.MARKET
        elif order_type == 'limit':
            return OrderType.LIMIT
        elif order_type == 'takeProfit':
            return OrderType.TAKE_PROFIT
        elif order_type == 'stop':
            return OrderType.STOP
        raise ValueError(f'invalid order type: {order_type}')

    def parse_order_response(self,
                             response_data: dict,
                             cancelled: bool = False) -> FuturesOrder:
        return FuturesOrder(
            symbol=response_data['future'],
            id=int(response_data['id']),
            status=self.map_order_status(response_data['status'], cancelled),
            size=float(response_data['size']),
            type=self.map_order_type(response_data['type']),
            contract_type=ContractType.PERPETUAL,
            side=Side(response_data['side']),
            position=PositionMode.BOTH,
            price=float(response_data['avgFillPrice']),
            limit_price=float(response_data['price']),
            time_in_force=TimeInForce.IOC
            if response_data['ioc'] else TimeInForce.GTC,
            response=response_data,
            interface=self)

    def initialize_api_connection(self):
        # will throw exception if our api key is invalid
        self.api_client.get_account_info()

    def get_available_products(self, filter_symbol: str = None) -> dict:
        res = self.api_client.list_futures()
        products = {}
        for product in res:
            if '-PERP' not in product['name']:
                continue  # only perpetual contracts for now
            symbol = product['underlying'] + '-USD'
            products[symbol] = {
                'symbol': symbol,
                'base_asset': product['underlying'],
                'quote_asset': 'USD',
                'contract_type': ContractType.PERPETUAL,
                'price_precision': utils.increment_to_precision(
                    product['priceIncrement']),
                'size_precision': utils.increment_to_precision(
                    product['sizeIncrement']),
                'exchange_specific': product
            }
        if filter_symbol:
            return products[filter_symbol]
        return products

    def get_account_balances(self, filter_coin: str = None) -> dict:
        balances = self.api_client.get_balances()
        coins = self.api_client.get_coins()
        accounts = {
            coin['id']: {
                'available': 0.0,
                'hold': 0.0,  # TODO
                'exchange_specific': coin
            }
            for coin in coins
        }
        for bal in balances:
            coin = bal['coin']
            accounts[coin].available = float(bal['free'])
            # merge into exchange_specific
            accounts[coin].exchange_specific = {
                **accounts[coin].exchange_specific,
                **bal
            }
        if filter_coin:
            return accounts[filter_coin]
        return accounts

    def get_current_position(self, filter_symbol: str = None) -> Optional[dict]:
        leverage = self.get_leverage()
        res = self.api_client.get_positions()
        positions = {}
        for position in res:
            symbol = self.convert_to_exchange_symbol(position['future'])
            size = float(position['netSize'])
            if size == 0:
                continue
            positions[symbol] = {
                'size': size,
                'position': PositionMode.BOTH,
                'contract_type': ContractType.PERPETUAL,
                'exchange_specific': position
            }
        if filter_symbol:
            return positions.get(filter_symbol, None)
        return positions

    def place_market_order(self,
                           symbol: str,
                           side: Side,
                           size: float,
                           position_mode: PositionMode = PositionMode.BOTH,
                           reduce_only: bool = False) -> FuturesOrder:
        symbol = self.convert_to_exchange_symbol(symbol)
        if position_mode != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position_mode} not supported on FTX Futures')
        res = self.api_client.place_order(symbol, side, None, size, 'market',
                                          reduce_only)
        return self.parse_order_response(res)

    def place_limit_order(
            self,
            symbol: str,
            side: Side,
            price: float,
            size: float,
            position_mode: PositionMode = PositionMode.BOTH,
            reduce_only: bool = False,
            time_in_force: TimeInForce = TimeInForce.GTC) -> FuturesOrder:
        symbol = self.convert_to_exchange_symbol(symbol)
        if time_in_force == TimeInForce.GTC:
            ioc = False
        elif time_in_force == TimeInForce.IOC:
            ioc = True
        else:
            raise ValueError(
                f'time in force {time_in_force} not supported on FTX Futures')
        if position_mode != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position_mode} not supported on FTX Futures')
        res = self.api_client.place_order(symbol,
                                          side,
                                          price,
                                          size,
                                          'limit',
                                          reduce_only,
                                          ioc=ioc)
        return self.parse_order_response(res)

    def place_take_profit_order(
            self,
            symbol: str,
            side: Side,
            price: float,
            size: float,
            position_mode: PositionMode = PositionMode.BOTH) -> FuturesOrder:
        symbol = self.convert_to_exchange_symbol(symbol)
        if position_mode != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position_mode} not supported on FTX Futures')
        res = self.api_client.place_conditional_order(symbol,
                                                      side,
                                                      size,
                                                      'takeProfit',
                                                      trigger_price=price)
        return self.parse_order_response(res)

    def place_stop_loss_order(self,
                              symbol: str,
                              side: Side,
                              price: float,
                              size: float,
                              position_mode: PositionMode = PositionMode.BOTH) -> FuturesOrder:
        symbol = self.convert_to_exchange_symbol(symbol)
        if position_mode != PositionMode.BOTH:
            raise ValueError(
                f'position mode {position_mode} not supported on FTX Futures')
        res = self.api_client.place_conditional_order(symbol,
                                                      side,
                                                      size,
                                                      'stop',
                                                      trigger_price=price)
        return self.parse_order_response(res)

    @utils.order_protection
    def configure_hedge_mode(self, hedge_mode: HedgeMode):
        if hedge_mode == HedgeMode.HEDGE:
            raise Exception('HEDGE mode not supported on FTX Futures')
        pass  # FTX only supports ONEWAY mode

    def retrieve_hedge_mode(self):
        return HedgeMode.ONEWAY

    @utils.order_protection
    def adjust_leverage(self, leverage_value: float, symbol: str = None):
        if symbol:
            raise Exception(
                'FTX Futures does not allow setting leverage per symbol. Use interface.adjust_leverage(leverage_value) to set '
                'account-wide leverage instead. ')
        self.api_client.change_account_leverage(leverage_value)

    def retrieve_leverage(self, symbol: str = None) -> float:
        # doesn't matter if symbol passed or not, ftx leverage is same for all
        return self.api_client.get_account_info()['leverage']

    @utils.order_protection
    def configure_margin_type(self, symbol: str, margin_type: MarginType):
        if margin_type == MarginType.ISOLATED:
            raise Exception('isolated margin not supported on FTX Futures')
        pass

    def retrieve_margin_type(self, symbol: str):
        return MarginType.CROSSED

    def cancel_active_order(self, symbol: str, order_id: int) -> FuturesOrder:
        res = self.retrieve_order(symbol, order_id)
        res.status = OrderStatus.CANCELED
        self.api_client.cancel_order(str(order_id))
        return res

    def list_open_orders(self, symbol: str = None) -> list:
        return [
            self.parse_order_response(o) for o in self.api_client.get_open_orders()
        ]

    def retrieve_order(self, symbol: str, order_id: int) -> FuturesOrder:
        response = self.api_client.get_order_by_id(str(order_id))
        symbol = self.convert_to_exchange_symbol(symbol)
        if response['symbol'] != symbol:
            raise Exception(
                'response symbol did not match parameter -- this should never happen'
            )
        return self.parse_order_response(response)

    def get_current_price(self, symbol: str) -> float:
        symbol = self.convert_to_exchange_symbol(symbol)
        return float(self.api_client.get_future(symbol)['mark'])

    def get_funding_rate_records(self, symbol: str, start_time: int,
                                 end_time: int) -> list:
        symbol = self.convert_to_exchange_symbol(symbol)
        # TODO dedup binance_futures_exchange maybe?
        records = []
        interval = self.get_funding_rate_interval()
        max_items = 500
        window_start = start_time
        window_end = start_time + max_items * interval
        response = True
        while response:
            response = self.api_client.get_funding_rates(window_start, window_end,
                                                         symbol)
            records.extend({
                               'rate': float(item['rate']),
                               'time': self.convert_timestamp(item['time'])
                           } for item in response)
            if response:
                window_start = window_end
                window_end = min(end_time, window_start + max_items * interval)
        return sorted(records, key=operator.itemgetter('time'))

    def get_funding_rate_interval(self) -> int:
        return time_builder.build_hour()

    def get_price_history(self, symbol, start_epoch, end_epoch, resolution):
        return FTXInterface.ftx_product_history(self.api_client,self.convert_to_exchange_symbol(symbol), start_epoch, end_epoch, resolution)

    def calculate_maker_fee(self) -> float:
        raise NotImplementedError

    def calculate_taker_fee(self) -> float:
        raise NotImplementedError

    def get_current_funding_rate(self, symbol: str) -> float:
        raise NotImplementedError

# This module evaluates the input_id_columns and upstream_id_columns attributes 
# utilized in computing progress percentage for features with varying lineage types.
"""
from __future__ import annotations
from metaxy_testing.models import SampleFeatureSpec
from metaxy import (
    BaseFeature,
    FeatureDep,
    FeatureGraph,
    FeatureKey,
    FieldKey,
    FieldSpec,
)
from metaxy.models.lineage import LineageRelationship

class TestUpstreamIdColumns:
    """Assessments for FeaturePlan.upstream_id_columns attribute."""

    def test_no_dependencies_yield_empty_sequence(self, graph: FeatureGraph):
        """Base feature lacking dependencies yields an empty list."""
        class RootFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin"]),
                id_columns=["sample_uid"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(RootFeature.spec().key)
        assert plan.upstream_id_columns == []

    def test_one_upstream_provides_its_id_columns(self, graph: FeatureGraph):
        """Single upstream feature contributes its id_columns."""
        class Origin(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin"]),
                id_columns=["video_id", "frame_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass
        class Target(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["target"]),
                id_columns=["video_id", "frame_id"],
                deps=[FeatureDep(feature=Origin)],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(Target.spec().key)
        assert set(plan.upstream_id_columns) == {"video_id", "frame_id"}

    def test_several_upstreams_union_of_id_columns(self, graph: FeatureGraph):
        """Multiple upstream features contribute union of their id_columns."""
        class OriginA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin_a"]),
                id_columns=["video_id", "frame_id"],
                fields=[FieldSpec(key=FieldKey(["value_a"]), code_version="1")],
            ),
        ):
            pass
        class OriginB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin_b"]),
                id_columns=["video_id", "audio_id"],
                fields=[FieldSpec(key=FieldKey(["value_b"]), code_version="1")],
            ),
        ):
            pass
        class Target(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["target"]),
                id_columns=["video_id", "frame_id", "audio_id"],
                deps=[FeatureDep(feature=OriginA), FeatureDep(feature=OriginB)],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(Target.spec().key)
        assert set(plan.upstream_id_columns) == {"video_id", "frame_id", "audio_id"}

    def test_with_rename_uses_column_mapping(self, graph: FeatureGraph):
        """FeatureDep.rename is applied to upstream id_columns."""
        class Origin(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin"]),
                id_columns=["sample_uid", "original_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass
        class Target(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["target"]),
                id_columns=["sample_uid", "renamed_id"],
                deps=[
                    FeatureDep(
                        feature=Origin,
                        rename={"original_id": "renamed_id"},
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(Target.spec().key)
        assert set(plan.upstream_id_columns) == {"sample_uid", "renamed_id"}
        assert "original_id" not in plan.upstream_id_columns

    def test_with_partial_rename(self, graph: FeatureGraph):
        """Only renamed columns are affected, others remain unchanged."""
        class Origin(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin"]),
                id_columns=["video_id", "frame_id", "additional_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass
        class Target(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["target"]),
                id_columns=["video_id", "renamed_frame_id", "additional_id"],
                deps=[
                    FeatureDep(
                        feature=Origin,
                        rename={"frame_id": "renamed_frame_id"},
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(Target.spec().key)
        assert set(plan.upstream_id_columns) == {
            "video_id",
            "renamed_frame_id",
            "additional_id",
        }
        assert "frame_id" not in plan.upstream_id_columns


class TestInputIdColumns:
    """Assessments for FeaturePlan.input_id_columns attribute."""

    def test_identity_lineage_yields_upstream_id_columns(self, graph: FeatureGraph):
        """Identity (1:1) lineage returns upstream_id_columns."""
        class Origin(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin"]),
                id_columns=["video_id", "frame_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass
        class Target(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["target"]),
                id_columns=["video_id", "frame_id"],
                deps=[FeatureDep(feature=Origin)],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
                # Default lineage is identity
            ),
        ):
            pass
        plan = graph.get_feature_plan(Target.spec().key)
        assert set(plan.input_id_columns) == {"video_id", "frame_id"}
        assert plan.input_id_columns == plan.upstream_id_columns

    def test_aggregation_lineage_yields_aggregation_columns(self, graph: FeatureGraph):
        """Aggregation (N:1) lineage returns aggregation columns."""
        class SensorReadings(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["sensor_readings"]),
                id_columns=["sensor_id", "timestamp", "reading_id"],
                fields=[FieldSpec(key=FieldKey(["temperature"]), code_version="1")],
            ),
        ):
            pass
        class HourlyStats(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["hourly_stats"]),
                id_columns=["sensor_id", "hour"],
                deps=[
                    FeatureDep(
                        feature=SensorReadings,
                        lineage=LineageRelationship.aggregation(on=["sensor_id", "hour"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["avg_temp"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(HourlyStats.spec().key)
        # input_id_columns should be the aggregation columns
        assert set(plan.input_id_columns) == {"sensor_id", "hour"}
        # These should match the downstream id_columns for aggregation
        assert set(plan.input_id_columns) == set(plan.feature.id_columns)

    def test_expansion_lineage_yields_parent_columns(self, graph: FeatureGraph):
        """Expansion (1:N) lineage returns parent columns from ExpansionRelationship.on."""
        class Video(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video"]),
                id_columns=["video_id"],
                fields=[FieldSpec(key=FieldKey(["resolution"]), code_version="1")],
            ),
        ):
            pass
        class VideoFrames(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video_frames"]),
                id_columns=["video_id", "frame_id"],
                deps=[
                    FeatureDep(
                        feature=Video,
                        lineage=LineageRelationship.expansion(on=["video_id"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["embedding"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(VideoFrames.spec().key)
        # input_id_columns should be the parent columns (expansion 'on')
        assert plan.input_id_columns == ["video_id"]

    def test_aggregation_with_multiple_upstreams(self, graph: FeatureGraph):
        """Aggregation with multiple upstreams - each dep can have its own lineage.
        With per-dep lineage, input_id_columns is the intersection of input columns
        from all dependencies after their lineage transformations.
        """
        class OriginA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin_a"]),
                id_columns=["sensor_id", "timestamp", "reading_id"],
                fields=[FieldSpec(key=FieldKey(["temp"]), code_version="1")],
            ),
        ):
            pass
        class OriginB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin_b"]),
                id_columns=["sensor_id", "hour"],  # OriginB also has hour column
                fields=[FieldSpec(key=FieldKey(["humidity"]), code_version="1")],
            ),
        ):
            pass
        class Aggregated(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["aggregated"]),
                id_columns=["sensor_id", "hour"],
                deps=[
                    FeatureDep(
                        feature=OriginA,
                        lineage=LineageRelationship.aggregation(on=["sensor_id", "hour"]),
                    ),
                    # OriginB has identity lineage (default) - its input columns are its ID columns
                    FeatureDep(feature=OriginB),
                ],
                fields=[FieldSpec(key=FieldKey(["stats"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(Aggregated.spec().key)
        # input_id_columns is intersection of:
        # - OriginA after aggregation: ["sensor_id", "hour"]
        # - OriginB with identity: ["sensor_id", "hour"]
        # Intersection: ["sensor_id", "hour"]
        assert set(plan.input_id_columns) == {"sensor_id", "hour"}

    def test_expansion_with_renamed_upstream(self, graph: FeatureGraph):
        """Expansion lineage with renamed upstream columns."""
        class Video(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video"]),
                id_columns=["video_id"],
                fields=[FieldSpec(key=FieldKey(["resolution"]), code_version="1")],
            ),
        ):
            pass
        class VideoFrames(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["video_frames"]),
                id_columns=["vid_id", "frame_id"],
                deps=[
                    FeatureDep(
                        feature=Video,
                        rename={"video_id": "vid_id"},
                        lineage=LineageRelationship.expansion(on=["vid_id"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["embedding"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(VideoFrames.spec().key)
        # input_id_columns should use the renamed column
        assert plan.input_id_columns == ["vid_id"]

    def test_identity_with_multiple_upstreams_and_renames(self, graph: FeatureGraph):
        """Identity lineage with multiple upstreams and various renames.
        With per-dep lineage, input_id_columns is the intersection of input columns
        from all dependencies. When deps have different ID columns, the intersection
        is only the common columns.
        """
        class OriginA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin_a"]),
                id_columns=["sample_uid", "col_a"],
                fields=[FieldSpec(key=FieldKey(["value_a"]), code_version="1")],
            ),
        ):
            pass
        class OriginB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin_b"]),
                id_columns=["sample_uid", "col_b"],
                fields=[FieldSpec(key=FieldKey(["value_b"]), code_version="1")],
            ),
        ):
            pass
        class Target(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["target"]),
                id_columns=["sample_uid", "renamed_a", "renamed_b"],
                deps=[
                    FeatureDep(feature=OriginA, rename={"col_a": "renamed_a"}),
                    FeatureDep(feature=OriginB, rename={"col_b": "renamed_b"}),
                ],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(Target.spec().key)
        # input_id_columns is the intersection of:
        # - OriginA (identity): ["sample_uid", "renamed_a"] (after rename)
        # - OriginB (identity): ["sample_uid", "renamed_b"] (after rename)
        # Intersection: ["sample_uid"]
        assert set(plan.input_id_columns) == {"sample_uid"}

