def determine_score_color(score: float, max_value: float = 5.0) -> str:
    """Get color based on score value.
    Args:
        score: The score value
        max_value: Maximum possible score (default 5.0)
    Returns:
        Hex color string
    """
    ratio = score / max_value
    if ratio >= 0.8:
        return PALETTE["success"]
    elif ratio >= 0.6:
        return PALETTE["warning"]
    else:
        return PALETTE["error"]

