# Helper functions for string processing
def _is_whitespace(char: str) -> bool:
    return char == " " or char == "\t" or char == "\n" or char == "\r"

def _has_character(characters: str, target: str) -> bool:
    index = 0
    length = len(characters)
    while index < length:
        if characters[index] == target:
            return True
        index += 1
    return False

def _adjust_index(position: int, size: int) -> int:
    result = position
    if result < 0:
        result += size
    if result < 0:
        result = 0
    if result > size:
        result = size
    return result

def trim_left(text: str) -> str:
    index = 0
    length = len(text)
    while index < length and _is_whitespace(text[index]):
        index += 1
    return text[index:length]

def trim_left_chars(text: str, chars: str) -> str:
    index = 0
    length = len(text)
    while index < length and _has_character(chars, text[index]):
        index += 1
    return text[index:length]

def trim_right(text: str) -> str:
    length = len(text)
    index = length - 1
    while index >= 0 and _is_whitespace(text[index]):
        index -= 1
    return text[0 : index + 1]

def trim_right_chars(text: str, chars: str) -> str:
    length = len(text)
    index = length - 1
    while index >= 0 and _has_character(chars, text[index]):
        index -= 1
    return text[0 : index + 1]

def strip_string(text: str) -> str:
    return trim_right(trim_left(text))

def strip_chars(text: str, chars: str) -> str:
    return trim_right_chars(trim_left_chars(text, chars), chars)

def starts_with(text: str, prefix: str) -> bool:
    text_len = len(text)
    prefix_len = len(prefix)
    if prefix_len > text_len:
        return False
    index = 0
    while index < prefix_len:
        if text[index] != prefix[index]:
            return False
        index += 1
    return True

def ends_with(text: str, suffix: str) -> bool:
    text_len = len(text)
    suffix_len = len(suffix)
    if suffix_len > text_len:
        return False
    index = 0
    base = text_len - suffix_len
    while index < suffix_len:
        if text[base + index] != suffix[index]:
            return False
        index += 1
    return True

def find_substring(text: str, pattern: str) -> int:
    return find_window(text, pattern, 0, len(text))

def find_window(text: str, pattern: str, start: int, end: int) -> int:
    text_len = len(text)
    pattern_len = len(pattern)
    lower = _adjust_index(start, text_len)
    upper = _adjust_index(end, text_len)
    if upper < lower:
        return -1
    if pattern_len == 0:
        return lower
    index = lower
    max_pos = upper - pattern_len
    while index <= max_pos:
        pos = 0
        match = True
        while pos < pattern_len:
            if text[index + pos] != pattern[pos]:
                match = False
                break
            pos += 1
        if match:
            return index
        index += 1
    return -1

def rfind_substring(text: str, pattern: str) -> int:
    return rfind_window(text, pattern, 0, len(text))

def rfind_window(text: str, pattern: str, start: int, end: int) -> int:
    text_len = len(text)
    pattern_len = len(pattern)
    lower = _adjust_index(start, text_len)
    upper = _adjust_index(end, text_len)
    if upper < lower:
        return -1
    if pattern_len == 0:
        return upper
    index = upper - pattern_len
    while index >= lower:
        pos = 0
        match = True
        while pos < pattern_len:
            if text[index + pos] != pattern[pos]:
                match = False
                break
            pos += 1
        if match:
            return index
        index -= 1
    return -1

def replace_substring(text: str, old: str, new: str) -> str:
    if old == "":
        return text
    result = ""
    text_len = len(text)
    old_len = len(old)
    index = 0
    while index < text_len:
        if index + old_len <= text_len and find_window(text, old, index, index + old_len) == index:
            result += new
            index += old_len
        else:
            result += text[index]
            index += 1
    return result

