import psutil
import logging
import threading
from typing import Optional

logger = logging.getLogger("api.utils.fd_guard")

class FDGuard:
    """
    Utility to monitor and protect against File Descriptor (FD) leaks.
    Logs warnings if the current process exceeds a specific threshold of open handles.
    """

    _process = psutil.Process()
    _lock = threading.Lock()
    _warning_threshold = 50   # Per-request context limit (theoretical)
    _critical_threshold = 800 # Process-wide limit (standard soft limit is often 1024)

    @classmethod
    def get_open_fd_count(cls) -> int:
        """Returns the number of open file descriptors for the current process."""
        try:
            return cls._process.num_fds()
        except (psutil.AccessDenied, AttributeError):
            # Fallback for systems where num_fds() might not be available or restricted
            return -1

    @classmethod
    def check_fd_usage(cls, context_name: str = "request"):
        """
        Checks current FD usage and logs a warning if it exceeds thresholds.
        Call this at the beginning or end of heavy I/O operations.
        """
        count = cls.get_open_fd_count()
        if count == -1:
            return

        if count > cls._critical_threshold:
            logger.critical(
                f"[FD_GUARD] CRITICAL: Process-wide File Descriptors at {count}. "
                f"Approaching system limit! Context: {context_name}"
            )
        elif count > 600:  # Adjusted global warning threshold
            logger.warning(
                f"[FD_GUARD] WARNING: High File Descriptor usage detected ({count}). "
                f"Context: {context_name}"
            )

    @classmethod
    def log_leak_warning(cls, filename: str, count: int):
        """Specifically logs a suspected leak for a file."""
        logger.warning(
            f"[FD_GUARD] SUSPECTED LEAK: File '{filename}' was not closed properly. "
            f"Current process FD count: {count}"
        )


# Global helper for middleware or decorators
def monitor_fd_usage(func):
    """Decorator to monitor FD usage around a function."""
    import functools

    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        FDGuard.check_fd_usage(f"before_{func.__name__}")
        try:
            return await func(*args, **kwargs)
        finally:
            FDGuard.check_fd_usage(f"after_{func.__name__}")

    return wrapper

# Manage request context using ContextVar
from contextvars import ContextVar
from contextlib import contextmanager

REQUEST_CONTEXT = ContextVar("request_context", default=None)

def retrieve_request_context(key, fallback=None):
    current_ctx = REQUEST_CONTEXT.get()
    return current_ctx[key] if current_ctx and key in current_ctx else fallback

def modify_request_context(**values):
    current_ctx = REQUEST_CONTEXT.get()
    if current_ctx is not None:
        current_ctx.update(values)

@contextmanager
def establish_request_context(payload):
    token = REQUEST_CONTEXT.set(payload)
    try:
        yield
    finally:
        REQUEST_CONTEXT.reset(token)

# Script to analyze pytest output files for skipped, failed, and errored tests
import argparse
import re

def extract_skipped_tests(input_file):
    skipped_info = {}
    total_skipped = 0
    with open(input_file, 'r') as f:
        for current_line in f:
            result = re.match(r'^SKIPPED \[(\d+)\] (tests/.*): (.*)$', current_line)
            if result:
                total_skipped += 1
                file_path, line_num, cause = result.groups()
                skipped_info[cause] = skipped_info.get(cause, []) + [(file_path, line_num)]

    # Sort by number of occurrences (ascending)
    for reason, occurrences in sorted(skipped_info.items(), key=lambda item: len(item[1])):
        print(f"{len(occurrences):4} skipped because: {reason}")
    print("Total skipped tests:", total_skipped)

def extract_failed_tests(input_file):
    failure_info = {}
    total_failures = 0
    with open(input_file, 'r') as f:
        for current_line in f:
            result = re.match(r'^FAILED (tests/.*) - (.*): (.*)$', current_line)
            if result:
                total_failures += 1
                _, error_type, description = result.groups()
                failure_info[description] = failure_info.get(description, []) + [error_type]

    # Sort by number of occurrences (ascending)
    for description, errors in sorted(failure_info.items(), key=lambda item: len(item[1])):
        print(f"{len(errors):4} failed because `{errors[0]}` -> {description}")
    print("Total failed tests:", total_failures)

    if total_failures > 0:
        exit(1)

def extract_error_tests(input_file):
    print(input_file)
    error_info = {}
    total_errors = 0
    with open(input_file, 'r') as f:
        for current_line in f:
            result = re.match(r'^ERROR (tests/.*) - (.*): (.*)$', current_line)
            if result:
                total_errors += 1
                _, error_detail, description = result.groups()
                error_info[description] = error_info.get(description, []) + [error_detail]

    # Sort by number of occurrences (ascending)
    for description, details in sorted(error_info.items(), key=lambda item: len(item[1])):
        print(f"{len(details):4} errored out because of `{details[0]}` -> {description}")
    print("Total errors:", total_errors)

    if total_errors > 0:
        exit(1)

def main():
    parser = argparse.ArgumentParser(description="Parse pytest output for test results")
    parser.add_argument("--file", help="Path to the output file to analyze")
    parser.add_argument("--skip", action="store_true", help="Display reasons for skipped tests")
    parser.add_argument("--fail", action="store_true", help="Display information about failed tests")
    parser.add_argument("--errors", action="store_true", help="Display information about errors")

    arguments = parser.parse_args()

    if arguments.skip:
        extract_skipped_tests(arguments.file)
    if arguments.fail:
        extract_failed_tests(arguments.file)
    if arguments.errors:
        extract_error_tests(arguments.file)

if __name__ == "__main__":
    main()

# Custom JAX module implementation based on flax.nnx
from typing import Iterable, Iterator
from flax import nnx

class CustomJaxModule(nnx.Module):
    """Base class for JAX neural network layers, built upon flax.nnx.Module."""

    def _get_class_name(self) -> str:
        return self.__class__.__name__

    def get_named_params(self,
                         prefix: str = "",
                         include_submodules=True) -> Iterator[tuple[str, nnx.Param]]:
        """Generates the named parameters of the module.

        Arguments:
            prefix: String to prepend to parameter names.
            include_submodules: If True, includes parameters from this module and all nested modules.
                If False, only returns parameters directly belonging to this module.
        Yields:
            (string, Param): Tuple with a name and corresponding parameter
        """
        for attr_name, attr_value in self.__dict__.items():
            if isinstance(attr_value, nnx.Param):
                full_name = f"{prefix}.{attr_name}" if prefix else attr_name
                yield full_name, attr_value

        if not include_submodules:
            return

        for child_name, submodule in self.get_direct_children():
            child_prefix = f"{prefix}.{child_name}" if prefix else child_name
            yield from submodule.get_named_params(prefix=child_prefix,
                                                  include_submodules=True)

    def get_direct_children(
            self) -> Iterator[tuple[str, "CustomJaxModule | CustomJaxModuleList"]]:
        """Provides an iterator over the immediate child modules.

        Yields:
            (string, Module | list): Tuple containing the attribute name and child module
        """
        for attr_name, attr_value in self.__dict__.items():
            if isinstance(attr_value, CustomJaxModule):
                yield attr_name, attr_value
            elif isinstance(attr_value, list) or isinstance(attr_value, nnx.List):
                yield attr_name, CustomJaxModuleList(attr_value)


class CustomJaxModuleList(nnx.List):
    """Container class for holding multiple CustomJaxModule instances."""

    def __init__(self, module_list: Iterable[CustomJaxModule]):
        """Constructs the CustomJaxModuleList.
        Args:
            module_list: An iterable of CustomJaxModule objects to populate the list.
        """
        super().__init__()
        for module in module_list:
            self.append(module)

    def _get_class_name(self) -> str:
        return self.__class__.__name__

    def get_named_params(self,
                         prefix: str = "",
                         include_submodules=True) -> Iterator[tuple[str, nnx.Param]]:
        """Generates the named parameters from all modules contained in the list."""
        for index, module in enumerate(self):
            module_prefix = f"{prefix}.{index}" if prefix else str(index)
            yield from module.get_named_params(prefix=module_prefix,
                                               include_submodules=include_submodules)

    def get_direct_children(
            self) -> Iterator[tuple[str, "CustomJaxModule | CustomJaxModuleList"]]:
        """Returns an iterator over modules in the list using their indices as identifiers.
        Yields:
            (string, CustomJaxModule): Tuple containing the index (as string) and the module
        """
        for index, item in enumerate(self):
            if isinstance(item, CustomJaxModule):
                yield str(index), item
            elif isinstance(item, list):
                yield str(index), CustomJaxModuleList(item)

# Renamed variables and literals for Type I clone
from graph_net.sample_pass.resumable_sample_pass_mixin import ResumableSamplePassMixin
from pathlib import Path
import os
import shutil
import tempfile
import ast
import inspect
import torch
from graph_net.imp_util import load_module
from graph_net.tensor_meta import TensorMeta
from graph_net.hash_util import get_sha256_hash

class AstGraphVariableRenamer(SamplePass, ResumableSamplePassMixin):
    def __init__(self, cfg):
        super().__init__(cfg)
        self.input_checker = self._build_input_checker(cfg)
        self.executable_checker = self._build_executable_checker(cfg)

    def _build_input_checker(self, cfg):
        mod = load_module(cfg["input_checker_filepath"])
        clss = getattr(mod, cfg["input_checker_class_name"])
        return clss(cfg["input_checker_config"])

    def _build_executable_checker(self, cfg):
        mod = load_module(cfg["executable_checker_filepath"])
        clss = getattr(mod, cfg["executable_checker_class_name"])
        return clss(cfg["executable_checker_config"])

    def declare_config(
        self,
        model_dir_prefix: str,
        output_path: str,
        device_type: str,
        resume_flag: bool = False,
        dry_run: bool = False,
        max_handled_models: int = None,
        input_checker_filepath: str = None,
        input_checker_class_name: str = None,
        input_checker_config: dict = None,
        executable_checker_filepath: str = None,
        executable_checker_class_name: str = None,
        executable_checker_config: dict = None,
    ):
        pass

    def __call__(self, rel_model_path: str):
        self.resumable_handle_sample(rel_model_path)

    def sample_handled(self, rel_model_path: str) -> bool:
        return self.naive_sample_handled(rel_model_path, search_file_name="model.py")

    def resume(self, rel_model_path: str):
        torch.cuda.empty_cache()
        final_model_path = os.path.realpath(
            os.path.join(self.config["output_path"], rel_model_path)
        )
        original_model_path = os.path.join(self.config["model_dir_prefix"], rel_model_path)
        GraphModuleClass = load_class_from_file(
            os.path.join(original_model_path, "model.py"), class_name="GraphModule"
        )
        input_names, weight_names = self._extract_input_and_weight_names(
            GraphModuleClass, original_model_path
        )
        mapping = self._generate_mapping(input_names, weight_names)
        with tempfile.TemporaryDirectory(prefix="graph_var_renamer_") as tmp_dir:
            temp_model_dir = os.path.join(tmp_dir, os.path.basename(final_model_path))
            shutil.copytree(original_model_path, temp_model_dir, dirs_exist_ok=True)
            self._modify_model_py_file(
                temp_model_dir, mapping, input_names, weight_names
            )
            self._update_metadata(temp_model_dir, "weight_meta.py", mapping)
            self._update_metadata(temp_model_dir, "input_meta.py", mapping)
            if self.config["dry_run"]:
                self._test_execution(temp_model_dir)
            shutil.copytree(temp_model_dir, final_model_path, dirs_exist_ok=True)

    def _extract_input_and_weight_names(self, graph_module, model_path):
        input_names = []
        weight_names = []
        sig = inspect.signature(graph_module.forward)
        for name, param in sig.parameters.items():
            if name == "self":
                continue
            is_not_data_input = not self.input_checker(model_path, name)
            if is_not_data_input:
                weight_names.append(name)
            else:
                input_names.append(name)
        return input_names, weight_names

    def _generate_mapping(self, input_names, weight_names):
        mapping = {}
        for idx, name in enumerate(input_names):
            mapping[name] = f"in_{idx}"
        for idx, name in enumerate(weight_names):
            mapping[name] = f"w_{idx}"
        return mapping

    def _modify_model_py_file(
        self, model_dir, mapping, input_names, weight_names
    ):
        model_file = Path(model_dir) / "model.py"
        source_code = model_file.read_text(encoding="utf-8")
        tree = ast.parse(source_code)
        node = self._find_graph_module_ast(tree)
        renamer = AstGraphRenamer(mapping, input_names, weight_names)
        renamer.visit(node)
        updated_code = ast.unparse(tree)
        model_file.write_text(updated_code, encoding="utf-8")
        hash_val = get_sha256_hash(updated_code)
        (Path(model_dir) / "graph_hash.txt").write_text(hash_val)

    def _find_graph_module_ast(self, tree):
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name == "GraphModule":
                return node
        return None

    def _update_metadata(self, model_dir, meta_filename, mapping):
        meta_file = Path(model_dir) / meta_filename
        tensor_metas = TensorMeta.unserialize_from_py_file(str(meta_file))
        for meta in tensor_metas:
            assert (
                meta.name in mapping
            ), f"[Warning] {meta.name} in {meta_filename} not found in mapping."
            if meta.original_name is None:
                meta.original_name = meta.name
            meta.name = mapping[meta.name]
        py_code = "\n\n".join([meta.serialize_to_py_str() for meta in tensor_metas])
        meta_file.write_text(py_code)

    def _test_execution(self, model_dir):
        print(f"[AstGraphVariableRenamer] Attempting to run {model_dir}")
        assert self.executable_checker(
            model_dir
        ), f"{model_dir} is not a runnable model"

def load_class_from_file(file_path: str, class_name: str):
    print(f"Loading {class_name} from {file_path}")
    module = load_module(file_path, "unnamed_graph_module")
    target_class = getattr(module, class_name, None)
    return target_class

class AstGraphRenamer(ast.NodeTransformer):
    def __init__(self, mapping, input_names, weight_names):
        self.mapping = mapping
        self.input_and_weight_names = set(input_names) | set(weight_names)
        self.counters = {"tmp": 0}
        self.in_forward_method = False

    def visit_FunctionDef(self, node):
        if node.name != "forward":
            return node
        self.in_forward_method = True
        node.args.args = self._rename_function_parameters(node.args.args)
        node.body = self._rename_function_statements(node.body)
        self.in_forward_method = False
        return node

    def _rename_function_parameters(self, args):
        new_args = []
        for arg in args:
            if arg.arg == "self":
                new_args.append(arg)
            else:
                new_args.append(self._create_renamed_argument(arg))
        return new_args

    def _create_renamed_argument(self, arg):
        if arg.arg in self.mapping:
            return ast.arg(arg=self.mapping[arg.arg], annotation=arg.annotation)
        return arg

    def _rename_function_statements(self, body):
        new_body = []
        for stmt in body:
            stmt = self._remove_clear_assignments(stmt)
            if stmt:
                stmt = self.visit(stmt)
                new_body.append(stmt)
        return new_body

    def _remove_clear_assignments(self, stmt):
        # remove statements like w_0 = None
        if self._is_assignment_to_none(stmt):
            return self._strip_assignment_to_none(stmt)
        # remove statements like del w_0
        elif isinstance(stmt, ast.Delete):
            return self._strip_delete_statement(stmt)
        return stmt

    def _is_assignment_to_none(self, stmt):
        return (
            isinstance(stmt, ast.Assign)
            and isinstance(stmt.value, ast.Constant)
            and stmt.value.value is None
        )

    def _strip_assignment_to_none(self, stmt):
        updated_targets = [t for t in stmt.targets if not self._is_input_or_weight_variable(t)]
        if not updated_targets:
            return None
        stmt.targets = updated_targets
        return stmt

    def _is_input_or_weight_variable(self, target):
        return (
            isinstance(target, ast.Name)
            and target.id in self.input_and_weight_names
        )

    def _strip_delete_statement(self, stmt):
        kept_items = []
        for target in stmt.targets:
            preserved = self._filter_delete_target(target)
            if preserved:
                kept_items.append(preserved)
        if not kept_items:
            return None
        stmt.targets = kept_items
        return stmt

    def _filter_delete_target(self, target):
        if isinstance(target, ast.Tuple):  # del (a, b)
            preserved_elts = [e for e in target.elts if not self._is_input_or_weight_variable(e)]
            return ast.Tuple(elts=preserved_elts, ctx=ast.Del()) if preserved_elts else None
        elif not self._is_input_or_weight_variable(target):  # del a
            return target
        return None

    def visit_Assign(self, node):
        if not self.in_forward_method:
            return node
        self._track_new_local_variables(node.targets)
        self.generic_visit(node)
        return node

    def _track_new_local_variables(self, targets):
        for target in targets:
            for name in self._unpack_assignment_target(target):
                self._register_if_needed(name)

    def _unpack_assignment_target(self, target):
        if isinstance(target, ast.Name):
            yield target.id
        elif isinstance(target, (ast.Tuple, ast.List)):
            for elt in target.elts:
                yield from self._unpack_assignment_target(elt)
        else:
            pass

    def _register_if_needed(self, name):
        if name not in self.mapping:
            new_name = f"tmp_{self.counters['tmp']}"
            self.counters["tmp"] += 1
            self.mapping[name] = new_name

    def visit_Name(self, node):
        if not self.in_forward_method:
            return node
        if node.id in self.mapping:
            return ast.Name(id=self.mapping[node.id], ctx=node.ctx)
        return node

