# Import password policy module with fallback handling
try:
    from security.password_policy import validate_password, get_password_strength, get_policy_requirements
    PASSWORD_POLICY_AVAILABLE = True
except ImportError:
    PASSWORD_POLICY_AVAILABLE = False

users_bp = Blueprint('users_v2', __name__)

# Legacy password validation constants (fallback when security module unavailable)
MIN_PWD_LENGTH = 8
PWD_RULES = """Password must:
- Be at least 8 characters long
- Contain at least one uppercase letter
- Contain at least one lowercase letter
- Contain at least one number
- Contain at least one special character (!@#$%^&*(),.?":{}|<>)"""

def check_password_compliance(password, username=None):
    """
    SECURITY: Verify password meets security requirements
    Returns (is_valid, error_message)
    """
    # Use enhanced security module if available
    if PASSWORD_POLICY_AVAILABLE:
        is_valid, errors = validate_password(password, username=username)
        if not is_valid:
            return False, errors[0] if errors else "Invalid password"
        return True, None

    # Fallback legacy validation
    if len(password) < MIN_PWD_LENGTH:
        return False, f"Password must be at least {MIN_PWD_LENGTH} characters"
    if not re.search(r'[A-Z]', password):
        return False, "Password must contain at least one uppercase letter"
    if not re.search(r'[a-z]', password):
        return False, "Password must contain at least one lowercase letter"
    if not re.search(r'\d', password):
        return False, "Password must contain at least one number"
    if not re.search(r'[!@#$%^&*(),.?":{}|<>]', password):
        return False, "Password must contain at least one special character"
    return True, None

