@users_bp.route('/api/v2/users/bulk/delete', methods=['POST'])
@require_auth(['delete:users'])
def bulk_remove_users():
    """Bulk deactivate users (soft delete)"""
    if g.current_user.role != 'admin':
        return error_response('Insufficient permissions', 403)
    payload = request.get_json()
    if not payload or not payload.get('ids'):
        return error_response('ids array required', 400)
    ids = payload['ids']
    outcomes = {'success': [], 'failed': []}
    for user_id in ids:
        try:
            if g.current_user.id == user_id:
                outcomes['failed'].append({'id': user_id, 'error': 'Cannot delete your own account'})
                continue
            user = db.session.get(User, user_id)
            if not user:
                outcomes['failed'].append({'id': user_id, 'error': 'Not found'})
                continue
            user.active = False
            db.session.commit()
            outcomes['success'].append(user_id)
        except Exception as e:
            db.session.rollback()
            log.error(f"Failed to delete user {user_id}: {e}")
            outcomes['failed'].append({'id': user_id, 'error': 'Deletion failed'})
    AuditService.log_action(
        action='users_bulk_deactivated',
        resource_type='user',
        resource_id=','.join(str(i) for i in outcomes['success']),
        resource_name=f'{len(outcomes["success"])} users',
        details=f'Bulk deactivated {len(outcomes["success"])} users',
        success=True
    )
    return success_response(data=outcomes, message=f'{len(outcomes["success"])} users deactivated')

