@users_bp.route('/api/v2/users/import', methods=['POST'])
@require_auth(['write:users'])
def import_user_records():
    """
    Import users from CSV file (admin only)

    POST /api/v2/users/import
    Content-Type: multipart/form-data

    CSV format:
    username,email,full_name,role,password
    john.doe,redacted@example.invalid,John Doe,operator,SecurePass123!
    """
    # SECURITY: Only admins can import users
    if g.current_user.role != 'admin':
        return error_response('Insufficient permissions', 403)

    if 'file' not in request.files:
        return error_response('No file provided', 400)

    uploaded_file = request.files['file']
    if uploaded_file.filename == '':
        return error_response('No file selected', 400)

    if not uploaded_file.filename.endswith('.csv'):
        return error_response('File must be CSV format', 400)

    try:
        # Read CSV content
        stream = io.StringIO(uploaded_file.stream.read().decode('utf-8'))
        csv_reader = csv.DictReader(stream)

        imported_count = 0
        skipped_count = 0
        issues = []

        for row in csv_reader:
            row_number = imported_count + skipped_count + 1

            # Required fields validation
            if not row.get('username') or not row.get('email') or not row.get('password'):
                skipped_count += 1
                issues.append(f"Row {row_number}: Missing required fields")
                continue

            # SECURITY: Validate password strength
            is_valid, error_msg = check_password_compliance(row['password'])
            if not is_valid:
                skipped_count += 1
                issues.append(f"Row {row_number}: {error_msg}")
                continue

            # Check for duplicate credentials
            if User.query.filter_by(username=row['username']).first():
                skipped_count += 1
                issues.append(f"Row {row_number}: Username '{row['username']}' already exists")
                continue

            if User.query.filter_by(email=row['email']).first():
                skipped_count += 1
                issues.append(f"Row {row_number}: Email '{row['email']}' already exists")
                continue

            # Create user record
            role = row.get('role', 'viewer')
            if role not in ['admin', 'operator', 'viewer']:
                role = 'viewer'

            user = User(
                username=row['username'],
                email=row['email'],
                full_name=row.get('full_name', ''),
                role=role,
                active=True
            )
            user.set_password(row['password'])

            db.session.add(user)
            imported_count += 1

        db.session.commit()

        AuditService.log_action(
            action='user_import',
            resource_type='user',
            resource_name='CSV Import',
            details=f'Imported {imported_count} users, skipped {skipped_count}',
            success=True
        )

        return success_response(
            data={
                'imported': imported_count,
                'skipped': skipped_count,
                'errors': issues
            },
            message=f'Imported {imported_count} users, skipped {skipped_count}'
        )

    except Exception as e:
        db.session.rollback()
        return error_response('Failed to import users', 500)

