            self._send_json_response(PUBLIC_KEYS)
        elif self.path == "/tokens":
            self._send_json_response(AUTH_TOKENS)
        elif self.path == "/health":
            self._send_json_response({"status": "ok"})
        else:
            self.send_error(404)

    def _send_json_response(self, payload: dict) -> None:
        """Format and send JSON response to client."""
        body = json.dumps(payload).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format: str, *args: Any) -> None:
        """Disable default logging of HTTP requests."""
        pass

