    print("Mock JWKS server running on port :8000")
    server.serve_forever()

# Enhanced AutoTree for task analysis with additional functionality
from collections.abc import Callable
from typing import Any
from haive.core.common.structures.tree import AutoTree
from haive.agents.task_analysis.base.models import ActionStep, TaskNode

class TaskTree(AutoTree[TaskNode]):
    """Specialized AutoTree implementation for analyzing task structures.
    Provides methods to identify parallel execution paths, join points, and critical paths.
    """
    def __init__(self, content: TaskNode, **kwargs):
        """Initialize the task tree with analysis capabilities.
        Args:
            content: The root task node for this tree
        """
        super().__init__(content, **kwargs)
        # Initialize internal data structures for analysis
        self._join_points: list[dict[str, Any]] = []
        self._parallel_groups: list[list[str]] = []
        self._critical_path: list[str] = []
        self._perform_structure_analysis()

    def _perform_structure_analysis(self):
        """Execute structural analysis on the completed tree."""
        self._detect_join_points()
        self._find_parallel_task_groups()
        self._determine_critical_path()

    def _detect_join_points(self):
        """Locate all tasks that serve as synchronization points."""
        for node in self.traverse_depth_first(lambda n: n):  # type: ignore
            if hasattr(node.content, "is_join_point") and node.content.is_join_point:
                dependencies = self._get_predecessor_tasks(node.content.task_id)
                if len(dependencies) > 1:
                    self._join_points.append(
                        {
                            "join_id": f"join_{node.content.task_id}",
                            "task_id": node.content.task_id,
                            "incoming_tasks": dependencies,
                            "join_strategy": node.content.join_strategy or "merge",
                        }
                    )

    def _find_parallel_task_groups(self):
        """Identify sets of tasks that can be executed concurrently."""
        dependency_graph = self._create_dependency_graph()
        all_task_ids = self._collect_all_task_identifiers()

        for i, task_id1 in enumerate(all_task_ids):
            group = [task_id1]
            for task_id2 in all_task_ids[i + 1:]:
                if not self._check_dependency_path(task_id1, task_id2, dependency_graph):
                    group.append(task_id2)
            if len(group) > 1:
                self._parallel_groups.append(group)

    def _determine_critical_path(self):
        """Compute the longest path through the task tree."""
        path = []
        current = self.content
        path.append(current.task_id)

        while current.subtasks:
            slowest_subtask = None
            max_duration = 0
            for subtask in current.subtasks:
                duration = self._estimate_subtask_time(subtask)
                if duration > max_duration:
                    max_duration = duration
                    slowest_subtask = subtask

            if slowest_subtask:
                if isinstance(slowest_subtask, TaskNode):
                    path.append(slowest_subtask.task_id)
                    current = slowest_subtask
                else:
                    path.append(slowest_subtask.step_id)
                    break
            else:
                break

        self._critical_path = path

    def _create_dependency_graph(self) -> dict[str, list[str]]:
        """Construct a mapping of task dependencies."""
        dep_map = {}
        for node in self.traverse_depth_first(lambda n: n):  # type: ignore
            if hasattr(node.content, "dependencies"):
                for dep in node.content.dependencies:
                    if dep.target_id not in dep_map:
                        dep_map[dep.target_id] = []
                    dep_map[dep.target_id].append(dep.source_id)
        return dep_map

    def _collect_all_task_identifiers(self) -> list[str]:
        """Retrieve all unique task and step identifiers."""
        ids = []
        for node in self.traverse_depth_first(lambda n: n):  # type: ignore
            if hasattr(node.content, "task_id"):
                ids.append(node.content.task_id)
            elif hasattr(node.content, "step_id"):
                ids.append(node.content.step_id)
        return ids

    def _check_dependency_path(
        self, id1: str, id2: str, dep_graph: dict[str, list[str]]
    ) -> bool:
        """Determine if there exists a dependency chain between two tasks."""
        visited = set()
        queue = [id1]

        while queue:
            current = queue.pop(0)
            if current == id2:
                return True
            visited.add(current)

            if current in dep_graph:
                for dep in dep_graph[current]:
                    if dep not in visited:
                        queue.append(dep)

        return False

    def _get_predecessor_tasks(self, task_id: str) -> list[str]:
        """Find all tasks that must complete before the specified task."""
        predecessors = []
        for node in self.traverse_depth_first(lambda n: n):  # type: ignore
            if hasattr(node.content, "dependencies"):
                for dep in node.content.dependencies:
                    if dep.target_id == task_id:
                        predecessors.append(dep.source_id)
        return predecessors

    def _estimate_subtask_time(self, subtask: TaskNode | ActionStep) -> float:
        """Estimate the time required for a subtask."""
        if isinstance(subtask, ActionStep):
            return subtask.estimated_duration_minutes
        if isinstance(subtask, TaskNode):
            return subtask.calculate_total_duration()
        return 0.0

    # ========================================================================
    # PUBLIC METHODS
    # ========================================================================

    def get_join_points(self) -> list[dict[str, Any]]:
        """Return all identified synchronization points."""
        return self._join_points

    def get_parallel_groups(self) -> list[list[str]]:
        """Return groups of tasks that can execute simultaneously."""
        return self._parallel_groups

    def get_critical_path(self) -> list[str]:
        """Return the sequence of tasks forming the critical path."""
        return self._critical_path

    def get_execution_phases(self) -> list[dict[str, Any]]:
        """Organize tasks into sequential phases where each phase contains tasks that can run in parallel."""
        phases = []
        completed = set()

        dep_graph = self._create_dependency_graph()
        all_ids = self._collect_all_task_identifiers()
        phase_counter = 1

        while len(completed) < len(all_ids):
            ready_tasks = []
            for task_id in all_ids:
                if task_id in completed:
                    continue

                deps = dep_graph.get(task_id, [])
                if all(dep in completed for dep in deps):
                    ready_tasks.append(task_id)

            if ready_tasks:
                phases.append(
                    {
                        "phase_number": phase_counter,
                        "tasks": ready_tasks,
                        "can_parallelize": len(ready_tasks) > 1,
                    }
                )
                completed.update(ready_tasks)
                phase_counter += 1
            else:
                break

        return phases

    def expand_node(
        self,
        node_id: str,
        expansion_fn: Callable[[TaskNode], list[TaskNode | ActionStep]],
    ) -> bool:
        """Expand a specific node using the provided function.
        Returns True if expansion was successful.
        """
        target_node = None
        for node in self.traverse_depth_first(lambda n: n):  # type: ignore
            if hasattr(node.content, "task_id") and node.content.task_id == node_id:
                target_node = node
                break

        if not target_node or not isinstance(target_node.content, TaskNode):
            return False

        if not target_node.content.can_expand:
            return False

        new_subtasks = expansion_fn(target_node.content)

        for subtask in new_subtasks:
            target_node.content.add_subtask(subtask)

        target_node._build_children()
        self._perform_structure_analysis()
        return True

    def get_analysis_summary(self) -> dict[str, Any]:
        """Generate a summary of the task tree analysis."""
        all_steps = self.content.get_all_steps()
        return {
            "total_tasks": len(self._collect_all_task_identifiers()),
            "total_steps": len(all_steps),
            "max_depth": self._compute_max_depth(0),
            "total_duration_minutes": self.content.calculate_total_duration(),
            "critical_path_length": len(self._critical_path),
            "join_points": len(self._join_points),
            "parallel_groups": len(self._parallel_groups),
            "can_parallelize": len(self._parallel_groups) > 0,
        }

    def _compute_max_depth(self, current_depth: int) -> int:
        """Calculate the maximum depth of the tree from this node."""
        if not self.children:
            return current_depth

        max_child_depth = max(
            child._compute_max_depth(current_depth + 1)
            for child in self.children
            if isinstance(child, TaskTree)
        )
        return max_child_depth

