class CustomSentenceTokenizer(PunktLanguageVars):
    _period_context_fmt = r"""
        \S*                          # some word material
        %(SentEndChars)s             # a potential sentence ending
        \s*                       #  <-- Modified spacing
        (?=(?P<after_tok>
            %(NonWord)s              # either other punctuation
            |
            (?P<next_tok>\S+)     #  <-- Removed \s+ here
        ))"""


class NoOpSplitter(object):
    def tokenize(self, *text):
        return text


def parquet_line_generator(file_path, text_field, batch_size=5000):
    """Generate JSON lines from parquet file rows."""
    parquet_reader = pq.ParquetFile(file_path)
    for batch in parquet_reader.iter_batches(batch_size=batch_size, columns=[text_field]):
        for value in batch.column(text_field):
            yield json.dumps({"text": value.as_py()})


class DataProcessor(object):
    def __init__(self, config):
        self.config = config

    def setup(self):
        # Initialize tokenizer and sentence splitter
        DataProcessor.tokenizer = AutoTokenizer.from_pretrained(self.config.pretrained_model_name_or_path)

        if self.config.segment_sentences:
            if not has_nltk:
                print("NLTK is required for sentence splitting but not installed.")
                sys.exit(1)

            if os.environ.get("NLTK_DATA"):
                model_path = os.path.join(os.environ.get("NLTK_DATA"), "tokenizers", "punkt", f"{self.config.language}.pickle")
                source_url = f"file:{model_path}"
            else:
                model_path = os.path.join("tokenizers", "punkt", f"{self.config.language}.pickle")
                source_url = f"nltk:{model_path}"

            segmenter = nltk.load(source_url)

            if self.config.preserve_linebreaks:
                DataProcessor.segmenter = nltk.tokenize.punkt.PunktSentenceTokenizer(
                    train_text=segmenter._params, lang_vars=CustomSentenceTokenizer()
                )
            else:
                DataProcessor.segmenter = segmenter
        else:
            DataProcessor.segmenter = NoOpSplitter()

    def process_line(self, json_string):
        data = json.loads(json_string)
        result = {}
        for field in self.config.json_fields:
            content = data[field]
            chunk_size = 200000
            token_sequences = [DataProcessor.segmenter.tokenize(content[i : i + chunk_size]) 
                               for i in range(0, len(content), chunk_size)]
            result[field] = [tokens for seq in token_sequences for tokens in seq]
        return json.dumps(result), len(json_string)

    def tokenize_line(self, json_string):
        data = json.loads(json_string)
        token_ids = {}
        lengths = {}
        for field in self.config.json_fields:
            content = data[field]
            if isinstance(content, list):
                segments = content
            else:
                segments = [content]

            all_ids = []
            segment_lengths = []
            for segment in segments:
                encoded = DataProcessor.tokenizer(segment).input_ids
                if len(encoded) > 0:
                    all_ids.extend(encoded)
                    segment_lengths.append(len(encoded))

            if len(all_ids) > 0 and self.config.add_eos_token:
                all_ids.append(DataProcessor.tokenizer.eos_token_id)
                segment_lengths[-1] += 1

            token_ids[field] = all_ids
            lengths[field] = segment_lengths

        return token_ids, lengths, len(json_string)


class DatasetBuilder(object):
    def __init__(self, config, num_workers):
        self.config = config
        self.num_workers = num_workers

    def report_progress(self, processed_count, start_time, total_bytes, filename=None):
        if processed_count % self.config.report_interval == 0:
            current_time = time.time()
            elapsed = current_time - start_time
            throughput_mbs = total_bytes / elapsed / (1024 * 1024)
            source_info = f" from {os.path.basename(filename)}" if filename else ""
            print(
                f"Processed {processed_count} items{source_info}", 
                f"({processed_count / elapsed:.2f} items/s, {throughput_mbs:.2f} MB/s).", 
                file=sys.stderr
            )

    def segment_file(self, input_output_pair):
        input_path, output_path = input_output_pair
        print("Processing:", input_path)

        with open(input_path, "r", encoding="utf-8") as infile, \
             open(output_path, "w", encoding="utf-8") as outfile:

            processor = DataProcessor(self.config)
            pool = multiprocessing.Pool(self.num_workers, initializer=processor.setup)

            segmented_docs = pool.imap(processor.process_line, infile, 64)

            start_time = time.time()
            bytes_processed = 0

            for idx, (doc_json, byte_count) in enumerate(segmented_docs, start=1):
                bytes_processed += byte_count
                outfile.write(doc_json + "\n")
                self.report_progress(idx, start_time, bytes_processed, filename=input_path)

    def build_dataset_from_json(self, input_output_pair):
        input_path, output_prefix = input_output_pair
        print("Reading:", input_path)

        startup_start = time.time()
        processor = DataProcessor(self.config)
        tokenizer = AutoTokenizer.from_pretrained(self.config.model_name)
        pool = multiprocessing.Pool(self.num_workers, initializer=processor.setup)

        encoded_docs = pool.imap(processor.tokenize_line, open(input_path, "r", encoding="utf-8"), 64)

        level = "sentence" if self.config.segment_sentences else "document"

        bin_files = {}
        idx_files = {}
        builders = {}

        for field in self.config.json_fields:
            bin_files[field] = f"{output_prefix}_{field}_{level}.bin"
            idx_files[field] = f"{output_prefix}_{field}_{level}.idx"
            builders[field] = indexed_dataset.IndexedDatasetBuilder(
                bin_files[field],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )

        startup_end = time.time()
        start_time = time.time()
        bytes_processed = 0

        print("Startup duration:", startup_end - startup_start)

        for idx, (doc_ids, seg_lens, byte_count) in enumerate(encoded_docs, start=1):
            bytes_processed += byte_count
            for field in doc_ids.keys():
                builders[field].add_document(doc_ids[field], seg_lens[field])
            self.report_progress(idx, start_time, bytes_processed, filename=input_path)

        open(input_path, "r", encoding="utf-8").close()
        for field in builders.keys():
            builders[field].finalize(idx_files[field])

    def build_dataset_from_parquet(self, input_output_pair):
        input_path, output_prefix = input_output_pair
        print("Reading parquet file:", input_path)

        startup_start = time.time()
        processor = DataProcessor(self.config)
        tokenizer = AutoTokenizer.from_pretrained(self.config.model_name)
        pool = multiprocessing.Pool(self.num_workers, initializer=processor.setup)

        row_stream = parquet_line_generator(
            input_path, self.config.text_column, batch_size=self.config.parquet_batch_size
        )
        encoded_docs = pool.imap(processor.tokenize_line, row_stream, 64)

        level = "sentence" if self.config.segment_sentences else "document"

        bin_files = {}
        idx_files = {}
        builders = {}

        for field in self.config.json_fields:
            bin_files[field] = f"{output_prefix}_{field}_{level}.bin"
            idx_files[field] = f"{output_prefix}_{field}_{level}.idx"
            builders[field] = indexed_dataset.IndexedDatasetBuilder(
                bin_files[field],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )

        startup_end = time.time()
        start_time = time.time()
        bytes_processed = 0

        print("Startup duration:", startup_end - startup_start)

        for idx, (doc_ids, seg_lens, byte_count) in enumerate(encoded_docs, start=1):
            bytes_processed += byte_count
            for field in doc_ids.keys():
                builders[field].add_document(doc_ids[field], seg_lens[field])
            self.report_progress(idx, start_time, bytes_processed, filename=input_path)

        pool.close()
        pool.join()
        for field in builders.keys():
            builders[field].finalize(idx_files[field])


def parse_arguments():
    parser = argparse.ArgumentParser(description="Process text data for LLM training")

    # Input configuration
    input_group = parser.add_argument_group("Input options")
    input_group.add_argument("--input", type=str, required=True, help="Path to input files")
    input_group.add_argument(
        "--json-fields", nargs="+", default=["text"], help="Fields to extract from JSON"
    )
    input_group.add_argument(
        "--input-format",
        type=str,
        choices=["json", "parquet", "auto"],
        default="auto",
        help="Format of input files (default: auto)",
    )
    input_group.add_argument(
        "--text-column",
        type=str,
        default="text",
        help="Column name containing text in parquet files (default: text)",
    )
    input_group.add_argument(
        "--parquet-batch-size",
        type=int,
        default=5000,
        help="Batch size for reading parquet files (default: 5000)",
    )

    # Sentence processing
    input_group.add_argument("--segment-sentences", action="store_true", help="Split documents into sentences")
    input_group.add_argument("--preserve-linebreaks", action="store_true", help="Keep line breaks between sentences")

    # Tokenization options
    token_group = parser.add_argument_group("Tokenization options")
    token_group.add_argument("--add-eos-token", action="store_true", help="Add end-of-document token")
    token_group.add_argument(
        "--language", type=str, default="english", help="Language for sentence splitting (default: english)"
    )

    # Output configuration
    output_group = parser.add_argument_group("Output options")
    output_group.add_argument("--output-prefix", type=str, required=True, help="Prefix for output files")
    output_group.add_argument(
        "--output-dir",
        type=str,
        default=None,
        help="Output directory. Overrides path in --output-prefix if provided.",
    )

    # Runtime options
    runtime_group = parser.add_argument_group("Runtime options")
    runtime_group.add_argument(
        "--num-workers",
        type=int,
        required=True,
        help="Number of worker processes to use",
    )
    runtime_group.add_argument("--report-interval", type=int, default=1000, help="Progress reporting interval")
    runtime_group.add_argument(
        "--model-name", type=str, required=True, help="Pretrained model identifier"
    )

    return parser.parse_args()


def identify_file_format(path):
    """Determine file format based on extension."""
    ext = os.path.splitext(path)[1].lower()
    if ext in [".parquet", ".pq"]:
        return "parquet"
    elif ext in [".json", ".jsonl"]:
        return "json"
    else:
        return "json"


def verify_outputs(output_paths, key, count):
    for i in range(count):
        if not os.path.exists(output_paths[i][key]):
            return False
    return True


def run_pipeline():
    config = parse_arguments()

    if config.segment_sentences:
        if has_nltk:
            nltk.download("punkt", quiet=True, download_dir=os.environ.get("NLTK_DATA"))
        else:
            raise RuntimeError("NLTK library is required for sentence segmentation but not available.")

    # Create output directory if specified
    if config.output_dir:
        os.makedirs(config.output_dir, exist_ok=True)

    # Get list of input files
    if glob.has_magic(config.input):
        input_files = glob.glob(config.input)
    else:
        input_files = [config.input]

    if not input_files:
        print(f"No files matched pattern: {config.input}")
        return

    # Determine file type
    if config.input_format == "auto":
        file_type = identify_file_format(input_files[0])
    else:
        file_type = config.input_format

    # Validate requirements
    if file_type == "parquet" and not has_parquet:
        raise RuntimeError(
            "pyarrow library is needed for parquet files but not installed. Run: pip install pyarrow"
        )

    # Disable sentence splitting for parquet
    if file_type == "parquet" and config.segment_sentences:
        print("Warning: Sentence splitting not supported for parquet files. Ignoring flag.")
        config.segment_sentences = False

    workers_per_input = max(1, config.num_workers // len(input_files))
    builder = DatasetBuilder(config, workers_per_input)

    # Prepare input/output paths
    path_mappings = []
    for idx, input_file in enumerate(input_files):
        base_name, ext = os.path.splitext(input_file)

        if config.output_dir:
            base_filename = os.path.basename(base_name)
            split_file = os.path.join(config.output_dir, base_filename + "_ss" + ext)
            out_prefix = os.path.join(config.output_dir, f"{os.path.basename(config.output_prefix)}_{idx}")
        else:
            split_file = base_name + "_ss" + ext
            out_prefix = f"{config.output_prefix}_{idx}"

        path_mappings.append({
            "original": input_file,
            "split": split_file,
            "output_prefix": out_prefix
        })

    if file_type == "json":
        # Optional sentence splitting for JSON files
        split_exists = verify_outputs(path_mappings, "split", len(path_mappings))
        if config.segment_sentences and not split_exists:
            processes = []
            for mapping in path_mappings:
                p = multiprocessing.Process(
                    target=builder.segment_file, 
                    args=((mapping["original"], mapping["split"]),)
                )
                p.start()
                processes.append(p)
            for p in processes:
                p.join()

        # Process each file
        processes = []
        source_key = "split" if config.segment_sentences else "original"
        for mapping in path_mappings:
            p = multiprocessing.Process(
                target=builder.build_dataset_from_json, 
                args=((mapping[source_key], mapping["output_prefix"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()
    else:
        # Process parquet files
        processes = []
        for mapping in path_mappings:
            p = multiprocessing.Process(
                target=builder.build_dataset_from_parquet, 
                args=((mapping["original"], mapping["output_prefix"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()


if __name__ == "__main__":
    run_pipeline()

