from bson import ObjectId
from copy import deepcopy
from ..warhammer.character import query_character

class ElementNotFoundError(Exception):
    pass

def _update_edit_flag(element, user_id, is_master_admin, shared_accounts):
    # Determine edit permission based on ownership and admin status
    if element["owner_id"] != user_id and element["owner_id"] in shared_accounts:
        element["can_edit"] = False
    else:
        element["can_edit"] = is_master_admin or (element["owner_id"] == user_id)

    # Prepare output: include id field and exclude internal fields
    element["id"] = str(element["_id"])
    return {k: v for k, v in element.items() if k not in ["_id", "owner_id"]}

def _build_owner_query(user_id, shared_accounts):
    # Construct MongoDB query for allowed owners
    if shared_accounts:
        owner_conditions = [
            {"owner_id": user_id},
            {"owner_id": "admin"},
            {"$and": [
                {"shared": True},
                {"$or": [{"owner_id": sid} for sid in shared_accounts]}
            ]}
        ]
        return {"$or": owner_conditions}
    else:
        return {"$or": [{"owner_id": user_id}, {"owner_id": "admin"}]}

def create_new_element(user_id, data, is_master_admin, collection):
    # Create new element with appropriate owner assignment
    new_element = deepcopy(data)
    new_element["owner_id"] = "admin" if is_master_admin else user_id

    insert_result = collection.insert_one(new_element)
    return {"id": str(insert_result.inserted_id)}

def retrieve_element(user_id, element_id, is_master_admin, shared_accounts, collection):
    # Find element by ID with access control
    element = collection.find_one({
        "$and": [
            {"_id": ObjectId(element_id)},
            _build_owner_query(user_id, shared_accounts)
        ]
    })

    if not element:
        raise ElementNotFoundError

    return _update_edit_flag(element, user_id, is_master_admin, shared_accounts)

def modify_element(user_id, update_data, is_master_admin, collection):
    # Extract ID and prepare update payload
    elem_id = ObjectId(update_data["id"])
    update_payload = deepcopy(update_data)
    del update_payload["id"]

    if update_payload:
        # Build filter based on admin status
        if is_master_admin:
            filter_condition = {"$and": [{"_id": elem_id}, {"owner_id": "admin"}]}
        else:
            filter_condition = {"$and": [{"_id": elem_id}, {"owner_id": user_id}]}

        result = collection.update_one(filter_condition, {"$set": update_payload})
        if result.matched_count == 0:
            raise ElementNotFoundError

    return {"id": update_data["id"]}

def remove_element(user_id, element_id, is_master_admin, collection):
    # Delete element with proper authorization check
    if is_master_admin:
        filter_condition = {"$and": [{"_id": ObjectId(element_id)}, {"owner_id": "admin"}]}
    else:
        filter_condition = {"$and": [{"_id": ObjectId(element_id)}, {"owner_id": user_id}]}

    result = collection.delete_one(filter_condition)
    if result.deleted_count == 0:
        raise ElementNotFoundError

def list_all_elements(user_id, is_master_admin, shared_accounts, collection):
    # Retrieve all accessible elements and format them
    cursor = collection.find(_build_owner_query(user_id, shared_accounts))
    formatted_elements = []

    for item in cursor:
        formatted_elements.append(_update_edit_flag(item, user_id, is_master_admin, shared_accounts))

    return formatted_elements

def fetch_resolved_character(character_id, user_id, is_master_admin, shared_accounts, char_coll, item_prop_coll):
    # Get character with resolved properties and apply permissions
    owners_filter = _build_owner_query(user_id, shared_accounts)
    character = query_character(character_id, owners_filter, char_coll, item_prop_coll)

    if not character:
        raise ElementNotFoundError

    return _update_edit_flag(character, user_id, is_master_admin, shared_accounts)

def fetch_generation_properties(collection):
    # Retrieve generation properties from database
    props_doc = collection.find_one({"name": "generation_props"})
    if not props_doc:
        raise ElementNotFoundError

    # Return only relevant fields excluding internal identifiers
    return {k: v for k, v in props_doc.items() if k not in ["_id", "name"]}

