def handle_webhook(request, topic_name):
    # Validate incoming JSON payload
    try:
        payload = json.loads(request.body.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        log.warning("Invalid JSON in webhook request")
        return HttpResponseBadRequest()

    log.info(f"Received webhook for topic '{topic_name}' with data: {payload}")

    if topic_name == "present_proof":
        current_state = payload.get("state", "")
        if current_state != "presentation_received":
            log.debug(f"Proof not yet received; current state: {current_state}")
            return HttpResponse()

        exchange_id = "- not_set -"
        try:
            requested_proof = payload["presentation"]["requested_proof"]
            exchange_id = payload["presentation_exchange_id"]
            log.info(f"Received proof: {requested_proof}")

            auth_session = AuthSession.objects.get(
                presentation_request_id=exchange_id
            )
            auth_session.satisfy_session(requested_proof)

        except (AuthSession.DoesNotExist, AuthSession.MultipleObjectsReturned):
            log.warning(
                f"No matching session found for exchange ID: [{exchange_id}]"
            )
            return HttpResponse()
        except KeyError as ke:
            log.error(f"Missing expected key in webhook payload: {ke}")
            return HttpResponseBadRequest()
        except Exception as exc:
            log.error(f"Unexpected error processing 'present_proof': {exc}")
            return HttpResponse()

    return HttpResponse()


def redirect_mapped_url(request, identifier: str):
    if request.method != "GET":
        return HttpResponseNotAllowed(["GET"])

    try:
        mapping = MappedUrl.objects.get(pk=identifier)
        return HttpResponseRedirect(mapping.url)
    except MappedUrl.DoesNotExist:
        return HttpResponseBadRequest("Invalid URL key")


def check_poll_status(request):
    if request.method != "GET":
        return HttpResponseNotAllowed(["GET"])

    pid = request.GET.get("pid")
    if not pid:
        return HttpResponseNotFound("Missing 'pid' parameter")

    try:
        session = get_object_or_404(AuthSession, presentation_request_id=pid)
    except Exception:
        return HttpResponseNotFound("Session not found")

    if not session.presentation_request_satisfied:
        return HttpResponseBadRequest("Presentation not yet satisfied")

    return HttpResponse()


def handle_callback(request):
    if request.method != "GET":
        return HttpResponseNotAllowed(["GET"])

    pid = request.GET.get("pid")
    if not pid:
        return HttpResponseNotFound("Missing 'pid' parameter")

    try:
        session = get_object_or_404(AuthSession, presentation_request_id=pid)
    except Exception:
        return HttpResponseNotFound("Session not found")

    if not session.presentation_request_satisfied:
        return HttpResponseBadRequest("Presentation not yet satisfied")

    response_type = session.request_parameters.get("response_type", "")
    if response_type == "code":
        redirect_uri = session.request_parameters.get("redirect_uri", "")
        if not redirect_uri:
            return HttpResponseBadRequest("Missing redirect_uri")

        url_parts = [redirect_uri]
        url_parts.append(f"?code={session.pk}")

        state_val = session.request_parameters.get("state")
        if state_val:
            url_parts.append(f"&state={state_val}")

        final_url = "".join(url_parts)
        return HttpResponseRedirect(final_url)

    return HttpResponseBadRequest("Unsupported response type")


@csrf_exempt
def process_token_request(request):
    if request.method != "POST":
        return HttpResponseNotAllowed(["POST"])

    try:
        body = json.loads(request.body.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        return HttpResponseBadRequest("Malformed request body")

    grant = body.get("grant_type")
    if not grant or grant != "authorization_code":
        return HttpResponseBadRequest("Invalid or missing grant_type")

    session_key = body.get("code")
    if not session_key:
        return HttpResponseBadRequest("Missing 'code' parameter")

    try:
        session_obj = get_object_or_404(AuthSession, id=session_key)
    except Exception:
        return HttpResponseNotFound("Session not found")

    if not session_obj.presentation_request_satisfied:
        return HttpResponseBadRequest("Session not satisfied")

    try:
        token_payload = create_id_token(session_obj)
        session_obj.delete()
    except Exception as err:
        log.error(f"Failed to generate token for session {session_key}: {err}")
        return HttpResponseServerError("Token generation failed")

    response_data = {
        "access_token": "REDACTED_CREDENTIAL",
        "id_token": token_payload,
        "token_type": "Bearer"
    }
    return JsonResponse(response_data)


def initiate_authorization(request):
    template_file = "qr_display.html"

    if request.method != "GET":
        return HttpResponseNotAllowed(["GET"])

    pres_req_conf_id = request.GET.get("pres_req_conf_id")
    if not pres_req_conf_id:
        return HttpResponseBadRequest("Missing 'pres_req_conf_id' parameter")

    scope_param = request.GET.get("scope", "")
    scopes = scope_param.split() if scope_param else []
    if "vc_authn" not in scopes:
        return HttpResponseBadRequest("Required scope 'vc_authn' not present")

    auth_endpoint = AuthorizeEndpoint(request)
    try:
        auth_endpoint.validate_params()
    except Exception as e:
        return HttpResponseBadRequest(
            f"Parameter validation failed: [{getattr(e, 'error', 'unknown')}: {getattr(e, 'description', '')}]"
        )

    short_url, session_id, pres_req, b64_presentation = authorization(
        pres_req_conf_id, request.GET
    )
    request.session["sessionid"] = session_id

    context = {
        "url": short_url,
        "b64_presentation": b64_presentation,
        "poll_interval": getattr(settings, "POLL_INTERVAL", 5),
        "poll_max_tries": getattr(settings, "POLL_MAX_TRIES", 10),
        "poll_url": f"{settings.SITE_URL}/vc/connect/poll?pid={pres_req}",
        "resolution_url": f"{settings.SITE_URL}/vc/connect/callback?pid={pres_req}",
    }

    return TemplateResponse(request, template_file, context)

