class WebEngine:
    """
    Class that represents a web engine, such as Google.
    """
    @typechecked
    def __init__(self, engine_name: str, base_url: str, search_template: str):
        if not engine_name or len(engine_name.strip()) == 0:
            raise TypeError("engine_name must be a non-empty string")

        if not assess_url(base_url):
            raise TypeError("The base url '{}' is not a valid url".format(base_url))

        if not assess_url(search_template.format("")):
            raise TypeError("The search template url '{}' is not a valid url".format(search_template.format("")))

        self._engine_name = engine_name
        self._base_url = base_url
        self._search_template = search_template

    @typechecked
    def fetch_html(self, query_terms: Union[str, List[Union[str, int, float, complex]]]) -> Optional[str]:
        query_params = ""

        if isinstance(query_terms, (str, int, float, complex)):
            query_terms = [str(query_terms)]

        for term in query_terms:
            if query_params:
                query_params += " "
            query_params += str(term)

        encoded_query = urllib.parse.urlencode({"q": query_params}).split('=')[1]

        # Special handling for Qwant to avoid '+' encoding
        if self.engine_name.lower() == "qwant":
            encoded_query = encoded_query.replace('+', "%20")

        full_url = self.search_template.format(encoded_query)

        request = urllib.request.Request(url=full_url, headers={'User-Agent': 'Mozilla/5.0'})
        html_content = None
        with urllib.request.urlopen(request) as response:
            html_content = response.read().decode("utf-8")

        if os.getenv("DEBUG", "").lower() == "true":
            self.__save_debug_html(html_content)

        return html_content

    @typechecked
    def extract_results_html(self, query_terms: Union[str, List[Union[str, int, float, complex]]],
                            as_string: bool = True) -> Union[List[str], List[Tag], None]:

        page_content = self.fetch_html(query_terms)
        soup = BeautifulSoup(page_content, features="html.parser")

        if self.engine_name.lower() == "google":
            result_blocks = soup.find_all("div", {"class": 'g'})
            extracted_items = []
            for block in result_blocks:
                extracted_items.append(str(block) if as_string else block)

            return extracted_items
        else:
            list_containers = soup.find_all("ol")
            if not list_containers:
                list_containers = soup.find_all("ul")

                if not list_containers:
                    raise TypeError("Not configured yet. Please try to make a search with google")

            # Find the most relevant container based on keyword matches
            if not isinstance(query_terms, list):
                query_terms = [query_terms]

            best_match_count = 0
            best_index = 0

            for idx, container in enumerate(list_containers):
                combined_keywords = ' '.join(map(str, query_terms))
                matches = re.findall(combined_keywords, str(container))
                if len(matches) > best_match_count:
                    best_match_count = len(matches)
                    best_index = idx

            selected_container = list_containers[best_index]
            raw_items = selected_container.contents

            for item in raw_items:
                if len(item) == 1:
                    nested_elements = item.find_all()
                    print("{} -> {}".format(item.name, nested_elements))
                else:
                    print("{}".format(item))

            if as_string:
                raw_items = map(str, raw_items)

            return list(raw_items)

        return None

    @typechecked
    def get_search_results(self, query_terms: Union[str, List[Union[str, int, float, complex]]]) \
            -> Optional[List[WebResult]]:

        items = self.extract_results_html(query_terms, as_string=False)
        if isinstance(query_terms, Iterable):
            query_text = ' '.join(map(str, query_terms))
        else:
            query_text = str(query_terms)

        results_list = []

        if self.engine_name.lower() == "google":
            for item in items:
                title_header = item.find("h3", {"class": 'r'})

                if title_header is None:
                    # Try alternative class names for Google results
                    title_header = item.find("h3", {"class": "p9j1ue"})

                    if title_header is None:
                        title_header = item.find("h3")

                        if title_header is None:
                            continue

                # Extract URL
                link_tag = title_header.find('a')

                if link_tag is None or not link_tag.has_attr("href"):
                    continue

                relative_url = link_tag["href"]

                # Clean up URL construction
                if not self.base_url.endswith('/'):
                    relative_url = '/' + relative_url
                if self.base_url.endswith('/') and relative_url.startswith('/'):
                    relative_url = relative_url[1:]

                full_url = self.base_url + relative_url

                # Extract title
                title_text = str(self.strip_html_tags(link_tag.text))

                # Extract date information
                snippet_span = item.find("span", {"class": 'st'})
                publication_date = ""

                if snippet_span is not None:
                    date_span = snippet_span.find("span", {"class": 'f'})

                    if date_span is not None:
                        date_nobr = date_span.find("span", {"class": "nobr"})

                        if date_nobr is not None:
                            publication_date = self.strip_html_tags(date_nobr.text)

                # Extract description
                description_text = ""
                if snippet_span is not None:
                    # Remove date elements from description
                    for date_elem in snippet_span.find_all("span", {"class": 'f'}):
                        date_elem.extract()

                    description_text = snippet_span.text

                    if publication_date == "" and " ... " in description_text:
                        parts = description_text.split(" ... ")
                        publication_date = parts[0]
                        description_text = parts[1] if len(parts) > 1 else ""

                    publication_date = self.strip_html_tags(publication_date, False)
                    description_text = self.strip_html_tags(description_text, True)

                # Extract thumbnail image
                image_tag = item.find("img")
                image_url = None

                if image_tag is not None and image_tag.has_attr("src"):
                    image_url = image_tag["src"]
                    if image_url.startswith('/'):
                        # Handle relative image URLs
                        if not self.base_url.endswith('/'):
                            image_url = '/' + image_url

                        image_url = self.base_url + image_url

                results_list.append(WebResult(
                    title=title_text,
                    url=full_url,
                    thumbnail=image_url,
                    date=publication_date,
                    description=description_text
                ))

            return results_list
        else:
            # Non-Google engines - placeholder implementation
            if not items:
                return None

            first_item = items[0]
            all_tags = first_item.find_all()
            print("Tags:")
            for i, tag in enumerate(all_tags):
                print("\t[{}] {}".format(i, tag))

            # Process each result item
            for idx, item in enumerate(items):
                item_tags = item.find_all()

                # Attempt to find titles
                candidate_titles = []  # List of (keyword_matches, match_ratio, title_text)
                anchor_tags = item.find_all('a')

                for anchor in anchor_tags:
                    candidate_title = self.strip_html_tags(anchor.get_text())
                    keyword_matches = re.findall(query_text.lower(), candidate_title.lower())
                    num_keywords = len(keyword_matches) if keyword_matches else 0
                    word_count = len(candidate_title.split()) if candidate_title else 1
                    ratio = num_keywords / word_count if word_count > 0 else 0
                    candidate_titles.append((num_keywords, ratio, candidate_title))

                # Select best title based on match ratio
                best_title = ""
                best_ratio = 0.0
                for title_info in candidate_titles:
                    if title_info[1] > best_ratio:
                        best_ratio = title_info[1]
                        best_title = title_info[2]

                # Find URLs
                potential_urls = []
                for anchor in anchor_tags:
                    if anchor.has_attr("href") and assess_url(anchor["href"]):
                        potential_urls.append(anchor["href"])

                # Deduplicate URLs
                unique_urls = list(set(potential_urls))

                # Score URLs by keyword presence
                scored_urls = []
                for url in unique_urls:
                    match_count = len(re.findall(query_text.lower(), url.lower()))
                    scored_urls.append((match_count, url))

                # Sort by relevance score and select best URL
                sorted_urls = sorted(scored_urls, key=lambda x: x[0])
                final_url = sorted_urls[-1][1] if sorted_urls else ""

                # Extract description
                description = ""

            raise TypeError("Not configured yet. Please try to make a search with google")

        return None

    # Alias method
    search = get_search_results

    @staticmethod
    @typechecked
    def strip_html_tags(text: str, preserve_line_breaks: bool = False) -> str:
        if preserve_line_breaks:
            text = re.sub(r'</?br[\s]*/?>', '\n', text)
        return re.sub(r'</?[^>]*/?>', '', text)

    @staticmethod
    def __save_debug_html(content: str):
        with open("../../out/debug.html", 'w') as file:
            file.write(content)

    # Factory methods #

    @staticmethod
    def create_google():
        return WebEngine(engine_name="Google", base_url="https://www.google.com/",
                         search_template="https://www.google.fr/search?q={}&ie=UTF-8&oe=UTF-8")

    @staticmethod
    def create_bing():
        return WebEngine(engine_name="Bing", base_url="https://www.bing.com/",
                         search_template="https://www.bing.com/search?q={}")

    @staticmethod
    def create_yahoo():
        return WebEngine(engine_name="Yahoo", base_url="https://www.yahoo.com/",
                         search_template="https://www.search.yahoo.com/search?p={}&ei=UTF-8")

    @staticmethod
    def create_duckduckgo():
        return WebEngine(engine_name="DuckDuckGo", base_url="https://duckduckgo.com/",
                         search_template="https://duckduckgo.com/?q={}")

    @staticmethod
    def create_qwant():
        return WebEngine(engine_name="Qwant", base_url="https://www.qwant.com/",
                         search_template="https://www.qwant.com/?q={}")

    # Property accessors #

    @property
    def engine_name(self) -> str:
        return self._engine_name

    @engine_name.setter
    @typechecked
    def engine_name(self, value: str):
        self._engine_name = value

    @property
    def base_url(self) -> str:
        return self._base_url

    @base_url.setter
    @typechecked
    def base_url(self, value: str):
        self._base_url = value

    @property
    def search_template(self) -> str:
        return self._search_template

    @search_template.setter
    @typechecked
    def search_template(self, value: str):
        self._search_template = value

    # Override methods #

    def __eq__(self, other: object) -> bool:
        return (isinstance(other, WebEngine) and 
                self.engine_name == other.engine_name and 
                self.base_url == other.base_url and 
                self.search_template == other.search_template)

    def __str__(self) -> str:
        return "{} ({})".format(self.engine_name, self.base_url)

    def __repr__(self) -> str:
        return "WebEngine{engine_name='{}', base_url='{}', search_template='{}'}".format(
            self.engine_name, self.base_url, self.search_template)

import re
from dunit import Unit
from dunit import Quantity
import pkgutil
import json

class UnitRegistry:
    __slots__ = ("_units", )

    def __init__(self):
        self._units = {}

    # Support dictionary-style access: reg.units["unit_string"]
    def __getitem__(self, key: str) -> Unit:
        return self._units[key]

    # Support attribute-style access: reg.units.unit_string
    def __getattr__(self, name: str) -> Unit:
        if name in self._units:
            return self._units[name]
        raise AttributeError(f"'UnitRegistry' object has no attribute '{name}'")

    def __contains__(self, name: str) -> bool:
        return name in self._units

    # Register a new unit with multiple names/symbols
    def register(self, *args, **kwargs) -> Unit:
        unit = Unit(*args, **kwargs)
        all_names = [unit, unit.name, unit.symbol] + list(unit.aliases)
        for name in all_names:
            self._units[str(name)] = unit
        return unit

    def load_json(self, data) -> None:
        for u in data:
            self.register(**u)

    # Load definitions from a JSON file
    def load_file(self, path) -> None:
        with open(path, 'r') as f:
            data = json.load(f)
            self.load_json(data)

    # Load default units from package data
    def load_defaults(self) -> None:
        try:
            data_str = pkgutil.get_data(__name__, "units.json").decode('utf-8')
            data = json.loads(data_str)
            self.load_json(data)
        except Exception as e:
            raise RuntimeError(f"Failed to load default units: {e}")

class Registry:
    __slots__ = ("_unit_registry", )

    def __init__(self, load_defaults=True):
        self._unit_registry = UnitRegistry()
        if load_defaults:
            self.units.load_defaults()

    @property
    def units(self):
        return self._unit_registry

    def parse_quantity(self, quantity_string: str) -> Quantity:
        # Convert feet and inches notation to standard unit strings
        processed = quantity_string.replace("'", "ft").replace('"', "in")

        # Extract numeric values and their associated unit names
        matches = re.findall(r'(\d+\.?\d*)\s*([a-zA-Z][a-zA-Z0-9_]*)', processed)

        if not matches:
            raise ValueError("No quantities found in input string")

        total_quantity = None

        for value_str, unit_name in matches:
            if unit_name not in self.units:
                raise ValueError(f"Unit '{unit_name}' not recognized")

            unit = self.units[unit_name]
            current = Quantity(registry=self, value=float(value_str), unit=unit)

            if total_quantity is None:
                total_quantity = current
            else:
                total_quantity += current

        return total_quantity if total_quantity is not None else Quantity(registry=self, value=0, unit=self.units['dimensionless'])

    __call__ = parse_quantity

