        def generate_balanced_tree(cls, levels=0) -> 'TreeNode':
            def spawn_subtree(parent_node, remaining_levels):
                if remaining_levels > 0:
                    new_children = cls.Batch.create_many(
                        data=[
                            {'parent_id': parent_node._id, 'root_id': parent_node.root_id},
                            {'parent_id': parent_node._id, 'root_id': parent_node.root_id}
                        ]
                    )
                    for child in new_children:
                        spawn_subtree(child, remaining_levels - 1)

            # Create root node
            root = cls(label='root', parent_id=None)
            root.root_id = root._id
            root.save()

            # Build tree iteratively using a stack to avoid recursion
            stack = [(root, levels)]
            while stack:
                current_node, depth = stack.pop()
                if depth > 0:
                    children = cls.Batch.generate(
                        defaults={
                            'parent_id': current_node._id,
                            'root_id': current_node.root_id,
                        },
                        size=2
                    ).commit()
                    for child in children:
                        stack.append((child, depth - 1))

            return root

    app.bind(TreeNode)
