import logging
from drink_partners.contrib.exceptions import (
    BadRequest,
    Conflict,
    PartnerAlreadyExists
)
from drink_partners.contrib.response import JSONResponse
from drink_partners.partners.schemas import PartnerSchema
from drink_partners.partners.views.generic import PartnerView

logger = logging.getLogger(__name__)

class PartnerCreateView(PartnerView):
    async def post(self):
        partner_data = await self._process_request_data()
        try:
            await self._persist_partner(partner_data)
        except PartnerAlreadyExists as exc:
            logger.warning(str(exc))
            raise Conflict(
                error_message=str(exc)
            )
        return JSONResponse(status=201, data=json.dumps(partner_data))

    async def _process_request_data(self):
        payload = {}
        try:
            payload = await self.request.json()
        except Exception as err:
            raise BadRequest(
                error_message=f'Invalid payload: {payload} error: {err}'
            )
        if not payload:
            raise BadRequest(
                error_message=f'Empty JSON payload: {payload}'
            )
        validation_errors = self._check_partner_fields(payload)
        if validation_errors:
            raise BadRequest(
                error_message=f'Invalid partner payload: {validation_errors}'
            )
        return payload

    def _check_partner_fields(self, partner_data):
        schema = PartnerSchema()
        return schema.validate(partner_data)

    async def _persist_partner(self, partner_info):
        await self.datasource.save(partner_info)

