    'y': {'u', 'o', 'i', 'e', 'a'},
    'z': {'y', 'o', 'i', 'e', 'a'}
}

# Memoization dictionaries with same keys/values but different initialization style
memoized_partitions = {0: 1}
memoized_sum_of_factors = {}
memoized_primeness = {1: False, 2: True}
memoized_prime_numbers = [2, 3, 5]
memoized_spiral_corners = {}
memoized_sqrt_continued_fractions_periods = {}

# Using lambda instead of partial for multiplication
multiply = lambda iterable: reduce(lambda x, y: x * y, iterable, 1)

def capacity(iterable: Iterable[Any]) -> int:
    # Count elements using enumerate instead of direct iteration
    count = 0
    for _ in enumerate(iterable):
        count += 1
    return count

def star_filter(function: Callable[..., bool],
                iterable: Iterable) -> Iterator[Any]:
    # Using list comprehension instead of generator expression
    result = []
    for element in iterable:
        if function(*element):
            result.append(element)
    yield from result

def map_tuples(elements: Iterable[Any],
               *,
               function: Callable[[Any], Any]
               ) -> Iterable[Tuple[Any, Any]]:
    # Using list instead of tuple for intermediate storage
    temp_list = []
    for number in elements:
        transformed = function(number)
        temp_list.append((transformed, number))
    yield from temp_list

def collect_mapping(keys_values: Iterable[Tuple[Hashable, Any]],
                    mapping_type: Callable[[], MutableMapping] = dict,
                    values_container: Callable[[], MutableSequence] = list
                    ) -> MutableMapping:
    dictionary = mapping_type()
    for key, value in keys_values:
        if key not in dictionary:
            dictionary[key] = values_container()
        dictionary[key].append(value)
    return dictionary

def has_n_elements(collection: Collection[Any],
                   *,
                   n: int) -> bool:
    # Using manual counting instead of len()
    count = 0
    for _ in collection:
        count += 1
    return count == n

def chunks(sequence: Sequence[Any],
           size: int,
           *,
           exact: bool = False) -> Iterable[Sequence[Any]]:
    elements_count = len(sequence)
    stop = elements_count - size + 1 if exact else elements_count
    offset = 0
    while offset < stop:
        yield sequence[offset:offset + size]
        offset += 1

def sort_permutation(permutation: Sequence[int]) -> Sequence[int]:
    # Manual min finding instead of using min with key
    min_val = permutation[0]
    min_idx = 0
    for idx, val in enumerate(permutation):
        if val < min_val:
            min_val = val
            min_idx = idx
    return rotate(permutation, min_idx)

def rotate(sequence: Sequence[Any],
           position: int) -> Sequence[Any]:
    # Using slicing differently
    length = len(sequence)
    pos = position % length if length > 0 else 0
    return sequence[pos:] + sequence[:pos]

def bisect(sequence: Sequence[Any]) -> Tuple[Sequence[Any],
                                             Sequence[Any]]:
    middle = len(sequence) // 2
    return sequence[:middle], sequence[middle:]

def find_cycle(sequence: Sequence[Any]) -> Optional[Sequence[Any]]:
    elements_count = len(sequence)
    for cycle_stop in range(1, elements_count):
        cycle = sequence[:cycle_stop]
        candidates = []
        offset = elements_count - cycle_stop
        while offset >= cycle_stop:
            candidates.append(sequence[offset: offset + cycle_stop])
            offset -= cycle_stop

        if not candidates:
            continue

        last_candidate = candidates[0]
        if (cycle[:len(last_candidate)] == last_candidate and
                all(candidate == cycle
                    for candidate in candidates)):
            return cycle
    return None

def parse_lines(lines: Iterable[str],
                *,
                sep: str = ',',
                strip_chars: str = '"') -> Iterable[str]:
    for line in lines:
        for word in line.split(sep):
            yield word.strip(strip_chars)

def max_number(digits_count: int) -> int:
    # Using loop instead of exponentiation
    result = 1
    for _ in range(digits_count):
        result *= 10
    return result - 1

def number_digits_sum(number: int) -> int:
    total = 0
    for digit in number_to_digits(number):
        total += digit
    return total

def number_digits_count(number: int) -> int:
    return sum(1 for _ in str(number))

def number_to_digits(number: int) -> Iterable[int]:
    for char in str(abs(number)):
        yield int(char)

def digits_to_number(digits: Iterable[int]) -> int:
    result_str = ""
    for digit in digits:
        result_str += str(digit)
    return int(result_str)

def phi(number: int) -> Fraction:
    return number / n_phi(number)

def n_phi(number: int) -> Fraction:
    prime_factors = []
    for factor in factors(number):
        if prime(factor):
            prime_factors.append(factor)

    numerators = []
    denominators = []
    for factor in prime_factors:
        numerators.append(factor)
        denominators.append(factor - 1)

    numerator_product = multiply(numerators)
    denominator_product = multiply(denominators)
    return Fraction(numerator_product, denominator_product)

def sum_of_factors(number: int) -> int:
    if number in memoized_sum_of_factors:
        return memoized_sum_of_factors[number]

    total = 0
    for factor in factors(number):
        total += factor

    memoized_sum_of_factors[number] = total
    return total

def partitions(number: int) -> int:
    if number in memoized_partitions:
        return memoized_partitions[number]

    total = 0
    for offset in range(number):
        total += sum_of_factors(number - offset) * partitions(offset)

    result = total // number
    memoized_partitions[number] = result
    return result

def factors(number: int,
            *,
            start: int = 1) -> Set[int]:
    result = {1}
    limit = int(sqrt(number)) + 1
    for candidate in range(start, limit):
        if number % candidate == 0:
            result.add(candidate)
            result.add(number // candidate)
    return result

proper_divisors = lambda number: factors(number, start=2)

def fibonacci_numbers(stop: Real = float('inf')) -> Iterable[int]:
    a, b = 0, 1
    while b < stop:
        yield b
        a, b = b, a + b

def prime_numbers(stop: int,
                  *,
                  reverse: bool = False) -> Iterator[int]:
    global memoized_prime_numbers
    max_memoized = memoized_prime_numbers[-1]

    if stop < max_memoized:
        result = []
        for prime_num in reversed(memoized_prime_numbers):
            if prime_num < stop:
                break
            result.append(prime_num)

        if reverse:
            yield from reversed(result)
        else:
            yield from result
        return

    # Generate primes up to stop
    initial_primes = [2, 3]
    if reverse:
        initial_primes = list(reversed([p for p in initial_primes if p < stop]))
        yield from initial_primes
    else:
        for p in initial_primes:
            if p < stop:
                yield p

    # Sieve implementation
    stop_mod_6 = stop % 6
    corrections = {0: 0, 1: -1, 2: 4, 3: 3, 4: 2, 5: 1}
    adjusted_stop = stop + corrections.get(stop_mod_6, 0)

    sieve_size = adjusted_stop // 3
    sieve = [True] * sieve_size
    sieve[0] = False

    factor_limit = int(sqrt(adjusted_stop)) // 3 + 1
    for factor in range(factor_limit):
        if not sieve[factor]:
            continue

        k = 3 * factor + 1 | 1
        k_squared = k * k
        k_double = 2 * k

        # Mark multiples
        start_idx = k_squared // 3
        step = k_double
        for i in range(start_idx, sieve_size, step):
            sieve[i] = False

        k_diff = k_squared + 4 * k - k_double * (factor & 1)
        start_idx2 = k_diff // 3
        for i in range(start_idx2, sieve_size, step):
            sieve[i] = False

    prime_numbers_list = []
    for index in range(1, adjusted_stop // 3 - (stop_mod_6 > 1)):
        if sieve[index]:
            candidate = 3 * index + 1 | 1
            prime_numbers_list.append(candidate)
            memoized_primeness[candidate] = True
            if not reverse:
                yield candidate

    if reverse:
        for candidate in reversed(prime_numbers_list):
            yield candidate

    memoized_prime_numbers = sorted(set(memoized_prime_numbers + prime_numbers_list))

def primes_sieve(stop: int) -> List[bool]:
    sieve = [True] * (stop // 3)
    sieve[0] = False
    factor_stop = int(sqrt(stop)) // 3 + 1

    for factor in range(factor_stop):
        if not sieve[factor]:
            continue

        k = 3 * factor + 1 | 1
        k_squared = k ** 2
        k_doubled = 2 * k

        # First sequence
        start1 = k_squared // 3
        step = k_doubled
        count1 = ((stop // 6 - 1) - k_squared // 6) // k + 1
        for i in range(count1):
            idx = start1 + i * step
            if idx < len(sieve):
                sieve[idx] = False

        # Second sequence
        k_diff = k_squared + 4 * k - k_doubled * (factor & 1)
        start2 = k_diff // 3
        count2 = ((stop // 6 - 1) - k_diff // 6) // k + 1
        for i in range(count2):
            idx = start2 + i * step
            if idx < len(sieve):
                sieve[idx] = False

    return sieve

def reduced_proper_fractions(*,
                             start: Fraction = Fraction(0, 1),
                             stop: Fraction,
                             max_denominator: int,
                             only_first: bool = False) -> Iterable[Fraction]:
    start_num, start_den = start.numerator, start.denominator
    stop_num, stop_den = stop.numerator, stop.denominator
    stop_float = float(stop)

    for denominator in range(max_denominator, 1, -1):
        for numerator in range(int(stop_float * denominator), 0, -1):
            if start_num * denominator >= start_den * numerator:
                continue
            if stop_den * numerator >= stop_num * denominator:
                continue
            if gcd(numerator, denominator) != 1:
                continue

            yield Fraction(numerator, denominator)
            if only_first:
                break

def prime(number: int) -> bool:
    if number in memoized_primeness:
        return memoized_primeness[number]

    if number % 2 == 0:
        memoized_primeness[number] = False
        return False

    limit = int(sqrt(number)) + 1
    for candidate in prime_numbers(limit):
        if number % candidate == 0:
            memoized_primeness[number] = False
            return False

    memoized_primeness[number] = True
    return True

def odd(number: int) -> int:
    return number & 1

def relatively_prime(number: int, other_number: int) -> bool:
    return gcd(number, other_number) == 1

def is_palindrome(string: str) -> bool:
    left = 0
    right = len(string) - 1
    while left < right:
        if string[left] != string[right]:
            return False
        left += 1
        right -= 1
    return True

def integer_right_triangles(max_perimeter: int
                            ) -> Iterable[Tuple[int, int, int]]:
    def is_valid(triplet):
        return sum(triplet) <= max_perimeter

    for triplet in pythagorean_triplets(max_perimeter):
        if is_valid(triplet):
            yield triplet

def pythagorean_triplets(stop: int) -> Iterable[int]:
    seen = set()
    for triplet in pythagorean_triplets_candidates(stop):
        sorted_triplet = tuple(sorted(triplet))
        if sorted_triplet not in seen:
            seen.add(sorted_triplet)
            yield sorted_triplet

def is_pythagorean_triplet(triplet: Tuple[int, int, int]) -> bool:
    a, b, c = sorted(triplet)
    return a * a + b * b == c * c

def pythagorean_triplets_candidates(stop: int
                                    ) -> Iterable[Tuple[int, int, int]]:
    max_k = stop // (1 + 4)  # n=1, m=2 gives 1+4=5

    for k in range(1, max_k + 1):
        numbers = list(range(1, int(sqrt(stop // k)) + 1))
        for perm in permutations(numbers, r=2):
            n, m = sorted(perm)
            base_triplet = [
                m * m - n * n,
                2 * m * n,
                m * m + n * n
            ]
            scaled = tuple(k * coord for coord in base_triplet)
            yield scaled

def polygonal(number: int,
              *,
              dimension: int) -> bool:
    a = dimension - 2
    minus_b = dimension - 4
    minus_c = 2 * number

    discriminant = minus_b * minus_b + 4 * a * minus_c
    if discriminant < 0:
        return False

    sqrt_disc = int(sqrt(discriminant))
    if sqrt_disc * sqrt_disc != discriminant:
        return False

    numerator = minus_b + sqrt_disc
    return numerator % (2 * a) == 0

triangular = partial(polygonal, dimension=3)
pentagonal = partial(polygonal, dimension=5)

def is_perfect_square(number: int) -> bool:
    if number < 0:
        return False
    root = int(sqrt(number))
    return root * root == number

def int_sqrt(number: int) -> int:
    return int(sqrt(number))

def binomial_coefficient(n: int, k: int) -> int:
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use smaller of k and n-k
    k = min(k, n - k)

    numerator = 1
    for i in range(n - k + 1, n + 1):
        numerator *= i

    denominator = 1
    for i in range(1, k + 1):
        denominator *= i

    return numerator // denominator

def spiral_corners(dimension: int,
                   *,
                   start: int = SPIRAL_START
                   ) -> Iterable[Tuple]:
    dim = 3
    while dim <= dimension + 1:
        try:
            yield memoized_spiral_corners[dim]
        except KeyError:
            decrement = dim - 1
            right_top = dim * dim + start - 1
            left_top = right_top - decrement
            left_bottom = left_top - decrement
            right_bottom = left_bottom - decrement
            corners = (right_bottom, left_bottom, left_top, right_top)
            memoized_spiral_corners[dim] = corners
            yield corners
        dim += 2

def english_text(text: str,
                 *,
                 acceptable_non_english_words_ratio: float = 0.1
                 ) -> bool:
    words_list = list(words(text))
    if not words_list:
        return False

    non_english_count = 0
    for word in map(str.lower, words_list):
        if len(word) < 2:
            continue

        first_char = word[0]
        second_char = word[1]
        if first_char in FIRST_LETTERS_FOLLOWERS:
            if second_char not in FIRST_LETTERS_FOLLOWERS[first_char]:
                non_english_count += 1

    ratio = non_english_count / len(words_list)
    return ratio <= acceptable_non_english_words_ratio

def words(text: str) -> Iterable[str]:
    for match in WORDS_RE.finditer(text):
        yield match.group(0)

def sqrt_continued_fraction(number: int) -> Iterable[int]:
    memoized_b_coefficients = {0: Decimal(number).sqrt()}

    def b_coefficient(index: int) -> Decimal:
        if index in memoized_b_coefficients:
            return memoized_b_coefficients[index]

        prev = b_coefficient(index - 1)
        a_prev = int(prev)
        numerator = prev + a_prev
        denominator = numerator * (prev - a_prev)
        coefficient = numerator / denominator
        memoized_b_coefficients[index] = coefficient
        return coefficient

    idx = 0
    while True:
        yield int(b_coefficient(idx))
        idx += 1

def sqrt_continued_fraction_period(number: int,
                                   *,
                                   members_count_start: int = 250,
                                   members_count_step: int = 50,
                                   precision_start: int = 500,
                                   precision_step: int = 250,
                                   precision_stop: int = 2_501
                                   ) -> Sequence[int]:
    if number in memoized_sqrt_continued_fractions_periods:
        return memoized_sqrt_continued_fractions_periods[number]

    for members_count in count(members_count_start, members_count_step):
        for precision in range(precision_start, precision_stop, precision_step):
            context = Context(prec=precision)
            setcontext(context)

            sequence = list(islice(sqrt_continued_fraction(number), 1, members_count))
            cycle = find_cycle(sequence)
            if cycle is not None:
                memoized_sqrt_continued_fractions_periods[number] = cycle
                return cycle

def sqrt_convergent(number: int,
                    index: int,
                    *,
                    members_count_start: int = 250,
                    members_count_step: int = 50,
                    precision_start: int = 500,
                    precision_step: int = 250,
                    precision_stop: int = 2_501
                    ):
    period = sqrt_continued_fraction_period(
        number,
        members_count_start=members_count_start,
        members_count_step=members_count_step,
        precision_start=precision_start,
        precision_step=precision_step,
        precision_stop=precision_stop)

    first_coefficient = Fraction(int(sqrt(number)))
    coefficients = list(islice(chain.from_iterable(repeat(period)), index))

    if not coefficients:
        return first_coefficient

    increment = coefficients.pop()
    for coefficient in reversed(coefficients):
        increment = coefficient + Fraction(1, increment)

    return first_coefficient + Fraction(1, increment)

def aggregated_path_sum(*,
                        rows: Iterable[Iterable[int]],
                        successors_count: int,
                        function: Callable[[Iterable[int]], int]) -> int:
    rows_reversed = list(rows)
    rows_reversed.reverse()

    next_row = list(rows_reversed[0])

    for row in rows_reversed[1:]:
        new_row = []
        for index, number in enumerate(row):
            subsequence = next_row[index:index + successors_count]
            new_row.append(number + function(subsequence))
        next_row = new_row

    return next_row[0]

maximum_path_sum = partial(aggregated_path_sum, function=max)
minimum_path_sum = partial(aggregated_path_sum, function=min)

import json
import os
from typing import Any, Dict, Optional, NoReturn
from dbt import flags, tracking
from dbt.clients.jinja import undefined_error, get_rendered
from dbt.exceptions import raise_compiler_error, MacroReturn
from dbt.logger import GLOBAL_LOGGER as logger
from dbt.utils import merge
from dbt.version import __version__ as dbt_version
import yaml

# Replaced module imports with equivalent logic for context exposure
import pytz
import datetime


def _extract_pytz_exports() -> Dict[str, Any]:
    """Extracts public members from pytz module."""
    exported_names = getattr(pytz, '__all__', [])
    return {name: getattr(pytz, name) for name in exported_names}


def _extract_datetime_exports() -> Dict[str, Any]:
    """Extracts specific datetime classes for use in templates."""
    target_classes = ['date', 'datetime', 'time', 'timedelta', 'tzinfo']
    return {cls_name: getattr(datetime, cls_name) for cls_name in target_classes}


def _build_module_context() -> Dict[str, Dict[str, Any]]:
    """Constructs a dictionary mapping module names to their exposed objects."""
    return {
        'pytz': _extract_pytz_exports(),
        'datetime': _extract_datetime_exports(),
    }


class ContextAttribute:
    """Wrapper class to mark attributes intended for context injection."""
    def __init__(self, obj, alias=None):
        self.alias = alias
        self.obj = obj

    def resolve_key(self, default_key):
        return self.alias if self.alias is not None else default_key


def context_attribute(name_or_obj):
    """Decorator factory to define context attributes or properties."""
    if isinstance(name_or_obj, str):
        return lambda obj: ContextAttribute(obj, alias=name_or_obj)
    return ContextAttribute(name_or_obj)


class ContextMeta(type):
    """Metaclass to collect and register context members across class hierarchy."""
    def __new__(mcs, cls_name, bases, namespace):
        inherited_members = {}
        inherited_attrs_map = {}
        updated_namespace = {}

        # Inherit context definitions from base classes
        for base in bases:
            inherited_members.update(getattr(base, '_context_members_', {}))
            inherited_attrs_map.update(getattr(base, '_context_attrs_', {}))

        # Process current class members
        for attr_name, attr_value in namespace.items():
            if isinstance(attr_value, ContextAttribute):
                key = attr_value.resolve_key(attr_name)
                inherited_members[key] = attr_value.obj
                inherited_attrs_map[key] = attr_name
                attr_value = attr_value.obj
            updated_namespace[attr_name] = attr_value

        updated_namespace['_context_members_'] = inherited_members
        updated_namespace['_context_attrs_'] = inherited_attrs_map
        return super().__new__(mcs, cls_name, bases, updated_namespace)


class VariableResolver:
    """Handles variable lookup and rendering within dbt models."""
    MISSING_VAR_MSG = "Required var '{}' not found in config:\nVars supplied to {} = {}"

    _UNSPECIFIED = object()

    def __init__(self, model_obj, ctx_dict, override_vars):
        self.model = model_obj
        self.context = ctx_dict
        self.overrides = override_vars

        if model_obj is None:
            self.model_label = '<Configuration>'
            local_data = {}
        else:
            self.model_label = model_obj.name
            local_data = model_obj.local_vars()

        self.local_data = merge(local_data, override_vars)

    def format_dict(self, data):
        return json.dumps(data, sort_keys=True, indent=4)

    def report_missing_var(self, var_name):
        formatted = self.format_dict(self.local_data)
        msg = self.MISSING_VAR_MSG.format(var_name, self.model_label, formatted)
        raise_compiler_error(msg, self.model)

    def validate_var(self, var_name, fallback):
        if var_name not in self.local_data and fallback is self._UNSPECIFIED:
            self.report_missing_var(var_name)

    def evaluate_var(self, var_name):
        raw_val = self.local_data[var_name]
        if not isinstance(raw_val, str):
            return raw_val
        return get_rendered(raw_val, self.context)

    def __call__(self, var_name, fallback=_UNSPECIFIED):
        if var_name in self.local_data:
            return self.evaluate_var(var_name)
        elif fallback is not self._UNSPECIFIED:
            return fallback
        else:
            self.report_missing_var(var_name)


class RootContext(metaclass=ContextMeta):
    """Base context class providing shared utilities and environment integration."""

    def __init__(self, cli_overrides):
        self._internal_ctx = {}
        self.cli_overrides = cli_overrides

    def build_exposed_api(self):
        """Builds the set of callable attributes available in template context."""
        result = {}
        for key, func in self._context_members_.items():
            if hasattr(func, '__get__'):
                func = func.__get__(self)
            result[key] = func
        return result

    def finalize_context(self):
        """Populates and returns the final context dictionary."""
        self._internal_ctx['context'] = self._internal_ctx
        exposed = self.build_exposed_api()
        self._internal_ctx['builtins'] = exposed
        self._internal_ctx.update(exposed)
        return self._internal_ctx

    @context_attribute('dbt_version')
    def version_info(self) -> str:
        return dbt_version

    @context_attribute('var')
    def variable_accessor(self) -> VariableResolver:
        return VariableResolver(None, self._internal_ctx, self.cli_overrides)

    @context_attribute('env_var')
    @staticmethod
    def environment_variable(name: str, fallback: Optional[str] = None) -> str:
        if name in os.environ:
            return os.environ[name]
        elif fallback is not None:
            return fallback
        else:
            undefined_error(f"Environment variable '{name}' must be set")

    if os.environ.get('DBT_MACRO_DEBUGGING'):
        @context_attribute('debug')
        @staticmethod
        def enter_debugger():
            import sys
            import ipdb  # type: ignore
            stack_frame = sys._getframe(3)
            ipdb.set_trace(stack_frame)
            return ''

    @context_attribute('return')
    @staticmethod
    def emit_macro_result(value: Any) -> NoReturn:
        raise MacroReturn(value)

    @context_attribute('fromjson')
    @staticmethod
    def parse_json_string(text: str, fallback: Any = None) -> Any:
        try:
            return json.loads(text)
        except (json.JSONDecodeError, TypeError):
            return fallback

    @context_attribute('tojson')
    @staticmethod
    def serialize_to_json(obj: Any, fallback: Any = None, sort_keys: bool = False) -> Any:
        try:
            return json.dumps(obj, sort_keys=sort_keys)
        except (TypeError, ValueError):
            return fallback

    @context_attribute('fromyaml')
    @staticmethod
    def parse_yaml_string(text: str, fallback: Any = None) -> Any:
        try:
            return yaml.safe_load(text)
        except (AttributeError, ValueError, yaml.YAMLError):
            return fallback

    @context_attribute('toyaml')
    @staticmethod
    def serialize_to_yaml(obj: Any, fallback: Optional[str] = None, sort_keys: bool = False) -> Optional[str]:
        try:
            return yaml.safe_dump(data=obj, sort_keys=sort_keys)
        except (ValueError, yaml.YAMLError):
            return fallback

    @context_attribute('log')
    @staticmethod
    def log_message(message: str, verbose: bool = False) -> str:
        if verbose:
            logger.info(message)
        else:
            logger.debug(message)
        return ''

    @context_attribute('run_started_at')
