        if tracking.active_user is not None:
            return tracking.active_user.run_started_at
        return None

    @context_attribute('invocation_id')
    def invocation_identifier(self) -> Optional[str]:
        if tracking.active_user is not None:
            return tracking.active_user.invocation_id
        return None

    @context_attribute('modules')
    def external_modules(self) -> Dict[str, Any]:
        return _build_module_context()

    @context_attribute('flags')
    def flag_settings(self) -> Any:
        return flags


def create_base_context(cli_vars: Dict[str, Any]) -> Dict[str, Any]:
    """Instantiates and returns the fully populated base context."""
    instance = RootContext(cli_vars)
    return instance.finalize_context()

