from ..jamming import BaseJamDatabase, Jam, JamId, JamItem, JamKind, JamParchment, JamFileDatabase
from . import helpers as utils
from .exceptions import EmptyJam
from ..file_locking import FileLock


class Repository:
    def __init__(self, storage_backend: BaseJamDatabase) -> None:
        self.storage_backend = storage_backend

    @classmethod
    def create_volatile(cls) -> Repository:
        return cls(JamFileDatabase.create_ethereal())

    def fetch_jam_category(self, candidate: Union[RepositoryItem, Type[RepositoryItem], str]) -> JamKind:
        resolved = type(candidate) if isinstance(candidate, RepositoryItem) else candidate
        return self.storage_backend[resolved]

    def fetch_jam_entry(self, item: RepositoryItem) -> JamKind:
        assert item.has_identity_and_position
        return self.fetch_jam_category(item)[item.identity][item.position]

    def resolve_item_class(self, candidate: Union[RepositoryItem, Type[RepositoryItem], str]) -> Type[RepositoryItem]:
        if isinstance(candidate, str):
            category_name = candidate
            return utils.alias_to_class(category_name)
        else:
            if isinstance(candidate, RepositoryItem):
                return type(candidate)
            elif issubclass(candidate, RepositoryItem):
                return candidate

    def retrieve(self, item_type_or_label: Union[Type[RepositoryItem], str],
                 identity: Union[JamId, str],
                 position: int) -> RepositoryItem:
        category = self.fetch_jam_category(item_type_or_label)
        item_class = self.resolve_item_class(item_type_or_label)
        entry = category[identity][position]
        data = entry.read()
        if data is None:
            raise EmptyJam
        return item_class._RepositoryItem__deserialize(data,
                                                       identity=identity,
                                                       position=position,
                                                       repository=self)

    def store(self, item: RepositoryItem) -> None:
        if not item.has_identity_and_position:
            item.identity = JamId.create(block_size=item.default_block_size)
            item.position = 0
        entry = self.fetch_jam_entry(item)
        payload = item._RepositoryItem__serialize()
        entry.write(payload)

    def latest_items(self, item_type: Type[RepositoryItem]) -> Iterable[RepositoryItem]:
        return item_type.recent_entries(self)

    def _reduce_state(self) -> tuple:
        return (type(self), self.storage_backend)

    def __eq__(self, other: Any) -> bool:
        return (type(other) == type(self)) and (self._reduce_state() == other._reduce_state())

    def __hash__(self) -> int:
        return hash(self._reduce_state())

    def __repr__(self) -> str:
        return f'{type(self).__name__}({self.storage_backend})'


class CategoryMeta(abc.ABCMeta):
    def __new__(mcls, name, bases, namespace) -> Type[RepositoryItem]:
        cls = abc.ABCMeta.__new__(mcls, name, bases, namespace)
        if len(cls.mro()) >= 3:  # skip base class
            cls._RepositoryItem__attributes = mcls.__collect_attributes(cls)
        return cls

    def __collect_attributes(cls) -> dict:
        attrs = {}
        seen_names = set()
        for base in cls.mro():
            for attr_name, attr_val in vars(base).items():
                if attr_name in seen_names:
                    continue
                seen_names.add(attr_name)
                if attr_name.startswith('__'):
                    continue
                if isinstance(attr_val, AttributeBase):
                    assert attr_name not in attrs
                    attrs[attr_name] = attr_val
        return attrs

    def recent_entries(cls, repository: Repository) -> Iterable[RepositoryItem]:
        parchments_sorted = sorted(
            repository.fetch_jam_category(cls),
            key=lambda p: p._get_path().stat().st_mtime,
            reverse=True,
        )
        for parchment in parchments_sorted:
            for idx in reversed(range(len(parchment))):
                yield repository.retrieve(cls, parchment.jam_id, idx)

    def most_recent(cls, repository: Repository) -> RepositoryItem:
        try:
            return next(cls.recent_entries(repository))
        except StopIteration:
            raise IndexError

    def find_by_partial_name(cls, repository: Repository, partial: str) -> RepositoryItem:
        for item in cls.recent_entries(repository):
            if partial in str(item.identity):
                return item
        raise LookupError


class RepositoryItem(metaclass=CategoryMeta):
    default_block_size: int = 1_000
    identity: Optional[JamId] = None
    position: Optional[int] = None

    def __init__(self, *, repository: Repository,
                 identity: Optional[Union[JamId, str]] = None,
                 position: Optional[int] = None,
                 **kwargs):
        assert (identity, position).count(None) in {0, 2}
        self.__value_store = {}
        self.identity = None if identity is None else JamId.cast(identity)
        self.position = position
        self.repository = repository
        assert set(kwargs) <= set(self._RepositoryItem__attributes)
        for attr_name, attr_spec in self.__attributes.items():
            try:
                val = kwargs[attr_name]
            except KeyError:
                val = attr_spec.provide_default(repository)
            setattr(self, attr_name, val)

    @property
    def has_identity_and_position(self):
        id_exists = (self.identity is not None)
        pos_exists = (self.position is not None)
        assert id_exists == pos_exists
        return id_exists

    @classmethod
    def __deserialize(cls, data: Jam, *,
                      identity: JamId,
                      position: int,
                      repository: Repository) -> RepositoryItem:
        attributes = cls._RepositoryItem__attributes
        instance = cls.__new__(cls)
        cache = {(identity, position): instance}

        # Deserialize fields from jam data
        for full_key, value in data.items():
            field_name, type_tag = full_key.split('.')
            attr = attributes[field_name]
            assert type_tag == attr.type_tag
            instance.__value_store[field_name] = attr.deserialize(value,
                                                                  repository=repository,
                                                                  cache=cache)

        cls.__init__(instance,
                     **{k: v for k, v in instance.__value_store.items()},
                     identity=identity,
                     position=position,
                     repository=repository)
        return instance

    def __serialize(self) -> Jam:
        attrs = self._RepositoryItem__attributes
        return {
            f'{name}.{spec.type_tag}': spec.serialize(getattr(self, name, None), self.repository)
            for name, spec in attrs.items()
        }

    @classmethod
    def load(cls, repository: Repository, identity: Union[JamId, str],
             position: int) -> RepositoryItem:
        return repository.retrieve(cls, identity=identity, position=position)

    def refresh(self) -> RepositoryItem:
        return type(self).load(self.repository, self.identity, self.position)

    def commit(self, *, persist_parchments: bool = True) -> RepositoryItem:
        from .fields import ParchmentAttribute
        self.repository.store(self)
        if persist_parchments:
            for name, spec in self._RepositoryItem__attributes.items():
                if isinstance(spec, ParchmentAttribute):
                    getattr(self, name).commit()

    def _reduce_state(self) -> tuple:
        return (type(self), self.repository, self.identity, self.position)

    def __eq__(self, other: Any) -> bool:
        return (
            (type(other) == type(self)) and
            self.has_identity_and_position and
            (self._reduce_state() == other._reduce_state())
        )

    def __hash__(self) -> int:
        return hash(self._reduce_state())

    def __repr__(self) -> str:
        parts = ', '.join(
            f'{k}={v}' for k, v in self.__value_store.items()
        )
        return f'<{type(self).__name__}: {parts}>'

    def to_savvy_format(self) -> tuple:
        return (str(self.identity), self.position)

    @property
    @functools.cache
    def lock_file(self):
        entry = self.repository.fetch_jam_entry(self)
        lock_path = entry.parchment._get_lock_path()
        return FileLock(lock_path)


class Reference:
    def __init__(self, repository: Repository, item_type: Type[RepositoryItem],
                 identity: JamId, position: int) -> None:
        self.repository = repository
        self.item_type = item_type
        self.item_type_alias = utils.class_to_alias(item_type)
        self.category_alias = self.item_type_alias
        assert isinstance(identity, JamId)
        self.identity = identity
        assert isinstance(position, int)
        self.position = position

    @property
    def entry(self) -> JamItem:
        return self.repository.storage_backend[self.category_alias][self.identity][self.position]

    def access(self) -> RepositoryItem:
        return self.repository.retrieve(self.category_alias, self.identity, self.position)

    @staticmethod
    def from_instance_or_ref(instance_or_ref: Optional[Union[RepositoryItem, Reference]]) -> Optional[Reference]:
        if instance_or_ref is None:
            return None
        elif isinstance(instance_or_ref, RepositoryItem):
            inst = instance_or_ref
            assert inst.has_identity_and_position
            return Reference(inst.repository, type(inst), inst.identity, inst.position)
        else:
            assert isinstance(instance_or_ref, Reference)
            return instance_or_ref

    def _reduce_state(self) -> tuple:
        return (type(self), self.repository, self.item_type, self.identity, self.position)

    @property
    @functools.cache
    def lock_file(self):
        category = self.repository.fetch_jam_category(self.item_type)
        entry = category[self.identity][self.position]
        lock_path = entry.parchment._get_lock_path()
        return FileLock(lock_path)

    @contextlib.contextmanager
    def acquire_and_use(self, *, commit: bool = False) -> RepositoryItem:
        with self.lock_file:
            yield (item := self.access())
            if commit:
                item.commit()

    @contextlib.contextmanager
    def acquire_or_create(self, *, commit: bool = False) -> RepositoryItem:
        with self.lock_file:
            try:
                item = self.access()
            except EmptyJam:
                item = self.item_type(repository=self.repository,
                                      identity=self.identity,
                                      position=self.position)
            yield item
            if commit:
                item.commit()

    def __repr__(self) -> str:
        return f'<{type(self).__name__}: {self.item_type_alias}>'

    def __eq__(self, other: Any) -> bool:
        return (type(other) == type(self)) and (self._reduce_state() == other._reduce_state())

    def __hash__(self) -> int:
        return hash(self._reduce_state())


