# Reimplementation of type validation for Falcon resource methods
import functools
import inspect
import re
from typing import (Any, Callable, Dict, List, Optional, Set, Tuple, Union,
                    get_type_hints)

try:
    from typing_extensions import Protocol

    class _RequestResponseHandler(Protocol):
        def __call__(self, req: object, resp: object, **kw: Any) -> None: ...

    class _RequestResponseWithResult(Protocol):
        def __call__(self, req: object, resp: object, **kw: Any) -> Any: ...

except ImportError:
    _RequestResponseHandler = Callable  # type: ignore
    _RequestResponseWithResult = Callable  # type: ignore

# External schema providers
_schema_providers = []
try:
    from marshmallow import Schema as _MarshmallowSchema
    _schema_providers.append(_MarshmallowSchema)
except ImportError:
    pass

try:
    from pydantic import BaseModel as _PydanticModel
    _schema_providers.append(_PydanticModel)
except ImportError:
    pass

# URI template parameter extractor
_URI_PARAM_REGEX = re.compile(
    r'\{(?P<name>[^}:]+)(?::(?P<converter>[^}\(]*)(?:\((?P<args>[^}]*)\))?)?\}'
)

# HTTP method handlers naming convention
_HTTP_METHODS = ['get', 'post', 'put', 'patch', 'delete', 'head', 'options']
_RESOURCE_METHOD_NAMES = [f'on_{m}' for m in _HTTP_METHODS]

class _ValidationException(Exception):
    """Custom exception for validation errors."""
    pass

def _check_type_constraints(target_type: Any) -> None:
    """Verify that the given type is acceptable for request/response bodies."""
    if not _schema_providers:
        raise _ValidationException('No schema provider available. Install either Marshmallow or Pydantic')

    def _is_valid_type(t: Any) -> bool:
        """Determine if a type can be used in body context."""
        try:
            if getattr(t, '__origin__', None) is Union:
                return all(_is_valid_type(arg) for arg in getattr(t, '__args__', []))

            # Check against supported schema types
            for provider in _schema_providers:
                try:
                    if issubclass(t, provider):
                        return True
                except TypeError:
                    pass

            return t is type(None)
        except TypeError:
            return False

    if target_type and not _is_valid_type(target_type):
        raise _ValidationException(f'Unsupported type {target_type} in resource method signature')

def _analyze_method_signature(func: _RequestResponseWithResult, path_params: Set[str]) -> Tuple[Optional[str], Dict]:
    """
    Analyze a resource method's signature for type correctness.
    Returns the body parameter name and collected type information.
    """
    type_annotations = get_type_hints(func)
    param_names = inspect.getfullargspec(func).args

    # Validate URI parameters are properly typed
    for param in path_params:
        if param not in param_names or type_annotations.get(param) is Any:
            raise _ValidationException(f'Missing or Any-typed URI parameter: {param}')

    # Check return type constraints
    _check_type_constraints(type_annotations.get('return'))

    # Verify required first two parameters
    if len(param_names) < 3:
        raise _ValidationException('Resource methods require at least three parameters: self, request, response')

    # Validate first two parameters are correct types
    if param_names[1] not in ('request', 'req') and type_annotations.get(param_names[1]) not in [object, Any]:
        raise _ValidationException('Second parameter must be request-like (typically falcon.Request)')

    if param_names[2] not in ('response', 'resp') and type_annotations.get(param_names[2]) not in [object, Any]:
        raise _ValidationException('Third parameter must be response-like (typically falcon.Response)')

    # Identify body parameter(s)
    positional_params = set(param_names[:3])
    candidate_body_params = set(param_names) - path_params - positional_params - {'return'}

    # Ensure only one body parameter exists
    active_body_params = [p for p in candidate_body_params if type_annotations.get(p)]
    if len(active_body_params) > 1:
        raise _ValidationException('Only one body parameter allowed per method')

    # Validate body parameter types
    for param in active_body_params:
        _check_type_constraints(type_annotations[param])

    return active_body_params[0] if active_body_params else None, type_annotations

def _decorate_resource_methods(path: str, instance: Any) -> None:
    """Apply type validation and wrapping to resource methods."""
    # Extract URI parameters from template
    uri_args = {match.group('name') for match in _URI_PARAM_REGEX.finditer(path)}

    def _wrap_handler(original: _RequestResponseWithResult) -> _RequestResponseHandler:
        """Wrap handler to assign return value to response.media."""
        @functools.wraps(original)
        def _handler(request: object, response: object, **kwargs: Any) -> None:
            result = original(request, response, **kwargs)
            if result is not None:
                response.media = result
        return _handler

    # Initialize metadata storage on resource instance
    instance._body_params = {}
    instance._type_hints = {}

    # Process each potential HTTP method
    for method_name in filter(lambda n: hasattr(instance, n), _RESOURCE_METHOD_NAMES):
        handler = getattr(instance, method_name)

        if not callable(handler):
            raise _ValidationException(f'{instance}.{method_name} must be callable')

        try:
            body_param, annotations = _analyze_method_signature(handler, uri_args)
            instance._body_params[method_name] = body_param
            instance._type_hints[method_name] = annotations
        except _ValidationException as err:
            raise _ValidationException(f'Error in {instance}.{method_name}: {err}')

        # Replace original method with wrapped version
        setattr(instance, method_name, _wrap_handler(handler))

