def indent_text(data: str, spaces: int = 4) -> str:
    """Indents each non-empty line of a string by the specified number of spaces."""
    if not data:
        return ""

    indentation = " " * spaces
    lines = data.split("\n")
    result_lines = []

    for line in lines:
        if line.strip():
            result_lines.append(indentation + line)
        else:
            result_lines.append(line)

    return "\n".join(result_lines)

def is_valid_identifier(text: str) -> bool:
    """Checks if the given text is a valid Python identifier and not a keyword."""
    return text.isidentifier() and not keyword.iskeyword(text)

def extract_cookies(headers: Dict[str, str]) -> Dict[str, str]:
    """Extracts cookies from a 'cookie' header into a dictionary."""
    cookie_header = headers.pop("cookie", None)
    if not cookie_header:
        return {}

    cookie_dict = {}
    # Split on "; " as per standard cookie format
    for cookie in cookie_header.split("; "):
        if "=" in cookie:
            key, value = cookie.split("=", 1)
            cookie_dict[key] = value

    return cookie_dict

def combine_dictionaries(*dicts: Dict[str, str]) -> Dict[str, str]:
    """Returns a dictionary containing only items common to all provided dictionaries."""
    if len(dicts) <= 1:
        return {}

    # Start with the first dictionary and check against others
    result = {}
    for key, value in dicts[0].items():
        if all(d.get(key) == value for d in dicts[1:]):
            result[key] = value

    return result

def format_dictionary(data: dict, indent_size: Optional[int] = 4, variables: Optional[List[str]] = None) -> str:
    """Formats a dictionary as JSON-like string with Python-specific replacements."""
    variables = variables or []

    # Convert to JSON string
    formatted = json.dumps(data, indent=indent_size)

    # Replace JSON literals with Python equivalents
    formatted = formatted.replace(" null", " None")
    formatted = formatted.replace(" true", " True")
    formatted = formatted.replace(" false", " False")

    # Replace variable names when they appear as values
    for var in variables:
        formatted = formatted.replace(f': "{var}"', f": {var}")

    return formatted

def parse_url_encoded(data: str) -> Dict[str, str]:
    """Parses URL-encoded form data or query strings into a dictionary."""
    return dict(urllib.parse.parse_qsl(data, keep_blank_values=True))

# Word conversion mappings
ONES_MAP = {
    "1": "one",
    "2": "two",
    "3": "three",
    "4": "four",
    "5": "five",
    "6": "six",
    "7": "seven",
    "8": "eight",
    "9": "nine",
}

TENS_MAP = {
    "1": "ten",
    "2": "twenty",
    "3": "thirty",
    "4": "forty",
    "5": "fifty",
    "6": "sixty",
    "7": "seventy",
    "8": "eighty",
    "9": "ninety",
}

UNIQUE_NUMBERS_MAP = {
    "11": "eleven",
    "12": "twelve",
    "13": "thirteen",
    "14": "fourteen",
    "15": "fifteen",
    "16": "sixteen",
    "17": "seventeen",
    "18": "eighteen",
    "19": "nineteen",
}

def number_to_words(num: Union[int, str]) -> str:
    """Converts an integer (0-999) or leading integer in a string to its written form."""
    if isinstance(num, str):
        if num.isdigit():
            return number_to_words(int(num))

        match = leading_integer_regexp.search(num)
        if not match:
            return num

        initial_num = match.group(0)
        written_part = number_to_words(int(initial_num))
        remaining_part = num[match.end():]
        return f"{written_part}_{remaining_part}"

    # Validate range
    if not (0 <= num <= 999):
        raise NotImplementedError("Numbers must be in range 0...999 inclusive")

    if num == 0:
        return "zero"

    # Process digits
    padded = str(num).zfill(3)
    hundreds_digit = padded[0]
    tens_digit = padded[1]
    ones_digit = padded[2]

    parts = []

    # Handle hundreds place
    if ONES_MAP.get(hundreds_digit):
        parts.append(f"{ONES_MAP[hundreds_digit]}_hundred")

    # Handle tens and ones places
    combined_tens_ones = f"{tens_digit}{ones_digit}"
    if UNIQUE_NUMBERS_MAP.get(combined_tens_ones):
        parts.append(UNIQUE_NUMBERS_MAP[combined_tens_ones])
    else:
        tens_word = TENS_MAP.get(tens_digit)
        ones_word = ONES_MAP.get(ones_digit)

        if tens_word and ones_word:
            parts.append(f"{tens_word}_{ones_word}")
        elif tens_word:
            parts.append(tens_word)
        elif ones_word:
            parts.append(ones_word)

    return "_and_".join(parts)

def generate_unique_name(name: str, existing_names: List[str]) -> str:
    """Generates a unique name based on the input name and list of existing names."""
    matching_names = [item for item in existing_names if item.startswith(name)]

    if not matching_names:
        return name

    count = len(matching_names) + 1
    if count > 999:
        raise NotImplementedError(">999 methods with similar names not supported")

    suffix = number_to_words(count)
    return f"{name}_{suffix}"

def unescape_special_chars(text: str) -> str:
    """
    Converts escaped characters like \\t to their actual representations.
    Uses UTF-8 encoding with fallback handling for invalid sequences.
    """
    try:
        # Encode to bytes, then decode using unicode_escape
        return text.encode('utf-8', errors='ignore').decode('unicode_escape', errors='replace')
    except Exception:
        # Fallback for edge cases
        return text

