# Constants and defaults
DEFAULT_CORENLP_PATH = os.path.expanduser('~/lltk_data/tools/corenlp')
CPU_COUNT = mp.cpu_count()
DEFAULT_ANNOTATORS = ['tokenize', 'ssplit', 'pos', 'lemma', 'ner', 'parse', 'depparse', 'coref', 'quote']

def build_command(
        java_path='java',
        heap_size='16G',
        server_port=9000,
        timeout_ms=30000,
        thread_count=None,
        max_text_length=100000,
        annotators_list=None,
        preload_models=True,
        suppress_output=True,
        format_pretty=True,
        output_type="json"):

    if thread_count is None:
        thread_count = CPU_COUNT
    if annotators_list is None:
        annotators_list = DEFAULT_ANNOTATORS

    # Construct command string using list join instead of direct concatenation
    cmd_parts = [
        f"cd {get_corenlp_dir()} &&",
        f"{java_path} -Xmx{heap_size} -cp \"*\" edu.stanford.nlp.pipeline.StanfordCoreNLPServer",
        f"-port {server_port}",
        f"-timeout {timeout_ms}",
        f"-threads {thread_count}",
        f"-maxCharLength {max_text_length}",
        f"-annotators {','.join(annotators_list)}",
        f"{'-preload' if preload_models else ''}",
        f"-outputFormat {output_type}",
        f"{'-prettyPrint' if format_pretty else ''}"
    ]

    return " ".join(cmd_parts)

def get_corenlp_dir():
    try:
        import lltk
        return lltk.config.get('PATH_CORENLP', DEFAULT_CORENLP_PATH)
    except ImportError:
        return DEFAULT_CORENLP_PATH

def ensure_stanza():
    try:
        import stanza
    except ImportError:
        os.system('pip install stanza -q')
        import stanza
    stanza.install_corenlp(dir=get_corenlp_dir())

def launch_server(**kwargs):
    os.system(build_command(**kwargs))

def process_text_segment(text):
    if not text or not text.strip():
        return {}

    from stanza.server import CoreNLPClient, StartServer
    try:
        with CoreNLPClient(
                start_server=StartServer.DONT_START,
                output_format='json') as client:
            return client.annotate(text.strip())
    except Exception:
        return {}

def annotate_text(
        full_text,
        workers=4,
        paragraph_mode=True,
        show_progress=None):

    import lltk

    # Set default progress bar visibility
    if show_progress is None:
        show_progress = workers > 1

    if paragraph_mode:
        paragraphs = [p.strip() for p in full_text.split('\n\n') if p.strip()]
        return lltk.pmap(process_text_segment, paragraphs, num_proc=workers, progress=show_progress)
    else:
        return process_text_segment(full_text)

def process_file(
        file_path,
        workers=4,
        paragraph_mode=True,
        save_output=True,
        output_file=None,
        overwrite=False,
        show_progress=True):

    # Skip non-existent files
    if not os.path.exists(file_path):
        return []

    # Read input file
    content = ""
    with open(file_path) as f:
        content = f.read().strip()

    if not content:
        return []

    # Annotate the content
    result = annotate_text(content, num_proc=workers, by_para=paragraph_mode, progress=show_progress)
    if not result:
        return []

    # Save results if requested
    if save_output:
        if not output_file:
            output_file = file_path.replace('/txt/', '/corenlp/')
            base_name, _ = os.path.splitext(output_file)
            output_file = base_name + '.json'

        # Avoid overwriting unless explicitly allowed
        if not overwrite and os.path.exists(output_file):
            return result

        # Create directory if needed
        output_dir = os.path.dirname(output_file)
        if output_dir and not os.path.exists(output_dir):
            os.makedirs(output_dir)

        # Write JSON output
        with open(output_file, 'w') as out_f:
            json.dump(result, out_f, indent=4)

    return result

def process_batch_files(file_paths):
    from lltk import tools
    def single_file_wrapper(path):
        return process_file(path, workers=1, show_progress=False)
    return tools.pmap(single_file_wrapper, file_paths, num_proc=8)

# Core classes for structured access to annotations
class AnnotationBase:
    def __init__(self, data, index=None, parent=None):
        self._data = data
        self._index = index
        self._parent = parent

    @property
    def data(self):
        return self._data

class Entity(AnnotationBase):
    @property
    def entities(self):
        result = []
        for sentence in self.sentences:
            for mention in sentence.entitymentions:
                result.append(Entity(mention, parent=self))
        return result

    @property
    def people(self):
        return [e for e in self.entities if e.data.get('ner') == 'PERSON']

class Sentence(AnnotationBase):
    def __init__(self, data, index=None, parent=None):
        super().__init__(data, index, parent)
        for key, value in self.data.items():
            setattr(self, key, value)

class Coreference(AnnotationBase): pass
class Quote(AnnotationBase): pass

class DocumentSection(AnnotationBase):
    def __init__(self, data, index=None, parent=None):
        super().__init__(data, index, parent)

        # Initialize sentences
        self.sentences = [
            Sentence(sent, i=i, parent=self)
            for i, sent in enumerate(data.get('sentences', []))
        ]

        # Initialize coreferences
        self.corefs = [
            Coreference(coref, i=i, parent=self)
            for i, coref in enumerate(data.get('corefs', []))
        ]

        # Initialize quotes
        self.quotes = [
            Quote(quote, i=i, parent=parent)
            for i, quote in enumerate(data.get('quotes', []))
        ]

class Document:
    def __init__(self, json_data_list):
        self._data = json_data_list
        self.sections = [
            DocumentSection(item, i=i, parent=self)
            for i, item in enumerate(json_data_list)
            if item
        ]

    @property
    def sentences(self):
        return [
            sent
            for section in self.sections
            for sent in section.sentences
        ]

