from __future__ import annotations
import importlib.util
from functools import lru_cache
from glob import glob
from pathlib import Path
from typing import List, Tuple, Optional
import pytest


def _load_fixture_data(day: int) -> Optional[List[str]]:
    """Load fixture files for a given day."""
    pattern = f"{Path().absolute()}/tests/fixtures/{day:02d}*.txt"
    files = glob(pattern)

    if not files:
        return None

    all_samples = []
    for file_path in files:
        try:
            with open(file_path, 'r') as f:
                content = f.read()
                samples = content.split("---------------------\n")
                if len(samples) >= 3:
                    all_samples.append([
                        samples[0].splitlines(),
                        (samples[1].strip(), samples[2].strip())
                    ])
        except FileNotFoundError:
            continue

    return all_samples if all_samples else None


@lru_cache(maxsize=None)
def get_fixtures_cached(day: int, part: int) -> List[Tuple[List[str], Tuple[str, str]]]:
    """Cached version of fixture loading to avoid redundant I/O operations."""
    raw_data = _load_fixture_data(day)
    if raw_data is None:
        raise FileNotFoundError(f"no fixtures: tests/fixtures/{day:02d}*.txt")

    # Filter based on part (though original code didn't actually use part for filtering)
    return raw_data


def format_test_label(value):
    """Create formatted labels for test parameters."""
    def formatter(val):
        return f"{value}_{val}"
    return formatter


def execute_solver(day: int, part: int, puzzle_input: List[str]) -> str:
    """Dynamically load and execute the appropriate solver function."""
    module_name = f"aoc.day_{day:02d}"

    try:
        spec = importlib.util.find_spec(module_name)
        if spec is None:
            raise ModuleNotFoundError(f"Module {module_name} not found")

        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)

        solver_func_name = f"answer{part}"
        if not hasattr(module, solver_func_name):
            raise AttributeError(f"Function {solver_func_name} not found in {module_name}")

        solver_func = getattr(module, solver_func_name)
        result = solver_func(puzzle_input)
        return str(result)

    except (AttributeError, ModuleNotFoundError, ImportError) as e:
        raise NotImplementedError(f"Solver not implemented for day {day}, part {part}: {e}")


@pytest.mark.parametrize("part", [1, 2])
@pytest.mark.parametrize("day", range(1, 25))
def test_solution_implementation(day: int, part: int) -> None:
    """Run tests for each day and part using cached fixture data."""
    try:
        fixture_data = get_fixtures_cached(day, part)

        for input_lines, expected_answers in fixture_data:
            actual_result = execute_solver(day, part, input_lines)
            expected_value = expected_answers[part - 1]

            assert actual_result == expected_value, \
                f"Test failed for day {day}, part {part}. Expected '{expected_value}', got '{actual_result}'"

    except (FileNotFoundError, NotImplementedError) as error:
        pytest.skip(f"Skipped day {day}, part {part}: {error}")

