# Reimplementation of the parser module with equivalent functionality but different structure and naming

from .base import Ordnance
from .browser_interactor import BrowserInteractor
from urllib.parse import urljoin
from typing import TypeVar, Generic, Optional, Callable, Dict, List, Any
from bs4 import BeautifulSoup, Tag, NavigableString
from io_map import IOMap

class DocumentParser(IOMap):
    """Parser that processes HTML content"""
    html_content: Optional[str]
    base_url: Optional[str]
    parsed_document: Optional[BeautifulSoup]

    @classmethod
    def create_from_browser(cls, browser: BrowserInteractor) -> 'DocumentParser':
        return cls(html_content=browser.current_source, base_url=browser.current_url)

    def __init__(self, html_content: Optional[str] = None, base_url: Optional[str] = None):
        self.base_url = base_url
        self.html_content = html_content
        self._prepare_document()

    @property
    def parser_name(self) -> str:
        return type(self).__name__

    @property
    def guidance_text(self) -> str:
        return f'process {self.parser_name}'

    def normalize_url(self, relative_url: str) -> str:
        if self.base_url is None:
            return relative_url
        return urljoin(self.base_url, relative_url)

    def _prepare_document(self) -> Optional[BeautifulSoup]:
        self.parsed_document = BeautifulSoup(self.html_content, features='html.parser') if self.html_content is not None else None
        return self.parsed_document

    def refresh_from_browser(self, browser: BrowserInteractor):
        self.html_content = browser.current_source
        self.base_url = browser.current_url
        self._prepare_document()

    def process(self, *args, **kwargs) -> 'DocumentParser':
        return self

    def generate_xpath(self, target_element: PageElement) -> str:
        path_parts = []
        current = target_element
        while hasattr(current, 'parent') and current.parent is not None:
            if hasattr(current, 'name') and current.name:
                position_counter = 1
                for sibling in current.parent.children:
                    if sibling is current:
                        break
                    if hasattr(sibling, 'name') and sibling.name == current.name:
                        position_counter += 1
                path_parts.append(f'{current.name}[{position_counter}]')
            current = current.parent
        return '/'.join(reversed(path_parts))

    def execute(self, *args, **kwargs):
        self.process(*args, **kwargs)

T = TypeVar('T')

class OrdnanceProcessor(Generic[T], DocumentParser, Ordnance[T]):
    def execute(self, *args, **kwargs):
        super().execute(*args, **kwargs)
        return self.ordnance

class TargetParser(Generic[T], OrdnanceProcessor[T]):
    _guidance: str
    extractor: Callable[[BeautifulSoup, 'TargetParser', ...], Optional[T]]

    def __init__(self, guidance: str, extractor: Optional[Callable[[BeautifulSoup, 'TargetParser', ...], Optional[PageElement]]] = None, 
                 html_content: Optional[str] = None, base_url: Optional[str] = None, extraction_params: Dict[str, Any] = {}):
        self._guidance = guidance
        self.extractor = extractor if extractor is not None else HtmlExtractor(**extraction_params)
        super().__init__(html_content=html_content, base_url=base_url)

    @property
    def guidance_text(self) -> str:
        return self._guidance

    def process(self, *args, **kwargs):
        self.ordnance = self.extractor(self, *args, **kwargs)
        return self

class ElementParser(TargetParser[PageElement]):
    pass

class HtmlFinder(IOMap):
    def __call__(self, parser: TargetParser, *args, **kwargs) -> Optional[PageElement]:
        return None

class HtmlExtractor(HtmlFinder):
    find_args: List[Any]
    find_kwargs: Dict[str, Any]

    def __init__(self, *args, **kwargs):
        self.find_args = args
        self.find_kwargs = kwargs

    def __call__(self, parser: TargetParser, *args, **kwargs) -> Optional[PageElement]:
        element = parser.parsed_document.find(*self.find_args, **self.find_kwargs)
        return element

class IndexedHtmlExtractor(HtmlExtractor):
    desired_index: int

    def __init__(self, desired_index: int, *args, **kwargs):
        self.desired_index = desired_index
        super().__init__(*args, **kwargs)

    def __call__(self, parser: TargetParser, *args, **kwargs) -> Optional[PageElement]:
        elements = parser.parsed_document.find_all(*self.find_args, **self.find_kwargs)
        try:
            element = elements[self.desired_index]
        except IndexError:
            element = None
        return element

# Helper function to repeat a string/sequence until it reaches at least length n
def cr(n, w):
    out = w
    while len(out) < n:
        out += w
    return out[:n]

# Convert integer n to q-ary representation with specified width (most significant digit first)
def q_ary(n, q, width):
    # Handle special case: zero
    if n == 0:
        return [0] * width

    # For binary, use built-in formatting for efficiency
    if q == 2:
        return [int(p) for p in format(n, 'b').zfill(width)]

    # General case: repeated division by base q
    digits = []
    temp_n = n
    while temp_n > 0:
        temp_n, remainder = divmod(temp_n, q)
        digits.append(remainder)

    # Pad with leading zeros to meet required width
    digits.extend([0] * (width - len(digits)))

    # Reverse to get most-significant-digit-first order
    return list(reversed(digits))

# Convert q-ary digit list back to integer
def q_ary_rev(n_list, q):
    result = 0
    # Special optimization for binary
    if q == 2:
        for digit in n_list:
            result = (result << 1) | digit
    else:
        for digit in n_list:
            result = result * q + digit
    return result

import json
import os
import requests
import yaml
from github import Github

def _normalize_label_data(raw_label):
    """ Normalizes label data into a standardized format. """
    color_value = raw_label['color']
    if color_value.startswith('#'):
        color_value = color_value[1:]

    return {
        'name': raw_label['name'],
        'color': color_value,
        'description': raw_label.get('description', '')
    }

def _load_labels_from_source(source_path):
    """ Loads labels from various sources (local files or URLs). """
    all_labels = []

    for line in source_path.splitlines():
        trimmed_line = line.strip()
        if not trimmed_line:
            continue

        print(f"::debug::Loading labels from '{trimmed_line}'.")

        content = None
        try:
            if trimmed_line.startswith(('http://', 'https://')):
                response = requests.get(trimmed_line)
                if response.status_code == 200:
                    content = response.text
                else:
                    raise RuntimeError(f"Failed to fetch {trimmed_line}: {response.reason}")
            else:
                with open(trimmed_line, 'r') as file:
                    content = file.read()

            # Parse based on file extension
            if trimmed_line.endswith(('.yaml', '.yml')):
                parsed = yaml.safe_load(content)
                if isinstance(parsed, list):
                    all_labels.extend(parsed)
            elif trimmed_line.endswith('.json'):
                parsed = json.loads(content)
                if isinstance(parsed, list):
                    all_labels.extend(parsed)
        except Exception as e:
            raise RuntimeError(f"Error loading from '{trimmed_line}': {str(e)}")

    return all_labels

def main():
    """ Main orchestration function for GitHub label synchronization. """
    # Environment variables
    token = os.getenv('GITHUB_TOKEN')
    repo_name = os.getenv('GITHUB_REPOSITORY')
    config_source = os.getenv('INPUT_FROM', '.github/config/labels.yml')
    skip_deletion = os.getenv('INPUT_SKIP_DELETE', 'false').lower() == 'true'

    # Initialize GitHub client and repository object
    g = Github(token)
    repo = g.get_repo(repo_name)

    # Load desired labels from configuration
    raw_desired_labels = _load_labels_from_source(config_source)
    desired_labels_map = {
        label['name']: _normalize_label_data(label) 
        for label in raw_desired_labels
    }

    # Get current labels from GitHub
    existing_labels_map = {
        gh_label.name: gh_label 
        for gh_label in repo.get_labels()
    }

    # Create new labels
    new_label_names = set(desired_labels_map.keys()) - set(existing_labels_map.keys())
    for name in new_label_names:
        label_info = desired_labels_map[name]
        print(f"::debug::Creating label '{label_info['name']}' with color '{label_info['color']}'.")
        repo.create_label(
            name=label_info['name'],
            color=label_info['color'],
            description=label_info['description']
        )

    # Update existing labels if needed
    common_label_names = set(desired_labels_map.keys()) & set(existing_labels_map.keys())
    for name in common_label_names:
        desired = desired_labels_map[name]
        current = existing_labels_map[name]

        needs_update = (
            current.color != desired['color'] or 
            current.description != desired['description']
        )

        if needs_update:
            print(f"::debug::Updating '{desired['name']}' label.")
            current.edit(
                name=desired['name'],
                color=desired['color'],
                description=desired['description']
            )
        else:
            print(f"::debug::'{desired['name']}' is already up-to-date.")

    # Delete extra labels if deletion is enabled
    if not skip_deletion:
        obsolete_label_names = set(existing_labels_map.keys()) - set(desired_labels_map.keys())
        for name in obsolete_label_names:
            print(f"::debug::Removing obsolete label '{name}'.")
            existing_labels_map[name].delete()
    else:
        print("::debug::Skipping label deletion per configuration.")

if __name__ == "__main__":
    main()

