@kopf.on.delete(ORBIT_API_GROUP, ORBIT_API_VERSION, "teamspaces")  # type: ignore
def on_teamspace_deleted(namespace: str, name: str, spec: kopf.Spec, patch: kopf.Patch, logger: kopf.Logger, **_: Any) -> str:
    logger.info(f"Processing deletion of Teamspace '{name}' in namespace '{namespace}'")

    team_name = spec.get("team")
    if not team_name:
        logger.warning("No 'team' field found in spec; skipping resource cleanup")
    else:
        logger.info(f"Initiating cleanup for team '{team_name}' in namespace '{namespace}'")
        _cleanup_team_resources(team_name=team_name, target_namespace=namespace, logger=logger)
        _cleanup_user_namespaces(team_name=team_name, parent_namespace=namespace, logger=logger)
        patch["status"] = {"teamspaceOperator": {"status": "DeleteProcessed"}}

    return "Uninstalled"

def _cleanup_user_namespaces(team_name: str, parent_namespace: str, logger: kopf.Logger, **_: Any) -> None:
    logger.info(f"Scanning for user namespaces labeled with orbit/team={team_name},orbit/space=user under {parent_namespace}")
    v1_core = CoreV1Api()
    selector = f"orbit/team={team_name},orbit/space=user"
    ns_list = v1_core.list_namespace(label_selector=selector).to_dict()

    user_ns_names = [
        ns_entry["metadata"]["name"]
        for ns_entry in ns_list.get("items", [])
        if ns_entry.get("metadata", {}).get("name")
    ]

    for ns in user_ns_names:
        logger.info(f"Triggering async deletion of namespace: {ns}")
        try:
            v1_core.delete_namespace(name=ns, async_req=True)
        except ApiException as err:
            logger.warning(f"Failed to delete namespace '{ns}': {err}")

def _cleanup_team_resources(team_name: str, target_namespace: str, logger: kopf.Logger, **_: Any) -> None:
    v1_core = CoreV1Api()
    label_selector = f"orbit/team={team_name}"
    ns_list = v1_core.list_namespace(label_selector=label_selector).to_dict()

    affected_ns = [
        ns_entry["metadata"]["name"]
        for ns_entry in ns_list.get("items", [])
        if ns_entry.get("metadata", {}).get("name")
    ]

    # Define list of custom resource types to clean up
    crd_definitions = [
        ("sagemaker.aws.amazon.com", "v1", "hyperparametertuningjobs", "trainingJobStatus"),
        ("sagemaker.aws.amazon.com", "v1", "trainingjobs", "trainingJobStatus"),
        ("sagemaker.aws.amazon.com", "v1", "batchtransformjobs", "transformJobStatus"),
        ("sagemaker.aws.amazon.com", "v1", "hostingdeployments", "status"),
        ("kubeflow.org", "v1", "notebooks", "NA"),
        ("kubeflow.org", "v1", "profile", "NA"),
        ("batch", "v1", "jobs", "NA"),
        ("apps", "v1", "deployments", "NA"),
        ("apps", "v1", "statefulsets", "NA"),
    ]

    for ns in affected_ns:
        logger.info(f"Processing namespace: {ns}")
        for group, version, plural, _ in crd_definitions:
            _remove_custom_objects(group=group, version=version, plural=plural, namespace=ns, logger=logger)

        _remove_all_pods_in(ns, logger=logger)

        # Only apply extra handling to first four items (SageMaker resources)
        for group, version, plural, status_field in crd_definitions[:4]:
            _force_delete_stuck_resources(
                group=group,
                version=version,
                plural=plural,
                status_key=status_field,
                namespace=ns,
                logger=logger
            )

def _remove_all_pods_in(namespace: str, logger: kopf.Logger, use_async: bool = True, **_: Any) -> None:
    logger.info(f"Removing all pods in namespace '{namespace}'")
    v1 = CoreV1Api()
    try:
        v1.delete_collection_namespaced_pod(
            namespace=namespace,
            async_req=use_async,
            grace_period_seconds=0,
            propagation_policy="Background",
            body=V1DeleteOptions(),
        )
    except ApiException as e:
        logger.warning(f"Pod collection deletion failed in '{namespace}': {e}")

def _remove_custom_objects(group: str, version: str, plural: str, namespace: str, logger: kopf.Logger, use_async: bool = True, **_: Any) -> None:
    logger.info(f"Attempting to delete all {plural}.{group} in namespace '{namespace}'")
    co_api = CustomObjectsApi()
    try:
        co_api.delete_collection_namespaced_custom_object(
            group=group,
            version=version,
            namespace=namespace,
            plural=plural,
            grace_period_seconds=0,
            propagation_policy="Background",
            pretty="true",
            async_req=use_async,
            body=V1DeleteOptions(),
        )
    except ApiException as e:
        logger.warning(f"Custom object collection deletion failed ({group}/{version}/{plural}): {e}")

def _force_delete_stuck_resources(group: str, version: str, plural: str, status_key: str, namespace: str, logger: kopf.Logger, use_async: bool = True, **_: Any) -> None:
    logger.info(f"Inspecting stuck resources in {plural}.{group} under '{namespace}'")
    co_api = CustomObjectsApi()
    try:
        list_resp = co_api.list_namespaced_custom_object(group=group, version=version, plural=plural, namespace=namespace)
    except ApiException as e:
        logger.warning(f"Could not list {plural}.{group}: {e}")
        return

    problematic_items = []
    for item in list_resp.get("items", []):
        status_val = item.get("status", {}).get(status_key)
        if status_val in ["Failed", "Completed", "InProgress"]:
            problematic_items.append(item["metadata"]["name"])

    for res_name in problematic_items:
        try:
            logger.info(f"Removing finalizers from {res_name} in {plural}.{group}")
            patch_body = json.loads('{"metadata":{"finalizers":[]}}')
            co_api.patch_namespaced_custom_object(
                group=group,
                version=version,
                plural=plural,
                namespace=namespace,
                name=res_name,
                body=patch_body,
            )
            logger.info(f"Deleting {res_name} in {plural}.{group}")
            co_api.delete_namespaced_custom_object(
                group=group,
                version=version,
                plural=plural,
                namespace=namespace,
                name=res_name,
            )
        except ApiException as e:
            logger.warning(f"Failed to remove finalizer/delete {res_name}: {e}")

import copy
from typing import Any, Iterable, List, Optional, Tuple, Union
import numpy as np
from sortedcontainers import SortedList

# Assuming Function is defined elsewhere and imported properly
class Individual:
    def __init__(self, data: Any, fitness_value: Union[float, int]):
        self._data = copy.deepcopy(data)
        self._fitness = copy.deepcopy(fitness_value)

    @property
    def data(self) -> Any:
        return self._data

    @property
    def fitness(self) -> Union[float, int]:
        return self._fitness

    def __eq__(self, other: "Individual"):
        if isinstance(other, Individual):
            data_match = self.data == other.data
            fitness_match = self.fitness == other.fitness

            # Handle non-boolean comparison results for data
            if not isinstance(data_match, bool):
                try:
                    iter(data_match)
                    data_match = all(data_match)
                except TypeError:
                    pass

            # Handle non-boolean comparison results for fitness
            if not isinstance(fitness_match, bool):
                try:
                    iter(fitness_match)
                    fitness_match = all(fitness_match)
                except TypeError:
                    pass

            return data_match and fitness_match
        return False

    def __str__(self):
        return f"[{self.fitness}] {self.data}"

    def __repr__(self):
        return str(self)

class FitnessEvaluator:
    @staticmethod
    def _validate_fitness_function(fitness_func) -> Any:
        # Check that the provided object has required callable interface
        if not callable(fitness_func):
            raise TypeError(
                "Expected argument fitness_function to be callable, instead it is "
                f"{type(fitness_func)}."
            )
        return fitness_func

    @property
    def fitness_function(self):
        return self._fitness_func

    def __init__(self, fitness_function):
        self._fitness_func = self._validate_fitness_function(fitness_function=fitness_function)

    def evaluate(self, data_point: Any) -> Individual:
        return Individual(data=data_point, fitness_value=self._fitness_func(data_point))

    def __call__(self, data_point) -> Individual:
        return self.evaluate(data_point)

class Group:
    @staticmethod
    def _validate_initialization(
        fitness_function,
        initial_data: Optional[Iterable[Union[Any, Individual]]],
        max_size: int,
        elite_count: int,
    ) -> Tuple[FitnessEvaluator, List[Individual], int, int]:
        # Validate fitness function
        evaluator = FitnessEvaluator(fitness_function=fitness_function)

        # Validate max_size
        if not isinstance(max_size, int):
            raise TypeError(
                "Expected argument max_size to be an int, instead it is "
                f"{type(max_size)}."
            )
        if max_size < 1:
            raise ValueError(
                "Expected argument max_size to be a positive integer, instead it is "
                f"{max_size}."
            )

        # Validate initial_data
        processed_data = []
        if initial_data is not None:
            try:
                iter(initial_data)
            except TypeError:
                raise TypeError(
                    "Expected argument initial_data to be an iterable or None, instead it "
                    f"is {type(initial_data)}."
                )

            # Convert raw data to Individuals
            processed_data = [
                item if isinstance(item, Individual) else evaluator(item)
                for item in initial_data
            ]

            # Trim if over capacity
            if len(processed_data) > max_size:
                processed_data.sort(key=lambda x: -x.fitness)
                processed_data = processed_data[:max_size]

        # Validate elite_count
        if not isinstance(elite_count, int):
            raise TypeError(
                "Expected argument elite_count to be an int, instead it is "
                f"{type(elite_count)}."
            )
        if elite_count < 0:
            raise ValueError(
                "Expected argument elite_count to be a non-negative integer, instead it is "
                f"{elite_count}."
            )

        return evaluator, processed_data, max_size, elite_count

    def __init__(
        self,
        fitness_function,
        initial_data: Optional[Iterable[Union[Any, Individual]]] = None,
        max_size: int = 10,
        elite_count: int = 0,
    ):
        evaluator, processed_data, max_size, elite_count = self._validate_initialization(
            fitness_function=fitness_function,
            initial_data=initial_data,
            max_size=max_size,
            elite_count=elite_count,
        )

        self._evaluator = evaluator
        self._max_size = max_size
        self._elite_count = elite_count
        self.__members = SortedList(iterable=processed_data, key=lambda x: -x.fitness)

    @property
    def fitness_function(self):
        return self._evaluator.fitness_function

    @property
    def evaluator(self):
        return self._evaluator

    @property
    def max_size(self):
        return self._max_size

    @property
    def elite_count(self):
        return self._elite_count

    def remove_member(self, member: Union[Any, Individual]):
        if member is not None:
            actual_member = (
                member if isinstance(member, Individual) 
                else self.evaluator(member)
            )
            self.__members.discard(actual_member)

    def trim(self, extra_to_remove: int = 0):
        if not isinstance(extra_to_remove, int):
            raise TypeError(
                "Expected argument extra_to_remove to be an int, instead it is "
                f"{type(extra_to_remove)}."
            )
        if extra_to_remove < 0:
            raise ValueError(
                "Expected argument extra_to_remove to be a non-negative integer, instead "
                f"it is {extra_to_remove}."
            )

        max_removable = len(self) - self.elite_count
        to_remove_count = len(self) - self.max_size + extra_to_remove
        to_remove_count = min(to_remove_count, max_removable)

        if to_remove_count < len(self):
            for _ in range(to_remove_count):
                self.__members.pop()
        else:
            self.__members.clear()

    def extract(self, position: int = -1):
        if not isinstance(position, int):
            raise TypeError(
                f"Expected argument position to be an int, instead it is {type(position)}."
            )

        return (
            self.__members.pop(position)
            if len(self) > self.elite_count
            else self.__members[position]
        )

    def include(self, new_member: Individual):
        if not isinstance(new_member, Individual):
            try:
                new_member = self.evaluator(new_member)
            except Exception as e:
                raise TypeError(
                    "Expected argument new_member to be an Individual, instead it is "
                    f"{type(new_member)}. Or {e}. One of those."
                )
        self.__members.add(new_member)

    def insert(self, new_member: Individual, evict_first: bool = True):
        if not isinstance(evict_first, bool):
            raise TypeError(
                "Expected argument evict_first to be a bool, instead it is "
                f"{type(evict_first)}."
            )

        if evict_first:
            self.trim(extra_to_remove=1)

        self.include(new_member=new_member)
        self.trim()

    def integrate(self, new_members: Iterable[Individual]):
        try:
            iter(new_members)
        except TypeError:
            raise TypeError(
                "Expected argument new_members to be an iterable, instead it is"
                f"{type(new_members)}."
            )

        for member in new_members:
            self.include(member)

    def infiltrate(self, new_members: Iterable[Individual], evict_first: bool = True):
        if not isinstance(evict_first, bool):
            raise TypeError(
                "Expected argument evict_first to be a bool, instead it is "
                f"{type(evict_first)}."
            )

        if evict_first:
            self.trim(len(new_members))

        self.integrate(new_members)
        self.trim()

    def __getitem__(self, index: Union[int, Iterable]):
        try:
            return self.__members[int(index)]
        except Exception:
            try:
                iter(index)
                return np.array([self[i] for i in index])
            except TypeError:
                raise ValueError(
                    "Expected argument index to be an int or an iterable, instead it is "
                    f"{type(index)}."
                )

    def __len__(self):
        return len(self.__members)

    def __str__(self):
        result = f"Group ({len(self)} / {self.max_size})"
        if self.elite_count != 0:
            result += f", elite: {self.elite_count}"
        for member in self.__members:
            result += f"\n\t{member}"
        return result

# Merge two sorted linked lists into one sorted list

def mergeTwoLists(l1, l2):
    # Handle edge cases where one list is empty or both are empty
    if not l1:
        return l2
    if not l2:
        return l1

    # Determine which node should be the head (smaller value first)
    if l1.val > l2.val:
        l1, l2 = l2, l1

    current = l1
    while current.next and l2:
        # If next node in l1 is greater than current l2 node, insert l2 node
        if current.next.val > l2.val:
            temp = current.next
            current.next = l2
            l2 = l2.next
            current.next.next = temp
        else:
            current = current.next

    # If l2 still has nodes left, append them
    if l2:
        current.next = l2

    return l1

