def _convert_to_input_format(rde_dict, target_version):
    """Convert a defined entity to specified input format version."""
    def_entity = common_models.DefEntity(**rde_dict)
    converted_entity = rde_utils.convert_runtime_rde_to_input_rde_version_format(
        def_entity.entity, target_version)
    def_entity.entity = converted_entity
    def_entity.entityType = common_models.EntityType.NATIVE_ENTITY_TYPE_1_0_0.value.get_id()
    return def_entity.to_dict()

def _get_cluster_service(op_ctx, rde_version=None):
    """Get appropriate cluster service based on RDE version."""
    factory = cluster_service_factory.ClusterServiceFactory(op_ctx)
    if rde_version:
        return factory.get_cluster_service(rde_version)
    return factory.get_cluster_service()

def _handle_with_generic_backend(data, op_ctx, handler_func):
    """Handle request using generic backend when RDE 2.0+ is supported."""
    rde_data = handler_func(data=data, op_ctx=op_ctx)
    return common_models.DefEntity(**rde_data).to_dict()

def _process_cluster_operation(operation_func, data, op_ctx, needs_conversion=True):
    """Generic wrapper for cluster operations with version checking."""
    rde_in_use = server_utils.get_rde_version_in_use()

    # Check if we should use the generic backend
    if semantic_version.Version(rde_in_use) >= semantic_version.Version(RDE_VERSION_2_0_0):
        result = _handle_with_generic_backend(data, op_ctx, operation_func)
    else:
        # Use legacy backend
        svc = _get_cluster_service(op_ctx, rde_in_use)
        result = operation_func(data, svc, op_ctx)

    # Convert back to expected format if needed
    if needs_conversion:
        return _convert_to_input_format(result, rde_constants.RDEVersion.RDE_1_0_0.value)
    return result

