from __future__ import annotations
import typing as t

T = t.TypeVar("T")

def safe_get(
    data: t.Dict[object, object],
    /,
    lookup_key: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform_func: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
) -> t.Optional[T]:
    """Retrieve a value from dictionary using key with optional transformation.

    Returns the value if found and valid, otherwise returns None.
    Raises ValueError if value exists but doesn't match expected type.
    """
    # Use provided transformation function or default to direct lookup
    result = transform_func(data, lookup_key) if transform_func else data.get(lookup_key)

    # Validate type if value is present
    if result is not None and not isinstance(result, expected_type):
        raise ValueError(
            f"{data}: {repr(lookup_key)}: {repr(result)}: invalid type {type(result)}, expecting {expected_type}"
        )

    return t.cast(T, result)

def mandatory_get(
    data: t.Dict[object, object],
    /,
    lookup_key: object,
    expected_type: t.Union[type, t.Tuple[type, ...]],
    *,
    transform_func: t.Optional[t.Callable[[t.Dict[object, object], object], object]] = None,
    fallback_value: t.Optional[T] = None,
    fallback_factory: t.Optional[t.Callable[[], T]] = None,
) -> T:
    """Ensure required value exists in dictionary with proper type checking.

    Returns the value if found and valid. Falls back to provided default/factory if specified.
    Raises ValueError if value is missing and no fallback is available.
    """
    # First try to get optional value
    candidate = safe_get(data, lookup_key, expected_type, transform_func=transform_func)

    # Handle missing value case
    if candidate is None:
        if fallback_value is not None:
            return fallback_value
        if fallback_factory is not None:
            return fallback_factory()
        raise ValueError(f"{data}: {repr(lookup_key)}: value is required")

    return candidate

def expand_nested_dict(nested_data: t.Dict[t.Any, t.Any]) -> t.Dict[str, object]:
    """Convert nested dictionary structure into flat representation with colon-separated keys.

    :param nested_data: Input dictionary potentially containing nested dictionaries
    :return: Flattened dictionary with composite keys
    """
    def traverse() -> t.Iterable[t.Tuple[str, object]]:
        for key, value in nested_data.items():
            # Ensure all keys are strings
            if not isinstance(key, str):
                raise ValueError(f"{key}: expected {str}, but got {type(key)}")

            # Recursively process nested dictionaries
            if isinstance(value, dict):
                for sub_key, sub_value in expand_nested_dict(value).items():
                    if not isinstance(sub_key, str):
                        raise ValueError(
                            f"{sub_key}: expected {str}, but got {type(sub_key)}"
                        )
                    yield f"{key}:{sub_key}", sub_value
            else:
                yield key, value

    return dict(traverse())

def compress_flat_dict(flat_data: t.Dict[object, object]) -> t.Dict[object, object]:
    """Reconstruct nested dictionary from flattened representation.

    :param flat_data: Dictionary with colon-separated keys representing hierarchy
    :return: Nested dictionary structure
    """
    result: t.Dict[object, object] = {}

    for key, value in flat_data.items():
        # Validate key type
        if not isinstance(key, str):
            raise ValueError(f"{key}: expected {str}, but got {type(key)}")

        # Process hierarchical keys
        if ":" in key:
            current_level: t.Union[object, t.Dict[object, object]] = result
            path_parts = key.split(":")

            # Navigate/create nested structure
            for idx, part in enumerate(path_parts):
                if not isinstance(current_level, dict):
                    continue

                if part not in current_level:
                    current_level[part] = value if idx == len(path_parts) - 1 else {}

                current_level = current_level[part]
        else:
            # Direct assignment for non-hierarchical keys
            result[key] = value

    return result

import os
import glob
import torch
import logging
import typing
from collections import OrderedDict

log = logging.getLogger(__name__)
__all__ = ["VPoserLoader"]

class VPoserLoader(typing.Callable[[torch.nn.Module], None]):
    def __init__(self, 
        checkpoint_path: str,        
        use_cache: bool = False,
    ):
        # Determine checkpoint file path
        if os.path.isdir(checkpoint_path):
            snapshot_dir = os.path.join(checkpoint_path, 'snapshots')
            ckpt_files = glob.glob(os.path.join(snapshot_dir, '*.ckpt'))
            self.checkpoint_file = ckpt_files[-1] if ckpt_files else None
        else:
            self.checkpoint_file = checkpoint_path

        # Optionally load state dict into memory for reuse
        if use_cache and self.checkpoint_file is not None:
            self.cached_state = torch.load(
                self.checkpoint_file, map_location=lambda storage, loc: storage
            )['state_dict']

    def __call__(self,
        model: torch.nn.Module
    ) -> None:
        # Only apply to VPoser instances
        if isinstance(model, VPoser):
            # Get state dict (from cache or load fresh)
            if hasattr(self, 'cached_state') and self.cached_state is not None:
                raw_state = self.cached_state
            else:
                raw_state = torch.load(
                    self.checkpoint_file, map_location=lambda storage, loc: storage
                )['state_dict']

            # Clean up keys by removing 'vp_model.' prefix
            cleaned_state = OrderedDict()
            for key, value in raw_state.items():
                new_key = key.replace('vp_model.', '', 1) if key.startswith('vp_model.') else key
                cleaned_state[new_key] = value

            # Load state dict with relaxed matching
            model.load_state_dict(cleaned_state, strict=False)
            log.info(f"Loaded VPoser weights from {self.checkpoint_file}")

import ast
import enum
import importlib.util
import logging
import sys
import tokenize
from collections import defaultdict
from functools import reduce
from itertools import chain
from typing import (
    Any,
    Dict,
    Iterable,
    List,
    Optional,
    Tuple,
    Union,
)

log = logging.getLogger(__name__)


class ImportErrorCodes(enum.Enum):
    SAME_LINE_IMPORT = 'AZUL101 more than one symbol imported per line'
    SEPARATE_IMPORTS = 'AZUL102 symbols from the same module imported in separate statements'
    BAD_STMT_ORDER = 'AZUL111 import statements are not correctly ordered'
    BAD_SYMBOL_ORDER = 'AZUL112 symbols in from import are not correctly ordered'
    MISSING_PARENS = 'AZUL131 from import lacks parentheses'
    MISSING_NEWLINES = 'AZUL132 missing newline between parentheses and imported symbols'
    NO_TRAILING_COMMA = 'AZUL133 symbol in from import lacks trailing comma'
    UNRESOLVABLE_MODULE = 'AZUL141 cannot resolve import statement from project root'


@enum.unique
class SourceOrigin(enum.IntEnum):
    PYTHON_STD = 1
    EXTERNAL_PKG = 2
    INTERNAL_MOD = 3

    @classmethod
    def derive(cls, mod_name: str) -> 'SourceOrigin':
        spec = importlib.util.find_spec(mod_name)
        if spec is None:
            raise ImportError(f"Could not locate module '{mod_name}'")
        elif spec.origin is None and spec.submodule_search_locations is None:
            assert mod_name in sys.builtin_module_names, f"{mod_name} should be builtin"
            return cls.PYTHON_STD
        else:
            path = (
                spec.origin
                if spec.origin is not None
                else next(iter(spec.submodule_search_locations))
            )
            if 'site-packages' in path:
                return cls.EXTERNAL_PKG
            elif path.startswith(config.project_root):
                return cls.INTERNAL_MOD
            else:
                return cls.PYTHON_STD


# Type aliases
ImportNode = Union[ast.Import, ast.ImportFrom]


class ModuleMetadata:
    def __init__(self, origin: SourceOrigin, name: str, is_from: bool):
        self.origin = origin
        self.name = name
        self.is_from = is_from

    def __lt__(self, other):
        return (self.origin, self.name, self.is_from) < (other.origin, other.name, other.is_from)

    @staticmethod
    def extract(node: ImportNode) -> Tuple[str, bool]:
        if isinstance(node, ast.Import):
            return one([n.name for n in node.names]), False
        elif isinstance(node, ast.ImportFrom):
            return node.module or '', True
        else:
            raise TypeError(f"Unexpected node type: {type(node)}")

    @classmethod
    def build(cls, node: ImportNode) -> 'ModuleMetadata':
        mod_name, is_from = cls.extract(node)
        try:
            origin = SourceOrigin.derive(mod_name)
        except ImportError:
            if mod_name not in {'pydevd', '_typeshed'}:
                raise
            origin = SourceOrigin.EXTERNAL_PKG
        return cls(origin=origin, name=mod_name, is_from=is_from)


class OrderedImport:
    def __init__(self, node: ImportNode, meta: ModuleMetadata):
        self.node = node
        self.meta = meta

    def precedes(self, other: 'OrderedImport') -> bool:
        return self.node.lineno <= other.node.lineno and self.meta <= other.meta

    def matches_block(self, other: 'OrderedImport') -> bool:
        return (
            self.node.col_offset == other.node.col_offset
            and not any(
                tokens and tokens[0].start[1] < self.node.col_offset
                for tokens in map(
                    lambda ln: [
                        t for t in line_tokens[ln]
                        if t.type not in {
                            tokenize.COMMENT,
                            tokenize.NEWLINE,
                            tokenize.NL,
                            tokenize.ENDMARKER
                        }
                    ],
                    range(self.node.lineno + 1, other.node.lineno)
                )
            )
            if self.node.lineno < other.node.lineno
            else self.precedes(other)
        )


class ErrorRecord:
    def __init__(self, line: int, col: int, message: str):
        self.line = line
        self.col = col
        self.message = message

    @classmethod
    def create(cls, node: ImportNode, code: ImportErrorCodes):
        return cls(line=node.lineno, col=node.col_offset, message=str(code.value))

    def as_flake8(self) -> tuple:
        return self.line, self.col, self.message, None


class ImportAnalyzer(ast.NodeVisitor):
    IGNORED_MODULES = {'pydevd', '_typeshed'}

    def __init__(self, filename: str, tokens: Iterable[tokenize.TokenInfo]):
        self.filename = filename
        self.token_lines: Dict[int, List[tokenize.TokenInfo]] = defaultdict(list)
        for tok in tokens:
            self.token_lines[tok.start[0]].append(tok)
        for line_list in self.token_lines.values():
            line_list.sort(key=lambda t: t.start[1])
        self.errors: List[ErrorRecord] = []
        self.seen_imports: List[OrderedImport] = []

    def visit_Import(self, node: ast.Import):
        self._check_single_import(node)
        self._check_stmt_order(node)

    def visit_ImportFrom(self, node: ast.ImportFrom):
        self._check_joined_import(node)
        self._check_parentheses(node)
        self._check_symbol_order(node)
        self._check_stmt_order(node)

    def _check_single_import(self, node: ImportNode):
        if len(node.names) > 1:
            self.errors.append(ErrorRecord.create(node, ImportErrorCodes.SAME_LINE_IMPORT))

    def _check_stmt_order(self, node: ImportNode):
        try:
            meta = ModuleMetadata.build(node)
            ordered = OrderedImport(node, meta)
        except ValueError:
            pass
        except ImportError:
            mod_name, _ = ModuleMetadata.extract(node)
            if mod_name not in self.IGNORED_MODULES:
                self.errors.append(ErrorRecord.create(node, ImportErrorCodes.UNRESOLVABLE_MODULE))
        else:
            prev = self._find_prev_import(node)
            next_ = self._find_next_import(node)
            if prev and not prev.precedes(ordered):
                self.errors.append(ErrorRecord.create(node, ImportErrorCodes.BAD_STMT_ORDER))
            elif next_ and not ordered.precedes(next_):
                self.errors.append(ErrorRecord.create(node, ImportErrorCodes.BAD_STMT_ORDER))
            self.seen_imports.append(ordered)

    def _check_joined_import(self, node: ast.ImportFrom):
        for seen in self.seen_imports:
            if (
                isinstance(seen.node, ast.ImportFrom)
                and seen.node.module == node.module
                and self._same_indentation(seen.node, node)
            ):
                self.errors.append(ErrorRecord.create(node, ImportErrorCodes.SEPARATE_IMPORTS))
                break

    def _check_parentheses(self, node: ast.ImportFrom):
        start_line = self._clean_tokens(node.lineno)
        end_line = self._clean_tokens(node.end_lineno)

        has_opening = any(t.string == '(' for t in start_line)
        if not has_opening:
            self.errors.append(ErrorRecord.create(node, ImportErrorCodes.MISSING_PARENS))
        elif len(start_line) > 1 or len(end_line) > 1:
            self.errors.append(ErrorRecord.create(node, ImportErrorCodes.MISSING_NEWLINES))

        for i in range(node.lineno + 1, node.end_lineno):
            tokens = self._clean_tokens(i)
            if tokens:
                last = tokens[-1]
                if last.string != ',':
                    self.errors.append(ErrorRecord.create(node, ImportErrorCodes.NO_TRAILING_COMMA))

    def _check_symbol_order(self, node: ast.ImportFrom):
        names = [alias.name for alias in node.names]
        for idx in range(len(names) - 1):
            if names[idx] > names[idx + 1]:
                self.errors.append(ErrorRecord.create(node, ImportErrorCodes.BAD_SYMBOL_ORDER))

    def _same_indentation(self, n1: ImportNode, n2: ImportNode) -> bool:
        return n1.col_offset == n2.col_offset

    def _find_prev_import(self, node: ImportNode) -> Optional[OrderedImport]:
        candidates = [o for o in self.seen_imports if o.node.lineno < node.lineno]
        return max(candidates, key=lambda x: x.node.lineno, default=None)

    def _find_next_import(self, node: ImportNode) -> Optional[OrderedImport]:
        candidates = [o for o in self.seen_imports if o.node.lineno > node.lineno]
        return min(candidates, key=lambda x: x.node.lineno, default=None)

    def _clean_tokens(self, lineno: int) -> List[tokenize.TokenInfo]:
        return [
            t for t in self.token_lines.get(lineno, [])
            if t.type not in {
                tokenize.COMMENT,
                tokenize.NEWLINE,
                tokenize.NL,
                tokenize.ENDMARKER
            }
        ]


class AzulImportsChecker:
    name = 'azul_imports'
    version = 1.0

    def __init__(self, tree: ast.AST, file_tokens: Iterable[tokenize.TokenInfo], filename: str):
        self.tree = tree
        self.tokens = file_tokens
        self.filename = filename

    def execute(self) -> List[ErrorRecord]:
        visitor = ImportAnalyzer(self.filename, self.tokens)
        visitor.visit(self.tree)
        return visitor.errors

    def run(self) -> List[tuple]:
        return [err.as_flake8() for err in self.execute()]

