class Collaboration(db.Model, HoustonModel):
    """
    Database model for collaborations.
    """
    __mapper_args__ = {
        'confirm_deleted_rows': False,
    }

    guid = db.Column(
        db.GUID, default=uuid.uuid4, primary_key=True
    )  # pylint: disable=invalid-name

    user_links = db.relationship(
        'UserCollabLink', back_populates='collab'
    )

    creator_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=False
    )
    edit_requester_guid = db.Column(
        db.GUID, db.ForeignKey('user.guid'), index=True, nullable=True
    )

    def __init__(self, participants, requestor, **kwargs):
        participant_count = len(participants)
        if participant_count != 2:
            raise ValueError('A collaboration must have exactly two participants.')

        if not hasattr(requestor, 'is_user_manager'):
            raise ValueError(f'Requestor {requestor} is not a valid user')

        manager_initiated = requestor not in participants

        if manager_initiated and not requestor.is_user_manager:
            raise ValueError(
                f'Non-manager {requestor.email} attempted to create a collaboration.'
            )

        self.creator_guid = requestor.guid
        self.edit_requester_guid = None

        for member in participants:
            if not hasattr(member, 'is_user_manager'):
                raise ValueError(f'Invalid participant {member}')

            link = UserCollabLink(
                collab=self, user=member
            )
            link.edit_permission = UserCollabStatus.UNSTARTED

            with db.session.begin(subtransactions=True):
                db.session.add(link)

            # Auto-grant view permission for initiators and managers
            if member == requestor or manager_initiated:
                link.view_permission = UserCollabStatus.GRANTED
            else:
                link.view_permission = UserCollabStatus.AWAITING

        if manager_initiated:
            originator_link = UserCollabLink(
                collab=self, user=requestor
            )
            from app.modules.notifications.models import NotificationType

            originator_link.view_permission = UserCollabStatus.ORIGINATOR
            originator_link.edit_permission = UserCollabStatus.ORIGINATOR

            for member in participants:
                member_link = self._find_link_for_user(member.guid)
                self._send_notification(
                    originator_link, member_link, NotificationType.collab_manager_create
                )

            with db.session.begin(subtransactions=True):
                db.session.add(originator_link)

    def _find_link_for_user(self, user_guid):
        for link in self.user_links:
            if link.user_guid == user_guid:
                return link
        return None

    def _find_peer_link(self, user_guid):
        peer_guids = [
            link.user_guid
            for link in self.user_links
            if (link.user_guid != user_guid) and 
               (link.view_permission != UserCollabStatus.ORIGINATOR)
        ]
        assert len(peer_guids) == 1
        return self._find_link_for_user(peer_guids[0])

    def get_members(self):
        return [
            link.user for link in self.user_links
            if link.view_permission != UserCollabStatus.ORIGINATOR
        ]

    def member_ids(self):
        return [
            link.user_guid for link in self.user_links
            if link.view_permission != UserCollabStatus.ORIGINATOR
        ]

    def notify_awaiting_users(self):
        for link in self.user_links:
            if (
                link.view_permission == UserCollabStatus.AWAITING or
                link.edit_permission == UserCollabStatus.AWAITING
            ):
                from app.modules.notifications.models import NotificationType
                peer_link = self._find_peer_link(link.user.guid)

                if link.view_permission == UserCollabStatus.AWAITING:
                    self._send_notification(
                        peer_link, link, NotificationType.collab_request
                    )

                if link.edit_permission == UserCollabStatus.AWAITING:
                    self._send_notification(
                        peer_link, link, NotificationType.collab_edit_request
                    )

    def _send_notification(self, sender_link, receiver_link, notification_type):
        from app.modules.notifications.models import Notification, NotificationBuilder
        builder = NotificationBuilder(sender_link.user)
        builder.set_collaboration(self)
        Notification.create(notification_type, receiver_link.user, builder)

    def get_user_data_as_json(self):
        from app.modules.users.schemas import BaseUserSchema
        user_data = {}

        for link in self.user_links:
            if link.view_permission == UserCollabStatus.ORIGINATOR:
                continue

            user_info = BaseUserSchema().dump(link.user).data
            user_info['viewState'] = link.view_permission
            user_info['editState'] = link.edit_permission
            user_data[str(link.user.guid)] = user_info

        return user_data

    def _validate_permission_change(self, old_state, new_state):
        allowed_transitions = {
            UserCollabStatus.UNSTARTED: [
                UserCollabStatus.ORIGINATOR,
                UserCollabStatus.GRANTED,
                UserCollabStatus.AWAITING,
            ],
            UserCollabStatus.AWAITING: [
                UserCollabStatus.GRANTED,
                UserCollabStatus.REJECTED,
            ],
            UserCollabStatus.GRANTED: [
                UserCollabStatus.WITHDRAWN,
            ],
            UserCollabStatus.REJECTED: [
                UserCollabStatus.GRANTED,
            ],
            UserCollabStatus.WITHDRAWN: [
                UserCollabStatus.GRANTED,
            ],
        }

        return (new_state in allowed_transitions.get(old_state, []) or 
                old_state == new_state)

    def update_view_permission(self, user_guid, new_state):
        success = False

        if new_state not in UserCollabStatus.VALID_STATUSES:
            raise ValueError(
                f'State "{new_state}" not in allowed states: {", ".join(UserCollabStatus.VALID_STATUSES)}'
            )

        if user_guid is not None:
            assert isinstance(user_guid, uuid.UUID)

            for link in self.user_links:
                if link.user_guid == user_guid:
                    if self._validate_permission_change(
                        link.view_permission, new_state
                    ):
                        link.view_permission = new_state

                        # If view is revoked, also revoke edit if previously granted
                        if (
                            new_state == UserCollabStatus.WITHDRAWN and
                            link.edit_permission == UserCollabStatus.GRANTED
                        ):
                            link.edit_permission = new_state

                        from app.modules.notifications.models import NotificationType

                        if new_state == UserCollabStatus.WITHDRAWN:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_guid),
                                NotificationType.collab_revoke,
                            )
                        elif new_state == UserCollabStatus.GRANTED:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_guid),
                                NotificationType.collab_approved,
                            )

                        with db.session.begin(subtransactions=True):
                            db.session.merge(link)

                        success = True

        return success

    def user_has_view_access(self, user_guid):
        assert isinstance(user_guid, uuid.UUID)

        my_link = self._find_link_for_user(user_guid)
        peer_link = self._find_peer_link(user_guid)

        if my_link and peer_link:
            return (
                my_link.view_permission == UserCollabStatus.GRANTED and
                peer_link.view_permission == UserCollabStatus.GRANTED
            )
        return False

    def user_has_edit_access(self, user_guid):
        assert isinstance(user_guid, uuid.UUID)

        my_link = self._find_link_for_user(user_guid)
        peer_link = self._find_peer_link(user_guid)

        if my_link and peer_link:
            return (
                my_link.edit_permission == UserCollabStatus.GRANTED and
                peer_link.edit_permission == UserCollabStatus.GRANTED
            )
        return False

    def get_other_member(self, user_guid):
        peer_link = self._find_peer_link(user_guid)
        return peer_link.user if peer_link else None

    def update_edit_permission(self, user_guid, new_state):
        success = False

        if new_state not in UserCollabStatus.VALID_STATUSES:
            raise ValueError(
                f'State "{new_state}" not in allowed states: {", ".join(UserCollabStatus.VALID_STATUSES)}'
            )

        if user_guid is not None:
            assert isinstance(user_guid, uuid.UUID)

            for link in self.user_links:
                if link.user_guid == user_guid:
                    if self._validate_permission_change(
                        link.edit_permission, new_state
                    ):
                        link.edit_permission = new_state

                        with db.session.begin(subtransactions=True):
                            db.session.merge(link)

                        from app.modules.notifications.models import NotificationType

                        if new_state == UserCollabStatus.WITHDRAWN:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_guid),
                                NotificationType.collab_edit_revoke,
                            )
                        elif new_state == UserCollabStatus.GRANTED:
                            self._send_notification(
                                link,
                                self._find_peer_link(user_guid),
                                NotificationType.collab_edit_approved,
                            )

                        success = True

        return success

    def start_edit_session(self):
        self.edit_requester_guid = current_user.guid
        my_link = self._find_link_for_user(current_user.guid)
        peer_link = self._find_peer_link(current_user.guid)

        if (
            my_link.view_permission == UserCollabStatus.GRANTED and
            peer_link.view_permission == UserCollabStatus.GRANTED
        ):
            if self._validate_permission_change(
                my_link.view_permission, UserCollabStatus.GRANTED
            ):
                my_link.edit_permission = UserCollabStatus.GRANTED
                with db.session.begin(subtransactions=True):
                    db.session.merge(my_link)

            if self._validate_permission_change(
                peer_link.edit_permission, UserCollabStatus.AWAITING
            ):
                peer_link.edit_permission = UserCollabStatus.AWAITING
                with db.session.begin(subtransactions=True):
                    db.session.merge(peer_link)
        else:
            raise HoustonException(
                log, 'Cannot start edit on unapproved collaboration'
            )

    def user_can_access(self, user):
        return user in self.get_members()

    def __repr__(self):
        return (
            '<{class_name}('
            'guid={self.guid}, '
            ')>'.format(class_name=self.__class__.__name__, self=self)
        )

    def handle_user_removal(self, user_link):
        if user_link.view_permission == UserCollabStatus.ORIGINATOR:
            # Find new originator among remaining links
            remaining_links = [
                link for link in self.user_links if link != user_link
            ]
            new_originator = remaining_links[0] if remaining_links else None

            if new_originator:
                message = (
                    f'Originator removed, assigning {new_originator.user_guid} as initiator'
                )
                AuditLog.audit_log_object(log, self, message)
                self.creator_guid = new_originator.user_guid

                with db.session.begin(subtransactions=True):
                    db.session.merge(self)
                    db.session.delete(user_link)
        else:
            # Remove entire collaboration if non-originator is removed
            self.delete()

    def delete(self):
        AuditLog.delete_object(log, self)
        with db.session.begin(subtransactions=True):
            for link in self.user_links:
                db.session.delete(link)
            db.session.delete(self)

