import os
import json
import requests
from requests.exceptions import HTTPError
from dotenv import load_dotenv
import logging

# Initialize logger
logger = logging.getLogger()
logging.basicConfig(level=logging.INFO)

def __missing_env_error(var_name: str):
    """Generate error response for missing environment variable"""
    msg = f"Lambda function misconfigured: required environment variable '{var_name}' is missing."
    logger.error(msg)
    return {
        'statusCode': 500,
        'body': json.dumps(msg)
    }

def handler(event, context):
    # Load environment variables from .env file
    load_dotenv()

    # Set log level based on environment configuration
    log_level_str = os.getenv("HULL_LOG_LEVEL", "ERROR")
    numeric_level = getattr(logging, log_level_str.upper(), logging.ERROR)
    logger.setLevel(numeric_level)

    # Log incoming event
    logger.info("Hull extract requester invoked with event: %s", event)

    # Extract and validate environment variables
    logger.info("Parsing configuration from environment variables...")

    org_id = os.getenv("HULL_ORG_ID")
    connector_id = os.getenv("HULL_CONNECTOR_ID")
    connector_secret = os.getenv("HULL_CONNECTOR_SECRET")
    callback_url = os.getenv("HULL_EXPORT_CALLBACKURL")
    object_type = os.getenv("HULL_EXPORT_OBJECTTYPE")
    fields_str = os.getenv("HULL_EXPORT_FIELDS")
    es_query_str = os.getenv("HULL_EXPORT_ESQUERY")

    logger.debug("Environment variables loaded: %s", {
        "HULL_ORG_ID": org_id,
        "HULL_CONNECTOR_ID": connector_id,
        "HULL_CONNECTOR_SECRET": connector_secret,
        "HULL_EXPORT_CALLBACKURL": callback_url,
        "HULL_EXPORT_OBJECTTYPE": object_type,
        "HULL_EXPORT_FIELDS": fields_str,
        "HULL_EXPORT_ESQUERY": es_query_str
    })

    # Validate required environment variables
    if not org_id:
        return __missing_env_error("HULL_ORG_ID")
    if not connector_id:
        return __missing_env_error("HULL_CONNECTOR_ID")
    if not connector_secret:
        return __missing_env_error("HULL_CONNECTOR_SECRET")
    if not callback_url:
        return __missing_env_error("HULL_EXPORT_CALLBACKURL")
    if not object_type:
        return __missing_env_error("HULL_EXPORT_OBJECTTYPE")
    if not fields_str:
        return __missing_env_error("HULL_EXPORT_FIELDS")
    if not es_query_str:
        return __missing_env_error("HULL_EXPORT_ESQUERY")

    # Validate object type
    valid_types = ["user", "account"]
    if object_type not in valid_types:
        msg = f"Invalid object type '{object_type}'. Must be one of {valid_types}."
        logger.error(msg)
        return {
            'statusCode': 500,
            'body': json.dumps(msg)
        }

    # Prepare API request
    try:
        api_endpoint = f"https://{org_id}/api/v1/extract/{object_type}s"

        payload = {
            "url": callback_url,
            "format": "json",
            "fields": json.loads(fields_str),
            "query": json.loads(es_query_str)
        }

        headers = {
            "Accept": "application/json",
            "Hull-App-Id": connector_id,
            "Hull-Access-Token": connector_secret
        }

        logger.info("Sending extract request to Hull at '%s' with headers %s and body %s", 
                   api_endpoint, headers, payload)

        response = requests.post(api_endpoint, json=payload, headers=headers)
        logger.info("Extract request completed with status: %s %s", 
                   response.status_code, response.reason)

        response.raise_for_status()

    except HTTPError as http_err:
        logger.error("HTTP error occurred: %s", http_err)
        return {
            'statusCode': http_err.response.status_code,
            'body': json.dumps(f"HTTP error: {http_err}")
        }
    except Exception as exc:
        logger.error("Unexpected error occurred: %s", exc)
        return {
            'statusCode': 500,
            'body': json.dumps(f"Unexpected error: {exc}")
        }
    else:
        logger.info("Successfully initiated export. Results will be sent to '%s'", callback_url)
        return {
            'statusCode': 200,
            'body': json.dumps(f"Successfully initiated export. Results will be sent to '{callback_url}'")
        }

class cache:
    def __init__(
        self,
        key_gen: Callable[..., Dict[str, Any]],
        check_state_size=False,
        additional_keys: Optional[List[Callable[[Dict[str, Any]], Dict[str, Any]]]] = None,
    ):
        self.key_gen = key_gen
        self.check_state_size = check_state_size
        self.additional_keys = additional_keys or []

    def __call__(self, func):
        this = self
        async def _wrapper(self, *args, **kwargs):
            # Generate cache key arguments
            key_args = this.key_gen(*args, **kwargs)

            # Try to get from cache first
            result = await self._cache.get(**key_args)

            # Handle cache hit case
            if result is not None:
                record_cache_metric(func.__name__, "hit", result, key_args)
                return result

            # Cache miss - execute original function
            result = await func(self, *args, **kwargs)
            record_cache_metric(func.__name__, "miss", result, key_args)

            # Only proceed if we have a valid result
            if result is not None:
                # Handle empty value case
                if result == _EMPTY:
                    await self._cache.set(result, keyset=[key_args])
                else:
                    # Determine if we should store in cache based on size constraints
                    should_store = True
                    if this.check_state_size:
                        try:
                            if len(result["state"]) >= self._cache.max_cache_record_size:
                                should_store = False
                        except (TypeError, KeyError):
                            should_store = False

                    if should_store:
                        try:
                            # Build complete keyset for storage
                            keysets = [key_args]
                            for key_gen_func in this.additional_keys:
                                keysets.append(key_gen_func(result))
                            await self._cache.set(result, keyset=keysets)
                        except (TypeError, KeyError):
                            # Fallback to simple key-based storage
                            await self._cache.set(result, **key_args)

            return result

        return _wrapper

import click
import subprocess
from variables import *  # noqa: F403

@click.command()
@click.option(
    "--environment",
    default="staging",
    type=click.Choice(["staging", "prod"], case_sensitive=True),
    help="Select deployment environment"
)
@click.option(
    "--model_class", default=None, type=str, help="Specify model class for data upload"
)
def trigger_public_data_upload(environment, model_class=None):
    """Initiate public data loading command on Scalingo host."""
    # Retrieve environment configuration
    config = ENVS[environment]  # noqa: F405

    # Construct the base scalingo command
    base_cmd = (
        f"scalingo --app {config['app']} --region {config['region']} "
        "run python manage.py load_data"
    )

    # Append class specification if provided
    if model_class:
        if model_class.startswith("public_data.models"):
            full_cmd = f"{base_cmd} --class {model_class}"
        else:
            full_cmd = f"{base_cmd} --class public_data.models.{model_class}"
    else:
        full_cmd = base_cmd

    click.echo(f"Running: {full_cmd}")

    # Execute the command
    try:
        result = subprocess.run(
            full_cmd.split(),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )

        if result.stdout:
            click.secho(result.stdout, fg="green")

    except Exception as error:
        click.secho(f"Operation failed: {error}", fg="red")

if __name__ == "__main__":
    trigger_public_data_upload()

from typing import List, Dict, Any
from collections import defaultdict
from elasticsearch.exceptions import RequestError
from lucyfer.searchset.fields.mapping.base import MappingMixin


class ElasticMappingMixin(MappingMixin):
    def _build_suggestion_query(self, base_query, search_prefix: str) -> Any:
        # Construct a search query with size=0 and wildcard pattern for suggestions
        query_body = {
            "fields": self.sources,
            "query": f"*{search_prefix}*"
        }
        modified_qs = base_query.extra(size=0).query("query_string", **query_body)

        # Add term aggregations per source field
        for field in self.sources:
            modified_qs.aggs.bucket(field, "terms", field=field)
        return modified_qs

    def fetch_suggestions(self, initial_qs, search_prefix: str) -> List[str]:
        try:
            response = initial_qs.execute()
            raw_aggs = response.to_dict().get("aggregations", defaultdict(dict))
        except RequestError:
            return []

        collected_terms = []
        for field_name in self.sources:
            bucket_data = raw_aggs.get(field_name, {}).get("buckets", [])
            if bucket_data:
                # Extract keys from buckets and filter by prefix
                for item in bucket_data:
                    term_value = str(item.get("key", ""))
                    if search_prefix in term_value:
                        collected_terms.append(term_value)

        # Deduplicate and return results
        return list(set(collected_terms))

import sqlite3

class WorkDatabaseManager:
    def __init__(self) -> None:
        self.connection = sqlite3.connect("WorkDatabase.db")
        self.cursor_obj = self.connection.cursor()
        self.cursor_obj.execute(
            "CREATE TABLE IF NOT EXISTS WorkDatabase(description TEXT, category TEXT, creationDate DATE)"
        )

    def InsertWork(self, work_item):
        self.cursor_obj.execute(
            "INSERT INTO WorkDatabase(description, category, creationDate) VALUES (?, ?, ?)",
            (work_item.description, work_item.category, work_item.creationDate)
        )
        return self.cursor_obj.lastrowid

    def GetAllWorks(self):
        return self.cursor_obj.execute("SELECT rowid, * FROM WorkDatabase").fetchall()

    def __del__(self):
        self.connection.commit()
        self.connection.close()

