import oneflow as flow
from oneflow_gpt.model import Embedding, LayerNorm
from oneflow_gpt.model import ColumnParallelLinear, RowParallelLinear

def create_gradient_scaler(config):
    if hasattr(config, 'loss_scale') and config.loss_scale is not None:
        return flow.amp.StaticGradScaler(config.loss_scale)
    elif hasattr(config, 'initial_loss_scale') and config.initial_loss_scale is not None:
        return flow.amp.GradScaler(
            init_scale=config.initial_loss_scale,
            growth_factor=2.0,
            backoff_factor=0.5,
            growth_interval=config.loss_scale_window,
        )
    else:
        return None

def build_lr_scheduler(config, optimizer):
    assert config.lr_decay_style in ("none", "cosine")

    if config.lr_decay_style == "none":
        return None

    if not hasattr(config, 'lr_decay_iters') or config.lr_decay_iters is None:
        return None

    min_lr_ratio = config.min_lr / config.lr
    cosine_scheduler = flow.optim.lr_scheduler.CosineDecayLR(
        optimizer, 
        decay_steps=config.lr_decay_iters, 
        alpha=min_lr_ratio,
    )

    if hasattr(config, 'lr_warmup_iters') and config.lr_warmup_iters is not None and config.lr_warmup_iters > 0:
        warmup_scheduler = flow.optim.lr_scheduler.WarmUpLR(
            cosine_scheduler,
            warmup_factor=0,
            warmup_iters=config.lr_warmup_iters,
            warmup_method="linear",
        )
        return warmup_scheduler

    return cosine_scheduler

def extract_weight_decay_param_groups(model):
    weight_decay_group = {"params": []}
    no_weight_decay_group = {"params": [], "weight_decay": 0.0}

    for module in model.modules():
        if isinstance(module, Embedding):
            for param in module.parameters(recurse=False):
                if param is not None:
                    weight_decay_group["params"].append(param)
        elif isinstance(module, LayerNorm):
            for param in module.parameters(recurse=False):
                if param is not None:
                    no_weight_decay_group["params"].append(param)
        elif isinstance(module, (ColumnParallelLinear, RowParallelLinear)):
            for name, param in module.named_parameters(recurse=False):
                if param is None:
                    continue
                if name == "weight":
                    weight_decay_group["params"].append(param)
                elif name == "bias":
                    no_weight_decay_group["params"].append(param)
                else:
                    raise ValueError(f"Unexpected parameter '{name}' in {module.__class__.__name__}")
        else:
            # Ensure no unexpected parameters exist in other modules
            assert len(list(module.parameters(recurse=False))) == 0

    return [weight_decay_group, no_weight_decay_group]

def apply_gradient_clipping_to_groups(param_groups, grad_clip_value):
    if int(grad_clip_value) == 1:
        for group in param_groups:
            group["clip_grad_max_norm"] = 1.0
            group["clip_grad_norm_type"] = 2.0

def construct_optimizer(config, model):
    param_list = extract_weight_decay_param_groups(model)
    apply_gradient_clipping_to_groups(param_list, config.clip_grad)

    if config.optimizer == "adamw":
        opt = flow.optim.AdamW(
            param_list,
            lr=config.lr,
            weight_decay=config.weight_decay,
            betas=(config.adam_beta1, config.adam_beta2),
            eps=config.adam_eps,
        )
    elif config.optimizer == "sgd":
        opt = flow.optim.SGD(param_list, lr=config.lr)
    else:
        raise NotImplementedError("Optimizer type not supported")

    return opt

