from __future__ import annotations
from typing import Dict, List, Any, Optional, Union
import numpy as np
import paddle
from paddle.io import Dataset, Sampler, DataLoader
from paddle.metric import Metric, Accuracy, Precision, Recall
from paddlenlp.transformers.tokenizer_utils import PretrainedTokenizer
from paddle_prompt.config import Tensor


def encode_sample(
    sample: dict,
    tokenizer: PretrainedTokenizer,
    label_mapping: Dict[str, int],
    max_len: int = 512,
    phase: str = 'training'
) -> tuple:
    """Transforms a single data sample into model-ready tensors.

    Args:
        sample (dict): Input dictionary containing 'text', optionally 'text_pair' and 'label'.
        tokenizer (PretrainedTokenizer): Tokenizer to process text.
        label_mapping (Dict[str, int]): Maps string labels to integer indices.
        max_len (int, optional): Maximum sequence length. Defaults to 512.
        phase (str, optional): Execution context ('train' or 'test'). Defaults to 'training'.
    """
    # Tokenize input(s)
    tokenized = tokenizer(
        text=sample['text'],
        text_pair=sample.get('text_pair'),
        max_seq_len=max_len,
        pad_to_max_seq_len=True
    )

    ids = tokenized["input_ids"]
    type_ids = tokenized["token_type_ids"]

    if phase == 'inference':
        return ids, type_ids

    # Convert label to index and wrap in array
    y_idx = label_mapping[sample['label']]
    label_arr = np.array([y_idx], dtype=np.int64)
    return ids, type_ids, label_arr


def build_dataloader(
    data: Dataset,
    mode: str = 'training',
    batch_size: int = 16,
    collator=None,
    preprocessor=None
) -> DataLoader:
    """Constructs a PaddlePaddle DataLoader from a dataset.

    Args:
        data (Dataset): Source dataset.
        mode (str, optional): Mode ('training' or otherwise). Affects shuffling & sampling strategy.
        batch_size (int, optional): Batch size per iteration. Defaults to 16.
        collator (_type_, optional): Function to merge samples into batches. Defaults to None.
        preprocessor (_type_, optional): Optional transformation applied before batching. Defaults to None.
    """
    if preprocessor:
        data = data.map(preprocessor)

    if mode == 'training':
        sampler = paddle.io.DistributedBatchSampler(
            data, batch_size=batch_size, shuffle=True
        )
    else:
        sampler = paddle.io.BatchSampler(
            data, batch_size=batch_size
        )

    return DataLoader(
        dataset=data,
        batch_sampler=sampler,
        collate_fn=collator,
        return_list=True
    )


def gather_fields_from_batch(
    batch_features: List[Dict[str, Any]], field_names: List[str]
) -> List[np.ndarray]:
    """Extract specified fields from list of dictionaries (e.g., tokenized outputs).

    Handles both old-style tokenizer output and newer formats.

    Args:
        batch_features (List[Dict[str, Any]]): List of feature dicts.
        field_names (List[str]): Keys to extract.

    Returns:
        List[np.ndarray]: Extracted arrays in same order as field_names.
    """
    if isinstance(batch_features, dict):
        return [batch_features[f] for f in field_names]

    extracted = {}
    for key in field_names:
        vals = [item[key] for item in batch_features]
        extracted[key] = np.asarray(vals)

    return [extracted[f] for f in field_names]


def scalar_value(x: Any) -> float:
    """Converts tensor-like objects to scalar floats."""
    if paddle.is_tensor(x):
        x = paddle.sum(x)
        return float(x.detach().cpu().numpy())
    return float(x)


def to_native_list(x: Any) -> List[float]:
    """Converts tensor or array-like to native Python list."""
    if paddle.is_tensor(x):
        return x.detach().cpu().numpy().tolist()
    return list(x)


def pack_into_tensors(
    feature_lists: List[List[Any]],
    device: Optional[paddle.CUDAPlace | paddle.CPUPlace] = None
) -> List[Tensor]:
    """Converts nested lists into Paddle Tensors on specified device."""
    kwargs = {'place': device} if device is not None else {}
    return [paddle.to_tensor(fl, **kwargs) for fl in feature_lists]


def instantiate_metric(metric_name: str, **params) -> Metric:
    """Factory function to create metric instances by name."""
    if metric_name == 'accuracy':
        return Accuracy(**params)
    elif metric_name == 'precision_score':
        return Precision(**params)
    elif metric_name == 'recall_score':
        return Recall(**params)
    else:
        raise ValueError(f"Unsupported metric: {metric_name}")

