class TextGenie:
    def __init__(
        self,
        paraphrase_model_name,
        mask_model_name=None,
        spacy_model_name="en_core_web_sm",
        device="cpu",
    ):
        tqdm.write("Loading Paraphrase Model..")
        self.paraphrase_model = T5ForConditionalGeneration.from_pretrained(
            paraphrase_model_name
        )
        self.paraphrase_tokenizer = T5Tokenizer.from_pretrained(paraphrase_model_name)
        self.paraphrase_model = self.paraphrase_model.to(device)
        self.device = device

        if mask_model_name:
            tqdm.write("Loading Mask Fill Model..")
            from transformers import pipeline
            import spacy
            self.mask_augmenter = pipeline("fill-mask", model=mask_model_name)
            self.nlp = spacy.load(spacy_model_name)

    def extract_keywords(self, sentence):
        result = []
        target_pos_tags = ["PROPN", "NOUN", "ADJ"]
        special_tags = ["NUM"]
        target_pos_tags += special_tags

        doc = self.nlp(sentence)
        for token in doc:
            # Skip stopwords and punctuation unless they are special tags
            if (token.text in self.nlp.Defaults.stop_words or token.text in punctuation) and token.pos_ not in special_tags:
                continue
            if token.pos_ in target_pos_tags:
                result.append(token.text)
        return list(set(result))

    def augment_sent_mask_filling(self, sent, n_predictions=5):
        keywords = self.extract_keywords(sent)
        augmented_sents = []

        for keyword in keywords:
            masked_text = sent.replace(keyword, self.mask_augmenter.tokenizer.mask_token, 1)
            predictions = self.mask_augmenter(masked_text, top_k=n_predictions)

            for pred in predictions:
                candidate = pred["sequence"]
                if candidate.lower() != sent.lower():
                    augmented_sents.append(candidate)

        return list(set(augmented_sents))

    def augment_sent_t5(self, sent, prefix, n_predictions=5, top_k=120, max_length=256):
        text = prefix + sent + " </s>"
        encoding = self.paraphrase_tokenizer.encode_plus(
            text, pad_to_max_length=True, return_tensors="pt"
        )
        input_ids = encoding["input_ids"].to(self.device)
        attention_mask = encoding["attention_mask"].to(self.device)

        generated_sequences = self.paraphrase_model.generate(
            input_ids=input_ids,
            attention_mask=attention_mask,
            do_sample=True,
            max_length=max_length,
            top_k=top_k,
            top_p=0.98,
            early_stopping=True,
            num_return_sequences=n_predictions,
        )

        final_outputs = []
        for seq in generated_sequences:
            decoded = self.paraphrase_tokenizer.decode(
                seq, skip_special_tokens=True, clean_up_tokenization_spaces=True
            )
            if decoded.lower() != sent.lower() and decoded not in final_outputs:
                final_outputs.append(decoded)
        return final_outputs

    def convert_to_active(self, sent):
        if is_passive(sent):
            return pass2act(sent)
        else:
            return sent

    def magic_once(
        self,
        sent,
        paraphrase_prefix,
        n_paraphrase_predictions=5,
        paraphrase_top_k=120,
        paraphrase_max_length=256,
        n_mask_predictions=None,
        convert_to_active=True,
    ):
        sent = sent.strip()
        results = []

        # Generate paraphrases using T5
        t5_results = self.augment_sent_t5(
            sent,
            paraphrase_prefix,
            n_paraphrase_predictions,
            paraphrase_top_k,
            paraphrase_max_length,
        )
        results.extend(t5_results)

        # Generate masked predictions if requested
        if isinstance(n_mask_predictions, int) and n_mask_predictions > 0:
            mask_results = self.augment_sent_mask_filling(sent, n_mask_predictions)
            results.extend(mask_results)

        # Convert to active voice if needed
        if convert_to_active:
            active_version = self.convert_to_active(sent)
            if active_version.lower() != sent.lower():
                results.append(active_version)

        return list(set(results))

    def magic_lamp(
        self,
        sentences,
        paraphrase_prefix,
        n_paraphrase_predictions=5,
        paraphrase_top_k=120,
        paraphrase_max_length=256,
        n_mask_predictions=None,
        convert_to_active=True,
        label_column=None,
        data_column=None,
        column_names=None,
    ):
        all_sentences = None
        with_labels = False
        output_file = os.path.join(os.getcwd(), "sentences_aug.txt")

        # Handle string input (file path)
        if isinstance(sentences, str):
            full_path = os.path.join(os.getcwd(), sentences)

            if full_path.endswith(".txt"):
                with open(full_path, 'r') as f:
                    all_sentences = f.read().strip().split("\n")

            elif full_path.endswith(".csv") or full_path.endswith(".tsv"):
                if not label_column:
                    raise Exception(
                        "Please provide the column name that contains labels using the 'label_column' parameter."
                    )
                if not data_column:
                    raise Exception(
                        "Please provide the column name that contains data using the 'data_column' parameter."
                    )
                if column_names and not isinstance(column_names, list):
                    raise Exception("Please provide column names in a python list.")

                output_file = (
                    full_path.replace(".csv", "").replace(".tsv", "") + "_aug.tsv"
                )
                with_labels = True

                try:
                    if full_path.endswith(".csv"):
                        if column_names:
                            all_sentences = pd.read_csv(full_path, names=column_names)
                        else:
                            all_sentences = pd.read_csv(full_path)
                    elif full_path.endswith(".tsv"):
                        if column_names:
                            all_sentences = pd.read_csv(full_path, names=column_names, sep="\t")
                        else:
                            all_sentences = pd.read_csv(full_path, sep="\t")
                except Exception as e:
                    raise Exception(f"Error reading file: {e}")

                # Validate columns
                if label_column not in all_sentences.columns:
                    raise Exception(
                        "Please provide label column name for the dataset using the 'label_column' parameter."
                    )
                if data_column not in all_sentences.columns:
                    raise Exception(
                        "Please provide data column name for the dataset using the 'data_column' parameter."
                    )

                # Drop header row if it was used as column names
                if all_sentences.iloc[0].tolist() == column_names:
                    all_sentences = all_sentences.drop(0).reset_index(drop=True)

                # Process each row
                labels = all_sentences[label_column].unique()
                augmented_data = []

                for idx in tqdm(range(all_sentences.shape[0])):
                    original_text = all_sentences[data_column][idx].strip()
                    label = all_sentences[label_column][idx].strip()

                    augmented_texts = self.magic_once(
                        original_text,
                        paraphrase_prefix,
                        n_paraphrase_predictions,
                        paraphrase_top_k,
                        paraphrase_max_length,
                        n_mask_predictions,
                        convert_to_active,
                    )

                    for aug_text in augmented_texts:
                        augmented_data.append([aug_text, label])

                # Save results
                augmented_df = pd.DataFrame(data=augmented_data, columns=["Text", "Label"])
                augmented_df.to_csv(output_file, sep="\t", index=None)

            else:
                raise Exception(
                    "Unsupported file format. Currently, following formats are supported: txt/csv/tsv"
                )

        elif isinstance(sentences, list):
            all_sentences = sentences

        if all_sentences is None:
            raise Exception("Error: No sentences found.")

        # Process without labels
        if not with_labels:
            augmented_data = []
            for sent in tqdm(all_sentences):
                augmented_texts = self.magic_once(
                    sent,
                    paraphrase_prefix,
                    n_paraphrase_predictions,
                    paraphrase_top_k,
                    paraphrase_max_length,
                    n_mask_predictions,
                    convert_to_active,
                )
                augmented_data.extend(augmented_texts)

            with open(output_file, "w") as f:
                for line in augmented_data:
                    f.write(line + "\n")

        tqdm.write(f"\nCompleted writing output to {output_file}.")
        return augmented_data

import collections
from typing import Iterable, Optional, Sequence
from absl import logging

class Vocabulary:
  """A class to manage vocabulary construction and loading."""

  def __init__(self,
               vocab_file: Optional[str] = None,
               sequences: Optional[Iterable[Sequence[bytes]]] = None,
               min_count: int = 1,
               padding_token: bytes = b'<pad>',
               unknown_token: bytes = b'<unk>',
               start_token: bytes = b'<s>',
               end_token: bytes = b'</s>'):
    """Initialize vocabulary either by loading from file or constructing from data."""
    self.padding_token = padding_token
    self.unknown_token = unknown_token
    self.start_token = start_token
    self.end_token = end_token
    self.special_tokens = (padding_token, unknown_token, start_token, end_token)

    if vocab_file is not None:
      self.import_from_file(vocab_file)
    elif sequences is not None:
      self.construct(sequences, min_count=min_count)
    else:
      raise ValueError(
          ('Vocabulary requires either `vocab_file` or `sequences` to be provided, '
           'got %r and %r.') % (vocab_file, sequences))

  def construct(self,
                sequences: Iterable[Sequence[bytes]],
                min_count: int = 1):
    """Build vocabulary from token sequences with frequency threshold.

    Args:
      sequences: Collection of tokenized sequences for vocabulary building.
      min_count: Minimum occurrence count required for inclusion. Default: 1.
    """
    # Count occurrences of each token
    token_counts = collections.Counter()
    for seq in sequences:
      token_counts.update(seq)

    # Initialize ordered dictionary with special tokens first
    vocab_dict = collections.OrderedDict()
    for token in self.special_tokens:
      vocab_dict[token] = len(vocab_dict)

    # Add regular tokens sorted by descending frequency, then alphabetically
    for token, count in sorted(
        token_counts.items(),
        key=lambda item: (-item[1], item[0])):
      if count >= min_count:
        vocab_dict[token] = len(vocab_dict)

    logging.info('Total unique tokens observed: %d', len(token_counts))
    logging.info('Final vocabulary size (after filtering): %d', len(vocab_dict))
    self.vocab_dict = vocab_dict

  def __getitem__(self, token: str) -> int:
    return self.vocab_dict[token]

  def get_all_tokens(self):
    return list(self.vocab_dict.keys())

  def get_all_indices(self):
    return list(self.vocab_dict.values())

  def __len__(self):
    return len(self.vocab_dict)

  @property
  def pad_id(self):
    """Return index of padding token."""
    return self.vocab_dict[self.padding_token]

  @property
  def unk_id(self):
    """Return index of unknown token."""
    return self.vocab_dict[self.unknown_token]

  @property
  def bos_id(self):
    """Return index of beginning-of-sequence token."""
    return self.vocab_dict[self.start_token]

  @property
  def eos_id(self):
    """Return index of end-of-sequence token."""
    return self.vocab_dict[self.end_token]

  def import_from_file(self, filepath: str) -> None:
    """Load vocabulary from a text file (one token per line)."""
    vocab_dict = collections.OrderedDict()
    with open(filepath, 'rb') as file:
      for idx, line in enumerate(file):
        token = line.rstrip(b'\n\r')
        assert isinstance(token, bytes), 'Tokens must be byte strings.'
        vocab_dict[token] = idx

    logging.info('Successfully loaded vocabulary from %s, size: %d', filepath, len(vocab_dict))
    self.vocab_dict = vocab_dict

  def export_to_file(self, filepath: str) -> None:
    """Save vocabulary to a text file (one token per line)."""
    with open(filepath, 'wb') as file:
      for token in self.vocab_dict:
        assert isinstance(token, bytes), 'Tokens must be byte strings.'
        file.write(token + b'\n')
    logging.info('Vocabulary saved to %s.', filepath)

# Abstract base class for terminal renderers with context management support

from __future__ import annotations
from abc import ABC, abstractmethod
from contextlib import contextmanager
from dataclasses import dataclass, field
from types import TracebackType
from typing import ContextManager, Generator, Optional, Text, Type, TypeVar
from ..messages import Event

T = TypeVar("T", bound="TerminalRenderer")

@dataclass  # type: ignore
class TerminalRenderer(ContextManager["TerminalRenderer"], ABC):
    """Base class for terminal rendering implementations."""
    enable_fullscreen: bool = field(default=True, init=False)
    """Flag indicating if fullscreen display mode is active."""

    @abstractmethod
    def draw(self, content: Text) -> None:
        """Display the given content on the terminal."""
        raise NotImplementedError("Subclasses must implement the draw method")

    @abstractmethod
    def poll_event(self) -> Optional[Event]:
        """Non-blocking check for the next terminal input event."""
        raise NotImplementedError("Subclasses must implement the poll_event method")

    @abstractmethod
    def __enter__(self: T) -> T:
        """
        Initialize renderer resources when entering context.
        Should set up necessary terminal states.
        """
        raise NotImplementedError("Subclasses must implement __enter__")

    @abstractmethod
    def __exit__(
        self,
        exception_type: Optional[Type[BaseException]],
        exception_value: Optional[BaseException],
        traceback: Optional[TracebackType],
    ) -> Optional[bool]:
        """
        Clean up renderer resources when exiting context.
        Should restore terminal to previous state.
        """
        raise NotImplementedError("Subclasses must implement __exit__")

    @abstractmethod
    @contextmanager
    def switch_to_raw_input(self: T) -> Generator[T, None, None]:
        """Context manager for switching terminal to raw input mode."""
        raise NotImplementedError("Subclasses must implement switch_to_raw_input")

    @abstractmethod
    @contextmanager
    def disable_cursor_display(self: T) -> Generator[T, None, None]:
        """Context manager for temporarily hiding the cursor."""
        raise NotImplementedError("Subclasses must implement disable_cursor_display")

