# A utility module for formatting various Python objects into readable,
# markdown-friendly strings—especially useful for logging, error messages,
# or CLI output. No external dependencies beyond the standard library.

from typing import Sequence, Callable, Any, Iterable, Union
import inspect
from pathlib import Path
import shlex


def inline_code(value: str) -> str:
    """Wrap a string in backticks to render as inline code in Markdown."""
    return f"`{value}`"


def format_type(cls: type) -> str:
    """Format a class object as a Markdown inline code string, with full module path unless built-in."""
    if cls.__module__ == "builtins":
        return inline_code(cls.__name__)
    return inline_code(f"{cls.__module__}.{cls.__name__}")


def format_file_path(path_obj: Path) -> str:
    """Format a pathlib.Path as Markdown inline code."""
    return inline_code(str(path_obj))


def format_command(
    cmd_sequence: Iterable[str],
    *,
    max_line_length: int = 80,
    indentation: Union[str, int] = "  "
) -> str:
    """
    Format a command (list of arguments) as a multi-line shell snippet,
    inserting line continuations (`\`) when needed to stay within `max_line_length`.
    """
    if isinstance(indentation, int):
        indentation = " " * indentation

    lines = [""]
    for arg in cmd_sequence:
        quoted_arg = shlex.quote(arg)
        # Check if adding this token would exceed line length (accounting for space + backslash)
        if len(lines[-1]) + 1 + len(quoted_arg) > max_line_length - 2:
            lines[-1] += " \\"
            lines.append(indentation)
        # Add space before appending only if current line isn't empty/whitespace-only
        if not lines[-1].isspace():
            lines[-1] += " "
        lines[-1] += quoted_arg

    return "\n".join(lines)


def smart_format(obj: Any) -> str:
    """Dispatch formatting based on object type: classes, paths, or generic repr."""
    if inspect.isclass(obj):
        return format_type(obj)
    if isinstance(obj, Path):
        return format_file_path(obj)
    return repr(obj)


def join_with_conjunction(
    items: Sequence,
    connector: str,
    *,
    converter: Callable[[Any], str] = smart_format,
    separator: str = ",",
) -> str:
    """
    Join a sequence of items using natural language conventions:
    - Empty list → "[empty]"
    - One item → just the item
    - Two items → "item1 and item2"
    - Three+ items → "item1, item2 and item3"

    Example:
        >>> join_with_conjunction([1, 2, 3], "and")
        '1, 2 and 3'
    """
    count = len(items)
    if count == 0:
        return "[empty]"
    if count == 1:
        return converter(items[0])

    first_part = separator.join(converter(item) for item in items[:-1])
    last_part = converter(items[-1])
    return f"{first_part} {connector} {last_part}"

import dataclasses
from typing import Optional, Dict, Set, Tuple, List
import stim

# Replaced set literals with frozensets for immutability and clarity
CLIFFORD_1_OPS = frozenset({"C_XYZ", "C_ZYX", "H", "H_YZ", "I"})
CLIFFORD_2_OPS = frozenset({"CX", "CY", "CZ", "XCX", "XCY", "XCZ", "YCX", "YCY", "YCZ"})
RESET_OPS = frozenset({"R", "RX", "RY"})
MEASURE_OPS = frozenset({"M", "MX", "MY"})
ANNOTATION_OPS = frozenset({"OBSERVABLE_INCLUDE", "DETECTOR", "SHIFT_COORDS", "QUBIT_COORDS", "TICK"})


@dataclasses.dataclass(frozen=True)
class NoiseModel:
    idle: float
    measure_reset_idle: float
    noisy_gates: Dict[str, float]
    any_clifford_1: Optional[float] = None
    any_clifford_2: Optional[float] = None
    use_correlated_parity_measurement_errors: bool = False

    @staticmethod
    def SD6(p: float) -> 'NoiseModel':
        return NoiseModel(
            any_clifford_1=p,
            idle=p,
            measure_reset_idle=0.0,
            noisy_gates={
                "CX": p,
                "R": p,
                "M": p,
            },
        )

    @staticmethod
    def PC3(p: float) -> 'NoiseModel':
        return NoiseModel(
            any_clifford_1=p,
            any_clifford_2=p,
            idle=p,
            measure_reset_idle=0.0,
            noisy_gates={
                "R": p,
                "M": p,
            },
        )

    @staticmethod
    def EM3_v1(p: float) -> 'NoiseModel':
        """EM3 variant 1: independent measurement flip errors."""
        return NoiseModel(
            idle=p,
            measure_reset_idle=0.0,
            any_clifford_1=p,
            noisy_gates={
                "R": p,
                "M": p,
                "MPP": p,
            },
        )

    @staticmethod
    def EM3_v2(p: float) -> 'NoiseModel':
        """EM3 variant 2: correlated measurement flip errors."""
        return NoiseModel(
            any_clifford_1=0.0,
            any_clifford_2=0.0,
            idle=p,
            measure_reset_idle=0.0,
            use_correlated_parity_measurement_errors=True,
            noisy_gates={
                "R": p / 2,
                "M": p / 2,
                "MPP": p,
            },
        )

    @staticmethod
    def SI1000(p: float) -> 'NoiseModel':
        return NoiseModel(
            any_clifford_1=p / 10,
            idle=p / 10,
            measure_reset_idle=2 * p,
            noisy_gates={
                "CZ": p,
                "R": 2 * p,
                "M": 5 * p,
            },
        )

    def _apply_noise_to_single_qubit_gate(self, op: stim.CircuitInstruction, prob: float) -> Tuple[stim.Circuit, stim.Circuit, stim.Circuit]:
        pre = stim.Circuit()
        mid = stim.Circuit()
        post = stim.Circuit()
        targets = op.targets_copy()
        args = op.gate_args_copy()
        if prob > 0:
            post.append_operation("DEPOLARIZE1", targets, prob)
        mid.append_operation(op.name, targets, args)
        return pre, mid, post

    def _apply_noise_to_two_qubit_gate(self, op: stim.CircuitInstruction, prob: float) -> Tuple[stim.Circuit, stim.Circuit, stim.Circuit]:
        pre = stim.Circuit()
        mid = stim.Circuit()
        post = stim.Circuit()
        targets = op.targets_copy()
        args = op.gate_args_copy()
        if prob > 0:
            post.append_operation("DEPOLARIZE2", targets, prob)
        mid.append_operation(op.name, targets, args)
        return pre, mid, post

    def _apply_noise_to_reset_or_measure(self, op: stim.CircuitInstruction, prob: float) -> Tuple[stim.Circuit, stim.Circuit, stim.Circuit]:
        pre = stim.Circuit()
        mid = stim.Circuit()
        post = stim.Circuit()
        targets = op.targets_copy()
        args = op.gate_args_copy()

        # Determine error type based on gate suffix
        is_x_target = op.name.endswith("X")
        error_type = "Z_ERROR" if is_x_target else "X_ERROR"

        if op.name in RESET_OPS:
            post.append_operation(error_type, targets, prob)
        if op.name in MEASURE_OPS:
            pre.append_operation(error_type, targets, prob)

        mid.append_operation(op.name, targets, args)
        return pre, mid, post

    def _apply_noise_to_mpp(self, op: stim.CircuitInstruction, prob: float, ancilla: int) -> Tuple[stim.Circuit, stim.Circuit, stim.Circuit]:
        pre = stim.Circuit()
        mid = stim.Circuit()
        post = stim.Circuit()
        targets = op.targets_copy()
        args = op.gate_args_copy()

        assert len(targets) % 3 == 0 and all(t.is_combiner for t in targets[1::3]), repr(op)
        assert args == [] or args == [0]

        if self.use_correlated_parity_measurement_errors:
            for k in range(0, len(targets), 3):
                mid += parity_measurement_with_correlated_measurement_noise(
                    t1=targets[k],
                    t2=targets[k + 2],
                    ancilla=ancilla,
                    mix_probability=prob)
            return pre, mid, post
        else:
            depol_targets = [t.value for t in targets if not t.is_combiner]
            pre.append_operation("DEPOLARIZE2", depol_targets, prob)
            args = [prob]
            mid.append_operation(op.name, targets, args)
            return pre, mid, post

    def noisy_op(self, op: stim.CircuitInstruction, p: float, ancilla: int) -> Tuple[stim.Circuit, stim.Circuit, stim.Circuit]:
        if p <= 0:
            return stim.Circuit(), stim.Circuit([op]), stim.Circuit()

        if op.name in CLIFFORD_1_OPS:
            return self._apply_noise_to_single_qubit_gate(op, p)
        elif op.name in CLIFFORD_2_OPS:
            return self._apply_noise_to_two_qubit_gate(op, p)
        elif op.name in RESET_OPS or op.name in MEASURE_OPS:
            return self._apply_noise_to_reset_or_measure(op, p)
        elif op.name == "MPP":
            return self._apply_noise_to_mpp(op, p, ancilla)
        else:
            raise NotImplementedError(repr(op))

    def noisy_circuit(self, circuit: stim.Circuit, *, qs: Optional[Set[int]] = None) -> stim.Circuit:
        result = stim.Circuit()
        ancilla = circuit.num_qubits
        current_moment_pre = stim.Circuit()
        current_moment_mid = stim.Circuit()
        current_moment_post = stim.Circuit()
        used_qubits: Set[int] = set()
        measured_or_reset_qubits: Set[int] = set()

        if qs is None:
            qs = set(range(circuit.num_qubits))

        def flush():
            nonlocal result
            if not current_moment_mid:
                return

            # Idle depolarization
            idle_qubits = sorted(qs - used_qubits)
            if used_qubits and idle_qubits and self.idle > 0:
                current_moment_post.append_operation("DEPOLARIZE1", idle_qubits, self.idle)

            idle_qubits = sorted(qs - measured_or_reset_qubits)
            if measured_or_reset_qubits and idle_qubits and self.measure_reset_idle > 0:
                current_moment_post.append_operation("DEPOLARIZE1", idle_qubits, self.measure_reset_idle)

            result += current_moment_pre + current_moment_mid + current_moment_post
            used_qubits.clear()
            measured_or_reset_qubits.clear()
            current_moment_pre.clear()
            current_moment_mid.clear()
            current_moment_post.clear()

        for op in circuit:
            if isinstance(op, stim.CircuitRepeatBlock):
                flush()
                noisy_body = self.noisy_circuit(op.body_copy(), qs=qs)
                result += noisy_body * op.repeat_count
            elif isinstance(op, stim.CircuitInstruction):
                if op.name == "TICK":
                    flush()
                    result.append_operation("TICK", [])
                    continue

                # Determine noise probability
                if op.name in self.noisy_gates:
                    p = self.noisy_gates[op.name]
                elif self.any_clifford_1 is not None and op.name in CLIFFORD_1_OPS:
                    p = self.any_clifford_1
                elif self.any_clifford_2 is not None and op.name in CLIFFORD_2_OPS:
                    p = self.any_clifford_2
                elif op.name in ANNOTATION_OPS:
                    p = 0.0
                else:
                    raise NotImplementedError(repr(op))

                pre, mid, post = self.noisy_op(op, p, ancilla)
                current_moment_pre += pre
                current_moment_mid += mid
                current_moment_post += post

                # Track touched qubits
                touched_qubits = {
                    t.value
                    for t in op.targets_copy()
                    if t.is_x_target or t.is_y_target or t.is_z_target or t.is_qubit_target
                }
                if op.name in ANNOTATION_OPS:
                    touched_qubits.clear()
                used_qubits.update(touched_qubits)

                if op.name in MEASURE_OPS or op.name in RESET_OPS:
                    measured_or_reset_qubits.update(touched_qubits)
            else:
                raise NotImplementedError(repr(op))

        flush()
        return result


def mix_probability_to_independent_component_probability(mix_probability: float, n: float) -> float:
    """Converts full-mixing probability to per-component independent application probability.

    Ensures that independently applying each component with returned probability yields
    same effect as uniformly sampling one component with probability `mix_probability`.
    Note: identity is included among possible components.
    """
    exponent = 2 ** (n - 1)
    base = 1 - mix_probability
    return 0.5 - 0.5 * (base ** (1.0 / exponent))


def parity_measurement_with_correlated_measurement_noise(
        *,
        t1: stim.GateTarget,
        t2: stim.GateTarget,
        ancilla: int,
        mix_probability: float) -> stim.Circuit:
    """Performs a noisy parity measurement with correlated errors."""
    ind_p = mix_probability_to_independent_component_probability(mix_probability, 5)
    circuit = stim.Circuit()

    # Prepare ancilla
    circuit.append_operation('R', [ancilla])

    # Entangle ancilla with data qubits based on Pauli basis
    basis_ops = {
        'x': ('XCX', stim.target_x),
        'y': ('YCX', stim.target_y),
        'z': ('ZCX', stim.target_z),
    }

    for target, (gate_name, target_factory) in [(t1, basis_ops), (t2, basis_ops)]:
        for basis_char, (gate, factory) in basis_ops.items():
            if getattr(target, f"is_{basis_char}_target"):
                circuit.append_operation(gate, [target.value, ancilla])

    # Generate error combinations
    first_basis = ["I", stim.target_x(t1.value), stim.target_y(t1.value), stim.target_z(t1.value)]
    second_basis = ["I", stim.target_x(t2.value), stim.target_y(t2.value), stim.target_z(t2.value)]
    measure_basis = ["I", stim.target_x(ancilla)]

    error_combinations = []
    for f in first_basis:
        for s in second_basis:
            for m in measure_basis:
                err_list = []
                if f != "I":
                    err_list.append(f)
                if s != "I":
                    err_list.append(s)
                if m != "I":
                    err_list.append(m)
                if err_list:
                    error_combinations.append(err_list)

    # Apply correlated errors
    for err_combo in error_combinations:
        circuit.append_operation("CORRELATED_ERROR", err_combo, ind_p)

    # Final measurement
    circuit.append_operation('M', [ancilla])
    return circuit

