log = logging.getLogger(__name__)

# Renamed constants and reorganized structure for clarity
CONTAINER_UPDATE_PARAMETERS = [
    # (inspect_field, config_param, check_in_create_opts, requires_client_support, converter_func)
    ('BlkioWeight', 'blkio_weight', False, False, None),
    ('CpuPeriod', 'cpu_period', False, True, None),
