]

def _verify_environment(container_config, container_details):
    def _extract_env_vars():
        for env_entry in container_env_list:
            name_part, _, value_part = env_entry.partition('=')
            if value_part:
                yield name_part, value_part

    creation_opts = init_options(container_config.create_options)
    if not creation_opts:
        return True

    container_env_list = container_details['Config'].get('Env') or []
    configured_env = resolve_value(creation_opts.get('environment'))
    if not configured_env:
        return True

    current_env_dict = dict(_extract_env_vars())
    log.debug("Verifying environment variables. Config vs Instance:\n%s\n%s", configured_env, current_env_dict)

    for key, expected_val in six.iteritems(configured_env):
        actual_val = current_env_dict.get(key)
        if actual_val != resolve_value(expected_val):
            return False
    return True

def _clean_quoted_string(cmd_segment):
    if len(cmd_segment) >= 2 and cmd_segment[0] == cmd_segment[-1] and cmd_segment[0] in ("'", '"'):
        return cmd_segment[1:-1]
    return cmd_segment

def _standardize_command(cmd_input):
    if isinstance(cmd_input, six.string_types):
        cmd_input = shlex.split(cmd_input)
    return [cmd_cleaner(s) for s in cmd_input]

def _check_command(container_config, container_details):
    creation_opts = init_options(container_config.create_options)
    if not creation_opts:
        return True

    instance_config = container_details['Config']
    config_cmd = resolve_value(creation_opts.get('command')) if creation_opts else None

    if config_cmd:
        instance_cmd = instance_config.get('Cmd') or []
        log.debug("Checking command. Config / Instance:\n%s\n%s", config_cmd, instance_cmd)
        if _standardize_command(config_cmd) != instance_cmd:
            return False

    config_entrypoint = resolve_value(creation_opts.get('entrypoint')) if creation_opts else None
    if config_entrypoint:
        instance_entrypoint = instance_config.get('Entrypoint') or []
        log.debug("Checking entrypoint. Config / Instance:\n%s\n%s", config_entrypoint, instance_entrypoint)

        if isinstance(config_entrypoint, six.string_types):
            if [config_entrypoint] != instance_entrypoint:
                return False
        elif list(config_entrypoint) != instance_entrypoint:
            return False

    return True

def _validate_network_ports(container_config, client_config, container_details):
    if not container_config.exposes:
        return True

    instance_ports = container_details['NetworkSettings'].get('Ports') or {}

    for port_binding in container_config.exposes:
        exposed_port = resolve_value(port_binding.exposed_port)
        port_key = exposed_port if isinstance(exposed_port, six.string_types) and '/' in exposed_port else '{0}/tcp'.format(exposed_port)
        log.debug("Verifying port configuration: %s", port_key)

        if port_key not in instance_ports:
            log.debug("Port not found.")
            return False

        host_port = resolve_value(port_binding.host_port)
        if host_port:
            port_info = instance_ports[port_key]
            if not port_info:
                log.debug("Port is exposed but not published.")
                return False

            interface_name = resolve_value(port_binding.interface)
            if interface_name:
                bind_address = resolve_value(client_config.interfaces.get(interface_name))
            else:
                bind_address = '0.0.0.0'

            expected_config = {'HostIp': bind_address, 'HostPort': six.text_type(host_port)}
            log.debug("Comparing port config. Expected vs Actual:\n%s\n%s", expected_config, port_info)

            if expected_config not in port_info:
                return False

    return True

def _assess_resource_limits(container_config, container_details, client_config):
    constraints = client_config.constraints
    instance_host_config = container_details['HostConfig']
    config_host_config = container_config.host_config
    config_create_opts = container_config.create_options

    update_params = {}
    needs_container_rebuild = False

    for inspect_field, config_param, check_in_create, requires_constraint_support, conversion_fn in CONTAINER_UPDATE_PARAMETERS:
        if requires_constraint_support and not constraints.get(config_param):
            log.debug("Skipping parameter %s - not supported by client.", config_param)
            continue

        instance_val = instance_host_config.get(inspect_field) or None
        config_val = config_host_config.get(config_param) or None

        if not config_val and check_in_create:
            config_val = config_create_opts.get(config_param) or None

        if config_param == 'memswap_limit' and not config_val:
            mem_limit = config_host_config.get('mem_limit') or config_create_opts.get('mem_limit')
            if mem_limit:
                config_val = docker_utils.parse_bytes(mem_limit) * 2

        if config_val and conversion_fn:
            config_val = conversion_fn(config_val)

        if instance_val or config_val:
            log.debug("Comparing resource limit %s - Instance: %s - Config: %s.", inspect_field, instance_val, config_val)
            if instance_val != config_val:
                if config_val is not None:
                    log.debug("Updating %s to %s.", inspect_field, config_val)
                    update_params[config_param] = config_val
                else:
                    log.debug("Resource limit %s cannot be reset to default, suggesting container rebuild.", inspect_field)
                    needs_container_rebuild = True

    return update_params, needs_container_rebuild

def _verify_restart_policy(container_config, container_details):
    config_restart = container_config.host_config.get('restart_policy')
    instance_restart = container_details['HostConfig'].get('RestartPolicy')

    if config_restart and instance_restart:
        config_name = config_restart.get('Name')
        instance_name = instance_restart.get('Name')

        if config_name == 'on-failure':
            if instance_name == 'on-failure':
                retry_count_changed = config_restart.get('MaximumRetryCount', 0) != instance_restart.get('MaximumRetryCount', 0)
            else:
                retry_count_changed = True
        else:
            retry_count_changed = config_name != instance_name
    else:
        retry_count_changed = False

    if retry_count_changed:
        return {'restart_policy': config_restart}
    return {}

class UpdateContainerState(ContainerBaseState):
    """
    Enhanced state management for containers that verifies current instance against configuration,
    including volumes, links, network settings, and resource limits.
    """
    def __init__(self, *args, **kwargs):
        super(UpdateContainerState, self).__init__(*args, **kwargs)
        self.volume_checker = None
        self.endpoint_registry = None
        self.active_exec_commands = None

    def _validate_links(self):
        instance_links = self.detail['HostConfig'].get('Links') or []
        link_map = defaultdict(set)

        for link_entry in instance_links:
            host_name, _, alias = link_entry.partition(':')
            link_map[host_name[1:]].add(alias.rpartition('/')[2])

        for link in self.config.links:
            instance_aliases = link_map.get(self.policy.cname(self.config_id.map_name, link.container))
            expected_alias = link.alias or self.policy.get_hostname(link.container)

            if not instance_aliases or expected_alias not in instance_aliases:
                log.debug("Link validation failed for %s - missing alias %s", link.container, expected_alias)
                return False

            log.debug("Link validation passed for %s - found alias %s", link.container, expected_alias)

        return True

    def _validate_exec_commands(self, check_mode):
        def _search_full_match(target_cmd, target_user):
            for _, user, cmd in self.active_exec_commands:
                if user == target_user and cmd == target_cmd:
                    log.debug("Full match found for user %s: %s.", target_user, cmd)
                    return True
            log.debug("No full match found for user %s: %s.", target_user, target_cmd)
            return False

        def _search_partial_match(target_cmd, target_user):
            for _, user, cmd in self.active_exec_commands:
                if user == target_user and target_cmd in cmd:
                    log.debug("Partial match found for user %s: %s.", target_user, cmd)
                    return True
            log.debug("No partial match found for user %s: %s.", target_user, target_cmd)
            return False

        def _is_command_active(cmd_spec, cmd_user):
            resolved_cmd = resolve_value(cmd_spec)
            if isinstance(resolved_cmd, (list, tuple)):
                resolved_cmd = ' '.join(map(str, resolved_cmd))

            resolved_user = resolve_value(cmd_user) if cmd_user is not None else extract_user(self.config.user)
            if resolved_user is None:
                resolved_user = 'root'

            log.debug("Checking for %s command for user %s: %s", check_mode, resolved_user, resolved_cmd)
            return cmd_exists(resolved_cmd, resolved_user)

        if not self.config.exec_commands:
            return None

        if not self.active_exec_commands:
            log.debug("No active exec commands detected for container.")
            return self.config.exec_commands

        log.debug("Validating execution commands for container %s.", self.container_name)

        if check_mode == CmdCheck.FULL:
            cmd_check_func = _search_full_match
        elif check_mode == CmdCheck.PARTIAL:
            cmd_check_func = _search_partial_match
        else:
            log.debug("Invalid check mode %s - skipping.", check_mode)
            return None

        return [exec_cmd for exec_cmd in self.config.exec_commands
                if not _is_command_active(exec_cmd.cmd, exec_cmd.user) and exec_cmd.policy != ExecPolicy.INITIAL]

    def _validate_volumes(self):
        instance_volumes = get_instance_volumes(self.detail, self.client_config.features['volumes'])
        return self.volume_checker.check(self.config_id, self.container_map, self.config, instance_volumes)

    def _validate_network_mode(self):
        desired_net_mode = self.config.network_mode or 'default'

        if (desired_net_mode == 'none') != self.detail['Config'].get('NetworkDisabled', False):
            return False

        instance_net_mode = self.detail['HostConfig'].get('NetworkMode') or 'default'

        if isinstance(desired_net_mode, tuple):
            reference_mode = 'container:{0}'.format(self.policy.cname(self.config_id.map_name, *desired_net_mode))
        else:
            reference_mode = desired_net_mode

        return reference_mode == instance_net_mode

    def set_defaults(self):
        super(UpdateContainerState, self).set_defaults()
        self.active_exec_commands = None

    def inspect(self):
        super(UpdateContainerState, self).inspect()
        if self.detail and self.detail['State']['Running'] and self.config_id.config_type == ItemType.CONTAINER:
            exec_check_option = self.options['check_exec_commands']
            if exec_check_option and exec_check_option != CmdCheck.NONE and self.config.exec_commands:
                top_result = self.client.top(self.detail['Id'], ps_args='-eo pid,user,args')
                self.active_exec_commands = top_result['Processes'] if top_result else []

    def get_state(self):
        base_state, state_flags, extra = super(UpdateContainerState, self).get_state()

        if base_state == State.ABSENT or state_flags & StateFlags.NEEDS_RESET:
            return base_state, state_flags, extra

        config_id = self.config_id
        container_image_id = self.detail['Image']

        if config_id.config_type == ItemType.VOLUME:
            volumes = get_instance_volumes(self.detail, False)
            if volumes:
                default_paths = self.policy.default_volume_paths[config_id.map_name]
                volume_name = '{0}.{1}'.format(config_id.config_name, config_id.instance_name) \
                    if self.container_map.use_attached_parent_name else config_id.instance_name
                mapped_path = resolve_value(default_paths[volume_name])
                self.volume_checker.register_attached(volume_name, mapped_path, volumes.get(mapped_path))
        else:
            image_name = format_image_tag(self.container_map.get_image(self.config.image or config_id.config_name))
            images = self.policy.images[self.client_name]
            expected_image_id = images.get(image_name)

            if container_image_id != expected_image_id and (not self.config.persistent or self.options['update_persistent']):
                state_flags |= StateFlags.IMAGE_MISMATCH

            if not self._validate_volumes():
                state_flags |= StateFlags.VOLUME_MISMATCH

            if not self._validate_links():
                state_flags |= StateFlags.MISSING_LINK

            if not (_verify_environment(self.config, self.detail) and 
                    _check_command(self.config, self.detail) and
                    _validate_network_ports(self.config, self.client_config, self.detail)):
                state_flags |= StateFlags.MISC_MISMATCH

            if base_state == State.RUNNING:
                exec_check_option = self.options['check_exec_commands']
                if exec_check_option:
                    missing_exec_cmds = self._validate_exec_commands(exec_check_option)
                    if missing_exec_cmds:
                        state_flags |= StateFlags.EXEC_COMMANDS
                        extra['exec_commands'] = missing_exec_cmds

            if self.endpoint_registry:
                net_state_flags, net_extra = self.endpoint_registry.check_container_config(
                    config_id, self.config, self.detail)
                state_flags |= net_state_flags
                extra.update(net_extra)
            elif not self._validate_network_mode():
                state_flags |= StateFlags.MISC_MISMATCH

            host_config_updates, needs_rebuild = _assess_resource_limits(self.config, self.detail, self.client_config)
            restart_policy_update = _verify_restart_policy(self.config, self.detail)
            host_config_updates.update(restart_policy_update)

            if not self.client_config.features['container_update_restart_policy'] and restart_policy_update:
                needs_rebuild = True

            if host_config_updates:
                if not self.client_config.features['container_update']:
                    needs_rebuild = True
                state_flags |= StateFlags.HOST_CONFIG_UPDATE
                extra['update_container'] = host_config_updates

            if needs_rebuild:
                if not self.options['skip_limit_reset']:
                    state_flags |= StateFlags.MISC_MISMATCH
                else:
                    log.info("Container has incompatible host-config that cannot be updated, but will not be rebuilt.")

        return base_state, state_flags, extra

