from __future__ import annotations
# mypy: disallow-untyped-defs, disallow-incomplete-defs, disallow-untyped-calls
import typing
from .grammar import Element, InitNt, Nt
from . import types, grammar

class ParserAction:
    __slots__ = ["input_traits", "output_traits", "_cached_hash"]

    input_traits: typing.List[str]
    output_traits: typing.List[str]
    _cached_hash: typing.Optional[int]

    def __init__(self, input_traits: typing.List[str], output_traits: typing.List[str]) -> None:
        self.input_traits = input_traits
        self.output_traits = output_traits
        self._cached_hash = None

    def is_inconsistent(self) -> bool:
        return False

    def is_condition_check(self) -> bool:
        return False

    def get_condition(self) -> ParserAction:
        raise TypeError("ParserAction.get_condition not implemented")

    def modifies_stack(self) -> bool:
        return False

    def get_reduction(self) -> Reduction:
        assert self.modifies_stack()
        raise TypeError("ParserAction.get_reduction not implemented.")

    def shift_transform(self, shifted_element: Element) -> ShiftedResult:
        return self

    def terminates_parsing(self) -> bool:
        return False

    def __eq__(self, other: object) -> bool:
        if self.__class__ != other.__class__:
            return False
        assert isinstance(other, ParserAction)
        if sorted(self.input_traits) != sorted(other.input_traits):
            return False
        if sorted(self.output_traits) != sorted(other.output_traits):
            return False
        for attr in self.__slots__:
            if getattr(self, attr) != getattr(other, attr):
                return False
        return True

    def __hash__(self) -> int:
        if self._cached_hash is not None:
            return self._cached_hash

        def hash_components() -> typing.Iterator[object]:
            yield self.__class__
            yield "in"
            for trait in self.input_traits:
                yield trait
            yield "out"
            for trait in self.output_traits:
                yield trait
            for attr in self.__slots__:
                yield repr(getattr(self, attr))

        self._cached_hash = hash(tuple(hash_components()))
        return self._cached_hash

    def __lt__(self, other: ParserAction) -> bool:
        return hash(self) < hash(other)

    def __repr__(self) -> str:
        return str(self)

    def stable_format(self, parser_states: typing.Any) -> str:
        return str(self)

ShiftedResult = typing.Union[ParserAction, bool]

class Reduction(ParserAction):
    __slots__ = ['nonterminal', 'pop_count', 'replay_count']
    nonterminal: Nt
    pop_count: int
    replay_count: int

    def __init__(self, nonterminal: Nt, pop_count: int, replay_count: int = 0) -> None:
        nt_name = nonterminal.name
        if isinstance(nt_name, InitNt):
            name = "Start_" + str(nt_name.goal.name)
        else:
            name = nt_name
        super().__init__([], ["nt_" + name])
        self.nonterminal = nonterminal
        self.pop_count = pop_count
        self.replay_count = replay_count

    def __str__(self) -> str:
        return "Reduction({}, {}, {})".format(self.nonterminal, self.pop_count, self.replay_count)

    def modifies_stack(self) -> bool:
        return True

    def get_reduction(self) -> Reduction:
        return self

    def shift_transform(self, shifted_element: Element) -> Reduction:
        return Reduction(self.nonterminal, self.pop_count, replay_count=self.replay_count + 1)

class AcceptAction(ParserAction):
    __slots__: typing.List[str] = []

    def __init__(self) -> None:
        super().__init__([], [])

    def __str__(self) -> str:
        return "AcceptAction()"

    def terminates_parsing(self) -> bool:
        return True

    def shift_transform(self, shifted_element: Element) -> AcceptAction:
        return AcceptAction()

class LookaheadCheck(ParserAction):
    __slots__ = ['required_terms', 'accept_flag']
    required_terms: typing.FrozenSet[str]
    accept_flag: bool

    def __init__(self, required_terms: typing.FrozenSet[str], accept_flag: bool):
        super().__init__([], [])
        self.required_terms = required_terms
        self.accept_flag = accept_flag

    def is_inconsistent(self) -> bool:
        return True

    def is_condition_check(self) -> bool:
        return True

    def get_condition(self) -> LookaheadCheck:
        return self

    def __str__(self) -> str:
        return "LookaheadCheck({}, {})".format(self.required_terms, self.accept_flag)

    def shift_transform(self, shifted_element: Element) -> ShiftedResult:
        if isinstance(shifted_element, Nt):
            return True
        if shifted_element in self.required_terms:
            return self.accept_flag
        return not self.accept_flag

class NewLineCheck(ParserAction):
    __slots__ = ['stack_depth']
    stack_depth: int

    def __init__(self, stack_depth: int = 0) -> None:
        super().__init__([], [])
        self.stack_depth = stack_depth

    def is_inconsistent(self) -> bool:
        return self.stack_depth >= 0

    def is_condition_check(self) -> bool:
        return True

    def get_condition(self) -> NewLineCheck:
        return self

    def shift_transform(self, shifted_element: Element) -> ShiftedResult:
        if isinstance(shifted_element, Nt):
            return True
        return NewLineCheck(self.stack_depth - 1)

    def __str__(self) -> str:
        return "NewLineCheck({})".format(self.stack_depth)

class FlagFilter(ParserAction):
    __slots__ = ['flag_name', 'expected_value']
    flag_name: str
