OutputExpression = typing.Union[str, int, None, grammar.Some]

class MethodCall(ParserAction):
    __slots__ = ['trait_type', 'method_name', 'offset_adjustment', 'arguments', 'error_handling', 'target_var']
    trait_type: types.Type
    method_name: str
    offset_adjustment: int
    arguments: typing.Tuple[OutputExpression, ...]
    error_handling: bool
    target_var: str

    def __init__(
            self,
            method_name: str,
            arguments: typing.Tuple[OutputExpression, ...],
            trait_type: types.Type = types.Type("AstBuilder"),
            error_handling: bool = False,
            target_var: str = "val",
            offset_adjustment: int = 0,
            read_traits: typing.List[str] = [],
            write_traits: typing.List[str] = []
    ) -> None:
        super().__init__(read_traits, write_traits)
        self.trait_type = trait_type
        self.method_name = method_name
        self.error_handling = error_handling
        self.offset_adjustment = offset_adjustment
        self.arguments = arguments
        self.target_var = target_var

    def __str__(self) -> str:
        return "{} = {}::{}({}){} [off: {}]".format(
            self.target_var, self.trait_type, self.method_name,
            ", ".join(map(str, self.arguments)),
            self.error_handling and '?' or '',
            self.offset_adjustment)

    def __repr__(self) -> str:
        return "MethodCall({})".format(', '.join(map(repr, [
            self.trait_type, self.method_name, self.error_handling, self.input_traits, self.output_traits,
            self.arguments, self.target_var, self.offset_adjustment
        ])))

    def shift_transform(self, shifted_element: Element) -> MethodCall:
        return MethodCall(self.method_name,
                          self.arguments,
                          trait_type=self.trait_type,
                          error_handling=self.error_handling,
                          target_var=self.target_var,
                          offset_adjustment=self.offset_adjustment + 1,
                          read_traits=self.input_traits,
                          write_traits=self.output_traits)

class SequentialAction(ParserAction):
    __slots__ = ['action_sequence']
    action_sequence: typing.Tuple[ParserAction, ...]

    def __init__(self, actions: typing.Sequence[ParserAction]) -> None:
        input_traits = [rd for a in actions for rd in a.input_traits]
        output_traits = [wr for a in actions for wr in a.output_traits]
        super().__init__(input_traits, output_traits)
        self.action_sequence = tuple(actions)
        assert all([not a.is_condition_check() for a in actions])
        assert all([not isinstance(a, SequentialAction) for a in actions])
        assert all([not a.modifies_stack() for a in actions[:-1]])

    def __str__(self) -> str:
        return "{{ {} }}".format("; ".join(map(str, self.action_sequence)))

    def __repr__(self) -> str:
        return "SequentialAction({})".format(repr(self.action_sequence))

    def is_condition_check(self) -> bool:
        return self.action_sequence[0].is_condition_check()

    def get_condition(self) -> ParserAction:
        return self.action_sequence[0]

    def modifies_stack(self) -> bool:
        return self.action_sequence[-1].modifies_stack()

    def get_reduction(self) -> Reduction:
        return self.action_sequence[-1].get_reduction()

    def shift_transform(self, shift: Element) -> ShiftedResult:
        transformed_actions: typing.List[ParserAction] = []
        for action in self.action_sequence:
            new_action = action.shift_transform(shift)
            if isinstance(new_action, bool):
                if new_action is False:
                    return False
            else:
                transformed_actions.append(new_action)
        return SequentialAction(transformed_actions)

    def terminates_parsing(self) -> bool:
        return any(action.terminates_parsing() for action in self.action_sequence)

