import numpy as np
from PIL import Image

def compute_resized_dimensions(original_size, target_dimension):
    """Compute new image dimensions based on resizing strategy."""
    width, height = original_size

    # Handle scalar or single-element resize specification
    if isinstance(target_dimension, (int, float)) or len(target_dimension) == 1:
        min_edge = min(width, height)
        max_edge = max(width, height)

        # Extract the target short edge size
        target_short = (target_dimension if isinstance(target_dimension, (int, float)) 
                       else target_dimension[0])

        # Calculate proportional long edge
        scale_factor = target_short / min_edge
        target_long = int(max_edge * scale_factor)

        # Assign dimensions preserving aspect ratio orientation
        if width <= height:
            new_width, new_height = int(target_short), target_long
        else:
            new_width, new_height = target_long, int(target_short)
    else:
        # Explicit width/height specification
        new_height, new_width = target_dimension[0], target_dimension[1]

    return (int(new_width), int(new_height))

class ImageTransformer:
    """Base class for image transformation operations."""
    def transform(self, image):
        raise NotImplementedError

class RescaleImage(ImageTransformer):
    """Rescale image to specified dimensions."""
    def __init__(self, dimensions=None, method=Image.BILINEAR):
        self.dimensions = dimensions
        self.method = method

    def transform(self, image):
        final_size = compute_resized_dimensions(image.size, self.dimensions)
        return image.resize(final_size, self.method)

class CropCenter(ImageTransformer):
    """Crop image from center with specified size."""
    def __init__(self, crop_size):
        self.crop_size = (crop_size, crop_size) if isinstance(crop_size, int) else crop_size

    def transform(self, image):
        return execute_center_crop(image, self.crop_size)

class StandardizeImage(ImageTransformer):
    """Normalize image using mean and standard deviation."""
    def __init__(self, normalization_scale=None, average_values=None, deviation_values=None):
        # Process scaling factor
        if isinstance(normalization_scale, str):
            normalization_scale = eval(normalization_scale)

        self.scale = np.float32(normalization_scale if normalization_scale is not None else 1.0/255.0)

        # Default ImageNet statistics if not provided
        avg_vals = average_values if average_values is not None else [0.485, 0.456, 0.406]
        dev_vals = deviation_values if deviation_values is not None else [0.229, 0.224, 0.225]

        # Prepare arrays for broadcasting
        shape_params = (1, 1, 3)
        self.mean_array = np.array(avg_vals).reshape(shape_params).astype(np.float32)
        self.std_array = np.array(dev_vals).reshape(shape_params).astype(np.float32)

    def transform(self, image):
        # Convert PIL image to numpy array if needed
        if isinstance(image, Image.Image):
            image_data = np.array(image)
        else:
            image_data = image

        # Apply normalization: (pixel * scale - mean) / std
        normalized = (image_data * self.scale - self.mean_array) / self.std_array
        return normalized

class ReorderChannels(ImageTransformer):
    """Reorder image channels from HWC to CHW format."""
    def transform(self, image):
        if isinstance(image, Image.Image):
            image = np.array(image)
        return np.transpose(image, (2, 0, 1))

def execute_center_crop(image_data, crop_spec, channel_flag=True):
    """Perform center cropping operation."""
    # Convert PIL image to numpy array if necessary
    if isinstance(image_data, Image.Image):
        image_data = np.array(image_data)

    # Extract crop size
    crop_dimension = crop_spec[0] if isinstance(crop_spec, (list, tuple)) else crop_spec

    # Get image dimensions
    height, width = image_data.shape[:2]

    # Calculate crop boundaries
    top = (height - crop_dimension) // 2
    left = (width - crop_dimension) // 2
    bottom = top + crop_dimension
    right = left + crop_dimension

    # Perform cropping based on channel configuration
    if channel_flag:
        cropped = image_data[top:bottom, left:right, :]
    else:
        cropped = image_data[top:bottom, left:right]

    return cropped

class PipelineProcessor:
    """Process images through a sequence of transformations."""
    def __init__(self, operations_list):
        self.operations = operations_list

    def process(self, image):
        current_image = image
        for operation in self.operations:
            current_image = operation.transform(current_image)
        return current_image

