import hashlib
from datetime import datetime
from typing import List, Tuple
from uuid import uuid4
from django.db import models, connection
from django.db.migrations.recorder import MigrationRecorder
from django.db.models import Max, Index, Q
from django.utils.crypto import get_random_string
from django.utils.functional import cached_property
from django.utils.timezone import now
from liquidb.consts import SELF_NAME


def _generate_commit_name() -> str:
    """Generates commit name based on timestamp and random salt"""
    timestamp = now().strftime("%d-%m-%YT%H:%M:%S")
    random_suffix = get_random_string(6)
    return f"{random_suffix}_{timestamp}"


def _create_migration_hash(migration_list: List[Tuple[str, str]]) -> str:
    """Creates MD5 hash from list of (app_name, migration_name) tuples"""
    # Sort migrations to ensure deterministic ordering
    sorted_migrations = sorted(migration_list)

    # Build canonical string representation
    parts = []
    for app_name, migration_name in sorted_migrations:
        parts.append(f"{app_name}-{migration_name}")

    # Join with semicolon separator and compute hash
    canonical_form = ";".join(parts)
    return hashlib.md5(canonical_form.encode("utf-8")).hexdigest()


def get_latest_applied_migrations_qs(connection_obj=None):
    """Fetches the most recent applied migration for each Django app"""
    if connection_obj is None:
        connection_obj = connection

    recorder = MigrationRecorder(connection_obj)
    base_query = recorder.migration_qs.exclude(app=SELF_NAME)

    # Find latest migration ID per app using subquery pattern
    latest_ids_subquery = (
        base_query
        .values("app")
        .annotate(latest_id=Max("id"))
        .values_list("latest_id", flat=True)
    )

    return base_query.filter(id__in=latest_ids_subquery)


class Snapshot(models.Model):
    name = models.TextField(default=_generate_commit_name, db_index=True, unique=True)
    created = models.DateTimeField(default=now)
    applied = models.BooleanField(default=False)

    class Meta:
        indexes = [
            # Ensure only one snapshot can be marked as applied at a time
            Index(
                fields=["applied"],
                name="unique_applied",
                condition=Q(applied=True)
            )
        ]

    def __repr__(self):
        return f"{self.__class__.__name__}: {self.id}, {self.name}"

    def __eq__(self, other):
        if not isinstance(other, Snapshot):
            return False
        return self._compute_migration_hash() == other._compute_migration_hash()

    def __hash__(self):
        return hash(self._compute_migration_hash())

    @property
    def consistent_state(self) -> bool:
        """Check if current database state matches snapshot's recorded state"""
        current_db_state = get_latest_applied_migrations_qs().values_list("app", "name")
        current_hash = _create_migration_hash(current_db_state)
        return self._compute_migration_hash() == current_hash

    @cached_property
    def _compute_migration_hash(self) -> str:
        """Computes migration hash for this snapshot"""
        return _create_migration_hash(self.migrations.values_list("app", "name"))


class MigrationState(models.Model):
    uuid = models.UUIDField(unique=True, primary_key=True, db_index=True, default=uuid4)
    snapshot = models.ForeignKey(
        Snapshot, on_delete=models.CASCADE, related_name="migrations"
    )
    migration_id = models.IntegerField(db_index=True)

    # Redundant fields for migration reconstruction
    app = models.CharField(max_length=255)
    name = models.CharField(max_length=255)

    def __repr__(self):
        return f"Migration {self.app} {self.name}"

import copy
from ansible_filter.helpers import array_to_dict

# Constants for state and action handling
STATE_KEY = 'state'
STATE_PRESENT = 'present'
STATE_ABSENT = 'absent'

ACTION_KEY = 'action'
ACTION_CREATE = 'create'
ACTION_UPDATE = 'update'
ACTION_NOOP = 'noop'
ACTION_DELETE = 'delete'

OBJ_KEY = 'value'

def convert_dict_to_list(obj_dict):
    """Convert dictionary to list of values"""
    result_list = []
    for _, value in obj_dict.items():
        result_list.append(value)
    return result_list

def determine_action(current_obj, existing_obj, target_state, default_obj):
    """Determine the appropriate action based on object states"""
    if not existing_obj:
        # No existing object
        return ACTION_CREATE if target_state == STATE_PRESENT else ACTION_NOOP
    elif objects_match(current_obj, existing_obj):
        # Objects are equivalent
        if target_state == STATE_PRESENT or objects_match(default_obj, existing_obj):
            return ACTION_NOOP
        else:
            return ACTION_DELETE
    else:
        # Objects differ
        if target_state == STATE_PRESENT:
            return ACTION_UPDATE
        else:
            return ACTION_DELETE

def parse_bool(value):
    """Convert string representation to boolean"""
    if isinstance(value, bool):
        return value
    return str(value).lower() in ("yes", "true", "t", "1")

def objects_match(obj_a, obj_b):
    """Recursively compare two objects for equality"""
    if both_empty(obj_a, obj_b):
        return True

    if any_boolean(obj_a, obj_b):
        return boolean_equal(obj_a, obj_b)

    if both_dicts(obj_a, obj_b):
        return dict_equal(obj_a, obj_b)

    if is_sequence(obj_a) and is_sequence(obj_b):
        return sequence_equal(obj_a, obj_b)

    # Default comparison
    return obj_a == obj_b

def boolean_equal(val1, val2):
    """Compare two boolean-like values"""
    b1 = val1 if isinstance(val1, bool) else parse_bool(val1)
    b2 = val2 if isinstance(val2, bool) else parse_bool(val2)
    return b1 is b2

def sequence_equal(seq1, seq2):
    """Compare two sequences element by element"""
    if len(seq1) != len(seq2):
        return False

    for item1, item2 in zip(seq1, seq2):
        if not objects_match(item1, item2):
            return False
    return True

def dict_equal(dict1, dict2):
    """Compare two dictionaries key by key"""
    for key, value1 in dict1.items():
        value2 = dict2.get(key)
        if not objects_match(value1, value2):
            return False
    return True

def any_boolean(val1, val2):
    """Check if either value is a boolean"""
    return isinstance(val1, bool) or isinstance(val2, bool)

def both_empty(val1, val2):
    """Check if both values are empty/None"""
    return is_empty(val1) and is_empty(val2)

def both_dicts(val1, val2):
    """Check if both values are dictionaries"""
    return isinstance(val1, dict) and isinstance(val2, dict)

def both_sequences(val1, val2):
    """Check if both values are sequences (lists)"""
    return is_sequence(val1) and is_sequence(val2)

def is_dict(obj):
    """Check if object is a dictionary"""
    return isinstance(obj, dict)

def is_sequence(obj):
    """Check if object is a list"""
    return isinstance(obj, list)

def is_empty(value):
    """Check if value is considered empty"""
    return not bool(value)

def extract_state(obj):
    """Extract state from object, defaulting to present"""
    return obj.pop(STATE_KEY, STATE_PRESENT)

def merge_objects(new_obj, base_obj):
    """Merge new object into base object, preserving base when no new value"""
    if base_obj:
        merged = copy.deepcopy(base_obj)
        merged.update(new_obj)
    else:
        merged = new_obj
    return merged

def compute_changes(local_data, existing_data, default_data=None, identifier='name'):
    """Compute the set of changes needed between local and existing data"""
    change_map = {
        ACTION_CREATE: [],
        ACTION_UPDATE: [],
        ACTION_DELETE: [],
        ACTION_NOOP: []
    }

    if not local_data:
        return change_map

    if is_dict(local_data):
        existing_data = {} if not is_dict(existing_data) else existing_data
        process_single_change(change_map, local_data, existing_data, default_data)
        return change_map

    if is_sequence(local_data):
        local_map = array_to_dict(local_data, identifier)
        existing_map = {} if not is_sequence(existing_data) else array_to_dict(existing_data, identifier)
        process_multiple_changes(change_map, local_map, existing_map, default_data)
        return change_map

    raise TypeError('Cannot compute changes for: ' + str(local_data) + ", " + str(existing_data))

def process_single_change(changes, current, existing, default):
    """Process a single object change"""
    obj = copy.deepcopy(current)
    state = extract_state(obj)
    action = determine_action(obj, existing, state, default)
    obj = merge_objects(obj, existing)
    changes[action].append(obj)

def process_multiple_changes(changes, local_map, existing_map, default):
    """Process multiple object changes"""
    for key, current_obj in local_map.items():
        existing_obj = existing_map.get(key)
        process_single_change(changes, current_obj, existing_obj, default)

