def _load_yaml_settings(path: str, **overrides) -> Dict[str, Any]:
    with open(path) as fp:
        base = yaml.load(fp, Loader=yaml.FullLoader) or {}
    merged = {**base, **overrides}
    panel = Table(title="Configuration", show_header=False)
    panel.add_column("Key")
    panel.add_column("Value")
    for k, v in merged.items():
        panel.add_row(str(k), str(v))
    console.print(panel)
    return merged


def _parse_cli_args(cli_args: List[str]) -> Dict[str, Any]:
    result = {}
    idx = 0
    while idx < len(cli_args):
        arg = cli_args[idx]
        if "=" in arg:
            parts = arg.split("=", 1)
            key = parts[0].lstrip("-")
            val = parts[1]
            idx += 1
        else:
            key = arg.lstrip("-")
            val = cli_args[idx + 1] if idx + 1 < len(cli_args) else None
            idx += 2
        # Attempt numeric conversion
        for conv in (int, float):
            try:
                val = conv(val)
                break
            except (TypeError, ValueError):
                continue
        result[key] = val
    return result


def _collect_files(source: Path, predicate=lambda p: p.is_file()) -> List[Path]:
    if source.is_dir():
        return [f for f in source.glob("**/*") if predicate(f)]
    else:
        pattern = str(source)
        return [Path(p) for p in glob.glob(pattern) if predicate(Path(p))]


def _resolve_output_directory(prefix: Path, label: str, cfg: Dict[str, Any]) -> Path:
    target = prefix / label
    if target.exists():
        try:
            with open(target / "settings.yaml") as fp:
                prior_cfg = yaml.load(fp, Loader=yaml.FullLoader) or {}
        except FileNotFoundError:
            return target
        if prior_cfg != cfg:
            table = Table("Existing", "New", width=console.width)
            table.add_row(yaml.dump(prior_cfg), yaml.dump(cfg))
            console.print(table)
            if not click.confirm(
                f"{target} has existing files with different settings. Remove and continue?"
            ):
                console.print("Understood. Exiting.")
                sys.exit(1)
        else:
            console.print("[dim]Using existing label with matching configuration.")
    return target


def _expand_path(raw_path: str, band: str = "", raw_mode: bool = True) -> Path:
    if not raw_path.startswith(":"):
        return Path(raw_path).expanduser()
    elif raw_mode:
        if not band:
            raise ValueError("Band must be specified when using colon-prefixed paths.")
        return Path(config["paths"]["raw_field_data"]) / "mro" / band / raw_path[1:]
    else:
        return Path(config["paths"]["field_products"]) / raw_path[1:]


@main.command(
