    default="",
    help="Output filename for combine stage only.",
)
@click.option("-j", "--workers", default=1, help="Number of worker threads.")
@click.pass_context
def process(ctx, stage, config_file, source, label, note, force, dest, workers):
    console.print(
        Panel(f"edges-analysis [blue]{stage}[/]", box=box.DOUBLE_EDGE),
        style="bold",
        justify="center",
    )
    console.print(Rule("Initializing"))

    stage_class = {
        "raw": levels.RawData,
        "calibrate": levels.CalibratedData,
        "model": levels.ModelData,
        "combine": levels.CombinedData,
        "day": levels.DayAveragedData,
        "bin": levels.BinnedData,
    }[stage]

    cli_config = _parse_cli_args(ctx.args)
    config_dict = _load_yaml_settings(config_file, **cli_config)
    label = config_dict.pop("label", "") or label
    if not label:
        label = click.prompt("Enter a short label for this run", type=str)

    file_predicate = (
        lambda p: p.suffix[1:] in io.Spectrum.supported_formats
        if stage == "raw"
        else h5py.is_hdf5
    )

    sources = [
        _expand_path(s, band=config_dict.get("band"), raw_mode=(stage == "raw"))
        for s in source
    ]
    files = []
    for src in sources:
        files.extend(_collect_files(src, predicate=file_predicate))

    if not files:
        logger.error(f"No input files found at: {sources}")
        return

    console.print("[bold]Found Input Files:")
    for f in files:
        console.print(f"   {f}")
    console.print()

    if stage != "raw":
        dirs = {f.parent for f in files}
        if len(dirs) != 1:
            raise ValueError("All inputs must come from the same processing directory.")

    first_type = levels.get_step_type(files[0])

    if stage == "raw":
        dest_dir = Path(config["paths"]["field_products"]) / label
    else:
        dest_dir = _resolve_output_directory(files[0].parent, label, config_dict)

    dest_dir.mkdir(parents=True, exist_ok=True)
    console.print(f"[bold]Output Directory:[dim] {dest_dir}")

    if stage == "combine":
        if not dest:
            dest = [click.prompt("Enter output filename", type=str)]
        dest_paths = [Path(d).with_suffix(".h5") for d in dest]
    elif stage != "raw":
        dest_paths = [f.name for f in files]
    else:
        dest_paths = None

    if stage == "bin" and first_type in (levels.CombinedData, levels.CombinedBinnedData):
        stage_class = levels.CombinedBinnedData

    if dest_paths:
        for path in dest_paths:
            full_path = dest_dir / path
            if full_path.exists():
                if force:
                    full_path.unlink()
                else:
                    raise FileExistsError(
                        f"File {full_path} exists. Use --force to overwrite."
                    )

    if note:
        (dest_dir / "README.txt").write_text(note)

    (dest_dir / "settings.yaml").write_text(yaml.dump(config_dict))

    console.print()
    console.print(Rule("Processing Data"))
    out_paths = _run_stage(
        files, workers, dest_dir, dest_paths, stage_class, config_dict
    )
    console.print(Rule("Processing Complete"))

    for pth in out_paths:
        with h5py.File(pth, "a") as fl:
            fl.attrs["note"] = note

    console.print()
    if stage == "combine":
        console.print(f"[bold]Output File: [blue]{out_paths[0]}")
    elif stage in ("raw", "calibrate", "model"):
        console.print(f"[bold]Files written to:[dim] {dest_dir}")
    else:
        console.print("[bold]Generated Output Files:")
        for fname in dest_paths:
            console.print(f"\t[bold]{dest_dir}/{fname}")


def _run_stage(
    files: List[Path],
    n_workers: int,
    dest_dir: Path,
    output_names: Optional[List[Path]],
    stage_class: Type[levels._ReductionStep],
    cfg: Dict[str, Any],
) -> List[Path]:
    if not files:
        raise ValueError("No input files provided!")

    if stage_class._multi_input:
        data = stage_class.promote(prev_step=files, **cfg)
        output_path = dest_dir / (output_names[0] if output_names else "combined.h5")
        data.write(output_path)
        return [output_path]
    else:
        output_names = output_names or [None] * len(files)

        def _process_single(input_file: Path, output_name: Optional[str]):
            try:
                obj = stage_class.promote(prev_step=input_file, **cfg)
            except (levels.FullyFlaggedError, levels.WeatherError) as err:
                logger.warning(str(err))
                return None
            name = output_name or f"{obj.datestring}.h5"
            out_path = dest_dir / name
            obj.write(out_path)
            return out_path

        if n_workers > 1:
            with ThreadPoolExecutor(max_workers=n_workers) as pool:
                results = list(pool.map(_process_single, files, output_names))
        else:
            results = [_process_single(f, n) for f, n in zip(files, output_names)]

        return [r for r in results if r is not None]


@main.command()
@click.argument("config_file", type=click.Path(dir_okay=False, exists=True))
@click.option(
    "-i",
    "--source",
    type=click.Path(dir_okay=True),
    multiple=True,
    help="Input paths (supports globs); can be repeated.",
)
@click.option("-j", "--workers", default=1, help="Number of worker threads.")
@click.option(
    "--flag-idx",
    default=-1,
    type=int,
    help="If non-negative, copy files and truncate flags up to this index.",
)
@click.option(
    "-l",
    "--label",
    default="",
    help="Label for new output directory when flag_idx >= 0.",
)
@click.option(
    "-f/-F",
    "--force/--no-force",
    default=False,
    help="Whether to overwrite existing label directory.",
)
def filter(config_file, source, workers, flag_idx, label, force):  # noqa: A001
    console.print(
        Panel("edges-analysis [blue]filter[/]", box=box.DOUBLE_EDGE),
        style="bold",
        justify="center",
    )
    console.print(Rule("Initializing"))

    with open(config_file) as fp:
        configs = yaml.load(fp, Loader=yaml.FullLoader)
    if isinstance(configs, dict):
        raise OSError("Filter configuration must be a list of filter definitions.")

    console.print()
    table = Table(title="Filters", show_header=False)
    table.add_column("Filter")
    table.add_column("Parameter")
    table.add_column("Value")
    for item in configs:
        key = list(item.keys())[0]
        params = item[key] or {}
        for i, (param, value) in enumerate(params.items()):
            table.add_row(key if i == 0 else "", param, str(value))
    console.print(table)
    console.print()

    predicate = h5py.is_hdf5
    sources = [_expand_path(s, raw_mode=False).expanduser() for s in source]
    files = []
    for src in sources:
        files.extend(_collect_files(src, predicate=predicate))

    if not files:
        logger.error(f"No input files found at: {sources}")
        return

    console.print("[bold]Input Files:")
    for f in files:
        console.print(f"   {f}")
    console.print()

    dirs = {f.parent for f in files}
    if len(dirs) != 1:
        raise ValueError("All inputs must come from the same processing directory.")

    input_data = [levels.read_step(fl, validate=False) for fl in files]

    output_dir = files[0].parent
    if flag_idx >= 0:
        if label:
            output_dir /= label
            if output_dir.exists():
                if not (force or click.confirm(f"Directory '{label}' exists. Overwrite?")):
                    logger.info("Aborting.")
                    sys.exit(0)
                shutil.rmtree(output_dir)
            output_dir.mkdir(parents=True)
            for f in files:
                shutil.copy(f, output_dir / f.name)
            files = [output_dir / f.name for f in files]
            input_data = [levels.read_step(fl, validate=False) for fl in files]
        elif not (force or click.confirm(
            "Modifying flags in-place without label. Proceed?"
        )):
            logger.info("Aborting.")
            sys.exit(0)

        for dataset in input_data:
            with dataset.open("r+") as flobj:
                dset = flobj["flags"]["flags"]
                dset.resize(flag_idx, axis=0)
                attrs = dict(flobj["flags"].attrs)
                for name, idx in attrs.items():
                    if idx >= flag_idx:
                        del flobj["flags"].attrs[name]
                        del flobj["flags"][name]

    n_filters = len(list(output_dir.glob("filter_*.yaml")))
    (output_dir / f"filter_settings_{n_filters}.yaml").write_text(
        yaml.dump(configs)
    )

    console.print()
    console.print(Rule("Running Filters"))
    for item in configs:
        filt_name = list(item.keys())[0]
        settings = item[filt_name] or {}
        func = filters.get_step_filter(filt_name)
        func(data=input_data, in_place=True, n_threads=workers, **settings)

    console.print(Rule("Filtering Complete"))
    console.print()
    console.print("[bold]Flags updated in place within input files.")

import yaml
from pathlib import Path

def Tenants(directory_path: str) -> dict:
    # Helper function to load YAML content from a file
    def load_yaml_document(filepath: str) -> dict:
        """Opens and parses a YAML file into a dictionary."""
        with open(filepath, 'r') as file_handle:
            return yaml.safe_load(file_handle)

    # Initialize the tenants dictionary
    tenants_data = {}

    # Iterate through all YAML files in the given directory
    for config_file in Path(directory_path).glob("*.yaml"):
        file_content = load_yaml_document(str(config_file))
        if file_content is not None:
            tenants_data.update(file_content)

    return tenants_data

# Import required modules
import uuid
import rxv
from fastapi import Depends, Body, APIRouter
from auth import User, get_user
from capabilities import (
    get_all_capabilities,
    get_capabilities_with_state,
    get_capability_by_name,
)

# Initialize the router
router = APIRouter()

@router.get("/user/devices")
async def list_devices(user: User = Depends(get_user)):
    # Prepare response structure with unique request ID
    result = {
        "request_id": str(uuid.uuid4()),
        "payload": {"user_id": user.id, "devices": []},
    }

    # Discover Yamaha devices and build device entries
    for dev in rxv.find():
        device_entry = {
            "id": dev.ctrl_url,
            "name": f"{dev.friendly_name} {dev.model_name}",
            "description": "AV Receiver",
            "room": "",
            "type": "devices.types.media_device",
            "custom_data": {"base_url": dev.ctrl_url},
            "capabilities": get_all_capabilities(),
            "device_info": {
                "manufacturer": "Yamaha Corporation",
                "model": dev.model_name,
            },
        }
        result["payload"]["devices"].append(device_entry)

    return result

@router.post("/user/devices/query")
async def query_devices(user: User = Depends(get_user)):
    # Prepare response structure with unique request ID
    result = {
        "request_id": str(uuid.uuid4()),
        "payload": {"user_id": str(user.id), "devices": []},
    }

    # Query each discovered device for its current state
    for dev in rxv.find():
        device_state = {
            "id": dev.ctrl_url,
            "capabilities": get_capabilities_with_state(dev),
        }
        result["payload"]["devices"].append(device_state)

    return result

@router.post("/user/devices/action")
async def execute_action(user: User = Depends(get_user), payload=Body(None)):
    # Extract request data
    input_data = payload

    # Prepare response structure with unique request ID
    result = {
        "request_id": str(uuid.uuid4()),
        "payload": {"user_id": user.id, "devices": []},
    }

    # Process each device action request
    for target_device in input_data["payload"]["devices"]:
        # Connect to the specific device
        yamaha_device = rxv.RXV(target_device["id"])
        processed_device = {"id": target_device["id"], "capabilities": []}

        # Apply each capability action
        for cap_request in target_device["capabilities"]:
            cap_handler = get_capability_by_name(cap_request["type"])
            cap_result = cap_handler.change_device_state(yamaha_device, cap_request)
            processed_device["capabilities"].append(cap_result)

        result["payload"]["devices"].append(processed_device)

    return result

