import socket
from .. import schema

class Address(schema.BinarySchema):
    address_type: int = schema.uint8
    host_address: str = schema.Switch(
        "address_type",
        {
            1: schema.Convert(
                schema.Bytes(4), 
                encode=lambda x: socket.inet_aton(x),
                decode=lambda x: socket.inet_ntoa(x)
            ),
            4: schema.Convert(
                schema.Bytes(16),
                encode=lambda x: socket.inet_pton(socket.AF_INET6, x),
                decode=lambda x: socket.inet_ntop(socket.AF_INET6, x),
            ),
            3: schema.LengthPrefixedString(schema.uint8),
        },
    )
    port_number: int = schema.uint16be

    @classmethod
    def create_from_endpoint(cls, endpoint):
        ip, port = endpoint
        try:
            # Try IPv4 first
            packed_ip = socket.inet_aton(ip)
            return cls(1, (ip, port))
        except OSError:
            try:
                # Then try IPv6
                packed_ip = socket.inet_pton(socket.AF_INET6, ip)
                return cls(4, (ip, port))
            except OSError:
                # Fall back to domain name
                return cls(3, (ip, port))

