class ArmaturePoseOperator(Operator):
    """Operator only available for objects of type armature in pose mode."""
    @classmethod
    def poll(cls, context):
        return (context.object and
                context.object.type == 'ARMATURE' and
                context.mode == 'POSE')


class NeedBoneGroupOperator(ArmaturePoseOperator):
    """Operator only available if the armature has a selected bone group."""
    @classmethod
    def poll(cls, context):
        if not super().poll(context):
            return False
        arm = context.object
        return 0 <= arm.active_bone_group < len(arm.bone_groups)


