    bl_label = "Remove Selected Bones from All Sets"
    bl_description = "Removes the Selected Bones from All Sets"
    bl_options = {'UNDO', 'REGISTER'}

    def execute(self, context):
        arm = context.object
        for bone in context.selected_pose_bones:
            for grp in arm.bone_groups:
                if bone.name in [entry.bone_name for entry in grp.bones]:
                    idx = grp.bones.find(bone.name)
                    grp.bones.remove(idx)
