class POSE_OT_selection_set_move(NeedBoneGroupOperator):
    bl_idname = "pose.selection_set_move"
    bl_label = "Move Bone Group in List"
    bl_description = "Move the active Bone Group up/down the list of groups"
    bl_options = {'UNDO', 'REGISTER'}

    direction: EnumProperty(
        name="Move Direction",
        description="Direction to move the active Bone Group: UP (default) or DOWN",
        items=[
            ('UP', "Up", "", -1),
            ('DOWN', "Down", "", 1),
        ],
        default='UP',
        options={'HIDDEN'},
    )

    @classmethod
    def poll(cls, context):
        if not super().poll(context):
            return False
        arm = context.object
        return len(arm.bone_groups) > 1

    def execute(self, context):
        arm = context.object
        active_idx = arm.active_bone_group
        new_idx = active_idx + (-1 if self.direction == 'UP' else 1)
        if new_idx < 0 or new_idx >= len(arm.bone_groups):
            return {'FINISHED'}
        arm.bone_groups.move(active_idx, new_idx)
        arm.active_bone_group = new_idx
        return {'FINISHED'}


