def menu_func_select_bone_group(self, context):
    self.layout.menu('POSE_MT_selection_sets_select', text="Bone Selection Set")


def serialize_to_json(context) -> str:
    """Convert the selected Bone Groups of the current rig to JSON.
    Selected Groups are the active_bone_group determined by the UIList
    plus any with the active_state checkbox on."""
    import json
    arm = context.object
    active_idx = arm.active_bone_group
    json_obj = {}
    for idx, grp in enumerate(context.object.bone_groups):
        if idx == active_idx or grp.active_state:
            bones = [entry.bone_name for entry in grp.bones]
            json_obj[grp.group_name] = bones
    return json.dumps(json_obj)


def deserialize_from_json(context, as_json: str):
    """Add the bone groups (one or more) from JSON to the current rig."""
    import json
    json_obj = json.loads(as_json)
    bone_groups = context.object.bone_groups
    for name, bones in json_obj.items():
        new_group = bone_groups.add()
        new_group.group_name = generate_unique_name(name, bone_groups.keys())
        for bone_name in bones:
            entry = new_group.bones.add()
            entry.bone_name = bone_name


def generate_unique_name(base_name: str, existing_names) -> str:
    """Return a unique name with .xxx suffix if necessary."""
    if base_name not in existing_names:
        return base_name

    offset = len(base_name) + 1
    candidates = (n[offset:] for n in existing_names if n.startswith(base_name + '.'))
    used_numbers = sorted(int(suffix) for suffix in candidates if suffix.isdigit())

    next_num = 1
    for num in used_numbers:
        if next_num < num:
            break
        next_num = num + 1

    return "{}.{:03d}".format(base_name, next_num)


