def register():
    for cls in classes:
        bpy.utils.register_class(cls)

    # Add properties.
    bpy.types.Object.bone_groups = CollectionProperty(
        type=BoneGroup,
        name="Bone Groups",
        description="List of groups of bones for easy selection"
    )
    bpy.types.Object.active_bone_group = IntProperty(
        name="Active Bone Group",
        description="Index of the currently active bone group",
        default=0
    )

    # Add shortcuts to the keymap.
    wm = bpy.context.window_manager
    km = wm.keyconfigs.addon.keymaps.new(name='Pose')
    kmi = km.keymap_items.new('wm.call_menu', 'W', 'PRESS', alt=True, shift=True)
    kmi.properties.name = 'POSE_MT_selection_sets_select'
    addon_keymaps.append((km, kmi))

    # Add entries to menus.
    bpy.types.VIEW3D_MT_select_pose.append(menu_func_select_bone_group)


def unregister():
    for cls in classes:
        bpy.utils.unregister_class(cls)

    # Clear properties.
    del bpy.types.Object.bone_groups
    del bpy.types.Object.active_bone_group

    # Clear shortcuts from the keymap.
    for km, kmi in addon_keymaps:
        km.keymap_items.remove(kmi)
    addon_keymaps.clear()

    # Clear entries from menus.
    bpy.types.VIEW3D_MT_select_pose.remove(menu_func_select_bone_group)


