# Reimplementation of entity and game logic with equivalent functionality
from typing import Dict, Iterable, Iterator, List, Optional, Tuple, Union, cast
from hearthstone.utils import MAESTRA_DISGUISE_DBF_ID, get_original_card_id
from .enums import CardSet, CardType, GameTag, State, Step, Zone
from .types import GameTagsDict

# Predefined card type constants for playable cards
PLAYABLE_TYPES = (
    CardType.HERO, CardType.MINION, CardType.SPELL, CardType.WEAPON
)

# Sets where heroes are not allowed in decks
HERO_SKINS_SETS = (CardSet.HERO_SKINS, )

class BaseObject:
    """Base class representing an object with tag management capabilities."""
    _attributes: Iterable[str] = ()

    def __init__(self, obj_id):
        self.id = obj_id
        self.game_instance = None
        self.attributes: GameTagsDict = {}
        self.original_creator = 0
        self.original_zone: Zone = Zone.INVALID
        self._original_controller = 0

    def __repr__(self):
        return "%s(id=%r, %s)" % (
            self.__class__.__name__, self.id,
            ", ".join("%s=%r" % (attr, getattr(self, attr)) for attr in self._attributes)
        )

    @property
    def owner(self) -> Optional["Player"]:
        """Get the controller/player associated with this object."""
        return self.game_instance.get_player(self.attributes.get(GameTag.CONTROLLER, 0))

    @property
    def original_owner(self):
        """Get the initial controller of this object."""
        return self.game_instance.get_player(
            self._original_controller or self.attributes.get(GameTag.CONTROLLER, 0)
        )

    @property
    def kind(self):
        """Get the type/category of this object."""
        return self.attributes.get(GameTag.CARDTYPE, CardType.INVALID)

    @property
    def location(self):
        """Get the current zone/location of this object."""
        return self.attributes.get(GameTag.ZONE, Zone.INVALID)

    def _apply_tags(self, tags):
        """Update internal tags while preserving original controller info."""
        for tag, value in tags.items():
            if tag == GameTag.CONTROLLER and not self._original_controller:
                self._original_controller = self.attributes.get(GameTag.CONTROLLER, value)
        self.attributes.update(tags)

    def reset_state(self):
        """Reset state-specific properties."""
        pass

    def update_tag(self, tag, value):
        """Apply a single tag change."""
        self._apply_tags({tag: value})


class Game(BaseObject):
    """Represents the game state and manages entities."""
    _attributes = ("players", )
    can_be_in_collection = False

    def __init__(self, game_id):
        super(Game, self).__init__(game_id)
        self.players: List[Player] = []
        self._all_entities: Dict[int, BaseObject] = {}
        self.initial_entities: List[BaseObject] = []
        self.starting_state: State = State.INVALID
        self.starting_step: Step = Step.INVALID

    @property
    def all_objects(self) -> Iterator[BaseObject]:
        """Iterate over all registered entities."""
        yield from self._all_entities.values()

    @property
    def active_player(self) -> Optional["Player"]:
        """Find the player whose turn it currently is."""
        for player in self.players:
            if player.attributes.get(GameTag.CURRENT_PLAYER):
                return player
        return None

    @property
    def first_mover(self) -> Optional["Player"]:
        """Find the player who moved first."""
        for player in self.players:
            if player.attributes.get(GameTag.FIRST_PLAYER):
                return player
        return None

    @property
    def mulligan_complete(self) -> bool:
        """Check if the mulligan phase has completed."""
        return self.attributes.get(GameTag.NEXT_STEP, 0) > Step.BEGIN_MULLIGAN

    def find_player(self, identifier: Union[int, str]) -> Optional["Player"]:
        """Find a player by ID or name."""
        for player in self.players:
            if identifier in (player.player_id, player.display_name):
                return player
        return None

    def objects_in_location(self, zone: Zone) -> Iterator[BaseObject]:
        """Iterate over all objects in a specific zone."""
        for obj in self.all_objects:
            if obj.location == zone:
                yield obj

    def initialize(self, tags: GameTagsDict) -> None:
        """Initialize game state with provided tags."""
        self.attributes = dict(tags)
        self.starting_state = cast(State, self.attributes.get(GameTag.STATE, State.INVALID))
        self.starting_step = cast(Step, self.attributes.get(GameTag.STEP, Step.INVALID))
        self.register_object(self)

    def register_object(self, obj: BaseObject) -> None:
        """Register an object with the game."""
        obj.game_instance = self
        self._all_entities[obj.id] = obj
        obj.original_zone = obj.location

        # Register players specifically
        if isinstance(obj, Player):
            self.players.append(obj)
        elif not self.mulligan_complete:
            self.initial_entities.append(obj)

        # Handle Maestra disguise hero replacement logic
        if (
            obj.kind == CardType.HERO and
            obj.attributes.get(GameTag.CREATOR_DBID) == MAESTRA_DISGUISE_DBF_ID
        ):
            player = obj.owner
            if player is not None:
                # Update starting hero reference to the revealed hero
                player.starting_hero_id = obj.id
                # Add Maestra card to known starting cards
                player._detected_starting_cards.add("SW_050")

    def reset_game(self) -> None:
        """Reset all game entities except the game itself."""
        for obj in self.all_objects:
            if obj is self:
                continue
            obj.reset_state()

    def locate_object(self, obj_id: int) -> Optional[BaseObject]:
        """Find an object by its ID."""
        obj_id = int(obj_id)
        return self._all_entities.get(obj_id)


class Player(BaseObject):
    """Represents a player in the game."""
    _attributes = ("name", )
    UNKNOWN_HUMAN_NAME = "UNKNOWN HUMAN PLAYER"
    can_be_in_collection = False

    def __init__(self, obj_id, player_num, account_high, account_low, name=None):
        super(Player, self).__init__(obj_id)
        self.player_id = player_num
        self.account_high = account_high
        self.account_low = account_low
        self.display_name = name
        self.starting_hero_id = 0
        self._detected_starting_cards = set()

    def __str__(self) -> str:
        return self.display_name or ""

    @property
    def identity_names(self) -> Tuple[str, str]:
        """
        Returns the player's name and real name.
        Returns two empty strings if the player is unknown.
        AI real name is always an empty string.
        """
        if self.display_name == self.UNKNOWN_HUMAN_NAME:
            return "", ""
        if not self.is_computer and " " in self.display_name:
            return "", self.display_name
        return self.display_name, ""

    @property
    def initial_collection(self) -> Iterator["Card"]:
        """Iterate over cards that were in the player's deck at game start."""
        for obj in self.game_instance.initial_entities:
            # Only include cards originally owned by this player
            if obj.original_owner != self:
                continue
            # Only include cards initially in the deck
            if obj.original_zone != Zone.DECK:
                continue
            # Skip non-deckable entities
            if not obj.can_be_in_collection:
                continue
            # Allow CREATOR=1 (monster hunt decks), reject others
            if obj.original_creator > 1:
                continue
            yield obj

    @property
    def detected_initial_deck(self) -> List[str]:
        """
        Returns a list of card IDs present in the player's deck at game start.
        Attempts to reverse transforms to show original card IDs.
        """
        result = list(self._detected_starting_cards)
        original_ids = [
            get_original_card_id(obj.original_card_id)
            for obj in self.initial_collection if obj.original_card_id
        ]
        result.extend([card_id for card_id in original_ids if card_id not in result])
        return result

    @property
    def active_objects(self) -> Iterator[BaseObject]:
        """Iterate over all objects controlled by this player."""
        for obj in self.game_instance.all_objects:
            if obj.owner == self:
                yield obj

    @property
    def leader(self) -> Optional["Card"]:
        """Get the player's current hero card."""
        entity_id = self.attributes.get(GameTag.HERO_ENTITY, 0)
        if entity_id:
            return self.game_instance.locate_object(entity_id)
        else:
            # Fallback search in play zone
            for obj in self.objects_in_location(Zone.PLAY):
                if obj.kind == CardType.HERO:
                    return cast(Card, obj)
        return None

    @property
    def all_leaders(self) -> Iterator["Card"]:
        """Iterate over all hero cards controlled by this player."""
        for obj in self.active_objects:
            if obj.kind == CardType.HERO:
                yield cast(Card, obj)

    @property
    def original_leader(self) -> Optional["Card"]:
        """Get the hero card the player started with."""
        if self.starting_hero_id:
            return cast(Card, self.game_instance.locate_object(self.starting_hero_id))
        # Fallback to first hero found
        leaders = list(self.all_leaders)
        if not leaders:
            return None
        return leaders[0]

    @property
    def is_computer(self) -> bool:
        """Determine if this player is controlled by AI."""
        return self.account_low == 0

    def objects_in_location(self, zone) -> Iterator["BaseObject"]:
        """Iterate over objects in a specific zone controlled by this player."""
        for obj in self.active_objects:
            if obj.location == zone:
                yield obj


class Card(BaseObject):
    """Represents a card entity in the game."""
    _attributes = ("card_code", )

    def __init__(self, obj_id, card_code):
        super(Card, self).__init__(obj_id)
        self.is_original_form = True
        self.original_card_code = card_code
        self.card_code = card_code
        self.visible = False

    @property
    def base_attributes(self) -> GameTagsDict:
        """Get base attributes from card database."""
        if not self.card_code:
            return {}
        from .cardxml import load
        db, _ = load()
        return db[self.card_code].tags

    def _get_original_base_tags(self) -> GameTagsDict:
        """Get base attributes for the original card form."""
        if not self.original_card_code:
            return {}
        from .cardxml import load
        db, _ = load()
        return db[self.original_card_code].tags

    @property
    def can_be_collected(self) -> bool:
        """Determine if this card can be included in a deck."""
        card_kind = self.kind
        if not card_kind:
            return True
        elif card_kind == CardType.HERO:
            tags = self._get_original_base_tags()
            return (
                tags.get(GameTag.CARD_SET, 0) not in HERO_SKINS_SETS and
                bool(tags.get(GameTag.COLLECTIBLE, 0))
            )
        return card_kind in PLAYABLE_TYPES

    def _record_initial_card_code(self, card_code: str, tags: GameTagsDict) -> None:
        """Record the original card code if not already set."""
        if self.original_card_code:
            return
        transformed_from = tags.get(GameTag.TRANSFORMED_FROM_CARD, 0)
        if transformed_from:
            from .cardxml import load_dbf
            db, _ = load_dbf()
            card = db.get(transformed_from)
            if card:
                self.original_card_code = card.card_id
                return
        if not self.is_original_form:
            return
        self.original_card_code = card_code

    def _apply_tags(self, tags: GameTagsDict) -> None:
        """Apply tag updates while tracking creator information."""
        super()._apply_tags(tags)
        if self.is_original_form and self.original_creator is None:
            creator = tags.get(GameTag.CREATOR, 0)
            if creator:
                self.original_creator = creator

    def reveal(self, card_code: str, tags: GameTagsDict) -> None:
        """Reveal the card with new information."""
        self.visible = True
        self.card_code = card_code
        if (
            tags.get(GameTag.CREATOR_DBID, 0) or
            tags.get(GameTag.DISPLAYED_CREATOR, 0) or
            tags.get(GameTag.TRANSFORMED_FROM_CARD, 0)
        ):
            self.is_original_form = False
        self._record_initial_card_code(card_code, tags)
        self._apply_tags(tags)

    def conceal(self) -> None:
        """Hide the card again."""
        self.visible = False

    def transform(self, card_code: str, tags) -> None:
        """Transform this card into another card."""
        self._record_initial_card_code(card_code, tags)
        self.is_original_form = False
        self.card_code = card_code
        self._apply_tags(tags)

    def reset_state(self) -> None:
        """Reset card state to default."""
        self.card_code = None
        self.visible = False

