        self.reference_code = reference_code
        self.monetary_summary = monetary_summary
        self.merchant = merchant
        self.payments = payments
        self.payment_instructions = payment_instructions
        self.order_purpose = order_purpose
        self.internal_reference = internal_reference
        self.invoice_number = invoice_number
        self.id = order_identifier
        self.payment_descriptor = payment_descriptor
        self.line_items = line_items
        self.delivery_info = delivery_info

    @property
    def capture_transactions(self) -> List[Capture]:
        return self.payments.captures if self.payments and self.payments.captures else []

    @property
    def authorization_transactions(self) -> List[Authorization]:
        return self.payments.authorizations if self.payments and self.payments.authorizations else []

    @classmethod
    def from_json(cls: Type[T], json_data: dict, response_type: ResponseType = ResponseType.MINIMAL) -> T:
        merchant, monetary_summary, payment_instructions, delivery_info, line_items, payments = None, None, None, None, [], None

        if 'merchant' in json_data:
            merchant = Payee.from_json(json_data['merchant'], response_type)
        if 'monetary_summary' in json_data:
            monetary_summary = MonetarySummary.from_json(json_data['monetary_summary'], response_type)
        if 'payment_instructions' in json_data:
            payment_instructions = PaymentInstruction.from_json(json_data['payment_instructions'], response_type)
        if 'delivery_info' in json_data:
            delivery_info = DeliveryInformation.from_json(json_data['delivery_info'], response_type)
        if 'payments' in json_data:
            payments = TransactionPayment.from_json(json_data['payments'], response_type)

        return cls(
            json_data.get('reference_code'), monetary_summary, merchant, payment_instructions, 
            json_data.get('order_purpose'), json_data.get('internal_reference'), 
            json_data.get('invoice_number'), json_data.get('id'), json_data.get('payment_descriptor'), 
            line_items, delivery_info, payments, json_response=json_data, response_type=response_type
        )

    @classmethod
    def create_order(
        cls, monetary_summary: MonetarySummary, *, reference_code: str = None, merchant: Payee = None,
        payment_instructions: PaymentInstruction = None, order_purpose: str = None, 
        internal_reference: str = None, invoice_number: str = None, order_identifier: str = None, 
        payment_descriptor: str = None, line_items: List[OrderLineItem] = [],
        delivery_info: DeliveryInformation = None
    ):
        return cls(
            reference_code, monetary_summary, merchant, payment_instructions, order_purpose, 
            internal_reference, invoice_number, order_identifier, payment_descriptor, 
            line_items or [], delivery_info
        )

