class OrderTransaction(PayPalEntity):
    """Paypal Order transaction object representation."""
    def __init__(self, transaction_intent: str, customer: CustomerInformation, purchase_orders: List[PurchaseOrder], app_context: OrderContext, **kwargs):
        super().__init__(kwargs.get('json_response', dict()), kwargs.get('response_type', ResponseType.MINIMAL))
        self.transaction_intent = transaction_intent
        self.customer = customer
        self.purchase_orders = purchase_orders
        self.app_context = app_context
        self.status = self._json_response.get('status')
        self.id = self._json_response.get('id', kwargs.get('id'))
        self._created_at = self._json_response.get('create_time')
        self._last_updated = self._json_response.get('update_time')
        self.links = [ActionLink(x['href'], x['rel'], x.get('method', 'GET')) for x in self._json_response.get('links', [])]

    @property
    def status_enum(self) -> TransactionStatus:
        try:
            return TransactionStatus[self.status] if self.status else None
        except:
            return None

    @property
    def created_at(self) -> datetime:
        try:
            return datetime.strptime(self._created_at, '%Y-%m-%d') if self._created_at else None
        except:
            return None

    @property
    def last_updated(self) -> datetime:
        try:
            return datetime.strptime(self._last_updated, '%Y-%m-%d') if self._last_updated else None
        except:
            return None

