# Type III clone: Refactored SI unit conversion functions with equivalent logic
from __future__ import annotations
from ..TypesHelper import Number_t
from . import SIUnits
from ..prefixes import SIPrefixes

def celsius_to_kelvin(value: Number_t, *, power: Number_t = 1) -> Number_t:
    """Convert Celsius to Kelvin with optional power scaling."""
    return SIUnits.kelvinUnit(value + 273.15, power=power)

def hertz_with_scaling(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Hertz unit with exponential and prefix scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")
    return value / SIUnits.secondUnit(1, exp10=-factor, power=power)

def newton_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Newton unit (kg·m/s²) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=power)
    denominator = SIUnits.secondUnit(1, power=2 * power)
    return numerator / denominator

def pascal_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Pascal unit (N/m²) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    numerator = SIUnits.kilogramUnit(value, exp10=factor, power=power)
    denominator = SIUnits.meterUnit(1, power=power) * SIUnits.secondUnit(1, power=2 * power)
    return numerator / denominator

def joule_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Joule unit (N·m) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=2 * power)
    denominator = SIUnits.secondUnit(1, power=2 * power)
    return numerator / denominator

def watt_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Watt unit (J/s) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=2 * power)
    denominator = SIUnits.secondUnit(1, power=3 * power)
    return numerator / denominator

def coulomb_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Coulomb unit (A·s) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    return SIUnits.secondUnit(value, power=power) * SIUnits.ampereUnit(1, exp10=factor, power=power)

def volt_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Volt unit (W/A) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    numerator = SIUnits.kilogramUnit(value, power=power) * SIUnits.meterUnit(1, exp10=factor, power=2 * power)
    denominator = SIUnits.secondUnit(1, power=3 * power) * SIUnits.ampereUnit(1, power=power)
    return numerator / denominator

def farad_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Farad unit (C/V) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    return coulomb_scaled(value, exp10=factor, power=power) / volt_scaled(1, power=power)

def ohm_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Ohm unit (V/A) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    return volt_scaled(value, exp10=factor, power=power) / SIUnits.ampereUnit(1, power=power)

def siemens_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Siemens unit (1/Ω) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    return value / ohm_scaled(1, exp10=-factor, power=power)

def weber_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Weber unit (V·s) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    return joule_scaled(value, exp10=factor, power=power) / SIUnits.ampereUnit(1, power=power)

def tesla_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Tesla unit (Wb/m²) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    numerator = SIUnits.kilogramUnit(value, exp10=factor, power=power)
    denominator = SIUnits.ampereUnit(1, power=power) * SIUnits.secondUnit(1, power=2 * power)
    return numerator / denominator

def henry_scaled(value: Number_t, *, exp10: int = 0, prefix: str = "", power: Number_t = 1) -> Number_t:
    """Create Henry unit (Wb/A) with scaling."""
    factor = SIPrefixes.magnitudeFactor(prefix, "") * power + exp10
    if not isinstance(factor, int):
        raise RuntimeError("Exponent must be an integer")

    numerator = volt_scaled(value, exp10=factor, power=power) * SIUnits.secondUnit(1, power=power)
    denominator = SIUnits.ampereUnit(1, power=power)
    return numerator / denominator

