    delete_directory(flag=first_arg, folder=second_arg)
else:
    print("Please type '--rmdir' followed by the directory name")

# Tic-Tac-Toe with speech recognition support and AI opponent

import random
import sys
import speech_recognition as sr

# Game configuration
difficulty_level = 0  # 0: Easy, 1: Normal, 2: Hard
board_state = ['1', '2', '3', '4', '5', '6', '7', '8', '9']
current_game = None
is_human_turn = True
player_symbols = {True: 'X', False: 'O'}
player_names = {True: 'Human', False: 'Computer AI'}
match_ended = False

# Speech recognition setup
speech_converter = sr.Recognizer()
word_to_number = {
    'one': 0, 'two': 1, 'three': 2, 'four': 3, 'five': 4,
    'six': 5, 'seven': 6, 'eight': 7, 'nine': 8
}

def display_board():
    global current_game
    current_game = """
\t          |     |     
\t       %(g0)s  |  %(g1)s  |  %(g2)s
\t     _____|_____|_____
\t          |     |     
\t       %(g3)s  |  %(g4)s  |  %(g5)s
\t     _____|_____|_____
\t          |     |     
\t       %(g6)s  |  %(g7)s  |  %(g8)s  
\t          |     |
""" % {'g0': board_state[0], 'g1': board_state[1], 'g2': board_state[2],
       'g3': board_state[3], 'g4': board_state[4], 'g5': board_state[5],
       'g6': board_state[6], 'g7': board_state[7], 'g8': board_state[8]}

def show_game_status():
    print('\n\t===========================\n\t\tTIC-TAC-TOE\n\t===========================')
    display_board()
    print(current_game)

    if match_ended:
        return

    if is_human_turn:
        print(' Turn: Human')
        print(' HINT: To make a move, speak a free position number.')
        get_human_input()
    else:
        print(' Turn: Computer AI - Please wait, thinking....')

def execute_move(position):
    global is_human_turn, match_ended

    if match_ended:
        print('Game Over!')
        return

    if position < 0 or position > 8:
        print('Invalid Move, out of bounds')
        if is_human_turn:
            get_human_input()
        return

    if not board_state[position].isdigit():
        print('Invalid move, already placed')
        if is_human_turn:
            get_human_input()
        return

    board_state[position] = player_symbols[is_human_turn]

    if check_victory():
        match_ended = True
        show_game_status()
        winner_name = player_names[is_human_turn]
        symbol = player_symbols[is_human_turn]
        print(f'Game Over, {winner_name} [{symbol}] is the winner!')
        return

    is_human_turn = not is_human_turn
    show_game_status()

    if not is_human_turn:
        ai_make_move()

def ai_make_move():
    if difficulty_level == 0:
        while True:
            pos = random.randint(0, 8)
            if board_state[pos].isdigit():
                execute_move(pos)
                break

def check_victory():
    sym = player_symbols[is_human_turn]
    return (
        # Rows
        (board_state[6] == sym and board_state[7] == sym and board_state[8] == sym) or
        (board_state[3] == sym and board_state[4] == sym and board_state[5] == sym) or
        (board_state[0] == sym and board_state[1] == sym and board_state[2] == sym) or
        # Columns
        (board_state[6] == sym and board_state[3] == sym and board_state[0] == sym) or
        (board_state[7] == sym and board_state[4] == sym and board_state[1] == sym) or
        (board_state[8] == sym and board_state[5] == sym and board_state[2] == sym) or
        # Diagonals
        (board_state[6] == sym and board_state[4] == sym and board_state[2] == sym) or
        (board_state[8] == sym and board_state[4] == sym and board_state[0] == sym)
    )

def reset_game():
    global board_state, is_human_turn, match_ended
    board_state = ['1', '2', '3', '4', '5', '6', '7', '8', '9']
    is_human_turn = True
    match_ended = False

def get_human_input():
    if match_ended or not is_human_turn:
        return

    with sr.Microphone() as source:
        print("Say something!")
        audio_data = speech_converter.listen(source)

    recognized_text = None

    try:
        # Try Google Speech Recognition first
        recognized_text = speech_converter.recognize_google(audio_data)
        handle_speech_input(recognized_text)
    except sr.UnknownValueError:
        print("Google Speech Recognition could not understand audio")
    except sr.RequestError as error:
        print(f"Could not request results from Google Speech Recognition service; {error}")

    if recognized_text is None:
        # Fallback to Sphinx
        try:
            recognized_text = speech_converter.recognize_sphinx(audio_data)
            handle_speech_input(recognized_text)
        except sr.UnknownValueError:
            print("Sphinx could not understand audio")
        except sr.RequestError as error:
            print(f"Sphinx error; {error}")

def handle_speech_input(text):
    if text.isdigit():
        num = int(text)
        if num < 1 or num > 9:
            print('Invalid Move, out of bounds, try again')
            get_human_input()
            return
        else:
            execute_move(num - 1)
            return

    if text.lower() in word_to_number:
        execute_move(word_to_number[text.lower()])
        return

    print(f'Invalid Move, not recognized "{text}", try again')
    get_human_input()

def main_loop():
    while True:
        show_game_status()
        user_input = input("Type 'q' to quit or 'r' to restart\n")

        if not match_ended and is_human_turn and user_input.isdigit() and 1 <= int(user_input) <= 9:
            execute_move(int(user_input) - 1)
            continue

        if user_input.lower() == 'q':
            sys.exit(1)
        elif user_input.lower() == 'r':
            reset_game()
            continue

if __name__ == "__main__":
    main_loop()

import collections
from typing import Dict, Counter, List, Optional, Sequence
import numpy as np
import cirq

class QPUResult:
    """The results of running on an IonQ QPU."""
    def __init__(
        self, counts: Dict[int, int], num_qubits: int, measurement_dict: Dict[str, Sequence[int]]
    ):
        # Maintain consistent ordering using sorted items
        self._counts = collections.OrderedDict(sorted(counts.items()))
        self._num_qubits_val = num_qubits
        self._measurement_dict = measurement_dict
        self._repetitions = sum(self._counts.values())

    def num_qubits(self) -> int:
        """Returns the number of qubits the circuit was run on."""
        return self._num_qubits_val

    def repetitions(self) -> int:
        """Returns the number of times the circuit was run."""
        return self._repetitions

    def ordered_results(self, key: Optional[str] = None) -> List[int]:
        """Returns a list of consistently ordered results as big endian ints."""
        if key is not None and key not in self._measurement_dict:
            raise ValueError(
                f'Measurement key {key} is not a key for a measurement gate in the'
                'circuit that produced these results.'
            )

        targets = self._measurement_dict[key] if key is not None else range(self.num_qubits())
        result: List[int] = []

        for value, count in self._counts.items():
            # Extract bits for each target qubit
            bits = []
            for target in targets:
                bit_pos = self.num_qubits() - target - 1
                bit = (value >> bit_pos) & 1
                bits.append(bit)

            # Convert to big-endian integer
            bit_value = 0
            for i, bit in enumerate(reversed(bits)):
                bit_value += bit * (1 << i)

            result.extend([bit_value] * count)

        return result

    def counts(self, key: Optional[str] = None) -> Counter[int]:
        """Returns the processed counts of the measurement results."""
        if key is None:
            return collections.Counter(self._counts)

        if key not in self._measurement_dict:
            raise ValueError(
                f'Measurement key {key} is not a key for a measurement gate in the'
                'circuit that produced these results.'
            )

        result: Counter[int] = collections.Counter()
        result.update(self.ordered_results(key))
        return result

    def measurement_dict(self) -> Dict[str, Sequence[int]]:
        """Returns a map from measurement keys to target qubit indices for this measurement."""
        return self._measurement_dict

    def to_cirq_result(
        self,
        params: Optional[cirq.ParamResolver] = None,
    ) -> cirq.Result:
        """Returns a `cirq.Result` for these results."""
        if len(self.measurement_dict()) == 0:
            raise ValueError(
                'Can convert to cirq results only if the circuit had measurement gates '
                'with measurement keys.'
            )

        measurements = {}
        for key, targets in self.measurement_dict().items():
            qpu_results = self.ordered_results(key)
            # Convert integers to bit arrays
            bit_arrays = []
            for x in qpu_results:
                bits = cirq.big_endian_int_to_bits(x, bit_count=len(targets))
                bit_arrays.append(bits)
            measurements[key] = np.array(bit_arrays)

        return cirq.Result(params=params or cirq.ParamResolver({}), measurements=measurements)

    def __eq__(self, other):
        if not isinstance(other, QPUResult):
            return NotImplemented
        return (
            self._counts == other._counts
            and self._num_qubits_val == other._num_qubits_val
            and self._measurement_dict == other._measurement_dict
            and self._repetitions == other._repetitions
        )

    def __str__(self) -> str:
        return _pretty_str_dict(self._counts, self._num_qubits_val)

class SimulatorResult:
    """The results of running on an IonQ simulator."""
    def __init__(
        self,
        probabilities: Dict[int, float],
        num_qubits: int,
        measurement_dict: Dict[str, Sequence[int]],
        repetitions: int,
    ):
        self._probabilities = probabilities
        self._num_qubits_val = num_qubits
        self._measurement_dict = measurement_dict
        self._repetitions = repetitions

    def num_qubits(self) -> int:
        """Returns the number of qubits the circuit was run on."""
        return self._num_qubits_val

    def repetitions(self) -> int:
        """Returns the number of times the circuit was run."""
        return self._repetitions

    def probabilities(self, key: Optional[str] = None) -> Dict[int, float]:
        """Returns the probabilities of the measurement results."""
        if key is None:
            return self._probabilities

        if key not in self._measurement_dict:
            raise ValueError(
                f'Measurement key {key} is not a key for a measurement gate in the'
                'circuit that produced these results.'
            )

        targets = self._measurement_dict[key]
        result: Dict[int, float] = dict()

        for value, probability in self._probabilities.items():
            # Extract bits for each target qubit
            bits = []
            for target in targets:
                bit_pos = self.num_qubits() - target - 1
                bit = (value >> bit_pos) & 1
                bits.append(bit)

            # Convert to big-endian integer
            bit_value = 0
            for i, bit in enumerate(reversed(bits)):
                bit_value += bit * (1 << i)

            # Accumulate probabilities for same bit values
            if bit_value in result:
                result[bit_value] += probability
            else:
                result[bit_value] = probability

        return result

    def measurement_dict(self) -> Dict[str, Sequence[int]]:
        """Returns a map from measurement keys to target qubit indices for this measurement."""
        return self._measurement_dict

    def to_cirq_result(
        self,
        params: cirq.ParamResolver = None,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
        override_repetitions=None,
    ) -> cirq.Result:
        """Samples from the simulation probability result, producing a `cirq.Result`."""
        if len(self.measurement_dict()) == 0:
            raise ValueError(
                'Can convert to cirq results only if the circuit had measurement gates '
                'with measurement keys.'
            )

        rand = cirq.value.parse_random_state(seed)
        measurements = {}

        values, weights = zip(*list(self.probabilities().items()))
        indices = rand.choice(
            range(len(values)), p=weights, size=override_repetitions or self.repetitions()
        )
        rand_values = np.array(values)[indices]

        for key, targets in self.measurement_dict().items():
            # Generate bit arrays for each sampled value
            bit_arrays = []
            for value in rand_values:
                bits = []
                for target in targets:
                    bit_pos = self.num_qubits() - target - 1
                    bit = (value >> bit_pos) & 1
                    bits.append(bit)
                bit_arrays.append(bits)
            measurements[key] = np.array(bit_arrays)

        return cirq.Result(params=params or cirq.ParamResolver({}), measurements=measurements)

    def __eq__(self, other):
        if not isinstance(other, SimulatorResult):
            return NotImplemented
        return (
            self._probabilities == other._probabilities
            and self._num_qubits_val == other._num_qubits_val
            and self._measurement_dict == other._measurement_dict
            and self._repetitions == other._repetitions
        )

    def __str__(self) -> str:
        return _pretty_str_dict(self._probabilities, self._num_qubits_val)

def _pretty_str_dict(value: dict, bit_count: int) -> str:
    """Pretty prints a dict, converting int dict values to bit strings."""
    strs = []
    for k, v in value.items():
        bits = ''.join(str(b) for b in cirq.big_endian_int_to_bits(k, bit_count=bit_count))
        strs.append(f'{bits}: {v}')
    return '\n'.join(strs)

import logging
import multiprocessing
import os
import re
import sys
import time
from copy import deepcopy
from concurrent.futures import ProcessPoolExecutor, as_completed

import psutil

from pyro.Anonymizer import Anonymizer
from pyro.Enums.BuildEvent import BuildEvent
from pyro.Comparators import is_command_node
from pyro.PackageManager import PackageManager
from pyro.PapyrusProject import PapyrusProject
from pyro.PathHelper import PathHelper
from pyro.PexReader import PexReader
from pyro.ProcessManager import ProcessManager
from pyro.Enums.ProcessState import ProcessState
from pyro.TimeElapsed import TimeElapsed

from pyro.Comparators import endswith


class BuildFacade:
    log: logging.Logger = logging.getLogger('pyro')

    ppj: PapyrusProject = None

    _timer: TimeElapsed = TimeElapsed()

    total_scripts: int = 0
    compiled_successfully: int = 0
    total_commands: int = 0

    @property
    def failed_count(self) -> int:
        return self.total_commands - self.compiled_successfully

    @property
    def build_time(self) -> str:
        elapsed = self._timer.value()
        avg_per_script = elapsed / self.compiled_successfully if self.compiled_successfully else 0.0
        return (
            f"Compilation time: "
            f"{elapsed:.3f}s ({avg_per_script:.3f}s/script) - "
            f"{self.compiled_successfully} succeeded, "
            f"{self.failed_count} failed "
            f"({self.total_scripts} scripts)"
        )

    def __init__(self, ppj: PapyrusProject) -> None:
        self.ppj = ppj
        self.total_scripts = len(ppj.psc_paths)

        # Copy options and selectively override defaults from project instance
        cfg = deepcopy(ppj.options.__dict__)
        skip_keys = {'args', 'input_path', 'anonymize', 'package', 'zip', 'zip_compression'}
        ignore_prefixes = ('ignore_', 'no_', 'force_', 'resolve_')
        ignore_suffixes = ('_token',)

        for attr_name, value in cfg.items():
            if attr_name in skip_keys:
                continue
            if any(attr_name.startswith(prefix) for prefix in ignore_prefixes):
                continue
            if any(attr_name.endswith(suffix) for suffix in ignore_suffixes):
                continue
            getter_name = f'get_{attr_name}'
            if hasattr(ppj, getter_name):
                setattr(ppj.options, attr_name, getattr(ppj, getter_name)())

    def _detect_stale_compilations(self) -> list:
        """Identify .pex files that were compiled before their corresponding .psc source."""
        stale_pex = []

        for obj_name, psc_path in self.ppj.psc_paths.items():
            base_name = os.path.splitext(os.path.basename(psc_path))[0]
            candidates = [p for p in self.ppj.pex_paths if endswith(p, f'{base_name}.pex', ignorecase=True)]
            if not candidates:
                continue

            pex_file = candidates[0]
            if not os.path.isfile(pex_file):
                continue

            try:
                header = PexReader.get_header(pex_file)
            except ValueError:
                BuildFacade.log.warning(f'Cannot determine compilation time due to unknown magic: "{pex_file}"')
                continue

            psc_mtime = os.path.getmtime(psc_path)
            pex_ctime = float(header.compilation_time.value)

            if psc_mtime < pex_ctime:
                stale_pex.append(pex_file)

        return PathHelper.uniqify(stale_pex)

    @staticmethod
    def _reduce_process_priority() -> None:
        proc = psutil.Process(os.getpid())
        priority = psutil.BELOW_NORMAL_PRIORITY_CLASS if sys.platform == 'win32' else 19
        proc.nice(priority)

    def trigger_build_hook(self, phase: BuildEvent) -> None:
        if phase == BuildEvent.PRE:
            has_hook, hook_node = self.ppj.has_pre_build_node, self.ppj.pre_build_node
        elif phase == BuildEvent.POST:
            has_hook, hook_node = self.ppj.has_post_build_node, self.ppj.post_build_node
        else:
            raise NotImplementedError("Unsupported build event type")

        if has_hook:
            BuildFacade.log.info(hook_node.get('Description'))

            def normalize_whitespace(text: str) -> str:
                return re.sub(r'\s+', ' ', text.strip())

            env = os.environ.copy()
            commands = [
                normalize_whitespace(node.text)
                for node in filter(is_command_node, hook_node)
            ]
            full_cmd = ' && '.join(commands)
            ProcessManager.run_command(full_cmd, self.ppj.project_path, env)

    def execute_compilation(self) -> None:
        """Runs compiler commands either sequentially or in parallel."""
        cmds = self.ppj.build_commands()
        self.total_commands = len(cmds)
        self._timer.start_time = time.perf_counter()

        if self.ppj.options.no_parallel or self.total_commands <= 1:
            for cmd in cmds:
                if ProcessManager.run_compiler(cmd) == ProcessState.SUCCESS:
                    self.compiled_successfully += 1
        elif self.total_commands > 0:
            multiprocessing.freeze_support()
            workers = min(self.total_commands, self.ppj.options.worker_limit)
            with ProcessPoolExecutor(
                max_workers=workers,
                initializer=BuildFacade._reduce_process_priority
            ) as executor:
                futures = {executor.submit(ProcessManager.run_compiler, c): c for c in cmds}
                for future in as_completed(futures):
                    if future.result() == ProcessState.SUCCESS:
                        self.compiled_successfully += 1

        self._timer.end_time = time.perf_counter()

    def attempt_anonymization(self) -> None:
        """Obfuscates metadata in newly compiled or modified scripts."""
        outdated = self._detect_stale_compilations()
        needs_anon = outdated or self.ppj.missing_scripts or self.ppj.options.no_incremental_build

        if not needs_anon:
            BuildFacade.log.error('No modified scripts found; skipping anonymization.')
            return

        for pex_path in self.ppj.pex_paths:
            if not os.path.isfile(pex_path):
                BuildFacade.log.warning(f'Missing file for anonymization: "{pex_path}"')
                continue
            Anonymizer.anonymize_script(pex_path)

    def attempt_packaging(self) -> None:
        """Generates BSA/BA2 archives."""
        PackageManager(self.ppj).create_packages()

    def attempt_archiving(self) -> None:
        """Creates ZIP archive of output."""
        PackageManager(self.ppj).create_zip()

# Convert various location types to a string representation

from typing import Union, Sequence, List, Any
from opentrons.protocol_api.labware import Well
from opentrons.types import Location

# Define the type alias for command locations
CommandLocation = Union[Location, None, Sequence, Well]

def flatten_location(location: Any) -> List:
    """
    Recursively process location input to ensure it's in list form.
    Handles nested lists and single objects uniformly.
    """
    if isinstance(location, list):
        if len(location) == 0:
            return [location]
        else:
            # Process first element recursively, then combine with rest
            first_item = flatten_location(location[0])
            rest_items = flatten_location(location[1:])
            return first_item + rest_items
    else:
        return [location]

def format_location_component(loc: Union[Location, Well]) -> str:
    """
    Convert a single location component to its string representation.
    """
    if isinstance(loc, Location):
        if loc.labware is None or loc.labware.is_empty:
            return str(loc.point)
        else:
            return repr(loc.labware)
    elif isinstance(loc, Well):
        return str(loc)
    else:
        raise TypeError(f"Unsupported location type: {type(loc)}")

def format_command_location(location: CommandLocation) -> str:
    """
    Format a location (or sequence of locations) into a comma-separated string.
    """
    processed_locations = [format_location_component(loc) for loc in flatten_location(location)]
    return ", ".join(processed_locations)

# Type III clone: Refactored version with equivalent functionality but different structure

from typing import Any, Dict, Tuple
from collections import OrderedDict
from collections.abc import Iterable
from mypyc.ops import (
    deserialize_modules, DeserMaps, ModuleIR, FuncDecl, FuncIR, ClassIR, FuncSignature, RType
)
from mypyc.sametype import is_same_type, is_same_signature


def extract_attributes(obj: Any) -> Dict[str, Any]:
    """Extract attributes from an object, prioritizing __mypyc_attrs__ if present."""
    if hasattr(obj, '__mypyc_attrs__'):
        return {attr_name: getattr(obj, attr_name) 
                for attr_name in obj.__mypyc_attrs__ 
                if hasattr(obj, attr_name)}
    else:
        return vars(obj)


def extract_function_metadata(func_ir: FuncIR) -> Dict[str, Any]:
    """Extract function metadata suitable for comparison after serialization."""
    base_dict = extract_attributes(func_ir)
    # Exclude non-serializable or implementation-specific fields
    base_dict.pop('blocks', None)
    base_dict.pop('env', None)
    return base_dict


def compare_ir_blobs(obj_a: Any, obj_b: Any, path: Tuple[Any, ...]) -> None:
    """Recursively compare two IR objects for structural equality.

    Special handling for:
    - Named IR entities (FuncDecl, FuncIR, ClassIR): compared by fullname
    - OrderedDict/dict: key-value pairs compared recursively
    - Iterables: elements compared positionally
    - Types/signatures: using semantic equality checks
    - Primitives: direct equality check
    """
    assert type(obj_a) is type(obj_b), f"Type mismatch at {'.'.join(map(str, path))}"

    if isinstance(obj_a, (FuncDecl, FuncIR, ClassIR)):
        assert obj_a.fullname == obj_b.fullname
    elif isinstance(obj_a, OrderedDict):
        assert len(obj_a) == len(obj_b), f"Length mismatch in OrderedDict at {'.'.join(map(str, path))}"
        for (key_a, val_a), (key_b, val_b) in zip(obj_a.items(), obj_b.items()):
            compare_ir_blobs(key_a, key_b, path + ("keys",))
            compare_ir_blobs(val_a, val_b, path + (key_a,))
    elif isinstance(obj_a, dict):
        assert set(obj_a.keys()) == set(obj_b.keys()), f"Key set mismatch at {'.'.join(map(str, path))}"
        for key in obj_a:
            compare_ir_blobs(obj_a[key], obj_b[key], path + (key,))
    elif isinstance(obj_a, Iterable) and not isinstance(obj_a, (str, bytes)):
        for idx, (item_a, item_b) in enumerate(zip(obj_a, obj_b)):
            compare_ir_blobs(item_a, item_b, path + (idx,))
    elif isinstance(obj_a, RType):
        assert is_same_type(obj_a, obj_b), f"RType semantic mismatch at {'.'.join(map(str, path))}"
    elif isinstance(obj_a, FuncSignature):
        assert is_same_signature(obj_a, obj_b), f"Signature semantic mismatch at {'.'.join(map(str, path))}"
    else:
        assert obj_a == obj_b, f"Value mismatch at {'.'.join(map(str, path))}"


def validate_module_equivalence(mod1: ModuleIR, mod2: ModuleIR) -> None:
    """Verify that two module IRs are semantically equivalent post-serialization."""
    assert mod1.fullname == mod2.fullname
    assert mod1.imports == mod2.imports

    # Compare class definitions
    for cls_def1, cls_def2 in zip(mod1.classes, mod2.classes):
        compare_ir_blobs(extract_attributes(cls_def1), 
                         extract_attributes(cls_def2),
                         (mod1.fullname, cls_def1.fullname))

    # Compare function definitions
    for func_ir1, func_ir2 in zip(mod1.functions, mod2.functions):
        compare_ir_blobs(extract_function_metadata(func_ir1),
                         extract_function_metadata(func_ir2),
                         (mod1.fullname, func_ir1.fullname))
        compare_ir_blobs(extract_attributes(func_ir1.decl),
                         extract_attributes(func_ir2.decl),
                         (mod1.fullname, func_ir1.fullname))

    # Compare final names mapping
    compare_ir_blobs(mod1.final_names, mod2.final_names, (mod1.fullname, 'final_names'))


def verify_serialization_roundtrip(module_map: Dict[str, ModuleIR]) -> None:
    """Test that serialization/deserialization preserves essential module structure."""
    # Serialize all modules
    serialized_data = {name: module.serialize() for name, module in module_map.items()}

    # Prepare deserialization context
    deser_context = DeserMaps({}, {})

    # Deserialize back to IR objects
    restored_modules = deserialize_modules(serialized_data, deser_context)

    # Verify keys match
    assert set(module_map.keys()) == set(restored_modules.keys())

    # Validate each module's equivalence
    for module_name in module_map:
        validate_module_equivalence(module_map[module_name], 
                                    restored_modules[module_name])

from typing import Tuple
import numpy as np
import torch
from torch import matmul

def regularize_matrix(mat, regularization, relative_to_diag_mean=True):
    if regularization <= 0:
        return mat

    # Ensure matrix is square
    n_rows, n_cols = mat.shape[-2], mat.shape[-1]
    if n_rows != n_cols:
        raise ValueError("Matrix must be square for regularization")

    # Compute diagonal mean if needed
    if relative_to_diag_mean:
        diag_values = torch.diagonal(mat, dim1=-2, dim2=-1)
        diag_mean = diag_values.mean(dim=-1, keepdim=True)
        reg_strength = diag_mean * regularization
    else:
        reg_strength = regularization

    # Create regularization matrix and add to original
    reg_matrix = torch.diag_embed(torch.ones_like(mat[..., 0]) * reg_strength)
    return mat + reg_matrix

def cholesky(
    mat,
    upper=False,
    out=None,
    regularization=0.0,
    initial_try_regularization=1e-6,
    max_regularization=1e2,
    step_factor=10,
    warning=True,
):
    # Handle warnings and initial regularization
    if regularization > 0 and warning:
        print(f"Warning: Regularizing matrix with value: {regularization}")

    # Apply regularization if needed
    if regularization > 0:
        regularized_mat = regularize_matrix(
            mat=mat, regularization=regularization, relative_to_diag_mean=True
        )
    else:
        regularized_mat = mat

    try:
        # Attempt Cholesky decomposition
        return torch.cholesky(regularized_mat, upper=upper, out=out)
    except RuntimeError as e:
        # Check for NaNs in input
        if torch.isnan(mat).any():
            raise ValueError("NaN detected in input mat.")

        # Increase regularization and retry
        new_reg = max(regularization * step_factor, initial_try_regularization)
        if new_reg > max_regularization:
            raise ValueError(
                f"Attempted regularization ({new_reg}) exceeded maximum ({max_regularization})."
            )
        else:
            return cholesky(
                mat=mat,
                upper=upper,
                out=out,
                regularization=new_reg,
                initial_try_regularization=initial_try_regularization,
                max_regularization=max_regularization,
                step_factor=step_factor,
                warning=False,
            )

def cov_and_chol_from_invcholesky_param(Linv_tril, Linv_logdiag):
    # Construct inverse of L from parameters
    Linv = torch.tril(Linv_tril, -1) + torch.diag_embed(torch.exp(Linv_logdiag))
    # Compute L as inverse of Linv
    L = torch.inverse(Linv)
    # Return covariance matrix and Cholesky factor
    return matmul(L, L.transpose(-1, -2)), L

def cov_from_invcholesky_param(Linv_tril, Linv_logdiag):
    return cov_and_chol_from_invcholesky_param(
        Linv_tril=Linv_tril, Linv_logdiag=Linv_logdiag
    )[0]

def inv_from_invcholesky_param(Linv_tril, Linv_logdiag):
    # Construct Linv directly from parameters
    Linv = torch.tril(Linv_tril, -1) + torch.diag_embed(torch.exp(Linv_logdiag))
    # Compute inverse covariance: (Linv^T)^{-1} * Linv^{-1} = (Linv * Linv^T)^{-1}
    return matmul(Linv.transpose(-1, -2), Linv)

def batch_cholesky_inverse(Lmat):
    # Compute inverse of Cholesky factor
    Lmat_inv = torch.inverse(Lmat)
    # Compute inverse of covariance: L^{-T} * L^{-1}
    return matmul(Lmat_inv.transpose(-1, -2), Lmat_inv)

def batch_diag(mat):
    # Extract diagonal elements from each matrix in batch
    return torch.diagonal(mat, dim1=-2, dim2=-1)

def batch_diag_matrix(diagonal):
    # Create diagonal matrices from vectors
    N = diagonal.shape[-1]
    shape = diagonal.shape[:-1] + (N, N)
    device = diagonal.device
    dtype = diagonal.dtype

    # Initialize zero tensor
    result = torch.zeros(shape, dtype=dtype, device=device)

    # Set diagonal elements using advanced indexing
    idx = torch.arange(N, device=device)
    result[..., idx, idx] = diagonal
    return result

def symmetrize(mat):
    # Make matrix symmetric by averaging with its transpose
    return 0.5 * (mat + mat.transpose(-1, -2))

def matvec(mat, vec):
    # Matrix-vector multiplication handling different dimensions
    if vec.ndim == 1:
        return torch.matmul(mat, vec)
    elif mat.ndim == 2:
        return torch.matmul(vec, mat.t())
    else:
        # For batched operations
        return torch.matmul(mat, vec.unsqueeze(-1)).squeeze(-1)

def get_numerical_precision(x):
    # Determine machine epsilon for various types
    if isinstance(x, float):
        return np.finfo(np.array(x).dtype).eps
    elif isinstance(x, torch.Tensor):
        return torch.finfo(x.dtype).eps
    elif isinstance(x, (np.ndarray, np.generic)):
        return np.finfo(x.dtype).eps
    else:
        raise ValueError(f"Unknown type for precision calculation: {type(x)}")

def stable_log(x, eps=None):
    # Logarithm with numerical stability
    if eps is None:
        eps = get_numerical_precision(x)
    return torch.log(x + eps)

def kron(A, B):
    # Kronecker product implementation with batch support
    A_shp, B_shp = A.shape, B.shape
    if A_shp[:-2] != B_shp[:-2]:
        raise ValueError("Batch dimensions must match for Kronecker product")

    # Efficient computation using outer products
    kron_block = torch.einsum('...ij,...kl->...ikjl', A, B)
    kron = kron_block.reshape(
        A_shp[:-2] + (A_shp[-2] * B_shp[-2], A_shp[-1] * B_shp[-1],)
    )
    return kron

def vectorize_normal_dist_params(m, V):
    # Vectorize normal distribution parameters
    indices = torch.tril_indices(row=V.shape[-2], col=V.shape[-1], offset=0, device=V.device)
    V_vec = V[..., indices[0], indices[1]]
    return torch.cat((m, V_vec), dim=-1)

def logmeanexp(self: torch.Tensor, dim: int, keepdim: bool = False):
    # Compute log(mean(exp(x))) in a numerically stable way
    return torch.logsumexp(self, dim=dim, keepdim=keepdim) - np.log(
        self.shape[dim]
    )

def make_block_diagonal(mats: Tuple[torch.Tensor]) -> torch.Tensor:
    # Recursively build block diagonal matrix
    if not isinstance(mats, (list, tuple)):
        raise TypeError("Input must be a list or tuple of tensors")

    if len(mats) == 0:
        raise ValueError("At least one matrix required")

    if len(mats) == 1:
        return mats[0]

    # Combine last two matrices into a block
    m1, m2 = mats[-2], mats[-1]
    rows1, cols1 = m1.shape[-2], m1.shape[-1]
    rows2, cols2 = m2.shape[-2], m2.shape[-1]

    # Create off-diagonal zero blocks
    zeros_ur = torch.zeros(
        m1.shape[:-2] + (rows1, cols2),
        dtype=m1.dtype,
        device=m1.device
    )
    zeros_ll = torch.zeros(
        m2.shape[:-2] + (rows2, cols1),
        dtype=m2.dtype,
        device=m2.device
    )

    # Build combined block
    top = torch.cat([m1, zeros_ur], dim=-1)
    bottom = torch.cat([zeros_ll, m2], dim=-1)
    combined = torch.cat([top, bottom], dim=-2)

    # Recursively combine remaining matrices
    return make_block_diagonal(mats[:-2] + (combined,))

