from __future__ import unicode_literals
import os
from jinja2 import Environment, PackageLoader
from .analyzer import model_check as run_model_analysis
from .electrum2haros import parse_output as interpret_result, render_result as format_report
from .haros2electrum import config_to_model, generate_electrum_code

PLUGIN_NAME = 'haros_plugin_electrum'

def analyze_configuration(interface, configuration):
    # Early exit conditions
    if not configuration.launch_commands or len(configuration.nodes.enabled) < 2 or not configuration.hpl_properties:
        return

    plugin_config = configuration.user_attributes.get(PLUGIN_NAME, {})

    try:
        _validate_plugin_configuration(plugin_config)
    except PluginConfigurationError as error:
        interface.log_error(error.message)
        return

    jar_file_path = _locate_jar_file(plugin_config)
    analysis_scopes = _determine_analysis_scopes(plugin_config)

    template_engine = create_template_environment()

    try:
        # Generate Electrum model from ROS configuration
        electrum_model = config_to_model(configuration)
        electrum_source = generate_electrum_code(template_engine, electrum_model)

        # Write model to file
        safe_name = '_'.join(configuration.name.split())
        model_filename = f'model_{safe_name}.ele'

        with open(model_filename, 'w') as file_handle:
            file_handle.write(electrum_source)
            file_handle.write('\n')

        interface.export_file(model_filename)

        # Run analysis and process results
        analysis_output = run_model_analysis(jar_file_path, electrum_source, analysis_scopes)
        parsed_results = interpret_result(analysis_output, configuration)
        report_html = format_report(template_engine, parsed_results)

        interface.report_runtime_violation('counterexample', report_html, parsed_results.resources)

    except Exception as exception:
        interface.log_error(str(exception))

def _validate_plugin_configuration(config):
    jar_section = config.get('jar')

    if not jar_section:
        raise PluginConfigurationError.missing_jar_field()

    if not isinstance(jar_section, dict):
        raise PluginConfigurationError.jar_not_dictionary()

    has_path = 'path' in jar_section
    has_env = 'env' in jar_section

    if not has_path and not has_env:
        raise PluginConfigurationError.no_jar_location_specified()

    if has_env and not os.environ.get(jar_section['env']):
        raise PluginConfigurationError.environment_variable_missing(jar_section['env'])

    scope_section = config.get('scope')
    if scope_section:
        for dimension in ('time', 'msgs', 'values'):
            value = scope_section.get(dimension)
            if value is not None and (not isinstance(value, int) or value < 0):
                raise PluginConfigurationError.invalid_scope_value(dimension, value)

def _locate_jar_file(config):
    jar_config = config['jar']

    if 'path' in jar_config:
        return jar_config['path']
    else:
        env_variable = jar_config['env']
        return os.environ[env_variable]

def _determine_analysis_scopes(config):
    default_scopes = {
        'time': 10,
        'msgs': 9,
        'values': 4
    }

    provided_scopes = config.get('scope', {})

    for key, default_value in default_scopes.items():
        if key not in provided_scopes:
            provided_scopes[key] = default_value

    return provided_scopes

def create_template_environment():
    return Environment(
        loader=PackageLoader(PLUGIN_NAME, 'templates'),
        line_statement_prefix=None,
        line_comment_prefix=None,
        trim_blocks=True,
        lstrip_blocks=True,
        autoescape=False
    )

class PluginConfigurationError(Exception):
    @classmethod
    def missing_jar_field(cls):
        return cls('missing `jar` field in plugin settings')

    @classmethod
    def jar_not_dictionary(cls):
        return cls('expected a dictionary under the `jar` setting')

    @classmethod
    def no_jar_location_specified(cls):
        return cls('missing .jar path; expected one of `jar:path` or `jar:env`')

    @classmethod
    def environment_variable_missing(cls, var_name):
        return cls("missing '{}' environment variable containing .jar path".format(var_name))

    @classmethod
    def invalid_scope_value(cls, dimension, value):
        return cls("invalid scope value for '{}': {}".format(dimension, value))

