# Thread-safe registry for authentication backends

from threading import Lock
from pyfire.auth.exceptions import AuthenticationFailureException

class BackendRegistry:
    """Manages registered authentication backends"""

    def __init__(self):
        self._backends = {}
        self._mutex = Lock()

    def add_backend(self, name, instance):
        """Adds a new authentication backend if not already present"""
        added = False
        with self._mutex:
            if name not in self._backends:
                self._backends[name] = instance
                added = True

        if not added:
            raise ValueError("backend already registered")

    def remove_backend(self, name):
        """Removes an existing authentication backend"""
        removed = False
        with self._mutex:
            if name in self._backends:
                self._backends[name].cleanup()
                del self._backends[name]
                removed = True

        if not removed:
            raise ValueError("backend not found")

    def check_credentials(self, user, passwd):
        """Verifies user credentials against all registered backends.
           Returns the name of the first matching backend or raises
           AuthenticationFailureException if no match is found.
        """
        matched = ""
        with self._mutex:
            for backend_name, handler in self._backends.items():
                if handler.authenticate(user, passwd):
                    matched = backend_name
                    break

        if not matched:
            raise AuthenticationFailureException("invalid credentials provided")

        return matched

    def verify_session(self, session_token):
        """Validates a session token against all registered backends.
           Returns the name of the first matching backend or raises
           AuthenticationFailureException if no match is found.
        """
        matched = ""
        with self._mutex:
            for backend_name, handler in self._backends.items():
                if handler.check_token(session_token):
                    matched = backend_name
                    break

        if not matched:
            raise AuthenticationFailureException("session token invalid")

        return matched

import os
import mutagen.oggvorbis
import tempfile
from django import forms
from django.core.files import File
from django.db import models
from django.db.models.fields.files import (
    FileDescriptor,
    FieldFile,
    FileField,
)

class AudioFile(File):
    def __get_artist(self):
        return self.metadata.get("artist", "") or ""

    artist = property(__get_artist)

    def __get_title(self):
        return self.metadata.get("title", "") or ""

    title = property(__get_title)

    def __get_genre(self):
        return self.metadata.get("genre", "") or ""

    genre = property(__get_genre)

    def __get_length(self):
        return self.metadata.get("total_time", 0) or 0

    length = property(__get_length)

    def __get_metadata(self):
        if not hasattr(self, "_metadata_cache"):
            self.__cache_file_metadata()
        return self._metadata_cache

    metadata = property(__get_metadata)

    def __extract_tag_attrs(self, mf):
        result = {}
        if mf.tags is not None:
            for key in ("artist", "title", "album", "genre"):
                values = mf.tags.get(key, [])
                result[key] = ",".join(values) if values else ""
        return result

    def __extract_info_attrs(self, mf):
        result = {}
        if mf.info is not None:
            result["bitrate"] = mf.info.bitrate // 1000
            result["samplerate"] = mf.info.sample_rate
            result["total_time"] = int(mf.info.length)
        return result

    def __cache_file_metadata(self):
        def __build_metadata(mf):
            meta = {}
            meta.update(**self.__extract_tag_attrs(mf))
            meta.update(**self.__extract_info_attrs(mf))
            return meta

        was_closed = self.closed
        self.open()

        fd, tmp_path = tempfile.mkstemp()
        try:
            self.seek(0)
            data = self.read()
            os.write(fd, data)
            os.close(fd)

            try:
                audio = mutagen.oggvorbis.OggVorbis(tmp_path)
                self._metadata_cache = __build_metadata(audio)
            except mutagen.oggvorbis.OggVorbisHeaderError:
                self._metadata_cache = {}
        finally:
            os.remove(tmp_path)
            if was_closed:
                self.close()

    def __repr__(self):
        return self.name

    def __str__(self):
        return repr(self)

class AudioFileDescriptor(FileDescriptor):
    def __set__(self, instance, value):
        old_file = instance.__dict__.get(self.field.name)
        super().__set__(instance, value)
        if old_file is not None:
            self.field._refresh_metadata_fields(instance, force=True)

class AudioFieldFile(AudioFile, FieldFile):
    def delete(self, save=True):
        if hasattr(self, "_metadata_cache"):
            del self._metadata_cache
        super().delete(save)

class AudioField(FileField):
    attr_class = AudioFieldFile
    descriptor_class = AudioFileDescriptor
    description = "Audio file field"

    def __init__(
        self,
        verbose_name=None,
        name=None,
        upload_to="",
        storage=None,
        artist_field=None,
        title_field=None,
        genre_field=None,
        duration_field=None,
        size_field=None,
        **kwargs,
    ):
        self.artist_field = artist_field
        self.title_field = title_field
        self.genre_field = genre_field
        self.duration_field = duration_field
        self.size_field = size_field
        super().__init__(verbose_name, name, upload_to, storage, **kwargs)

    def contribute_to_class(self, cls, name, **kwargs):
        super().contribute_to_class(cls, name, **kwargs)
        models.signals.post_init.connect(
            self._refresh_metadata_fields, sender=cls
        )

    def _refresh_metadata_fields(self, instance, force=False, *args, **kwargs):
        """
        Updates model fields based on audio metadata when available.
        """
        has_target_fields = any([
            self.artist_field,
            self.title_field,
            self.duration_field,
            self.genre_field,
        ])

        if not has_target_fields:
            return

        # Accessing the field triggers descriptor logic
        audio_file = getattr(instance, self.attname)

        # Skip update unless forced or there's a file
        if not audio_file and not force:
            return

        # Check if metadata fields already have values (unless forced)
        existing_data = (
            (not self.duration_field or getattr(instance, self.duration_field)) or
            (not self.size_field or getattr(instance, self.size_field))
        )
        if existing_data and not force:
            return

        # Extract metadata or set to None if no file
        if audio_file:
            artist_val = audio_file.artist
            title_val = audio_file.title
            genre_val = audio_file.genre
            duration_val = audio_file.length
            size_val = audio_file.size
        else:
            artist_val = title_val = genre_val = duration_val = size_val = None

        # Update only empty fields
        if self.artist_field and not getattr(instance, self.artist_field):
            setattr(instance, self.artist_field, artist_val)
        if self.title_field and not getattr(instance, self.title_field):
            setattr(instance, self.title_field, title_val)
        if self.genre_field and not getattr(instance, self.genre_field):
            setattr(instance, self.genre_field, genre_val)
        if self.duration_field and not getattr(instance, self.duration_field):
            setattr(instance, self.duration_field, duration_val)
        if self.size_field and not getattr(instance, self.size_field):
            setattr(instance, self.size_field, size_val)

    def formfield(self, **kwargs):
        defaults = {"form_class": forms.FileField}
        defaults.update(kwargs)
        return super().formfield(**defaults)

# Image integrity checker using PIL

from PIL import Image
import os
import argparse

def check_image_integrity(filepath, show_progress=False):
    if show_progress:
        print(f"Validating {filepath}", end="... ")

    try:
        # First pass: open and verify image structure
        with Image.open(filepath) as img:
            img.verify()

        # Second pass: perform a basic transformation to ensure full load capability
        with Image.open(filepath) as img:
            img.transpose(Image.FLIP_LEFT_RIGHT)

        if show_progress:
            print("passed")
        return True

    except Exception:
        if show_progress:
            print("failed")
        return False

def scan_directory_for_broken_images(directory_path, show_progress=False):
    base_dir = os.path.join(os.getcwd(), directory_path)
    problematic_files = []

    print("Scanning directory recursively...", flush=True)
    for root, _, files in os.walk(base_dir):
        for file_name in files:
            full_file_path = os.path.join(root, file_name)
            if not check_image_integrity(full_file_path, show_progress):
                problematic_files.append(file_name)
    print("Scan completed.")

    if problematic_files:
        print(f"The following images failed validation:\n{problematic_files}")

if __name__ == "__main__":
    argument_parser = argparse.ArgumentParser(description="Image integrity verification tool")
    argument_parser.add_argument("-i", "--image", help="Path to a single image file to check")
    argument_parser.add_argument("-d", "--directory", help="Path to directory to scan recursively")
    argument_parser.add_argument("-v", "--verbose", action="store_true", help="Enable detailed output")

    parsed_args = argument_parser.parse_args()

    if parsed_args.image:
        check_image_integrity(parsed_args.image, parsed_args.verbose)
    if parsed_args.directory:
        scan_directory_for_broken_images(parsed_args.directory, parsed_args.verbose)

