    DataFieldDocumentation,
    EventDeclarations,
    EventDocumentation,
]


def generate_html(xml_root: ET.Element) -> str:
    """
    Generate HTML content for a reference article based on XML input.

    This function extracts the article type from the XML tree and constructs
    an HTML article element by delegating to various sub-components.
    """
    # Extract article kind attribute (e.g., "class", "struct", etc.)
    root_elem = xml_root.find("./compounddef")
    article_kind = root_elem.attrib.get("kind", "unknown")

    # Build HTML using component-specific renderers
    html_parts = [
        f"<article class='{article_kind} reference'>",
        ArticleHeader.html(xml_root),
        "<div class='contents article'>",
        BriefDescription.html(xml_root),
        FunctionDeclarations.html(xml_root),
        DataStructureDeclarations.html(xml_root),
        DataFieldDeclarations.html(xml_root),
        EnumDeclarations.html(xml_root),
        EventDeclarations.html(xml_root),
        DetailedDescription.html(xml_root),
        EnumDocumentation.html(xml_root),
        FunctionDocumentation.html(xml_root),
        EventDocumentation.html(xml_root),
        DataFieldDocumentation.html(xml_root),
        "</div>",
        "</article>",
    ]

    return "\n".join(html_parts)


