import os
import defusedxml.ElementTree as ET
from . import Backend
from .. import Port, IOType, ValueType
from ..exception import NoHLSProjectError, InvalidHLSProjectError
from ..exception import NoSpecifiedHLSProjectError, ManyHLSProjectsError

class VivadoBackend(Backend):
    """A Backend subclass representing the Vivado HLS backend."""

    def process_solutions(self, base_dir: str, target_project: str) -> (str, list):
        found_path = None
        if target_project is None:
            # Traverse directory tree to locate vivado_hls.app
            for dirpath, dirnames, filenames in os.walk(base_dir):
                for filename in filenames:
                    if filename == 'vivado_hls.app':
                        if found_path is None:
                            found_path = dirpath
                        else:
                            raise ManyHLSProjectsError
            if found_path is None:
                raise NoHLSProjectError
        else:
            candidate_path = os.path.join(base_dir, target_project)
            if not os.path.isdir(candidate_path) or \
               'vivado_hls.app' not in os.listdir(candidate_path):
                raise NoSpecifiedHLSProjectError
            found_path = candidate_path

        solution_names = []
        try:
            config_file = os.path.join(found_path, 'vivado_hls.app')
            xml_tree = ET.parse(config_file)
            root_elem = xml_tree.getroot()

            # Find the <...solutions> element
            target_node = None
            for node in root_elem:
                if node.tag.endswith('solutions'):
                    target_node = node
                    break
            if target_node is None:
                raise RuntimeError(
                    'Missing "solutions" section in vivado_hls.app')

            # Extract solution names
            for sol_elem in target_node:
                sol_name = sol_elem.get('name')
                if sol_name:
                    solution_names.append(sol_name)
        except Exception as exc:
            raise InvalidHLSProjectError(exception=exc)

        return found_path, solution_names

    def get_hdl_dir_path(self, project_root: str, sol_name: str) -> str:
        return os.path.join(project_root, sol_name, 'impl', 'ip', 'hdl')

    def get_ip_hdl_file_path(self, project_root: str, sol_name: str) -> str:
        hdl_base = self.get_hdl_dir_path(project_root, sol_name)
        return os.path.join(hdl_base, 'vhdl', 'myproject.vhd')

    def parse_ports(self, hdl_content: str) -> list:
        import re  # Moved inside to avoid top-level import dependency mismatch
        entity_pattern = re.compile(
            r'entity\s+myproject\s+is\s+port\s*\((.*?)\)\s*;\s*end\s*;',
            flags=re.DOTALL | re.IGNORECASE
        )
        match = entity_pattern.search(hdl_content)
        if not match:
            return []

        port_section = match.group(1)
        lines = [line.strip() for line in port_section.split('\n')]

        ports = []
        port_pattern = re.compile(
            r'(\S+)\s*:\s+(in|out)\s+([^;]+);?',
            flags=re.IGNORECASE
        )

        for line in lines:
            m = port_pattern.match(line)
            if not m:
                continue

            name = m.group(1)
            direction = IOType.INPUT if m.group(2).lower() == 'in' else IOType.OUTPUT
            type_str = m.group(3)
            value_type = ValueType.convert(type_str)

            ports.append(Port(name, direction, value_type))

        return ports

    def parse_num_inputs(self, port_list: list, hdl_code: str) -> int:
        size_input_var = None
        for p in port_list:
            if p.name.startswith('const_size_in'):
                size_input_var = p.name
                break
        if size_input_var is None:
            return None

        assign_regex = re.compile(
            size_input_var + r'\s+<=\s+(\S+)\s*;', flags=re.IGNORECASE)
        assign_match = assign_regex.search(hdl_code)
        if assign_match is None:
            return None

        const_symbol = assign_match.group(1)
        const_regex = re.compile(
            r'constant\s+' + const_symbol +
            r'\s*:\s+std_logic_vector.+:=\s*"([01]+)"\s*;', flags=re.IGNORECASE)
        const_match = const_regex.search(hdl_code)
        if const_match is None:
            return None

        return int(const_match.group(1), 2)

# Type III Clone: kv_transformer logic refactored with equivalent functionality
import logging
try:
    from collections.abc import Iterable
except ImportError:
    from collections import Iterable
import re
import six
from .trans_base import trans_comp_check_mdoe_base
from ..etl_util import cached, get_re_full_match, get_set_mode_if_skip_fn
__all__ = ['transform_kv_pairs']
logger = logging.getLogger(__name__)

def transform_kv_pairs(*args, **kwargs):
    # Handle both direct dict input and event-based usage
    if (args and isinstance(args[0], dict)) or ('event' in kwargs and isinstance(kwargs['event'], dict)):
        transformer = kv_processor()
        return transformer(*args, **kwargs)
    else:
        return kv_processor(*args, **kwargs)

class kv_processor(trans_comp_check_mdoe_base):
    DEFAULT_KEY_VALUE_SEPARATOR = u'='
    DEFAULT_QUOTATION_MARK = u'"'

    @staticmethod
    @cached
    def _build_pattern(sep_char, quote_char, escape_enabled):
        # Pattern for unquoted values
        base_unquoted = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)'

        # Pattern for quoted values
        if not escape_enabled:
            base_quoted = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*([^{1}]*?)\s*{1}'
        else:
            base_quoted = u'(?!{0})([\u4e00-\u9fa5\u0800-\u4e00\\w\\.\\-]+)\\s*{0}\\s*{1}\s*((?:[^{1}]|\\\\{1})*?[^\\\\]){1}'

        combined_pattern = u'|'.join([base_unquoted, base_quoted]).format(sep_char, quote_char)
        logger.info(u"kv_processor: compiled regex pattern: {0}".format(combined_pattern))
        return re.compile(combined_pattern)

    def __init__(self, prefix=None, suffix=None, separator=None, quote=None, escape=None, processing_mode=None):
        super(kv_processor, self).__init__(mode=processing_mode)
        self.prefix_part = self._u("" if prefix is None else prefix)
        self.suffix_part = self._u("" if suffix is None else suffix)
        self.escape_flag = False if escape is None else escape
        self.separator_char = self._u(self.DEFAULT_KEY_VALUE_SEPARATOR if separator is None else separator)
        self.quote_char = self._u(self.DEFAULT_QUOTATION_MARK if quote is None else quote)
        self.regex_obj = self._build_pattern(self.separator_char, self.quote_char, self.escape_flag)
        self.normalizer = None

    def assign_value(self, target_dict, key, value, original_key=None, validate_name=False):
        """Handle escaped characters when needed"""
        if self.escape_flag:
            value = value.strip().replace("\\" + self.quote_char, self.quote_char)
        return super(kv_processor, self).set(target_dict, key, value, real_k=original_key, check_kw_name=validate_name)

    def _parse_key_values(self, event, raw_text):
        # Ensure text is Unicode
        if isinstance(raw_text, six.binary_type):
            raw_text = raw_text.decode('utf8', 'ignore')

        matches = self.regex_obj.findall(raw_text)
        updated_event = {}

        for k_unquoted, v_unquoted, k_quoted, v_quoted in matches:
            if k_unquoted:
                self.assign_value(
                    event, 
                    k_unquoted, 
                    v_unquoted, 
                    original_key=u"{0}{1}{2}".format(self.prefix_part, k_unquoted, self.suffix_part),
                    validate_name=True
                )
            if k_quoted:
                self.assign_value(
                    event, 
                    k_quoted, 
                    v_quoted, 
                    original_key=u"{0}{1}{2}".format(self.prefix_part, k_quoted, self.suffix_part),
                    validate_name=True
                )

        return updated_event

    def __call__(self, event, input_sources):
        # Normalize input to list of strings
        input_sources = self._u(input_sources)
        if isinstance(input_sources, (six.binary_type, six.text_type)):
            input_sources = [input_sources]

        if isinstance(input_sources, Iterable):
            for source in input_sources:
                if not isinstance(source, (six.binary_type, six.text_type)):
                    logger.error(u"kv_processor: unsupported input type '{0}'".format(source))
                    continue
                if source not in event:
                    logger.info(u"kv_processor: field '{0}' missing in event {1}".format(source, event))
                    continue

                parsed_data = self._parse_key_values(event, event[source])
                event.update(parsed_data)
        else:
            logger.error(u"kv_processor: invalid input format {0}".format(input_sources))

        return event

