import sys
import csv
import bpy
import re
import unicodedata
from bl_i18n_utils import settings as i18n_settings
from .. import compatibility as compat
from .translation_helpers import *
# get_system_locale() -> Returns the actual locale
# get_available_locale() -> Returns the nearest supported locale for translation
TRANSLATIONS = {}  # {locale: {(context, original): translation, ...}, ...}
# locale can be like 'fr', 'pt_BR', 'sr@latin', or 'uz_UZ@cyrilic'
# key is tuple (msg_context, msg_original)
# verbosity level: -1 means no output
log_level = 0
should_dump_messages = True
validate_contexts = False
detect_duplicates = False
supported_locales = set()
translations_dir = os.path.dirname(__file__)

# Custom CSV dialect for CM3D2 Converter
csv.register_dialect('cm3d2_converter',
    delimiter        = ','            ,
    doublequote      = False          ,
    escapechar       = '\\'           ,
    lineterminator   = '\n'           ,
    quotechar        = '"'            ,
    quoting          = csv.QUOTE_ALL  ,
    skipinitialspace = False          ,
    strict           = True         
)

# Mapping of internal Blender i18n contexts to their string identifiers
i18n_context_map = {
    identifer: getattr(bpy.app.translations.contexts, identifer) 
    for identifer in bpy.app.translations.contexts_C_to_py.values()
}

def log_verbose(level: int, *args, indent: str="\t", sep: str=" ", end: str="\n", out=sys.stdout, flush: bool=False, **fmt_kwargs) -> None:
    if level > log_level:
        return
    msg = indent * level + sep.join(str(arg) for arg in args)
    if fmt_kwargs:
        msg = msg.format(**fmt_kwargs)
    print(msg, end=end, file=out, flush=flush)

def validate_context_tag(context: str) -> bool:
    if not validate_contexts:
        return True
    return context in i18n_context_map.values()

def has_duplicate(key: tuple, lang: str) -> bool:
    if not detect_duplicates:
        return False
    return key in TRANSLATIONS.get(lang, {}).keys()

def find_best_locale_match(locale: str, candidates=supported_locales) -> str:
    # Try exact match first
    if locale in candidates:
        return locale

    # Fallback to best partial match
    best = 'en_US'
    score = 0
    for tag in TRANSLATIONS.keys():
        lang, country, variant, lang_country, lang_variant = bpy.app.translations.locale_explode(tag)

        if   score < 4 and lang_variant in candidates:
            score, best = 4, tag
        elif score < 3 and lang_country in candidates:
            score, best = 3, tag
        elif score < 2 and lang in candidates:
            score, best = 2, tag
        elif score < 1 and country in candidates:
            score, best = 1, tag

    return best

def build_translations(locale: str):
    # Special-case overrides could go here
    pass
    # Otherwise use best available match
    fallback = find_best_locale_match(locale)
    TRANSLATIONS[locale] = TRANSLATIONS.get(fallback, {})

def get_system_locale() -> str:
    loc = ''
    if bpy.app.translations.locale:
        loc = bpy.app.translations.locale
    else:
        try:
            import locale as py_locale
            system_info = compat.get_system(bpy.context)
            if system_info.language == 'DEFAULT':
                loc = py_locale.getdefaultlocale()[0]
        except Exception as err:
            print("Failed to determine system locale:", err)
    return loc

def get_supported_locale() -> str:
    return find_best_locale_match(get_system_locale())

# Regex patterns for source extraction
source_file_pattern = re.compile(r":?\d+$")
python_path_pattern = re.compile(
    r"(?:bpy\.types)?"
    r"(?:\.|\:|\[[\'\"])" 
    r"([^\.]+?)"          
    r"(?:[\'\"]\])?"      
    r"(?=\.|\:|$)"        
)
comment_marker_pattern = re.compile(r"#\s")

class_hash_table = {}

def extract_source_file(src: str) -> str:
    if not src.startswith('bpy.'):
        base = os.path.basename(src)
        base = source_file_pattern.sub("", base)
        return base
    else:
        cls_name = python_path_pattern.match(src)[1]
        if not class_hash_table:
            for cls in compat.BlRegister.classes:
                class_hash_table[cls.bl_rna.identifier] = cls

        cls = class_hash_table.get(cls_name)
        if not cls:
            return cls_name
        mod_name, ext = os.path.splitext(cls.__module__)
        if not ext:
            return "__init__.py"
        elif ext == "translations":
            return "translations/__init__.py"
        else:
            return ext[1:] + ".py"

def format_csv_line(message, include_sources=False):
    row = [message.msgctxt, message.msgid, message.msgstr]

    sources_str = f'FROM <{" & ".join(extract_source_file(s) for s in message.sources)}>' if include_sources else ""
    comment = comment_marker_pattern.sub("", message.comment_lines[-1]) if message.is_commented else ""

    if sources_str or comment:
        if not sources_str or sources_str in comment:
            row.append(f"# {comment}")
        elif not comment:
            row.append(f"# {sources_str}")
        else:
            row.append(f"# {sources_str} {comment}")

    class StringIO:
        def __init__(self, content=""):
            self.content = content
        def write(self, text):
            if isinstance(text, bytes):
                text = text.decode('utf-8')
            self.content += text
        trans_table = str.maketrans({'\n':'', '\r':''})
        def value(self):
            return self.content.translate(self.trans_table)

    buffer = StringIO("")
    writer = csv.writer(buffer, dialect='cm3d2_converter')
    writer.writerow(row)
    return buffer.value()

def export_messages_to_csv(messages, reports, lang=get_supported_locale(), only_missing=True):
    lang_data = TRANSLATIONS.get(lang)
    header = "Context,Original,Translation,Comments\n# encoding UTF-8"
    current_src = None
    shared_items = []

    sorted_msgs = sorted(
        ((key, msg, extract_source_file(msg.sources[0])) for key, msg in messages.items()),
        key=lambda x: x[2]
    )

    for key, msg, src in sorted_msgs:
        msg.normalize()
        check_key = (msg.msgctxt, msg.msgid)
        if check_key != key:
            print(f"Mismatched key detected: {key} vs {check_key}")

        if lang_data and lang_data.get(check_key):
            if only_missing:
                continue
            msg.msgstr = msg.msgstr or lang_data[check_key]
            comment = comments_dict.get(lang, {}).get(check_key)
            if comment:
                msg.comment_lines.append(comment)
                msg.is_commented = True

        sources = msg.sources
        if 'KM_HIERARCHY' in sources[0]:
            continue

        if len(sources) > 1:
            new_src = extract_source_file(sources[0])
            if any(extract_source_file(sub) != new_src for sub in sources):
                shared_items.append(msg)
                continue

        if src != current_src:
            current_src = src
            header += f"\n# {src}"
        header += f"\n{format_csv_line(msg)}"

    if shared_items:
        header += "\n# shared"
        for msg in shared_items:
            header += f"\n{format_csv_line(msg, include_sources=True)}"

    return header

def export_reports_to_csv(reports):
    result = "### Generated Reports ###"
    for title, data in reports.items():
        result += f"\n## {title} ##"
        if hasattr(data, '__iter__') and not isinstance(data, (str, bytes)):
            for item in data:
                result += f"\n{str(item)}"
        else:
            result += f"\n{str(data)}"
    return result

@compat.BlRegister()
class CNV_OT_export_python_strings(bpy.types.Operator):
