    only_foreign     = bpy.props.BoolProperty(name="Only Foreign", default=False)

    language_list = [
        (code, name, "", 'NONE', idx) 
        for idx, name, code in i18n_settings.LANGUAGES
    ]
    target_language = bpy.props.EnumProperty(items=language_list, name="Language", default=get_supported_locale())

    @classmethod
    def poll(cls, context):
        return True

    @staticmethod
    def contains_japanese(text: str) -> bool:
        for char in text:
            info = unicodedata.name(char, "")
            if 'CJK UNIFIED' in info or 'HIRAGANA' in info or 'KATAKANA' in info:
                return True
        return False

    def invoke(self, context, event):
        return context.window_manager.invoke_props_dialog(self)

    def draw(self, context):
        layout = self.layout
        layout.prop(self, 'perform_checks')
        layout.prop(self, 'generate_reports')
        layout.prop(self, 'only_missing')
        layout.prop(self, 'target_language')
        row = layout.row()
        row.prop(self, 'only_foreign')
        row.enabled = self.target_language in ('en_US', 'ja_JP')

    def execute(self, context):
        from . import msg_extractor
        msgs = {}
        rep = msg_extractor.generate_reports(
            msg_extractor.check_contexts(i18n_settings) if self.perform_checks else None
        )
        msg_extractor.extract_rna_messages(
            messages=msgs,
            reports=rep,
            config=i18n_settings,
            verbose=False,
            classes=[ meta.bl_rna.__class__ for meta in compat.BlRegister.classes ]
        )
        msg_extractor.extract_py_messages(
            messages=msgs,
            reports=rep,
            addons=[__import__("CM3D2 Converter")],
            config=i18n_settings,
            only_addons=True
        )

        # Filter unwanted entries
        for key in list(msgs.keys()):
            msg = msgs.pop(key)
            if '_OT_' in msg.msgid:
                continue
            if self.only_foreign:
                is_ja = self.contains_japanese(msg.msgid)
                if is_ja and 'ja' in self.target_language:
                    continue
                if not is_ja and 'en' in self.target_language:
                    continue
            msgs[key] = msg

        csv_content = export_messages_to_csv(msgs, rep, lang=self.target_language, only_missing=self.only_missing)
        txt_name = "cm3d2_messages_csv"
        if txt_name in context.blend_data.texts:
            txt = context.blend_data.texts[txt_name]
            txt.clear()
        else:
            txt = context.blend_data.texts.new(txt_name)
        txt.write(csv_content)

        if self.generate_reports:
            report_txt = "cm3d2_message_reports"
            if report_txt in context.blend_data.texts:
                rtxt = context.blend_data.texts[report_txt]
                rtxt.clear()
            else:
                rtxt = context.blend_data.texts.new(report_txt)
            rtxt.write(export_reports_to_csv(rep))

        self.report(type={'INFO'}, message=f_tip_("Strings exported to {txt_name}. Check Text Editor.", txt_name=txt_name))
        return {'FINISHED'}

# Global state management
initial_settings = None

def register(module_name=__name__):
    global TRANSLATIONS
    global comments_dict
    global initial_settings

    system = compat.get_system(bpy.context)
    if hasattr(system, 'use_international_fonts'):
        initial_settings = system.use_international_fonts
        system.use_international_fonts = True
    elif bpy.app.version >= (2, 93):
        if system.language in {'en_US', 'DEFAULT'} \
            and system.use_translate_tooltips     == False \
            and system.use_translate_interface    == False \
            and system.use_translate_new_dataname == False:
            system.use_translate_tooltips     = True
            system.use_translate_interface    = True
            system.use_translate_new_dataname = True
    elif bpy.app.version >= (2, 83):
        if system.language == 'en_US':
            initial_settings = system.language
            system.language = 'DEFAULT'
            def restore_flags():
                system.use_translate_tooltips     = True
                system.use_translate_interface    = True
                system.use_translate_new_dataname = True
            bpy.app.timers.register(restore_flags, first_interval=0)

    # Load translations from CSV files
    for lang in os.listdir(translations_dir):
        lang_dir = os.path.join(translations_dir, lang)
        if not os.path.isdir(lang_dir):
            continue
        if lang.startswith("_") or lang.startswith("."):
            continue

        log_verbose(0, "Loading translations for", lang)
        lang_data = TRANSLATIONS.get(lang)
        if not lang_data:
            lang_data = {}
            TRANSLATIONS[lang] = lang_data
            comments_dict[lang] = {}

        before = len(lang_data)
        for fname in os.listdir(lang_dir):
            _, ext = os.path.splitext(fname)
            if ext.lower() != ".csv":
                continue

            log_verbose(1, f"Reading {fname}")
            count = 0
            dupes = 0
            path = os.path.join(lang_dir, fname)
            with open(path, 'rt', encoding='utf-8', newline='') as f:
                reader = csv.reader(f, dialect='cm3d2_converter')
                try:
                    for idx, row in enumerate(reader):
                        if idx == 0:
                            continue
                        if len(row) < 3:
                            continue
                        if row[0].lstrip()[0] == "#":
                            continue
                        if row[0] not in i18n_context_map.values():
                            log_verbose(2, f"Unknown context '{row[0]}' at line {idx}")
                        key = (row[0], row[1])
                        if has_duplicate(key, lang):
                            log_verbose(2, f"Duplicate entry at line {idx}")
                            count -= 1
                            dupes += 1
                        val = row[2]
                        lang_data[key] = val
                        count += 1
                        if len(row) > 3:
                            comments_dict[lang][key] = row[3]
                        log_verbose(3, f"{idx:{4}} {key}: {val}")
                except csv.Error as e:
                    print(f"Error parsing {fname} in {lang_dir}:")
                    print(e)
            log_verbose(1, f"-> Added {count} entries from {fname}")
            if detect_duplicates:
                log_verbose(1, f"-> Replaced {dupes} entries in {fname}")
        log_verbose(0, f"-> Added {len(lang_data) - before} entries for {lang}")

    supported_locales.update(TRANSLATIONS.keys())

    # Fill missing locales
    log_verbose(0, "Generating missing translations...")
    built_count = 0
    for loc in bpy.app.translations.locales:
        if loc not in TRANSLATIONS:
            log_verbose(1, f"Building translations for '{loc}'")
            build_translations(loc)
            built_count += 1

    sys_locale = get_system_locale()
    if sys_locale not in TRANSLATIONS:
        log_verbose(1, f"Building translations for '{sys_locale}'")
        build_translations(sys_locale)
        built_count += 1

    log_verbose(0, f"-> Created {built_count} missing locale sets")
    bpy.app.translations.register(module_name, TRANSLATIONS)

def unregister(module_name=__name__):
    global TRANSLATIONS
    global supported_locales
    global initial_settings

    TRANSLATIONS = {}
    supported_locales = set()
    bpy.app.translations.unregister(module_name)

    if initial_settings is not None:
        system = compat.get_system(bpy.context)
        if hasattr(system, 'use_international_fonts'):
            system.use_international_fonts = initial_settings
        if (2, 83, 0) <= bpy.app.version < (2, 93):
            system.language = initial_settings
    initial_settings = None

if __name__ == "__main__":
    register()

from .. import types
from .schedule import Stage, create_schedule

def build_scheme(input_data, operation):
    """Construct a quantization scheme."""
    if not isinstance(input_data, list):
        input_data = [input_data]
    return QuantizationScheme(input_data, operation)

def generate_schedule_from_quantization(scheme_obj, label=""):
    """Generate a schedule based on a quantization scheme."""
    return create_schedule(scheme_obj.data_inputs, func=None, name=label)

class QuantizationScheme(object):
    """Represents a quantization configuration."""

    def __init__(self, data_inputs, operation):
        self.data_inputs = data_inputs
        self.operation = operation
        # Run the operation and link stages to the function
        result = operation(*data_inputs)
        for operator, stage in Stage._mapping:
            operation.__setattr__(operator.name, operator)

    def reduce_precision(self, data_tensors, target_type):
        """Convert a (list of) tensor to a lower-precision integer format."""
        if not isinstance(target_type, (types.Int, types.UInt)):
            raise RuntimeError("Precision reduction to non-integer type is prohibited")
        if not isinstance(data_tensors, list):
            data_tensors = [data_tensors]
        for tensor in data_tensors:
            tensor.dtype = target_type

    def apply_quantization(self, data_tensors, fixed_point_type):
        """Apply fixed-point quantization to a (list of) tensor."""
        if not isinstance(fixed_point_type, (types.Fixed, types.UFixed)):
            raise RuntimeError("Quantization to integer-only type is disallowed")
        if not isinstance(data_tensors, list):
            data_tensors = [data_tensors]
        for tensor in data_tensors:
            tensor.dtype = fixed_point_type

