class ID3D12InfoQueue(IUnknown):
    def __init__(self):
        self.message_count_limit = 0
        self.stored_messages = []
        self.storage_filter = D3D12_INFO_QUEUE_FILTER()
        self.retrieval_filter = D3D12_INFO_QUEUE_FILTER()
        self.break_on_category = set()
        self.break_on_severity = set()
        self.break_on_id = set()
        self.muted = False

    def SetMessageCountLimit(self, limit):
        self.message_count_limit = limit

    def ClearStoredMessages(self):
        self.stored_messages.clear()

    def GetMessageA(self, index, message_ptr, byte_length_ptr):
        if 0 <= index < len(self.stored_messages):
            msg = self.stored_messages[index]
            message_ptr.update(msg)
            byte_length_ptr[0] = len(str(msg))
            return 0  # S_OK
        return 1  # E_FAIL

    def GetNumMessagesAllowedByStorageFilter(self):
        return len(self.stored_messages)

    def GetNumMessagesDeniedByStorageFilter(self):
        return 0

    def GetNumStoredMessages(self):
        return len(self.stored_messages)

    def GetNumStoredMessagesAllowedByRetrievalFilter(self):
        return len(self.stored_messages)

    def GetNumMessagesDiscardedByMessageCountLimit(self):
        return 0

    def GetMessageCountLimit(self):
        return self.message_count_limit

    def AddStorageFilterEntries(self, filter_desc):
        self.storage_filter = filter_desc
        return 0

    def GetStorageFilter(self, filter_ptr, byte_length_ptr):
        filter_ptr.update(self.storage_filter)
        byte_length_ptr[0] = len(str(self.storage_filter))
        return 0

    def ClearStorageFilter(self):
        self.storage_filter = D3D12_INFO_QUEUE_FILTER()

    def PushEmptyStorageFilter(self):
        self.storage_filter = D3D12_INFO_QUEUE_FILTER()
        return 0

    def PushCopyOfStorageFilter(self):
        return 0

    def PushStorageFilter(self, filter_desc):
        self.storage_filter = filter_desc
        return 0

    def PopStorageFilter(self):
        self.storage_filter = D3D12_INFO_QUEUE_FILTER()

    def GetStorageFilterStackSize(self):
        return 0

    def AddRetrievalFilterEntries(self, filter_desc):
        self.retrieval_filter = filter_desc
        return 0

    def GetRetrievalFilter(self, filter_ptr, byte_length_ptr):
        filter_ptr.update(self.retrieval_filter)
        byte_length_ptr[0] = len(str(self.retrieval_filter))
        return 0

    def ClearRetrievalFilter(self):
        self.retrieval_filter = D3D12_INFO_QUEUE_FILTER()

    def PushEmptyRetrievalFilter(self):
        self.retrieval_filter = D3D12_INFO_QUEUE_FILTER()
        return 0

    def PushCopyOfRetrievalFilter(self):
        return 0

    def PushRetrievalFilter(self, filter_desc):
        self.retrieval_filter = filter_desc
        return 0

    def PopRetrievalFilter(self):
        self.retrieval_filter = D3D12_INFO_QUEUE_FILTER()

    def GetRetrievalFilterStackSize(self):
        return 0

    def AddMessage(self, category, severity, msg_id, description):
        message = {
            'Category': category,
            'Severity': severity,
            'ID': msg_id,
            'pDescription': description,
            'DescriptionByteLength': len(description) if description else 0
        }
        if len(self.stored_messages) < self.message_count_limit:
            self.stored_messages.append(message)
        return 0

    def AddApplicationMessage(self, severity, description):
        return self.AddMessage(
            D3D12_MESSAGE_CATEGORY['D3D12_MESSAGE_CATEGORY_APPLICATION_DEFINED'],
            severity,
            D3D12_MESSAGE_ID['D3D12_MESSAGE_ID_STRING_FROM_APPLICATION'],
            description
        )

    def SetBreakOnCategory(self, category, enable):
        if enable:
            self.break_on_category.add(category)
        else:
            self.break_on_category.discard(category)
        return 0

    def SetBreakOnSeverity(self, severity, enable):
        if enable:
            self.break_on_severity.add(severity)
        else:
            self.break_on_severity.discard(severity)
        return 0

    def SetBreakOnID(self, msg_id, enable):
        if enable:
            self.break_on_id.add(msg_id)
        else:
            self.break_on_id.discard(msg_id)
        return 0

    def GetBreakOnCategory(self, category):
        return category in self.break_on_category

    def GetBreakOnSeverity(self, severity):
        return severity in self.break_on_severity

    def GetBreakOnID(self, msg_id):
        return msg_id in self.break_on_id

    def SetMuteDebugOutput(self, mute):
        self.muted = bool(mute)

    def GetMuteDebugOutput(self):
        return self.muted

