from pathlib import Path
from typing import Dict
import toml

class JournalConfig:
    """Represents configuration for a journal"""
    def __init__(self, journal_name: str, journal_path: Path):
        self.name = journal_name
        self.path = journal_path

    def __str__(self) -> str:
        return f"{self.name} located at {self.path}"

    def export(self) -> dict:
        """Convert configuration to dictionary format for TOML serialization"""
        return {"path": str(self.path)}

class WaldenAppConfig:
    """Holds the main application configuration for Walden"""
    def __init__(self, config_file: Path, default_journal_dir: Path, journals_data: Dict[str, JournalConfig]):
        self.config_path = config_file
        self.default_journal_location = default_journal_dir
        self.journals = journals_data

    def persist(self):
        """Save current configuration state to disk in TOML format"""
        data_store = {}
        for name, info in self.journals.items():
            data_store[name] = info.export()

        data_store["config_file"] = str(self.config_path)
        data_store["default_journal_directory"] = str(self.default_journal_location)

        output_structure = {"walden": data_store}
        self.config_path.write_text(toml.dumps(output_structure))

