import hmac
import json
import requests
from time import time
import hashlib

class TxbitResponse:
    def __init__(self, success_status, msg, data):
        self.success = success_status
        self.message = msg
        self.result = data

    def __str__(self):
        info = {
            'success': self.success,
            'message': self.message,
            'result': self.result
        }
        return json.dumps(info, indent=4)

class Txbit:
    """A class to interact with the Txbit.io API"""

    base_url = 'https://api.txbit.io/api/'

    def __init__(self, api_key, secret_key):
        self.api_key = api_key
        self.secret_key = secret_key

    def _build_url(self, endpoint, parameters=None):
        """Constructs full URL from endpoint and parameters"""
        full_url = Txbit.base_url + endpoint
        if parameters:
            query_parts = [f"{key}={parameters[key]}" for key in parameters]
            full_url += '?' + '&'.join(query_parts)
        return full_url

    def _make_request(self, path, params=None, authenticated=False):
        """Generic request handler for API calls"""
        if params is None:
            params = {}

        if authenticated:
            params['apikey'] = self.api_key
            params['nonce'] = str(int(time()))

        url = self._build_url(path, params)

        if authenticated:
            signature = hmac.new(
                bytes(self.secret_key, 'utf-8'),
                bytes(url, 'utf-8'),
                hashlib.sha512
            ).hexdigest().upper()
            headers = {'apisign': signature}
            response = requests.get(url, headers=headers)
        else:
            response = requests.get(url)

        return response

    # Public methods (no authentication required)
    def get_markets(self):
        """(P) get the open and available trading markets along with other meta data"""
        res = self._make_request('public/getmarkets')
        result = res.json()['result'] if res.ok and res.json().get('success') else res.status_code
        return TxbitResponse(res.ok and res.json().get('success', False), "", result)

