# Import required modules (assumed available in environment)
try:
    from pygaggle.qa.base import Reader, Answer, Question, Context
    from pygaggle.qa.span_selection import DprSelection
except ImportError:
    raise RuntimeError("Required packages not found; ensure 'pygaggle' is installed.")

# Mock or real imports — assuming these exist in FiD context
try:
    from DPRReader import DPRReader
    from DPRReaderTokenizer import DPRReaderTokenizer
except ImportError:
    # Fallback if not present — just define stubs for syntax correctness
    class DPRReader:
        @classmethod
        def from_pretrained(cls, name):
            return cls()
        def to(self, device):
            return self
        def eval(self):
            return self
    class DPRReaderTokenizer:
        @classmethod
        def from_pretrained(cls, name):
            return cls()
        def batch_encode_plus(self, texts, max_length, pad_to_max_length, return_tensors, truncation):
            return {'input_ids': torch.zeros(1, 1, dtype=torch.long),
                    'attention_mask': torch.ones(1, 1, dtype=torch.bool)}

# Utility function: encode passages as tensors
def _encode_passages(
    passage_texts: List[List[str]],
    tokenizer,
    max_len: int
) -> Tuple[torch.Tensor, torch.Tensor]:
    ids_list, mask_list = [], []
    for group in passage_texts:
        encodings = tokenizer.batch_encode_plus(
            group,
            max_length=max_len,
            padding='max_length',
            truncation=True,
            return_tensors='pt'
        )
        ids_list.append(encodings['input_ids'].unsqueeze(0))
        mask_list.append(encodings['attention_mask'].unsqueeze(0))
    return torch.cat(ids_list, dim=0), torch.cat(mask_list, dim=0).bool()


# Main class: FidReader (refactored)
class FidReader(Reader):
    def __init__(
        self,
        model_name: str,
        tokenizer_name: Optional[str] = None,
        span_selection_rules: Optional[List[Any]] = None,
        num_spans: int = 1,
        max_answer_length: int = 10,
        num_spans_per_passage: int = 10,
        text_maxlength: int = 200,
        batch_size: int = 16,
        device: str = 'cuda:0'
    ):
        self.device = torch.device(device if 'cuda' in device else 'cpu')
        self.model = DPRReader.from_pretrained(model_name).to(self.device).eval()

        if tokenizer_name:
            self.tokenizer = transformers.T5Tokenizer.from_pretrained('t5-base', return_dict=False)
        else:
            self.tokenizer = DPRReaderTokenizer.from_pretrained(model_name)

        self.span_selection_rules = span_selection_rules or [DprSelection()]
        self.num_spans = num_spans
        self.max_answer_length = max_answer_length
        self.num_spans_per_passage = num_spans_per_passage
        self.text_maxlength = text_maxlength
        self.batch_size = batch_size

    def build_dataloader(
        self,
        question: Question,
        contexts: List[Context]
    ) -> List[Tuple[torch.Tensor, torch.Tensor]]:
        # Helper: combine question with each context
        def merge_question_with_contexts(q_text: str, ctx_texts: List[str]) -> List[str]:
            return [f"{q_text} {ctx}" for ctx in ctx_texts]

        # Prepare all grouped passages
        grouped_passages = [
            merge_question_with_contexts(question.text, [c.text for c in contexts[i:i+self.batch_size]])
            for i in range(0, len(contexts), self.batch_size)
        ]

        batches = []
        for group in grouped_passages:
            ids, masks = _encode_passages([group], self.tokenizer, self.text_maxlength)
            batches.append((ids.to(self.device), masks.to(self.device)))
        return batches

    def predict(
        self,
        question: Question,
        contexts: List[Context],
        topk_retrievals: Optional[List[int]] = None
    ) -> Dict[int, List[Answer]]:
        dataloader = self.build_dataloader(question, contexts)
        results: Dict[int, List[Answer]] = {}

        if not dataloader:
            return results

        idx = 0
        with torch.no_grad():
            for batch_ids, batch_masks in dataloader:
                try:
                    generated = self.model.generate(
                        input_ids=batch_ids,
                        attention_mask=batch_masks,
                        max_length=self.max_answer_length
                    )
                except Exception as e:
                    print(f"Generation failed: {e}")
                    continue

                for output_seq in generated:
                    decoded_ans = self.tokenizer.decode(output_seq, skip_special_tokens=True).strip()
                    answer_obj = Answer(text=decoded_ans, score=0.0, start=None, end=None)
                    results.setdefault(idx, []).append(answer_obj)
                    idx += 1

        return results


