def _extract_locale_from_request():
    """Helper to extract current locale from Flask request context."""
    from flask import request
    return request.args.get('ln', 'en')


def _build_terms_dict(field_base, values):
    """Constructs a terms filter dict with locale-aware field name."""
    locale = _extract_locale_from_request()
    suffix = '.raw' if 'text' in field_base else ''
    full_field = f"{field_base}{locale}{suffix}"
    return {'terms': {full_field: values}}


def _build_match_bool(terms_list, field_prefix):
    """Builds a bool/should match query for multiple terms."""
    should_clauses = []
    locale = _extract_locale_from_request()
    field_name = f"{field_prefix}.{locale}"

    for term in terms_list:
        should_clauses.append({
            'match': {
                field_name: {'query': term}
            }
        })

    return {
        'bool': {
            'minimum_should_match': 1,
            'should': should_clauses
        }
    }


