requests.packages.urllib3.disable_warnings()
LOG = logging.getLogger(__name__)

def __virtual__():
    return True

def _get_auth_header():
    username = __salt__['pillar.get']('rubrik.username', '')
    password = __salt__['pillar.get']('rubrik.password', '')

    if sys.version_info < (3,):
        auth_str = username + ":" + password
        return base64.b64encode(auth_str)
    else:
        auth_str = username + ':' + password
        return base64.b64encode(auth_str.encode('utf-8'))

def _get_token():
    '''
    Obtain authentication token using credentials from pillar data
    '''
    try:
        node = __salt__['pillar.get']('rubrik.node', '')
        uri = f'https://{node}/api/v1/session'
        b64auth = 'Basic ' + _get_auth_header().decode("utf-8")
        headers = {'Content-Type': 'application/json', 'Authorization': b64auth}
        response = requests.post(uri, headers=headers, verify=False)

        if response.status_code == 422:
            raise ValueError("Authentication failed with Rubrik cluster")

        token = json.loads(response.text).get("token", "")
        return f'Bearer {token}'
    except Exception as e:
        LOG.error(f"Rubrik node connection issues. Please check Rubrik node IP address or hostname in the YAML configuration file, error: {e}")
        return f"Rubrik node connection issues. Please check Rubrik node IP address or hostname in the YAML configuration file, error: {e}"

def cluster_info():
    '''
    Retrieve cluster information from Rubrik
    '''
    try:
        token = _get_token()
        node = __salt__['pillar.get']('rubrik.node', '')
        uri = f'https://{node}/api/v1/cluster/me'
        headers = {'Accept': 'application/json', 'Authorization': token}
        response = requests.get(uri, headers=headers, verify=False, timeout=15)
