    Update SLA domain for a VMware VM
    '''
    try:
        if not hostname:
            hostname = __grains__['id']
        if not sla_domain:
            LOG.error("No SLA Domain name provided")
            raise ValueError("No SLA Domain name provided")

        token = _get_token()
        node = __salt__['pillar.get']('rubrik.node', '')

        # Check if VM exists
        uri = f'https://{node}/api/v1/vmware/vm?primary_cluster_id=local&is_relic=false&name={hostname}'
        headers = {'Accept': 'application/json', 'Authorization': token}
        vm_query = requests.get(uri, headers=headers, verify=False, timeout=15)

        my_vm = None
        for vm in vm_query.json().get('data', []):
            if vm['name'] == hostname:
                my_vm = vm
                break

        if not my_vm:
            LOG.error("VMware VM not found.")
            raise ValueError("VMware VM not found")

        # Compare current and desired SLA
        current_sla = my_vm.get('effectiveSlaDomainName', '')
        if current_sla == sla_domain:
            LOG.info(f'SLA Domain already set to {sla_domain}')
            return f'SLA Domain already set to {sla_domain}'

        # Find SLA domain ID
        uri = f'https://{node}/api/v1/sla_domain?primary_cluster_id=local&name={sla_domain}'
        sla_query = requests.get(uri, headers=headers, verify=False, timeout=15)

