                my_sla = sla
                break

        if not my_sla:
            LOG.error("SLA domain not found.")
            raise ValueError("SLA domain not found")

        # Update VM's SLA
        uri = f'https://{node}/api/v1/vmware/vm/{my_vm["id"]}'
        headers = {'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': token}
        payload = json.dumps({"configuredSlaDomainId": my_sla["id"]})
        update_response = requests.patch(uri, headers=headers, verify=False, data=payload)

