def od_backup_vmware_vm(hostname=None, sla_domain=None, object_type='vmware_vm', wait_for_completion=False):
    '''
    Trigger on-demand snapshot for a VMware VM
    '''
    try:
        if not hostname:
            hostname = __grains__['id']
        if not sla_domain:
            LOG.error("No SLA Domain name provided")
            raise ValueError("No SLA Domain name provided")

        token = _get_token()
        node = __salt__['pillar.get']('rubrik.node', '')

        # Check if VM exists
        uri = f'https://{node}/api/v1/vmware/vm?primary_cluster_id=local&is_relic=false&name={hostname}'
        headers = {'Accept': 'application/json', 'Authorization': token}
        vm_query = requests.get(uri, headers=headers, verify=False, timeout=15)

        my_vm = None
        for vm in vm_query.json().get('data', []):
            if vm['name'] == hostname:
                my_vm = vm
                break

        if not my_vm:
            LOG.error("VMware VM not found.")
            raise ValueError("VMware VM not found")

        # Find SLA domain ID
        uri = f'https://{node}/api/v1/sla_domain?primary_cluster_id=local&name={sla_domain}'
        sla_query = requests.get(uri, headers=headers, verify=False, timeout=15)

        my_sla = None
        for sla in sla_query.json().get('data', []):
            if sla['name'] == sla_domain:
                my_sla = sla
                break

        if not my_sla:
            LOG.error("SLA domain not found.")
            raise ValueError("SLA domain not found")

        # Take snapshot
        uri = f'https://{node}/api/v1/vmware/vm/{my_vm["id"]}/snapshot'
        headers = {'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': token}
        payload = json.dumps({"slaId": my_sla["id"]})
        snapshot_response = requests.post(uri, headers=headers, verify=False, data=payload)

        if snapshot_response.status_code != 202:
            raise ValueError("Failed to take snapshot")

        task_id = snapshot_response.json().get("id", "")
        LOG.info(f'Snapshot taken with task ID: {task_id}')

        if wait_for_completion:
            status = snapshot_response.json().get("status", "")
            while status not in ['SUCCEEDED', 'FAILED', 'WARNING']:
                time.sleep(5)
                uri = f'https://{node}/api/v1/vmware/vm/request/{task_id}'
                task_status = requests.get(uri, headers=headers, verify=False)
                status = task_status.json().get("status", "")

            LOG.info(f'Snapshot finished with status: {status}')
            return f'Snapshot finished with status: {status}'
        else:
            return f'Snapshot taken with task ID: {task_id}'
    except Exception as e:
        LOG.error(f'Error taking on-demand snapshot for this VM: {e}')
        return f'Something went wrong taking an on-demand snapshot for this VM, error: {e}'

