def add_fileset_to_host(hostname=None, fileset_name=None, sla_domain=None, os_type='Linux'):
    '''
    Add fileset to a Windows/Linux/Unix host
    '''
    try:
        if not hostname:
            hostname = __grains__['id']
        if not sla_domain:
            LOG.error("No SLA Domain name provided")
            raise ValueError("No SLA Domain name provided")
        if not fileset_name:
            LOG.error("No Fileset Template name provided")
            raise ValueError("No Fileset Template name provided")

        token = _get_token()
        node = __salt__['pillar.get']('rubrik.node', '')

        # Normalize OS type
        if os_type == 'Linux':
            os_type = 'UnixLike'
        elif os_type == 'Windows':
            os_type = 'Windows'

        # Get Host ID
        uri = f'https://{node}/api/v1/host?primary_cluster_id=local&operating_system_type={os_type}&name={hostname}'
        headers = {'Accept': 'application/json', 'Authorization': token}
        host_query = requests.get(uri, headers=headers, verify=False, timeout=15)

        my_host = None
        for host in host_query.json().get('data', []):
            if host['name'] == hostname:
                my_host = host
                break

        if not my_host:
            LOG.error("Host not found.")
            raise ValueError("Host not found")

        # Get Fileset Template ID
        uri = f'https://{node}/api/v1/fileset_template?primary_cluster_id=local&operating_system_type={os_type}&name={fileset_name}'
        fst_query = requests.get(uri, headers=headers, verify=False, timeout=15)

        my_fst = None
        for fst in fst_query.json().get('data', []):
            if fst['name'] == fileset_name:
                my_fst = fst
                break

        if not my_fst:
            LOG.error("Fileset template not found.")
            raise ValueError("Fileset template not found")

        # Get SLA Domain ID
        uri = f'https://{node}/api/v1/sla_domain?primary_cluster_id=local&name={sla_domain}'
        sla_query = requests.get(uri, headers=headers, verify=False, timeout=15)

        my_sla = None
        for sla in sla_query.json().get('data', []):
            if sla['name'] == sla_domain:
                my_sla = sla
                break

        if not my_sla:
            LOG.error("SLA domain not found.")
            raise ValueError("SLA domain not found")

        # Check if fileset already exists
        uri = f'https://{node}/api/v1/fileset?primary_cluster_id=local&is_relic=false&host_id={my_host["id"]}&template_id={my_fst["id"]}'
        fileset_query = requests.get(uri, headers=headers, verify=False, timeout=15)

        fileset_id = None
        if fileset_query.json().get('total', 0) > 0:
            fileset_id = fileset_query.json()['data'][0]['id']

        # Create fileset if it doesn't exist
        if not fileset_id:
            uri = f'https://{node}/api/v1/fileset'
            headers = {'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': token}
            payload = json.dumps({"hostId": my_host["id"], "templateId": my_fst["id"]})
            create_response = requests.post(uri, headers=headers, verify=False, data=payload)

            if create_response.status_code != 201:
                raise ValueError("Failed to create fileset")

            fileset_id = create_response.json().get('id', '')

        # Apply SLA to fileset
        uri = f'https://{node}/api/v1/fileset/{fileset_id}'
        headers = {'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': token}
        payload = json.dumps({"configuredSlaDomainId": my_sla["id"]})
        sla_response = requests.patch(uri, headers=headers, verify=False, data=payload)

        if sla_response.status_code != 200:
            raise ValueError("Failed to apply SLA to fileset")

        message = f'Fileset created, ID is {fileset_id}. SLA {my_sla["name"]} applied.'
        LOG.info(message)
        return message
    except Exception as e:
        LOG.error(f'Error creating fileset: {e}')
        return f'Something went wrong creating the fileset, error: {e}'

def check_fileset_configuration(hostname=None, fileset_name=None, sla_domain=None, os_type='Linux'):
    '''
    Verify if fileset exists and has correct SLA protection
    '''
    try:
        if not hostname:
            hostname = __grains__['id']
        if not sla_domain:
            LOG.error("No SLA Domain name provided")
            raise ValueError("No SLA Domain name provided")
        if not fileset_name:
            LOG.error("No Fileset Template name provided")
            raise ValueError("No Fileset Template name provided")

        token = _get_token()
        os_type = _normalize_os_type(os_type)

        # Get IDs
        my_host_id = _get_host_id(hostname, os_type)
        if not my_host_id:
            raise ValueError(f"No host ID found for {hostname}")

        my_sla_id = _get_sla_id(sla_domain)
        if not my_sla_id:
            raise ValueError(f"No SLA Domain found with name: {sla_domain}")

        my_fst_id = _get_fst_id(fileset_name, os_type)
        if not my_fst_id:
            raise ValueError(f"No Fileset Template found with name: {fileset_name}")

        # Get fileset ID
        my_fileset_id = _get_fileset_id(my_host_id, my_fst_id)
        if not my_fileset_id:
            LOG.info('Fileset does not exist.')
            return False

        # Check fileset SLA
        my_fileset_sla = _get_fileset_sla(my_fileset_id)
        if not my_fileset_sla:
            raise ValueError(f"Failed to get SLA for {fileset_name}")

        return my_fileset_sla == my_sla_id
    except Exception as e:
        LOG.error(f'Error checking fileset configuration: {e}')
