def get_latest_snapshot(hostname=None, object_type='vmware_vm', **kwargs):
    '''
    Get latest snapshot timestamp for an object
    '''
    try:
        if not hostname:
            hostname = __grains__['id']
        token = _get_token()

        if object_type == 'vmware_vm':
            vm_id = _get_vmware_vm_id(hostname)
            if not vm_id:
                raise ValueError(f"No VM found with name {hostname}")
            return _get_latest_snapshot(vm_id)

        if object_type == 'fileset':
            fileset_name = kwargs.get('fileset_name')
            os_type = kwargs.get('os_type', 'Linux')
            os_type = _normalize_os_type(os_type)

            my_host_id = _get_host_id(hostname, os_type)
            if not my_host_id:
                raise ValueError(f"No host ID found for {hostname}")

            if fileset_name:
                my_fst_id = _get_fst_id(fileset_name, os_type)
                if not my_fst_id:
                    raise ValueError(f"No Fileset Template found with name: {fileset_name}")

                my_fileset_id = _get_fileset_id(my_host_id, my_fst_id)
                if not my_fileset_id:
                    LOG.info('Fileset does not exist.')
                return _get_latest_snapshot(my_fileset_id)
            else:
                output_list = []
                fileset_list = _get_fileset_list(my_host_id)
                for fileset in fileset_list:
                    this_fileset = fileset.copy()
                    this_fileset['last_snapshot'] = _get_latest_snapshot(fileset['id'])
                    output_list.append(this_fileset)
                return output_list
    except Exception as e:
        LOG.error(f'Error getting latest snapshot: {e}')
        return f'Error getting latest snapshot: {e}'

