def _get_latest_snapshot(object_id):
    '''Get latest snapshot timestamp for an object'''
    object_type = object_id.split(':::')[0] if ':::' in object_id else object_id.split(':')[0]
    token = _get_token()
    node = __salt__['pillar.get']('rubrik.node', '')

    if object_type == 'VirtualMachine':
        uri = f'https://{node}/api/v1/vmware/vm/{object_id}/snapshot'
    elif object_type == 'Fileset':
        uri = f'https://{node}/api/v1/fileset/{object_id}'
    else:
        raise ValueError(f"Unsupported object type: {object_type}")

    headers = {'Accept': 'application/json', 'Authorization': token}
    snapshot_query = requests.get(uri, headers=headers, verify=False, timeout=15)

    if object_type == 'VirtualMachine':
        if snapshot_query.json().get('total', 0) > 0:
            datestr = snapshot_query.json()['data'][0]['date']
            return str(datetime.datetime.strptime(datestr, '%Y-%m-%dT%H:%M:%S.%fZ'))
        return None

    elif object_type == 'Fileset':
        snapshots = snapshot_query.json().get('snapshots', [])
        if len(snapshots) > 0:
            datestr = snapshots[-1]['date']
            return str(datetime.datetime.strptime(datestr, '%Y-%m-%dT%H:%M:%S.%fZ'))
        return None
    return None

def _normalize_os_type(os_type):
    '''Normalize operating system type'''
    if os_type == 'Linux':
        return 'UnixLike'
    elif os_type == 'Windows':
        return 'Windows'
    return None

