class PullRequest:
    def __init__(self, data, _):
        self.data = data or {}
        self.title = self.data.get("title", "")
        self.labels = self.data.get("labels", [])

    @property
    def release_version(self):
        import re
        match = re.search(r"Release version\s+(\S+)", self.title)
        if match:
            version = match.group(1)
            # Ensure it's a valid semver-like string (basic check)
            if re.match(r'^\d+\.\d+\.\d+(-[a-zA-Z0-9]+)?$', version):
                return version
        return None

    def generate_body(self, version, commits):
        commit_list = "\n".join(f"- {commit}" for commit in commits)
        return f"""These commits are new since version {version}:
{commit_list}
To release the new version:
- [ ] Label this PR (ex. `release: major`)
- [ ] Update the changelog on this branch (optional)
- [ ] Merge this PR (commit message should start with `Release version {version}`)
"""

def test_pr_release_version():
    pr = PullRequest({"title": "Release version <next>"}, None)
    assert pr.release_version is None
    pr = PullRequest({"title": "Release version 1.0.0"}, None)
    assert pr.release_version == "1.0.0"
    pr = PullRequest({"title": "Release version 1.0.0-beta"}, None)
    assert pr.release_version == "1.0.0-beta"
    pr = PullRequest({"title": "Release version 1.0.0-beta ok"}, None)
    assert pr.release_version == "1.0.0-beta"

def test_pr_body():
    pr = PullRequest(None, None)
    expected = """These commits are new since version 1.0.0:
- Update x
- Update y
To release the new version:
- [ ] Label this PR (ex. `release: major`)
- [ ] Update the changelog on this branch (optional)
- [ ] Merge this PR (commit message should start with `Release version 1.0.0`)
"""
    assert pr.generate_body("1.0.0", ["Update x", "Update y"]) == expected

def test_pr_body_prerelease():
    pr = PullRequest(None, None)
    expected = """These commits are new since version 1.0.0-beta:
- Update x
- Update y
To release the new version:
