- [ ] Update the changelog on this branch (optional)
- [ ] Merge this PR (commit message should start with `Release version 1.0.0-beta`)
"""
    assert pr.generate_body("1.0.0-beta", ["Update x", "Update y"]) == expected

def test_pr_next_semver():
    def parse_semver(version):
        import re
        match = re.match(r'(\d+)\.(\d+)\.(\d+)(?:-(\w+)\.(\d+))?', version)
        if not match:
            return None
        major, minor, patch = map(int, match.groups()[:3])
        prerelease = match.group(4)
        prerelease_num = int(match.group(5)) if match.group(5) else None
        return major, minor, patch, prerelease, prerelease_num

    def format_semver(major, minor, patch, prerelease=None, prerelease_num=None):
        base = f"{major}.{minor}.{patch}"
        if prerelease and prerelease_num is not None:
            return f"{base}-{prerelease}.{prerelease_num}"
        return base

    def get_next_semver(pr_data):
        pr = PullRequest(pr_data, None)
        labels = [label.get("name") for label in pr.labels]

        # Determine bump type
        is_major = "release: major" in labels
        is_minor = "release: minor" in labels
        is_prerelease = "release: prerelease" in labels

        def increment_version(current_version):
            parts = parse_semver(current_version)
            if not parts:
                return None
            major, minor, patch, pre, pre_num = parts

            if is_prerelease:
                if pre and pre_num is not None:
                    # Already in prerelease, increment prerelease number
                    return format_semver(major, minor, patch, pre, pre_num + 1)
                else:
                    # First prerelease after stable
                    if is_major:
                        return format_semver(major + 1, 0, 0, "rc", 1)
                    elif is_minor:
                        return format_semver(major, minor + 1, 0, "rc", 1)
                    else:
                        return format_semver(major, minor, patch + 1, "rc", 1)
            else:
                # Not in prerelease mode
                if is_major:
                    return format_semver(major + 1, 0, 0)
                elif is_minor:
                    return format_semver(major, minor + 1, 0)
                else:
                    return format_semver(major, minor, patch + 1)

        return increment_version("1.0.0")

    # Test cases
    pr = PullRequest({"labels": [{"name": "release: major"}]}, None)
    assert get_next_semver(pr.data) == "2.0.0"

    pr = PullRequest({"labels": [{"name": "release: minor"}]}, None)
    assert get_next_semver(pr.data) == "1.1.0"

    pr = PullRequest({"labels": [{"name": "release: prerelease"}]}, None)
    assert get_next_semver(pr.data) is None

    pr = PullRequest(
        {"labels": [{"name": "release: prerelease"}, {"name": "release: major"}]}, None
    )
    assert get_next_semver(pr.data) == "2.0.0-rc.1"

    pr = PullRequest(
        {"labels": [{"name": "release: prerelease"}, {"name": "release: minor"}]}, None
    )
    assert get_next_semver(pr.data) == "1.1.0-rc.1"

    pr = PullRequest({"labels": [{"name": "release: prerelease"}]}, None)
    assert get_next_semver(pr.data) == "1.0.0-rc.2"

from fnmatch import fnmatch
import inspect
import json
import re
import gramex
import gramex.cache
from typing import get_type_hints
from textwrap import dedent
from gramex.config import merge
from gramex.transforms.transforms import typelist, Header
from gramex.handlers import BaseHandler

config = gramex.cache.open('openapiconfig.yaml', 'config', rel=True)


def extract_url_name(url_pattern):
    # Extract meaningful segments from URL path
    parts = url_pattern.split('/')
    meaningful_parts = []
    for segment in parts:
        has_alphanumeric = False
        for char in segment:
            if char.isalnum():
                has_alphanumeric = True
                break
        if has_alphanumeric:
            meaningful_parts.append(segment)

    # Normalize separators and capitalize each word
    combined = ' '.join(meaningful_parts)
    words = re.split(r'[\s\-_]', combined)
    capitalized_words = [word.capitalize() for word in words if word]
    return ' '.join(capitalized_words)


class OpenAPIHandler(BaseHandler):
    type_mapping = {
        str: 'string',
        int: 'integer',
        float: 'number',
        bool: 'boolean',
        type(None): 'null'
    }

    @classmethod
    def generate_function_schema(cls, func_obj):
        parameter_list = []
        schema = {
            'description': dedent(getattr(func_obj, '__doc__', '') or ''),
            'parameters': parameter_list
        }

        try:
            sig = inspect.signature(func_obj)
        except ValueError:
            return schema

        annotations = get_type_hints(func_obj)

        for param_name, param_obj in sig.parameters.items():
            annotation = annotations.get(param_name, None)
            base_type, is_array = (typelist(annotation) if annotation else (str, False))

            location = 'header' if annotation is Header else 'query'

            desc = ''
            if hasattr(annotation, '__metadata__') and len(annotation.__metadata__) > 0:
                desc = annotation.__metadata__[0]

            entry = {
                'in': location,
                'name': param_name,
                'description': desc,
                'schema': {}
            }
            parameter_list.append(entry)

            # Required vs optional
            if param_obj.default is inspect.Parameter.empty:
                entry['required'] = True
            else:
                entry['schema']['default'] = param_obj.default

            # Schema type handling
            mapped_type = cls.type_mapping.get(base_type, 'string')
            if is_array:
                entry['schema']['type'] = 'array'
                entry['schema']['items'] = {'type': mapped_type}
            else:
                entry['schema']['type'] = mapped_type

        schema['responses'] = config.responses
        return schema

    def build_formhandler_schema(self, handler_class, operation_summary):
        schema = {}
        data_sources = getattr(handler_class, 'datasets', {})
        get_operation = {
            'summary': operation_summary,
            'description': f'Query data from {len(data_sources)} data source(s)',
        }
        query_params = get_operation['parameters'] = []

        for ds_name, dataset in data_sources.items():
            def append_param(original, **overrides):
                merged = merge({}, original)
                final_name = merged['name'] if handler_class.single else f'{ds_name}:{merged["name"]}'
                query_params.append(merge(merged, {
                    'name': final_name,
                    **overrides
                }))

            columns_list = []
            sort_options = []

            raw_cols = dataset.get('columns', [])
            for col_def in raw_cols:
                if isinstance(col_def, dict):
                    append_param(config.formhandler.col, name=col_def['name'], schema={'type': col_def['type']})
                    columns_list.append(col_def['name'])
                    sort_options.append(col_def['name'])
                    sort_options.append('-' + col_def['name'])
                else:
                    append_param(config.formhandler.col, name=col_def)
                    columns_list.append(col_def)
                    sort_options.append(col_def)
                    sort_options.append('-' + col_def)

            append_param(config.formhandler._sort, schema={'items': {'enum': sort_options}})
            append_param(config.formhandler._c, schema={'items': {'enum': columns_list}})
            append_param(config.formhandler._offset)
            append_param(config.formhandler._limit)
            append_param(config.formhandler._meta)

        get_operation['responses'] = config.responses
        return {'get': get_operation}

    def get(self):
        kwargs = self.conf.get('kwargs', {})
        self.set_header('Content-Type', 'application/json')

        openapi_spec = {
            'openapi': '3.0.2',
            'info': kwargs.get('info', {}),
            'servers': kwargs.get('servers', {}),
            'paths': {}
        }

        url_patterns = kwargs.get('urls', ['*'])

        for route_key, route_config in gramex.conf['url'].items():
            key_suffix = route_key.split(':')[-1]
            if not any(fnmatch(key_suffix, pattern) for pattern in url_patterns):
                continue

            normalized_pattern = route_config['pattern'].replace('/./', '/')
            if route_key not in gramex.service.url or 'handler' not in route_config:
                continue

            summary = f'{extract_url_name(normalized_pattern)}: {route_config["handler"]}'

            path_entry = {
                'get': {'summary': summary},
            }

            handler_cls = gramex.service.url[route_key].handler_class

            if issubclass(handler_cls, gramex.handlers.FunctionHandler):
                if not hasattr(handler_cls, 'info') or 'function' not in handler_cls.info:
                    continue
                func_ref = handler_cls.info['function']
                if hasattr(func_ref, '__func__') and func_ref.__func__:
                    func_ref = func_ref.__func__
                elif callable(func_ref):
                    pass
                else:
                    continue

                func_schema = self.generate_function_schema(func_ref)
                func_schema['summary'] = summary
                methods_to_include = getattr(handler_cls, '_http_methods', 'GET POST PUT DELETE PATCH OPTIONS'.split())
                for method in methods_to_include:
                    path_entry[method.lower()] = func_schema

            elif issubclass(handler_cls, gramex.handlers.FormHandler):
                path_entry.update(self.build_formhandler_schema(handler_cls, summary=summary))

            # Apply user-defined overrides
            merge(path_entry, handler_cls.conf.get('openapi', {}), mode='overwrite')

            openapi_spec['paths'][normalized_pattern] = path_entry

        # Parse query args for indentation
        indent_val = self.argparse(indent={'type': int, 'default': 0}).indent or None

        output = json.dumps(
            openapi_spec,
            indent=indent_val,
            separators=(', ', ': ') if indent_val else (',', ':'),
        )
        self.write(output)

