from rlinf.data.tool_call.tool_io_struct import ToolChannelRequest, ToolChannelResponse

class BaseExecutor:
    name = None

    def __init__(self, config):
        self.config = config
        self.endpoint = f"http://{config.tools.codejudge.host_addr}:{config.tools.codejudge.host_port}/run/long-batch"

    def _format_response(self, outcome):
        if outcome["run_success"] and outcome["success"]:
            parts = []
            parts.append("Tool call success")
            if outcome.get("stdout"):
                parts.append(f"stdout: {outcome['stdout']}")
            if outcome.get("stderr"):
                parts.append(f"stderr: {outcome['stderr']}")
            parts.append(f"execution time: {outcome['cost']:.2f}s")
            return ToolChannelResponse(success=True, result="\n".join(parts))
        else:
            parts = []
            parts.append("Tool call failure")
            parts.append(f"reason: {outcome.get('reason', 'Unknown error')}")
            if outcome.get("stdout"):
                parts.append(f"stdout: {outcome['stdout']}")
            if outcome.get("stderr"):
                parts.append(f"stderr: {outcome['stderr']}")
            parts.append(f"execution time: {outcome['cost']:.2f}s")
            return ToolChannelResponse(success=False, result="\n".join(parts))

