            code: The source code string
        Returns:
            tuple[str, Optional[str]]: (main code body, last expression if exists)
        """
        try:
            tree = ast.parse(code)
            if not tree.body:
                return code, None

            last_stmt = tree.body[-1]
            if isinstance(last_stmt, ast.Expr):
                start_line = last_stmt.lineno
                end_line = last_stmt.end_lineno if hasattr(last_stmt, 'end_lineno') else start_line

                lines = code.splitlines()
                main_part = '\\n'.join(lines[:start_line-1])
                expr_part = '\\n'.join(lines[start_line-1:end_line])
                return main_part, expr_part
        except SyntaxError as e:
            raise ExecutionError(e, code)
        return code, None

    def run_code(self, code: str, suppress_output: bool) -> None:
        """
        Execute code while preserving environment state.
        If the final line is an expression, its value will be printed to stdout.
        Args:
            code: The source code string to execute
            suppress_output: If True, suppress stdout and stderr output
        """
        try:
            main_body, final_expr = self.separate_code(code)

            # Setup output redirection
            if suppress_output:
                out_buffer = StringIO()
                err_buffer = StringIO()
                out_context = redirect_stdout(out_buffer)
                err_context = redirect_stderr(err_buffer)
            else:
                out_context = redirect_stdout(sys.stdout)
                err_context = redirect_stderr(sys.stderr)

            # Execute main code body
            if main_body:
                try:
                    compiled_main = compile(main_body, '<string>', 'exec')
                    with out_context, err_context:
                        exec(compiled_main, self.global_state)
                except Exception as e:
                    raise ExecutionError(e, main_body)

            # Evaluate and print final expression if present
            if final_expr:
                try:
                    compiled_expr = compile(final_expr, '<string>', 'eval')
                    with out_context, err_context:
                        result = eval(compiled_expr, self.global_state)
                    if result is not None and not suppress_output:
                        print(repr(result), file=sys.stdout)
                except Exception as e:
                    try:
                        compiled_stmt = compile(final_expr, '<string>', 'exec')
                        with out_context, err_context:
                            exec(compiled_stmt, self.global_state)
                    except Exception as e:
                        offset = len(main_body.splitlines()) if main_body else 0
                        raise ExecutionError(e, final_expr, offset)
        except Exception as e:
            if suppress_output:
                return
            if isinstance(e, ExecutionError):
                print(str(e), file=sys.stderr)
            else:
                traceback.print_exc(file=sys.stderr)
            os._exit(1)
            return

stateful_runner = StatefulRunner()
'''

code_execution_template = """
code_to_run = base64.b64decode("{}\\n".encode()).decode()
stateful_runner.run_code(code_to_run, suppress_output={})
"""

class PythonExecutor(BaseExecutor):
    name = "python_code_with_standard_io"

    def __init__(self, cfg):
        super().__init__(cfg=cfg)

    async def run(
        self,
        request: ToolChannelRequest,
        api_call_func: Callable[[str, dict], ToolChannelResponse],
    ):
        validation_result = self.validate(request)
        if validation_result:
            return validation_result

        # Encode the code for transmission
        encoded_code = base64.b64encode(
            request.tool_args.get("code", "").encode()
        ).decode()

        # Construct final execution script
        full_script = code_setup_block
        full_script += code_execution_template.format(encoded_code, "False")

        # Prepare submission payload
        submission_data = {
            "type": "python",
            "solution": full_script,
            "input": request.tool_args.get("input", ""),
        }
        payload = {"type": "batch", "submissions": [submission_data]}

        # Retry logic for robustness
        for attempt in range(4):
            try:
                response_data = await api_call_func(self.endpoint, payload)
                results = response_data["results"]
                break
            except Exception as ex:
                print(f"Retry attempt {attempt}, error: {ex}")
                time.sleep(1)
        else:
            raise RuntimeError("Tool invocation failed after maximum retries")

        # Ensure single result
        assert len(results) == 1, f"Unexpected result count: {results}"
        return self._format_response(results[0])

    def specification(self) -> dict:
        return {
            "type": "function",
            "function": {
                "name": "python_code_with_standard_io",
                "description": "Execute Python code with standard input handling. This function accepts a Python code string and an input string, feeds the input via stdin during execution, and captures any stdout output. Exceptions are caught and returned as part of the response.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "code": {
                            "type": "string",
                            "description": "Python code to execute, may include input() calls",
                        },
                        "input": {
                            "type": "string",
                            "description": "Input data to provide through stdin when code calls input()",
                        },
                    },
                    "required": ["code", "input"],
                },
            },
        }

    def validate(self, request) -> Optional[ToolChannelResponse]:
        args = request.tool_args

        # Check tool name matches
        if request.tool_name != self.name:
            return ToolChannelResponse(
                success=False,
                result=f"Name mismatch: expected '{self.name}', got '{request.tool_name}'"
            )

        # Validate argument structure
        if not isinstance(args, dict):
            return ToolChannelResponse(
                success=False,
                result="Invalid arguments format: expected dictionary"
            )

        # Validate individual fields
        if "code" in args and not isinstance(args["code"], str):
            return ToolChannelResponse(
                success=False,
                result="Invalid 'code' field: expected string"
            )

        if "input" in args and not isinstance(args["input"], str):
            return ToolChannelResponse(
                success=False,
                result="Invalid 'input' field: expected string"
            )

