# Retrieve API key from environment variables
API_KEY = os.getenv("LEETIFY_API_KEY")
if not API_KEY:
    print(json.dumps({"error": "LEETIFY_API_KEY environment variable not set"}))
    sys.exit(1)

# Define base URL for the Leetify public API
API_BASE_URL = "https://api-public.cs-prod.leetify.com"

def make_api_call(path, query_params=None):
    """
    Send a GET request to the Leetify API with proper authentication.
    Returns a standardized result dictionary indicating success/failure.
    """
    auth_headers = {"Authorization": f"Bearer {API_KEY}"}
    full_url = f"{API_BASE_URL}{path}"

    try:
        response = requests.get(full_url, params=query_params, headers=auth_headers)

        if response.status_code == 200:
            return {"success": True, "payload": response.json()}
        else:
            return {
                "success": False,
                "message": f"HTTP {response.status_code}: {response.text}"
            }
    except Exception as exc:
        return {"success": False, "message": str(exc)}

def fetch_player_match_stats(steam_id, match_position=0):
    # Step 1: Fetch list of recent matches for the given Steam ID
    api_result = make_api_call('/v3/profile/matches', {
        'steam64_id': steam_id,
        'limit': match_position + 1
    })

    if not api_result['success']:
        print(json.dumps({"error": api_result.get('message')}))
        return

    raw_matches = api_result['payload']

    # Normalize response format — handle both direct list and wrapped object
    if isinstance(raw_matches, dict) and 'matches' in raw_matches:
        raw_matches = raw_matches['matches']

    if not isinstance(raw_matches, list):
        print(json.dumps({"error": "Unexpected API response structure"}))
        return

    # Validate requested match index
    if len(raw_matches) <= match_position:
        print(json.dumps({
            "error": f"Match index {match_position} out of range. Total available: {len(raw_matches)}"
        }))
        return

    selected_match = raw_matches[match_position]

    # Step 2: Locate player's stats within the match
    player_data = next(
        (entry for entry in selected_match.get('stats', []) if entry.get('steam64_id') == steam_id),
        None
    )

    if player_data is None:
        print(json.dumps({"error": "Player statistics not found in this match record"}))
        return

    # Step 3: Assemble comprehensive analysis payload
    output = {
        "metadata": {
            "map": selected_match.get('map_name'),
            "timestamp": selected_match.get('finished_at'),
            "scores": selected_match.get('team_scores'),
            "source": selected_match.get('data_source'),
            "match_uuid": selected_match.get('id')
        },
        "performance": player_data
    }

    # Output formatted JSON for downstream processing
    print(json.dumps(output, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Fetch detailed CS2 match stats for a Leetify user")
    parser.add_argument("--username", required=True, help="Steam username to look up")
    parser.add_argument("--match", type=int, default=0, dest="index", help="Index of match to analyze (0 = most recent)")
    cli_args = parser.parse_args()

    script_path = os.path.abspath(__file__)
    script_folder = os.path.dirname(script_path)

    try:
        # Resolve Steam username to Steam64 ID using external helper script
        lookup_output = subprocess.check_output(
            ['python3', os.path.join(script_folder, 'steam_ids.py'), 'get', '--username', cli_args.username],
            text=True
        ).strip()

        if not lookup_output or "No Steam ID" in lookup_output:
            print(json.dumps({"error": f"Could not resolve Steam ID for user '{cli_args.username}'"}))
            sys.exit(1)

        resolved_steam_id = lookup_output

    except subprocess.CalledProcessError as err:
        print(json.dumps({"error": f"Failed to resolve Steam ID: {str(err)}"}))
        sys.exit(1)
    except Exception as e:
        print(json.dumps({"error": f"Unexpected error during Steam ID lookup: {str(e)}"}))
        sys.exit(1)

    # Proceed with fetching match data
    fetch_player_match_stats(resolved_steam_id, cli_args.index)

