import os

def read_file_safe(filename):
    """Read file - SECURE VERSION with path validation"""
    base_dir = "/path/to/user/documents"

    # Normalize the input and resolve any relative paths
    normalized_input = os.path.normpath(filename)

    # Prevent directory traversal by checking for '..' in the path
    if '..' in normalized_input or normalized_input.startswith('/'):
        raise ValueError("Invalid filename: path traversal detected")

    # Construct full path safely
    filepath = os.path.join(base_dir, normalized_input)

    # Ensure the resolved path is still within base_dir
    real_base = os.path.realpath(base_dir)
    real_path = os.path.realpath(filepath)

    if not real_path.startswith(real_base + os.sep) and real_path != real_base:
        raise ValueError("Access denied: path outside allowed directory")

    with open(filepath, 'r') as f:
        return f.read()

def read_config_safe(config_name):
    """Read config - SECURE VERSION with restricted access"""
    # Only allow specific config names from a predefined list
    allowed_configs = {"settings.conf", "database.conf", "app.conf"}

    if config_name not in allowed_configs:
        raise ValueError(f"Access denied: '{config_name}' is not an allowed configuration")

    # Construct safe path using only validated config name
    path = f"/etc/app/{config_name}"

    # Additional safety check
    if not os.path.isfile(path):
        raise FileNotFoundError(f"Configuration file '{config_name}' not found")

    with open(path, 'r') as f:
        return f.read()

if __name__ == "__main__":
    print("Secure file reader ready")

# WebAuthn API - Passwordless Authentication Credential Management
# Implements cryptographic verification via WebAuthnService

from flask import Blueprint, request, g
from auth.unified import require_auth
from models import db
from models.webauthn import WebAuthnCredential
from services.webauthn_service import WebAuthnService
from services.audit_service import AuditService
from utils.response import success_response, error_response

bp = Blueprint('webauthn', __name__, url_prefix='/api/v2/webauthn')

@bp.route('/credentials', methods=['GET'])
@require_auth()
def list_credentials():
    """Retrieve all registered WebAuthn credentials for the authenticated user"""
    current_user = g.current_user
    user_creds = WebAuthnService.fetch_credentials_for_user(current_user.id)
    return success_response(data=[cred.as_dict() for cred in user_creds])

@bp.route('/credentials/<int:cred_id>', methods=['DELETE'])
@require_auth()
def remove_credential(cred_id):
    """Remove a specific WebAuthn credential by ID"""
    current_user = g.current_user
    deletion_ok, msg = WebAuthnService.remove_credential(cred_id, current_user.id)

    if not deletion_ok:
        return error_response(msg, 404)

    AuditService.record_event(
        event_type='webauthn_removal',
        target_entity='webauthn',
        entity_identifier=str(cred_id),
        entity_label=f'WebAuthn credential {cred_id}',
        description=f'Removed WebAuthn credential {cred_id}',
        outcome=True
    )

    return success_response(message=msg)

@bp.route('/credentials/<int:cred_id>/status', methods=['POST'])
@require_auth()
def update_credential_status(cred_id):
    """Toggle activation status of a WebAuthn credential"""
    current_user = g.current_user
    payload = request.get_json(silent=True) or {}
    activate = payload.get('active', True)

    update_ok, msg = WebAuthnService.set_credential_status(cred_id, current_user.id, activate)

    if not update_ok:
        return error_response(msg, 404)

    AuditService.record_event(
        event_type='webauthn_status_change',
        target_entity='webauthn',
        entity_identifier=str(cred_id),
        entity_label=f'WebAuthn credential {cred_id}',
        description=f'{"Activated" if activate else "Deactivated"} WebAuthn credential {cred_id}',
        outcome=True
    )

    return success_response(message=msg)

@bp.route('/enroll/options', methods=['POST'])
@require_auth()
def get_enrollment_params():
    """Generate WebAuthn registration parameters using secure cryptographic setup"""
    current_user = g.current_user
    server_origin = request.host

    reg_params = WebAuthnService.create_registration_parameters(current_user, server_origin)
    return success_response(data=reg_params)

@bp.route('/enroll/validate', methods=['POST'])
@require_auth()
def confirm_enrollment():
    """Validate WebAuthn registration response and store new credential"""
    current_user = g.current_user
    payload = request.get_json()

    attestation_data = payload.get('attestation', {})
    credential_label = payload.get('label', 'Security Key')
    server_origin = request.host

    validation_ok, msg, new_credential = WebAuthnService.validate_attestation(
        current_user.id, attestation_data, server_origin, credential_label
    )

    if not validation_ok:
        return error_response(msg, 400)

    AuditService.record_event(
        event_type='webauthn_enrollment',
        target_entity='webauthn',
        entity_identifier=str(new_credential.id) if new_credential else None,
        entity_label=credential_label,
        description=f'Completed WebAuthn enrollment: {credential_label}',
        outcome=True
    )

    return success_response(
        data=new_credential.as_dict() if new_credential else None,
        message=msg
    )

# Type III Clone: Refactored version with equivalent functionality but different structure

import os
import sys
import copy
import tempfile
import shutil
from pathlib import Path
from dataclasses import asdict
from contextlib import contextmanager
from typing import Callable, Tuple, List, Optional, Any
import functools

# Assuming these modules exist in the same project structure
from graph_net.dynamic_dim_constraints import DynamicDimConstraints
from graph_net.imp_util import load_module
from graph_net.tensor_meta import TensorMeta


class InputConstraintUpdater:
    def __init__(self, config=None):
        self.config = self._build_config(config or {})
        self.data_input_checker = self._create_data_input_checker()
        self.model_runner_checker = self._create_model_runner_checker()
        self.handled_count = 0

    def _build_config(self, raw_config):
        defaults = {
            "data_input_predicator_filepath": None,
            "model_runnable_predicator_filepath": None,
            "data_input_predicator_class_name": "DataInputPredicator",
            "model_runnable_predicator_class_name": "ModelRunner",
            "data_input_predicator_config": {},
            "model_runnable_predicator_config": {},
            "dimension_generalizer_filepath": None,
            "dimension_generalizer_class_name": "StaticToDynamic",
            "dimension_generalizer_config": {},
            "model_path_prefix": "",
            "resume": False,
            "last_model_log_file": None,
            "limits_handled_models": None,
        }
        for key in defaults:
            if key not in raw_config:
                raw_config[key] = defaults[key]
        return raw_config

    def _create_data_input_checker(self):
        module = load_module(self.config["data_input_predicator_filepath"])
        cls = getattr(module, self.config["data_input_predicator_class_name"])
        return cls(self.config["data_input_predicator_config"])

    def _create_model_runner_checker(self):
        module = load_module(self.config["model_runnable_predicator_filepath"])
        cls = getattr(module, self.config["model_runnable_predicator_class_name"])
        return cls(self.config["model_runnable_predicator_config"])

    def __call__(self, model_path):
        full_model_path = os.path.join(self.config["model_path_prefix"], model_path)
        constraint_file = os.path.join(full_model_path, "input_tensor_constraints.py")

        # Resume logic: skip if constraints already exist and contain symbols
        if (self.config["resume"] and 
            os.path.exists(constraint_file) and 
            DynamicDimConstraints.kSymbols in open(constraint_file).read()):
            module = load_module(constraint_file)
            symbols = getattr(module, DynamicDimConstraints.kSymbols)
            if len(symbols) > 0:
                return

        # Process tensor metadata
        tensor_metas = self._collect_tensor_metadata(full_model_path)
        meta_dicts = [asdict(tm) for tm in tensor_metas]

        # Generate inputs using dimension generalizer
        dim_gen = self._get_dimension_generalizer()
        inputs = dim_gen.create_inputs_by_metas(
            module=self._load_model(full_model_path),
            tensor_meta_attrs_list=meta_dicts
        )

        # Create initial dynamic dimension constraints
        dyn_cstr = self._make_initial_constraints(tensor_metas)

        # Define helper functions for constraint checking
        def check_data_input(var_name):
            return self.data_input_checker(full_model_path, var_name)

        def get_temp_model_context(dim_pairs):
            return self._attempt_dimension_generalization(
                dim_pairs, full_model_path, inputs
            )

        def make_feasibility_checker(temp_path):
            def check_feasibility(cstr):
                return self._check_constraint_feasibility(
                    temp_path, tensor_metas, cstr
                )
            return check_feasibility

        # Set up feasibility context manager
        feasibility_mgr = FeasibilityContextManager(
            get_temp_model_context,
            make_feasibility_checker
        )

        # Symbolize dimensions
        updated_cstr, pass_names = self._symbolize_dimensions(
            dyn_cstr, 
            check_data_input, 
            feasibility_mgr
        )

        # Save results
        self._save_constraints(updated_cstr, full_model_path)
        self._save_pass_names(pass_names, full_model_path)

        # Update handled count and check limits
        self.handled_count += 1
        limit = self.config["limits_handled_models"]
        if limit is not None and self.handled_count >= limit:
            print("Handled model limit reached", file=sys.stderr)
            sys.exit(0)

    def _get_dimension_generalizer(self):
        if hasattr(self, "_dim_gen"):
            return self._dim_gen

        filepath = self.config["dimension_generalizer_filepath"]
        assert filepath is not None, "Dimension generalizer filepath required"

        module = load_module(filepath)
        cls = getattr(module, self.config["dimension_generalizer_class_name"])
        self._dim_gen = cls(self.config["dimension_generalizer_config"])
        return self._dim_gen

    def _load_model(self, path):
        py_mod = load_module(os.path.join(path, "model.py"))
        GraphModule = getattr(py_mod, "GraphModule")
        GraphModule.__graph_net_file_path__ = py_mod.__graph_net_file_path__
        return GraphModule()

    @contextmanager
    def _attempt_dimension_generalization(self, dim_axes, model_path, inputs):
        if self.config["dimension_generalizer_filepath"] is None:
            self._log_model(model_path)
            yield model_path, ()
            return

        model = self._load_model(model_path)
        dim_gen = self._get_dimension_generalizer()
        gen_pass = dim_gen(model, dim_axes)

        need_rewrite = gen_pass.need_rewrite(inputs)
        if not need_rewrite:
            self._log_model(model_path)
            yield model_path, ()
            return

        graph_module = gen_pass.rewrite(inputs)

        with tempfile.TemporaryDirectory() as tmp_dir:
            shutil.copytree(Path(model_path), Path(tmp_dir), dirs_exist_ok=True)
            gen_pass.save_graph_module(graph_module, tmp_dir)
            self._log_model(tmp_dir)
            yield tmp_dir, gen_pass.get_pass_names()

    def _log_model(self, model_path):
        if self.config["last_model_log_file"]:
            log_file = Path(self.config["last_model_log_file"])
            shutil.copy(
                Path(model_path) / "model.py", 
                log_file
            )

    def _save_pass_names(self, pass_names, model_path):
        from graph_net.graph_net_json_file_util import (
            kDimensionGeneralizationPasses,
            update_json,
        )
        update_json(
            model_path, 
            kDimensionGeneralizationPasses, 
            list(pass_names)
        )

    def _save_constraints(self, constraints, model_path):
        code = constraints.serialize_to_py_str()
        with open(os.path.join(model_path, "input_tensor_constraints.py"), "w") as f:
            f.write(code)

    def _collect_tensor_metadata(self, path):
        unserializer = TensorMeta.unserialize_from_py_file
        input_meta = unserializer(os.path.join(path, "input_meta.py"))
        weight_meta = unserializer(os.path.join(path, "weight_meta.py"))
        return list(input_meta) + list(weight_meta)

    def _check_constraint_feasibility(self, model_path, tensor_metas, constraints):
        deep_copy = copy.deepcopy(tensor_metas)
        self._apply_constraints_to_metas(deep_copy, constraints)

        weight_code = "\n".join(
            tm.serialize_to_py_str() for tm in deep_copy
        )

        with tempfile.TemporaryDirectory() as tmpdir:
            for fname in ["graph_net.json", "model.py"]:
                src = os.path.join(model_path, fname)
                dst = os.path.join(tmpdir, fname)
                with open(dst, "w") as f:
                    f.write(open(src).read())

            with open(os.path.join(tmpdir, "input_meta.py"), "w") as f:
                f.write("")
            with open(os.path.join(tmpdir, "weight_meta.py"), "w") as f:
                f.write(weight_code)

            return self.model_runner_checker(tmpdir)

    def _apply_constraints_to_metas(self, metas, constraints):
        shape_map = {
            name: [constraints._try_reify(d) for d in shape]
            for shape, name in constraints.input_shapes
        }

        for meta in metas:
            if meta.name not in shape_map:
                continue
            meta.shape = shape_map[meta.name]
            if meta.data is not None:
                size = functools.reduce(lambda a, b: a * b, meta.shape, 1)
                doubled = list(meta.data) * 2
                meta.data = doubled[:size]

    def _make_initial_constraints(self, tensor_metas):
        named_inputs = [
            (tm.shape, tm.name) 
            for tm in tensor_metas
        ]
        return DynamicDimConstraints.make_by_named_inputs(named_shapes=named_inputs)

    def _symbolize_dimensions(self, constraints, is_data_input, feasibility_mgr):
        unique_dims = []
        dim_to_axes = {}

        # First pass: collect all input dimensions
        def dummy_filter(name, idx, axis, dim):
            if is_data_input(name):
                if dim not in unique_dims:
                    unique_dims.append(dim)
                    dim_to_axes[dim] = []
                dim_to_axes[dim].append(axis)
            return False

        assert constraints.symbolize(dummy_filter) is None

        total_pass_names = ()

        def add_pass_names(pass_names):
            nonlocal total_pass_names
            total_pass_names = tuple(set(total_pass_names + tuple(pass_names)))

        # Process each dimension
        for i, dim in enumerate(unique_dims):
            current = copy.deepcopy(constraints)

            def select_filter(name, idx, axis, d):
                return (
                    is_data_input(name) and 
                    d == dim and 
                    (d > 1 or axis == 0)
                )

            symbol = current.symbolize(select_filter)
            if symbol is None:
                continue

            value_map = {symbol: dim + 1}
            if not current.check_delta_symbol2example_value(value_map):
                continue

            dim_pairs = tuple(
                (d, dim_to_axes[d]) 
                for d in unique_dims[:i+1]
            )

            with feasibility_mgr(dim_pairs) as checker:
                temp_cstr = copy.deepcopy(current)
                temp_cstr.update_symbol2example_value(value_map)

                if checker(temp_cstr):
                    constraints = current
                    add_pass_names(checker.dim_gen_pass_names)

        return constraints, total_pass_names


class FeasibilityContextManager:
    def __init__(self, get_temp_path_ctx, get_checker_func):
        self.get_temp_path_context = get_temp_path_ctx
        self.get_checker_function = get_checker_func

    @contextmanager
    def __call__(self, dim_pairs):
        with self.get_temp_path_context(dim_pairs) as (temp_path, pass_names):
            checker_func = self.get_checker_function(temp_path)
            yield FeasibilityChecker(checker_func, pass_names)


class FeasibilityChecker:
    def __init__(self, checker_func, pass_names):
        self.checker = checker_func
        self.dim_gen_pass_names = pass_names

    def __call__(self, constraints):
        return self.checker(constraints)


# Helper function to replace standalone make_dyn_dim_cstr_from_tensor_metas
def create_constraints_from_metas(metas):
    named_inputs = [
        (tm.shape, tm.name) 
        for tm in metas
    ]
    return DynamicDimConstraints.make_by_named_inputs(named_shapes=named_inputs)

# Spotify API client wrapper with token management and command-line interface

import json
import urllib.request
import urllib.parse
import base64
import sys
import os
from pathlib import Path
from datetime import datetime

# Configuration constants
CLIENT_ID = os.environ.get("SPOTIFY_CLIENT_ID", "")
CLIENT_SECRET = os.environ.get("SPOTIFY_SPOTIFY_CLIENT_SECRET", "")
TOKEN_FILE = Path.home() / ".config" / "spotify-clawd" / "token.json"

def load_token():
    """Load stored authentication token or exit if not found."""
    if not TOKEN_FILE.exists():
        print("Error: Not authenticated. Run spotify-auth.py first.")
        sys.exit(1)
    return json.loads(TOKEN_FILE.read_text())

def save_token(token_data):
    """Save token data to the configuration file."""
    TOKEN_FILE.write_text(json.dumps(token_data, indent=2))

def refresh_access_token(current_token):
    """Refresh expired access token using refresh token."""
    # Encode credentials for Basic Auth
    auth_bytes = f"{CLIENT_ID}:{CLIENT_SECRET}".encode()
    auth_header_value = base64.b64encode(auth_bytes).decode()

    # Prepare request body
    post_data = urllib.parse.urlencode({
        "grant_type": "refresh_token",
        "refresh_token": current_token["refresh_token"],
    }).encode()

    # Build request
    request = urllib.request.Request(
        "https://accounts.spotify.com/api/token",
        data=post_data,
        headers={
            "Authorization": f"Basic {auth_header_value}",
            "Content-Type": "application/x-www-form-urlencoded",
        }
    )

    # Execute request and process response
    with urllib.request.urlopen(request) as response:
        updated_data = json.load(response)

    # Preserve original refresh token if missing in new response
    if "refresh_token" not in updated_data:
        updated_data["refresh_token"] = current_token["refresh_token"]

    # Save updated token and return it
    save_token(updated_data)
    return updated_data

def make_spotify_request(path, token_info, query_params=None):
    """Make authenticated request to Spotify API endpoint."""
    # Construct full URL
    full_url = f"https://api.spotify.com/v1{path}"
    if query_params:
        full_url += "?" + urllib.parse.urlencode(query_params)

    # Create request with authorization header
    request = urllib.request.Request(
        full_url,
        headers={"Authorization": f"Bearer {token_info['access_token']}"}
    )

    try:
        # Attempt initial request
        with urllib.request.urlopen(request) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        # Handle unauthorized (401) by refreshing token and retrying
        if error.code == 401:
            token_info = refresh_access_token(token_info)

            # Retry with new token
            request = urllib.request.Request(
                full_url,
                headers={"Authorization": f"Bearer {token_info['access_token']}"}
            )
            with urllib.request.urlopen(request) as response:
                return json.load(response)
        raise

def fetch_recent_tracks(token_info, count=20):
    """Get recently played tracks."""
    return make_spotify_request("/me/player/recently-played", token_info, {"limit": count})

def fetch_top_artists(token_info, period="medium_term", count=20):
    """Get user's top artists."""
    return make_spotify_request("/me/top/artists", token_info, {
        "time_range": period,
        "limit": count
    })

def fetch_top_songs(token_info, period="medium_term", count=20):
    """Get user's top tracks."""
    return make_spotify_request("/me/top/tracks", token_info, {
        "time_range": period,
        "limit": count
    })

def get_song_recommendations(token_info, artist_ids=None, track_ids=None, genre_list=None, count=20):
    """Generate song recommendations based on seeds."""
    params = {"limit": count}

    if artist_ids:
        params["seed_artists"] = ",".join(artist_ids[:5])
    if track_ids:
        params["seed_tracks"] = ",".join(track_ids[:5])
    if genre_list:
        params["seed_genres"] = ",".join(genre_list[:5])

    return make_spotify_request("/recommendations", token_info, params)

def main():
    """Main entry point for CLI commands."""
    if len(sys.argv) < 2:
        print("Usage: spotify-api.py <command>")
        print("Commands: recent, top-artists, top-tracks, recommend")
        return 1

    command = sys.argv[1]
    auth_token = load_token()

    if command == "recent":
        result = fetch_recent_tracks(auth_token)
        print("Recently Played:")
        for item in result["items"]:
            track = item["track"]
            timestamp = item["played_at"]
            artist_names = ", ".join(artist["name"] for artist in track["artists"])
            print(f"  {track['name']} - {artist_names} ({timestamp[:10]})")

    elif command == "top-artists":
        time_period = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        result = fetch_top_artists(auth_token, time_period)
        print(f"Top Artists ({time_period}):")
        for idx, artist in enumerate(result["items"], 1):
            genre_str = ", ".join(artist["genres"][:3]) if artist["genres"] else "N/A"
            print(f"  {idx}. {artist['name']} [{genre_str}]")

    elif command == "top-tracks":
        time_period = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        result = fetch_top_songs(auth_token, time_period)
        print(f"Top Tracks ({time_period}):")
        for idx, song in enumerate(result["items"], 1):
            artist_names = ", ".join(artist["name"] for artist in song["artists"])
            print(f"  {idx}. {song['name']} - {artist_names}")

    elif command == "recommend":
        # Use top 3 artists as seed
        top_artists = fetch_top_artists(auth_token, count=5)
        seed_artist_ids = [artist["id"] for artist in top_artists["items"][:3]]

        recommendations = get_song_recommendations(auth_token, artist_ids=seed_artist_ids)
        print("Recommendations based on your top artists:")
        for track in recommendations["tracks"]:
            artist_names = ", ".join(artist["name"] for artist in track["artists"])
            print(f"  {track['name']} - {artist_names}")

    elif command == "json":
        # Output raw JSON for any endpoint
        endpoint_path = sys.argv[2] if len(sys.argv) > 2 else "/me"
        result = make_spotify_request(endpoint_path, auth_token)
        print(json.dumps(result, indent=2))

    else:
        print(f"Unknown command: {command}")
        return 1

    return 0

if __name__ == "__main__":
    sys.exit(main())

import math
import struct
from collections import Counter
import numpy as np

class EntropyAnalyzer:
    """Analyzes entropy patterns to distinguish code from data."""

    def __init__(self):
        # Adjusted thresholds for different data types
        self.code_entropy_range = (5.0, 7.0)  # Typical for source code
        self.random_data_entropy = (7.5, 8.0)  # Near maximum entropy
        self.weight_data_entropy = (6.5, 7.8)  # ML weight distributions
        self.text_entropy_range = (4.0, 6.0)  # Natural language text

    def calculate_shannon_entropy(self, data: bytes) -> float:
        """Calculate Shannon entropy of byte sequence."""
        if not data:
            return 0.0

        byte_counts = Counter(data)
        total_bytes = len(data)

        entropy = 0.0
        for count in byte_counts.values():
            if count > 0:
                probability = count / total_bytes
                entropy -= probability * math.log2(probability)

        return entropy

    def calculate_sliding_window_entropy(self, data: bytes, window_size: int = 256) -> list[float]:
        """Calculate entropy using sliding window approach."""
        if len(data) < window_size:
            return [self.calculate_shannon_entropy(data)]

        entropies = []
        step_size = window_size // 2

        for i in range(0, len(data) - window_size + 1, step_size):
            window = data[i : i + window_size]
            entropies.append(self.calculate_shannon_entropy(window))

        return entropies

    def analyze_float_patterns(self, data: bytes) -> dict[str, float]:
        """Analyze patterns specific to floating-point data."""
        if len(data) < 4:
            return {"float_ratio": 0.0, "float_entropy": 0.0}

        float_values = []
        valid_floats = 0

        for i in range(0, len(data) - 3, 4):
            try:
                value = struct.unpack("<f", data[i : i + 4])[0]
                if -1e10 < value < 1e10 and not math.isnan(value) and not math.isinf(value):
                    float_values.append(value)
                    valid_floats += 1
            except (struct.error, ValueError):
                pass

        float_ratio = valid_floats / (len(data) // 4) if len(data) >= 4 else 0.0

        float_entropy = 0.0
        if float_values:
            bins = np.histogram(float_values, bins=50)[0]
            total = sum(bins)
            if total > 0:
                for count in bins:
                    if count > 0:
                        p = count / total
                        float_entropy -= p * math.log2(p)

        weight_indicators = 0
        if float_values:
            values_array = np.array(float_values)
            mean = np.mean(values_array)
            std = np.std(values_array)

            if -0.1 < mean < 0.1:
                weight_indicators += 1
            if 0.01 < std < 2.0:
                weight_indicators += 1
            if np.percentile(values_array, 95) < 3.0:
                weight_indicators += 1

        return {
            "float_ratio": float_ratio,
            "float_entropy": float_entropy,
            "weight_probability": weight_indicators / 3.0,
            "valid_float_count": valid_floats,
        }

    def detect_code_patterns(self, data: bytes) -> dict[str, float]:
        """Detect patterns indicative of code vs data."""
        if not data:
            return {"code_probability": 0.0}

        entropy = self.calculate_shannon_entropy(data)
        code_indicators = 0
        total_checks = 0

        printable_count = sum(1 for b in data if 32 <= b < 127)
        printable_ratio = printable_count / len(data)
        if 0.7 < printable_ratio < 0.95:
            code_indicators += 1
        total_checks += 1

        newline_count = data.count(b"\n") + data.count(b"\r\n")
        newline_ratio = newline_count / len(data)
        if 0.01 < newline_ratio < 0.1:
            code_indicators += 1
        total_checks += 1

        null_ratio = data.count(b"\x00") / len(data)
        if null_ratio < 0.01:
            code_indicators += 1
        total_checks += 1

        code_patterns = [
            b"def ", b"class ", b"import ", b"from ",
            b"if ", b"else:", b"for ", b"while ",
            b"return ", b"print(", b"self."
        ]
        pattern_matches = sum(1 for pattern in code_patterns if pattern in data)
        if pattern_matches >= 3:
            code_indicators += 1
        total_checks += 1

        if self.code_entropy_range[0] <= entropy <= self.code_entropy_range[1]:
            code_indicators += 1
        total_checks += 1

        binary_indicators = 0
        if entropy > 7.5:
            binary_indicators += 1
        if null_ratio > 0.1:
            binary_indicators += 1
        if printable_ratio < 0.3:
            binary_indicators += 1

        code_probability = code_indicators / total_checks
        binary_probability = binary_indicators / 3.0

        if binary_probability > 0.5:
            code_probability *= 1.0 - binary_probability

        return {
            "code_probability": code_probability,
            "binary_probability": binary_probability,
            "entropy": entropy,
            "printable_ratio": printable_ratio,
            "pattern_matches": pattern_matches,
        }

    def classify_data_type(self, data: bytes) -> tuple[str, float]:
        """Classify data type with confidence score."""
        if len(data) < 16:
            return "unknown", 0.0

        entropy_info = self.detect_code_patterns(data)
        float_info = self.analyze_float_patterns(data)
        classifications = []

        if float_info["float_ratio"] > 0.8 and float_info["weight_probability"] > 0.6:
            classifications.append(("ml_weights", 0.9 * float_info["weight_probability"]))

        if entropy_info["code_probability"] > 0.6:
            classifications.append(("code", entropy_info["code_probability"]))

        if entropy_info["binary_probability"] > 0.7:
            classifications.append(("binary_data", entropy_info["binary_probability"]))

        if entropy_info["entropy"] > 7.5:
            classifications.append(("random_data", 0.8))

        if classifications:
            return max(classifications, key=lambda x: x[1])
        return "unknown", 0.0

    def should_skip_pattern_search(self, data: bytes, pattern: bytes) -> bool:
        """Determine if pattern search should be skipped based on data type."""
        data_type, confidence = self.classify_data_type(data)

        if data_type == "ml_weights" and confidence > 0.8:
            extremely_suspicious = [b"exec", b"eval", b"__import__"]
            return pattern not in extremely_suspicious

        if data_type == "random_data" and confidence > 0.7:
            return True

        if data_type == "binary_data" and confidence > 0.7:
            detection_result = self.detect_code_patterns(data)
            printable_ratio = detection_result.get("printable_ratio", 0.0)
            return printable_ratio < 0.3

        return False

# Dynamically load provider clients based on protocol type

from __future__ import annotations
import importlib
from typing import Optional, TYPE_CHECKING, Type, cast
from ripperdoc.core.config import ProtocolType
from ripperdoc.core.providers.base import ProviderClient
from ripperdoc.utils.log import get_logger

if TYPE_CHECKING:  # pragma: no cover - type checking only
    from ripperdoc.core.providers.anthropic import AnthropicClient  # noqa: F401
    from ripperdoc.core.providers.gemini import GeminiClient  # noqa: F401
    from ripperdoc.core.providers.openai import OpenAIClient  # noqa: F401

logger = get_logger()


def _instantiate_provider(module_name: str, class_name: str, required_extra: str) -> Type[ProviderClient]:
    """Dynamically import and return a provider client class, guiding users to install required dependencies."""
    try:
        module = importlib.import_module(f"ripperdoc.core.providers.{module_name}")
        provider_class = cast(Type[ProviderClient], getattr(module, class_name, None))
        if provider_class is None:
            raise ImportError(f"{class_name} not found in {module_name}")
        return provider_class
    except ImportError as error:
        raise RuntimeError(
            f"{class_name} requires optional dependency group '{required_extra}'. "
            f"Install with `pip install ripperdoc[{required_extra}]`."
        ) from error


def fetch_client_for_protocol(protocol: ProtocolType) -> Optional[ProviderClient]:
    """Instantiate and return the appropriate provider client for the specified protocol."""
    if protocol == ProtocolType.ANTHROPIC:
        return _instantiate_provider("anthropic", "AnthropicClient", "anthropic")()
    if protocol == ProtocolType.OPENAI_COMPATIBLE:
        return _instantiate_provider("openai", "OpenAIClient", "openai")()
    if protocol == ProtocolType.GEMINI:
        return _instantiate_provider("gemini", "GeminiClient", "gemini")()
    if protocol == ProtocolType.OAUTH:
        return _instantiate_provider("openai", "OpenAIClient", "openai")()

    logger.warning("[providers] Unsupported protocol", extra={"protocol": protocol})
    return None


__all__ = ["ProviderClient", "fetch_client_for_protocol"]

import importlib.util
import paddle
from pathlib import Path
import sys
import os
import numpy as np
import random
import platform
import traceback
import subprocess
import re
from graph_net.paddle import utils
from graph_net_bench import path_utils
from graph_net_bench import test_compiler_util
from graph_net import model_path_util
from graph_net.paddle.backend.graph_compiler_backend import GraphCompilerBackend
from graph_net.paddle.backend.cinn_backend import CinnBackend
from graph_net.paddle.backend.nope_backend import NopeBackend

# Registry mapping compiler names to backend instances
backend_registry = {
    "cinn": CinnBackend(),
    "nope": NopeBackend(),
}

def fetch_backend_instance(config):
    if config.compiler not in backend_registry:
        raise ValueError(f"Unsupported compiler: {config.compiler}")
    return backend_registry[config.compiler]

def seed_all(random_seed):
    paddle.seed(random_seed)
    random.seed(random_seed)
    np.random.seed(random_seed)

def configure_environment(config):
    if test_compiler_util.is_gpu_device(config.device):
        paddle.set_flags({"FLAGS_cudnn_exhaustive_search": 1})

def retrieve_hardware_info(config):
    device_name = "unknown"
    if test_compiler_util.is_gpu_device(config.device):
        try:
            device_name = paddle.device.cuda.get_device_name(0)
        except Exception:
            pass
    elif config.device == "xpu":
        try:
            raw_output = subprocess.check_output(["xpu-smi", "-L"], text=True)
            for line in raw_output.splitlines():
                match = re.match(r"XPU\s+(\d+):\s+(.+?)\s+\(UUID:\s*([^)]+)\)", line)
                if match:
                    device_name = match.group(2)
                    break
        except Exception:
            pass
    elif config.device == "cpu":
        device_name = platform.processor()
    return device_name

def get_framework_version(config):
    if config.compiler in ["cinn", "nope"]:
        return paddle.__version__
    return "unknown"

def load_model_class_from_file(filepath: str, target_class: str):
    resolved_path = Path(filepath).resolve()
    module_id = resolved_path.stem
    with open(filepath, "r", encoding="utf-8") as f:
        source_code = f.read()
    prepend_import = "import paddle"
    modified_source = f"{prepend_import}\n{source_code}"
    spec = importlib.util.spec_from_loader(module_id, loader=None)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[module_id] = mod
    bytecode = compile(modified_source, filename=str(resolved_path), mode="exec")
    exec(bytecode, mod.__dict__)
    cls = getattr(mod, target_class, None)
    return cls

def instantiate_model(model_dir):
    cls = load_model_class_from_file(
        f"{model_dir}/model.py", class_name="GraphModule"
    )
    return cls()

def prepare_input_state_dict(model_dir):
    data = utils.load_converted_from_text(f"{model_dir}")
    weight_params = data["weight_info"]
    input_params = data["input_info"]
    combined = {**weight_params, **input_params}
    state_dict = {k: utils.replay_tensor(v) for k, v in combined.items()}
    return state_dict

def build_input_specification(model_dir):
    info_list = utils.load_converted_list_from_text(f"{model_dir}")
    specs = [None] * len(info_list)
    for idx, item in enumerate(info_list):
        dtype_str = item["info"]["dtype"]
        shape = item["info"]["shape"]
        specs[idx] = paddle.static.InputSpec(shape, dtype_str)
    return specs

def convert_to_static_graph(config, model):
    static_graph = paddle.jit.to_static(
        model,
        input_spec=build_input_specification(config.model_path),
        full_graph=True,
        backend=None,
    )
    static_graph.eval()
    _ = static_graph.forward.concrete_program.main_program  # noqa
    return static_graph

def benchmark_execution(model_fn, config, backend, enable_profiling=False):
    runtime_seed = 1024
    metrics = {}
    paddle.seed(runtime_seed)
    initial_outputs = model_fn()

    # Warm-up phase
    warmup_durations = []
    for _ in range(config.warmup):
        timer = test_compiler_util.DurationBox(-1)
        with test_compiler_util.naive_timer(timer, backend.synchronize):
            model_fn()
        warmup_durations.append(timer.value)
    backend.synchronize()

    # Determine minimum required trials based on warm-up average
    avg_warmup = np.mean(warmup_durations[1:]) if len(warmup_durations) > 1 else 0.1
    min_required_trials = int(100 / avg_warmup) if avg_warmup > 0 else 1
    trial_count = max(config.trials, min_required_trials)

    hw_identifier = retrieve_hardware_info(config)
    print(
        f"[Profiling] Using device: {config.device} {hw_identifier}, warmup={config.warmup}, trials={trial_count}",
        file=sys.stderr,
        flush=True,
    )

    if enable_profiling:
        import paddle.profiler as profiler
        prof = profiler.Profiler()
        prof.start()

    if test_compiler_util.is_gpu_device(config.device):
        e2e_timings = []
        gpu_timings = []
        for i in range(trial_count):
            # End-to-end timing
            timer = test_compiler_util.DurationBox(-1)
            with test_compiler_util.naive_timer(timer, backend.synchronize):
                # GPU-only timing using CUDA events
                start_ev = paddle.device.Event(enable_timing=True)
                end_ev = paddle.device.Event(enable_timing=True)
                start_ev.record()
                model_fn()
                end_ev.record()
            if enable_profiling:
                prof.step()
            gpu_ms = start_ev.elapsed_time(end_ev)
            e2e_timings.append(timer.value)
            gpu_timings.append(gpu_ms)
            print(
                f"Trial {i + 1}: e2e={timer.value:.5f} ms, gpu={gpu_ms:.5f} ms",
                file=sys.stderr,
                flush=True,
            )
        metrics["e2e"] = test_compiler_util.get_timing_stats(e2e_timings)
        metrics["gpu"] = test_compiler_util.get_timing_stats(gpu_timings)
    else:
        e2e_timings = []
        for i in range(trial_count):
            timer = test_compiler_util.DurationBox(-1)
            with test_compiler_util.naive_timer(timer, backend.synchronize):
                model_fn()
            if enable_profiling:
                prof.step()
            e2e_timings.append(timer.value)
            print(
                f"Trial {i + 1}: e2e={timer.value:.4f} ms",
                file=sys.stderr,
                flush=True,
            )
        metrics["e2e"] = test_compiler_util.get_timing_stats(e2e_timings)

    if enable_profiling:
        prof.stop()
        prof.summary()
    return initial_outputs, metrics

def validate_outputs(config, reference_out, compiled_out):
    def flatten_to_list(output):
        result = output
        if isinstance(output, paddle.Tensor):
            result = [output]
        else:
            flat = []
            for item in (output if isinstance(output, (tuple, list)) else [output]):
                if isinstance(item, (tuple, list)):
                    flat.extend(item)
                else:
                    flat.append(item)
            result = flat
        return result

    ref_flat = flatten_to_list(reference_out)
    comp_flat = flatten_to_list(compiled_out)

    def extract_dtypes(outs):
        return [
            str(t.dtype).replace("paddle.", "")
            if isinstance(t, paddle.Tensor)
            else None
            for t in outs
        ]

    ref_dtypes = extract_dtypes(ref_flat)
    comp_dtypes = extract_dtypes(comp_flat)
    dtypes_ok = test_compiler_util.check_output_datatype(config, ref_dtypes, comp_dtypes)

    def extract_shapes(outs):
        return [
            t.shape if isinstance(t, paddle.Tensor) else None
            for t in outs
        ]

    ref_shapes = extract_shapes(ref_flat)
    comp_shapes = extract_shapes(comp_flat)
    shapes_ok = test_compiler_util.check_output_shape(config, ref_shapes, comp_shapes)

    def cast_to_float32_if_needed(tensor_list):
        converted = []
        for t in tensor_list:
            if isinstance(t, paddle.Tensor) and t.dtype not in [paddle.float32, paddle.float64]:
                t = t.astype("float32")
            converted.append(t)
        return converted

    if dtypes_ok and shapes_ok:
        test_compiler_util.check_equal(
            config,
            ref_flat,
            comp_flat,
            cmp_equal_func=compare_tensors_equal,
        )
        ref_fp32 = cast_to_float32_if_needed(ref_flat)
        comp_fp32 = cast_to_float32_if_needed(comp_flat)
        test_compiler_util.check_allclose(
            config,
            ref_fp32,
            comp_fp32,
            cmp_all_close_func=compare_allclose,
            cmp_max_diff_func=compute_max_diff,
            cmp_mean_diff_func=compute_mean_diff,
            cmp_max_relative_diff_func=compute_max_relative_diff,
            cmp_mean_relative_diff_func=compute_mean_relative_diff,
        )

def report_gpu_utilization(backend):
    if paddle.device.is_compiled_with_cuda():
        dev_id = int(paddle.device.get_device().split(":")[-1])
        dev_count = paddle.device.cuda.device_count()
        gpu_pct, mem_pct = test_compiler_util.get_device_utilization(
            dev_id, dev_count, backend.synchronize
        )
        if gpu_pct is not None and mem_pct is not None:
            print(
                f"Device status: gpu_id {dev_id}, gpu_util {gpu_pct:.2f}%, mem_util {mem_pct:.2f}%",
                file=sys.stderr,
                flush=True,
            )

def run_single_test(config):
    model_dir = os.path.normpath(config.model_path)
    test_compiler_util.print_with_log_prompt(
        "[Processing]", model_dir, config.log_prompt
    )
    backend = fetch_backend_instance(config)
    report_gpu_utilization(backend)
    input_dict = prepare_input_state_dict(model_dir)
    model = instantiate_model(model_dir)
    model.eval()
    test_compiler_util.print_basic_config(
        config,
        retrieve_hardware_info(config),
        get_framework_version(config)
    )

    eager_success = False
    eager_stats = {}
    try:
        print("Run model in eager mode.", file=sys.stderr, flush=True)
        static_model = convert_to_static_graph(config, model)
        expected_result, eager_stats = benchmark_execution(
            lambda: static_model(**input_dict), config, backend, profile=False
        )
        eager_success = True
    except Exception as e:
        print(
            f"Run model in eager mode failed: {str(e)}\n{traceback.format_exc()}",
            file=sys.stderr,
            flush=True,
        )

    compiled_success = False
    compiled_stats = {}
    try:
        print("Run model in compiled mode.", file=sys.stderr, flush=True)
        input_specs = build_input_specification(config.model_path)
        compiled_model = backend(model, input_specs)
        compiled_result, compiled_stats = benchmark_execution(
            lambda: compiled_model(**input_dict), config, backend, profile=False
        )
        compiled_success = True
    except Exception as e:
        print(
            f"Run model in compiled mode failed: {str(e)}\n{traceback.format_exc()}",
            file=sys.stderr,
            flush=True,
        )

    test_compiler_util.print_running_status(config, eager_success, compiled_success)
    if eager_success and compiled_success:
        validate_outputs(config, expected_result, compiled_result)
    test_compiler_util.print_times_and_speedup(
        config, eager_stats, compiled_stats
    )

def compare_tensors_equal(ref, comp):
    def normalize_dtype(x):
        if x.dtype in [paddle.float16, paddle.bfloat16]:
            return x.astype("float32")
        elif x.dtype in [paddle.uint8, paddle.int8, paddle.int16]:
            return x.astype("int32")
        return x
    return " ".join(
        str(int(paddle.equal_all(normalize_dtype(a), normalize_dtype(b))))
        for a, b in zip(ref, comp)
    )

def compare_allclose(ref, comp, atol, rtol):
    return " ".join(
        str(int(paddle.allclose(a, b, atol=atol, rtol=rtol)))
        for a, b in zip(comp, ref)
    )

def format_number(val):
    if abs(val) > 1e5 or abs(val) < 1e-5 and val != 0.0:
        return f"{val:.5E}"
    else:
        return f"{val:.5f}"

def compute_max_diff(ref, comp):
    return " ".join(
        format_number(paddle.max(paddle.abs(a - b)).item())
        for a, b in zip(ref, comp)
    )

def compute_mean_diff(ref, comp):
    return " ".join(
        format_number(paddle.mean(paddle.abs(a - b)).item())
        for a, b in zip(ref, comp)
    )

def compute_max_relative_diff(ref, comp):
    eps = 1e-8
    return " ".join(
        format_number(paddle.max(paddle.abs(a - b) / (paddle.abs(a) + eps)).item())
        for a, b in zip(ref, comp)
    )

def compute_mean_relative_diff(ref, comp):
    eps = 1e-8
    return " ".join(
        format_number(
            paddle.mean(paddle.abs(a - b) / (paddle.abs(a) + eps)).item()
        )
        for a, b in zip(ref, comp)
    )

def run_batch_tests(config):
    allowed_samples = model_path_util.get_allow_samples(config.allow_list)
    total_count = 0
    failures = []
    script_module = os.path.splitext(os.path.basename(__file__))[0]
    for model_dir in path_utils.get_recursively_model_path(config.model_path):
        if allowed_samples is None or os.path.abspath(model_dir) in allowed_samples:
            print(
                f"[{total_count}] {script_module}, model_path: {model_dir}",
                file=sys.stderr,
                flush=True,
            )
            cmd_parts = [
                sys.executable,
                f"-m graph_net.paddle.{script_module}",
                f"--model-path {model_dir}",
                f"--compiler {config.compiler}",
                f"--device {config.device}",
                f"--warmup {config.warmup}",
                f"--trials {config.trials}",
                f"--log-prompt {config.log_prompt}",
            ]
            exit_code = os.system(" ".join(cmd_parts))
            if exit_code != 0:
                failures.append(model_dir)
            total_count += 1
    print(
        f"Totally {total_count} verified samples, failed {len(failures)} samples.",
        file=sys.stderr,
        flush=True,
    )
    for path in failures:
        print(f"- {path}", file=sys.stderr, flush=True)

def main(config):
    assert os.path.isdir(config.model_path)
    assert config.compiler in {"cinn", "nope"}
    assert config.device in ["cuda", "dcu", "xpu", "cpu"]
    init_seed = 123
    seed_all(init_seed)
    if path_utils.is_single_model_dir(config.model_path):
        run_single_test(config)
    else:
        run_batch_tests(config)

