import re
from datetime import datetime, timedelta
from dateutil import parser as dateutil_parser
from dateutil.relativedelta import relativedelta

# Common prefixes used by financial institutions in transaction descriptions
BANK_PREFIXES = [
    r"^POS\s+(DEBIT\s+)?",
    r"^DEBIT\s+(CARD\s+)?(PURCHASE\s+)?",
    r"^ACH\s+(DEBIT\s+|CREDIT\s+)?",
    r"^CHECKCARD\s+\d+\s+",
    r"^PURCHASE\s+(AUTHORIZED\s+ON\s+)?",
    r"^RECURRING\s+(DEBIT\s+|PAYMENT\s+)?",
    r"^VISA\s+DDA\s+",
    r"^PENDING\s+",
    r"^ELECTRONIC\s+",
    r"^ONLINE\s+(BANKING\s+)?(PAYMENT\s+|TRANSFER\s+)?",
    r"^WIRE\s+(TRANSFER\s+)?",
    r"^BILL\s+PAY(MENT)?\s+",
    r"^AUTOPAY\s+",
    r"^MOBILE\s+(PURCHASE\s+)?",
    r"^SQ\s+\*",
    r"^TST\s+\*",
    r"^SP\s+\*?\s*",
]

# Suffixes commonly found at the end of transaction descriptions (dates, IDs, etc.)
TRANSACTION_SUFFIXES = [
    r"\s+\d{2}/\d{2}$",
    r"\s+\d{2}/\d{2}/\d{2,4}$",
    r"\s+\d{4,}$",
    r"\s+#\d+$",
    r"\s+REF\s*#?\s*\d+$",
    r"\s+CARD\s+\d+$",
    r"\s+X{2,}\d{4}$",
    r"\s+\d{2}:\d{2}:\d{2}$",
    r"\s+[A-Z]{2}\s+\d{5}(-\d{4})?$",  # state + zip
]

def normalize_merchant_name(description):
    if not description:
        return ""

    # Clean and standardize input
    merchant = description.strip().upper()

    # Remove known prefixes
    for pattern in BANK_PREFIXES:
        merchant = re.sub(pattern, "", merchant, flags=re.IGNORECASE).strip()

    # Remove known suffixes
    for pattern in TRANSACTION_SUFFIXES:
        merchant = re.sub(pattern, "", merchant, flags=re.IGNORECASE).strip()

    # Normalize whitespace
    merchant = re.sub(r"\s+", " ", merchant)

    # Convert to title case for readability
    return merchant.title()

def convert_date(date_input):
    if not date_input:
        return None

    date_str = str(date_input).strip()

    # List of common date formats used by banks
    date_formats = [
        "%m/%d/%Y",
        "%m/%d/%y",
        "%Y-%m-%d",
        "%m-%d-%Y",
        "%m-%d-%y",
        "%d/%m/%Y",
        "%Y%m%d",
        "%m/%d/%Y %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S",
    ]

    # Try parsing with known formats first
    for fmt in date_formats:
        try:
            parsed = datetime.strptime(date_str, fmt)
            return parsed.strftime("%Y-%m-%d")
        except ValueError:
            continue

    # Fallback to flexible date parsing
    try:
        parsed = dateutil_parser.parse(date_str)
        return parsed.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def interpret_amount(value):
    if value is None:
        return None

    if isinstance(value, (int, float)):
        return round(float(value), 2)

    text = str(value).strip()
    text = text.replace("$", "").replace(",", "").strip()

    # Handle accounting notation for negatives: (100) -> -100
    if text.startswith("(") and text.endswith(")"):
        text = "-" + text[1:-1]

    try:
        return round(float(text), 2)
    except ValueError:
        return None

def display_currency(amount):
    if amount is None:
        return "$0.00"

    abs_val = abs(amount)
    formatted = f"${abs_val:,.2f}"

    if amount < 0:
        return "-" + formatted
    return formatted

def interpret_time_period(query):
    """Convert natural language time references into (start_date, end_date) tuples."""
    current_date = datetime.now()
    query = query.lower().strip()

    # This month
    if query in ("this month", "current month"):
        start = current_date.replace(day=1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Last month
    if query in ("last month", "previous month"):
        end = current_date.replace(day=1) - timedelta(days=1)
        start = end.replace(day=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Year-to-date or this year
    if query in ("this year", "current year", "ytd"):
        start = current_date.replace(month=1, day=1)
        return start.strftime("%Y-%m-%d"), current_date.strftime("%Y-%m-%d")

    # Last year
    if query in ("last year", "previous year"):
        start = current_date.replace(year=current_date.year - 1, month=1, day=1)
        end = current_date.replace(year=current_date.year - 1, month=12, day=31)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # This week
    if query in ("this week", "current week"):
        days_since_monday = current_date.weekday()
        start = current_date - timedelta(days=days_since_monday)
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Last week
    if query in ("last week", "previous week"):
        days_since_last_monday = current_date.weekday() + 7
        start = current_date - timedelta(days=days_since_last_monday)
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Today / Yesterday
    if query == "today":
        d = current_date.strftime("%Y-%m-%d")
        return d, d
    if query == "yesterday":
        d = (current_date - timedelta(days=1)).strftime("%Y-%m-%d")
        return d, d

    # Generic "last N [unit]" expressions
    match = re.match(r"last\s+(\d+)\s+(day|week|month|year)s?", query)
    if match:
        count = int(match.group(1))
        unit = match.group(2)

        if unit == "day":
            start = current_date - timedelta(days=count)
        elif unit == "week":
            start = current_date - timedelta(weeks=count)
        elif unit == "month":
            start = current_date - relativedelta(months=count)
        elif unit == "year":
            start = current_date - relativedelta(years=count)

        return start.strftime("%Y-%m-%d"), current_date.strftime("%Y-%m-%d")

    # Month name parsing (e.g., "january", "february 2024")
    month_map = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "jun": 6, "jul": 7, "aug": 8, "sep": 9, "sept": 9,
        "oct": 10, "nov": 11, "dec": 12,
    }

    match = re.match(
        r"(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)(?:\s+(\d{4}))?",
        query
    )
    if match:
        month_num = month_map[match.group(1)]
        year = int(match.group(2)) if match.group(2) else current_date.year

        start = datetime(year, month_num, 1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Explicit date range format: "2024-01-01 to 2024-01-31"
    match = re.match(r"(\d{4}-\d{2}-\d{2})\s+to\s+(\d{4}-\d{2}-\d{2})", query)
    if match:
        return match.group(1), match.group(2)

    return None, None

# Multi-framework testing support module.
# Supports various test frameworks including Jest, Pytest, JUnit, Vitest, and others.
# Manages framework-specific syntax, imports, and test organization.

from typing import Dict, List, Any, Optional
from enum import Enum

class TestFramework(Enum):
    """Available testing frameworks."""
    JEST = "jest"
    VITEST = "vitest"
    PYTEST = "pytest"
    UNITTEST = "unittest"
    JUNIT = "junit"
    TESTNG = "testng"
    MOCHA = "mocha"
    JASMINE = "jasmine"

class ProgrammingLanguage(Enum):
    """Supported programming languages."""
    TYPESCRIPT = "typescript"
    JAVASCRIPT = "javascript"
    PYTHON = "python"
    JAVA = "java"

class FrameworkHandler:
    """Handler for different testing frameworks."""
    def __init__(self, framework: TestFramework, language: ProgrammingLanguage):
        """
        Initialize the framework handler.
        Args:
            framework: Testing framework to use
            language: Programming language being used
        """
        self.framework = framework
        self.language = language

    def fetch_imports(self) -> str:
        """Retrieve framework-specific import statements."""
        if self.framework == TestFramework.JEST:
            return self._jest_imports()
        elif self.framework == TestFramework.VITEST:
            return self._vitest_imports()
        elif self.framework == TestFramework.PYTEST:
            return self._pytest_imports()
        elif self.framework == TestFramework.UNITTEST:
            return self._unittest_imports()
        elif self.framework == TestFramework.JUNIT:
            return self._junit_imports()
        elif self.framework == TestFramework.TESTNG:
            return self._testng_imports()
        elif self.framework == TestFramework.MOCHA:
            return self._mocha_imports()
        else:
            return ""

    def _jest_imports(self) -> str:
        """Return Jest-specific imports."""
        return """import { describe, it, expect, beforeEach, afterEach } from '@jest/globals';"""

    def _vitest_imports(self) -> str:
        """Return Vitest-specific imports."""
        return """import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';"""

    def _pytest_imports(self) -> str:
        """Return Pytest-specific imports."""
        return """import pytest"""

    def _unittest_imports(self) -> str:
        """Return unittest-specific imports."""
        return """import unittest"""

    def _junit_imports(self) -> str:
        """Return JUnit-specific imports."""
        return """import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.AfterEach;
import static org.junit.jupiter.api.Assertions.*;"""

    def _testng_imports(self) -> str:
        """Return TestNG-specific imports."""
        return """import org.testng.annotations.Test;
import org.testng.annotations.BeforeMethod;
import org.testng.annotations.AfterMethod;
import static org.testng.Assert.*;"""

    def _mocha_imports(self) -> str:
        """Return Mocha-specific imports."""
        return """import { describe, it, beforeEach, afterEach } from 'mocha';
import { expect } from 'chai';"""

    def wrap_test_suite(
        self,
        suite_name: str,
        test_content: str
    ) -> str:
        """
        Encapsulate test content within framework-specific structure.
        Args:
            suite_name: Name of the test suite
            test_content: Content of the tests
        Returns:
            Complete test suite code
        """
        if self.framework in [TestFramework.JEST, TestFramework.VITEST, TestFramework.MOCHA]:
            return f"""describe('{suite_name}', () => {{
{self._apply_indent(test_content, 2)}
}});"""
        elif self.framework == TestFramework.PYTEST:
            return f"""class Test{self._to_class_format(suite_name)}:
    \"\"\"Test suite for {suite_name}.\"\"\"
{self._apply_indent(test_content, 4)}"""
        elif self.framework == TestFramework.UNITTEST:
            return f"""class Test{self._to_class_format(suite_name)}(unittest.TestCase):
    \"\"\"Test suite for {suite_name}.\"\"\"
{self._apply_indent(test_content, 4)}"""
        elif self.framework in [TestFramework.JUNIT, TestFramework.TESTNG]:
            return f"""public class {self._to_class_format(suite_name)}Test {{
{self._apply_indent(test_content, 4)}
}}"""
        return test_content

    def create_test_function(
        self,
        test_name: str,
        test_body: str,
        description: str = ""
    ) -> str:
        """
        Create a test function tailored to the framework.
        Args:
            test_name: Name of the test
            test_body: Code inside the test
            description: Description of what the test does
        Returns:
            Complete test function code
        """
        if self.framework == TestFramework.JEST:
            return self._jest_test_case(test_name, test_body, description)
        elif self.framework == TestFramework.VITEST:
            return self._vitest_test_case(test_name, test_body, description)
        elif self.framework == TestFramework.PYTEST:
            return self._pytest_test_case(test_name, test_body, description)
        elif self.framework == TestFramework.UNITTEST:
            return self._unittest_test_case(test_name, test_body, description)
        elif self.framework == TestFramework.JUNIT:
            return self._junit_test_case(test_name, test_body, description)
        elif self.framework == TestFramework.TESTNG:
            return self._testng_test_case(test_name, test_body, description)
        elif self.framework == TestFramework.MOCHA:
            return self._mocha_test_case(test_name, test_body, description)
        else:
            return ""

    def _jest_test_case(self, test_name: str, test_body: str, description: str) -> str:
        """Create Jest-style test."""
        return f"""it('{test_name}', () => {{
  // {description}
{self._apply_indent(test_body, 2)}
}});"""

    def _vitest_test_case(self, test_name: str, test_body: str, description: str) -> str:
        """Create Vitest-style test."""
        return f"""it('{test_name}', () => {{
  // {description}
{self._apply_indent(test_body, 2)}
}});"""

    def _pytest_test_case(self, test_name: str, test_body: str, description: str) -> str:
        """Create Pytest-style test."""
        func_name = test_name.replace(' ', '_').replace('-', '_')
        return f"""def test_{func_name}(self):
    \"\"\"
    {description or test_name}
    \"\"\"
{self._apply_indent(test_body, 4)}"""

    def _unittest_test_case(self, test_name: str, test_body: str, description: str) -> str:
        """Create unittest-style test."""
        func_name = self._to_camel_case_format(test_name)
        return f"""def test_{func_name}(self):
    \"\"\"
    {description or test_name}
    \"\"\"
{self._apply_indent(test_body, 4)}"""

    def _junit_test_case(self, test_name: str, test_body: str, description: str) -> str:
        """Create JUnit-style test."""
        method_name = self._to_camel_case_format(test_name)
        return f"""@Test
public void test{method_name}() {{
    // {description}
{self._apply_indent(test_body, 4)}
}}"""

    def _testng_test_case(self, test_name: str, test_body: str, description: str) -> str:
        """Create TestNG-style test."""
        method_name = self._to_camel_case_format(test_name)
        return f"""@Test
public void test{method_name}() {{
    // {description}
{self._apply_indent(test_body, 4)}
}}"""

    def _mocha_test_case(self, test_name: str, test_body: str, description: str) -> str:
        """Create Mocha-style test."""
        return f"""it('{test_name}', () => {{
  // {description}
{self._apply_indent(test_body, 2)}
}});"""

    def produce_assertion(
        self,
        actual: str,
        expected: str,
        assertion_type: str = "equals"
    ) -> str:
        """
        Generate framework-specific assertion statement.
        Args:
            actual: Actual value expression
            expected: Expected value expression
            assertion_type: Type of assertion (equals, not_equals, true, false, throws)
        Returns:
            Assertion statement
        """
        if self.framework in [TestFramework.JEST, TestFramework.VITEST]:
            return self._jest_verify(actual, expected, assertion_type)
        elif self.framework in [TestFramework.PYTEST, TestFramework.UNITTEST]:
            return self._python_verify(actual, expected, assertion_type)
        elif self.framework in [TestFramework.JUNIT, TestFramework.TESTNG]:
            return self._java_verify(actual, expected, assertion_type)
        elif self.framework == TestFramework.MOCHA:
            return self._chai_verify(actual, expected, assertion_type)
        else:
            return f"assert {actual} == {expected}"

    def _jest_verify(self, actual: str, expected: str, assertion_type: str) -> str:
        """Generate Jest assertion."""
        if assertion_type == "equals":
            return f"expect({actual}).toBe({expected});"
        elif assertion_type == "not_equals":
            return f"expect({actual}).not.toBe({expected});"
        elif assertion_type == "true":
            return f"expect({actual}).toBe(true);"
        elif assertion_type == "false":
            return f"expect({actual}).toBe(false);"
        elif assertion_type == "throws":
            return f"expect(() => {actual}).toThrow();"
        else:
            return f"expect({actual}).toBe({expected});"

    def _python_verify(self, actual: str, expected: str, assertion_type: str) -> str:
        """Generate Python assertion."""
        if assertion_type == "equals":
            return f"assert {actual} == {expected}"
        elif assertion_type == "not_equals":
            return f"assert {actual} != {expected}"
        elif assertion_type == "true":
            return f"assert {actual} is True"
        elif assertion_type == "false":
            return f"assert {actual} is False"
        elif assertion_type == "throws":
            return f"with pytest.raises(Exception):\n    {actual}"
        else:
            return f"assert {actual} == {expected}"

    def _java_verify(self, actual: str, expected: str, assertion_type: str) -> str:
        """Generate Java assertion."""
        if assertion_type == "equals":
            return f"assertEquals({expected}, {actual});"
        elif assertion_type == "not_equals":
            return f"assertNotEquals({expected}, {actual});"
        elif assertion_type == "true":
            return f"assertTrue({actual});"
        elif assertion_type == "false":
            return f"assertFalse({actual});"
        elif assertion_type == "throws":
            return f"assertThrows(Exception.class, () -> {actual});"
        else:
            return f"assertEquals({expected}, {actual});"

    def _chai_verify(self, actual: str, expected: str, assertion_type: str) -> str:
        """Generate Chai assertion."""
        if assertion_type == "equals":
            return f"expect({actual}).to.equal({expected});"
        elif assertion_type == "not_equals":
            return f"expect({actual}).to.not.equal({expected});"
        elif assertion_type == "true":
            return f"expect({actual}).to.be.true;"
        elif assertion_type == "false":
            return f"expect({actual}).to.be.false;"
        elif assertion_type == "throws":
            return f"expect(() => {actual}).to.throw();"
        else:
            return f"expect({actual}).to.equal({expected});"

    def produce_lifecycle_hooks(
        self,
        setup_code: str = "",
        teardown_code: str = ""
    ) -> str:
        """Generate setup and teardown hooks based on framework."""
        result = []
        if self.framework in [TestFramework.JEST, TestFramework.VITEST, TestFramework.MOCHA]:
            if setup_code:
                result.append(f"""beforeEach(() => {{
{self._apply_indent(setup_code, 2)}
}});""")
            if teardown_code:
                result.append(f"""afterEach(() => {{
{self._apply_indent(teardown_code, 2)}
}});""")
        elif self.framework == TestFramework.PYTEST:
            if setup_code:
                result.append(f"""@pytest.fixture(autouse=True)
def setup_method(self):
{self._apply_indent(setup_code, 4)}
    yield""")
            if teardown_code:
                result.append(f"""
{self._apply_indent(teardown_code, 4)}""")
        elif self.framework == TestFramework.UNITTEST:
            if setup_code:
                result.append(f"""def setUp(self):
{self._apply_indent(setup_code, 4)}""")
            if teardown_code:
                result.append(f"""def tearDown(self):
{self._apply_indent(teardown_code, 4)}""")
        elif self.framework in [TestFramework.JUNIT, TestFramework.TESTNG]:
            annotation = "@BeforeEach" if self.framework == TestFramework.JUNIT else "@BeforeMethod"
            if setup_code:
                result.append(f"""{annotation}
public void setUp() {{
{self._apply_indent(setup_code, 4)}
}}""")
            annotation = "@AfterEach" if self.framework == TestFramework.JUNIT else "@AfterMethod"
            if teardown_code:
                result.append(f"""{annotation}
public void tearDown() {{
{self._apply_indent(teardown_code, 4)}
}}""")
        return "\n\n".join(result)

    def _apply_indent(self, text: str, spaces: int) -> str:
        """Apply indentation to text."""
        indent = " " * spaces
        lines = text.split('\n')
        return '\n'.join(indent + line if line.strip() else line for line in lines)

    def _to_camel_case_format(self, text: str) -> str:
        """Convert text to camelCase format."""
        words = text.replace('-', ' ').replace('_', ' ').split()
        if not words:
            return text
        return words[0].lower() + ''.join(word.capitalize() for word in words[1:])

    def _to_class_format(self, text: str) -> str:
        """Convert text to ClassName format."""
        words = text.replace('-', ' ').replace('_', ' ').split()
        return ''.join(word.capitalize() for word in words)

    def identify_framework(self, code: str) -> Optional[TestFramework]:
        """
        Automatically detect testing framework from provided code.
        Args:
            code: Test code to analyze
        Returns:
            Detected framework or None
        """
        # Jest patterns
        if 'from \'@jest/globals\'' in code or '@jest/' in code:
            return TestFramework.JEST
        # Vitest patterns
        if 'from \'vitest\'' in code or 'import { vi }' in code:
            return TestFramework.VITEST
        # Pytest patterns
        if 'import pytest' in code or ('def test_' in code and 'pytest.fixture' in code):
            return TestFramework.PYTEST
        # Unittest patterns
        if 'import unittest' in code and 'unittest.TestCase' in code:
            return TestFramework.UNITTEST
        # JUnit patterns
        if '@Test' in code and 'import org.junit' in code:
            return TestFramework.JUNIT
        # TestNG patterns
        if '@Test' in code and 'import org.testng' in code:
            return TestFramework.TESTNG
        # Mocha patterns
        if 'from \'mocha\'' in code or ('describe(' in code and 'from \'chai\'' in code):
            return TestFramework.MOCHA
        return None

# Calculate the sum based on odd/even logic for input list

def compute_adjusted_sum(numbers: list[int]) -> int:
    result: int = 0
    idx = 0
    while idx < len(numbers):
        val = numbers[idx]
        if val % 2 != 0:
            result += val * 2
        else:
            result += val
        idx += 1
    return result

def _run_test_case() -> None:
    print(compute_adjusted_sum([1, 2, 3, 4]))

if __name__ == "__main__":
    from pytra.utils.assertions import py_assert_stdout
    print(py_assert_stdout(['14'], _run_test_case))

