class ANSIFormatting:
    """ANSI escape code helper for terminal formatting"""
    BOLD = "\u001b[1m"
    RED = "\u001b[31m"
    GRAY = "\u001b[90m"
    RESET = "\u001b[0m"

    @classmethod
    def apply(cls, text: str, *styles) -> str:
        return "".join(styles) + text + cls.RESET

    @classmethod
    def bold(cls, text: str) -> str:
        return cls.apply(text, cls.BOLD)

    @classmethod
    def red(cls, text: str) -> str:
        return cls.apply(text, cls.BOLD, cls.RED)

    @classmethod
    def gray(cls, text: str) -> str:
        return cls.apply(text, cls.GRAY)


def format_table(rows: List[List[Union[str, int]]], headers: List[str]) -> str:
    """
    Format data into a human-readable table.

    Args:
        rows: List of row data lists
        headers: Column header names

    Returns:
        Formatted table string
    """
    if not rows:
        return ""

    # Calculate column widths
    all_data = [headers] + rows
    col_widths = [max(len(str(row[i])) for row in all_data) for i in range(len(headers))]

    # Build format string
    row_format = " ".join(f"{{:<{w}}}" for w in col_widths)

    # Generate table lines
    lines = [
        row_format.format(*headers),
        row_format.format(*["-" * w for w in col_widths])
    ]

    for row in rows:
        lines.append(row_format.format(*row))

    return "\n".join(lines)


