class RepoCreateCommand(UserCommandBase):
    def execute(self) -> None:
        print(
            ANSIFormatting.red(
                "WARNING: Repository creation through transformers-cli is deprecated. "
                "Switch to `huggingface-cli` for repository management."
            )
        )

        token = HfFolder.get_token()
        if token is None:
            print("Authentication required. Please log in first.")
            return

        # Check git installation
        try:
            version_output = subprocess.check_output(["git", "--version"]).decode().strip()
            print(ANSIFormatting.gray(version_output))
        except FileNotFoundError:
            print("Git not found. Please install Git to continue.")

        # Check git-lfs installation
        try:
            lfs_version = subprocess.check_output(["git-lfs", "--version"]).decode().strip()
            print(ANSIFormatting.gray(lfs_version))
        except FileNotFoundError:
            print(
                ANSIFormatting.red(
                    "Git LFS is missing. Install from https://git-lfs.github.com/ "
                    "and run 'git lfs install' once."
                )
            )

        print()  # Empty line for readability

        # Determine namespace
        try:
            current_user, _ = whoami(token)
        except Exception:
            print("Failed to retrieve user information.")
            return

        namespace = self.args.organization or current_user
        repo_id = f"{namespace}/{self.args.name}"

        print(f"Creating repository: {ANSIFormatting.bold(repo_id)}")

        # Confirmation prompt
        if not self.args.yes:
            response = input("Continue? [Y/n] ").strip().lower()
            if response not in ("", "y", "yes"):
                print("Operation cancelled.")
                return

        # Create repository
        try:
            repo_url = create_repo(repo_id=repo_id, token=token)
        except HTTPError as error:
            print(f"Repository creation failed: {error}")
            if hasattr(error, 'response') and error.response:
                print(ANSIFormatting.red(error.response.text))
            return

        # Output success information
        print("\nRepository created successfully:")
        print(f"  URL: {ANSIFormatting.bold(repo_url)}")
        print("\nClone locally with:")
        print(f"\n  git clone {repo_url}")
        print("\nThen commit and push changes as usual.")

