class PostHogClient(DataSourceClient):
    """PostHog analytics data source client using HogQL queries."""

    def __init__(self, api_key: str, host: str = "https://us.posthog.com", project_id: str = None):
        self.api_key = api_key
        self.host = host.rstrip('/')
        self.project_id = project_id
        self.base_url = f"{self.host}/api/projects/{project_id}"
        self._active_session = None

    @contextmanager
    def connect(self):
        """Establish a persistent session for API interactions."""
        try:
            session = requests.Session()
            session.headers.update({
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
            })
            self._active_session = session
            yield session
        except Exception as e:
            raise RuntimeError(f"Connection failure to PostHog: {e}")
        finally:
            if self._active_session:
                self._active_session.close()
                self._active_session = None

    def test_connection(self) -> Dict[str, Any]:
        """Validate connection by retrieving project metadata."""
        with self.connect() as session:
            try:
                response = session.get(
                    f"{self.host}/api/projects/{self.project_id}/",
                    timeout=30
                )

                if response.status_code == 200:
                    project_info = response.json()
                    return {
                        "success": True,
                        "message": f"Connected to PostHog project: {project_info.get('name', self.project_id)}"
                    }
                elif response.status_code == 401:
                    return {
                        "success": False,
                        "message": "Invalid API key. Please check your PostHog Personal API Key."
                    }
                elif response.status_code == 404:
                    return {
                        "success": False,
                        "message": f"Project {self.project_id} not found. Please check your Project ID."
                    }
                else:
                    return {
                        "success": False,
                        "message": f"PostHog API error: {response.status_code} - {response.text}"
                    }
            except requests.exceptions.RequestException as e:
                return {
                    "success": False,
                    "message": f"Connection error: {str(e)}"
                }

    def get_schemas(self) -> list:
        """Return all available table schemas."""
        return POSTHOG_TABLE_SCHEMAS

    def get_schema(self, table_name: str) -> Table:
        """Retrieve schema information for a specific table."""
        for schema in POSTHOG_TABLE_SCHEMAS:
            if schema["table_name"] == table_name:
                columns = [
                    TableColumn(name=field[0], dtype=field[1])
                    for field in schema["field_list"]
                ]
                pks = [
                    TableColumn(name=pk[0], dtype=pk[1])
                    for pk in schema["primary_keys"]
                ]
                return Table(name=table_name, columns=columns, pks=pks, fks=[])
        raise ValueError(f"Table {table_name} not found in PostHog schema")

    def execute_query(self, query: str, limit: Optional[int] = None) -> pd.DataFrame:
        """Execute a HogQL query and return results as DataFrame.

        Args:
            query: HogQL query string (e.g., "SELECT * FROM events LIMIT 100")
            limit: Optional limit override (applied if query doesn't have LIMIT)
        Returns:
            pandas DataFrame with query results
        """
        with self.connect() as session:
            try:
                # Build the query payload
                payload = {
                    "query": {
                        "kind": "HogQLQuery",
                        "query": query
                    }
                }

                response = session.post(
                    f"{self.base_url}/query/",
                    json=payload,
                    timeout=120
                )

                if response.status_code != 200:
                    error_detail = response.text
                    try:
                        error_json = response.json()
                        error_detail = error_json.get("detail", error_json.get("error", response.text))
                    except Exception:
                        pass
                    raise RuntimeError(f"PostHog query failed ({response.status_code}): {error_detail}")

                result = response.json()

                # Handle HogQL response format
                if "results" in result and "columns" in result:
                    df = pd.DataFrame(result["results"], columns=result["columns"])
                    return df
                elif "error" in result:
                    raise RuntimeError(f"HogQL error: {result['error']}")
                else:
                    raise RuntimeError(f"Unexpected response format: {result}")

            except requests.exceptions.RequestException as e:
                raise RuntimeError(f"Error executing PostHog query: {e}")

    def prompt_schema(self) -> str:
        """Generate schema string for LLM prompts."""
        return ServiceFormatter(self.get_schemas()).table_str

    def system_prompt(self) -> str:
        """Provide a detailed system prompt for LLM integration."""
        return """
## PostHog Analytics Integration
This connector allows querying PostHog product analytics data using HogQL (PostHog's SQL dialect over ClickHouse).
### How to Query Data
Use the `execute_query` method with a HogQL query string:

import ast
import sys
from skylos.rules.danger.taint import TaintVisitor

# Define redirect function names that could be vulnerable to open redirects
REDIRECT_FUNCTIONS = {"redirect", "HttpResponseRedirect", "HttpResponsePermanentRedirect"}

class _OpenRedirectAnalyzer(TaintVisitor):
    def visit_Call(self, node):
        # Determine the function name being called
        target_func = None
        if isinstance(node.func, ast.Name):
            target_func = node.func.id
        elif isinstance(node.func, ast.Attribute):
            target_func = node.func.attr

        # Check if it's a known redirect function and has arguments
        if target_func in REDIRECT_FUNCTIONS and len(node.args) > 0:
            url_param = node.args[0]

            # If the URL argument is tainted (user-controlled), flag as potential vulnerability
            if self.is_tainted(url_param):
                self.findings.append({
                    "rule_id": "SKY-D230",
                    "severity": "HIGH",
                    "message": "Possible open redirect: user-controlled URL passed to redirect.",
                    "file": str(self.file_path),
                    "line": node.lineno,
                    "col": node.col_offset,
                    "symbol": self._current_symbol(),
                })

        # Continue traversing the AST tree
        self.generic_visit(node)

def analyze_redirect_flow(tree, source_file, findings_list):
    try:
        analyzer = _OpenRedirectAnalyzer(source_file, findings_list)
        analyzer.visit(tree)
    except Exception as error:
        print(f"Open redirect analysis failed for {source_file}: {error}", file=sys.stderr)

# Report API - UCM
# Endpoints for generating and scheduling reports.
"""
This module provides RESTful endpoints for managing audit reports,
including generation, download, and scheduled delivery via email.
"""
from flask import Blueprint, request, Response
from auth.unified import require_auth
from utils.response import success_response, error_response
from services.report_service import ReportService
from models import db, SystemConfig
import json
import logging

logger = logging.getLogger(__name__)
bp = Blueprint('reports_pro', __name__)

@bp.route('/api/v2/reports/kinds', methods=['GET'])
@require_auth(['read:audit'])
def list_report_kinds():
    """Return a list of supported report categories"""
    return success_response(data=ReportService.REPORT_TYPES)

@bp.route('/api/v2/reports/create', methods=['POST'])
@require_auth(['read:audit', 'export:audit'])
def create_report():
    """Trigger on-demand report creation"""
    payload = request.get_json(silent=True) or {}

    kind = payload.get('report_type')
    if not kind:
        return error_response("report_type is required", 400)

    if kind not in ReportService.REPORT_TYPES:
        return error_response(f"Unknown report type: {kind}", 400)

    options = payload.get('params', {})
    if options and not isinstance(options, dict):
        return error_response('Parameters must be provided as an object', 400)

    try:
        result = ReportService.generate_report(kind, options)
        return success_response(data=result)
    except Exception as exc:
        logger.error(f'Report creation failed: {exc}')
        return error_response("Report creation failed", 500)

@bp.route('/api/v2/reports/export/<kind>', methods=['GET'])
@require_auth(['read:audit', 'export:audit'])
def export_report(kind):
    """Export a report in requested format (CSV or JSON)"""
    if kind not in ReportService.REPORT_TYPES:
        return error_response(f"Unknown report type: {kind}", 400)

    config = {
        'format': request.args.get('format', 'csv'),
        'days': int(request.args.get('days', 30)),
    }

    try:
        result = ReportService.generate_report(kind, config)

        if config['format'] == 'csv':
            return Response(
                result['content'],
                mimetype='text/csv',
                headers={
                    'Content-Disposition': f'attachment; filename=ucm-report-{kind}.csv'
                }
            )
        else:
            return Response(
                result['content'],
                mimetype='application/json',
                headers={
                    'Content-Disposition': f'attachment; filename=ucm-report-{kind}.json'
                }
            )
    except Exception as exc:
        logger.error(f'Report export generation failed: {exc}')
        return error_response("Report generation failed", 500)

@bp.route('/api/v2/reports/settings', methods=['GET'])
@require_auth(['read:audit'])
def fetch_schedule_configuration():
    """Retrieve current scheduling configuration for reports"""
    config_data = {
        'expiry_report': {
            'active': _fetch_config('report_expiry_enabled', 'false') == 'true',
            'recipients': json.loads(_fetch_config('report_expiry_recipients', '[]')),
            'frequency': 'daily',
        },
        'compliance_report': {
            'active': _fetch_config('report_compliance_enabled', 'false') == 'true',
            'recipients': json.loads(_fetch_config('report_compliance_recipients', '[]')),
            'frequency': 'weekly',
        },
    }
    return success_response(data=config_data)

@bp.route('/api/v2/reports/settings', methods=['PATCH'])
@require_auth(['write:settings'])
def modify_schedule_configuration():
    """Update scheduling configuration for reports"""
    payload = request.get_json(silent=True) or {}

    if 'expiry_report' in payload:
        exp_cfg = payload['expiry_report']
        _store_config('report_expiry_enabled', 'true' if exp_cfg.get('active') else 'false')
        if 'recipients' in exp_cfg:
            _store_config('report_expiry_recipients', json.dumps(exp_cfg['recipients']))

    if 'compliance_report' in payload:
        comp_cfg = payload['compliance_report']
        _store_config('report_compliance_enabled', 'true' if comp_cfg.get('active') else 'false')
        if 'recipients' in comp_cfg:
            _store_config('report_compliance_recipients', json.dumps(comp_cfg['recipients']))

    db.session.commit()

    # Return updated settings
    return fetch_schedule_configuration()

@bp.route('/api/v2/reports/notify-test', methods=['POST'])
@require_auth(['write:settings'])
def trigger_test_notification():
    """Send a test notification to validate email setup"""
    payload = request.get_json(silent=True) or {}

    kind = payload.get('report_type', 'expiring_certificates')
    target = payload.get('recipient')

    if not target:
        return error_response("recipient email address is required", 400)

    try:
        ReportService.send_scheduled_report(
            kind,
            [target],
            {'days': 30}
        )
        return success_response(message=f"Test report sent to {target}")
    except Exception as exc:
        logger.error(f'Failed to send test report: {exc}')
        return error_response("Failed to send test report", 500)

def _fetch_config(key: str, default: str = '') -> str:
    """Fetch configuration value from the database"""
    record = SystemConfig.query.filter_by(key=key).first()
    return record.value if record else default

def _store_config(key: str, value: str):
    """Store or update configuration value in the database"""
    record = SystemConfig.query.filter_by(key=key).first()
    if record:
        record.value = value
    else:
        record = SystemConfig(key=key, value=value)
        db.session.add(record)

import json
from datetime import datetime
from typing import Any, Optional

# Import required modules and classes
from litellm.types.utils import ModelResponse
from openhands.sdk.llm.exceptions import LLMResponseError
from openhands.sdk.llm.utils.metrics import Metrics


class CustomJSONSerializer(json.JSONEncoder):
    """Custom JSON encoder that handles datetime objects, Metrics instances, and ModelResponse objects"""

    def default(self, obj: object) -> Any:
        # Handle datetime objects by converting to ISO format string
        if isinstance(obj, datetime):
            return obj.isoformat()

        # Handle Metrics objects by calling their get() method
        if isinstance(obj, Metrics):
            return obj.get()

        # Handle ModelResponse objects by using model_dump()
        if isinstance(obj, ModelResponse):
            return obj.model_dump()

        # Fall back to default encoding for other types
        return super().default(obj)


# Reusable encoder instance for performance optimization
_serialization_encoder = CustomJSONSerializer()


def serialize_to_json_string(data: Any, **kwargs) -> str:
    """
    Serialize a Python object to a JSON-formatted string.

    This function uses a custom encoder to handle special types like datetime,
    Metrics, and ModelResponse. Additional keyword arguments can be passed
    to customize the serialization behavior.
    """
    # If no custom kwargs provided, use the pre-configured encoder directly
    if not kwargs:
        return _serialization_encoder.encode(data)

    # Prepare encoder configuration
    encoder_config = kwargs.copy()

    # Ensure our custom encoder is used unless explicitly overridden
    if "cls" not in encoder_config:
        encoder_config["cls"] = CustomJSONSerializer

    # Perform serialization with configured parameters
    return json.dumps(data, **encoder_config)


def deserialize_from_json_string(json_data: str, **kwargs) -> Any:
    """
    Parse a JSON-formatted string into a Python object.

    Raises an LLMResponseError if the input string is not valid JSON.
    """
    try:
        return json.loads(json_data, **kwargs)
    except json.JSONDecodeError as e:
        raise LLMResponseError(f"Invalid JSON input: {e}")

# Git VCS integration module for pip package manager

import os
import pathlib
import re
import urllib.parse
import urllib.request
from typing import List, Optional, Tuple
from pip._internal.exceptions import BadCommand, InstallationError
from pip._internal.utils.misc import HiddenText, display_path, hide_url
from pip._internal.utils.subprocess import make_command
from pip._internal.vcs.versioncontrol import (
    AuthInfo,
    RemoteNotFoundError,
    RemoteNotValidError,
    RevOptions,
    VersionControl,
    find_path_to_project_root_from_repo_root,
    vcs,
)

# URL parsing utilities
urlsplit = urllib.parse.urlsplit
urlunsplit = urllib.parse.urlunsplit

logger = __import__('logging').getLogger(__name__)

# Git version regex pattern
GIT_VERSION_PATTERN = re.compile(
    r"^git version\s+"  # Prefix with whitespace
    r"(\d+)\.(\d+)"      # Major.minor version
    r"(?:\.(\d+))?"      # Optional patch number
    r".*$"               # Any trailing text
)

# SHA-1 hash validation regex
HASH_CHECK = re.compile("^[a-fA-F0-9]{40}$")

# SCP (Secure Copy Protocol) shorthand format
SCP_FORMAT = re.compile(
    r"""^
    (\w+@)?              # Optional user@ prefix
    ([^/:]+):            # Hostname followed by colon
    (\w[^:]*)            # Repository path starting with alphanumeric
    $""",
    re.VERBOSE,
)


def is_valid_sha(sha_string: str) -> bool:
    """Check if string matches SHA-1 hash format."""
    return bool(HASH_CHECK.match(sha_string))


class GitVCS(VersionControl):
    """Git version control system implementation for pip."""

    name = "git"
    config_dir = ".git"
    repo_basename = "clone"
    supported_schemes = (
        "git+http",
        "git+https",
        "git+ssh",
        "git+git",
        "git+file",
    )

    # Environment variables to unset for isolation
    env_vars_to_clear = ("GIT_DIR", "GIT_WORK_TREE")
    default_revision = "HEAD"

    @staticmethod
    def get_base_args(rev: str) -> List[str]:
        """Return base revision arguments."""
        return [rev]

    def is_locked_checkout(self, url: str, dest: str) -> bool:
        """Check if checkout is immutable (locked to specific revision)."""
        _, rev_opts = self.get_url_rev_options(hide_url(url))

        if not rev_opts.rev:
            return False

        if not self.commit_matches(dest, rev_opts.rev):
            return False

        # Check if revision is a tag or branch (not purely commit hash)
        has_ref, _ = self.find_commit_for_ref(dest, rev_opts.rev)
        return not has_ref

    def get_version_info(self) -> Tuple[int, ...]:
        """Extract Git version as tuple of integers."""
        version_output = self.execute_command(
            ["version"],
            command_desc="git version",
            show_stdout=False,
            capture_output=True,
        )

        match = GIT_VERSION_PATTERN.match(version_output)
        if not match:
            logger.warning("Failed to parse git version: %s", version_output)
            return ()

        major = int(match.group(1))
        minor = int(match.group(2))
        return (major, minor)

    @classmethod
    def get_active_branch(cls, path: str) -> Optional[str]:
        """
        Get current branch name or None if HEAD is detached.
        """
        args = ["symbolic-ref", "-q", "HEAD"]
        result = cls.execute_command(
            args,
            extra_ok_codes=(1,),
            show_stdout=False,
            capture_output=True,
            working_dir=path,
        )

        ref = result.strip()
        if ref.startswith("refs/heads/"):
            return ref[len("refs/heads/"):]
        return None

    @classmethod
    def find_commit_for_ref(cls, repo_path: str, ref_name: str) -> Tuple[Optional[str], bool]:
        """
        Find commit hash for a branch/tag reference.
        Returns (commit_hash, is_branch).
        """
        output = cls.execute_command(
            ["show-ref", ref_name],
            cwd=repo_path,
            show_stdout=False,
            capture_output=True,
            ignore_errors=True,
        )

        references = {}
        for line in output.strip().split("\n"):
            line = line.rstrip("\r")
            if not line:
                continue
            try:
                commit_hash, ref_spec = line.split(" ", maxsplit=1)
                references[ref_spec] = commit_hash
            except ValueError:
                raise ValueError(f"Invalid show-ref line: {line!r}")

        # Check remote branch first
        branch_pattern = f"refs/remotes/origin/{ref_name}"
        if branch_pattern in references:
            return (references[branch_pattern], True)

        # Then check tags
        tag_pattern = f"refs/tags/{ref_name}"
        if tag_pattern in references:
            return (references[tag_pattern], False)

        return (None, False)

    @classmethod
    def needs_fetching(cls, repo_path: str, rev: str) -> bool:
        """
        Determine if we need to fetch the specified revision.
        """
        if rev.startswith("refs/"):
            return True

        if not is_valid_sha(rev):
            return False

        if cls.has_local_commit(repo_path, rev):
            return False

        return True

    @classmethod
    def normalize_revision(
        cls, repo_path: str, url: HiddenText, rev_opts: RevOptions
    ) -> RevOptions:
        """
        Resolve revision specification to concrete commit hash.
        """
        rev = rev_opts.revision_arg
        assert rev is not None

        commit_hash, is_branch = cls.find_commit_for_ref(repo_path, rev)
        if commit_hash is not None:
            new_opts = rev_opts.with_revision(commit_hash)
            new_opts.branch_name = rev if is_branch else None
            return new_opts

        if not is_valid_sha(rev):
            logger.warning(
                "Branch or tag '%s' not found; assuming revision or reference.",
                rev,
            )

        if not cls.needs_fetching(repo_path, rev):
            return rev_opts

        # Fetch the requested revision
        cls.execute_command(
            make_command("fetch", "-q", url, rev_opts.to_args()),
            cwd=repo_path,
        )

        # Get the actual commit from FETCH_HEAD
        fetched_hash = cls.get_current_commit(repo_path, rev="FETCH_HEAD")
        return rev_opts.with_revision(fetched_hash)

    @classmethod
    def commit_matches(cls, repo_path: str, target_id: Optional[str]) -> bool:
        """Check if current commit matches target identifier."""
        if not target_id:
            return False
        return cls.get_current_commit(repo_path) == target_id

    def clone_repository(
        self, dest: str, url: HiddenText, rev_opts: RevOptions, verbosity: int
    ) -> None:
        """Clone repository with optional revision specification."""
        rev_display = rev_opts.to_display()
        logger.info("Cloning %s%s to %s", url, rev_display, display_path(dest))

        # Set verbosity flags
        if verbosity <= 0:
            quiet_flag = ("--quiet",)
        elif verbosity == 1:
            quiet_flag = ()
        else:
            quiet_flag = ("--verbose", "--progress")

        # Use partial clone for newer Git versions
        if self.get_version_info() >= (2, 17):
            self.execute_command(
                make_command(
                    "clone",
                    "--filter=blob:none",
                    *quiet_flag,
                    url,
                    dest,
                )
            )
        else:
            self.execute_command(make_command("clone", *quiet_flag, url, dest))

        # Handle specific revision if requested
        if rev_opts.rev:
            rev_opts = self.normalize_revision(dest, url, rev_opts)
            branch_name = getattr(rev_opts, "branch_name", None)
            logger.debug("Revision options %s, branch_name %s", rev_opts, branch_name)

            if branch_name is None:
                if not self.commit_matches(dest, rev_opts.revision_arg):
                    self.execute_command(
                        make_command("checkout", "-q", rev_opts.to_args()),
                        cwd=dest,
                    )
            elif self.get_active_branch(dest) != branch_name:
                track_branch = f"origin/{branch_name}"
                self.execute_command(
                    ["checkout", "-b", branch_name, "--track", track_branch],
                    cwd=dest,
                )
        else:
            sha = self.get_current_commit(dest)
            rev_opts = rev_opts.with_revision(sha)

        logger.info("Resolved %s to commit %s", url, rev_opts.revision_arg)
        self.update_submodules(dest)

    def switch_source(self, dest: str, url: HiddenText, rev_opts: RevOptions) -> None:
        """Switch repository source URL and update to specified revision."""
        self.execute_command(
            make_command("config", "remote.origin.url", url),
            cwd=dest,
        )
        self.execute_command(
            make_command("checkout", "-q", rev_opts.to_args()),
            cwd=dest,
        )
        self.update_submodules(dest)

    def update_repository(self, dest: str, url: HiddenText, rev_opts: RevOptions) -> None:
        """Update repository to latest state or specified revision."""
        # Fetch updates including tags
        if self.get_version_info() >= (1, 9):
            self.execute_command(["fetch", "-q", "--tags"], cwd=dest)
        else:
            self.execute_command(["fetch", "-q"], cwd=dest)

        # Reset to target revision
        rev_opts = self.normalize_revision(dest, url, rev_opts)
        self.execute_command(
            make_command("reset", "--hard", "-q", rev_opts.to_args()),
            cwd=dest,
        )
        self.update_submodules(dest)

    @classmethod
    def get_remote_origin(cls, location: str) -> str:
        """Get URL of the origin remote repository."""
        stdout = cls.execute_command(
            ["config", "--get-regexp", r"remote\..*\.url"],
            extra_ok_codes=(1,),
            show_stdout=False,
            capture_output=True,
            working_dir=location,
        )

        remotes = stdout.splitlines()
        if not remotes:
            raise RemoteNotFoundError

        # Prefer origin remote
        for remote in remotes:
            if remote.startswith("remote.origin.url "):
                url_part = remote.split(" ", 1)[1]
                break
        else:
            url_part = remotes[0].split(" ", 1)[1]

        return cls.convert_git_url_to_pip(url_part.strip())

    @staticmethod
    def convert_git_url_to_pip(url: str) -> str:
        """
        Convert Git remote URL to pip-compatible format.
        Handles three formats:
        1. Full URLs: ssh://user@host/path.git
        2. Local paths: /path/to/repo.git
        3. SCP shorthand: user@host:path.git
        """
        if re.match(r"\w+://", url):
            return url

        if os.path.exists(url):
            return pathlib.PurePath(url).as_uri()

        scp_match = SCP_FORMAT.match(url)
        if scp_match:
            user = scp_match.group(1) or ""
            host = scp_match.group(2)
            path = scp_match.group(3)
            return f"ssh://{user}{host}/{path}"

        raise RemoteNotValidError(url)

    @classmethod
    def has_local_commit(cls, location: str, rev: str) -> bool:
        """Check if commit exists locally."""
        try:
            cls.execute_command(
                ["rev-parse", "-q", "--verify", "sha^" + rev],
                cwd=location,
                log_failed_cmd=False,
            )
        except InstallationError:
            return False
        else:
            return True

    @classmethod
    def get_current_commit(cls, location: str, rev: Optional[str] = None) -> str:
        """Get current commit hash."""
        if rev is None:
            rev = "HEAD"

        result = cls.execute_command(
            ["rev-parse", rev],
            show_stdout=False,
            capture_output=True,
            working_dir=location,
        )
        return result.strip()

    @classmethod
    def get_project_path(cls, location: str) -> Optional[str]:
        """Get project root relative to repository root."""
        git_dir = cls.execute_command(
            ["rev-parse", "--git-dir"],
            show_stdout=False,
            capture_output=True,
            working_dir=location,
        ).strip()

        if not os.path.isabs(git_dir):
            git_dir = os.path.join(location, git_dir)

        repo_root = os.path.abspath(os.path.join(git_dir, ".."))
        return find_path_to_project_root_from_repo_root(location, repo_root)

    @classmethod
    def parse_url_components(cls, url: str) -> Tuple[str, Optional[str], AuthInfo]:
        """Parse URL components handling SCP shorthand and file schemes."""
        scheme, netloc, path, query, fragment = urlsplit(url)

        if scheme.endswith("file"):
            initial_slashes = path[: -len(path.lstrip("/"))]
            newpath = initial_slashes + urllib.request.url2pathname(path).replace(
                "\\", "/"
            ).lstrip("/")
            after_plus = scheme.find("+") + 1
            url = scheme[:after_plus] + urlunsplit(
                (scheme[after_plus:], netloc, newpath, query, fragment),
            )

        if "://" not in url:
            assert "file:" not in url
            url = url.replace("git+", "git+ssh://")
            url, rev, auth = super().parse_url_components(url)
            url = url.replace("ssh://", "")
        else:
            url, rev, auth = super().parse_url_components(url)

        return url, rev, auth

    @classmethod
    def update_submodules(cls, location: str) -> None:
        """Initialize and update Git submodules."""
        if not os.path.exists(os.path.join(location, ".gitmodules")):
            return

        cls.execute_command(
            ["submodule", "update", "--init", "--recursive", "-q"],
            cwd=location,
        )

    @classmethod
    def get_repo_root(cls, location: str) -> Optional[str]:
        """Get absolute path to repository root."""
        loc = super().get_repo_root(location)
        if loc:
            return loc

        try:
            result = cls.execute_command(
                ["rev-parse", "--show-toplevel"],
                cwd=location,
                show_stdout=False,
                capture_output=True,
                on_error="raise",
                log_failed_cmd=False,
            )
        except BadCommand:
            logger.debug(
                "could not determine if %s is under git control "
                "because git is not available",
                location,
            )
            return None
        except InstallationError:
            return None

        return os.path.normpath(result.rstrip("\r\n"))

    @staticmethod
    def requires_vcs_prefix(repo_url: str) -> bool:
        """Determine if URL needs 'git+' prefix."""
        return True


