import functools
import os
import sys
from typing import TYPE_CHECKING, List, Optional, Type, cast
from pip._internal.utils.misc import strtobool
from .base import BaseDistribution, BaseEnvironment, FilesystemWheel, MemoryWheel, Wheel

if TYPE_CHECKING:
    from typing import Literal, Protocol
else:
    Protocol = object

__all__ = [
    "BaseDistribution",
    "BaseEnvironment",
    "FilesystemWheel",
    "MemoryWheel",
    "Wheel",
    "get_default_environment",
    "get_environment",
    "get_wheel_distribution",
    "select_backend",
]

def _prefer_importlib_metadata() -> bool:
    """Determine whether to use the importlib.metadata backend over pkg_resources.

    The decision follows these rules (in order):
    1. If the environment variable _PIP_USE_IMPORTLIB_METADATA is set, its value
       (interpreted as a boolean) takes precedence.
    2. For Python versions below 3.11, default to False (i.e., use pkg_resources).
    3. On Python 3.11+, check if importlib.metadata has been patched by distributors
       with a _PIP_USE_IMPORTLIB_METADATA attribute set to False; otherwise default to True.
    """
    try:
        env_val = os.environ.get("_PIP_USE_IMPORTLIB_METADATA")
        if env_val is not None:
            return bool(strtobool(env_val))
    except (KeyError, ValueError):
        pass

    if sys.version_info < (3, 11):
        return False

    try:
        import importlib.metadata
        return getattr(importlib.metadata, "_PIP_USE_IMPORTLIB_METADATA", True)
    except ImportError:
        return False


class Backend(Protocol):
    NAME: 'Literal["importlib", "pkg_resources"]'
    Distribution: Type[BaseDistribution]
    Environment: Type[BaseEnvironment]


@functools.lru_cache(maxsize=None)
def select_backend() -> Backend:
    if _prefer_importlib_metadata():
        from . import importlib as backend_module
        return cast(Backend, backend_module)
    else:
        from . import pkg_resources as backend_module
        return cast(Backend, backend_module)


def get_default_environment() -> BaseEnvironment:
    """Obtain the standard environment representation for the current Python setup.

    Returns an Environment instance from the selected backend, constructed using
    sys.path and potentially leveraging caching for performance across invocations.
    """
    return select_backend().Environment.default()


def get_environment(paths: Optional[List[str]]) -> BaseEnvironment:
    """Construct an environment representation based on specific import paths.

    Returns a fresh Environment instance from the chosen backend, initialized
    with the distribution state found at the provided paths.
    """
    return select_backend().Environment.from_paths(paths)


def get_directory_distribution(directory: str) -> BaseDistribution:
    """Extract distribution metadata from a specified directory path.

    Returns a Distribution instance representing the .dist-info directory
    located at the given filesystem path.
    """
    return select_backend().Distribution.from_directory(directory)


def get_wheel_distribution(wheel: Wheel, canonical_name: str) -> BaseDistribution:
    """Create a distribution representation from a wheel file's metadata.

    :param wheel: The wheel object containing the .dist-info directory.
    :param canonical_name: Normalized project name used for identification.
    """
    return select_backend().Distribution.from_wheel(wheel, canonical_name)


def get_metadata_distribution(
    metadata_contents: bytes,
    filename: str,
    canonical_name: str,
) -> BaseDistribution:
    """Build a distribution object from raw METADATA content.

    :param metadata_contents: Raw byte content of a METADATA file.
    :param filename: Original filename associated with the metadata.
    :param canonical_name: Normalized project name for reference.
    """
    return select_backend().Distribution.from_metadata_file_contents(
        metadata_contents,
        filename,
        canonical_name,
    )

import os
import gymnasium as gym
import numpy as np
from typing import Union, List, Any, Optional, Dict
from dataclasses import dataclass, field
from libero.libero import get_libero_path
import torch
from cosmos_rl.simulators.libero.venv import ReconfigureSubprocEnv
from cosmos_rl.simulators.libero.utils import (
    get_benchmark_overridden,
    get_libero_dummy_action,
)
from cosmos_rl.simulators.utils import save_rollout_video


def normalize_gripper_action(action: np.ndarray, binarize: bool = True) -> np.ndarray:
    """Normalize gripper action from [0,1] to [-1,+1], optionally binarizing."""
    normalized = 2 * action - 1
    if binarize:
        return np.where(normalized[..., -1:] >= 0, 1.0, -1.0)
    else:
        return normalized


def invert_gripper_action(action: np.ndarray) -> np.ndarray:
    """Flip sign of gripper action (last dimension only)."""
    flipped = action.copy()
    flipped[..., -1] *= -1.0
    return flipped


@dataclass
class EnvStateSnapshot:
    idx: int
    task_id: int = -1
    trial_id: int = -1
    is_active: bool = True
    is_done: bool = False
    steps_taken: int = 0
    lang_desc: str = ""
    last_observation: Optional[Dict[str, Any]] = None
    is_for_validation: bool = False
    validation_frames: Dict[str, List[np.ndarray]] = field(default_factory=lambda: {
        "full_images": [],
        "wrist_images": []
    })


class LiberoEnvAdapter(gym.Env):
    def __init__(self, config, *args, **kwargs):
        self.num_parallel_envs = getattr(config, "num_envs", 1)
        self.rng_seed = getattr(config, "seed", 0)
        self.benchmark_name = getattr(config, "task_suite_name", "libero_all")
        self.obs_height = getattr(config, "height", 256)
        self.obs_width = getattr(config, "width", 256)
        self.max_episode_length = getattr(config, "max_steps", 512)

        self.task_suite = get_benchmark_overridden(self.benchmark_name)()
        self._env_states = [
            EnvStateSnapshot(idx=i) for i in range(self.num_parallel_envs)
        ]
        self._setup_env()

    def _setup_env(self):
        # Create placeholder env functions lazily
        dummy_fns = [lambda: None for _ in range(self.num_parallel_envs)]
        self.env = ReconfigureSubprocEnv(dummy_fns)

    def _prepare_task_params(self, task_idx: int) -> tuple[str, dict]:
        task = self.task_suite.get_task(task_idx)
        bddl_path = os.path.join(
            get_libero_path("bddl_files"),
            task.problem_folder,
            task.bddl_file
        )
        params = {
            "camera_heights": self.obs_height,
            "camera_widths": self.obs_width,
            "bddl_file_name": bddl_path,
            "seed": self.rng_seed,
        }
        return task.language, params

    def _extract_observations(self, raw_obs: List[Dict]) -> Dict[str, np.ndarray]:
        rgb_full = []
        rgb_wrist = []
        states_vec = []

        for obs in raw_obs:
            rgb_full.append(obs["agentview_image"][::-1, ::-1])
            rgb_wrist.append(obs["robot0_eye_in_hand_image"][::-1, ::-1])
            eef_pos = obs["robot0_eef_pos"]
            eef_quat = obs["robot0_eef_quat"]
            gripper_qpos = obs["robot0_gripper_qpos"]
            states_vec.append(np.concatenate([eef_pos, eef_quat, gripper_qpos]))

        return {
            "full_images": np.stack(rgb_full),
            "wrist_images": np.stack(rgb_wrist),
            "states": np.stack(states_vec),
        }

    def _reconfigure_sync(
        self,
        target_env_ids: List[int],
        assigned_task_ids: List[int],
        assigned_trial_ids: List[int]
    ) -> tuple[Dict[str, np.ndarray], List[str]]:
        env_configs = []
        descriptions = []
        initial_states = []

        for i, eid in enumerate(target_env_ids):
            desc, cfg = self._prepare_task_params(assigned_task_ids[i])
            descriptions.append(desc)
            env_configs.append(cfg)

            n_init = len(self.task_suite.get_task_init_states(assigned_task_ids[i]))
            init_state = self.task_suite.get_task_init_states(assigned_task_ids[i])[
                assigned_trial_ids[i] % n_init
            ]
            initial_states.append(init_state)

            self._env_states[eid] = EnvStateSnapshot(
                idx=eid,
                task_id=assigned_task_ids[i],
                trial_id=assigned_trial_ids[i],
            )

        self.env.reconfigure_env_fns(env_configs, target_env_ids)
        self.env.set_init_state(initial_states, target_env_ids)

        dummy_actions = get_libero_dummy_action(len(target_env_ids))
        for _ in range(15):
            _, _, _, _ = self.env.step(dummy_actions, target_env_ids)

        obs_data = self._extract_observations(
            self.env.reset_wait(target_env_ids)[0] if hasattr(self.env, 'reset_wait') else [{}]
        )
        for i, eid in enumerate(target_env_ids):
            self._env_states[eid].last_observation = {
                k: v[i] for k, v in obs_data.items()
            }

        return obs_data, descriptions

    def _reconfigure_async(
        self,
        target_env_ids: List[int],
        assigned_task_ids: List[int],
        assigned_trial_ids: List[int]
    ):
        env_configs = []
        for i, eid in enumerate(target_env_ids):
            desc, cfg = self._prepare_task_params(assigned_task_ids[i])
            env_configs.append(cfg)
            self._env_states[eid] = EnvStateSnapshot(
                idx=eid,
                task_id=assigned_task_ids[i],
                trial_id=assigned_trial_ids[i],
                lang_desc=desc,
            )
        self.env.reconfigure_env_fns_async(env_configs, target_env_ids)

    def reset(
        self,
        env_ids: Union[int, List[int]],
        task_ids: Union[int, List[int]],
        trial_ids: Union[int, List[int]],
        do_validation: Union[bool, List[bool]]
    ) -> tuple[Dict[str, np.ndarray], List[str]]:
        env_ids = [env_ids] if isinstance(env_ids, int) else env_ids
        task_ids = [task_ids] if isinstance(task_ids, int) else task_ids
        trial_ids = [trial_ids] if isinstance(trial_ids, int) else trial_ids
        do_validation = [do_validation] if isinstance(do_validation, bool) else do_validation

        obs_dict, lang_list = self._reconfigure_sync(env_ids, task_ids, trial_ids)

        for i, eid in enumerate(env_ids):
            self._env_states[eid].is_for_validation = do_validation[i]
            if do_validation[i]:
                self._env_states[eid].validation_frames = {
                    "full_images": [],
                    "wrist_images": []
                }

        return obs_dict, lang_list

    def reset_async(
        self,
        env_ids: Union[int, List[int]],
        task_ids: Union[int, List[int]],
        trial_ids: Union[int, List[int]],
        do_validation: Union[bool, List[bool]]
    ):
        env_ids = [env_ids] if isinstance(env_ids, int) else env_ids
        task_ids = [task_ids] if isinstance(task_ids, int) else task_ids
        trial_ids = [trial_ids] if isinstance(trial_ids, int) else trial_ids
        do_validation = [do_validation] if isinstance(do_validation, bool) else do_validation

        self._reconfigure_async(env_ids, task_ids, trial_ids)

        for i, eid in enumerate(env_ids):
            self._env_states[eid].is_for_validation = do_validation[i]
            if do_validation[i]:
                self._env_states[eid].validation_frames = {
                    "full_images": [],
                    "wrist_images": []
                }

    def reset_wait(self, env_ids: List[int]) -> tuple[Dict[str, np.ndarray], List[str]]:
        self.env.wait_for_reconfigure(env_ids)

        init_states = []
        for eid in env_ids:
            task_id = self._env_states[eid].task_id
            n_trials = len(self.task_suite.get_task_init_states(task_id))
            init_states.append(
                self.task_suite.get_task_init_states(task_id)[
                    self._env_states[eid].trial_id % n_trials
                ]
            )
        self.env.set_init_state(init_states, env_ids)

        dummy_actions = get_libero_dummy_action(len(env_ids))
        for _ in range(15):
            _, _, _, _ = self.env.step(dummy_actions, env_ids)

        obs_batch = self.env.reset_wait(env_ids)[0] if hasattr(self.env, 'reset_wait') else [{}]
        obs_data = self._extract_observations(obs_batch)

        for i, eid in enumerate(env_ids):
            self._env_states[eid].last_observation = {
                k: v[i] for k, v in obs_data.items()
            }

        descriptions = [self._env_states[eid].lang_desc for eid in env_ids]
        return obs_data, descriptions

    def step(
        self,
        env_ids: List[int],
        actions: Union[np.ndarray, torch.Tensor]
    ) -> Dict[str, np.ndarray]:
        if isinstance(actions, torch.Tensor):
            actions = actions.detach().cpu().numpy()

        active_indices = [
            idx for idx, eid in enumerate(env_ids)
            if self._env_states[eid].is_active
        ]

        if not active_indices:
            return {
                "full_images": np.zeros((len(env_ids), self.obs_height, self.obs_width, 3)),
                "wrist_images": np.zeros((len(env_ids), self.obs_height, self.obs_width, 3)),
                "states": np.zeros((len(env_ids), 15)),
                "complete": np.full(len(env_ids), False),
                "active": np.full(len(env_ids), False),
                "finish_step": np.zeros(len(env_ids), dtype=int),
            }

        active_envs = [env_ids[i] for i in active_indices]
        selected_actions = actions[active_indices]

        obs, _, dones, _ = self.env.step(selected_actions, active_envs)
        frame_data = self._extract_observations(obs)

        for i, eid in enumerate(active_envs):
            self._env_states[eid].steps_taken += 1
            if dones[i] or self._env_states[eid].steps_taken >= self.max_episode_length:
                self._env_states[eid].is_done = dones[i]
                self._env_states[eid].is_active = False

            for key, val in frame_data.items():
                self._env_states[eid].last_observation[key] = val[i]

            if self._env_states[eid].is_for_validation:
                for img_key in ["full_images", "wrist_images"]:
                    self._env_states[eid].validation_frames[img_key].append(
                        frame_data[img_key][i]
                    )

        completes = np.array([self._env_states[eid].is_done for eid in env_ids])
        actives = np.array([self._env_states[eid].is_active for eid in env_ids])
        steps = np.array([self._env_states[eid].steps_taken for eid in env_ids])

        full_output = {}
        for key in ["full_images", "wrist_images", "states"]:
            full_output[key] = np.stack([
                self._env_states[eid].last_observation[key] for eid in env_ids
            ])

        full_output.update({
            "complete": completes,
            "active": actives,
            "finish_step": steps,
        })
        return full_output

    def chunk_step(
        self,
        env_ids: List[int],
        actions: torch.Tensor
    ) -> Dict[str, np.ndarray]:
        if isinstance(actions, torch.Tensor):
            actions = actions.detach().cpu().numpy()

        num_steps = actions.shape[1] if actions.ndim > 2 else 1
        if actions.ndim == 2:
            actions = actions[:, None, :]

        result = None
        for t in range(num_steps):
            result = self.step(env_ids, actions[:, t])
        return result

    def get_snapshot(self, env_ids: List[int]) -> List[EnvStateSnapshot]:
        return [self._env_states[eid] for eid in env_ids]

    def export_validation_videos(self, output_dir: str, env_ids: List[int]):
        for eid in env_ids:
            state = self._env_states[eid]
            if not state.is_for_validation:
                continue

            name = f"{self.benchmark_name}_task_{state.task_id}_trial_{state.trial_id}"
            save_rollout_video(
                state.validation_frames["full_images"],
                output_dir,
                name,
                state.is_done,
            )

import logging
from typing import Dict, List, Optional, Tuple
from .base import DriverBase

logger = logging.getLogger("OpenCastor.Dynamixel")

# Attempt SDK import; fall back gracefully if missing
try:
    from dynamixel_sdk import (
        COMM_SUCCESS,
        PacketHandler,
        PortHandler,
    )
    DYNAMIXEL_SDK_AVAILABLE = True
except ImportError:
    DYNAMIXEL_SDK_AVAILABLE = False
    logger.warning("Dynamixel SDK not found. Running in simulation/mode.")

class DynamixelDriver(DriverBase):
    """
    Robotis Dynamixel Servo (Protocol 2.0) driver.
    Converts RCAN angular commands (degrees, centered at 0°) to hardware ticks.
    """

    # Control table offsets (X-series / MX-series compatible)
    TORQUE_ENABLE_ADDRESS = 64
    GOAL_POSITION_ADDRESS = 116
    PRESENT_POSITION_ADDRESS = 132
    PROTOCOL_VER = 2.0

    # Conversion constants
    TICKS_PER_REVOLUTION = 4096
    CENTER_TICK = 2048
    DEG_PER_TICK = 0.088

    def __init__(self, config: Dict):
        self.serial_port_path = config.get("port", "/dev/ttyUSB0")
        self.baud_setting = config.get("baud_rate", 57600)
        self.active_servos: List[int] = []
        self._serial_handle = None
        self._packet_manager = None

        if not DYNAMIXEL_SDK_AVAILABLE:
            logger.warning("Dynamixel SDK unavailable — operating in mock mode.")
            return

        self._serial_handle = PortHandler(self.serial_port_path)
        self._packet_manager = PacketHandler(self.PROTOCOL_VER)

        if self._establish_serial_connection():
            logger.info(f"Dynamixel serial port established: {self.serial_port_path}")
        else:
            logger.error(f"Failed to initialize Dynamixel port: {self.serial_port_path}")

    def _establish_serial_connection(self) -> bool:
        if self._serial_handle is None:
            return False
        try:
            if not self._serial_handle.openPort():
                return False
            if not self._serial_handle.setBaudRate(self.baud_setting):
                return False
            return True
        except Exception as e:
            logger.debug(f"Serial setup exception: {e}")
            return False

    def activate(self, ids: List[int]):
        """Enable torque on specified servos."""
        if self._serial_handle is None or self._packet_manager is None:
            return
        for sid in ids:
            _, err_code = self._packet_manager.write1ByteTxRx(
                self._serial_handle, sid, self.TORQUE_ENABLE_ADDRESS, 1
            )
            if err_code != COMM_SUCCESS:
                logger.error(
                    f"Torque activation failed for motor {sid}: "
                    f"{self._packet_manager.getTxRxResult(err_code)}"
                )
            elif sid not in self.active_servos:
                self.active_servos.append(sid)

    def deactivate(self, ids: List[int]):
        """Disable torque on specified servos (safety release)."""
        if self._serial_handle is None or self._packet_manager is None:
            return
        for sid in ids:
            self._packet_manager.write1ByteTxRx(
                self._serial_handle, sid, self.TORQUE_ENABLE_ADDRESS, 0
            )

    def _deg_to_ticks(self, deg: float) -> int:
        """Convert degrees (RCAN zero-centered) to Dynamixel ticks."""
        raw = self.CENTER_TICK + deg / self.DEG_PER_TICK
        return max(0, min(self.TICKS_PER_REVOLUTION - 1, int(raw)))

    def move_to(self, servo_id: int, angle_deg: float):
        """Command a specific servo to an angular position."""
        if self._serial_handle is None or self._packet_manager is None:
            logger.info(f"[MOCK] Servo {servo_id} → {angle_deg}°")
            return

        target_ticks = self._deg_to_ticks(angle_deg)
        _, err = self._packet_manager.write4ByteTxRx(
            self._serial_handle, servo_id, self.GOAL_POSITION_ADDRESS, target_ticks
        )
        if err != COMM_SUCCESS:
            logger.error(f"Position command failed for ID {servo_id}: {err}")

    def read_position(self, servo_id: int) -> float:
        """Query current angular position (in degrees)."""
        if self._serial_handle is None or self._packet_manager is None:
            return 0.0

        ticks, comm_result, err_code = self._packet_manager.read4ByteTxRx(
            self._serial_handle, servo_id, self.PRESENT_POSITION_ADDRESS
        )
        if comm_result != COMM_SUCCESS:
            return 0.0
        return (ticks - self.CENTER_TICK) * self.DEG_PER_TICK

    def status_report(self) -> Dict[str, object]:
        """Check health of first active servo (or ID=1 fallback)."""
        if self._serial_handle is None or self._packet_manager is None:
            return {
                "ok": False,
                "mode": "mock",
                "error": "SDK unavailable or serial not initialized"
            }

        target_id = self.active_servos[0] if self.active_servos else 1
        try:
            model, result, _ = self._packet_manager.ping(self._serial_handle, target_id)
            if result == COMM_SUCCESS:
                return {"ok": True, "mode": "hardware", "error": None}
            return {
                "ok": False,
                "mode": "hardware",
                "error": f"Ping failure on ID {target_id} (code={result})"
            }
        except Exception as exc:
            return {"ok": False, "mode": "hardware", "error": str(exc)}

    def shutdown(self):
        """Release all servos and close serial port."""
        if self.active_servos:
            self.deactivate(self.active_servos)
        if self._serial_handle is not None:
            try:
                self._serial_handle.closePort()
            except Exception:
                pass  # Silent fail on cleanup

    def __del__(self):
        self.shutdown()

