    pass

# Constants
GENERAL_TIMEOUT = 30
CLEAN_RECORD_TIMEOUT = 10
START_EPISODE_RETRY_DELAY = 15
TROTTLE_EPISODE_RETRY_DELAY = 2
WAIT_MORE_AVAIL_EPISODE_RETRY_DELAY = 2

def handle_http_error(response):
    """Handle HTTP errors with detailed logging and error messages."""
    try:
        response.raise_for_status()
    except httpx.HTTPStatusError as exc:
        response_text = response.text
        try:
            error_detail = json.loads(response_text)
            logger.error(f"SwarmClient error {response.status_code}: {error_detail}")
            raise RuntimeError(f"SwarmClient error {response.status_code}: {error_detail}") from exc
        except (json.JSONDecodeError, ValueError):
            logger.error(f"SwarmClient error {response.status_code} with non-JSON response: {response_text}")
            raise RuntimeError(f"SwarmClient error {response.status_code} with non-JSON response: {response_text}") from exc

class SwarmClient:
    def __init__(self, server_url: str):
        self.server_url = server_url
        self.client_uuid = str(uuid.uuid4())
        self.last_warning_time = 0
        self.episode_expiry_times = {}
        self.recent_tasks = []
        self.http_client = httpx.Client(timeout=GENERAL_TIMEOUT)
        self._lock = None  # Placeholder for threading lock if needed

    def _refresh_http_client(self):
        """Refresh the HTTP client by closing the old one and creating a new one."""
        try:
            self.http_client.close()
        except Exception:
            pass
        self.http_client = httpx.Client(timeout=GENERAL_TIMEOUT)
        logger.info("HTTP client refreshed due to connection error")

    def _should_refresh_on_error(self, error: Exception) -> bool:
        """Check if an error suggests the HTTP client should be refreshed."""
        error_msg = str(error).lower()
        return any(keyword in error_msg for keyword in [
            "disconnected",
            "connection reset",
            "connection closed",
            "broken pipe",
            "connection aborted"
        ])

    def _log_info_once_per_second(self, message: str):
        """Log message at most once per second to avoid flooding."""
        if not hasattr(self, '_last_log_times'):
            self._last_log_times = {}

        current_time = time.time()
        if message in self._last_log_times:
            if current_time - self._last_log_times[message] < 1:
                return
        self._last_log_times[message] = current_time

        # Clean up old entries
        cutoff = current_time - 1
        self._last_log_times = {k: v for k, v in self._last_log_times.items() if v > cutoff}

        logger.info(message)

    def _cleanup_expired_episodes(self):
        """Remove expired episode records that have been expired for CLEAN_RECORD_TIMEOUT seconds."""
        current_time = time.time()
        expired_episodes = [
            ep_id for ep_id, exp_time in self.episode_expiry_times.items()
            if exp_time < current_time - CLEAN_RECORD_TIMEOUT
        ]
        for ep_id in expired_episodes:
            self.episode_expiry_times.pop(ep_id, None)

    def _check_throttle_policy(self, policy, pool_info) -> Tuple[bool, str]:
        """
        Check if the client should throttle based on the throttle policy.
        Returns: (should_throttle, reason)
        """
        if not policy:
            return False, ""

        current_task_id = getattr(policy, 'current_task_id', None)
        if not current_task_id:
            raise RuntimeError("Task_Ratio_Limit requires current_task_id to be set.")

        # Count completed tasks
        task_set = set()
        alien_task_set = set()
        task_counts = {}

        completed_tasks = getattr(pool_info, 'completed_tasks_client_uuids', {})
        for task_id, uuid_list in completed_tasks.items():
            for uuid_val in uuid_list:
                task_counts[task_id] = task_counts.get(task_id, 0) + 1
                if uuid_val != self.client_uuid:
                    alien_task_set.add(task_id)
                if uuid_val == self.client_uuid:
                    task_set.add(task_id)
                    break

        # Process running episodes if available
        running_episodes = getattr(pool_info, 'running_episode_details', None)
        if running_episodes:
            for ep_id, ep_detail in running_episodes.items():
                cuuid = ep_detail.get("client_uuid", "")
                tid = ep_detail.get("optional_task_id", "")
                task_counts[tid] = task_counts.get(tid, 0) + 1
                if cuuid != self.client_uuid:
                    alien_task_set.add(tid)
                if tid and cuuid == self.client_uuid:
                    task_set.add(tid)
        else:
            # No running episodes - check completed tasks
            total_completed = sum(1 for count in task_counts.values() 
                                if count >= getattr(policy, 'expected_num_repeat', 1))
            if total_completed < getattr(policy, 'expected_batch_size', 0):
                return False, ""

        # Skip throttling if task was recently seen
        if current_task_id in self.recent_tasks:
            return False, ""

        # Check if same task already exists in batch
        if current_task_id in task_set or current_task_id in alien_task_set:
            return False, ""

        # Calculate unique tasks for this client
        real_unique_tasks = task_set - alien_task_set
        n_unique = len(real_unique_tasks)
        max_allowed = getattr(policy, 'expected_batch_size', 0) * getattr(policy, 'ratio', 1.0)

        if n_unique >= max_allowed:
            reason = f"Throttling because there are already {n_unique} unique tasks in the batch, which meets/exceeds the threshold of {max_allowed} for task_id {current_task_id}."
            return True, reason

        return False, ""

    def _remember_task(self, task_id: str, batch_size: int, num_repeat: int):
        """Remember a task ID for throttling purposes."""
        buffer_size = batch_size * num_repeat * 3
        if task_id not in self.recent_tasks:
            self.recent_tasks.append(task_id)
            if len(self.recent_tasks) > buffer_size:
                self.recent_tasks = self.recent_tasks[-buffer_size:]

    def _should_throttle(self, policy, pool_info) -> bool:
        """Determine if episode claiming should be throttled."""
        should_throttle, _ = self._check_throttle_policy(policy, pool_info)
        if not should_throttle:
            self._remember_task(
                getattr(policy, 'current_task_id', ''), 
                getattr(policy, 'expected_batch_size', 1),
                getattr(policy, 'expected_num_repeat', 1)
            )
        return should_throttle

    def begin_episode(self, discard_timeout=240, episode_type="train", throttle_policy=None) -> Tuple[str, dict]:
        """
        Block until an episode is claimed.
        Returns: (episode_uuid, api_config_dict)
        """
        return self._begin_with_retry(discard_timeout, episode_type, throttle_policy)

    def _begin_with_retry(self, discard_timeout=240, episode_type="train", throttle_policy=None) -> Tuple[str, dict]:
        max_episode_time = 8 * discard_timeout
        status, _ = self.get_engine_status()

        if status != "ENGINE.ROLLING":
            self._log_info_once_per_second(f"Engine status is {status}. Waiting until ENGINE.ROLLING...")
            self._wait_for_status("ENGINE.ROLLING", verbose=False)

        retry_delay = 0

        while True:
            if retry_delay > 0:
                time.sleep(retry_delay)
                status, _ = self.get_engine_status()
                if status != "ENGINE.ROLLING":
                    self._log_info_once_per_second(f"Engine status is {status}. Waiting until ENGINE.ROLLING...")
                    self._wait_for_status("ENGINE.ROLLING", verbose=False)

            # Throttle handling
            if throttle_policy and episode_type == "train":
                pool_info = self.get_rollout_stat()
                if self._should_throttle(throttle_policy, pool_info):
                    self._log_info_once_per_second("Throttle policy is active, delaying episode ...")
                    retry_delay = TROTTLE_EPISODE_RETRY_DELAY
                    continue

            # Claim episode
            req_data = {
                "client_uuid": self.client_uuid,
                "episode_type": episode_type,
                "discard_episode_timeout": discard_timeout,
                "throttle_policy": throttle_policy.model_dump() if throttle_policy else None
            }

            try:
                resp = self.http_client.post(
                    f"{self.server_url}/claim_episode",
                    json=req_data
                )
                handle_http_error(resp)

                data = json.loads(resp.text)
                episode_uuid = data.get("episode_uuid")

                if episode_uuid:
                    self.episode_expiry_times[episode_uuid] = time.time() + max_episode_time
                    self._cleanup_expired_episodes()

                    if data.get("success"):
                        base_url = data.get("openai_base_url", "")
                        api_key = data.get("openai_api_key", "")

                        # Replace host with server URL
                        base_url = re.sub(r'^https?://[^/]+', self.server_url, base_url)

                        self._log_info_once_per_second(f"Claimed episode {episode_uuid}")
                        return episode_uuid, {
                            "base_url": base_url,
                            "api_key": api_key,
                            "episode_uuid": episode_uuid
                        }
                    else:
                        fail_cause = data.get("fail_cause", "")
                        need_snap = ["Engine is syncing weights", "Engine is in post-rolling phase"]
                        need_wait = ["No available episodes to claim."]

                        if any(scenario in fail_cause for scenario in need_snap):
                            if time.time() - self.last_warning_time > 60:
                                self._log_info_once_per_second(f"{fail_cause}. Retrying ...")
                                self.last_warning_time = time.time()
                            retry_delay = START_EPISODE_RETRY_DELAY
                            continue
                        elif any(scenario in fail_cause for scenario in need_wait):
                            retry_delay = WAIT_MORE_AVAIL_EPISODE_RETRY_DELAY
                            continue
                        else:
                            logger.warning(f"Failed to claim episode: {fail_cause}. Retrying ...")
                            retry_delay = START_EPISODE_RETRY_DELAY
                            continue

            except Exception as e:
                logger.error(f"Error claiming episode: {e}. Retrying ...")
                retry_delay = START_EPISODE_RETRY_DELAY
                continue

    def end_episode(self, task, episode_uuid: str, workflow_output):
        """End an episode and report results back to the server."""
        if not episode_uuid:
            logger.error("No episode to end.")
            return

        if episode_uuid in self.episode_expiry_times:
            remaining = self.episode_expiry_times.pop(episode_uuid, 0) - time.time()
            if remaining < 0:
                logger.warning(f"Episode {episode_uuid} has expired ({-remaining}s ago). Aborting.")
                self.abort_episode(episode_uuid)
                return
        else:
            logger.warning(f"Episode {episode_uuid} has expired. Aborting.")
            self.abort_episode(episode_uuid)
            return

        # Prepare request
        task_id = getattr(task, 'task_id', '')
        output_dict = workflow_output.model_dump() if hasattr(workflow_output, 'model_dump') else {}
        output_dict["metadata"]["task_id"] = task_id

        req_data = {
            "client_uuid": self.client_uuid,
            "episode_uuid": episode_uuid,
            "workflow_output": output_dict,
            "task_id": task_id
        }

        try:
            resp = self.http_client.post(
                f"{self.server_url}/end_episode",
                json=req_data
            )
            handle_http_error(resp)

            result = json.loads(resp.text)
            if result.get("success"):
                self._log_info_once_per_second(f"Ended episode {episode_uuid}")
            else:
                logger.error(f"Failed to end episode {episode_uuid}")
                raise RuntimeError(f"Failed to end episode {episode_uuid}")
        except Exception as e:
            logger.error(f"Error ending episode: {e}")

    def abort_episode(self, episode_uuid: str):
        """Abort an episode."""
        if not episode_uuid:
            logger.error("No episode to abort.")
            return

        try:
            req_data = {
                "client_uuid": self.client_uuid,
                "episode_uuid": episode_uuid,
                "workflow_output": {"reward": 0.0, "metadata": {}},
                "task_id": ""
            }

            resp = self.http_client.post(
                f"{self.server_url}/abort_episode",
                json=req_data
            )
            handle_http_error(resp)

            result = json.loads(resp.text)
            if result.get("success"):
                self._log_info_once_per_second(f"Aborted episode {episode_uuid}")
            else:
                logger.error(f"Failed to abort episode {episode_uuid}")
        except Exception as e:
            logger.error(f"Error aborting episode: {e}")

    def get_engine_status(self) -> Tuple[str, dict]:
        """Get current engine status from the server."""
        try:
            resp = self.http_client.get(
                f"{self.server_url}/get_engine_status",
                timeout=10
            )
            handle_http_error(resp)

            data = json.loads(resp.text)
            status = data.get("engine_status", "unknown")
            detail = data.get("engine_status_detail", {})

            if status == "unknown":
                logger.warning(f"get_engine_status returned unknown: {data}")

            return status, data
        except Exception as e:
            if self._should_refresh_on_error(e):
                self._refresh_http_client()
            logger.error(f"Error getting engine status: {e}")
            return "ENGINE.CANNOT_CONNECT", {}

    def _wait_for_status(self, desired_status="ENGINE.ROLLING", verbose=True, timeout=3600):
        """Wait until engine reaches desired status."""
        if verbose:
            self._log_info_once_per_second(f"Polling engine status until {desired_status}...")

        last_report = time.time()
        start_time = last_report
        initial_status, _ = self.get_engine_status()

        while True:
            try:
                current_status, _ = self.get_engine_status()
                current_time = time.time()

                if current_time - start_time >= timeout:
                    raise TimeoutError(f"Timeout waiting for {desired_status}")

                if (initial_status == "ENGINE.OFFLINE" and 
                    current_status == "ENGINE.OFFLINE" and 
                    desired_status != "ENGINE.OFFLINE"):
                    raise SwarmServerOfflineError(
                        f"Engine went offline while waiting for {desired_status}"
                    )

                if current_time - last_report >= 30:
                    if verbose:
                        elapsed = int(current_time - start_time)
                        self._log_info_once_per_second(f"Current engine status (waited {elapsed}s): {current_status}")
                    last_report = current_time

                if current_status == desired_status:
                    if verbose:
                        self._log_info_once_per_second(f"Engine status is {desired_status}.")
                    break

                time.sleep(5)

            except SwarmServerOfflineError:
                raise
            except Exception as e:
                logger.error(f"Error polling engine status: {e}")
                time.sleep(5)

    def sync_train_config(self, agent_job):
        """Sync training configuration to the server."""
        status, _ = self.get_engine_status()

        if status != "ENGINE.OFFLINE":
            raise RuntimeError(f"Cannot sync config when engine is {status}")

        try:
            config_dict = agent_job.config.to_dict() if hasattr(agent_job.config, 'to_dict') else {}
            yaml_str = yaml.safe_dump(config_dict, sort_keys=False)

            req_data = {"yaml_as_string": yaml_str}
            resp = self.http_client.post(
                f"{self.server_url}/sync_train_config",
                json=req_data
            )
            handle_http_error(resp)

            self._log_info_once_per_second("Synced train config to Swarm server")
        except Exception as e:
            logger.error(f"Error syncing train config: {e}")
            raise

    def start_engine(self):
        """Start the training engine."""
        status, _ = self.get_engine_status()

        if status != "ENGINE.OFFLINE":
            raise RuntimeError(f"Cannot start engine when it's {status}")

        try:
            resp = self.http_client.post(
                f"{self.server_url}/start_engine",
                json={},
                timeout=600
            )
            handle_http_error(resp)

            result = json.loads(resp.text)
            if result.get("success"):
                self._log_info_once_per_second("Successfully started training engine")
            else:
                logger.error("Failed to start training engine")
                raise RuntimeError("Failed to start training engine")

            self._wait_for_status("ENGINE.ROLLING")
            logger.success("Training engine is now ROLLING and ready.")
        except Exception as e:
            logger.error(f"Error starting engine: {e}")
            raise

    def stop_engine(self):
        """Stop the training engine."""
        status, _ = self.get_engine_status()

        if status == "ENGINE.OFFLINE":
            self._log_info_once_per_second("Engine is already OFFLINE.")
            return

        try:
            resp = self.http_client.post(
                f"{self.server_url}/stop_engine",
                json={},
                timeout=600
            )
            handle_http_error(resp)

            result = json.loads(resp.text)
            if result.get("success"):
                self._log_info_once_per_second("Successfully stopped training engine")
            else:
                logger.error("Failed to stop training engine")
                raise RuntimeError("Failed to stop training engine")

            self._wait_for_status("ENGINE.OFFLINE")
        except Exception as e:
            logger.error(f"Error stopping engine: {e}")
            raise

    def get_rollout_stat(self) -> dict:
        """Get current rollout statistics."""
        try:
            resp = self.http_client.get(
                f"{self.server_url}/get_current_batch_rollout_pool_information",
                timeout=10
            )
            handle_http_error(resp)

            data = json.loads(resp.text)
            return data
        except Exception as e:
            logger.error(f"Error getting rollout stats: {e}")
            return {}

    def print_rollout_stat(self):
        """Print rollout statistics in readable format."""
        try:
            stat = self.get_rollout_stat()
            completed_tasks = stat.get("completed_tasks_details", {})

            episodes_per_task = []
            task_buffer = ""
            for task_id, episode_list in completed_tasks.items():
                episodes_per_task.append(len(episode_list))
                task_buffer += f"Task-{task_id} ({len(episode_list)})  "

            avg_episodes = sum(episodes_per_task) / len(episodes_per_task) if episodes_per_task else 0.0

            stats = {
                "Completed tasks: (current) / (required)": 
                    f"{stat.get('completed_tasks', 0)} / {stat.get('completed_task_target', 0)}",
                "Completed episodes: (current) / (required)": 
                    f"{stat.get('completed_episodes', 0)} / {stat.get('completed_episode_target', 0)}",
                "Average episodes per task: (current) / (expected)": 
                    f"{avg_episodes:.2f} / {stat.get('task_expected_num_repeat', 0)}",
                "Completed num-dummy tasks: (current) / (required)": 
                    f"{stat.get('completed_non_dummy_tasks', 0)} / {stat.get('completed_task_target', 0)}",
                "Tasks (Number of episodes completed for each task)": task_buffer,
                "Hint": f"Please run `ajet-swarm overwatch --swarm-url={self.server_url}` to get more details."
            }

            # Print formatted output
            print("=" * 60)
            print("Current Swarm Rollout Pool Information")
            print("=" * 60)
            for key, value in stats.items():
                print(f"{key}: {value}")
            print("=" * 60)
        except Exception:
            pass

def execute_episodes(tasks: List, func, max_workers=None, auto_retry=True):
    """Execute episodes concurrently with optional retry logic."""
    if not max_workers:
        max_workers = len(tasks)

    def retry_wrapper(fn, arg):
        while True:
            try:
                return fn(arg)
            except Exception as e:
                logger.exception(f"[execute_episodes] Error executing episode: {e}. Retrying...")

    results = []
    for task in tasks:
        if auto_retry:
            result = retry_wrapper(func, task)
        else:
            result = func(task)
        results.append(result)

    print(f"*** Batch results: Finished {len(results)} Episodes. ***")
    time.sleep(5)
    return results

def auto_train_with_dataset(dataset, swarm_client: SwarmClient, execute_agent, local_grpo_n=2, remote_batch_size=8):
    """Run automatic training loop with dataset."""
    def rollout(task):
        # Begin episode
        episode_uuid, api_config = swarm_client.begin_episode()

        # Execute agent
        workflow_output = execute_agent(task, api_config)

        # Report results
        swarm_client.end_episode(task, episode_uuid, workflow_output)

        # Print global status
        swarm_client.print_rollout_stat()

        return workflow_output.reward

    episodes = []
    for task in dataset.generate_training_tasks():
        for _ in range(local_grpo_n):
            episodes.append(task)

            if len(episodes) == (remote_batch_size * local_grpo_n):
                episode_results = execute_episodes(episodes, func=rollout, auto_retry=True)
                for episode, reward in zip(episodes, episode_results):
                    print(f"Episode for task {episode.task_id} completed with reward: {reward}")
                episodes.clear()

from functools import wraps
from typing import Callable, Optional, Dict, Any
import torch

# Import utility functions from rlinf.algorithms.utils
from rlinf.algorithms.utils import (
    calculate_scores,
    postprocess_embodied_advantages_outputs,
    postprocess_loss_metric,
    postprocess_reasoning_advantages_outputs,
    preprocess_embodied_advantages_inputs,
    preprocess_loss_inputs,
    preprocess_reasoning_advantages_inputs,
)

# Registry dictionaries for advantages and policy losses
ADVANTAGE_REGISTRY: Dict[str, Callable] = {}
POLICY_LOSS_REGISTRY: Dict[str, Callable] = {}


def register_advantage_function(name: str):
    """Decorator to register an advantage computation function."""
    def decorator(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        ADVANTAGE_REGISTRY[name.lower()] = wrapped
        return wrapped
    return decorator


def fetch_advantage_by_name(name: str) -> Callable:
    """Retrieve a registered advantage function by its identifier."""
    key = name.lower()
    if key not in ADVANTAGE_REGISTRY:
        raise ValueError(
            f"Advantage '{name}' is not registered. Available options: {list(ADVANTAGE_REGISTRY.keys())}"
        )
    return ADVANTAGE_REGISTRY[key]


def register_policy_loss_function(name: str):
    """Decorator to register a policy loss function."""
    def decorator(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        POLICY_LOSS_REGISTRY[name.lower()] = wrapped
        return wrapped
    return decorator


def retrieve_policy_loss_function(name: str) -> Callable:
    """Get a registered policy loss function by name."""
    key = name.lower()
    if key not in POLICY_LOSS_REGISTRY:
        raise ValueError(f"Loss '{name}' has not been registered.")
    return POLICY_LOSS_REGISTRY[key]


def compute_actor_loss(**config) -> tuple[torch.Tensor, dict]:
    """
    Centralized actor loss computation dispatcher.
    Handles preprocessing/postprocessing based on task type.
    """
    loss_kind = config["loss_type"]
    loss_module = retrieve_policy_loss_function(loss_kind)
    environment_mode = config["task_type"]

    if environment_mode == "embodied":
        config = preprocess_loss_inputs(**config)

    total_loss, metric_dict = loss_module(**config)

    if environment_mode == "embodied":
        metric_dict = postprocess_loss_metric(metric_dict)

    return total_loss, metric_dict


def estimate_advantage_and_return_values(**hyperparams) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    """
    Unified interface for computing advantages and returns across algorithms.
    Routes to appropriate implementation via registry after preprocessing inputs.
    """
    method_name = hyperparams["adv_type"]
    algorithm_fn = fetch_advantage_by_name(method_name)
    task_domain = hyperparams["task_type"]

    if task_domain == "embodied":
        hyperparams = preprocess_embodied_advantages_inputs(**hyperparams)
        if method_name != "gae":
            hyperparams = calculate_scores(**hyperparams)
        adv_vals, ret_vals = algorithm_fn(**hyperparams)
        result = postprocess_embodied_advantages_outputs(
            advantages=adv_vals, returns=ret_vals, **hyperparams
        )
    else:
        # reasoning tasks
        hyperparams = preprocess_reasoning_advantages_inputs(**hyperparams)
        adv_vals, ret_vals = algorithm_fn(**hyperparams)
        result = postprocess_reasoning_advantages_outputs(adv_vals, ret_vals)

    return result

# Custom error handling module for Castor Gateway API
# Ensures all gateway errors follow a consistent JSON structure

from __future__ import annotations
import logging
from fastapi import HTTPException, Request
from fastapi.responses import JSONResponse

# Configure logger for gateway error tracking
logger = logging.getLogger("OpenCastor.Gateway")

class CastorAPIError(Exception):
    """Custom exception to standardize API error responses.

    Raising this exception will automatically produce a structured JSON response
    with error message, code, and HTTP status without manual JSONResponse construction.
    """

    def __init__(self, error_code: str, error_message: str, http_status: int = 400):
        self.error_code = error_code
        self.error_message = error_message
        self.http_status = http_status
        super().__init__(error_message)

def install_error_handlers(api_app) -> None:
    """Register global exception handlers for the FastAPI application.

    This function should be invoked once during application initialization,
    after creating the app instance but before starting request processing.
    """

    # Handle Castor-specific API errors
    @api_app.exception_handler(CastorAPIError)
    async def _castor_exception_handler(request: Request, exc: CastorAPIError):
        return JSONResponse(
            status_code=exc.http_status,
            content={
                "error": exc.error_message,
                "code": exc.error_code,
                "status": exc.http_status
            },
        )

    # Handle FastAPI's built-in HTTP exceptions
    @api_app.exception_handler(HTTPException)
    async def _http_exception_handler(request: Request, exc: HTTPException):
        detail_msg = exc.detail if isinstance(exc.detail, str) else str(exc.detail)
        return JSONResponse(
            status_code=exc.status_code,
            content={
                "error": detail_msg,
                "code": f"HTTP_{exc.status_code}",
                "status": exc.status_code,
            },
        )

    # Catch-all handler for unhandled exceptions
    @api_app.exception_handler(Exception)
    async def _generic_exception_handler(request: Request, exc: Exception):
        logger.exception(
            "Unhandled exception in gateway at %s %s", 
            request.method, 
            request.url.path
        )
        return JSONResponse(
            status_code=500,
            content={
                "error": "Internal server error",
                "code": "INTERNAL_ERROR",
                "status": 500,
            },
        )

