# Agent directory structure analyzer - Type III clone
# Modified logic: uses different iteration patterns, variable names, and control flow

import json
import os
import sys
from collections import Counter

def inspect_agent_directory(agent_path):
    """Inspect and gather metadata from an agent's Python files."""
    output = {
        "file_list": [],
        "import_map": {},
        "class_list": [],
        "function_list": []
    }

    for dirpath, _, filenames in os.walk(agent_path):
        for filename in filenames:
            if filename.endswith(".py"):
                full_path = os.path.join(dirpath, filename)
                relative_path = os.path.relpath(full_path, agent_path)

                # Track file presence
                output["file_list"].append(relative_path)

                # Initialize import list for this file
                if relative_path not in output["import_map"]:
                    output["import_map"][relative_path] = []

                try:
                    with open(full_path, 'r', encoding='utf-8') as file_obj:
                        lines = file_obj.readlines()

                        # Process each line for imports
                        for line in lines:
                            stripped = line.strip()
                            if stripped.startswith("import ") or stripped.startswith("from "):
                                tokens = stripped.split()
                                if len(tokens) > 1:
                                    module_name = tokens[1]
                                    output["import_map"][relative_path].append(stripped)

                        # Detect class definitions
                        for line in lines:
                            stripped = line.strip()
                            if stripped.startswith("class "):
                                # Extract class name more robustly
                                class_part = stripped.replace("class ", "").split(":")[0]
                                if "(" in class_part:
                                    class_name = class_part.split("(")[0].strip()
                                else:
                                    class_name = class_part.strip()
                                output["class_list"].append(f"{relative_path}: {class_name}")

                        # Detect top-level function definitions only
                        for line in lines:
                            stripped = line.strip()
                            if stripped.startswith("def ") and not stripped.startswith("    def"):
                                func_part = stripped.replace("def ", "").split(":")[0]
                                if "(" in func_part:
                                    func_name = func_part.split("(")[0].strip()
                                else:
                                    func_name = func_part.strip()
                                output["function_list"].append(f"{relative_path}: {func_name}")
                except Exception:
                    continue

    return output

def process_all_agents(root_dir):
    """Process all directories that appear to be agent folders."""
    agent_data = {}

    for entry in os.listdir(root_dir):
        candidate_path = os.path.join(root_dir, entry)
        if os.path.isdir(candidate_path):
            # Check for typical agent files using alternative markers
            required_files = ["agent.py", "config.py", "state.py"]
            has_markers = any(
                os.path.isfile(os.path.join(candidate_path, marker))
                for marker in required_files
            )

            if has_markers:
                agent_data[entry] = inspect_agent_directory(candidate_path)

    return agent_data

def identify_shared_elements(analysis_results):
    """Identify elements common across multiple agents."""
    shared_items = set()
    first_iteration = True

    for agent_name, data in analysis_results.items():
        current_files = set(data["file_list"])

        if first_iteration:
            shared_items = current_files
            first_iteration = False
        else:
            shared_items &= current_files

    # Calculate frequency of files across all agents
    file_counter = Counter()
    for agent_data in analysis_results.values():
        for file_entry in agent_data["file_list"]:
            file_counter[file_entry] += 1

    sorted_frequencies = dict(sorted(file_counter.items(), key=lambda item: item[1], reverse=True))

    return {
        "shared_files": sorted(list(shared_items)),
        "file_occurrences": sorted_frequencies
    }

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(1)

    base_directory = sys.argv[1]
    if not os.path.isdir(base_directory):
        sys.exit(1)

    # Perform analysis
    agent_analysis = process_all_agents(base_directory)

    # Identify patterns
    pattern_summary = identify_shared_elements(agent_analysis)

    # Output results to JSON file
    with open("agent_inspection_report.json", "w") as report_file:
        json.dump(agent_analysis, report_file, indent=2)

import itertools
from dataclasses import dataclass, field
from enum import Enum, auto
from typing import TYPE_CHECKING, List, Self, Tuple
import torch

from vllm.config import VllmConfig
from vllm.distributed.kv_transfer.kv_connector.v1.base import (
    KVConnectorMetadata,
