@dataclass
class ChunkInfo:
    """Represents metadata about a chunked segment of tokens."""
    token_start_idx: int
    num_tokens_in_chunk: int
    block_start_idx: int
    num_blocks_in_chunk: int
    cached_position_offset: int
    block_hashes: List[bytes] = field(default_factory=list)
    hit_flags: List[bool] = field(default_factory=list)

    @property
    def token_end_idx(self) -> int:
        return self.token_start_idx + self.num_tokens_in_chunk

    @property
    def block_end_idx(self) -> int:
        return self.block_start_idx + self.num_blocks_in_chunk

    @property
    def cached_end_pos(self) -> int:
        return self.cached_position_offset + self.num_tokens_in_chunk

    @property
    def position_delta(self) -> int:
        return self.token_start_idx - self.cached_position_offset

    @property
    def matched_block_hashes(self) -> List[bytes]:
        return [h for h, hit in zip(self.block_hashes, self.hit_flags) if hit]

    @property
    def matched_vllm_ids(self) -> List[int]:
        # Assume vllm_blk_ids is populated elsewhere; here we simulate extraction
        return []

    def merge_with(self, other: Self) -> None:
        """Merge another chunk into this one."""
        self.num_tokens_in_chunk += other.num_tokens_in_chunk
        self.num_blocks_in_chunk += other.num_blocks_in_chunk
        self.block_hashes.extend(other.block_hashes)

    def adjust_for_partial_prefix(self, partial_blocks: int, blk_size: int) -> None:
        """Adjust chunk metadata when part of it overlaps with prefix cache."""
        if partial_blocks <= 0:
            return
        offset = partial_blocks * blk_size
        self.token_start_idx += offset
        self.num_tokens_in_chunk -= offset
        self.block_start_idx += partial_blocks
        self.num_blocks_in_chunk -= partial_blocks
        self.block_hashes = self.block_hashes[partial_blocks:]
        self.hit_flags = self.hit_flags[partial_blocks:]
        self.cached_position_offset += offset


class BlendMode(Enum):
    INITIALIZE_CHUNKS = auto()
    PREPARE_PREFIX = auto()
    MERGE_CACHES = auto()

    def is_merging(self) -> bool:
        return self == BlendMode.MERGE_CACHES

    def is_prefix_only(self) -> bool:
        return self == BlendMode.PREPARE_PREFIX


@dataclass
class BlendRequestState:
    ucm_hashes: List[bytes] = field(default_factory=list)
    prefix_hits: int = 0
    chunk_hits: int = 0
    chunk_infos: List[ChunkInfo] = field(default_factory=list)
    current_mode: BlendMode = BlendMode.PREPARE_PREFIX


@dataclass
class BlendDispatchMeta(RequestDispatchMeta):
    chunk_info_list: List[ChunkInfo]


@dataclass
class BlendUCMMetadata(UCMConnectorMetadata):
    request_states: dict[str, BlendDispatchMeta] = field(default_factory=dict)


class BlendUCMConnector(UCMDirectConnector):
    """
    Manages blending of chunked KV caches and prefix caching.
    """

    def __init__(self, vllm_config: "VllmConfig", role: KVConnectorRole):
        super().__init__(vllm_config, role)
        sparse_cfg = self.launch_config.get("ucm_sparse_config", {})
        self._blend_mode = BlendMode.PREPARE_PREFIX
        self._req_to_chunks: dict[str, List[ChunkInfo]] = {}
        self._chunk_boundary_token = None
        self._min_blend_threshold = 16
        self._delta_rope_vllm_ids = None
        self._delta_rope_positions = None
        self._cos_sin_table = None

        if "Blend" in sparse_cfg:
            blend_cfg = sparse_cfg["Blend"]
            self._chunk_boundary_token = blend_cfg.get("chunk_end_token_id")
            self._enable_blend = True
        else:
            raise RuntimeError("UCMBlendConnector initialization failed: missing 'Blend' config")

        self._blend_request_states: dict[str, BlendRequestState] = {}

    def _analyze_request_tokens(self, token_ids: List[int]) -> Tuple[BlendMode, List[bytes], List[ChunkInfo], List[bytes]]:
        """
        Analyze input tokens to detect chunk boundaries and build metadata.
        Returns mode, prefix hashes, chunk metadata, and all chunk hashes.
        """
        chunks = []
        prefix_hashes = self.generate_hash(self.block_size, token_ids, self._seed)

        # Check if full block-aligned chunk ending
        if (
            len(token_ids) % self.block_size == 0
            and token_ids[-1] == self._chunk_boundary_token
        ):
            return BlendMode.INITIALIZE_CHUNKS, prefix_hashes, chunks, []

        start_block = 0
        start_token = 0
        all_chunk_hashes = []

        for end_block in range(len(token_ids) // self.block_size):
            end_token = (end_block + 1) * self.block_size - 1
            if token_ids[end_token] == self._chunk_boundary_token:
                chunk_tokens = token_ids[start_token:end_token + 1]
                chunk_hashes = self.generate_hash(self.block_size, chunk_tokens, self._seed)
                chunk_len_tokens = len(chunk_tokens)
                chunk_len_blks = len(chunk_hashes)

                new_chunk = ChunkInfo(
                    token_start_idx=start_token,
                    num_tokens_in_chunk=chunk_len_tokens,
                    block_start_idx=start_block,
                    num_blocks_in_chunk=chunk_len_blks,
                    cached_position_offset=0,
                    block_hashes=chunk_hashes,
                )
                chunks.append(new_chunk)
                all_chunk_hashes.extend(chunk_hashes)

                start_block = end_block + 1
                start_token = end_token + 1

        if chunks:
            return BlendMode.MERGE_CACHES, prefix_hashes, chunks, all_chunk_hashes
        else:
            return BlendMode.PREPARE_PREFIX, prefix_hashes, [], []

    def _compute_hits(self, mode: BlendMode, prefix_hashes, chunk_meta, chunk_hashes) -> Tuple[int, int]:
        """Determine how many prefix and chunk blocks are already cached."""
        prefix_hits = 0
        chunk_hits = 0

        # First check prefix cache
        prefix_results = self.store.lookup(prefix_hashes)
        for hit in prefix_results:
            if not hit:
                break
            prefix_hits += 1

        if not mode.is_merging():
            return prefix_hits, chunk_hits

        # Then check remaining chunk hashes after prefix overlap
        suffix_hashes = chunk_hashes[prefix_hits:]
        chunk_results = self.store.lookup(suffix_hashes)
        chunk_hits = sum(chunk_results)

        # Update per-chunk hit flags
        for chunk in chunk_meta:
            start = chunk.block_start_idx
            end = chunk.block_end_idx
            chunk.hit_flags = prefix_results[:prefix_hits] + chunk_results[
                max(0, start - prefix_hits):max(0, end - prefix_hits)
            ]

        # Adjust first chunk for prefix overlap
        if chunk_meta:
            first = chunk_meta[0]
            first.adjust_for_partial_prefix(prefix_hits, self.block_size)
            if first.num_tokens_in_chunk == 0:
                chunk_meta.pop(0)

        return prefix_hits, chunk_hits

    def _build_dispatch_metadata(self, state: BlendRequestState, new_tokens: int, vllm_ids: List[int]) -> BlendDispatchMeta:
        """Construct dispatch metadata for loading/dumping based on current blend stage."""
        prefix_hit_count = state.prefix_hits
        ucm_hashes = state.ucm_hashes

        load_ucm, load_vllm = ucm_hashes[:prefix_hit_count], vllm_ids[:prefix_hit_count]
        dump_ucm, dump_vllm = [], []

        if state.current_mode.is_merging():
            for chunk in state.chunk_infos:
                chunk.matched_vllm_ids = vllm_ids[
                    chunk.block_start_idx : chunk.block_end_idx
                ]
                load_ucm.extend(chunk.matched_block_hashes)
                load_vllm.extend(chunk.matched_vllm_ids)
        else:
            dump_ucm = ucm_hashes[prefix_hit_count:]
            dump_vllm = vllm_ids[prefix_hit_count:len(dump_ucm)]

        return BlendDispatchMeta(
            (load_ucm, load_vllm),
            (dump_ucm, dump_vllm),
            state.chunk_infos,
        )

    def _apply_rope_correction(self, k_cache, vllm_ids, positions) -> None:
        """Apply delta RoPE correction to loaded chunk KV caches."""
        if self._cos_sin_table is None:
            raise RuntimeError("RoPE cos/sin table not initialized. Call setup_model().")
        block_wise_rope_forward(k_cache, vllm_ids, positions, self._cos_sin_table)

    def _capture_rotary_params(self, model: "Model") -> None:
        """Extract rotary embedding tables from model."""
        try:
            layer = model.model.layers[0].self_attn.rotary_emb
            self._cos_sin_table = layer.cos_sin_cache
        except Exception as e:
            raise RuntimeError(f"Failed to extract RoPE parameters: {e}")

    def setup_model(self, model: "Model") -> None:
        self._capture_rotary_params(model)

    def get_num_new_matched_tokens(
        self,
        request: "Request",
        num_computed_tokens: int,
    ) -> Tuple[int, bool]:
        assert num_computed_tokens == 0, "HBM prefix caching not supported"
        token_ids = request.all_token_ids
        total_blocks = len(token_ids) // self.block_size or 1

        mode, prefix_hashes, chunks, chunk_hashes = self._analyze_request_tokens(token_ids)
        prefix_hits, chunk_hits = self._compute_hits(mode, prefix_hashes, chunks, chunk_hashes)

        if chunk_hits < self._min_blend_threshold:
            mode = BlendMode.PREPARE_PREFIX
            chunks.clear()

        final_hashes = chunk_hashes if mode.is_merging() else prefix_hashes

        logger.info(
            f"request_id={request.request_id}, "
            f"blocks={total_blocks}, "
            f"mode={mode.name}, "
            f"prefix_hits={prefix_hits}, "
            f"chunk_hits={chunk_hits}"
        )

        if self.metrics_config:
            self.monitor.update_stats(
                "ConnStats",
                {"interval_lookup_hit_rates": chunk_hits / total_blocks},
            )

        prefix_tokens = prefix_hits * self.block_size
        if prefix_tokens == request.num_tokens:
            prefix_tokens -= 1

        self._blend_request_states[request.request_id] = BlendRequestState(
            ucm_hashes=final_hashes,
            prefix_hits=prefix_hits,
            chunk_hits=chunk_hits,
            chunk_infos=chunks,
            current_mode=mode,
        )
        return prefix_tokens, False

    def update_state_after_alloc(self, request: "Request", blocks: "KVCacheBlocks", num_external_tokens: int) -> None:
        pass  # Placeholder for future extension

    def build_connector_meta(self, scheduler_output: SchedulerOutput) -> KVConnectorMetadata:
        dispatch_map = {}

        for req in scheduler_output.scheduled_new_reqs:
            rid, vllm_ids = req.req_id, req.block_ids[0]
            state = self._blend_request_states.get(rid)
            if state:
                dispatch_map[rid] = self._build_dispatch_metadata(
                    state,
                    scheduler_output.num_scheduled_tokens[rid],
                    vllm_ids,
                )

        # Handle cached requests (resumed or chunked prefill)
        cached_reqs = scheduler_output.scheduled_cached_reqs
        if hasattr(cached_reqs, "req_ids"):
            for i, rid in enumerate(cached_reqs.req_ids):
                if scheduler_output.num_scheduled_tokens[rid] != 1:
                    state = self._blend_request_states.get(rid)
                    if state:
                        dispatch_map[rid] = self._build_dispatch_metadata(
                            state,
                            scheduler_output.num_scheduled_tokens[rid],
                            cached_reqs.new_block_ids[i][0],
                        )
        else:
            for req in cached_reqs:
                rid = req.request_id
                if scheduler_output.num_scheduled_tokens[rid] != 1:
                    state = self._blend_request_states.get(rid)
                    if state:
                        dispatch_map[rid] = self._build_dispatch_metadata(
                            state,
                            scheduler_output.num_scheduled_tokens[rid],
                            req.new_block_ids[0],
                        )

        # Cleanup finished requests
        for rid in scheduler_output.finished_req_ids:
            self._blend_request_states.pop(rid, None)

        return BlendUCMMetadata(dispatch_map)

    def bind_connector_metadata(self, meta: KVConnectorMetadata) -> None:
        super().bind_connector_metadata(meta)
        all_vllm_ids = []
        all_positions = []

        for rid, dispatch in meta.request_meta.items():
            for chunk in dispatch.chunk_info_list:
                all_vllm_ids.extend(chunk.matched_vllm_ids)
                all_positions.extend([chunk.position_delta] * len(chunk.matched_vllm_ids))

        if all_vllm_ids:
            self._delta_rope_vllm_ids = torch.tensor(all_vllm_ids, device=self.device)
            self._delta_rope_positions = torch.tensor(all_positions, device=self.device)

    def clear_connector_metadata(self) -> None:
        super().clear_connector_metadata()
        self._delta_rope_vllm_ids = None
        self._delta_rope_positions = None

    def wait_for_layer_load(self, layer_name: str) -> None:
        if self._delta_rope_vllm_ids is not None:
            k_cache = self.kv_caches[layer_name][0]
            self._apply_rope_correction(
                k_cache,
                self._delta_rope_vllm_ids,
                self._delta_rope_positions,
            )

import ast
import re
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple

class AutoDocstring:
    """Automatically generate docstrings for Python code elements."""

    def __init__(self):
        self.doc_count = 0
        self.ignore_count = 0

    def inspect_function(self, func_node: ast.FunctionDef) -> dict:
        """Examine function node to gather information for docstring creation."""
        details = {
            "identifier": func_node.name,
            "parameters": [],
            "output_type": None,
            "exceptions": set(),
            "is_coroutine": isinstance(func_node, ast.AsyncFunctionDef),
            "is_accessor": False,
            "is_class_method": False,
            "is_static_method": False,
            "has_generator": False,
            "difficulty": 0,
        }

        # Analyze decorators
        for dec in func_node.decorator_list:
            if isinstance(dec, ast.Name):
                if dec.id == "property":
                    details["is_accessor"] = True
                elif dec.id == "classmethod":
                    details["is_class_method"] = True
                elif dec.id == "staticmethod":
                    details["is_static_method"] = True

        # Collect parameter details
        for param in func_node.args.args:
            if param.arg not in ["self", "cls"]:
                param_info = {"name": param.arg, "type_hint": None, "default_val": None}
                if param.annotation:
                    param_info["type_hint"] = ast.unparse(param.annotation)
                details["parameters"].append(param_info)

        # Capture return type annotation
        if func_node.returns:
            details["output_type"] = ast.unparse(func_node.returns)

        # Examine function body content
        for element in ast.walk(func_node):
            # Detect raise statements
            if isinstance(element, ast.Raise):
                if isinstance(element.exc, ast.Call) and isinstance(
                    element.exc.func, ast.Name
                ):
                    details["exceptions"].add(element.exc.func.id)
                elif isinstance(element.exc, ast.Name):
                    details["exceptions"].add(element.exc.id)

            # Check for generator patterns
            if isinstance(element, ast.Yield | ast.YieldFrom):
                details["has_generator"] = True

            # Calculate cyclomatic complexity indicator
            if isinstance(element, ast.If | ast.For | ast.While | ast.Try):
                details["difficulty"] += 1

        return details

    def create_function_docstring(self, func_details: dict) -> str:
        """Produce a docstring based on function analysis."""
        segments = []

        # Create summary line
        summary_line = self._produce_summary(func_details)
        segments.append(f'"""{summary_line}')

        # Add detailed description for complex functions
        if func_details["difficulty"] > 3 or len(func_details["parameters"]) > 3:
            segments.append("")
            segments.append(self._produce_detailed_description(func_details))

        # Add parameters section
        if func_details["parameters"]:
            segments.append("")
            segments.append("Args:")
            for param in func_details["parameters"]:
                param_desc = self._produce_parameter_description(param)
                if param["type_hint"]:
                    segments.append(f"    {param['name']}: {param_desc}")
                else:
                    segments.append(f"    {param['name']}: {param_desc}")

        # Add return value section
        if func_details["output_type"] or not func_details["is_accessor"]:
            segments.append("")
            segments.append("Returns:")
            returns_desc = self._produce_return_description(func_details)
            segments.append(f"    {returns_desc}")

        # Add exceptions section
        if func_details["exceptions"]:
            segments.append("")
            segments.append("Raises:")
            for exc in sorted(func_details["exceptions"]):
                exc_desc = self._produce_exception_description(exc)
                segments.append(f"    {exc}: {exc_desc}")

        # Add yields section for generators
        if func_details["has_generator"]:
            segments.append("")
            segments.append("Yields:")
            segments.append("    Values produced by the generator.")

        # Add examples for public methods with moderate complexity
        if not func_details["identifier"].startswith("_") and func_details["difficulty"] > 2:
            segments.append("")
            segments.append("Examples:")
            segments.append(self._produce_example(func_details))

        segments.append('"""')
        return "\n".join(segments)

    def _produce_summary(self, func_details: dict) -> str:
        """Generate concise one-line function description."""
        identifier = func_details["identifier"]

        # Pattern matching for common naming conventions
        if identifier.startswith("get_"):
            return f"Retrieve {identifier[4:].replace('_', ' ')}."
        if identifier.startswith("set_"):
            return f"Assign {identifier[4:].replace('_', ' ')}."
        elif identifier.startswith("is_"):
            return f"Determine whether {identifier[3:].replace('_', ' ')}."
        elif identifier.startswith("has_"):
            return f"Check existence of {identifier[4:].replace('_', ' ')}."
        elif identifier.startswith("create_"):
            return f"Construct {identifier[7:].replace('_', ' ')}."
        elif identifier.startswith("update_"):
            return f"Modify {identifier[7:].replace('_', ' ')}."
        elif identifier.startswith("delete_"):
            return f"Remove {identifier[7:].replace('_', ' ')}."
        elif identifier.startswith("validate_"):
            return f"Verify {identifier[9:].replace('_', ' ')}."
        elif identifier.startswith("process_"):
            return f"Process {identifier[8:].replace('_', ' ')}."
        elif identifier.startswith("handle_"):
            return f"Manage {identifier[7:].replace('_', ' ')}."
        elif identifier == "__init__":
            return "Initialize the object instance."
        elif identifier == "__str__":
            return "Provide string representation of the object."
        elif identifier == "__repr__":
            return "Provide unambiguous representation of the object."
        elif func_details["is_accessor"]:
            return f"Access the {identifier.replace('_', ' ')} property."
        elif func_details["is_coroutine"]:
            return f"Execute {identifier.replace('_', ' ')} asynchronously."
        else:
            return f"{identifier.replace('_', ' ').capitalize()}."

    def _produce_detailed_description(self, func_details: dict) -> str:
        """Generate extended explanation for complex functions."""
        if func_details["is_coroutine"]:
            return "This asynchronous function must be awaited when called."
        if func_details["has_generator"]:
            return "This generator function produces values incrementally."
        elif func_details["difficulty"] > 5:
            return "This implementation involves intricate conditional logic."
        else:
            param_count = len(func_details['parameters'])
            return f"This function handles {param_count} input parameters to compute output."

    def _produce_parameter_description(self, param: dict) -> str:
        """Generate descriptive text for function parameters."""
        name = param["name"]
        param_type = param["type_hint"]

        # Type-based descriptions
        if param_type:
            if "str" in param_type:
                return f"The {name.replace('_', ' ')} string argument."
            if "int" in param_type:
                return f"The {name.replace('_', ' ')} integer value."
            elif "float" in param_type:
                return f"The {name.replace('_', ' ')} decimal number."
            elif "bool" in param_type:
                return f"Boolean flag indicating {name.replace('_', ' ')}."
            elif "List" in param_type:
                return f"Collection of {name.replace('_', ' ')}."
            elif "Dict" in param_type:
                return f"Mapping containing {name.replace('_', ' ')}."
            elif "Optional" in param_type:
                return f"Optional {name.replace('_', ' ')} value."

        # Name-based heuristics
        if name == "config":
            return "Configuration dictionary object."
        if name == "data":
            return "Input data to be processed."
        elif name == "context":
            return "Execution context information."
        elif name == "callback":
            return "Function to be invoked as callback."
        elif name.endswith("_id"):
            return f"Unique identifier for {name[:-3].replace('_', ' ')}."
        elif name.endswith("_path"):
            return f"Filesystem path to {name[:-5].replace('_', ' ')}."
        elif name.endswith("_url"):
            return f"Web address for {name[:-4].replace('_', ' ')}."
        else:
            return f"The {name.replace('_', ' ')} parameter."

    def _produce_return_description(self, func_details: dict) -> str:
        """Generate description for function return value."""
        return_type = func_details["output_type"]
        identifier = func_details["identifier"]

        if return_type:
            if return_type == "None":
                return "No value is returned."
            if return_type == "bool":
                return "Boolean result indicating success or failure."
            elif return_type == "str":
                return "String value representing the result."
            elif return_type == "int":
                return "Integer value computed by the function."
            elif return_type == "float":
                return "Floating-point value calculated by the function."
            elif "List" in return_type:
                return "Sequence of results."
            elif "Dict" in return_type:
                return "Dictionary with computed results."
            elif "Optional" in return_type:
                return "Result when available, otherwise None."
            else:
                return f"The {return_type} result object."

        # Inference from function name
        if identifier.startswith(("is_", "has_")):
            return "True when condition holds, False otherwise."
        if identifier.startswith(("get_", "find_")):
            return "The requested item or None if unavailable."
        elif identifier.startswith(("create_", "build_")):
            return "Newly instantiated object."
        elif func_details["is_accessor"]:
            return f"Current value of the {identifier.replace('_', ' ')} property."
        else:
            return "Processed output from the function."

    def _produce_exception_description(self, exc_name: str) -> str:
        """Generate description for possible exceptions."""
        exception_descriptions = {
            "ValueError": "When input does not meet expected format.",
            "TypeError": "When argument types are incompatible.",
            "KeyError": "When required key is absent from mapping.",
            "AttributeError": "When expected attribute is missing.",
            "RuntimeError": "When unexpected runtime condition occurs.",
            "NotImplementedError": "When functionality is not yet implemented.",
            "FileNotFoundError": "When specified file cannot be located.",
            "PermissionError": "When access rights are insufficient.",
            "ConnectionError": "When network connection fails.",
            "TimeoutError": "When operation exceeds time limit.",
        }
        return exception_descriptions.get(exc_name, f"When {exc_name.lower()} situation arises.")

    def _produce_example(self, func_details: dict) -> str:
        """Generate usage example for function."""
        identifier = func_details["identifier"]
        params = func_details["parameters"]

        # Construct example call
        if params:
            param_examples = []
            for param in params[:3]:  # Limit to first three parameters
                if param["type_hint"] and "str" in param["type_hint"]:
                    param_examples.append(f'"{param["name"]}_value"')
                elif param["type_hint"] and "int" in param["type_hint"]:
                    param_examples.append("42")
                elif param["type_hint"] and "bool" in param["type_hint"]:
                    param_examples.append("True")
                else:
                    param_examples.append(f"{param['name']}_value")
            args_str = ", ".join(param_examples)
            example = f"    >>> outcome = {identifier}({args_str})"
        else:
            example = f"    >>> outcome = {identifier}()"

        if func_details["is_coroutine"]:
            example = f"    >>> outcome = await {identifier}()"

        return example

    def inspect_class(self, class_node: ast.ClassDef) -> dict:
        """Analyze class node to extract relevant information."""
        details = {
            "name": class_node.name,
            "parents": [],
            "methods": [],
            "fields": [],
            "is_dataclass": False,
            "is_pydantic_model": False,
        }

        # Extract base classes
        for base in class_node.bases:
            if isinstance(base, ast.Name):
                details["parents"].append(base.id)
                if base.id in ["BaseModel", "BaseSettings"]:
                    details["is_pydantic_model"] = True

        # Check for dataclass decorator
        for decorator in class_node.decorator_list:
            if isinstance(decorator, ast.Name) and decorator.id == "dataclass":
                details["is_dataclass"] = True

        # Collect method names
        for member in class_node.body:
            if isinstance(member, ast.FunctionDef):
                details["methods"].append(member.name)

        return details

    def create_class_docstring(self, class_details: dict) -> str:
        """Generate docstring for a class definition."""
        segments = []
        name = class_details["name"]

        # Summary line
        if class_details["is_pydantic_model"]:
            segments.append(f'"""{name} Pydantic data model.')
        elif class_details["is_dataclass"]:
            segments.append(f'"""{name} data container.')
        elif class_details["parents"]:
            segments.append(f'"""{name} extending {", ".join(class_details["parents"])}.')
        else:
            segments.append(f'"""{name} implementation.')

        # Extended description
        segments.append("")
        if class_details["is_pydantic_model"]:
            segments.append("This model validates and serializes data using Pydantic library.")
        elif class_details["is_dataclass"]:
            segments.append("This dataclass provides convenient data storage with minimal boilerplate.")
        else:
            segments.append(
                f"This class implements {name.replace('_', ' ').lower()} behavior."
            )

        # Attributes section
        if class_details["fields"]:
            segments.append("")
            segments.append("Attributes:")
            for attr in class_details["fields"]:
                segments.append(f"    {attr}: Description of {attr}.")

        # Methods section
        if class_details["methods"]:
            public_methods = [m for m in class_details["methods"] if not m.startswith("_")]
            if public_methods:
                segments.append("")
                segments.append("Methods:")
                for method in public_methods[:5]:  # Limit to first five
                    segments.append(
                        f"    {method}: {method.replace('_', ' ').capitalize()}."
                    )

        segments.append('"""')
        return "\n".join(segments)

    def produce_module_docstring(self, file_path: Path) -> str:
        """Generate module-level documentation."""
        module_name = file_path.stem

        # Special cases for common module names
        if module_name == "__init__":
            parent = file_path.parent.name
            return f'"""Package initialization for {parent}."""'
        if module_name == "config":
            return '"""Module for application configuration management."""'
        elif module_name == "utils":
            return '"""Collection of utility helper functions."""'
        elif module_name == "models":
            return '"""Data models and schema definitions."""'
        elif module_name == "exceptions":
            return '"""Custom exception class definitions."""'
        elif module_name.startswith("test_"):
            return f'"""Test suite for {module_name[5:].replace("_", " ")}."""'
        else:
            return f'"""{module_name.replace("_", " ").capitalize()} module implementation."""'

    def process_file(self, file_path: Path, preview_mode: bool = False) -> bool:
        """Process a single Python file to add docstrings."""
        try:
            with open(file_path, encoding="utf-8") as source_file:
                content = source_file.read()

            # Parse AST
            tree = ast.parse(content)

            # Check for existing module docstring
            has_module_docstring = (
                isinstance(tree.body[0], ast.Expr)
                and isinstance(tree.body[0].value, ast.Constant)
                and isinstance(tree.body[0].value.value, str)
            )

            changes = []

            # Add module docstring if missing
            if not has_module_docstring:
                module_doc = self.produce_module_docstring(file_path)
                changes.append((0, 0, module_doc + "\n\n"))

            # Process functions and classes
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    if not ast.get_docstring(node):
                        func_details = self.inspect_function(node)
                        docstring = self.create_function_docstring(func_details)
                        indent = "    " * (node.col_offset // 4)
                        changes.append(
                            (node.lineno, node.col_offset, f"{indent}{docstring}")
                        )
                        self.doc_count += 1

                elif isinstance(node, ast.ClassDef) and not ast.get_docstring(node):
                    class_details = self.inspect_class(node)
                    docstring = self.create_class_docstring(class_details)
                    indent = "    " * (node.col_offset // 4)
                    changes.append(
                        (node.lineno, node.col_offset, f"{indent}{docstring}")
                    )
                    self.doc_count += 1

            if changes and not preview_mode:
                # Apply modifications
                lines = content.split("\n")
                # Sort by line number (descending) to avoid offset issues
                changes.sort(key=lambda x: x[0], reverse=True)

                for line_no, _col_offset, docstring in changes:
                    if line_no == 0:
                        # Module docstring
                        lines.insert(0, docstring)
                    else:
                        # Function/class docstring
                        lines.insert(line_no, docstring)

                # Write back to file
                with open(file_path, "w", encoding="utf-8") as target_file:
                    target_file.write("\n".join(lines))

                return True

            return bool(changes)

        except Exception as error:
            print(f"Error processing {file_path}: {error}")
            return False


def main():
    """Main entry point for the docstring generator."""
    import argparse

    parser = argparse.ArgumentParser(description="Automatically generate docstrings for Python files")
    parser.add_argument("target", help="File or directory to process")
    parser.add_argument(
        "--preview", action="store_true", help="Show what would be changed without modifying files"
    )
    args = parser.parse_args()

    generator = AutoDocstring()
    target_path = Path(args.target)

    if target_path.is_file():
        if generator.process_file(target_path, args.preview):
            print(f"Processed {target_path}")
    elif target_path.is_dir():
        python_files = list(target_path.rglob("*.py"))
        for file_path in python_files:
            if "__pycache__" not in str(file_path):
                if generator.process_file(file_path, args.preview):
                    print(f"Processed {file_path}")


if __name__ == "__main__":
    main()

import csv
import logging
import pickle
import re
import torch
import torchaudio
from speechbrain.dataio.dataset import DynamicItemDataset

logger = logging.getLogger(__name__)

# Supported audio formats via torchaudio
AUDIO_FORMATS = {"wav", "flac", "aac", "ogg", "mp3"}

# Suffix appended to CSV field names for internal storage
DATA_SUFFIX = "_data"

# Regex pattern for bash-style variable substitution
VARIABLE_PATTERN = re.compile(r"\$(\w+(?:\.\w+)*)")


class ExtendedCSVDataset(DynamicItemDataset):
    """
    Extended CSV compatibility wrapper for DynamicItemDataset.

    Requires 'ID' and 'duration' columns in the CSV.
    Additional fields must appear in triplets: <name>, <name>_format, <name>_opts.
    Each triplet defines a dynamic item named <name> that loads data from disk.

    Supports Bash-like $variable substitution via replacements dict.
    """

    def __init__(
        self,
        csv_path,
        replacements=None,
        sorting="original",
        min_duration=0.0,
        max_duration=36000.0,
        dynamic_items=None,
        output_keys=None,
    ):
        # Normalize defaults
        if replacements is None:
            replacements = {}
        if dynamic_items is None:
            dynamic_items = []
        if output_keys is None:
            output_keys = []

        # Validate sorting option
        valid_sortings = {"original", "ascending", "descending"}
        if sorting not in valid_sortings:
            raise ValueError(
                f"ExtendedCSVDataset does not support '{sorting}' sorting; "
                f"must be one of {valid_sortings}"
            )

        # Load CSV data and prepare dynamic items
        raw_data, extra_di_list, field_names = _load_sb_extended_csv(
            csv_path, replacements
        )

        # Initialize parent class with loaded data
        super().__init__(raw_data, dynamic_items, output_keys)
        self.pipeline.add_dynamic_items(extra_di_list)

        # Apply filtering and sorting
        sort_direction = -1 if sorting == "descending" else 1
        if sorting in ("ascending", "descending"):
            sorted_ids = sorted(
                self.data_ids,
                key=lambda x: self.data[x]["duration"],
                reverse=(sort_direction == -1),
            )
        else:
            sorted_ids = list(self.data_ids)  # preserve original order

        # Filter by duration bounds
        filtered_ids = [
            sid for sid in sorted_ids
            if min_duration <= self.data[sid]["duration"] <= max_duration
        ]

        self.data_ids = filtered_ids

        # Set default output keys if none specified
        if not output_keys:
            self.set_output_keys(field_names)


def _load_sb_extended_csv(csv_file, replacements):
    """
    Internal loader for SpeechBrain extended CSV format.

    Returns:
        data_dict: dict mapping ID -> {'duration': float, '<field>_data': ...}
        di_list: list of dicts describing dynamic items to add
        field_names: list of base field names (e.g., ['wav', 'txt'])
    """
    data_store = {}
    dynamic_items = []
    field_names = []

    with open(csv_file, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh, skipinitialspace=True)

        # Enforce required columns
        if not reader.fieldnames or reader.fieldnames[0] != "ID":
            raise ValueError("CSV must have an 'ID' column as first field")
        if len(reader.fieldnames) < 2 or reader.fieldnames[1] != "duration":
            raise ValueError("CSV must have a 'duration' column as second field")

        # Check triplet structure
        remaining_fields = reader.fieldnames[2:]
        if len(remaining_fields) % 3 != 0:
            raise ValueError(
                "All non-ID/duration fields must come in triplets: "
                "<name>, <name>_format, <name>_opts"
            )

        # Extract base field names (every third starting at index 2)
        field_names = [remaining_fields[i] for i in range(0, len(remaining_fields), 3)]

        # Process each row
        for row in reader:
            entry_id = row["ID"]
            if entry_id in data_store:
                raise ValueError(f"Duplicate ID '{entry_id}' found in CSV")

            # Store duration
            try:
                dur_val = float(row["duration"])
            except ValueError:
                raise ValueError(f"Invalid duration value for ID '{entry_id}': {row['duration']}")

            record = {"duration": dur_val}

            # Apply replacements to data fields only (not format/opts)
            for idx, base_name in enumerate(field_names):
                data_field = row.get(base_name, "")
                fmt_field = row.get(f"{base_name}_format", "")
                opts_field = row.get(f"{base_name}_opts", "")

                # Perform variable substitution on data field only
                substituted_data = _apply_replacements(data_field, replacements)

                # Store triplet under suffixed key
                triplet_key = f"{base_name}{DATA_SUFFIX}"
                record[triplet_key] = {
                    "path": substituted_data,
                    "fmt": fmt_field,
                    "opts": opts_field,
                }

            data_store[entry_id] = record

        # Build dynamic item specs
        for name in field_names:
            dynamic_items.append({
                "func": _read_csv_entry,
                "takes": f"{name}{DATA_SUFFIX}",
                "provides": name,
            })

    return data_store, dynamic_items, field_names


def _apply_replacements(text, repl_map):
    """Replace $var patterns in text using given replacement dictionary."""
    def replace_match(match):
        var_name = match.group(1)
        if var_name not in repl_map:
            raise KeyError(f"Missing replacement for variable '${var_name}'")
        return str(repl_map[var_name])

    return VARIABLE_PATTERN.sub(replace_match, text)


def _read_csv_entry(triplet):
    """
    Read data based on triplet info: path, format, options.
    Delegates to appropriate loader depending on format.
    """
    path = triplet["path"]
    fmt = triplet["fmt"]
    opts_str = triplet["opts"]

    # Parse options string into dict
    opts = _parse_opts(opts_str)

    # Dispatch based on format
    if fmt in AUDIO_FORMATS:
        waveform, _ = torchaudio.load(path)
        return waveform.squeeze(0).detach()
    elif fmt == "pkl":
        return _load_pickle(path, opts)
    elif fmt == "string":
        raw = path.encode("utf-8") if isinstance(path, str) else path
        decoded = raw.decode("utf-8")
        return decoded.strip().split() if decoded.strip() else []
    else:
        raise TypeError(f"Unsupported data format '{fmt}' encountered")


def _parse_opts(opt_string):
    """Parse space-separated key:value pairs like 'sr:16000 downsample:true'."""
    result = {}
    parts = opt_string.strip().split()
    for part in parts:
        if ":" not in part:
            continue  # skip malformed entries
        key, val = part.split(":", 1)
        result[key.strip()] = val.strip()
    return result


def _load_pickle(file_path, options):
    """Load tensor(s) from a .pkl file."""
    try:
        with open(file_path, "rb") as f:
            obj = pickle.load(f)
    except Exception as e:
        raise ValueError(f"Failed to load pickle file '{file_path}': {e}")

    # Convert lists to tensors
    if isinstance(obj, list):
        if not obj:
            return torch.empty(0)
        elem_type = type(obj[0])
        if elem_type is float:
            tensor = torch.tensor(obj, dtype=torch.float32)
        elif elem_type is int:
            tensor = torch.tensor(obj, dtype=torch.int64)
        elif elem_type is str:
            # Optional label-to-index mapping
            if "lab2ind" in options:
                lab2ind = eval(options["lab2ind"])  # insecure in real use!
                obj = [lab2ind.get(s, -1) for s in obj]
            tensor = torch.tensor(obj, dtype=torch.int64)
        else:
            raise TypeError(
                f"Pickle list must contain only ints/floats/strs; got {elem_type}"
            )
    else:
        tensor = obj

    # Downcast high-precision types
    if tensor.dtype == torch.float64:
        tensor = tensor.to(torch.float32)
    elif tensor.dtype == torch.int64:
        tensor = tensor.to(torch.int32)

    return tensor

import os
import platform
import subprocess
from pathlib import Path

from .helpers import (
    SOURCE_FNM,
    NotInstalledError,
    get_itk_dir,
    get_node_binaries_dir,
    get_nvm_dir,
    get_viewer_dir,
)


class SetupManager:
    """
    Manages cross-platform setup of ITK-VTK viewer dependencies: Node.js, npm, and the viewer package itself.
    Supports both system-wide and local installations depending on environment state.
    """

    def __init__(self):
        self.os_name = platform.system()
        self.base_dir = get_itk_dir()  # Root directory for qim3d.viz
        self.install_stage = 0  # 0: none installed, 1: node manager only, 2: full stack

        # Determine NVM directory: prefer env var if present, else local fallback
        raw_env_nvm = os.getenv('NVM_DIR')
        self.global_nvm_path = Path(raw_env_nvm) if raw_env_nvm else None
        self.local_nvm_path = get_nvm_dir(self.base_dir)
        self._ensure_directory_exists(self.local_nvm_path)

        # Set current working NVM dir (will be updated during detection)
        self.active_nvm_path = None

    @staticmethod
    def _ensure_directory_exists(path: Path):
        if not path.exists():
            path.mkdir(parents=True, exist_ok=True)

    def detect_node_manager(self) -> bool:
        """Check whether fnm or nvm is already available."""
        if self.os_name == 'Windows':
            try:
                result = subprocess.run(
                    ['powershell.exe', '-NoProfile', 'fnm', '--version'],
                    capture_output=True,
                    text=True,
                    timeout=5,
                )
                return result.returncode == 0
            except Exception:
                return False

        elif self.os_name in ('Linux', 'Darwin'):
            # Try global NVM first
            if self.global_nvm_path and self.global_nvm_path.joinpath('nvm.sh').exists():
                script_path = self.global_nvm_path / 'nvm.sh'
                cmd = f'/bin/bash -c "source {script_path} && nvm --version"'
                try:
                    res = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)
                    if not res.stderr and res.stdout.strip():
                        self.active_nvm_path = self.global_nvm_path
                        return True
                except Exception:
                    pass

            # Fallback to local NVM
            local_script = self.local_nvm_path / 'nvm.sh'
            if local_script.exists():
                cmd = f'/bin/bash -c "source {local_script} && nvm --version"'
                try:
                    res = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)
                    if not res.stderr and res.stdout.strip():
                        self.active_nvm_path = self.local_nvm_path
                        return True
                except Exception:
                    pass

        return False

    def detect_node_runtime(self) -> bool:
        """Check if Node.js/npm are functional."""
        if self.os_name == 'Windows':
            # Local-only mode enforced for Windows due to path complexity
            return False

        elif self.os_name in ('Linux', 'Darwin'):
            binaries = get_node_binaries_dir(self.active_nvm_path or self.local_nvm_path)
            if not binaries:
                return False

            env_path = os.environ.get('PATH', '')
            new_path = f"{env_path}{os.pathsep}{binaries}"
            try:
                proc = subprocess.run(
                    ['bash', '-c', f'export PATH="{new_path}" && npm --version'],
                    capture_output=True,
                    text=True,
                    timeout=10,
                    env={**os.environ, 'PATH': new_path},
                )
                return proc.returncode == 0 and proc.stdout.strip()
            except Exception:
                return False

        return False

    def run_installation_sequence(self):
        """Execute required installation steps based on current state."""
        # Detect existing components
        has_manager = self.detect_node_manager()
        has_runtime = self.detect_node_runtime()

        if has_manager:
            self.install_stage = 1
            print("Node version manager detected.")
            if has_runtime:
                self.install_stage = 2
                print("Node.js runtime detected.")
        else:
            self.install_stage = 0

        # Run remaining steps
        steps = [
            self._setup_node_manager,
            self._install_nodejs,
            self._deploy_viewer,
        ]
        for step in steps[self.install_stage:]:
            step()

    def _setup_node_manager(self):
        print(f"Installing Node manager at {self.local_nvm_path}...")
        if self.os_name == 'Windows':
            subprocess.run(
                [
                    'powershell.exe',
                    f'$env:XDG_DATA_HOME = "{self.base_dir}";',
                    'winget install Schniz.fnm',
                ],
                check=True,
            )
        elif self.os_name in ('Linux', 'Darwin'):
            script = self.base_dir / 'install_nvm.sh'
            env_vars = f"NVM_DIR={self.local_nvm_path}"
            full_cmd = f'{env_vars} bash "{script}"'
            subprocess.run(full_cmd, shell=True, check=True, executable='/bin/bash')

        print("Node manager installation complete.")

    def _install_nodejs(self):
        print("Setting up Node.js runtime...")
        if self.os_name == 'Windows':
            subprocess.run(
                [
                    'powershell.exe',
                    f'$env:XDG_DATA_HOME = "{self.base_dir}";',
                    SOURCE_FNM,
                    f'fnm use --fnm-dir {self.base_dir} --install-if-missing 22',
                ],
                check=True,
            )
        elif self.os_name in ('Linux', 'Darwin'):
            nvm_root = self.active_nvm_path or self.local_nvm_path
            nvm_sh = nvm_root / 'nvm.sh'

            prefix = ''
            if self.install_stage == 0:
                prefix = f'export NVM_DIR={nvm_root} && '

            cmd = f'{prefix}/bin/bash -c "source {nvm_sh} && nvm install 22"'
            subprocess.run(cmd, shell=True, check=True, executable='/bin/bash')

        print("Node.js installation complete.")

    def _deploy_viewer(self):
        target_dir = get_viewer_dir(self.base_dir)
        self._ensure_directory_exists(target_dir)

        print(f"Deploying itk-vtk-viewer to {target_dir}...")

        if self.os_name == 'Windows':
            bin_path = get_node_binaries_dir(self.base_dir)
            if bin_path:
                try:
                    subprocess.run(
                        [
                            'powershell.exe',
                            f"$env:PATH += ';{bin_path}'",
                            f'npm install --prefix "{target_dir}" @qim3d/itk-vtk-viewer',
                        ],
                        check=True,
                    )
                except subprocess.CalledProcessError:
                    raise NotInstalledError("Failed to install viewer locally.")
            else:
                # Global fallback attempt
                subprocess.run(
                    ['powershell.exe', SOURCE_FNM, 'npm install @qim3d/itk-vtk-viewer'],
                    check=True,
                )

        elif self.os_name in ('Linux', 'Darwin'):
            bin_dir = get_node_binaries_dir(self.active_nvm_path or self.local_nvm_path)
            if bin_dir:
                env_path = os.environ.get('PATH', '')
                new_path = f"{env_path}{os.pathsep}{bin_dir}"
                cmd = f'export PATH="{new_path}" && npm install --prefix "{target_dir}" @qim3d/itk-vtk-viewer'
                subprocess.run(cmd, shell=True, check=True, executable='/bin/bash')
            else:
                raise RuntimeError("Node binary directory unavailable for viewer install.")

        print("itk-vtk-viewer deployment finished.")


