import re
from dataclasses import dataclass
from typing import Any

def extract_version_numbers(version_string: str) -> tuple[int, int]:
    """Extract major and minor version numbers from a RenderDoc version string."""
    pattern = r"(\d+)\.(\d+)"
    result = re.search(pattern, version_string)
    if not result:
        return (0, 0)
    return (int(result.group(1)), int(result.group(2)))

@dataclass(frozen=True)
class RenderDocCompatibilityLayer:
    """Adapts RenderDoc API to handle version-specific differences."""
    replay_controller: Any
    version_info: tuple[int, int]

    def retrieve_root_events(self) -> Any:
        """Fetch root event actions using version-aware logic."""
        if self.version_info >= (1, 32) and hasattr(self.replay_controller, "GetRootActions"):
            return self.replay_controller.GetRootActions()
        if hasattr(self.replay_controller, "GetDrawcalls"):
            return self.replay_controller.GetDrawcalls()
        raise AttributeError("replay_controller lacks required methods: GetRootActions or GetDrawcalls")

    def fetch_api_details(self) -> Any:
        """Obtain API properties from the controller."""
        return self.replay_controller.GetAPIProperties()

    def list_all_resources(self) -> Any:
        """Retrieve all available resources."""
        return self.replay_controller.GetResources()

    def current_pipeline_state(self) -> Any:
        """Access current graphics/compute pipeline state."""
        return self.replay_controller.GetPipelineState()

    def structured_output_stream(self) -> Any:
        """Get structured logging/output stream."""
        return self.replay_controller.GetStructuredFile()

    def jump_to_event(self, event_id: int, immediate: bool = True) -> None:
        """Reposition replay cursor to specified event ID."""
        self.replay_controller.SetFrameEvent(event_id, immediate)

    def enumerate_textures(self) -> Any:
        """List all texture metadata."""
        return self.replay_controller.GetTextures()

    def enumerate_buffers(self) -> Any:
        """List all buffer metadata."""
        return self.replay_controller.GetBuffers()

    def terminate_replay(self) -> None:
        """Cleanly shut down the replay controller."""
        self.replay_controller.Shutdown()

import time
import os
import threading
from PyFT8.receiver import Receiver, AudioIn
from PyFT8.gui import Gui
from PyFT8.transmitter import AudioOut

# === Configuration & Initialization Helpers ===

def initialize_rig_control():
    try:
        from Rigctrl.rig import Rig
        print("Rig control module loaded successfully.")
        return Rig()
    except ImportError:
        print("Warning: Rig control not available.")
        return None

def load_or_create_config(filename='PyFT8.pkl'):
    import pickle
    if os.path.exists(filename):
        with open(filename, 'rb') as fh:
            return pickle.load(fh)
    else:
        callsign = input("Enter your amateur radio callsign: ")
        locator  = input("Enter your 4-character Maidenhead grid square: ")
        cfg = {'mStation': {'c': callsign, 'g': locator}}
        with open(filename, 'wb') as fh:
            pickle.dump(cfg, fh)
        return cfg

# === QSO Logging Module (Refactored) ===

class FT8_Contact:
    def __init__(self):
        self.remote_station = {}
        self.local_station = {}
        self.frequency_info = {'band': '20m', 'freq': 14.074}
        self.timestamps = {'start': None, 'end': None}
        self.signal_reports = {'tx': None, 'rx': None}

    def begin_session(self, config):
        self.local_station = config['mStation']
        self.remote_station.clear()

    def record_qso(self, log_file="PyFT8.adif"):
        # Prepare ADIF fields
        adif_data = {
            'call': self.remote_station.get('c', ''),
            'gridsquare': self.remote_station.get('g', ''),
            'mode': 'FT8',
            'operator': self.local_station['c'],
            'station_callsign': self.local_station['c'],
            'my_gridsquare': self.local_station['g'],
            'rst_sent': self.signal_reports['tx'],
            'rst_rcvd': self.signal_reports['rx'],
            'qso_date': time.strftime("%Y%m%d", self.timestamps['start']),
            'qso_date_off': time.strftime("%Y%m%d", self.timestamps['end']),
            'time_on': time.strftime("%H%M%S", self.timestamps['start']),
            'time_off': time.strftime("%H%M%S", self.timestamps['end']),
            'band': self.frequency_info['band'],
            'freq': self.frequency_info['freq']
        }

        # Ensure header exists
        if not os.path.exists(log_file):
            with open(log_file, 'w') as f:
                f.write("header <eoh>")

        # Append entry
        with open(log_file, 'a') as f:
            f.write("\n")
            for key, val in adif_data.items():
                sval = str(val) if val is not None else ''
                f.write(f"<{key}:{len(sval)}>{sval} ")
            f.write("<eor>\n")

# === Timing Utilities ===

def current_cycle_start():
    now = time.time()
    remainder = now % 15
    return int(now - remainder + 15)

def is_tx_window_active():
    cycle_time = time.time() % 15
    return 0.5 < cycle_time < 2.5

# === Message Parsing Logic (Reimplemented) ===

def contains_report(text):
    return '+' in text or '-' in text

def contains_response_report(text):
    return contains_report(text) and 'R' in text

def contains_double_response(text):
    return 'RRR' in text

def contains_double_seven_three(text):
    return 'RR73' in text

def contains_simple_seven_three(text):
    return '73' in text and not contains_double_seven_three(text)

def is_grid_locator(text):
    return not contains_report(text) and \
           not contains_simple_seven_three(text) and \
           not contains_double_seven_three(text) and \
           not contains_double_response(text)

# === Message Handling Core ===

def handle_received_message(decoded_msg, msg_origin_idx, snr_value, contact_obj, rig_obj, audio_out_obj, output_dev_id):
    start_of_cycle = current_cycle_start()
    if time.time() - start_of_cycle > 17.5:
        print("Message received too late; ignoring.")
        return

    parts = decoded_msg.split()
    if len(parts) < 4:
        return

    caller_a, caller_b, report, _ = parts[:4]
    local_station = config['mStation']

    response = ""
    if caller_a == "CQ":
        contact_obj.begin_session(config)
        contact_obj.timestamps['start'] = time.gmtime()
        contact_obj.remote_station = {'c': caller_b, 'g': report}
        response = f"{caller_b} {local_station['c']} {local_station['g']}"
        schedule_transmission(response, should_tx_now=is_tx_window_active(),
                              audio_out=audio_out_obj, dev=output_dev_id, rig=rig_obj)
        return

    if caller_a == local_station['c']:
        if not contact_obj.remote_station.get('c'):
            contact_obj.remote_station['c'] = caller_b

        if is_grid_locator(report):
            contact_obj.remote_station = {'c': caller_b, 'g': report}
            contact_obj.signal_reports['tx'] = f"{snr_value:+03d}"
            response = f"{contact_obj.remote_station['c']} {local_station['c']} {snr_value:+03d}"

        elif contains_report(report):
            contact_obj.signal_reports['rx'] = report[-3:]
            response = f"{contact_obj.remote_station['c']} {local_station['c']} R{snr_value:+03d}"

        elif contains_response_report(report) or contains_double_response(report):
            response = f"{contact_obj.remote_station['c']} {local_station['c']} RR73"

        elif contains_double_seven_three(report):
            response = f"{contact_obj.remote_station['c']} {local_station['c']} 73"

        if response:
            schedule_transmission(response, should_tx_now=is_tx_window_active(),
                                  audio_out=audio_out_obj, dev=output_dev_id, rig=rig_obj)

        if contains_simple_seven_three(report) or " 73" in response or contains_double_seven_three(report):
            contact_obj.timestamps['end'] = time.gmtime()
            contact_obj.record_qso()

# === Transmission Subsystem (Threaded) ===

def prepare_audio_for_message(msg_text, audio_output_instance):
    symbols = audio_output_instance.create_ft8_symbols(msg_text)
    waveform = audio_output_instance.create_ft8_wave(symbols)
    return waveform

def transmit_message_async(msg, audio_out, device_id, rig, immediate=False):
    thread = threading.Thread(target=transmit_message_sync,
                              args=(msg, audio_out, device_id, rig, immediate),
                              daemon=True)
    thread.start()

def transmit_message_sync(msg, audio_out, device_id, rig, immediate=False):
    print(f"Preparing to send: {msg}")
    if device_id is None:
        print("No valid output audio device configured.")
        return False

    audio_data = prepare_audio_for_message(msg, audio_out)

    if not immediate:
        delay = 15 - ((time.time() - 0.5) % 15)
        if delay > 0:
            time.sleep(delay)

    print("Activating PTT...")
    rig.ptt_on()
    audio_out.play_data_to_soundcard(audio_data, device_id)
    rig.ptt_off()
    print("Transmission complete.")
    return True

# === GUI Interaction Handlers ===

def on_gui_decode_event(event_data):
    if gui_instance:
        gui_instance.post_decode(event_data.h0_idx, event_data.f0_idx, event_data.msg, event_data.snr)
    print(f"{event_data.cyclestart_str} {event_data.snr} {event_data.dt:4.1f} {event_data.fHz} ~ {event_data.msg}")

def on_gui_button_click(btn_label, btn_origin, btn_params):
    global qso_instance
    if btn_label == "CQ":
        my_call, my_loc = config['mStation']['c'], config['mStation']['g']
        transmit_message_async(f"CQ {my_call} {my_loc}",
                               audio_out=audio_out_global,
                               device_id=output_device_idx,
                               rig=rig_global,
                               immediate=is_tx_window_active())
    elif btn_label == "Tx off":
        rig_global.ptt_off()
    elif 'm' in btn_label:
        band_name = btn_label
        freq_val = float(btn_params)
        qso_instance.frequency_info = {'band': band_name, 'freq': freq_val}
        rig_global.set_freq_Hz(int(1000 * 1000 * freq_val))

# === CLI Entry Point ===

def main_cli_entrypoint():
    global config, audio_in_global, audio_out_global, output_device_idx, rig_global, gui_instance, qso_instance

    import argparse
    parser = argparse.ArgumentParser(prog='PyFT8rx', description='FT8 decoder and transceiver')
    parser.add_argument('-i', '--inputcard_keywords', help='Keywords to match input sound card')
    parser.add_argument('-v', '--verbose', action='store_true', help='Enable verbose logging')
    parser.add_argument('-o', '--outputcard_keywords', help='Keywords to match output sound card')
    parser.add_argument('-n', '--no_gui', action='store_true', help='Disable GUI')
    parser.add_argument('-m', '--transmit_message', nargs='?', help='Transmit specified message')
    parser.add_argument('-w', '--wave_output_file', nargs='?', default='PyFT8.wav', help='Output WAV filename')

    args = parser.parse_args()

    output_device_idx = None
    gui_instance = None
    audio_out_global = None

    if args.outputcard_keywords:
        keywords = [k.strip() for k in args.outputcard_keywords.split(',')]
        audio_out_global = AudioOut()
        output_device_idx = audio_out_global.find_device(keywords)
        config = load_or_create_config()
        rig_global = initialize_rig_control()

    if args.transmit_message:
        success = transmit_message_sync(args.transmit_message,
                                        audio_out=audio_out_global,
                                        device_id=output_device_idx,
                                        rig=rig_global,
                                        immediate=is_tx_window_active())
        if not success:
            wave_path = args.wave_output_file
            audio_data = prepare_audio_for_message(args.transmit_message, audio_out_global)
            audio_out_global.write_to_wave_file(audio_data, wave_path)
            print(f"WAV file generated: {wave_path}")
    else:
        audio_in_global = AudioIn(3100)
        input_keywords = [k.strip() for k in args.inputcard_keywords.replace(' ', '').split(',')] if args.inputcard_keywords else []
        input_device_id = audio_in_global.find_device(input_keywords)

        if not input_device_id:
            print("Error: No suitable input audio device found.")
            return

        gui_instance = None if args.no_gui else Gui(
            audio_in_global.dBgrid_main, 4, 2, config['mStation'],
            lambda msg, origin, snr: handle_received_message(msg, origin, snr, qso_instance, rig_global, audio_out_global, output_device_id),
            on_gui_button_click
        )

        rx_engine = Receiver(audio_in_global, [200, 3100], on_gui_decode_event)
        audio_in_global.start_streamed_audio(input_device_id)

        if gui_instance is not None:
            qso_instance = FT8_Contact()
            gui_instance.plt.show()
        else:
            try:
                while True:
                    time.sleep(1)
            except KeyboardInterrupt:
                pass

# === Standalone Execution Hook ===

if __name__ == "__main__":
    import mock
    with mock.patch('sys.argv', ['pyft8', '-i Mic, CODEC', '-o Speak, CODEC']):
        main_cli_entrypoint()

# Type III Clone: EMATeacher implementation with structural & lexical variation

from __future__ import annotations
from typing import Any, Dict, Callable
import torch
from weathergen.model.ssl_target_processing import (
    DINOTargetProcessing,
    JEPATargetProcessing,
    iBOTPatchTargetProcessing,
)
from weathergen.train.target_and_aux_module_base import TargetAndAuxModuleBase, TargetAuxOutput


class EMATeacher(TargetAndAuxModuleBase):
    def __init__(self, student_model, teacher_ema_model, batch_sz, train_cfg, **extra_args):
        # Note: Teacher may differ structurally from student (e.g., JEPA).
        # We rely on external setup for correct EMA model creation.
        # Also, student_model.state_dict() ≠ ema_model.state_dict() due to sharding.
        self.teacher_ema = teacher_ema_model
        self.batch_size_val = batch_sz
        loss_cfg_list = [
            v.loss_fcts
            for k, v in train_cfg.losses.items()
            if v.type == "LossLatentSSLStudentTeacher"
        ]
        # Currently only one such loss term is supported
        ssl_target_handlers = build_ssl_target_processors(loss_cfg_list[0], train_cfg, **extra_args)
        self.target_processors = ssl_target_handlers
        self.reset()

    def reset(self, new_batch_size=None):
        self.teacher_ema.reset()
        if new_batch_size is not None:
            self.batch_size_val = new_batch_size

    def update_state_pre_backward(self, step_idx, data_batch, student_model, **kwargs) -> None:
        pass  # no-op for EMATeacher

    def update_state_post_opt_step(self, step_idx, data_batch, student_model, **kwargs) -> None:
        if getattr(self.teacher_ema, 'is_model_sharded', False):
            self.teacher_ema.ema_model.reshard()
        self.teacher_ema.update(step_idx, self.batch_size_val)

    def compute(self, batch_idx, data_batch, model_params, student_model) -> tuple[Any, Any]:
        with torch.no_grad():
            latent_preds = self.teacher_ema.forward_eval(model_params, data_batch).get_latent_prediction(0)
            processed_targets = {}
            for key in self.target_processors:
                proc_mod = self.target_processors[key]
                processed_targets[key] = proc_mod(latent_preds[key])
            # Gather auxiliary metadata per sample
            aux_data = [list(sample.meta_info.values())[0] for sample in data_batch.get_samples()]
            result = TargetAuxOutput(data_batch.get_output_len(), data_batch.get_output_idxs())
            result.latent = processed_targets
            result.aux_outputs = aux_data
            return result

    def to_device(self, dev) -> EMATeacher:
        for _, mod in self.target_processors.items():
            mod.to(dev)
        return self

    def get_current_beta(self, current_step: int) -> float:
        return self.teacher_ema.get_current_beta(current_step)


def build_ssl_target_processors(loss_specs: dict, training_config, **kwargs):
    # Dispatch table mapping loss name to constructor function
    dispatch_map: Dict[str, Callable] = {
        "iBOT": lambda cfg: iBOTPatchTargetProcessing(
            patch_out_dim=cfg["out_dim"],
            center_momentum=cfg["center_momentum"],
            student_temp=cfg["loss_extra_args"]["student_temp"],
            teacher_temp=cfg["teacher_temp"],
            teacher_style=cfg["teacher_style"],
        ),
        "DINO": lambda cfg: DINOTargetProcessing(
            out_dim=cfg["out_dim"],
            center_momentum=cfg["center_momentum"],
            student_temp=cfg["loss_extra_args"]["student_temp"],
            teacher_style=cfg["teacher_style"],
        ),
        "JEPA": lambda cfg: JEPATargetProcessing(),
    }

    result_dict = {}
    loss_keys = list(loss_specs.keys())
    idx = 0
    while idx < len(loss_keys):
        loss_key = loss_keys[idx]
        cfg_item = loss_specs[loss_key]
        if loss_key in dispatch_map:
            result_dict[loss_key] = dispatch_map[loss_key](cfg_item)
        else:
            # Skip unsupported loss types silently
            pass
        idx += 1
    return result_dict

import argparse
import json
import os
import sys
import numpy as np


def extract_layer_indices(json_data):
    """Extract unique layer indices from node keys in JSON data."""
    layers = set()
    for key in json_data.get("Nodes", {}):
        if key.startswith("model.layers."):
            parts = key.split(".")
            if len(parts) > 2:
                try:
                    layers.add(int(parts[2]))
                except ValueError:
                    continue
    return sorted(layers)


def determine_attn_and_cache_names(args):
    """Return attention and cache variable names based on model type."""
    if args.deepseek:
        return "mla_attn.mla_attn", "latent_cache_k", "latent_cache_k"
    else:
        return "self_attn", "k_cache", "v_cache"


def build_node_keys(layer_idx, attn_name, k_cache_name, v_cache_name):
    """Construct full node keys for relevant operations."""
    base = f"model.layers.{layer_idx}.self_attn.{attn_name}.impl"
    return {
        "matmul_av": f"{base}.matmul_av",
        "v_cache": f"{base}.{v_cache_name}",
        "matmul_qk": f"{base}.matmul_qk",
        "k_cache": f"{base}.{k_cache_name}"
    }


def get_node_input(node_dict, index=0, default=None):
    """Safely retrieve an input from a node dictionary."""
    inputs = node_dict.get("inputs", [])
    return inputs[index] if len(inputs) > index else default


def fix_node_inputs(json_data, layer_idx, args):
    """Fix incorrect cache inputs in a given layer's nodes."""
    attn_name, k_cache_name, v_cache_name = determine_attn_and_cache_names(args)
    keys = build_node_keys(layer_idx, attn_name, k_cache_name, v_cache_name)

    # Extract current inputs
    matmul_av_node = json_data["Nodes"].get(keys["matmul_av"], {})
    v_cache_node = json_data["Nodes"].get(keys["v_cache"], {})
    matmul_qk_node = json_data["Nodes"].get(keys["matmul_qk"], {})
    k_cache_node = json_data["Nodes"].get(keys["k_cache"], {})

    matmul_av_input = get_node_input(matmul_av_node, 1)
    v_cache_input = get_node_input(v_cache_node, 0)
    matmul_qk_input = get_node_input(matmul_qk_node, 1)
    k_cache_input = get_node_input(k_cache_node, 0)

    # Fix inputs if mismatched
    if matmul_av_input != v_cache_input:
        target_input = k_cache_input if args.deepseek else v_cache_input
        json_data["Nodes"][keys["matmul_av"]]["inputs"][1] = target_input

    if matmul_qk_input != k_cache_input:
        json_data["Nodes"][keys["matmul_qk"]]["inputs"][1] = k_cache_input


def load_json_file(filepath):
    """Load and return JSON content from file."""
    with open(filepath, 'r') as f:
        return json.load(f)


def save_json_file(filepath, data):
    """Save JSON data to file."""
    with open(filepath, 'w') as f:
        json.dump(data, f)


def convert_node_arrays(node_dict):
    """Convert all numeric arrays in node inputs/outputs/params to numpy arrays."""
    result = {}
    for layer_key, layer_data in node_dict.items():
        new_layer = {}
        for field in ["inputs", "outputs"]:
            if field in layer_data:
                new_layer[field] = [np.array(arr) for arr in layer_data[field]]
        if "params" in layer_data:
            new_layer["params"] = {}
            for param_key, param_val in layer_data["params"].items():
                if param_key == "weight":
                    new_layer["params"][param_key] = np.array(param_val)
        result[layer_key] = new_layer
    return result


def process_measurements(measurements_dir, output_dir, deepseek=False):
    """Process all measurement files in directory and apply fixes."""
    # List and filter files
    all_files = os.listdir(measurements_dir)
    range_files = [f for f in all_files if f.endswith('.json')
                   and 'MAXABS_HW' not in f and 'mod_list' not in f]
    scale_files = [f for f in all_files if f.endswith('.json')
                   and 'MAXABS_HW' in f and 'mod_list' not in f]

    print(range_files)
    print(scale_files)

    for filename in range_files + scale_files:
        src_path = os.path.join(measurements_dir, filename)
        dst_path = os.path.join(output_dir, os.path.basename(filename))

        # Load and fix JSON
        raw_data = load_json_file(src_path)
        fix_all_layers(raw_data, deepseek)
        save_json_file(dst_path, raw_data)

        # Convert arrays and save .npz
        fixed_npz_path = dst_path.replace('.json', '.npz')
        layers = convert_node_arrays(raw_data["Nodes"])
        npz_data = {
            "GlobalRank": raw_data["GlobalRank"],
            "LocalRank": raw_data["LocalRank"],
            "Mode": raw_data["Mode"],
            "Nodes": layers
        }
        np.savez(fixed_npz_path, **{"data": npz_data})

        print(f"Processed: {filename}")


def fix_all_layers(json_data, deepseek):
    """Apply cache input fixes across all layers."""
    layer_indices = extract_layer_indices(json_data)
    for idx in layer_indices:
        fix_node_inputs(json_data, idx, type('Args', (), {'deepseek': deepseek})())


def parse_arguments(argv):
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(
        description="Fix incorrect cache inputs in measurement JSONs",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter
    )
    parser.add_argument("-m", "--measurements", required=True,
                        help="Directory containing measurement JSON files")
    parser.add_argument("-o", "--output", default=os.getcwd(),
                        help="Output directory for fixed files")
    parser.add_argument("-d", "--deepseek", action="store_true",
                        help="Enable DeepSeek-specific handling")

    return parser.parse_args(argv)


def main(argv):
