from __future__ import annotations
from dataclasses import dataclass
from enum import Enum, auto

class TestQuality(Enum):
    """
    Quality levels for test suite evaluation.
    L0: Minimum - only positive tests required
    L1: Standard - positive and negative tests required
    L2: Full - positive, negative, and edge case tests required
    """
    BASIC = auto()
    STANDARD = auto()
    FULL = auto()

@dataclass(frozen=True)
class TestDistribution:
    """
    Represents the composition of a test suite in terms of test categories.
    Used to assess whether a test suite meets defined quality standards.

    Fields:
        happy_path: Count of successful execution path tests
        error_path: Count of exception/error handling tests
        boundary: Count of boundary/edge condition tests

    Constraints:
        All counts must be non-negative integers
        Total number of tests must be at least one
    """
    happy_path: int
    error_path: int
    boundary: int

    def __post_init__(self) -> None:
        # Validate types
        if not isinstance(self.happy_path, int):
            raise TypeError("happy_path must be an integer")
        if not isinstance(self.error_path, int):
            raise TypeError("error_path must be an integer")
        if not isinstance(self.boundary, int):
            raise TypeError("boundary must be an integer")

        # Validate values
        if self.happy_path < 0:
            raise ValueError("happy_path cannot be negative")
        if self.error_path < 0:
            raise ValueError("error_path cannot be negative")
        if self.boundary < 0:
            raise ValueError("boundary cannot be negative")
        if self.total_tests == 0:
            raise ValueError("Test suite must contain at least one test")

    @property
    def total_tests(self) -> int:
        """Total count of all test cases."""
        return self.happy_path + self.error_path + self.boundary

    @property
    def happy_ratio(self) -> float:
        """Percentage of happy path tests (rounded to 2 decimals)."""
        return round((self.happy_path / self.total_tests) * 100, 2)

    @property
    def error_ratio(self) -> float:
        """Percentage of error handling tests (rounded to 2 decimals)."""
        return round((self.error_path / self.total_tests) * 100, 2)

    @property
    def boundary_ratio(self) -> float:
        """Percentage of boundary condition tests (rounded to 2 decimals)."""
        return round((self.boundary / self.total_tests) * 100, 2)

    def satisfies(self, tier: TestQuality | str) -> bool:
        """
        Determine if this distribution meets the specified quality tier.

        Args:
            tier: Quality level to check against

        Returns:
            True if requirements for the tier are satisfied

        Tier Requirements:
            BASIC: At least one happy path test
            STANDARD: At least one happy path and one error path test
            FULL: At least one test from each category
        """
        # Handle string input
        if isinstance(tier, str):
            try:
                tier = TestQuality[tier.upper()]
            except KeyError:
                raise ValueError(f"Invalid quality tier: {tier}") from None

        # Check tier requirements
        if tier == TestQuality.BASIC:
            return self.happy_path > 0
        elif tier == TestQuality.STANDARD:
            return self.happy_path > 0 and self.error_path > 0
        elif tier == TestQuality.FULL:
            return self.happy_path > 0 and self.error_path > 0 and self.boundary > 0
        else:
            raise ValueError(f"Unknown quality tier: {tier}")

    def best_fit_tier(self) -> TestQuality:
        """
        Find the highest quality tier that this distribution satisfies.

        Returns:
            The most comprehensive tier that passes the satisfaction check
        """
        if self.satisfies(TestQuality.FULL):
            return TestQuality.FULL
        elif self.satisfies(TestQuality.STANDARD):
            return TestQuality.STANDARD
        else:
            return TestQuality.BASIC

    def __str__(self) -> str:
        """Human-readable summary of test distribution."""
        return f"H:{self.happy_path}/E:{self.error_path}/B:{self.boundary}"

    def __repr__(self) -> str:
        """Detailed representation for debugging."""
        return (
            f"TestDistribution(happy_path={self.happy_path}, "
            f"error_path={self.error_path}, boundary={self.boundary})"
        )

from partialjson.json_parser import JSONParser
from app.models.llm_model import LLMModel
from app.models.step import Step
from app.models.widget import Widget
from typing import List, Optional
from app.ai.context.builders.instruction_context_builder import InstructionContextBuilder
import json

class DashboardDesigner:
    def __init__(self, model: LLMModel, instruction_context_builder: InstructionContextBuilder) -> None:
        self.model_instance = LLM(model)
        self.context_generator = instruction_context_builder

    async def generate_dashboard(self, user_request: str, available_widgets: List[Widget], 
                                 analysis_steps: Optional[List[Step]], chat_history: str):
        parser = JSONParser()
        layout_design = {
            "intro_text": "",
            "components": [],
            "closing_note": ""
        }
        processed_ids = set()
        widget_details = []
        widget_lookup = {}

        if available_widgets:
            for w in available_widgets:
                widget_lookup[str(w.id)] = w
                widget_kind = getattr(w, 'type', 'unknown')
                data_schema = getattr(w, 'data_model', None)

                if not widget_kind or widget_kind == 'unknown':
                    if data_schema and isinstance(data_schema, dict):
                        widget_kind = data_schema.get('kind', 'unknown')

                col_info = 'N/A'
                if data_schema and isinstance(data_schema, dict):
                    cols = data_schema.get('fields', [])
                    if cols:
                        col_info = ", ".join([c.get('name', '?') for c in cols])

                widget_details.append(
                    f"Widget ID: {w.id}\n"
                    f"  Label: {w.title}\n"
                    f"  Category: {widget_kind}\n"
                    f"  Fields: {col_info}"
                )

            detailed_widgets_str = "\n\n".join(widget_details)
        else:
            detailed_widgets_str = "No widgets available for layout."

        steps_info = []
        if analysis_steps:
            for idx, s in enumerate(analysis_steps):
                action_name = getattr(s, 'action', getattr(s, 'name', 'Unknown'))
                description = getattr(s, 'description', getattr(s, 'prefix', 'No details.'))
                target_widget_id = getattr(s, 'widget_id', None)
                target_widget_title = widget_lookup.get(str(target_widget_id), None)
                target_title = target_widget_title.title if target_widget_title else "N/A"

                schema_summary = ""
                if hasattr(s, 'data_model') and s.data_model:
                    try:
                        dm_type = s.data_model.get('kind', 'N/A')
                        dm_fields = [f.get('name', 'N/A') for f in s.data_model.get('fields', [])]
                        schema_summary = f"\n  Data Type: {dm_type} | Fields: {', '.join(dm_fields)}"
                    except Exception:
                        schema_summary = "\n  (Failed to parse data schema)"

                steps_info.append(f"Step {idx+1}: ({action_name} → '{target_title}' [ID: {target_widget_id}])\n  Description: {description}{schema_summary}")

            steps_str = "\n\n".join(steps_info)
        else:
            steps_str = "No prior analysis steps recorded."

        # Build context using the standard builder pattern
        context_section = await self.context_generator.create()
        context_content = context_section.display()

        prompt_template = f"""
        You are a professional dashboard architect. Design an optimal dashboard layout based on:
        - User's request: "{user_request}"
        - Analysis performed: {steps_str}
        - Available components: {detailed_widgets_str}
        - Conversation history: {chat_history}

        **Design Principles**:
        1. Follow user instructions precisely as provided in the context section below.
        2. Create a logical flow: summary → details → insights.
        3. Use HTML formatting for text blocks only (no markdown).
        4. Grid system: 12 columns, integer coordinates only.

        **Context from User Instructions**:
        {context_content}

        **Layout Requirements**:
        - Use mosaic-style arrangements where appropriate
        - Text blocks should explain and connect data components
        - Ensure no overlapping blocks
        - Minimum component heights: charts ≥5 rows, tables ≥4 rows
        - All coordinates must be integers between 0-11 for x/width

        **Output Format**:
        {{
          "intro_text": "...",
          "components": [
            {{"type": "text", "html": "...", "x": N, "y": N, "w": N, "h": N}},
            {{"type": "widget", "id": "UUID", "x": N, "y": N, "w": N, "h": N}}
          ],
          "closing_note": "..."
        }}
        """

        accumulated_response = ""
        previous_layout = ""

        async for token in self.model_instance.stream_response(prompt_template):
            accumulated_response += token

            try:
                parsed_data = parser.parse(accumulated_response)
                if not parsed_data or not isinstance(parsed_data, dict):
                    continue

                changed = False

                # Update intro text
                new_intro = parsed_data.get("intro_text")
                if new_intro is not None and new_intro != layout_design["intro_text"]:
                    layout_design["intro_text"] = new_intro
                    changed = True

                # Update components incrementally
                if "components" in parsed_data and isinstance(parsed_data["components"], list):
                    temp_components = list(layout_design["components"])
                    comp_changed = False

                    for i, comp in enumerate(parsed_data["components"]):
                        if not isinstance(comp, dict):
                            continue

                        comp_type = comp.get("type")
                        coords = ["x", "y", "w", "h"]

                        if not comp_type or not all(k in comp for k in coords):
                            continue

                        comp_id = None
                        if comp_type == "widget":
                            wid = str(comp.get("id"))
                            if wid in widget_lookup:
                                comp_id = wid
                            else:
                                continue
                        elif comp_type == "text":
                            content_hash = hash(comp.get("html", ""))
                            comp_id = f"text_{i}_{content_hash}"
                        else:
                            continue

                        comp_with_id = {**comp, "internal_id": comp_id}

                        found_idx = -1
                        for j, existing in enumerate(temp_components):
                            if existing.get("internal_id") == comp_id:
                                found_idx = j
                                break

                        if found_idx != -1:
                            if temp_components[found_idx] != comp_with_id:
                                temp_components[found_idx] = comp_with_id
                                comp_changed = True
                        else:
                            temp_components.append(comp_with_id)
                            comp_changed = True

                    if comp_changed:
                        layout_design["components"] = temp_components
                        changed = True

                # Update closing note
                new_closing_raw = parsed_data.get("closing_note")
                if new_closing_raw and new_closing_raw.endswith("$."):
                    new_closing = new_closing_raw[:-2].strip()
                    if new_closing != layout_design["closing_note"]:
                        layout_design["closing_note"] = new_closing
                        changed = True

                current_json = json.dumps(layout_design, sort_keys=True)
                if changed and current_json != previous_layout:
                    yield layout_design
                    previous_layout = current_json

            except Exception:
                continue

        final_json = json.dumps(layout_design, sort_keys=True)
        if final_json != previous_layout:
            yield layout_design

# Custom block for managing sliding window buffers of context and decoded frames
from diffusers.modular_pipelines import ModularPipelineBlocks, PipelineState
from diffusers.modular_pipelines.modular_pipeline_utils import (
    ComponentSpec,
    InputParam,
    OutputParam,
)
import torch

class FrameBufferManagerBlock(ModularPipelineBlocks):
    @property
    def required_components(self) -> list[ComponentSpec]:
        return [
            ComponentSpec("noise_scheduler", torch.nn.Module),
        ]

    @property
    def summary(self) -> str:
        return "Manages sliding window buffers for context and decoded frames during video generation"

    @property
    def input_specs(self) -> list[InputParam]:
        return [
            InputParam(
                "latent_input",
                required=True,
                type_hint=torch.Tensor,
                description="Current denoised latent tensor",
            ),
            InputParam(
                "decoded_output",
                required=True,
                type_hint=torch.Tensor,
                description="Decoded video frames from current step",
            ),
            InputParam(
                "frame_offset",
                required=True,
                type_hint=int,
                description="Index of the first frame in the current processing chunk",
            ),
            InputParam(
                "context_buffer_capacity",
                type_hint=int,
                description="Maximum number of context frames to retain",
            ),
            InputParam(
                "output_buffer_capacity",
                type_hint=int,
                description="Maximum number of decoded frames to retain",
            ),
            InputParam(
                "context_history",
                type_hint=torch.Tensor,
                description="Existing buffer containing previous context frames",
            ),
            InputParam(
                "output_history",
                type_hint=torch.Tensor,
                description="Existing buffer containing previous decoded frames",
            ),
            InputParam(
                "initial_frame",
                type_hint=torch.Tensor,
                description="First frame in the entire sequence (used for initialization)",
            ),
        ]

    @property
    def output_specs(self) -> list[OutputParam]:
        return [
            OutputParam(
                "initial_frame",
                type_hint=torch.Tensor,
                description="Updated reference to the first frame",
            ),
            OutputParam(
                "context_history",
                type_hint=torch.Tensor,
                description="Updated buffer with new context frames",
            ),
            OutputParam(
                "output_history",
                type_hint=torch.Tensor,
                description="Updated buffer with new decoded frames",
            ),
        ]

    @torch.no_grad()
    def __call__(self, components, state: PipelineState) -> tuple[any, PipelineState]:
        local_state = self.extract_block_state(state)

        # Initialize initial frame if this is the first chunk
        if local_state.frame_offset == 0:
            local_state.initial_frame = local_state.latent_input[:, :1]

        # Update context frame buffer with new latents (sliding window)
        if hasattr(local_state, 'context_buffer_capacity') and local_state.context_buffer_capacity > 0:
            new_context = torch.cat([
                local_state.context_history,
                local_state.latent_input.to(
                    local_state.context_history.device,
                    local_state.context_history.dtype
                )
            ], dim=1)
            local_state.context_history = new_context[:, -local_state.context_buffer_capacity:]

        # Update decoded frame buffer with new outputs (sliding window)
        if hasattr(local_state, 'output_buffer_capacity') and local_state.output_buffer_capacity > 0:
            new_output = torch.cat([
                local_state.output_history,
                local_state.decoded_output.to(
                    local_state.output_history.device,
                    local_state.output_history.dtype
                )
            ], dim=1)
            local_state.output_history = new_output[:, -local_state.output_buffer_capacity:]

        # Save updated state back
        self.update_block_state(state, local_state)
        return components, state

