import collections
import os
import unicodedata
from typing import Iterable, List, Optional, Tuple
from ...tokenization_utils import PreTrainedTokenizer, _is_control, _is_punctuation, _is_whitespace
from ...utils import logging

logger = logging.get_logger(__name__)

VOCAB_FILE_NAME = {"tokenizer_file": "prophetnet.tokenizer"}

def basic_whitespace_split(text):
    """Performs minimal whitespace-based cleaning and tokenization."""
    text = text.strip()
    if not text:
        return []
    return text.split()

class SimpleTokenizer:
    """
    Implements simplified tokenization logic (case handling, accent removal, punctuation splitting).
    """
    def __init__(
        self,
        lowercase=True,
        fixed_tokens=None,
        handle_cjk=True,
        remove_accents=None,
        split_punctuation=True,
    ):
        self.fixed_tokens = set(fixed_tokens) if fixed_tokens else set()
        self.lowercase = lowercase
        self.handle_cjk = handle_cjk
        self.remove_accents = remove_accents
        self.split_punctuation = split_punctuation

    def process(self, input_text, additional_fixed=None):
        """Main tokenization pipeline."""
        combined_fixed = self.fixed_tokens.union(set(additional_fixed)) if additional_fixed else self.fixed_tokens

        cleaned = self._sanitize(input_text)
        if self.handle_cjk:
            cleaned = self._insert_spaces_for_cjk(cleaned)

        normalized = unicodedata.normalize("NFC", cleaned)
        raw_tokens = basic_whitespace_split(normalized)

        processed_tokens = []
        for token in raw_tokens:
            if token in combined_fixed:
                processed_tokens.append(token)
                continue

            # Apply case conversion and accent stripping
            current = token.lower() if self.lowercase else token
            if self.remove_accents is not False or (self.remove_accents and not self.lowercase):
                current = self._strip_diacritics(current)

            # Split on punctuation unless disabled or token is fixed
            subtokens = [current] if not self.split_punctuation else self._segment_on_punctuation(current, combined_fixed)
            processed_tokens.extend(subtokens)

        final_tokens = basic_whitespace_split(" ".join(processed_tokens))
        return final_tokens

    def _strip_diacritics(self, text):
        """Removes diacritical marks from characters."""
        decomposed = unicodedata.normalize("NFD", text)
        filtered = [ch for ch in decomposed if unicodedata.category(ch) != "Mn"]
        return "".join(filtered)

    def _segment_on_punctuation(self, text, fixed_set=None):
        """Splits text into segments at punctuation boundaries."""
        if not self.split_punctuation or (fixed_set and text in fixed_set):
            return [text]

        segments = []
        current_segment = []
        for char in text:
            if _is_punctuation(char):
                if current_segment:
                    segments.append("".join(current_segment))
                    current_segment = []
                segments.append(char)
            else:
                current_segment.append(char)

        if current_segment:
            segments.append("".join(current_segment))

        return [seg for seg in segments if seg]

    def _insert_spaces_for_cjk(self, text):
        """Inserts spaces around CJK characters."""
        result = []
        for char in text:
            code_point = ord(char)
            if self._is_cjk_codepoint(code_point):
                result.extend([" ", char, " "])
            else:
                result.append(char)
        return "".join(result)

    def _is_cjk_codepoint(self, cp):
        """Determines if a Unicode code point belongs to CJK ranges."""
        return (
            0x4E00 <= cp <= 0x9FFF or
            0x3400 <= cp <= 0x4DBF or
            0x20000 <= cp <= 0x2A6DF or
            0x2A700 <= cp <= 0x2B73F or
            0x2B740 <= cp <= 0x2B81F or
            0x2B820 <= cp <= 0x2CEAF or
            0xF900 <= cp <= 0xFAFF or
            0x2F800 <= cp <= 0x2FA1F
        )

    def _sanitize(self, text):
        """Filters out invalid characters and normalizes whitespace."""
        safe_chars = []
        for char in text:
            code = ord(char)
            if code == 0 or code == 0xFFFD or _is_control(char):
                continue
            safe_chars.append(" " if _is_whitespace(char) else char)
        return "".join(safe_chars)

class SubwordTokenizer:
    """Implements greedy longest-match-first WordPiece tokenization."""

    def __init__(self, vocabulary, unknown_token, max_word_length=100):
        self.vocab = vocabulary
        self.unk = unknown_token
        self.max_len = max_word_length

    def encode(self, text):
        """Converts text into subword units."""
        result = []
        for word in basic_whitespace_split(text):
            chars = list(word)
            if len(chars) > self.max_len:
                result.append(self.unk)
                continue

            pieces = []
            position = 0
            failed = False

            while position < len(chars):
                boundary = len(chars)
                candidate = None

                while position < boundary:
                    segment = "".join(chars[position:boundary])
                    if position > 0:
                        segment = "##" + segment

                    if segment in self.vocab:
                        candidate = segment
                        break
                    boundary -= 1

                if candidate is None:
                    failed = True
                    break

                pieces.append(candidate)
                position = boundary

            if failed:
                result.append(self.unk)
            else:
                result.extend(pieces)

        return result

def read_vocabulary(path):
    """Loads vocabulary from file into ordered mapping."""
    vocab = collections.OrderedDict()
    with open(path, "r", encoding="utf-8") as f:
        lines = f.readlines()

    for idx, line in enumerate(lines):
        token = line.rstrip("\n")
        vocab[token] = idx

    return vocab

class ProphetNetTokenizer(PreTrainedTokenizer):
    r"""
    Tokenizer based on WordPiece for ProphetNet models.
    Inherits core functionality from PreTrainedTokenizer.
    """
    vocab_files = VOCAB_FILE_NAME
    model_inputs = ["input_ids", "attention_mask"]

    def __init__(
        self,
        vocab_path: str,
        do_lower_case: Optional[bool] = True,
        enable_basic_tokenize: Optional[bool] = True,
        special_tokens: Optional[Iterable] = None,
        unknown_token: Optional[str] = "[UNK]",
        end_token: Optional[str] = "[SEP]",
        extra_sep_token: Optional[str] = "[X_SEP]",
        padding_token: Optional[str] = "[PAD]",
        masking_token: Optional[str] = "[MASK]",
        handle_cjk: Optional[bool] = True,
        remove_accents: Optional[bool] = None,
        **kwargs,
    ):
        if not os.path.isfile(vocab_path):
            raise ValueError(
                f"Vocabulary file not found at '{vocab_path}'. "
                "Use AutoTokenizer.from_pretrained() for pretrained models."
            )

        self.vocab_dict = read_vocabulary(vocab_path)
        self.id_to_token = collections.OrderedDict((idx, tok) for tok, idx in self.vocab_dict.items())
        self.use_basic_tokenizer = enable_basic_tokenize

        if enable_basic_tokenize:
            self.preprocessor = SimpleTokenizer(
                lowercase=do_lower_case,
                fixed_tokens=special_tokens,
                handle_cjk=handle_cjk,
                remove_accents=remove_accents,
            )

        self.subword_encoder = SubwordTokenizer(
            vocabulary=self.vocab_dict,
            unknown_token=str(unknown_token),
        )

        super().__init__(
            do_lower_case=do_lower_case,
            do_basic_tokenize=enable_basic_tokenize,
            never_split=special_tokens,
            unk_token=unknown_token,
            sep_token=end_token,
            additional_sep_token=extra_sep_token,
            pad_token=padding_token,
            mask_token=masking_token,
            tokenize_chinese_chars=handle_cjk,
            strip_accents=remove_accents,
            **kwargs,
        )

    @property
    def vocabulary_size(self):
        return len(self.vocab_dict)

    def get_full_vocab(self):
        return {**self.vocab_dict, **self.special_token_map}

    def _tokenize(self, text):
        tokens = []
        if self.use_basic_tokenizer:
            for part in self.preprocessor.process(text, self.all_special_tokens):
                if part in self.preprocessor.fixed_tokens:
                    tokens.append(part)
                else:
                    tokens.extend(self.subword_encoder.encode(part))
        else:
            tokens = self.subword_encoder.encode(text)
        return tokens

    def _map_token_to_index(self, token: str):
        return self.vocab_dict.get(token, self.vocab_dict.get(self.unk_token))

    def _map_index_to_token(self, index: int):
        return self.id_to_token.get(index, self.unk_token)

    def reconstruct_text(self, tokens):
        """Reconstructs readable string from token sequence."""
        joined = " ".join(tokens)
        cleaned = joined.replace(" ##", "").strip()
        return cleaned

    def compute_attention_mask(
        self,
        ids_0: List[int],
        ids_1: Optional[List[int]] = None,
        pre_masked: Optional[bool] = False,
    ) -> List[int]:
        """Generates attention mask indicating special tokens."""
        if pre_masked:
            return super().compute_attention_mask(ids_0, ids_1, pre_masked)

        if ids_1 is None:
            return [0] * len(ids_0) + [1]
        return [0] * len(ids_0) + [1] + [0] * len(ids_1) + [1]

    def generate_type_ids(
        self, 
        sequence_a: List[int], 
        sequence_b: Optional[List[int]] = None
    ) -> List[int]:
        """Creates token type IDs for single/pair sequences."""
        separator = [self.end_token_id]
        if sequence_b is None:
            return [0] * (len(sequence_a) + len(separator))
        return [0] * (len(sequence_a) + len(separator)) + [1] * (len(sequence_b) + len(separator))

    def export_vocabulary(self, directory: str, prefix: Optional[str] = None) -> Tuple[str]:
        index = 0
        output_path = os.path.join(
            directory, (prefix + "-" if prefix else "") + self.vocab_files["tokenizer_file"]
        ) if os.path.isdir(directory) else (prefix + "-" if prefix else "") + directory

        with open(output_path, "w", encoding="utf-8") as writer:
            for token, idx in sorted(self.vocab_dict.items(), key=lambda x: x[1]):
                if index != idx:
                    logger.warning(
                        f"Non-consecutive indices detected in vocabulary: {output_path}"
                    )
                    index = idx
                writer.write(token + "\n")
                index += 1
        return (output_path,)

    def prepare_input_sequence(
        self, 
        base_ids: List[int], 
        additional_ids: Optional[List[int]] = None
    ) -> List[int]:
        """Constructs final input sequence with special tokens."""
        if additional_ids is None:
            return base_ids + [self.end_token_id]
        return base_ids + [self.end_token_id] + additional_ids + [self.end_token_id]

# DeepThinking Memory System - Type III Clone
# Modified logic: Uses list comprehensions and generator expressions for filtering,
# alternative date parsing, and refactored tag indexing with set operations.

import sys
import os
import re
import json
import subprocess
from datetime import datetime
from pathlib import Path

MEMORY_DIR = Path.home() / ".deepthinking" / "memory"
ENGRAMS_FILE = MEMORY_DIR / "engrams.log"
INDEX_FILE = MEMORY_DIR / "tags.idx"

def ensure_dir():
    """Ensure memory directory and files exist."""
    MEMORY_DIR.mkdir(parents=True, exist_ok=True)
    ENGRAMS_FILE.touch(exist_ok=True)

def cmd_store(args):
    """Store a new engram. Usage: memory.py store <tags> <content>
    Tags are comma-separated. Example: memory.py store "fear,career" "User afraid of leaving stable job"
    """
    if len(args) < 2:
        print(json.dumps({"error": "usage: store <tags> <content>"}))
        return

    tags = args[0]
    content = " ".join(args[1:])
    ensure_dir()

    timestamp = datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
    entry_line = f"{timestamp} | {tags} | {content}\n"

    with open(ENGRAMS_FILE, "a", encoding="utf-8") as f:
        f.write(entry_line)

    _update_index(tags)
    total_engrams = sum(1 for _ in open(ENGRAMS_FILE, encoding="utf-8"))
    print(json.dumps({"stored": True, "tags": tags, "total_engrams": total_engrams}))

def cmd_search(args):
    """Search engrams using grep or fallback to Python.
    Usage: memory.py search <query> [--tags <tag>] [--after <date>] [--limit <n>]
    """
    if not args:
        print(json.dumps({"error": "usage: search <query> [--tags tag] [--after date] [--limit n]"}))
        return

    ensure_dir()
    if not ENGRAMS_FILE.exists() or ENGRAMS_FILE.stat().st_size == 0:
        print(json.dumps({"results": [], "count": 0}))
        return

    query = args[0]
    tags_filter = None
    after_date = None
    limit = 20

    i = 1
    while i < len(args):
        if args[i] == "--tags" and i + 1 < len(args):
            tags_filter = args[i + 1]
            i += 2
        elif args[i] == "--after" and i + 1 < len(args):
            after_date = args[i + 1]
            i += 2
        elif args[i] == "--limit" and i + 1 < len(args):
            limit = int(args[i + 1])
            i += 2
        else:
            i += 1

    # Use grep when available, otherwise use Python implementation
    try:
        result = subprocess.run(
            ["grep", "-i", "-n", query, str(ENGRAMS_FILE)],
            capture_output=True, text=True, timeout=5
        )
        raw_lines = result.stdout.strip().split("\n") if result.stdout.strip() else []
    except Exception:
        raw_lines = []
        with open(ENGRAMS_FILE, encoding="utf-8") as f:
            raw_lines = [
                f"{num}:{line.rstrip()}"
                for num, line in enumerate(f, 1)
                if query.lower() in line.lower()
            ]

    # Parse and filter results
    def parse_and_filter(raw_line):
        parts = raw_line.split(":", 1)
        if len(parts) < 2:
            return None

        line_content = parts[1]

        # Apply tag filter
        if tags_filter:
            tag_section = line_content.split("|")[1].strip() if "|" in line_content else ""
            if tags_filter.lower() not in tag_section.lower():
                return None

        # Apply date filter
        if after_date:
            line_date = line_content[:10]
            if line_date < after_date:
                return None

        return line_content.strip()

    filtered_results = [res for res in map(parse_and_filter, raw_lines) if res is not None]
    limited_results = filtered_results[:limit]

    print(json.dumps({
        "results": limited_results,
        "count": len(limited_results),
        "total_matches": len(filtered_results)
    }, ensure_ascii=False))

def cmd_themes(args):
    """Extract recurring themes from memory. Analyzes tag frequency and co-occurrence."""
    ensure_dir()
    if not ENGRAMS_FILE.exists():
        print(json.dumps({"themes": {}, "count": 0}))
        return

    tag_counts = {}
    cooccurrence = {}
    total = 0

    with open(ENGRAMS_FILE, encoding="utf-8") as f:
        for line in f:
            total += 1
            parts = line.split("|")
            if len(parts) < 3:
                continue

            tags = [t.strip().lower() for t in parts[1].split(",")]

            # Count individual tags
            for t in tags:
                tag_counts[t] = tag_counts.get(t, 0) + 1

            # Count co-occurring pairs
            for j in range(len(tags)):
                for k in range(j + 1, len(tags)):
                    pair = tuple(sorted([tags[j], tags[k]]))
                    cooccurrence[pair] = cooccurrence.get(pair, 0) + 1

    # Sort by frequency
    sorted_tags = sorted(tag_counts.items(), key=lambda x: -x[1])[:15]
    sorted_pairs = sorted(cooccurrence.items(), key=lambda x: -x[1])[:10]

    print(json.dumps({
        "total_engrams": total,
        "top_tags": {t: c for t, c in sorted_tags},
        "co_occurring": {f"{a}+{b}": c for (a, b), c in sorted_pairs}
    }, ensure_ascii=False))

def cmd_recent(args):
    """Show most recent N engrams. Usage: memory.py recent [n]"""
    n = int(args[0]) if args else 10
    ensure_dir()

    if not ENGRAMS_FILE.exists():
        print(json.dumps({"results": [], "count": 0}))
        return

    try:
        result = subprocess.run(
            ["tail", f"-{n}", str(ENGRAMS_FILE)],
            capture_output=True, text=True, timeout=5
        )
        lines = [l.strip() for l in result.stdout.strip().split("\n") if l.strip()]
    except Exception:
        with open(ENGRAMS_FILE, encoding="utf-8") as f:
            all_lines = f.readlines()
        lines = [l.strip() for l in all_lines[-n:]]

    print(json.dumps({"results": lines, "count": len(lines)}, ensure_ascii=False))

def cmd_connect(args):
    """Find connections between two concepts. Searches for engrams containing both."""
    if len(args) < 2:
        print(json.dumps({"error": "usage: connect <concept1> <concept2>"}))
        return

    ensure_dir()
    c1, c2 = args[0].lower(), args[1].lower()

    matches = []
    c1_tags = set()
    c2_tags = set()

    with open(ENGRAMS_FILE, encoding="utf-8") as f:
        for line in f:
            low = line.lower()
            if c1 in low and c2 in low:
                matches.append(line.strip())

            parts = line.split("|")
            if len(parts) >= 3:
                tags = {t.strip().lower() for t in parts[1].split(",")}
                if c1 in low:
                    c1_tags.update(tags)
                if c2 in low:
                    c2_tags.update(tags)

    shared_tags = c1_tags & c2_tags

    print(json.dumps({
        "direct_matches": matches[:10],
        "shared_tags": list(shared_tags),
        "bridge_strength": len(shared_tags)
    }, ensure_ascii=False))

def cmd_stats(args):
    """Memory stats."""
    ensure_dir()
    if not ENGRAMS_FILE.exists():
        print(json.dumps({"total": 0, "size_bytes": 0}))
        return

    total = sum(1 for _ in open(ENGRAMS_FILE, encoding="utf-8"))
    size = ENGRAMS_FILE.stat().st_size

    first = last = ""
    with open(ENGRAMS_FILE, encoding="utf-8") as f:
        for line in f:
            if not first:
                first = line[:10]
            last = line[:10]

    print(json.dumps({
        "total_engrams": total,
        "size_bytes": size,
        "first_entry": first,
        "last_entry": last,
        "file": str(ENGRAMS_FILE)
    }))

def _update_index(tags):
    """Lightweight tag index for fast tag listing."""
    existing = set()
    if INDEX_FILE.exists():
        existing = set(INDEX_FILE.read_text().strip().split("\n"))

    new_tags = {t.strip().lower() for t in tags.split(",")}
    all_tags = existing.union(new_tags)

    INDEX_FILE.write_text("\n".join(sorted(all_tags)))

COMMANDS = {
    "store": cmd_store,
    "search": cmd_search,
    "themes": cmd_themes,
    "recent": cmd_recent,
    "connect": cmd_connect,
    "stats": cmd_stats,
}

def main():
    if len(sys.argv) < 2:
        print("Usage: memory.py <command> [args...]")
        print(f"Commands: {', '.join(COMMANDS.keys())}")
        sys.exit(1)

    cmd = sys.argv[1]
    args = sys.argv[2:]

    if cmd in COMMANDS:
        COMMANDS[cmd](args)
    else:
        print(json.dumps({"error": f"unknown command: {cmd}"}))
        sys.exit(1)

if __name__ == "__main__":
    main()

# Type III Clone: docstring-adder with modified logic and structure

from __future__ import annotations
import argparse
import ast
import contextlib
import importlib
import inspect
import io
import itertools
import subprocess
import sys
import textwrap
import types
import typing
from collections.abc import Sequence
from dataclasses import dataclass
from itertools import chain
from pathlib import Path
from typing import TypeVar, Optional
import libcst
import tomli
import typeshed_client
from rich_argparse import RawDescriptionRichHelpFormatter
from termcolor import colored
from typing_extensions import override

def log(*objects: object) -> None:
    """Log a warning to the terminal."""
    print(colored(" ".join(map(str, objects)), "yellow"))

DocumentableT = TypeVar("DocumentableT", libcst.ClassDef, libcst.FunctionDef)

def triple_quoted_docstring(content: str, indentation: str | None = None) -> str:
    """Escape the docstring and return it as a triple-quoted string.
    Logic adapted from `ast.unparse()` internals.
    """
    def escape_char(c: str) -> str:
        if c.isspace():
            return c
        if c == "\\" or not c.isprintable():
            return c.encode("unicode_escape").decode("ascii")
        return c

    newline_count = content.count("\n")
    if newline_count > 0:
        ends_with_newline = content.rstrip(" \t").endswith("\n")
        if ends_with_newline:
            if (
                newline_count == 1
                and content.strip()
                and content.rstrip(" \t")[-2] not in {'"', "'"}
            ):
                content = content.rstrip(" \t").removesuffix("\n")
        else:
            content = content.rstrip(" \t") + "\n"
            if indentation is not None:
                content += indentation
    escaped_string = "".join(map(escape_char, content))

    if not escaped_string:
        return '"' * 6

    quotes = ['"""', "'''"]
    possible_quotes = [q for q in quotes if q not in escaped_string]
    if not possible_quotes:
        string = repr(content)
        quote = next((q for q in quotes if string[0] in q), string[0])
        return f"{quote}{string[1:-1]}{quote}"

    possible_quotes.sort(key=lambda q: q[0] == escaped_string[-1])
    quote = possible_quotes[0]

    if quote == escaped_string[-1]:
        escaped_string = escaped_string[:-1] + "\\" + escaped_string[-1]
    return f"{quote}{escaped_string}{quote}"

@dataclass
class RuntimeValue:
    """An arbitrary value at runtime (that may or may not have a docstring)."""
    inner: object
    def is_not_found(self) -> bool:
        """Return `True` if the runtime object could not be found."""
        return self.inner is NOT_FOUND

@dataclass
class RuntimeParent:
    """Information regarding the namespace `DocstringAdder` is currently visiting."""
    name: str
    value: RuntimeValue

class DocstringAdder(libcst.CSTTransformer):
    """Visitor to add docstrings to a stub file."""
    def __init__(
        self,
        *,
        module_name: str,
        runtime_module: types.ModuleType,
        stub_file_path: Path,
        typeshed_client_context: typeshed_client.SearchContext,
        blacklisted_objects: frozenset[str],
    ) -> None:
        self.runtime_parents: list[RuntimeParent] = [
            RuntimeParent(name=module_name, value=RuntimeValue(inner=runtime_module))
        ]
        self.stub_file_path: Path = stub_file_path
        self.typeshed_client_context: typeshed_client.SearchContext = (
            typeshed_client_context
        )
        self.blacklisted_objects: frozenset[str] = blacklisted_objects
        self.suite_visitation_stack: list[set[str]] = [set()]
        self.if_stack: list[list[tuple[libcst.If, bool] | libcst.Else]] = []

    def visiting_reachable_code(self) -> bool:
        """Return `True` if we're currently visiting reachable code."""
        if not self.if_stack:
            return True
        for stack in self.if_stack:
            for entry in stack[:-1]:
                assert not isinstance(entry, libcst.Else)
                _, truthiness_of_test = entry
                if truthiness_of_test:
                    return False
            last_entry = stack[-1]
            if isinstance(last_entry, libcst.Else):
                continue
            else:
                _, truthiness_of_test = last_entry
                if not truthiness_of_test:
                    return False
        return True

    def maybe_mangled_name(self, name: str) -> str:
        """Apply name mangling to `name`, if it is necessary."""
        parent = self.runtime_parents[-1]
        if not isinstance(parent.value, type):
            return name
        if name.startswith("__") and not name.endswith("__"):
            return f"_{parent.name.lstrip('_')}{name}"
        return name

    @override
    def visit_ClassDef(self, node: libcst.ClassDef) -> None:
        """Visit a class definition node in the stub file."""
        runtime_object = get_runtime_object_for_stub(
            name=self.maybe_mangled_name(node.name.value),
            runtime_parent=self.runtime_parents[-1],
        )
        if runtime_object is None:
            self._log_runtime_object_not_found(node.name.value)
            runtime_object = RuntimeValue(NOT_FOUND)
        self.runtime_parents.append(
            RuntimeParent(name=node.name.value, value=runtime_object)
        )

    @override
    def leave_ClassDef(
        self, original_node: libcst.ClassDef, updated_node: libcst.ClassDef
    ) -> libcst.ClassDef:
        """Attempt to add a docstring to the class definition."""
        runtime_class = self.runtime_parents.pop().value
        if runtime_class.is_not_found():
            return original_node
        else:
            return self.document_class_or_function(
                updated_node=updated_node, runtime_object=runtime_class
            )

    def object_fullname(self, final_part: str) -> str:
        """Given an unqualified name, convert it to a fully qualified name."""
        parent_fullname = ".".join(parent.name for parent in self.runtime_parents)
        mangled_name = self.maybe_mangled_name(final_part)
        return f"{parent_fullname}.{mangled_name}"

    def _log_runtime_object_not_found(self, name: str) -> None:
        if self.visiting_reachable_code():
            log(f"Could not find {self.object_fullname(name)} at runtime")

    @override
    def leave_FunctionDef(
        self, original_node: libcst.FunctionDef, updated_node: libcst.FunctionDef
    ) -> libcst.FunctionDef:
        """Attempt to add a docstring to the function definition."""
        if original_node.name.value in self.suite_visitation_stack[-1]:
            return original_node
        self.suite_visitation_stack[-1].add(original_node.name.value)
        runtime_parent = self.runtime_parents[-1]
        if runtime_parent.value.is_not_found():
            return original_node
        runtime_object = get_runtime_object_for_stub(
            name=self.maybe_mangled_name(updated_node.name.value),
            runtime_parent=runtime_parent,
        )
        if runtime_object is None:
            self._log_runtime_object_not_found(updated_node.name.value)
            return original_node
        return self.document_class_or_function(
            updated_node=updated_node, runtime_object=runtime_object
        )

    @override
    def visit_IndentedBlock(self, node: libcst.IndentedBlock) -> None:
        """Hook called before visiting an `IndentedBlock` node."""
        self.suite_visitation_stack.append(set())

    @override
    def leave_IndentedBlock(
        self, original_node: libcst.IndentedBlock, updated_node: libcst.IndentedBlock
    ) -> libcst.IndentedBlock:
        """Hook called after an `IndentedBlock` node has been visited."""
        self.suite_visitation_stack.pop()
        if not self.visiting_reachable_code():
            return updated_node

        runtime_parent = self.runtime_parents[-1].value.inner
        if (
            isinstance(runtime_parent, type)
            and issubclass(runtime_parent, tuple)
            and hasattr(runtime_parent, "_fields")
        ):
            return updated_node

        return updated_node.with_changes(
            body=add_attribute_docstrings(
                updated_node.body,
                runtime_parent=self.runtime_parents[-1],
                blacklisted_objects=self.blacklisted_objects,
                indentation=len(self.suite_visitation_stack),
            )
        )

    @override
    def visit_If(self, node: libcst.If) -> None:
        """Hook called when the transformer visits an `if` statement."""
        condition_as_libcst_module = libcst.Module(
            body=[libcst.SimpleStatementLine(body=[libcst.Expr(value=node.test)])]
        )
        condition_as_ast_expr = ast.parse(condition_as_libcst_module.code).body[0]
        assert isinstance(condition_as_ast_expr, ast.Expr)
        parsed_condition = typeshed_client.evaluate_expression_truthiness(
            condition_as_ast_expr.value,
            ctx=self.typeshed_client_context,
            file_path=self.stub_file_path,
        )
        assert isinstance(parsed_condition, bool)
        if (
            self.if_stack
            and self.if_stack[-1][-1]
            and not isinstance(self.if_stack[-1][-1], libcst.Else)
            and self.if_stack[-1][-1][0].orelse is node
        ):
            self.if_stack[-1].append((node, parsed_condition))
        else:
            self.if_stack.append([(node, parsed_condition)])

    @override
    def leave_If(self, original_node: libcst.If, updated_node: libcst.If) -> libcst.If:
        """Hook called when the transformer leaves an `if` statement."""
        self.if_stack[-1].pop()
        if not self.if_stack[-1]:
            self.if_stack.pop()
        return updated_node

    @override
    def visit_Else(self, node: libcst.Else) -> None:
        """Hook called prior to visiting an `else` block."""
        if self.if_stack:
            last_if = self.if_stack[-1][-1]
            if not isinstance(last_if, libcst.Else) and node is last_if[0].orelse:
                self.if_stack[-1].append(node)

    @override
    def leave_Else(
        self, original_node: libcst.Else, updated_node: libcst.Else
    ) -> libcst.Else:
        """Hook called when the transformer leaves an `else` block."""
        if self.if_stack and self.if_stack[-1][-1] is original_node:
            self.if_stack[-1].pop()
        return updated_node

    def document_class_or_function(
        self, updated_node: DocumentableT, runtime_object: RuntimeValue
    ) -> DocumentableT:
        """Attempt to add a docstring to a class or function definition."""
        if not self.visiting_reachable_code():
            return updated_node
        object_fullname = self.object_fullname(updated_node.name.value)
        if object_fullname in self.blacklisted_objects:
            return updated_node
        if updated_node.get_docstring() is not None:
            return updated_node
        docstring = get_runtime_docstring(runtime=runtime_object)
        if docstring is None:
            return updated_node

        if (
            isinstance(updated_node, libcst.FunctionDef)
            and not isinstance(runtime_object.inner, types.ModuleType)
            and updated_node.name.value in object.__dict__
        ):
            method_docstring_on_object = get_runtime_docstring(
                runtime=RuntimeValue(inner=object.__dict__[updated_node.name.value])
            )
            if docstring == method_docstring_on_object:
                return updated_node

        docstring_node = libcst.Expr(
            libcst.SimpleString(triple_quoted_docstring(docstring))
        )

        if (
            isinstance(updated_node.body, libcst.SimpleStatementSuite)
            and len(updated_node.body.body) == 1
            and isinstance(updated_node.body.body[0], libcst.Expr)
            and isinstance(updated_node.body.body[0].value, libcst.Ellipsis)
        ):
            new_body = libcst.IndentedBlock(
                body=[libcst.SimpleStatementLine(body=[docstring_node])],
                header=updated_node.body.trailing_whitespace,
            )
        elif isinstance(updated_node.body, libcst.IndentedBlock):
            if (
                len(updated_node.body.body) == 1
                and isinstance(updated_node.body.body[0], libcst.Expr)
                and isinstance(updated_node.body.body[0].value, libcst.Ellipsis)
            ):
                new_body = updated_node.body.with_changes(
                    body=[libcst.SimpleStatementLine(body=[docstring_node])]
                )
            else:
                new_body = updated_node.body.with_changes(
                    body=list(
                        chain(
                            [libcst.SimpleStatementLine(body=[docstring_node])],
                            updated_node.body.body,
                        )
                    )
                )
        else:
            return updated_node

        return updated_node.with_changes(body=new_body)

def get_runtime_docstring(runtime: RuntimeValue) -> str | None:
    """Attempt to retrieve the docstring for a given runtime object."""
    runtime_object = runtime.inner
    try:
        runtime_docstring = runtime_object.__doc__
    except Exception:
        return None
    if not isinstance(runtime_docstring, str):
        return None

    if runtime_object is not staticmethod:
        assert runtime_docstring != staticmethod.__doc__, runtime
    if runtime_object is not classmethod:
        assert runtime_docstring != classmethod.__doc__, runtime
    if runtime_object is not property:
        assert runtime_docstring != property.__doc__, runtime

    if (
        runtime_object is not type
        and type(runtime_object).__module__ != "sys"
        and (
            runtime_docstring
            == get_runtime_docstring(RuntimeValue(type(runtime_object)))
        )
    ):
        return None
    return runtime_docstring

SuiteItemT = TypeVar(
    "SuiteItemT",
    "libcst.SimpleStatementLine | libcst.BaseCompoundStatement",
    "libcst.BaseSmallStatement | libcst.BaseStatement",
)

def final_statement_of_if(
    node: libcst.If,
) -> libcst.BaseStatement | libcst.BaseSmallStatement:
    """Retrieve the final statement of an `if`/`elif`/`else` chain."""
    if node.orelse is None:
        return node.body.body[-1]
    if isinstance(node.orelse, libcst.Else):
        return node.orelse.body.body[-1]
    return final_statement_of_if(node.orelse)

def add_attribute_docstrings(
    body: Sequence[SuiteItemT],
    *,
    runtime_parent: RuntimeParent,
    blacklisted_objects: frozenset[str],
    indentation: int,
) -> list[SuiteItemT]:
    """Add Sphinx-style 'attribute docstrings' to assignments in a suite."""
    new_body: list[SuiteItemT] = []
    added_docstring_to_previous = False
    for statement, next_statement in itertools.zip_longest(body, body[1:]):
        if (
            added_docstring_to_previous
            and isinstance(
                statement, (libcst.SimpleStatementLine, libcst.BaseCompoundStatement)
            )
            and all(line.comment is not None for line in statement.leading_lines)
        ):
            new_body.append(
                statement.with_changes(
                    leading_lines=[libcst.EmptyLine(), *statement.leading_lines]
                )
            )
        else:
            new_body.append(statement)
        added_docstring_to_previous = False

        if isinstance(statement, libcst.If):
            final_line = final_statement_of_if(statement)
            if (
                isinstance(final_line, libcst.SimpleStatementLine)
                and len(final_line.body) == 1
                and isinstance(final_line.body[0], libcst.Expr)
                and isinstance(final_line.body[0].value, libcst.SimpleString)
            ):
                added_docstring_to_previous = True
                continue

        if (
            isinstance(statement, libcst.SimpleStatementLine)
            and len(statement.body) == 1
            and not (
                isinstance(next_statement, libcst.SimpleStatementLine)
                and len(next_statement.body) == 1
                and isinstance(next_statement.body[0], libcst.Expr)
                and isinstance(next_statement.body[0].value, libcst.SimpleString)
            )
        ):
            assignment = statement.body[0]
            if isinstance(assignment, libcst.AnnAssign):
                target = assignment.target
            elif isinstance(assignment, libcst.Assign) and len(assignment.targets) == 1:
                target = assignment.targets[0].target
            else:
                continue
            if not isinstance(target, libcst.Name):
                continue

            runtime_name = target.value
            runtime_fullname = f"{runtime_parent.name}.{runtime_name}"
            if runtime_fullname in blacklisted_objects:
                continue
            runtime_value = get_runtime_object_for_stub(runtime_name, runtime_parent)
            if runtime_value is None:
                continue

            # Skip module docstrings
            if isinstance(runtime_value.inner, types.ModuleType):
                continue

            if isinstance(
                runtime_value.inner,
                (
                    type,
                    types.FunctionType,
                    types.BuiltinFunctionType,
                    types.GenericAlias,
                    types.MethodWrapperType,
                ),
            ):
                if isinstance(assignment, libcst.Assign):
                    continue
                if assignment.value is not None:
                    continue

                if (
                    isinstance(runtime_value.inner, (type, types.FunctionType))
                    and isinstance(assignment.annotation.annotation, libcst.Subscript)
                    and runtime_fullname != "typing.Generic"
                ):
                    continue

                try:
                    runtime_module = runtime_value.inner.__module__
                except Exception:
                    pass
                else:
                    if isinstance(runtime_parent.value.inner, types.ModuleType):
                        parent_module = runtime_parent.value.inner.__name__
                    else:
                        try:
                            parent_module = runtime_parent.value.inner.__module__
                        except Exception:
                            parent_module = None
                    if parent_module is not None and runtime_module != parent_module:
                        continue

            docstring = get_runtime_docstring(runtime_value)
            if docstring is None:
                continue

            docstring = docstring.strip(" \t")
            docstring_lines = docstring.split("\n")
            docstring = "\n".join([
                docstring_lines[0],
                textwrap.dedent("\n".join(docstring_lines[1:])),
            ])

            if indentation and "\n" in docstring:
                indentation_string = " " * indentation * 4
                docstring = (
                    textwrap.indent(docstring, prefix=indentation_string)
                    + indentation_string
                ).lstrip(" \t")
            else:
                indentation_string = None

            docstring_node = libcst.SimpleString(
                triple_quoted_docstring(docstring, indentation=indentation_string)
            )
            new_body.append(
                libcst.SimpleStatementLine(body=[libcst.Expr(docstring_node)])
            )
            added_docstring_to_previous = True

    return new_body

class NOT_FOUND:
    """Sentinel to indicate the runtime object for a stub definition could not be found."""

def get_runtime_object_for_stub(
    name: str, runtime_parent: RuntimeParent
) -> RuntimeValue | None:
    """Retrieve the runtime object corresponding to a stub definition."""
    if runtime_parent.value.inner is sys and name in {
        "_float_info",
        "_flags",
        "_int_info",
        "_hash_info",
        "_thread_info",
        "_version_info",
    }:
        name = name[1:]

    try:
        runtime = inspect.unwrap(
            inspect.getattr_static(runtime_parent.value.inner, name)
        )
        if (
            sys.version_info < (3, 10)
            and not isinstance(runtime, type)
            and hasattr(runtime, "__func__")
        ):
            runtime = runtime.__func__
    except Exception:
        return None

    if (
        isinstance(runtime, type(typing.Mapping))
        and runtime is not typing.Callable
        and runtime.__origin__.__module__ == "collections.abc"
    ):
        runtime = runtime.__origin__

    return RuntimeValue(inner=runtime)

def add_docstrings_to_stub(
    module_name: str,
    path: Path,
    context: typeshed_client.SearchContext,
    blacklisted_objects: frozenset[str],
) -> None:
    """Add docstrings to a stub module and all functions/classes in it."""
    print(f"Processing {module_name}... ", flush=True)
    try:
        with contextlib.redirect_stdout(io.StringIO()):
            runtime_module = importlib.import_module(module_name)
    except KeyboardInterrupt:
        raise
    except BaseException as e:
        log(f'Could not import {module_name}: {type(e).__name__}: "{e}"')
        return

    stub_source = path.read_text(encoding="utf-8")
    try:
        parsed_module = libcst.parse_module(stub_source)
    except libcst.ParserSyntaxError as e:
        log(f"Could not parse '{module_name}' at {path}: {e}")
        return

    if runtime_module.__doc__ and parsed_module.get_docstring() is None:
        docstring = triple_quoted_docstring(runtime_module.__doc__) + "\n"
        stub_source = docstring + stub_source if stub_source.strip() else docstring
        parsed_module = libcst.parse_module(stub_source)

    transformer = DocstringAdder(
        module_name=module_name,
        runtime_module=runtime_module,
        stub_file_path=path,
        typeshed_client_context=context,
        blacklisted_objects=blacklisted_objects,
    )
    parsed_module = parsed_module.visit(transformer)
    parsed_module = parsed_module.with_changes(
        body=add_attribute_docstrings(
            parsed_module.body,
            runtime_parent=RuntimeParent(module_name, RuntimeValue(runtime_module)),
            blacklisted_objects=blacklisted_objects,
            indentation=0,
        )
    )
    new_module = parsed_module.code
    path.write_text(new_module, encoding="utf-8")
    check_no_destructive_changes(
        path=path, previous_stub=stub_source, new_stub=new_module
    )

def assert_asts_match(old: ast.AST, new: ast.AST) -> None:
    """Check that two ASTs are equivalent, except for changes we choose to ignore."""
    if type(old) is not type(new):
        raise _make_safety_error(
            old, new, type(old).__name__, type(new).__name__, "AST node types differ"
        )

    for field_name in old._fields:
        old_field = getattr(old, field_name)
        new_field = getattr(new, field_name)
        if field_name in {"body", "orelse"}:
            if (
                len(old_field) == 1
                and isinstance(old_field[0], ast.Expr)
                and isinstance(old_field[0].value, ast.Constant)
                and old_field[0].value.value is ...
                and len(new_field) == 1
                and isinstance(new_field[0], ast.Expr)
                and isinstance(new_field[0].value, ast.Constant)
                and isinstance(new_field[0].value.value, str)
            ):
                continue

            old_field_iter = iter(old_field)
            new_field_iter = iter(new_field)
            new_field = []
            next_old = next(old_field_iter, None)
            next_new = next(new_field_iter, None)
            while next_old is not None:
                if next_new is None:
                    raise _make_safety_error(
                        old,
                        new,
                        type(old).__name__,
                        type(new).__name__,
                        "Nodes appear to have been removed from the body of a function/class/module/if-else",
                    )
                if (
                    isinstance(next_old, ast.Expr)
                    and isinstance(next_old.value, ast.Constant)
                    and isinstance(next_old.value.value, str)
                ):
                    new_field.append(next_new)
                    next_old = next(old_field_iter, None)
                    next_new = next(new_field_iter, None)
                elif (
                    isinstance(next_new, ast.Expr)
                    and isinstance(next_new.value, ast.Constant)
                    and isinstance(next_new.value.value, str)
                ):
                    next_new = next(new_field_iter, None)
                else:
                    new_field.append(next_new)
                    next_old = next(old_field_iter, None)
                    next_new = next(new_field_iter, None)
        _assert_ast_fields_match(old, new, old_field, new_field)

def _make_safety_error(
    old: ast.AST, new: ast.AST, old_value: object, new_value: object, message: str
) -> RuntimeError:
    def explain(node: ast.AST) -> str:
        return f" (at line {node.lineno})" if hasattr(node, "lineno") else ""
    raise RuntimeError(
        f"{message}: {old_value}{explain(old)} != {new_value}{explain(new)}"
    )

_SCALAR_TYPES = (float, int, str, bytes, complex, type(None), type(...))

def _assert_ast_fields_match(
    old_container: ast.AST, new_container: ast.AST, old_value: object, new_value: object
) -> None:
    if isinstance(old_value, list) and isinstance(new_value, list):
        if len(old_value) != len(new_value):
            raise _make_safety_error(
                old_container,
                new_container,
                len(old_value),
                len(new_value),
                "AST node lists differ in length",
            )
        for old_item, new_item in zip(old_value, new_value):
            _assert_ast_fields_match(old_container, new_container, old_item, new_item)
    elif isinstance(old_value, _SCALAR_TYPES) and isinstance(new_value, _SCALAR_TYPES):
        if type(old_value) is not type(new_value):
            raise _make_safety_error(
                old_container,
                new_container,
                type(old_value).__name__,
                type(new_value).__name__,
                "AST node types differ",
            )
        if old_value != new_value:
            raise _make_safety_error(
                old_container,
                new_container,
                old_value,
                new_value,
                "AST node values differ",
            )
    elif isinstance(old_value, ast.AST) and isinstance(new_value, ast.AST):
        assert_asts_match(old_value, new_value)
    else:
        raise _make_safety_error(
            old_container,
            new_container,
            type(old_value).__name__,
            type(new_value).__name__,
            "AST node values differ in type",
        )

def check_no_destructive_changes(path: Path, previous_stub: str, new_stub: str) -> None:
    """Check that docstring-adder has not made any destructive changes to the stub file."""
    previous_ast = ast.parse(previous_stub)
    try:
        new_ast = ast.parse(new_stub)
    except Exception:
        message = f"\nERROR: new stub file at {path} cannot be parsed/visited\n"
        print(colored(message, "red"))
        raise
    try:
        assert_asts_match(previous_ast, new_ast)
    except RuntimeError:
        message = f"\nERROR: new stub file at {path} has destructive changes\n"
        print(colored(message, "red"))
        raise

def install_typeshed_packages(typeshed_paths: Sequence[Path]) -> None:
    """Install the runtime packages corresponding to the given typeshed packages."""
    to_install: list[str] = []
    for path in typeshed_paths:
        metadata_path = path / "METADATA.toml"
        if not metadata_path.exists():
            print(f"{path} does not look like a typeshed package", file=sys.stderr)
            sys.exit(1)
        metadata_bytes = metadata_path.read_text(encoding="utf-8")
        metadata = tomli.loads(metadata_bytes)
        version = metadata["version"].lstrip("~=")
        to_install.append(f"{path.name}=={version}")
        stubtest_requirements = (
            metadata
            .get("tool", {})
            .get("stubtest", {})
            .get("stubtest_requirements", [])
        )
        to_install.extend(stubtest_requirements)

    if to_install:
        command = ["uv", "pip", "install", "--python", sys.executable, *to_install]
        print(f"Running install command: {' '.join(command)}")
        try:
            subprocess.check_call(command)
        except subprocess.CalledProcessError:
            sys.exit(10)

STDLIB_MODULE_BLACKLIST = frozenset({
    "_typeshed/*.pyi",
    "antigravity.pyi",
    "__main__.pyi",
    "sys/_monitoring.pyi",
})
STDLIB_OBJECT_BLACKLIST = frozenset({
    "enum.auto.value"
})

def load_blacklist(path: Path) -> frozenset[str]:
    """Load a "blacklist" file."""
    with path.open() as f:
        entries = frozenset(line.split("#")[0].strip() for line in f)
    return entries - {""}

def _main() -> None:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=RawDescriptionRichHelpFormatter
    )
    parser.add_argument(
        "-s",
        "--stdlib-path",
        help=(
            "Path to typeshed's stdlib directory. If given, we will add docstrings to"
            " stubs in this directory."
        ),
    )
    parser.add_argument(
        "-p",
        "--packages",
        nargs="+",
        help=(
            "List of stub package root paths to add docstrings to. We will add docstrings "
            "to these stubs. The runtime package must be installed."
        ),
        default=(),
    )
    parser.add_argument(
        "-t",
        "--typeshed-packages",
        nargs="+",
        help=(
            "List of typeshed packages to add docstrings to. WARNING: We will install the package locally. "
            "If installation of packages fails, we will exit with code 10."
        ),
        default=(),
    )
    parser.add_argument(
        "-b",
        "--blacklists",
        nargs="+",
        help=(
            "List of paths pointing to 'blacklist files', which can be used to specify functions/classes "
            "that docstring-adder should skip trying to add docstrings to."
        ),
        default=(),
    )
    args = parser.parse_args()
    stdlib_path = Path(args.stdlib_path) if args.stdlib_path else None
    if stdlib_path is not None and not (
        stdlib_path.is_dir() and (stdlib_path / "VERSIONS").is_file()
    ):
        parser.error(f'"{stdlib_path}" does not point to a valid stdlib directory')

    typeshed_paths = [Path(p) for p in args.typeshed_packages]
    install_typeshed_packages(typeshed_paths)
    package_paths = [Path(p) for p in args.packages]
    all_package_paths = package_paths + typeshed_paths
    search_paths = [*dict.fromkeys(p.parent for p in package_paths), *typeshed_paths]
    combined_blacklist = frozenset(
        chain.from_iterable(load_blacklist(Path(path)) for path in args.blacklists)
    )
    stdlib_blacklist = combined_blacklist | STDLIB_OBJECT_BLACKLIST
    context = typeshed_client.get_search_context(
        typeshed=stdlib_path, search_path=search_paths, version=sys.version_info[:2]
    )

    codemodded_stubs = 0
    for module, path in typeshed_client.get_all_stub_files(context):
        if stdlib_path is not None and path.is_relative_to(stdlib_path):
            if any(
                path.relative_to(stdlib_path).match(pattern)
                for pattern in STDLIB_MODULE_BLACKLIST
            ):
                log(f"Skipping {module}: blacklisted module")
                continue
            else:
                add_docstrings_to_stub(module, path, context, stdlib_blacklist)
        elif any(path.is_relative_to(p) for p in all_package_paths):
            add_docstrings_to_stub(module, path, context, combined_blacklist)
        else:
            continue
        codemodded_stubs += 1

    if codemodded_stubs == 0:
        m = "\n--- ERROR: Didn't find any stubs to codemod for the passed packages ---"
        print(colored(m, "red"))
        sys.exit(1)
    else:
        m = "\n--- Successfully completed the codemod ---"
        print(colored(m, "green"))
        sys.exit(0)

if __name__ == "__main__":
    _main()

from typing import List, Optional, Dict, Any
from fastapi import APIRouter, Depends, Query, Body, HTTPException
from ..services.feature_flags import get_feature_service
from ..routers.auth import require_admin
from ..models import User

router = APIRouter(prefix="/flags", tags=["Feature Flags"])

@router.get("/")
async def fetch_all_flags(current_user: User = Depends(require_admin)):
    """Retrieve all feature flags stored in Consul."""
    flag_service = get_feature_service()
    return flag_service.retrieve_all_flags()

@router.post("/")
async def modify_flag(
    feature_name: str = Query(...),
    settings: Dict[str, Any] = Body(...),  # {enabled: bool, rollout_percentage: int, tenant_overrides: {...}}
    current_user: User = Depends(require_admin)
):
    """Admin-only: Modify or create a feature flag configuration."""
    flag_service = get_feature_service()

    # Validate required fields in the configuration
    if 'enabled' not in settings or not isinstance(settings['enabled'], bool):
        raise HTTPException(status_code=400, detail="'enabled' must be a boolean value")

    result = flag_service.apply_flag(feature_name, settings)
    if not result:
        raise HTTPException(status_code=500, detail="Unable to persist changes to Consul")

    return {"message": f"Flag '{feature_name}' has been updated.", "settings": settings}

@router.delete("/")
async def remove_flag(
    feature_name: str = Query(...),
    current_user: User = Depends(require_admin)
):
    """Admin-only: Delete an existing feature flag."""
    flag_service = get_feature_service()
    try:
        flag_service.client.kv.delete(f"soulsense/features/{feature_name}")
        flag_service.cache.flush()
        return {"message": f"Flag '{feature_name}' has been removed."}
    except Exception as error:
        raise HTTPException(status_code=500, detail=str(error))

# Alternative implementation of session filtering by user ID

from common.session_manager import SessionManager

class _MockCheckpointer:
    def __init__(self, data_store):
        self.storage = data_store

class _ThreadConfig:
    def __init__(self, thread_identifier: str):
        self.configurable = {"thread_id": thread_identifier}

    def __hash__(self) -> int:  # pragma: no cover
        return hash(self.configurable["thread_id"])

    def __eq__(self, other: object) -> bool:  # pragma: no cover
        return isinstance(other, _ThreadConfig) and other.configurable == self.configurable

def test_list_sessions_with_user_filter():
    checkpointer = _MockCheckpointer(
        data_store={
            _ThreadConfig("session_alice"): {
                "channel_values": {
                    "user_id": "alice",
                    "message": "greetings",
                    "path": "direct",
                }
            },
            _ThreadConfig("session_bob"): {
                "channel_values": {
                    "user_id": "bob",
                    "message": "hey",
                    "path": "direct",
                }
            },
        }
    )

    manager = SessionManager(checkpointer)
    result_sessions = manager.list_sessions(limit=50, user_id_filter="alice")

    assert [s.thread_id for s in result_sessions] == ["session_alice"]

