# Custom registry implementation for managing reward handlers and their associated virtual environments
from typing import Dict, Type
from cosmos_rl_reward.utils.logging import logger

class RewardManager:
    """
    A centralized manager to register and retrieve reward handler classes along with their 
    corresponding virtual environment specifications.
    """
    _HANDLER_MAP: Dict[str, Type] = {}
    _ENVIRONMENT_MAP: Dict[str, str] = {}

    @classmethod
    def add_handler(cls, handler_class: Type):
        """Registers a reward handler class by its reward_name attribute."""
        name = handler_class.reward_name
        cls._HANDLER_MAP[name] = handler_class

    @classmethod
    def assign_venv(cls, handler_name: str, venv_path: str):
        """Associates a virtual environment path with a registered reward handler."""
        cls._ENVIRONMENT_MAP[handler_name] = venv_path

    @classmethod
    def fetch_handler(cls, handler_name: str) -> Type:
        """Retrieves the handler class for a given reward type."""
        if handler_name not in cls._HANDLER_MAP:
            raise ValueError(f"Handler '{handler_name}' is not registered.")
        return cls._HANDLER_MAP[handler_name]

    @classmethod
    def get_venv_for_handler(cls, handler_name: str) -> str:
        """Gets the virtual environment path for a handler; defaults to 'python' if unregistered."""
        if handler_name not in cls._ENVIRONMENT_MAP:
            logger.warning(
                f"No virtual environment specified for '{handler_name}'. Falling back to system python."
            )
            return "python"
        return cls._ENVIRONMENT_MAP[handler_name]

    @classmethod
    def register_decorator(
        cls,
        *,
        permit_override: bool = False,
    ):
        """Decorator factory to register handler classes conditionally."""
        def wrapper(handler_class: Type) -> Type:
            handler_id = handler_class.reward_name
            if (
                not permit_override
                and handler_id in cls._HANDLER_MAP
                and cls._HANDLER_MAP[handler_id] != handler_class
            ):
                raise ValueError(f"Handler '{handler_id}' has already been registered.")
            cls.add_handler(handler_class)
            return handler_class
        return wrapper

    @classmethod
    def supports_handler(cls, handler_name: str) -> bool:
        """Checks whether a handler is registered."""
        return handler_name in cls._HANDLER_MAP

    @classmethod
    def supports_venv(cls, handler_name: str) -> bool:
        """Checks whether a virtual environment is configured for a handler."""
        return handler_name in cls._ENVIRONMENT_MAP

    @classmethod
    def list_handlers(cls):
        """Returns a list of all registered handler names."""
        return list(cls._HANDLER_MAP.keys())

    @classmethod
    def list_venvs(cls):
        """Returns a dictionary mapping handler names to their virtual environments."""
        return dict(cls._ENVIRONMENT_MAP)

