# Simplified MessagePack-like serializer/deserializer

import struct
import sys

PY2 = sys.version_info[0] == 2
if PY2:
    int_types = (int, long)
else:
    int_types = int
    unicode = str

def _convert_to_bytes(data):
    if isinstance(data, memoryview):
        return data.tobytes()
    elif isinstance(data, bytearray):
        return bytes(data)
    else:
        return data

class SimpleBuffer:
    def __init__(self, initial=b""):
        self._data = bytearray(initial)

    def add(self, content):
        content = _convert_to_bytes(content)
        self._data.extend(content)

    def get_contents(self):
        return bytes(self._data)

    def get_length(self):
        return len(self._data)

class Serializer:
    def __init__(self):
        self._storage = SimpleBuffer()

    def store_value(self, value):
        if value is None:
            self._storage.add(b'\xc0')
        elif isinstance(value, bool):
            self._storage.add(b'\xc3' if value else b'\xc2')
        elif isinstance(value, int_types):
            self._store_integer(value)
        elif isinstance(value, (bytes, bytearray)):
            self._store_bytes(value)
        elif isinstance(value, unicode):
            encoded = value.encode('utf-8')
            self._store_bytes(encoded)
        elif isinstance(value, float):
            self._storage.add(struct.pack('>Bd', 0xCB, value))
        elif isinstance(value, list):
            self._store_list(value)
        elif isinstance(value, dict):
            self._store_dict(value)
        else:
            raise TypeError(f"Cannot serialize {type(value)}")

    def _store_integer(self, num):
        if -32 <= num < 128:
            self._storage.add(struct.pack('b', num))
        elif 0 <= num <= 255:
            self._storage.add(struct.pack('>BB', 0xCC, num))
        elif -128 <= num < 0:
            self._storage.add(struct.pack('>Bb', 0xD0, num))
        elif 0 < num <= 65535:
            self._storage.add(struct.pack('>BH', 0xCD, num))
        elif -32768 <= num < -128:
            self._storage.add(struct.pack('>Bh', 0xD1, num))
        elif 0 < num <= 4294967295:
            self._storage.add(struct.pack('>BI', 0xCE, num))
        elif -2147483648 <= num < -32768:
            self._storage.add(struct.pack('>Bi', 0xD2, num))
        else:
            self._storage.add(struct.pack('>BQ', 0xCF, num))

    def _store_bytes(self, data):
        length = len(data)
        if length <= 31:
            self._storage.add(struct.pack('B', 0xA0 + length))
        elif length <= 255:
            self._storage.add(struct.pack('>BB', 0xD9, length))
        elif length <= 65535:
            self._storage.add(struct.pack('>BH', 0xDA, length))
        else:
            self._storage.add(struct.pack('>BI', 0xDB, length))
        self._storage.add(data)

    def _store_list(self, items):
        count = len(items)
        if count <= 15:
            self._storage.add(struct.pack('B', 0x90 + count))
        elif count <= 65535:
            self._storage.add(struct.pack('>BH', 0xDC, count))
        else:
            self._storage.add(struct.pack('>BI', 0xDD, count))
        for item in items:
            self.store_value(item)

    def _store_dict(self, mapping):
        count = len(mapping)
        if count <= 15:
            self._storage.add(struct.pack('B', 0x80 + count))
        elif count <= 65535:
            self._storage.add(struct.pack('>BH', 0xDE, count))
        else:
            self._storage.add(struct.pack('>BI', 0xDF, count))
        for key, value in mapping.items():
            self.store_value(key)
            self.store_value(value)

    def retrieve_data(self):
        return self._storage.get_contents()

class Deserializer:
    def __init__(self, data):
        self._buffer = bytearray(data)
        self._position = 0

    def extract_value(self):
        if self._position >= len(self._buffer):
            raise ValueError("Incomplete data")

        byte_val = self._buffer[self._position]
        self._position += 1

        if byte_val == 0xC0:
            return None
        elif byte_val == 0xC2:
            return False
        elif byte_val == 0xC3:
            return True
        elif byte_val & 0b10000000 == 0:
            return byte_val
        elif byte_val & 0b11100000 == 0b11100000:
            return -1 - (byte_val ^ 0xFF)
        elif byte_val & 0b11100000 == 0b10100000:
            length = byte_val & 0b00011111
            result = bytes(self._buffer[self._position:self._position+length])
            self._position += length
            return result.decode('utf-8')
        elif byte_val & 0b11110000 == 0b10010000:
            length = byte_val & 0b00001111
            result = []
            for _ in range(length):
                result.append(self.extract_value())
            return result
        elif byte_val & 0b11110000 == 0b10000000:
            length = byte_val & 0b00001111
            result = {}
            for _ in range(length):
                key = self.extract_value()
                value = self.extract_value()
                result[key] = value
            return result
        elif 0xC4 <= byte_val <= 0xC6:
            sizes = {0xC4: 1, 0xC5: 2, 0xC6: 4}
            size = sizes[byte_val]
            if self._position + size > len(self._buffer):
                raise ValueError("Incomplete data")
            if size == 1:
                length = self._buffer[self._position]
            elif size == 2:
                length = struct.unpack('>H', self._buffer[self._position:self._position+2])[0]
            else:
                length = struct.unpack('>I', self._buffer[self._position:self._position+4])[0]
            self._position += size
            result = bytes(self._buffer[self._position:self._position+length])
            self._position += length
            return result
        elif 0xCA <= byte_val <= 0xD3:
            formats = {
                0xCA: ('>f', 4),
                0xCB: ('>d', 8),
                0xCC: (None, 1),
                0xCD: ('>H', 2),
                0xCE: ('>I', 4),
                0xCF: ('>Q', 8),
                0xD0: ('b', 1),
                0xD1: ('>h', 2),
                0xD2: ('>i', 4),
                0xD3: ('>q', 8),
            }
            fmt, size = formats[byte_val]
            if self._position + size > len(self._buffer):
                raise ValueError("Incomplete data")
            if fmt is None:
                result = self._buffer[self._position]
            else:
                result = struct.unpack(fmt, self._buffer[self._position:self._position+size])[0]
            self._position += size
            return result
        elif 0xD4 <= byte_val <= 0xD8:
            ext_sizes = {0xD4: 2, 0xD5: 3, 0xD6: 5, 0xD7: 9, 0xD8: 17}
            size = ext_sizes[byte_val]
            if self._position + size > len(self._buffer):
                raise ValueError("Incomplete data")
            code = self._buffer[self._position]
            data = bytes(self._buffer[self._position+1:self._position+size])
            self._position += size
            return (code, data)
        elif 0xD9 <= byte_val <= 0xDB:
            sizes = {0xD9: 1, 0xDA: 2, 0xDB: 4}
            size = sizes[byte_val]
            if self._position + size > len(self._buffer):
                raise ValueError("Incomplete data")
            if size == 1:
                length = self._buffer[self._position]
            elif size == 2:
                length = struct.unpack('>H', self._buffer[self._position:self._position+2])[0]
            else:
                length = struct.unpack('>I', self._buffer[self._position:self._position+4])[0]
            self._position += size
            result = bytes(self._buffer[self._position:self._position+length])
            self._position += length
            return result
        elif 0xDC <= byte_val <= 0xDD:
            sizes = {0xDC: 2, 0xDD: 4}
            size = sizes[byte_val]
            if self._position + size > len(self._buffer):
                raise ValueError("Incomplete data")
            if size == 2:
                length = struct.unpack('>H', self._buffer[self._position:self._position+2])[0]
            else:
                length = struct.unpack('>I', self._buffer[self._position:self._position+4])[0]
            self._position += size
            result = []
            for _ in range(length):
                result.append(self.extract_value())
            return result
        elif 0xDE <= byte_val <= 0xDF:
            sizes = {0xDE: 2, 0xDF: 4}
            size = sizes[byte_val]
            if self._position + size > len(self._buffer):
                raise ValueError("Incomplete data")
            if size == 2:
                length = struct.unpack('>H', self._buffer[self._position:self._position+2])[0]
            else:
                length = struct.unpack('>I', self._buffer[self._position:self._position+4])[0]
            self._position += size
            result = {}
            for _ in range(length):
                key = self.extract_value()
                value = self.extract_value()
                result[key] = value
            return result
        else:
            raise ValueError(f"Unknown type: {hex(byte_val)}")

# Example usage demonstrating the functionality
def demonstrate_functionality():
    # Test basic types
    test_cases = [
        None,
        True,
        False,
        42,
        -5,
        1000,
        3.14,
        "hello",
        b"world",
        [1, 2, 3],
        {"key": "value"},
        {"a": 1, "b": [2, 3], "c": {"nested": True}},
    ]

    for original in test_cases:
        serializer = Serializer()
        serializer.store_value(original)
        serialized = serializer.retrieve_data()

        deserializer = Deserializer(serialized)
        restored = deserializer.extract_value()

        assert original == restored, f"Failed for {original}"

# Run demonstration
if __name__ == "__main__":
    demonstrate_functionality()

