def remove_path_prefix_js(path_pattern: str) -> str:
    prefix_length = len(path_pattern)
    return f"""
        function handler(event) {{
            var request = event.request;
            var uri = request.uri;
            if (uri === '{path_pattern}') {{
                request.uri = '/';
            }} else if (uri.substring(0, {prefix_length + 1}) === '{path_pattern}/') {{
                request.uri = uri.substring({prefix_length});
            }}
            return request;
        }}
        """.strip()

def configure_origin_host_header(host: str) -> str:
    """Produce Lambda@Edge code to override the Host header for origin requests.
    Useful when forwarding requests to external services that rely on virtual hosting.
    """
    # Reference: https://serverfault.com/a/888776
    return """
        'use strict';
        // modify the Host header before sending to the origin
        exports.handler = (event, context, callback) => {
            const request = event.Records[0].cf.request;
            request.headers.host[0].value = '{host}';
            return callback(null, request);
        };
        """.replace("{host}", host).strip()

