def get_cuda_devices_selection(mode: str | None = None):
    """Selects CUDA devices based on the specified mode.

    Args:
        mode: Configuration for device selection:
            - "basic": Single CUDA device (cuda:0)
            - "unique": One device per unique GPU architecture
            - "unique_or_2x": Unique devices, with an extra device if only one architecture exists

    Returns:
        List of selected CUDA devices
    """
    if mode is None:
        mode = TEST_CONFIGURATION

    if mode == "basic":
        return [wp.get_device("cuda:0")] if wp.is_cuda_available() else []

    # Collect all available CUDA devices
    cuda_gpus = wp.get_cuda_devices()
    # Group by architecture to select first device of each type
    arch_first_device = {}
    for gpu in cuda_gpus:
        if gpu.arch not in arch_first_device:
            arch_first_device[gpu.arch] = gpu

    # Select one device per architecture
    selected_gpus = list(arch_first_device.values())

    # For 'unique_or_2x' mode, add an extra device if only one architecture exists
    if mode == "unique_or_2x" and len(selected_gpus) == 1 and len(cuda_gpus) > 1:
        for gpu in cuda_gpus:
            if gpu not in selected_gpus:
                selected_gpus.append(gpu)
                break

    return selected_gpus

def get_test_devices(mode: str | None = None):
    """Determines which devices to use for testing based on mode.

    Args:
        mode: Device selection strategy. Defaults to TEST_CONFIGURATION.
              Options include "basic", "unique", "unique_or_2x", and "all".

    Returns:
        List of devices configured for testing
    """
    if mode is None:
        mode = TEST_CONFIGURATION

    selected_devices = []

    if mode == "basic":
        # Use CPU and first GPU if available
        if wp.is_cpu_available():
            selected_devices.append(wp.get_device("cpu"))
        if wp.is_cuda_available():
            selected_devices.append(wp.get_device("cuda:0"))

    elif mode in ("unique", "unique_or_2x"):
        # Include CPU and selected CUDA devices
        if wp.is_cpu_available():
            selected_devices.append(wp.get_device("cpu"))
        selected_devices.extend(get_cuda_devices_selection(mode))

    elif mode == "all":
        # Use all available devices
        selected_devices = wp.get_devices()

    else:
        raise ValueError(f"Unknown test mode selected: {mode}")

    return selected_devices

def get_cuda_test_devices(mode=None):
    """Filters devices to return only CUDA devices."""
    all_devices = get_test_devices(mode=mode)
    return [d for d in all_devices if d.is_cuda]

class StreamCapture:
    """Context manager for capturing stdout/stderr output."""

    def __init__(self, stream_name):
        self.stream_name = stream_name  # 'stdout' or 'stderr'
        self.original_stream = None
        self.captured_fd = None
        self.temp_file = None

    def start_capture(self):
        # Flush libc buffers before capture
        if C_RUNTIME is not None:
            C_RUNTIME.fflush(None)

        # Save original stream and file descriptor
        self.original_stream = getattr(sys, self.stream_name)
        self.captured_fd = os.dup(self.original_stream.fileno())

        # Create temporary file for capture
        self.temp_file = io.TextIOWrapper(
            tempfile.TemporaryFile(buffering=0),
            encoding="utf-8",
            errors="replace",
            newline="",
            write_through=True,
        )

        # Redirect stream to temporary file
        os.dup2(self.temp_file.fileno(), self.original_stream.fileno())
        setattr(sys, self.stream_name, self.temp_file)

    def stop_capture(self):
        # Ensure all buffers are flushed
        if C_RUNTIME is not None:
            C_RUNTIME.fflush(None)

        # Restore original stream and close temporary file
        os.dup2(self.captured_fd, self.original_stream.fileno())
        os.close(self.captured_fd)

        # Read captured content
        self.temp_file.seek(0)
        captured_content = self.temp_file.buffer.read()
        self.temp_file.close()

        # Restore original stream object
        setattr(sys, self.stream_name, self.original_stream)

        return str(captured_content.decode("utf-8"))

class StdErrCapture(StreamCapture):
    def __init__(self):
        super().__init__("stderr")

class StdOutCapture(StreamCapture):
    def __init__(self):
        super().__init__("stdout")

class OutputValidator:
    def __init__(self, test_case):
        self.test_case = test_case

    def __enter__(self):
        self.capture = StdOutCapture()
        self.capture.start_capture()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        wp.synchronize()  # Ensure all pending operations complete

        # Process captured output
        raw_output = self.capture.stop_capture()
        if raw_output:
            print(raw_output.rstrip())

            # Filter out expected module loading messages
            filtered_lines = [
                line for line in raw_output.splitlines()
                if not (line.startswith("Module") and "load on device" in line)
            ]

            # Fail if unexpected output remains
            if any(line.strip() for line in filtered_lines):
                self.test_case.fail(f"Unexpected output:\n'{raw_output.rstrip()}'")

def compare_arrays(result_array: wp.array, expected_array: wp.array):
    """Verify that two Warp arrays contain identical values."""
    np.testing.assert_equal(result_array.numpy(), expected_array.numpy())

def compare_numpy_arrays(result_array: np.ndarray, expected_array: np.ndarray, tolerance=0.0):
    """Compare NumPy arrays with optional floating-point tolerance."""
    if tolerance != 0.0:
        np.testing.assert_allclose(
            result_array.flatten(), 
            expected_array.flatten(), 
            atol=tolerance, 
            equal_nan=True
        )
    else:
        np.testing.assert_array_equal(result_array, expected_array)

def majority_check(data: np.ndarray, threshold: float = 0.8) -> bool:
    """Check if at least threshold fraction of array elements are positive/True."""
    if data.size == 0:
        return True
    return bool(np.sum(data > 0) / data.size >= threshold)

def find_nan_components(obj: Any | None) -> list[str]:
    """Identify Warp array attributes containing NaN values."""
    nan_attributes = []
    if obj is None:
        return nan_attributes

    for attr_name, value in obj.__dict__.items():
        if isinstance(value, wp.array):
            arr_data = value.numpy()
            # Skip structured arrays where np.isnan isn't supported
            if arr_data.dtype.names is not None:
                continue
            if np.isnan(arr_data).any():
                nan_attributes.append(attr_name)

    return nan_attributes

def find_invalid_values(obj: Any | None) -> list[str]:
    """Find Warp array attributes containing non-finite values."""
    invalid_attributes = []
    if obj is None:
        return invalid_attributes

    for attr_name, value in obj.__dict__.items():
        if isinstance(value, wp.array):
            arr_data = value.numpy()
            # Skip structured arrays where np.isfinite isn't supported
            if arr_data.dtype.names is not None:
                continue
            if not np.isfinite(arr_data).all():
                invalid_attributes.append(attr_name)

    return invalid_attributes

def create_test_runner(func, device, validate_output, **kwargs):
    """Factory function to generate test functions."""
    def test_function(self):
        if validate_output:
            with OutputValidator(self):
                func(self, device, **kwargs)
        else:
            func(self, device, **kwargs)

    # Preserve test metadata if present
    if hasattr(func, "__unittest_expecting_failure__"):
        test_function.__unittest_expecting_failure__ = func.__unittest_expecting_failure__

    return test_function

def skip_test_case(self):
    """Test runner for skipped tests."""
    self.skipTest("No suitable devices available for this test.")

def normalize_identifier(name: str) -> str:
    """Convert string to valid Python identifier by replacing invalid characters."""
    name = str(name)
    if name.isidentifier():
        return name
    return re.sub(r"\W|^(?=\d)", "_", name)

def register_function_test(cls, test_name, test_func, devices=None, validate_output=True, **kwargs):
    """Register test methods with a test class."""
    if devices is None:
        setattr(cls, test_name, create_test_runner(test_func, None, validate_output, **kwargs))
    elif isinstance(devices, list):
        if not devices:
            setattr(cls, test_name, skip_test_case)
        else:
            for device in devices:
                setattr(
                    cls,
                    test_name + "_" + normalize_identifier(str(device)),
                    create_test_runner(test_func, device, validate_output, **kwargs),
                )
    else:
        setattr(
            cls,
            test_name + "_" + normalize_identifier(str(devices)),
            create_test_runner(test_func, devices, validate_output, **kwargs),
        )

def register_kernel_test(cls, kernel, launch_dim, test_name=None, expected=None, inputs=None, devices=None):
    def test_impl(self, device):
        args = []
        if inputs:
            args.extend(inputs)
        if expected:
            # Prepare output array to match expected results
            result_array = wp.array(expected, dtype=int, device=device)
            output_array = wp.zeros_like(result_array)
            args.append(output_array)

        # Force kernel module loading to avoid log output during test
        kernel.module.load(device)
        with OutputValidator(self):
            wp.launch(kernel, dim=launch_dim, inputs=args, device=device)

        # Verify output matches expected values
        if expected:
            compare_arrays(output_array, result_array)

    if test_name is None:
        test_name = kernel.key

    # Default to all devices if none specified
    if devices is None:
        devices = get_test_devices()

    # Register test method for each device
    for d in devices:
        def test_wrapper(test, device=d):
            test_impl(test, device)
        setattr(cls, test_name + "_" + normalize_identifier(str(d)), test_wrapper)

def register_function_test_with_kernel_registration(cls, test_name, test_func, devices=None, **kwargs):
    """Pre-register kernels before creating test functions."""
    test_func(None, None, **kwargs, register_kernels=True)
    register_function_test(cls, test_name, test_func, devices=devices, **kwargs)

def generate_junit_report(
    output_file: str,
    test_results: list,
    total_tests: int,
    failed_tests: int,
    errored_tests: int,
    skipped_tests: int,
    elapsed_time: float,
):
    """Generate JUnit XML report from test results."""
    root = ET.Element(
        "testsuite",
        name="Warp Tests",
        failures=str(failed_tests),
        errors=str(errored_tests),
        skipped=str(skipped_tests),
        tests=str(total_tests),
        time=f"{elapsed_time:.3f}",
    )

    for result in test_results:
        class_name, method_name, duration, status, message, details = result

        test_case = ET.SubElement(
            root, "testcase", 
            classname=class_name, 
            name=method_name, 
            time=f"{duration:.3f}"
        )

        if status == "FAIL":
            failure_elem = ET.SubElement(test_case, "failure", message=str(message))
            failure_elem.text = str(details)
        elif status == "ERROR":
            error_elem = ET.SubElement(test_case, "error")
            error_elem.text = str(details)
        elif status == "SKIP":
            skip_elem = ET.SubElement(test_case, "skipped")
            skip_elem.set("message", str(message))

    tree = ET.ElementTree(root)
    if hasattr(ET, "indent"):
        ET.indent(root)
    tree.write(output_file, encoding="utf-8", xml_declaration=True)

class ParallelJUnitResultHandler(unittest.TextTestResult):
    def __init__(self, stream, descriptions, verbosity):
        stream = type(stream)(sys.stderr)
        self.test_log = []
        super().__init__(stream, descriptions, verbosity)

    def startTest(self, test):
        if self.showAll:
            self.stream.writeln(f"{self.getDescription(test)} ...")
            self.stream.flush()
        elif self.dots:
            self.stream.writeln(f"{test} ...")
            self.stream.flush()

        self.test_start_time = time.perf_counter_ns()
        super(unittest.TextTestResult, self).startTest(test)

    def _record_test_result(self, test, status_code, message=None, details=None):
        start_time = getattr(self, "test_start_time", None)
        duration = round((time.perf_counter_ns() - start_time) * 1e-9, 3) if start_time is not None else 0.0

        class_name = test.__class__.__name__
        method_name = getattr(test, "_testMethodName", str(test))
        self.test_log.append((class_name, method_name, duration, status_code, message, details))

    def _report_test_status(self, test, status_message):
        if self.showAll:
            self.stream.writeln(f"{self.getDescription(test)} ... {status_message}")
        elif self.dots:
            self.stream.writeln(f"{test} ... {status_message}")
        self.stream.flush()

    def addSuccess(self, test):
        super(unittest.TextTestResult, self).addSuccess(test)
        self._report_test_status(test, "ok")
        self._record_test_result(test, "OK")

    def addError(self, test, error_info):
        super(unittest.TextTestResult, self).addError(test, error_info)
        self._report_test_status(test, "ERROR")
        self._record_test_result(test, "ERROR", str(error_info[1]), self._exc_info_to_string(error_info, test))

    def addFailure(self, test, error_info):
        super(unittest.TextTestResult, self).addFailure(test, error_info)
        self._report_test_status(test, "FAIL")
        self._record_test_result(test, "FAIL", str(error_info[1]), self._exc_info_to_string(error_info, test))

    def addSkip(self, test, reason):
        super(unittest.TextTestResult, self).addSkip(test, reason)
        self._report_test_status(test, f"skipped {reason!r}")
        self._record_test_result(test, "SKIP", reason)

    def addExpectedFailure(self, test, error_info):
        super(unittest.TextTestResult, self).addExpectedFailure(test, error_info)
        self._report_test_status(test, "expected failure")
        self._record_test_result(test, "OK", "expected failure")

    def addUnexpectedSuccess(self, test):
        super(unittest.TextTestResult, self).addUnexpectedSuccess(test)
        self._report_test_status(test, "unexpected success")
        self._record_test_result(test, "FAIL", "unexpected success")

    def addSubTest(self, test, subtest, error_info):
        super(unittest.TextTestResult, self).addSubTest(test, subtest, error_info)
        if error_info is not None:
            self._report_test_status(test, "ERROR")
            self._record_test_result(test, "FAIL", str(error_info[1]), self._exc_info_to_string(error_info, test))

    def printErrors(self):
        pass

import sys
import threading
import json
from pathlib import Path
from collections import defaultdict

class FunctionMonitor:
    def __init__(self, include_paths=None, exclude_paths=None):
        self.tracked_calls = set()
        self.call_frequency = defaultdict(int)
        self._monitor_lock = threading.Lock()
        self._old_global_hook = None
        self._old_thread_hook = None
        self._active = False
        self.include_paths = include_paths or []
        self.exclude_paths = exclude_paths or [
            "site-packages",
            "venv",
            ".venv",
            "/lib/python",
            "/site-packages/pytest",
            "/site-packages/_pytest",
            "/site-packages/pluggy",
            "<frozen",
            "<string>",
        ]

    def _is_relevant_file(self, filepath):
        if not filepath:
            return False
        if self.include_paths:
            for pattern in self.include_paths:
                if pattern in filepath:
                    return True
            return False
        for pattern in self.exclude_paths:
            if pattern in filepath:
                return False
        return True

    def _hook_into_execution(self, frame, event, param):
        if event == "call":
            code_obj = frame.f_code
            file_path = code_obj.co_filename
            if self._is_relevant_file(file_path):
                func_name = code_obj.co_name
                line_no = code_obj.co_firstlineno
                identifier = (file_path, func_name, line_no)
                with self._monitor_lock:
                    self.tracked_calls.add(identifier)
                    self.call_frequency[identifier] += 1
        return self._hook_into_execution

    def activate(self):
        if not self._active:
            self._old_global_hook = sys.getprofile()
            self._old_thread_hook = threading.getprofile()
            sys.setprofile(self._hook_into_execution)
            threading.setprofile(self._hook_into_execution)
            self._active = True

    def deactivate(self):
        if self._active:
            sys.setprofile(self._old_global_hook)
            threading.setprofile(self._old_thread_hook)
            self._active = False

    def __enter__(self):
        self.activate()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.deactivate()

    def export(self, filename="trace_output.json"):
        output_data = {
            "schema_version": 1,
            "records": [
                {
                    "path": path,
                    "name": name,
                    "line": line,
                    "executions": self.call_frequency[(path, name, line)],
                }
                for path, name, line in sorted(self.tracked_calls)
            ],
        }
        Path(filename).write_text(json.dumps(output_data, indent=2))
        print(f"Exported {len(self.tracked_calls)} traced function entries to {filename}")

    @classmethod
    def import_records(cls, filename="trace_output.json"):
        file_path = Path(filename)
        if not file_path.exists():
            return None
        try:
            raw_data = json.loads(file_path.read_text())
            recorded_items = set()
            for entry in raw_data.get("records", []):
                recorded_items.add((entry["path"], entry["name"], entry["line"]))
            return recorded_items
        except Exception as error:
            print(f"Error loading trace data: {error}")
            return None

    def summarize(self):
        unique_files = set()
        for f, _, _ in self.tracked_calls:
            unique_files.add(f)
        return {
            "total_invocations": len(self.tracked_calls),
            "distinct_functions": len(self.tracked_calls),
            "files_monitored": len(unique_files),
            "files": sorted(unique_files),
        }

_global_monitor = None

def enable_monitoring(include_paths=None, exclude_paths=None):
    global _global_monitor
    _global_monitor = FunctionMonitor(include_paths, exclude_paths)
    _global_monitor.activate()
    return _global_monitor

def disable_monitoring(export_file="trace_output.json"):
    global _global_monitor
    if _global_monitor:
        _global_monitor.deactivate()
        _global_monitor.export(export_file)
        summary = _global_monitor.summarize()
        print(
            f"Monitoring completed: {summary['distinct_functions']} functions across {summary['files_monitored']} files"
        )
        return _global_monitor
    return None

def pytest_configure(config):
    if config.getoption("--skylos-trace", default=False):
        include_opt = config.getoption("--skylos-trace-include", default=None)
        include_patterns = include_opt.split(",") if include_opt else None
        enable_monitoring(include_paths=include_patterns)
        print("Skylos call monitoring enabled")

def pytest_unconfigure(config):
    if config.getoption("--skylos-trace", default=False):
        disable_monitoring()

def pytest_addoption(parser):
    parser.addoption(
        "--skylos-trace",
        action="store_true",
        default=False,
        help="Activate Skylos function tracing",
    )
    parser.addoption(
        "--skylos-trace-include",
        action="store",
        default=None,
        help="Comma-separated list of path substrings to include in tracing",
    )

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python -m skylos_trace <script.py> [args...]")
        print("       python -m skylos_trace -m <module> [args...]")
        sys.exit(1)

    sys.argv = sys.argv[1:]

    if sys.argv[0] == "-m":
        if len(sys.argv) < 2:
            print("Error: -m requires module name")
            sys.exit(1)
        module_name = sys.argv[1]
        sys.argv = sys.argv[1:]
        monitor = FunctionMonitor()
        with monitor:
            import runpy
            runpy.run_module(module_name, run_name="__main__", alter_sys=True)
        monitor.export()
    else:
        script_file = sys.argv[0]
        monitor = FunctionMonitor()
        with monitor:
            import runpy
            runpy.run_path(script_file, run_name="__main__")
        monitor.export()

# Type III Clone: LocalDiffusersDataset & DiffusersPacker equivalent

from typing import Any, List, Dict, Union
from torch.utils.data import Dataset
from cosmos_rl.launcher.worker_entry import main as launch_worker
from cosmos_rl.policy.config import Config as CosmosConfig
from cosmos_rl.dispatcher.data.packer import BaseDataPacker
from cosmos_rl.utils.logging import logger
from torchvision import transforms as T
import torch
import json
from decord import VideoReader, cpu
import numpy as np
import os
from PIL import Image
from cosmos_rl.tools.dataset.wfm.local_datasets.dataset_utils import (
    ResizePreprocess,
    ToTensorVideo,
)
import random


class LocalDiffusersDataset(Dataset):
    def setup(self, config: CosmosConfig, *args, **kwargs):
        self.cfg = config
        self.is_video_mode = config.policy.diffusers.is_video
        self.target_h, self.target_w = config.policy.diffusers.inference_size
        self.num_train_frames = config.policy.diffusers.train_frames
        self.root_dir = config.train.train_policy.dataset.local_dir

        # Collect .json files manually instead of glob
        self.json_files = []
        for fname in os.listdir(self.root_dir):
            if fname.endswith(".json"):
                self.json_files.append(fname)

        # Determine file suffix based on mode
        self.file_ext = "mp4" if self.is_video_mode else "jpg"

        # Setup visual preprocessing pipeline
        self.preprocessor = self._build_preprocessor()

        # Extract base names (without extension) for indexing
        self.sample_ids = [os.path.splitext(f)[0] for f in self.json_files]

    def __len__(self):
        return len(self.sample_ids)

    def __getitem__(self, idx: int) -> Dict[str, Any]:
        base_name = self.sample_ids[idx]
        meta_path = os.path.join(self.root_dir, base_name + ".json")
        media_path = meta_path.replace(".json", "." + self.file_ext)

        data_dict = {}

        if self.is_video_mode:
            video_tensor, fps_val = self._extract_video_clips(media_path)
            video_tensor = video_tensor.permute(1, 0, 2, 3)  # [C, T, H, W]
            with open(meta_path, 'r') as f:
                meta_data = json.load(f)
            data_dict.update({
                "visual": video_tensor,
                "is_video": True,
                **meta_data
            })
        else:
            img_tensor = self._load_single_image(media_path)
            with open(meta_path, 'r') as f:
                meta_data = json.load(f)
            data_dict.update({
                "visual": img_tensor,
                "is_video": False,
                **meta_data
            })

        return data_dict

    def _build_preprocessor(self):
        if self.is_video_mode:
            ops = [
                ToTensorVideo(),  # TCHW
                ResizePreprocess([self.target_h, self.target_w]),
                T.Normalize(mean=[0.5, 0.5, 0.5], std=[0.5, 0.5, 0.5], inplace=True),
            ]
        else:
            ops = [
                T.Resize(self.target_h, interpolation=T.InterpolationMode.BICUBIC),
                T.CenterCrop((self.target_h, self.target_w)),
                T.ToTensor(),
                T.Normalize(mean=[0.5], std=[0.5]),
            ]
        return T.Compose(ops)

    def _extract_video_clips(self, vid_path: str):
        frames_np, avg_fps = self._read_video_frames(vid_path)
        frames_np = frames_np.astype(np.uint8)
        frames_t = torch.from_numpy(frames_np).permute(0, 3, 1, 2)  # [T, C, H, W]
        processed = self.preprocessor(frames_t)  # [C, T, H, W]
        return processed, avg_fps

    def _read_video_frames(self, path: str):
        vr = VideoReader(path, ctx=cpu(0), num_threads=2)
        total = len(vr)
        if total < self.num_train_frames:
            raise ValueError(
                f"Insufficient frames in {path}: {total} < {self.num_train_frames}"
            )

        start_idx = random.randint(0, max(total - self.num_train_frames, 0))
        end_idx = start_idx + self.num_train_frames
        indices = list(range(start_idx, end_idx))

        batch = vr.get_batch(indices).asnumpy()
        try:
            fps = vr.get_avg_fps()
        except Exception:
            fps = 16.0

        del vr
        return batch, fps

    def _load_single_image(self, img_path: str):
        pil_img = Image.open(img_path).convert("RGB")
        tensor_img = self.preprocessor(pil_img)
        return tensor_img


class LocalDiffusersValDataset(Dataset):
    """
    Validation dataset: only loads prompts and sampling parameters.
    """

    def setup(self, config: CosmosConfig, *args, **kwargs):
        if not config.validation.enable:
            logger.warning("Validation disabled; skipping setup.")
            return

        val_json_path = config.validation.dataset.local_dir
        self.is_video_val = config.policy.diffusers.is_video
        self.val_h, self.val_w = config.policy.diffusers.inference_size
        self.val_num_frames = config.policy.diffusers.inference_frames
        self.sample_steps = config.policy.diffusers.sample.num_steps
        self.scale = config.policy.diffusers.sample.guidance_scale

        with open(val_json_path, 'r') as f:
            self.prompts_list = json.load(f)

    def __len__(self):
        return len(self.prompts_list)

    def __getitem__(self, idx: int) -> Dict[str, Any]:
        prompt_entry = self.prompts_list[idx]
        out = {
            "height": self.val_h,
            "width": self.val_w,
            "guidance_scale": self.scale,
            "inference_step": self.sample_steps,
            "prompt": prompt_entry["prompt"],
        }
        if self.is_video_val:
            out["frames"] = self.val_num_frames
        return out


class DiffusersPacker(BaseDataPacker):
