from cosmos_rl.policy.model.base import WeightMapper
from transformers.models.qwen2_5_vl.configuration_qwen2_5_vl import Qwen2_5_VLConfig
import torch
from cosmos_rl.utils import util
from transformers import AutoConfig
from typing import List, Tuple, Optional, Dict, Any
import re


class QwenVL25WeightMapper(WeightMapper):
    def __init__(self, hf_config: AutoConfig):
        super().__init__(hf_config)
        if not isinstance(self.config, Qwen2_5_VLConfig):
            raise TypeError("Expected Qwen2_5_VLConfig instance")

        # Compute attention-related dimensions
        self._num_query_heads = self.config.num_attention_heads
        self._num_kv_heads = self.config.num_key_value_heads
        self._hidden_size = self.config.hidden_size

        # Precompute ratio and head dimension for reuse
        self._kv_head_ratio = self._num_query_heads // self._num_kv_heads
        self._head_dim = self._hidden_size // self._num_query_heads

    def _map_rollout_weight_name_to_hf(self, local_name: str) -> str:
        """Convert rollout weight name to HuggingFace format based on backend."""
        if self.backend == "vllm":
            return self._map_policy_weight_name_to_hf(local_name)
        elif self.backend == "trtllm":
            return self._remap_trtllm_name(local_name)
        else:
            raise ValueError(f"Unsupported backend: {self.backend}")

    def _remap_trtllm_name(self, name: str) -> str:
        """Handle TRT-LLM specific name transformations."""
        if name.startswith("llm.model."):
            return name.replace("llm.model.", "model.")
        elif name.startswith("llm.lm_head."):
            return name.replace("llm.lm_head.", "lm_head.")
        elif name.startswith("mm_encoder."):
            # Replace dots with 'visual.' prefix for visual module
            return "visual." + name[len("mm_encoder.") - 1:].replace(".", ".")
        else:
            return name

    def _split_qkv_tensor(self, tensor: torch.Tensor, is_visual: bool) -> Tuple[torch.Tensor, ...]:
        """Split QKV tensor into separate Q, K, V components."""
        total_features = tensor.shape[0]
        if is_visual:
            # Visual modules have equal heads: q=k=v
            assert total_features % 3 == 0, "Invalid QKV size for visual module"
            chunk_size = total_features // 3
            return (
                tensor[:chunk_size],
                tensor[chunk_size : 2 * chunk_size],
                tensor[2 * chunk_size :]
            )
        else:
            # Language model: Q has more heads than K/V
            share_unit = total_features // (self._kv_head_ratio + 2)
            q_len = share_unit * self._kv_head_ratio
            k_len = share_unit
            v_len = share_unit
            return (
                tensor[:q_len],
                tensor[q_len : q_len + k_len],
                tensor[q_len + k_len :]
            )

    def _decompose_gate_up_projection(self, combined: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        """Decompose fused gate+up projection weights."""
        mid_point = combined.shape[0] // 2
        return combined[:mid_point], combined[mid_point:]

    def _create_split_entries(
        self,
        base_key: str,
        parts: Tuple[torch.Tensor, ...],
        suffixes: Tuple[str, ...]
    ) -> List[Tuple[str, torch.Tensor]]:
        """Helper to generate list of (key, tensor) pairs from split tensors."""
        result = []
        for idx, part in enumerate(parts):
            new_key = base_key.replace("qkv", suffixes[idx])
            result.append((new_key, part))
        return result

    def rollout_split_local_key_n_param_to_hf_key_n_param(
        self, param_name: str, param: torch.Tensor
    ) -> List[Tuple[str, torch.Tensor]]:
        """Split and remap parameters according to HuggingFace naming conventions."""
        mapped_name = self._map_rollout_weight_name_to_hf(param_name)

        # Handle QKV projections
        if "qkv_proj" in mapped_name:
            q, k, v = self._split_qkv_tensor(param, is_visual=False)
            return self._create_split_entries(mapped_name, (q, k, v), ("q_proj", "k_proj", "v_proj"))

        # Handle fused gate+up projections
        elif "gate_up_proj" in mapped_name:
            gate, up = self._decompose_gate_up_projection(param)
            return [
                (mapped_name.replace("gate_up_proj", "gate_proj"), gate),
                (mapped_name.replace("gate_up_proj", "up_proj"), up)
            ]

        # Handle visual QKV (different naming pattern)
        elif "qkv" in mapped_name and "visual" in mapped_name:
            q, k, v = self._split_qkv_tensor(param, is_visual=True)
            return self._create_split_entries(mapped_name, (q, k, v), ("q", "k", "v"))

        # Default: no splitting needed
        else:
            return [(mapped_name, param)]

    def _map_policy_weight_name_to_hf(self, raw_name: str) -> str:
        """Normalize policy weight names to match HF checkpoint keys."""
        normalized = util.clear_weight_name(raw_name)
        if normalized.startswith("language_model."):
            normalized = normalized[len("language_model."):]
        if normalized == "model.lm_head.weight":
            normalized = "lm_head.weight"
        return normalized

    def name_to_model_part_index(self, dest_name: str) -> int:
        """Determine which model component (language/visual) a weight belongs to."""
        if dest_name in ("lm_head.weight", "lm_head.bias"):
            return 0
        elif dest_name.startswith("visual."):
            return 1
        elif dest_name.startswith("model."):
            return 0
        else:
            raise ValueError(f"Unrecognized destination key: {dest_name}")

    def policy_decompose_param_1_to_n_for_sync(self, src_name: str) -> List[Tuple[str, Dict[str, Any]]]:
        """Define how to decompose fused parameters during synchronization."""
        # Match only visual block QKV weights/biases
        match = re.search(r"visual\.blocks\.(\d+)\.attn\.qkv\.(weight|bias)", src_name)
        if match:
            layer_idx = match.group(1)
            suffix = match.group(2)
            splits = []
            for i, label in enumerate(["q", "k", "v"]):
                new_name = f"visual.blocks.{layer_idx}.attn.{label}.{suffix}"
                splits.append((
                    new_name,
                    {
                        0: {
                            "offset": i,
                            "total_size": 3,
                            "length": 1
                        }
                    }
                ))
            return splits
        return []

