from werkzeug.utils import secure_filename
from pathlib import Path

# Define maximum upload size as 10 MB
MAX_FILE_SIZE = 10 * 1024 * 1024

# Supported certificate file extensions
CERTIFICATE_TYPES = {'.pem', '.crt', '.cer', '.p12', '.pfx', '.p7b', '.der', '.key'}
# JSON file extensions
JSON_TYPE = {'.json'}
# Backup archive extensions
BACKUP_TYPES = {'.zip', '.enc'}

def check_upload(file_obj, valid_extensions=None, limit_size=MAX_FILE_SIZE):
    """Check an uploaded file. Returns (content_bytes, sanitized_name) or raises ValueError."""
    # Ensure file object and filename exist
    if not file_obj or not hasattr(file_obj, 'filename') or not file_obj.filename:
        raise ValueError("No file provided")

    # Sanitize the filename using secure_filename
    clean_name = secure_filename(file_obj.filename)
    if not clean_name:
        raise ValueError("Invalid filename")

    # Check extension if allowed extensions are specified
    if valid_extensions is not None:
        file_suffix = Path(clean_name).suffix.lower()
        if file_suffix not in valid_extensions:
            raise ValueError(f"Unsupported file format: {file_suffix}")

    # Read file content with size limit
    raw_data = file_obj.read(limit_size + 1)
    if len(raw_data) > limit_size:
        max_mb = limit_size // (1024 * 1024)
        raise ValueError(f"File exceeds size limit ({max_mb}MB)")

    return raw_data, clean_name

import subprocess
from threading import Thread
from subprocess import Popen
from threading import Event

def terminate_threads(threads: list[Thread]):
    """Gracefully terminate a collection of threads"""
    for t in threads:
        t.join(timeout=5)

def terminate_subprocesses(proc_list: list[Popen]):
    """Safely terminate a list of running subprocesses"""
    for proc in proc_list:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except subprocess.TimeoutExpired:
                proc.kill()

def watch_subprocess(proc: Popen, shutdown_flag: Event, error_log: list, label: str):
    """Observe a subprocess and log errors to a shared container."""
    exit_code = proc.wait()
    if exit_code != 0:
        msg = f"{label.capitalize()} failed with exit code {exit_code}"
        if proc.stderr:
            try:
                stderr_output = proc.stderr.read().decode('utf-8')
                if stderr_output.strip():
                    msg += f"\n{stderr_output}"
            except Exception:
                pass
        error_log.append(RuntimeError(msg))
    shutdown_flag.set()

from typing import List
from ripperdoc.utils.file_watch import ChangedFileNotice

def _format_changed_file_notice(notices: List[ChangedFileNotice]) -> str:
    """Generate a formatted message regarding files that have been modified on disk."""
    output_lines = [
        "System notice: Files you previously read have changed on disk.",
        "Please re-read the affected files before making further edits.",
        "",
    ]

    for item in notices:
        output_lines.append(f"- {item.file_path}")
        summary_text = (item.summary or "").rstrip()
        if summary_text:
            # Split the summary into lines and indent each line
            processed_summary = "\n".join(
                f"    {line}" for line in summary_text.splitlines()
            )
            output_lines.append(processed_summary)

    return "\n".join(output_lines)

import torch
import torch.nn as nn
from einops import rearrange, repeat
import math

def generate_time_embeddings(time_indices, embedding_dim, max_duration=10000, only_repeat=False, tensor_type=torch.float32):
    if not only_repeat:
        half_dim = embedding_dim // 2
        angular_freqs = torch.exp(-math.log(max_duration) * torch.arange(start=0, end=half_dim, dtype=torch.float32, device=time_indices.device) / half_dim)
        scaled_time = time_indices[:, None].float() * angular_freqs[None]
        positional_encoding = torch.cat([torch.cos(scaled_time), torch.sin(scaled_time)], dim=-1)
        if embedding_dim % 2 == 1:
            positional_encoding = torch.cat([positional_encoding, torch.zeros_like(positional_encoding[:, :1])], dim=-1)
    else:
        positional_encoding = repeat(time_indices, "batch -> batch features", features=embedding_dim)
    return positional_encoding.to(tensor_type)

class TemporalFeatureEmbedder(nn.Module):
    def __init__(self, feature_size, projection_dim=None, max_duration=10000, only_repeat=False):
        super().__init__()
        self.feature_size = feature_size
        self.projection_dim = projection_dim if projection_dim is not None else feature_size
        self.max_duration = max_duration
        self.only_repeat = only_repeat

        self.temporal_projector = nn.Sequential(
            nn.Linear(self.feature_size, self.projection_dim),
            nn.SiLU(),
            nn.Linear(self.projection_dim, self.projection_dim),
        )

    @property
    def data_type(self) -> torch.dtype:
        """Determines the data type of the module (assuming uniform parameter types)."""
        parameters = tuple(self.parameters())
        if len(parameters) > 0:
            return parameters[0].dtype
        else:
            buffers = tuple(self.buffers())
            return buffers[0].dtype

    def forward(self, time_steps):
        encoded = generate_time_embeddings(time_steps, self.feature_size, self.max_duration, self.only_repeat, tensor_type=self.data_type)
        return self.temporal_projector(encoded)

