from .seeit import draw_box
from . import LayoutRecognizer, TableStructureRecognizer, OCR, init_in_out
import argparse


def execute_pipeline(args):
    # Initialize input images and output paths
    image_list, result_paths = init_in_out(args)

    # Determine processing mode
    if args.mode.lower() == "layout":
        detector = LayoutRecognizer("layout")
        detections = detector(image_list, thr=float(args.threshold))
    elif args.mode.lower() == "tsr":
        table_detector = TableStructureRecognizer()
        ocr_engine = OCR()
        detections = table_detector(image_list, thr=float(args.threshold))

    # Process each image
    for idx, layout in enumerate(detections):
        if args.mode.lower() == "tsr":
            # Generate HTML for table structure recognition
            html_content = generate_table_html(image_list[idx], layout, ocr_engine)
            with open(result_paths[idx] + ".html", "w+", encoding='utf-8') as file:
                file.write(html_content)

            # Normalize layout bounding boxes for visualization
            normalized_layout = [
                {
                    "type": item["label"],
                    "bbox": [item["x0"], item["top"], item["x1"], item["bottom"]],
                    "score": item["score"]
                }
                for item in layout
            ]
            layout = normalized_layout

        # Draw bounding boxes on image
        annotated_image = draw_box(image_list[idx], layout, getattr(detector, 'labels', None), float(args.threshold))
        annotated_image.save(result_paths[idx], quality=95)
        logging.info(f"Saved result to: {result_paths[idx]}")


def generate_table_html(image_data, table_components, ocr_processor):
    # Perform OCR on the image
    ocr_results = ocr_processor(np.array(image_data))

    # Preprocess OCR results into structured format
    processed_boxes = []
    for box_coords, text_info in ocr_results:
        if not (box_coords[0][0] > box_coords[1][0] or box_coords[0][1] > box_coords[-1][1]):
            processed_boxes.append({
                "x0": box_coords[0][0],
                "x1": box_coords[1][0],
                "top": box_coords[0][1],
                "text": text_info[0],
                "bottom": box_coords[-1][1],
                "layout_type": "table",
                "page_number": 0
            })

    # Sort OCR results vertically
    avg_height = np.mean([b["bottom"] - b["top"] for b in processed_boxes]) / 3 if processed_boxes else 0
    sorted_boxes = LayoutRecognizer.sort_Y_firstly(processed_boxes, avg_height)

    # Helper function to collect specific components by regex pattern
    def extract_by_pattern(keyword, tolerance=10, overlap_ratio=0.6):
        nonlocal sorted_boxes
        candidates = LayoutRecognizer.sort_Y_firstly(
            [comp for comp in table_components if re.match(keyword, comp["label"])], tolerance)
        cleaned = LayoutRecognizer.layouts_cleanup(sorted_boxes, candidates, 5, overlap_ratio)
        return LayoutRecognizer.sort_Y_firstly(cleaned, 0)

    # Extract table elements
    headers = extract_by_pattern(r".*header$")
    rows = extract_by_pattern(r".* (row|header)")
    spans = extract_by_pattern(r".*spanning")
    columns = sorted(
        [item for item in table_components if re.match(r"table column$", item["label"])],
        key=lambda x: x["x0"]
    )
    columns = LayoutRecognizer.layouts_cleanup(sorted_boxes, columns, 5, 0.5)

    # Assign row/column/header relationships to each OCR box
    for box in sorted_boxes:
        # Match with rows
        row_idx = LayoutRecognizer.find_overlapped_with_threshold(box, rows, thr=0.3)
        if row_idx is not None:
            box["R"] = row_idx
            box["R_top"] = rows[row_idx]["top"]
            box["R_bott"] = rows[row_idx]["bottom"]

        # Match with headers
        header_idx = LayoutRecognizer.find_overlapped_with_threshold(box, headers, thr=0.3)
        if header_idx is not None:
            box["H_top"] = headers[header_idx]["top"]
            box["H_bott"] = headers[header_idx]["bottom"]
            box["H_left"] = headers[header_idx]["x0"]
            box["H_right"] = headers[header_idx]["x1"]
            box["H"] = header_idx

        # Match with columns
        col_idx = LayoutRecognizer.find_horizontally_tightest_fit(box, columns)
        if col_idx is not None:
            box["C"] = col_idx
            box["C_left"] = columns[col_idx]["x0"]
            box["C_right"] = columns[col_idx]["x1"]

        # Match with spanning cells
        span_idx = LayoutRecognizer.find_overlapped_with_threshold(box, spans, thr=0.3)
        if span_idx is not None:
            box["H_top"] = spans[span_idx]["top"]
            box["H_bott"] = spans[span_idx]["bottom"]
            box["H_left"] = spans[span_idx]["x0"]
            box["H_right"] = spans[span_idx]["x1"]
            box["SP"] = span_idx

    # Construct HTML template
    html_template = """
    <html>
    <head>
    <style>
    ._table_1nkzy_11 {
      margin: auto;
      width: 70%%;
      padding: 10px;
    }
    ._table_1nkzy_11 p {
      margin-bottom: 50px;
      border: 1px solid #e1e1e1;
    }
    caption {
      color: #6ac1ca;
      font-size: 20px;
      height: 50px;
      line-height: 50px;
      font-weight: 600;
      margin-bottom: 10px;
    }
    ._table_1nkzy_11 table {
      width: 100%%;
      border-collapse: collapse;
    }
    th {
      color: #fff;
      background-color: #6ac1ca;
    }
    td:hover {
      background: #c1e8e8;
    }
    tr:nth-child(even) {
      background-color: #f2f2f2;
    }
    ._table_1nkzy_11 th,
    ._table_1nkzy_11 td {
      text-align: center;
      border: 1px solid #ddd;
      padding: 8px;
    }
    </style>
    </head>
    <body>
    %s
    </body>
    </html>
""" % TableStructureRecognizer.construct_table(sorted_boxes, html=True)

    return html_template


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Document layout analysis and table structure recognition pipeline")
    parser.add_argument('--inputs',
                        help="Path to directory containing images or PDFs, or a single image/PDF file",
                        required=True)
    parser.add_argument('--output_dir',
                        help="Directory to save output images. Default: './layouts_outputs'",
                        default="./layouts_outputs")
    parser.add_argument('--threshold',
                        help="Detection confidence threshold. Default: 0.5",
                        default=0.5)
    parser.add_argument('--mode',
                        help="Processing mode: 'layout' for general layout detection, 'tsr' for table structure recognition",
                        choices=["layout", "tsr"],
                        default="layout")

    arguments = parser.parse_args()
    execute_pipeline(arguments)

