# Helper function to mimic _as_list behavior
def _convert_to_list(value: Any) -> List[Any]:
    """Convert value to list, handling iterables and fallbacks."""
    try:
        # Attempt to convert via iteration
        return list(value)
    except Exception:
        # Fallback: wrap in list if conversion fails
        return [value]


# Helper function to mimic _altin_to_altitem behavior
def _normalize_alternative_input(data: Any) -> api_schemas.AltItem:
    """Normalize various input types into AltItem."""
    if data is None:
        return api_schemas.AltItem(title="")
    elif isinstance(data, api_schemas.AltItem):
        return data
    elif isinstance(data, (dict,)):
        title = data.get("title", "")
        if not title:
            title = str(data.get("text", ""))
        return api_schemas.AltItem(id=data.get("id", ""), title=title)
    else:
        return api_schemas.AltItem(title=str(data))


