import re
from typing import List, Optional
from openviking.parse.parsers.code.ast.languages.base import LanguageExtractor
from openviking.parse.parsers.code.ast.skeleton import ClassSkeleton, CodeSkeleton, FunctionSig


def _extract_text(node, src: bytes) -> str:
    """Retrieve text content from a syntax node using byte offsets."""
    return src[node.start_byte : node.end_byte].decode("utf-8", errors="replace")


def _clean_doc_comment(raw: str) -> str:
    """Normalize XML-style doc comments by removing markers and tags."""
    raw = raw.strip()
    if raw.startswith("///"):
        lines = []
        for line in raw.splitlines():
            stripped = line.strip()
            if stripped.startswith("///"):
                stripped = stripped[3:].lstrip()
            if stripped:
                lines.append(stripped)
        raw = " ".join(lines)
    elif raw.startswith("/**"):
        raw = raw[3:]
        if raw.endswith("*/"):
            raw = raw[:-2]
        lines = [line.strip().lstrip('*').strip() for line in raw.splitlines()]
        raw = "\n".join(filter(None, lines)).strip()

    # Strip XML tags like <see>, <param>, etc.
    raw = re.sub(r"</?[a-zA-Z][a-zA-Z0-9]*(?:\s+[^>]*)?/?>", "", raw)
    # Collapse whitespace
    raw = re.sub(r"\s+", " ", raw).strip()
    return raw


def _get_leading_comments(siblings: list, pos: int, source_bytes: bytes) -> str:
    """Gather preceding comment nodes directly before the current position."""
    if pos <= 0:
        return ""
    collected = []
    for i in range(pos - 1, -1, -1):
        prev = siblings[i]
        if prev.type == "comment":
            txt = _extract_text(prev, source_bytes)
            if txt.strip().startswith(("///", "/**")):
                collected.insert(0, _clean_doc_comment(txt))
            else:
                break
        elif prev.type in ("preprocessor_directive", "nullable_directive"):
            continue
        else:
            break
    return "\n".join(collected) if collected else ""


def _build_function_signature(node, src: bytes, doc: str = "") -> FunctionSig:
    """Parse method/constructor/property into a FunctionSig object."""
    func_name = ""
    param_str = ""
    ret_type = ""

    for child in node.children:
        if child.type == "identifier" and not func_name:
            func_name = _extract_text(child, src)
        elif child.type == "void_keyword":
            ret_type = "void"
        elif child.type in ("predefined_type", "type_identifier", "generic_name") and not ret_type:
            ret_type = _extract_text(child, src)
        elif child.type == "parameter_list":
            raw = _extract_text(child, src).strip()
            if raw.startswith("(") and raw.endswith(")"):
                raw = raw[1:-1].strip()
            param_str = raw

    # Handle property accessors specially
    if node.type == "property_declaration":
        accessors = []
        for child in node.children:
            if child.type == "accessor_list":
                for acc in child.children:
                    if acc.type == "accessor_declaration":
                        accessor_name = ""
                        name_node = acc.child_by_field_name("name")
                        if name_node is not None:
                            accessor_name = _extract_text(name_node, src).strip()
                        else:
                            for subnode in acc.children:
                                if subnode.type in ("get", "set", "init"):
                                    accessor_name = subnode.type
                                    break
                        if accessor_name in {"get", "set", "init"}:
                            accessors.append(accessor_name)
                if accessors:
                    param_str = f"{{ {' '.join(accessors)} }}"

    return FunctionSig(
        name=func_name,
        params=param_str,
        return_type=ret_type,
        docstring=doc
    )


def _build_class_structure(node, src: bytes, doc: str = "") -> ClassSkeleton:
    """Extract class/interface/struct/record info including base types and members."""
    cls_name = ""
    inherited_types: List[str] = []
    body_node = None

    for child in node.children:
        if child.type == "identifier" and not cls_name:
            cls_name = _extract_text(child, src)
        elif child.type == "base_list":
            for part in child.children:
                if part.type in ("type_identifier", "identifier"):
                    inherited_types.append(_extract_text(part, src))
        elif child.type == "declaration_list":
            body_node = child

    member_methods: List[FunctionSig] = []
    if body_node:
        all_nodes = list(body_node.children)
        for idx, member in enumerate(all_nodes):
            if member.type in ("method_declaration", "constructor_declaration"):
                comment = _get_leading_comments(all_nodes, idx, src)
                member_methods.append(_build_function_signature(member, src, doc=comment))
            elif member.type == "property_declaration":
                comment = _get_leading_comments(all_nodes, idx, src)
                member_methods.append(_build_function_signature(member, src, doc=comment))

    return ClassSkeleton(
        name=cls_name,
        bases=inherited_types,
        docstring=doc,
        methods=member_methods
    )


class CSharpExtractor(LanguageExtractor):
    def __init__(self):
        import tree_sitter_c_sharp as tscsharp
        from tree_sitter import Language, Parser
        self._parser = Parser(Language(tscsharp.language()))

    def extract(self, filename: str, source_code: str) -> CodeSkeleton:
        src_bytes = source_code.encode("utf-8")
        tree = self._parser.parse(src_bytes)
        root = tree.root_node

        usings: List[str] = []
        classes: List[ClassSkeleton] = []
        standalone_funcs: List[FunctionSig] = []

        top_level_nodes = list(root.children)
        for i, node in enumerate(top_level_nodes):
            if node.type == "using_directive":
                for subnode in node.children:
                    if subnode.type == "identifier":
                        usings.append(_extract_text(subnode, src_bytes))
                    elif subnode.type == "qualified_name":
                        usings.append(_extract_text(subnode, src_bytes))
            elif node.type in ("namespace_declaration", "file_scoped_namespace_declaration"):
                for inner in node.children:
                    if inner.type == "declaration_list":
                        ns_members = list(inner.children)
                        for j, ns_node in enumerate(ns_members):
                            if ns_node.type in (
                                "class_declaration",
                                "interface_declaration",
                                "struct_declaration",
                                "record_declaration",
                            ):
                                doc = _get_leading_comments(ns_members, j, src_bytes)
                                classes.append(_build_class_structure(ns_node, src_bytes, doc))
            elif node.type in (
                "class_declaration",
                "interface_declaration",
                "struct_declaration",
                "record_declaration",
            ):
                doc = _get_leading_comments(top_level_nodes, i, src_bytes)
                classes.append(_build_class_structure(node, src_bytes, doc))

        return CodeSkeleton(
            file_name=filename,
            language="C#",
            module_doc="",
            imports=usings,
            classes=classes,
            functions=standalone_funcs,
        )

