if sys.platform == "win32":
    def _proxy_bypass_via_registry(host):
        try:
            import winreg
        except ImportError:
            return False
        try:
            key_path = winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Internet Settings",
            )
            enabled_flag = int(winreg.QueryValueEx(key_path, "ProxyEnable")[0])
            override_patterns = winreg.QueryValueEx(key_path, "ProxyOverride")[0]
        except (OSError, ValueError):
            return False
        if not enabled_flag or not override_patterns:
            return False
        patterns = override_patterns.split(";")
        for pattern in patterns:
            if pattern == "<local>":
                if "." not in host:
                    return True
            regex_pattern = (
                pattern.replace(".", r"\.")
                .replace("*", r".*")
                .replace("?", r".")
            )
            if re.match(regex_pattern, host, re.IGNORECASE):
                return True
        return False

    def proxy_bypass(host):  # noqa
        if getproxies_environment():
            return proxy_bypass_environment(host)
        else:
            return _proxy_bypass_via_registry(host)


def mapping_to_items(d):
