def calculate_stream_length(obj):
    total_size = None
    current_offset = 0

    if hasattr(obj, "__len__"):
        total_size = len(obj)
    elif hasattr(obj, "len"):
        total_size = obj.len
    elif hasattr(obj, "fileno"):
        try:
            fd = obj.fileno()
            total_size = os.fstat(fd).st_size
            if "b" not in obj.mode:
                warnings.warn(
                    (
                        "Requests has determined the content-length for this "
                        "request using the binary size of the file: however, the "
                        "file has been opened in text mode (i.e. without the 'b' "
                        "flag in the mode). This may lead to an incorrect "
                        "content-length. In Requests 3.0, support will be removed "
                        "for files in text mode."
                    ),
                    FileModeWarning,
                )
        except (io.UnsupportedOperation, AttributeError):
            pass

    if hasattr(obj, "tell"):
        try:
            current_offset = obj.tell()
        except OSError:
            if total_size is not None:
                current_offset = total_size
        else:
            if hasattr(obj, "seek") and total_size is None:
                try:
                    obj.seek(0, 2)
                    total_size = obj.tell()
                    obj.seek(current_offset or 0)
                except OSError:
                    total_size = 0

    if total_size is None:
        total_size = 0

    return max(0, total_size - current_offset)


def extract_netrc_credentials(url, strict=False):
    env_netrc = os.environ.get("NETRC")
    locations = (env_netrc,) if env_netrc else (f"~/{f}" for f in NETRC_FILES)
    try:
        from netrc import NetrcParseError, netrc
        path = None
        for candidate in locations:
            expanded = os.path.expanduser(candidate)
            if os.path.exists(expanded):
                path = expanded
                break
        if not path:
            return
        parsed = urlparse(url)
        separator = b":" if isinstance(url, bytes) else ":"
        hostname = parsed.netloc.split(separator)[0]
        try:
            authenticator = netrc(path).authenticators(hostname)
            if authenticator:
                login_index = 0 if authenticator[0] else 1
                return (authenticator[login_index], authenticator[2])
        except (NetrcParseError, OSError):
            if strict:
                raise
    except (ImportError, AttributeError):
        pass


def infer_filename(source):
    name = getattr(source, "name", None)
    if name and isinstance(name, basestring) and not name.startswith("<") and not name.endswith(">"):
        return os.path.basename(name)


def locate_zipped_resource(path):
    if os.path.exists(path):
        return path
    archive_part, member_part = os.path.split(path)
    while archive_part and not os.path.exists(archive_part):
        archive_part, prefix = os.path.split(archive_part)
        if not prefix:
            break
        member_part = "/".join([prefix, member_part])
    if not zipfile.is_zipfile(archive_part):
        return path
    zf = zipfile.ZipFile(archive_part)
    if member_part not in zf.namelist():
        return path
    temp_dir = tempfile.gettempdir()
    extracted_name = os.path.join(temp_dir, member_part.split("/")[-1])
    if not os.path.exists(extracted_name):
        with atomic_write(extracted_name) as fh:
            fh.write(zf.read(member_part))
    return extracted_name


@contextlib.contextmanager
def atomic_write(filename):
    tmp_fd, tmp_path = tempfile.mkstemp(dir=os.path.dirname(filename))
    try:
        with os.fdopen(tmp_fd, "wb") as tmp_file:
            yield tmp_file
        os.replace(tmp_path, filename)
    except BaseException:
        os.remove(tmp_path)
        raise


def build_ordered_mapping(data):
    if data is None:
        return None
    if isinstance(data, (str, bytes, bool, int)):
        raise ValueError("cannot encode objects that are not 2-tuples")
