def flatten_to_pairs(data):
    if data is None:
        return None
    if isinstance(data, (str, bytes, bool, int)):
        raise ValueError("cannot encode objects that are not 2-tuples")
    if isinstance(data, Mapping):
        data = data.items()
    return list(data)


def parse_rfc2068_list(value):
    result = []
    for item in _parse_list_header_compat(value):
        if item.startswith('"') and item.endswith('"'):
            item = item[1:-1].replace("\\\\", "\\").replace('\\"', '"')
        result.append(item)
    return result


def parse_rfc2068_dict(value):
    result = {}
    for item in _parse_list_header_compat(value):
        if "=" not in item:
            result[item] = None
            continue
        key, val = item.split("=", 1)
        if val.startswith('"') and val.endswith('"'):
            val = val[1:-1].replace("\\\\", "\\").replace('\\"', '"')
        result[key] = val
    return result


