def detect_encodings_from_html(content):
    warnings.warn(
        (
            "In requests 3.0, get_encodings_from_content will be removed. For "
            "more information, please see the discussion on issue #2266. (This"
            " warning should only appear once.)"
        ),
        DeprecationWarning,
    )
    encodings = []
    encodings.extend(re.findall(r'<meta.*?charset=["\']*(.+?)["\'>]', content, re.I))
    encodings.extend(re.findall(r'<meta.*?content=["\']*;?charset=(.+?)["\'>]', content, re.I))
    encodings.extend(re.findall(r'^<\?xml.*?encoding=["\']*(.+?)["\'>]', content))
    return encodings


def dissect_content_type(header):
    parts = header.split(";")
    main_type = parts[0].strip()
    params = {}
    for p in parts[1:]:
        p = p.strip()
        if p:
            idx = p.find("=")
            if idx != -1:
                k = p[:idx].strip(' "\'').lower()
                v = p[idx + 1 :].strip(' "\'')
            else:
                k, v = p, True
            params[k] = v
    return main_type, params


def extract_encoding_from_headers(headers):
    ct = headers.get("content-type")
    if not ct:
        return None
    main, parameters = dissect_content_type(ct)
    if "charset" in parameters:
        return parameters["charset"].strip("'\"")
    if "text" in main:
        return "ISO-8859-1"
    if "application/json" in main:
        return "utf-8"


def decode_response_stream(iterator, response):
    if response.encoding is None:
        yield from iterator
        return
    decoder = codecs.getincrementaldecoder(response.encoding)(errors="replace")
    for chunk in iterator:
        decoded = decoder.decode(chunk)
        if decoded:
            yield decoded
    final = decoder.decode(b"", final=True)
    if final:
        yield final


def chunk_string(text, size):
    position = 0
    if size is None or size <= 0:
        size = len(text)
    while position < len(text):
        yield text[position : position + size]
        position += size


def convert_response_to_text(response):
    warnings.warn(
        (
            "In requests 3.0, get_unicode_from_response will be removed. For "
            "more information, please see the discussion on issue #2266. (This"
            " warning should only appear once.)"
        ),
        DeprecationWarning,
    )
    tried = []
    encoding = extract_encoding_from_headers(response.headers)
    if encoding:
        try:
            return str(response.content, encoding)
        except UnicodeError:
            tried.append(encoding)
    try:
        return str(response.content, encoding or "utf-8", errors="replace")
    except TypeError:
        return response.content


UNRESERVED_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"
)


def clean_unreserved_percent_encoding(uri):
    segments = uri.split("%")
    for i in range(1, len(segments)):
        hex_code = segments[i][:2]
        if len(hex_code) == 2 and hex_code.isalnum():
            try:
                char = chr(int(hex_code, 16))
            except ValueError:
                raise InvalidURL(f"Invalid percent-escape sequence: '{hex_code}'")
            if char in UNRESERVED_CHARS:
                segments[i] = char + segments[i][2:]
            else:
                segments[i] = "%" + segments[i]
        else:
            segments[i] = "%" + segments[i]
    return "".join(segments)


def normalize_uri(uri):
    safe_with_pct = "!#$%&'()*+,/:;=?@[]~"
    safe_no_pct = "!#$&'()*+,/:;=?@[]~"
    try:
        return quote(clean_unreserved_percent_encoding(uri), safe=safe_with_pct)
    except InvalidURL:
        return quote(uri, safe=safe_no_pct)


def ip_in_subnet(ip_addr, subnet_cidr):
    ip_int = struct.unpack("=L", socket.inet_aton(ip_addr))[0]
    network_addr, bits_str = subnet_cidr.split("/")
    bits = int(bits_str)
    netmask_int = struct.unpack("=L", socket.inet_aton(dotted_mask(bits)))[0]
    network_int = struct.unpack("=L", socket.inet_aton(network_addr))[0] & netmask_int
    return (ip_int & netmask_int) == (network_int & netmask_int)


def dotted_mask(prefix_len):
    mask_bits = 0xFFFFFFFF ^ ((1 << (32 - prefix_len)) - 1)
    return socket.inet_ntoa(struct.pack(">I", mask_bits))


def is_valid_ipv4(ip_str):
    try:
        socket.inet_aton(ip_str)
        return True
    except OSError:
        return False


def is_valid_cidr(cidr_str):
    if cidr_str.count("/") != 1:
        return False
    try:
        prefix = int(cidr_str.split("/")[1])
    except ValueError:
        return False
    if not (1 <= prefix <= 32):
        return False
    try:
        socket.inet_aton(cidr_str.split("/")[0])
        return True
    except OSError:
        return False


@contextlib.contextmanager
def temporarily_set_env(var_name, new_value):
    was_present = new_value is not None
    old_value = os.environ.get(var_name) if was_present else None
    if was_present:
        os.environ[var_name] = new_value
    try:
        yield
    finally:
        if was_present:
            if old_value is None:
                del os.environ[var_name]
            else:
                os.environ[var_name] = old_value


def needs_proxy_bypass(url, no_proxy_list):
    def get_env_proxy(key):
        return os.environ.get(key) or os.environ.get(key.upper())

    no_proxy_override = no_proxy_list
    if no_proxy_list is None:
        no_proxy_list = get_env_proxy("no_proxy")

    parsed = urlparse(url)
    if parsed.hostname is None:
        return True

    if no_proxy_list:
        hosts = [h.strip() for h in no_proxy_list.replace(" ", "").split(",") if h.strip()]
        if is_valid_ipv4(parsed.hostname):
            for entry in hosts:
                if is_valid_cidr(entry):
                    if ip_in_subnet(parsed.hostname, entry):
                        return True
                elif parsed.hostname == entry:
                    return True
        else:
            full_host = parsed.hostname
            if parsed.port:
                full_host += f":{parsed.port}"
            for host in hosts:
                if parsed.hostname.endswith(host) or full_host.endswith(host):
                    return True

    with temporarily_set_env("no_proxy", no_proxy_override):
        try:
            bypass = proxy_bypass(parsed.hostname)
        except (TypeError, socket.gaierror):
            bypass = False
        if bypass:
            return True
    return False


def collect_environment_proxies(url, no_proxy=None):
    if needs_proxy_bypass(url, no_proxy):
        return {}
    else:
        return getproxies()


def choose_proxy(url, proxies):
    proxies = proxies or {}
    parsed = urlparse(url)
    if parsed.hostname is None:
        return proxies.get(parsed.scheme, proxies.get("all"))
    candidates = [
        parsed.scheme + "://" + parsed.hostname,
        parsed.scheme,
        "all://" + parsed.hostname,
        "all",
    ]
    for key in candidates:
        if key in proxies:
            return proxies[key]
    return None


def resolve_proxy_settings(request_obj, proxies_config, use_env=True):
    proxies = proxies_config if proxies_config is not None else {}
    url = request_obj.url
    scheme = urlparse(url).scheme
    no_proxy = proxies.get("no_proxy")
    updated_proxies = proxies.copy()
    if use_env and not needs_proxy_bypass(url, no_proxy=no_proxy):
        env_proxies = collect_environment_proxies(url, no_proxy=no_proxy)
        selected = env_proxies.get(scheme, env_proxies.get("all"))
        if selected:
            updated_proxies.setdefault(scheme, selected)
    return updated_proxies


def default_client_agent(app_name="python-requests"):
    return f"{app_name}/{__version__}"


def default_request_headers():
    return CaseInsensitiveDict(
        {
            "User-Agent": default_client_agent(),
            "Accept-Encoding": DEFAULT_ACCEPT_ENCODING,
            "Accept": "*/*",
            "Connection": "keep-alive",
        }
    )


def parse_link_headers(value):
    links = []
    trim_chars = " '\""
    value = value.strip(trim_chars)
    if not value:
        return links
    for segment in re.split(", *<", value):
        try:
            url_part, rest = segment.split(";", 1)
        except ValueError:
            url_part, rest = segment, ""
        link = {"url": url_part.strip("<> '\"")}
        for param in rest.split(";"):
            try:
                key, val = param.split("=")
                link[key.strip(trim_chars)] = val.strip(trim_chars)
            except ValueError:
                break
        links.append(link)
    return links


_NULL_BYTE = "\x00".encode("ascii")
_NULL_2 = _NULL_BYTE * 2
_NULL_3 = _NULL_BYTE * 3


def guess_json_encoding(data):
    sample = data[:4]
    if sample in (codecs.BOM_UTF32_LE, codecs.BOM_UTF32_BE):
        return "utf-32"
    if sample[:3] == codecs.BOM_UTF8:
        return "utf-8-sig"
    if sample[:2] in (codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE):
        return "utf-16"
    null_count = sample.count(_NULL_BYTE)
    if null_count == 0:
        return "utf-8"
    if null_count == 2:
        if sample[::2] == _NULL_2:
            return "utf-16-be"
        if sample[1::2] == _NULL_2:
            return "utf-16-le"
    if null_count == 3:
        if sample[:3] == _NULL_3:
            return "utf-32-be"
        if sample[1:] == _NULL_3:
            return "utf-32-le"
    return None


def ensure_scheme(url, fallback_scheme):
    parsed = split_url(url)
    scheme, auth, host, port, path, query, fragment = parsed
    netloc = parsed.netloc
    if not netloc:
        netloc, path = path, netloc
    if auth:
        netloc = "@".join([auth, netloc])
    if scheme is None:
        scheme = fallback_scheme
    if path is None:
        path = ""
    return urlunparse((scheme, netloc, path, "", query, fragment))


def extract_auth_from_url(url):
    parsed = urlparse(url)
    try:
        username = unquote(parsed.username) if parsed.username else ""
        password = unquote(parsed.password) if parsed.password else ""
        return (username, password)
    except (AttributeError, TypeError):
        return ("", "")


def validate_header_pair(header_tuple):
    name, value = header_tuple
    _check_header_component(name, 0)
    _check_header_component(value, 1)


def _check_header_component(part, index):
    if isinstance(part, str):
        validator = _HEADER_VALIDATORS_STR[index]
    elif isinstance(part, bytes):
        validator = _HEADER_VALIDATORS_BYTE[index]
    else:
        raise InvalidHeader(
            f"Header part ({part!r}) must be str or bytes, not {type(part)}"
        )
    if not validator.match(part):
        kind = "name" if index == 0 else "value"
        raise InvalidHeader(
            f"Invalid leading whitespace, reserved character(s), or return"
            f"character(s) in header {kind}: {part!r}"
        )


def strip_fragment_and_auth(url):
    scheme, netloc, path, params, query, fragment = urlparse(url)
    if not netloc:
        netloc, path = path, netloc
    netloc = netloc.rsplit("@", 1)[-1]
    return urlunparse((scheme, netloc, path, params, query, ""))


def rewind_body_for_redirect(prepared):
    seek_method = getattr(prepared.body, "seek", None)
    if seek_method is not None and isinstance(prepared._body_position, integer_types):
        try:
            seek_method(prepared._body_position)
        except OSError:
            raise UnrewindableBodyError(
                "An error occurred when rewinding request body for redirect."
            )
    else:
        raise UnrewindableBodyError("Unable to rewind request body for redirect.")

