# ============ BM25 IMPLEMENTATION (Modified) ============
class BM25Ranker:
    """Enhanced BM25 implementation with adjusted scoring parameters"""
    def __init__(self, k1=1.2, b=0.6):
        self.k1 = k1
        self.b = b
        self.corpus_tokens = []
        self.doc_lengths = []
        self.avgdl = 0.0
        self.idf_scores = {}
        self.word_doc_counts = Counter()
        self.total_docs = 0

    def _clean_and_split(self, text):
        """Normalize text: lowercase, strip punctuation, filter tokens"""
        normalized = re.sub(r'[^\w\s]', ' ', str(text).lower())
        tokens = [token.strip() for token in normalized.split()]
        return [t for t in tokens if len(t) > 2]

    def train(self, documents):
        """Build index from document collection"""
        self.corpus_tokens = [self._clean_and_split(doc) for doc in documents]
        self.total_docs = len(self.corpus_tokens)
        if self.total_docs == 0:
            return

        self.doc_lengths = [len(tokens) for tokens in self.corpus_tokens]
        self.avgdl = sum(self.doc_lengths) / self.total_docs

        # Document frequency calculation
        for doc in self.corpus_tokens:
            unique_terms = set(doc)
            for term in unique_terms:
                self.word_doc_counts[term] += 1

        # Compute IDF values
        for term, df in self.word_doc_counts.items():
            self.idf_scores[term] = log((self.total_docs - df + 0.5) / (df + 0.5) + 1)

    def rank(self, query_text):
        """Score documents against a query string"""
        query_tokens = self._clean_and_split(query_text)
        scores = []

        for doc_idx, doc in enumerate(self.corpus_tokens):
            score = 0.0
            doc_len = self.doc_lengths[doc_idx]

            # Term frequency per document
            term_freq = Counter(doc)

            for q_token in query_tokens:
                if q_token in self.idf_scores:
                    tf = term_freq[q_token]
                    idf = self.idf_scores[q_token]

                    numerator = tf * (self.k1 + 1)
                    denominator = tf + self.k1 * (1 - self.b + self.b * doc_len / self.avgdl)
                    score += idf * (numerator / denominator)

            scores.append((doc_idx, score))

        # Sort by descending score
        return sorted(scores, key=lambda x: x[1], reverse=True)

# ============ SEARCH FUNCTIONS ============
def _read_csv_file(path):
    """Read CSV file and return list of dictionaries"""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return list(csv.DictReader(f))
    except FileNotFoundError:
        return []

def _execute_search(file_path, input_cols, output_cols, search_query, top_k):
    """Core search logic using BM25 ranking"""
    if not file_path.exists():
        return []

    data = _read_csv_file(file_path)
    if not data:
        return []

    # Construct searchable documents
    docs = [" ".join(str(row.get(col, "")) for col in input_cols) for row in data]

    # Initialize and train BM25 model
    ranker = BM25Ranker()
    ranker.train(docs)

    # Get ranked results
    ranked_indices = ranker.rank(search_query)

    # Extract top-k results with positive scores
    results = []
    for idx, score in ranked_indices[:top_k]:
        if score > 0:
            row_data = data[idx]
            filtered_row = {field: row_data.get(field, "") for field in output_cols if field in row_data}
            results.append(filtered_row)

    return results

def _identify_category(query_text):
    """Determine most relevant domain based on keyword matching"""
    query_lower = query_text.lower()

    category_patterns = {
        "color": ["color", "palette", "hex", "#", "rgb"],
        "chart": ["chart", "graph", "visualization", "trend", "bar", "pie", "scatter", "heatmap", "funnel"],
        "landing": ["landing", "page", "cta", "conversion", "hero", "testimonial", "pricing", "section"],
