        "web": ["aria", "focus", "outline", "semantic", "virtualize", "autocomplete", "form", "input type", "preconnect"]
    }

    category_scores = {
        cat: sum(1 for kw in keywords if kw in query_lower)
        for cat, keywords in category_patterns.items()
    }

    best_match = max(category_scores, key=category_scores.get)
    return best_match if category_scores[best_match] > 0 else "style"

def execute_search(query, category=None, limit=TOP_K_RESULTS):
    """Main search interface with auto-detection"""
    if category is None:
        category = _identify_category(query)

    config = CSV_SETTINGS.get(category, CSV_SETTINGS["style"])
    file_path = DATA_DIR / config["filename"]

    if not file_path.exists():
        return {
            "error": f"File not found: {file_path}",
