from functools import wraps
from typing import Callable, TypeVar, Optional
from psycopg.errors import UniqueViolation
from sqlalchemy import UniqueConstraint
from sqlalchemy.exc import IntegrityError as SQLAIntegrityError
from sqlalchemy.inspection import inspect

T = TypeVar("T")

def handle_duplicate_entries(func: Callable[..., T]) -> Callable[..., Optional[T]]:
    """
    Decorator that intercepts duplicate insertion attempts and retrieves the existing record.

    When a database integrity error due to unique constraint violation occurs,
    this decorator attempts to locate the conflicting record by checking each
    unique constraint defined on the model's table. If no match is found via
    unique constraints, it falls back to searching using primary key values.
    """
    @wraps(func)
    def inner_wrapper(*args, **kwargs) -> Optional[T]:
        try:
            return func(*args, **kwargs)
        except SQLAIntegrityError as exc:
            if isinstance(exc.orig, UniqueViolation):
                # Extract relevant objects from function arguments
                instance_model = args[0].model
                session = args[1]
                input_data = args[2]

                # Rollback failed transaction to allow new queries
                session.rollback()

                # Prepare data dictionary from the input object
                input_dict = input_data.model_dump()

                # Get model metadata for introspection
                model_inspector = inspect(instance_model)
                target_table = model_inspector.local_table

                # Try matching against each unique constraint
                for constraint in target_table.constraints:
                    if isinstance(constraint, UniqueConstraint):
                        base_query = session.query(instance_model)
                        all_fields_available = True

                        for col in constraint.columns:
                            if col.name in input_dict:
                                base_query = base_query.filter(
                                    getattr(instance_model, col.name) == input_dict[col.name]
                                )
                            else:
                                all_fields_available = False
                                break

                        if all_fields_available:
                            candidate = base_query.first()
                            if candidate is not None:
                                return candidate

                # Fallback: attempt lookup using primary key fields
                pk_query = session.query(instance_model)
                for pk_col in model_inspector.primary_key:
                    if pk_col.name in input_dict:
                        pk_query = pk_query.filter(
                            getattr(instance_model, pk_col.name) == input_dict[pk_col.name]
                        )

                result = pk_query.first()
                if result is not None:
                    return result

            # Re-raise if no duplicate handling was possible
            raise

    return inner_wrapper

