# Import necessary modules for pattern matching and evaluation
import re

# Base judge class (assumed to be defined elsewhere)
class BaseJudge:
    pass

# Workflow classes (assumed to be defined elsewhere)
class WorkflowOutput:
    pass

class WorkflowTask:
    pass


class CountdownAnswerAsJudge(BaseJudge):
    def __init__(self, config):
        self.config = config
        self.format_score = 0.1
        self.correct_score = 1.0

    def _check_equation_numbers(self, equation_str, available_numbers):
        try:
            # Extract all numbers from the equation string
            extracted_nums = sorted([int(digit) for digit in re.findall(r"\d+", equation_str)])
            # Sort the provided numbers for comparison
            original_nums = sorted(available_numbers)
            return extracted_nums == original_nums
        except Exception:
            return False

    def _compute_result(self, equation_str):
        try:
            # Define allowed characters using regex
            if not re.match(r"^[\d+\-*/().\s]+$", equation_str):
                raise ValueError("Equation contains disallowed characters.")
            # Safely evaluate the expression without built-in functions
            computed_value = eval(equation_str, {"__builtins__": {}}, {})
            return computed_value
        except Exception:
            return None

    def _calculate_score(self, equation_expr, goal_value, number_pool):
        if equation_expr is None:
            return 0.0
        if not self._check_equation_numbers(equation_expr, number_pool):
            return self.format_score
        try:
            evaluated = self._compute_result(equation_expr)
            if evaluated is None:
                return self.format_score
            # Check if result matches target within floating point tolerance
            if abs(evaluated - goal_value) < 1e-5:
                return self.correct_score
            else:
                return self.format_score
        except Exception:
            return self.format_score

    def compute_reward(self, workflow_task: WorkflowTask, workflow_output: WorkflowOutput) -> tuple:
        reward_value = 0.0
        final_response = workflow_output.metadata.get("final_answer")
        expected_target = workflow_output.metadata.get("target")
        given_numbers = workflow_output.metadata.get("nums")

        # Skip evaluation if required data is missing
        if expected_target is None or not given_numbers:
            return 0.0, False

        # Extract boxed answer content using regex
        box_pattern = r"\\boxed\{([^}]*)\}"
        match = re.search(box_pattern, final_response)
        if match:
            candidate_solution = match.group(1)
            reward_value = self._calculate_score(candidate_solution, expected_target, given_numbers)
            success_flag = reward_value >= self.correct_score
        else:
            reward_value = 0.0
            success_flag = False

        return reward_value, success_flag

# Session Catchup Tool for Planning Files
# This script helps detect and summarize unsynced context from previous sessions
# by scanning for updates to planning files (task_plan.md, progress.md, findings.md)

import json
import sys
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple

PLANNING_FILES = ['task_plan.md', 'progress.md', 'findings.md']

def identify_ide_environment() -> str:
    """
    Determine the active IDE based on environment variables and directory structure.
    Returns 'claude-code', 'opencode', or 'unknown'.
    """
    # Check OpenCode-specific environment variable
    if os.getenv('OPENCODE_DATA_DIR'):
        return 'opencode'

    # Look for Claude Code home directory
    claude_home = Path.home() / '.claude'
    if claude_home.is_dir():
        return 'claude-code'

    # Check for OpenCode data directory
    opencode_data = Path.home() / '.local' / 'share' / 'opencode'
    if opencode_data.is_dir():
        return 'opencode'

    return 'unknown'

def get_claude_project_path(project_root: str) -> Path:
    """Transform a project path into Claude's internal storage format."""
    normalized = project_root.replace('/', '-')
    if not normalized.startswith('-'):
        normalized = '-' + normalized
    normalized = normalized.replace('_', '-')
    return Path.home() / '.claude' / 'projects' / normalized

def get_opencode_storage_path() -> Optional[Path]:
    """
    Retrieve OpenCode's storage root directory.
    Uses OPENCODE_DATA_DIR env var or defaults to ~/.local/share/opencode.
    """
    base_dir = os.environ.get('OPENCODE_DATA_DIR',
                              str(Path.home() / '.local' / 'share' / 'opencode'))
    storage_path = Path(base_dir) / 'storage'
    return storage_path if storage_path.exists() else None

def collect_session_files_claude(storage_path: Path) -> List[Path]:
    """Get all session files (.jsonl) sorted by modification time (newest first)."""
    all_sessions = list(storage_path.glob('*.jsonl'))
    main_sessions = [s for s in all_sessions if not s.name.startswith('agent-')]
    return sorted(main_sessions, key=lambda p: p.stat().st_mtime, reverse=True)

def collect_session_files_opencode(storage_base: Path) -> List[Path]:
    """
    Collect OpenCode session files (.json).
    Sessions are stored under storage/session/{projectHash}/{sessionID}.json
    """
    session_root = storage_base / 'session'
    if not session_root.exists():
        return []

    collected = []
    for hash_dir in session_root.iterdir():
        if hash_dir.is_dir():
            collected.extend(hash_dir.glob('*.json'))
    return sorted(collected, key=lambda p: p.stat().st_mtime, reverse=True)

def get_first_message_timestamp(session_file: Path) -> Optional[str]:
    """Extract timestamp of the first message in a session file."""
    try:
        with open(session_file, 'r') as f:
            for line in f:
                try:
                    entry = json.loads(line)
                    ts = entry.get('timestamp')
                    if ts:
                        return ts
                except:
                    continue
    except:
        pass
    return None

def locate_planning_updates(session_file: Path) -> Tuple[int, Optional[str]]:
    """
    Scan session file for last Write/Edit operation on planning files.
    Returns (line_number, filename) of most recent update, or (-1, None).
    """
    latest_line = -1
    latest_file = None

    try:
        with open(session_file, 'r') as f:
            for idx, line in enumerate(f):
                if '"Write"' not in line and '"Edit"' not in line:
                    continue
                try:
                    data = json.loads(line)
                    if data.get('type') != 'assistant':
                        continue

                    content = data.get('message', {}).get('content', [])
                    if not isinstance(content, list):
                        continue

                    for item in content:
                        if item.get('type') != 'tool_use':
                            continue

                        tool_name = item.get('name', '')
                        if tool_name not in ('Write', 'Edit'):
                            continue

                        file_path = item.get('input', {}).get('file_path', '')
                        for pf in PLANNING_FILES:
                            if file_path.endswith(pf):
                                latest_line = idx
                                latest_file = pf
                                break
                except json.JSONDecodeError:
                    continue
    except Exception:
        pass

    return latest_line, latest_file

def extract_conversation_history(session_file: Path, start_from: int = -1) -> List[Dict]:
    """
    Extract conversation messages from a session file.
    If start_from >= 0, only extract messages after that line.
    """
    output = []

    try:
        with open(session_file, 'r') as f:
            for line_num, line in enumerate(f):
                if start_from >= 0 and line_num <= start_from:
                    continue

                try:
                    msg = json.loads(line)
                except json.JSONDecodeError:
                    continue

                msg_type = msg.get('type')
                is_meta = msg.get('isMeta', False)

                if msg_type == 'user' and not is_meta:
                    raw_content = msg.get('message', {}).get('content', '')

                    if isinstance(raw_content, list):
                        text_parts = []
                        for part in raw_content:
                            if isinstance(part, dict) and part.get('type') == 'text':
                                text_parts.append(part.get('text', ''))
                        raw_content = '\n'.join(text_parts)

                    if isinstance(raw_content, str) and raw_content.strip():
                        if raw_content.startswith(('<local-command', '<command-', '<task-notification')):
                            continue
                        if len(raw_content) > 20:
                            output.append({
                                'role': 'user',
                                'content': raw_content,
                                'line': line_num,
                                'session': session_file.stem[:8]
                            })

                elif msg_type == 'assistant':
                    raw_msg = msg.get('message', {})
                    text_content = ''
                    tools_used = []

                    if isinstance(raw_msg, str):
                        text_content = raw_msg
                    elif isinstance(raw_msg, list):
                        for part in raw_msg:
                            if part.get('type') == 'text':
                                text_content = part.get('text', '')
                            elif part.get('type') == 'tool_use':
                                tool_name = part.get('name', '')
                                tool_input = part.get('input', {})

                                if tool_name == 'Edit':
                                    tools_used.append(f"Edit: {tool_input.get('file_path', 'unknown')}")
                                elif tool_name == 'Write':
                                    tools_used.append(f"Write: {tool_input.get('file_path', 'unknown')}")
                                elif tool_name == 'Bash':
                                    cmd = tool_input.get('command', '')[:80]
                                    tools_used.append(f"Bash: {cmd}")
                                elif tool_name == 'AskUserQuestion':
                                    tools_used.append("AskUserQuestion")
                                else:
                                    tools_used.append(tool_name)

                    if text_content or tools_used:
                        output.append({
                            'role': 'assistant',
                            'content': text_content[:600] if text_content else '',
                            'tools': tools_used,
                            'line': line_num,
                            'session': session_file.stem[:8]
                        })
    except Exception:
        pass

    return output

def main():
    project_path = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()

    ide_env = identify_ide_environment()

    if ide_env == 'opencode':
        print("\n[planning-with-files] OpenCode session catchup is not yet fully supported")
        print("OpenCode uses a different session storage format (.json) than Claude Code (.jsonl)")
        print("Session catchup requires parsing OpenCode's message storage structure.")
        print("\nWorkaround: Manually read task_plan.md, progress.md, and findings.md to catch up.")
        return

    project_storage = get_claude_project_path(project_path)
    if not project_storage.exists():
        return

    sessions = collect_session_files_claude(project_storage)
    if len(sessions) < 2:
        return

    # Skip current session (most recent = index 0)
    prior_sessions = sessions[1:]

    # Find most recent planning file update across all prior sessions
    found_session = None
    found_line = -1
    found_file = None
    session_index = -1

    for idx, session in enumerate(prior_sessions):
        line, filename = locate_planning_updates(session)
        if line >= 0:
            found_session = session
            found_line = line
            found_file = filename
            session_index = idx
            break

    if not found_session:
        return

    # Gather all messages from the update point forward
    combined_messages = []

    # Messages from the session where update occurred (after update line)
    messages_after_update = extract_conversation_history(found_session, start_from=found_line)
    combined_messages.extend(messages_after_update)

    # Messages from sessions newer than the update session
    newer_sessions = prior_sessions[:session_index]
    for session in reversed(newer_sessions):
        all_messages = extract_conversation_history(session, start_from=-1)
        combined_messages.extend(all_messages)

    if not combined_messages:
        return

    # Output summary report
    print(f"\n[planning-with-files] SESSION CATCHUP DETECTED (IDE: {ide_env})")
    print(f"Last planning update: {found_file} in session {found_session.stem[:8]}...")

    total_scanned = session_index + 1
    if total_scanned > 1:
        print(f"Scanning {total_scanned} sessions for unsynced context")

    print(f"Unsynced messages: {len(combined_messages)}")
    print("\n--- UNSYNCED CONTEXT ---")

    # Limit display to 100 most recent messages
    MAX_MESSAGES = 100
    if len(combined_messages) > MAX_MESSAGES:
        print(f"(Showing last {MAX_MESSAGES} of {len(combined_messages)} messages)\n")
        display_messages = combined_messages[-MAX_MESSAGES:]
    else:
        display_messages = combined_messages

    current_session_id = None
    for msg in display_messages:
        session_id = msg.get('session')
        if session_id != current_session_id:
            current_session_id = session_id
            print(f"\n[Session: {current_session_id}...]")

        if msg['role'] == 'user':
            print(f"USER: {msg['content'][:300]}")
        else:
            if msg.get('content'):
                print(f"CLAUDE: {msg['content'][:300]}")
            if msg.get('tools'):
                print(f"  Tools: {', '.join(msg['tools'][:4])}")

    print("\n--- RECOMMENDED ---")
    print("1. Run: git diff --stat")
    print("2. Read: task_plan.md, progress.md, findings.md")
    print("3. Update planning files based on above context")
    print("4. Continue with task")

if __name__ == '__main__':
    main()

import json
import os
import pickle
import re
import shutil
import time
from pathlib import Path
from typing import Any, Dict, Generator, Iterable, Tuple, Union

import safetensors.torch
import torch
import torch.distributed.checkpoint as dist_cp
from transformers import AutoConfig


# --- Pickle Unpickler Wrapper ---
class _DummyClass:
    def __init__(self, *args, **kwargs):
        pass


class _CustomUnpickler(pickle.Unpickler):
    def find_class(self, module_name: str, class_name: str) -> Any:
        if module_name.startswith(("megatron", "glm")):
            return _DummyClass
        return super().find_class(module_name, class_name)


pickle.Unpickler = _CustomUnpickler


# --- Storage Reader Wrapper ---
class _AdaptedStorageReader(dist_cp.FileSystemReader):
    def read_metadata(self) -> dist_cp.metadata.Metadata:
        meta_path = self.fs.concat_path(self.path, ".metadata")
        with self.fs.create_stream(meta_path, "rb") as f:
            metadata = _CustomUnpickler(f).load()

        if not hasattr(metadata, "storage_meta") or metadata.storage_meta is None:
            metadata.storage_meta = dist_cp.StorageMeta()
        metadata.storage_meta.load_id = self.load_id
        if metadata.planner_data is None:
            metadata.planner_data = {}
        return metadata


# --- Load Planner Wrapper ---
class _MinimalLoadPlanner(dist_cp.default_planner.DefaultLoadPlanner):
    def set_up_planner(
        self,
        state_dict: dist_cp.metadata.STATE_DICT_TYPE,
        metadata: Union[dist_cp.metadata.Metadata, None] = None,
        is_coordinator: bool = False,
    ) -> None:
        for key, val in metadata.state_dict_metadata.items():
            if any(s in key for s in ("optimizer", "_state")):
                continue
            print(f"Found {key} in torch_dist checkpoint")
            if isinstance(val, dist_cp.metadata.TensorStorageMetadata):
                val = torch.empty(val.size, dtype=val.properties.dtype)
            state_dict[key] = val
        super().set_up_planner(state_dict, metadata, is_coordinator)


# --- Helper Generators for Parameter Extraction ---

def _extract_expert_params(args: Any, name: str, param: torch.Tensor) -> Generator[Tuple[str, torch.Tensor], None, None]:
    if ".experts." not in name:
        yield name, param
        return

    num_experts = args.num_experts
    match = re.search(r"mlp\.experts\.(.+)\.weight(\d+)", name)
    if not match:
        assert param.shape[0] == num_experts, f"Expected {num_experts} experts, got {param.shape[0]}"
        for eid in range(num_experts):
            new_name = name.replace(".experts.experts.", ".experts.") + str(eid)
            yield new_name, param[eid]
    else:
        yield name, param


def _extract_layer_params(args: Any, name: str, param: torch.Tensor) -> Generator[Tuple[str, torch.Tensor], None, None]:
    if ".layers." not in name:
        yield from _extract_expert_params(args, name, param)
        return

    num_layers = args.num_layers
    match = re.search(r"\.layers\.(\d+)\.", name)
    if not match:
        assert param.shape[0] == num_layers, f"Expected {num_layers} layers, got {param.shape[0]}"
        for lid in range(num_layers):
            layer_name = name.replace(".layers.", f".layers.{lid}.")
            yield from _extract_expert_params(args, layer_name, param[lid])
    else:
        yield from _extract_expert_params(args, name, param)


def _collect_named_params(args: Any, state_dict: Dict[str, torch.Tensor]) -> Generator[Tuple[str, torch.Tensor], None, None]:
    for k, v in state_dict.items():
        full_name = f"module.module.{k}"
        yield from _extract_layer_params(args, full_name, v)


# --- Main Saving Logic ---

def _save_model_tensors(
    args: Any,
    model_name: str,
    state_dict: Dict[str, torch.Tensor],
    output_dir: str,
    chunk_size: int,
    vocab_size: Union[int, None],
) -> None:
    args.sglang_enable_ep_moe = False
    print(f"Saving to {output_dir}")
    Path(output_dir).mkdir(parents=True, exist_ok=True)

    current_chunk = {}
    current_size = 0
    total_size = 0
    chunks = [current_chunk]

    for name, param in _collect_named_params(args, state_dict):
        if vocab_size:
            param = remove_padding(name, param, vocab_size)
        for conv_name, conv_param in convert_to_hf(args, model_name, name, param):
            tensor_bytes = conv_param.numel() * conv_param.element_size()
            if current_size + tensor_bytes > chunk_size:
                current_chunk = {}
                chunks.append(current_chunk)
                current_size = 0
            current_chunk[conv_name] = conv_param
            current_size += tensor_bytes
            total_size += tensor_bytes

    # Build index
    metadata = {
        "metadata": {"total_size": total_size},
        "weight_map": {},
    }
    num_files = len(chunks)
    for idx, chunk in enumerate(chunks):
        filename = f"model-{idx:05d}-of-{num_files:05d}.safetensors"
        for key in chunk:
            metadata["weight_map"][key] = filename

    index_path = os.path.join(output_dir, "model.safetensors.index.json")
    with open(index_path, "w") as f:
        json.dump(metadata, f, indent=2)
    print(f"{index_path} saved.")

    # Save each chunk
    for idx, chunk in enumerate(chunks):
        filename = f"model-{idx:05d}-of-{num_files:05d}.safetensors"
        t0 = time.time()
        filepath = os.path.join(output_dir, filename)
        safetensors.torch.save_file(chunk, filepath)
        print(f"{filename} saved in {time.time() - t0:.2f}s")


def _copy_assets(src_dir: str, dst_dir: str) -> None:
    for fname in os.listdir(src_dir):
        if fname.endswith((".safetensors", ".index.json")):
            continue
        src = os.path.join(src_dir, fname)
        if not os.path.isfile(src):
            print(f"Skipping {fname}: not a file.")
            continue
        dst = os.path.join(dst_dir, fname)
        print(f"Copying {src} → {dst}")
        shutil.copy2(src, dst)


# --- Entry Point ---

