    args = parser.parse_args()

    if os.path.exists(args.output_dir) and not args.force:
        raise ValueError(f"Output dir '{args.output_dir}' exists; use --force to overwrite.")

    if args.model_name is None and args.origin_hf_dir is None:
        raise ValueError("Provide either --model-name or --origin-hf-dir.")

    if args.model_name is None:
        hf_cfg = AutoConfig.from_pretrained(args.origin_hf_dir, trust_remote_code=True)
        args.model_name = type(hf_cfg).__name__.lower()

    state_dict = {}
