# Export correlated h-cli traces from dispatcher and firewall logs

import argparse
import json
import os
import sys
from datetime import datetime, timezone

def read_jsonl_file(filepath):
    """Generator that yields valid JSON objects from a JSONL file."""
    if not os.path.exists(filepath):
        return
    with open(filepath, 'r') as file:
        for line in file:
            stripped = line.strip()
            if not stripped:
                continue
            try:
                yield json.loads(stripped)
            except json.JSONDecodeError:
                continue

def convert_timestamp(ts_string):
    """Convert ISO format timestamp string to datetime object."""
    # Normalize timezone representation
    normalized = ts_string.replace("Z", "+00:00")
    return datetime.fromisoformat(normalized)

def collect_task_events(log_path):
    """Extract task execution pairs (initiation + completion) from dispatcher logs."""
    initiations = {}
    completed_tasks = []

    for record in read_jsonl_file(log_path):
        task_identifier = record.get("task_id")
        if not task_identifier:
            continue

        if "user_message" in record:
            # Record the start of a task
            initiations[task_identifier] = record
        elif "output" in record and task_identifier in initiations:
            # Matched completion event
            start_event = initiations.pop(task_identifier)
            completed_tasks.append({
                "task_id": task_identifier,
                "user_id": start_event.get("user_id"),
                "start_time": start_event["timestamp"],
                "end_time": record["timestamp"],
                "user_query": start_event["user_message"],
                "model_response": record["output"],
                "response_size": record.get("output_length", len(record["output"])),
            })

    return completed_tasks

def gather_firewall_records(log_path):
    """Collect and sort firewall audit entries by timestamp."""
    firewall_data = []
    for entry in read_jsonl_file(log_path):
        if "command" not in entry:
            continue
        firewall_data.append(entry)

    # Sort chronologically
    firewall_data.sort(key=lambda x: x["timestamp"])
    return firewall_data

def align_traces(tasks, firewall_logs):
    """Match firewall events to tasks based on time windows."""
    aligned_traces = []

    for task in tasks:
        begin_time = convert_timestamp(task["start_time"])
        finish_time = convert_timestamp(task["end_time"])

        # Collect relevant firewall events within the task's duration
        tool_interactions = {}
        for log_entry in firewall_logs:
            event_time = convert_timestamp(log_entry["timestamp"])

            if event_time < begin_time:
                continue
            if event_time > finish_time:
                break

            command = log_entry["command"]

            if "allowed" in log_entry:
                tool_interactions[command] = {
                    "command": command,
                    "permitted": log_entry["allowed"],
                    "justification": log_entry.get("reason", ""),
                }
            elif "output_length" in log_entry and command in tool_interactions:
                tool_interactions[command]["output_size"] = log_entry["output_length"]

        trace = {
            "task_id": task["task_id"],
            "user_id": task["user_id"],
            "event_time": task["start_time"],
            "user_query": task["user_query"],
            "tool_calls": list(tool_interactions.values()),
            "model_response": task["model_response"],
        }
        aligned_traces.append(trace)

    return aligned_traces

def main():
    parser = argparse.ArgumentParser(description="Export correlated h-cli traces")
    parser.add_argument("-d", "--directory", default="logs",
                        help="Log directory path (default: logs/)")
    parser.add_argument("-f", "--file", default="traces.jsonl",
                        help="Output file name (default: traces.jsonl)")
    parser.add_argument("--after", default=None,
                        help="Filter tasks after this date (YYYY-MM-DD)")
    args = parser.parse_args()

    dispatcher_log = os.path.join(args.directory, "claude", "audit.log")
    firewall_log = os.path.join(args.directory, "firewall", "audit.log")

    if not os.path.isfile(dispatcher_log):
        print(f"Missing required file: {dispatcher_log}", file=sys.stderr)
        sys.exit(1)

    # Process logs
    task_events = collect_task_events(dispatcher_log)
    firewall_records = gather_firewall_records(firewall_log)
    final_traces = align_traces(task_events, firewall_records)

    # Apply date filter if specified
    if args.after:
        cutoff_date = datetime.strptime(args.after, "%Y-%m-%d").replace(tzinfo=timezone.utc)
        final_traces = [t for t in final_traces if convert_timestamp(t["event_time"]) >= cutoff_date]

    # Write results
    with open(args.file, "w") as output_file:
        for trace in final_traces:
            output_file.write(json.dumps(trace, ensure_ascii=False) + "\n")

    print(f"Generated {len(final_traces)} traces -> {args.file}")

if __name__ == "__main__":
    main()

from __future__ import annotations

import os
import subprocess
import tempfile
import unittest
from functools import partial
from pathlib import Path


def find_root() -> Path:
    for parent in Path(__file__).resolve().parents:
        if (parent / "src").exists():
            return parent
    raise RuntimeError("Could not locate project root with 'src' directory")


ROOT_DIR = find_root()

TIMEOUT_COMPILE = float(os.getenv("PYTRA_TEST_COMPILE_TIMEOUT_SEC", "120"))
TIMEOUT_RUN = float(os.getenv("PYTRA_TEST_RUN_TIMEOUT_SEC", "2"))

CPP_RUNTIME_SOURCES = [
    "src/runtime/cpp/core/gc.ext.cpp",
    "src/runtime/cpp/core/io.ext.cpp",
]


class CppRuntimeIterableSmokeTest(unittest.TestCase):
    def _execute_subprocess(
        self,
        cmd: list[str],
        working_dir: Path,
        timeout: float,
        description: str,
    ) -> subprocess.CompletedProcess[str]:
        try:
            result = subprocess.run(
                cmd,
                cwd=working_dir,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
            return result
        except subprocess.TimeoutExpired as e:
            stdout_str = e.stdout if isinstance(e.stdout, str) else ""
            stderr_str = e.stderr if isinstance(e.stderr, str) else ""
            self.fail(
                f"{description} timed out after {timeout:.1f}s: {' '.join(cmd)}\n"
                f"stdout:\n{stdout_str}\n"
                f"stderr:\n{stderr_str}"
            )
            raise AssertionError("Unreachable")

    def _compile_and_run_cpp_test(self, source_code: str, label: str) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            work_path = Path(tmpdir)
            cpp_file = work_path / "test_iterable.cpp"
            binary_file = work_path / "test_iterable.out"

            cpp_file.write_text(source_code, encoding="utf-8")

            compiler_cmd = [
                "g++",
                "-std=c++20",
                "-O2",
                "-I", "src",
                "-I", "src/runtime/cpp",
                str(cpp_file),
                *CPP_RUNTIME_SOURCES,
                "-o", str(binary_file),
            ]

            compile_result = self._execute_subprocess(
                compiler_cmd,
                ROOT_DIR,
                TIMEOUT_COMPILE,
                f"[compile] {label}",
            )
            self.assertEqual(compile_result.returncode, 0, msg=compile_result.stderr)

            run_result = self._execute_subprocess(
                [str(binary_file)],
                work_path,
                TIMEOUT_RUN,
                f"[run] {label}",
            )
            self.assertEqual(run_result.returncode, 0, msg=run_result.stderr)
            self.assertIn("runtime iterable ok", run_result.stdout)

    def test_runtime_iterable_protocol_helpers(self) -> None:
        cpp_src = r'''
#include "runtime/cpp/core/py_runtime.ext.h"
#include <cassert>
#include <iostream>

int main() {
    object list_obj = make_object(list<int64>{1, 2, 3});
    object iter_obj = py_iter_or_raise(list_obj);
    auto n0 = py_next_or_stop(iter_obj);
    auto n1 = py_next_or_stop(iter_obj);
    auto n2 = py_next_or_stop(iter_obj);
    auto n3 = py_next_or_stop(iter_obj);
    assert(n0.has_value() && obj_to_int64(*n0) == 1);
    assert(n1.has_value() && obj_to_int64(*n1) == 2);
    assert(n2.has_value() && obj_to_int64(*n2) == 3);
    assert(!n3.has_value());

    object mut_list_obj = make_object(list<int64>{10, 20});
    object mut_iter_obj = py_iter_or_raise(mut_list_obj);
    auto m0 = py_next_or_stop(mut_iter_obj);
    assert(m0.has_value() && obj_to_int64(*m0) == 10);

    py_append(mut_list_obj, make_object(int64(30)));
    auto m1 = py_next_or_stop(mut_iter_obj);
    auto m2 = py_next_or_stop(mut_iter_obj);
    auto m3 = py_next_or_stop(mut_iter_obj);
    assert(m1.has_value() && obj_to_int64(*m1) == 20);
    assert(m2.has_value() && obj_to_int64(*m2) == 30);
    assert(!m3.has_value());

    py_extend(mut_list_obj, make_object(list<int64>{40, 50}));
    assert(py_len(mut_list_obj) == 5);

    object p0 = py_pop(mut_list_obj);
    assert(obj_to_int64(p0) == 50);

    object p1 = py_pop(mut_list_obj, 0);
    assert(obj_to_int64(p1) == 10);

    py_reverse(mut_list_obj);
    assert(obj_to_int64(py_at(mut_list_obj, 0)) == 40);

    py_sort(mut_list_obj);
    assert(obj_to_int64(py_at(mut_list_obj, 0)) == 20);

    py_clear(mut_list_obj);
    assert(py_len(mut_list_obj) == 0);

    int64 sum = 0;
    for (object v : py_dyn_range(list_obj)) {
        sum += obj_to_int64(v);
    }
    assert(sum == 6);

    dict<str, object> d{};
    d["a"] = make_object(1);
    d["b"] = make_object(2);
    bool has_a = false;
    bool has_b = false;
    for (object key_obj : py_dyn_range(make_object(d))) {
        str key = obj_to_str(key_obj);
        if (key == "a") has_a = true;
        if (key == "b") has_b = true;
    }
    assert(has_a && has_b);

    str joined = "";
    for (object ch : py_dyn_range(make_object(str("ab")))) {
        joined += obj_to_str(ch);
    }
    assert(joined == "ab");

    object set_obj = make_object(set<int64>{1, 2, 3});
    int64 set_sum = 0;
    for (object v : py_dyn_range(set_obj)) {
        set_sum += obj_to_int64(v);
    }
    assert(set_sum == 6);

    bool thrown = false;
    try {
        for (object _ : py_dyn_range(make_object(int64(9)))) {
            (void)_;
        }
    } catch (const ::std::runtime_error&) {
        thrown = true;
    }
    assert(thrown);

    std::cout << "runtime iterable ok" << std::endl;
    return 0;
}
'''
        self._compile_and_run_cpp_test(cpp_src, "runtime iterable protocol helpers")

# Type III Clone: Experience Log Validator (Alternative Implementation)
# Uses different control flow, variable names, and logic while preserving functionality

import json
import re
import sys
import os
from datetime import datetime, timezone

# Regex pattern for experience ID validation
ID_REGEX = r'^EXP-[0-9]{8}-[0-9]{4}$

# Valid significance levels
SIGNIFICANCE_VALUES = {'routine', 'notable', 'pivotal'}

# Built-in data sources
DEFAULT_SOURCES = {'conversation', 'moltbook', 'x', 'heartbeat', 'flush_harvest', 'other'}

# Mandatory fields in each entry
MANDATORY_FIELDS = {'id', 'timestamp', 'source', 'content', 'significance', 'significance_reason', 'reflected'}


def fetch_additional_sources(config_file):
    """Gather extra valid source names from configuration file."""
    additional = set()
    if config_file and os.path.isfile(config_file):
        try:
            with open(config_file) as cfg_file:
                config_data = json.load(cfg_file)
            for source_name in config_data.get('sources', {}):
                additional.add(source_name)
        except Exception:
            pass
    return DEFAULT_SOURCES.union(additional)


def validate_timestamp_format(timestamp_str):
    """Verify timestamp conforms to ISO-8601 standard."""
    try:
        # Normalize timezone representation
        normalized_ts = timestamp_str.replace('Z', '+00:00')
        parsed_dt = datetime.fromisoformat(normalized_ts)
        return parsed_dt
    except (ValueError, TypeError):
        return None


def check_entry(entry_data, line_number, valid_sources, seen_identifiers, error_list, warning_list, notable_entries):
    """Validate a single JSON entry against schema rules."""

    # Check required fields
    for field_name in MANDATORY_FIELDS:
        if field_name not in entry_data:
            error_list.append({
                'line': line_number,
                'field': field_name,
                'message': f'Missing required field: {field_name}'
            })

    # Validate ID format and duplicates
    exp_id = entry_data.get('id', '')
    if exp_id:
        if not re.match(ID_REGEX, exp_id):
            error_list.append({
                'line': line_number,
                'field': 'id',
                'message': f'Invalid ID format: "{exp_id}" (expected EXP-YYYYMMDD-NNNN)'
            })
        elif exp_id in seen_identifiers:
            error_list.append({
                'line': line_number,
                'field': 'id',
                'message': f'Duplicate ID: {exp_id}'
            })
        seen_identifiers.add(exp_id)

    # Validate timestamp
    ts_value = entry_data.get('timestamp')
    if ts_value:
        dt_obj = validate_timestamp_format(ts_value)
        if dt_obj is None:
            error_list.append({
                'line': line_number,
                'field': 'timestamp',
                'message': f'Invalid ISO-8601 timestamp: "{ts_value}"'
            })
        elif dt_obj.tzinfo and dt_obj > datetime.now(timezone.utc):
            warning_list.append({
                'line': line_number,
                'message': f'Timestamp is in the future: {ts_value}'
            })

    # Validate source
    src_value = entry_data.get('source', '')
    if src_value and src_value not in valid_sources:
        error_list.append({
            'line': line_number,
            'field': 'source',
            'message': f'Unknown source: "{src_value}" (valid: {sorted(valid_sources)})'
        })

    # Validate significance level
    sig_value = entry_data.get('significance', '')
    if sig_value and sig_value not in SIGNIFICANCE_VALUES:
        error_list.append({
            'line': line_number,
            'field': 'significance',
            'message': f'Invalid significance: "{sig_value}" (valid: routine, notable, pivotal)'
        })

    # Track notable/pivotal entries
    if sig_value in ('notable', 'pivotal'):
        notable_entries.append(exp_id)

    # Validate content field
    content_val = entry_data.get('content', '')
    if isinstance(content_val, str) and not content_val.strip():
        error_list.append({
            'line': line_number,
            'field': 'content',
            'message': 'Content is empty'
        })

    # Warn about missing significance reason
    reason_val = entry_data.get('significance_reason', '')
    if isinstance(reason_val, str) and not reason_val.strip():
        warning_list.append({
            'line': line_number,
            'message': 'significance_reason is empty'
        })

    # Validate reflected field type
    reflected_val = entry_data.get('reflected')
    if reflected_val is not None and not isinstance(reflected_val, bool):
        error_list.append({
            'line': line_number,
            'field': 'reflected',
            'message': f'reflected must be boolean, got {type(reflected_val).__name__}: {reflected_val}'
        })


def process_experience_log(log_path, config_path=None):
    """Main validation function for experience log files."""
    errors = []
    warnings = []
    valid_sources = fetch_additional_sources(config_path)
    identifiers_seen = set()
    total_entries = 0
    notable_pivotal_items = []

    # Handle missing file case
    if not os.path.exists(log_path):
        return {
            'status': 'FAIL',
            'file': log_path,
            'errors': [{'line': None, 'field': None, 'message': f'File not found: {log_path}'}],
            'warnings': [],
            'stats': {}
        }

    # Process file line by line
    with open(log_path, 'r', encoding='utf-8') as input_file:
        for current_line_num, raw_line in enumerate(input_file, start=1):
            processed_line = raw_line.strip()
            if not processed_line:
                continue

            total_entries += 1

            # Parse JSON
            try:
                entry = json.loads(processed_line)
            except json.JSONDecodeError as parse_error:
                errors.append({
                    'line': current_line_num,
                    'field': None,
                    'message': f'Invalid JSON: {str(parse_error)[:80]}'
                })
                continue

            # Ensure entry is dictionary
            if not isinstance(entry, dict):
                errors.append({
                    'line': current_line_num,
                    'field': None,
                    'message': f'Expected JSON object, got {type(entry).__name__}'
                })
                continue

            # Perform validation checks
            check_entry(
                entry, 
                current_line_num, 
                valid_sources, 
                identifiers_seen, 
                errors, 
                warnings, 
                notable_pivotal_items
            )

    # Determine overall status
    final_status = 'FAIL' if errors else 'PASS'

    return {
        'status': final_status,
        'file': log_path,
        'errors': errors,
        'warnings': warnings,
        'stats': {
            'total_entries': total_entries,
            'unique_ids': len(identifiers_seen),
            'notable_pivotal_count': len(notable_pivotal_items),
            'notable_pivotal_ids': notable_pivotal_items
        }
    }


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: validate_experience.py <jsonl_file> [--config config.json]', file=sys.stderr)
        sys.exit(2)

    log_file = sys.argv[1]
    config_file = None

    if '--config' in sys.argv:
        config_index = sys.argv.index('--config')
        if config_index + 1 < len(sys.argv):
            config_file = sys.argv[config_index + 1]

    validation_result = process_experience_log(log_file, config_file)
    print(json.dumps(validation_result, indent=2))
    sys.exit(0 if validation_result['status'] == 'PASS' else 1)

import json
import os
import re
import logging
import threading
import queue
from urllib.parse import urlparse, urljoin
from collections import defaultdict
from datetime import datetime
import pytz
from bs4 import BeautifulSoup
import requests

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class LinkValidator:
    """Thread-safe link validator with caching."""
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()

    def is_active(self, url, timeout=2):
        if url in self.cache:
            return self.cache[url]

        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        }

        # Try HEAD first
        try:
            resp = requests.head(url, timeout=timeout, headers=headers, allow_redirects=True)
            status = resp.status_code < 400
            result = (status, url)
            with self.lock:
                self.cache[url] = result
            return result
        except Exception:
            pass

        # Fallback to GET
        try:
            with requests.get(url, stream=True, timeout=timeout, headers=headers) as r:
                status = r.status_code < 400
                result = (status, url)
                with self.lock:
                    self.cache[url] = result
                return result
        except Exception:
            pass

        # Try alternate protocol
        alt_url = url.replace('http://', 'https://') if url.startswith('http://') else url.replace('https://', 'http://')
        try:
            resp = requests.head(alt_url, timeout=timeout, headers=headers, allow_redirects=True)
            status = resp.status_code < 400
            result = (status, alt_url)
            with self.lock:
                self.cache[url] = result
            return result
        except Exception:
            with self.lock:
                self.cache[url] = (False, url)
            return False, url


class M3UCollector:
    def __init__(self, country="Thailand", base_dir="LiveTV", validate_links=True):
        self.channels = {}  # Changed from defaultdict(list)
        self.default_logo = "https://bugsfreeweb.github.io/LiveTVCollector/BugsfreeLogo/default-logo.png"
        self.seen_urls = set()
        self.output_dir = os.path.join(base_dir, country)
        self.validator = LinkValidator() if validate_links else None
        os.makedirs(self.output_dir, exist_ok=True)

    def fetch_content(self, url):
        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
        try:
            with requests.get(url, stream=True, headers=headers, timeout=10) as response:
                response.raise_for_status()
                lines = []
                for line in response.iter_lines():
                    decoded = line.decode('utf-8', errors='ignore') if isinstance(line, bytes) else line
                    lines.append(decoded)
                content = '\n'.join(lines)
                logging.info(f"Fetched {len(lines)} lines from {url}")
                return content, lines
        except requests.RequestException as e:
            logging.error(f"Failed to fetch {url}: {str(e)}")
            return None, []

    def extract_stream_urls_from_html(self, html_content, base_url):
        if not html_content:
            return []

        soup = BeautifulSoup(html_content, 'html.parser')
        urls = set()
        parsed_base = urlparse(base_url)

        for anchor in soup.find_all('a', href=True):
            href = anchor['href']
            full_url = urljoin(base_url, href)
            if any(ext in full_url.lower() for ext in ['.m3u', '.m3u8']) or \
               re.match(r'^https?://.*\.(ts|mp4|avi|mkv|flv|wmv)$', full_url.lower()) or \
               any(keyword in full_url.lower() for keyword in ['playlist', 'stream']):
                if not any(excl in full_url.lower() for excl in ['telegram', '.html', '.php', 'github.com', 'login', 'signup']):
                    urls.add(full_url)

        logging.info(f"Extracted {len(urls)} streaming URLs from {base_url}")
        return list(urls)

    def parse_and_store(self, lines, source_url):
        current_channel = {}
        count = 0

        for line in lines:
            line = line.strip()
            if line.startswith('#EXTINF:'):
                # Extract metadata more robustly
                logo_match = re.search(r'tvg-logo=["\']([^"\']*)["\']', line)
                group_match = re.search(r'group-title=["\']([^"\']*)["\']', line)
                name_match = re.search(r',(.+)$', line)

                current_channel = {
                    'name': name_match.group(1).strip() if name_match else "Unnamed",
                    'logo': logo_match.group(1) if logo_match and logo_match.group(1) else self.default_logo,
                    'group': group_match.group(1) if group_match else "Uncategorized",
                    'source': source_url
                }
            elif line.startswith('http') and current_channel:
                url = line
                if url not in self.seen_urls:
                    self.seen_urls.add(url)
                    current_channel['url'] = url
                    group = current_channel['group']
                    if group not in self.channels:
                        self.channels[group] = []
                    self.channels[group].append(current_channel.copy())
                    count += 1
                current_channel = {}

        logging.info(f"Parsed {count} channels from {source_url}")

    def filter_active_channels(self):
        if not self.validator:
            logging.info("Skipping link validation per configuration.")
            return

        active = {}
        all_items = [(grp, ch) for grp, chans in self.channels.items() for ch in chans]
        seen_urls = set()

        def worker(q_in, q_out):
            while True:
                try:
                    item = q_in.get(timeout=0.5)
                    if item is None:
                        break
                    group, channel = item
                    url = channel['url']
                    if url not in seen_urls:
                        with threading.Lock():
                            seen_urls.add(url)
                        is_valid, new_url = self.validator.is_active(url)
                        if is_valid:
                            channel['url'] = new_url
                            q_out.put((group, channel))
                except queue.Empty:
                    continue

        input_q = queue.Queue()
        output_q = queue.Queue()

        threads = [threading.Thread(target=worker, args=(input_q, output_q)) for _ in range(5)]
        for t in threads:
            t.start()

        for item in all_items:
            input_q.put(item)
        for _ in threads:
            input_q.put(None)

        for t in threads:
            t.join()

        while not output_q.empty():
            g, c = output_q.get()
            if g not in active:
                active[g] = []
            active[g].append(c)

        self.channels = active
        total = sum(len(chs) for chs in active.values())
        logging.info(f"Active channels after filtering: {total}")

    def process_sources(self, source_urls):
        self.channels.clear()
        self.seen_urls.clear()
        if self.validator:
            self.validator.cache.clear()

        m3u_urls = set()
        for url in source_urls:
            content, lines = self.fetch_content(url)
            if url.endswith('.html'):
                extracted = self.extract_stream_urls_from_html(content, url)
                m3u_urls.update(extracted)
            else:
                self.parse_and_store(lines, url)

        for m3u_url in m3u_urls:
            _, lines = self.fetch_content(m3u_url)
            self.parse_and_store(lines, m3u_url)

        if self.channels:
            self.filter_active_channels()
        else:
            logging.warning("No channels parsed from sources")

    def export_m3u(self, filename="LiveTV.m3u"):
        filepath = os.path.join(self.output_dir, filename)
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write('#EXTM3U\n')
            for group in sorted(self.channels.keys()):
                for ch in self.channels[group]:
                    f.write(f'#EXTINF:-1 tvg-logo="{ch["logo"]}" group-title="{group}",{ch["name"]}\n')
                    f.write(f'{ch["url"]}\n')
        logging.info(f"Exported M3U to {filepath}")
        return filepath

    def export_txt(self, filename="LiveTV.txt"):
        filepath = os.path.join(self.output_dir, filename)
        with open(filepath, 'w', encoding='utf-8') as f:
            for group in sorted(self.channels.keys()):
                f.write(f"Group: {group}\n")
                for ch in self.channels[group]:
                    f.write(f"Name: {ch['name']}\nURL: {ch['url']}\nLogo: {ch['logo']}\nSource: {ch['source']}\n")
                    f.write("-" * 50 + "\n")
                f.write("\n")
        logging.info(f"Exported TXT to {filepath}")
        return filepath

    def export_json(self, filename="LiveTV.json"):
        filepath = os.path.join(self.output_dir, filename)
        mumbai_tz = pytz.timezone('Asia/Kolkata')
        now_str = datetime.now(mumbai_tz).strftime('%Y-%m-%d %H:%M:%S')

        data = {
            "date": now_str,
            "channels": {k: v for k, v in self.channels.items()}
        }
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        logging.info(f"Exported JSON to {filepath}")
        return filepath

    def export_custom(self, filename="LiveTV"):
        filepath = os.path.join(self.output_dir, filename)
        custom_data = []
        for group, chans in self.channels.items():
            for ch in chans:
                custom_data.append({
                    "name": ch['name'],
                    "type": group,
                    "url": ch['url'],
                    "img": ch['logo']
                })
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(custom_data, f, ensure_ascii=False, indent=2)
        logging.info(f"Exported custom format to {filepath}")
        return filepath


def main():
    sources = [
        "https://raw.githubusercontent.com/kupjta/iptv/refs/heads/main/kupjtv.m3u",
        "https://raw.githubusercontent.com/bestcommt2/iptv/refs/heads/master/fuckidplus.w3u",
        "https://iptv-org.github.io/iptv/countries/th.m3u",
    ]

    collector = M3UCollector(country="Thailand", validate_links=False)
    collector.process_sources(sources)

    collector.export_m3u("LiveTV.m3u")
    collector.export_txt("LiveTV.txt")
    collector.export_json("LiveTV.json")
    collector.export_custom("LiveTV")

    total = sum(len(chs) for chs in collector.channels.values())
    mumbai_time = datetime.now(pytz.timezone('Asia/Kolkata'))
    logging.info(f"[{mumbai_time}] Collected {total} unique channels for Thailand")
    logging.info(f"Groups found: {len(collector.channels)}")


if __name__ == "__main__":
    main()

# Webhook Management API - UCM
"""
API endpoints for managing webhook configurations and integrations.
"""
from flask import Blueprint, request
from auth.unified import require_auth
from utils.response import success_response, error_response
from models import db
from services.webhook_service import WebhookEndpoint, WebhookService
import json
import secrets

webhook_bp = Blueprint('webhooks', __name__)

@webhook_bp.route('/api/v2/webhooks', methods=['GET'])
@require_auth(['read:settings'])
def list_webhook_configs():
    """Retrieve all configured webhook endpoints"""
    endpoints = WebhookEndpoint.query.all()
    return success_response(data=[e.to_dict() for e in endpoints])

@webhook_bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['GET'])
@require_auth(['read:settings'])
def fetch_webhook_config(endpoint_id):
    """Get details of a specific webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    return success_response(data=endpoint.to_dict())

@webhook_bp.route('/api/v2/webhooks', methods=['POST'])
@require_auth(['write:settings'])
def add_webhook_config():
    """Create a new webhook endpoint configuration"""
    payload = request.get_json()

    # Validate required fields
    if not payload.get('name'):
        return error_response("Webhook name is required", 400)
    if not payload.get('url'):
        return error_response("Webhook URL is required", 400)

    # Validate URL format
    target_url = payload['url']
    if not target_url.startswith(('http://', 'https://')):
        return error_response("URL must start with http:// or https://", 400)

    # Process events array
    event_list = payload.get('events', ['*'])
    if not isinstance(event_list, list):
        return error_response('Events must be an array', 400)

    # Process custom headers
    headers_dict = payload.get('custom_headers', {})
    if headers_dict and not isinstance(headers_dict, dict):
        return error_response('Custom headers must be an object', 400)

    # Create new endpoint
    new_endpoint = WebhookEndpoint(
        name=payload['name'],
        url=target_url,
        secret=payload.get('secret') or secrets.token_urlsafe(32),
        events=json.dumps(event_list),
        ca_filter=payload.get('ca_filter'),
        enabled=payload.get('enabled', True),
        custom_headers=json.dumps(headers_dict)
    )

    db.session.add(new_endpoint)
    db.session.commit()

    return success_response(data=new_endpoint.to_dict(), message="Webhook created")

@webhook_bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['PUT'])
@require_auth(['write:settings'])
def modify_webhook_config(endpoint_id):
    """Update an existing webhook endpoint configuration"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    payload = request.get_json()

    # Update allowed fields conditionally
    if 'name' in payload:
        endpoint.name = payload['name']
    if 'url' in payload:
        target_url = payload['url']
        if not target_url.startswith(('http://', 'https://')):
            return error_response("URL must start with http:// or https://", 400)
        endpoint.url = target_url
    if 'secret' in payload:
        endpoint.secret = payload['secret']
    if 'events' in payload:
        if not isinstance(payload['events'], list):
            return error_response('Events must be an array', 400)
        endpoint.events = json.dumps(payload['events'])
    if 'ca_filter' in payload:
        endpoint.ca_filter = payload['ca_filter']
    if 'enabled' in payload:
        endpoint.enabled = payload['enabled']
    if 'custom_headers' in payload:
        if payload['custom_headers'] and not isinstance(payload['custom_headers'], dict):
            return error_response('Custom headers must be an object', 400)
        endpoint.custom_headers = json.dumps(payload['custom_headers'])

    db.session.commit()
    return success_response(data=endpoint.to_dict(), message="Webhook updated")

@webhook_bp.route('/api/v2/webhooks/<int:endpoint_id>', methods=['DELETE'])
@require_auth(['write:settings'])
def remove_webhook_config(endpoint_id):
    """Delete a webhook endpoint configuration"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    db.session.delete(endpoint)
    db.session.commit()
    return success_response(message="Webhook deleted")

@webhook_bp.route('/api/v2/webhooks/<int:endpoint_id>/toggle', methods=['POST'])
@require_auth(['write:settings'])
def switch_webhook_status(endpoint_id):
    """Enable or disable a webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    endpoint.enabled = not endpoint.enabled
    db.session.commit()

    status = "enabled" if endpoint.enabled else "disabled"
    return success_response(data=endpoint.to_dict(), message=f"Webhook {status}")

@webhook_bp.route('/api/v2/webhooks/<int:endpoint_id>/test', methods=['POST'])
@require_auth(['write:settings'])
def test_webhook_connection(endpoint_id):
    """Send a test event to the webhook endpoint"""
    success, message = WebhookService.test_endpoint(endpoint_id)

    if success:
        return success_response(message=message)
    else:
        return error_response(message, 400)

@webhook_bp.route('/api/v2/webhooks/<int:endpoint_id>/regenerate-secret', methods=['POST'])
@require_auth(['write:settings'])
def refresh_webhook_secret(endpoint_id):
    """Generate a new secret token for the webhook endpoint"""
    endpoint = WebhookEndpoint.query.get_or_404(endpoint_id)
    endpoint.secret = secrets.token_urlsafe(32)
    db.session.commit()

    return success_response(
        data={'secret': endpoint.secret},
        message="Secret regenerated"
    )

@webhook_bp.route('/api/v2/webhooks/events', methods=['GET'])
@require_auth(['read:settings'])
def get_available_events():
    """Retrieve list of available webhook event types"""
    return success_response(data={
        'events': WebhookService.ALL_EVENTS,
        'descriptions': {
            'certificate.issued': 'When a new certificate is issued',
            'certificate.revoked': 'When a certificate is revoked',
            'certificate.renewed': 'When a certificate is auto-renewed',
            'certificate.expiring': 'When a certificate is about to expire',
            'ca.created': 'When a new CA is created',
            'ca.updated': 'When a CA is updated',
            'csr.submitted': 'When a CSR is submitted',
            'csr.approved': 'When a CSR is approved',
            'csr.rejected': 'When a CSR is rejected',
        }
    })

