import numpy as np
from typing import Dict, List, Tuple

# Define the seven primary affects in consistent order (aligned with dynamic_affect.py)
PRIMARY_AFFECTS = ["SEEKING", "RAGE", "FEAR", "LUST", "CARE", "PANIC", "PLAY"]
AFFECT_POSITION = {name: idx for idx, name in enumerate(PRIMARY_AFFECTS)}

# Interaction rules: source emotion → target emotions with effect strength
# Negative values indicate suppression; positive values indicate amplification
# Effects only manifest when source emotion exceeds minimum activation level
EMOTIONAL_CROSS_TALK: Dict[str, Dict[str, float]] = {
    "FEAR": {
        "PLAY": -0.25,
        "SEEKING": -0.15,
        "LUST": -0.20,
    },
    "RAGE": {
        "CARE": -0.30,
        "FEAR": -0.20,
        "PLAY": -0.20,
    },
    "PANIC": {
        "SEEKING": -0.20,
        "PLAY": -0.30,
        "LUST": -0.15,
    },
    "CARE": {
        "RAGE": -0.30,
        "FEAR": -0.15,
    },
    "PLAY": {
        "PANIC": -0.20,
        "FEAR": -0.15,
        "RAGE": -0.15,
    },
    "SEEKING": {
        "PANIC": -0.15,
        "FEAR": -0.10,
    },
    "LUST": {
        "RAGE": -0.15,
        "FEAR": -0.10,
    },
}

# Minimum activation required for an emotion to influence others
ACTIVATION_THRESHOLD = 0.5


def adjust_cross_emotional_effects(
    affect_vector: np.ndarray,
    mapping: Dict[str, int] = None
) -> np.ndarray:
    """
    Apply mutual emotional influences to a 7-dimensional affect state vector.

    When one emotion is strongly active, it modulates other emotions:
    e.g., heightened FEAR reduces PLAY intensity.

    IMPLEMENTATION NOTE: All adjustments are computed beforehand and applied simultaneously
    to prevent cascading effects during sequential updates.

    Args:
        affect_vector: 7-element array representing current affect intensities
        mapping: Optional custom index mapping (defaults to AFFECT_POSITION)

    Returns:
        Updated 7-element array with emotional interactions applied
    """
    if mapping is None:
        mapping = AFFECT_POSITION

    # Initialize output copy and adjustment accumulator
    adjusted_state = affect_vector.copy()
    modifications = np.zeros(7, dtype=np.float32)

    # Compute all adjustments first
    for origin_emotion, impact_map in EMOTIONAL_CROSS_TALK.items():
        origin_idx = mapping.get(origin_emotion)
        if origin_idx is None:
            continue

        origin_intensity = affect_vector[origin_idx]

        # Skip if source emotion too weak to trigger influence
        if origin_intensity < ACTIVATION_THRESHOLD:
            continue

        for destination_emotion, modulation in impact_map.items():
            dest_idx = mapping.get(destination_emotion)
            if dest_idx is None:
                continue

            # Accumulate change without immediate application
            modifications[dest_idx] += origin_intensity * modulation

    # Apply all changes at once and clamp within valid range [0, 1]
    updated_vector = np.clip(adjusted_state + modifications, 0.0, 1.0)

    return updated_vector


def describe_emotional_impacts(affect_values: np.ndarray) -> Dict[str, Dict[str, float]]:
    """
    Generate interpretable summary of which emotions are influencing others.

    Args:
        affect_values: 7-element array of current affect intensities

    Returns:
        Nested dictionary showing effective impacts, e.g.:
        {"FEAR": {"PLAY": -0.24, "SEEKING": -0.12}}
    """
    impact_summary = {}

    for origin_emotion, influence_rules in EMOTIONAL_CROSS_TALK.items():
        origin_pos = AFFECT_POSITION.get(origin_emotion)
        if origin_pos is None:
            continue

        origin_level = affect_values[origin_pos]
        if origin_level < ACTIVATION_THRESHOLD:
            continue

        current_effects = {}
        for target_emotion, coefficient in influence_rules.items():
            impact_magnitude = origin_level * coefficient
            if abs(impact_magnitude) > 0.05:
                current_effects[target_emotion] = round(impact_magnitude, 3)

        if current_effects:
            impact_summary[origin_emotion] = current_effects

    return impact_summary


def generate_explanation() -> str:
    """
    Produce plain-language description of the emotional interaction model.
    """
    explanation_lines = [
        "# Emotional Interaction Framework",
        "",
        "Drawing from Panksepp's affective neuroscience research, this model",
        "captures how emotional states mutually influence each other:",
        "",
    ]

    for origin, targets in EMOTIONAL_CROSS_TALK.items():
        suppressions = []
        enhancements = []

        for target, coefficient in targets.items():
            if coefficient < 0:
                suppressions.append(f"{target} ({coefficient:.1f})")
            else:
                enhancements.append(f"{target} (+{coefficient:.1f})")

        if suppressions:
            explanation_lines.append(f"- **{origin}** dampens: {', '.join(suppressions)}")
        if enhancements:
            explanation_lines.append(f"- **{origin}** boosts: {', '.join(enhancements)}")

    explanation_lines.extend([
        "",
        f"Emotional influences activate only when source emotion exceeds {ACTIVATION_THRESHOLD}",
    ])

    return "\n".join(explanation_lines)

from .kernel_jb_base import ARM64_OP_IMM, asm

class KernelJBPatchSecureRootMixin:
    def patch_io_secure_bsd_root(self):
        """Bypass security validation in _IOSecureBSDRoot.
        Prioritize symbol-based resolution; fallback to heuristic detection on stripped kernels.
        Locate a function referencing both 'SecureRoot' strings and patch its critical branch.
        """
        self._log("\n[JB] _IOSecureBSDRoot: bypass check")

        # Attempt direct symbol lookup first
        func_offset = self._resolve_symbol("_IOSecureBSDRoot")
        if func_offset < 0:
            func_offset = self._discover_secure_root_function()
        if func_offset < 0:
            self._log("  [-] target function not located")
            return False

        # Determine function boundaries
        end_addr = self._locate_func_end(func_offset, 0x1200)

        # Identify secure-root policy branch site
        branch_site = self._detect_policy_branch(func_offset, end_addr)
        if not branch_site:
            self._log("  [-] secure-root policy branch not identified")
            return False

        offset, target = branch_site
        patch_bytes = self._encode_branch_patch(offset, target)
        self.emit(offset, patch_bytes, f"b #0x{target - offset:X} [_IOSecureBSDRoot]")
        return True

    def _discover_secure_root_function(self):
        # Gather functions referencing "SecureRootName"
        candidates_by_name = self._functions_using_string(b"SecureRootName")
        if not candidates_by_name:
            return -1

        # Intersect with those referencing "SecureRoot"
        candidates_by_root = self._functions_using_string(b"SecureRoot")
        overlap = candidates_by_name.intersection(candidates_by_root)
        if not overlap:
            # Avoid false positives: only consider functions referencing both strings
            return -1

        # Return earliest (lowest address) matching function
        return min(overlap)

    def _functions_using_string(self, pattern):
        found_funcs = set()
        for str_addr in self._cstring_locations(pattern):
            references = self.find_string_refs(str_addr, *self.kern_text)
            for adrp_off, _, _ in references:
                fn_start = self.find_function_start(adrp_off)
                if fn_start >= 0:
                    found_funcs.add(fn_start)
        return found_funcs

    def _cstring_locations(self, pattern):
        if isinstance(pattern, str):
            pattern = pattern.encode()
        positions = []
        idx = 0
        while True:
            pos = self.raw.find(pattern, idx)
            if pos == -1:
                break
            # Backtrack to find null-terminated start
            start = pos
            while start > 0 and self.raw[start - 1] != 0:
                start -= 1
            end = self.raw.find(b"\x00", start)
            if end > start and self.raw[start:end] == pattern:
                positions.append(start)
            idx = pos + 1
        return sorted(set(positions))

    def _detect_policy_branch(self, func_begin, func_limit):
        # Search for specific branch pattern:
        #   - conditional branch (cbnz/cbz)
        #   - operand is w0
        #   - preceded by BL instruction
        #   - target lies within function bounds
        #   - not part of epilogue guard sequence (e.g., AUTIBSP/TBZ/BRK)
        for addr in range(func_begin, func_limit - 4, 4):
            disasm = self._disas_at(addr)
            if not disasm:
                continue
            instr = disasm[0]
            if instr.mnemonic not in ("cbnz", "cbz"):
                continue
            clean_op_str = instr.op_str.replace(" ", "")
            if not clean_op_str.startswith("w0,"):
                continue
            prev_disasm = self._disas_at(addr - 4)
            if not prev_disasm or not prev_disasm[0].mnemonic.startswith("bl"):
                continue

            # Extract branch target
            branch_target = None
            for op in reversed(instr.operands):
                if op.type == ARM64_OP_IMM:
                    branch_target = op.imm
                    break
            if not branch_target or not (addr < branch_target < func_limit):
                continue

            # Exclude epilogue guards
            if self._is_epilogue_protection(addr, branch_target, func_limit):
                continue

            return (addr, branch_target)
        return None

    def _is_epilogue_protection(self, branch_loc, target, func_limit):
        # Heuristic: skip if near function end or inside known guard sequences
        if branch_loc >= func_limit - 0x40 or target >= func_limit - 0x20:
            return True

        # Check for BRK in nearby instructions around target
        for probe in range(max(target - 4, 0), min(target + 0x14, func_limit), 4):
            d = self._disas_at(probe)
            if d and d[0].mnemonic == "brk":
                return True

        # Check for AUTIBSP before branch location
        for probe in range(max(branch_loc - 0x10, 0), branch_loc + 4, 4):
            d = self._disas_at(probe)
            if d and d[0].mnemonic == "autibsp":
                return True

        return False

    def _encode_branch_patch(self, loc, dest):
        delta = dest - loc
        raw_bytes = asm(f"b #{delta}")
        decoded = self._disas_n(raw_bytes, 0, 1)
        assert decoded, "Capstone decoding failed for branch patch"
        inst = decoded[0]
        assert inst.mnemonic == "b", (
            f"branch patch decode mismatch: expected 'b', got '{inst.mnemonic}'"
        )
        computed_target = None
        for op in reversed(inst.operands):
            if op.type == ARM64_OP_IMM:
                computed_target = op.imm
                break
        assert computed_target == delta, (
            "branch patch target verification failed: "
            f"expected delta 0x{delta:X}, got 0x{(computed_target or -1):X}"
        )
        return raw_bytes

"""
requests.exceptions
~~~~~~~~~~~~~~~~~~~
This module contains the set of Requests' exceptions.
"""
from pip._vendor.urllib3.exceptions import HTTPError as BaseHTTPError
from .compat import JSONDecodeError as CompatJSONDecodeError

class RequestException(IOError):
    """Base exception for all Requests-related errors."""
    def __init__(self, *args, **kwargs):
        """Initialize with optional request and response objects."""
        self.response = kwargs.pop("response", None)
        self.request = kwargs.pop("request", None)

        if self.response is not None and not self.request and hasattr(self.response, "request"):
            self.request = self.response.request

        super().__init__(*args, **kwargs)

class InvalidJSONError(RequestException):
    """Raised when a JSON parsing error occurs."""

class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Raised when text cannot be decoded into JSON format."""
    def __init__(self, *args, **kwargs):
        """
        Initialize by first constructing the CompatJSONDecodeError,
        then passing its arguments to InvalidJSONError to preserve
        proper error messaging.
        """
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)

class HTTPError(RequestException):
    """Raised when an HTTP protocol error occurs."""

class ConnectionError(RequestException):
    """Raised when network connection fails."""

class ProxyError(ConnectionError):
    """Raised when proxy-related connection issues occur."""

class SSLError(ConnectionError):
    """Raised when SSL/TLS related problems happen."""

class Timeout(RequestException):
    """Raised when request operations exceed time limits.

    This covers both connection and read timeouts.
    """
    pass

class ConnectTimeout(ConnectionError, Timeout):
    """Raised when connection establishment exceeds timeout limit.

    These requests are generally safe to retry.
    """

class ReadTimeout(Timeout):
    """Raised when server takes too long to send data."""

class URLRequired(RequestException):
    """Raised when a valid URL is missing for the request."""

class TooManyRedirects(RequestException):
    """Raised when maximum redirect count is exceeded."""

class MissingSchema(RequestException, ValueError):
    """Raised when URL scheme (http/https) is absent."""

class InvalidSchema(RequestException, ValueError):
    """Raised when URL schema is not supported or invalid."""

class InvalidURL(RequestException, ValueError):
    """Raised when URL format is malformed."""

class InvalidHeader(RequestException, ValueError):
    """Raised when HTTP header value is invalid."""

class InvalidProxyURL(InvalidURL):
    """Raised when proxy URL is invalid."""

class ChunkedEncodingError(RequestException):
    """Raised when chunked transfer encoding is malformed."""

class ContentDecodingError(RequestException, BaseHTTPError):
    """Raised when content decoding fails."""

class StreamConsumedError(RequestException, TypeError):
    """Raised when attempting to consume already consumed response content."""

class RetryError(RequestException):
    """Raised when custom retry logic fails."""

class UnrewindableBodyError(RequestException):
    """Raised when body cannot be rewound after error."""

# Warnings
class RequestsWarning(Warning):
    """Base class for all Requests warnings."""

class FileModeWarning(RequestsWarning, DeprecationWarning):
    """Raised when file opened in text mode has binary length detected."""

class RequestsDependencyWarning(RequestsWarning):
    """Raised when dependency version doesn't meet requirements."""

