import datetime
import math
from typing import Optional, Dict, List
from blankly.enums import MarginType, HedgeMode, Side, PositionMode, TimeInForce, ContractType, OrderStatus, OrderType
from blankly.exchanges.interfaces.ftx.ftx_api import FTXAPI
from blankly.exchanges.interfaces.ftx.ftx_interface import FTXInterface
from blankly.exchanges.interfaces.futures_exchange_interface import FuturesExchangeInterface
from blankly.exchanges.orders.futures.futures_order import FuturesOrder
from blankly.utils import utils, time_builder


class FTXFuturesAdapter(FuturesExchangeInterface):
    api_client: FTXAPI

    @staticmethod
    def convert_to_exchange_ticker(symbol: str) -> str:
        parts = symbol.split('-', 1)
        if len(parts) != 2 or parts[1] != 'USD':
            raise ValueError("Invalid base-quote format")
        return f"{parts[0]}-PERP"

    @staticmethod
    def convert_to_standard_ticker(exchange_ticker: str) -> str:
        parts = exchange_ticker.split('-', 1)
        if len(parts) != 2 or parts[1] != 'PERP':
            raise ValueError("Only perpetual contracts supported")
        return f"{parts[0]}-USD"

    @staticmethod
    def parse_iso_timestamp(ts_str: str) -> int:
        dt = datetime.datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
        return int(dt.timestamp())

    @staticmethod
    def map_status(status_str: str, was_cancelled: bool = False) -> OrderStatus:
        if status_str in ('new', 'open'):
            return OrderStatus.OPEN
        elif status_str == 'closed':
            return OrderStatus.CANCELED if was_cancelled else OrderStatus.FILLED
        raise ValueError(f"Unknown order status: {status_str}")

    @staticmethod
    def map_order_kind(kind_str: str) -> OrderType:
        mapping = {
            'market': OrderType.MARKET,
            'limit': OrderType.LIMIT,
            'takeProfit': OrderType.TAKE_PROFIT,
            'stop': OrderType.STOP
        }
        result = mapping.get(kind_str)
        if result is None:
            raise ValueError(f"Unsupported order type: {kind_str}")
        return result

    def build_order_from_response(self, raw_data: dict, cancelled: bool = False) -> FuturesOrder:
        return FuturesOrder(
            symbol=self.convert_to_standard_ticker(raw_data['future']),
            id=int(raw_data['id']),
            status=self.map_status(raw_data['status'], cancelled),
            size=float(raw_data['size']),
            type=self.map_order_kind(raw_data['type']),
            contract_type=ContractType.PERPETUAL,
            side=Side(raw_data['side']),
            position=PositionMode.BOTH,
            price=float(raw_data.get('avgFillPrice', 0.0)),
            limit_price=float(raw_data.get('price', 0.0)),
            time_in_force=TimeInForce.IOC if raw_data.get('ioc', False) else TimeInForce.GTC,
            response=raw_data,
            interface=self
        )

    def initialize(self):
        try:
            self.api_client.get_account_info()
        except Exception as e:
            raise RuntimeError("API credentials invalid") from e

    def list_products(self, filter_symbol: str = None) -> dict:
        futures_list = self.api_client.list_futures()
        products = {}
        for item in futures_list:
            if '-PERP' not in item['name']:
                continue
            ticker = self.convert_to_standard_ticker(item['underlying'] + '-PERP')
            products[ticker] = {
                'symbol': ticker,
                'base_asset': item['underlying'],
                'quote_asset': 'USD',
                'contract_type': ContractType.PERPETUAL,
                'price_precision': utils.increment_to_precision(item['priceIncrement']),
                'size_precision': utils.increment_to_precision(item['sizeIncrement']),
                'exchange_specific': item
            }
        return products.get(filter_symbol) if filter_symbol else products

    def fetch_balances(self, coin_filter: str = None) -> dict:
        raw_balances = self.api_client.get_balances()
        coins = self.api_client.get_coins()
        accounts = {
            c['id']: {
                'available': 0.0,
                'hold': 0.0,
                'exchange_specific': c.copy()
            } for c in coins
        }

        for bal in raw_balances:
            coin_id = bal['coin']
            accounts[coin_id]['available'] = float(bal['free'])
            accounts[coin_id]['exchange_specific'].update(bal)

        return accounts.get(coin_filter) if coin_filter else accounts

    def get_current_positions(self, symbol_filter: str = None) -> Optional[dict]:
        leverage_info = self.get_leverage()
        positions_raw = self.api_client.get_positions()
        positions = {}

        for pos in positions_raw:
            ex_sym = self.convert_to_exchange_ticker(pos['future'])
            net_size = float(pos['netSize'])
            if net_size == 0:
                continue
            std_sym = self.convert_to_standard_ticker(ex_sym)
            positions[std_sym] = {
                'size': net_size,
                'position': PositionMode.BOTH,
                'contract_type': ContractType.PERPETUAL,
                'exchange_specific': pos
            }

        return positions.get(symbol_filter) if symbol_filter else positions

    def place_market_order(self,
                           symbol: str,
                           direction: Side,
                           qty: float,
                           mode: PositionMode = PositionMode.BOTH,
                           reduce_only: bool = False) -> FuturesOrder:
        ex_sym = self.convert_to_exchange_ticker(symbol)
        if mode != PositionMode.BOTH:
            raise ValueError("Only BOTH position mode is allowed on FTX Futures")
        resp = self.api_client.place_order(ex_sym, direction, None, qty, 'market', reduce_only)
        return self.build_order_from_response(resp)

    def place_limit_order(self,
                          symbol: str,
                          direction: Side,
                          price: float,
                          qty: float,
                          mode: PositionMode = PositionMode.BOTH,
                          reduce_only: bool = False,
                          fill_policy: TimeInForce = TimeInForce.GTC) -> FuturesOrder:
        ex_sym = self.convert_to_exchange_ticker(symbol)
        ioc_flag = fill_policy == TimeInForce.IOC
        if fill_policy not in (TimeInForce.GTC, TimeInForce.IOC):
            raise ValueError("Only GTC and IOC are supported")

        if mode != PositionMode.BOTH:
            raise ValueError("Only BOTH position mode is allowed on FTX Futures")

        resp = self.api_client.place_order(ex_sym, direction, price, qty, 'limit', reduce_only, ioc=ioc_flag)
        return self.build_order_from_response(resp)

    def trigger_take_profit(self,
                            symbol: str,
                            direction: Side,
                            trigger_price: float,
                            qty: float,
                            mode: PositionMode = PositionMode.BOTH) -> FuturesOrder:
        ex_sym = self.convert_to_exchange_ticker(symbol)
        if mode != PositionMode.BOTH:
            raise ValueError("Only BOTH position mode is allowed on FTX Futures")
        resp = self.api_client.place_conditional_order(ex_sym, direction, qty, 'takeProfit', trigger_price=trigger_price)
        return self.build_order_from_response(resp)

    def trigger_stop_loss(self,
                          symbol: str,
                          direction: Side,
                          trigger_price: float,
                          qty: float,
                          mode: PositionMode = PositionMode.BOTH) -> FuturesOrder:
        ex_sym = self.convert_to_exchange_ticker(symbol)
        if mode != PositionMode.BOTH:
            raise ValueError("Only BOTH position mode is allowed on FTX Futures")
        resp = self.api_client.place_conditional_order(ex_sym, direction, qty, 'stop', trigger_price=trigger_price)
        return self.build_order_from_response(resp)

    @utils.order_protection
    def configure_hedge_mode(self, mode: HedgeMode):
        if mode == HedgeMode.HEDGE:
            raise NotImplementedError("HEDGE mode unsupported on FTX Futures")
        # Only ONEWAY is valid here

    def query_hedge_mode(self) -> HedgeMode:
        return HedgeMode.ONEWAY

    @utils.order_protection
    def adjust_leverage(self, new_leverage: float, symbol: str = None):
        if symbol:
            raise RuntimeError("FTX does not support per-symbol leverage settings.")
        self.api_client.change_account_leverage(new_leverage)

    def query_leverage(self, symbol: str = None) -> float:
        return self.api_client.get_account_info()['leverage']

    @utils.order_protection
    def set_margin_mode(self, symbol: str, mode: MarginType):
        if mode == MarginType.ISOLATED:
            raise NotImplementedError("Isolated margin not available on FTX Futures")
        # Default is crossed

    def get_margin_mode(self, symbol: str) -> MarginType:
        return MarginType.CROSSED

    def cancel_active_order(self, symbol: str, order_id: int) -> FuturesOrder:
        original = self.fetch_single_order(symbol, order_id)
        original.status = OrderStatus.CANCELED
        self.api_client.cancel_order(str(order_id))
        return original

    def list_pending_orders(self, symbol: str = None) -> List[FuturesOrder]:
        orders_raw = self.api_client.get_open_orders()
        return [self.build_order_from_response(o) for o in orders_raw]

    def fetch_single_order(self, symbol: str, order_id: int) -> FuturesOrder:
        raw = self.api_client.get_order_by_id(str(order_id))
        expected_sym = self.convert_to_exchange_ticker(symbol)
        actual_sym = raw['symbol']
        if actual_sym != expected_sym:
            raise RuntimeError("Mismatched symbol in order response")
        return self.build_order_from_response(raw)

    def fetch_current_price(self, symbol: str) -> float:
        ex_sym = self.convert_to_exchange_ticker(symbol)
        return float(self.api_client.get_future(ex_sym)['mark'])

    def retrieve_funding_history(self, symbol: str, start_ts: int, end_ts: int) -> List[Dict]:
        ex_sym = self.convert_to_exchange_ticker(symbol)
        history = []
        step = self.get_funding_interval()
        batch_limit = 500
        window_start = start_ts
        window_end = start_ts + batch_limit * step

        while True:
            batch = self.api_client.get_funding_rates(window_start, window_end, ex_sym)
            if not batch:
                break
            history.extend({
                'rate': float(entry['rate']),
                'time': self.parse_iso_timestamp(entry['time'])
            } for entry in batch)
            window_start = window_end
            window_end = min(end_ts, window_start + batch_limit * step)

        return sorted(history, key=lambda x: x['time'])

    def get_funding_interval(self) -> int:
        return time_builder.build_hour()

    def fetch_candle_data(self, symbol, start_epoch, end_epoch, interval_seconds):
        ex_sym = self.convert_to_exchange_ticker(symbol)
        return FTXInterface.ftx_product_history(self.api_client, ex_sym, start_epoch, end_epoch, interval_seconds)

    def calculate_maker_fee(self) -> float:
        raise NotImplementedError("Maker fee calculation not implemented")

    def calculate_taker_fee(self) -> float:
        raise NotImplementedError("Taker fee calculation not implemented")

    def current_funding_rate(self, symbol: str) -> float:
        raise NotImplementedError("Live funding rate retrieval not implemented")

# This module verifies the behavior of input_id_columns and upstream_id_columns 
# for computing progress percentages in features with varying lineage configurations.
