from __future__ import annotations
from metaxy_testing.models import SampleFeatureSpec
from metaxy import (
    BaseFeature,
    FeatureDep,
    FeatureGraph,
    FeatureKey,
    FieldKey,
    FieldSpec,
)
from metaxy.models.lineage import LineageRelationship

class TestUpstreamIdentifierColumns:
    """Validation suite for FeaturePlan.upstream_id_columns functionality."""

    def test_feature_without_dependencies_yields_empty_collection(self, graph: FeatureGraph):
        """A root-level feature devoid of dependencies should produce an empty list."""
        class StandaloneFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["standalone"]),
                id_columns=["entity_uid"],
                fields=[FieldSpec(key=FieldKey(["metric"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(StandaloneFeature.spec().key)
        assert plan.upstream_id_columns == []

    def test_one_parent_provides_its_identifier_columns(self, graph: FeatureGraph):
        """When a feature depends on a single parent, its ID columns are inherited."""
        class ParentFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["parent"]),
                id_columns=["asset_id", "segment_id"],
                fields=[FieldSpec(key=FieldKey(["data"]), code_version="1")],
            ),
        ):
            pass
        class ChildFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["child"]),
                id_columns=["asset_id", "segment_id"],
                deps=[FeatureDep(feature=ParentFeature)],
                fields=[FieldSpec(key=FieldKey(["processed"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(ChildFeature.spec().key)
        assert set(plan.upstream_id_columns) == {"asset_id", "segment_id"}

    def test_multiple_parents_contribute_union_of_identifiers(self, graph: FeatureGraph):
        """When multiple parents exist, the result is the union of all their ID columns."""
        class SourceAlpha(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["source_alpha"]),
                id_columns=["asset_id", "segment_id"],
                fields=[FieldSpec(key=FieldKey(["alpha_data"]), code_version="1")],
            ),
        ):
            pass
        class SourceBeta(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["source_beta"]),
                id_columns=["asset_id", "channel_id"],
                fields=[FieldSpec(key=FieldKey(["beta_data"]), code_version="1")],
            ),
        ):
            pass
        class CompositeFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["composite"]),
                id_columns=["asset_id", "segment_id", "channel_id"],
                deps=[FeatureDep(feature=SourceAlpha), FeatureDep(feature=SourceBeta)],
                fields=[FieldSpec(key=FieldKey(["combined"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(CompositeFeature.spec().key)
        assert set(plan.upstream_id_columns) == {"asset_id", "segment_id", "channel_id"}

    def test_column_renaming_modifies_upstream_mapping(self, graph: FeatureGraph):
        """When renaming is specified in FeatureDep, the resulting ID columns reflect this mapping."""
        class OriginFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["origin"]),
                id_columns=["entity_uid", "legacy_key"],
                fields=[FieldSpec(key=FieldKey(["info"]), code_version="1")],
            ),
        ):
            pass
        class TransformedFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["transformed"]),
                id_columns=["entity_uid", "updated_key"],
                deps=[
                    FeatureDep(
                        feature=OriginFeature,
                        rename={"legacy_key": "updated_key"},
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(TransformedFeature.spec().key)
        assert set(plan.upstream_id_columns) == {"entity_uid", "updated_key"}
        assert "legacy_key" not in plan.upstream_id_columns

    def test_partial_column_rename_preserves_unmapped_columns(self, graph: FeatureGraph):
        """Only explicitly renamed columns change; others remain as-is."""
        class InputFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["input"]),
                id_columns=["asset_id", "segment_id", "metadata_id"],
                fields=[FieldSpec(key=FieldKey(["raw"]), code_version="1")],
            ),
        ):
            pass
        class ModifiedFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["modified"]),
                id_columns=["asset_id", "renamed_segment_id", "metadata_id"],
                deps=[
                    FeatureDep(
                        feature=InputFeature,
                        rename={"segment_id": "renamed_segment_id"},
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["refined"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(ModifiedFeature.spec().key)
        assert set(plan.upstream_id_columns) == {
            "asset_id",
            "renamed_segment_id",
            "metadata_id",
        }
        assert "segment_id" not in plan.upstream_id_columns


class TestInputIdentifierColumns:
    """Validation suite for FeaturePlan.input_id_columns functionality."""

    def test_identity_lineage_preserves_upstream_columns(self, graph: FeatureGraph):
        """For identity (1:1) lineage, input_id_columns mirrors upstream_id_columns."""
        class SourceFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["source"]),
                id_columns=["asset_id", "segment_id"],
                fields=[FieldSpec(key=FieldKey(["value"]), code_version="1")],
            ),
        ):
            pass
        class TargetFeature(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["target"]),
                id_columns=["asset_id", "segment_id"],
                deps=[FeatureDep(feature=SourceFeature)],
                fields=[FieldSpec(key=FieldKey(["output"]), code_version="1")],
                # Default lineage type is identity
            ),
        ):
            pass
        plan = graph.get_feature_plan(TargetFeature.spec().key)
        assert set(plan.input_id_columns) == {"asset_id", "segment_id"}
        assert plan.input_id_columns == plan.upstream_id_columns

    def test_aggregation_lineage_uses_aggregation_keys(self, graph: FeatureGraph):
        """For aggregation (N:1) lineage, input_id_columns reflects the aggregation keys."""
        class RawMetrics(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["raw_metrics"]),
                id_columns=["sensor_id", "timestamp", "event_id"],
                fields=[FieldSpec(key=FieldKey(["temperature"]), code_version="1")],
            ),
        ):
            pass
        class AggregatedStats(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["aggregated_stats"]),
                id_columns=["sensor_id", "hour"],
                deps=[
                    FeatureDep(
                        feature=RawMetrics,
                        lineage=LineageRelationship.aggregation(on=["sensor_id", "hour"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["avg_temp"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(AggregatedStats.spec().key)
        # input_id_columns should be the aggregation keys
        assert set(plan.input_id_columns) == {"sensor_id", "hour"}
        # These should match the downstream's own ID columns for aggregation
        assert set(plan.input_id_columns) == set(plan.feature.id_columns)

    def test_expansion_lineage_returns_parent_columns(self, graph: FeatureGraph):
        """For expansion (1:N) lineage, input_id_columns corresponds to parent columns defined in 'on'."""
        class MasterRecord(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["master_record"]),
                id_columns=["video_id"],
                fields=[FieldSpec(key=FieldKey(["metadata"]), code_version="1")],
            ),
        ):
            pass
        class ExpandedRecords(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["expanded_records"]),
                id_columns=["video_id", "frame_id"],
                deps=[
                    FeatureDep(
                        feature=MasterRecord,
                        lineage=LineageRelationship.expansion(on=["video_id"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["features"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(ExpandedRecords.spec().key)
        # input_id_columns should be the parent identifier used in expansion
        assert plan.input_id_columns == ["video_id"]

    def test_multi_parent_aggregation_scenario(self, graph: FeatureGraph):
        """Aggregation involving multiple upstream sources allows per-dependency lineage specification.
        In such cases, input_id_columns is determined by intersecting transformed upstream inputs.
        """
        class MetricsSourceA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["metrics_source_a"]),
                id_columns=["sensor_id", "timestamp", "reading_id"],
                fields=[FieldSpec(key=FieldKey(["temp_val"]), code_version="1")],
            ),
        ):
            pass
        class MetricsSourceB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["metrics_source_b"]),
                id_columns=["sensor_id", "hour"],  # Already aligned on hour
                fields=[FieldSpec(key=FieldKey(["humidity_val"]), code_version="1")],
            ),
        ):
            pass
        class UnifiedMetrics(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["unified_metrics"]),
                id_columns=["sensor_id", "hour"],
                deps=[
                    FeatureDep(
                        feature=MetricsSourceA,
                        lineage=LineageRelationship.aggregation(on=["sensor_id", "hour"]),
                    ),
                    # MetricsSourceB uses default identity lineage
                    FeatureDep(feature=MetricsSourceB),
                ],
                fields=[FieldSpec(key=FieldKey(["summary"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(UnifiedMetrics.spec().key)
        # input_id_columns is intersection of:
        # - MetricsSourceA after aggregation: ["sensor_id", "hour"]
        # - MetricsSourceB via identity: ["sensor_id", "hour"]
        # Result: ["sensor_id", "hour"]
        assert set(plan.input_id_columns) == {"sensor_id", "hour"}

    def test_expansion_with_renamed_parent_columns(self, graph: FeatureGraph):
        """Expansion lineage respects column renaming when determining input_id_columns."""
        class MasterData(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["master_data"]),
                id_columns=["video_id"],
                fields=[FieldSpec(key=FieldKey(["meta_info"]), code_version="1")],
            ),
        ):
            pass
        class DerivedFrames(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["derived_frames"]),
                id_columns=["vid_ref", "frame_num"],
                deps=[
                    FeatureDep(
                        feature=MasterData,
                        rename={"video_id": "vid_ref"},
                        lineage=LineageRelationship.expansion(on=["vid_ref"]),
                    )
                ],
                fields=[FieldSpec(key=FieldKey(["embeddings"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(DerivedFrames.spec().key)
        # input_id_columns should use the renamed parent identifier
        assert plan.input_id_columns == ["vid_ref"]

    def test_identity_lineage_with_multiple_sources_and_renames(self, graph: FeatureGraph):
        """Identity lineage across multiple upstreams with selective renames yields intersection of transformed inputs."""
        class DataStreamA(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["data_stream_a"]),
                id_columns=["user_id", "field_x"],
                fields=[FieldSpec(key=FieldKey(["val_a"]), code_version="1")],
            ),
        ):
            pass
        class DataStreamB(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["data_stream_b"]),
                id_columns=["user_id", "field_y"],
                fields=[FieldSpec(key=FieldKey(["val_b"]), code_version="1")],
            ),
        ):
            pass
        class MergedOutput(
            BaseFeature,
            spec=SampleFeatureSpec(
                key=FeatureKey(["merged_output"]),
                id_columns=["user_id", "mapped_x", "mapped_y"],
                deps=[
                    FeatureDep(feature=DataStreamA, rename={"field_x": "mapped_x"}),
                    FeatureDep(feature=DataStreamB, rename={"field_y": "mapped_y"}),
                ],
                fields=[FieldSpec(key=FieldKey(["final_result"]), code_version="1")],
            ),
        ):
            pass
        plan = graph.get_feature_plan(MergedOutput.spec().key)
        # input_id_columns is intersection of:
        # - DataStreamA (identity + rename): ["user_id", "mapped_x"]
        # - DataStreamB (identity + rename): ["user_id", "mapped_y"]
        # Common element: ["user_id"]
        assert set(plan.input_id_columns) == {"user_id"}

