def _is_whitespace(ch: str) -> bool:
    return ch in {' ', '\t', '\n', '\r'}

def _has_character(char_set: str, target: str) -> bool:
    for char in char_set:
        if char == target:
            return True
    return False

def _adjust_index(position: int, length: int) -> int:
    adjusted = position
    if adjusted < 0:
        adjusted += length
    if adjusted < 0:
        adjusted = 0
    elif adjusted > length:
        adjusted = length
    return adjusted

def _trim_left(text: str) -> str:
    idx = 0
    size = len(text)
    while idx < size and _is_whitespace(text[idx]):
        idx += 1
    return text[idx:]

def _trim_left_chars(text: str, chars: str) -> str:
    idx = 0
    size = len(text)
    while idx < size and _has_character(chars, text[idx]):
        idx += 1
    return text[idx:]

def _trim_right(text: str) -> str:
    size = len(text)
    idx = size - 1
    while idx >= 0 and _is_whitespace(text[idx]):
        idx -= 1
    return text[:idx + 1]

def _trim_right_chars(text: str, chars: str) -> str:
    size = len(text)
    idx = size - 1
    while idx >= 0 and _has_character(chars, text[idx]):
        idx -= 1
    return text[:idx + 1]

def _strip(text: str) -> str:
    return _trim_right(_trim_left(text))

def _strip_chars(text: str, chars: str) -> str:
    return _trim_right_chars(_trim_left_chars(text, chars), chars)

def _begins_with(text: str, prefix: str) -> bool:
    text_len = len(text)
    prefix_len = len(prefix)
    if prefix_len > text_len:
        return False
    for i in range(prefix_len):
        if text[i] != prefix[i]:
            return False
    return True

def _ends_with(text: str, suffix: str) -> bool:
    text_len = len(text)
    suffix_len = len(suffix)
    if suffix_len > text_len:
        return False
    start_pos = text_len - suffix_len
    for i in range(suffix_len):
        if text[start_pos + i] != suffix[i]:
            return False
    return True

def _find_substring(text: str, pattern: str) -> int:
    return _search_window(text, pattern, 0, len(text))

def _search_window(text: str, pattern: str, begin: int, finish: int) -> int:
    text_len = len(text)
    pattern_len = len(pattern)
    left_bound = _adjust_index(begin, text_len)
    right_bound = _adjust_index(finish, text_len)

    if right_bound < left_bound:
        return -1

    if pattern_len == 0:
        return left_bound

    search_limit = right_bound - pattern_len
    pos = left_bound
    while pos <= search_limit:
        match = True
        for offset in range(pattern_len):
            if text[pos + offset] != pattern[offset]:
                match = False
                break
        if match:
            return pos
        pos += 1
    return -1

def _rfind_substring(text: str, pattern: str) -> int:
    return _reverse_search_window(text, pattern, 0, len(text))

def _reverse_search_window(text: str, pattern: str, begin: int, finish: int) -> int:
    text_len = len(text)
    pattern_len = len(pattern)
    left_bound = _adjust_index(begin, text_len)
    right_bound = _adjust_index(finish, text_len)

    if right_bound < left_bound:
        return -1

    if pattern_len == 0:
        return right_bound

    start_pos = right_bound - pattern_len
    pos = start_pos
    while pos >= left_bound:
        match = True
        for offset in range(pattern_len):
            if text[pos + offset] != pattern[offset]:
                match = False
                break
        if match:
            return pos
        pos -= 1
    return -1

def _substitute(text: str, old: str, new: str) -> str:
    if not old:
        return text

    result = []
    pos = 0
    text_len = len(text)
    old_len = len(old)

    while pos < text_len:
        if (pos + old_len <= text_len and 
            _search_window(text, old, pos, pos + old_len) == pos):
            result.append(new)
            pos += old_len
        else:
            result.append(text[pos])
            pos += 1

    return ''.join(result)

