import psutil
import logging
import threading
from typing import Optional

# Configure logger for file descriptor monitoring
logger = logging.getLogger("api.utils.fd_monitor")

class FDWatcher:
    """
    Utility to track and safeguard against File Descriptor (FD) exhaustion.
    Issues alerts when the current process approaches critical FD usage levels.
    """

    _proc_instance = psutil.Process()
    _sync_lock = threading.Lock()
    _per_request_limit = 50   # Threshold per request context (theoretical)
    _global_hard_limit = 800  # Process-wide threshold (standard soft limit is typically 1024)

    @classmethod
    def count_active_fds(cls) -> int:
        """Returns the count of currently open file descriptors for this process."""
        try:
            return cls._proc_instance.num_fds()
        except (psutil.AccessDenied, AttributeError):
            # Handle environments where num_fds() may be unsupported or inaccessible
            return -1

    @classmethod
    def assess_fd_status(cls, operation_context: str = "operation"):
        """
        Evaluates current FD consumption and logs alerts if thresholds are breached.
        Intended for use before/after resource-intensive I/O tasks.
        """
        fd_count = cls.count_active_fds()
        if fd_count == -1:
            return

        if fd_count > cls._global_hard_limit:
            logger.critical(
                f"[FD_MONITOR] CRITICAL ALERT: Process has {fd_count} open file descriptors. "
                f"Approaching system limit! Context: {operation_context}"
            )
        elif fd_count > 500:
            logger.warning(
                f"[FD_MONITOR] WARNING: Elevated file descriptor usage ({fd_count}) observed. "
                f"Context: {operation_context}"
            )

    @classmethod
    def report_potential_leak(cls, resource_path: str, current_count: int):
        """Logs a suspected leak related to a specific file/resource."""
        logger.warning(
            f"[FD_MONITOR] POTENTIAL LEAK DETECTED: Resource '{resource_path}' appears unclosed. "
            f"Current FD count: {current_count}"
        )

# Decorator utility for automatic monitoring
def track_fd_consumption(func):
    """Decorator to monitor file descriptor usage around function execution."""
    import functools
    @functools.wraps(func)
    async def decorated(*args, **kwargs):
        FDWatcher.assess_fd_status(f"pre_{func.__name__}")
        try:
            return await func(*args, **kwargs)
        finally:
            FDWatcher.assess_fd_status(f"post_{func.__name__}")
    return decorated

