import shlex
from typing import List, Tuple, Dict, Optional

class Redirection:
    """Represents a redirection operation"""
    def __init__(self, operator: str, target: str, fd: int = None):
        self.operator = operator  # '<', '>', '>>', '2>', '2>>', '&>', etc.
        self.target = target      # filename
        self.fd = fd             # file descriptor (0=stdin, 1=stdout, 2=stderr)

class CommandParser:
    """Parse shell command strings into pipeline components"""

    @staticmethod
    def _split_by_delimiter_ignoring_quotes(text: str, delimiter: str) -> List[str]:
        """
        Split string by delimiter while ignoring delimiters inside quotes
        Uses state machine approach instead of character-by-character processing
        """
        result = []
        segment = []
        quote_state = None  # None, '"', or "'"
        i = 0

        while i < len(text):
            char = text[i]

            # Handle escape sequences
            if char == '\\' and i + 1 < len(text):
                segment.append(char)
                segment.append(text[i+1])
                i += 2
                continue

            # Track quote state changes
            if char in ('"', "'"):
                if quote_state is None:
                    quote_state = char
                elif quote_state == char:
                    quote_state = None
                segment.append(char)
            # Check for delimiter only when not in quotes
            elif quote_state is None and text[i:i+len(delimiter)] == delimiter:
                result.append(''.join(segment))
                segment = []
                i += len(delimiter)
                continue
            else:
                segment.append(char)

            i += 1

        # Add remaining segment
        if segment:
            result.append(''.join(segment))

        return result

    @staticmethod
    def _extract_redirections_from_command(cmd_line: str) -> Tuple[str, Dict[str, str]]:
        """
        Extract redirection operators from command line respecting quotes
        Uses regex-based scanning after quote-aware preprocessing
        """
        redir_map = {}
        processed = []
        i = 0
        in_quote = False
        quote_char = None

        while i < len(cmd_line):
            char = cmd_line[i]

            # Handle escape sequences
            if char == '\\' and i + 1 < len(cmd_line):
                processed.append(char)
                processed.append(cmd_line[i+1])
                i += 2
                continue

            # Track quote state
            if char in ('"', "'") and not in_quote:
                in_quote = True
                quote_char = char
                processed.append(char)
            elif char == quote_char and in_quote:
                in_quote = False
                quote_char = None
                processed.append(char)
            elif not in_quote:
                # Process redirections outside quotes
                matched = False

                # Heredoc operator <<
                if cmd_line[i:i+2] == '<<':
                    i += 2
                    # Skip whitespace
                    while i < len(cmd_line) and cmd_line[i] in ' \t':
                        i += 1
                    # Extract heredoc delimiter
                    delimiter_start = i
                    while i < len(cmd_line) and cmd_line[i] not in ' \t\n':
                        i += 1
                    if i > delimiter_start:
                        redir_map['heredoc_delimiter'] = cmd_line[delimiter_start:i]
                    matched = True

                # Append stderr >>
                elif cmd_line[i:i+3] == '2>>':
                    i += 3
                    fname_result = CommandParser._get_filename(cmd_line, i)
                    if fname_result:
                        redir_map['stderr'], redir_map['stderr_mode'] = fname_result
                        i = redir_map['end_pos']
                    matched = True

                # Redirect stderr >
                elif cmd_line[i:i+2] == '2>':
                    i += 2
                    fname_result = CommandParser._get_filename(cmd_line, i)
                    if fname_result:
                        redir_map['stderr'], redir_map['stderr_mode'] = fname_result
                        i = redir_map['end_pos']
                    matched = True

                # Append stdout >>
                elif cmd_line[i:i+2] == '>>':
                    i += 2
                    fname_result = CommandParser._get_filename(cmd_line, i)
                    if fname_result:
                        redir_map['stdout'], redir_map['stdout_mode'] = fname_result
                        i = redir_map['end_pos']
                    matched = True

                # Redirect stdout >
                elif cmd_line[i] == '>':
                    i += 1
                    fname_result = CommandParser._get_filename(cmd_line, i)
                    if fname_result:
                        redir_map['stdout'], redir_map['stdout_mode'] = fname_result
                        i = redir_map['end_pos']
                    matched = True

                # Redirect stdin <
                elif cmd_line[i] == '<':
                    i += 1
                    fname_result = CommandParser._get_filename(cmd_line, i)
                    if fname_result:
                        redir_map['stdin'] = fname_result[0]
                        i = fname_result[1]
                    matched = True

                if not matched:
                    processed.append(char)
                    i += 1
            else:
                processed.append(char)
                i += 1

        return ''.join(processed).strip(), redir_map

    @staticmethod
    def _get_filename(cmd_line: str, start_idx: int) -> Optional[Tuple[str, int]]:
        """Extract filename after redirection operator"""
        pos = start_idx
        # Skip leading whitespace
        while pos < len(cmd_line) and cmd_line[pos] in ' \t':
            pos += 1

        if pos >= len(cmd_line):
            return None

        filename_chars = []
        quote_type = None

        # Check for quoted filename
        if cmd_line[pos] in ('"', "'"):
            quote_type = cmd_line[pos]
            pos += 1
            while pos < len(cmd_line):
                if cmd_line[pos] == quote_type:
                    pos += 1
                    break
                filename_chars.append(cmd_line[pos])
                pos += 1
        else:
            # Unquoted filename - read until special chars
            while pos < len(cmd_line) and cmd_line[pos] not in ' \t\n|<>;&':
                filename_chars.append(cmd_line[pos])
                pos += 1

        if filename_chars:
            return (''.join(filename_chars), pos)
        return None

    @staticmethod
    def parse_command_line(command_line: str) -> Tuple[List[Tuple[str, List[str]]], Dict]:
        """
        Parse complete command line with pipelines and redirections
        Returns tuple of (pipeline_commands, global_redirections)
        """
        # First extract redirections using new method
        clean_cmd, redir_info = CommandParser._extract_redirections_from_command(command_line)

        # Then parse the pipeline
        pipeline_cmds = CommandParser._process_pipeline(clean_cmd)

        return pipeline_cmds, redir_info

    @staticmethod
    def _process_pipeline(cmd_line: str) -> List[Tuple[str, List[str]]]:
        """
        Process command line into pipeline components
        Uses quote-aware splitting and tokenization
        """
        if not cmd_line.strip():
            return []

        # Split by pipe respecting quotes
        segments = CommandParser._split_by_delimiter_ignoring_quotes(cmd_line, '|')
        commands = []

        for segment in segments:
            segment = segment.strip()
            if not segment:
                continue

            try:
                tokens = shlex.split(segment)
            except ValueError:
                tokens = segment.split()

            if tokens:
                cmd_name = tokens[0]
                args = tokens[1:] if len(tokens) > 1 else []
                commands.append((cmd_name, args))

        return commands

    @staticmethod
    def _extract_redirections(cmd_line: str) -> Tuple[str, Dict[str, str]]:
        """Wrapper for redirection extraction"""
        return CommandParser._extract_redirections_from_command(cmd_line)

    @staticmethod
    def format_argument(arg: str) -> str:
        """Quote argument if necessary for shell safety"""
        special_chars = set('|&;<>()$`\\\'" ')
        if any(c in arg for c in special_chars):
            return shlex.quote(arg)
        return arg

    @staticmethod
    def strip_quotes(arg: str) -> str:
        """Remove surrounding quotes from argument"""
        if len(arg) >= 2 and ((arg[0] == '"' and arg[-1] == '"') or 
                              (arg[0] == "'" and arg[-1] == "'")):
            return arg[1:-1]
        return arg

# Request context management using ContextVar

from contextvars import ContextVar
from contextlib import contextmanager

_request_context = ContextVar("request_context", default=None)

def fetch_request_context(key, fallback=None):
    current_ctx = _request_context.get()
    return current_ctx.get(key, fallback) if current_ctx else fallback

def modify_request_context(**changes):
    current_ctx = _request_context.get()
    if current_ctx is not None:
        current_ctx.update(changes)

@contextmanager
def with_request_context(initial_data):
    token = _request_context.set(initial_data)
    try:
        yield
    finally:
        _request_context.reset(token)

