import copy
import json
import os
import time
import uuid
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Dict, List, Optional, Union, Any
import requests
from common.uc_eval.utils.data_class import (
    ModelConfig,
    MultiTurnDialogRecord,
    RequestRecord,
)
from common.uc_eval.utils.utils import PathUtil, get_logger
from tqdm import tqdm
from transformers import AutoTokenizer
from typing_extensions import override
import logging

logger = get_logger()
TIMEOUT_SECONDS = 6000
HEADERS = {"User-Agent": "Benchmark Client", "Content-Type": "application/json"}
CHUNK_SIZE_BYTES = 2**16

def _execute_with_thread_pool(
    worker_func,
    processor_func,
    input_items,
    concurrency_level,
    progress_label="Processing Tasks",
) -> List[Any]:
    results: List[Any] = []

    if concurrency_level > len(input_items):
        logger.warning(
            f"Requested concurrency ({concurrency_level}) exceeds task count ({len(input_items)}). Adjusting..."
        )
        concurrency_level = max(1, len(input_items))

    logger.info(f"Initiating {len(input_items)} tasks with concurrency level {concurrency_level}...")

    with ThreadPoolExecutor(max_workers=concurrency_level) as executor:
        future_to_item = {executor.submit(worker_func, item): item for item in input_items}

        with tqdm(total=len(future_to_item), desc=progress_label, mininterval=0.5) as pbar:
            for future in as_completed(future_to_item):
                try:
                    result = processor_func(future.result())
                    results.append(result)
                    pbar.update(1)
                    pbar.set_postfix({
                        "Completed": len(results),
                        "Remaining": len(future_to_item) - pbar.n
                    })
                except Exception as e:
                    pbar.update(1)
                    logger.error(f"Task execution failed: {str(e)}")
                    raise RuntimeError(f"Task execution failed: {str(e)}")

    return results


class BaseClient:
    def __init__(
        self,
        config: ModelConfig,
        streaming_mode: bool = False,
        **kwargs,
    ):
        # Configuration setup
        self.server_address = config.ip_ports
        self.api_endpoint = f"http://{self.server_address}/v1/chat/completions"
        self.model_name = config.served_model_name

        tokenizer_dir = PathUtil.get_datasets_dir_path(config.tokenizer_path)
        self.tokenizer = AutoTokenizer.from_pretrained(tokenizer_dir)

        # Parallelism settings
        self.max_concurrent_requests = kwargs.get("max_parallel_num", 10)
        self.http_session = self._create_http_session(self.max_concurrent_requests)

        # Model constraints
        self.sequence_length_limit = config.max_seq_length
        self.base_payload = copy.deepcopy(config.payload)

        # Streaming configuration
        self.enable_streaming = streaming_mode
        if self.enable_streaming:
            self.base_payload.update({
                "stream": True,
                "ignore_eos": True,
                "temperature": 0.0
            })

    def _create_http_session(self, pool_size: int):
        session = requests.Session()
        adapter = requests.adapters.HTTPAdapter(
            pool_maxsize=max(pool_size, 10)
        )
        session.mount("http://", adapter)
        session.mount("https://", adapter)
        return session

    def process_batch_requests(
        self, 
        prompts: List[str], 
        batch_size: int, 
        token_limit: int
    ) -> List[RequestRecord]:
        return _execute_with_thread_pool(
            worker_func=lambda prompt: self._submit_single_request(prompt, token_limit),
            processor_func=self._process_single_record,
            input_items=prompts,
            concurrency_level=batch_size,
        )

    def _submit_single_request(self, prompt_text: str, max_tokens: int) -> RequestRecord:
        payload = self._prepare_request_payload(prompt_text, max_tokens)
        record = self._initialize_request_record(prompt_text)

        if self.enable_streaming:
            record = self._handle_streaming_request(payload, record)
        else:
            record = self._handle_synchronous_request(payload, record)

        return record

    def _prepare_request_payload(self, prompt_text: str, max_tokens: int) -> Dict:
        payload = copy.deepcopy(self.base_payload)
        payload["model"] = self.model_name

        if max_tokens > 0:
            payload["max_tokens"] = max_tokens

        # Truncate long inputs if necessary
        encoded_input = self.tokenizer.encode(prompt_text)
        if len(encoded_input) > self.sequence_length_limit:
            half_len = self.sequence_length_limit // 2
            truncated_ids = encoded_input[:half_len] + encoded_input[-half_len:]
            prompt_text = self.tokenizer.decode(truncated_ids)

        # Format message based on input type
        if isinstance(prompt_text, str):
            messages = [{"role": "user", "content": prompt_text}]
        elif isinstance(prompt_text, list):
            messages = prompt_text
        else:
            raise ValueError("Prompt must be either a string or list of message dictionaries")

        payload["messages"] = messages
        return payload

    def _initialize_request_record(self, prompt_data) -> RequestRecord:
        if isinstance(prompt_data, str):
            return RequestRecord(input_data=prompt_data)
        else:
            return RequestRecord(input_data=str(prompt_data))

    def _process_single_record(self, record: RequestRecord) -> RequestRecord:
        if not record:
            logger.warning("Received empty record, skipping processing")
            return record

        record.input_tokens = len(self.tokenizer.tokenize(record.input_data))
        record.output_tokens = len(self.tokenizer.tokenize(record.output_data))

        # Process timing data
        if record.tbt_list:
            record.tbt_latency = sum(record.tbt_list[2:]) / record.output_tokens if record.output_tokens > 0 else 0
        else:
            record.tbt_latency = 0

        return record

    def _send_http_request(self, payload: Dict) -> requests.Response:
        try:
            response = self.http_session.post(
                self.api_endpoint,
                headers=HEADERS,
                json=payload,
                timeout=TIMEOUT_SECONDS,
                stream=self.enable_streaming
            )
            response.raise_for_status()
            return response
        except Exception as error:
            raise self._translate_error(error)

    def _handle_synchronous_request(self, payload: Dict, record: RequestRecord) -> RequestRecord:
        record.start_timestamp = time.time()
        response = self._send_http_request(payload)
        result = json.loads(response.text)

        request_id = result.get("id", "unknown_request_id")
        output_content = self._extract_output_from_response(result)

        record.request_id = request_id
        record.output_data = output_content
        record.is_success = True
        record.end_timestamp = time.time()
        record.request_duration = record.end_timestamp - record.start_timestamp

        return record

    def _extract_output_from_response(self, response_data: Dict) -> str:
        choices = response_data.get("choices", [])
        if not choices:
            return ""

        message = choices[0].get("message", {})
        content = message.get("content") or message.get("reasoning_content") or ""
        return content

    def _handle_streaming_request(self, payload: Dict, record: RequestRecord) -> RequestRecord:
        all_chunks = []
        first_token_processed = True
        last_chunk_data = None
        timed_out_due_to_length = False

        current_time = previous_time = time.perf_counter()
        record.start_timestamp = previous_time

        with self.http_session.post(
            self.api_endpoint,
            headers=HEADERS,
            json=payload,
            stream=True
        ) as response:
            for chunk in response.iter_content(chunk_size=CHUNK_SIZE_BYTES):
                current_time = time.perf_counter()
                all_chunks.append(chunk)

                if not chunk.strip():
                    continue

                last_chunk_data = chunk

                # Timing measurements
                elapsed = current_time - previous_time
                if first_token_processed:
                    record.prefill_latency = elapsed
                    first_token_processed = False
                else:
                    record.tbt_list.append(elapsed)
                previous_time = current_time

                # Process chunk content
                try:
                    chunk_content = chunk[5:].strip().decode("utf-8")
                except (UnicodeDecodeError, IndexError):
                    continue

                # Handle special cases
                if chunk.startswith(b"Engine callback timeout"):
                    self._log_request_details(
                        request_id=record.request_id,
                        chunk=chunk,
                        content=record.output_data,
                        all_chunks=all_chunks,
                        payload=payload,
                        message="Engine callback timeout occurred"
                    )
                    record.output_data = "TIMEOUT"
                    return record

                if "[DONE]" in chunk_content:
                    continue

                # Extract output from chunk
                chunk_data = json.loads(chunk_content)
                output_text = self._extract_output_from_stream(chunk_data)

                if not record.request_id:
                    record.request_id = chunk_data.get("id", "unknown_request_id")

                record.output_data += output_text

                # Check finish reason
                finish_reason = (
                    chunk_data.get("choices", [{}])[0]
                    .get("finish_reason", "")
                )
                if finish_reason == "length":
                    timed_out_due_to_length = True

        # Finalize stream processing
        if last_chunk_data and last_chunk_data.startswith(b"data:"):
            final_chunk = last_chunk_data[5:].strip().decode("utf-8").rstrip("\0")
        else:
            final_chunk = last_chunk_data.strip().decode("utf-8").rstrip("\0") if last_chunk_data else ""

        if "[DONE]" in final_chunk:
            pass  # Normal completion
        else:
            self._log_request_details(
                request_id=record.request_id,
                chunk=last_chunk_data,
                content=record.output_data,
                all_chunks=all_chunks,
                payload=payload,
                message="Stream ended unexpectedly"
            )

        # Handle empty output scenarios
        if not record.output_data:
            if timed_out_due_to_length:
                self._log_request_details(
                    request_id=record.request_id,
                    chunk=last_chunk_data,
                    content=record.output_data,
                    all_chunks=all_chunks,
                    payload=payload,
                    message="Server scheduling timeout detected"
                )
            else:
                self._log_request_details(
                    request_id=record.request_id,
                    chunk=last_chunk_data,
                    content=record.output_data,
                    all_chunks=all_chunks,
                    payload=payload,
                    message="Empty response received - possible engine error"
                )
            return record

        record.is_success = True
        record.end_timestamp = time.perf_counter()
        record.request_duration = record.end_timestamp - record.start_timestamp
        logger.debug(f"Request {record.request_id} completed in {record.request_duration:.2f}s")

        return record

    def _extract_output_from_stream(self, chunk_data: Dict) -> str:
        delta = chunk_data.get("choices", [{}])[0].get("delta", {})
        content = delta.get("content") or delta.get("reasoning_content") or ""
        return content

    def clear_gpu_memory(self) -> bool:
        """Clear GPU memory via API endpoint"""
        os.environ["NO_PROXY"] = "127.0.0.1,localhost,local,.local"
        logger.info("Initiating GPU memory cleanup")

        headers = {"Content-Type": "application/json"}
        payload = {}
        url = f"http://{self.server_address}/reset_prefix_cache"

        try:
            response = requests.post(
                url, json=payload, headers=headers, timeout=TIMEOUT_SECONDS
            )
            response.raise_for_status()
        except Exception as error:
            raise self._translate_error(error)

        time.sleep(5)
        logger.info("GPU memory cleanup completed successfully")
        return True

    def _translate_error(self, error: Exception) -> Exception:
        """Convert low-level errors to meaningful exceptions"""
        if isinstance(error, requests.exceptions.ConnectionError):
            logger.error(f"Connection failed to {self.api_endpoint}")
            return ConnectionError(f"Unable to connect to {self.api_endpoint}")

        elif isinstance(error, requests.exceptions.Timeout):
            logger.error("Request timed out - server may be overloaded")
            return TimeoutError("Request timed out - please check server status")

        elif isinstance(error, requests.exceptions.HTTPError):
            status_code = error.response.status_code
            if status_code == 404:
                logger.error("Resource not found - verify model name and endpoint")
            else:
                logger.error(f"HTTP error with status code {status_code}")
            return Exception(f"HTTP error: {status_code}, Details: {error}")

        else:
            logger.error(f"Unexpected error: {error}")
            return Exception(f"Unexpected error: {error}")

    @staticmethod
    def _log_request_details(**details):
        """Format and log request details for debugging"""
        for key, value in details.items():
            formatted_value = (
                json.dumps(value, ensure_ascii=False)
                if isinstance(value, dict)
                else str(value)
            )
            logger.error(f"{key}: {formatted_value}")


class MultiTurnClient(BaseClient):
    def __init__(self, config: ModelConfig, streaming_mode: bool, **kwargs):
        super().__init__(config, streaming_mode, **kwargs)
        self.session_uuid = uuid.uuid4().hex
        self.use_prefix_cache = kwargs.get("enable_prefix_cache", False)
        self.should_clear_memory = kwargs.get("enable_clear_hbm", False)

    @override
    def process_batch_requests(
        self,
        conversation_cases: List[List[Union[str, Dict]]],
        batch_size: int,
        token_limit: int = -1,
    ) -> List[List[MultiTurnDialogRecord]]:
        return _execute_with_thread_pool(
            worker_func=lambda case: self._process_conversation(case, token_limit),
            processor_func=self._process_multi_turn_records,
            input_items=conversation_cases,
            concurrency_level=batch_size,
        )

    def _process_conversation(
        self, conversation_case: List[Union[str, Dict]], max_tokens: int = -1
    ) -> List[MultiTurnDialogRecord]:
        case_name, dialog_data = conversation_case
        conversation_history = []
        turn_records = []

        conversations = dialog_data["conversations"]
        turn_pairs = self._group_conversation_into_turns(conversations, 2)

        for idx, turn in enumerate(turn_pairs):
            user_message = turn[0]["value"]
            assistant_response = turn[1]["value"]

            # Prepare request payload
            request_prompt = self._construct_turn_payload(conversation_history, user_message)

            # Execute request
            single_record = self._submit_single_request(request_prompt, max_tokens)
            single_record.case_name = case_name

            # Update conversation history
            conversation_history = self._update_conversation_history(
                conversation_history, user_message, assistant_response
            )

            # Clear memory if enabled
            if self.should_clear_memory:
                self.clear_gpu_memory()

            # Create multi-turn record
            multi_turn_record = self._create_multi_turn_record(
                single_record, len(turn_pairs), idx
            )
            turn_records.append(multi_turn_record)

        return turn_records

    def _create_multi_turn_record(
        self, base_record: RequestRecord, total_turns: int, current_turn: int
    ) -> MultiTurnDialogRecord:
        new_record = MultiTurnDialogRecord()
        new_record.__dict__.update(base_record.__dict__)
        new_record.total_turns = total_turns
        new_record.turn_index = current_turn
        return new_record

    @staticmethod
    def _group_conversation_into_turns(conversation_list: list, group_size: int) -> List[List[Dict]]:
        if group_size <= 0:
            raise ValueError("Group size must be positive")

        num_groups = len(conversation_list) // group_size
        return [
            conversation_list[i * group_size : (i + 1) * group_size]
            for i in range(num_groups)
        ]

    def _construct_turn_payload(self, history: Optional[List[Dict]], new_message: str) -> List[Dict]:
        history_copy = copy.deepcopy(history)

        # Add unique identifier for prefix caching
        if history_copy:
            if self.use_prefix_cache:
                history_copy[0]["content"] = f"uuid: [{self.session_uuid}]" + history_copy[0]["content"]
            else:
                history_copy[0]["content"] = f"uuid: [{uuid.uuid4().hex}]" + history_copy[0]["content"]

        return history_copy + [{"role": "user", "content": new_message}]

    @staticmethod
    def _update_conversation_history(
        history: Optional[List[Dict]], user_message: str, assistant_message: str
    ) -> List[Dict]:
        updated_history = history or []
        updated_history.append({"role": "user", "content": user_message})
        updated_history.append({"role": "assistant", "content": assistant_message})
        return updated_history


class DocQaClient(BaseClient):
    def __init__(self, config: ModelConfig, streaming_mode: bool, **kwargs):
        super().__init__(config, streaming_mode, **kwargs)

    @override
    def process_batch_requests(
        self, 
        qa_cases: List[Union[str, List[str], str, str]], 
        batch_size: int, 
        token_limit: int = -1
    ) -> List[MultiTurnDialogRecord]:
        return _execute_with_thread_pool(
            worker_func=lambda case: self._process_qa_case(case, token_limit),
            processor_func=self._process_single_record,
            input_items=qa_cases,
            concurrency_level=batch_size,
        )

    def _process_qa_case(
        self, qa_case: Union[str, List[str], str, str], max_tokens: int = -1
    ) -> RequestRecord:
        case_name, prompt_list, question, expected_answer = qa_case
        final_record = RequestRecord()

        for idx, prompt in enumerate(prompt_list):
            single_record = self._submit_single_request(prompt, max_tokens)

            if idx == 0:
                final_record = single_record
                final_record.case_name = case_name
                final_record.question = question
                final_record.expected_output = expected_answer

            if idx == len(prompt_list) - 1:
                final_record.output_data = single_record.output_data
                final_record.output_tokens = single_record.output_tokens

        return final_record

import argparse
import re

def analyze_skipped_tests(input_file):
    skip_details = {}
    total_skipped = 0
    with open(input_file, 'r') as data:
        for record in data:
            pattern = re.search(r'^SKIPPED \[(\d+)\] (tests/.*): (.*)$', record)
            if pattern:
                total_skipped += 1
                file_path, line_num, cause = pattern.groups()
                skip_details.setdefault(cause, []).append((file_path, line_num))

    for reason, occurrences in sorted(skip_details.items(), key=lambda item: len(item[1])):
        print(f"{len(occurrences):4} skipped due to: {reason}")
    print("Total skipped tests:", total_skipped)

def analyze_failed_tests(input_file):
    fail_details = {}
    total_failures = 0
    with open(input_file, 'r') as data:
        for record in data:
            pattern = re.search(r'^FAILED (tests/.*) - (.*): (.*)$', record)
            if pattern:
                total_failures += 1
                _, error_type, description = pattern.groups()
                fail_details.setdefault(description, []).append(error_type)

    for desc, errors in sorted(fail_details.items(), key=lambda item: len(item[1])):
        print(f"{len(errors):4} failed due to `{errors[0]}` -> {desc}")
    print("Total failed tests:", total_failures)
    if total_failures > 0:
        exit(1)

def analyze_error_tests(input_file):
    print(input_file)
    error_details = {}
    total_errors = 0
    with open(input_file, 'r') as data:
        for record in data:
            pattern = re.search(r'^ERROR (tests/.*) - (.*): (.*)$', record)
            if pattern:
                total_errors += 1
                _, test_issue, explanation = pattern.groups()
                error_details.setdefault(explanation, []).append(test_issue)

    for explanation, issues in sorted(error_details.items(), key=lambda item: len(item[1])):
        print(f"{len(issues):4} encountered errors due to `{issues[0]}` -> {explanation}")
    print("Total errors:", total_errors)
    if total_errors > 0:
        exit(1)

def main():
    parser = argparse.ArgumentParser(description="Parse pytest output logs")
    parser.add_argument("--file", required=True, help="Path to the log file")
    parser.add_argument("--skip", action="store_true", help="Display skipped test reasons")
    parser.add_argument("--fail", action="store_true", help="Display failed test details")
    parser.add_argument("--errors", action="store_true", help="Display error details")

    options = parser.parse_args()

    if options.skip:
        analyze_skipped_tests(options.file)
    if options.fail:
        analyze_failed_tests(options.file)
    if options.errors:
        analyze_error_tests(options.file)

if __name__ == "__main__":
    main()

# Custom JAX module utilities for parameter and child traversal

from typing import Iterable, Iterator
from flax import nnx


class ExtendedJaxModule(nnx.Module):
    """Extended base module for JAX layers, providing enhanced traversal capabilities."""

    def _module_name(self) -> str:
        return self.__class__.__name__

    def get_params_with_prefix(
        self,
        prefix: str = "",
        traverse_submodules: bool = True
    ) -> Iterator[tuple[str, nnx.Param]]:
        """Generates parameter names and values with optional prefixing.

        Args:
            prefix: Initial string to prepend to parameter names.
            traverse_submodules: Whether to include parameters from nested modules.

        Yields:
            (string, Param): Tuple of fully qualified name and parameter object.
        """
        # Process direct parameters first
        for attr_name, attr_value in vars(self).items():
            if isinstance(attr_value, nnx.Param):
                full_name = f"{prefix}.{attr_name}" if prefix else attr_name
                yield full_name, attr_value

        # Early exit if not recursing
        if not traverse_submodules:
            return

        # Recursively process submodules
        for submodule_name, submodule in self.get_direct_submodules():
            new_prefix = f"{prefix}.{submodule_name}" if prefix else submodule_name
            yield from submodule.get_params_with_prefix(
                prefix=new_prefix,
                traverse_submodules=True
            )

    def get_direct_submodules(
        self
    ) -> Iterator[tuple[str, "ExtendedJaxModule | ExtendedJaxModuleList"]]:
        """Provides iterator over immediate submodule members.

        Yields:
            (string, Module | list): Name and corresponding submodule instance.
        """
        for attr_name, attr_value in vars(self).items():
            if isinstance(attr_value, ExtendedJaxModule):
                yield attr_name, attr_value
            elif isinstance(attr_value, list) or isinstance(attr_value, nnx.List):
                yield attr_name, ExtendedJaxModuleList(attr_value)


class ExtendedJaxModuleList(nnx.List):
    """Container for managing ordered collections of JAX modules."""

    def __init__(self, module_sequence: Iterable[ExtendedJaxModule]):
        """Constructs the module list from an iterable of modules.

        Args:
            module_sequence: Collection of ExtendedJaxModule instances.
        """
        super().__init__()
        for mod in module_sequence:
            self.append(mod)

    def _container_name(self) -> str:
        return self.__class__.__name__

    def collect_all_parameters(
        self,
        root_prefix: str = "",
        include_nested: bool = True
    ) -> Iterator[tuple[str, nnx.Param]]:
        """Aggregates parameters from all contained modules.

        Args:
            root_prefix: Base path for parameter naming.
            include_nested: Flag to control recursive parameter collection.

        Yields:
            (string, Param): Qualified parameter name and value.
        """
        for position, module in enumerate(self):
            segment_prefix = f"{root_prefix}.{position}" if root_prefix else str(position)
            yield from module.collect_all_parameters(
                prefix=segment_prefix,
                include_nested=include_nested
            )

    def list_submodules(
        self
    ) -> Iterator[tuple[str, "ExtendedJaxModule | ExtendedJaxModuleList"]]:
        """Iterates through contained modules with index-based identifiers.

        Yields:
            (string, ExtendedJaxModule): Index as string and corresponding module.
        """
        for idx, element in enumerate(self):
            if isinstance(element, ExtendedJaxModule):
                yield str(idx), element
            elif isinstance(element, list):
                yield str(idx), ExtendedJaxModuleList(element)

# Type III Clone: AstGraphVariableRenamer with equivalent logic but different structure and naming

import ast
import inspect
import os
import shutil
import tempfile
from pathlib import Path
from typing import Dict, List, Set, Tuple, Any, Optional

import torch

from graph_net.hash_util import get_sha256_hash
from graph_net.imp_util import load_module
from graph_net.sample_pass.resumable_sample_pass_mixin import ResumableSamplePassMixin
from graph_net.tensor_meta import TensorMeta


class GraphVariableReplacer(ResumableSamplePassMixin):
    def __init__(self, configuration):
        super().__init__()
        self._config = configuration
        self._input_checker = self._build_input_predicate(configuration)
        self._runnable_checker = self._build_runnable_predicate(configuration)

    def _build_input_predicate(self, cfg):
        mod = load_module(cfg["data_input_predicator_filepath"])
        cls = getattr(mod, cfg["data_input_predicator_class_name"])
        return cls(cfg["data_input_predicator_config"])

    def _build_runnable_predicate(self, cfg):
        mod = load_module(cfg["model_runnable_predicator_filepath"])
        cls = getattr(mod, cfg["model_runnable_predicator_class_name"])
        return cls(cfg["model_runnable_predicator_config"])

    def configure(
        self,
        model_root: str,
        output_root: str,
        device: str,
        resume_mode: bool = False,
        dry_run: bool = False,
        max_models: int = None,
        input_pred_file: str = None,
        input_pred_class: str = None,
        input_pred_args: dict = None,
        runnable_pred_file: str = None,
        runnable_pred_class: str = None,
        runnable_pred_args: dict = None,
    ):
        pass

    def __call__(self, relative_model_path: str):
        self.process_with_resume(relative_model_path)

    def is_processed(self, rel_model_path: str) -> bool:
        return self.is_already_processed(rel_model_path, search_filename="model.py")

    def process_resumed(self, rel_model_path: str):
        torch.cuda.empty_cache()
        target_dir = os.path.realpath(os.path.join(self._config["output_dir"], rel_model_path))
        source_dir = os.path.join(self._config["model_path_prefix"], rel_model_path)

        graph_cls = retrieve_graph_module_class(
            os.path.join(source_dir, "model.py"), "GraphModule"
        )
        param_inputs, param_weights = self._extract_parameter_names(graph_cls, source_dir)
        mapping = self._generate_replacement_map(param_inputs, param_weights)

        with tempfile.TemporaryDirectory(prefix="var_rename_") as tmp_dir:
            temp_model_dir = os.path.join(tmp_dir, os.path.basename(target_dir))
            shutil.copytree(source_dir, temp_model_dir, dirs_exist_ok=True)

            self._rewrite_model_file(temp_model_dir, mapping, param_inputs, param_weights)
            self._rewrite_metadata(temp_model_dir, "weight_meta.py", mapping)
            self._rewrite_metadata(temp_model_dir, "input_meta.py", mapping)

            if self._config.get("try_run", False):
                self._validate_model(temp_model_dir)

            shutil.copytree(temp_model_dir, target_dir, dirs_exist_ok=True)

    def _extract_parameter_names(self, graph_module, model_directory):
        inputs = []
        weights = []
        signature = inspect.signature(graph_module.forward)
        for param_name, parameter in signature.parameters.items():
            if param_name == "self":
                continue
            if not self._input_checker(model_directory, param_name):
                weights.append(param_name)
            else:
                inputs.append(param_name)
        return inputs, weights

    def _generate_replacement_map(self, input_params, weight_params):
        replacements = {}
        for i, name in enumerate(input_params):
            replacements[name] = f"in_{i}"
        for i, name in enumerate(weight_params):
            replacements[name] = f"w_{i}"
        return replacements

    def _rewrite_model_file(self, model_dir, rename_dict, input_names, weight_names):
        model_path = Path(model_dir) / "model.py"
        code_text = model_path.read_text(encoding="utf-8")
        tree = ast.parse(code_text)
        class_node = self._find_graph_module_ast(tree)
        transformer = VariableTransformer(rename_dict, input_names, weight_names)
        transformer.visit(class_node)
        updated_code = ast.unparse(tree)
        model_path.write_text(updated_code, encoding="utf-8")
        hash_value = get_sha256_hash(updated_code)
        (Path(model_dir) / "graph_hash.txt").write_text(hash_value)

    def _find_graph_module_ast(self, tree):
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name == "GraphModule":
                return node
        return None

    def _rewrite_metadata(self, model_dir, meta_filename, rename_dict):
        meta_path = Path(model_dir) / meta_filename
        metas = TensorMeta.unserialize_from_py_file(str(meta_path))
        for meta_obj in metas:
            assert (
                meta_obj.name in rename_dict
            ), f"[Warning] {meta_obj.name} in {meta_filename} missing from rename map."
            if meta_obj.original_name is None:
                meta_obj.original_name = meta_obj.name
            meta_obj.name = rename_dict[meta_obj.name]
        py_content = "\n\n".join([m.serialize_to_py_str() for m in metas])
        meta_path.write_text(py_content)

    def _validate_model(self, model_path):
        print(f"[GraphVariableReplacer] Attempting execution of {model_path}")
        assert self._runnable_checker(
            model_path
        ), f"{model_path} does not meet runnability criteria"


def retrieve_graph_module_class(filepath: str, target_class: str):
    print(f"Fetching {target_class} from {filepath}")
    module = load_module(filepath, "anonymous_graph_module")
    cls = getattr(module, target_class, None)
    return cls


class VariableTransformer(ast.NodeTransformer):
    def __init__(self, rename_map, input_vars, weight_vars):
        self._rename_map = rename_map
        self._tracked_vars = set(input_vars) | set(weight_vars)
        self._counter = {"temp": 0}
        self._in_forward_method = False

    def visit_FunctionDef(self, node):
        if node.name != "forward":
            return node
        self._in_forward_method = True
        node.args.args = self._transform_function_arguments(node.args.args)
        node.body = self._process_body_statements(node.body)
        self._in_forward_method = False
        return node

    def _transform_function_arguments(self, args):
        new_args = []
        for arg in args:
            if arg.arg == "self":
                new_args.append(arg)
            else:
                new_args.append(self._create_new_argument(arg))
        return new_args

    def _create_new_argument(self, arg):
        if arg.arg in self._rename_map:
            return ast.arg(arg=self._rename_map[arg.arg], annotation=arg.annotation)
        return arg

    def _process_body_statements(self, body):
        processed = []
        for stmt in body:
            cleaned = self._strip_clear_assignments(stmt)
            if cleaned is not None:
                transformed = self.visit(cleaned)
                processed.append(transformed)
        return processed

    def _strip_clear_assignments(self, stmt):
        if self._is_none_assignment(stmt):
            return self._prune_none_assignment(stmt)
        elif isinstance(stmt, ast.Delete):
            return self._prune_deletion(stmt)
        return stmt

    def _is_none_assignment(self, stmt):
        return (
            isinstance(stmt, ast.Assign)
            and isinstance(stmt.value, ast.Constant)
            and stmt.value.value is None
        )

    def _prune_none_assignment(self, stmt):
        filtered = [t for t in stmt.targets if not self._is_tracked_variable(t)]
        if not filtered:
            return None
        stmt.targets = filtered
        return stmt

    def _is_tracked_variable(self, target):
        return (
            isinstance(target, ast.Name)
            and target.id in self._tracked_vars
        )

    def _prune_deletion(self, stmt):
        kept = []
        for t in stmt.targets:
            result = self._filter_deletion_target(t)
            if result is not None:
                kept.append(result)
        if not kept:
            return None
        stmt.targets = kept
        return stmt

    def _filter_deletion_target(self, target):
        if isinstance(target, ast.Tuple):  # del (a, b)
            elements = [e for e in target.elts if not self._is_tracked_variable(e)]
            return ast.Tuple(elts=elements, ctx=ast.Del()) if elements else None
        elif not self._is_tracked_variable(target):
            return target
        return None

    def visit_Assign(self, node):
        if not self._in_forward_method:
            return node
        self._track_assigned_variables(node.targets)
        self.generic_visit(node)
        return node

    def _track_assigned_variables(self, targets):
        for t in targets:
            for name in self._extract_variable_names(t):
                self._register_if_needed(name)

    def _extract_variable_names(self, target):
        if isinstance(target, ast.Name):
            yield target.id
        elif isinstance(target, (ast.Tuple, ast.List)):
            for elt in target.elts:
                yield from self._extract_variable_names(elt)
        else:
            pass

    def _register_if_needed(self, name):
        if name not in self._rename_map:
            new_name = f"tmp_{self._counter['temp']}"
            self._counter["temp"] += 1
            self._rename_map[name] = new_name

    def visit_Name(self, node):
        if not self._in_forward_method:
            return node
        if node.id in self._rename_map:
            return ast.Name(id=self._rename_map[node.id], ctx=node.ctx)
        return node

