# Custom integer conversion utility with default fallback

from typing import Any

def convert_to_int(value: Any, *, fallback: int) -> int:
    """Attempt to convert a value to an integer, returning fallback if conversion fails."""
    # Handle boolean values explicitly (since bool is subclass of int)
    if isinstance(value, bool):
        return 1 if value else 0

    # Handle integer types directly
    if isinstance(value, int):
        return value

    # Handle float by truncating towards zero
    if isinstance(value, float):
        return int(value)

    # Handle string conversion with exception handling
    if isinstance(value, str):
        try:
            return int(value.strip())
        except (ValueError, AttributeError):
            return fallback

    # Return fallback for unsupported types
    return fallback

