    GREEDY = 1

@wp.kernel
def validate_graph_coloring(edge_indices: wp.array(dtype=int, ndim=2), colors: wp.array(dtype=int)):
    edge_idx = wp.tid()
    v1 = edge_indices[edge_idx, 0]
    v2 = edge_indices[edge_idx, 1]
    wp.expect_neq(colors[v1], colors[v2])

@wp.kernel
def count_color_group_size(
    colors: wp.array(dtype=int),
    group_sizes: wp.array(dtype=int),
):
    for particle_idx in range(colors.shape[0]):
        color_id = colors[particle_idx]
        group_sizes[color_id] += 1

@wp.kernel
def fill_color_groups(
    colors: wp.array(dtype=int),
    group_fill_count: wp.array(dtype=int),
    group_offsets: wp.array(dtype=int),
    color_groups_flatten: wp.array(dtype=int),
):
    for particle_idx in range(colors.shape[0]):
        color_id = colors[particle_idx]
        offset = group_offsets[color_id]
        position = group_fill_count[color_id]
        color_groups_flatten[offset + position] = particle_idx
        group_fill_count[color_id] = position + 1

def convert_to_color_groups(num_colors: int, particle_colors: wp.array, return_wp_array: bool = False, device: str = "cpu") -> list:
    group_sizes = wp.zeros(shape=(num_colors,), dtype=int, device="cpu")
    wp.launch(kernel=count_color_group_size, inputs=[particle_colors, group_sizes], device="cpu", dim=1)
    sizes_np = group_sizes.numpy()
    offsets_np = np.concatenate([np.array([0]), np.cumsum(sizes_np)])
    offsets = wp.array(offsets_np, dtype=int, device="cpu")
    fill_counts = wp.zeros(shape=(num_colors,), dtype=int, device="cpu")
    total_size = int(np.sum(sizes_np))
    color_groups_flatten = wp.empty(shape=(total_size,), dtype=int, device="cpu")

    wp.launch(
        kernel=fill_color_groups,
        inputs=[particle_colors, fill_counts, offsets, color_groups_flatten],
        device="cpu",
        dim=1,
    )

    flatten_np = color_groups_flatten.numpy()
    result_groups = []

    if return_wp_array:
        for color_idx in range(num_colors):
            start = offsets_np[color_idx]
            end = offsets_np[color_idx + 1]
            result_groups.append(
                wp.array(flatten_np[start:end], dtype=int, device=device)
            )
    else:
        for color_idx in range(num_colors):
            start = offsets_np[color_idx]
            end = offsets_np[color_idx + 1]
            result_groups.append(flatten_np[start:end])

    return result_groups

def _canonicalize_edges_np(edges_np: np.ndarray) -> np.ndarray:
    """Sort edge endpoints and remove duplicate edges."""
    if edges_np.size == 0:
        return np.empty((0, 2), dtype=np.int32)
    sorted_edges = np.sort(edges_np, axis=1)
    unique_edges = np.unique(sorted_edges, axis=0)
    return unique_edges.astype(np.int32)

def construct_tetmesh_graph_edges(tet_indices, tet_active_mask=None):
    """
    Convert tetrahedron connectivity into unique graph edges.
    """
    if tet_indices is None:
        return np.empty((0, 2), dtype=np.int32)

    if isinstance(tet_indices, wp.array):
        tet_data = tet_indices.numpy()
    else:
        tet_data = np.asarray(tet_indices, dtype=np.int32)

    # Apply active mask if provided
    if tet_active_mask is not None:
        mask = np.asarray(tet_active_mask, dtype=bool)
        if mask.ndim == 0:
            if not mask:
                tet_data = tet_data[:0]
        else:
            tet_data = tet_data[mask]

    if tet_data.size == 0:
        return np.empty((0, 2), dtype=np.int32)

    # Extract vertices from each tetrahedron
    v0 = tet_data[:, 0]
    v1 = tet_data[:, 1]
    v2 = tet_data[:, 2]
    v3 = tet_data[:, 3]

    # Create all 6 edges per tetrahedron
    edges = np.stack([
        np.column_stack([v0, v1]),
        np.column_stack([v0, v2]),
        np.column_stack([v0, v3]),
        np.column_stack([v1, v2]),
        np.column_stack([v1, v3]),
        np.column_stack([v2, v3]),
    ], axis=0).reshape(-1, 2)

    return _canonicalize_edges_np(edges)

def construct_trimesh_graph_edges(
    tri_indices,
    tri_active_mask=None,
    bending_edge_indices=None,
    bending_edge_active_mask=None,
    return_wp_array=True,
):
    """
    Generate graph edges from triangular mesh and optional bending edges.
    """
    edge_list = []

    # Process triangle edges
    if tri_indices is not None:
        tri_data = tri_indices.numpy() if isinstance(tri_indices, wp.array) else np.asarray(tri_indices, dtype=np.int32)

        if tri_data.size > 0:
            if tri_active_mask is not None:
                mask = np.asarray(tri_active_mask, dtype=bool)
                if mask.ndim == 0:
                    if not mask:
                        tri_data = tri_data[:0]
                else:
                    tri_data = tri_data[mask]

            if tri_data.size > 0:
                v0, v1, v2 = tri_data[:, 0], tri_data[:, 1], tri_data[:, 2]
                tri_edges = np.stack([
                    np.column_stack([v0, v1]),
                    np.column_stack([v0, v2]),
                    np.column_stack([v1, v2]),
                ], axis=0).reshape(-1, 2)
                edge_list.append(tri_edges)

    # Process bending edges (hinges)
    if bending_edge_indices is not None:
        bend_data = np.asarray(bending_edge_indices, dtype=np.int32)

        if bend_data.size > 0:
            if bending_edge_active_mask is not None:
                mask = np.asarray(bending_edge_active_mask, dtype=bool)
                if mask.ndim == 0:
                    if not mask:
                        bend_data = bend_data[:0]
                else:
                    bend_data = bend_data[mask]

            if bend_data.size > 0:
                v0 = bend_data[:, 0:1]
                v1 = bend_data[:, 1:2]
                v2 = bend_data[:, 2:3]
                v3 = bend_data[:, 3:4]

                pairs = np.concatenate([
                    np.concatenate([v0, v1], axis=1),
                    np.concatenate([v0, v2], axis=1),
                    np.concatenate([v0, v3], axis=1),
                    np.concatenate([v1, v2], axis=1),
                    np.concatenate([v1, v3], axis=1),
                    np.concatenate([v2, v3], axis=1),
                ], axis=0)

                valid_mask = np.all(pairs >= 0, axis=1)
                filtered_pairs = pairs[valid_mask]

                if filtered_pairs.size > 0:
                    edge_list.append(filtered_pairs)

    if edge_list:
        combined_edges = np.concatenate(edge_list, axis=0)
    else:
        combined_edges = np.empty((0, 2), dtype=np.int32)

    canonical_edges = _canonicalize_edges_np(combined_edges)

    if return_wp_array:
        return wp.array(canonical_edges, dtype=int, device="cpu")
    return canonical_edges

def construct_particle_graph(
    tri_graph_edges=None,
    tri_active_mask=None,
    bending_edge_indices=None,
    bending_edge_active_mask=None,
    tet_graph_edges_np=None,
    tet_active_mask=None,
):
    """
    Combine triangle and tetrahedron mesh edges into a unified particle graph.
    """
    tri_edges = construct_trimesh_graph_edges(
        tri_graph_edges, tri_active_mask,
        bending_edge_indices, bending_edge_active_mask,
        return_wp_array=False
    )
    tet_edges = construct_tetmesh_graph_edges(tet_graph_edges_np, tet_active_mask)

    merged = np.vstack([tri_edges, tet_edges]).astype(np.int32)
    canonical_merged = _canonicalize_edges_np(merged)

    return wp.array(canonical_merged, dtype=int, device="cpu")

def color_graph(
    num_nodes: int,
    graph_edge_indices: wp.array(dtype=int, ndim=2),
    balance_colors: bool = True,
    target_max_min_color_ratio: float = 1.1,
    algorithm: ColoringAlgorithm = ColoringAlgorithm.MCS,
) -> list:
    """
    Generate graph coloring using either MCS or greedy algorithm.
    """
    if num_nodes == 0:
        return []

    particle_colors = wp.empty(shape=(num_nodes,), dtype=wp.int32, device="cpu")

    if graph_edge_indices.ndim != 2:
        raise ValueError(f"graph_edge_indices must be 2D, got {graph_edge_indices.ndim}D")

    indices = graph_edge_indices if graph_edge_indices.device.is_cpu else wp.clone(graph_edge_indices, device="cpu")

    num_colors = wp._src.context.runtime.core.wp_graph_coloring(
        num_nodes,
        indices.__ctype__(),
        algorithm.value,
        particle_colors.__ctype__(),
    )

    if balance_colors:
        max_min_ratio = wp._src.context.runtime.core.wp_balance_coloring(
            num_nodes,
            indices.__ctype__(),
            num_colors,
            target_max_min_color_ratio,
            particle_colors.__ctype__(),
        )
        if max_min_ratio > target_max_min_color_ratio and wp.config.verbose:
            warnings.warn(
                f"Color balancing stopped early: ratio {max_min_ratio:.3f} exceeds target {target_max_min_color_ratio:.3f}.",
                stacklevel=2,
            )

    return convert_to_color_groups(num_colors, particle_colors, return_wp_array=False)

def plot_graph(
    vertices,
    edges,
    edge_labels=None,
    node_labels=None,
    node_colors=None,
    layout: Literal["spring", "kamada_kawai"] = "kamada_kawai",
):
    """
    Visualize a graph using matplotlib and networkx.
    """
    import matplotlib.pyplot as plt
    import networkx as nx

    G = nx.DiGraph()
    name_to_index = {}

    for i, name in enumerate(vertices):
        G.add_node(i)
        name_to_index[name] = i

    g_edge_labels = {}
    for i, (a, b) in enumerate(edges):
        ai = a if isinstance(a, int) else name_to_index[a]
        bi = b if isinstance(b, int) else name_to_index[b]
        label = edge_labels[i] if edge_labels and i < len(edge_labels) else None
        if label:
            g_edge_labels[(ai, bi)] = label
        G.add_edge(ai, bi, label=label)

    if layout == "spring":
        pos = nx.spring_layout(G, k=3.5, iterations=200)
    elif layout == "kamada_kawai":
        pos = nx.kamada_kawai_layout(G)
    else:
        raise ValueError(f"Invalid layout: {layout}")

    default_args = {"alpha": 0.9, "edgecolors": "black", "linewidths": 0.5}
    nx.draw_networkx_nodes(G, pos, node_color=node_colors, **default_args)

    labels_dict = dict(enumerate(node_labels if node_labels is not None else vertices))
    nx.draw_networkx_labels(
        G, pos, labels=labels_dict,
        font_size=8,
        bbox={"facecolor": "white", "alpha": 0.8, "edgecolor": "none", "pad": 0.5},
    )

    nx.draw_networkx_edges(G, pos, arrows=True, edge_color="black", node_size=1000)

    if g_edge_labels:
        nx.draw_networkx_edge_labels(
            G, pos, edge_labels=g_edge_labels,
            font_color="darkslategray", font_size=8,
        )

    plt.axis("off")
    plt.show()

def combine_independent_particle_coloring(color_groups_1: list, color_groups_2: list) -> list:
    """
    Combine two independent graph colorings by pairing groups of similar sizes.
    """
    if not color_groups_1:
        return color_groups_2
    if not color_groups_2:
        return color_groups_1

    num_colors = max(len(color_groups_1), len(color_groups_2))
    combined = []

    # Ensure color_groups_1 has more or equal groups
    if len(color_groups_1) < len(color_groups_2):
        color_groups_1, color_groups_2 = color_groups_2, color_groups_1

    # Sort groups by size (ascending for first, descending for second)
    sorted_1 = sorted(color_groups_1, key=lambda g: len(g))
    sorted_2 = sorted(color_groups_2, key=lambda g: -len(g))

    for i in range(num_colors):
        g1 = sorted_1[i] if i < len(sorted_1) else None
        g2 = sorted_2[i] if i < len(sorted_2) else None

        if g1 is not None and g2 is not None:
            combined.append(np.concatenate([g1, g2]))
        elif g1 is not None:
            combined.append(g1)
        else:
            combined.append(g2)

    return combined

def color_rigid_bodies(
    num_bodies: int,
    joint_parent: list[int],
    joint_child: list[int],
    balance_colors: bool = True,
    target_max_min_color_ratio: float = 1.1,
    algorithm: ColoringAlgorithm = ColoringAlgorithm.MCS,
) -> list:
    """
    Generate coloring for rigid bodies based on joint connectivity.
    """
    if num_bodies == 0:
        return []

    if len(joint_parent) != len(joint_child):
        raise ValueError(
            f"joint_parent and joint_child must have same length ({len(joint_parent)} vs {len(joint_child)})"
        )

    edge_list = []
    for parent, child in zip(joint_parent, joint_child, strict=True):
        if parent != -1 and child != -1 and parent != child:
            edge_list.append([parent, child])

    if not edge_list:
        return [np.arange(num_bodies, dtype=int)]

    edge_indices = np.array(edge_list, dtype=int)
    edge_indices_wp = wp.array(edge_indices, dtype=int, device="cpu")

    return color_graph(num_bodies, edge_indices_wp, balance_colors, target_max_min_color_ratio, algorithm)

# Custom exception hierarchy for the Agents SDK

from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from .agent import Agent
    from .guardrail import InputGuardrailResult, OutputGuardrailResult
    from .items import ModelResponse, RunItem, TResponseInputItem
    from .run_context import RunContextWrapper
    from .tool_guardrails import (
        ToolGuardrailFunctionOutput,
        ToolInputGuardrail,
        ToolOutputGuardrail,
    )
from .util._pretty_print import pretty_print_run_error_details


@dataclass
class ExecutionErrorDetails:
    """Aggregated information gathered during an agent execution when an error occurs."""
    user_input: str | list[TResponseInputItem]
    generated_items: list[RunItem]
    raw_model_outputs: list[ModelResponse]
    final_agent: Agent[Any]
    session_context: RunContextWrapper[Any]
    input_safety_checks: list[InputGuardrailResult]
    output_safety_checks: list[OutputGuardrailResult]

    def __str__(self) -> str:
        return pretty_print_run_error_details(self)


class BaseAgentsError(Exception):
    """Root exception class for all custom exceptions in the Agents framework."""
    execution_context: ExecutionErrorDetails | None

    def __init__(self, *args: object) -> None:
        super().__init__(*args)
        self.execution_context = None


class TurnLimitExceeded(BaseAgentsError):
    """Raised when the conversation exceeds the allowed number of turns."""
    description: str

    def __init__(self, description: str):
        self.description = description
        super().__init__(description)


class UnexpectedModelBehavior(BaseAgentsError):
    """Raised when the model behaves unexpectedly—for example, invoking non-existent tools or producing invalid JSON."""
    explanation: str

    def __init__(self, explanation: str):
        self.explanation = explanation
        super().__init__(explanation)


class ClientMisuseError(BaseAgentsError):
    """Raised due to incorrect usage of the SDK by the developer or end-user."""
    description: str

    def __init__(self, description: str):
        self.description = description
        super().__init__(description)


class ToolExecutionTimeout(BaseAgentsError):
    """Raised when a tool function fails to complete within its specified time limit."""
    function_name: str
    max_duration: float

    def __init__(self, function_name: str, max_duration: float):
        self.function_name = function_name
        self.max_duration = max_duration
        super().__init__(f"Tool '{function_name}' exceeded timeout of {max_duration:g} seconds.")


class InputSafetyCheckFailed(BaseAgentsError):
    """Raised when an input guardrail tripwire is activated."""
    check_result: InputGuardrailResult

    def __init__(self, check_result: InputGuardrailResult):
        self.check_result = check_result
        super().__init__(
            f"Input safety mechanism {check_result.guardrail.__class__.__name__} activated"
        )


class OutputSafetyCheckFailed(BaseAgentsError):
    """Raised when an output guardrail tripwire is activated."""
    check_result: OutputGuardrailResult

    def __init__(self, check_result: OutputGuardrailResult):
        self.check_result = check_result
        super().__init__(
            f"Output safety mechanism {check_result.guardrail.__class__.__name__} activated"
        )


class ToolInputSafetyCheckFailed(BaseAgentsError):
    """Raised when a tool-specific input guardrail tripwire is activated."""
    safety_mechanism: ToolInputGuardrail[Any]
    guard_output: ToolGuardrailFunctionOutput

    def __init__(self, safety_mechanism: ToolInputGuardrail[Any], guard_output: ToolGuardrailFunctionOutput):
        self.safety_mechanism = safety_mechanism
        self.guard_output = guard_output
        super().__init__(
            f"Tool input safety filter {safety_mechanism.__class__.__name__} triggered"
        )


class ToolOutputSafetyCheckFailed(BaseAgentsError):
    """Raised when a tool-specific output guardrail tripwire is activated."""
    safety_mechanism: ToolOutputGuardrail[Any]
    guard_output: ToolGuardrailFunctionOutput

    def __init__(self, safety_mechanism: ToolOutputGuardrail[Any], guard_output: ToolGuardrailFunctionOutput):
        self.safety_mechanism = safety_mechanism
        self.guard_output = guard_output
        super().__init__(
            f"Tool output safety filter {safety_mechanism.__class__.__name__} triggered"
        )

