class RequestHandler(BaseHTTPRequestHandler):
    """Custom HTTP request handler for serving JWKS and token data."""

    def do_GET(self) -> None:
        """Route incoming GET requests based on path."""
        if self.path == "/.well-known/jwks.json":
            self._send_json(PUBLIC_KEYS)
        elif self.path == "/tokens":
            self._send_json(AUTH_TOKENS)
        elif self.path == "/health":
            self._send_json({"status": "healthy"})
        else:
            self.send_error(404, "Not Found")

    def _send_json(self, payload: Dict[str, Any]) -> None:
        """Format and send JSON response."""
        encoded_body = json.dumps(payload).encode('utf-8')
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(encoded_body)))
        self.end_headers()
        self.wfile.write(encoded_body)

    def log_message(self, format_str: str, *args: Any) -> None:
        """Suppress default logging of HTTP requests."""
        pass

