    server_instance.serve_forever()

from collections.abc import Callable
from typing import Any
from haive.core.common.structures.tree import AutoTree
from haive.agents.task_analysis.base.models import ActionStep, TaskNode


class TaskTree(AutoTree[TaskNode]):
    """Enhanced AutoTree specifically for task analysis.
    Adds task-specific functionality while leveraging AutoTree's auto-building.
    """

    def __init__(self, content: TaskNode, **kwargs):
        super().__init__(content, **kwargs)
        # Internal analysis state
        self._merge_nodes: list[dict[str, Any]] = []
        self._concurrent_clusters: list[list[str]] = []
        self._bottleneck_route: list[str] = []
        self._post_build_analysis()

    def _post_build_analysis(self):
        """Run structural diagnostics after tree construction."""
        self._detect_merge_points()
        self._cluster_concurrent_tasks()
        self._trace_bottleneck_path()

    def _detect_merge_points(self):
        """Locate tasks where multiple independent paths converge."""
        for nd in self.depth_first_iter(lambda n: n):  # type: ignore
            if getattr(nd.content, "is_join_point", False):
                sources = self._collect_predecessors(nd.content.task_id)
                if len(sources) > 1:
                    self._merge_nodes.append(
                        {
                            "join_id": f"join_{nd.content.task_id}",
                            "task_id": nd.content.task_id,
                            "incoming_tasks": sources,
                            "join_strategy": getattr(nd.content, "join_strategy", "merge"),
                        }
                    )

    def _cluster_concurrent_tasks(self):
        """Group tasks that do not depend on each other directly or transitively."""
        dep_graph = self._assemble_dependency_graph()
        all_ids = self._list_all_task_identifiers()
        seen_pairs = set()
        for idx, t1 in enumerate(all_ids):
            cluster = [t1]
            for t2 in all_ids[idx + 1 :]:
                pair_key = tuple(sorted((t1, t2)))
                if pair_key in seen_pairs:
                    continue
                if not self._check_interdependence(t1, t2, dep_graph):
                    cluster.append(t2)
                    seen_pairs.add(pair_key)
            if len(cluster) > 1:
                self._concurrent_clusters.append(cluster)

    def _trace_bottleneck_path(self):
        """Determine longest-duration root-to-leaf path (critical path approximation)."""
        route = []
        current = self.content
        route.append(current.task_id)
        while current.subtasks:
            best_child = None
            best_dur = -1.0
            for child in current.subtasks:
                dur = self._fetch_duration(child)
                if dur > best_dur:
                    best_dur = dur
                    best_child = child
            if best_child is None:
                break
            if isinstance(best_child, TaskNode):
                route.append(best_child.task_id)
                current = best_child
            else:
                route.append(best_child.step_id)
                break
        self._bottleneck_route = route

    def _assemble_dependency_graph(self) -> dict[str, list[str]]:
        """Construct reverse dependency map: target → list of sources."""
        graph: dict[str, list[str]] = {}
        for nd in self.depth_first_iter(lambda n: n):  # type: ignore
            deps = getattr(nd.content, "dependencies", [])
            for d in deps:
                target = d.target_id
                source = d.source_id
                graph.setdefault(target, []).append(source)
        return graph

    def _list_all_task_identifiers(self) -> list[str]:
        """Gather all unique identifiers from nodes/steps."""
        ids = []
        for nd in self.depth_first_iter(lambda n: n):  # type: ignore
            if hasattr(nd.content, "task_id"):
                ids.append(nd.content.task_id)
            elif hasattr(nd.content, "step_id"):
                ids.append(nd.content.step_id)
        return ids

    def _check_interdependence(self, id_a: str, id_b: str, dep_graph: dict[str, list[str]]) -> bool:
        """Determine if there exists any directed path between two tasks."""
        stack = [id_a]
        visited = set()
        while stack:
            cur = stack.pop()
            if cur == id_b:
                return True
            if cur in visited:
                continue
            visited.add(cur)
            stack.extend(dep_graph.get(cur, []))
        return False

    def _collect_predecessors(self, tid: str) -> list[str]:
        """Return all immediate predecessor task IDs feeding into given task."""
        preds = []
        for nd in self.depth_first_iter(lambda n: n):  # type: ignore
            for d in getattr(nd.content, "dependencies", []):
                if d.target_id == tid:
                    preds.append(d.source_id)
        return preds

    def _fetch_duration(self, item: TaskNode | ActionStep) -> float:
        """Retrieve estimated duration for a node or step."""
        if isinstance(item, ActionStep):
            return item.estimated_duration_minutes
        elif isinstance(item, TaskNode):
            return item.calculate_total_duration()
        return 0.0

    # ========================================================================
    # PUBLIC METHODS
    # ========================================================================

    def get_join_points(self) -> list[dict[str, Any]]:
        return self._merge_nodes

    def get_parallel_groups(self) -> list[list[str]]:
        return self._concurrent_clusters

    def get_critical_path(self) -> list[str]:
        return self._bottleneck_route

    def get_execution_phases(self) -> list[dict[str, Any]]:
        """Partition tasks into sequential phases respecting dependencies."""
        result = []
        completed = set()
        dep_map = self._assemble_dependency_graph()
        all_ids = self._list_all_task_identifiers()
        phase_idx = 1
        while len(completed) < len(all_ids):
            ready = [
                tid
                for tid in all_ids
                if tid not in completed
                and all(pre in completed for pre in dep_map.get(tid, []))
            ]
            if not ready:
                break
            result.append(
                {
                    "phase_number": phase_idx,
                    "tasks": ready,
                    "can_parallelize": len(ready) > 1,
                }
            )
            completed.update(ready)
            phase_idx += 1
        return result

    def expand_node(
        self,
        node_id: str,
        expansion_fn: Callable[[TaskNode], list[TaskNode | ActionStep]],
    ) -> bool:
        """Apply user-provided expansion function to a specific node."""
        target = next(
            (
                nd
                for nd in self.depth_first_iter(lambda n: n)  # type: ignore
                if hasattr(nd.content, "task_id") and nd.content.task_id == node_id
            ),
            None,
        )
        if not target or not isinstance(target.content, TaskNode):
            return False
        if not getattr(target.content, "can_expand", False):
            return False
        expanded_items = expansion_fn(target.content)
        for sub in expanded_items:
            target.content.add_subtask(sub)
        target._build_children()
        self._post_build_analysis()
        return True

    def get_analysis_summary(self) -> dict[str, Any]:
        """Produce high-level statistics about the task tree."""
        all_steps = self.content.get_all_steps()
        return {
            "total_tasks": len(self._list_all_task_identifiers()),
            "total_steps": len(all_steps),
            "max_depth": self._depth_bound(0),
            "total_duration_minutes": self.content.calculate_total_duration(),
            "critical_path_length": len(self._bottleneck_route),
            "join_points": len(self._merge_nodes),
            "parallel_groups": len(self._concurrent_clusters),
            "can_parallelize": len(self._concurrent_clusters) > 0,
        }

    def _depth_bound(self, depth: int) -> int:
        """Recursively compute maximum tree depth."""
        if not self.children:
            return depth
        return max(
            (
                child._depth_bound(depth + 1)
                for child in self.children
                if isinstance(child, TaskTree)
            ),
            default=depth,
        )

# Custom exception hierarchy for Codex authentication issues

class AuthenticationException(Exception):
    """Root exception class for all Codex authentication problems."""

class NotAuthenticatedError(AuthenticationException):
    """Raised when a user attempts to access a protected resource without logging in."""

class TokenRefreshFailureError(AuthenticationException):
    """Raised when an expired token cannot be refreshed successfully."""

class OAuthProcessFailureError(AuthenticationException):
    """Raised when the OAuth handshake or flow encounters an error."""

