class SentenceBreaker(PunktLanguageVars):
    _period_context_fmt = r"""
        \S*                          
        %(SentEndChars)s             
        \s*                       
        (?=(?P<after_tok>
            %(NonWord)s              
            |
            (?P<next_tok>\S+)     
        ))"""

class NoOpTokenizer(object):
    def break_text(self, *parts):
        return parts

def read_parquet_lines(file_path, col_name, batch_size=10000):
    """Generate JSON strings from parquet file rows."""
    pf = pq.ParquetFile(file_path)
    for chunk in pf.iter_batches(batch_size=batch_size, columns=[col_name]):
        for val in chunk.column(col_name):
            yield json.dumps({"text": val.as_py()})

class TextProcessor(object):
    def __init__(self, config):
        self.config = config

    def setup(self):
        TextProcessor.tokenizer = AutoTokenizer.from_pretrained(self.config.pretrained_model_name_or_path)
        if self.config.segment_sentences:
            if not nltk_available:
                print("NLTK unavailable for sentence segmentation.")
                sys.exit(1)
            if os.environ.get("NLTK_DATA"):
                model_path = os.path.join(os.environ.get("NLTK_DATA"), "tokenizers", "punkt", f"{self.config.lang}.pickle")
                source_url = f"file:{model_path}"
            else:
                model_path = os.path.join("tokenizers", "punkt", f"{self.config.lang}.pickle")
                source_url = f"nltk:{model_path}"
            segmenter = nltk.load(source_url)
            if self.config.preserve_linebreaks:
                TextProcessor.segmenter = nltk.tokenize.punkt.PunktSentenceTokenizer(
                    train_text=segmenter._params, lang_vars=SentenceBreaker()
                )
            else:
                TextProcessor.segmenter = segmenter
        else:
            TextProcessor.segmenter = NoOpTokenizer()

    def segment(self, json_string):
        record = json.loads(json_string)
        result = {}
        for field in self.config.json_fields:
            content = record[field]
            max_segment = 1000000
            segments_list = [TextProcessor.segmenter.break_text(content[i : i + max_segment]) for i in range(0, len(content), max_segment)]
            result[field] = [seg for group in segments_list for seg in group]
        return json.dumps(result), len(json_string)

    def tokenize(self, json_string):
        record = json.loads(json_string)
        token_ids = {}
        lengths = {}
        for field in self.config.json_fields:
            content = record[field]
            if isinstance(content, list):
                chunks = content
            else:
                chunks = [content]
            all_tokens = []
            chunk_lengths = []
            for chunk in chunks:
                encoded = TextProcessor.tokenizer(chunk).input_ids
                if len(encoded) > 0:
                    all_tokens.extend(encoded)
                    chunk_lengths.append(len(encoded))
            if len(all_tokens) > 0 and self.config.add_end_token:
                all_tokens.append(TextProcessor.tokenizer.eos_token_id)
                chunk_lengths[-1] += 1
            token_ids[field] = all_tokens
            lengths[field] = chunk_lengths
        return token_ids, lengths, len(json_string)

class DataPartitioner(object):
    def __init__(self, config, parallelism):
        self.config = config
        self.parallelism = parallelism

    def report_progress(self, count, start_time, total_bytes, filename=None):
        if count % self.config.report_step == 0:
            now = time.time()
            duration = now - start_time
            speed_mbs = total_bytes / duration / 1024 / 1024
            source_info = f" from {os.path.basename(filename)}" if filename else ""
            print(
                f"Completed {count} items{source_info}", f"({count / duration:.1f} items/sec, {speed_mbs:.1f} MB/s).", file=sys.stderr
            )

    def perform_sentence_splitting(self, filenames):
        src_file, dst_file = filenames
        print("Processing:", src_file)
        with open(src_file, "r", encoding="utf-8") as fin:
            with open(dst_file, "w") as fout:
                processor = TextProcessor(self.config)
                pool = multiprocessing.Pool(self.parallelism, initializer=processor.setup)
                segmented = pool.imap(processor.segment, fin, 32)
                start_time = time.time()
                processed_bytes = 0
                for idx, (doc, byte_count) in enumerate(segmented, 1):
                    processed_bytes += byte_count
                    fout.write(doc + "\n")
                    self.report_progress(idx, start_time, processed_bytes, filename=src_file)

    def handle_json_input(self, filenames):
        src_file, output_base = filenames
        print("Reading:", src_file)
        startup_start = time.time()
        processor = TextProcessor(self.config)
        tokenizer = AutoTokenizer.from_pretrained(self.config.pretrained_model_name_or_path)
        pool = multiprocessing.Pool(self.parallelism, initializer=processor.setup)
        tokenized_docs = pool.imap(processor.tokenize, src_file, 32)
        level = "document"
        if self.config.segment_sentences:
            level = "sentence"
        bin_files = {}
        idx_files = {}
        builders = {}
        for field in self.config.json_fields:
            bin_files[field] = "{}_{}_{}.bin".format(output_base, field, level)
            idx_files[field] = "{}_{}_{}.idx".format(output_base, field, level)
            builders[field] = indexed_dataset.IndexedDatasetBuilder(
                bin_files[field],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )
        startup_end = time.time()
        proc_start = time.time()
        total_bytes = 0
        print("Initialization took:", startup_end - startup_start)
        for i, (tokens, lengths, bytes_read) in enumerate(tokenized_docs, 1):
            total_bytes += bytes_read
            for field in tokens.keys():
                builders[field].add_document(tokens[field], lengths[field])
            self.report_progress(i, proc_start, total_bytes, filename=src_file)
        pool.close()
        pool.join()
        for field in builders:
            builders[field].finalize(idx_files[field])

    def handle_parquet_input(self, filenames):
        src_file, output_base = filenames
        print("Reading parquet:", src_file)
        startup_start = time.time()
        processor = TextProcessor(self.config)
        tokenizer = AutoTokenizer.from_pretrained(self.config.pretrained_model_name_or_path)
        pool = multiprocessing.Pool(self.parallelism, initializer=processor.setup)
        row_stream = read_parquet_lines(
            src_file, self.config.text_column, batch_size=self.config.parquet_batch_size
        )
        tokenized_docs = pool.imap(processor.tokenize, row_stream, 32)
        level = "document"
        if self.config.segment_sentences:
            level = "sentence"
        bin_files = {}
        idx_files = {}
        builders = {}
        for field in self.config.json_fields:
            bin_files[field] = "{}_{}_{}.bin".format(output_base, field, level)
            idx_files[field] = "{}_{}_{}.idx".format(output_base, field, level)
            builders[field] = indexed_dataset.IndexedDatasetBuilder(
                bin_files[field],
                dtype=indexed_dataset.DType.optimal_dtype(len(tokenizer)),
            )
        startup_end = time.time()
        proc_start = time.time()
        total_bytes = 0
        print("Setup duration:", startup_end - startup_start)
        for i, (tokens, lengths, bytes_read) in enumerate(tokenized_docs, 1):
            total_bytes += bytes_read
            for field in tokens.keys():
                builders[field].add_document(tokens[field], lengths[field])
            self.report_progress(i, proc_start, total_bytes, filename=src_file)
        pool.close()
        pool.join()
        for field in builders:
            builders[field].finalize(idx_files[field])

def parse_arguments():
    parser = argparse.ArgumentParser(description="Process text data for language modeling")
    # Input configuration
    parser.add_argument("--source", type=str, required=True, help="Input file(s) path pattern")
    parser.add_argument(
        "--json-fields", nargs="+", default=["text"], help="Keys to extract from JSON objects"
    )
    parser.add_argument(
        "--source-type",
        type=str,
        choices=["json", "parquet", "auto"],
        default="auto",
        help="Format of input files (default: auto)",
    )
    parser.add_argument(
        "--text-field",
        type=str,
        default="text",
        help="Column name containing text in parquet files (default: text)",
    )
    parser.add_argument(
        "--parquet-chunk-size",
        type=int,
        default=10000,
        help="Batch size for parquet reading (default: 10000)",
    )
    parser.add_argument("--segment-sentences", action="store_true", help="Split documents into sentences")
    parser.add_argument("--preserve-linebreaks", action="store_true", help="Keep newlines during sentence splitting")
    # Tokenization settings
    parser.add_argument("--add-end-token", action="store_true", help="Add end-of-document token")
    parser.add_argument(
        "--language", type=str, default="english", help="Language for sentence splitting (default: english)"
    )
    # Output configuration
    parser.add_argument("--output-base", type=str, required=True, help="Base path for output files")
    parser.add_argument(
        "--output-dir",
        type=str,
        default=None,
        help="Output directory for generated files (overrides path in --output-base)"
    )
    # Performance settings
    parser.add_argument(
        "--threads",
        type=int,
        required=True,
        help="Number of worker processes to use"
    )
    parser.add_argument("--report-step", type=int, default=1000, help="Progress update frequency")
    parser.add_argument("--pretrained-model", type=str, required=True, help="Pretrained model identifier")
    return parser.parse_args()

def identify_file_format(path):
    """Determine file type by extension."""
    _, ext = os.path.splitext(path)
    ext = ext.lower()
    if ext in [".parquet", ".pq"]:
        return "parquet"
    elif ext in [".json", ".jsonl"]:
        return "json"
    else:
        return "json"

def verify_outputs(partition_data, key, count):
    for i in range(count):
        if not os.path.exists(partition_data[i][key]):
            return False
    return True

def main():
    config = parse_arguments()

    # Setup NLTK if needed
    if config.segment_sentences:
        if nltk_available:
            nltk.download("punkt", quiet=True, download_dir=os.environ.get("NLTK_DATA"))
        else:
            raise Exception("NLTK library required for sentence splitting is not available.")

    # Create output directory if specified
    if config.output_dir:
        os.makedirs(config.output_dir, exist_ok=True)

    # Get list of input files
    if glob.has_magic(config.source):
        input_files = glob.glob(config.source)
    else:
        input_files = [config.source]

    if not input_files:
        print(f"No files matched pattern: {config.source}")
        return

    # Determine file format
    if config.source_type == "auto":
        file_format = identify_file_format(input_files[0])
    else:
        file_format = config.source_type

    # Validate requirements
    if file_format == "parquet" and not parquet_available:
        raise Exception(
            "pyarrow library required for parquet files is missing. Install with: pip install pyarrow"
        )

    # Parquet doesn't support sentence splitting
    if file_format == "parquet" and config.segment_sentences:
        print("Warning: Sentence splitting not supported for parquet files. Disabling option.")
        config.segment_sentences = False

    # Distribute workers across files
    workers_per_file = max(1, config.threads // len(input_files))
    partitioner = DataPartitioner(config, workers_per_file)

    # Prepare file paths
    file_mappings = []
    for idx, src_path in enumerate(input_files):
        base, ext = os.path.splitext(src_path)
        if config.output_dir:
            filename = os.path.basename(base)
            split_file = os.path.join(config.output_dir, filename + "_ss" + ext)
            out_prefix = os.path.join(config.output_dir, f"{os.path.basename(config.output_base)}_{idx}")
        else:
            split_file = base + "_ss" + ext
            out_prefix = f"{config.output_base}_{idx}"
        file_mappings.append({
            "original": src_path,
            "split_output": split_file,
            "final_output": out_prefix
        })

    if file_format == "json":
        # Handle optional sentence splitting
        split_exists = verify_outputs(file_mappings, "split_output", len(file_mappings))
        if config.segment_sentences and not split_exists:
            processes = []
            for mapping in file_mappings:
                p = multiprocessing.Process(
                    target=partitioner.perform_sentence_splitting,
                    args=((mapping["original"], mapping["split_output"]),)
                )
                p.start()
                processes.append(p)
            for p in processes:
                p.join()

        # Process each file
        processes = []
        input_source = "split_output" if config.segment_sentences else "original"
        for mapping in file_mappings:
            p = multiprocessing.Process(
                target=partitioner.handle_json_input,
                args=((mapping[input_source], mapping["final_output"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()
    else:
        # Process parquet files
        processes = []
        for mapping in file_mappings:
            p = multiprocessing.Process(
                target=partitioner.handle_parquet_input,
                args=((mapping["original"], mapping["final_output"]),)
            )
            p.start()
            processes.append(p)
        for p in processes:
            p.join()

if __name__ == "__main__":
    main()

# Define base error class for Metaxy-related exceptions
class MetaxyError(Exception):
    @property
    def is_user_code_error(self):
        """Indicates whether the error stems from user-provided code."""
        return False

# Specialized error for invariant violations enforceable only at runtime
class MetaxyInvariantViolationError(MetaxyError):
    """Raised when a clearly specified invariant is violated, detectable only during execution."""

    @property
    def is_user_code_error(self):
        """Returns True if the violation originates from user-supplied logic."""
        return True

# Error for providing an empty string where a non-empty code version is required
class MetaxyEmptyCodeVersionError(MetaxyInvariantViolationError):
    """Signifies that an empty code version was supplied in a context requiring a non-empty string.
    Valid code versions must be non-empty strings.
    """

# Error for missing dependencies required by a feature within the dependency graph
class MetaxyMissingFeatureDependency(MetaxyInvariantViolationError):
    """Triggered when a feature's necessary dependency is absent from the dependency graph."""
